      'NOT_FOR_ENFORCEMENT'                           AS deliverable_class,
       ROUND(e.agent_cost_a_legacy,4)                  AS agent_cost_a_legacy,
       ROUND(e.agent_cost_valid_base_legacy,4)         AS agent_cost_valid_base_legacy,
           ROUND(-e.net-e.rebate,4)                        AS ngr,
       ROUND(-e.net-e.rebate-e.agent_cost,4)           AS residual_b,
       ROUND(-e.net-e.rebate-e.agent_cost_a_legacy,4)  AS residual_a,
           ROUND((-e.net-e.rebate)/NULLIF(e.stake,0),8)    AS ngr_rate,
       ROUND((-e.net-e.rebate-e.agent_cost)/NULLIF(e.stake,0),8)   AS residual_b_rate,
      -- 【HF9c · canonical accounting contract】
      --   以下 canonical 字段只增加明确 scope；不删除、不覆盖既有字段。
      --   formal_bet23_* 保持 HF9b 当前生产公式及其 NULL/0 语义；
      --   lv1~lv5 / additive / nested 则分别采用各自原始 e.* 成本字段，
      --   rate 一律从未舍入的 e.* 分子 / e.stake 计算，禁止由展示值反算。
      ROUND(e.agent_cost,4) AS agent_cost_bet23_formal_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost,4) AS net_margin_bet23_formal_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost)/NULLIF(e.stake,0),8) AS net_margin_bet23_formal_rate_canonical,
      ROUND(e.agent_cost_lv1,4) AS agent_cost_lv1_bet23_canonical,
      ROUND(e.agent_cost_lv2,4) AS agent_cost_lv2_bet24_canonical,
      ROUND(e.agent_cost_lv3,4) AS agent_cost_lv3_bet25_canonical,
      ROUND(e.agent_cost_lv4,4) AS agent_cost_lv4_bet26_canonical,
      ROUND(e.agent_cost_lv5,4) AS agent_cost_lv5_bet27_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_lv1,4) AS net_margin_lv1_bet23_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_lv1)/NULLIF(e.stake,0),8) AS net_margin_lv1_bet23_rate_canonical,
      ROUND(e.agent_cost_chain_additive,4) AS agent_cost_chain_additive_canonical,
      ROUND(e.agent_cost_chain_nested,4) AS agent_cost_chain_nested_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_additive,4) AS net_margin_chain_additive_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_nested,4) AS net_margin_chain_nested_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_chain_additive)/NULLIF(e.stake,0),8) AS net_margin_chain_additive_rate_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_chain_nested)/NULLIF(e.stake,0),8) AS net_margin_chain_nested_rate_canonical,
       ROUND((-e.net-e.rebate-e.agent_cost_a_legacy)/NULLIF(e.stake,0),8) AS residual_a_rate,
           -- 二·分布层
           ROUND(e.stake/NULLIF(e.n_bets,0),4) AS avg_stake_per_bet,
           ROUND(e.valid/NULLIF(e.n_rounds,0),4) AS avg_valid_bet_per_round,
           ROUND(-e.net/NULLIF(e.n_rounds,0),4) AS avg_profit_per_round,
           ROUND(-e.net/NULLIF(e.active_days,0),4) AS avg_profit_per_day,
           ROUND(-e.net/NULLIF(e.active_shoes,0),4) AS avg_profit_per_shoe,
           ROUND(e.stake/NULLIF(e.active_days,0),4) AS avg_stake_per_active_day,
           ROUND(e.n_rounds*1.0/NULLIF(e.active_days,0),4) AS avg_rounds_per_active_day,
           ROUND(e.st_in/NULLIF(e.nb_in,0),4) AS avg_stake_freecomm,
           ROUND(e.st_out/NULLIF(e.nb_out,0),4) AS avg_stake_non_freecomm,
           ROUND(e.p25,4) AS p25_stake, ROUND(e.p50,4) AS p50_stake, ROUND(e.p75,4) AS p75_stake,
           ROUND(e.p90,4) AS p90_stake, ROUND(e.p95,4) AS p95_stake, ROUND(e.p99,4) AS p99_stake,
           ROUND(e.p50_valid,4) AS p50_valid_bet, ROUND(e.p50_profit,4) AS p50_profit,
           ROUND(e.p95/NULLIF(e.p50,0),6) AS p95_over_p50,
           ROUND(e.p99/NULLIF(e.p50,0),6) AS p99_over_p50,
           ROUND((e.stake/NULLIF(e.n_bets,0))/NULLIF(e.p50,0),6) AS avg_over_p50,
           -- 三·关系层
           e.n_tables AS common_table_count, e.n_dealers AS common_dealer_count,
           e.n_ips AS common_ip_count, e.n_products AS common_product_count,
           ROUND(e.st_in/NULLIF(e.stake,0),8) AS share_freecomm,
           -- 四·rate 层
           ROUND(-e.net/NULLIF(e.stake,0),8) AS hold_rate,
           ROUND(-e.net_in/NULLIF(e.st_in,0),8) AS hold_rate_freecomm,
           ROUND(e.rebate/NULLIF(e.valid,0),8) AS rebate_rate_actual,
           ROUND(e.rbpct,6) AS rebate_pct_config,
           ROUND(e.valid/NULLIF(e.stake,0),6) AS turnover_multiple,
           ROUND(e.freecomm_rate,6) AS free_comm_rate,
           ROUND(e.net_in/NULLIF(e.st_in,0)-e.net_out/NULLIF(e.st_out,0),8) AS roi_delta_freecomm,
           -- 五·动态层
           e.first_seen_d AS first_seen, e.last_seen_d AS last_seen,
           e.active_days, e.active_shoes, e.active_sessions,
           DATEDIFF(e.last_seen_d, e.first_seen_d)+1 AS span_days,
           ROUND(e.active_days*1.0/NULLIF(DATEDIFF(e.last_seen_d,e.first_seen_d)+1,0),6) AS persistence,
           ROUND((e.st_in/NULLIF(e.nb_in,0))/NULLIF(e.st_out/NULLIF(e.nb_out,0),0),6) AS ramp_freecomm,
           ROUND((e.st_rec/NULLIF(e.nb_rec,0))/NULLIF(e.stake/NULLIF(e.n_bets,0),0),6) AS ramp_recent,
           ROUND((e.st_rec/NULLIF(e.stake,0))/0.30,6) AS stake_ramp,
           -- 六·决策层（HF9g-P5 · D-14 斧正 —— 本件属【全窗基线族】，相对刻度与决策标签一律 NULL）
           --   病灶：x_win 系全窗单行聚合（无 GROUP BY，恒 1 行，此为设计使然，非缺陷），
           --         经 CROSS JOIN 接入后 e.* 全行同值；六层之 NTILE / PERCENT_RANK 施于常数即退化，
           --         PERCENT_RANK 恒 0 ⇒ action_priority 恒判 A，全件 100% 误标。
           --   ★ 斧正原则：不给 x_win 补 GROUP BY —— 那会改变其「全窗基线」语义，属退化。
           --     正解与 #018 之 G-05／G-06 同治：范围外之行不得接受任何下游评分与决策标签。
           --   ★ 本件之 e.* 仍照常供其它列作全窗基线使用，仅六层相对刻度与决策标签置 NULL。
           CAST(NULL AS INT)                                              AS vip_tier,                        -- 空值取值：全窗基线族无实体可分档，置 NULL（NULL＝不适用，非 0）
           CAST(NULL AS DOUBLE)                                           AS economic_value,                  -- 空值取值：同上，禁以常数百分位冒充经济价值
           CAST(NULL AS DOUBLE)                                           AS roi_pr_global,                   -- 空值取值：同上
           CAST(NULL AS DOUBLE)                                           AS risk_value,                      -- 空值取值：兼容列，同上
           CAST(NULL AS DOUBLE)                                           AS pr_stake,                        -- 空值取值：兼容列，同上
           CAST(NULL AS DOUBLE)                                           AS pr_global,                       -- 空值取值：同上
           CAST(NULL AS DOUBLE)                                           AS pr_qualified,                    -- 空值取值：同上
           'GLOBAL_BASELINE_NO_ENTITY_RANKING'                            AS pr_qualified_population,         -- 字面取值：血统 —— 明示本件为全窗基线族，无实体排序总体
           CAST(NULL AS BIGINT)                                           AS pr_global_population_n,          -- 空值取值：血统 —— 不适用
           CAST(NULL AS BIGINT)                                           AS pr_qualified_population_n,       -- 空值取值：血统 —— 不适用
           'NOT_APPLICABLE_GLOBAL_BASELINE'                               AS pr_calculation_method,           -- 字面取值：血统 —— 算法不适用
           'HF9g-P5'                                                      AS pr_calculation_version,          -- 字面取值：血统 —— 算法版本
           CAST(NULL AS STRING)                                           AS evidence_flag,                   -- 空值取值：证据旗标不适用于全窗基线
           CAST(NULL AS STRING)                                           AS evidence_rate,                   -- 空值取值：同上
           CAST(NULL AS DOUBLE)                                           AS hold_ci_halfwidth_approx,        -- 空值取值：同上
           'X 全窗基线 · 不参与实体赏罚'                                    AS action_priority                  -- 字面取值：★ D-14 斧正 —— 本族恒不入赏罚，取代原 100% 误标之「A」
    FROM q
    CROSS JOIN x_win e
  ) y
) z
-- ── 逐批 WHERE 阶梯（★ 口诀：上界 ＝ 下界 ＋ 100000，两数同进）──
--    本件 T_true 未测，无需先跑 T_true；以 0 / 100000 控制本批返回区间，末批由实际行数 < 100000 判定
--    WHERE z.audit_rn >        0 AND z.audit_rn <=   100000   -- 第 1 批
--    WHERE z.audit_rn >   100000 AND z.audit_rn <=   200000   -- 第 2 批
--    WHERE z.audit_rn >   200000 AND z.audit_rn <=   300000   -- 第 3 批
--    WHERE z.audit_rn >   300000 AND z.audit_rn <=   400000   -- 第 4 批
--    WHERE z.audit_rn >   400000 AND z.audit_rn <=   500000   -- 第 5 批
--    WHERE z.audit_rn >   500000 AND z.audit_rn <=   600000   -- 第 6 批
--    WHERE z.audit_rn >   600000 AND z.audit_rn <=   700000   -- 第 7 批
--    …余批类推。第 k 批：WHERE z.audit_rn > (k-1)*100000 AND z.audit_rn <= k*100000
--    某批返回 < 100000 行即为末批，其后不再取。
--
--    ⚠ 常见误写（务必避开）：只推下界而上界不动 ——
--        WHERE z.audit_rn > 100000 AND z.audit_rn <= 100000   ← 自相矛盾，恒为假，返回空集
--        WHERE z.audit_rn > 200000 AND z.audit_rn <= 100000   ← 同上，空集
--      两个数必须**同时**前进，且始终相差 100000。
--      下界 ＝ 上一批之上界；上界 ＝ 本批之上界。
WHERE z.audit_rn > 0 AND z.audit_rn <= 100000 -- ★ HF9c 本批区间
ORDER BY z.audit_rn;


-- ══════════════════════════════════════════════════════════════════════════════════════════════
--  62. QSB_02b_state_cross.csv   [总包行 11331~11424 · 原 9 列 ＋六层约 60 列]
--     典型学：M14 投注形态　派生旗标：freecomm（s.x_freecomm = 1 · 仅供 CASE 条件聚合，全包无任何 WHERE/AND/HAVING 以此过滤）　连接：全窗基线
-- ══════════════════════════════════════════════════════════════════════════════════════════════
-- ★ W-64 · D-14 警示（本件属 x_win 族 · 66 件之一 · 详见 §Z 段 D-14 全案）
--   本件以 `CROSS JOIN x_win e` 接入全局基线，x_win 无 GROUP BY ⇒ 恒 1 行 ⇒ e.* 全行同值。
--   故：economic_value / roi_pr_global / risk_value / pr_stake / pr_global 恒为 0；
--       action_priority 每一行皆为「A 净亏最大十分位 · 优先复核」（Z 分支永不触发）；
--       evidence_rate 恒为最高档；vip_tier 由常数键分档 ⇒ 无信息且非确定。
--   ⇒ 本件决策层三列 **NOT_FOR_DECISION**，裁定前不得用于排班、抽查或汇报。
-- ── ① 先跑 T_true 留档（不足 100000 者一次导全，不必分批）──
-- ── ① T_true：HF9c 不再强制预跑完整 COUNT。
--    本批实际返回行数 < 100000 即判定为末批；全批完成后以各批 n_rows / audit_rn 范围核对总量。

-- ── ② 分批取数：第 1 批。第 k 批只改末行两数为 (k-1)*100000 与 k*100000 ──
--    审计字段二（REDTEAM 2026-08-24 裁定 · 四锁）：
--      audit_rn  全局观测坐标 —— 由**与原版审计版逐字同一**之排序键所生，两版可逐行对账
--      batch_id  物理分批信息 —— 该行所属批次，由 audit_rn 算得，非引擎所赋
--    ★ 锁三：二者皆为审计字段，**不得进入任何业务指标计算**。
--    ★ 锁四：两版经 audit_rn 逐行字段核验后，方可宣布输出完全一致。

-- ── ③ 每批取回后自证四数（任一不符即停手回报，禁止放行）──
--    n_rows        = COUNT(*)      须等于 COUNT(DISTINCT audit_rn)   （批内无重复）
--    audit_rn_min  = MIN(audit_rn) 须等于 (k-1)*100000 + 1           （与上批严丝合缝）
--    audit_rn_max  = MAX(audit_rn) 须等于 min + n_rows - 1           （批内无缺口）
--    全批取毕再验：各批 audit_rn 之并集 = 1 .. T_true，无缺号、无重号。
--     ★ 首行＝平台真净亏最多者（已扣退水与代理占成）。
--
SELECT z.*,
       CAST(FLOOR((z.audit_rn - 1) / 100000) + 1 AS INT)          AS batch_id,
       'A168_HF9F_20260827_0900' AS run_id,
       '2026-08-27 09:00:00' AS snapshot_sync_time
FROM (
  SELECT y.*,
         ROW_NUMBER() OVER (ORDER BY y.`residual_b` ASC, y.`roi` DESC, y.`field_name`, y.`field_value`, y.`n_rows`, y.`n_pnl_zero`, y.`n_pnl_pos`, y.`n_pnl_neg`, y.`n_payout_zero`, y.`n_bet09`, y.`verdict_align`) AS audit_rn
  FROM (
    WITH
      x_ranked AS (
    SELECT b.bet01, b.bet03, b.bet04, b.bet05, b.bet09, b.bet11, b.bet13,
           b.bet15, b.bet16, b.bet17, b.bet18, b.bet19, b.bet20, b.bet21,
           b.bet22, b.bet23, b.bet24, b.bet25, b.bet26, b.bet27, b.bet38, b.bet39, b.category, b.commission,
           b.dt, b.eid, b.ip, b.validbet, b.updatetime, b.sync_time,
           ROW_NUMBER() OVER (
             PARTITION BY b.bet01
             ORDER BY b.updatetime DESC, b.sync_time DESC, b.dt DESC)      AS x_rn
    FROM ods_mariadb_2b.ods_a168_bet02 b
    WHERE b.dt >= '2026-03-21' AND b.dt < '2026-08-07'
      AND b.bet02 = '101'
      AND b.sync_time <= '2026-08-27 09:00:00'
  ),
    x_testagent AS (
    SELECT age001 AS agent_id FROM ods_mariadb_2b.ods_a168_agent WHERE age022 = '1'
  ),
    x_bs0 AS (
    SELECT b.bet05 AS x_member, b.eid AS x_dealer, b.bet39 AS x_table,
           b.bet03 AS x_shoe, b.ip AS x_ip, b.bet09 AS x_product, b.dt AS x_date,
           CONCAT_WS('|', b.bet03, b.bet04, b.bet39)                      AS x_round,
           CONCAT_WS('|', b.bet39, b.bet03)                               AS x_tblshoe,
           CAST(NULLIF(TRIM(b.bet04),'') AS INT)                          AS x_rno,
           CASE WHEN b.dt >= '2026-07-08' THEN 1 ELSE 0 END               AS x_rec,
           CASE WHEN TRIM(b.commission)='1' THEN 1 ELSE 0 END             AS x_freecomm,
           CAST(NULLIF(TRIM(b.bet13),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_stake,
           CAST(NULLIF(TRIM(b.validbet),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_valid,
           CAST(NULLIF(TRIM(b.bet16),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_rebate,
           CAST(NULLIF(TRIM(b.bet17),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_net,
           CAST(NULLIF(TRIM(b.bet15),'') AS DECIMAL(20,6))                AS x_rbpct,
           COALESCE(CAST(NULLIF(TRIM(b.bet23),'') AS DECIMAL(20,6)),0)   AS x_agpct,
          NULLIF(CAST(NULLIF(TRIM(b.bet23),'') AS DECIMAL(20,6)),0)     AS x_rate1,
          NULLIF(CAST(NULLIF(TRIM(b.bet24),'') AS DECIMAL(20,6)),0)     AS x_rate2,
          NULLIF(CAST(NULLIF(TRIM(b.bet25),'') AS DECIMAL(20,6)),0)     AS x_rate3,
          NULLIF(CAST(NULLIF(TRIM(b.bet26),'') AS DECIMAL(20,6)),0)     AS x_rate4,
          NULLIF(CAST(NULLIF(TRIM(b.bet27),'') AS DECIMAL(20,6)),0)     AS x_rate5,
          (CASE WHEN NULLIF(CAST(NULLIF(TRIM(b.bet22),'') AS BIGINT),0) IS NOT NULL THEN 5
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet21),'') AS BIGINT),0) IS NOT NULL THEN 4
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet20),'') AS BIGINT),0) IS NOT NULL THEN 3
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet19),'') AS BIGINT),0) IS NOT NULL THEN 2
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet18),'') AS BIGINT),0) IS NOT NULL THEN 1
                ELSE 0 END)                                             AS x_chain_depth,
           CASE WHEN COALESCE(t1.agent_id,t2.agent_id,t3.agent_id,
                              t4.agent_id,t5.agent_id) IS NOT NULL
                THEN 1 ELSE 0 END                                        AS f_testline
    FROM x_ranked b
    LEFT JOIN x_testagent t1 ON t1.agent_id = b.bet18
    LEFT JOIN x_testagent t2 ON t2.agent_id = b.bet19
    LEFT JOIN x_testagent t3 ON t3.agent_id = b.bet20
    LEFT JOIN x_testagent t4 ON t4.agent_id = b.bet21
    LEFT JOIN x_testagent t5 ON t5.agent_id = b.bet22
    WHERE b.x_rn = 1
      AND b.category='1' AND UPPER(TRIM(b.bet38))='N'
      AND CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8)) > 0
  ),
  x_mk AS (
    SELECT s.*,
           CASE WHEN s.f_testline = 0 THEN 1 ELSE 0 END                 AS is_clean
    FROM x_bs0 s
  ),
  x_agg AS (
    SELECT s.x_member                                                        AS x_key,
           COUNT(*) AS n_bets, COUNT(DISTINCT s.x_round) AS n_rounds,
           COUNT(DISTINCT s.x_date) AS active_days, COUNT(DISTINCT s.x_tblshoe) AS active_shoes,
           COUNT(DISTINCT CONCAT_WS('|', s.x_date, s.x_table)) AS active_sessions,
           COUNT(DISTINCT s.x_table) AS n_tables, COUNT(DISTINCT s.x_dealer) AS n_dealers,
           COUNT(DISTINCT s.x_ip) AS n_ips, COUNT(DISTINCT s.x_product) AS n_products,
           MIN(s.x_date) AS first_seen_d, MAX(s.x_date) AS last_seen_d,
           SUM(s.x_stake) AS stake, SUM(s.x_valid) AS valid, SUM(s.x_rebate) AS rebate,
           SUM(s.x_net) AS net, SUM(-s.x_net *(100.0-s.x_agpct)/100.0) AS agent_cost,
           AVG(100.0-s.x_agpct)                   AS agent_pct,
           AVG(s.x_agpct)                         AS company_retain_pct,
           SUM(-s.x_net *s.x_agpct/100.0)         AS agent_cost_a_legacy,
           SUM(s.x_valid*s.x_agpct/100.0)         AS agent_cost_valid_base_legacy,
          AVG(COALESCE(s.x_rate1,100)) AS retain_pct_lv1, AVG(COALESCE(s.x_rate2,100)) AS retain_pct_lv2,
          AVG(COALESCE(s.x_rate3,100)) AS retain_pct_lv3, AVG(COALESCE(s.x_rate4,100)) AS retain_pct_lv4,
          AVG(COALESCE(s.x_rate5,100)) AS retain_pct_lv5, AVG(s.x_chain_depth) AS chain_depth_avg,
          AVG(COALESCE(100.0-s.x_rate1,0)) AS agent_pct_lv1, AVG(COALESCE(100.0-s.x_rate2,0)) AS agent_pct_lv2,
          AVG(COALESCE(100.0-s.x_rate3,0)) AS agent_pct_lv3, AVG(COALESCE(100.0-s.x_rate4,0)) AS agent_pct_lv4,
          AVG(COALESCE(100.0-s.x_rate5,0)) AS agent_pct_lv5,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate1,0)/100.0)                        AS agent_cost_lv1,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate2,0)/100.0)                        AS agent_cost_lv2,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate3,0)/100.0)                        AS agent_cost_lv3,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate4,0)/100.0)                        AS agent_cost_lv4,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate5,0)/100.0)                        AS agent_cost_lv5,
          SUM(-s.x_net*(COALESCE(100.0-s.x_rate1,0)+COALESCE(100.0-s.x_rate2,0)
                       +COALESCE(100.0-s.x_rate3,0)+COALESCE(100.0-s.x_rate4,0)
                       +COALESCE(100.0-s.x_rate5,0))/100.0)                   AS agent_cost_chain_additive,
          SUM(-s.x_net*(1.0 - CAST(COALESCE(s.x_rate1,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate2,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate3,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate4,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate5,100) AS DOUBLE)/100.0))
                                                                       AS agent_cost_chain_nested,
           AVG(s.x_rbpct) AS rbpct, AVG(s.x_freecomm*1.0) AS freecomm_rate,
           PERCENTILE_APPROX(s.x_stake,0.25) AS p25, PERCENTILE_APPROX(s.x_stake,0.50) AS p50,
           PERCENTILE_APPROX(s.x_stake,0.75) AS p75, PERCENTILE_APPROX(s.x_stake,0.90) AS p90,
           PERCENTILE_APPROX(s.x_stake,0.95) AS p95, PERCENTILE_APPROX(s.x_stake,0.99) AS p99,
           PERCENTILE_APPROX(s.x_valid,0.50) AS p50_valid,
           PERCENTILE_APPROX(s.x_net,0.50)   AS p50_profit,
           SUM(CASE WHEN s.x_freecomm = 1 THEN s.x_stake ELSE 0 END) AS st_in,
           SUM(CASE WHEN s.x_freecomm = 1 THEN 1 ELSE 0 END)         AS nb_in,
           SUM(CASE WHEN s.x_freecomm = 1 THEN s.x_net ELSE 0 END)   AS net_in,
           SUM(CASE WHEN NOT (s.x_freecomm = 1) THEN s.x_stake ELSE 0 END) AS st_out,
           SUM(CASE WHEN NOT (s.x_freecomm = 1) THEN 1 ELSE 0 END)         AS nb_out,
           SUM(CASE WHEN NOT (s.x_freecomm = 1) THEN s.x_net ELSE 0 END)   AS net_out,
           SUM(CASE WHEN s.x_rec=1 THEN s.x_stake ELSE 0 END) AS st_rec,
           SUM(CASE WHEN s.x_rec=1 THEN 1 ELSE 0 END)         AS nb_rec
    FROM x_mk s
    WHERE s.is_clean = 1
      AND s.x_member IS NOT NULL AND TRIM(CAST(s.x_member AS STRING)) <> ''
    GROUP BY s.x_member
  ),
  x_win AS (
    SELECT            COUNT(*) AS n_bets, COUNT(DISTINCT s.x_round) AS n_rounds,
           COUNT(DISTINCT s.x_date) AS active_days, COUNT(DISTINCT s.x_tblshoe) AS active_shoes,
           COUNT(DISTINCT CONCAT_WS('|', s.x_date, s.x_table)) AS active_sessions,
           COUNT(DISTINCT s.x_table) AS n_tables, COUNT(DISTINCT s.x_dealer) AS n_dealers,
           COUNT(DISTINCT s.x_ip) AS n_ips, COUNT(DISTINCT s.x_product) AS n_products,
           MIN(s.x_date) AS first_seen_d, MAX(s.x_date) AS last_seen_d,
           SUM(s.x_stake) AS stake, SUM(s.x_valid) AS valid, SUM(s.x_rebate) AS rebate,
           SUM(s.x_net) AS net, SUM(-s.x_net *(100.0-s.x_agpct)/100.0) AS agent_cost,
           AVG(100.0-s.x_agpct)                   AS agent_pct,
           AVG(s.x_agpct)                         AS company_retain_pct,
           SUM(-s.x_net *s.x_agpct/100.0)         AS agent_cost_a_legacy,
           SUM(s.x_valid*s.x_agpct/100.0)         AS agent_cost_valid_base_legacy,
          AVG(COALESCE(s.x_rate1,100)) AS retain_pct_lv1, AVG(COALESCE(s.x_rate2,100)) AS retain_pct_lv2,
          AVG(COALESCE(s.x_rate3,100)) AS retain_pct_lv3, AVG(COALESCE(s.x_rate4,100)) AS retain_pct_lv4,
          AVG(COALESCE(s.x_rate5,100)) AS retain_pct_lv5, AVG(s.x_chain_depth) AS chain_depth_avg,
          AVG(COALESCE(100.0-s.x_rate1,0)) AS agent_pct_lv1, AVG(COALESCE(100.0-s.x_rate2,0)) AS agent_pct_lv2,
          AVG(COALESCE(100.0-s.x_rate3,0)) AS agent_pct_lv3, AVG(COALESCE(100.0-s.x_rate4,0)) AS agent_pct_lv4,
          AVG(COALESCE(100.0-s.x_rate5,0)) AS agent_pct_lv5,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate1,0)/100.0)                        AS agent_cost_lv1,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate2,0)/100.0)                        AS agent_cost_lv2,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate3,0)/100.0)                        AS agent_cost_lv3,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate4,0)/100.0)                        AS agent_cost_lv4,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate5,0)/100.0)                        AS agent_cost_lv5,
          SUM(-s.x_net*(COALESCE(100.0-s.x_rate1,0)+COALESCE(100.0-s.x_rate2,0)
                       +COALESCE(100.0-s.x_rate3,0)+COALESCE(100.0-s.x_rate4,0)
                       +COALESCE(100.0-s.x_rate5,0))/100.0)                   AS agent_cost_chain_additive,
          SUM(-s.x_net*(1.0 - CAST(COALESCE(s.x_rate1,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate2,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate3,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate4,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate5,100) AS DOUBLE)/100.0))
                                                                       AS agent_cost_chain_nested,
           AVG(s.x_rbpct) AS rbpct, AVG(s.x_freecomm*1.0) AS freecomm_rate,
           PERCENTILE_APPROX(s.x_stake,0.25) AS p25, PERCENTILE_APPROX(s.x_stake,0.50) AS p50,
           PERCENTILE_APPROX(s.x_stake,0.75) AS p75, PERCENTILE_APPROX(s.x_stake,0.90) AS p90,
           PERCENTILE_APPROX(s.x_stake,0.95) AS p95, PERCENTILE_APPROX(s.x_stake,0.99) AS p99,
           PERCENTILE_APPROX(s.x_valid,0.50) AS p50_valid,
           PERCENTILE_APPROX(s.x_net,0.50)   AS p50_profit,
           SUM(CASE WHEN s.x_freecomm = 1 THEN s.x_stake ELSE 0 END) AS st_in,
           SUM(CASE WHEN s.x_freecomm = 1 THEN 1 ELSE 0 END)         AS nb_in,
           SUM(CASE WHEN s.x_freecomm = 1 THEN s.x_net ELSE 0 END)   AS net_in,
           SUM(CASE WHEN NOT (s.x_freecomm = 1) THEN s.x_stake ELSE 0 END) AS st_out,
           SUM(CASE WHEN NOT (s.x_freecomm = 1) THEN 1 ELSE 0 END)         AS nb_out,
           SUM(CASE WHEN NOT (s.x_freecomm = 1) THEN s.x_net ELSE 0 END)   AS net_out,
           SUM(CASE WHEN s.x_rec=1 THEN s.x_stake ELSE 0 END) AS st_rec,
           SUM(CASE WHEN s.x_rec=1 THEN 1 ELSE 0 END)         AS nb_rec
    FROM x_mk s
    WHERE s.is_clean = 1
      AND s.x_member IS NOT NULL AND TRIM(CAST(s.x_member AS STRING)) <> ''
  ),
      q AS (
        SELECT                                                                                              -- 取列：起始取列子句
          'bet23'                                                                AS field_name,             -- 字面取值：受检字段名
          COALESCE(NULLIF(TRIM(bet23), ''), '(空)')                              AS field_value,            -- 条件取值：字段取值，空另列
          COUNT(*)                                                               AS n_rows,                 -- 计数表达式：该取值之行数
          SUM(CASE WHEN CAST(NULLIF(TRIM(bet13), '') AS DECIMAL(20,8))
                       - CAST(NULLIF(TRIM(bet14), '') AS DECIMAL(20,8)) = 0 THEN 1 ELSE 0 END) AS n_pnl_zero, -- 条件计数：净输赢为零
          SUM(CASE WHEN CAST(NULLIF(TRIM(bet13), '') AS DECIMAL(20,8))
                       - CAST(NULLIF(TRIM(bet14), '') AS DECIMAL(20,8)) > 0 THEN 1 ELSE 0 END) AS n_pnl_pos,  -- 条件计数：会员输
          SUM(CASE WHEN CAST(NULLIF(TRIM(bet13), '') AS DECIMAL(20,8))
                       - CAST(NULLIF(TRIM(bet14), '') AS DECIMAL(20,8)) < 0 THEN 1 ELSE 0 END) AS n_pnl_neg,  -- 条件计数：会员赢
          SUM(CASE WHEN CAST(NULLIF(TRIM(bet14), '') AS DECIMAL(20,8)) = 0 THEN 1 ELSE 0 END)   AS n_payout_zero, -- 条件计数：派彩为零
          COUNT(DISTINCT TRIM(bet09))                                            AS n_bet09,                -- 计数表达式：涉及注型数
          CASE                                                                                              -- 条件分支：起始分支——对齐度裁定
            WHEN SUM(CASE WHEN CAST(NULLIF(TRIM(bet13), '') AS DECIMAL(20,8))
                             - CAST(NULLIF(TRIM(bet14), '') AS DECIMAL(20,8)) = 0 THEN 1 ELSE 0 END) = COUNT(*)
              THEN '★ 该取值下 pnl 恒零 —— PUSH 之强候选'                                                     -- 分支判定：恒零
            WHEN SUM(CASE WHEN CAST(NULLIF(TRIM(bet13), '') AS DECIMAL(20,8))
                             - CAST(NULLIF(TRIM(bet14), '') AS DECIMAL(20,8)) > 0 THEN 1 ELSE 0 END) = COUNT(*)
              THEN '★ 该取值下 pnl 恒正 —— LOSS 之强候选'                                                     -- 分支判定：恒正
            WHEN SUM(CASE WHEN CAST(NULLIF(TRIM(bet13), '') AS DECIMAL(20,8))
                             - CAST(NULLIF(TRIM(bet14), '') AS DECIMAL(20,8)) < 0 THEN 1 ELSE 0 END) = COUNT(*)
              THEN '★ 该取值下 pnl 恒负 —— WIN 之强候选'                                                      -- 分支判定：恒负
            ELSE '◐ 三态混杂 —— 该取值非结算态之判别'                                                          -- 分支判定：混杂
          END                                                                    AS verdict_align           -- 条件分支：收束上方判词，产出「verdict_align」
        FROM ods_mariadb_2b.ods_a168_bet02                                                                  -- 取数来源：取自注单主表
        WHERE dt >= '2026-03-21' AND dt < '2026-08-07'                                                      -- 过滤条件：限定分析窗
          AND sync_time <= '2026-08-27 09:00:00'
          AND CAST(bet02 AS STRING) = '101'                                                                 -- 并列条件：限定百家乐
          AND TRIM(category) = '1'                                                                          -- 并列条件：只看 QSB 候选宇宙
        GROUP BY COALESCE(NULLIF(TRIM(bet23), ''), '(空)')                                                  -- 分组：按 bet23 取值汇总
        
        UNION ALL                                                                                           -- 集合运算：并接下一候选字段之同构结果
        
        SELECT                                                                                              -- 取列：起始取列子句
          'bet24'                                                                AS field_name,             -- 字面取值：受检字段名
          COALESCE(NULLIF(TRIM(bet24), ''), '(空)')                              AS field_value,            -- 条件取值：字段取值，空另列
          COUNT(*)                                                               AS n_rows,                 -- 计数表达式：该取值之行数
          SUM(CASE WHEN CAST(NULLIF(TRIM(bet13), '') AS DECIMAL(20,8))
                       - CAST(NULLIF(TRIM(bet14), '') AS DECIMAL(20,8)) = 0 THEN 1 ELSE 0 END) AS n_pnl_zero, -- 条件计数：净输赢为零
          SUM(CASE WHEN CAST(NULLIF(TRIM(bet13), '') AS DECIMAL(20,8))
                       - CAST(NULLIF(TRIM(bet14), '') AS DECIMAL(20,8)) > 0 THEN 1 ELSE 0 END) AS n_pnl_pos,  -- 条件计数：会员输
          SUM(CASE WHEN CAST(NULLIF(TRIM(bet13), '') AS DECIMAL(20,8))
                       - CAST(NULLIF(TRIM(bet14), '') AS DECIMAL(20,8)) < 0 THEN 1 ELSE 0 END) AS n_pnl_neg,  -- 条件计数：会员赢
          SUM(CASE WHEN CAST(NULLIF(TRIM(bet14), '') AS DECIMAL(20,8)) = 0 THEN 1 ELSE 0 END)   AS n_payout_zero, -- 条件计数：派彩为零
          COUNT(DISTINCT TRIM(bet09))                                            AS n_bet09,                -- 计数表达式：涉及注型数
          CASE                                                                                              -- 条件分支：起始分支——对齐度裁定
            WHEN SUM(CASE WHEN CAST(NULLIF(TRIM(bet13), '') AS DECIMAL(20,8))
                             - CAST(NULLIF(TRIM(bet14), '') AS DECIMAL(20,8)) = 0 THEN 1 ELSE 0 END) = COUNT(*)
              THEN '★ 该取值下 pnl 恒零 —— PUSH 之强候选'                                                     -- 分支判定：恒零
            WHEN SUM(CASE WHEN CAST(NULLIF(TRIM(bet13), '') AS DECIMAL(20,8))
                             - CAST(NULLIF(TRIM(bet14), '') AS DECIMAL(20,8)) > 0 THEN 1 ELSE 0 END) = COUNT(*)
              THEN '★ 该取值下 pnl 恒正 —— LOSS 之强候选'                                                     -- 分支判定：恒正
            WHEN SUM(CASE WHEN CAST(NULLIF(TRIM(bet13), '') AS DECIMAL(20,8))
                             - CAST(NULLIF(TRIM(bet14), '') AS DECIMAL(20,8)) < 0 THEN 1 ELSE 0 END) = COUNT(*)
              THEN '★ 该取值下 pnl 恒负 —— WIN 之强候选'                                                      -- 分支判定：恒负
            ELSE '◐ 三态混杂 —— 该取值非结算态之判别'                                                          -- 分支判定：混杂
          END                                                                    AS verdict_align           -- 条件分支：收束上方判词，产出「verdict_align」
        FROM ods_mariadb_2b.ods_a168_bet02                                                                  -- 取数来源：取自注单主表
        WHERE dt >= '2026-03-21' AND dt < '2026-08-07'                                                      -- 过滤条件：限定分析窗
          AND sync_time <= '2026-08-27 09:00:00'
          AND CAST(bet02 AS STRING) = '101'                                                                 -- 并列条件：限定百家乐
          AND TRIM(category) = '1'                                                                          -- 并列条件：只看 QSB 候选宇宙
        GROUP BY COALESCE(NULLIF(TRIM(bet24), ''), '(空)')                                                  -- 分组：按 bet24 取值汇总
        
        UNION ALL                                                                                           -- 集合运算：并接下一候选字段之同构结果
        
        SELECT                                                                                              -- 取列：起始取列子句
          'bet40'                                                                AS field_name,             -- 字面取值：受检字段名
          COALESCE(NULLIF(TRIM(bet40), ''), '(空)')                              AS field_value,            -- 条件取值：字段取值，空另列
          COUNT(*)                                                               AS n_rows,                 -- 计数表达式：该取值之行数
          SUM(CASE WHEN CAST(NULLIF(TRIM(bet13), '') AS DECIMAL(20,8))
                       - CAST(NULLIF(TRIM(bet14), '') AS DECIMAL(20,8)) = 0 THEN 1 ELSE 0 END) AS n_pnl_zero, -- 条件计数：净输赢为零
          SUM(CASE WHEN CAST(NULLIF(TRIM(bet13), '') AS DECIMAL(20,8))
                       - CAST(NULLIF(TRIM(bet14), '') AS DECIMAL(20,8)) > 0 THEN 1 ELSE 0 END) AS n_pnl_pos,  -- 条件计数：会员输
          SUM(CASE WHEN CAST(NULLIF(TRIM(bet13), '') AS DECIMAL(20,8))
                       - CAST(NULLIF(TRIM(bet14), '') AS DECIMAL(20,8)) < 0 THEN 1 ELSE 0 END) AS n_pnl_neg,  -- 条件计数：会员赢
          SUM(CASE WHEN CAST(NULLIF(TRIM(bet14), '') AS DECIMAL(20,8)) = 0 THEN 1 ELSE 0 END)   AS n_payout_zero, -- 条件计数：派彩为零
          COUNT(DISTINCT TRIM(bet09))                                            AS n_bet09,                -- 计数表达式：涉及注型数
          CASE                                                                                              -- 条件分支：起始分支——对齐度裁定
            WHEN SUM(CASE WHEN CAST(NULLIF(TRIM(bet13), '') AS DECIMAL(20,8))
                             - CAST(NULLIF(TRIM(bet14), '') AS DECIMAL(20,8)) = 0 THEN 1 ELSE 0 END) = COUNT(*)
              THEN '★ 该取值下 pnl 恒零 —— PUSH 之强候选'                                                     -- 分支判定：恒零
            WHEN SUM(CASE WHEN CAST(NULLIF(TRIM(bet13), '') AS DECIMAL(20,8))
                             - CAST(NULLIF(TRIM(bet14), '') AS DECIMAL(20,8)) > 0 THEN 1 ELSE 0 END) = COUNT(*)
              THEN '★ 该取值下 pnl 恒正 —— LOSS 之强候选'                                                     -- 分支判定：恒正
            WHEN SUM(CASE WHEN CAST(NULLIF(TRIM(bet13), '') AS DECIMAL(20,8))
                             - CAST(NULLIF(TRIM(bet14), '') AS DECIMAL(20,8)) < 0 THEN 1 ELSE 0 END) = COUNT(*)
              THEN '★ 该取值下 pnl 恒负 —— WIN 之强候选'                                                      -- 分支判定：恒负
            ELSE '◐ 三态混杂 —— 该取值非结算态之判别'                                                          -- 分支判定：混杂
          END                                                                    AS verdict_align           -- 条件分支：收束上方判词，产出「verdict_align」
        FROM ods_mariadb_2b.ods_a168_bet02                                                                  -- 取数来源：取自注单主表
        WHERE dt >= '2026-03-21' AND dt < '2026-08-07'                                                      -- 过滤条件：限定分析窗
          AND sync_time <= '2026-08-27 09:00:00'
          AND CAST(bet02 AS STRING) = '101'                                                                 -- 并列条件：限定百家乐
          AND TRIM(category) = '1'                                                                          -- 并列条件：只看 QSB 候选宇宙
        GROUP BY COALESCE(NULLIF(TRIM(bet40), ''), '(空)')                                                  -- 分组：按 bet40 取值汇总
      )
    SELECT q.*,
           -- 一·经济层
           ROUND(e.stake,4) AS stake, ROUND(e.valid,4) AS valid_bet,
           ROUND(-e.net,4) AS profit, e.n_bets, e.n_rounds,
           ROUND(e.net/NULLIF(e.stake,0),8) AS roi,
           ROUND(e.net_in/NULLIF(e.st_in,0),8) AS roi_freecomm,
           ROUND(e.net_out/NULLIF(e.st_out,0),8) AS roi_non_freecomm,
           ROUND((e.net-e.rebate)/NULLIF(e.stake,0),8) AS roi_ex_rebate,
           ROUND(e.net,4) AS roi_numerator, ROUND(e.stake,4) AS roi_denominator,
           CASE WHEN e.stake IS NULL THEN 'NULL_DENOM' WHEN e.stake<=0 THEN 'ZERO_DENOM'
                WHEN e.n_bets<30 THEN 'THIN_EXPOSURE' ELSE 'OK' END AS roi_denominator_status,
           ROUND(e.rebate,4) AS rebate_cost, ROUND(e.agent_cost,4)                           AS cost_complement_b,
       ROUND(e.agent_pct,4)                            AS pct_complement,
       ROUND(e.company_retain_pct,4)                   AS pct_top_bet23,
       'AG03-UNRESOLVED'                                     AS agent_formula_version,
      'ALL5_LEVELS_bet23_to_bet27'                    AS agent_level_scope,
      ROUND(e.agent_cost_lv1,4) AS agent_cost_lv1, ROUND(e.agent_cost_lv2,4) AS agent_cost_lv2,
      ROUND(e.agent_cost_lv3,4) AS agent_cost_lv3, ROUND(e.agent_cost_lv4,4) AS agent_cost_lv4,
      ROUND(e.agent_cost_lv5,4) AS agent_cost_lv5,
      ROUND(e.agent_pct_lv1,6) AS agent_pct_lv1, ROUND(e.agent_pct_lv2,6) AS agent_pct_lv2,
      ROUND(e.agent_pct_lv3,6) AS agent_pct_lv3, ROUND(e.agent_pct_lv4,6) AS agent_pct_lv4,
      ROUND(e.agent_pct_lv5,6) AS agent_pct_lv5,
      ROUND(e.retain_pct_lv1,6) AS retain_pct_lv1, ROUND(e.retain_pct_lv2,6) AS retain_pct_lv2,
      ROUND(e.retain_pct_lv3,6) AS retain_pct_lv3, ROUND(e.retain_pct_lv4,6) AS retain_pct_lv4,
      ROUND(e.retain_pct_lv5,6) AS retain_pct_lv5, ROUND(e.chain_depth_avg,4) AS chain_depth_avg,
      ROUND(e.agent_cost_chain_additive,4)            AS agent_cost_chain_additive,
      ROUND(e.agent_cost_chain_nested,4)              AS agent_cost_chain_nested,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_additive,4) AS residual_chain_additive,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_nested,4)   AS residual_chain_nested,
      'PENDING_AG03'                                  AS decision_status,
      'FALSE'                                         AS admit_to_risk_decision,
      'NOT_FOR_ENFORCEMENT'                           AS deliverable_class,
       ROUND(e.agent_cost_a_legacy,4)                  AS agent_cost_a_legacy,
       ROUND(e.agent_cost_valid_base_legacy,4)         AS agent_cost_valid_base_legacy,
           ROUND(-e.net-e.rebate,4)                        AS ngr,
       ROUND(-e.net-e.rebate-e.agent_cost,4)           AS residual_b,
       ROUND(-e.net-e.rebate-e.agent_cost_a_legacy,4)  AS residual_a,
           ROUND((-e.net-e.rebate)/NULLIF(e.stake,0),8)    AS ngr_rate,
       ROUND((-e.net-e.rebate-e.agent_cost)/NULLIF(e.stake,0),8)   AS residual_b_rate,
      -- 【HF9c · canonical accounting contract】
      --   以下 canonical 字段只增加明确 scope；不删除、不覆盖既有字段。
      --   formal_bet23_* 保持 HF9b 当前生产公式及其 NULL/0 语义；
      --   lv1~lv5 / additive / nested 则分别采用各自原始 e.* 成本字段，
      --   rate 一律从未舍入的 e.* 分子 / e.stake 计算，禁止由展示值反算。
      ROUND(e.agent_cost,4) AS agent_cost_bet23_formal_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost,4) AS net_margin_bet23_formal_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost)/NULLIF(e.stake,0),8) AS net_margin_bet23_formal_rate_canonical,
      ROUND(e.agent_cost_lv1,4) AS agent_cost_lv1_bet23_canonical,
      ROUND(e.agent_cost_lv2,4) AS agent_cost_lv2_bet24_canonical,
      ROUND(e.agent_cost_lv3,4) AS agent_cost_lv3_bet25_canonical,
      ROUND(e.agent_cost_lv4,4) AS agent_cost_lv4_bet26_canonical,
      ROUND(e.agent_cost_lv5,4) AS agent_cost_lv5_bet27_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_lv1,4) AS net_margin_lv1_bet23_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_lv1)/NULLIF(e.stake,0),8) AS net_margin_lv1_bet23_rate_canonical,
      ROUND(e.agent_cost_chain_additive,4) AS agent_cost_chain_additive_canonical,
      ROUND(e.agent_cost_chain_nested,4) AS agent_cost_chain_nested_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_additive,4) AS net_margin_chain_additive_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_nested,4) AS net_margin_chain_nested_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_chain_additive)/NULLIF(e.stake,0),8) AS net_margin_chain_additive_rate_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_chain_nested)/NULLIF(e.stake,0),8) AS net_margin_chain_nested_rate_canonical,
       ROUND((-e.net-e.rebate-e.agent_cost_a_legacy)/NULLIF(e.stake,0),8) AS residual_a_rate,
           -- 二·分布层
           ROUND(e.stake/NULLIF(e.n_bets,0),4) AS avg_stake_per_bet,
           ROUND(e.valid/NULLIF(e.n_rounds,0),4) AS avg_valid_bet_per_round,
           ROUND(-e.net/NULLIF(e.n_rounds,0),4) AS avg_profit_per_round,
           ROUND(-e.net/NULLIF(e.active_days,0),4) AS avg_profit_per_day,
           ROUND(-e.net/NULLIF(e.active_shoes,0),4) AS avg_profit_per_shoe,
           ROUND(e.stake/NULLIF(e.active_days,0),4) AS avg_stake_per_active_day,
           ROUND(e.n_rounds*1.0/NULLIF(e.active_days,0),4) AS avg_rounds_per_active_day,
           ROUND(e.st_in/NULLIF(e.nb_in,0),4) AS avg_stake_freecomm,
           ROUND(e.st_out/NULLIF(e.nb_out,0),4) AS avg_stake_non_freecomm,
           ROUND(e.p25,4) AS p25_stake, ROUND(e.p50,4) AS p50_stake, ROUND(e.p75,4) AS p75_stake,
           ROUND(e.p90,4) AS p90_stake, ROUND(e.p95,4) AS p95_stake, ROUND(e.p99,4) AS p99_stake,
           ROUND(e.p50_valid,4) AS p50_valid_bet, ROUND(e.p50_profit,4) AS p50_profit,
           ROUND(e.p95/NULLIF(e.p50,0),6) AS p95_over_p50,
           ROUND(e.p99/NULLIF(e.p50,0),6) AS p99_over_p50,
           ROUND((e.stake/NULLIF(e.n_bets,0))/NULLIF(e.p50,0),6) AS avg_over_p50,
           -- 三·关系层
           e.n_tables AS common_table_count, e.n_dealers AS common_dealer_count,
           e.n_ips AS common_ip_count, e.n_products AS common_product_count,
           ROUND(e.st_in/NULLIF(e.stake,0),8) AS share_freecomm,
           -- 四·rate 层
           ROUND(-e.net/NULLIF(e.stake,0),8) AS hold_rate,
           ROUND(-e.net_in/NULLIF(e.st_in,0),8) AS hold_rate_freecomm,
           ROUND(e.rebate/NULLIF(e.valid,0),8) AS rebate_rate_actual,
           ROUND(e.rbpct,6) AS rebate_pct_config,
           ROUND(e.valid/NULLIF(e.stake,0),6) AS turnover_multiple,
           ROUND(e.freecomm_rate,6) AS free_comm_rate,
           ROUND(e.net_in/NULLIF(e.st_in,0)-e.net_out/NULLIF(e.st_out,0),8) AS roi_delta_freecomm,
           -- 五·动态层
           e.first_seen_d AS first_seen, e.last_seen_d AS last_seen,
           e.active_days, e.active_shoes, e.active_sessions,
           DATEDIFF(e.last_seen_d, e.first_seen_d)+1 AS span_days,
           ROUND(e.active_days*1.0/NULLIF(DATEDIFF(e.last_seen_d,e.first_seen_d)+1,0),6) AS persistence,
           ROUND((e.st_in/NULLIF(e.nb_in,0))/NULLIF(e.st_out/NULLIF(e.nb_out,0),0),6) AS ramp_freecomm,
           ROUND((e.st_rec/NULLIF(e.nb_rec,0))/NULLIF(e.stake/NULLIF(e.n_bets,0),0),6) AS ramp_recent,
           ROUND((e.st_rec/NULLIF(e.stake,0))/0.30,6) AS stake_ramp,
           -- 六·决策层（HF9g-P5 · D-14 斧正 —— 本件属【全窗基线族】，相对刻度与决策标签一律 NULL）
           --   病灶：x_win 系全窗单行聚合（无 GROUP BY，恒 1 行，此为设计使然，非缺陷），
           --         经 CROSS JOIN 接入后 e.* 全行同值；六层之 NTILE / PERCENT_RANK 施于常数即退化，
           --         PERCENT_RANK 恒 0 ⇒ action_priority 恒判 A，全件 100% 误标。
           --   ★ 斧正原则：不给 x_win 补 GROUP BY —— 那会改变其「全窗基线」语义，属退化。
           --     正解与 #018 之 G-05／G-06 同治：范围外之行不得接受任何下游评分与决策标签。
           --   ★ 本件之 e.* 仍照常供其它列作全窗基线使用，仅六层相对刻度与决策标签置 NULL。
           CAST(NULL AS INT)                                              AS vip_tier,                        -- 空值取值：全窗基线族无实体可分档，置 NULL（NULL＝不适用，非 0）
           CAST(NULL AS DOUBLE)                                           AS economic_value,                  -- 空值取值：同上，禁以常数百分位冒充经济价值
           CAST(NULL AS DOUBLE)                                           AS roi_pr_global,                   -- 空值取值：同上
           CAST(NULL AS DOUBLE)                                           AS risk_value,                      -- 空值取值：兼容列，同上
           CAST(NULL AS DOUBLE)                                           AS pr_stake,                        -- 空值取值：兼容列，同上
           CAST(NULL AS DOUBLE)                                           AS pr_global,                       -- 空值取值：同上
           CAST(NULL AS DOUBLE)                                           AS pr_qualified,                    -- 空值取值：同上
           'GLOBAL_BASELINE_NO_ENTITY_RANKING'                            AS pr_qualified_population,         -- 字面取值：血统 —— 明示本件为全窗基线族，无实体排序总体
           CAST(NULL AS BIGINT)                                           AS pr_global_population_n,          -- 空值取值：血统 —— 不适用
           CAST(NULL AS BIGINT)                                           AS pr_qualified_population_n,       -- 空值取值：血统 —— 不适用
           'NOT_APPLICABLE_GLOBAL_BASELINE'                               AS pr_calculation_method,           -- 字面取值：血统 —— 算法不适用
           'HF9g-P5'                                                      AS pr_calculation_version,          -- 字面取值：血统 —— 算法版本
           CAST(NULL AS STRING)                                           AS evidence_flag,                   -- 空值取值：证据旗标不适用于全窗基线
           CAST(NULL AS STRING)                                           AS evidence_rate,                   -- 空值取值：同上
           CAST(NULL AS DOUBLE)                                           AS hold_ci_halfwidth_approx,        -- 空值取值：同上
           'X 全窗基线 · 不参与实体赏罚'                                    AS action_priority                  -- 字面取值：★ D-14 斧正 —— 本族恒不入赏罚，取代原 100% 误标之「A」
    FROM q
    CROSS JOIN x_win e
  ) y
) z
-- ── 逐批 WHERE 阶梯（★ 口诀：上界 ＝ 下界 ＋ 100000，两数同进）──
--    本件 T_true 未测，无需先跑 T_true；以 0 / 100000 控制本批返回区间，末批由实际行数 < 100000 判定
--    WHERE z.audit_rn >        0 AND z.audit_rn <=   100000   -- 第 1 批
--    WHERE z.audit_rn >   100000 AND z.audit_rn <=   200000   -- 第 2 批
--    WHERE z.audit_rn >   200000 AND z.audit_rn <=   300000   -- 第 3 批
--    WHERE z.audit_rn >   300000 AND z.audit_rn <=   400000   -- 第 4 批
--    WHERE z.audit_rn >   400000 AND z.audit_rn <=   500000   -- 第 5 批
--    WHERE z.audit_rn >   500000 AND z.audit_rn <=   600000   -- 第 6 批
--    WHERE z.audit_rn >   600000 AND z.audit_rn <=   700000   -- 第 7 批
--    …余批类推。第 k 批：WHERE z.audit_rn > (k-1)*100000 AND z.audit_rn <= k*100000
--    某批返回 < 100000 行即为末批，其后不再取。
--
--    ⚠ 常见误写（务必避开）：只推下界而上界不动 ——
--        WHERE z.audit_rn > 100000 AND z.audit_rn <= 100000   ← 自相矛盾，恒为假，返回空集
--        WHERE z.audit_rn > 200000 AND z.audit_rn <= 100000   ← 同上，空集
--      两个数必须**同时**前进，且始终相差 100000。
--      下界 ＝ 上一批之上界；上界 ＝ 本批之上界。
WHERE z.audit_rn > 0 AND z.audit_rn <= 100000 -- ★ HF9c 本批区间
ORDER BY z.audit_rn;


-- ══════════════════════════════════════════════════════════════════════════════════════════════
--  63. QSB_02c_push_by_family.csv   [总包行 11437~11489 · 原 10 列 ＋六层约 60 列]
--     典型学：M14 投注形态　派生旗标：freecomm（s.x_freecomm = 1 · 仅供 CASE 条件聚合，全包无任何 WHERE/AND/HAVING 以此过滤）　连接：全窗基线
-- ══════════════════════════════════════════════════════════════════════════════════════════════
-- ★ W-64 · D-14 警示（本件属 x_win 族 · 66 件之一 · 详见 §Z 段 D-14 全案）
--   本件以 `CROSS JOIN x_win e` 接入全局基线，x_win 无 GROUP BY ⇒ 恒 1 行 ⇒ e.* 全行同值。
--   故：economic_value / roi_pr_global / risk_value / pr_stake / pr_global 恒为 0；
--       action_priority 每一行皆为「A 净亏最大十分位 · 优先复核」（Z 分支永不触发）；
--       evidence_rate 恒为最高档；vip_tier 由常数键分档 ⇒ 无信息且非确定。
--   ⇒ 本件决策层三列 **NOT_FOR_DECISION**，裁定前不得用于排班、抽查或汇报。
-- ── ① 先跑 T_true 留档（不足 100000 者一次导全，不必分批）──
-- ── ① T_true：HF9c 不再强制预跑完整 COUNT。
--    本批实际返回行数 < 100000 即判定为末批；全批完成后以各批 n_rows / audit_rn 范围核对总量。

-- ── ② 分批取数：第 1 批。第 k 批只改末行两数为 (k-1)*100000 与 k*100000 ──
--    审计字段二（REDTEAM 2026-08-24 裁定 · 四锁）：
--      audit_rn  全局观测坐标 —— 由**与原版审计版逐字同一**之排序键所生，两版可逐行对账
--      batch_id  物理分批信息 —— 该行所属批次，由 audit_rn 算得，非引擎所赋
--    ★ 锁三：二者皆为审计字段，**不得进入任何业务指标计算**。
--    ★ 锁四：两版经 audit_rn 逐行字段核验后，方可宣布输出完全一致。

-- ── ③ 每批取回后自证四数（任一不符即停手回报，禁止放行）──
--    n_rows        = COUNT(*)      须等于 COUNT(DISTINCT audit_rn)   （批内无重复）
--    audit_rn_min  = MIN(audit_rn) 须等于 (k-1)*100000 + 1           （与上批严丝合缝）
--    audit_rn_max  = MAX(audit_rn) 须等于 min + n_rows - 1           （批内无缺口）
--    全批取毕再验：各批 audit_rn 之并集 = 1 .. T_true，无缺号、无重号。
--     ★ 首行＝平台真净亏最多者（已扣退水与代理占成）。
--
SELECT z.*,
       CAST(FLOOR((z.audit_rn - 1) / 100000) + 1 AS INT)          AS batch_id,
       'A168_HF9F_20260827_0900' AS run_id,
       '2026-08-27 09:00:00' AS snapshot_sync_time
FROM (
  SELECT y.*,
         ROW_NUMBER() OVER (ORDER BY y.`residual_b` ASC, y.`roi` DESC, y.`bet09_family`, y.`n_bet09_in_family`, y.`n_rows`, y.`n_pnl_zero`, y.`pct_pnl_zero`, y.`n_exact_refund`, y.`n_payout_zero_stake_pos`, y.`pct_player_win`, y.`mu0_pct`, y.`verdict_family`) AS audit_rn
  FROM (
    WITH
      x_ranked AS (
    SELECT b.bet01, b.bet03, b.bet04, b.bet05, b.bet09, b.bet11, b.bet13,
           b.bet15, b.bet16, b.bet17, b.bet18, b.bet19, b.bet20, b.bet21,
           b.bet22, b.bet23, b.bet24, b.bet25, b.bet26, b.bet27, b.bet38, b.bet39, b.category, b.commission,
           b.dt, b.eid, b.ip, b.validbet, b.updatetime, b.sync_time,
           ROW_NUMBER() OVER (
             PARTITION BY b.bet01
             ORDER BY b.updatetime DESC, b.sync_time DESC, b.dt DESC)      AS x_rn
    FROM ods_mariadb_2b.ods_a168_bet02 b
    WHERE b.dt >= '2026-03-21' AND b.dt < '2026-08-07'
      AND b.bet02 = '101'
      AND b.sync_time <= '2026-08-27 09:00:00'
  ),
    x_testagent AS (
    SELECT age001 AS agent_id FROM ods_mariadb_2b.ods_a168_agent WHERE age022 = '1'
  ),
    x_bs0 AS (
    SELECT b.bet05 AS x_member, b.eid AS x_dealer, b.bet39 AS x_table,
           b.bet03 AS x_shoe, b.ip AS x_ip, b.bet09 AS x_product, b.dt AS x_date,
           CONCAT_WS('|', b.bet03, b.bet04, b.bet39)                      AS x_round,
           CONCAT_WS('|', b.bet39, b.bet03)                               AS x_tblshoe,
           CAST(NULLIF(TRIM(b.bet04),'') AS INT)                          AS x_rno,
           CASE WHEN b.dt >= '2026-07-08' THEN 1 ELSE 0 END               AS x_rec,
           CASE WHEN TRIM(b.commission)='1' THEN 1 ELSE 0 END             AS x_freecomm,
           CAST(NULLIF(TRIM(b.bet13),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_stake,
           CAST(NULLIF(TRIM(b.validbet),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_valid,
           CAST(NULLIF(TRIM(b.bet16),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_rebate,
           CAST(NULLIF(TRIM(b.bet17),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_net,
           CAST(NULLIF(TRIM(b.bet15),'') AS DECIMAL(20,6))                AS x_rbpct,
           COALESCE(CAST(NULLIF(TRIM(b.bet23),'') AS DECIMAL(20,6)),0)   AS x_agpct,
          NULLIF(CAST(NULLIF(TRIM(b.bet23),'') AS DECIMAL(20,6)),0)     AS x_rate1,
          NULLIF(CAST(NULLIF(TRIM(b.bet24),'') AS DECIMAL(20,6)),0)     AS x_rate2,
          NULLIF(CAST(NULLIF(TRIM(b.bet25),'') AS DECIMAL(20,6)),0)     AS x_rate3,
          NULLIF(CAST(NULLIF(TRIM(b.bet26),'') AS DECIMAL(20,6)),0)     AS x_rate4,
          NULLIF(CAST(NULLIF(TRIM(b.bet27),'') AS DECIMAL(20,6)),0)     AS x_rate5,
          (CASE WHEN NULLIF(CAST(NULLIF(TRIM(b.bet22),'') AS BIGINT),0) IS NOT NULL THEN 5
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet21),'') AS BIGINT),0) IS NOT NULL THEN 4
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet20),'') AS BIGINT),0) IS NOT NULL THEN 3
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet19),'') AS BIGINT),0) IS NOT NULL THEN 2
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet18),'') AS BIGINT),0) IS NOT NULL THEN 1
                ELSE 0 END)                                             AS x_chain_depth,
           CASE WHEN COALESCE(t1.agent_id,t2.agent_id,t3.agent_id,
                              t4.agent_id,t5.agent_id) IS NOT NULL
                THEN 1 ELSE 0 END                                        AS f_testline
    FROM x_ranked b
    LEFT JOIN x_testagent t1 ON t1.agent_id = b.bet18
    LEFT JOIN x_testagent t2 ON t2.agent_id = b.bet19
    LEFT JOIN x_testagent t3 ON t3.agent_id = b.bet20
    LEFT JOIN x_testagent t4 ON t4.agent_id = b.bet21
    LEFT JOIN x_testagent t5 ON t5.agent_id = b.bet22
    WHERE b.x_rn = 1
      AND b.category='1' AND UPPER(TRIM(b.bet38))='N'
      AND CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8)) > 0
  ),
  x_mk AS (
    SELECT s.*,
           CASE WHEN s.f_testline = 0 THEN 1 ELSE 0 END                 AS is_clean
    FROM x_bs0 s
  ),
  x_agg AS (
    SELECT s.x_member                                                        AS x_key,
           COUNT(*) AS n_bets, COUNT(DISTINCT s.x_round) AS n_rounds,
           COUNT(DISTINCT s.x_date) AS active_days, COUNT(DISTINCT s.x_tblshoe) AS active_shoes,
           COUNT(DISTINCT CONCAT_WS('|', s.x_date, s.x_table)) AS active_sessions,
           COUNT(DISTINCT s.x_table) AS n_tables, COUNT(DISTINCT s.x_dealer) AS n_dealers,
           COUNT(DISTINCT s.x_ip) AS n_ips, COUNT(DISTINCT s.x_product) AS n_products,
           MIN(s.x_date) AS first_seen_d, MAX(s.x_date) AS last_seen_d,
           SUM(s.x_stake) AS stake, SUM(s.x_valid) AS valid, SUM(s.x_rebate) AS rebate,
           SUM(s.x_net) AS net, SUM(-s.x_net *(100.0-s.x_agpct)/100.0) AS agent_cost,
           AVG(100.0-s.x_agpct)                   AS agent_pct,
           AVG(s.x_agpct)                         AS company_retain_pct,
           SUM(-s.x_net *s.x_agpct/100.0)         AS agent_cost_a_legacy,
           SUM(s.x_valid*s.x_agpct/100.0)         AS agent_cost_valid_base_legacy,
          AVG(COALESCE(s.x_rate1,100)) AS retain_pct_lv1, AVG(COALESCE(s.x_rate2,100)) AS retain_pct_lv2,
          AVG(COALESCE(s.x_rate3,100)) AS retain_pct_lv3, AVG(COALESCE(s.x_rate4,100)) AS retain_pct_lv4,
          AVG(COALESCE(s.x_rate5,100)) AS retain_pct_lv5, AVG(s.x_chain_depth) AS chain_depth_avg,
          AVG(COALESCE(100.0-s.x_rate1,0)) AS agent_pct_lv1, AVG(COALESCE(100.0-s.x_rate2,0)) AS agent_pct_lv2,
          AVG(COALESCE(100.0-s.x_rate3,0)) AS agent_pct_lv3, AVG(COALESCE(100.0-s.x_rate4,0)) AS agent_pct_lv4,
          AVG(COALESCE(100.0-s.x_rate5,0)) AS agent_pct_lv5,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate1,0)/100.0)                        AS agent_cost_lv1,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate2,0)/100.0)                        AS agent_cost_lv2,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate3,0)/100.0)                        AS agent_cost_lv3,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate4,0)/100.0)                        AS agent_cost_lv4,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate5,0)/100.0)                        AS agent_cost_lv5,
          SUM(-s.x_net*(COALESCE(100.0-s.x_rate1,0)+COALESCE(100.0-s.x_rate2,0)
                       +COALESCE(100.0-s.x_rate3,0)+COALESCE(100.0-s.x_rate4,0)
                       +COALESCE(100.0-s.x_rate5,0))/100.0)                   AS agent_cost_chain_additive,
          SUM(-s.x_net*(1.0 - CAST(COALESCE(s.x_rate1,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate2,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate3,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate4,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate5,100) AS DOUBLE)/100.0))
                                                                       AS agent_cost_chain_nested,
           AVG(s.x_rbpct) AS rbpct, AVG(s.x_freecomm*1.0) AS freecomm_rate,
           PERCENTILE_APPROX(s.x_stake,0.25) AS p25, PERCENTILE_APPROX(s.x_stake,0.50) AS p50,
           PERCENTILE_APPROX(s.x_stake,0.75) AS p75, PERCENTILE_APPROX(s.x_stake,0.90) AS p90,
           PERCENTILE_APPROX(s.x_stake,0.95) AS p95, PERCENTILE_APPROX(s.x_stake,0.99) AS p99,
           PERCENTILE_APPROX(s.x_valid,0.50) AS p50_valid,
           PERCENTILE_APPROX(s.x_net,0.50)   AS p50_profit,
           SUM(CASE WHEN s.x_freecomm = 1 THEN s.x_stake ELSE 0 END) AS st_in,
           SUM(CASE WHEN s.x_freecomm = 1 THEN 1 ELSE 0 END)         AS nb_in,
           SUM(CASE WHEN s.x_freecomm = 1 THEN s.x_net ELSE 0 END)   AS net_in,
           SUM(CASE WHEN NOT (s.x_freecomm = 1) THEN s.x_stake ELSE 0 END) AS st_out,
           SUM(CASE WHEN NOT (s.x_freecomm = 1) THEN 1 ELSE 0 END)         AS nb_out,
           SUM(CASE WHEN NOT (s.x_freecomm = 1) THEN s.x_net ELSE 0 END)   AS net_out,
           SUM(CASE WHEN s.x_rec=1 THEN s.x_stake ELSE 0 END) AS st_rec,
           SUM(CASE WHEN s.x_rec=1 THEN 1 ELSE 0 END)         AS nb_rec
    FROM x_mk s
    WHERE s.is_clean = 1
      AND s.x_member IS NOT NULL AND TRIM(CAST(s.x_member AS STRING)) <> ''
    GROUP BY s.x_member
  ),
  x_win AS (
    SELECT            COUNT(*) AS n_bets, COUNT(DISTINCT s.x_round) AS n_rounds,
           COUNT(DISTINCT s.x_date) AS active_days, COUNT(DISTINCT s.x_tblshoe) AS active_shoes,
           COUNT(DISTINCT CONCAT_WS('|', s.x_date, s.x_table)) AS active_sessions,
           COUNT(DISTINCT s.x_table) AS n_tables, COUNT(DISTINCT s.x_dealer) AS n_dealers,
           COUNT(DISTINCT s.x_ip) AS n_ips, COUNT(DISTINCT s.x_product) AS n_products,
           MIN(s.x_date) AS first_seen_d, MAX(s.x_date) AS last_seen_d,
           SUM(s.x_stake) AS stake, SUM(s.x_valid) AS valid, SUM(s.x_rebate) AS rebate,
           SUM(s.x_net) AS net, SUM(-s.x_net *(100.0-s.x_agpct)/100.0) AS agent_cost,
           AVG(100.0-s.x_agpct)                   AS agent_pct,
           AVG(s.x_agpct)                         AS company_retain_pct,
           SUM(-s.x_net *s.x_agpct/100.0)         AS agent_cost_a_legacy,
           SUM(s.x_valid*s.x_agpct/100.0)         AS agent_cost_valid_base_legacy,
          AVG(COALESCE(s.x_rate1,100)) AS retain_pct_lv1, AVG(COALESCE(s.x_rate2,100)) AS retain_pct_lv2,
          AVG(COALESCE(s.x_rate3,100)) AS retain_pct_lv3, AVG(COALESCE(s.x_rate4,100)) AS retain_pct_lv4,
          AVG(COALESCE(s.x_rate5,100)) AS retain_pct_lv5, AVG(s.x_chain_depth) AS chain_depth_avg,
          AVG(COALESCE(100.0-s.x_rate1,0)) AS agent_pct_lv1, AVG(COALESCE(100.0-s.x_rate2,0)) AS agent_pct_lv2,
          AVG(COALESCE(100.0-s.x_rate3,0)) AS agent_pct_lv3, AVG(COALESCE(100.0-s.x_rate4,0)) AS agent_pct_lv4,
          AVG(COALESCE(100.0-s.x_rate5,0)) AS agent_pct_lv5,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate1,0)/100.0)                        AS agent_cost_lv1,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate2,0)/100.0)                        AS agent_cost_lv2,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate3,0)/100.0)                        AS agent_cost_lv3,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate4,0)/100.0)                        AS agent_cost_lv4,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate5,0)/100.0)                        AS agent_cost_lv5,
          SUM(-s.x_net*(COALESCE(100.0-s.x_rate1,0)+COALESCE(100.0-s.x_rate2,0)
                       +COALESCE(100.0-s.x_rate3,0)+COALESCE(100.0-s.x_rate4,0)
                       +COALESCE(100.0-s.x_rate5,0))/100.0)                   AS agent_cost_chain_additive,
          SUM(-s.x_net*(1.0 - CAST(COALESCE(s.x_rate1,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate2,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate3,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate4,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate5,100) AS DOUBLE)/100.0))
                                                                       AS agent_cost_chain_nested,
           AVG(s.x_rbpct) AS rbpct, AVG(s.x_freecomm*1.0) AS freecomm_rate,
           PERCENTILE_APPROX(s.x_stake,0.25) AS p25, PERCENTILE_APPROX(s.x_stake,0.50) AS p50,
           PERCENTILE_APPROX(s.x_stake,0.75) AS p75, PERCENTILE_APPROX(s.x_stake,0.90) AS p90,
           PERCENTILE_APPROX(s.x_stake,0.95) AS p95, PERCENTILE_APPROX(s.x_stake,0.99) AS p99,
           PERCENTILE_APPROX(s.x_valid,0.50) AS p50_valid,
           PERCENTILE_APPROX(s.x_net,0.50)   AS p50_profit,
           SUM(CASE WHEN s.x_freecomm = 1 THEN s.x_stake ELSE 0 END) AS st_in,
           SUM(CASE WHEN s.x_freecomm = 1 THEN 1 ELSE 0 END)         AS nb_in,
           SUM(CASE WHEN s.x_freecomm = 1 THEN s.x_net ELSE 0 END)   AS net_in,
           SUM(CASE WHEN NOT (s.x_freecomm = 1) THEN s.x_stake ELSE 0 END) AS st_out,
           SUM(CASE WHEN NOT (s.x_freecomm = 1) THEN 1 ELSE 0 END)         AS nb_out,
           SUM(CASE WHEN NOT (s.x_freecomm = 1) THEN s.x_net ELSE 0 END)   AS net_out,
           SUM(CASE WHEN s.x_rec=1 THEN s.x_stake ELSE 0 END) AS st_rec,
           SUM(CASE WHEN s.x_rec=1 THEN 1 ELSE 0 END)         AS nb_rec
    FROM x_mk s
    WHERE s.is_clean = 1
      AND s.x_member IS NOT NULL AND TRIM(CAST(s.x_member AS STRING)) <> ''
  ),
      q AS (
        SELECT                                                                                              -- 取列：起始取列子句
          CASE                                                                                              -- 条件分支：起始分支——注型分族
            WHEN TRIM(bet09) IN ('Banker', 'Player')                        THEN 'F1_庄闲主注'               -- 分支判定：主注族
            WHEN TRIM(bet09) = 'Tie'                                        THEN 'F2_和局'                   -- 分支判定：和局
            WHEN TRIM(bet09) IN ('BPair', 'PPair', 'AnyPair', 'PerfectPair') THEN 'F3_对子族'                 -- 分支判定：对子族
            WHEN TRIM(bet09) IN ('BankerNatural', 'PlayerNatural')          THEN 'F4_例牌族'                  -- 分支判定：例牌族
            WHEN TRIM(bet09) IN ('BankerDragonBonus', 'PlayerDragonBonus')  THEN 'F5_龙宝族'                  -- 分支判定：龙宝族
            WHEN TRIM(bet09) IN ('Super6', 'Lucky7', 'SuperLucky7')         THEN 'F6_幸运族'                  -- 分支判定：幸运族
            WHEN TRIM(bet09) IN ('Big', 'Small')                            THEN 'F7_大小'                    -- 分支判定：大小
            ELSE 'F8_其他与新上线'                                                                            -- 分支判定：其余
          END                                                                    AS bet09_family,           -- 条件分支：收束上方分族，产出「bet09_family」
          COUNT(DISTINCT TRIM(bet09))                                            AS n_bet09_in_family,      -- 计数表达式：族内注型数
          COUNT(*)                                                               AS n_rows,                 -- 计数表达式：族内行数
          SUM(CASE WHEN CAST(NULLIF(TRIM(bet13), '') AS DECIMAL(20,8))
                       - CAST(NULLIF(TRIM(bet14), '') AS DECIMAL(20,8)) = 0 THEN 1 ELSE 0 END) AS n_pnl_zero, -- 条件计数：净输赢为零
          ROUND(SUM(CASE WHEN CAST(NULLIF(TRIM(bet13), '') AS DECIMAL(20,8))
                            - CAST(NULLIF(TRIM(bet14), '') AS DECIMAL(20,8)) = 0 THEN 1 ELSE 0 END) * 100.0
                / NULLIF(COUNT(*), 0), 6)                                        AS pct_pnl_zero,           -- 比率表达式：★ 该族之零输赢率
          SUM(CASE WHEN CAST(NULLIF(TRIM(bet13), '') AS DECIMAL(20,8))
                     = CAST(NULLIF(TRIM(bet14), '') AS DECIMAL(20,8))
                    AND CAST(NULLIF(TRIM(bet13), '') AS DECIMAL(20,8)) > 0 THEN 1 ELSE 0 END) AS n_exact_refund, -- 条件计数：★ 原额退还
          SUM(CASE WHEN CAST(NULLIF(TRIM(bet14), '') AS DECIMAL(20,8)) = 0
                    AND CAST(NULLIF(TRIM(bet13), '') AS DECIMAL(20,8)) > 0 THEN 1 ELSE 0 END) AS n_payout_zero_stake_pos, -- 条件计数：★ 派彩为零而本金为正——全输
          ROUND(SUM(CASE WHEN CAST(NULLIF(TRIM(bet13), '') AS DECIMAL(20,8))
                            - CAST(NULLIF(TRIM(bet14), '') AS DECIMAL(20,8)) < 0 THEN 1 ELSE 0 END) * 100.0
                / NULLIF(COUNT(*), 0), 6)                                        AS pct_player_win,         -- 比率表达式：会员赢之占比
          ROUND(-1 * SUM(CAST(NULLIF(TRIM(bet13), '') AS DECIMAL(20,8))
                        - CAST(NULLIF(TRIM(bet14), '') AS DECIMAL(20,8))) * 100.0
                / NULLIF(SUM(CAST(NULLIF(TRIM(bet13), '') AS DECIMAL(20,8))), 0), 6) AS mu0_pct,            -- 比率表达式：★ 该族之 μ0——与 push 率并读
          CASE                                                                                              -- 条件分支：起始分支——机制线索
            WHEN SUM(CASE WHEN CAST(NULLIF(TRIM(bet13), '') AS DECIMAL(20,8))
                            - CAST(NULLIF(TRIM(bet14), '') AS DECIMAL(20,8)) = 0 THEN 1 ELSE 0 END)
               = SUM(CASE WHEN CAST(NULLIF(TRIM(bet13), '') AS DECIMAL(20,8))
                            = CAST(NULLIF(TRIM(bet14), '') AS DECIMAL(20,8))
                           AND CAST(NULLIF(TRIM(bet13), '') AS DECIMAL(20,8)) > 0 THEN 1 ELSE 0 END)
              THEN '★ 零输赢者 100% 系原额退还 —— 形态一致（★ 惟机制仍须上游确认）'                              -- 分支判定：形态一致
            ELSE '❌ 零输赢者非全为原额退还 —— 该族另有他因，须逐笔查'                                            -- 分支判定：形态不一
          END                                                                    AS verdict_family          -- 条件分支：收束上方判词，产出「verdict_family」
        FROM ods_mariadb_2b.ods_a168_bet02                                                                  -- 取数来源：取自注单主表
        WHERE dt >= '2026-03-21' AND dt < '2026-08-07'                                                      -- 过滤条件：限定分析窗
          AND sync_time <= '2026-08-27 09:00:00'
          AND CAST(bet02 AS STRING) = '101'                                                                 -- 并列条件：限定百家乐
          AND TRIM(category) = '1'                                                                          -- 并列条件：只看 QSB 候选宇宙
        GROUP BY CASE                                                                                       -- 分组：按上方同一分族表达式汇总
            WHEN TRIM(bet09) IN ('Banker', 'Player')                        THEN 'F1_庄闲主注'
            WHEN TRIM(bet09) = 'Tie'                                        THEN 'F2_和局'
            WHEN TRIM(bet09) IN ('BPair', 'PPair', 'AnyPair', 'PerfectPair') THEN 'F3_对子族'
            WHEN TRIM(bet09) IN ('BankerNatural', 'PlayerNatural')          THEN 'F4_例牌族'
            WHEN TRIM(bet09) IN ('BankerDragonBonus', 'PlayerDragonBonus')  THEN 'F5_龙宝族'
            WHEN TRIM(bet09) IN ('Super6', 'Lucky7', 'SuperLucky7')         THEN 'F6_幸运族'
            WHEN TRIM(bet09) IN ('Big', 'Small')                            THEN 'F7_大小'
            ELSE 'F8_其他与新上线'
          END                                                                                               -- 续行：收束上方分组表达式
      )
    SELECT q.*,
           -- 一·经济层
           ROUND(e.stake,4) AS stake, ROUND(e.valid,4) AS valid_bet,
           ROUND(-e.net,4) AS profit, e.n_bets, e.n_rounds,
           ROUND(e.net/NULLIF(e.stake,0),8) AS roi,
           ROUND(e.net_in/NULLIF(e.st_in,0),8) AS roi_freecomm,
           ROUND(e.net_out/NULLIF(e.st_out,0),8) AS roi_non_freecomm,
           ROUND((e.net-e.rebate)/NULLIF(e.stake,0),8) AS roi_ex_rebate,
           ROUND(e.net,4) AS roi_numerator, ROUND(e.stake,4) AS roi_denominator,
           CASE WHEN e.stake IS NULL THEN 'NULL_DENOM' WHEN e.stake<=0 THEN 'ZERO_DENOM'
                WHEN e.n_bets<30 THEN 'THIN_EXPOSURE' ELSE 'OK' END AS roi_denominator_status,
           ROUND(e.rebate,4) AS rebate_cost, ROUND(e.agent_cost,4)                           AS cost_complement_b,
       ROUND(e.agent_pct,4)                            AS pct_complement,
       ROUND(e.company_retain_pct,4)                   AS pct_top_bet23,
       'AG03-UNRESOLVED'                                     AS agent_formula_version,
      'ALL5_LEVELS_bet23_to_bet27'                    AS agent_level_scope,
      ROUND(e.agent_cost_lv1,4) AS agent_cost_lv1, ROUND(e.agent_cost_lv2,4) AS agent_cost_lv2,
      ROUND(e.agent_cost_lv3,4) AS agent_cost_lv3, ROUND(e.agent_cost_lv4,4) AS agent_cost_lv4,
      ROUND(e.agent_cost_lv5,4) AS agent_cost_lv5,
      ROUND(e.agent_pct_lv1,6) AS agent_pct_lv1, ROUND(e.agent_pct_lv2,6) AS agent_pct_lv2,
      ROUND(e.agent_pct_lv3,6) AS agent_pct_lv3, ROUND(e.agent_pct_lv4,6) AS agent_pct_lv4,
      ROUND(e.agent_pct_lv5,6) AS agent_pct_lv5,
      ROUND(e.retain_pct_lv1,6) AS retain_pct_lv1, ROUND(e.retain_pct_lv2,6) AS retain_pct_lv2,
      ROUND(e.retain_pct_lv3,6) AS retain_pct_lv3, ROUND(e.retain_pct_lv4,6) AS retain_pct_lv4,
      ROUND(e.retain_pct_lv5,6) AS retain_pct_lv5, ROUND(e.chain_depth_avg,4) AS chain_depth_avg,
      ROUND(e.agent_cost_chain_additive,4)            AS agent_cost_chain_additive,
      ROUND(e.agent_cost_chain_nested,4)              AS agent_cost_chain_nested,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_additive,4) AS residual_chain_additive,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_nested,4)   AS residual_chain_nested,
      'PENDING_AG03'                                  AS decision_status,
      'FALSE'                                         AS admit_to_risk_decision,
      'NOT_FOR_ENFORCEMENT'                           AS deliverable_class,
       ROUND(e.agent_cost_a_legacy,4)                  AS agent_cost_a_legacy,
       ROUND(e.agent_cost_valid_base_legacy,4)         AS agent_cost_valid_base_legacy,
           ROUND(-e.net-e.rebate,4)                        AS ngr,
       ROUND(-e.net-e.rebate-e.agent_cost,4)           AS residual_b,
       ROUND(-e.net-e.rebate-e.agent_cost_a_legacy,4)  AS residual_a,
           ROUND((-e.net-e.rebate)/NULLIF(e.stake,0),8)    AS ngr_rate,
       ROUND((-e.net-e.rebate-e.agent_cost)/NULLIF(e.stake,0),8)   AS residual_b_rate,
      -- 【HF9c · canonical accounting contract】
      --   以下 canonical 字段只增加明确 scope；不删除、不覆盖既有字段。
      --   formal_bet23_* 保持 HF9b 当前生产公式及其 NULL/0 语义；
      --   lv1~lv5 / additive / nested 则分别采用各自原始 e.* 成本字段，
      --   rate 一律从未舍入的 e.* 分子 / e.stake 计算，禁止由展示值反算。
      ROUND(e.agent_cost,4) AS agent_cost_bet23_formal_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost,4) AS net_margin_bet23_formal_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost)/NULLIF(e.stake,0),8) AS net_margin_bet23_formal_rate_canonical,
      ROUND(e.agent_cost_lv1,4) AS agent_cost_lv1_bet23_canonical,
      ROUND(e.agent_cost_lv2,4) AS agent_cost_lv2_bet24_canonical,
      ROUND(e.agent_cost_lv3,4) AS agent_cost_lv3_bet25_canonical,
      ROUND(e.agent_cost_lv4,4) AS agent_cost_lv4_bet26_canonical,
      ROUND(e.agent_cost_lv5,4) AS agent_cost_lv5_bet27_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_lv1,4) AS net_margin_lv1_bet23_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_lv1)/NULLIF(e.stake,0),8) AS net_margin_lv1_bet23_rate_canonical,
      ROUND(e.agent_cost_chain_additive,4) AS agent_cost_chain_additive_canonical,
      ROUND(e.agent_cost_chain_nested,4) AS agent_cost_chain_nested_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_additive,4) AS net_margin_chain_additive_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_nested,4) AS net_margin_chain_nested_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_chain_additive)/NULLIF(e.stake,0),8) AS net_margin_chain_additive_rate_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_chain_nested)/NULLIF(e.stake,0),8) AS net_margin_chain_nested_rate_canonical,
       ROUND((-e.net-e.rebate-e.agent_cost_a_legacy)/NULLIF(e.stake,0),8) AS residual_a_rate,
           -- 二·分布层
           ROUND(e.stake/NULLIF(e.n_bets,0),4) AS avg_stake_per_bet,
           ROUND(e.valid/NULLIF(e.n_rounds,0),4) AS avg_valid_bet_per_round,
           ROUND(-e.net/NULLIF(e.n_rounds,0),4) AS avg_profit_per_round,
           ROUND(-e.net/NULLIF(e.active_days,0),4) AS avg_profit_per_day,
           ROUND(-e.net/NULLIF(e.active_shoes,0),4) AS avg_profit_per_shoe,
           ROUND(e.stake/NULLIF(e.active_days,0),4) AS avg_stake_per_active_day,
           ROUND(e.n_rounds*1.0/NULLIF(e.active_days,0),4) AS avg_rounds_per_active_day,
           ROUND(e.st_in/NULLIF(e.nb_in,0),4) AS avg_stake_freecomm,
           ROUND(e.st_out/NULLIF(e.nb_out,0),4) AS avg_stake_non_freecomm,
           ROUND(e.p25,4) AS p25_stake, ROUND(e.p50,4) AS p50_stake, ROUND(e.p75,4) AS p75_stake,
           ROUND(e.p90,4) AS p90_stake, ROUND(e.p95,4) AS p95_stake, ROUND(e.p99,4) AS p99_stake,
           ROUND(e.p50_valid,4) AS p50_valid_bet, ROUND(e.p50_profit,4) AS p50_profit,
           ROUND(e.p95/NULLIF(e.p50,0),6) AS p95_over_p50,
           ROUND(e.p99/NULLIF(e.p50,0),6) AS p99_over_p50,
           ROUND((e.stake/NULLIF(e.n_bets,0))/NULLIF(e.p50,0),6) AS avg_over_p50,
           -- 三·关系层
           e.n_tables AS common_table_count, e.n_dealers AS common_dealer_count,
           e.n_ips AS common_ip_count, e.n_products AS common_product_count,
           ROUND(e.st_in/NULLIF(e.stake,0),8) AS share_freecomm,
           -- 四·rate 层
           ROUND(-e.net/NULLIF(e.stake,0),8) AS hold_rate,
           ROUND(-e.net_in/NULLIF(e.st_in,0),8) AS hold_rate_freecomm,
           ROUND(e.rebate/NULLIF(e.valid,0),8) AS rebate_rate_actual,
           ROUND(e.rbpct,6) AS rebate_pct_config,
           ROUND(e.valid/NULLIF(e.stake,0),6) AS turnover_multiple,
           ROUND(e.freecomm_rate,6) AS free_comm_rate,
           ROUND(e.net_in/NULLIF(e.st_in,0)-e.net_out/NULLIF(e.st_out,0),8) AS roi_delta_freecomm,
           -- 五·动态层
           e.first_seen_d AS first_seen, e.last_seen_d AS last_seen,
           e.active_days, e.active_shoes, e.active_sessions,
           DATEDIFF(e.last_seen_d, e.first_seen_d)+1 AS span_days,
           ROUND(e.active_days*1.0/NULLIF(DATEDIFF(e.last_seen_d,e.first_seen_d)+1,0),6) AS persistence,
           ROUND((e.st_in/NULLIF(e.nb_in,0))/NULLIF(e.st_out/NULLIF(e.nb_out,0),0),6) AS ramp_freecomm,
           ROUND((e.st_rec/NULLIF(e.nb_rec,0))/NULLIF(e.stake/NULLIF(e.n_bets,0),0),6) AS ramp_recent,
           ROUND((e.st_rec/NULLIF(e.stake,0))/0.30,6) AS stake_ramp,
           -- 六·决策层（HF9g-P5 · D-14 斧正 —— 本件属【全窗基线族】，相对刻度与决策标签一律 NULL）
           --   病灶：x_win 系全窗单行聚合（无 GROUP BY，恒 1 行，此为设计使然，非缺陷），
           --         经 CROSS JOIN 接入后 e.* 全行同值；六层之 NTILE / PERCENT_RANK 施于常数即退化，
           --         PERCENT_RANK 恒 0 ⇒ action_priority 恒判 A，全件 100% 误标。
           --   ★ 斧正原则：不给 x_win 补 GROUP BY —— 那会改变其「全窗基线」语义，属退化。
           --     正解与 #018 之 G-05／G-06 同治：范围外之行不得接受任何下游评分与决策标签。
           --   ★ 本件之 e.* 仍照常供其它列作全窗基线使用，仅六层相对刻度与决策标签置 NULL。
           CAST(NULL AS INT)                                              AS vip_tier,                        -- 空值取值：全窗基线族无实体可分档，置 NULL（NULL＝不适用，非 0）
           CAST(NULL AS DOUBLE)                                           AS economic_value,                  -- 空值取值：同上，禁以常数百分位冒充经济价值
           CAST(NULL AS DOUBLE)                                           AS roi_pr_global,                   -- 空值取值：同上
           CAST(NULL AS DOUBLE)                                           AS risk_value,                      -- 空值取值：兼容列，同上
           CAST(NULL AS DOUBLE)                                           AS pr_stake,                        -- 空值取值：兼容列，同上
           CAST(NULL AS DOUBLE)                                           AS pr_global,                       -- 空值取值：同上
           CAST(NULL AS DOUBLE)                                           AS pr_qualified,                    -- 空值取值：同上
           'GLOBAL_BASELINE_NO_ENTITY_RANKING'                            AS pr_qualified_population,         -- 字面取值：血统 —— 明示本件为全窗基线族，无实体排序总体
           CAST(NULL AS BIGINT)                                           AS pr_global_population_n,          -- 空值取值：血统 —— 不适用
           CAST(NULL AS BIGINT)                                           AS pr_qualified_population_n,       -- 空值取值：血统 —— 不适用
           'NOT_APPLICABLE_GLOBAL_BASELINE'                               AS pr_calculation_method,           -- 字面取值：血统 —— 算法不适用
           'HF9g-P5'                                                      AS pr_calculation_version,          -- 字面取值：血统 —— 算法版本
           CAST(NULL AS STRING)                                           AS evidence_flag,                   -- 空值取值：证据旗标不适用于全窗基线
           CAST(NULL AS STRING)                                           AS evidence_rate,                   -- 空值取值：同上
           CAST(NULL AS DOUBLE)                                           AS hold_ci_halfwidth_approx,        -- 空值取值：同上
           'X 全窗基线 · 不参与实体赏罚'                                    AS action_priority                  -- 字面取值：★ D-14 斧正 —— 本族恒不入赏罚，取代原 100% 误标之「A」
    FROM q
    CROSS JOIN x_win e
  ) y
) z
-- ── 逐批 WHERE 阶梯（★ 口诀：上界 ＝ 下界 ＋ 100000，两数同进）──
--    本件 T_true 未测，无需先跑 T_true；以 0 / 100000 控制本批返回区间，末批由实际行数 < 100000 判定
--    WHERE z.audit_rn >        0 AND z.audit_rn <=   100000   -- 第 1 批
--    WHERE z.audit_rn >   100000 AND z.audit_rn <=   200000   -- 第 2 批
--    WHERE z.audit_rn >   200000 AND z.audit_rn <=   300000   -- 第 3 批
--    WHERE z.audit_rn >   300000 AND z.audit_rn <=   400000   -- 第 4 批
--    WHERE z.audit_rn >   400000 AND z.audit_rn <=   500000   -- 第 5 批
--    WHERE z.audit_rn >   500000 AND z.audit_rn <=   600000   -- 第 6 批
--    WHERE z.audit_rn >   600000 AND z.audit_rn <=   700000   -- 第 7 批
--    …余批类推。第 k 批：WHERE z.audit_rn > (k-1)*100000 AND z.audit_rn <= k*100000
--    某批返回 < 100000 行即为末批，其后不再取。
--
--    ⚠ 常见误写（务必避开）：只推下界而上界不动 ——
--        WHERE z.audit_rn > 100000 AND z.audit_rn <= 100000   ← 自相矛盾，恒为假，返回空集
--        WHERE z.audit_rn > 200000 AND z.audit_rn <= 100000   ← 同上，空集
--      两个数必须**同时**前进，且始终相差 100000。
--      下界 ＝ 上一批之上界；上界 ＝ 本批之上界。
WHERE z.audit_rn > 0 AND z.audit_rn <= 100000 -- ★ HF9c 本批区间
ORDER BY z.audit_rn;


-- ══════════════════════════════════════════════════════════════════════════════════════════════
--  64. R01_late_shoe.csv   [总包行 3463~3539 · 原 15 列 ＋六层约 60 列]
--     典型学：M03 尾段投注　派生旗标：late（s.x_rno*1.0/NULLIF(p.max_rno,0) >= 0.80 · 仅供 CASE 条件聚合，全包无任何 WHERE/AND/HAVING 以此过滤）　连接：q.`uid`
-- ══════════════════════════════════════════════════════════════════════════════════════════════
-- ── ① 先跑 T_true 留档（不足 100000 者一次导全，不必分批）──
-- ── ① T_true：HF9c 不再强制预跑完整 COUNT。
--    本批实际返回行数 < 100000 即判定为末批；全批完成后以各批 n_rows / audit_rn 范围核对总量。

-- ── ② 分批取数：第 1 批。第 k 批只改末行两数为 (k-1)*100000 与 k*100000 ──
--    审计字段二（REDTEAM 2026-08-24 裁定 · 四锁）：
--      audit_rn  全局观测坐标 —— 由**与原版审计版逐字同一**之排序键所生，两版可逐行对账
--      batch_id  物理分批信息 —— 该行所属批次，由 audit_rn 算得，非引擎所赋
--    ★ 锁三：二者皆为审计字段，**不得进入任何业务指标计算**。
--    ★ 锁四：两版经 audit_rn 逐行字段核验后，方可宣布输出完全一致。

-- ── ③ 每批取回后自证四数（任一不符即停手回报，禁止放行）──
--    n_rows        = COUNT(*)      须等于 COUNT(DISTINCT audit_rn)   （批内无重复）
--    audit_rn_min  = MIN(audit_rn) 须等于 (k-1)*100000 + 1           （与上批严丝合缝）
--    audit_rn_max  = MAX(audit_rn) 须等于 min + n_rows - 1           （批内无缺口）
--    全批取毕再验：各批 audit_rn 之并集 = 1 .. T_true，无缺号、无重号。
--     ★ 首行＝平台真净亏最多者（已扣退水与代理占成）。
--
SELECT z.*,
       CAST(FLOOR((z.audit_rn - 1) / 100000) + 1 AS INT)          AS batch_id,
       'A168_HF9F_20260827_0900' AS run_id,
       '2026-08-27 09:00:00' AS snapshot_sync_time
FROM (
  SELECT y.*,
         ROW_NUMBER() OVER (ORDER BY y.`residual_b` ASC, y.`roi` DESC, y.`uid`, y.`n_orders_all`, y.`n_orders_late`, y.`late_def`, y.`late_share`, y.`shoe_pos_p50`, y.`stake_late_avg`, y.`stake_early_avg`, y.`stake_ramp`, y.`roi_late`, y.`roi_early`, y.`stake_late`, y.`game_pnl_late`, y.`stake_all`, y.`game_pnl_all`) AS audit_rn
  FROM (
    WITH
      x_ranked AS (
    SELECT b.bet01, b.bet03, b.bet04, b.bet05, b.bet09, b.bet11, b.bet13,
           b.bet15, b.bet16, b.bet17, b.bet18, b.bet19, b.bet20, b.bet21,
           b.bet22, b.bet23, b.bet24, b.bet25, b.bet26, b.bet27, b.bet38, b.bet39, b.category, b.commission,
           b.dt, b.eid, b.ip, b.validbet, b.updatetime, b.sync_time,
           ROW_NUMBER() OVER (
             PARTITION BY b.bet01
             ORDER BY b.updatetime DESC, b.sync_time DESC, b.dt DESC)      AS x_rn
    FROM ods_mariadb_2b.ods_a168_bet02 b
    WHERE b.dt >= '2026-03-21' AND b.dt < '2026-08-07'
      AND b.bet02 = '101'
      AND b.sync_time <= '2026-08-27 09:00:00'
  ),
    x_testagent AS (
    SELECT age001 AS agent_id FROM ods_mariadb_2b.ods_a168_agent WHERE age022 = '1'
  ),
    x_bs0 AS (
    SELECT b.bet05 AS x_member, b.eid AS x_dealer, b.bet39 AS x_table,
           b.bet03 AS x_shoe, b.ip AS x_ip, b.bet09 AS x_product, b.dt AS x_date,
           CONCAT_WS('|', b.bet03, b.bet04, b.bet39)                      AS x_round,
           CONCAT_WS('|', b.bet39, b.bet03)                               AS x_tblshoe,
           CAST(NULLIF(TRIM(b.bet04),'') AS INT)                          AS x_rno,
           CASE WHEN b.dt >= '2026-07-08' THEN 1 ELSE 0 END               AS x_rec,
           CASE WHEN TRIM(b.commission)='1' THEN 1 ELSE 0 END             AS x_freecomm,
           CAST(NULLIF(TRIM(b.bet13),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_stake,
           CAST(NULLIF(TRIM(b.validbet),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_valid,
           CAST(NULLIF(TRIM(b.bet16),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_rebate,
           CAST(NULLIF(TRIM(b.bet17),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_net,
           CAST(NULLIF(TRIM(b.bet15),'') AS DECIMAL(20,6))                AS x_rbpct,
           COALESCE(CAST(NULLIF(TRIM(b.bet23),'') AS DECIMAL(20,6)),0)   AS x_agpct,
          NULLIF(CAST(NULLIF(TRIM(b.bet23),'') AS DECIMAL(20,6)),0)     AS x_rate1,
          NULLIF(CAST(NULLIF(TRIM(b.bet24),'') AS DECIMAL(20,6)),0)     AS x_rate2,
          NULLIF(CAST(NULLIF(TRIM(b.bet25),'') AS DECIMAL(20,6)),0)     AS x_rate3,
          NULLIF(CAST(NULLIF(TRIM(b.bet26),'') AS DECIMAL(20,6)),0)     AS x_rate4,
          NULLIF(CAST(NULLIF(TRIM(b.bet27),'') AS DECIMAL(20,6)),0)     AS x_rate5,
          (CASE WHEN NULLIF(CAST(NULLIF(TRIM(b.bet22),'') AS BIGINT),0) IS NOT NULL THEN 5
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet21),'') AS BIGINT),0) IS NOT NULL THEN 4
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet20),'') AS BIGINT),0) IS NOT NULL THEN 3
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet19),'') AS BIGINT),0) IS NOT NULL THEN 2
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet18),'') AS BIGINT),0) IS NOT NULL THEN 1
                ELSE 0 END)                                             AS x_chain_depth,
           CASE WHEN COALESCE(t1.agent_id,t2.agent_id,t3.agent_id,
                              t4.agent_id,t5.agent_id) IS NOT NULL
                THEN 1 ELSE 0 END                                        AS f_testline
    FROM x_ranked b
    LEFT JOIN x_testagent t1 ON t1.agent_id = b.bet18
    LEFT JOIN x_testagent t2 ON t2.agent_id = b.bet19
    LEFT JOIN x_testagent t3 ON t3.agent_id = b.bet20
    LEFT JOIN x_testagent t4 ON t4.agent_id = b.bet21
    LEFT JOIN x_testagent t5 ON t5.agent_id = b.bet22
    WHERE b.x_rn = 1
      AND b.category='1' AND UPPER(TRIM(b.bet38))='N'
      AND CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8)) > 0
  ),
  x_mk AS (
    SELECT s.*,
           CASE WHEN s.f_testline = 0 THEN 1 ELSE 0 END                 AS is_clean
    FROM x_bs0 s
  ),
  x_sp AS (SELECT x_table, x_shoe, MAX(x_rno) AS max_rno FROM x_mk GROUP BY x_table, x_shoe),
  x_agg AS (
    SELECT s.x_member                                                        AS x_key,
           COUNT(*) AS n_bets, COUNT(DISTINCT s.x_round) AS n_rounds,
           COUNT(DISTINCT s.x_date) AS active_days, COUNT(DISTINCT s.x_tblshoe) AS active_shoes,
           COUNT(DISTINCT CONCAT_WS('|', s.x_date, s.x_table)) AS active_sessions,
           COUNT(DISTINCT s.x_table) AS n_tables, COUNT(DISTINCT s.x_dealer) AS n_dealers,
           COUNT(DISTINCT s.x_ip) AS n_ips, COUNT(DISTINCT s.x_product) AS n_products,
           MIN(s.x_date) AS first_seen_d, MAX(s.x_date) AS last_seen_d,
           SUM(s.x_stake) AS stake, SUM(s.x_valid) AS valid, SUM(s.x_rebate) AS rebate,
           SUM(s.x_net) AS net, SUM(-s.x_net *(100.0-s.x_agpct)/100.0) AS agent_cost,
           AVG(100.0-s.x_agpct)                   AS agent_pct,
           AVG(s.x_agpct)                         AS company_retain_pct,
           SUM(-s.x_net *s.x_agpct/100.0)         AS agent_cost_a_legacy,
           SUM(s.x_valid*s.x_agpct/100.0)         AS agent_cost_valid_base_legacy,
          AVG(COALESCE(s.x_rate1,100)) AS retain_pct_lv1, AVG(COALESCE(s.x_rate2,100)) AS retain_pct_lv2,
          AVG(COALESCE(s.x_rate3,100)) AS retain_pct_lv3, AVG(COALESCE(s.x_rate4,100)) AS retain_pct_lv4,
          AVG(COALESCE(s.x_rate5,100)) AS retain_pct_lv5, AVG(s.x_chain_depth) AS chain_depth_avg,
          AVG(COALESCE(100.0-s.x_rate1,0)) AS agent_pct_lv1, AVG(COALESCE(100.0-s.x_rate2,0)) AS agent_pct_lv2,
          AVG(COALESCE(100.0-s.x_rate3,0)) AS agent_pct_lv3, AVG(COALESCE(100.0-s.x_rate4,0)) AS agent_pct_lv4,
          AVG(COALESCE(100.0-s.x_rate5,0)) AS agent_pct_lv5,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate1,0)/100.0)                        AS agent_cost_lv1,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate2,0)/100.0)                        AS agent_cost_lv2,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate3,0)/100.0)                        AS agent_cost_lv3,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate4,0)/100.0)                        AS agent_cost_lv4,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate5,0)/100.0)                        AS agent_cost_lv5,
          SUM(-s.x_net*(COALESCE(100.0-s.x_rate1,0)+COALESCE(100.0-s.x_rate2,0)
                       +COALESCE(100.0-s.x_rate3,0)+COALESCE(100.0-s.x_rate4,0)
                       +COALESCE(100.0-s.x_rate5,0))/100.0)                   AS agent_cost_chain_additive,
          SUM(-s.x_net*(1.0 - CAST(COALESCE(s.x_rate1,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate2,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate3,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate4,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate5,100) AS DOUBLE)/100.0))
                                                                       AS agent_cost_chain_nested,
           AVG(s.x_rbpct) AS rbpct, AVG(s.x_freecomm*1.0) AS freecomm_rate,
           PERCENTILE_APPROX(s.x_stake,0.25) AS p25, PERCENTILE_APPROX(s.x_stake,0.50) AS p50,
           PERCENTILE_APPROX(s.x_stake,0.75) AS p75, PERCENTILE_APPROX(s.x_stake,0.90) AS p90,
           PERCENTILE_APPROX(s.x_stake,0.95) AS p95, PERCENTILE_APPROX(s.x_stake,0.99) AS p99,
           PERCENTILE_APPROX(s.x_valid,0.50) AS p50_valid,
           PERCENTILE_APPROX(s.x_net,0.50)   AS p50_profit,
           SUM(CASE WHEN s.x_rno*1.0/NULLIF(p.max_rno,0) >= 0.80 THEN s.x_stake ELSE 0 END) AS st_in,
           SUM(CASE WHEN s.x_rno*1.0/NULLIF(p.max_rno,0) >= 0.80 THEN 1 ELSE 0 END)         AS nb_in,
           SUM(CASE WHEN s.x_rno*1.0/NULLIF(p.max_rno,0) >= 0.80 THEN s.x_net ELSE 0 END)   AS net_in,
           SUM(CASE WHEN NOT (s.x_rno*1.0/NULLIF(p.max_rno,0) >= 0.80) THEN s.x_stake ELSE 0 END) AS st_out,
           SUM(CASE WHEN NOT (s.x_rno*1.0/NULLIF(p.max_rno,0) >= 0.80) THEN 1 ELSE 0 END)         AS nb_out,
           SUM(CASE WHEN NOT (s.x_rno*1.0/NULLIF(p.max_rno,0) >= 0.80) THEN s.x_net ELSE 0 END)   AS net_out,
           SUM(CASE WHEN s.x_rec=1 THEN s.x_stake ELSE 0 END) AS st_rec,
           SUM(CASE WHEN s.x_rec=1 THEN 1 ELSE 0 END)         AS nb_rec
    FROM x_mk s
    JOIN x_sp p ON p.x_table = s.x_table AND p.x_shoe = s.x_shoe
    WHERE s.is_clean = 1
      AND s.x_member IS NOT NULL AND TRIM(CAST(s.x_member AS STRING)) <> ''
    GROUP BY s.x_member
  ),
      q AS (
        WITH test_agents AS (                                                                               -- 公共表表达式：开启中间结果集 test_agents，其后各行为其定义体（§R01）
          SELECT age001 AS agent_id                                                                         -- 取列：产出「agent_id」
          FROM ods_mariadb_2b.ods_a168_agent                                                                -- 取数来源：取自代理主档（五级代理线归属来源）
          WHERE age022 = '1'                                  -- 铁律④b：公司测试线
        ),                                                                                                  -- 续行：收束上方的子查询或函数括号（§R01）
        ranked AS (                                            -- 需求 §3.2：同单号保留最新版本
          SELECT b.bet01, b.updatetime, b.sync_time, b.dt, b.bet02,                                         -- 取列：起始取列子句，本行先列 b.bet01, b.updatetime, b.sync_time, b.dt, b.bet02，涉 bet02（游戏类别）、dt（营业日）
                 b.bet03, b.bet04, b.bet05, b.bet11, b.bet13,                                               -- 续行：接续上一取列子句，续列 b.bet03, b.bet04, b.bet05, b.bet11, b.bet13，涉 bet03（靴号）、bet04（局内序号）、bet05（会员号）
                 b.bet14, b.bet18, b.bet19, b.bet20, b.bet21,                                               -- 续行：接续上一取列子句，续列 b.bet14, b.bet18, b.bet19, b.bet20, b.bet21，涉 bet14（派彩金额）、bet18（一级代理线）、bet19（二级代理线）
                 b.bet22, b.bet38, b.bet39, b.category,                                                     -- 续行：接续上一取列子句，续列 b.bet22, b.bet38, b.bet39, b.category，涉 bet22（五级代理线）、bet38（重對）、bet39（桌号）
                 ROW_NUMBER() OVER (                                                                        -- 行号窗口表达式：以行号窗口取每组头部或去重，免出重复行
                   PARTITION BY b.bet01                                                                     -- 窗口分区：按 b.bet01 分组开窗，组内各自编号或排名
                   ORDER BY b.updatetime DESC, b.sync_time DESC, b.dt DESC) AS rn                           -- 排序：按 b.updatetime（降序）, b.sync_time（降序）, b.dt（降序）) AS rn 排列；导出必带排序，否则分页无稳定序（曾致 36.49% 重复行）
          FROM ods_mariadb_2b.ods_a168_bet02 b                 -- ★ 表名开关
          WHERE b.dt >= '2026-03-21' AND b.dt < '2026-08-07'                                                -- 过滤条件：限定 b.dt不少于 '2026-03-21'、b.dt小于 '2026-08-07'，涉 dt（营业日）
            AND b.bet02 = '101'
      AND b.sync_time <= '2026-08-27 09:00:00'                                                                             -- 并列条件：限定 b.bet02等于 '101'，涉 bet02（游戏类别）
        ),                                                                                                  -- 续行：收束上方的子查询或函数括号（§R01）
        base AS (                                                                                           -- 公共表表达式：开启中间结果集 base，其后各行为其定义体（§R01）
          SELECT r.bet01 AS bet_id, r.bet05 AS member_id,                                                   -- 取列：起始取列子句，本行先取「member_id」，涉 bet05（会员号）、member_id（会员号）
                 r.bet03 AS shoe_id, r.bet39 AS table_id,                                                   -- 取值表达式：取用 bet03（靴号）、bet39（桌号），产出「table_id」
                 CAST(NULLIF(TRIM(r.bet04),'') AS INT)           AS round_no,                               -- 取值表达式：先去空白、空串归 NULL，再显式转型——本库字段多为 varchar，不转型即比较失真，产出「round_no」
                 CAST(NULLIF(TRIM(r.bet11),'') AS DECIMAL(20,8)) AS fx,                                     -- 取值表达式：先去空白、空串归 NULL，再显式转型——本库字段多为 varchar，不转型即比较失真，产出「fx」
                 CAST(NULLIF(TRIM(r.bet13),'') AS DECIMAL(20,4)) AS stake_raw,                              -- 取值表达式：先去空白、空串归 NULL，再显式转型——本库字段多为 varchar，不转型即比较失真，产出「stake_raw」
                 CAST(NULLIF(TRIM(r.bet14),'') AS DECIMAL(20,4)) AS payout_raw                              -- 取值表达式：先去空白、空串归 NULL，再显式转型——本库字段多为 varchar，不转型即比较失真，产出「payout_raw」
          FROM ranked r                                                                                     -- 取数来源：取自本条自建的中间结果集 ranked
          /* StarRocks 不支持 EXISTS + 多列 IN，测试线剔除改五路 LEFT JOIN */
          LEFT JOIN test_agents t1 ON t1.agent_id = r.bet18                                                 -- 左连接：取自本条自建的中间结果集 test_agents，连接键为 bet18（一级代理线）
          LEFT JOIN test_agents t2 ON t2.agent_id = r.bet19                                                 -- 左连接：取自本条自建的中间结果集 test_agents，连接键为 bet19（二级代理线）
          LEFT JOIN test_agents t3 ON t3.agent_id = r.bet20                                                 -- 左连接：取自本条自建的中间结果集 test_agents，连接键为 bet20（三级代理线）
          LEFT JOIN test_agents t4 ON t4.agent_id = r.bet21                                                 -- 左连接：取自本条自建的中间结果集 test_agents，连接键为 bet21（四级代理线）
          LEFT JOIN test_agents t5 ON t5.agent_id = r.bet22                                                 -- 左连接：取自本条自建的中间结果集 test_agents，连接键为 bet22（五级代理线）
          WHERE r.rn = 1                                                                                    -- 过滤条件：限定 r.rn等于 1
            AND r.category = '1'                                                                            -- 并列条件：限定 r.category等于 '1'
            AND UPPER(TRIM(r.bet38)) = 'N'                                                                  -- 并列条件：限定 UPPER(TRIM(r.bet38))等于 'N'，涉 bet38（重對）
            AND CAST(NULLIF(TRIM(r.bet05),'') AS BIGINT) > 0                                                -- 并列条件：限定 CAST(NULLIF(TRIM(r.bet05),'') AS BIGINT)大于 0，涉 bet05（会员号）
            AND CAST(NULLIF(TRIM(r.bet11),'') AS DECIMAL(20,8)) > 0                                         -- 并列条件：限定 CAST(NULLIF(TRIM(r.bet11),'') AS DECIMAL(20,8))大于 0，涉 bet11（汇率）
            AND CAST(NULLIF(TRIM(r.bet04),'') AS INT) > 0                                                   -- 并列条件：限定 CAST(NULLIF(TRIM(r.bet04),'') AS INT)大于 0，涉 bet04（局内序号）
            AND COALESCE(t1.agent_id,t2.agent_id,t3.agent_id,t4.agent_id,t5.agent_id) IS NULL               -- 并列条件：限定该值为空——本包以左连接加空值判定替代 EXISTS，因 StarRocks 不支持 EXISTS 配多列 IN
        ),                                                                                                  -- 续行：收束上方的子查询或函数括号（§R01）
        shoe_len AS (          /* ★ 命名警示：本 CTE 名为 shoe_len（靴长）系历史沿用，其所算 max_round = MAX(round_no) 为『该靴该桌观测到的最大局号』，非 COUNT(round_no) 之局数；二者仅在局号自1起连续无缺口时相等。选 MAX 为刻意设计：对中间缺口免疫，COUNT 会因清洗剔单而使分母缩水。★ B-01 斧正（2026-08-12）：定标基准逐靴现算，绝对局号不是固定靴位 */   -- 缺陷一修正：定标基准不定，固定 50 不是固定位置
          SELECT shoe_id, table_id, MAX(round_no) AS max_round                                              -- 取列：取最大局号（≠COUNT 局数），产出「max_round」
          FROM base GROUP BY shoe_id, table_id                                                              -- 取数来源：取自本条自建的中间结果集 base
        ),                                                                                                  -- 续行：收束上方的子查询或函数括号（§R01）
        enriched AS (                                                                                       -- 公共表表达式：开启中间结果集 enriched，其后各行为其定义体（§R01）
          SELECT b.member_id, b.shoe_id, b.table_id, b.round_no, s.max_round,                               -- 取列：起始取列子句，本行先列 b.member_id, b.shoe_id, b.table_id, b.round_no, s.max_round，涉 member_id（会员号）
                 b.round_no * 1.0 / NULLIF(s.max_round,0)     AS shoe_pos,                                  -- 取值表达式：产出「shoe_pos」
                 b.stake_raw / b.fx                           AS stake,                                     -- 取值表达式：取用 stake（下注额（经汇率归一化）），产出「stake」
                 (b.payout_raw - b.stake_raw) / b.fx          AS game_pnl,                                  -- 续行：取用 game_pnl（游戏净输赢），产出「game_pnl」
                 CASE WHEN b.round_no * 1.0 / NULLIF(s.max_round,0) >= 0.80
                      THEN 1 ELSE 0 END                        AS is_late   -- B-01 斧正：相对靴位                                    -- 条件分支：产出「is_late」
          FROM base b                                                                                       -- 取数来源：取自本条自建的中间结果集 base
          JOIN shoe_len s ON s.shoe_id = b.shoe_id AND s.table_id = b.table_id                              -- 连接：取自本条自建的中间结果集 shoe_len，连接键为 s.shoe_id = b.shoe_id AND s.table_id = b.table_id
        )                                                                                                   -- 续行：收束上方的子查询或函数括号（§R01）
        SELECT                                                                                              -- 续行：接续上一取列子句，续列 SELECT
          member_id                                                     AS uid,                             -- 取值表达式：取用 member_id（会员号）、uid（会员号），产出「uid」
          COUNT(*)                                                      AS n_orders_all,                    -- 计数表达式：产出「n_orders_all」
          SUM(is_late)                                                  AS n_orders_late,                   -- 汇总表达式：产出「n_orders_late」
          'shoe_pos>=0.80'                                              AS late_def,        -- 口径锁：definition_version = v2
          SUM(is_late) * 1.0 / COUNT(*)                                 AS late_share,                      -- 汇总表达式：计数，取用 late_share（晚注占比），产出「late_share」
          PERCENTILE_APPROX(CASE WHEN is_late=1 THEN shoe_pos END, 0.5) AS shoe_pos_p50,                    -- 取近似分位数表达式：产出「shoe_pos_p50」
          SUM(CASE WHEN is_late=1 THEN stake END) / NULLIF(SUM(is_late),0)              AS stake_late_avg,  -- 汇总表达式：取用 stake（下注额（经汇率归一化）），产出「stake_late_avg」
          SUM(CASE WHEN is_late=0 THEN stake END) / NULLIF(COUNT(*)-SUM(is_late),0)     AS stake_early_avg,  -- 汇总表达式：早段注额合计除以早段注单数 ＝ 早段均注，与 GGR 无涉，产出「stake_early_avg」
          (SUM(CASE WHEN is_late=1 THEN stake END) / NULLIF(SUM(is_late),0))                                -- 续行：汇总，取用 stake（下注额（经汇率归一化））
            / NULLIF(SUM(CASE WHEN is_late=0 THEN stake END)                                                -- 除法或乘法计算：汇总，取用 stake（下注额（经汇率归一化））
                     / NULLIF(COUNT(*)-SUM(is_late),0), 0)                              AS stake_ramp,      -- 除法计算：晚段均注除以早段均注 ＝ 注额斜率，与 GGR 无涉，产出「stake_ramp」
          SUM(CASE WHEN is_late=1 THEN game_pnl END)                                                        -- 汇总表达式：取用 game_pnl（游戏净输赢）
            / NULLIF(SUM(CASE WHEN is_late=1 THEN stake END),0)                         AS roi_late,        -- 除法或乘法计算：汇总，取用 stake（下注额（经汇率归一化）），产出「roi_late」
          SUM(CASE WHEN is_late=0 THEN game_pnl END)                                                        -- 汇总表达式：取用 game_pnl（游戏净输赢）
            / NULLIF(SUM(CASE WHEN is_late=0 THEN stake END),0)                         AS roi_early,       -- 除法或乘法计算：汇总，取用 stake（下注额（经汇率归一化）），产出「roi_early」
          SUM(CASE WHEN is_late=1 THEN stake END)                                       AS stake_late,      -- 汇总表达式：取用 stake（下注额（经汇率归一化）），产出「stake_late」
          SUM(CASE WHEN is_late=1 THEN game_pnl END)                                    AS game_pnl_late,   -- 汇总表达式：取用 game_pnl（游戏净输赢），产出「game_pnl_late」
          SUM(stake)                                                                    AS stake_all,       -- 汇总表达式：取用 stake（下注额（经汇率归一化）），产出「stake_all」
          SUM(game_pnl)                                                                 AS game_pnl_all     -- 汇总表达式：取用 game_pnl（游戏净输赢），产出「game_pnl_all」
        FROM enriched                                                                                       -- 取数来源：取自本条自建的中间结果集 enriched
        GROUP BY member_id                                                                                  -- 分组：按 member_id 汇总
        HAVING COUNT(*) >= 100                                    -- 需求：订单数据 > 100 笔
      )
    SELECT q.*,
           -- 一·经济层
           ROUND(e.stake,4) AS stake, ROUND(e.valid,4) AS valid_bet,
           ROUND(-e.net,4) AS profit, e.n_bets, e.n_rounds,
           ROUND(e.net/NULLIF(e.stake,0),8) AS roi,
           ROUND(e.net_in/NULLIF(e.st_in,0),8) AS roi_late_xagg,
           ROUND(e.net_out/NULLIF(e.st_out,0),8) AS roi_non_late,
           ROUND((e.net-e.rebate)/NULLIF(e.stake,0),8) AS roi_ex_rebate,
           ROUND(e.net,4) AS roi_numerator, ROUND(e.stake,4) AS roi_denominator,
           CASE WHEN e.stake IS NULL THEN 'NULL_DENOM' WHEN e.stake<=0 THEN 'ZERO_DENOM'
                WHEN e.n_bets<30 THEN 'THIN_EXPOSURE' ELSE 'OK' END AS roi_denominator_status,
           ROUND(e.rebate,4) AS rebate_cost, ROUND(e.agent_cost,4)                           AS cost_complement_b,
       ROUND(e.agent_pct,4)                            AS pct_complement,
       ROUND(e.company_retain_pct,4)                   AS pct_top_bet23,
       'AG03-UNRESOLVED'                                     AS agent_formula_version,
      'ALL5_LEVELS_bet23_to_bet27'                    AS agent_level_scope,
      ROUND(e.agent_cost_lv1,4) AS agent_cost_lv1, ROUND(e.agent_cost_lv2,4) AS agent_cost_lv2,
      ROUND(e.agent_cost_lv3,4) AS agent_cost_lv3, ROUND(e.agent_cost_lv4,4) AS agent_cost_lv4,
      ROUND(e.agent_cost_lv5,4) AS agent_cost_lv5,
      ROUND(e.agent_pct_lv1,6) AS agent_pct_lv1, ROUND(e.agent_pct_lv2,6) AS agent_pct_lv2,
      ROUND(e.agent_pct_lv3,6) AS agent_pct_lv3, ROUND(e.agent_pct_lv4,6) AS agent_pct_lv4,
      ROUND(e.agent_pct_lv5,6) AS agent_pct_lv5,
      ROUND(e.retain_pct_lv1,6) AS retain_pct_lv1, ROUND(e.retain_pct_lv2,6) AS retain_pct_lv2,
      ROUND(e.retain_pct_lv3,6) AS retain_pct_lv3, ROUND(e.retain_pct_lv4,6) AS retain_pct_lv4,
      ROUND(e.retain_pct_lv5,6) AS retain_pct_lv5, ROUND(e.chain_depth_avg,4) AS chain_depth_avg,
      ROUND(e.agent_cost_chain_additive,4)            AS agent_cost_chain_additive,
      ROUND(e.agent_cost_chain_nested,4)              AS agent_cost_chain_nested,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_additive,4) AS residual_chain_additive,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_nested,4)   AS residual_chain_nested,
      'PENDING_AG03'                                  AS decision_status,
      'FALSE'                                         AS admit_to_risk_decision,
      'NOT_FOR_ENFORCEMENT'                           AS deliverable_class,
       ROUND(e.agent_cost_a_legacy,4)                  AS agent_cost_a_legacy,
       ROUND(e.agent_cost_valid_base_legacy,4)         AS agent_cost_valid_base_legacy,
           ROUND(-e.net-e.rebate,4)                        AS ngr,
       ROUND(-e.net-e.rebate-e.agent_cost,4)           AS residual_b,
       ROUND(-e.net-e.rebate-e.agent_cost_a_legacy,4)  AS residual_a,
           ROUND((-e.net-e.rebate)/NULLIF(e.stake,0),8)    AS ngr_rate,
       ROUND((-e.net-e.rebate-e.agent_cost)/NULLIF(e.stake,0),8)   AS residual_b_rate,
      -- 【HF9c · canonical accounting contract】
      --   以下 canonical 字段只增加明确 scope；不删除、不覆盖既有字段。
      --   formal_bet23_* 保持 HF9b 当前生产公式及其 NULL/0 语义；
      --   lv1~lv5 / additive / nested 则分别采用各自原始 e.* 成本字段，
      --   rate 一律从未舍入的 e.* 分子 / e.stake 计算，禁止由展示值反算。
      ROUND(e.agent_cost,4) AS agent_cost_bet23_formal_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost,4) AS net_margin_bet23_formal_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost)/NULLIF(e.stake,0),8) AS net_margin_bet23_formal_rate_canonical,
      ROUND(e.agent_cost_lv1,4) AS agent_cost_lv1_bet23_canonical,
      ROUND(e.agent_cost_lv2,4) AS agent_cost_lv2_bet24_canonical,
      ROUND(e.agent_cost_lv3,4) AS agent_cost_lv3_bet25_canonical,
      ROUND(e.agent_cost_lv4,4) AS agent_cost_lv4_bet26_canonical,
      ROUND(e.agent_cost_lv5,4) AS agent_cost_lv5_bet27_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_lv1,4) AS net_margin_lv1_bet23_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_lv1)/NULLIF(e.stake,0),8) AS net_margin_lv1_bet23_rate_canonical,
      ROUND(e.agent_cost_chain_additive,4) AS agent_cost_chain_additive_canonical,
      ROUND(e.agent_cost_chain_nested,4) AS agent_cost_chain_nested_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_additive,4) AS net_margin_chain_additive_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_nested,4) AS net_margin_chain_nested_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_chain_additive)/NULLIF(e.stake,0),8) AS net_margin_chain_additive_rate_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_chain_nested)/NULLIF(e.stake,0),8) AS net_margin_chain_nested_rate_canonical,
       ROUND((-e.net-e.rebate-e.agent_cost_a_legacy)/NULLIF(e.stake,0),8) AS residual_a_rate,
           -- 二·分布层
           ROUND(e.stake/NULLIF(e.n_bets,0),4) AS avg_stake_per_bet,
           ROUND(e.valid/NULLIF(e.n_rounds,0),4) AS avg_valid_bet_per_round,
           ROUND(-e.net/NULLIF(e.n_rounds,0),4) AS avg_profit_per_round,
           ROUND(-e.net/NULLIF(e.active_days,0),4) AS avg_profit_per_day,
           ROUND(-e.net/NULLIF(e.active_shoes,0),4) AS avg_profit_per_shoe,
           ROUND(e.stake/NULLIF(e.active_days,0),4) AS avg_stake_per_active_day,
           ROUND(e.n_rounds*1.0/NULLIF(e.active_days,0),4) AS avg_rounds_per_active_day,
           ROUND(e.st_in/NULLIF(e.nb_in,0),4) AS avg_stake_late,
           ROUND(e.st_out/NULLIF(e.nb_out,0),4) AS avg_stake_non_late,
           ROUND(e.p25,4) AS p25_stake, ROUND(e.p50,4) AS p50_stake, ROUND(e.p75,4) AS p75_stake,
           ROUND(e.p90,4) AS p90_stake, ROUND(e.p95,4) AS p95_stake, ROUND(e.p99,4) AS p99_stake,
           ROUND(e.p50_valid,4) AS p50_valid_bet, ROUND(e.p50_profit,4) AS p50_profit,
           ROUND(e.p95/NULLIF(e.p50,0),6) AS p95_over_p50,
           ROUND(e.p99/NULLIF(e.p50,0),6) AS p99_over_p50,
           ROUND((e.stake/NULLIF(e.n_bets,0))/NULLIF(e.p50,0),6) AS avg_over_p50,
           -- 三·关系层
           e.n_tables AS common_table_count, e.n_dealers AS common_dealer_count,
           e.n_ips AS common_ip_count, e.n_products AS common_product_count,
           ROUND(e.st_in/NULLIF(e.stake,0),8) AS share_late,
           -- 四·rate 层
           ROUND(-e.net/NULLIF(e.stake,0),8) AS hold_rate,
           ROUND(-e.net_in/NULLIF(e.st_in,0),8) AS hold_rate_late,
           ROUND(e.rebate/NULLIF(e.valid,0),8) AS rebate_rate_actual,
           ROUND(e.rbpct,6) AS rebate_pct_config,
           ROUND(e.valid/NULLIF(e.stake,0),6) AS turnover_multiple,
           ROUND(e.freecomm_rate,6) AS free_comm_rate,
           ROUND(e.net_in/NULLIF(e.st_in,0)-e.net_out/NULLIF(e.st_out,0),8) AS roi_delta_late,
           -- 五·动态层
           e.first_seen_d AS first_seen, e.last_seen_d AS last_seen,
           e.active_days, e.active_shoes, e.active_sessions,
           DATEDIFF(e.last_seen_d, e.first_seen_d)+1 AS span_days,
           ROUND(e.active_days*1.0/NULLIF(DATEDIFF(e.last_seen_d,e.first_seen_d)+1,0),6) AS persistence,
           ROUND((e.st_in/NULLIF(e.nb_in,0))/NULLIF(e.st_out/NULLIF(e.nb_out,0),0),6) AS ramp_late,
           ROUND((e.st_rec/NULLIF(e.nb_rec,0))/NULLIF(e.stake/NULLIF(e.n_bets,0),0),6) AS ramp_recent,
           ROUND((e.st_rec/NULLIF(e.stake,0))/0.30,6) AS stake_ramp_xagg,
           -- 六·决策层（HF9f · 详见档头【HF9f 变更说明】；本段两版逐字同一）
           NTILE(5) OVER (ORDER BY e.stake) AS vip_tier,                                                        -- 窗口取值：相对刻度 B 族，全体五等分；须连同下方血统五元组一并解读，禁作硬阈值判型
           PERCENT_RANK() OVER (ORDER BY -e.net-e.rebate-e.agent_cost)    AS economic_value,                    -- 窗口取值：HF9f·F-19 修正 —— HF9e 写作 -(-…) 双负号致方向颠倒（#075 实测 corr(economic_value, residual_b) = -1.0000）；今与 action_priority 排序键归一，值大即平台真净利高
           PERCENT_RANK() OVER (ORDER BY e.net/NULLIF(e.stake,0))         AS roi_pr_global,                     -- 窗口取值：HF9f·F-17 正名 —— 本列实为 ROI（玩家净回报率）之全体百分位，与「风险」无关；旧名 risk_value 见下一行
           PERCENT_RANK() OVER (ORDER BY e.net/NULLIF(e.stake,0))         AS risk_value,                        -- 窗口取值：兼容列，恒等于 roi_pr_global，仅为下游迁移窗保留；HF9g 起废弃，禁新引用
           PERCENT_RANK() OVER (ORDER BY e.stake)                         AS pr_stake,                          -- 窗口取值：兼容列，恒等于 pr_global，原名保留以免断链
           PERCENT_RANK() OVER (ORDER BY e.stake)                         AS pr_global,                         -- 窗口取值：HF9f·F-1 双轨之一 —— 全体口径百分位，参照总体即本件全部输出行
           CASE WHEN e.n_rounds >= 30                                                                           -- 条件分支：起始分支 —— 仅在合格子集内计算合格口径百分位
                  THEN PERCENT_RANK() OVER (PARTITION BY CASE WHEN e.n_rounds >= 30 THEN 1 ELSE 0 END ORDER BY e.stake)  -- 分支取值：以合格与否分区，故本值即 n_rounds>=30 子集内之百分位
                ELSE NULL END                                             AS pr_qualified,                      -- 条件分支：收束上方分支 —— 不合格者留 NULL（NULL＝未测，非 0），产出「pr_qualified」
           'n_rounds>=30'                                                 AS pr_qualified_population,           -- 字面取值：血统 —— 合格子集之定义
           COUNT(*) OVER ()                                               AS pr_global_population_n,            -- 窗口取值：血统 —— 全体口径之参照总体规模，渲染时现算，禁写死
           SUM(CASE WHEN e.n_rounds >= 30 THEN 1 ELSE 0 END) OVER ()      AS pr_qualified_population_n,         -- 窗口取值：血统 —— 合格子集之参照总体规模，现算，禁写死
           'PERCENT_RANK_OVER_ORDER_BY_e_stake'                           AS pr_calculation_method,             -- 字面取值：血统 —— 算法标识
           'HF9f'                                                         AS pr_calculation_version,            -- 字面取值：血统 —— 算法版本
           CASE WHEN e.n_rounds IS NULL OR e.n_rounds < 30 THEN 'THIN_ROUNDS' ELSE 'OK' END AS evidence_flag,   -- 条件分支：HF9f·F-2a 证据旗标 —— THIN_ROUNDS 者禁入执行队列，仅入观察队列
           CASE WHEN e.n_rounds IS NULL       THEN NULL                                                         -- 条件分支：起始分支 —— 未测者留 NULL（自家铁律：NULL ≠ 0）
                WHEN e.n_rounds >= 31483      THEN 'L1_POWERED'                                                 -- 分支判定：MDE 反解第一档
                WHEN e.n_rounds >= 15409      THEN 'L2_CI_1P5'                                                  -- 分支判定：MDE 反解第二档
                WHEN e.n_rounds >=  8668      THEN 'L3_CI_2P0'                                                  -- 分支判定：MDE 反解第三档
                WHEN e.n_rounds >=  3852      THEN 'L4_CI_3P0'                                                  -- 分支判定：MDE 反解第四档
                ELSE 'L5_INSUFFICIENT' END                                AS evidence_rate,                     -- 条件分支：收束上方 —— HF9f·F-3 证据分档，承 HF9e 前议之 MDE 反解五档，须于 F-4 敏感性实验后复核
           ROUND(1.96 * 0.95 / SQRT(NULLIF(CAST(e.n_rounds AS DOUBLE),0)),8) AS hold_ci_halfwidth_approx,       -- 比率表达式：HF9f·F-3 逐行现算之 95% 半宽近似；常数 0.95 为登记值，本轮 #075 实测每局 ROI 隐含 σ 于最薄层为 0.9249，二者差异待 F-4 裁定
           CASE WHEN e.stake IS NULL OR e.stake<=0 OR e.n_bets<30 OR e.n_rounds IS NULL OR e.n_rounds<30 THEN 'Z 证据不足 · 不动作'  -- 条件分支：HF9f·F-2 双条件取严 —— HF9e 仅卡 e.n_bets<30，致 n_bets>=30 而 n_rounds<30 者绕过 Z（#075 实测 18,537 名，其中 8,145 名已入 A/D 待裁）；今两条件并列取严
                WHEN PERCENT_RANK() OVER (ORDER BY -e.net-e.rebate-e.agent_cost)<=0.10                          -- 分支判定：平台真净利之最低十分位
                  THEN 'A 净亏最大十分位 · 优先复核'                                                             -- 分支取值：HF9f·F-20 正名 —— 本档 Σresidual_b 于 #075 实测 = -100,236,896，系平台净亏最大群，旧名「残值最低十分位 · 待裁」名实不符
                WHEN PERCENT_RANK() OVER (ORDER BY -e.net-e.rebate-e.agent_cost)>=0.80                          -- 分支判定：平台真净利之最高二十分位
                  THEN 'D 净利最高二十分位 · 优先留存'                                                           -- 分支取值：HF9f·F-20 正名 —— 本档 Σresidual_b 于 #075 实测 = +281,733,190，系核心利润源；与 A 档方向相反，旧版同标「待裁」属名实不符
                ELSE 'E 常规' END                                          AS action_priority                   -- 条件分支：收束上方判词，产出「action_priority」
    FROM q
    LEFT JOIN x_agg e ON CAST(e.x_key AS STRING) = CAST(q.`uid` AS STRING)
  ) y
) z
-- ── 逐批 WHERE 阶梯（★ 口诀：上界 ＝ 下界 ＋ 100000，两数同进）──
--    本件 T_true 未测，无需先跑 T_true；以 0 / 100000 控制本批返回区间，末批由实际行数 < 100000 判定
--    WHERE z.audit_rn >        0 AND z.audit_rn <=   100000   -- 第 1 批
--    WHERE z.audit_rn >   100000 AND z.audit_rn <=   200000   -- 第 2 批
--    WHERE z.audit_rn >   200000 AND z.audit_rn <=   300000   -- 第 3 批
--    WHERE z.audit_rn >   300000 AND z.audit_rn <=   400000   -- 第 4 批
--    WHERE z.audit_rn >   400000 AND z.audit_rn <=   500000   -- 第 5 批
--    WHERE z.audit_rn >   500000 AND z.audit_rn <=   600000   -- 第 6 批
--    WHERE z.audit_rn >   600000 AND z.audit_rn <=   700000   -- 第 7 批
--    …余批类推。第 k 批：WHERE z.audit_rn > (k-1)*100000 AND z.audit_rn <= k*100000
--    某批返回 < 100000 行即为末批，其后不再取。
--
--    ⚠ 常见误写（务必避开）：只推下界而上界不动 ——
--        WHERE z.audit_rn > 100000 AND z.audit_rn <= 100000   ← 自相矛盾，恒为假，返回空集
--        WHERE z.audit_rn > 200000 AND z.audit_rn <= 100000   ← 同上，空集
--      两个数必须**同时**前进，且始终相差 100000。
--      下界 ＝ 上一批之上界；上界 ＝ 本批之上界。
WHERE z.audit_rn > 0 AND z.audit_rn <= 100000 -- ★ HF9c 本批区间
ORDER BY z.audit_rn;


-- ══════════════════════════════════════════════════════════════════════════════════════════════
--  65. R01_late_shoe_w2.csv   [总包行 10048~10124 · 原 15 列 ＋六层约 60 列]
--     典型学：M03 尾段投注　派生旗标：late（s.x_rno*1.0/NULLIF(p.max_rno,0) >= 0.80 · 仅供 CASE 条件聚合，全包无任何 WHERE/AND/HAVING 以此过滤）　连接：q.`uid`
-- ══════════════════════════════════════════════════════════════════════════════════════════════
-- ── ① 先跑 T_true 留档（不足 100000 者一次导全，不必分批）──
-- ── ① T_true：HF9c 不再强制预跑完整 COUNT。
--    本批实际返回行数 < 100000 即判定为末批；全批完成后以各批 n_rows / audit_rn 范围核对总量。

-- ── ② 分批取数：第 1 批。第 k 批只改末行两数为 (k-1)*100000 与 k*100000 ──
--    审计字段二（REDTEAM 2026-08-24 裁定 · 四锁）：
--      audit_rn  全局观测坐标 —— 由**与原版审计版逐字同一**之排序键所生，两版可逐行对账
--      batch_id  物理分批信息 —— 该行所属批次，由 audit_rn 算得，非引擎所赋
--    ★ 锁三：二者皆为审计字段，**不得进入任何业务指标计算**。
--    ★ 锁四：两版经 audit_rn 逐行字段核验后，方可宣布输出完全一致。

-- ── ③ 每批取回后自证四数（任一不符即停手回报，禁止放行）──
--    n_rows        = COUNT(*)      须等于 COUNT(DISTINCT audit_rn)   （批内无重复）
--    audit_rn_min  = MIN(audit_rn) 须等于 (k-1)*100000 + 1           （与上批严丝合缝）
--    audit_rn_max  = MAX(audit_rn) 须等于 min + n_rows - 1           （批内无缺口）
--    全批取毕再验：各批 audit_rn 之并集 = 1 .. T_true，无缺号、无重号。
--     ★ 首行＝平台真净亏最多者（已扣退水与代理占成）。
--
SELECT z.*,
       CAST(FLOOR((z.audit_rn - 1) / 100000) + 1 AS INT)          AS batch_id,
       'A168_HF9F_20260827_0900' AS run_id,
       '2026-08-27 09:00:00' AS snapshot_sync_time
FROM (
  SELECT y.*,
         ROW_NUMBER() OVER (ORDER BY y.`residual_b` ASC, y.`roi` DESC, y.`uid`, y.`n_orders_all`, y.`n_orders_late`, y.`late_def`, y.`late_share`, y.`shoe_pos_p50`, y.`stake_late_avg`, y.`stake_early_avg`, y.`stake_ramp`, y.`roi_late`, y.`roi_early`, y.`stake_late`, y.`game_pnl_late`, y.`stake_all`, y.`game_pnl_all`) AS audit_rn
  FROM (
    WITH
      x_ranked AS (
    SELECT b.bet01, b.bet03, b.bet04, b.bet05, b.bet09, b.bet11, b.bet13,
           b.bet15, b.bet16, b.bet17, b.bet18, b.bet19, b.bet20, b.bet21,
           b.bet22, b.bet23, b.bet24, b.bet25, b.bet26, b.bet27, b.bet38, b.bet39, b.category, b.commission,
           b.dt, b.eid, b.ip, b.validbet, b.updatetime, b.sync_time,
           ROW_NUMBER() OVER (
             PARTITION BY b.bet01
             ORDER BY b.updatetime DESC, b.sync_time DESC, b.dt DESC)      AS x_rn
    FROM ods_mariadb_2b.ods_a168_bet02 b
    WHERE b.dt >= '2026-03-21' AND b.dt < '2026-08-07'
      AND b.bet02 = '101'
      AND b.sync_time <= '2026-08-27 09:00:00'
  ),
    x_testagent AS (
    SELECT age001 AS agent_id FROM ods_mariadb_2b.ods_a168_agent WHERE age022 = '1'
  ),
    x_bs0 AS (
    SELECT b.bet05 AS x_member, b.eid AS x_dealer, b.bet39 AS x_table,
           b.bet03 AS x_shoe, b.ip AS x_ip, b.bet09 AS x_product, b.dt AS x_date,
           CONCAT_WS('|', b.bet03, b.bet04, b.bet39)                      AS x_round,
           CONCAT_WS('|', b.bet39, b.bet03)                               AS x_tblshoe,
           CAST(NULLIF(TRIM(b.bet04),'') AS INT)                          AS x_rno,
           CASE WHEN b.dt >= '2026-07-08' THEN 1 ELSE 0 END               AS x_rec,
           CASE WHEN TRIM(b.commission)='1' THEN 1 ELSE 0 END             AS x_freecomm,
           CAST(NULLIF(TRIM(b.bet13),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_stake,
           CAST(NULLIF(TRIM(b.validbet),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_valid,
           CAST(NULLIF(TRIM(b.bet16),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_rebate,
           CAST(NULLIF(TRIM(b.bet17),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_net,
           CAST(NULLIF(TRIM(b.bet15),'') AS DECIMAL(20,6))                AS x_rbpct,
           COALESCE(CAST(NULLIF(TRIM(b.bet23),'') AS DECIMAL(20,6)),0)   AS x_agpct,
          NULLIF(CAST(NULLIF(TRIM(b.bet23),'') AS DECIMAL(20,6)),0)     AS x_rate1,
          NULLIF(CAST(NULLIF(TRIM(b.bet24),'') AS DECIMAL(20,6)),0)     AS x_rate2,
          NULLIF(CAST(NULLIF(TRIM(b.bet25),'') AS DECIMAL(20,6)),0)     AS x_rate3,
          NULLIF(CAST(NULLIF(TRIM(b.bet26),'') AS DECIMAL(20,6)),0)     AS x_rate4,
          NULLIF(CAST(NULLIF(TRIM(b.bet27),'') AS DECIMAL(20,6)),0)     AS x_rate5,
          (CASE WHEN NULLIF(CAST(NULLIF(TRIM(b.bet22),'') AS BIGINT),0) IS NOT NULL THEN 5
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet21),'') AS BIGINT),0) IS NOT NULL THEN 4
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet20),'') AS BIGINT),0) IS NOT NULL THEN 3
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet19),'') AS BIGINT),0) IS NOT NULL THEN 2
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet18),'') AS BIGINT),0) IS NOT NULL THEN 1
                ELSE 0 END)                                             AS x_chain_depth,
           CASE WHEN COALESCE(t1.agent_id,t2.agent_id,t3.agent_id,
                              t4.agent_id,t5.agent_id) IS NOT NULL
                THEN 1 ELSE 0 END                                        AS f_testline
    FROM x_ranked b
    LEFT JOIN x_testagent t1 ON t1.agent_id = b.bet18
    LEFT JOIN x_testagent t2 ON t2.agent_id = b.bet19
    LEFT JOIN x_testagent t3 ON t3.agent_id = b.bet20
    LEFT JOIN x_testagent t4 ON t4.agent_id = b.bet21
    LEFT JOIN x_testagent t5 ON t5.agent_id = b.bet22
    WHERE b.x_rn = 1
      AND b.category='1' AND UPPER(TRIM(b.bet38))='N'
      AND CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8)) > 0
  ),
  x_mk AS (
    SELECT s.*,
           CASE WHEN s.f_testline = 0 THEN 1 ELSE 0 END                 AS is_clean
    FROM x_bs0 s
  ),
  x_sp AS (SELECT x_table, x_shoe, MAX(x_rno) AS max_rno FROM x_mk GROUP BY x_table, x_shoe),
  x_agg AS (
    SELECT s.x_member                                                        AS x_key,
           COUNT(*) AS n_bets, COUNT(DISTINCT s.x_round) AS n_rounds,
           COUNT(DISTINCT s.x_date) AS active_days, COUNT(DISTINCT s.x_tblshoe) AS active_shoes,
           COUNT(DISTINCT CONCAT_WS('|', s.x_date, s.x_table)) AS active_sessions,
           COUNT(DISTINCT s.x_table) AS n_tables, COUNT(DISTINCT s.x_dealer) AS n_dealers,
           COUNT(DISTINCT s.x_ip) AS n_ips, COUNT(DISTINCT s.x_product) AS n_products,
           MIN(s.x_date) AS first_seen_d, MAX(s.x_date) AS last_seen_d,
           SUM(s.x_stake) AS stake, SUM(s.x_valid) AS valid, SUM(s.x_rebate) AS rebate,
           SUM(s.x_net) AS net, SUM(-s.x_net *(100.0-s.x_agpct)/100.0) AS agent_cost,
           AVG(100.0-s.x_agpct)                   AS agent_pct,
           AVG(s.x_agpct)                         AS company_retain_pct,
           SUM(-s.x_net *s.x_agpct/100.0)         AS agent_cost_a_legacy,
           SUM(s.x_valid*s.x_agpct/100.0)         AS agent_cost_valid_base_legacy,
          AVG(COALESCE(s.x_rate1,100)) AS retain_pct_lv1, AVG(COALESCE(s.x_rate2,100)) AS retain_pct_lv2,
          AVG(COALESCE(s.x_rate3,100)) AS retain_pct_lv3, AVG(COALESCE(s.x_rate4,100)) AS retain_pct_lv4,
          AVG(COALESCE(s.x_rate5,100)) AS retain_pct_lv5, AVG(s.x_chain_depth) AS chain_depth_avg,
          AVG(COALESCE(100.0-s.x_rate1,0)) AS agent_pct_lv1, AVG(COALESCE(100.0-s.x_rate2,0)) AS agent_pct_lv2,
          AVG(COALESCE(100.0-s.x_rate3,0)) AS agent_pct_lv3, AVG(COALESCE(100.0-s.x_rate4,0)) AS agent_pct_lv4,
          AVG(COALESCE(100.0-s.x_rate5,0)) AS agent_pct_lv5,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate1,0)/100.0)                        AS agent_cost_lv1,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate2,0)/100.0)                        AS agent_cost_lv2,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate3,0)/100.0)                        AS agent_cost_lv3,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate4,0)/100.0)                        AS agent_cost_lv4,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate5,0)/100.0)                        AS agent_cost_lv5,
          SUM(-s.x_net*(COALESCE(100.0-s.x_rate1,0)+COALESCE(100.0-s.x_rate2,0)
                       +COALESCE(100.0-s.x_rate3,0)+COALESCE(100.0-s.x_rate4,0)
                       +COALESCE(100.0-s.x_rate5,0))/100.0)                   AS agent_cost_chain_additive,
          SUM(-s.x_net*(1.0 - CAST(COALESCE(s.x_rate1,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate2,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate3,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate4,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate5,100) AS DOUBLE)/100.0))
                                                                       AS agent_cost_chain_nested,
           AVG(s.x_rbpct) AS rbpct, AVG(s.x_freecomm*1.0) AS freecomm_rate,
           PERCENTILE_APPROX(s.x_stake,0.25) AS p25, PERCENTILE_APPROX(s.x_stake,0.50) AS p50,
           PERCENTILE_APPROX(s.x_stake,0.75) AS p75, PERCENTILE_APPROX(s.x_stake,0.90) AS p90,
           PERCENTILE_APPROX(s.x_stake,0.95) AS p95, PERCENTILE_APPROX(s.x_stake,0.99) AS p99,
           PERCENTILE_APPROX(s.x_valid,0.50) AS p50_valid,
           PERCENTILE_APPROX(s.x_net,0.50)   AS p50_profit,
           SUM(CASE WHEN s.x_rno*1.0/NULLIF(p.max_rno,0) >= 0.80 THEN s.x_stake ELSE 0 END) AS st_in,
           SUM(CASE WHEN s.x_rno*1.0/NULLIF(p.max_rno,0) >= 0.80 THEN 1 ELSE 0 END)         AS nb_in,
           SUM(CASE WHEN s.x_rno*1.0/NULLIF(p.max_rno,0) >= 0.80 THEN s.x_net ELSE 0 END)   AS net_in,
           SUM(CASE WHEN NOT (s.x_rno*1.0/NULLIF(p.max_rno,0) >= 0.80) THEN s.x_stake ELSE 0 END) AS st_out,
           SUM(CASE WHEN NOT (s.x_rno*1.0/NULLIF(p.max_rno,0) >= 0.80) THEN 1 ELSE 0 END)         AS nb_out,
           SUM(CASE WHEN NOT (s.x_rno*1.0/NULLIF(p.max_rno,0) >= 0.80) THEN s.x_net ELSE 0 END)   AS net_out,
           SUM(CASE WHEN s.x_rec=1 THEN s.x_stake ELSE 0 END) AS st_rec,
           SUM(CASE WHEN s.x_rec=1 THEN 1 ELSE 0 END)         AS nb_rec
    FROM x_mk s
    JOIN x_sp p ON p.x_table = s.x_table AND p.x_shoe = s.x_shoe
    WHERE s.is_clean = 1
      AND s.x_member IS NOT NULL AND TRIM(CAST(s.x_member AS STRING)) <> ''
    GROUP BY s.x_member
  ),
      q AS (
        WITH test_agents AS (                                                                               -- 公共表表达式：开启中间结果集 test_agents，其后各行为其定义体（§R01）
          SELECT age001 AS agent_id                                                                         -- 取列：产出「agent_id」
          FROM ods_mariadb_2b.ods_a168_agent                                                                -- 取数来源：取自代理主档（五级代理线归属来源）
          WHERE age022 = '1'                                  -- 铁律④b：公司测试线
        ),                                                                                                  -- 续行：收束上方的子查询或函数括号（§R01）
        ranked AS (                                            -- 需求 §3.2：同单号保留最新版本
          SELECT b.bet01, b.updatetime, b.sync_time, b.dt, b.bet02,                                         -- 取列：起始取列子句，本行先列 b.bet01, b.updatetime, b.sync_time, b.dt, b.bet02，涉 bet02（游戏类别）、dt（营业日）
                 b.bet03, b.bet04, b.bet05, b.bet11, b.bet13,                                               -- 续行：接续上一取列子句，续列 b.bet03, b.bet04, b.bet05, b.bet11, b.bet13，涉 bet03（靴号）、bet04（局内序号）、bet05（会员号）
                 b.bet14, b.bet18, b.bet19, b.bet20, b.bet21,                                               -- 续行：接续上一取列子句，续列 b.bet14, b.bet18, b.bet19, b.bet20, b.bet21，涉 bet14（派彩金额）、bet18（一级代理线）、bet19（二级代理线）
                 b.bet22, b.bet38, b.bet39, b.category,                                                     -- 续行：接续上一取列子句，续列 b.bet22, b.bet38, b.bet39, b.category，涉 bet22（五级代理线）、bet38（重對）、bet39（桌号）
                 ROW_NUMBER() OVER (                                                                        -- 行号窗口表达式：以行号窗口取每组头部或去重，免出重复行
                   PARTITION BY b.bet01                                                                     -- 窗口分区：按 b.bet01 分组开窗，组内各自编号或排名
                   ORDER BY b.updatetime DESC, b.sync_time DESC, b.dt DESC) AS rn                           -- 排序：按 b.updatetime（降序）, b.sync_time（降序）, b.dt（降序）) AS rn 排列；导出必带排序，否则分页无稳定序（曾致 36.49% 重复行）
          FROM ods_mariadb_2b.ods_a168_bet02 b                 -- ★ 表名开关
          WHERE b.dt >= '2026-08-07' AND b.dt < '2026-08-20'                                                -- 过滤条件：限定 b.dt不少于 '2026-08-07'、b.dt小于 '2026-08-20'，涉 dt（营业日）——W2 紧接主窗右开端点
            AND b.bet02 = '101'
      AND b.sync_time <= '2026-08-27 09:00:00'                                                                             -- 并列条件：限定 b.bet02等于 '101'，涉 bet02（游戏类别）
        ),                                                                                                  -- 续行：收束上方的子查询或函数括号（§R01）
        base AS (                                                                                           -- 公共表表达式：开启中间结果集 base，其后各行为其定义体（§R01）
          SELECT r.bet01 AS bet_id, r.bet05 AS member_id,                                                   -- 取列：起始取列子句，本行先取「member_id」，涉 bet05（会员号）、member_id（会员号）
                 r.bet03 AS shoe_id, r.bet39 AS table_id,                                                   -- 取值表达式：取用 bet03（靴号）、bet39（桌号），产出「table_id」
                 CAST(NULLIF(TRIM(r.bet04),'') AS INT)           AS round_no,                               -- 取值表达式：先去空白、空串归 NULL，再显式转型——本库字段多为 varchar，不转型即比较失真，产出「round_no」
                 CAST(NULLIF(TRIM(r.bet11),'') AS DECIMAL(20,8)) AS fx,                                     -- 取值表达式：先去空白、空串归 NULL，再显式转型——本库字段多为 varchar，不转型即比较失真，产出「fx」
                 CAST(NULLIF(TRIM(r.bet13),'') AS DECIMAL(20,4)) AS stake_raw,                              -- 取值表达式：先去空白、空串归 NULL，再显式转型——本库字段多为 varchar，不转型即比较失真，产出「stake_raw」
                 CAST(NULLIF(TRIM(r.bet14),'') AS DECIMAL(20,4)) AS payout_raw                              -- 取值表达式：先去空白、空串归 NULL，再显式转型——本库字段多为 varchar，不转型即比较失真，产出「payout_raw」
          FROM ranked r                                                                                     -- 取数来源：取自本条自建的中间结果集 ranked
          /* StarRocks 不支持 EXISTS + 多列 IN，测试线剔除改五路 LEFT JOIN */
          LEFT JOIN test_agents t1 ON t1.agent_id = r.bet18                                                 -- 左连接：取自本条自建的中间结果集 test_agents，连接键为 bet18（一级代理线）
          LEFT JOIN test_agents t2 ON t2.agent_id = r.bet19                                                 -- 左连接：取自本条自建的中间结果集 test_agents，连接键为 bet19（二级代理线）
          LEFT JOIN test_agents t3 ON t3.agent_id = r.bet20                                                 -- 左连接：取自本条自建的中间结果集 test_agents，连接键为 bet20（三级代理线）
          LEFT JOIN test_agents t4 ON t4.agent_id = r.bet21                                                 -- 左连接：取自本条自建的中间结果集 test_agents，连接键为 bet21（四级代理线）
          LEFT JOIN test_agents t5 ON t5.agent_id = r.bet22                                                 -- 左连接：取自本条自建的中间结果集 test_agents，连接键为 bet22（五级代理线）
          WHERE r.rn = 1                                                                                    -- 过滤条件：限定 r.rn等于 1
            AND r.category = '1'                                                                            -- 并列条件：限定 r.category等于 '1'
            AND UPPER(TRIM(r.bet38)) = 'N'                                                                  -- 并列条件：限定 UPPER(TRIM(r.bet38))等于 'N'，涉 bet38（重對）
            AND CAST(NULLIF(TRIM(r.bet05),'') AS BIGINT) > 0                                                -- 并列条件：限定 CAST(NULLIF(TRIM(r.bet05),'') AS BIGINT)大于 0，涉 bet05（会员号）
            AND CAST(NULLIF(TRIM(r.bet11),'') AS DECIMAL(20,8)) > 0                                         -- 并列条件：限定 CAST(NULLIF(TRIM(r.bet11),'') AS DECIMAL(20,8))大于 0，涉 bet11（汇率）
            AND CAST(NULLIF(TRIM(r.bet04),'') AS INT) > 0                                                   -- 并列条件：限定 CAST(NULLIF(TRIM(r.bet04),'') AS INT)大于 0，涉 bet04（局内序号）
            AND COALESCE(t1.agent_id,t2.agent_id,t3.agent_id,t4.agent_id,t5.agent_id) IS NULL               -- 并列条件：限定该值为空——本包以左连接加空值判定替代 EXISTS，因 StarRocks 不支持 EXISTS 配多列 IN
        ),                                                                                                  -- 续行：收束上方的子查询或函数括号（§R01）
        shoe_len AS (          /* ★ 命名警示：本 CTE 名为 shoe_len（靴长）系历史沿用，其所算 max_round = MAX(round_no) 为『该靴该桌观测到的最大局号』，非 COUNT(round_no) 之局数；二者仅在局号自1起连续无缺口时相等。选 MAX 为刻意设计：对中间缺口免疫，COUNT 会因清洗剔单而使分母缩水。★ B-01 斧正（2026-08-12）：定标基准逐靴现算，绝对局号不是固定靴位 */   -- 缺陷一修正：定标基准不定，固定 50 不是固定位置
          SELECT shoe_id, table_id, MAX(round_no) AS max_round                                              -- 取列：取最大局号（≠COUNT 局数），产出「max_round」
          FROM base GROUP BY shoe_id, table_id                                                              -- 取数来源：取自本条自建的中间结果集 base
        ),                                                                                                  -- 续行：收束上方的子查询或函数括号（§R01）
        enriched AS (                                                                                       -- 公共表表达式：开启中间结果集 enriched，其后各行为其定义体（§R01）
          SELECT b.member_id, b.shoe_id, b.table_id, b.round_no, s.max_round,                               -- 取列：起始取列子句，本行先列 b.member_id, b.shoe_id, b.table_id, b.round_no, s.max_round，涉 member_id（会员号）
                 b.round_no * 1.0 / NULLIF(s.max_round,0)     AS shoe_pos,                                  -- 取值表达式：产出「shoe_pos」
                 b.stake_raw / b.fx                           AS stake,                                     -- 取值表达式：取用 stake（下注额（经汇率归一化）），产出「stake」
                 (b.payout_raw - b.stake_raw) / b.fx          AS game_pnl,                                  -- 续行：取用 game_pnl（游戏净输赢），产出「game_pnl」
                 CASE WHEN b.round_no * 1.0 / NULLIF(s.max_round,0) >= 0.80
                      THEN 1 ELSE 0 END                        AS is_late   -- B-01 斧正：相对靴位                                    -- 条件分支：产出「is_late」
          FROM base b                                                                                       -- 取数来源：取自本条自建的中间结果集 base
          JOIN shoe_len s ON s.shoe_id = b.shoe_id AND s.table_id = b.table_id                              -- 连接：取自本条自建的中间结果集 shoe_len，连接键为 s.shoe_id = b.shoe_id AND s.table_id = b.table_id
        )                                                                                                   -- 续行：收束上方的子查询或函数括号（§R01）
        SELECT                                                                                              -- 续行：接续上一取列子句，续列 SELECT
          member_id                                                     AS uid,                             -- 取值表达式：取用 member_id（会员号）、uid（会员号），产出「uid」
          COUNT(*)                                                      AS n_orders_all,                    -- 计数表达式：产出「n_orders_all」
          SUM(is_late)                                                  AS n_orders_late,                   -- 汇总表达式：产出「n_orders_late」
          'shoe_pos>=0.80'                                              AS late_def,        -- 口径锁：definition_version = v2
          SUM(is_late) * 1.0 / COUNT(*)                                 AS late_share,                      -- 汇总表达式：计数，取用 late_share（晚注占比），产出「late_share」
          PERCENTILE_APPROX(CASE WHEN is_late=1 THEN shoe_pos END, 0.5) AS shoe_pos_p50,                    -- 取近似分位数表达式：产出「shoe_pos_p50」
          SUM(CASE WHEN is_late=1 THEN stake END) / NULLIF(SUM(is_late),0)              AS stake_late_avg,  -- 汇总表达式：取用 stake（下注额（经汇率归一化）），产出「stake_late_avg」
          SUM(CASE WHEN is_late=0 THEN stake END) / NULLIF(COUNT(*)-SUM(is_late),0)     AS stake_early_avg,  -- 汇总表达式：早段注额合计除以早段注单数 ＝ 早段均注，与 GGR 无涉，产出「stake_early_avg」
          (SUM(CASE WHEN is_late=1 THEN stake END) / NULLIF(SUM(is_late),0))                                -- 续行：汇总，取用 stake（下注额（经汇率归一化））
            / NULLIF(SUM(CASE WHEN is_late=0 THEN stake END)                                                -- 除法或乘法计算：汇总，取用 stake（下注额（经汇率归一化））
                     / NULLIF(COUNT(*)-SUM(is_late),0), 0)                              AS stake_ramp,      -- 除法计算：晚段均注除以早段均注 ＝ 注额斜率，与 GGR 无涉，产出「stake_ramp」
          SUM(CASE WHEN is_late=1 THEN game_pnl END)                                                        -- 汇总表达式：取用 game_pnl（游戏净输赢）
            / NULLIF(SUM(CASE WHEN is_late=1 THEN stake END),0)                         AS roi_late,        -- 除法或乘法计算：汇总，取用 stake（下注额（经汇率归一化）），产出「roi_late」
          SUM(CASE WHEN is_late=0 THEN game_pnl END)                                                        -- 汇总表达式：取用 game_pnl（游戏净输赢）
            / NULLIF(SUM(CASE WHEN is_late=0 THEN stake END),0)                         AS roi_early,       -- 除法或乘法计算：汇总，取用 stake（下注额（经汇率归一化）），产出「roi_early」
          SUM(CASE WHEN is_late=1 THEN stake END)                                       AS stake_late,      -- 汇总表达式：取用 stake（下注额（经汇率归一化）），产出「stake_late」
          SUM(CASE WHEN is_late=1 THEN game_pnl END)                                    AS game_pnl_late,   -- 汇总表达式：取用 game_pnl（游戏净输赢），产出「game_pnl_late」
          SUM(stake)                                                                    AS stake_all,       -- 汇总表达式：取用 stake（下注额（经汇率归一化）），产出「stake_all」
          SUM(game_pnl)                                                                 AS game_pnl_all     -- 汇总表达式：取用 game_pnl（游戏净输赢），产出「game_pnl_all」
        FROM enriched                                                                                       -- 取数来源：取自本条自建的中间结果集 enriched
        GROUP BY member_id                                                                                  -- 分组：按 member_id 汇总
        HAVING COUNT(*) >= 100                                    -- 需求：订单数据 > 100 笔
      )
    SELECT q.*,
           -- 一·经济层
           ROUND(e.stake,4) AS stake, ROUND(e.valid,4) AS valid_bet,
           ROUND(-e.net,4) AS profit, e.n_bets, e.n_rounds,
           ROUND(e.net/NULLIF(e.stake,0),8) AS roi,
           ROUND(e.net_in/NULLIF(e.st_in,0),8) AS roi_late_xagg,
           ROUND(e.net_out/NULLIF(e.st_out,0),8) AS roi_non_late,
           ROUND((e.net-e.rebate)/NULLIF(e.stake,0),8) AS roi_ex_rebate,
           ROUND(e.net,4) AS roi_numerator, ROUND(e.stake,4) AS roi_denominator,
           CASE WHEN e.stake IS NULL THEN 'NULL_DENOM' WHEN e.stake<=0 THEN 'ZERO_DENOM'
                WHEN e.n_bets<30 THEN 'THIN_EXPOSURE' ELSE 'OK' END AS roi_denominator_status,
           ROUND(e.rebate,4) AS rebate_cost, ROUND(e.agent_cost,4)                           AS cost_complement_b,
       ROUND(e.agent_pct,4)                            AS pct_complement,
       ROUND(e.company_retain_pct,4)                   AS pct_top_bet23,
       'AG03-UNRESOLVED'                                     AS agent_formula_version,
      'ALL5_LEVELS_bet23_to_bet27'                    AS agent_level_scope,
      ROUND(e.agent_cost_lv1,4) AS agent_cost_lv1, ROUND(e.agent_cost_lv2,4) AS agent_cost_lv2,
      ROUND(e.agent_cost_lv3,4) AS agent_cost_lv3, ROUND(e.agent_cost_lv4,4) AS agent_cost_lv4,
      ROUND(e.agent_cost_lv5,4) AS agent_cost_lv5,
      ROUND(e.agent_pct_lv1,6) AS agent_pct_lv1, ROUND(e.agent_pct_lv2,6) AS agent_pct_lv2,
      ROUND(e.agent_pct_lv3,6) AS agent_pct_lv3, ROUND(e.agent_pct_lv4,6) AS agent_pct_lv4,
      ROUND(e.agent_pct_lv5,6) AS agent_pct_lv5,
      ROUND(e.retain_pct_lv1,6) AS retain_pct_lv1, ROUND(e.retain_pct_lv2,6) AS retain_pct_lv2,
      ROUND(e.retain_pct_lv3,6) AS retain_pct_lv3, ROUND(e.retain_pct_lv4,6) AS retain_pct_lv4,
      ROUND(e.retain_pct_lv5,6) AS retain_pct_lv5, ROUND(e.chain_depth_avg,4) AS chain_depth_avg,
      ROUND(e.agent_cost_chain_additive,4)            AS agent_cost_chain_additive,
      ROUND(e.agent_cost_chain_nested,4)              AS agent_cost_chain_nested,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_additive,4) AS residual_chain_additive,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_nested,4)   AS residual_chain_nested,
      'PENDING_AG03'                                  AS decision_status,
      'FALSE'                                         AS admit_to_risk_decision,
      'NOT_FOR_ENFORCEMENT'                           AS deliverable_class,
       ROUND(e.agent_cost_a_legacy,4)                  AS agent_cost_a_legacy,
       ROUND(e.agent_cost_valid_base_legacy,4)         AS agent_cost_valid_base_legacy,
           ROUND(-e.net-e.rebate,4)                        AS ngr,
       ROUND(-e.net-e.rebate-e.agent_cost,4)           AS residual_b,
       ROUND(-e.net-e.rebate-e.agent_cost_a_legacy,4)  AS residual_a,
           ROUND((-e.net-e.rebate)/NULLIF(e.stake,0),8)    AS ngr_rate,
       ROUND((-e.net-e.rebate-e.agent_cost)/NULLIF(e.stake,0),8)   AS residual_b_rate,
      -- 【HF9c · canonical accounting contract】
      --   以下 canonical 字段只增加明确 scope；不删除、不覆盖既有字段。
      --   formal_bet23_* 保持 HF9b 当前生产公式及其 NULL/0 语义；
      --   lv1~lv5 / additive / nested 则分别采用各自原始 e.* 成本字段，
      --   rate 一律从未舍入的 e.* 分子 / e.stake 计算，禁止由展示值反算。
      ROUND(e.agent_cost,4) AS agent_cost_bet23_formal_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost,4) AS net_margin_bet23_formal_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost)/NULLIF(e.stake,0),8) AS net_margin_bet23_formal_rate_canonical,
      ROUND(e.agent_cost_lv1,4) AS agent_cost_lv1_bet23_canonical,
      ROUND(e.agent_cost_lv2,4) AS agent_cost_lv2_bet24_canonical,
      ROUND(e.agent_cost_lv3,4) AS agent_cost_lv3_bet25_canonical,
      ROUND(e.agent_cost_lv4,4) AS agent_cost_lv4_bet26_canonical,
      ROUND(e.agent_cost_lv5,4) AS agent_cost_lv5_bet27_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_lv1,4) AS net_margin_lv1_bet23_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_lv1)/NULLIF(e.stake,0),8) AS net_margin_lv1_bet23_rate_canonical,
      ROUND(e.agent_cost_chain_additive,4) AS agent_cost_chain_additive_canonical,
      ROUND(e.agent_cost_chain_nested,4) AS agent_cost_chain_nested_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_additive,4) AS net_margin_chain_additive_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_nested,4) AS net_margin_chain_nested_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_chain_additive)/NULLIF(e.stake,0),8) AS net_margin_chain_additive_rate_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_chain_nested)/NULLIF(e.stake,0),8) AS net_margin_chain_nested_rate_canonical,
       ROUND((-e.net-e.rebate-e.agent_cost_a_legacy)/NULLIF(e.stake,0),8) AS residual_a_rate,
           -- 二·分布层
           ROUND(e.stake/NULLIF(e.n_bets,0),4) AS avg_stake_per_bet,
           ROUND(e.valid/NULLIF(e.n_rounds,0),4) AS avg_valid_bet_per_round,
           ROUND(-e.net/NULLIF(e.n_rounds,0),4) AS avg_profit_per_round,
           ROUND(-e.net/NULLIF(e.active_days,0),4) AS avg_profit_per_day,
           ROUND(-e.net/NULLIF(e.active_shoes,0),4) AS avg_profit_per_shoe,
           ROUND(e.stake/NULLIF(e.active_days,0),4) AS avg_stake_per_active_day,
           ROUND(e.n_rounds*1.0/NULLIF(e.active_days,0),4) AS avg_rounds_per_active_day,
           ROUND(e.st_in/NULLIF(e.nb_in,0),4) AS avg_stake_late,
           ROUND(e.st_out/NULLIF(e.nb_out,0),4) AS avg_stake_non_late,
           ROUND(e.p25,4) AS p25_stake, ROUND(e.p50,4) AS p50_stake, ROUND(e.p75,4) AS p75_stake,
           ROUND(e.p90,4) AS p90_stake, ROUND(e.p95,4) AS p95_stake, ROUND(e.p99,4) AS p99_stake,
           ROUND(e.p50_valid,4) AS p50_valid_bet, ROUND(e.p50_profit,4) AS p50_profit,
           ROUND(e.p95/NULLIF(e.p50,0),6) AS p95_over_p50,
           ROUND(e.p99/NULLIF(e.p50,0),6) AS p99_over_p50,
           ROUND((e.stake/NULLIF(e.n_bets,0))/NULLIF(e.p50,0),6) AS avg_over_p50,
           -- 三·关系层
           e.n_tables AS common_table_count, e.n_dealers AS common_dealer_count,
           e.n_ips AS common_ip_count, e.n_products AS common_product_count,
           ROUND(e.st_in/NULLIF(e.stake,0),8) AS share_late,
           -- 四·rate 层
           ROUND(-e.net/NULLIF(e.stake,0),8) AS hold_rate,
           ROUND(-e.net_in/NULLIF(e.st_in,0),8) AS hold_rate_late,
           ROUND(e.rebate/NULLIF(e.valid,0),8) AS rebate_rate_actual,
           ROUND(e.rbpct,6) AS rebate_pct_config,
           ROUND(e.valid/NULLIF(e.stake,0),6) AS turnover_multiple,
           ROUND(e.freecomm_rate,6) AS free_comm_rate,
           ROUND(e.net_in/NULLIF(e.st_in,0)-e.net_out/NULLIF(e.st_out,0),8) AS roi_delta_late,
           -- 五·动态层
           e.first_seen_d AS first_seen, e.last_seen_d AS last_seen,
           e.active_days, e.active_shoes, e.active_sessions,
           DATEDIFF(e.last_seen_d, e.first_seen_d)+1 AS span_days,
           ROUND(e.active_days*1.0/NULLIF(DATEDIFF(e.last_seen_d,e.first_seen_d)+1,0),6) AS persistence,
           ROUND((e.st_in/NULLIF(e.nb_in,0))/NULLIF(e.st_out/NULLIF(e.nb_out,0),0),6) AS ramp_late,
           ROUND((e.st_rec/NULLIF(e.nb_rec,0))/NULLIF(e.stake/NULLIF(e.n_bets,0),0),6) AS ramp_recent,
           ROUND((e.st_rec/NULLIF(e.stake,0))/0.30,6) AS stake_ramp_xagg,
           -- 六·决策层（HF9f · 详见档头【HF9f 变更说明】；本段两版逐字同一）
           NTILE(5) OVER (ORDER BY e.stake) AS vip_tier,                                                        -- 窗口取值：相对刻度 B 族，全体五等分；须连同下方血统五元组一并解读，禁作硬阈值判型
           PERCENT_RANK() OVER (ORDER BY -e.net-e.rebate-e.agent_cost)    AS economic_value,                    -- 窗口取值：HF9f·F-19 修正 —— HF9e 写作 -(-…) 双负号致方向颠倒（#075 实测 corr(economic_value, residual_b) = -1.0000）；今与 action_priority 排序键归一，值大即平台真净利高
           PERCENT_RANK() OVER (ORDER BY e.net/NULLIF(e.stake,0))         AS roi_pr_global,                     -- 窗口取值：HF9f·F-17 正名 —— 本列实为 ROI（玩家净回报率）之全体百分位，与「风险」无关；旧名 risk_value 见下一行
           PERCENT_RANK() OVER (ORDER BY e.net/NULLIF(e.stake,0))         AS risk_value,                        -- 窗口取值：兼容列，恒等于 roi_pr_global，仅为下游迁移窗保留；HF9g 起废弃，禁新引用
           PERCENT_RANK() OVER (ORDER BY e.stake)                         AS pr_stake,                          -- 窗口取值：兼容列，恒等于 pr_global，原名保留以免断链
           PERCENT_RANK() OVER (ORDER BY e.stake)                         AS pr_global,                         -- 窗口取值：HF9f·F-1 双轨之一 —— 全体口径百分位，参照总体即本件全部输出行
           CASE WHEN e.n_rounds >= 30                                                                           -- 条件分支：起始分支 —— 仅在合格子集内计算合格口径百分位
                  THEN PERCENT_RANK() OVER (PARTITION BY CASE WHEN e.n_rounds >= 30 THEN 1 ELSE 0 END ORDER BY e.stake)  -- 分支取值：以合格与否分区，故本值即 n_rounds>=30 子集内之百分位
                ELSE NULL END                                             AS pr_qualified,                      -- 条件分支：收束上方分支 —— 不合格者留 NULL（NULL＝未测，非 0），产出「pr_qualified」
           'n_rounds>=30'                                                 AS pr_qualified_population,           -- 字面取值：血统 —— 合格子集之定义
           COUNT(*) OVER ()                                               AS pr_global_population_n,            -- 窗口取值：血统 —— 全体口径之参照总体规模，渲染时现算，禁写死
           SUM(CASE WHEN e.n_rounds >= 30 THEN 1 ELSE 0 END) OVER ()      AS pr_qualified_population_n,         -- 窗口取值：血统 —— 合格子集之参照总体规模，现算，禁写死
           'PERCENT_RANK_OVER_ORDER_BY_e_stake'                           AS pr_calculation_method,             -- 字面取值：血统 —— 算法标识
           'HF9f'                                                         AS pr_calculation_version,            -- 字面取值：血统 —— 算法版本
           CASE WHEN e.n_rounds IS NULL OR e.n_rounds < 30 THEN 'THIN_ROUNDS' ELSE 'OK' END AS evidence_flag,   -- 条件分支：HF9f·F-2a 证据旗标 —— THIN_ROUNDS 者禁入执行队列，仅入观察队列
           CASE WHEN e.n_rounds IS NULL       THEN NULL                                                         -- 条件分支：起始分支 —— 未测者留 NULL（自家铁律：NULL ≠ 0）
                WHEN e.n_rounds >= 31483      THEN 'L1_POWERED'                                                 -- 分支判定：MDE 反解第一档
                WHEN e.n_rounds >= 15409      THEN 'L2_CI_1P5'                                                  -- 分支判定：MDE 反解第二档
                WHEN e.n_rounds >=  8668      THEN 'L3_CI_2P0'                                                  -- 分支判定：MDE 反解第三档
                WHEN e.n_rounds >=  3852      THEN 'L4_CI_3P0'                                                  -- 分支判定：MDE 反解第四档
                ELSE 'L5_INSUFFICIENT' END                                AS evidence_rate,                     -- 条件分支：收束上方 —— HF9f·F-3 证据分档，承 HF9e 前议之 MDE 反解五档，须于 F-4 敏感性实验后复核
           ROUND(1.96 * 0.95 / SQRT(NULLIF(CAST(e.n_rounds AS DOUBLE),0)),8) AS hold_ci_halfwidth_approx,       -- 比率表达式：HF9f·F-3 逐行现算之 95% 半宽近似；常数 0.95 为登记值，本轮 #075 实测每局 ROI 隐含 σ 于最薄层为 0.9249，二者差异待 F-4 裁定
           CASE WHEN e.stake IS NULL OR e.stake<=0 OR e.n_bets<30 OR e.n_rounds IS NULL OR e.n_rounds<30 THEN 'Z 证据不足 · 不动作'  -- 条件分支：HF9f·F-2 双条件取严 —— HF9e 仅卡 e.n_bets<30，致 n_bets>=30 而 n_rounds<30 者绕过 Z（#075 实测 18,537 名，其中 8,145 名已入 A/D 待裁）；今两条件并列取严
                WHEN PERCENT_RANK() OVER (ORDER BY -e.net-e.rebate-e.agent_cost)<=0.10                          -- 分支判定：平台真净利之最低十分位
                  THEN 'A 净亏最大十分位 · 优先复核'                                                             -- 分支取值：HF9f·F-20 正名 —— 本档 Σresidual_b 于 #075 实测 = -100,236,896，系平台净亏最大群，旧名「残值最低十分位 · 待裁」名实不符
                WHEN PERCENT_RANK() OVER (ORDER BY -e.net-e.rebate-e.agent_cost)>=0.80                          -- 分支判定：平台真净利之最高二十分位
                  THEN 'D 净利最高二十分位 · 优先留存'                                                           -- 分支取值：HF9f·F-20 正名 —— 本档 Σresidual_b 于 #075 实测 = +281,733,190，系核心利润源；与 A 档方向相反，旧版同标「待裁」属名实不符
                ELSE 'E 常规' END                                          AS action_priority                   -- 条件分支：收束上方判词，产出「action_priority」
    FROM q
    LEFT JOIN x_agg e ON CAST(e.x_key AS STRING) = CAST(q.`uid` AS STRING)
  ) y
) z
-- ── 逐批 WHERE 阶梯（★ 口诀：上界 ＝ 下界 ＋ 100000，两数同进）──
--    本件 T_true 未测，无需先跑 T_true；以 0 / 100000 控制本批返回区间，末批由实际行数 < 100000 判定
--    WHERE z.audit_rn >        0 AND z.audit_rn <=   100000   -- 第 1 批
--    WHERE z.audit_rn >   100000 AND z.audit_rn <=   200000   -- 第 2 批
--    WHERE z.audit_rn >   200000 AND z.audit_rn <=   300000   -- 第 3 批
--    WHERE z.audit_rn >   300000 AND z.audit_rn <=   400000   -- 第 4 批
--    WHERE z.audit_rn >   400000 AND z.audit_rn <=   500000   -- 第 5 批
--    WHERE z.audit_rn >   500000 AND z.audit_rn <=   600000   -- 第 6 批
--    WHERE z.audit_rn >   600000 AND z.audit_rn <=   700000   -- 第 7 批
--    …余批类推。第 k 批：WHERE z.audit_rn > (k-1)*100000 AND z.audit_rn <= k*100000
--    某批返回 < 100000 行即为末批，其后不再取。
--
--    ⚠ 常见误写（务必避开）：只推下界而上界不动 ——
--        WHERE z.audit_rn > 100000 AND z.audit_rn <= 100000   ← 自相矛盾，恒为假，返回空集
--        WHERE z.audit_rn > 200000 AND z.audit_rn <= 100000   ← 同上，空集
--      两个数必须**同时**前进，且始终相差 100000。
--      下界 ＝ 上一批之上界；上界 ＝ 本批之上界。
WHERE z.audit_rn > 0 AND z.audit_rn <= 100000 -- ★ HF9c 本批区间
ORDER BY z.audit_rn;


-- ══════════════════════════════════════════════════════════════════════════════════════════════
--  66. R01anm_shoe_anomaly.csv   [总包行 3948~4009 · 原 11 列 ＋六层约 60 列]
--     典型学：M03 尾段投注　派生旗标：late（s.x_rno*1.0/NULLIF(p.max_rno,0) >= 0.80 · 仅供 CASE 条件聚合，全包无任何 WHERE/AND/HAVING 以此过滤）　连接：q.`table_id`
-- ══════════════════════════════════════════════════════════════════════════════════════════════
-- ── ① 先跑 T_true 留档（不足 100000 者一次导全，不必分批）──
-- ── ① T_true：HF9c 不再强制预跑完整 COUNT。
--    本批实际返回行数 < 100000 即判定为末批；全批完成后以各批 n_rows / audit_rn 范围核对总量。

-- ── ② 分批取数：第 1 批。第 k 批只改末行两数为 (k-1)*100000 与 k*100000 ──
--    审计字段二（REDTEAM 2026-08-24 裁定 · 四锁）：
--      audit_rn  全局观测坐标 —— 由**与原版审计版逐字同一**之排序键所生，两版可逐行对账
--      batch_id  物理分批信息 —— 该行所属批次，由 audit_rn 算得，非引擎所赋
--    ★ 锁三：二者皆为审计字段，**不得进入任何业务指标计算**。
--    ★ 锁四：两版经 audit_rn 逐行字段核验后，方可宣布输出完全一致。

-- ── ③ 每批取回后自证四数（任一不符即停手回报，禁止放行）──
--    n_rows        = COUNT(*)      须等于 COUNT(DISTINCT audit_rn)   （批内无重复）
--    audit_rn_min  = MIN(audit_rn) 须等于 (k-1)*100000 + 1           （与上批严丝合缝）
--    audit_rn_max  = MAX(audit_rn) 须等于 min + n_rows - 1           （批内无缺口）
--    全批取毕再验：各批 audit_rn 之并集 = 1 .. T_true，无缺号、无重号。
--     ★ 首行＝平台真净亏最多者（已扣退水与代理占成）。
--
SELECT z.*,
       CAST(FLOOR((z.audit_rn - 1) / 100000) + 1 AS INT)          AS batch_id,
       'A168_HF9F_20260827_0900' AS run_id,
       '2026-08-27 09:00:00' AS snapshot_sync_time
FROM (
  SELECT y.*,
         ROW_NUMBER() OVER (ORDER BY y.`residual_b` ASC, y.`roi` DESC, y.`dt`, y.`table_id`, y.`shoe_id`, y.`max_round`, y.`min_round`, y.`rounds_with_bet`, y.`gap`, y.`n_bettors`, y.`n_bets`, y.`anomaly_type`, y.`hi_cut_used`) AS audit_rn
  FROM (
    WITH
      x_ranked AS (
    SELECT b.bet01, b.bet03, b.bet04, b.bet05, b.bet09, b.bet11, b.bet13,
           b.bet15, b.bet16, b.bet17, b.bet18, b.bet19, b.bet20, b.bet21,
           b.bet22, b.bet23, b.bet24, b.bet25, b.bet26, b.bet27, b.bet38, b.bet39, b.category, b.commission,
           b.dt, b.eid, b.ip, b.validbet, b.updatetime, b.sync_time,
           ROW_NUMBER() OVER (
             PARTITION BY b.bet01
             ORDER BY b.updatetime DESC, b.sync_time DESC, b.dt DESC)      AS x_rn
    FROM ods_mariadb_2b.ods_a168_bet02 b
    WHERE b.dt >= '2026-03-21' AND b.dt < '2026-08-07'
      AND b.bet02 = '101'
      AND b.sync_time <= '2026-08-27 09:00:00'
  ),
    x_testagent AS (
    SELECT age001 AS agent_id FROM ods_mariadb_2b.ods_a168_agent WHERE age022 = '1'
  ),
    x_bs0 AS (
    SELECT b.bet05 AS x_member, b.eid AS x_dealer, b.bet39 AS x_table,
           b.bet03 AS x_shoe, b.ip AS x_ip, b.bet09 AS x_product, b.dt AS x_date,
           CONCAT_WS('|', b.bet03, b.bet04, b.bet39)                      AS x_round,
           CONCAT_WS('|', b.bet39, b.bet03)                               AS x_tblshoe,
           CAST(NULLIF(TRIM(b.bet04),'') AS INT)                          AS x_rno,
           CASE WHEN b.dt >= '2026-07-08' THEN 1 ELSE 0 END               AS x_rec,
           CASE WHEN TRIM(b.commission)='1' THEN 1 ELSE 0 END             AS x_freecomm,
           CAST(NULLIF(TRIM(b.bet13),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_stake,
           CAST(NULLIF(TRIM(b.validbet),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_valid,
           CAST(NULLIF(TRIM(b.bet16),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_rebate,
           CAST(NULLIF(TRIM(b.bet17),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_net,
           CAST(NULLIF(TRIM(b.bet15),'') AS DECIMAL(20,6))                AS x_rbpct,
           COALESCE(CAST(NULLIF(TRIM(b.bet23),'') AS DECIMAL(20,6)),0)   AS x_agpct,
          NULLIF(CAST(NULLIF(TRIM(b.bet23),'') AS DECIMAL(20,6)),0)     AS x_rate1,
          NULLIF(CAST(NULLIF(TRIM(b.bet24),'') AS DECIMAL(20,6)),0)     AS x_rate2,
          NULLIF(CAST(NULLIF(TRIM(b.bet25),'') AS DECIMAL(20,6)),0)     AS x_rate3,
          NULLIF(CAST(NULLIF(TRIM(b.bet26),'') AS DECIMAL(20,6)),0)     AS x_rate4,
          NULLIF(CAST(NULLIF(TRIM(b.bet27),'') AS DECIMAL(20,6)),0)     AS x_rate5,
          (CASE WHEN NULLIF(CAST(NULLIF(TRIM(b.bet22),'') AS BIGINT),0) IS NOT NULL THEN 5
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet21),'') AS BIGINT),0) IS NOT NULL THEN 4
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet20),'') AS BIGINT),0) IS NOT NULL THEN 3
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet19),'') AS BIGINT),0) IS NOT NULL THEN 2
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet18),'') AS BIGINT),0) IS NOT NULL THEN 1
                ELSE 0 END)                                             AS x_chain_depth,
           CASE WHEN COALESCE(t1.agent_id,t2.agent_id,t3.agent_id,
                              t4.agent_id,t5.agent_id) IS NOT NULL
                THEN 1 ELSE 0 END                                        AS f_testline
    FROM x_ranked b
    LEFT JOIN x_testagent t1 ON t1.agent_id = b.bet18
    LEFT JOIN x_testagent t2 ON t2.agent_id = b.bet19
    LEFT JOIN x_testagent t3 ON t3.agent_id = b.bet20
    LEFT JOIN x_testagent t4 ON t4.agent_id = b.bet21
    LEFT JOIN x_testagent t5 ON t5.agent_id = b.bet22
    WHERE b.x_rn = 1
      AND b.category='1' AND UPPER(TRIM(b.bet38))='N'
      AND CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8)) > 0
  ),
  x_mk AS (
    SELECT s.*,
           CASE WHEN s.f_testline = 0 THEN 1 ELSE 0 END                 AS is_clean
    FROM x_bs0 s
  ),
  x_sp AS (SELECT x_table, x_shoe, MAX(x_rno) AS max_rno FROM x_mk GROUP BY x_table, x_shoe),
  x_agg AS (
    SELECT s.x_table                                                        AS x_key,
           COUNT(*) AS n_bets, COUNT(DISTINCT s.x_round) AS n_rounds,
           COUNT(DISTINCT s.x_date) AS active_days, COUNT(DISTINCT s.x_tblshoe) AS active_shoes,
           COUNT(DISTINCT CONCAT_WS('|', s.x_date, s.x_table)) AS active_sessions,
           COUNT(DISTINCT s.x_table) AS n_tables, COUNT(DISTINCT s.x_dealer) AS n_dealers,
           COUNT(DISTINCT s.x_ip) AS n_ips, COUNT(DISTINCT s.x_product) AS n_products,
           MIN(s.x_date) AS first_seen_d, MAX(s.x_date) AS last_seen_d,
           SUM(s.x_stake) AS stake, SUM(s.x_valid) AS valid, SUM(s.x_rebate) AS rebate,
           SUM(s.x_net) AS net, SUM(-s.x_net *(100.0-s.x_agpct)/100.0) AS agent_cost,
           AVG(100.0-s.x_agpct)                   AS agent_pct,
           AVG(s.x_agpct)                         AS company_retain_pct,
           SUM(-s.x_net *s.x_agpct/100.0)         AS agent_cost_a_legacy,
           SUM(s.x_valid*s.x_agpct/100.0)         AS agent_cost_valid_base_legacy,
          AVG(COALESCE(s.x_rate1,100)) AS retain_pct_lv1, AVG(COALESCE(s.x_rate2,100)) AS retain_pct_lv2,
          AVG(COALESCE(s.x_rate3,100)) AS retain_pct_lv3, AVG(COALESCE(s.x_rate4,100)) AS retain_pct_lv4,
          AVG(COALESCE(s.x_rate5,100)) AS retain_pct_lv5, AVG(s.x_chain_depth) AS chain_depth_avg,
          AVG(COALESCE(100.0-s.x_rate1,0)) AS agent_pct_lv1, AVG(COALESCE(100.0-s.x_rate2,0)) AS agent_pct_lv2,
          AVG(COALESCE(100.0-s.x_rate3,0)) AS agent_pct_lv3, AVG(COALESCE(100.0-s.x_rate4,0)) AS agent_pct_lv4,
          AVG(COALESCE(100.0-s.x_rate5,0)) AS agent_pct_lv5,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate1,0)/100.0)                        AS agent_cost_lv1,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate2,0)/100.0)                        AS agent_cost_lv2,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate3,0)/100.0)                        AS agent_cost_lv3,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate4,0)/100.0)                        AS agent_cost_lv4,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate5,0)/100.0)                        AS agent_cost_lv5,
          SUM(-s.x_net*(COALESCE(100.0-s.x_rate1,0)+COALESCE(100.0-s.x_rate2,0)
                       +COALESCE(100.0-s.x_rate3,0)+COALESCE(100.0-s.x_rate4,0)
                       +COALESCE(100.0-s.x_rate5,0))/100.0)                   AS agent_cost_chain_additive,
          SUM(-s.x_net*(1.0 - CAST(COALESCE(s.x_rate1,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate2,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate3,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate4,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate5,100) AS DOUBLE)/100.0))
                                                                       AS agent_cost_chain_nested,
           AVG(s.x_rbpct) AS rbpct, AVG(s.x_freecomm*1.0) AS freecomm_rate,
           PERCENTILE_APPROX(s.x_stake,0.25) AS p25, PERCENTILE_APPROX(s.x_stake,0.50) AS p50,
           PERCENTILE_APPROX(s.x_stake,0.75) AS p75, PERCENTILE_APPROX(s.x_stake,0.90) AS p90,
           PERCENTILE_APPROX(s.x_stake,0.95) AS p95, PERCENTILE_APPROX(s.x_stake,0.99) AS p99,
           PERCENTILE_APPROX(s.x_valid,0.50) AS p50_valid,
           PERCENTILE_APPROX(s.x_net,0.50)   AS p50_profit,
           SUM(CASE WHEN s.x_rno*1.0/NULLIF(p.max_rno,0) >= 0.80 THEN s.x_stake ELSE 0 END) AS st_in,
           SUM(CASE WHEN s.x_rno*1.0/NULLIF(p.max_rno,0) >= 0.80 THEN 1 ELSE 0 END)         AS nb_in,
           SUM(CASE WHEN s.x_rno*1.0/NULLIF(p.max_rno,0) >= 0.80 THEN s.x_net ELSE 0 END)   AS net_in,
           SUM(CASE WHEN NOT (s.x_rno*1.0/NULLIF(p.max_rno,0) >= 0.80) THEN s.x_stake ELSE 0 END) AS st_out,
           SUM(CASE WHEN NOT (s.x_rno*1.0/NULLIF(p.max_rno,0) >= 0.80) THEN 1 ELSE 0 END)         AS nb_out,
           SUM(CASE WHEN NOT (s.x_rno*1.0/NULLIF(p.max_rno,0) >= 0.80) THEN s.x_net ELSE 0 END)   AS net_out,
           SUM(CASE WHEN s.x_rec=1 THEN s.x_stake ELSE 0 END) AS st_rec,
           SUM(CASE WHEN s.x_rec=1 THEN 1 ELSE 0 END)         AS nb_rec
    FROM x_mk s
    JOIN x_sp p ON p.x_table = s.x_table AND p.x_shoe = s.x_shoe
    WHERE s.is_clean = 1
      AND s.x_table IS NOT NULL AND TRIM(CAST(s.x_table AS STRING)) <> ''
    GROUP BY s.x_table
  ),
      q AS (
        WITH test_agents AS (                                                                               -- 公共表表达式：开启中间结果集 test_agents，其后各行为其定义体（§R01-anm）
          SELECT age001 AS agent_id                                                                         -- 取列：产出「agent_id」
          FROM ods_mariadb_2b.ods_a168_agent                                                                -- 取数来源：取自代理主档（五级代理线归属来源）
          WHERE age022 = '1'                                  -- 铁律④b：公司测试线
        ),                                                                                                  -- 续行：收束上方的子查询或函数括号（§R01-anm）
        ranked AS (                                            -- 需求 §3.2：同单号保留最新版本
          SELECT b.bet01, b.dt, b.bet03, b.bet04, b.bet05, b.bet11,                                         -- 取列：起始取列子句，本行先列 b.bet01, b.dt, b.bet03, b.bet04, b.bet05, b.bet11，涉 dt（营业日）、bet03（靴号）、bet04（局内序号）
                 b.bet18, b.bet19, b.bet20, b.bet21, b.bet22,                                               -- 续行：接续上一取列子句，续列 b.bet18~b.bet22，涉五级代理线（测试线剔除之连接键）
                 b.bet38, b.bet39, b.category,                                                              -- 续行：接续上一取列子句，续列 b.bet38, b.bet39, b.category，涉 bet38（重對）、bet39（桌号）、category（注单类别）
                 ROW_NUMBER() OVER (                                                                        -- 行号窗口表达式：以行号窗口取每组头部或去重，免出重复行
                   PARTITION BY b.bet01                                                                     -- 窗口分区：按 b.bet01 分组开窗，组内各自编号或排名
                   ORDER BY b.updatetime DESC, b.sync_time DESC, b.dt DESC) AS rn                           -- 排序：按 b.updatetime（降序）, b.sync_time（降序）, b.dt（降序）) AS rn 排列；导出必带排序，否则分页无稳定序（曾致 36.49% 重复行）
          FROM ods_mariadb_2b.ods_a168_bet02 b                 -- ★ 表名开关
          WHERE b.dt >= '2026-03-21' AND b.dt < '2026-08-07'                                                -- 过滤条件：限定 b.dt不少于 '2026-03-21'、b.dt小于 '2026-08-07'，涉 dt（营业日）
            AND b.bet02 = '101'
      AND b.sync_time <= '2026-08-27 09:00:00'                                                                             -- 并列条件：限定 b.bet02等于 '101'，涉 bet02（游戏类别）
        ),                                                                                                  -- 续行：收束上方的子查询或函数括号（§R01-anm）
        base AS (                                                                                           -- 公共表表达式：开启中间结果集 base，其后各行为其定义体（§R01-anm）
          SELECT r.dt                                          AS dt,                                       -- 取列：起始取列子句，本行先取「dt」，涉 dt（营业日）——本族较 §R01 之唯一增列
                 CAST(NULLIF(TRIM(r.bet05),'') AS BIGINT)      AS member_id,                                -- 取值表达式：先去空白、空串归 NULL，再显式转型——本库字段多为 varchar，不转型即比较失真，产出「member_id」
                 COALESCE(NULLIF(TRIM(r.bet03),''), '(空)')    AS shoe_id,                                  -- 取值表达式：空串归哨兵「(空)」以免与真靴号混算，涉 bet03（靴号），产出「shoe_id」
                 COALESCE(NULLIF(TRIM(r.bet39),''), '(空)')    AS table_id,                                 -- 取值表达式：空串归哨兵「(空)」以免与真桌号混算，涉 bet39（桌号），产出「table_id」
                 CAST(NULLIF(TRIM(r.bet04),'') AS INT)         AS round_no                                  -- 取值表达式：先去空白、空串归 NULL，再显式转型——本库字段多为 varchar，不转型即比较失真，产出「round_no」
          FROM ranked r                                                                                     -- 取数来源：取自本条自建的中间结果集 ranked
          LEFT JOIN test_agents t1 ON t1.agent_id = r.bet18                                                 -- 左连接：取自本条自建的中间结果集 test_agents，连接键为 bet18（一级代理线）
          LEFT JOIN test_agents t2 ON t2.agent_id = r.bet19                                                 -- 左连接：取自本条自建的中间结果集 test_agents，连接键为 bet19（二级代理线）
          LEFT JOIN test_agents t3 ON t3.agent_id = r.bet20                                                 -- 左连接：取自本条自建的中间结果集 test_agents，连接键为 bet20（三级代理线）
          LEFT JOIN test_agents t4 ON t4.agent_id = r.bet21                                                 -- 左连接：取自本条自建的中间结果集 test_agents，连接键为 bet21（四级代理线）
          LEFT JOIN test_agents t5 ON t5.agent_id = r.bet22                                                 -- 左连接：取自本条自建的中间结果集 test_agents，连接键为 bet22（五级代理线）
          WHERE r.rn = 1                                                                                    -- 过滤条件：限定 r.rn等于 1
            AND r.category = '1'                                                                            -- 并列条件：限定 r.category等于 '1'
            AND UPPER(TRIM(r.bet38)) = 'N'                                                                  -- 并列条件：限定 UPPER(TRIM(r.bet38))等于 'N'，涉 bet38（重對）
            AND CAST(NULLIF(TRIM(r.bet05),'') AS BIGINT) > 0                                                -- 并列条件：限定 CAST(NULLIF(TRIM(r.bet05),'') AS BIGINT)大于 0，涉 bet05（会员号）
            AND CAST(NULLIF(TRIM(r.bet11),'') AS DECIMAL(20,8)) > 0                                         -- 并列条件：限定 CAST(NULLIF(TRIM(r.bet11),'') AS DECIMAL(20,8))大于 0，涉 bet11（汇率）
            AND CAST(NULLIF(TRIM(r.bet04),'') AS INT) > 0                                                   -- 并列条件：限定 CAST(NULLIF(TRIM(r.bet04),'') AS INT)大于 0，涉 bet04（局内序号）
            AND COALESCE(t1.agent_id,t2.agent_id,t3.agent_id,t4.agent_id,t5.agent_id) IS NULL               -- 并列条件：限定该值为空——本包以左连接加空值判定替代 EXISTS，因 StarRocks 不支持 EXISTS 配多列 IN
        ),                                                                                                  -- 续行：收束上方的子查询或函数括号（§R01-anm）
        shoe_new AS (          /* ★ 新粒度（(dt, table_id, shoe_id)）：所算 max_round = MAX(round_no) 为最大局号，非局数；不沿用 shoe_len 之名，见卷首命名警示横幅。★ */
          SELECT dt, table_id, shoe_id,                                                                     -- 取列：起始取列子句，本行先列 dt, table_id, shoe_id，涉 dt（营业日）、bet39（桌号）、bet03（靴号）
                 MAX(round_no)                                        AS max_round,                         -- 取最大局号（≠COUNT 局数），产出「max_round」
                 MIN(round_no)                                        AS min_round,                         -- 聚合表达式：最小局号——不为 1 者示首局无人下注，产出「min_round」
                 COUNT(DISTINCT round_no)                             AS rounds_with_bet,                   -- 计数表达式：局内序号的去重个数——有注局数，产出「rounds_with_bet」
                 MAX(round_no) - COUNT(DISTINCT round_no)             AS gap,                               -- 取值表达式：最大局号减有注局数——内部缺口，非尾部截断，产出「gap」
                 COUNT(DISTINCT member_id)                            AS n_bettors,                         -- 计数表达式：会员号的去重个数，产出「n_bettors」
                 COUNT(*)                                             AS n_bets                             -- 计数表达式：注单数，产出「n_bets」
          FROM base                                                                                         -- 取数来源：取自本条自建的中间结果集 base
          GROUP BY dt, table_id, shoe_id                                                                    -- 分组：按 dt, table_id, shoe_id 汇总——新粒度
        ),                                                                                                  -- 续行：收束上方的子查询或函数括号（§R01-anm）
        cut AS (               /* 阈值由数据反解，禁硬写——本包不设普适门槛（见卷首常数集中登记之纪律）。 */
          SELECT PERCENTILE_APPROX(max_round, 0.99) * 1.5 AS hi_cut                                         -- 取近似分位数表达式：全域九九分位之 1.5 倍——超长靴之切点，产出「hi_cut」
          FROM shoe_new                                                                                     -- 取数来源：取自本条自建的中间结果集 shoe_new
        )                                                                                                   -- 续行：收束上方的子查询或函数括号（§R01-anm）
        SELECT s.dt, s.table_id, s.shoe_id,                                                                 -- 取列：起始取列子句，本行先列 s.dt, s.table_id, s.shoe_id，涉 dt（营业日）、bet39（桌号）、bet03（靴号）
               s.max_round, s.min_round, s.rounds_with_bet, s.gap,                                          -- 续行：接续上一取列子句，续列最大局号、最小局号、有注局数、内部缺口
               s.n_bettors, s.n_bets,                                                                       -- 续行：接续上一取列子句，续列下注会员数、注单数
               CASE WHEN s.max_round > c.hi_cut THEN '超长：碰撞或跨日合并可疑'                              -- 条件分支：起始分支——超长者列为碰撞候选
                    WHEN s.max_round <= 5       THEN '残靴：截断／换荷官／开收台可疑'                        -- 分支判定：残靴者列为截断候选
                    ELSE '—' END                             AS anomaly_type,                               -- 条件分支：收束上方判词，产出「anomaly_type」
               ROUND(c.hi_cut, 2)                            AS hi_cut_used                                 -- 取值表达式：本次实际所用之上界切点（随数据现算），产出「hi_cut_used」
        FROM shoe_new s                                                                                     -- 取数来源：取自本条自建的中间结果集 shoe_new
        CROSS JOIN cut c                                                                                    -- 连接：取自本条自建的中间结果集 cut，单行广播（阈值现算）
        WHERE s.max_round > c.hi_cut OR s.max_round <= 5                                                    -- 过滤条件：限定超长或残靴二者之一
      )
    SELECT q.*,
           -- 一·经济层
           ROUND(e.stake,4) AS stake, ROUND(e.valid,4) AS valid_bet,
           ROUND(-e.net,4) AS profit, e.n_bets AS n_bets_xagg, e.n_rounds,
           ROUND(e.net/NULLIF(e.stake,0),8) AS roi,
           ROUND(e.net_in/NULLIF(e.st_in,0),8) AS roi_late,
           ROUND(e.net_out/NULLIF(e.st_out,0),8) AS roi_non_late,
           ROUND((e.net-e.rebate)/NULLIF(e.stake,0),8) AS roi_ex_rebate,
           ROUND(e.net,4) AS roi_numerator, ROUND(e.stake,4) AS roi_denominator,
           CASE WHEN e.stake IS NULL THEN 'NULL_DENOM' WHEN e.stake<=0 THEN 'ZERO_DENOM'
                WHEN e.n_bets<30 THEN 'THIN_EXPOSURE' ELSE 'OK' END AS roi_denominator_status,
           ROUND(e.rebate,4) AS rebate_cost, ROUND(e.agent_cost,4)                           AS cost_complement_b,
       ROUND(e.agent_pct,4)                            AS pct_complement,
       ROUND(e.company_retain_pct,4)                   AS pct_top_bet23,
       'AG03-UNRESOLVED'                                     AS agent_formula_version,
      'ALL5_LEVELS_bet23_to_bet27'                    AS agent_level_scope,
      ROUND(e.agent_cost_lv1,4) AS agent_cost_lv1, ROUND(e.agent_cost_lv2,4) AS agent_cost_lv2,
      ROUND(e.agent_cost_lv3,4) AS agent_cost_lv3, ROUND(e.agent_cost_lv4,4) AS agent_cost_lv4,
      ROUND(e.agent_cost_lv5,4) AS agent_cost_lv5,
      ROUND(e.agent_pct_lv1,6) AS agent_pct_lv1, ROUND(e.agent_pct_lv2,6) AS agent_pct_lv2,
      ROUND(e.agent_pct_lv3,6) AS agent_pct_lv3, ROUND(e.agent_pct_lv4,6) AS agent_pct_lv4,
      ROUND(e.agent_pct_lv5,6) AS agent_pct_lv5,
      ROUND(e.retain_pct_lv1,6) AS retain_pct_lv1, ROUND(e.retain_pct_lv2,6) AS retain_pct_lv2,
      ROUND(e.retain_pct_lv3,6) AS retain_pct_lv3, ROUND(e.retain_pct_lv4,6) AS retain_pct_lv4,
      ROUND(e.retain_pct_lv5,6) AS retain_pct_lv5, ROUND(e.chain_depth_avg,4) AS chain_depth_avg,
      ROUND(e.agent_cost_chain_additive,4)            AS agent_cost_chain_additive,
      ROUND(e.agent_cost_chain_nested,4)              AS agent_cost_chain_nested,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_additive,4) AS residual_chain_additive,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_nested,4)   AS residual_chain_nested,
      'PENDING_AG03'                                  AS decision_status,
      'FALSE'                                         AS admit_to_risk_decision,
      'NOT_FOR_ENFORCEMENT'                           AS deliverable_class,
       ROUND(e.agent_cost_a_legacy,4)                  AS agent_cost_a_legacy,
       ROUND(e.agent_cost_valid_base_legacy,4)         AS agent_cost_valid_base_legacy,
           ROUND(-e.net-e.rebate,4)                        AS ngr,
       ROUND(-e.net-e.rebate-e.agent_cost,4)           AS residual_b,
       ROUND(-e.net-e.rebate-e.agent_cost_a_legacy,4)  AS residual_a,
           ROUND((-e.net-e.rebate)/NULLIF(e.stake,0),8)    AS ngr_rate,
       ROUND((-e.net-e.rebate-e.agent_cost)/NULLIF(e.stake,0),8)   AS residual_b_rate,
      -- 【HF9c · canonical accounting contract】
      --   以下 canonical 字段只增加明确 scope；不删除、不覆盖既有字段。
      --   formal_bet23_* 保持 HF9b 当前生产公式及其 NULL/0 语义；
      --   lv1~lv5 / additive / nested 则分别采用各自原始 e.* 成本字段，
      --   rate 一律从未舍入的 e.* 分子 / e.stake 计算，禁止由展示值反算。
      ROUND(e.agent_cost,4) AS agent_cost_bet23_formal_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost,4) AS net_margin_bet23_formal_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost)/NULLIF(e.stake,0),8) AS net_margin_bet23_formal_rate_canonical,
      ROUND(e.agent_cost_lv1,4) AS agent_cost_lv1_bet23_canonical,
      ROUND(e.agent_cost_lv2,4) AS agent_cost_lv2_bet24_canonical,
      ROUND(e.agent_cost_lv3,4) AS agent_cost_lv3_bet25_canonical,
      ROUND(e.agent_cost_lv4,4) AS agent_cost_lv4_bet26_canonical,
      ROUND(e.agent_cost_lv5,4) AS agent_cost_lv5_bet27_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_lv1,4) AS net_margin_lv1_bet23_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_lv1)/NULLIF(e.stake,0),8) AS net_margin_lv1_bet23_rate_canonical,
      ROUND(e.agent_cost_chain_additive,4) AS agent_cost_chain_additive_canonical,
      ROUND(e.agent_cost_chain_nested,4) AS agent_cost_chain_nested_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_additive,4) AS net_margin_chain_additive_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_nested,4) AS net_margin_chain_nested_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_chain_additive)/NULLIF(e.stake,0),8) AS net_margin_chain_additive_rate_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_chain_nested)/NULLIF(e.stake,0),8) AS net_margin_chain_nested_rate_canonical,
       ROUND((-e.net-e.rebate-e.agent_cost_a_legacy)/NULLIF(e.stake,0),8) AS residual_a_rate,
           -- 二·分布层
           ROUND(e.stake/NULLIF(e.n_bets,0),4) AS avg_stake_per_bet,
           ROUND(e.valid/NULLIF(e.n_rounds,0),4) AS avg_valid_bet_per_round,
           ROUND(-e.net/NULLIF(e.n_rounds,0),4) AS avg_profit_per_round,
           ROUND(-e.net/NULLIF(e.active_days,0),4) AS avg_profit_per_day,
           ROUND(-e.net/NULLIF(e.active_shoes,0),4) AS avg_profit_per_shoe,
           ROUND(e.stake/NULLIF(e.active_days,0),4) AS avg_stake_per_active_day,
           ROUND(e.n_rounds*1.0/NULLIF(e.active_days,0),4) AS avg_rounds_per_active_day,
           ROUND(e.st_in/NULLIF(e.nb_in,0),4) AS avg_stake_late,
           ROUND(e.st_out/NULLIF(e.nb_out,0),4) AS avg_stake_non_late,
           ROUND(e.p25,4) AS p25_stake, ROUND(e.p50,4) AS p50_stake, ROUND(e.p75,4) AS p75_stake,
           ROUND(e.p90,4) AS p90_stake, ROUND(e.p95,4) AS p95_stake, ROUND(e.p99,4) AS p99_stake,
           ROUND(e.p50_valid,4) AS p50_valid_bet, ROUND(e.p50_profit,4) AS p50_profit,
           ROUND(e.p95/NULLIF(e.p50,0),6) AS p95_over_p50,
           ROUND(e.p99/NULLIF(e.p50,0),6) AS p99_over_p50,
           ROUND((e.stake/NULLIF(e.n_bets,0))/NULLIF(e.p50,0),6) AS avg_over_p50,
           -- 三·关系层
           e.n_tables AS common_table_count, e.n_dealers AS common_dealer_count,
           e.n_ips AS common_ip_count, e.n_products AS common_product_count,
           ROUND(e.st_in/NULLIF(e.stake,0),8) AS share_late,
           -- 四·rate 层
           ROUND(-e.net/NULLIF(e.stake,0),8) AS hold_rate,
           ROUND(-e.net_in/NULLIF(e.st_in,0),8) AS hold_rate_late,
           ROUND(e.rebate/NULLIF(e.valid,0),8) AS rebate_rate_actual,
           ROUND(e.rbpct,6) AS rebate_pct_config,
           ROUND(e.valid/NULLIF(e.stake,0),6) AS turnover_multiple,
           ROUND(e.freecomm_rate,6) AS free_comm_rate,
           ROUND(e.net_in/NULLIF(e.st_in,0)-e.net_out/NULLIF(e.st_out,0),8) AS roi_delta_late,
           -- 五·动态层
           e.first_seen_d AS first_seen, e.last_seen_d AS last_seen,
           e.active_days, e.active_shoes, e.active_sessions,
           DATEDIFF(e.last_seen_d, e.first_seen_d)+1 AS span_days,
           ROUND(e.active_days*1.0/NULLIF(DATEDIFF(e.last_seen_d,e.first_seen_d)+1,0),6) AS persistence,
           ROUND((e.st_in/NULLIF(e.nb_in,0))/NULLIF(e.st_out/NULLIF(e.nb_out,0),0),6) AS ramp_late,
           ROUND((e.st_rec/NULLIF(e.nb_rec,0))/NULLIF(e.stake/NULLIF(e.n_bets,0),0),6) AS ramp_recent,
           ROUND((e.st_rec/NULLIF(e.stake,0))/0.30,6) AS stake_ramp,
           -- 六·决策层（HF9f · 详见档头【HF9f 变更说明】；本段两版逐字同一）
           NTILE(5) OVER (ORDER BY e.stake) AS vip_tier,                                                        -- 窗口取值：相对刻度 B 族，全体五等分；须连同下方血统五元组一并解读，禁作硬阈值判型
           PERCENT_RANK() OVER (ORDER BY -e.net-e.rebate-e.agent_cost)    AS economic_value,                    -- 窗口取值：HF9f·F-19 修正 —— HF9e 写作 -(-…) 双负号致方向颠倒（#075 实测 corr(economic_value, residual_b) = -1.0000）；今与 action_priority 排序键归一，值大即平台真净利高
           PERCENT_RANK() OVER (ORDER BY e.net/NULLIF(e.stake,0))         AS roi_pr_global,                     -- 窗口取值：HF9f·F-17 正名 —— 本列实为 ROI（玩家净回报率）之全体百分位，与「风险」无关；旧名 risk_value 见下一行
           PERCENT_RANK() OVER (ORDER BY e.net/NULLIF(e.stake,0))         AS risk_value,                        -- 窗口取值：兼容列，恒等于 roi_pr_global，仅为下游迁移窗保留；HF9g 起废弃，禁新引用
           PERCENT_RANK() OVER (ORDER BY e.stake)                         AS pr_stake,                          -- 窗口取值：兼容列，恒等于 pr_global，原名保留以免断链
           PERCENT_RANK() OVER (ORDER BY e.stake)                         AS pr_global,                         -- 窗口取值：HF9f·F-1 双轨之一 —— 全体口径百分位，参照总体即本件全部输出行
           CASE WHEN e.n_rounds >= 30                                                                           -- 条件分支：起始分支 —— 仅在合格子集内计算合格口径百分位
                  THEN PERCENT_RANK() OVER (PARTITION BY CASE WHEN e.n_rounds >= 30 THEN 1 ELSE 0 END ORDER BY e.stake)  -- 分支取值：以合格与否分区，故本值即 n_rounds>=30 子集内之百分位
                ELSE NULL END                                             AS pr_qualified,                      -- 条件分支：收束上方分支 —— 不合格者留 NULL（NULL＝未测，非 0），产出「pr_qualified」
           'n_rounds>=30'                                                 AS pr_qualified_population,           -- 字面取值：血统 —— 合格子集之定义
           COUNT(*) OVER ()                                               AS pr_global_population_n,            -- 窗口取值：血统 —— 全体口径之参照总体规模，渲染时现算，禁写死
           SUM(CASE WHEN e.n_rounds >= 30 THEN 1 ELSE 0 END) OVER ()      AS pr_qualified_population_n,         -- 窗口取值：血统 —— 合格子集之参照总体规模，现算，禁写死
           'PERCENT_RANK_OVER_ORDER_BY_e_stake'                           AS pr_calculation_method,             -- 字面取值：血统 —— 算法标识
           'HF9f'                                                         AS pr_calculation_version,            -- 字面取值：血统 —— 算法版本
           CASE WHEN e.n_rounds IS NULL OR e.n_rounds < 30 THEN 'THIN_ROUNDS' ELSE 'OK' END AS evidence_flag,   -- 条件分支：HF9f·F-2a 证据旗标 —— THIN_ROUNDS 者禁入执行队列，仅入观察队列
           CASE WHEN e.n_rounds IS NULL       THEN NULL                                                         -- 条件分支：起始分支 —— 未测者留 NULL（自家铁律：NULL ≠ 0）
                WHEN e.n_rounds >= 31483      THEN 'L1_POWERED'                                                 -- 分支判定：MDE 反解第一档
                WHEN e.n_rounds >= 15409      THEN 'L2_CI_1P5'                                                  -- 分支判定：MDE 反解第二档
                WHEN e.n_rounds >=  8668      THEN 'L3_CI_2P0'                                                  -- 分支判定：MDE 反解第三档
                WHEN e.n_rounds >=  3852      THEN 'L4_CI_3P0'                                                  -- 分支判定：MDE 反解第四档
                ELSE 'L5_INSUFFICIENT' END                                AS evidence_rate,                     -- 条件分支：收束上方 —— HF9f·F-3 证据分档，承 HF9e 前议之 MDE 反解五档，须于 F-4 敏感性实验后复核
           ROUND(1.96 * 0.95 / SQRT(NULLIF(CAST(e.n_rounds AS DOUBLE),0)),8) AS hold_ci_halfwidth_approx,       -- 比率表达式：HF9f·F-3 逐行现算之 95% 半宽近似；常数 0.95 为登记值，本轮 #075 实测每局 ROI 隐含 σ 于最薄层为 0.9249，二者差异待 F-4 裁定
           CASE WHEN e.stake IS NULL OR e.stake<=0 OR e.n_bets<30 OR e.n_rounds IS NULL OR e.n_rounds<30 THEN 'Z 证据不足 · 不动作'  -- 条件分支：HF9f·F-2 双条件取严 —— HF9e 仅卡 e.n_bets<30，致 n_bets>=30 而 n_rounds<30 者绕过 Z（#075 实测 18,537 名，其中 8,145 名已入 A/D 待裁）；今两条件并列取严
                WHEN PERCENT_RANK() OVER (ORDER BY -e.net-e.rebate-e.agent_cost)<=0.10                          -- 分支判定：平台真净利之最低十分位
                  THEN 'A 净亏最大十分位 · 优先复核'                                                             -- 分支取值：HF9f·F-20 正名 —— 本档 Σresidual_b 于 #075 实测 = -100,236,896，系平台净亏最大群，旧名「残值最低十分位 · 待裁」名实不符
                WHEN PERCENT_RANK() OVER (ORDER BY -e.net-e.rebate-e.agent_cost)>=0.80                          -- 分支判定：平台真净利之最高二十分位
                  THEN 'D 净利最高二十分位 · 优先留存'                                                           -- 分支取值：HF9f·F-20 正名 —— 本档 Σresidual_b 于 #075 实测 = +281,733,190，系核心利润源；与 A 档方向相反，旧版同标「待裁」属名实不符
                ELSE 'E 常规' END                                          AS action_priority                   -- 条件分支：收束上方判词，产出「action_priority」
    FROM q
    LEFT JOIN x_agg e ON CAST(e.x_key AS STRING) = CAST(q.`table_id` AS STRING)
  ) y
) z
-- ── 逐批 WHERE 阶梯（★ 口诀：上界 ＝ 下界 ＋ 100000，两数同进）──
--    本件 T_true 未测，无需先跑 T_true；以 0 / 100000 控制本批返回区间，末批由实际行数 < 100000 判定
--    WHERE z.audit_rn >        0 AND z.audit_rn <=   100000   -- 第 1 批
--    WHERE z.audit_rn >   100000 AND z.audit_rn <=   200000   -- 第 2 批
--    WHERE z.audit_rn >   200000 AND z.audit_rn <=   300000   -- 第 3 批
--    WHERE z.audit_rn >   300000 AND z.audit_rn <=   400000   -- 第 4 批
--    WHERE z.audit_rn >   400000 AND z.audit_rn <=   500000   -- 第 5 批
--    WHERE z.audit_rn >   500000 AND z.audit_rn <=   600000   -- 第 6 批
--    WHERE z.audit_rn >   600000 AND z.audit_rn <=   700000   -- 第 7 批
--    …余批类推。第 k 批：WHERE z.audit_rn > (k-1)*100000 AND z.audit_rn <= k*100000
--    某批返回 < 100000 行即为末批，其后不再取。
--
--    ⚠ 常见误写（务必避开）：只推下界而上界不动 ——
--        WHERE z.audit_rn > 100000 AND z.audit_rn <= 100000   ← 自相矛盾，恒为假，返回空集
--        WHERE z.audit_rn > 200000 AND z.audit_rn <= 100000   ← 同上，空集
--      两个数必须**同时**前进，且始终相差 100000。
--      下界 ＝ 上一批之上界；上界 ＝ 本批之上界。
WHERE z.audit_rn > 0 AND z.audit_rn <= 100000 -- ★ HF9c 本批区间
ORDER BY z.audit_rn;


-- ══════════════════════════════════════════════════════════════════════════════════════════════
--  67. R01chk_shoe_len_by_table.csv   [总包行 3725~3855 · 原 28 列 ＋六层约 60 列]
--     典型学：M03 尾段投注　派生旗标：late（s.x_rno*1.0/NULLIF(p.max_rno,0) >= 0.80 · 仅供 CASE 条件聚合，全包无任何 WHERE/AND/HAVING 以此过滤）　连接：q.`table_id`
-- ══════════════════════════════════════════════════════════════════════════════════════════════
-- ── ① 先跑 T_true 留档（不足 100000 者一次导全，不必分批）──
-- ── ① T_true：HF9c 不再强制预跑完整 COUNT。
--    本批实际返回行数 < 100000 即判定为末批；全批完成后以各批 n_rows / audit_rn 范围核对总量。

-- ── ② 分批取数：第 1 批。第 k 批只改末行两数为 (k-1)*100000 与 k*100000 ──
--    审计字段二（REDTEAM 2026-08-24 裁定 · 四锁）：
--      audit_rn  全局观测坐标 —— 由**与原版审计版逐字同一**之排序键所生，两版可逐行对账
--      batch_id  物理分批信息 —— 该行所属批次，由 audit_rn 算得，非引擎所赋
--    ★ 锁三：二者皆为审计字段，**不得进入任何业务指标计算**。
--    ★ 锁四：两版经 audit_rn 逐行字段核验后，方可宣布输出完全一致。

-- ── ③ 每批取回后自证四数（任一不符即停手回报，禁止放行）──
--    n_rows        = COUNT(*)      须等于 COUNT(DISTINCT audit_rn)   （批内无重复）
--    audit_rn_min  = MIN(audit_rn) 须等于 (k-1)*100000 + 1           （与上批严丝合缝）
--    audit_rn_max  = MAX(audit_rn) 须等于 min + n_rows - 1           （批内无缺口）
--    全批取毕再验：各批 audit_rn 之并集 = 1 .. T_true，无缺号、无重号。
--     ★ 首行＝平台真净亏最多者（已扣退水与代理占成）。
--
SELECT z.*,
       CAST(FLOOR((z.audit_rn - 1) / 100000) + 1 AS INT)          AS batch_id,
       'A168_HF9F_20260827_0900' AS run_id,
       '2026-08-27 09:00:00' AS snapshot_sync_time
FROM (
  SELECT y.*,
         ROW_NUMBER() OVER (ORDER BY y.`residual_b` ASC, y.`roi` DESC, y.`table_id`, y.`table_flag`, y.`n_shoes`, y.`n_shoes_old`, y.`n_shoes_delta`, y.`avg_max_round`, y.`avg_max_round_old`, y.`avg_maxround_inflation`, y.`sd_max_round`, y.`min_max_round`, y.`ceiling_observed`, y.`ceiling_old`, y.`p50_max_round`, y.`p90_max_round`, y.`p99_max_round`, y.`collision_flag`, y.`n_stub_shoes`, y.`avg_gap`, y.`avg_n_bettors`, y.`avg_bets_per_round`, y.`round_at_pos080`, y.`corr_len_density`, y.`corr_density_lo95`, y.`corr_density_hi95`, y.`corr_density_verdict`, y.`corr_len_bettors`, y.`corr_bettors_lo95`, y.`corr_bettors_hi95`) AS audit_rn
  FROM (
    WITH
      x_ranked AS (
    SELECT b.bet01, b.bet03, b.bet04, b.bet05, b.bet09, b.bet11, b.bet13,
           b.bet15, b.bet16, b.bet17, b.bet18, b.bet19, b.bet20, b.bet21,
           b.bet22, b.bet23, b.bet24, b.bet25, b.bet26, b.bet27, b.bet38, b.bet39, b.category, b.commission,
           b.dt, b.eid, b.ip, b.validbet, b.updatetime, b.sync_time,
           ROW_NUMBER() OVER (
             PARTITION BY b.bet01
             ORDER BY b.updatetime DESC, b.sync_time DESC, b.dt DESC)      AS x_rn
    FROM ods_mariadb_2b.ods_a168_bet02 b
    WHERE b.dt >= '2026-03-21' AND b.dt < '2026-08-07'
      AND b.bet02 = '101'
      AND b.sync_time <= '2026-08-27 09:00:00'
  ),
    x_testagent AS (
    SELECT age001 AS agent_id FROM ods_mariadb_2b.ods_a168_agent WHERE age022 = '1'
  ),
    x_bs0 AS (
    SELECT b.bet05 AS x_member, b.eid AS x_dealer, b.bet39 AS x_table,
           b.bet03 AS x_shoe, b.ip AS x_ip, b.bet09 AS x_product, b.dt AS x_date,
           CONCAT_WS('|', b.bet03, b.bet04, b.bet39)                      AS x_round,
           CONCAT_WS('|', b.bet39, b.bet03)                               AS x_tblshoe,
           CAST(NULLIF(TRIM(b.bet04),'') AS INT)                          AS x_rno,
           CASE WHEN b.dt >= '2026-07-08' THEN 1 ELSE 0 END               AS x_rec,
           CASE WHEN TRIM(b.commission)='1' THEN 1 ELSE 0 END             AS x_freecomm,
           CAST(NULLIF(TRIM(b.bet13),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_stake,
           CAST(NULLIF(TRIM(b.validbet),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_valid,
           CAST(NULLIF(TRIM(b.bet16),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_rebate,
           CAST(NULLIF(TRIM(b.bet17),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_net,
           CAST(NULLIF(TRIM(b.bet15),'') AS DECIMAL(20,6))                AS x_rbpct,
           COALESCE(CAST(NULLIF(TRIM(b.bet23),'') AS DECIMAL(20,6)),0)   AS x_agpct,
          NULLIF(CAST(NULLIF(TRIM(b.bet23),'') AS DECIMAL(20,6)),0)     AS x_rate1,
          NULLIF(CAST(NULLIF(TRIM(b.bet24),'') AS DECIMAL(20,6)),0)     AS x_rate2,
          NULLIF(CAST(NULLIF(TRIM(b.bet25),'') AS DECIMAL(20,6)),0)     AS x_rate3,
          NULLIF(CAST(NULLIF(TRIM(b.bet26),'') AS DECIMAL(20,6)),0)     AS x_rate4,
          NULLIF(CAST(NULLIF(TRIM(b.bet27),'') AS DECIMAL(20,6)),0)     AS x_rate5,
          (CASE WHEN NULLIF(CAST(NULLIF(TRIM(b.bet22),'') AS BIGINT),0) IS NOT NULL THEN 5
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet21),'') AS BIGINT),0) IS NOT NULL THEN 4
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet20),'') AS BIGINT),0) IS NOT NULL THEN 3
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet19),'') AS BIGINT),0) IS NOT NULL THEN 2
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet18),'') AS BIGINT),0) IS NOT NULL THEN 1
                ELSE 0 END)                                             AS x_chain_depth,
           CASE WHEN COALESCE(t1.agent_id,t2.agent_id,t3.agent_id,
                              t4.agent_id,t5.agent_id) IS NOT NULL
                THEN 1 ELSE 0 END                                        AS f_testline
    FROM x_ranked b
    LEFT JOIN x_testagent t1 ON t1.agent_id = b.bet18
    LEFT JOIN x_testagent t2 ON t2.agent_id = b.bet19
    LEFT JOIN x_testagent t3 ON t3.agent_id = b.bet20
    LEFT JOIN x_testagent t4 ON t4.agent_id = b.bet21
    LEFT JOIN x_testagent t5 ON t5.agent_id = b.bet22
    WHERE b.x_rn = 1
      AND b.category='1' AND UPPER(TRIM(b.bet38))='N'
      AND CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8)) > 0
  ),
  x_mk AS (
    SELECT s.*,
           CASE WHEN s.f_testline = 0 THEN 1 ELSE 0 END                 AS is_clean
    FROM x_bs0 s
  ),
  x_sp AS (SELECT x_table, x_shoe, MAX(x_rno) AS max_rno FROM x_mk GROUP BY x_table, x_shoe),
  x_agg AS (
    SELECT s.x_table                                                        AS x_key,
           COUNT(*) AS n_bets, COUNT(DISTINCT s.x_round) AS n_rounds,
           COUNT(DISTINCT s.x_date) AS active_days, COUNT(DISTINCT s.x_tblshoe) AS active_shoes,
           COUNT(DISTINCT CONCAT_WS('|', s.x_date, s.x_table)) AS active_sessions,
           COUNT(DISTINCT s.x_table) AS n_tables, COUNT(DISTINCT s.x_dealer) AS n_dealers,
           COUNT(DISTINCT s.x_ip) AS n_ips, COUNT(DISTINCT s.x_product) AS n_products,
           MIN(s.x_date) AS first_seen_d, MAX(s.x_date) AS last_seen_d,
           SUM(s.x_stake) AS stake, SUM(s.x_valid) AS valid, SUM(s.x_rebate) AS rebate,
           SUM(s.x_net) AS net, SUM(-s.x_net *(100.0-s.x_agpct)/100.0) AS agent_cost,
           AVG(100.0-s.x_agpct)                   AS agent_pct,
           AVG(s.x_agpct)                         AS company_retain_pct,
           SUM(-s.x_net *s.x_agpct/100.0)         AS agent_cost_a_legacy,
           SUM(s.x_valid*s.x_agpct/100.0)         AS agent_cost_valid_base_legacy,
          AVG(COALESCE(s.x_rate1,100)) AS retain_pct_lv1, AVG(COALESCE(s.x_rate2,100)) AS retain_pct_lv2,
          AVG(COALESCE(s.x_rate3,100)) AS retain_pct_lv3, AVG(COALESCE(s.x_rate4,100)) AS retain_pct_lv4,
          AVG(COALESCE(s.x_rate5,100)) AS retain_pct_lv5, AVG(s.x_chain_depth) AS chain_depth_avg,
          AVG(COALESCE(100.0-s.x_rate1,0)) AS agent_pct_lv1, AVG(COALESCE(100.0-s.x_rate2,0)) AS agent_pct_lv2,
          AVG(COALESCE(100.0-s.x_rate3,0)) AS agent_pct_lv3, AVG(COALESCE(100.0-s.x_rate4,0)) AS agent_pct_lv4,
          AVG(COALESCE(100.0-s.x_rate5,0)) AS agent_pct_lv5,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate1,0)/100.0)                        AS agent_cost_lv1,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate2,0)/100.0)                        AS agent_cost_lv2,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate3,0)/100.0)                        AS agent_cost_lv3,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate4,0)/100.0)                        AS agent_cost_lv4,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate5,0)/100.0)                        AS agent_cost_lv5,
          SUM(-s.x_net*(COALESCE(100.0-s.x_rate1,0)+COALESCE(100.0-s.x_rate2,0)
                       +COALESCE(100.0-s.x_rate3,0)+COALESCE(100.0-s.x_rate4,0)
                       +COALESCE(100.0-s.x_rate5,0))/100.0)                   AS agent_cost_chain_additive,
          SUM(-s.x_net*(1.0 - CAST(COALESCE(s.x_rate1,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate2,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate3,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate4,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate5,100) AS DOUBLE)/100.0))
                                                                       AS agent_cost_chain_nested,
           AVG(s.x_rbpct) AS rbpct, AVG(s.x_freecomm*1.0) AS freecomm_rate,
           PERCENTILE_APPROX(s.x_stake,0.25) AS p25, PERCENTILE_APPROX(s.x_stake,0.50) AS p50,
           PERCENTILE_APPROX(s.x_stake,0.75) AS p75, PERCENTILE_APPROX(s.x_stake,0.90) AS p90,
           PERCENTILE_APPROX(s.x_stake,0.95) AS p95, PERCENTILE_APPROX(s.x_stake,0.99) AS p99,
           PERCENTILE_APPROX(s.x_valid,0.50) AS p50_valid,
           PERCENTILE_APPROX(s.x_net,0.50)   AS p50_profit,
           SUM(CASE WHEN s.x_rno*1.0/NULLIF(p.max_rno,0) >= 0.80 THEN s.x_stake ELSE 0 END) AS st_in,
           SUM(CASE WHEN s.x_rno*1.0/NULLIF(p.max_rno,0) >= 0.80 THEN 1 ELSE 0 END)         AS nb_in,
           SUM(CASE WHEN s.x_rno*1.0/NULLIF(p.max_rno,0) >= 0.80 THEN s.x_net ELSE 0 END)   AS net_in,
           SUM(CASE WHEN NOT (s.x_rno*1.0/NULLIF(p.max_rno,0) >= 0.80) THEN s.x_stake ELSE 0 END) AS st_out,
           SUM(CASE WHEN NOT (s.x_rno*1.0/NULLIF(p.max_rno,0) >= 0.80) THEN 1 ELSE 0 END)         AS nb_out,
           SUM(CASE WHEN NOT (s.x_rno*1.0/NULLIF(p.max_rno,0) >= 0.80) THEN s.x_net ELSE 0 END)   AS net_out,
           SUM(CASE WHEN s.x_rec=1 THEN s.x_stake ELSE 0 END) AS st_rec,
           SUM(CASE WHEN s.x_rec=1 THEN 1 ELSE 0 END)         AS nb_rec
    FROM x_mk s
    JOIN x_sp p ON p.x_table = s.x_table AND p.x_shoe = s.x_shoe
    WHERE s.is_clean = 1
      AND s.x_table IS NOT NULL AND TRIM(CAST(s.x_table AS STRING)) <> ''
    GROUP BY s.x_table
  ),
      q AS (
        WITH test_agents AS (                                                                               -- 公共表表达式：开启中间结果集 test_agents，其后各行为其定义体（§R01-chk）
          SELECT age001 AS agent_id                                                                         -- 取列：产出「agent_id」
          FROM ods_mariadb_2b.ods_a168_agent                                                                -- 取数来源：取自代理主档（五级代理线归属来源）
          WHERE age022 = '1'                                  -- 铁律④b：公司测试线
        ),                                                                                                  -- 续行：收束上方的子查询或函数括号（§R01-chk）
        ranked AS (                                            -- 需求 §3.2：同单号保留最新版本
          SELECT b.bet01, b.dt, b.bet03, b.bet04, b.bet05, b.bet11,                                         -- 取列：起始取列子句，本行先列 b.bet01, b.dt, b.bet03, b.bet04, b.bet05, b.bet11，涉 dt（营业日）、bet03（靴号）、bet04（局内序号）
                 b.bet18, b.bet19, b.bet20, b.bet21, b.bet22,                                               -- 续行：接续上一取列子句，续列 b.bet18~b.bet22，涉五级代理线（测试线剔除之连接键）
                 b.bet38, b.bet39, b.category,                                                              -- 续行：接续上一取列子句，续列 b.bet38, b.bet39, b.category，涉 bet38（重對）、bet39（桌号）、category（注单类别）
                 ROW_NUMBER() OVER (                                                                        -- 行号窗口表达式：以行号窗口取每组头部或去重，免出重复行
                   PARTITION BY b.bet01                                                                     -- 窗口分区：按 b.bet01 分组开窗，组内各自编号或排名
                   ORDER BY b.updatetime DESC, b.sync_time DESC, b.dt DESC) AS rn                           -- 排序：按 b.updatetime（降序）, b.sync_time（降序）, b.dt（降序）) AS rn 排列；导出必带排序，否则分页无稳定序（曾致 36.49% 重复行）
          FROM ods_mariadb_2b.ods_a168_bet02 b                 -- ★ 表名开关
          WHERE b.dt >= '2026-03-21' AND b.dt < '2026-08-07'                                                -- 过滤条件：限定 b.dt不少于 '2026-03-21'、b.dt小于 '2026-08-07'，涉 dt（营业日）
            AND b.bet02 = '101'
      AND b.sync_time <= '2026-08-27 09:00:00'                                                                             -- 并列条件：限定 b.bet02等于 '101'，涉 bet02（游戏类别）
        ),                                                                                                  -- 续行：收束上方的子查询或函数括号（§R01-chk）
        base AS (                                                                                           -- 公共表表达式：开启中间结果集 base，其后各行为其定义体（§R01-chk）
          SELECT r.dt                                          AS dt,                                       -- 取列：起始取列子句，本行先取「dt」，涉 dt（营业日）——本族较 §R01 之唯一增列
                 CAST(NULLIF(TRIM(r.bet05),'') AS BIGINT)      AS member_id,                                -- 取值表达式：先去空白、空串归 NULL，再显式转型——本库字段多为 varchar，不转型即比较失真，产出「member_id」
                 COALESCE(NULLIF(TRIM(r.bet03),''), '(空)')    AS shoe_id,                                  -- 取值表达式：空串归哨兵「(空)」以免与真靴号混算，涉 bet03（靴号），产出「shoe_id」
                 COALESCE(NULLIF(TRIM(r.bet39),''), '(空)')    AS table_id,                                 -- 取值表达式：空串归哨兵「(空)」以免与真桌号混算，涉 bet39（桌号），产出「table_id」
                 CAST(NULLIF(TRIM(r.bet04),'') AS INT)         AS round_no                                  -- 取值表达式：先去空白、空串归 NULL，再显式转型——本库字段多为 varchar，不转型即比较失真，产出「round_no」
          FROM ranked r                                                                                     -- 取数来源：取自本条自建的中间结果集 ranked
          LEFT JOIN test_agents t1 ON t1.agent_id = r.bet18                                                 -- 左连接：取自本条自建的中间结果集 test_agents，连接键为 bet18（一级代理线）
          LEFT JOIN test_agents t2 ON t2.agent_id = r.bet19                                                 -- 左连接：取自本条自建的中间结果集 test_agents，连接键为 bet19（二级代理线）
          LEFT JOIN test_agents t3 ON t3.agent_id = r.bet20                                                 -- 左连接：取自本条自建的中间结果集 test_agents，连接键为 bet20（三级代理线）
          LEFT JOIN test_agents t4 ON t4.agent_id = r.bet21                                                 -- 左连接：取自本条自建的中间结果集 test_agents，连接键为 bet21（四级代理线）
          LEFT JOIN test_agents t5 ON t5.agent_id = r.bet22                                                 -- 左连接：取自本条自建的中间结果集 test_agents，连接键为 bet22（五级代理线）
          WHERE r.rn = 1                                                                                    -- 过滤条件：限定 r.rn等于 1
            AND r.category = '1'                                                                            -- 并列条件：限定 r.category等于 '1'
            AND UPPER(TRIM(r.bet38)) = 'N'                                                                  -- 并列条件：限定 UPPER(TRIM(r.bet38))等于 'N'，涉 bet38（重對）
            AND CAST(NULLIF(TRIM(r.bet05),'') AS BIGINT) > 0                                                -- 并列条件：限定 CAST(NULLIF(TRIM(r.bet05),'') AS BIGINT)大于 0，涉 bet05（会员号）
            AND CAST(NULLIF(TRIM(r.bet11),'') AS DECIMAL(20,8)) > 0                                         -- 并列条件：限定 CAST(NULLIF(TRIM(r.bet11),'') AS DECIMAL(20,8))大于 0，涉 bet11（汇率）
            AND CAST(NULLIF(TRIM(r.bet04),'') AS INT) > 0                                                   -- 并列条件：限定 CAST(NULLIF(TRIM(r.bet04),'') AS INT)大于 0，涉 bet04（局内序号）
            AND COALESCE(t1.agent_id,t2.agent_id,t3.agent_id,t4.agent_id,t5.agent_id) IS NULL               -- 并列条件：限定该值为空——本包以左连接加空值判定替代 EXISTS，因 StarRocks 不支持 EXISTS 配多列 IN
        ),                                                                                                  -- 续行：收束上方的子查询或函数括号（§R01-chk）
        shoe_new AS (          /* ★ 新粒度（(dt, table_id, shoe_id)）：靴号纵跨日复用亦不致合并。所算 max_round = MAX(round_no) 为『该靴该桌该日观测到的最大局号』，非 COUNT(round_no) 之局数；此处刻意不沿用 shoe_len 之名，见卷首命名警示横幅。★ */
          SELECT dt, table_id, shoe_id,                                                                     -- 取列：起始取列子句，本行先列 dt, table_id, shoe_id，涉 dt（营业日）、bet39（桌号）、bet03（靴号）
                 MAX(round_no)                                        AS max_round,                         -- 取最大局号（≠COUNT 局数），产出「max_round」
                 COUNT(DISTINCT round_no)                             AS rounds_with_bet,                   -- 计数表达式：局内序号的去重个数——有注局数，产出「rounds_with_bet」
                 MAX(round_no) - COUNT(DISTINCT round_no)             AS gap,                               -- 取值表达式：最大局号减有注局数——内部缺口，非尾部截断，产出「gap」
                 COUNT(DISTINCT member_id)                            AS n_bettors,                         -- 计数表达式：会员号的去重个数——桌面稀疏度之一，产出「n_bettors」
                 COUNT(*)                                             AS n_bets,                            -- 计数表达式：注单数，产出「n_bets」
                 COUNT(*) * 1.0 / NULLIF(COUNT(DISTINCT round_no), 0) AS bets_per_round                     -- 除法计算：每局注单数——桌面稀疏度之二，分母以 NULLIF 守门防零除，产出「bets_per_round」
          FROM base                                                                                         -- 取数来源：取自本条自建的中间结果集 base
          GROUP BY dt, table_id, shoe_id                                                                    -- 分组：按 dt, table_id, shoe_id 汇总——新粒度
        ),                                                                                                  -- 续行：收束上方的子查询或函数括号（§R01-chk）
        shoe_old AS (          /* ★ 旧粒度（(table_id, shoe_id)）：§R01 现行口径，留作对照，其与新粒度之差即粒度污染之量。★ */
          SELECT table_id, shoe_id,                                                                         -- 取列：起始取列子句，本行先列 table_id, shoe_id，涉 bet39（桌号）、bet03（靴号）
                 MAX(round_no) AS max_round_old                                                             -- 取最大局号（≠COUNT 局数），产出「max_round_old」
          FROM base                                                                                         -- 取数来源：取自本条自建的中间结果集 base
          GROUP BY table_id, shoe_id                                                                        -- 分组：按 table_id, shoe_id 汇总——旧粒度
        ),                                                                                                  -- 续行：收束上方的子查询或函数括号（§R01-chk）
        agg AS (                                                                                            -- 公共表表达式：开启中间结果集 agg，其后各行为其定义体（§R01-chk）
          SELECT table_id,                                                                                  -- 取列：起始取列子句，本行先取「table_id」，涉 bet39（桌号）
                 COUNT(*)                                     AS n_shoes,                                   -- 计数表达式：本桌之靴数（新粒度），产出「n_shoes」
                 AVG(max_round)                               AS avg_max_round,                             -- 聚合表达式：最大局号均值，产出「avg_max_round」
                 STDDEV_SAMP(max_round)                       AS sd_max_round,                              -- 聚合表达式：最大局号样本标准差，产出「sd_max_round」
                 MIN(max_round)                               AS min_max_round,                             -- 聚合表达式：最大局号下界——残靴之证据，产出「min_max_round」
                 MAX(max_round)                               AS ceiling_observed,                          -- 聚合表达式：最大局号上界——物理上限（切牌收靴）之证据，产出「ceiling_observed」
                 PERCENTILE_APPROX(max_round, 0.50)           AS p50_max_round,                             -- 取近似分位数表达式：中位，产出「p50_max_round」
                 PERCENTILE_APPROX(max_round, 0.90)           AS p90_max_round,                             -- 取近似分位数表达式：九十分位，产出「p90_max_round」
                 PERCENTILE_APPROX(max_round, 0.99)           AS p99_max_round,                             -- 取近似分位数表达式：九九分位，产出「p99_max_round」
                 AVG(gap)                                     AS avg_gap,                                   -- 聚合表达式：内部缺口均值，产出「avg_gap」
                 AVG(n_bettors)                               AS avg_n_bettors,                             -- 聚合表达式：每靴下注会员数均值，产出「avg_n_bettors」
                 AVG(bets_per_round)                          AS avg_bets_per_round,                        -- 聚合表达式：每局注单数均值，产出「avg_bets_per_round」
                 CORR(max_round, bets_per_round)              AS r_density,                                 -- 聚合表达式：靴长与桌面密度之相关——低估假说之判别力核心，产出「r_density」
                 CORR(max_round, n_bettors)                   AS r_bettors,                                 -- 聚合表达式：靴长与下注人数之相关，产出「r_bettors」
                 SUM(CASE WHEN max_round <= 5 THEN 1 ELSE 0 END) AS n_stub_shoes                            -- 条件分支：最大局号不超过 5 之残靴数，产出「n_stub_shoes」
          FROM shoe_new                                                                                     -- 取数来源：取自本条自建的中间结果集 shoe_new
          GROUP BY table_id                                                                                 -- 分组：按桌号汇总
        ),                                                                                                  -- 续行：收束上方的子查询或函数括号（§R01-chk）
        agg_old AS (                                                                                        -- 公共表表达式：开启中间结果集 agg_old，其后各行为其定义体（§R01-chk）
          SELECT table_id,                                                                                  -- 取列：起始取列子句，本行先取「table_id」，涉 bet39（桌号）
                 COUNT(*)           AS n_shoes_old,                                                         -- 计数表达式：本桌之靴数（旧粒度），产出「n_shoes_old」
                 AVG(max_round_old) AS avg_max_round_old,                                                   -- 聚合表达式：旧粒度最大局号均值，产出「avg_max_round_old」
                 MAX(max_round_old) AS ceiling_old                                                          -- 聚合表达式：旧粒度最大局号上界，产出「ceiling_old」
          FROM shoe_old                                                                                     -- 取数来源：取自本条自建的中间结果集 shoe_old
          GROUP BY table_id                                                                                 -- 分组：按桌号汇总
        ),                                                                                                  -- 续行：收束上方的子查询或函数括号（§R01-chk）
        zc AS (                /* Fisher-z 变换：z = 0.5·ln((1+r)/(1−r))，se = 1/√(n−3)；反变换 tanh(x) = (e^{2x}−1)/(e^{2x}+1)。样本量护栏不设普适门槛，由统计量本身反解：n ≤ 3 者 z 无定义，|r| → 1 者对数发散，二者一律归 NULL 照登，禁以点估计代 CI 下结论。 */
          SELECT a.*,                                                                                       -- 取列：承接上一子句，取 agg 全列
                 CASE WHEN a.n_shoes > 3 AND ABS(a.r_density) < 0.999999                                    -- 分支判定：样本量大于 3 且相关系数未贴边者方可变换
                      THEN 0.5 * LN((1 + a.r_density) / (1 - a.r_density)) END AS z_d,                      -- 条件分支：密度相关之 Fisher-z，产出「z_d」
                 CASE WHEN a.n_shoes > 3 AND ABS(a.r_bettors) < 0.999999                                    -- 分支判定：样本量大于 3 且相关系数未贴边者方可变换
                      THEN 0.5 * LN((1 + a.r_bettors) / (1 - a.r_bettors)) END AS z_b,                      -- 条件分支：人数相关之 Fisher-z，产出「z_b」
                 CASE WHEN a.n_shoes > 3                                                                    -- 分支判定：样本量大于 3 者方有标准误
                      THEN 1.959964 / SQRT(a.n_shoes - 3) END                  AS hw                        -- 条件分支：95% 区间半宽（z=1.959964 双侧），产出「hw」
          FROM agg a                                                                                        -- 取数来源：取自本条自建的中间结果集 agg
        )                                                                                                   -- 续行：收束上方的子查询或函数括号（§R01-chk）
        SELECT                                                                                              -- 取列：起始取列子句
          z.table_id,                                                                                       -- 取列：涉 bet39（桌号）
          CASE WHEN z.table_id = '(空)' THEN '哨兵（禁并入正常桌）' ELSE '正常' END      AS table_flag,      -- 条件分支：哨兵标记——空串桌号单列，禁与正常桌混算，产出「table_flag」
          z.n_shoes,                                                                                        -- 取列：本桌靴数（新粒度）
          o.n_shoes_old,                                                                                    -- 取列：本桌靴数（旧粒度）
          z.n_shoes - o.n_shoes_old                                    AS n_shoes_delta,                    -- 取值表达式：新旧粒度靴数之差——大于 0 即证靴号跨日复用，产出「n_shoes_delta」
          ROUND(z.avg_max_round, 4)                                    AS avg_max_round,                    -- 聚合表达式：最大局号均值（新粒度），产出「avg_max_round」
          ROUND(o.avg_max_round_old, 4)                                AS avg_max_round_old,                -- 聚合表达式：最大局号均值（旧粒度），产出「avg_max_round_old」
          ROUND(o.avg_max_round_old - z.avg_max_round, 4)              AS avg_maxround_inflation,           -- 取值表达式：旧粒度较新粒度夸大之量，产出「avg_maxround_inflation」
          ROUND(z.sd_max_round, 4)                                     AS sd_max_round,                     -- 聚合表达式：最大局号样本标准差，产出「sd_max_round」
          z.min_max_round,                                                                                  -- 取列：最大局号下界
          z.ceiling_observed,                                                                               -- 取列：最大局号上界（新粒度）
          o.ceiling_old,                                                                                    -- 取列：最大局号上界（旧粒度）
          ROUND(z.p50_max_round, 2)                                    AS p50_max_round,                    -- 取近似分位数表达式：中位，产出「p50_max_round」
          ROUND(z.p90_max_round, 2)                                    AS p90_max_round,                    -- 取近似分位数表达式：九十分位，产出「p90_max_round」
          ROUND(z.p99_max_round, 2)                                    AS p99_max_round,                    -- 取近似分位数表达式：九九分位，产出「p99_max_round」
          CASE WHEN z.ceiling_observed > z.p99_max_round * 1.5                                              -- 分支判定：上界逾九九分位之 1.5 倍者
               THEN '碰撞可疑' ELSE '—' END                            AS collision_flag,                   -- 条件分支：靴号碰撞或跨日合并之指纹，产出「collision_flag」
          z.n_stub_shoes,                                                                                   -- 取列：残靴数（最大局号不超过 5）
          ROUND(z.avg_gap, 4)                                          AS avg_gap,                          -- 聚合表达式：内部缺口均值，产出「avg_gap」
          ROUND(z.avg_n_bettors, 4)                                    AS avg_n_bettors,                    -- 聚合表达式：每靴下注会员数均值，产出「avg_n_bettors」
          ROUND(z.avg_bets_per_round, 4)                               AS avg_bets_per_round,               -- 聚合表达式：每局注单数均值，产出「avg_bets_per_round」
          ROUND(0.80 * z.avg_max_round, 2)                             AS round_at_pos080,                  -- 取值表达式：本桌 shoe_pos>=0.80（LATE_DEF）对应之起始局号——跨桌可比性之直接刻度，产出「round_at_pos080」
          ROUND(z.r_density, 6)                                        AS corr_len_density,                 -- 聚合表达式：靴长与桌面密度之相关点估计，产出「corr_len_density」
          ROUND((EXP(2*(z.z_d - z.hw)) - 1) / (EXP(2*(z.z_d - z.hw)) + 1), 6) AS corr_density_lo95,         -- 取值表达式：密度相关之 95% 下界（Fisher-z 反变换），产出「corr_density_lo95」
          ROUND((EXP(2*(z.z_d + z.hw)) - 1) / (EXP(2*(z.z_d + z.hw)) + 1), 6) AS corr_density_hi95,         -- 取值表达式：密度相关之 95% 上界（Fisher-z 反变换），产出「corr_density_hi95」
          CASE                                                                                              -- 条件分支：起始分支——密度相关之判词，四态互斥
            WHEN z.z_d IS NULL THEN '○ n 不足（须 > 3）'                                                    -- 分支判定：样本量不足者照登，禁读方向
            WHEN ((EXP(2*(z.z_d - z.hw)) - 1) / (EXP(2*(z.z_d - z.hw)) + 1)) <= 0                           -- 分支判定：下界不大于零
             AND ((EXP(2*(z.z_d + z.hw)) - 1) / (EXP(2*(z.z_d + z.hw)) + 1)) >= 0                           -- 分支判定：且上界不小于零——即区间跨零
              THEN 'CI 跨 0：方向不可读'                                                                    -- 分支判定：区间跨零者方向不可读
            WHEN ((EXP(2*(z.z_d - z.hw)) - 1) / (EXP(2*(z.z_d - z.hw)) + 1)) > 0                            -- 分支判定：下界大于零
              THEN 'CI > 0：低估假说得证'                                                                   -- 分支判定：密桌靴长——分母低估坐实
            ELSE 'CI < 0：与低估假说反向'                                                                   -- 分支判定：余者密桌反而靴短——指向切牌规程异质
          END                                                          AS corr_density_verdict,             -- 条件分支：收束上方判词，产出「corr_density_verdict」
          ROUND(z.r_bettors, 6)                                        AS corr_len_bettors,                 -- 聚合表达式：靴长与下注人数之相关点估计，产出「corr_len_bettors」
          ROUND((EXP(2*(z.z_b - z.hw)) - 1) / (EXP(2*(z.z_b - z.hw)) + 1), 6) AS corr_bettors_lo95,         -- 取值表达式：人数相关之 95% 下界（Fisher-z 反变换），产出「corr_bettors_lo95」
          ROUND((EXP(2*(z.z_b + z.hw)) - 1) / (EXP(2*(z.z_b + z.hw)) + 1), 6) AS corr_bettors_hi95          -- 取值表达式：人数相关之 95% 上界（Fisher-z 反变换），产出「corr_bettors_hi95」
        FROM zc z                                                                                           -- 取数来源：取自本条自建的中间结果集 zc
        LEFT JOIN agg_old o ON o.table_id = z.table_id                                                      -- 左连接：取自本条自建的中间结果集 agg_old，连接键为 table_id（桌号）
      )
    SELECT q.*,
           -- 一·经济层
           ROUND(e.stake,4) AS stake, ROUND(e.valid,4) AS valid_bet,
           ROUND(-e.net,4) AS profit, e.n_bets, e.n_rounds,
           ROUND(e.net/NULLIF(e.stake,0),8) AS roi,
           ROUND(e.net_in/NULLIF(e.st_in,0),8) AS roi_late,
           ROUND(e.net_out/NULLIF(e.st_out,0),8) AS roi_non_late,
           ROUND((e.net-e.rebate)/NULLIF(e.stake,0),8) AS roi_ex_rebate,
           ROUND(e.net,4) AS roi_numerator, ROUND(e.stake,4) AS roi_denominator,
           CASE WHEN e.stake IS NULL THEN 'NULL_DENOM' WHEN e.stake<=0 THEN 'ZERO_DENOM'
                WHEN e.n_bets<30 THEN 'THIN_EXPOSURE' ELSE 'OK' END AS roi_denominator_status,
           ROUND(e.rebate,4) AS rebate_cost, ROUND(e.agent_cost,4)                           AS cost_complement_b,
       ROUND(e.agent_pct,4)                            AS pct_complement,
       ROUND(e.company_retain_pct,4)                   AS pct_top_bet23,
       'AG03-UNRESOLVED'                                     AS agent_formula_version,
      'ALL5_LEVELS_bet23_to_bet27'                    AS agent_level_scope,
      ROUND(e.agent_cost_lv1,4) AS agent_cost_lv1, ROUND(e.agent_cost_lv2,4) AS agent_cost_lv2,
      ROUND(e.agent_cost_lv3,4) AS agent_cost_lv3, ROUND(e.agent_cost_lv4,4) AS agent_cost_lv4,
      ROUND(e.agent_cost_lv5,4) AS agent_cost_lv5,
      ROUND(e.agent_pct_lv1,6) AS agent_pct_lv1, ROUND(e.agent_pct_lv2,6) AS agent_pct_lv2,
      ROUND(e.agent_pct_lv3,6) AS agent_pct_lv3, ROUND(e.agent_pct_lv4,6) AS agent_pct_lv4,
      ROUND(e.agent_pct_lv5,6) AS agent_pct_lv5,
      ROUND(e.retain_pct_lv1,6) AS retain_pct_lv1, ROUND(e.retain_pct_lv2,6) AS retain_pct_lv2,
      ROUND(e.retain_pct_lv3,6) AS retain_pct_lv3, ROUND(e.retain_pct_lv4,6) AS retain_pct_lv4,
      ROUND(e.retain_pct_lv5,6) AS retain_pct_lv5, ROUND(e.chain_depth_avg,4) AS chain_depth_avg,
      ROUND(e.agent_cost_chain_additive,4)            AS agent_cost_chain_additive,
      ROUND(e.agent_cost_chain_nested,4)              AS agent_cost_chain_nested,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_additive,4) AS residual_chain_additive,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_nested,4)   AS residual_chain_nested,
      'PENDING_AG03'                                  AS decision_status,
      'FALSE'                                         AS admit_to_risk_decision,
      'NOT_FOR_ENFORCEMENT'                           AS deliverable_class,
       ROUND(e.agent_cost_a_legacy,4)                  AS agent_cost_a_legacy,
       ROUND(e.agent_cost_valid_base_legacy,4)         AS agent_cost_valid_base_legacy,
           ROUND(-e.net-e.rebate,4)                        AS ngr,
       ROUND(-e.net-e.rebate-e.agent_cost,4)           AS residual_b,
       ROUND(-e.net-e.rebate-e.agent_cost_a_legacy,4)  AS residual_a,
           ROUND((-e.net-e.rebate)/NULLIF(e.stake,0),8)    AS ngr_rate,
       ROUND((-e.net-e.rebate-e.agent_cost)/NULLIF(e.stake,0),8)   AS residual_b_rate,
      -- 【HF9c · canonical accounting contract】
      --   以下 canonical 字段只增加明确 scope；不删除、不覆盖既有字段。
      --   formal_bet23_* 保持 HF9b 当前生产公式及其 NULL/0 语义；
      --   lv1~lv5 / additive / nested 则分别采用各自原始 e.* 成本字段，
      --   rate 一律从未舍入的 e.* 分子 / e.stake 计算，禁止由展示值反算。
      ROUND(e.agent_cost,4) AS agent_cost_bet23_formal_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost,4) AS net_margin_bet23_formal_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost)/NULLIF(e.stake,0),8) AS net_margin_bet23_formal_rate_canonical,
      ROUND(e.agent_cost_lv1,4) AS agent_cost_lv1_bet23_canonical,
      ROUND(e.agent_cost_lv2,4) AS agent_cost_lv2_bet24_canonical,
      ROUND(e.agent_cost_lv3,4) AS agent_cost_lv3_bet25_canonical,
      ROUND(e.agent_cost_lv4,4) AS agent_cost_lv4_bet26_canonical,
      ROUND(e.agent_cost_lv5,4) AS agent_cost_lv5_bet27_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_lv1,4) AS net_margin_lv1_bet23_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_lv1)/NULLIF(e.stake,0),8) AS net_margin_lv1_bet23_rate_canonical,
      ROUND(e.agent_cost_chain_additive,4) AS agent_cost_chain_additive_canonical,
      ROUND(e.agent_cost_chain_nested,4) AS agent_cost_chain_nested_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_additive,4) AS net_margin_chain_additive_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_nested,4) AS net_margin_chain_nested_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_chain_additive)/NULLIF(e.stake,0),8) AS net_margin_chain_additive_rate_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_chain_nested)/NULLIF(e.stake,0),8) AS net_margin_chain_nested_rate_canonical,
       ROUND((-e.net-e.rebate-e.agent_cost_a_legacy)/NULLIF(e.stake,0),8) AS residual_a_rate,
           -- 二·分布层
           ROUND(e.stake/NULLIF(e.n_bets,0),4) AS avg_stake_per_bet,
           ROUND(e.valid/NULLIF(e.n_rounds,0),4) AS avg_valid_bet_per_round,
           ROUND(-e.net/NULLIF(e.n_rounds,0),4) AS avg_profit_per_round,
           ROUND(-e.net/NULLIF(e.active_days,0),4) AS avg_profit_per_day,
           ROUND(-e.net/NULLIF(e.active_shoes,0),4) AS avg_profit_per_shoe,
           ROUND(e.stake/NULLIF(e.active_days,0),4) AS avg_stake_per_active_day,
           ROUND(e.n_rounds*1.0/NULLIF(e.active_days,0),4) AS avg_rounds_per_active_day,
           ROUND(e.st_in/NULLIF(e.nb_in,0),4) AS avg_stake_late,
           ROUND(e.st_out/NULLIF(e.nb_out,0),4) AS avg_stake_non_late,
           ROUND(e.p25,4) AS p25_stake, ROUND(e.p50,4) AS p50_stake, ROUND(e.p75,4) AS p75_stake,
           ROUND(e.p90,4) AS p90_stake, ROUND(e.p95,4) AS p95_stake, ROUND(e.p99,4) AS p99_stake,
           ROUND(e.p50_valid,4) AS p50_valid_bet, ROUND(e.p50_profit,4) AS p50_profit,
           ROUND(e.p95/NULLIF(e.p50,0),6) AS p95_over_p50,
           ROUND(e.p99/NULLIF(e.p50,0),6) AS p99_over_p50,
           ROUND((e.stake/NULLIF(e.n_bets,0))/NULLIF(e.p50,0),6) AS avg_over_p50,
           -- 三·关系层
           e.n_tables AS common_table_count, e.n_dealers AS common_dealer_count,
           e.n_ips AS common_ip_count, e.n_products AS common_product_count,
           ROUND(e.st_in/NULLIF(e.stake,0),8) AS share_late,
           -- 四·rate 层
           ROUND(-e.net/NULLIF(e.stake,0),8) AS hold_rate,
           ROUND(-e.net_in/NULLIF(e.st_in,0),8) AS hold_rate_late,
           ROUND(e.rebate/NULLIF(e.valid,0),8) AS rebate_rate_actual,
           ROUND(e.rbpct,6) AS rebate_pct_config,
           ROUND(e.valid/NULLIF(e.stake,0),6) AS turnover_multiple,
           ROUND(e.freecomm_rate,6) AS free_comm_rate,
           ROUND(e.net_in/NULLIF(e.st_in,0)-e.net_out/NULLIF(e.st_out,0),8) AS roi_delta_late,
           -- 五·动态层
           e.first_seen_d AS first_seen, e.last_seen_d AS last_seen,
           e.active_days, e.active_shoes, e.active_sessions,
           DATEDIFF(e.last_seen_d, e.first_seen_d)+1 AS span_days,
           ROUND(e.active_days*1.0/NULLIF(DATEDIFF(e.last_seen_d,e.first_seen_d)+1,0),6) AS persistence,
           ROUND((e.st_in/NULLIF(e.nb_in,0))/NULLIF(e.st_out/NULLIF(e.nb_out,0),0),6) AS ramp_late,
           ROUND((e.st_rec/NULLIF(e.nb_rec,0))/NULLIF(e.stake/NULLIF(e.n_bets,0),0),6) AS ramp_recent,
           ROUND((e.st_rec/NULLIF(e.stake,0))/0.30,6) AS stake_ramp,
           -- 六·决策层（HF9f · 详见档头【HF9f 变更说明】；本段两版逐字同一）
           NTILE(5) OVER (ORDER BY e.stake) AS vip_tier,                                                        -- 窗口取值：相对刻度 B 族，全体五等分；须连同下方血统五元组一并解读，禁作硬阈值判型
           PERCENT_RANK() OVER (ORDER BY -e.net-e.rebate-e.agent_cost)    AS economic_value,                    -- 窗口取值：HF9f·F-19 修正 —— HF9e 写作 -(-…) 双负号致方向颠倒（#075 实测 corr(economic_value, residual_b) = -1.0000）；今与 action_priority 排序键归一，值大即平台真净利高
           PERCENT_RANK() OVER (ORDER BY e.net/NULLIF(e.stake,0))         AS roi_pr_global,                     -- 窗口取值：HF9f·F-17 正名 —— 本列实为 ROI（玩家净回报率）之全体百分位，与「风险」无关；旧名 risk_value 见下一行
           PERCENT_RANK() OVER (ORDER BY e.net/NULLIF(e.stake,0))         AS risk_value,                        -- 窗口取值：兼容列，恒等于 roi_pr_global，仅为下游迁移窗保留；HF9g 起废弃，禁新引用
           PERCENT_RANK() OVER (ORDER BY e.stake)                         AS pr_stake,                          -- 窗口取值：兼容列，恒等于 pr_global，原名保留以免断链
           PERCENT_RANK() OVER (ORDER BY e.stake)                         AS pr_global,                         -- 窗口取值：HF9f·F-1 双轨之一 —— 全体口径百分位，参照总体即本件全部输出行
           CASE WHEN e.n_rounds >= 30                                                                           -- 条件分支：起始分支 —— 仅在合格子集内计算合格口径百分位
                  THEN PERCENT_RANK() OVER (PARTITION BY CASE WHEN e.n_rounds >= 30 THEN 1 ELSE 0 END ORDER BY e.stake)  -- 分支取值：以合格与否分区，故本值即 n_rounds>=30 子集内之百分位
                ELSE NULL END                                             AS pr_qualified,                      -- 条件分支：收束上方分支 —— 不合格者留 NULL（NULL＝未测，非 0），产出「pr_qualified」
           'n_rounds>=30'                                                 AS pr_qualified_population,           -- 字面取值：血统 —— 合格子集之定义
           COUNT(*) OVER ()                                               AS pr_global_population_n,            -- 窗口取值：血统 —— 全体口径之参照总体规模，渲染时现算，禁写死
           SUM(CASE WHEN e.n_rounds >= 30 THEN 1 ELSE 0 END) OVER ()      AS pr_qualified_population_n,         -- 窗口取值：血统 —— 合格子集之参照总体规模，现算，禁写死
           'PERCENT_RANK_OVER_ORDER_BY_e_stake'                           AS pr_calculation_method,             -- 字面取值：血统 —— 算法标识
           'HF9f'                                                         AS pr_calculation_version,            -- 字面取值：血统 —— 算法版本
           CASE WHEN e.n_rounds IS NULL OR e.n_rounds < 30 THEN 'THIN_ROUNDS' ELSE 'OK' END AS evidence_flag,   -- 条件分支：HF9f·F-2a 证据旗标 —— THIN_ROUNDS 者禁入执行队列，仅入观察队列
           CASE WHEN e.n_rounds IS NULL       THEN NULL                                                         -- 条件分支：起始分支 —— 未测者留 NULL（自家铁律：NULL ≠ 0）
                WHEN e.n_rounds >= 31483      THEN 'L1_POWERED'                                                 -- 分支判定：MDE 反解第一档
                WHEN e.n_rounds >= 15409      THEN 'L2_CI_1P5'                                                  -- 分支判定：MDE 反解第二档
                WHEN e.n_rounds >=  8668      THEN 'L3_CI_2P0'                                                  -- 分支判定：MDE 反解第三档
                WHEN e.n_rounds >=  3852      THEN 'L4_CI_3P0'                                                  -- 分支判定：MDE 反解第四档
                ELSE 'L5_INSUFFICIENT' END                                AS evidence_rate,                     -- 条件分支：收束上方 —— HF9f·F-3 证据分档，承 HF9e 前议之 MDE 反解五档，须于 F-4 敏感性实验后复核
           ROUND(1.96 * 0.95 / SQRT(NULLIF(CAST(e.n_rounds AS DOUBLE),0)),8) AS hold_ci_halfwidth_approx,       -- 比率表达式：HF9f·F-3 逐行现算之 95% 半宽近似；常数 0.95 为登记值，本轮 #075 实测每局 ROI 隐含 σ 于最薄层为 0.9249，二者差异待 F-4 裁定
           CASE WHEN e.stake IS NULL OR e.stake<=0 OR e.n_bets<30 OR e.n_rounds IS NULL OR e.n_rounds<30 THEN 'Z 证据不足 · 不动作'  -- 条件分支：HF9f·F-2 双条件取严 —— HF9e 仅卡 e.n_bets<30，致 n_bets>=30 而 n_rounds<30 者绕过 Z（#075 实测 18,537 名，其中 8,145 名已入 A/D 待裁）；今两条件并列取严
                WHEN PERCENT_RANK() OVER (ORDER BY -e.net-e.rebate-e.agent_cost)<=0.10                          -- 分支判定：平台真净利之最低十分位
                  THEN 'A 净亏最大十分位 · 优先复核'                                                             -- 分支取值：HF9f·F-20 正名 —— 本档 Σresidual_b 于 #075 实测 = -100,236,896，系平台净亏最大群，旧名「残值最低十分位 · 待裁」名实不符
                WHEN PERCENT_RANK() OVER (ORDER BY -e.net-e.rebate-e.agent_cost)>=0.80                          -- 分支判定：平台真净利之最高二十分位
                  THEN 'D 净利最高二十分位 · 优先留存'                                                           -- 分支取值：HF9f·F-20 正名 —— 本档 Σresidual_b 于 #075 实测 = +281,733,190，系核心利润源；与 A 档方向相反，旧版同标「待裁」属名实不符
                ELSE 'E 常规' END                                          AS action_priority                   -- 条件分支：收束上方判词，产出「action_priority」
    FROM q
    LEFT JOIN x_agg e ON CAST(e.x_key AS STRING) = CAST(q.`table_id` AS STRING)
  ) y
) z
-- ── 逐批 WHERE 阶梯（★ 口诀：上界 ＝ 下界 ＋ 100000，两数同进）──
--    本件 T_true 未测，无需先跑 T_true；以 0 / 100000 控制本批返回区间，末批由实际行数 < 100000 判定
--    WHERE z.audit_rn >        0 AND z.audit_rn <=   100000   -- 第 1 批
--    WHERE z.audit_rn >   100000 AND z.audit_rn <=   200000   -- 第 2 批
--    WHERE z.audit_rn >   200000 AND z.audit_rn <=   300000   -- 第 3 批
--    WHERE z.audit_rn >   300000 AND z.audit_rn <=   400000   -- 第 4 批
--    WHERE z.audit_rn >   400000 AND z.audit_rn <=   500000   -- 第 5 批
--    WHERE z.audit_rn >   500000 AND z.audit_rn <=   600000   -- 第 6 批
--    WHERE z.audit_rn >   600000 AND z.audit_rn <=   700000   -- 第 7 批
--    …余批类推。第 k 批：WHERE z.audit_rn > (k-1)*100000 AND z.audit_rn <= k*100000
--    某批返回 < 100000 行即为末批，其后不再取。
--
--    ⚠ 常见误写（务必避开）：只推下界而上界不动 ——
--        WHERE z.audit_rn > 100000 AND z.audit_rn <= 100000   ← 自相矛盾，恒为假，返回空集
--        WHERE z.audit_rn > 200000 AND z.audit_rn <= 100000   ← 同上，空集
--      两个数必须**同时**前进，且始终相差 100000。
--      下界 ＝ 上一批之上界；上界 ＝ 本批之上界。
WHERE z.audit_rn > 0 AND z.audit_rn <= 100000 -- ★ HF9c 本批区间
ORDER BY z.audit_rn;


-- ══════════════════════════════════════════════════════════════════════════════════════════════
--  68. R01inv_shoe_len_census.csv   [总包行 3865~3940 · 原 19 列 ＋六层约 60 列]
--     典型学：M03 尾段投注　派生旗标：late（s.x_rno*1.0/NULLIF(p.max_rno,0) >= 0.80 · 仅供 CASE 条件聚合，全包无任何 WHERE/AND/HAVING 以此过滤）　连接：全窗基线
-- ══════════════════════════════════════════════════════════════════════════════════════════════
-- ★ W-64 · D-14 警示（本件属 x_win 族 · 66 件之一 · 详见 §Z 段 D-14 全案）
--   本件以 `CROSS JOIN x_win e` 接入全局基线，x_win 无 GROUP BY ⇒ 恒 1 行 ⇒ e.* 全行同值。
--   故：economic_value / roi_pr_global / risk_value / pr_stake / pr_global 恒为 0；
--       action_priority 每一行皆为「A 净亏最大十分位 · 优先复核」（Z 分支永不触发）；
--       evidence_rate 恒为最高档；vip_tier 由常数键分档 ⇒ 无信息且非确定。
--   ⇒ 本件决策层三列 **NOT_FOR_DECISION**，裁定前不得用于排班、抽查或汇报。
-- ── ① 先跑 T_true 留档（不足 100000 者一次导全，不必分批）──
-- ── ① T_true：HF9c 不再强制预跑完整 COUNT。
--    本批实际返回行数 < 100000 即判定为末批；全批完成后以各批 n_rows / audit_rn 范围核对总量。

-- ── ② 分批取数：第 1 批。第 k 批只改末行两数为 (k-1)*100000 与 k*100000 ──
--    审计字段二（REDTEAM 2026-08-24 裁定 · 四锁）：
--      audit_rn  全局观测坐标 —— 由**与原版审计版逐字同一**之排序键所生，两版可逐行对账
--      batch_id  物理分批信息 —— 该行所属批次，由 audit_rn 算得，非引擎所赋
--    ★ 锁三：二者皆为审计字段，**不得进入任何业务指标计算**。
--    ★ 锁四：两版经 audit_rn 逐行字段核验后，方可宣布输出完全一致。

-- ── ③ 每批取回后自证四数（任一不符即停手回报，禁止放行）──
--    n_rows        = COUNT(*)      须等于 COUNT(DISTINCT audit_rn)   （批内无重复）
--    audit_rn_min  = MIN(audit_rn) 须等于 (k-1)*100000 + 1           （与上批严丝合缝）
--    audit_rn_max  = MAX(audit_rn) 须等于 min + n_rows - 1           （批内无缺口）
--    全批取毕再验：各批 audit_rn 之并集 = 1 .. T_true，无缺号、无重号。
--     ★ 首行＝平台真净亏最多者（已扣退水与代理占成）。
--
SELECT z.*,
       CAST(FLOOR((z.audit_rn - 1) / 100000) + 1 AS INT)          AS batch_id,
       'A168_HF9F_20260827_0900' AS run_id,
       '2026-08-27 09:00:00' AS snapshot_sync_time
FROM (
  SELECT y.*,
         ROW_NUMBER() OVER (ORDER BY y.`residual_b` ASC, y.`roi` DESC, y.`n_tables`, y.`n_shoes`, y.`mean_len`, y.`sd_len`, y.`p0`, y.`p01`, y.`p25`, y.`p50`, y.`p75`, y.`p90`, y.`p99`, y.`p100`, y.`n_len_ge_70`, y.`n_len_le_5`, y.`pct_with_gap`, y.`avg_gap`, y.`corr_cross_table`, y.`round_at_080_shortest`, y.`round_at_080_longest`) AS audit_rn
  FROM (
    WITH
      x_ranked AS (
    SELECT b.bet01, b.bet03, b.bet04, b.bet05, b.bet09, b.bet11, b.bet13,
           b.bet15, b.bet16, b.bet17, b.bet18, b.bet19, b.bet20, b.bet21,
           b.bet22, b.bet23, b.bet24, b.bet25, b.bet26, b.bet27, b.bet38, b.bet39, b.category, b.commission,
           b.dt, b.eid, b.ip, b.validbet, b.updatetime, b.sync_time,
           ROW_NUMBER() OVER (
             PARTITION BY b.bet01
             ORDER BY b.updatetime DESC, b.sync_time DESC, b.dt DESC)      AS x_rn
    FROM ods_mariadb_2b.ods_a168_bet02 b
    WHERE b.dt >= '2026-03-21' AND b.dt < '2026-08-07'
      AND b.bet02 = '101'
      AND b.sync_time <= '2026-08-27 09:00:00'
  ),
    x_testagent AS (
    SELECT age001 AS agent_id FROM ods_mariadb_2b.ods_a168_agent WHERE age022 = '1'
  ),
    x_bs0 AS (
    SELECT b.bet05 AS x_member, b.eid AS x_dealer, b.bet39 AS x_table,
           b.bet03 AS x_shoe, b.ip AS x_ip, b.bet09 AS x_product, b.dt AS x_date,
           CONCAT_WS('|', b.bet03, b.bet04, b.bet39)                      AS x_round,
           CONCAT_WS('|', b.bet39, b.bet03)                               AS x_tblshoe,
           CAST(NULLIF(TRIM(b.bet04),'') AS INT)                          AS x_rno,
           CASE WHEN b.dt >= '2026-07-08' THEN 1 ELSE 0 END               AS x_rec,
           CASE WHEN TRIM(b.commission)='1' THEN 1 ELSE 0 END             AS x_freecomm,
           CAST(NULLIF(TRIM(b.bet13),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_stake,
           CAST(NULLIF(TRIM(b.validbet),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_valid,
           CAST(NULLIF(TRIM(b.bet16),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_rebate,
           CAST(NULLIF(TRIM(b.bet17),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_net,
           CAST(NULLIF(TRIM(b.bet15),'') AS DECIMAL(20,6))                AS x_rbpct,
           COALESCE(CAST(NULLIF(TRIM(b.bet23),'') AS DECIMAL(20,6)),0)   AS x_agpct,
          NULLIF(CAST(NULLIF(TRIM(b.bet23),'') AS DECIMAL(20,6)),0)     AS x_rate1,
          NULLIF(CAST(NULLIF(TRIM(b.bet24),'') AS DECIMAL(20,6)),0)     AS x_rate2,
          NULLIF(CAST(NULLIF(TRIM(b.bet25),'') AS DECIMAL(20,6)),0)     AS x_rate3,
          NULLIF(CAST(NULLIF(TRIM(b.bet26),'') AS DECIMAL(20,6)),0)     AS x_rate4,
          NULLIF(CAST(NULLIF(TRIM(b.bet27),'') AS DECIMAL(20,6)),0)     AS x_rate5,
          (CASE WHEN NULLIF(CAST(NULLIF(TRIM(b.bet22),'') AS BIGINT),0) IS NOT NULL THEN 5
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet21),'') AS BIGINT),0) IS NOT NULL THEN 4
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet20),'') AS BIGINT),0) IS NOT NULL THEN 3
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet19),'') AS BIGINT),0) IS NOT NULL THEN 2
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet18),'') AS BIGINT),0) IS NOT NULL THEN 1
                ELSE 0 END)                                             AS x_chain_depth,
           CASE WHEN COALESCE(t1.agent_id,t2.agent_id,t3.agent_id,
                              t4.agent_id,t5.agent_id) IS NOT NULL
                THEN 1 ELSE 0 END                                        AS f_testline
    FROM x_ranked b
    LEFT JOIN x_testagent t1 ON t1.agent_id = b.bet18
    LEFT JOIN x_testagent t2 ON t2.agent_id = b.bet19
    LEFT JOIN x_testagent t3 ON t3.agent_id = b.bet20
    LEFT JOIN x_testagent t4 ON t4.agent_id = b.bet21
    LEFT JOIN x_testagent t5 ON t5.agent_id = b.bet22
    WHERE b.x_rn = 1
      AND b.category='1' AND UPPER(TRIM(b.bet38))='N'
      AND CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8)) > 0
  ),
  x_mk AS (
    SELECT s.*,
           CASE WHEN s.f_testline = 0 THEN 1 ELSE 0 END                 AS is_clean
    FROM x_bs0 s
  ),
  x_sp AS (SELECT x_table, x_shoe, MAX(x_rno) AS max_rno FROM x_mk GROUP BY x_table, x_shoe),
  x_agg AS (
    SELECT s.x_member                                                        AS x_key,
           COUNT(*) AS n_bets, COUNT(DISTINCT s.x_round) AS n_rounds,
           COUNT(DISTINCT s.x_date) AS active_days, COUNT(DISTINCT s.x_tblshoe) AS active_shoes,
           COUNT(DISTINCT CONCAT_WS('|', s.x_date, s.x_table)) AS active_sessions,
           COUNT(DISTINCT s.x_table) AS n_tables, COUNT(DISTINCT s.x_dealer) AS n_dealers,
           COUNT(DISTINCT s.x_ip) AS n_ips, COUNT(DISTINCT s.x_product) AS n_products,
           MIN(s.x_date) AS first_seen_d, MAX(s.x_date) AS last_seen_d,
           SUM(s.x_stake) AS stake, SUM(s.x_valid) AS valid, SUM(s.x_rebate) AS rebate,
           SUM(s.x_net) AS net, SUM(-s.x_net *(100.0-s.x_agpct)/100.0) AS agent_cost,
           AVG(100.0-s.x_agpct)                   AS agent_pct,
           AVG(s.x_agpct)                         AS company_retain_pct,
           SUM(-s.x_net *s.x_agpct/100.0)         AS agent_cost_a_legacy,
           SUM(s.x_valid*s.x_agpct/100.0)         AS agent_cost_valid_base_legacy,
          AVG(COALESCE(s.x_rate1,100)) AS retain_pct_lv1, AVG(COALESCE(s.x_rate2,100)) AS retain_pct_lv2,
          AVG(COALESCE(s.x_rate3,100)) AS retain_pct_lv3, AVG(COALESCE(s.x_rate4,100)) AS retain_pct_lv4,
          AVG(COALESCE(s.x_rate5,100)) AS retain_pct_lv5, AVG(s.x_chain_depth) AS chain_depth_avg,
          AVG(COALESCE(100.0-s.x_rate1,0)) AS agent_pct_lv1, AVG(COALESCE(100.0-s.x_rate2,0)) AS agent_pct_lv2,
          AVG(COALESCE(100.0-s.x_rate3,0)) AS agent_pct_lv3, AVG(COALESCE(100.0-s.x_rate4,0)) AS agent_pct_lv4,
          AVG(COALESCE(100.0-s.x_rate5,0)) AS agent_pct_lv5,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate1,0)/100.0)                        AS agent_cost_lv1,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate2,0)/100.0)                        AS agent_cost_lv2,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate3,0)/100.0)                        AS agent_cost_lv3,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate4,0)/100.0)                        AS agent_cost_lv4,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate5,0)/100.0)                        AS agent_cost_lv5,
          SUM(-s.x_net*(COALESCE(100.0-s.x_rate1,0)+COALESCE(100.0-s.x_rate2,0)
                       +COALESCE(100.0-s.x_rate3,0)+COALESCE(100.0-s.x_rate4,0)
                       +COALESCE(100.0-s.x_rate5,0))/100.0)                   AS agent_cost_chain_additive,
          SUM(-s.x_net*(1.0 - CAST(COALESCE(s.x_rate1,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate2,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate3,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate4,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate5,100) AS DOUBLE)/100.0))
                                                                       AS agent_cost_chain_nested,
           AVG(s.x_rbpct) AS rbpct, AVG(s.x_freecomm*1.0) AS freecomm_rate,
           PERCENTILE_APPROX(s.x_stake,0.25) AS p25, PERCENTILE_APPROX(s.x_stake,0.50) AS p50,
           PERCENTILE_APPROX(s.x_stake,0.75) AS p75, PERCENTILE_APPROX(s.x_stake,0.90) AS p90,
           PERCENTILE_APPROX(s.x_stake,0.95) AS p95, PERCENTILE_APPROX(s.x_stake,0.99) AS p99,
           PERCENTILE_APPROX(s.x_valid,0.50) AS p50_valid,
           PERCENTILE_APPROX(s.x_net,0.50)   AS p50_profit,
           SUM(CASE WHEN s.x_rno*1.0/NULLIF(p.max_rno,0) >= 0.80 THEN s.x_stake ELSE 0 END) AS st_in,
           SUM(CASE WHEN s.x_rno*1.0/NULLIF(p.max_rno,0) >= 0.80 THEN 1 ELSE 0 END)         AS nb_in,
           SUM(CASE WHEN s.x_rno*1.0/NULLIF(p.max_rno,0) >= 0.80 THEN s.x_net ELSE 0 END)   AS net_in,
           SUM(CASE WHEN NOT (s.x_rno*1.0/NULLIF(p.max_rno,0) >= 0.80) THEN s.x_stake ELSE 0 END) AS st_out,
           SUM(CASE WHEN NOT (s.x_rno*1.0/NULLIF(p.max_rno,0) >= 0.80) THEN 1 ELSE 0 END)         AS nb_out,
           SUM(CASE WHEN NOT (s.x_rno*1.0/NULLIF(p.max_rno,0) >= 0.80) THEN s.x_net ELSE 0 END)   AS net_out,
           SUM(CASE WHEN s.x_rec=1 THEN s.x_stake ELSE 0 END) AS st_rec,
           SUM(CASE WHEN s.x_rec=1 THEN 1 ELSE 0 END)         AS nb_rec
    FROM x_mk s
    JOIN x_sp p ON p.x_table = s.x_table AND p.x_shoe = s.x_shoe
    WHERE s.is_clean = 1
      AND s.x_member IS NOT NULL AND TRIM(CAST(s.x_member AS STRING)) <> ''
    GROUP BY s.x_member
  ),
  x_win AS (
    SELECT            COUNT(*) AS n_bets, COUNT(DISTINCT s.x_round) AS n_rounds,
           COUNT(DISTINCT s.x_date) AS active_days, COUNT(DISTINCT s.x_tblshoe) AS active_shoes,
           COUNT(DISTINCT CONCAT_WS('|', s.x_date, s.x_table)) AS active_sessions,
           COUNT(DISTINCT s.x_table) AS n_tables, COUNT(DISTINCT s.x_dealer) AS n_dealers,
           COUNT(DISTINCT s.x_ip) AS n_ips, COUNT(DISTINCT s.x_product) AS n_products,
           MIN(s.x_date) AS first_seen_d, MAX(s.x_date) AS last_seen_d,
           SUM(s.x_stake) AS stake, SUM(s.x_valid) AS valid, SUM(s.x_rebate) AS rebate,
           SUM(s.x_net) AS net, SUM(-s.x_net *(100.0-s.x_agpct)/100.0) AS agent_cost,
           AVG(100.0-s.x_agpct)                   AS agent_pct,
           AVG(s.x_agpct)                         AS company_retain_pct,
           SUM(-s.x_net *s.x_agpct/100.0)         AS agent_cost_a_legacy,
           SUM(s.x_valid*s.x_agpct/100.0)         AS agent_cost_valid_base_legacy,
          AVG(COALESCE(s.x_rate1,100)) AS retain_pct_lv1, AVG(COALESCE(s.x_rate2,100)) AS retain_pct_lv2,
          AVG(COALESCE(s.x_rate3,100)) AS retain_pct_lv3, AVG(COALESCE(s.x_rate4,100)) AS retain_pct_lv4,
          AVG(COALESCE(s.x_rate5,100)) AS retain_pct_lv5, AVG(s.x_chain_depth) AS chain_depth_avg,
          AVG(COALESCE(100.0-s.x_rate1,0)) AS agent_pct_lv1, AVG(COALESCE(100.0-s.x_rate2,0)) AS agent_pct_lv2,
          AVG(COALESCE(100.0-s.x_rate3,0)) AS agent_pct_lv3, AVG(COALESCE(100.0-s.x_rate4,0)) AS agent_pct_lv4,
          AVG(COALESCE(100.0-s.x_rate5,0)) AS agent_pct_lv5,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate1,0)/100.0)                        AS agent_cost_lv1,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate2,0)/100.0)                        AS agent_cost_lv2,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate3,0)/100.0)                        AS agent_cost_lv3,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate4,0)/100.0)                        AS agent_cost_lv4,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate5,0)/100.0)                        AS agent_cost_lv5,
          SUM(-s.x_net*(COALESCE(100.0-s.x_rate1,0)+COALESCE(100.0-s.x_rate2,0)
                       +COALESCE(100.0-s.x_rate3,0)+COALESCE(100.0-s.x_rate4,0)
                       +COALESCE(100.0-s.x_rate5,0))/100.0)                   AS agent_cost_chain_additive,
          SUM(-s.x_net*(1.0 - CAST(COALESCE(s.x_rate1,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate2,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate3,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate4,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate5,100) AS DOUBLE)/100.0))
                                                                       AS agent_cost_chain_nested,
           AVG(s.x_rbpct) AS rbpct, AVG(s.x_freecomm*1.0) AS freecomm_rate,
           PERCENTILE_APPROX(s.x_stake,0.25) AS p25, PERCENTILE_APPROX(s.x_stake,0.50) AS p50,
           PERCENTILE_APPROX(s.x_stake,0.75) AS p75, PERCENTILE_APPROX(s.x_stake,0.90) AS p90,
           PERCENTILE_APPROX(s.x_stake,0.95) AS p95, PERCENTILE_APPROX(s.x_stake,0.99) AS p99,
           PERCENTILE_APPROX(s.x_valid,0.50) AS p50_valid,
           PERCENTILE_APPROX(s.x_net,0.50)   AS p50_profit,
           SUM(CASE WHEN s.x_rno*1.0/NULLIF(p.max_rno,0) >= 0.80 THEN s.x_stake ELSE 0 END) AS st_in,
           SUM(CASE WHEN s.x_rno*1.0/NULLIF(p.max_rno,0) >= 0.80 THEN 1 ELSE 0 END)         AS nb_in,
           SUM(CASE WHEN s.x_rno*1.0/NULLIF(p.max_rno,0) >= 0.80 THEN s.x_net ELSE 0 END)   AS net_in,
           SUM(CASE WHEN NOT (s.x_rno*1.0/NULLIF(p.max_rno,0) >= 0.80) THEN s.x_stake ELSE 0 END) AS st_out,
           SUM(CASE WHEN NOT (s.x_rno*1.0/NULLIF(p.max_rno,0) >= 0.80) THEN 1 ELSE 0 END)         AS nb_out,
           SUM(CASE WHEN NOT (s.x_rno*1.0/NULLIF(p.max_rno,0) >= 0.80) THEN s.x_net ELSE 0 END)   AS net_out,
           SUM(CASE WHEN s.x_rec=1 THEN s.x_stake ELSE 0 END) AS st_rec,
           SUM(CASE WHEN s.x_rec=1 THEN 1 ELSE 0 END)         AS nb_rec
    FROM x_mk s
    JOIN x_sp p ON p.x_table = s.x_table AND p.x_shoe = s.x_shoe
    WHERE s.is_clean = 1
      AND s.x_member IS NOT NULL AND TRIM(CAST(s.x_member AS STRING)) <> ''
  ),
      q AS (
        WITH test_agents AS (                                                                               -- 公共表表达式：开启中间结果集 test_agents，其后各行为其定义体（§R01-inv）
          SELECT age001 AS agent_id                                                                         -- 取列：产出「agent_id」
          FROM ods_mariadb_2b.ods_a168_agent                                                                -- 取数来源：取自代理主档（五级代理线归属来源）
          WHERE age022 = '1'                                  -- 铁律④b：公司测试线
        ),                                                                                                  -- 续行：收束上方的子查询或函数括号（§R01-inv）
        ranked AS (                                            -- 需求 §3.2：同单号保留最新版本
          SELECT b.bet01, b.dt, b.bet03, b.bet04, b.bet05, b.bet11,                                         -- 取列：起始取列子句，本行先列 b.bet01, b.dt, b.bet03, b.bet04, b.bet05, b.bet11，涉 dt（营业日）、bet03（靴号）、bet04（局内序号）
                 b.bet18, b.bet19, b.bet20, b.bet21, b.bet22,                                               -- 续行：接续上一取列子句，续列 b.bet18~b.bet22，涉五级代理线（测试线剔除之连接键）
                 b.bet38, b.bet39, b.category,                                                              -- 续行：接续上一取列子句，续列 b.bet38, b.bet39, b.category，涉 bet38（重對）、bet39（桌号）、category（注单类别）
                 ROW_NUMBER() OVER (                                                                        -- 行号窗口表达式：以行号窗口取每组头部或去重，免出重复行
                   PARTITION BY b.bet01                                                                     -- 窗口分区：按 b.bet01 分组开窗，组内各自编号或排名
                   ORDER BY b.updatetime DESC, b.sync_time DESC, b.dt DESC) AS rn                           -- 排序：按 b.updatetime（降序）, b.sync_time（降序）, b.dt（降序）) AS rn 排列；导出必带排序，否则分页无稳定序（曾致 36.49% 重复行）
          FROM ods_mariadb_2b.ods_a168_bet02 b                 -- ★ 表名开关
          WHERE b.dt >= '2026-03-21' AND b.dt < '2026-08-07'                                                -- 过滤条件：限定 b.dt不少于 '2026-03-21'、b.dt小于 '2026-08-07'，涉 dt（营业日）
            AND b.bet02 = '101'
      AND b.sync_time <= '2026-08-27 09:00:00'                                                                             -- 并列条件：限定 b.bet02等于 '101'，涉 bet02（游戏类别）
        ),                                                                                                  -- 续行：收束上方的子查询或函数括号（§R01-inv）
        base AS (                                                                                           -- 公共表表达式：开启中间结果集 base，其后各行为其定义体（§R01-inv）
          SELECT r.dt                                          AS dt,                                       -- 取列：起始取列子句，本行先取「dt」，涉 dt（营业日）——本族较 §R01 之唯一增列
                 CAST(NULLIF(TRIM(r.bet05),'') AS BIGINT)      AS member_id,                                -- 取值表达式：先去空白、空串归 NULL，再显式转型——本库字段多为 varchar，不转型即比较失真，产出「member_id」
                 COALESCE(NULLIF(TRIM(r.bet03),''), '(空)')    AS shoe_id,                                  -- 取值表达式：空串归哨兵「(空)」以免与真靴号混算，涉 bet03（靴号），产出「shoe_id」
                 COALESCE(NULLIF(TRIM(r.bet39),''), '(空)')    AS table_id,                                 -- 取值表达式：空串归哨兵「(空)」以免与真桌号混算，涉 bet39（桌号），产出「table_id」
                 CAST(NULLIF(TRIM(r.bet04),'') AS INT)         AS round_no                                  -- 取值表达式：先去空白、空串归 NULL，再显式转型——本库字段多为 varchar，不转型即比较失真，产出「round_no」
          FROM ranked r                                                                                     -- 取数来源：取自本条自建的中间结果集 ranked
          LEFT JOIN test_agents t1 ON t1.agent_id = r.bet18                                                 -- 左连接：取自本条自建的中间结果集 test_agents，连接键为 bet18（一级代理线）
          LEFT JOIN test_agents t2 ON t2.agent_id = r.bet19                                                 -- 左连接：取自本条自建的中间结果集 test_agents，连接键为 bet19（二级代理线）
          LEFT JOIN test_agents t3 ON t3.agent_id = r.bet20                                                 -- 左连接：取自本条自建的中间结果集 test_agents，连接键为 bet20（三级代理线）
          LEFT JOIN test_agents t4 ON t4.agent_id = r.bet21                                                 -- 左连接：取自本条自建的中间结果集 test_agents，连接键为 bet21（四级代理线）
          LEFT JOIN test_agents t5 ON t5.agent_id = r.bet22                                                 -- 左连接：取自本条自建的中间结果集 test_agents，连接键为 bet22（五级代理线）
          WHERE r.rn = 1                                                                                    -- 过滤条件：限定 r.rn等于 1
            AND r.category = '1'                                                                            -- 并列条件：限定 r.category等于 '1'
            AND UPPER(TRIM(r.bet38)) = 'N'                                                                  -- 并列条件：限定 UPPER(TRIM(r.bet38))等于 'N'，涉 bet38（重對）
            AND CAST(NULLIF(TRIM(r.bet05),'') AS BIGINT) > 0                                                -- 并列条件：限定 CAST(NULLIF(TRIM(r.bet05),'') AS BIGINT)大于 0，涉 bet05（会员号）
            AND CAST(NULLIF(TRIM(r.bet11),'') AS DECIMAL(20,8)) > 0                                         -- 并列条件：限定 CAST(NULLIF(TRIM(r.bet11),'') AS DECIMAL(20,8))大于 0，涉 bet11（汇率）
            AND CAST(NULLIF(TRIM(r.bet04),'') AS INT) > 0                                                   -- 并列条件：限定 CAST(NULLIF(TRIM(r.bet04),'') AS INT)大于 0，涉 bet04（局内序号）
            AND COALESCE(t1.agent_id,t2.agent_id,t3.agent_id,t4.agent_id,t5.agent_id) IS NULL               -- 并列条件：限定该值为空——本包以左连接加空值判定替代 EXISTS，因 StarRocks 不支持 EXISTS 配多列 IN
        ),                                                                                                  -- 续行：收束上方的子查询或函数括号（§R01-inv）
        shoe_new AS (          /* ★ 新粒度（(dt, table_id, shoe_id)）：所算 max_round = MAX(round_no) 为最大局号，非局数；不沿用 shoe_len 之名，见卷首命名警示横幅。★ */
          SELECT dt, table_id, shoe_id,                                                                     -- 取列：起始取列子句，本行先列 dt, table_id, shoe_id，涉 dt（营业日）、bet39（桌号）、bet03（靴号）
                 MAX(round_no)                                        AS max_round,                         -- 取最大局号（≠COUNT 局数），产出「max_round」
                 COUNT(DISTINCT round_no)                             AS rounds_with_bet,                   -- 计数表达式：局内序号的去重个数——有注局数，产出「rounds_with_bet」
                 MAX(round_no) - COUNT(DISTINCT round_no)             AS gap,                               -- 取值表达式：最大局号减有注局数——内部缺口，非尾部截断，产出「gap」
                 COUNT(DISTINCT member_id)                            AS n_bettors,                         -- 计数表达式：会员号的去重个数，产出「n_bettors」
                 COUNT(*) * 1.0 / NULLIF(COUNT(DISTINCT round_no), 0) AS bets_per_round                     -- 除法计算：每局注单数，分母以 NULLIF 守门防零除，产出「bets_per_round」
          FROM base                                                                                         -- 取数来源：取自本条自建的中间结果集 base
          GROUP BY dt, table_id, shoe_id                                                                    -- 分组：按 dt, table_id, shoe_id 汇总——新粒度
        ),                                                                                                  -- 续行：收束上方的子查询或函数括号（§R01-inv）
        by_table AS (               /* 跨桌相关之单位＝桌（非靴）：与 §R01-chk 之桌内相关分属两层，禁互相援引。 */
          SELECT table_id,                                                                                  -- 取列：起始取列子句，本行先取「table_id」，涉 bet39（桌号）
                 COUNT(*)            AS n_shoes,                                                            -- 计数表达式：本桌靴数，产出「n_shoes」
                 AVG(max_round)      AS avg_len,                                                            -- 聚合表达式：本桌最大局号均值，产出「avg_len」
                 AVG(bets_per_round) AS avg_density                                                         -- 聚合表达式：本桌每局注单数均值，产出「avg_density」
          FROM shoe_new                                                                                     -- 取数来源：取自本条自建的中间结果集 shoe_new
          GROUP BY table_id                                                                                 -- 分组：按桌号汇总
        )                                                                                                   -- 续行：收束上方的子查询或函数括号（§R01-inv）
        SELECT                                                                                              -- 取列：起始取列子句
          (SELECT COUNT(*) FROM by_table)                                   AS n_tables,                         -- 计数表达式：全域桌数——供核对 §R01-chk 结果行数是否被显示上限截断，产出「n_tables」
          COUNT(*)                                                     AS n_shoes,                          -- 计数表达式：全域靴数（新粒度），产出「n_shoes」
          ROUND(AVG(max_round), 4)                                     AS mean_len,                         -- 聚合表达式：最大局号均值，产出「mean_len」
          ROUND(STDDEV_SAMP(max_round), 4)                             AS sd_len,                           -- 聚合表达式：最大局号样本标准差，产出「sd_len」
          MIN(max_round)                                               AS p0,                               -- 聚合表达式：最小值，产出「p0」
          ROUND(PERCENTILE_APPROX(max_round, 0.01), 2)                 AS p01,                              -- 取近似分位数表达式：一分位，产出「p01」
          ROUND(PERCENTILE_APPROX(max_round, 0.25), 2)                 AS p25,                              -- 取近似分位数表达式：二五分位，产出「p25」
          ROUND(PERCENTILE_APPROX(max_round, 0.50), 2)                 AS p50,                              -- 取近似分位数表达式：中位，产出「p50」
          ROUND(PERCENTILE_APPROX(max_round, 0.75), 2)                 AS p75,                              -- 取近似分位数表达式：七五分位，产出「p75」
          ROUND(PERCENTILE_APPROX(max_round, 0.90), 2)                 AS p90,                              -- 取近似分位数表达式：九十分位，产出「p90」
          ROUND(PERCENTILE_APPROX(max_round, 0.99), 2)                 AS p99,                              -- 取近似分位数表达式：九九分位，产出「p99」
          MAX(max_round)                                               AS p100,                             -- 聚合表达式：最大值，产出「p100」
          SUM(CASE WHEN max_round >= 70 THEN 1 ELSE 0 END)             AS n_len_ge_70,                      -- 条件分支：最大局号不少于 70 之靴数——深切规程之证据，产出「n_len_ge_70」
          SUM(CASE WHEN max_round <= 5  THEN 1 ELSE 0 END)             AS n_len_le_5,                       -- 条件分支：最大局号不超过 5 之残靴数，产出「n_len_le_5」
          ROUND(SUM(CASE WHEN gap > 0 THEN 1 ELSE 0 END) * 100.0                                            -- 条件分支：有内部缺口之靴数
                / NULLIF(COUNT(*), 0), 4)                              AS pct_with_gap,                     -- 除法计算：分母以 NULLIF 守门防零除，产出「pct_with_gap」
          ROUND(AVG(gap), 4)                                           AS avg_gap,                          -- 聚合表达式：内部缺口均值，产出「avg_gap」
          ROUND((SELECT CORR(avg_density, avg_len) FROM by_table), 6)       AS corr_cross_table,                 -- 聚合表达式：跨桌相关（单位＝桌）——为负即密桌反而靴短，产出「corr_cross_table」
          ROUND(0.80 * (SELECT MIN(avg_len) FROM by_table), 2)              AS round_at_080_shortest,            -- 取值表达式：最短桌之 shoe_pos>=0.80 起始局号，产出「round_at_080_shortest」
          ROUND(0.80 * (SELECT MAX(avg_len) FROM by_table), 2)              AS round_at_080_longest              -- 取值表达式：最长桌之 shoe_pos>=0.80 起始局号——与上一列之差即跨桌规程异质之刻度，产出「round_at_080_longest」
        FROM shoe_new                                                                                      -- 取数来源：取自本条自建的中间结果集 shoe_new
      )
    SELECT q.*,
           -- 一·经济层
           ROUND(e.stake,4) AS stake, ROUND(e.valid,4) AS valid_bet,
           ROUND(-e.net,4) AS profit, e.n_bets, e.n_rounds,
           ROUND(e.net/NULLIF(e.stake,0),8) AS roi,
           ROUND(e.net_in/NULLIF(e.st_in,0),8) AS roi_late,
           ROUND(e.net_out/NULLIF(e.st_out,0),8) AS roi_non_late,
           ROUND((e.net-e.rebate)/NULLIF(e.stake,0),8) AS roi_ex_rebate,
           ROUND(e.net,4) AS roi_numerator, ROUND(e.stake,4) AS roi_denominator,
           CASE WHEN e.stake IS NULL THEN 'NULL_DENOM' WHEN e.stake<=0 THEN 'ZERO_DENOM'
                WHEN e.n_bets<30 THEN 'THIN_EXPOSURE' ELSE 'OK' END AS roi_denominator_status,
           ROUND(e.rebate,4) AS rebate_cost, ROUND(e.agent_cost,4)                           AS cost_complement_b,
       ROUND(e.agent_pct,4)                            AS pct_complement,
       ROUND(e.company_retain_pct,4)                   AS pct_top_bet23,
       'AG03-UNRESOLVED'                                     AS agent_formula_version,
      'ALL5_LEVELS_bet23_to_bet27'                    AS agent_level_scope,
      ROUND(e.agent_cost_lv1,4) AS agent_cost_lv1, ROUND(e.agent_cost_lv2,4) AS agent_cost_lv2,
      ROUND(e.agent_cost_lv3,4) AS agent_cost_lv3, ROUND(e.agent_cost_lv4,4) AS agent_cost_lv4,
      ROUND(e.agent_cost_lv5,4) AS agent_cost_lv5,
      ROUND(e.agent_pct_lv1,6) AS agent_pct_lv1, ROUND(e.agent_pct_lv2,6) AS agent_pct_lv2,
      ROUND(e.agent_pct_lv3,6) AS agent_pct_lv3, ROUND(e.agent_pct_lv4,6) AS agent_pct_lv4,
      ROUND(e.agent_pct_lv5,6) AS agent_pct_lv5,
      ROUND(e.retain_pct_lv1,6) AS retain_pct_lv1, ROUND(e.retain_pct_lv2,6) AS retain_pct_lv2,
      ROUND(e.retain_pct_lv3,6) AS retain_pct_lv3, ROUND(e.retain_pct_lv4,6) AS retain_pct_lv4,
      ROUND(e.retain_pct_lv5,6) AS retain_pct_lv5, ROUND(e.chain_depth_avg,4) AS chain_depth_avg,
      ROUND(e.agent_cost_chain_additive,4)            AS agent_cost_chain_additive,
      ROUND(e.agent_cost_chain_nested,4)              AS agent_cost_chain_nested,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_additive,4) AS residual_chain_additive,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_nested,4)   AS residual_chain_nested,
      'PENDING_AG03'                                  AS decision_status,
      'FALSE'                                         AS admit_to_risk_decision,
      'NOT_FOR_ENFORCEMENT'                           AS deliverable_class,
       ROUND(e.agent_cost_a_legacy,4)                  AS agent_cost_a_legacy,
       ROUND(e.agent_cost_valid_base_legacy,4)         AS agent_cost_valid_base_legacy,
           ROUND(-e.net-e.rebate,4)                        AS ngr,
       ROUND(-e.net-e.rebate-e.agent_cost,4)           AS residual_b,
       ROUND(-e.net-e.rebate-e.agent_cost_a_legacy,4)  AS residual_a,
           ROUND((-e.net-e.rebate)/NULLIF(e.stake,0),8)    AS ngr_rate,
       ROUND((-e.net-e.rebate-e.agent_cost)/NULLIF(e.stake,0),8)   AS residual_b_rate,
      -- 【HF9c · canonical accounting contract】
      --   以下 canonical 字段只增加明确 scope；不删除、不覆盖既有字段。
      --   formal_bet23_* 保持 HF9b 当前生产公式及其 NULL/0 语义；
      --   lv1~lv5 / additive / nested 则分别采用各自原始 e.* 成本字段，
      --   rate 一律从未舍入的 e.* 分子 / e.stake 计算，禁止由展示值反算。
      ROUND(e.agent_cost,4) AS agent_cost_bet23_formal_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost,4) AS net_margin_bet23_formal_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost)/NULLIF(e.stake,0),8) AS net_margin_bet23_formal_rate_canonical,
      ROUND(e.agent_cost_lv1,4) AS agent_cost_lv1_bet23_canonical,
      ROUND(e.agent_cost_lv2,4) AS agent_cost_lv2_bet24_canonical,
      ROUND(e.agent_cost_lv3,4) AS agent_cost_lv3_bet25_canonical,
      ROUND(e.agent_cost_lv4,4) AS agent_cost_lv4_bet26_canonical,
      ROUND(e.agent_cost_lv5,4) AS agent_cost_lv5_bet27_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_lv1,4) AS net_margin_lv1_bet23_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_lv1)/NULLIF(e.stake,0),8) AS net_margin_lv1_bet23_rate_canonical,
      ROUND(e.agent_cost_chain_additive,4) AS agent_cost_chain_additive_canonical,
      ROUND(e.agent_cost_chain_nested,4) AS agent_cost_chain_nested_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_additive,4) AS net_margin_chain_additive_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_nested,4) AS net_margin_chain_nested_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_chain_additive)/NULLIF(e.stake,0),8) AS net_margin_chain_additive_rate_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_chain_nested)/NULLIF(e.stake,0),8) AS net_margin_chain_nested_rate_canonical,
       ROUND((-e.net-e.rebate-e.agent_cost_a_legacy)/NULLIF(e.stake,0),8) AS residual_a_rate,
           -- 二·分布层
           ROUND(e.stake/NULLIF(e.n_bets,0),4) AS avg_stake_per_bet,
           ROUND(e.valid/NULLIF(e.n_rounds,0),4) AS avg_valid_bet_per_round,
           ROUND(-e.net/NULLIF(e.n_rounds,0),4) AS avg_profit_per_round,
           ROUND(-e.net/NULLIF(e.active_days,0),4) AS avg_profit_per_day,
           ROUND(-e.net/NULLIF(e.active_shoes,0),4) AS avg_profit_per_shoe,
           ROUND(e.stake/NULLIF(e.active_days,0),4) AS avg_stake_per_active_day,
           ROUND(e.n_rounds*1.0/NULLIF(e.active_days,0),4) AS avg_rounds_per_active_day,
           ROUND(e.st_in/NULLIF(e.nb_in,0),4) AS avg_stake_late,
           ROUND(e.st_out/NULLIF(e.nb_out,0),4) AS avg_stake_non_late,
           ROUND(e.p25,4) AS p25_stake, ROUND(e.p50,4) AS p50_stake, ROUND(e.p75,4) AS p75_stake,
           ROUND(e.p90,4) AS p90_stake, ROUND(e.p95,4) AS p95_stake, ROUND(e.p99,4) AS p99_stake,
           ROUND(e.p50_valid,4) AS p50_valid_bet, ROUND(e.p50_profit,4) AS p50_profit,
           ROUND(e.p95/NULLIF(e.p50,0),6) AS p95_over_p50,
           ROUND(e.p99/NULLIF(e.p50,0),6) AS p99_over_p50,
           ROUND((e.stake/NULLIF(e.n_bets,0))/NULLIF(e.p50,0),6) AS avg_over_p50,
           -- 三·关系层
           e.n_tables AS common_table_count, e.n_dealers AS common_dealer_count,
           e.n_ips AS common_ip_count, e.n_products AS common_product_count,
           ROUND(e.st_in/NULLIF(e.stake,0),8) AS share_late,
           -- 四·rate 层
           ROUND(-e.net/NULLIF(e.stake,0),8) AS hold_rate,
           ROUND(-e.net_in/NULLIF(e.st_in,0),8) AS hold_rate_late,
           ROUND(e.rebate/NULLIF(e.valid,0),8) AS rebate_rate_actual,
           ROUND(e.rbpct,6) AS rebate_pct_config,
           ROUND(e.valid/NULLIF(e.stake,0),6) AS turnover_multiple,
           ROUND(e.freecomm_rate,6) AS free_comm_rate,
           ROUND(e.net_in/NULLIF(e.st_in,0)-e.net_out/NULLIF(e.st_out,0),8) AS roi_delta_late,
           -- 五·动态层
           e.first_seen_d AS first_seen, e.last_seen_d AS last_seen,
           e.active_days, e.active_shoes, e.active_sessions,
           DATEDIFF(e.last_seen_d, e.first_seen_d)+1 AS span_days,
           ROUND(e.active_days*1.0/NULLIF(DATEDIFF(e.last_seen_d,e.first_seen_d)+1,0),6) AS persistence,
           ROUND((e.st_in/NULLIF(e.nb_in,0))/NULLIF(e.st_out/NULLIF(e.nb_out,0),0),6) AS ramp_late,
           ROUND((e.st_rec/NULLIF(e.nb_rec,0))/NULLIF(e.stake/NULLIF(e.n_bets,0),0),6) AS ramp_recent,
           ROUND((e.st_rec/NULLIF(e.stake,0))/0.30,6) AS stake_ramp,
           -- 六·决策层（HF9g-P5 · D-14 斧正 —— 本件属【全窗基线族】，相对刻度与决策标签一律 NULL）
           --   病灶：x_win 系全窗单行聚合（无 GROUP BY，恒 1 行，此为设计使然，非缺陷），
           --         经 CROSS JOIN 接入后 e.* 全行同值；六层之 NTILE / PERCENT_RANK 施于常数即退化，
           --         PERCENT_RANK 恒 0 ⇒ action_priority 恒判 A，全件 100% 误标。
           --   ★ 斧正原则：不给 x_win 补 GROUP BY —— 那会改变其「全窗基线」语义，属退化。
           --     正解与 #018 之 G-05／G-06 同治：范围外之行不得接受任何下游评分与决策标签。
           --   ★ 本件之 e.* 仍照常供其它列作全窗基线使用，仅六层相对刻度与决策标签置 NULL。
           CAST(NULL AS INT)                                              AS vip_tier,                        -- 空值取值：全窗基线族无实体可分档，置 NULL（NULL＝不适用，非 0）
           CAST(NULL AS DOUBLE)                                           AS economic_value,                  -- 空值取值：同上，禁以常数百分位冒充经济价值
           CAST(NULL AS DOUBLE)                                           AS roi_pr_global,                   -- 空值取值：同上
           CAST(NULL AS DOUBLE)                                           AS risk_value,                      -- 空值取值：兼容列，同上
           CAST(NULL AS DOUBLE)                                           AS pr_stake,                        -- 空值取值：兼容列，同上
           CAST(NULL AS DOUBLE)                                           AS pr_global,                       -- 空值取值：同上
           CAST(NULL AS DOUBLE)                                           AS pr_qualified,                    -- 空值取值：同上
           'GLOBAL_BASELINE_NO_ENTITY_RANKING'                            AS pr_qualified_population,         -- 字面取值：血统 —— 明示本件为全窗基线族，无实体排序总体
           CAST(NULL AS BIGINT)                                           AS pr_global_population_n,          -- 空值取值：血统 —— 不适用
           CAST(NULL AS BIGINT)                                           AS pr_qualified_population_n,       -- 空值取值：血统 —— 不适用
           'NOT_APPLICABLE_GLOBAL_BASELINE'                               AS pr_calculation_method,           -- 字面取值：血统 —— 算法不适用
           'HF9g-P5'                                                      AS pr_calculation_version,          -- 字面取值：血统 —— 算法版本
           CAST(NULL AS STRING)                                           AS evidence_flag,                   -- 空值取值：证据旗标不适用于全窗基线
           CAST(NULL AS STRING)                                           AS evidence_rate,                   -- 空值取值：同上
           CAST(NULL AS DOUBLE)                                           AS hold_ci_halfwidth_approx,        -- 空值取值：同上
           'X 全窗基线 · 不参与实体赏罚'                                    AS action_priority                  -- 字面取值：★ D-14 斧正 —— 本族恒不入赏罚，取代原 100% 误标之「A」
    FROM q
    CROSS JOIN x_win e
  ) y
) z
-- ── 逐批 WHERE 阶梯（★ 口诀：上界 ＝ 下界 ＋ 100000，两数同进）──
--    本件 T_true 未测，无需先跑 T_true；以 0 / 100000 控制本批返回区间，末批由实际行数 < 100000 判定
--    WHERE z.audit_rn >        0 AND z.audit_rn <=   100000   -- 第 1 批
--    WHERE z.audit_rn >   100000 AND z.audit_rn <=   200000   -- 第 2 批
--    WHERE z.audit_rn >   200000 AND z.audit_rn <=   300000   -- 第 3 批
--    WHERE z.audit_rn >   300000 AND z.audit_rn <=   400000   -- 第 4 批
--    WHERE z.audit_rn >   400000 AND z.audit_rn <=   500000   -- 第 5 批
--    WHERE z.audit_rn >   500000 AND z.audit_rn <=   600000   -- 第 6 批
--    WHERE z.audit_rn >   600000 AND z.audit_rn <=   700000   -- 第 7 批
--    …余批类推。第 k 批：WHERE z.audit_rn > (k-1)*100000 AND z.audit_rn <= k*100000
--    某批返回 < 100000 行即为末批，其后不再取。
--
--    ⚠ 常见误写（务必避开）：只推下界而上界不动 ——
--        WHERE z.audit_rn > 100000 AND z.audit_rn <= 100000   ← 自相矛盾，恒为假，返回空集
--        WHERE z.audit_rn > 200000 AND z.audit_rn <= 100000   ← 同上，空集
--      两个数必须**同时**前进，且始终相差 100000。
--      下界 ＝ 上一批之上界；上界 ＝ 本批之上界。
WHERE z.audit_rn > 0 AND z.audit_rn <= 100000 -- ★ HF9c 本批区间
ORDER BY z.audit_rn;


-- ══════════════════════════════════════════════════════════════════════════════════════════════
--  69. R02_same_table.csv   [总包行 4293~4365 · 原 12 列 ＋六层约 60 列]
--     典型学：M01 同桌团伙　派生旗标：same（c.n_seat >= 2 · 仅供 CASE 条件聚合，全包无任何 WHERE/AND/HAVING 以此过滤）　连接：q.`uid1`
-- ══════════════════════════════════════════════════════════════════════════════════════════════
-- ── ① 先跑 T_true 留档（不足 100000 者一次导全，不必分批）──
-- ── ① T_true：HF9c 不再强制预跑完整 COUNT。
--    本批实际返回行数 < 100000 即判定为末批；全批完成后以各批 n_rows / audit_rn 范围核对总量。

-- ── ② 分批取数：第 1 批。第 k 批只改末行两数为 (k-1)*100000 与 k*100000 ──
--    审计字段二（REDTEAM 2026-08-24 裁定 · 四锁）：
--      audit_rn  全局观测坐标 —— 由**与原版审计版逐字同一**之排序键所生，两版可逐行对账
--      batch_id  物理分批信息 —— 该行所属批次，由 audit_rn 算得，非引擎所赋
--    ★ 锁三：二者皆为审计字段，**不得进入任何业务指标计算**。
--    ★ 锁四：两版经 audit_rn 逐行字段核验后，方可宣布输出完全一致。

-- ── ③ 每批取回后自证四数（任一不符即停手回报，禁止放行）──
--    n_rows        = COUNT(*)      须等于 COUNT(DISTINCT audit_rn)   （批内无重复）
--    audit_rn_min  = MIN(audit_rn) 须等于 (k-1)*100000 + 1           （与上批严丝合缝）
--    audit_rn_max  = MAX(audit_rn) 须等于 min + n_rows - 1           （批内无缺口）
--    全批取毕再验：各批 audit_rn 之并集 = 1 .. T_true，无缺号、无重号。
--     ★ 首行＝平台真净亏最多者（已扣退水与代理占成）。
--
SELECT z.*,
       CAST(FLOOR((z.audit_rn - 1) / 100000) + 1 AS INT)          AS batch_id,
       'A168_HF9F_20260827_0900' AS run_id,
       '2026-08-27 09:00:00' AS snapshot_sync_time
FROM (
  SELECT y.*,
         ROW_NUMBER() OVER (ORDER BY y.`residual_b` ASC, y.`roi` DESC, y.`uid1`, y.`uid2`, y.`n_same_orders`, y.`rounds_1`, y.`rounds_2`, y.`same_rate`, y.`jaccard`, y.`lift`, y.`exp_same`, y.`n_tables`, y.`first_day`, y.`last_day`) AS audit_rn
  FROM (
    WITH
      x_ranked AS (
    SELECT b.bet01, b.bet03, b.bet04, b.bet05, b.bet09, b.bet11, b.bet13,
           b.bet15, b.bet16, b.bet17, b.bet18, b.bet19, b.bet20, b.bet21,
           b.bet22, b.bet23, b.bet24, b.bet25, b.bet26, b.bet27, b.bet38, b.bet39, b.category, b.commission,
           b.dt, b.eid, b.ip, b.validbet, b.updatetime, b.sync_time,
           ROW_NUMBER() OVER (
             PARTITION BY b.bet01
             ORDER BY b.updatetime DESC, b.sync_time DESC, b.dt DESC)      AS x_rn
    FROM ods_mariadb_2b.ods_a168_bet02 b
    WHERE b.dt >= '2026-03-21' AND b.dt < '2026-08-07'
      AND b.bet02 = '101'
      AND b.sync_time <= '2026-08-27 09:00:00'
  ),
    x_testagent AS (
    SELECT age001 AS agent_id FROM ods_mariadb_2b.ods_a168_agent WHERE age022 = '1'
  ),
    x_bs0 AS (
    SELECT b.bet05 AS x_member, b.eid AS x_dealer, b.bet39 AS x_table,
           b.bet03 AS x_shoe, b.ip AS x_ip, b.bet09 AS x_product, b.dt AS x_date,
           CONCAT_WS('|', b.bet03, b.bet04, b.bet39)                      AS x_round,
           CONCAT_WS('|', b.bet39, b.bet03)                               AS x_tblshoe,
           CAST(NULLIF(TRIM(b.bet04),'') AS INT)                          AS x_rno,
           CASE WHEN b.dt >= '2026-07-08' THEN 1 ELSE 0 END               AS x_rec,
           CASE WHEN TRIM(b.commission)='1' THEN 1 ELSE 0 END             AS x_freecomm,
           CAST(NULLIF(TRIM(b.bet13),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_stake,
           CAST(NULLIF(TRIM(b.validbet),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_valid,
           CAST(NULLIF(TRIM(b.bet16),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_rebate,
           CAST(NULLIF(TRIM(b.bet17),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_net,
           CAST(NULLIF(TRIM(b.bet15),'') AS DECIMAL(20,6))                AS x_rbpct,
           COALESCE(CAST(NULLIF(TRIM(b.bet23),'') AS DECIMAL(20,6)),0)   AS x_agpct,
          NULLIF(CAST(NULLIF(TRIM(b.bet23),'') AS DECIMAL(20,6)),0)     AS x_rate1,
          NULLIF(CAST(NULLIF(TRIM(b.bet24),'') AS DECIMAL(20,6)),0)     AS x_rate2,
          NULLIF(CAST(NULLIF(TRIM(b.bet25),'') AS DECIMAL(20,6)),0)     AS x_rate3,
          NULLIF(CAST(NULLIF(TRIM(b.bet26),'') AS DECIMAL(20,6)),0)     AS x_rate4,
          NULLIF(CAST(NULLIF(TRIM(b.bet27),'') AS DECIMAL(20,6)),0)     AS x_rate5,
          (CASE WHEN NULLIF(CAST(NULLIF(TRIM(b.bet22),'') AS BIGINT),0) IS NOT NULL THEN 5
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet21),'') AS BIGINT),0) IS NOT NULL THEN 4
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet20),'') AS BIGINT),0) IS NOT NULL THEN 3
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet19),'') AS BIGINT),0) IS NOT NULL THEN 2
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet18),'') AS BIGINT),0) IS NOT NULL THEN 1
                ELSE 0 END)                                             AS x_chain_depth,
           CASE WHEN COALESCE(t1.agent_id,t2.agent_id,t3.agent_id,
                              t4.agent_id,t5.agent_id) IS NOT NULL
                THEN 1 ELSE 0 END                                        AS f_testline
    FROM x_ranked b
    LEFT JOIN x_testagent t1 ON t1.agent_id = b.bet18
    LEFT JOIN x_testagent t2 ON t2.agent_id = b.bet19
    LEFT JOIN x_testagent t3 ON t3.agent_id = b.bet20
    LEFT JOIN x_testagent t4 ON t4.agent_id = b.bet21
    LEFT JOIN x_testagent t5 ON t5.agent_id = b.bet22
    WHERE b.x_rn = 1
      AND b.category='1' AND UPPER(TRIM(b.bet38))='N'
      AND CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8)) > 0
  ),
  x_mk AS (
    SELECT s.*,
           CASE WHEN s.f_testline = 0 THEN 1 ELSE 0 END                 AS is_clean
    FROM x_bs0 s
  ),
  x_co AS (SELECT x_round, COUNT(DISTINCT x_member) AS n_seat FROM x_mk WHERE is_clean = 1 GROUP BY x_round),
  x_agg AS (
    SELECT s.x_member                                                        AS x_key,
           COUNT(*) AS n_bets, COUNT(DISTINCT s.x_round) AS n_rounds,
           COUNT(DISTINCT s.x_date) AS active_days, COUNT(DISTINCT s.x_tblshoe) AS active_shoes,
           COUNT(DISTINCT CONCAT_WS('|', s.x_date, s.x_table)) AS active_sessions,
           COUNT(DISTINCT s.x_table) AS n_tables, COUNT(DISTINCT s.x_dealer) AS n_dealers,
           COUNT(DISTINCT s.x_ip) AS n_ips, COUNT(DISTINCT s.x_product) AS n_products,
           MIN(s.x_date) AS first_seen_d, MAX(s.x_date) AS last_seen_d,
           SUM(s.x_stake) AS stake, SUM(s.x_valid) AS valid, SUM(s.x_rebate) AS rebate,
           SUM(s.x_net) AS net, SUM(-s.x_net *(100.0-s.x_agpct)/100.0) AS agent_cost,
           AVG(100.0-s.x_agpct)                   AS agent_pct,
           AVG(s.x_agpct)                         AS company_retain_pct,
           SUM(-s.x_net *s.x_agpct/100.0)         AS agent_cost_a_legacy,
           SUM(s.x_valid*s.x_agpct/100.0)         AS agent_cost_valid_base_legacy,
          AVG(COALESCE(s.x_rate1,100)) AS retain_pct_lv1, AVG(COALESCE(s.x_rate2,100)) AS retain_pct_lv2,
          AVG(COALESCE(s.x_rate3,100)) AS retain_pct_lv3, AVG(COALESCE(s.x_rate4,100)) AS retain_pct_lv4,
          AVG(COALESCE(s.x_rate5,100)) AS retain_pct_lv5, AVG(s.x_chain_depth) AS chain_depth_avg,
          AVG(COALESCE(100.0-s.x_rate1,0)) AS agent_pct_lv1, AVG(COALESCE(100.0-s.x_rate2,0)) AS agent_pct_lv2,
          AVG(COALESCE(100.0-s.x_rate3,0)) AS agent_pct_lv3, AVG(COALESCE(100.0-s.x_rate4,0)) AS agent_pct_lv4,
          AVG(COALESCE(100.0-s.x_rate5,0)) AS agent_pct_lv5,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate1,0)/100.0)                        AS agent_cost_lv1,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate2,0)/100.0)                        AS agent_cost_lv2,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate3,0)/100.0)                        AS agent_cost_lv3,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate4,0)/100.0)                        AS agent_cost_lv4,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate5,0)/100.0)                        AS agent_cost_lv5,
          SUM(-s.x_net*(COALESCE(100.0-s.x_rate1,0)+COALESCE(100.0-s.x_rate2,0)
                       +COALESCE(100.0-s.x_rate3,0)+COALESCE(100.0-s.x_rate4,0)
                       +COALESCE(100.0-s.x_rate5,0))/100.0)                   AS agent_cost_chain_additive,
          SUM(-s.x_net*(1.0 - CAST(COALESCE(s.x_rate1,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate2,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate3,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate4,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate5,100) AS DOUBLE)/100.0))
                                                                       AS agent_cost_chain_nested,
           AVG(s.x_rbpct) AS rbpct, AVG(s.x_freecomm*1.0) AS freecomm_rate,
           PERCENTILE_APPROX(s.x_stake,0.25) AS p25, PERCENTILE_APPROX(s.x_stake,0.50) AS p50,
           PERCENTILE_APPROX(s.x_stake,0.75) AS p75, PERCENTILE_APPROX(s.x_stake,0.90) AS p90,
           PERCENTILE_APPROX(s.x_stake,0.95) AS p95, PERCENTILE_APPROX(s.x_stake,0.99) AS p99,
           PERCENTILE_APPROX(s.x_valid,0.50) AS p50_valid,
           PERCENTILE_APPROX(s.x_net,0.50)   AS p50_profit,
           SUM(CASE WHEN c.n_seat >= 2 THEN s.x_stake ELSE 0 END) AS st_in,
           SUM(CASE WHEN c.n_seat >= 2 THEN 1 ELSE 0 END)         AS nb_in,
           SUM(CASE WHEN c.n_seat >= 2 THEN s.x_net ELSE 0 END)   AS net_in,
           SUM(CASE WHEN NOT (c.n_seat >= 2) THEN s.x_stake ELSE 0 END) AS st_out,
           SUM(CASE WHEN NOT (c.n_seat >= 2) THEN 1 ELSE 0 END)         AS nb_out,
           SUM(CASE WHEN NOT (c.n_seat >= 2) THEN s.x_net ELSE 0 END)   AS net_out,
           SUM(CASE WHEN s.x_rec=1 THEN s.x_stake ELSE 0 END) AS st_rec,
           SUM(CASE WHEN s.x_rec=1 THEN 1 ELSE 0 END)         AS nb_rec
    FROM x_mk s
    JOIN x_co c ON c.x_round = s.x_round
    WHERE s.is_clean = 1
      AND s.x_member IS NOT NULL AND TRIM(CAST(s.x_member AS STRING)) <> ''
    GROUP BY s.x_member
  ),
      q AS (
        WITH mr AS (                          -- 阶段一：会员 × 物理局，去重后每人每局一行
          SELECT DISTINCT                                                                                   -- 取列：承接上一子句，构成完整语句，属 §R02 之取数
                 b.bet05 AS member_id,                                                                      -- 取值表达式：取用 bet05（会员号）、member_id（会员号），产出「member_id」
                 CONCAT_WS('|', b.bet03, b.bet04, b.bet39) AS round_key,                                    -- 取值表达式：取用 bet03（靴号）、bet04（局内序号）、bet39（桌号），产出「round_key」
                 b.bet39 AS table_id,                                                                       -- 取值表达式：取用 bet39（桌号），产出「table_id」
                 b.dt    AS bet_date                                                                        -- 取值表达式：取用 dt（营业日）、bet_date（营业日），产出「bet_date」
          FROM ods_mariadb_2b.ods_a168_bet02 b            -- ★ 表名开关
          WHERE b.dt >= '2026-03-21' AND b.dt < '2026-08-07'                                                -- 过滤条件：限定 b.dt不少于 '2026-03-21'、b.dt小于 '2026-08-07'，涉 dt（营业日）
            AND b.bet02 = '101'
      AND b.sync_time <= '2026-08-27 09:00:00' AND b.category = '1'                                                        -- 并列条件：限定 b.bet02等于 '101'、b.category等于 '1'，涉 bet02（游戏类别）
            AND UPPER(TRIM(b.bet38)) = 'N'                                                                  -- 并列条件：限定 UPPER(TRIM(b.bet38))等于 'N'，涉 bet38（重對）
            AND CAST(NULLIF(TRIM(b.bet05),'') AS BIGINT) > 0                                                -- 并列条件：限定 CAST(NULLIF(TRIM(b.bet05),'') AS BIGINT)大于 0，涉 bet05（会员号）
        ),                                                                                                  -- 续行：收束上方的子查询或函数括号（§R02）
        act AS (                              -- 候选池：局数不够就不可能凑到 100 局同桌
          --   ★ 门槛由 100 提至 300（降内存斧正三）：候选池是配对数的平方项底数，
          --     门槛提三倍，配对数约降一个数量级。判据本要求同桌 ≥100 笔，
          --     总局数不足 300 者几无可能构成稳定团伙对。要复原口径改回 100 即可，
          --     但须改走 §R02-1 分批模板。
          SELECT member_id, COUNT(*) AS n_rounds                                                            -- 取列：计数，取用 member_id（会员号），产出「n_rounds」
          FROM mr GROUP BY member_id HAVING COUNT(*) >= 100                                                 -- 取数来源：取自本条自建的中间结果集 mr
        ),                                                                                                  -- 续行：收束上方的子查询或函数括号（§R02）
        mr2 AS (                                                                                            -- 公共表表达式：开启中间结果集 mr2，其后各行为其定义体（§R02）
          SELECT m.* FROM mr m JOIN act a ON a.member_id = m.member_id                                      -- 取列：整体承接上游结果集的全部字段，不再逐列列举，取自本条自建的中间结果集 mr
        ),                                                                                                  -- 续行：收束上方的子查询或函数括号（§R02）
        pair AS (                             -- 阶段二：同局自连接（已压到候选池）
          SELECT x.member_id AS uid1, y.member_id AS uid2,                                                  -- 取列：起始取列子句，本行先取「uid2」，涉 member_id（会员号）
                 COUNT(*)                    AS same_rounds,                                                -- 计数表达式：产出「same_rounds」
                 COUNT(DISTINCT x.table_id)  AS n_tables,                                                   -- 计数表达式：统计去重个数，产出「n_tables」
                 MIN(x.bet_date)             AS first_day,                                                  -- 取最小值表达式：取用 bet_date（营业日），产出「first_day」
                 MAX(x.bet_date)             AS last_day                                                    -- 取最大值表达式：取用 bet_date（营业日），产出「last_day」
          FROM mr2 x                                                                                        -- 取数来源：取自本条自建的中间结果集 mr2
          JOIN mr2 y ON x.round_key = y.round_key AND x.member_id < y.member_id                             -- 连接：取自本条自建的中间结果集 mr2，连接键为 round_key（局键）、member_id（会员号）
          GROUP BY x.member_id, y.member_id                                                                 -- 分组：按 x.member_id, y.member_id 汇总
          HAVING COUNT(*) >= 100                           -- 需求：同桌订单数 > 100 笔
        ),                                                                                                  -- 续行：收束上方的子查询或函数括号（§R02）
        td AS (                               -- Lift 零假设的分子件：每人每桌每日局数
          SELECT table_id, bet_date, member_id, COUNT(*) AS n_md                                            -- 取列：计数，取用 member_id（会员号）、bet_date（营业日），产出「n_md」
          FROM mr2 GROUP BY table_id, bet_date, member_id                                                   -- 取数来源：取自本条自建的中间结果集 mr2
        ),                                                                                                  -- 续行：收束上方的子查询或函数括号（§R02）
        tot AS (                              -- Lift 零假设的分母件：每桌每日总局数
          SELECT table_id, bet_date, COUNT(DISTINCT round_key) AS n_td                                      -- 取列：统计去重个数，产出「n_td」
          FROM mr2 GROUP BY table_id, bet_date                                                              -- 取数来源：取自本条自建的中间结果集 mr2
        ),                                                                                                  -- 续行：收束上方的子查询或函数括号（§R02）
        expct AS (                            -- E[same] = Σ n_a(t,d)·n_b(t,d) / N(t,d)
          --   ★ 降内存斧正一（决定性）：改以 pair 为**驱动表**，只为实际存在的对算期望。
          --     原式先算「同桌同日」的全组合再 LEFT JOIN 取用——同桌同日的候选会员
          --     可达数千，配对数按其平方增长，且绝大多数对根本不在 pair 里，算了白算。
          --     今由 pair 驱动，配对数降为「pair 对数 × 其共同桌日数」。
          --     期望值的定义式一字未动，输出逐值一致。
          SELECT p.uid1, p.uid2,                                                                            -- 取列：起始取列子句，本行先列 p.uid1, p.uid2
                 SUM(a.n_md * b.n_md * 1.0 / NULLIF(t.n_td,0)) AS exp_same                                  -- 汇总表达式：产出「exp_same」
          FROM pair p                                                                                       -- 取数来源：取自本条自建的中间结果集 pair
          JOIN td a  ON a.member_id = p.uid1                                                                -- 连接：取自本条自建的中间结果集 td，连接键为 member_id（会员号）
          JOIN td b  ON b.member_id = p.uid2                                                                -- 连接：取自本条自建的中间结果集 td，连接键为 member_id（会员号）
                    AND b.table_id  = a.table_id                                                            -- 并列条件：限定 b.table_id等于 a.table_id
                    AND b.bet_date  = a.bet_date                                                            -- 并列条件：限定 b.bet_date等于 a.bet_date，涉 bet_date（营业日）
          JOIN tot t ON t.table_id  = a.table_id AND t.bet_date = a.bet_date                                -- 连接：取自本条自建的中间结果集 tot，连接键为 bet_date（营业日）
          GROUP BY p.uid1, p.uid2                                                                           -- 分组：按 p.uid1, p.uid2 汇总
        )                                                                                                   -- 续行：收束上方的子查询或函数括号（§R02）
        SELECT p.uid1, p.uid2,                                                                              -- 取列：起始取列子句，本行先列 p.uid1, p.uid2
               p.same_rounds                                          AS n_same_orders,                     -- 取值表达式：产出「n_same_orders」
               a1.n_rounds                                            AS rounds_1,                          -- 取值表达式：产出「rounds_1」
               a2.n_rounds                                            AS rounds_2,                          -- 取值表达式：产出「rounds_2」
               p.same_rounds * 1.0                                                                          -- 取值表达式：比率之分子，乘 1.0 以避整数除法截断
                 / NULLIF(LEAST(a1.n_rounds, a2.n_rounds),0)          AS same_rate,   -- 需求口径
               p.same_rounds * 1.0                                                                          -- 取值表达式：比率之分子，乘 1.0 以避整数除法截断
                 / NULLIF(a1.n_rounds + a2.n_rounds - p.same_rounds,0) AS jaccard,    -- 对照口径
               p.same_rounds * 1.0 / NULLIF(e.exp_same, 0)            AS lift,        -- ★ 去巧合
               e.exp_same, p.n_tables, p.first_day, p.last_day                                              -- 续行：接续上一取列子句，续列 e.exp_same, p.n_tables, p.first_day, p.last_day
        FROM pair p                                                                                         -- 取数来源：取自本条自建的中间结果集 pair
        JOIN act a1 ON a1.member_id = p.uid1                                                                -- 连接：取自本条自建的中间结果集 act，连接键为 member_id（会员号）
        JOIN act a2 ON a2.member_id = p.uid2                                                                -- 连接：取自本条自建的中间结果集 act，连接键为 member_id（会员号）
        LEFT JOIN expct e ON e.uid1 = p.uid1 AND e.uid2 = p.uid2                                            -- 左连接：取自本条自建的中间结果集 expct，连接键为 e.uid1 = p.uid1 AND e.uid2 = p.uid2
      )
    SELECT q.*,
           -- 一·经济层
           ROUND(e.stake,4) AS stake, ROUND(e.valid,4) AS valid_bet,
           ROUND(-e.net,4) AS profit, e.n_bets, e.n_rounds,
           ROUND(e.net/NULLIF(e.stake,0),8) AS roi,
           ROUND(e.net_in/NULLIF(e.st_in,0),8) AS roi_same,
           ROUND(e.net_out/NULLIF(e.st_out,0),8) AS roi_non_same,
           ROUND((e.net-e.rebate)/NULLIF(e.stake,0),8) AS roi_ex_rebate,
           ROUND(e.net,4) AS roi_numerator, ROUND(e.stake,4) AS roi_denominator,
           CASE WHEN e.stake IS NULL THEN 'NULL_DENOM' WHEN e.stake<=0 THEN 'ZERO_DENOM'
                WHEN e.n_bets<30 THEN 'THIN_EXPOSURE' ELSE 'OK' END AS roi_denominator_status,
           ROUND(e.rebate,4) AS rebate_cost, ROUND(e.agent_cost,4)                           AS cost_complement_b,
       ROUND(e.agent_pct,4)                            AS pct_complement,
       ROUND(e.company_retain_pct,4)                   AS pct_top_bet23,
       'AG03-UNRESOLVED'                                     AS agent_formula_version,
      'ALL5_LEVELS_bet23_to_bet27'                    AS agent_level_scope,
      ROUND(e.agent_cost_lv1,4) AS agent_cost_lv1, ROUND(e.agent_cost_lv2,4) AS agent_cost_lv2,
      ROUND(e.agent_cost_lv3,4) AS agent_cost_lv3, ROUND(e.agent_cost_lv4,4) AS agent_cost_lv4,
      ROUND(e.agent_cost_lv5,4) AS agent_cost_lv5,
      ROUND(e.agent_pct_lv1,6) AS agent_pct_lv1, ROUND(e.agent_pct_lv2,6) AS agent_pct_lv2,
      ROUND(e.agent_pct_lv3,6) AS agent_pct_lv3, ROUND(e.agent_pct_lv4,6) AS agent_pct_lv4,
      ROUND(e.agent_pct_lv5,6) AS agent_pct_lv5,
      ROUND(e.retain_pct_lv1,6) AS retain_pct_lv1, ROUND(e.retain_pct_lv2,6) AS retain_pct_lv2,
      ROUND(e.retain_pct_lv3,6) AS retain_pct_lv3, ROUND(e.retain_pct_lv4,6) AS retain_pct_lv4,
      ROUND(e.retain_pct_lv5,6) AS retain_pct_lv5, ROUND(e.chain_depth_avg,4) AS chain_depth_avg,
      ROUND(e.agent_cost_chain_additive,4)            AS agent_cost_chain_additive,
      ROUND(e.agent_cost_chain_nested,4)              AS agent_cost_chain_nested,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_additive,4) AS residual_chain_additive,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_nested,4)   AS residual_chain_nested,
      'PENDING_AG03'                                  AS decision_status,
      'FALSE'                                         AS admit_to_risk_decision,
      'NOT_FOR_ENFORCEMENT'                           AS deliverable_class,
       ROUND(e.agent_cost_a_legacy,4)                  AS agent_cost_a_legacy,
       ROUND(e.agent_cost_valid_base_legacy,4)         AS agent_cost_valid_base_legacy,
           ROUND(-e.net-e.rebate,4)                        AS ngr,
       ROUND(-e.net-e.rebate-e.agent_cost,4)           AS residual_b,
       ROUND(-e.net-e.rebate-e.agent_cost_a_legacy,4)  AS residual_a,
           ROUND((-e.net-e.rebate)/NULLIF(e.stake,0),8)    AS ngr_rate,
       ROUND((-e.net-e.rebate-e.agent_cost)/NULLIF(e.stake,0),8)   AS residual_b_rate,
      -- 【HF9c · canonical accounting contract】
      --   以下 canonical 字段只增加明确 scope；不删除、不覆盖既有字段。
      --   formal_bet23_* 保持 HF9b 当前生产公式及其 NULL/0 语义；
      --   lv1~lv5 / additive / nested 则分别采用各自原始 e.* 成本字段，
      --   rate 一律从未舍入的 e.* 分子 / e.stake 计算，禁止由展示值反算。
      ROUND(e.agent_cost,4) AS agent_cost_bet23_formal_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost,4) AS net_margin_bet23_formal_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost)/NULLIF(e.stake,0),8) AS net_margin_bet23_formal_rate_canonical,
      ROUND(e.agent_cost_lv1,4) AS agent_cost_lv1_bet23_canonical,
      ROUND(e.agent_cost_lv2,4) AS agent_cost_lv2_bet24_canonical,
      ROUND(e.agent_cost_lv3,4) AS agent_cost_lv3_bet25_canonical,
      ROUND(e.agent_cost_lv4,4) AS agent_cost_lv4_bet26_canonical,
      ROUND(e.agent_cost_lv5,4) AS agent_cost_lv5_bet27_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_lv1,4) AS net_margin_lv1_bet23_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_lv1)/NULLIF(e.stake,0),8) AS net_margin_lv1_bet23_rate_canonical,
      ROUND(e.agent_cost_chain_additive,4) AS agent_cost_chain_additive_canonical,
      ROUND(e.agent_cost_chain_nested,4) AS agent_cost_chain_nested_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_additive,4) AS net_margin_chain_additive_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_nested,4) AS net_margin_chain_nested_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_chain_additive)/NULLIF(e.stake,0),8) AS net_margin_chain_additive_rate_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_chain_nested)/NULLIF(e.stake,0),8) AS net_margin_chain_nested_rate_canonical,
       ROUND((-e.net-e.rebate-e.agent_cost_a_legacy)/NULLIF(e.stake,0),8) AS residual_a_rate,
           -- 二·分布层
           ROUND(e.stake/NULLIF(e.n_bets,0),4) AS avg_stake_per_bet,
           ROUND(e.valid/NULLIF(e.n_rounds,0),4) AS avg_valid_bet_per_round,
           ROUND(-e.net/NULLIF(e.n_rounds,0),4) AS avg_profit_per_round,
           ROUND(-e.net/NULLIF(e.active_days,0),4) AS avg_profit_per_day,
           ROUND(-e.net/NULLIF(e.active_shoes,0),4) AS avg_profit_per_shoe,
           ROUND(e.stake/NULLIF(e.active_days,0),4) AS avg_stake_per_active_day,
           ROUND(e.n_rounds*1.0/NULLIF(e.active_days,0),4) AS avg_rounds_per_active_day,
           ROUND(e.st_in/NULLIF(e.nb_in,0),4) AS avg_stake_same,
           ROUND(e.st_out/NULLIF(e.nb_out,0),4) AS avg_stake_non_same,
           ROUND(e.p25,4) AS p25_stake, ROUND(e.p50,4) AS p50_stake, ROUND(e.p75,4) AS p75_stake,
           ROUND(e.p90,4) AS p90_stake, ROUND(e.p95,4) AS p95_stake, ROUND(e.p99,4) AS p99_stake,
           ROUND(e.p50_valid,4) AS p50_valid_bet, ROUND(e.p50_profit,4) AS p50_profit,
           ROUND(e.p95/NULLIF(e.p50,0),6) AS p95_over_p50,
           ROUND(e.p99/NULLIF(e.p50,0),6) AS p99_over_p50,
           ROUND((e.stake/NULLIF(e.n_bets,0))/NULLIF(e.p50,0),6) AS avg_over_p50,
           -- 三·关系层
           e.n_tables AS common_table_count, e.n_dealers AS common_dealer_count,
           e.n_ips AS common_ip_count, e.n_products AS common_product_count,
           ROUND(e.st_in/NULLIF(e.stake,0),8) AS share_same,
           -- 四·rate 层
           ROUND(-e.net/NULLIF(e.stake,0),8) AS hold_rate,
           ROUND(-e.net_in/NULLIF(e.st_in,0),8) AS hold_rate_same,
           ROUND(e.rebate/NULLIF(e.valid,0),8) AS rebate_rate_actual,
           ROUND(e.rbpct,6) AS rebate_pct_config,
           ROUND(e.valid/NULLIF(e.stake,0),6) AS turnover_multiple,
           ROUND(e.freecomm_rate,6) AS free_comm_rate,
           ROUND(e.net_in/NULLIF(e.st_in,0)-e.net_out/NULLIF(e.st_out,0),8) AS roi_delta_same,
           -- 五·动态层
           e.first_seen_d AS first_seen, e.last_seen_d AS last_seen,
           e.active_days, e.active_shoes, e.active_sessions,
           DATEDIFF(e.last_seen_d, e.first_seen_d)+1 AS span_days,
           ROUND(e.active_days*1.0/NULLIF(DATEDIFF(e.last_seen_d,e.first_seen_d)+1,0),6) AS persistence,
           ROUND((e.st_in/NULLIF(e.nb_in,0))/NULLIF(e.st_out/NULLIF(e.nb_out,0),0),6) AS ramp_same,
           ROUND((e.st_rec/NULLIF(e.nb_rec,0))/NULLIF(e.stake/NULLIF(e.n_bets,0),0),6) AS ramp_recent,
           ROUND((e.st_rec/NULLIF(e.stake,0))/0.30,6) AS stake_ramp,
           -- 六·决策层（HF9f · 详见档头【HF9f 变更说明】；本段两版逐字同一）
           NTILE(5) OVER (ORDER BY e.stake) AS vip_tier,                                                        -- 窗口取值：相对刻度 B 族，全体五等分；须连同下方血统五元组一并解读，禁作硬阈值判型
           PERCENT_RANK() OVER (ORDER BY -e.net-e.rebate-e.agent_cost)    AS economic_value,                    -- 窗口取值：HF9f·F-19 修正 —— HF9e 写作 -(-…) 双负号致方向颠倒（#075 实测 corr(economic_value, residual_b) = -1.0000）；今与 action_priority 排序键归一，值大即平台真净利高
           PERCENT_RANK() OVER (ORDER BY e.net/NULLIF(e.stake,0))         AS roi_pr_global,                     -- 窗口取值：HF9f·F-17 正名 —— 本列实为 ROI（玩家净回报率）之全体百分位，与「风险」无关；旧名 risk_value 见下一行
           PERCENT_RANK() OVER (ORDER BY e.net/NULLIF(e.stake,0))         AS risk_value,                        -- 窗口取值：兼容列，恒等于 roi_pr_global，仅为下游迁移窗保留；HF9g 起废弃，禁新引用
           PERCENT_RANK() OVER (ORDER BY e.stake)                         AS pr_stake,                          -- 窗口取值：兼容列，恒等于 pr_global，原名保留以免断链
           PERCENT_RANK() OVER (ORDER BY e.stake)                         AS pr_global,                         -- 窗口取值：HF9f·F-1 双轨之一 —— 全体口径百分位，参照总体即本件全部输出行
           CASE WHEN e.n_rounds >= 30                                                                           -- 条件分支：起始分支 —— 仅在合格子集内计算合格口径百分位
                  THEN PERCENT_RANK() OVER (PARTITION BY CASE WHEN e.n_rounds >= 30 THEN 1 ELSE 0 END ORDER BY e.stake)  -- 分支取值：以合格与否分区，故本值即 n_rounds>=30 子集内之百分位
                ELSE NULL END                                             AS pr_qualified,                      -- 条件分支：收束上方分支 —— 不合格者留 NULL（NULL＝未测，非 0），产出「pr_qualified」
           'n_rounds>=30'                                                 AS pr_qualified_population,           -- 字面取值：血统 —— 合格子集之定义
           COUNT(*) OVER ()                                               AS pr_global_population_n,            -- 窗口取值：血统 —— 全体口径之参照总体规模，渲染时现算，禁写死
           SUM(CASE WHEN e.n_rounds >= 30 THEN 1 ELSE 0 END) OVER ()      AS pr_qualified_population_n,         -- 窗口取值：血统 —— 合格子集之参照总体规模，现算，禁写死
           'PERCENT_RANK_OVER_ORDER_BY_e_stake'                           AS pr_calculation_method,             -- 字面取值：血统 —— 算法标识
           'HF9f'                                                         AS pr_calculation_version,            -- 字面取值：血统 —— 算法版本
           CASE WHEN e.n_rounds IS NULL OR e.n_rounds < 30 THEN 'THIN_ROUNDS' ELSE 'OK' END AS evidence_flag,   -- 条件分支：HF9f·F-2a 证据旗标 —— THIN_ROUNDS 者禁入执行队列，仅入观察队列
           CASE WHEN e.n_rounds IS NULL       THEN NULL                                                         -- 条件分支：起始分支 —— 未测者留 NULL（自家铁律：NULL ≠ 0）
                WHEN e.n_rounds >= 31483      THEN 'L1_POWERED'                                                 -- 分支判定：MDE 反解第一档
                WHEN e.n_rounds >= 15409      THEN 'L2_CI_1P5'                                                  -- 分支判定：MDE 反解第二档
                WHEN e.n_rounds >=  8668      THEN 'L3_CI_2P0'                                                  -- 分支判定：MDE 反解第三档
                WHEN e.n_rounds >=  3852      THEN 'L4_CI_3P0'                                                  -- 分支判定：MDE 反解第四档
                ELSE 'L5_INSUFFICIENT' END                                AS evidence_rate,                     -- 条件分支：收束上方 —— HF9f·F-3 证据分档，承 HF9e 前议之 MDE 反解五档，须于 F-4 敏感性实验后复核
           ROUND(1.96 * 0.95 / SQRT(NULLIF(CAST(e.n_rounds AS DOUBLE),0)),8) AS hold_ci_halfwidth_approx,       -- 比率表达式：HF9f·F-3 逐行现算之 95% 半宽近似；常数 0.95 为登记值，本轮 #075 实测每局 ROI 隐含 σ 于最薄层为 0.9249，二者差异待 F-4 裁定
           CASE WHEN e.stake IS NULL OR e.stake<=0 OR e.n_bets<30 OR e.n_rounds IS NULL OR e.n_rounds<30 THEN 'Z 证据不足 · 不动作'  -- 条件分支：HF9f·F-2 双条件取严 —— HF9e 仅卡 e.n_bets<30，致 n_bets>=30 而 n_rounds<30 者绕过 Z（#075 实测 18,537 名，其中 8,145 名已入 A/D 待裁）；今两条件并列取严
                WHEN PERCENT_RANK() OVER (ORDER BY -e.net-e.rebate-e.agent_cost)<=0.10                          -- 分支判定：平台真净利之最低十分位
                  THEN 'A 净亏最大十分位 · 优先复核'                                                             -- 分支取值：HF9f·F-20 正名 —— 本档 Σresidual_b 于 #075 实测 = -100,236,896，系平台净亏最大群，旧名「残值最低十分位 · 待裁」名实不符
                WHEN PERCENT_RANK() OVER (ORDER BY -e.net-e.rebate-e.agent_cost)>=0.80                          -- 分支判定：平台真净利之最高二十分位
                  THEN 'D 净利最高二十分位 · 优先留存'                                                           -- 分支取值：HF9f·F-20 正名 —— 本档 Σresidual_b 于 #075 实测 = +281,733,190，系核心利润源；与 A 档方向相反，旧版同标「待裁」属名实不符
                ELSE 'E 常规' END                                          AS action_priority                   -- 条件分支：收束上方判词，产出「action_priority」
    FROM q
    LEFT JOIN x_agg e ON CAST(e.x_key AS STRING) = CAST(q.`uid1` AS STRING)
  ) y
) z
-- ── 逐批 WHERE 阶梯（★ 口诀：上界 ＝ 下界 ＋ 100000，两数同进）──
--    本件 T_true 未测，无需先跑 T_true；以 0 / 100000 控制本批返回区间，末批由实际行数 < 100000 判定
--    WHERE z.audit_rn >        0 AND z.audit_rn <=   100000   -- 第 1 批
--    WHERE z.audit_rn >   100000 AND z.audit_rn <=   200000   -- 第 2 批
--    WHERE z.audit_rn >   200000 AND z.audit_rn <=   300000   -- 第 3 批
--    WHERE z.audit_rn >   300000 AND z.audit_rn <=   400000   -- 第 4 批
--    WHERE z.audit_rn >   400000 AND z.audit_rn <=   500000   -- 第 5 批
--    WHERE z.audit_rn >   500000 AND z.audit_rn <=   600000   -- 第 6 批
--    WHERE z.audit_rn >   600000 AND z.audit_rn <=   700000   -- 第 7 批
--    …余批类推。第 k 批：WHERE z.audit_rn > (k-1)*100000 AND z.audit_rn <= k*100000
--    某批返回 < 100000 行即为末批，其后不再取。
--
--    ⚠ 常见误写（务必避开）：只推下界而上界不动 ——
--        WHERE z.audit_rn > 100000 AND z.audit_rn <= 100000   ← 自相矛盾，恒为假，返回空集
--        WHERE z.audit_rn > 200000 AND z.audit_rn <= 100000   ← 同上，空集
--      两个数必须**同时**前进，且始终相差 100000。
--      下界 ＝ 上一批之上界；上界 ＝ 本批之上界。
WHERE z.audit_rn > 0 AND z.audit_rn <= 100000 -- ★ HF9c 本批区间
ORDER BY z.audit_rn;


-- ══════════════════════════════════════════════════════════════════════════════════════════════
--  70. R03_player_dealer.csv   [总包行 4502~4633 · 原 33 列 ＋六层约 60 列]
--     典型学：M07 荷官关联　派生旗标：recent（s.x_rec = 1 · 仅供 CASE 条件聚合，全包无任何 WHERE/AND/HAVING 以此过滤）　连接：q.`uid`
-- ══════════════════════════════════════════════════════════════════════════════════════════════
-- ── ① 先跑 T_true 留档（不足 100000 者一次导全，不必分批）──
-- ── ① T_true：HF9c 不再强制预跑完整 COUNT。
--    本批实际返回行数 < 100000 即判定为末批；全批完成后以各批 n_rows / audit_rn 范围核对总量。

-- ── ② 分批取数：第 1 批。第 k 批只改末行两数为 (k-1)*100000 与 k*100000 ──
--    审计字段二（REDTEAM 2026-08-24 裁定 · 四锁）：
--      audit_rn  全局观测坐标 —— 由**与原版审计版逐字同一**之排序键所生，两版可逐行对账
--      batch_id  物理分批信息 —— 该行所属批次，由 audit_rn 算得，非引擎所赋
--    ★ 锁三：二者皆为审计字段，**不得进入任何业务指标计算**。
--    ★ 锁四：两版经 audit_rn 逐行字段核验后，方可宣布输出完全一致。

-- ── ③ 每批取回后自证四数（任一不符即停手回报，禁止放行）──
--    n_rows        = COUNT(*)      须等于 COUNT(DISTINCT audit_rn)   （批内无重复）
--    audit_rn_min  = MIN(audit_rn) 须等于 (k-1)*100000 + 1           （与上批严丝合缝）
--    audit_rn_max  = MAX(audit_rn) 须等于 min + n_rows - 1           （批内无缺口）
--    全批取毕再验：各批 audit_rn 之并集 = 1 .. T_true，无缺号、无重号。
--     ★ 首行＝平台真净亏最多者（已扣退水与代理占成）。
--
SELECT z.*,
       CAST(FLOOR((z.audit_rn - 1) / 100000) + 1 AS INT)          AS batch_id,
       'A168_HF9F_20260827_0900' AS run_id,
       '2026-08-27 09:00:00' AS snapshot_sync_time
FROM (
  SELECT y.*,
         ROW_NUMBER() OVER (ORDER BY y.`residual_b` ASC, y.`roi` DESC, y.`uid`, y.`dealer_id`, y.`is_sentinel_dealer`, y.`stake_amount`, y.`profit_amount`, y.`net_pnl`, y.`win_rate`, y.`n_related_orders`, y.`n_rounds_eff`, y.`p_base_mix_w`, y.`p_base_mix_unw`, y.`total_bet_amount`, y.`n_bets`, y.`z_score_w`, y.`z_score_unw`, y.`z_score`, y.`delta_p`, y.`delta_z`, y.`net_pnl_all`, y.`game_pnl_all`, y.`stake_all`, y.`win_rate_all`, y.`win_rate_other`, y.`eligibility_status`, y.`eligibility_min_n`, y.`eligibility_rule`, y.`filter_stage`, y.`filter_rule_version`, y.`comparison_id`, y.`cmp_time_window`, y.`cmp_population`, y.`cmp_label`, y.`z_score_alias_status`) AS audit_rn
  FROM (
    WITH
      x_ranked AS (
    SELECT b.bet01, b.bet03, b.bet04, b.bet05, b.bet09, b.bet11, b.bet13,
           b.bet15, b.bet16, b.bet17, b.bet18, b.bet19, b.bet20, b.bet21,
           b.bet22, b.bet23, b.bet24, b.bet25, b.bet26, b.bet27, b.bet38, b.bet39, b.category, b.commission,
           b.dt, b.eid, b.ip, b.validbet, b.updatetime, b.sync_time,
           ROW_NUMBER() OVER (
             PARTITION BY b.bet01
             ORDER BY b.updatetime DESC, b.sync_time DESC, b.dt DESC)      AS x_rn
    FROM ods_mariadb_2b.ods_a168_bet02 b
    WHERE b.dt >= '2026-03-21' AND b.dt < '2026-08-07'
      AND b.bet02 = '101'
      AND b.sync_time <= '2026-08-27 09:00:00'
  ),
    x_testagent AS (
    SELECT age001 AS agent_id FROM ods_mariadb_2b.ods_a168_agent WHERE age022 = '1'
  ),
    x_bs0 AS (
    SELECT b.bet05 AS x_member, b.eid AS x_dealer, b.bet39 AS x_table,
           b.bet03 AS x_shoe, b.ip AS x_ip, b.bet09 AS x_product, b.dt AS x_date,
           CONCAT_WS('|', b.bet03, b.bet04, b.bet39)                      AS x_round,
           CONCAT_WS('|', b.bet39, b.bet03)                               AS x_tblshoe,
           CAST(NULLIF(TRIM(b.bet04),'') AS INT)                          AS x_rno,
           CASE WHEN b.dt >= '2026-07-08' THEN 1 ELSE 0 END               AS x_rec,
           CASE WHEN TRIM(b.commission)='1' THEN 1 ELSE 0 END             AS x_freecomm,
           CAST(NULLIF(TRIM(b.bet13),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_stake,
           CAST(NULLIF(TRIM(b.validbet),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_valid,
           CAST(NULLIF(TRIM(b.bet16),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_rebate,
           CAST(NULLIF(TRIM(b.bet17),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_net,
           CAST(NULLIF(TRIM(b.bet15),'') AS DECIMAL(20,6))                AS x_rbpct,
           COALESCE(CAST(NULLIF(TRIM(b.bet23),'') AS DECIMAL(20,6)),0)   AS x_agpct,
          NULLIF(CAST(NULLIF(TRIM(b.bet23),'') AS DECIMAL(20,6)),0)     AS x_rate1,
          NULLIF(CAST(NULLIF(TRIM(b.bet24),'') AS DECIMAL(20,6)),0)     AS x_rate2,
          NULLIF(CAST(NULLIF(TRIM(b.bet25),'') AS DECIMAL(20,6)),0)     AS x_rate3,
          NULLIF(CAST(NULLIF(TRIM(b.bet26),'') AS DECIMAL(20,6)),0)     AS x_rate4,
          NULLIF(CAST(NULLIF(TRIM(b.bet27),'') AS DECIMAL(20,6)),0)     AS x_rate5,
          (CASE WHEN NULLIF(CAST(NULLIF(TRIM(b.bet22),'') AS BIGINT),0) IS NOT NULL THEN 5
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet21),'') AS BIGINT),0) IS NOT NULL THEN 4
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet20),'') AS BIGINT),0) IS NOT NULL THEN 3
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet19),'') AS BIGINT),0) IS NOT NULL THEN 2
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet18),'') AS BIGINT),0) IS NOT NULL THEN 1
                ELSE 0 END)                                             AS x_chain_depth,
           CASE WHEN COALESCE(t1.agent_id,t2.agent_id,t3.agent_id,
                              t4.agent_id,t5.agent_id) IS NOT NULL
                THEN 1 ELSE 0 END                                        AS f_testline
    FROM x_ranked b
    LEFT JOIN x_testagent t1 ON t1.agent_id = b.bet18
    LEFT JOIN x_testagent t2 ON t2.agent_id = b.bet19
    LEFT JOIN x_testagent t3 ON t3.agent_id = b.bet20
    LEFT JOIN x_testagent t4 ON t4.agent_id = b.bet21
    LEFT JOIN x_testagent t5 ON t5.agent_id = b.bet22
    WHERE b.x_rn = 1
      AND b.category='1' AND UPPER(TRIM(b.bet38))='N'
      AND CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8)) > 0
  ),
  x_mk AS (
    SELECT s.*,
           CASE WHEN s.f_testline = 0 THEN 1 ELSE 0 END                 AS is_clean
    FROM x_bs0 s
  ),
  x_agg AS (
    SELECT s.x_member                                                        AS x_key,
           COUNT(*) AS n_bets, COUNT(DISTINCT s.x_round) AS n_rounds,
           COUNT(DISTINCT s.x_date) AS active_days, COUNT(DISTINCT s.x_tblshoe) AS active_shoes,
           COUNT(DISTINCT CONCAT_WS('|', s.x_date, s.x_table)) AS active_sessions,
           COUNT(DISTINCT s.x_table) AS n_tables, COUNT(DISTINCT s.x_dealer) AS n_dealers,
           COUNT(DISTINCT s.x_ip) AS n_ips, COUNT(DISTINCT s.x_product) AS n_products,
           MIN(s.x_date) AS first_seen_d, MAX(s.x_date) AS last_seen_d,
           SUM(s.x_stake) AS stake, SUM(s.x_valid) AS valid, SUM(s.x_rebate) AS rebate,
           SUM(s.x_net) AS net, SUM(-s.x_net *(100.0-s.x_agpct)/100.0) AS agent_cost,
           AVG(100.0-s.x_agpct)                   AS agent_pct,
           AVG(s.x_agpct)                         AS company_retain_pct,
           SUM(-s.x_net *s.x_agpct/100.0)         AS agent_cost_a_legacy,
           SUM(s.x_valid*s.x_agpct/100.0)         AS agent_cost_valid_base_legacy,
          AVG(COALESCE(s.x_rate1,100)) AS retain_pct_lv1, AVG(COALESCE(s.x_rate2,100)) AS retain_pct_lv2,
          AVG(COALESCE(s.x_rate3,100)) AS retain_pct_lv3, AVG(COALESCE(s.x_rate4,100)) AS retain_pct_lv4,
          AVG(COALESCE(s.x_rate5,100)) AS retain_pct_lv5, AVG(s.x_chain_depth) AS chain_depth_avg,
          AVG(COALESCE(100.0-s.x_rate1,0)) AS agent_pct_lv1, AVG(COALESCE(100.0-s.x_rate2,0)) AS agent_pct_lv2,
          AVG(COALESCE(100.0-s.x_rate3,0)) AS agent_pct_lv3, AVG(COALESCE(100.0-s.x_rate4,0)) AS agent_pct_lv4,
          AVG(COALESCE(100.0-s.x_rate5,0)) AS agent_pct_lv5,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate1,0)/100.0)                        AS agent_cost_lv1,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate2,0)/100.0)                        AS agent_cost_lv2,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate3,0)/100.0)                        AS agent_cost_lv3,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate4,0)/100.0)                        AS agent_cost_lv4,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate5,0)/100.0)                        AS agent_cost_lv5,
          SUM(-s.x_net*(COALESCE(100.0-s.x_rate1,0)+COALESCE(100.0-s.x_rate2,0)
                       +COALESCE(100.0-s.x_rate3,0)+COALESCE(100.0-s.x_rate4,0)
                       +COALESCE(100.0-s.x_rate5,0))/100.0)                   AS agent_cost_chain_additive,
          SUM(-s.x_net*(1.0 - CAST(COALESCE(s.x_rate1,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate2,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate3,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate4,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate5,100) AS DOUBLE)/100.0))
                                                                       AS agent_cost_chain_nested,
           AVG(s.x_rbpct) AS rbpct, AVG(s.x_freecomm*1.0) AS freecomm_rate,
           PERCENTILE_APPROX(s.x_stake,0.25) AS p25, PERCENTILE_APPROX(s.x_stake,0.50) AS p50,
           PERCENTILE_APPROX(s.x_stake,0.75) AS p75, PERCENTILE_APPROX(s.x_stake,0.90) AS p90,
           PERCENTILE_APPROX(s.x_stake,0.95) AS p95, PERCENTILE_APPROX(s.x_stake,0.99) AS p99,
           PERCENTILE_APPROX(s.x_valid,0.50) AS p50_valid,
           PERCENTILE_APPROX(s.x_net,0.50)   AS p50_profit,
           SUM(CASE WHEN s.x_rec = 1 THEN s.x_stake ELSE 0 END) AS st_in,
           SUM(CASE WHEN s.x_rec = 1 THEN 1 ELSE 0 END)         AS nb_in,
           SUM(CASE WHEN s.x_rec = 1 THEN s.x_net ELSE 0 END)   AS net_in,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN s.x_stake ELSE 0 END) AS st_out,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN 1 ELSE 0 END)         AS nb_out,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN s.x_net ELSE 0 END)   AS net_out,
           SUM(CASE WHEN s.x_rec=1 THEN s.x_stake ELSE 0 END) AS st_rec,
           SUM(CASE WHEN s.x_rec=1 THEN 1 ELSE 0 END)         AS nb_rec
    FROM x_mk s
    WHERE s.is_clean = 1
      AND s.x_member IS NOT NULL AND TRIM(CAST(s.x_member AS STRING)) <> ''
    GROUP BY s.x_member
  ),
      q AS (
        WITH ranked AS (                                                                                    -- 公共表表达式：开启中间结果集 ranked，其后各行为其定义体（§R03）
          SELECT b.bet01,                                                                                   -- 取列：起始取列子句——★ 2026-08-11 提速：只投影下游真正用到的列
                 b.bet03, b.bet04, b.bet05, b.bet09, b.bet11,                                               -- 续行：涉 bet03（靴号）、bet04（局内序号）、bet05（会员号）、bet09（玩法）、bet11（汇率）
                 b.bet13, b.bet14, b.bet17, b.bet38, b.bet39,                                               -- 续行：涉 bet13（下注金额）、bet14（派彩金额）、bet17（会员净输赢）、bet38（重對）、bet39（桌号）
                 b.eid,                                                                                     -- 续行：涉 eid（荷官工号）——★ 已去 updatetime／sync_time／dt／bet02／category 五列（说明见段首提速注记）
                 ROW_NUMBER() OVER (                                                                        -- 行号窗口表达式：以行号窗口取每组头部或去重，免出重复行
                   PARTITION BY b.bet01                                                                     -- 窗口分区：按 b.bet01 分组开窗，组内各自编号或排名
                   ORDER BY b.updatetime DESC, b.sync_time DESC, b.dt DESC) AS rn                           -- 排序：按 b.updatetime（降序）, b.sync_time（降序）, b.dt（降序）) AS rn 排列；导出必带排序，否则分页无稳定序（曾致 36.49% 重复行）
          FROM ods_mariadb_2b.ods_a168_bet02 b            -- ★ 表名开关
          WHERE b.dt >= '2026-03-21' AND b.dt < '2026-08-07'                                                -- 过滤条件：限定 b.dt不少于 '2026-03-21'、b.dt小于 '2026-08-07'，涉 dt（营业日）
            AND b.bet02 = '101'
      AND b.sync_time <= '2026-08-27 09:00:00' AND b.category = '1'                                                        -- 并列条件：限定 b.bet02等于 '101'、b.category等于 '1'，涉 bet02（游戏类别）
        ),                                                                                                  -- 续行：收束上方的子查询或函数括号（§R03）
        base AS (                                                                                           -- 公共表表达式：开启中间结果集 base，其后各行为其定义体（§R03）
          SELECT r.bet01 AS bet_id, r.bet05 AS member_id, r.eid AS dealer_id,                               -- 取列：起始取列子句，本行先取「dealer_id」，涉 bet05（会员号）、eid（荷官工号）、member_id（会员号）
                 CASE WHEN TRIM(r.eid) IN ('-1','0') THEN 1 ELSE 0 END AS is_sentinel_dealer,               -- 取值表达式：哨兵标记——★ 2026-08-11 改：由**删除**改为**标注**（事实层不删，分析层才筛）
                 r.bet09 AS bet_side,                                                                       -- 取值表达式：取用 bet09（玩法），产出「bet_side」
                 r.bet03, r.bet04, r.bet39,                                                                 -- 续行：★ 提速：局键三列**原样透传**，不再 CONCAT_WS 造字符串（1.25 亿行少造 1.25 亿个串）
                 CAST(NULLIF(TRIM(r.bet11),'') AS DECIMAL(20,8)) AS fx,                                     -- 取值表达式：先去空白、空串归 NULL，再显式转型——本库字段多为 varchar，不转型即比较失真，产出「fx」
                 CAST(NULLIF(TRIM(r.bet13),'') AS DECIMAL(20,4)) AS stake_raw,                              -- 取值表达式：先去空白、空串归 NULL，再显式转型——本库字段多为 varchar，不转型即比较失真，产出「stake_raw」
                 CAST(NULLIF(TRIM(r.bet14),'') AS DECIMAL(20,4)) AS payout_raw,                             -- 取值表达式：先去空白、空串归 NULL，再显式转型——本库字段多为 varchar，不转型即比较失真，产出「payout_raw」
                 CAST(NULLIF(TRIM(r.bet17),'') AS DECIMAL(20,4)) AS net_raw                                 -- 取值表达式：先去空白、空串归 NULL，再显式转型——本库字段多为 varchar，不转型即比较失真，产出「net_raw」
          FROM ranked r                                                                                     -- 取数来源：取自本条自建的中间结果集 ranked
          WHERE r.rn = 1                                                                                    -- 过滤条件：限定 r.rn等于 1
            AND UPPER(TRIM(r.bet38)) = 'N'                                                                  -- 并列条件：限定 UPPER(TRIM(r.bet38))等于 'N'，涉 bet38（重對）
            AND CAST(NULLIF(TRIM(r.bet05),'') AS BIGINT) > 0                                                -- 并列条件：限定 CAST(NULLIF(TRIM(r.bet05),'') AS BIGINT)大于 0，涉 bet05（会员号）
            AND CAST(NULLIF(TRIM(r.bet11),'') AS DECIMAL(20,8)) > 0                                         -- 并列条件：限定 CAST(NULLIF(TRIM(r.bet11),'') AS DECIMAL(20,8))大于 0，涉 bet11（汇率）
            AND NULLIF(TRIM(r.eid),'') IS NOT NULL                                                          -- 并列条件：限定该值非空，涉 eid（荷官工号）
            AND UPPER(TRIM(r.bet09)) NOT LIKE 'TIP\_1\_%'      -- 阈值报告：排除小费单
        ),                                                                                                  -- 续行：收束上方的子查询或函数括号（§R03）
        ord AS (                                                                                            -- 公共表表达式：开启中间结果集 ord，其后各行为其定义体（§R03）
          SELECT bet_id, member_id, dealer_id, is_sentinel_dealer, bet_side, bet03, bet04, bet39,           -- 取列：起始取列子句，局键改三列透传，涉 bet03（靴号）、bet04（局内序号）、bet39（桌号）
                 stake_raw / fx                AS stake,                                                    -- 取值表达式：取用 stake（下注额（经汇率归一化）），产出「stake」
                 (payout_raw - stake_raw) / fx AS game_pnl,                                                 -- 续行：取用 game_pnl（游戏净输赢），产出「game_pnl」
                 net_raw / fx                  AS net_pnl                                                   -- 取值表达式：取用 net_pnl（会员净输赢），产出「net_pnl」
          FROM base                                                                                         -- 取数来源：取自本条自建的中间结果集 base
        ),                                                                                                  -- 续行：收束上方的子查询或函数括号（§R03）
        side_base AS (      -- ★ 玩法基准胜率：各投注产品各算各的（仅 23 行，连接时广播，无倾斜）
          SELECT bet_side,                                                                                  -- 取列：起始取列子句，本行先列 bet_side
                 SUM(CASE WHEN game_pnl >  0 THEN 1 ELSE 0 END) * 1.0                                       -- 取值表达式：该产品赢局数；乘 1.0 以避整数除法截断
                   / NULLIF(SUM(CASE WHEN game_pnl <> 0 THEN 1 ELSE 0 END), 0) AS p_base                    -- 除法或乘法计算：除以决胜局数——退还局不入分母，产出「p_base」
          FROM ord WHERE is_sentinel_dealer = 0                                                             -- 取数来源：取自本条自建的中间结果集 ord——基准只由真实牌桌估计
          GROUP BY bet_side                                                                                 -- 分组：按投注产品汇总——结果仅 23 行
        ),                                                                                                  -- 续行：收束上方的子查询或函数括号（§R03）
        ordb AS (             -- 注单层挂上各自产品的基准，供下方按注额加权
          SELECT o.member_id, o.dealer_id, o.is_sentinel_dealer, o.bet03, o.bet04, o.bet39, o.bet_side,     -- 取列：起始取列子句，局键三列透传
                 o.stake, o.game_pnl, o.net_pnl, s.p_base AS p_side                                         -- 续行：并取三项金额与该注自身产品的基准胜率，产出「p_side」
          FROM      ord o                                                                                   -- 取数来源：取自本条自建的中间结果集 ord
          LEFT JOIN side_base s ON s.bet_side = o.bet_side                                                  -- 左连接：取自本条自建的中间结果集 side_base（23 行，广播）——基准未定义者留空，不以 0.5 顶替
        ),                                                                                                  -- 续行：收束上方的子查询或函数括号（§R03）
        pr AS (             -- ★ 局级去重：同局多单折成一局，Z-score 才不被 √k 倍放大
          SELECT member_id, dealer_id, is_sentinel_dealer, bet03, bet04, bet39,                             -- 取列：起始取列子句，局键改**三列原生分组**——较 CONCAT 字符串分组显著更省
                 SUM(stake)    AS stake,                                                                    -- 汇总表达式：取用 stake（下注额（经汇率归一化）），产出「stake」
                 SUM(game_pnl) AS game_pnl,                                                                 -- 汇总表达式：取用 game_pnl（游戏净输赢），产出「game_pnl」
                 SUM(net_pnl)  AS net_pnl,                                                                  -- 汇总表达式：取用 net_pnl（会员净输赢），产出「net_pnl」
                 COUNT(*)      AS n_orders_in_round,                                                        -- 计数表达式：产出「n_orders_in_round」
                 SUM(stake * p_side)                                                                        -- 汇总表达式：注额加权基准起算——★ 2026-08-11 斧正，旧法 MAX(bet_side) 取字母序最大而非主注
                   / NULLIF(SUM(CASE WHEN p_side IS NOT NULL THEN stake ELSE 0 END), 0)                     -- 除法或乘法计算：除以有基准之注的注额合计，权重口径与分子对齐
                               AS p_base_round_w,                                                             -- 续行：产出「p_base_round_w」——该局的**注额加权**基准；全注皆无基准则留空
                 AVG(p_side)   AS p_base_round_unw,                                                         -- 汇总表达式：同局各注基准的**等权**均值——★ 2026-08-11 增，供两种 estimand 对照
                 MAX(bet_side) AS main_side                                                                 -- 取最大值表达式：字母序最大注项，**仅备查、不参与计算**（旧版据此取基准，已废）
          FROM ordb GROUP BY member_id, dealer_id, is_sentinel_dealer, bet03, bet04, bet39                  -- 取数来源：取自本条自建的中间结果集 ordb；★ 三列原生分组，等价于原 round_key 分组
        ),                                                                                                  -- 续行：收束上方的子查询或函数括号（§R03）
        pd AS (                                                                                             -- 公共表表达式：开启中间结果集 pd，其后各行为其定义体（§R03）
          SELECT p.member_id, p.dealer_id, p.is_sentinel_dealer,                                            -- 取列：起始取列子句，透传哨兵标记，涉 member_id（会员号）、dealer_id（荷官工号）
                 COUNT(*)                                          AS n_rounds_eff,                         -- 计数表达式：取用 n_rounds_eff（有效局数），产出「n_rounds_eff」
                 SUM(p.n_orders_in_round)                          AS n_orders,                             -- 汇总表达式：产出「n_orders」
                 SUM(p.stake)                                      AS stake,                                -- 汇总表达式：取用 stake（下注额（经汇率归一化）），产出「stake」
                 SUM(p.game_pnl)                                   AS game_pnl,                             -- 汇总表达式：取用 game_pnl（游戏净输赢），产出「game_pnl」
                 SUM(p.net_pnl)                                    AS net_pnl,                              -- 汇总表达式：取用 net_pnl（会员净输赢），产出「net_pnl」
                 SUM(CASE WHEN p.game_pnl >  0 THEN 1 ELSE 0 END)  AS n_win,                                -- 汇总表达式：取用 game_pnl（游戏净输赢），产出「n_win」
                 SUM(CASE WHEN p.game_pnl <> 0 THEN 1 ELSE 0 END)  AS n_dec,                                -- 汇总表达式：取用 game_pnl（游戏净输赢），产出「n_dec」
                 AVG(p.p_base_round_w)                               AS p_base_mix_w,                           -- 汇总表达式：对各局的注额加权基准取均值——★ 斧正：旧法以 0.5 顶替未定义基准，今删兜底
                 AVG(p.p_base_round_unw)                           AS p_base_mix_unw                        -- 汇总表达式：等权口径之对照量——★ 二者背离即示该会员的资金集中于某一产品
          FROM pr p                                                                                         -- 取数来源：取自本条自建的中间结果集 pr
          -- （已废）旧版在此按 main_side 连 side_base 取基准，2026-08-11 改为注单层注额加权                                       -- 注：连接已移至 ordb，本处不再取基准
          GROUP BY p.member_id, p.dealer_id, p.is_sentinel_dealer                                           -- 分组：按会员×荷官×哨兵标记汇总
        ),                                                                                                  -- 续行：收束上方的子查询或函数括号（§R03）
        pdw AS (             -- ★ 2026-08-11 提速：会员合计改由 pd 开窗求得，原 player_all 已删
          SELECT p.*,                                                                                       -- 取列：整体承接上游结果集的全部字段，不再逐列列举
                 SUM(p.net_pnl)  OVER (PARTITION BY p.member_id) AS net_pnl_all,                            -- 取值表达式：按会员开窗求净输赢合计——★ 与原 player_all 逐值等价（pd 为 pr 之细分组）
                 SUM(p.game_pnl) OVER (PARTITION BY p.member_id) AS game_pnl_all,                           -- 取值表达式：按会员开窗求游戏净输赢合计
                 SUM(p.stake)    OVER (PARTITION BY p.member_id) AS stake_all,                              -- 取值表达式：按会员开窗求下注额合计
                 SUM(p.n_win)    OVER (PARTITION BY p.member_id) AS win_all,                                -- 取值表达式：按会员开窗求赢局合计
                 SUM(p.n_dec)    OVER (PARTITION BY p.member_id) AS dec_all                                 -- 取值表达式：按会员开窗求决胜局合计
          FROM pd p                                                                                         -- 取数来源：取自本条自建的中间结果集 pd——★ pr 自此只被引用一次，免 inline 重算
        )                                                                                                   -- 续行：收束上方的子查询或函数括号（§R03）
        SELECT                                                                                              -- 续行：接续上一取列子句，续列 SELECT
          pdw.member_id AS uid, pdw.dealer_id, pdw.is_sentinel_dealer,                                         -- 取列：起始取列子句，本行先取「uid」与哨兵标记，涉 member_id（会员号）、dealer_id（荷官工号）
          pdw.stake      AS stake_amount,      -- 需求「投注金额」
          pdw.game_pnl   AS profit_amount,     -- 需求「盈利金额」（剔返水口径）
          pdw.net_pnl,                                                                                       -- 续行：接续上一取列子句，续列 pd.net_pnl，涉 net_pnl（会员净输赢）
          pdw.n_win * 1.0 / NULLIF(pdw.n_dec, 0)              AS win_rate,          -- 需求「胜率」
          pdw.n_orders  AS n_related_orders,                                       -- 需求「关联订单笔数」
          pdw.n_rounds_eff, pdw.p_base_mix_w, pdw.p_base_mix_unw,                                                -- 续行：并出两种口径的基准——注额加权（判定所用）与等权（对照），涉 n_rounds_eff（有效局数）
          pdw.stake      AS total_bet_amount,                                                                -- 取值表达式：该会员×荷官的总注额——★ 暴露量，供判读加权口径是否被少数巨注支配
          pdw.n_orders   AS n_bets,                                                                          -- 取值表达式：注单数——★ 与 n_rounds_eff 并列，可见同局多注之程度
          (pdw.n_win - pdw.n_dec * pdw.p_base_mix_w)                                                             -- 取值表达式：Z 分数之分子——观测胜局减期望胜局（**注额加权基准**，主估计量）
            / NULLIF(SQRT(pdw.n_dec * pdw.p_base_mix_w * (1 - pdw.p_base_mix_w)), 0)  AS z_score_w,            -- 除法或乘法计算：除以伯努利标准差，产出「z_score_w」——**加权候选臂**，分母 n_dec 为决胜局
          (pdw.n_win - pdw.n_dec * pdw.p_base_mix_unw)                                                         -- 取值表达式：★ 2026-08-11 增·**对照臂**——同式改用等权基准（Dixon & Coles 1996 之法：
            / NULLIF(SQRT(pdw.n_dec * pdw.p_base_mix_unw * (1 - pdw.p_base_mix_unw)), 0) AS z_score_unw,       -- 续行：先立无权重基线，加权之优势方能由对照证成），产出「z_score_unw」
          (pdw.n_win - pdw.n_dec * pdw.p_base_mix_w)                                                           -- 取值表达式：兼容别名之分子——与 z_score_w 逐字同式
            / NULLIF(SQRT(pdw.n_dec * pdw.p_base_mix_w * (1 - pdw.p_base_mix_w)), 0)  AS z_score,              -- 除法或乘法计算：产出「z_score」——★ **兼容别名，恒等于 z_score_w**；既有报告与数据契约沿用此名
          pdw.p_base_mix_w - pdw.p_base_mix_unw                AS delta_p,                                    -- 加减计算：比较层——两臂基准之差，产出「delta_p」；正即加权把基准抬高
          (pdw.n_win - pdw.n_dec * pdw.p_base_mix_w)                                                           -- 取值表达式：比较层之 Z 差起算——加权臂
            / NULLIF(SQRT(pdw.n_dec * pdw.p_base_mix_w * (1 - pdw.p_base_mix_w)), 0)                           -- 续行：加权臂 Z
          - (pdw.n_win - pdw.n_dec * pdw.p_base_mix_unw)                                                       -- 续行：减基线臂
            / NULLIF(SQRT(pdw.n_dec * pdw.p_base_mix_unw * (1 - pdw.p_base_mix_unw)), 0) AS delta_z,           -- 续行：产出「delta_z」——★ 判据是 Δ，不是加权臂本身之大小
          pdw.net_pnl_all, pdw.game_pnl_all, pdw.stake_all,                                                    -- 续行：接续上一取列子句，续列 pa.net_pnl_all, pa.game_pnl_all, pa.stake_all
          pdw.win_all * 1.0 / NULLIF(pdw.dec_all, 0)          AS win_rate_all,                                -- 取值表达式：产出「win_rate_all」
          (pdw.win_all - pdw.n_win) * 1.0                                                                     -- 取值表达式：比率之分子，乘 1.0 以避整数除法截断
            / NULLIF(pdw.dec_all - pdw.n_dec, 0)              AS win_rate_other,     -- ★ 对照检验
          CASE WHEN pdw.is_sentinel_dealer = 1        THEN 'SENTINEL_DEALER'                                 -- 取值表达式：统计资格判定起算——★ 2026-08-11 立：**事实层不删，此处只标注资格**
               WHEN pdw.p_base_mix_w IS NULL            THEN 'NO_BASE_RATE'                                    -- 续行：基准未定义（该会员所押产品皆无决胜局）
               WHEN pdw.n_dec = 0                     THEN 'NO_DECISIVE_ROUND'                               -- 续行：全为退还局，无胜负可判
               WHEN pdw.n_rounds_eff < 30             THEN 'INSUFFICIENT_N'                                  -- 续行：有效局数低于阈值报告所立的 30 局下限
               ELSE 'ELIGIBLE' END                   AS eligibility_status,                                 -- 续行：产出「eligibility_status」——分析层据此筛选，规则显式可追踪
          30                                         AS eligibility_min_n,                                  -- 取值表达式：本次所用的最小有效局数——显式化，改阈只改此处并记入变更日志
          'n_rounds_eff >= 30 且基准非空且非哨兵'      AS eligibility_rule,                                           -- 取值表达式：资格规则之明文，随行落档，免日后追问「当时筛的是什么」
          'L1_ELIGIBILITY'                           AS filter_stage,                                       -- 取值表达式：过滤所处之层——★ L0 事实层不删行，此处只标注其在 L1 资格层的去留
          'v2026-08-11'                              AS filter_rule_version,                                 -- 取值表达式：资格规则版本号——改规则须改版本号并记入变更日志，免「同名不同义」
          'R03_20260811_FULL_v1'                     AS comparison_id,                                      -- 取值表达式：比较批次号——★ 两臂须同批次方可比；口径见下五列，随行落档
          '2026-03-21..2026-08-06'                   AS cmp_time_window,                                    -- 取值表达式：时间窗，产出「cmp_time_window」——两臂必同
          'baccarat_bet02_101_all_pairs_incl_sentinel' AS cmp_population,                                   -- 取值表达式：总体定义（含哨兵之全量对），产出「cmp_population」——两臂必同
          'round_win = game_pnl > 0 (decisive only)' AS cmp_label,                                          -- 取值表达式：标签定义，产出「cmp_label」——两臂必同
          'COMPATIBILITY_ONLY_NOT_PRODUCTION'        AS z_score_alias_status                                -- 取值表达式：★ `z_score` 系兼容别名之状态标记——**禁止作任何模型／排序／阈值／能力值／处置之输入**
        FROM pdw                                                                                             -- 取数来源：取自本条自建的中间结果集 pdw（已含会员合计，无须再连 player_all）
        -- （已删）旧版在此连 player_all 取会员合计；2026-08-11 改由 pdw 开窗求得，pr 遂只算一遍
        WHERE   pdw.is_sentinel_dealer = 0                                                                  -- 过滤条件：★ 2026-08-11 立·L1 合格层——非哨兵荷官
          AND   pdw.p_base_mix_w IS NOT NULL                                                                -- 并列条件：基准已定义（该会员所押产品至少一项有决胜局）
          AND   pdw.n_dec > 0                                                                               -- 并列条件：至少有一局分出胜负（全为退还局者无从判定）
          AND   pdw.n_rounds_eff >= 30                                                                      -- 并列条件：有效局数不少于 30——四者合起来即 eligibility_status = 'ELIGIBLE'
      )
    SELECT q.*,
           -- 一·经济层
           ROUND(e.stake,4) AS stake, ROUND(e.valid,4) AS valid_bet,
           ROUND(-e.net,4) AS profit, e.n_bets AS n_bets_xagg, e.n_rounds,
           ROUND(e.net/NULLIF(e.stake,0),8) AS roi,
           ROUND(e.net_in/NULLIF(e.st_in,0),8) AS roi_recent,
           ROUND(e.net_out/NULLIF(e.st_out,0),8) AS roi_non_recent,
           ROUND((e.net-e.rebate)/NULLIF(e.stake,0),8) AS roi_ex_rebate,
           ROUND(e.net,4) AS roi_numerator, ROUND(e.stake,4) AS roi_denominator,
           CASE WHEN e.stake IS NULL THEN 'NULL_DENOM' WHEN e.stake<=0 THEN 'ZERO_DENOM'
                WHEN e.n_bets<30 THEN 'THIN_EXPOSURE' ELSE 'OK' END AS roi_denominator_status,
           ROUND(e.rebate,4) AS rebate_cost, ROUND(e.agent_cost,4)                           AS cost_complement_b,
       ROUND(e.agent_pct,4)                            AS pct_complement,
       ROUND(e.company_retain_pct,4)                   AS pct_top_bet23,
       'AG03-UNRESOLVED'                                     AS agent_formula_version,
      'ALL5_LEVELS_bet23_to_bet27'                    AS agent_level_scope,
      ROUND(e.agent_cost_lv1,4) AS agent_cost_lv1, ROUND(e.agent_cost_lv2,4) AS agent_cost_lv2,
      ROUND(e.agent_cost_lv3,4) AS agent_cost_lv3, ROUND(e.agent_cost_lv4,4) AS agent_cost_lv4,
      ROUND(e.agent_cost_lv5,4) AS agent_cost_lv5,
      ROUND(e.agent_pct_lv1,6) AS agent_pct_lv1, ROUND(e.agent_pct_lv2,6) AS agent_pct_lv2,
      ROUND(e.agent_pct_lv3,6) AS agent_pct_lv3, ROUND(e.agent_pct_lv4,6) AS agent_pct_lv4,
      ROUND(e.agent_pct_lv5,6) AS agent_pct_lv5,
      ROUND(e.retain_pct_lv1,6) AS retain_pct_lv1, ROUND(e.retain_pct_lv2,6) AS retain_pct_lv2,
      ROUND(e.retain_pct_lv3,6) AS retain_pct_lv3, ROUND(e.retain_pct_lv4,6) AS retain_pct_lv4,
      ROUND(e.retain_pct_lv5,6) AS retain_pct_lv5, ROUND(e.chain_depth_avg,4) AS chain_depth_avg,
      ROUND(e.agent_cost_chain_additive,4)            AS agent_cost_chain_additive,
      ROUND(e.agent_cost_chain_nested,4)              AS agent_cost_chain_nested,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_additive,4) AS residual_chain_additive,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_nested,4)   AS residual_chain_nested,
      'PENDING_AG03'                                  AS decision_status,
      'FALSE'                                         AS admit_to_risk_decision,
      'NOT_FOR_ENFORCEMENT'                           AS deliverable_class,
       ROUND(e.agent_cost_a_legacy,4)                  AS agent_cost_a_legacy,
       ROUND(e.agent_cost_valid_base_legacy,4)         AS agent_cost_valid_base_legacy,
           ROUND(-e.net-e.rebate,4)                        AS ngr,
       ROUND(-e.net-e.rebate-e.agent_cost,4)           AS residual_b,
       ROUND(-e.net-e.rebate-e.agent_cost_a_legacy,4)  AS residual_a,
           ROUND((-e.net-e.rebate)/NULLIF(e.stake,0),8)    AS ngr_rate,
       ROUND((-e.net-e.rebate-e.agent_cost)/NULLIF(e.stake,0),8)   AS residual_b_rate,
      -- 【HF9c · canonical accounting contract】
      --   以下 canonical 字段只增加明确 scope；不删除、不覆盖既有字段。
      --   formal_bet23_* 保持 HF9b 当前生产公式及其 NULL/0 语义；
      --   lv1~lv5 / additive / nested 则分别采用各自原始 e.* 成本字段，
      --   rate 一律从未舍入的 e.* 分子 / e.stake 计算，禁止由展示值反算。
      ROUND(e.agent_cost,4) AS agent_cost_bet23_formal_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost,4) AS net_margin_bet23_formal_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost)/NULLIF(e.stake,0),8) AS net_margin_bet23_formal_rate_canonical,
      ROUND(e.agent_cost_lv1,4) AS agent_cost_lv1_bet23_canonical,
      ROUND(e.agent_cost_lv2,4) AS agent_cost_lv2_bet24_canonical,
      ROUND(e.agent_cost_lv3,4) AS agent_cost_lv3_bet25_canonical,
      ROUND(e.agent_cost_lv4,4) AS agent_cost_lv4_bet26_canonical,
      ROUND(e.agent_cost_lv5,4) AS agent_cost_lv5_bet27_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_lv1,4) AS net_margin_lv1_bet23_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_lv1)/NULLIF(e.stake,0),8) AS net_margin_lv1_bet23_rate_canonical,
      ROUND(e.agent_cost_chain_additive,4) AS agent_cost_chain_additive_canonical,
      ROUND(e.agent_cost_chain_nested,4) AS agent_cost_chain_nested_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_additive,4) AS net_margin_chain_additive_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_nested,4) AS net_margin_chain_nested_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_chain_additive)/NULLIF(e.stake,0),8) AS net_margin_chain_additive_rate_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_chain_nested)/NULLIF(e.stake,0),8) AS net_margin_chain_nested_rate_canonical,
       ROUND((-e.net-e.rebate-e.agent_cost_a_legacy)/NULLIF(e.stake,0),8) AS residual_a_rate,
           -- 二·分布层
           ROUND(e.stake/NULLIF(e.n_bets,0),4) AS avg_stake_per_bet,
           ROUND(e.valid/NULLIF(e.n_rounds,0),4) AS avg_valid_bet_per_round,
           ROUND(-e.net/NULLIF(e.n_rounds,0),4) AS avg_profit_per_round,
           ROUND(-e.net/NULLIF(e.active_days,0),4) AS avg_profit_per_day,
           ROUND(-e.net/NULLIF(e.active_shoes,0),4) AS avg_profit_per_shoe,
           ROUND(e.stake/NULLIF(e.active_days,0),4) AS avg_stake_per_active_day,
           ROUND(e.n_rounds*1.0/NULLIF(e.active_days,0),4) AS avg_rounds_per_active_day,
           ROUND(e.st_in/NULLIF(e.nb_in,0),4) AS avg_stake_recent,
           ROUND(e.st_out/NULLIF(e.nb_out,0),4) AS avg_stake_non_recent,
           ROUND(e.p25,4) AS p25_stake, ROUND(e.p50,4) AS p50_stake, ROUND(e.p75,4) AS p75_stake,
           ROUND(e.p90,4) AS p90_stake, ROUND(e.p95,4) AS p95_stake, ROUND(e.p99,4) AS p99_stake,
           ROUND(e.p50_valid,4) AS p50_valid_bet, ROUND(e.p50_profit,4) AS p50_profit,
           ROUND(e.p95/NULLIF(e.p50,0),6) AS p95_over_p50,
           ROUND(e.p99/NULLIF(e.p50,0),6) AS p99_over_p50,
           ROUND((e.stake/NULLIF(e.n_bets,0))/NULLIF(e.p50,0),6) AS avg_over_p50,
           -- 三·关系层
           e.n_tables AS common_table_count, e.n_dealers AS common_dealer_count,
           e.n_ips AS common_ip_count, e.n_products AS common_product_count,
           ROUND(e.st_in/NULLIF(e.stake,0),8) AS share_recent,
           -- 四·rate 层
           ROUND(-e.net/NULLIF(e.stake,0),8) AS hold_rate,
           ROUND(-e.net_in/NULLIF(e.st_in,0),8) AS hold_rate_recent,
           ROUND(e.rebate/NULLIF(e.valid,0),8) AS rebate_rate_actual,
           ROUND(e.rbpct,6) AS rebate_pct_config,
           ROUND(e.valid/NULLIF(e.stake,0),6) AS turnover_multiple,
           ROUND(e.freecomm_rate,6) AS free_comm_rate,
           ROUND(e.net_in/NULLIF(e.st_in,0)-e.net_out/NULLIF(e.st_out,0),8) AS roi_delta_recent,
           -- 五·动态层
           e.first_seen_d AS first_seen, e.last_seen_d AS last_seen,
           e.active_days, e.active_shoes, e.active_sessions,
           DATEDIFF(e.last_seen_d, e.first_seen_d)+1 AS span_days,
           ROUND(e.active_days*1.0/NULLIF(DATEDIFF(e.last_seen_d,e.first_seen_d)+1,0),6) AS persistence,
           ROUND((e.st_in/NULLIF(e.nb_in,0))/NULLIF(e.st_out/NULLIF(e.nb_out,0),0),6) AS ramp_recent_vs_prior,
           ROUND((e.st_rec/NULLIF(e.nb_rec,0))/NULLIF(e.stake/NULLIF(e.n_bets,0),0),6) AS ramp_recent_vs_all,
           ROUND((e.st_rec/NULLIF(e.stake,0))/0.30,6) AS stake_ramp,
           -- 六·决策层（HF9f · 详见档头【HF9f 变更说明】；本段两版逐字同一）
           NTILE(5) OVER (ORDER BY e.stake) AS vip_tier,                                                        -- 窗口取值：相对刻度 B 族，全体五等分；须连同下方血统五元组一并解读，禁作硬阈值判型
           PERCENT_RANK() OVER (ORDER BY -e.net-e.rebate-e.agent_cost)    AS economic_value,                    -- 窗口取值：HF9f·F-19 修正 —— HF9e 写作 -(-…) 双负号致方向颠倒（#075 实测 corr(economic_value, residual_b) = -1.0000）；今与 action_priority 排序键归一，值大即平台真净利高
           PERCENT_RANK() OVER (ORDER BY e.net/NULLIF(e.stake,0))         AS roi_pr_global,                     -- 窗口取值：HF9f·F-17 正名 —— 本列实为 ROI（玩家净回报率）之全体百分位，与「风险」无关；旧名 risk_value 见下一行
           PERCENT_RANK() OVER (ORDER BY e.net/NULLIF(e.stake,0))         AS risk_value,                        -- 窗口取值：兼容列，恒等于 roi_pr_global，仅为下游迁移窗保留；HF9g 起废弃，禁新引用
           PERCENT_RANK() OVER (ORDER BY e.stake)                         AS pr_stake,                          -- 窗口取值：兼容列，恒等于 pr_global，原名保留以免断链
           PERCENT_RANK() OVER (ORDER BY e.stake)                         AS pr_global,                         -- 窗口取值：HF9f·F-1 双轨之一 —— 全体口径百分位，参照总体即本件全部输出行
           CASE WHEN e.n_rounds >= 30                                                                           -- 条件分支：起始分支 —— 仅在合格子集内计算合格口径百分位
                  THEN PERCENT_RANK() OVER (PARTITION BY CASE WHEN e.n_rounds >= 30 THEN 1 ELSE 0 END ORDER BY e.stake)  -- 分支取值：以合格与否分区，故本值即 n_rounds>=30 子集内之百分位
                ELSE NULL END                                             AS pr_qualified,                      -- 条件分支：收束上方分支 —— 不合格者留 NULL（NULL＝未测，非 0），产出「pr_qualified」
           'n_rounds>=30'                                                 AS pr_qualified_population,           -- 字面取值：血统 —— 合格子集之定义
           COUNT(*) OVER ()                                               AS pr_global_population_n,            -- 窗口取值：血统 —— 全体口径之参照总体规模，渲染时现算，禁写死
           SUM(CASE WHEN e.n_rounds >= 30 THEN 1 ELSE 0 END) OVER ()      AS pr_qualified_population_n,         -- 窗口取值：血统 —— 合格子集之参照总体规模，现算，禁写死
           'PERCENT_RANK_OVER_ORDER_BY_e_stake'                           AS pr_calculation_method,             -- 字面取值：血统 —— 算法标识
           'HF9f'                                                         AS pr_calculation_version,            -- 字面取值：血统 —— 算法版本
           CASE WHEN e.n_rounds IS NULL OR e.n_rounds < 30 THEN 'THIN_ROUNDS' ELSE 'OK' END AS evidence_flag,   -- 条件分支：HF9f·F-2a 证据旗标 —— THIN_ROUNDS 者禁入执行队列，仅入观察队列
           CASE WHEN e.n_rounds IS NULL       THEN NULL                                                         -- 条件分支：起始分支 —— 未测者留 NULL（自家铁律：NULL ≠ 0）
                WHEN e.n_rounds >= 31483      THEN 'L1_POWERED'                                                 -- 分支判定：MDE 反解第一档
                WHEN e.n_rounds >= 15409      THEN 'L2_CI_1P5'                                                  -- 分支判定：MDE 反解第二档
                WHEN e.n_rounds >=  8668      THEN 'L3_CI_2P0'                                                  -- 分支判定：MDE 反解第三档
                WHEN e.n_rounds >=  3852      THEN 'L4_CI_3P0'                                                  -- 分支判定：MDE 反解第四档
                ELSE 'L5_INSUFFICIENT' END                                AS evidence_rate,                     -- 条件分支：收束上方 —— HF9f·F-3 证据分档，承 HF9e 前议之 MDE 反解五档，须于 F-4 敏感性实验后复核
           ROUND(1.96 * 0.95 / SQRT(NULLIF(CAST(e.n_rounds AS DOUBLE),0)),8) AS hold_ci_halfwidth_approx,       -- 比率表达式：HF9f·F-3 逐行现算之 95% 半宽近似；常数 0.95 为登记值，本轮 #075 实测每局 ROI 隐含 σ 于最薄层为 0.9249，二者差异待 F-4 裁定
           CASE WHEN e.stake IS NULL OR e.stake<=0 OR e.n_bets<30 OR e.n_rounds IS NULL OR e.n_rounds<30 THEN 'Z 证据不足 · 不动作'  -- 条件分支：HF9f·F-2 双条件取严 —— HF9e 仅卡 e.n_bets<30，致 n_bets>=30 而 n_rounds<30 者绕过 Z（#075 实测 18,537 名，其中 8,145 名已入 A/D 待裁）；今两条件并列取严
                WHEN PERCENT_RANK() OVER (ORDER BY -e.net-e.rebate-e.agent_cost)<=0.10                          -- 分支判定：平台真净利之最低十分位
                  THEN 'A 净亏最大十分位 · 优先复核'                                                             -- 分支取值：HF9f·F-20 正名 —— 本档 Σresidual_b 于 #075 实测 = -100,236,896，系平台净亏最大群，旧名「残值最低十分位 · 待裁」名实不符
                WHEN PERCENT_RANK() OVER (ORDER BY -e.net-e.rebate-e.agent_cost)>=0.80                          -- 分支判定：平台真净利之最高二十分位
                  THEN 'D 净利最高二十分位 · 优先留存'                                                           -- 分支取值：HF9f·F-20 正名 —— 本档 Σresidual_b 于 #075 实测 = +281,733,190，系核心利润源；与 A 档方向相反，旧版同标「待裁」属名实不符
                ELSE 'E 常规' END                                          AS action_priority                   -- 条件分支：收束上方判词，产出「action_priority」
    FROM q
    LEFT JOIN x_agg e ON CAST(e.x_key AS STRING) = CAST(q.`uid` AS STRING)
  ) y
) z
-- ── 逐批 WHERE 阶梯（★ 口诀：上界 ＝ 下界 ＋ 100000，两数同进）──
--    本件 T_true 未测，无需先跑 T_true；以 0 / 100000 控制本批返回区间，末批由实际行数 < 100000 判定
--    WHERE z.audit_rn >        0 AND z.audit_rn <=   100000   -- 第 1 批
--    WHERE z.audit_rn >   100000 AND z.audit_rn <=   200000   -- 第 2 批
--    WHERE z.audit_rn >   200000 AND z.audit_rn <=   300000   -- 第 3 批
--    WHERE z.audit_rn >   300000 AND z.audit_rn <=   400000   -- 第 4 批
--    WHERE z.audit_rn >   400000 AND z.audit_rn <=   500000   -- 第 5 批
--    WHERE z.audit_rn >   500000 AND z.audit_rn <=   600000   -- 第 6 批
--    WHERE z.audit_rn >   600000 AND z.audit_rn <=   700000   -- 第 7 批
--    …余批类推。第 k 批：WHERE z.audit_rn > (k-1)*100000 AND z.audit_rn <= k*100000
--    某批返回 < 100000 行即为末批，其后不再取。
--
--    ⚠ 常见误写（务必避开）：只推下界而上界不动 ——
--        WHERE z.audit_rn > 100000 AND z.audit_rn <= 100000   ← 自相矛盾，恒为假，返回空集
--        WHERE z.audit_rn > 200000 AND z.audit_rn <= 100000   ← 同上，空集
--      两个数必须**同时**前进，且始终相差 100000。
--      下界 ＝ 上一批之上界；上界 ＝ 本批之上界。
WHERE z.audit_rn > 0 AND z.audit_rn <= 100000 -- ★ HF9c 本批区间
ORDER BY z.audit_rn;


-- ══════════════════════════════════════════════════════════════════════════════════════════════
--  71. R03b_player_dealer_daily.csv   [总包行 6143~6242 · 原 24 列 ＋六层约 60 列]
--     典型学：M07 荷官关联　派生旗标：recent（s.x_rec = 1 · 仅供 CASE 条件聚合，全包无任何 WHERE/AND/HAVING 以此过滤）　连接：q.`uid`
-- ══════════════════════════════════════════════════════════════════════════════════════════════
-- ── ① 先跑 T_true 留档（不足 100000 者一次导全，不必分批）──
-- ── ① T_true：HF9c 不再强制预跑完整 COUNT。
--    本批实际返回行数 < 100000 即判定为末批；全批完成后以各批 n_rows / audit_rn 范围核对总量。

-- ── ② 分批取数：第 1 批。第 k 批只改末行两数为 (k-1)*100000 与 k*100000 ──
--    审计字段二（REDTEAM 2026-08-24 裁定 · 四锁）：
--      audit_rn  全局观测坐标 —— 由**与原版审计版逐字同一**之排序键所生，两版可逐行对账
--      batch_id  物理分批信息 —— 该行所属批次，由 audit_rn 算得，非引擎所赋
--    ★ 锁三：二者皆为审计字段，**不得进入任何业务指标计算**。
--    ★ 锁四：两版经 audit_rn 逐行字段核验后，方可宣布输出完全一致。

-- ── ③ 每批取回后自证四数（任一不符即停手回报，禁止放行）──
--    n_rows        = COUNT(*)      须等于 COUNT(DISTINCT audit_rn)   （批内无重复）
--    audit_rn_min  = MIN(audit_rn) 须等于 (k-1)*100000 + 1           （与上批严丝合缝）
--    audit_rn_max  = MAX(audit_rn) 须等于 min + n_rows - 1           （批内无缺口）
--    全批取毕再验：各批 audit_rn 之并集 = 1 .. T_true，无缺号、无重号。
--     ★ 首行＝平台真净亏最多者（已扣退水与代理占成）。
--
SELECT z.*,
       CAST(FLOOR((z.audit_rn - 1) / 100000) + 1 AS INT)          AS batch_id,
       'A168_HF9F_20260827_0900' AS run_id,
       '2026-08-27 09:00:00' AS snapshot_sync_time
FROM (
  SELECT y.*,
         ROW_NUMBER() OVER (ORDER BY y.`residual_b` ASC, y.`roi` DESC, y.`bet_date`, y.`uid`, y.`dealer_id`, y.`is_sentinel_dealer`, y.`stake_amount`, y.`profit_amount`, y.`net_pnl`, y.`win_rate`, y.`n_related_orders`, y.`n_rounds_eff`, y.`p_base_mix_w`, y.`p_base_mix_unw`, y.`z_score_w`, y.`z_score_unw`, y.`z_score`, y.`delta_p`, y.`eligibility_status`, y.`comparison_id`, y.`filter_stage`, y.`filter_rule_version`, y.`cmp_time_window`, y.`cmp_population`, y.`cmp_label`, y.`z_score_alias_status`) AS audit_rn
  FROM (
    WITH
      x_ranked AS (
    SELECT b.bet01, b.bet03, b.bet04, b.bet05, b.bet09, b.bet11, b.bet13,
           b.bet15, b.bet16, b.bet17, b.bet18, b.bet19, b.bet20, b.bet21,
           b.bet22, b.bet23, b.bet24, b.bet25, b.bet26, b.bet27, b.bet38, b.bet39, b.category, b.commission,
           b.dt, b.eid, b.ip, b.validbet, b.updatetime, b.sync_time,
           ROW_NUMBER() OVER (
             PARTITION BY b.bet01
             ORDER BY b.updatetime DESC, b.sync_time DESC, b.dt DESC)      AS x_rn
    FROM ods_mariadb_2b.ods_a168_bet02 b
    WHERE b.dt >= '2026-03-21' AND b.dt < '2026-08-07'
      AND b.bet02 = '101'
      AND b.sync_time <= '2026-08-27 09:00:00'
  ),
    x_testagent AS (
    SELECT age001 AS agent_id FROM ods_mariadb_2b.ods_a168_agent WHERE age022 = '1'
  ),
    x_bs0 AS (
    SELECT b.bet05 AS x_member, b.eid AS x_dealer, b.bet39 AS x_table,
           b.bet03 AS x_shoe, b.ip AS x_ip, b.bet09 AS x_product, b.dt AS x_date,
           CONCAT_WS('|', b.bet03, b.bet04, b.bet39)                      AS x_round,
           CONCAT_WS('|', b.bet39, b.bet03)                               AS x_tblshoe,
           CAST(NULLIF(TRIM(b.bet04),'') AS INT)                          AS x_rno,
           CASE WHEN b.dt >= '2026-07-08' THEN 1 ELSE 0 END               AS x_rec,
           CASE WHEN TRIM(b.commission)='1' THEN 1 ELSE 0 END             AS x_freecomm,
           CAST(NULLIF(TRIM(b.bet13),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_stake,
           CAST(NULLIF(TRIM(b.validbet),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_valid,
           CAST(NULLIF(TRIM(b.bet16),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_rebate,
           CAST(NULLIF(TRIM(b.bet17),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_net,
           CAST(NULLIF(TRIM(b.bet15),'') AS DECIMAL(20,6))                AS x_rbpct,
           COALESCE(CAST(NULLIF(TRIM(b.bet23),'') AS DECIMAL(20,6)),0)   AS x_agpct,
          NULLIF(CAST(NULLIF(TRIM(b.bet23),'') AS DECIMAL(20,6)),0)     AS x_rate1,
          NULLIF(CAST(NULLIF(TRIM(b.bet24),'') AS DECIMAL(20,6)),0)     AS x_rate2,
          NULLIF(CAST(NULLIF(TRIM(b.bet25),'') AS DECIMAL(20,6)),0)     AS x_rate3,
          NULLIF(CAST(NULLIF(TRIM(b.bet26),'') AS DECIMAL(20,6)),0)     AS x_rate4,
          NULLIF(CAST(NULLIF(TRIM(b.bet27),'') AS DECIMAL(20,6)),0)     AS x_rate5,
          (CASE WHEN NULLIF(CAST(NULLIF(TRIM(b.bet22),'') AS BIGINT),0) IS NOT NULL THEN 5
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet21),'') AS BIGINT),0) IS NOT NULL THEN 4
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet20),'') AS BIGINT),0) IS NOT NULL THEN 3
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet19),'') AS BIGINT),0) IS NOT NULL THEN 2
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet18),'') AS BIGINT),0) IS NOT NULL THEN 1
                ELSE 0 END)                                             AS x_chain_depth,
           CASE WHEN COALESCE(t1.agent_id,t2.agent_id,t3.agent_id,
                              t4.agent_id,t5.agent_id) IS NOT NULL
                THEN 1 ELSE 0 END                                        AS f_testline
    FROM x_ranked b
    LEFT JOIN x_testagent t1 ON t1.agent_id = b.bet18
    LEFT JOIN x_testagent t2 ON t2.agent_id = b.bet19
    LEFT JOIN x_testagent t3 ON t3.agent_id = b.bet20
    LEFT JOIN x_testagent t4 ON t4.agent_id = b.bet21
    LEFT JOIN x_testagent t5 ON t5.agent_id = b.bet22
    WHERE b.x_rn = 1
      AND b.category='1' AND UPPER(TRIM(b.bet38))='N'
      AND CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8)) > 0
  ),
  x_mk AS (
    SELECT s.*,
           CASE WHEN s.f_testline = 0 THEN 1 ELSE 0 END                 AS is_clean
    FROM x_bs0 s
  ),
  x_agg AS (
    SELECT s.x_member                                                        AS x_key,
           COUNT(*) AS n_bets, COUNT(DISTINCT s.x_round) AS n_rounds,
           COUNT(DISTINCT s.x_date) AS active_days, COUNT(DISTINCT s.x_tblshoe) AS active_shoes,
           COUNT(DISTINCT CONCAT_WS('|', s.x_date, s.x_table)) AS active_sessions,
           COUNT(DISTINCT s.x_table) AS n_tables, COUNT(DISTINCT s.x_dealer) AS n_dealers,
           COUNT(DISTINCT s.x_ip) AS n_ips, COUNT(DISTINCT s.x_product) AS n_products,
           MIN(s.x_date) AS first_seen_d, MAX(s.x_date) AS last_seen_d,
           SUM(s.x_stake) AS stake, SUM(s.x_valid) AS valid, SUM(s.x_rebate) AS rebate,
           SUM(s.x_net) AS net, SUM(-s.x_net *(100.0-s.x_agpct)/100.0) AS agent_cost,
           AVG(100.0-s.x_agpct)                   AS agent_pct,
           AVG(s.x_agpct)                         AS company_retain_pct,
           SUM(-s.x_net *s.x_agpct/100.0)         AS agent_cost_a_legacy,
           SUM(s.x_valid*s.x_agpct/100.0)         AS agent_cost_valid_base_legacy,
          AVG(COALESCE(s.x_rate1,100)) AS retain_pct_lv1, AVG(COALESCE(s.x_rate2,100)) AS retain_pct_lv2,
          AVG(COALESCE(s.x_rate3,100)) AS retain_pct_lv3, AVG(COALESCE(s.x_rate4,100)) AS retain_pct_lv4,
          AVG(COALESCE(s.x_rate5,100)) AS retain_pct_lv5, AVG(s.x_chain_depth) AS chain_depth_avg,
          AVG(COALESCE(100.0-s.x_rate1,0)) AS agent_pct_lv1, AVG(COALESCE(100.0-s.x_rate2,0)) AS agent_pct_lv2,
          AVG(COALESCE(100.0-s.x_rate3,0)) AS agent_pct_lv3, AVG(COALESCE(100.0-s.x_rate4,0)) AS agent_pct_lv4,
          AVG(COALESCE(100.0-s.x_rate5,0)) AS agent_pct_lv5,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate1,0)/100.0)                        AS agent_cost_lv1,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate2,0)/100.0)                        AS agent_cost_lv2,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate3,0)/100.0)                        AS agent_cost_lv3,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate4,0)/100.0)                        AS agent_cost_lv4,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate5,0)/100.0)                        AS agent_cost_lv5,
          SUM(-s.x_net*(COALESCE(100.0-s.x_rate1,0)+COALESCE(100.0-s.x_rate2,0)
                       +COALESCE(100.0-s.x_rate3,0)+COALESCE(100.0-s.x_rate4,0)
                       +COALESCE(100.0-s.x_rate5,0))/100.0)                   AS agent_cost_chain_additive,
          SUM(-s.x_net*(1.0 - CAST(COALESCE(s.x_rate1,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate2,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate3,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate4,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate5,100) AS DOUBLE)/100.0))
                                                                       AS agent_cost_chain_nested,
           AVG(s.x_rbpct) AS rbpct, AVG(s.x_freecomm*1.0) AS freecomm_rate,
           PERCENTILE_APPROX(s.x_stake,0.25) AS p25, PERCENTILE_APPROX(s.x_stake,0.50) AS p50,
           PERCENTILE_APPROX(s.x_stake,0.75) AS p75, PERCENTILE_APPROX(s.x_stake,0.90) AS p90,
           PERCENTILE_APPROX(s.x_stake,0.95) AS p95, PERCENTILE_APPROX(s.x_stake,0.99) AS p99,
           PERCENTILE_APPROX(s.x_valid,0.50) AS p50_valid,
           PERCENTILE_APPROX(s.x_net,0.50)   AS p50_profit,
           SUM(CASE WHEN s.x_rec = 1 THEN s.x_stake ELSE 0 END) AS st_in,
           SUM(CASE WHEN s.x_rec = 1 THEN 1 ELSE 0 END)         AS nb_in,
           SUM(CASE WHEN s.x_rec = 1 THEN s.x_net ELSE 0 END)   AS net_in,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN s.x_stake ELSE 0 END) AS st_out,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN 1 ELSE 0 END)         AS nb_out,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN s.x_net ELSE 0 END)   AS net_out,
           SUM(CASE WHEN s.x_rec=1 THEN s.x_stake ELSE 0 END) AS st_rec,
           SUM(CASE WHEN s.x_rec=1 THEN 1 ELSE 0 END)         AS nb_rec
    FROM x_mk s
    WHERE s.is_clean = 1
      AND s.x_member IS NOT NULL AND TRIM(CAST(s.x_member AS STRING)) <> ''
    GROUP BY s.x_member
  ),
      q AS (
        WITH ranked AS (                                                                                    -- 公共表表达式：开启中间结果集 ranked，其后各行为其定义体（§R03b）
          SELECT b.bet01, b.updatetime, b.sync_time, b.dt, b.bet02,                                         -- 取列：起始取列子句，本行先列 b.bet01, b.updatetime, b.sync_time, b.dt, b.bet02，涉 bet02（游戏类别）、dt（营业日）
                 b.bet03, b.bet04, b.bet05, b.bet09, b.bet11,                                               -- 续行：接续上一取列子句，续列 b.bet03, b.bet04, b.bet05, b.bet09, b.bet11，涉 bet03（靴号）、bet04（局内序号）、bet05（会员号）
                 b.bet13, b.bet14, b.bet17, b.bet38, b.bet39,                                               -- 续行：接续上一取列子句，续列 b.bet13, b.bet14, b.bet17, b.bet38, b.bet39，涉 bet13（下注金额）、bet14（派彩金额）、bet17（会员净输赢）
                 b.category, b.eid,                                                                         -- 续行：接续上一取列子句，续列 b.category, b.eid，涉 eid（荷官工号）
                 ROW_NUMBER() OVER (                                                                        -- 行号窗口表达式：以行号窗口取每组头部或去重，免出重复行
                   PARTITION BY b.bet01                                                                     -- 窗口分区：按 b.bet01 分组开窗，组内各自编号或排名
                   ORDER BY b.updatetime DESC, b.sync_time DESC, b.dt DESC) AS rn                           -- 排序：按 b.updatetime（降序）, b.sync_time（降序）, b.dt（降序）) AS rn 排列；导出必带排序，否则分页无稳定序（曾致 36.49% 重复行）
          FROM ods_mariadb_2b.ods_a168_bet02 b                                                              -- 取数来源：取自注单明细表（金额与行为口径的第一料源）
          WHERE b.dt >= '2026-03-21' AND b.dt < '2026-08-07'                                                -- 过滤条件：限定 b.dt不少于 '2026-03-21'、b.dt小于 '2026-08-07'，涉 dt（营业日）
            AND b.bet02 = '101'
      AND b.sync_time <= '2026-08-27 09:00:00' AND b.category = '1'                                                        -- 并列条件：限定 b.bet02等于 '101'、b.category等于 '1'，涉 bet02（游戏类别）
        ),                                                                                                  -- 续行：收束上方的子查询或函数括号（§R03b）
        base AS (                                                                                           -- 公共表表达式：开启中间结果集 base，其后各行为其定义体（§R03b）
          SELECT r.bet05 AS member_id, r.eid AS dealer_id, r.dt AS bet_date,                                -- 取列：起始取列子句，本行先取「bet_date」，涉 bet05（会员号）、eid（荷官工号）、dt（营业日）
                 CASE WHEN TRIM(r.eid) IN ('-1','0') THEN 1 ELSE 0 END AS is_sentinel_dealer,               -- 取值表达式：哨兵标记——★ 由删除改为标注（事实层不删，分析层才筛）
                 r.bet09 AS bet_side,                                                                       -- 取值表达式：取用 bet09（玩法），产出「bet_side」
                 CONCAT_WS('|', r.bet03, r.bet04, r.bet39) AS round_key,                                    -- 取值表达式：取用 bet03（靴号）、bet04（局内序号）、bet39（桌号），产出「round_key」
                 CAST(NULLIF(TRIM(r.bet11),'') AS DECIMAL(20,8)) AS fx,                                     -- 取值表达式：先去空白、空串归 NULL，再显式转型——本库字段多为 varchar，不转型即比较失真，产出「fx」
                 CAST(NULLIF(TRIM(r.bet13),'') AS DECIMAL(20,4)) AS stake_raw,                              -- 取值表达式：先去空白、空串归 NULL，再显式转型——本库字段多为 varchar，不转型即比较失真，产出「stake_raw」
                 CAST(NULLIF(TRIM(r.bet14),'') AS DECIMAL(20,4)) AS payout_raw,                             -- 取值表达式：先去空白、空串归 NULL，再显式转型——本库字段多为 varchar，不转型即比较失真，产出「payout_raw」
                 CAST(NULLIF(TRIM(r.bet17),'') AS DECIMAL(20,4)) AS net_raw                                 -- 取值表达式：先去空白、空串归 NULL，再显式转型——本库字段多为 varchar，不转型即比较失真，产出「net_raw」
          FROM ranked r                                                                                     -- 取数来源：取自本条自建的中间结果集 ranked
          WHERE r.rn = 1 AND UPPER(TRIM(r.bet38)) = 'N'                                                     -- 过滤条件：限定 r.rn等于 1、UPPER(TRIM(r.bet38))等于 'N'，涉 bet38（重對）
            AND CAST(NULLIF(TRIM(r.bet05),'') AS BIGINT) > 0                                                -- 并列条件：限定 CAST(NULLIF(TRIM(r.bet05),'') AS BIGINT)大于 0，涉 bet05（会员号）
            AND CAST(NULLIF(TRIM(r.bet11),'') AS DECIMAL(20,8)) > 0                                         -- 并列条件：限定 CAST(NULLIF(TRIM(r.bet11),'') AS DECIMAL(20,8))大于 0，涉 bet11（汇率）
            AND NULLIF(TRIM(r.eid),'') IS NOT NULL                                                          -- 并列条件：限定该值非空，涉 eid（荷官工号）
            AND UPPER(TRIM(r.bet09)) NOT LIKE 'TIP\_1\_%'                                                   -- 并列条件：限定不匹配所给模式，涉 bet09（玩法）
        ),                                                                                                  -- 续行：收束上方的子查询或函数括号（§R03b）
        ord AS (                                                                                            -- 公共表表达式：开启中间结果集 ord，其后各行为其定义体（§R03b）
          SELECT member_id, dealer_id, is_sentinel_dealer, bet_date, bet_side, round_key,                   -- 取列：起始取列子句，透传哨兵标记，涉 bet_date（营业日）、round_key（局键）
                 stake_raw / fx                AS stake,                                                    -- 取值表达式：取用 stake（下注额（经汇率归一化）），产出「stake」
                 (payout_raw - stake_raw) / fx AS game_pnl,                                                 -- 续行：取用 game_pnl（游戏净输赢），产出「game_pnl」
                 net_raw / fx                  AS net_pnl                                                   -- 取值表达式：取用 net_pnl（会员净输赢），产出「net_pnl」
          FROM base                                                                                         -- 取数来源：取自本条自建的中间结果集 base
        ),                                                                                                  -- 续行：收束上方的子查询或函数括号（§R03b）
        side_base AS (                                                                                      -- 公共表表达式：开启中间结果集 side_base，其后各行为其定义体（§R03b）
          SELECT bet_side,                                                                                  -- 取列：起始取列子句，本行先列 bet_side
                 SUM(CASE WHEN game_pnl > 0 THEN 1 ELSE 0 END) * 1.0                                        -- 取值表达式：比率之分子，乘 1.0 以避整数除法截断，涉 game_pnl（游戏净输赢）
                   / NULLIF(SUM(CASE WHEN game_pnl <> 0 THEN 1 ELSE 0 END), 0) AS p_base                    -- 除法或乘法计算：汇总，取用 game_pnl（游戏净输赢），产出「p_base」
          FROM ord WHERE is_sentinel_dealer = 0                                                             -- 取数来源：取自本条自建的中间结果集 ord——★ 基准只由**真实牌桌**估计
          GROUP BY bet_side                                                                                 -- 分组：按投注产品汇总
        ),                                                                                                  -- 续行：收束上方的子查询或函数括号（§R03b）
        ordb AS (             -- ★ 2026-08-11 增：注单层挂上各自产品的基准，供下方按注额加权
          SELECT o.member_id, o.dealer_id, o.is_sentinel_dealer, o.bet_date, o.round_key, o.bet_side,       -- 取列：起始取列子句，透传五键与哨兵标记
                 o.stake, o.game_pnl, o.net_pnl, s.p_base AS p_side                                         -- 续行：并取三项金额与该注自身产品的基准胜率，产出「p_side」
          FROM      ord o                                                                                   -- 取数来源：取自本条自建的中间结果集 ord
          LEFT JOIN side_base s ON s.bet_side = o.bet_side                                                  -- 左连接：取自本条自建的中间结果集 side_base，基准未定义者留空——不以 0.5 顶替
        ),                                                                                                  -- 续行：收束上方的子查询或函数括号（§R03b）
        pr AS (   -- 局级去重：同一物理局折成一局，避免 Z-score 被 sqrt(k) 放大
          SELECT member_id, dealer_id, is_sentinel_dealer, bet_date, round_key,                             -- 取列：起始取列子句，透传哨兵标记
                 SUM(stake) AS stake, SUM(game_pnl) AS game_pnl, SUM(net_pnl) AS net_pnl,                   -- 汇总表达式：取用 stake（下注额（经汇率归一化））、net_pnl（会员净输赢）、game_pnl（游戏净输赢），产出「net_pnl」
                 COUNT(*) AS n_orders_in_round,                                                             -- 计数表达式：产出「n_orders_in_round」
                 SUM(stake * p_side)                                                                        -- 汇总表达式：注额加权基准起算——★ 斧正，旧法 MAX(bet_side) 取字母序最大而非主注
                   / NULLIF(SUM(CASE WHEN p_side IS NOT NULL THEN stake ELSE 0 END), 0)                     -- 除法或乘法计算：除以有基准之注的注额合计
                               AS p_base_round_w,                                                             -- 续行：产出「p_base_round_w」——该局的**注额加权**基准；全注皆无基准则留空
                 AVG(p_side)   AS p_base_round_unw,                                                         -- 汇总表达式：同局各注基准的**等权**均值——★ 2026-08-11 增，供两种 estimand 对照
                 MAX(bet_side) AS main_side                                                                 -- 取最大值表达式：字母序最大注项，**仅备查、不参与计算**
          FROM ordb GROUP BY member_id, dealer_id, is_sentinel_dealer, bet_date, round_key                  -- 取数来源：取自本条自建的中间结果集 ordb（已挂基准）
        )                                                                                                   -- 续行：收束上方的子查询或函数括号（§R03b）
        SELECT p.bet_date, p.member_id AS uid, p.dealer_id, p.is_sentinel_dealer,                           -- 取列：起始取列子句，本行先取「uid」与哨兵标记
               SUM(p.stake)                                        AS stake_amount,                         -- 汇总表达式：取用 stake（下注额（经汇率归一化）），产出「stake_amount」
               SUM(p.game_pnl)                                     AS profit_amount,                        -- 汇总表达式：取用 game_pnl（游戏净输赢），产出「profit_amount」
               SUM(p.net_pnl)                                      AS net_pnl,                              -- 汇总表达式：取用 net_pnl（会员净输赢），产出「net_pnl」
               SUM(CASE WHEN p.game_pnl > 0 THEN 1 ELSE 0 END) * 1.0                                        -- 取值表达式：比率之分子，乘 1.0 以避整数除法截断，涉 game_pnl（游戏净输赢）
                 / NULLIF(SUM(CASE WHEN p.game_pnl <> 0 THEN 1 ELSE 0 END), 0) AS win_rate,                 -- 除法或乘法计算：汇总，取用 game_pnl（游戏净输赢），产出「win_rate」
               SUM(p.n_orders_in_round)                            AS n_related_orders,                     -- 汇总表达式：产出「n_related_orders」
               COUNT(*)                                            AS n_rounds_eff,                         -- 计数表达式：取用 n_rounds_eff（有效局数），产出「n_rounds_eff」
               AVG(p.p_base_round_w)                                 AS p_base_mix_w,                           -- 汇总表达式：对各局的**注额加权**基准取均值——判定所用者
               AVG(p.p_base_round_unw)                             AS p_base_mix_unw,                       -- 汇总表达式：**等权**口径之对照量——★ 2026-08-11 与 §R03 对齐，二者背离即示资金集中于某产品
               (SUM(CASE WHEN p.game_pnl > 0 THEN 1 ELSE 0 END)                                             -- 续行：汇总，取用 game_pnl（游戏净输赢）
                - SUM(CASE WHEN p.game_pnl <> 0 THEN 1 ELSE 0 END) * AVG(p.p_base_round_w))           -- 加减计算：观测赢局数减期望赢局数 ＝ 超额，与 GGR 无涉
                 / NULLIF(SQRT(SUM(CASE WHEN p.game_pnl <> 0 THEN 1 ELSE 0 END)                             -- 除法或乘法计算：汇总，取用 game_pnl（游戏净输赢）
                               * AVG(p.p_base_round_w)                                                -- 除法或乘法计算：求均值
                               * (1 - AVG(p.p_base_round_w))), 0)        AS z_score_w,                      -- 除法或乘法计算：产出「z_score_w」——**加权候选臂**
               (SUM(CASE WHEN p.game_pnl > 0 THEN 1 ELSE 0 END)                                             -- 取值表达式：★ **对照臂**之分子——同式改用等权基准（Dixon & Coles 1996：先立无权重基线）
                - SUM(CASE WHEN p.game_pnl <> 0 THEN 1 ELSE 0 END) * AVG(p.p_base_round_unw))               -- 续行：期望胜局按等权基准算
                 / NULLIF(SQRT(SUM(CASE WHEN p.game_pnl <> 0 THEN 1 ELSE 0 END)                             -- 除法或乘法计算：除以伯努利标准差
                               * AVG(p.p_base_round_unw)                                                    -- 续行：等权基准
                               * (1 - AVG(p.p_base_round_unw))), 0)    AS z_score_unw,                      -- 续行：产出「z_score_unw」——加权之优势须由本臂对照证成
               (SUM(CASE WHEN p.game_pnl > 0 THEN 1 ELSE 0 END)                                             -- 取值表达式：兼容别名之分子——与 z_score_w 逐字同式
                - SUM(CASE WHEN p.game_pnl <> 0 THEN 1 ELSE 0 END) * AVG(p.p_base_round_w))                 -- 续行：期望胜局按加权基准算
                 / NULLIF(SQRT(SUM(CASE WHEN p.game_pnl <> 0 THEN 1 ELSE 0 END)                             -- 除法或乘法计算：除以伯努利标准差
                               * AVG(p.p_base_round_w)                                                      -- 续行：加权基准
                               * (1 - AVG(p.p_base_round_w))), 0)        AS z_score,                        -- 续行：产出「z_score」——★ **兼容别名，恒等于 z_score_w**；既有报告与数据契约沿用此名
               AVG(p.p_base_round_w) - AVG(p.p_base_round_unw)          AS delta_p,                         -- 加减计算：比较层——两臂基准之差，产出「delta_p」
               CASE WHEN p.is_sentinel_dealer = 1 THEN 'SENTINEL_DEALER'                                    -- 取值表达式：统计资格判定起算——事实层不删，此处只标注资格
                    WHEN AVG(p.p_base_round_w) IS NULL THEN 'NO_BASE_RATE'                                    -- 续行：基准未定义
                    WHEN SUM(CASE WHEN p.game_pnl <> 0 THEN 1 ELSE 0 END) = 0 THEN 'NO_DECISIVE_ROUND'      -- 续行：全为退还局，无胜负可判
                    ELSE 'ELIGIBLE' END                                 AS eligibility_status,               -- 续行：产出「eligibility_status」——日粒度不设局数下限，下限由分析层施加
               'R03b_20260811_FULL_v1'                              AS comparison_id,                       -- 取值表达式：比较批次号——与 §R03 同规格，两臂须同批次方可比
               'L1_ELIGIBILITY'                           AS filter_stage,                                  -- 取值表达式：过滤所处之层——★ L0 事实层不删行，此处只标注其在 L1 资格层的去留
               'v2026-08-11'                              AS filter_rule_version,                            -- 取值表达式：资格规则版本号——改规则须改版本号并记入变更日志，免「同名不同义」
               '2026-03-21..2026-08-06'                             AS cmp_time_window,                     -- 取值表达式：时间窗，产出「cmp_time_window」
               'baccarat_bet02_101_all_pairs_incl_sentinel'         AS cmp_population,                      -- 取值表达式：总体定义（含哨兵之全量对）
               'round_win = game_pnl > 0 (decisive only)'           AS cmp_label,                           -- 取值表达式：标签定义
               'COMPATIBILITY_ONLY_NOT_PRODUCTION'                  AS z_score_alias_status                 -- 取值表达式：★ 兼容别名状态——禁止作生产输入
        FROM pr p                                                                                           -- 取数来源：取自本条自建的中间结果集 pr
        -- （已废）旧版在此按 main_side 连 side_base 取基准，2026-08-11 改注单层注额加权                                          -- 注：连接已移至 ordb，本处不再取基准
        GROUP BY p.bet_date, p.member_id, p.dealer_id, p.is_sentinel_dealer                                 -- 分组：按营业日×会员×荷官×哨兵标记汇总
      )
    SELECT q.*,
           -- 一·经济层
           ROUND(e.stake,4) AS stake, ROUND(e.valid,4) AS valid_bet,
           ROUND(-e.net,4) AS profit, e.n_bets, e.n_rounds,
           ROUND(e.net/NULLIF(e.stake,0),8) AS roi,
           ROUND(e.net_in/NULLIF(e.st_in,0),8) AS roi_recent,
           ROUND(e.net_out/NULLIF(e.st_out,0),8) AS roi_non_recent,
           ROUND((e.net-e.rebate)/NULLIF(e.stake,0),8) AS roi_ex_rebate,
           ROUND(e.net,4) AS roi_numerator, ROUND(e.stake,4) AS roi_denominator,
           CASE WHEN e.stake IS NULL THEN 'NULL_DENOM' WHEN e.stake<=0 THEN 'ZERO_DENOM'
                WHEN e.n_bets<30 THEN 'THIN_EXPOSURE' ELSE 'OK' END AS roi_denominator_status,
           ROUND(e.rebate,4) AS rebate_cost, ROUND(e.agent_cost,4)                           AS cost_complement_b,
       ROUND(e.agent_pct,4)                            AS pct_complement,
       ROUND(e.company_retain_pct,4)                   AS pct_top_bet23,
       'AG03-UNRESOLVED'                                     AS agent_formula_version,
      'ALL5_LEVELS_bet23_to_bet27'                    AS agent_level_scope,
      ROUND(e.agent_cost_lv1,4) AS agent_cost_lv1, ROUND(e.agent_cost_lv2,4) AS agent_cost_lv2,
      ROUND(e.agent_cost_lv3,4) AS agent_cost_lv3, ROUND(e.agent_cost_lv4,4) AS agent_cost_lv4,
      ROUND(e.agent_cost_lv5,4) AS agent_cost_lv5,
      ROUND(e.agent_pct_lv1,6) AS agent_pct_lv1, ROUND(e.agent_pct_lv2,6) AS agent_pct_lv2,
      ROUND(e.agent_pct_lv3,6) AS agent_pct_lv3, ROUND(e.agent_pct_lv4,6) AS agent_pct_lv4,
      ROUND(e.agent_pct_lv5,6) AS agent_pct_lv5,
      ROUND(e.retain_pct_lv1,6) AS retain_pct_lv1, ROUND(e.retain_pct_lv2,6) AS retain_pct_lv2,
      ROUND(e.retain_pct_lv3,6) AS retain_pct_lv3, ROUND(e.retain_pct_lv4,6) AS retain_pct_lv4,
      ROUND(e.retain_pct_lv5,6) AS retain_pct_lv5, ROUND(e.chain_depth_avg,4) AS chain_depth_avg,
      ROUND(e.agent_cost_chain_additive,4)            AS agent_cost_chain_additive,
      ROUND(e.agent_cost_chain_nested,4)              AS agent_cost_chain_nested,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_additive,4) AS residual_chain_additive,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_nested,4)   AS residual_chain_nested,
      'PENDING_AG03'                                  AS decision_status,
      'FALSE'                                         AS admit_to_risk_decision,
      'NOT_FOR_ENFORCEMENT'                           AS deliverable_class,
       ROUND(e.agent_cost_a_legacy,4)                  AS agent_cost_a_legacy,
       ROUND(e.agent_cost_valid_base_legacy,4)         AS agent_cost_valid_base_legacy,
           ROUND(-e.net-e.rebate,4)                        AS ngr,
       ROUND(-e.net-e.rebate-e.agent_cost,4)           AS residual_b,
       ROUND(-e.net-e.rebate-e.agent_cost_a_legacy,4)  AS residual_a,
           ROUND((-e.net-e.rebate)/NULLIF(e.stake,0),8)    AS ngr_rate,
       ROUND((-e.net-e.rebate-e.agent_cost)/NULLIF(e.stake,0),8)   AS residual_b_rate,
      -- 【HF9c · canonical accounting contract】
      --   以下 canonical 字段只增加明确 scope；不删除、不覆盖既有字段。
      --   formal_bet23_* 保持 HF9b 当前生产公式及其 NULL/0 语义；
      --   lv1~lv5 / additive / nested 则分别采用各自原始 e.* 成本字段，
      --   rate 一律从未舍入的 e.* 分子 / e.stake 计算，禁止由展示值反算。
      ROUND(e.agent_cost,4) AS agent_cost_bet23_formal_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost,4) AS net_margin_bet23_formal_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost)/NULLIF(e.stake,0),8) AS net_margin_bet23_formal_rate_canonical,
      ROUND(e.agent_cost_lv1,4) AS agent_cost_lv1_bet23_canonical,
      ROUND(e.agent_cost_lv2,4) AS agent_cost_lv2_bet24_canonical,
      ROUND(e.agent_cost_lv3,4) AS agent_cost_lv3_bet25_canonical,
      ROUND(e.agent_cost_lv4,4) AS agent_cost_lv4_bet26_canonical,
      ROUND(e.agent_cost_lv5,4) AS agent_cost_lv5_bet27_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_lv1,4) AS net_margin_lv1_bet23_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_lv1)/NULLIF(e.stake,0),8) AS net_margin_lv1_bet23_rate_canonical,
      ROUND(e.agent_cost_chain_additive,4) AS agent_cost_chain_additive_canonical,
      ROUND(e.agent_cost_chain_nested,4) AS agent_cost_chain_nested_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_additive,4) AS net_margin_chain_additive_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_nested,4) AS net_margin_chain_nested_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_chain_additive)/NULLIF(e.stake,0),8) AS net_margin_chain_additive_rate_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_chain_nested)/NULLIF(e.stake,0),8) AS net_margin_chain_nested_rate_canonical,
       ROUND((-e.net-e.rebate-e.agent_cost_a_legacy)/NULLIF(e.stake,0),8) AS residual_a_rate,
           -- 二·分布层
           ROUND(e.stake/NULLIF(e.n_bets,0),4) AS avg_stake_per_bet,
           ROUND(e.valid/NULLIF(e.n_rounds,0),4) AS avg_valid_bet_per_round,
           ROUND(-e.net/NULLIF(e.n_rounds,0),4) AS avg_profit_per_round,
           ROUND(-e.net/NULLIF(e.active_days,0),4) AS avg_profit_per_day,
           ROUND(-e.net/NULLIF(e.active_shoes,0),4) AS avg_profit_per_shoe,
           ROUND(e.stake/NULLIF(e.active_days,0),4) AS avg_stake_per_active_day,
           ROUND(e.n_rounds*1.0/NULLIF(e.active_days,0),4) AS avg_rounds_per_active_day,
           ROUND(e.st_in/NULLIF(e.nb_in,0),4) AS avg_stake_recent,
           ROUND(e.st_out/NULLIF(e.nb_out,0),4) AS avg_stake_non_recent,
           ROUND(e.p25,4) AS p25_stake, ROUND(e.p50,4) AS p50_stake, ROUND(e.p75,4) AS p75_stake,
           ROUND(e.p90,4) AS p90_stake, ROUND(e.p95,4) AS p95_stake, ROUND(e.p99,4) AS p99_stake,
           ROUND(e.p50_valid,4) AS p50_valid_bet, ROUND(e.p50_profit,4) AS p50_profit,
           ROUND(e.p95/NULLIF(e.p50,0),6) AS p95_over_p50,
           ROUND(e.p99/NULLIF(e.p50,0),6) AS p99_over_p50,
           ROUND((e.stake/NULLIF(e.n_bets,0))/NULLIF(e.p50,0),6) AS avg_over_p50,
           -- 三·关系层
           e.n_tables AS common_table_count, e.n_dealers AS common_dealer_count,
           e.n_ips AS common_ip_count, e.n_products AS common_product_count,
           ROUND(e.st_in/NULLIF(e.stake,0),8) AS share_recent,
           -- 四·rate 层
           ROUND(-e.net/NULLIF(e.stake,0),8) AS hold_rate,
           ROUND(-e.net_in/NULLIF(e.st_in,0),8) AS hold_rate_recent,
           ROUND(e.rebate/NULLIF(e.valid,0),8) AS rebate_rate_actual,
           ROUND(e.rbpct,6) AS rebate_pct_config,
           ROUND(e.valid/NULLIF(e.stake,0),6) AS turnover_multiple,
           ROUND(e.freecomm_rate,6) AS free_comm_rate,
           ROUND(e.net_in/NULLIF(e.st_in,0)-e.net_out/NULLIF(e.st_out,0),8) AS roi_delta_recent,
           -- 五·动态层
           e.first_seen_d AS first_seen, e.last_seen_d AS last_seen,
           e.active_days, e.active_shoes, e.active_sessions,
           DATEDIFF(e.last_seen_d, e.first_seen_d)+1 AS span_days,
           ROUND(e.active_days*1.0/NULLIF(DATEDIFF(e.last_seen_d,e.first_seen_d)+1,0),6) AS persistence,
           ROUND((e.st_in/NULLIF(e.nb_in,0))/NULLIF(e.st_out/NULLIF(e.nb_out,0),0),6) AS ramp_recent_vs_prior,
           ROUND((e.st_rec/NULLIF(e.nb_rec,0))/NULLIF(e.stake/NULLIF(e.n_bets,0),0),6) AS ramp_recent_vs_all,
           ROUND((e.st_rec/NULLIF(e.stake,0))/0.30,6) AS stake_ramp,
           -- 六·决策层（HF9g-P5D-b · D-14b 斧正 —— 本件属【行加权错粒度族】，六层相对刻度与决策标签一律 NULL）
           --   详见档头【变更日志 · 改动 C】。原六·决策层 29 行逐字留存于本段下方注释，可原样恢复。
           --   ★ 本件之 e.* 仍照常供经济层／分布层／关系层／rate 层／动态层使用，仅六层置 NULL。
           --   ★ audit_rn 不受影响：其 26 个排序键之首二者 residual_b / roi 出自经济层，本段未动。
           --   ★ 副效：本段 8 个无 PARTITION BY 之窗口算子随之消失，全局排序由 9 个降为 1 个。
           --   ⚠⚠ 待裁 · 阻断告警（本段三处字面值随模板逐字沿用，于本件**名实不符**）：
           --        pr_qualified_population   = 'GLOBAL_BASELINE_NO_ENTITY_RANKING'
           --        pr_calculation_method     = 'NOT_APPLICABLE_GLOBAL_BASELINE'
           --        action_priority           = 'X 全窗基线 · 不参与实体赏罚'
           --        本件属【行加权错粒度族】，**并非全窗基线族**；三值将随 CSV 落地，构成失实血统标签。
           --        改之则须引入 P4D/P5D 以外之常量，违「禁引包外」之令 ⇒ 故逐字沿用并在此立案。
           --        ★ 本项未裁定前，本件 CSV **不得进入任何对外交付或下游消费**，仅供跑通性验证。
           CAST(NULL AS INT)                                              AS vip_tier,                        -- 空值取值：全窗基线族无实体可分档，置 NULL（NULL＝不适用，非 0）
           CAST(NULL AS DOUBLE)                                           AS economic_value,                  -- 空值取值：同上，禁以常数百分位冒充经济价值
           CAST(NULL AS DOUBLE)                                           AS roi_pr_global,                   -- 空值取值：同上
           CAST(NULL AS DOUBLE)                                           AS risk_value,                      -- 空值取值：兼容列，同上
           CAST(NULL AS DOUBLE)                                           AS pr_stake,                        -- 空值取值：兼容列，同上
           CAST(NULL AS DOUBLE)                                           AS pr_global,                       -- 空值取值：同上
           CAST(NULL AS DOUBLE)                                           AS pr_qualified,                    -- 空值取值：同上
           'GLOBAL_BASELINE_NO_ENTITY_RANKING'                            AS pr_qualified_population,         -- 字面取值：血统 —— 明示本件为全窗基线族，无实体排序总体
           CAST(NULL AS BIGINT)                                           AS pr_global_population_n,          -- 空值取值：血统 —— 不适用
           CAST(NULL AS BIGINT)                                           AS pr_qualified_population_n,       -- 空值取值：血统 —— 不适用
           'NOT_APPLICABLE_GLOBAL_BASELINE'                               AS pr_calculation_method,           -- 字面取值：血统 —— 算法不适用
           'HF9g-P5'                                                      AS pr_calculation_version,          -- 字面取值：血统 —— 算法版本
           CAST(NULL AS STRING)                                           AS evidence_flag,                   -- 空值取值：证据旗标不适用于全窗基线
           CAST(NULL AS STRING)                                           AS evidence_rate,                   -- 空值取值：同上
           CAST(NULL AS DOUBLE)                                           AS hold_ci_halfwidth_approx,        -- 空值取值：同上
           'X 全窗基线 · 不参与实体赏罚'                                    AS action_priority                  -- 字面取值：★ D-14 斧正 —— 本族恒不入赏罚，取代原 100% 误标之「A」
           --  ┌── 以下 29 行为原六·决策层，逐字留档（D-14b 斧正前），可原样恢复 ──┐
           -- -- 六·决策层（HF9f · 详见档头【HF9f 变更说明】；本段两版逐字同一）
           -- NTILE(5) OVER (ORDER BY e.stake) AS vip_tier,                                                        -- 窗口取值：相对刻度 B 族，全体五等分；须连同下方血统五元组一并解读，禁作硬阈值判型
           -- PERCENT_RANK() OVER (ORDER BY -e.net-e.rebate-e.agent_cost)    AS economic_value,                    -- 窗口取值：HF9f·F-19 修正 —— HF9e 写作 -(-…) 双负号致方向颠倒（#075 实测 corr(economic_value, residual_b) = -1.0000）；今与 action_priority 排序键归一，值大即平台真净利高
           -- PERCENT_RANK() OVER (ORDER BY e.net/NULLIF(e.stake,0))         AS roi_pr_global,                     -- 窗口取值：HF9f·F-17 正名 —— 本列实为 ROI（玩家净回报率）之全体百分位，与「风险」无关；旧名 risk_value 见下一行
           -- PERCENT_RANK() OVER (ORDER BY e.net/NULLIF(e.stake,0))         AS risk_value,                        -- 窗口取值：兼容列，恒等于 roi_pr_global，仅为下游迁移窗保留；HF9g 起废弃，禁新引用
           -- PERCENT_RANK() OVER (ORDER BY e.stake)                         AS pr_stake,                          -- 窗口取值：兼容列，恒等于 pr_global，原名保留以免断链
           -- PERCENT_RANK() OVER (ORDER BY e.stake)                         AS pr_global,                         -- 窗口取值：HF9f·F-1 双轨之一 —— 全体口径百分位，参照总体即本件全部输出行
           -- CASE WHEN e.n_rounds >= 30                                                                           -- 条件分支：起始分支 —— 仅在合格子集内计算合格口径百分位
           -- THEN PERCENT_RANK() OVER (PARTITION BY CASE WHEN e.n_rounds >= 30 THEN 1 ELSE 0 END ORDER BY e.stake)  -- 分支取值：以合格与否分区，故本值即 n_rounds>=30 子集内之百分位
           -- ELSE NULL END                                             AS pr_qualified,                      -- 条件分支：收束上方分支 —— 不合格者留 NULL（NULL＝未测，非 0），产出「pr_qualified」
           -- 'n_rounds>=30'                                                 AS pr_qualified_population,           -- 字面取值：血统 —— 合格子集之定义
           -- COUNT(*) OVER ()                                               AS pr_global_population_n,            -- 窗口取值：血统 —— 全体口径之参照总体规模，渲染时现算，禁写死
           -- SUM(CASE WHEN e.n_rounds >= 30 THEN 1 ELSE 0 END) OVER ()      AS pr_qualified_population_n,         -- 窗口取值：血统 —— 合格子集之参照总体规模，现算，禁写死
           -- 'PERCENT_RANK_OVER_ORDER_BY_e_stake'                           AS pr_calculation_method,             -- 字面取值：血统 —— 算法标识
           -- 'HF9f'                                                         AS pr_calculation_version,            -- 字面取值：血统 —— 算法版本
           -- CASE WHEN e.n_rounds IS NULL OR e.n_rounds < 30 THEN 'THIN_ROUNDS' ELSE 'OK' END AS evidence_flag,   -- 条件分支：HF9f·F-2a 证据旗标 —— THIN_ROUNDS 者禁入执行队列，仅入观察队列
           -- CASE WHEN e.n_rounds IS NULL       THEN NULL                                                         -- 条件分支：起始分支 —— 未测者留 NULL（自家铁律：NULL ≠ 0）
           -- WHEN e.n_rounds >= 31483      THEN 'L1_POWERED'                                                 -- 分支判定：MDE 反解第一档
           -- WHEN e.n_rounds >= 15409      THEN 'L2_CI_1P5'                                                  -- 分支判定：MDE 反解第二档
           -- WHEN e.n_rounds >=  8668      THEN 'L3_CI_2P0'                                                  -- 分支判定：MDE 反解第三档
           -- WHEN e.n_rounds >=  3852      THEN 'L4_CI_3P0'                                                  -- 分支判定：MDE 反解第四档
           -- ELSE 'L5_INSUFFICIENT' END                                AS evidence_rate,                     -- 条件分支：收束上方 —— HF9f·F-3 证据分档，承 HF9e 前议之 MDE 反解五档，须于 F-4 敏感性实验后复核
           -- ROUND(1.96 * 0.95 / SQRT(NULLIF(CAST(e.n_rounds AS DOUBLE),0)),8) AS hold_ci_halfwidth_approx,       -- 比率表达式：HF9f·F-3 逐行现算之 95% 半宽近似；常数 0.95 为登记值，本轮 #075 实测每局 ROI 隐含 σ 于最薄层为 0.9249，二者差异待 F-4 裁定
           -- CASE WHEN e.stake IS NULL OR e.stake<=0 OR e.n_bets<30 OR e.n_rounds IS NULL OR e.n_rounds<30 THEN 'Z 证据不足 · 不动作'  -- 条件分支：HF9f·F-2 双条件取严 —— HF9e 仅卡 e.n_bets<30，致 n_bets>=30 而 n_rounds<30 者绕过 Z（#075 实测 18,537 名，其中 8,145 名已入 A/D 待裁）；今两条件并列取严
           -- WHEN PERCENT_RANK() OVER (ORDER BY -e.net-e.rebate-e.agent_cost)<=0.10                          -- 分支判定：平台真净利之最低十分位
           -- THEN 'A 净亏最大十分位 · 优先复核'                                                             -- 分支取值：HF9f·F-20 正名 —— 本档 Σresidual_b 于 #075 实测 = -100,236,896，系平台净亏最大群，旧名「残值最低十分位 · 待裁」名实不符
           -- WHEN PERCENT_RANK() OVER (ORDER BY -e.net-e.rebate-e.agent_cost)>=0.80                          -- 分支判定：平台真净利之最高二十分位
           -- THEN 'D 净利最高二十分位 · 优先留存'                                                           -- 分支取值：HF9f·F-20 正名 —— 本档 Σresidual_b 于 #075 实测 = +281,733,190，系核心利润源；与 A 档方向相反，旧版同标「待裁」属名实不符
           -- ELSE 'E 常规' END                                          AS action_priority                   -- 条件分支：收束上方判词，产出「action_priority」
           --  └────────────────────────────────────────────────────────────────┘
    FROM q
    LEFT JOIN x_agg e ON CAST(e.x_key AS STRING) = CAST(q.`uid` AS STRING)
  ) y
) z
-- ── 逐批 WHERE 阶梯（★ 口诀：上界 ＝ 下界 ＋ 100000，两数同进）──
--    本件 T_true 未测，无需先跑 T_true；以 0 / 100000 控制本批返回区间，末批由实际行数 < 100000 判定
--    WHERE z.audit_rn >        0 AND z.audit_rn <=   100000   -- 第 1 批
--    WHERE z.audit_rn >   100000 AND z.audit_rn <=   200000   -- 第 2 批
--    WHERE z.audit_rn >   200000 AND z.audit_rn <=   300000   -- 第 3 批
--    WHERE z.audit_rn >   300000 AND z.audit_rn <=   400000   -- 第 4 批
--    WHERE z.audit_rn >   400000 AND z.audit_rn <=   500000   -- 第 5 批
--    WHERE z.audit_rn >   500000 AND z.audit_rn <=   600000   -- 第 6 批
--    WHERE z.audit_rn >   600000 AND z.audit_rn <=   700000   -- 第 7 批
--    …余批类推。第 k 批：WHERE z.audit_rn > (k-1)*100000 AND z.audit_rn <= k*100000
--    某批返回 < 100000 行即为末批，其后不再取。
--
--    ⚠ 常见误写（务必避开）：只推下界而上界不动 ——
--        WHERE z.audit_rn > 100000 AND z.audit_rn <= 100000   ← 自相矛盾，恒为假，返回空集
--        WHERE z.audit_rn > 200000 AND z.audit_rn <= 100000   ← 同上，空集
--      两个数必须**同时**前进，且始终相差 100000。
--      下界 ＝ 上一批之上界；上界 ＝ 本批之上界。
WHERE z.audit_rn > 0 AND z.audit_rn <= 100000 -- ★ HF9c 本批区间
ORDER BY z.audit_rn;


-- ══════════════════════════════════════════════════════════════════════════════════════════════
--  72. R03chk_settlement_form.csv   [总包行 4684~4723 · 原 6 列 ＋六层约 60 列]
--     典型学：M07 荷官关联　派生旗标：recent（s.x_rec = 1 · 仅供 CASE 条件聚合，全包无任何 WHERE/AND/HAVING 以此过滤）　连接：q.`bet_side`
-- ══════════════════════════════════════════════════════════════════════════════════════════════
-- ── ① 先跑 T_true 留档（不足 100000 者一次导全，不必分批）──
-- ── ① T_true：HF9c 不再强制预跑完整 COUNT。
--    本批实际返回行数 < 100000 即判定为末批；全批完成后以各批 n_rows / audit_rn 范围核对总量。

-- ── ② 分批取数：第 1 批。第 k 批只改末行两数为 (k-1)*100000 与 k*100000 ──
--    审计字段二（REDTEAM 2026-08-24 裁定 · 四锁）：
--      audit_rn  全局观测坐标 —— 由**与原版审计版逐字同一**之排序键所生，两版可逐行对账
--      batch_id  物理分批信息 —— 该行所属批次，由 audit_rn 算得，非引擎所赋
--    ★ 锁三：二者皆为审计字段，**不得进入任何业务指标计算**。
--    ★ 锁四：两版经 audit_rn 逐行字段核验后，方可宣布输出完全一致。

-- ── ③ 每批取回后自证四数（任一不符即停手回报，禁止放行）──
--    n_rows        = COUNT(*)      须等于 COUNT(DISTINCT audit_rn)   （批内无重复）
--    audit_rn_min  = MIN(audit_rn) 须等于 (k-1)*100000 + 1           （与上批严丝合缝）
--    audit_rn_max  = MAX(audit_rn) 须等于 min + n_rows - 1           （批内无缺口）
--    全批取毕再验：各批 audit_rn 之并集 = 1 .. T_true，无缺号、无重号。
--     ★ 首行＝平台真净亏最多者（已扣退水与代理占成）。
--
SELECT z.*,
       CAST(FLOOR((z.audit_rn - 1) / 100000) + 1 AS INT)          AS batch_id,
       'A168_HF9F_20260827_0900' AS run_id,
       '2026-08-27 09:00:00' AS snapshot_sync_time
FROM (
  SELECT y.*,
         ROW_NUMBER() OVER (ORDER BY y.`residual_b` ASC, y.`roi` DESC, y.`bet_side`, y.`n_rounds`, y.`n_push`, y.`push_rate`, y.`p_base_dnb`, y.`p_base_incl`) AS audit_rn
  FROM (
    WITH
      x_ranked AS (
    SELECT b.bet01, b.bet03, b.bet04, b.bet05, b.bet09, b.bet11, b.bet13,
           b.bet15, b.bet16, b.bet17, b.bet18, b.bet19, b.bet20, b.bet21,
           b.bet22, b.bet23, b.bet24, b.bet25, b.bet26, b.bet27, b.bet38, b.bet39, b.category, b.commission,
           b.dt, b.eid, b.ip, b.validbet, b.updatetime, b.sync_time,
           ROW_NUMBER() OVER (
             PARTITION BY b.bet01
             ORDER BY b.updatetime DESC, b.sync_time DESC, b.dt DESC)      AS x_rn
    FROM ods_mariadb_2b.ods_a168_bet02 b
    WHERE b.dt >= '2026-03-21' AND b.dt < '2026-08-07'
      AND b.bet02 = '101'
      AND b.sync_time <= '2026-08-27 09:00:00'
  ),
    x_testagent AS (
    SELECT age001 AS agent_id FROM ods_mariadb_2b.ods_a168_agent WHERE age022 = '1'
  ),
    x_bs0 AS (
    SELECT b.bet05 AS x_member, b.eid AS x_dealer, b.bet39 AS x_table,
           b.bet03 AS x_shoe, b.ip AS x_ip, b.bet09 AS x_product, b.dt AS x_date,
           CONCAT_WS('|', b.bet03, b.bet04, b.bet39)                      AS x_round,
           CONCAT_WS('|', b.bet39, b.bet03)                               AS x_tblshoe,
           CAST(NULLIF(TRIM(b.bet04),'') AS INT)                          AS x_rno,
           CASE WHEN b.dt >= '2026-07-08' THEN 1 ELSE 0 END               AS x_rec,
           CASE WHEN TRIM(b.commission)='1' THEN 1 ELSE 0 END             AS x_freecomm,
           CAST(NULLIF(TRIM(b.bet13),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_stake,
           CAST(NULLIF(TRIM(b.validbet),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_valid,
           CAST(NULLIF(TRIM(b.bet16),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_rebate,
           CAST(NULLIF(TRIM(b.bet17),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_net,
           CAST(NULLIF(TRIM(b.bet15),'') AS DECIMAL(20,6))                AS x_rbpct,
           COALESCE(CAST(NULLIF(TRIM(b.bet23),'') AS DECIMAL(20,6)),0)   AS x_agpct,
          NULLIF(CAST(NULLIF(TRIM(b.bet23),'') AS DECIMAL(20,6)),0)     AS x_rate1,
          NULLIF(CAST(NULLIF(TRIM(b.bet24),'') AS DECIMAL(20,6)),0)     AS x_rate2,
          NULLIF(CAST(NULLIF(TRIM(b.bet25),'') AS DECIMAL(20,6)),0)     AS x_rate3,
          NULLIF(CAST(NULLIF(TRIM(b.bet26),'') AS DECIMAL(20,6)),0)     AS x_rate4,
          NULLIF(CAST(NULLIF(TRIM(b.bet27),'') AS DECIMAL(20,6)),0)     AS x_rate5,
          (CASE WHEN NULLIF(CAST(NULLIF(TRIM(b.bet22),'') AS BIGINT),0) IS NOT NULL THEN 5
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet21),'') AS BIGINT),0) IS NOT NULL THEN 4
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet20),'') AS BIGINT),0) IS NOT NULL THEN 3
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet19),'') AS BIGINT),0) IS NOT NULL THEN 2
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet18),'') AS BIGINT),0) IS NOT NULL THEN 1
                ELSE 0 END)                                             AS x_chain_depth,
           CASE WHEN COALESCE(t1.agent_id,t2.agent_id,t3.agent_id,
                              t4.agent_id,t5.agent_id) IS NOT NULL
                THEN 1 ELSE 0 END                                        AS f_testline
    FROM x_ranked b
    LEFT JOIN x_testagent t1 ON t1.agent_id = b.bet18
    LEFT JOIN x_testagent t2 ON t2.agent_id = b.bet19
    LEFT JOIN x_testagent t3 ON t3.agent_id = b.bet20
    LEFT JOIN x_testagent t4 ON t4.agent_id = b.bet21
    LEFT JOIN x_testagent t5 ON t5.agent_id = b.bet22
    WHERE b.x_rn = 1
      AND b.category='1' AND UPPER(TRIM(b.bet38))='N'
      AND CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8)) > 0
  ),
  x_mk AS (
    SELECT s.*,
           CASE WHEN s.f_testline = 0 THEN 1 ELSE 0 END                 AS is_clean
    FROM x_bs0 s
  ),
  x_agg AS (
    SELECT s.x_product                                                        AS x_key,
           COUNT(*) AS n_bets, COUNT(DISTINCT s.x_round) AS n_rounds,
           COUNT(DISTINCT s.x_date) AS active_days, COUNT(DISTINCT s.x_tblshoe) AS active_shoes,
           COUNT(DISTINCT CONCAT_WS('|', s.x_date, s.x_table)) AS active_sessions,
           COUNT(DISTINCT s.x_table) AS n_tables, COUNT(DISTINCT s.x_dealer) AS n_dealers,
           COUNT(DISTINCT s.x_ip) AS n_ips, COUNT(DISTINCT s.x_product) AS n_products,
           MIN(s.x_date) AS first_seen_d, MAX(s.x_date) AS last_seen_d,
           SUM(s.x_stake) AS stake, SUM(s.x_valid) AS valid, SUM(s.x_rebate) AS rebate,
           SUM(s.x_net) AS net, SUM(-s.x_net *(100.0-s.x_agpct)/100.0) AS agent_cost,
           AVG(100.0-s.x_agpct)                   AS agent_pct,
           AVG(s.x_agpct)                         AS company_retain_pct,
           SUM(-s.x_net *s.x_agpct/100.0)         AS agent_cost_a_legacy,
           SUM(s.x_valid*s.x_agpct/100.0)         AS agent_cost_valid_base_legacy,
          AVG(COALESCE(s.x_rate1,100)) AS retain_pct_lv1, AVG(COALESCE(s.x_rate2,100)) AS retain_pct_lv2,
          AVG(COALESCE(s.x_rate3,100)) AS retain_pct_lv3, AVG(COALESCE(s.x_rate4,100)) AS retain_pct_lv4,
          AVG(COALESCE(s.x_rate5,100)) AS retain_pct_lv5, AVG(s.x_chain_depth) AS chain_depth_avg,
          AVG(COALESCE(100.0-s.x_rate1,0)) AS agent_pct_lv1, AVG(COALESCE(100.0-s.x_rate2,0)) AS agent_pct_lv2,
          AVG(COALESCE(100.0-s.x_rate3,0)) AS agent_pct_lv3, AVG(COALESCE(100.0-s.x_rate4,0)) AS agent_pct_lv4,
          AVG(COALESCE(100.0-s.x_rate5,0)) AS agent_pct_lv5,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate1,0)/100.0)                        AS agent_cost_lv1,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate2,0)/100.0)                        AS agent_cost_lv2,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate3,0)/100.0)                        AS agent_cost_lv3,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate4,0)/100.0)                        AS agent_cost_lv4,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate5,0)/100.0)                        AS agent_cost_lv5,
          SUM(-s.x_net*(COALESCE(100.0-s.x_rate1,0)+COALESCE(100.0-s.x_rate2,0)
                       +COALESCE(100.0-s.x_rate3,0)+COALESCE(100.0-s.x_rate4,0)
                       +COALESCE(100.0-s.x_rate5,0))/100.0)                   AS agent_cost_chain_additive,
          SUM(-s.x_net*(1.0 - CAST(COALESCE(s.x_rate1,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate2,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate3,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate4,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate5,100) AS DOUBLE)/100.0))
                                                                       AS agent_cost_chain_nested,
           AVG(s.x_rbpct) AS rbpct, AVG(s.x_freecomm*1.0) AS freecomm_rate,
           PERCENTILE_APPROX(s.x_stake,0.25) AS p25, PERCENTILE_APPROX(s.x_stake,0.50) AS p50,
           PERCENTILE_APPROX(s.x_stake,0.75) AS p75, PERCENTILE_APPROX(s.x_stake,0.90) AS p90,
           PERCENTILE_APPROX(s.x_stake,0.95) AS p95, PERCENTILE_APPROX(s.x_stake,0.99) AS p99,
           PERCENTILE_APPROX(s.x_valid,0.50) AS p50_valid,
           PERCENTILE_APPROX(s.x_net,0.50)   AS p50_profit,
           SUM(CASE WHEN s.x_rec = 1 THEN s.x_stake ELSE 0 END) AS st_in,
           SUM(CASE WHEN s.x_rec = 1 THEN 1 ELSE 0 END)         AS nb_in,
           SUM(CASE WHEN s.x_rec = 1 THEN s.x_net ELSE 0 END)   AS net_in,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN s.x_stake ELSE 0 END) AS st_out,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN 1 ELSE 0 END)         AS nb_out,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN s.x_net ELSE 0 END)   AS net_out,
           SUM(CASE WHEN s.x_rec=1 THEN s.x_stake ELSE 0 END) AS st_rec,
           SUM(CASE WHEN s.x_rec=1 THEN 1 ELSE 0 END)         AS nb_rec
    FROM x_mk s
    WHERE s.is_clean = 1
      AND s.x_product IS NOT NULL AND TRIM(CAST(s.x_product AS STRING)) <> ''
    GROUP BY s.x_product
  ),
      q AS (
        WITH ranked AS (                                                                                    -- 公共表表达式：开启中间结果集 ranked——口径与 §R03 逐字一致，便于对照（§R03-chk）
          SELECT b.bet01, b.bet03, b.bet04, b.bet39, b.bet05, b.bet09,                                      -- 取列：起始取列子句，涉 bet03（靴号）、bet04（局内序号）、bet39（桌号）、bet05（会员号）、bet09（玩法）
                 b.bet11, b.bet13, b.bet14, b.bet38, b.eid,                                                 -- 续行：接续上一取列子句，涉 bet11（汇率）、bet13（下注金额）、bet14（派彩金额）、bet38（重對）
                 ROW_NUMBER() OVER (                                                                        -- 行号窗口表达式：以行号窗口取每注最终态，免修订滞后造成重复
                   PARTITION BY b.bet01                                                                     -- 窗口分区：按 b.bet01 分组开窗，组内各自编号
                   ORDER BY b.updatetime DESC, b.sync_time DESC, b.dt DESC) AS rn                           -- 排序：取最新一版，产出「rn」
          FROM ods_mariadb_2b.ods_a168_bet02 b                                                              -- 取数来源：取自注单明细表（金额与行为口径的第一料源）
          WHERE b.dt >= '2026-03-21' AND b.dt < '2026-08-07'                                                -- 过滤条件：限定 E1 全局窗，涉 dt（营业日）
            AND b.bet02 = '101'
      AND b.sync_time <= '2026-08-27 09:00:00' AND b.category = '1'                                                        -- 并列条件：限定百家乐产品大类，涉 bet02（游戏类别）
        ),                                                                                                  -- 续行：收束上方的子查询或函数括号（§R03-chk）
        base AS (                                                                                           -- 公共表表达式：开启中间结果集 base——有效注单，与 §R03 同口径（§R03-chk）
          SELECT r.bet05 AS member_id, r.eid AS dealer_id, r.bet09 AS bet_side,                             -- 取列：起始取列子句，涉 bet05（会员号）、eid（荷官工号）、bet09（玩法）
                 CONCAT_WS('|', r.bet03, r.bet04, r.bet39) AS round_key,                                    -- 取值表达式：三键拼物理局键，产出「round_key」
                 (CAST(NULLIF(TRIM(r.bet14),'') AS DECIMAL(20,4))                                           -- 取值表达式：派彩额起算，涉 bet14（派彩金额）
                  - CAST(NULLIF(TRIM(r.bet13),'') AS DECIMAL(20,4)))                                        -- 续行：减投注额得游戏净输赢，涉 bet13（下注金额）
                  / CAST(NULLIF(TRIM(r.bet11),'') AS DECIMAL(20,8)) AS game_pnl                             -- 续行：折汇率归一，产出「game_pnl」——恰为 0 即退还局
          FROM ranked r                                                                                     -- 取数来源：取自本条自建的中间结果集 ranked
          WHERE r.rn = 1                                                                                    -- 过滤条件：限定 r.rn等于 1，只取每注最终态
            AND UPPER(TRIM(r.bet38)) = 'N'                                                                  -- 并列条件：剔除测试注单，涉 bet38（重對）
            AND CAST(NULLIF(TRIM(r.bet05),'') AS BIGINT) > 0                                                -- 并列条件：剔除无效会员号，涉 bet05（会员号）
            AND CAST(NULLIF(TRIM(r.bet11),'') AS DECIMAL(20,8)) > 0                                         -- 并列条件：汇率须为正，涉 bet11（汇率）
            AND UPPER(TRIM(r.bet09)) NOT LIKE 'TIP\_1\_%'                                                 -- 并列条件：排除小费单，涉 bet09（玩法）
        ),                                                                                                  -- 续行：收束上方的子查询或函数括号（§R03-chk）
        pr AS (                                                                                             -- 公共表表达式：开启中间结果集 pr——同局拆单先折叠，与 §R03 同法（§R03-chk）
          SELECT member_id, dealer_id, bet_side, round_key,                                                 -- 取列：起始取列子句，本行先列四键
                 SUM(game_pnl) AS game_pnl                                                                  -- 聚合：局内合计游戏净输赢，产出「game_pnl」
          FROM base GROUP BY member_id, dealer_id, bet_side, round_key                                      -- 分组：按会员×荷官×玩法×物理局汇总
        )                                                                                                   -- 续行：收束上方的子查询或函数括号（§R03-chk）
        SELECT  UPPER(TRIM(bet_side))                          AS bet_side,                                 -- 取列：起始取列子句，本行先取「bet_side」——逐投注产品分列
                COUNT(*)                                       AS n_rounds,                                 -- 聚合：该产品的总局数，产出「n_rounds」
                SUM(CASE WHEN game_pnl = 0 THEN 1 ELSE 0 END)  AS n_push,                                   -- 聚合：退还局数（game_pnl 恰为 0），产出「n_push」——DNB 的直接证据
                SUM(CASE WHEN game_pnl = 0 THEN 1 ELSE 0 END) * 1.0                                         -- 除法或乘法计算：退还局占比起算
                  / NULLIF(COUNT(*), 0)                        AS push_rate,                                -- 续行：除以总局数，产出「push_rate」——庄闲应约 9.5%，押和与边注应近 0
                SUM(CASE WHEN game_pnl > 0 THEN 1 ELSE 0 END) * 1.0                                         -- 除法或乘法计算：决胜局基准起算
                  / NULLIF(SUM(CASE WHEN game_pnl <> 0 THEN 1 ELSE 0 END), 0) AS p_base_dnb,                -- 续行：分母取决胜局，产出「p_base_dnb」——报告 Z 分数所用之基，庄应约 50.7%
                SUM(CASE WHEN game_pnl > 0 THEN 1 ELSE 0 END) * 1.0                                         -- 除法或乘法计算：无条件基准起算
                  / NULLIF(COUNT(*), 0)                        AS p_base_incl                               -- 续行：分母取全部局，产出「p_base_incl」——庄家优势所用之基，庄应约 45.9%
        FROM    pr                                                                                          -- 取数来源：取自本条自建的中间结果集 pr
        GROUP BY UPPER(TRIM(bet_side))                                                                      -- 分组：按投注产品汇总——23 种各出一行
      )
    SELECT q.*,
           -- 一·经济层
           ROUND(e.stake,4) AS stake, ROUND(e.valid,4) AS valid_bet,
           ROUND(-e.net,4) AS profit, e.n_bets, e.n_rounds AS n_rounds_xagg,
           ROUND(e.net/NULLIF(e.stake,0),8) AS roi,
           ROUND(e.net_in/NULLIF(e.st_in,0),8) AS roi_recent,
           ROUND(e.net_out/NULLIF(e.st_out,0),8) AS roi_non_recent,
           ROUND((e.net-e.rebate)/NULLIF(e.stake,0),8) AS roi_ex_rebate,
           ROUND(e.net,4) AS roi_numerator, ROUND(e.stake,4) AS roi_denominator,
           CASE WHEN e.stake IS NULL THEN 'NULL_DENOM' WHEN e.stake<=0 THEN 'ZERO_DENOM'
                WHEN e.n_bets<30 THEN 'THIN_EXPOSURE' ELSE 'OK' END AS roi_denominator_status,
           ROUND(e.rebate,4) AS rebate_cost, ROUND(e.agent_cost,4)                           AS cost_complement_b,
       ROUND(e.agent_pct,4)                            AS pct_complement,
       ROUND(e.company_retain_pct,4)                   AS pct_top_bet23,
       'AG03-UNRESOLVED'                                     AS agent_formula_version,
      'ALL5_LEVELS_bet23_to_bet27'                    AS agent_level_scope,
      ROUND(e.agent_cost_lv1,4) AS agent_cost_lv1, ROUND(e.agent_cost_lv2,4) AS agent_cost_lv2,
      ROUND(e.agent_cost_lv3,4) AS agent_cost_lv3, ROUND(e.agent_cost_lv4,4) AS agent_cost_lv4,
      ROUND(e.agent_cost_lv5,4) AS agent_cost_lv5,
      ROUND(e.agent_pct_lv1,6) AS agent_pct_lv1, ROUND(e.agent_pct_lv2,6) AS agent_pct_lv2,
      ROUND(e.agent_pct_lv3,6) AS agent_pct_lv3, ROUND(e.agent_pct_lv4,6) AS agent_pct_lv4,
      ROUND(e.agent_pct_lv5,6) AS agent_pct_lv5,
      ROUND(e.retain_pct_lv1,6) AS retain_pct_lv1, ROUND(e.retain_pct_lv2,6) AS retain_pct_lv2,
      ROUND(e.retain_pct_lv3,6) AS retain_pct_lv3, ROUND(e.retain_pct_lv4,6) AS retain_pct_lv4,
      ROUND(e.retain_pct_lv5,6) AS retain_pct_lv5, ROUND(e.chain_depth_avg,4) AS chain_depth_avg,
      ROUND(e.agent_cost_chain_additive,4)            AS agent_cost_chain_additive,
      ROUND(e.agent_cost_chain_nested,4)              AS agent_cost_chain_nested,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_additive,4) AS residual_chain_additive,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_nested,4)   AS residual_chain_nested,
      'PENDING_AG03'                                  AS decision_status,
      'FALSE'                                         AS admit_to_risk_decision,
      'NOT_FOR_ENFORCEMENT'                           AS deliverable_class,
       ROUND(e.agent_cost_a_legacy,4)                  AS agent_cost_a_legacy,
       ROUND(e.agent_cost_valid_base_legacy,4)         AS agent_cost_valid_base_legacy,
           ROUND(-e.net-e.rebate,4)                        AS ngr,
       ROUND(-e.net-e.rebate-e.agent_cost,4)           AS residual_b,
       ROUND(-e.net-e.rebate-e.agent_cost_a_legacy,4)  AS residual_a,
           ROUND((-e.net-e.rebate)/NULLIF(e.stake,0),8)    AS ngr_rate,
       ROUND((-e.net-e.rebate-e.agent_cost)/NULLIF(e.stake,0),8)   AS residual_b_rate,
      -- 【HF9c · canonical accounting contract】
      --   以下 canonical 字段只增加明确 scope；不删除、不覆盖既有字段。
      --   formal_bet23_* 保持 HF9b 当前生产公式及其 NULL/0 语义；
      --   lv1~lv5 / additive / nested 则分别采用各自原始 e.* 成本字段，
      --   rate 一律从未舍入的 e.* 分子 / e.stake 计算，禁止由展示值反算。
      ROUND(e.agent_cost,4) AS agent_cost_bet23_formal_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost,4) AS net_margin_bet23_formal_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost)/NULLIF(e.stake,0),8) AS net_margin_bet23_formal_rate_canonical,
      ROUND(e.agent_cost_lv1,4) AS agent_cost_lv1_bet23_canonical,
      ROUND(e.agent_cost_lv2,4) AS agent_cost_lv2_bet24_canonical,
      ROUND(e.agent_cost_lv3,4) AS agent_cost_lv3_bet25_canonical,
      ROUND(e.agent_cost_lv4,4) AS agent_cost_lv4_bet26_canonical,
      ROUND(e.agent_cost_lv5,4) AS agent_cost_lv5_bet27_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_lv1,4) AS net_margin_lv1_bet23_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_lv1)/NULLIF(e.stake,0),8) AS net_margin_lv1_bet23_rate_canonical,
      ROUND(e.agent_cost_chain_additive,4) AS agent_cost_chain_additive_canonical,
      ROUND(e.agent_cost_chain_nested,4) AS agent_cost_chain_nested_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_additive,4) AS net_margin_chain_additive_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_nested,4) AS net_margin_chain_nested_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_chain_additive)/NULLIF(e.stake,0),8) AS net_margin_chain_additive_rate_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_chain_nested)/NULLIF(e.stake,0),8) AS net_margin_chain_nested_rate_canonical,
       ROUND((-e.net-e.rebate-e.agent_cost_a_legacy)/NULLIF(e.stake,0),8) AS residual_a_rate,
           -- 二·分布层
           ROUND(e.stake/NULLIF(e.n_bets,0),4) AS avg_stake_per_bet,
           ROUND(e.valid/NULLIF(e.n_rounds,0),4) AS avg_valid_bet_per_round,
           ROUND(-e.net/NULLIF(e.n_rounds,0),4) AS avg_profit_per_round,
           ROUND(-e.net/NULLIF(e.active_days,0),4) AS avg_profit_per_day,
           ROUND(-e.net/NULLIF(e.active_shoes,0),4) AS avg_profit_per_shoe,
           ROUND(e.stake/NULLIF(e.active_days,0),4) AS avg_stake_per_active_day,
           ROUND(e.n_rounds*1.0/NULLIF(e.active_days,0),4) AS avg_rounds_per_active_day,
           ROUND(e.st_in/NULLIF(e.nb_in,0),4) AS avg_stake_recent,
           ROUND(e.st_out/NULLIF(e.nb_out,0),4) AS avg_stake_non_recent,
           ROUND(e.p25,4) AS p25_stake, ROUND(e.p50,4) AS p50_stake, ROUND(e.p75,4) AS p75_stake,
           ROUND(e.p90,4) AS p90_stake, ROUND(e.p95,4) AS p95_stake, ROUND(e.p99,4) AS p99_stake,
           ROUND(e.p50_valid,4) AS p50_valid_bet, ROUND(e.p50_profit,4) AS p50_profit,
           ROUND(e.p95/NULLIF(e.p50,0),6) AS p95_over_p50,
           ROUND(e.p99/NULLIF(e.p50,0),6) AS p99_over_p50,
           ROUND((e.stake/NULLIF(e.n_bets,0))/NULLIF(e.p50,0),6) AS avg_over_p50,
           -- 三·关系层
           e.n_tables AS common_table_count, e.n_dealers AS common_dealer_count,
           e.n_ips AS common_ip_count, e.n_products AS common_product_count,
           ROUND(e.st_in/NULLIF(e.stake,0),8) AS share_recent,
           -- 四·rate 层
           ROUND(-e.net/NULLIF(e.stake,0),8) AS hold_rate,
           ROUND(-e.net_in/NULLIF(e.st_in,0),8) AS hold_rate_recent,
           ROUND(e.rebate/NULLIF(e.valid,0),8) AS rebate_rate_actual,
           ROUND(e.rbpct,6) AS rebate_pct_config,
           ROUND(e.valid/NULLIF(e.stake,0),6) AS turnover_multiple,
           ROUND(e.freecomm_rate,6) AS free_comm_rate,
           ROUND(e.net_in/NULLIF(e.st_in,0)-e.net_out/NULLIF(e.st_out,0),8) AS roi_delta_recent,
           -- 五·动态层
           e.first_seen_d AS first_seen, e.last_seen_d AS last_seen,
           e.active_days, e.active_shoes, e.active_sessions,
           DATEDIFF(e.last_seen_d, e.first_seen_d)+1 AS span_days,
           ROUND(e.active_days*1.0/NULLIF(DATEDIFF(e.last_seen_d,e.first_seen_d)+1,0),6) AS persistence,
           ROUND((e.st_in/NULLIF(e.nb_in,0))/NULLIF(e.st_out/NULLIF(e.nb_out,0),0),6) AS ramp_recent_vs_prior,
           ROUND((e.st_rec/NULLIF(e.nb_rec,0))/NULLIF(e.stake/NULLIF(e.n_bets,0),0),6) AS ramp_recent_vs_all,
           ROUND((e.st_rec/NULLIF(e.stake,0))/0.30,6) AS stake_ramp,
           -- 六·决策层（HF9f · 详见档头【HF9f 变更说明】；本段两版逐字同一）
           NTILE(5) OVER (ORDER BY e.stake) AS vip_tier,                                                        -- 窗口取值：相对刻度 B 族，全体五等分；须连同下方血统五元组一并解读，禁作硬阈值判型
           PERCENT_RANK() OVER (ORDER BY -e.net-e.rebate-e.agent_cost)    AS economic_value,                    -- 窗口取值：HF9f·F-19 修正 —— HF9e 写作 -(-…) 双负号致方向颠倒（#075 实测 corr(economic_value, residual_b) = -1.0000）；今与 action_priority 排序键归一，值大即平台真净利高
           PERCENT_RANK() OVER (ORDER BY e.net/NULLIF(e.stake,0))         AS roi_pr_global,                     -- 窗口取值：HF9f·F-17 正名 —— 本列实为 ROI（玩家净回报率）之全体百分位，与「风险」无关；旧名 risk_value 见下一行
           PERCENT_RANK() OVER (ORDER BY e.net/NULLIF(e.stake,0))         AS risk_value,                        -- 窗口取值：兼容列，恒等于 roi_pr_global，仅为下游迁移窗保留；HF9g 起废弃，禁新引用
           PERCENT_RANK() OVER (ORDER BY e.stake)                         AS pr_stake,                          -- 窗口取值：兼容列，恒等于 pr_global，原名保留以免断链
           PERCENT_RANK() OVER (ORDER BY e.stake)                         AS pr_global,                         -- 窗口取值：HF9f·F-1 双轨之一 —— 全体口径百分位，参照总体即本件全部输出行
           CASE WHEN e.n_rounds >= 30                                                                           -- 条件分支：起始分支 —— 仅在合格子集内计算合格口径百分位
                  THEN PERCENT_RANK() OVER (PARTITION BY CASE WHEN e.n_rounds >= 30 THEN 1 ELSE 0 END ORDER BY e.stake)  -- 分支取值：以合格与否分区，故本值即 n_rounds>=30 子集内之百分位
                ELSE NULL END                                             AS pr_qualified,                      -- 条件分支：收束上方分支 —— 不合格者留 NULL（NULL＝未测，非 0），产出「pr_qualified」
           'n_rounds>=30'                                                 AS pr_qualified_population,           -- 字面取值：血统 —— 合格子集之定义
           COUNT(*) OVER ()                                               AS pr_global_population_n,            -- 窗口取值：血统 —— 全体口径之参照总体规模，渲染时现算，禁写死
           SUM(CASE WHEN e.n_rounds >= 30 THEN 1 ELSE 0 END) OVER ()      AS pr_qualified_population_n,         -- 窗口取值：血统 —— 合格子集之参照总体规模，现算，禁写死
           'PERCENT_RANK_OVER_ORDER_BY_e_stake'                           AS pr_calculation_method,             -- 字面取值：血统 —— 算法标识
           'HF9f'                                                         AS pr_calculation_version,            -- 字面取值：血统 —— 算法版本
           CASE WHEN e.n_rounds IS NULL OR e.n_rounds < 30 THEN 'THIN_ROUNDS' ELSE 'OK' END AS evidence_flag,   -- 条件分支：HF9f·F-2a 证据旗标 —— THIN_ROUNDS 者禁入执行队列，仅入观察队列
           CASE WHEN e.n_rounds IS NULL       THEN NULL                                                         -- 条件分支：起始分支 —— 未测者留 NULL（自家铁律：NULL ≠ 0）
                WHEN e.n_rounds >= 31483      THEN 'L1_POWERED'                                                 -- 分支判定：MDE 反解第一档
                WHEN e.n_rounds >= 15409      THEN 'L2_CI_1P5'                                                  -- 分支判定：MDE 反解第二档
                WHEN e.n_rounds >=  8668      THEN 'L3_CI_2P0'                                                  -- 分支判定：MDE 反解第三档
                WHEN e.n_rounds >=  3852      THEN 'L4_CI_3P0'                                                  -- 分支判定：MDE 反解第四档
                ELSE 'L5_INSUFFICIENT' END                                AS evidence_rate,                     -- 条件分支：收束上方 —— HF9f·F-3 证据分档，承 HF9e 前议之 MDE 反解五档，须于 F-4 敏感性实验后复核
           ROUND(1.96 * 0.95 / SQRT(NULLIF(CAST(e.n_rounds AS DOUBLE),0)),8) AS hold_ci_halfwidth_approx,       -- 比率表达式：HF9f·F-3 逐行现算之 95% 半宽近似；常数 0.95 为登记值，本轮 #075 实测每局 ROI 隐含 σ 于最薄层为 0.9249，二者差异待 F-4 裁定
           CASE WHEN e.stake IS NULL OR e.stake<=0 OR e.n_bets<30 OR e.n_rounds IS NULL OR e.n_rounds<30 THEN 'Z 证据不足 · 不动作'  -- 条件分支：HF9f·F-2 双条件取严 —— HF9e 仅卡 e.n_bets<30，致 n_bets>=30 而 n_rounds<30 者绕过 Z（#075 实测 18,537 名，其中 8,145 名已入 A/D 待裁）；今两条件并列取严
                WHEN PERCENT_RANK() OVER (ORDER BY -e.net-e.rebate-e.agent_cost)<=0.10                          -- 分支判定：平台真净利之最低十分位
                  THEN 'A 净亏最大十分位 · 优先复核'                                                             -- 分支取值：HF9f·F-20 正名 —— 本档 Σresidual_b 于 #075 实测 = -100,236,896，系平台净亏最大群，旧名「残值最低十分位 · 待裁」名实不符
                WHEN PERCENT_RANK() OVER (ORDER BY -e.net-e.rebate-e.agent_cost)>=0.80                          -- 分支判定：平台真净利之最高二十分位
                  THEN 'D 净利最高二十分位 · 优先留存'                                                           -- 分支取值：HF9f·F-20 正名 —— 本档 Σresidual_b 于 #075 实测 = +281,733,190，系核心利润源；与 A 档方向相反，旧版同标「待裁」属名实不符
                ELSE 'E 常规' END                                          AS action_priority                   -- 条件分支：收束上方判词，产出「action_priority」
    FROM q
    LEFT JOIN x_agg e ON CAST(e.x_key AS STRING) = CAST(q.`bet_side` AS STRING)
  ) y
) z
-- ── 逐批 WHERE 阶梯（★ 口诀：上界 ＝ 下界 ＋ 100000，两数同进）──
--    本件 T_true 未测，无需先跑 T_true；以 0 / 100000 控制本批返回区间，末批由实际行数 < 100000 判定
--    WHERE z.audit_rn >        0 AND z.audit_rn <=   100000   -- 第 1 批
--    WHERE z.audit_rn >   100000 AND z.audit_rn <=   200000   -- 第 2 批
--    WHERE z.audit_rn >   200000 AND z.audit_rn <=   300000   -- 第 3 批
--    WHERE z.audit_rn >   300000 AND z.audit_rn <=   400000   -- 第 4 批
--    WHERE z.audit_rn >   400000 AND z.audit_rn <=   500000   -- 第 5 批
--    WHERE z.audit_rn >   500000 AND z.audit_rn <=   600000   -- 第 6 批
--    WHERE z.audit_rn >   600000 AND z.audit_rn <=   700000   -- 第 7 批
--    …余批类推。第 k 批：WHERE z.audit_rn > (k-1)*100000 AND z.audit_rn <= k*100000
--    某批返回 < 100000 行即为末批，其后不再取。
--
--    ⚠ 常见误写（务必避开）：只推下界而上界不动 ——
--        WHERE z.audit_rn > 100000 AND z.audit_rn <= 100000   ← 自相矛盾，恒为假，返回空集
--        WHERE z.audit_rn > 200000 AND z.audit_rn <= 100000   ← 同上，空集
--      两个数必须**同时**前进，且始终相差 100000。
--      下界 ＝ 上一批之上界；上界 ＝ 本批之上界。
WHERE z.audit_rn > 0 AND z.audit_rn <= 100000 -- ★ HF9c 本批区间
ORDER BY z.audit_rn;


-- ══════════════════════════════════════════════════════════════════════════════════════════════
--  73. R03inv_pair_census.csv   [总包行 4745~4796 · 原 6 列 ＋六层约 60 列]
--     典型学：M07 荷官关联　派生旗标：recent（s.x_rec = 1 · 仅供 CASE 条件聚合，全包无任何 WHERE/AND/HAVING 以此过滤）　连接：全窗基线
-- ══════════════════════════════════════════════════════════════════════════════════════════════
-- ★ W-64 · D-14 警示（本件属 x_win 族 · 66 件之一 · 详见 §Z 段 D-14 全案）
--   本件以 `CROSS JOIN x_win e` 接入全局基线，x_win 无 GROUP BY ⇒ 恒 1 行 ⇒ e.* 全行同值。
--   故：economic_value / roi_pr_global / risk_value / pr_stake / pr_global 恒为 0；
--       action_priority 每一行皆为「A 净亏最大十分位 · 优先复核」（Z 分支永不触发）；
--       evidence_rate 恒为最高档；vip_tier 由常数键分档 ⇒ 无信息且非确定。
--   ⇒ 本件决策层三列 **NOT_FOR_DECISION**，裁定前不得用于排班、抽查或汇报。
-- ── ① 先跑 T_true 留档（不足 100000 者一次导全，不必分批）──
-- ── ① T_true：HF9c 不再强制预跑完整 COUNT。
--    本批实际返回行数 < 100000 即判定为末批；全批完成后以各批 n_rows / audit_rn 范围核对总量。

-- ── ② 分批取数：第 1 批。第 k 批只改末行两数为 (k-1)*100000 与 k*100000 ──
--    审计字段二（REDTEAM 2026-08-24 裁定 · 四锁）：
--      audit_rn  全局观测坐标 —— 由**与原版审计版逐字同一**之排序键所生，两版可逐行对账
--      batch_id  物理分批信息 —— 该行所属批次，由 audit_rn 算得，非引擎所赋
--    ★ 锁三：二者皆为审计字段，**不得进入任何业务指标计算**。
--    ★ 锁四：两版经 audit_rn 逐行字段核验后，方可宣布输出完全一致。

-- ── ③ 每批取回后自证四数（任一不符即停手回报，禁止放行）──
--    n_rows        = COUNT(*)      须等于 COUNT(DISTINCT audit_rn)   （批内无重复）
--    audit_rn_min  = MIN(audit_rn) 须等于 (k-1)*100000 + 1           （与上批严丝合缝）
--    audit_rn_max  = MAX(audit_rn) 须等于 min + n_rows - 1           （批内无缺口）
--    全批取毕再验：各批 audit_rn 之并集 = 1 .. T_true，无缺号、无重号。
--     ★ 首行＝平台真净亏最多者（已扣退水与代理占成）。
--
SELECT z.*,
       CAST(FLOOR((z.audit_rn - 1) / 100000) + 1 AS INT)          AS batch_id,
       'A168_HF9F_20260827_0900' AS run_id,
       '2026-08-27 09:00:00' AS snapshot_sync_time
FROM (
  SELECT y.*,
         ROW_NUMBER() OVER (ORDER BY y.`residual_b` ASC, y.`roi` DESC, y.`eligibility_status`, y.`n_bucket`, y.`n_pairs`, y.`n_members`, y.`n_dealers`, y.`n_rounds_total`) AS audit_rn
  FROM (
    WITH
      x_ranked AS (
    SELECT b.bet01, b.bet03, b.bet04, b.bet05, b.bet09, b.bet11, b.bet13,
           b.bet15, b.bet16, b.bet17, b.bet18, b.bet19, b.bet20, b.bet21,
           b.bet22, b.bet23, b.bet24, b.bet25, b.bet26, b.bet27, b.bet38, b.bet39, b.category, b.commission,
           b.dt, b.eid, b.ip, b.validbet, b.updatetime, b.sync_time,
           ROW_NUMBER() OVER (
             PARTITION BY b.bet01
             ORDER BY b.updatetime DESC, b.sync_time DESC, b.dt DESC)      AS x_rn
    FROM ods_mariadb_2b.ods_a168_bet02 b
    WHERE b.dt >= '2026-03-21' AND b.dt < '2026-08-07'
      AND b.bet02 = '101'
      AND b.sync_time <= '2026-08-27 09:00:00'
  ),
    x_testagent AS (
    SELECT age001 AS agent_id FROM ods_mariadb_2b.ods_a168_agent WHERE age022 = '1'
  ),
    x_bs0 AS (
    SELECT b.bet05 AS x_member, b.eid AS x_dealer, b.bet39 AS x_table,
           b.bet03 AS x_shoe, b.ip AS x_ip, b.bet09 AS x_product, b.dt AS x_date,
           CONCAT_WS('|', b.bet03, b.bet04, b.bet39)                      AS x_round,
           CONCAT_WS('|', b.bet39, b.bet03)                               AS x_tblshoe,
           CAST(NULLIF(TRIM(b.bet04),'') AS INT)                          AS x_rno,
           CASE WHEN b.dt >= '2026-07-08' THEN 1 ELSE 0 END               AS x_rec,
           CASE WHEN TRIM(b.commission)='1' THEN 1 ELSE 0 END             AS x_freecomm,
           CAST(NULLIF(TRIM(b.bet13),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_stake,
           CAST(NULLIF(TRIM(b.validbet),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_valid,
           CAST(NULLIF(TRIM(b.bet16),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_rebate,
           CAST(NULLIF(TRIM(b.bet17),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_net,
           CAST(NULLIF(TRIM(b.bet15),'') AS DECIMAL(20,6))                AS x_rbpct,
           COALESCE(CAST(NULLIF(TRIM(b.bet23),'') AS DECIMAL(20,6)),0)   AS x_agpct,
          NULLIF(CAST(NULLIF(TRIM(b.bet23),'') AS DECIMAL(20,6)),0)     AS x_rate1,
          NULLIF(CAST(NULLIF(TRIM(b.bet24),'') AS DECIMAL(20,6)),0)     AS x_rate2,
          NULLIF(CAST(NULLIF(TRIM(b.bet25),'') AS DECIMAL(20,6)),0)     AS x_rate3,
          NULLIF(CAST(NULLIF(TRIM(b.bet26),'') AS DECIMAL(20,6)),0)     AS x_rate4,
          NULLIF(CAST(NULLIF(TRIM(b.bet27),'') AS DECIMAL(20,6)),0)     AS x_rate5,
          (CASE WHEN NULLIF(CAST(NULLIF(TRIM(b.bet22),'') AS BIGINT),0) IS NOT NULL THEN 5
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet21),'') AS BIGINT),0) IS NOT NULL THEN 4
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet20),'') AS BIGINT),0) IS NOT NULL THEN 3
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet19),'') AS BIGINT),0) IS NOT NULL THEN 2
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet18),'') AS BIGINT),0) IS NOT NULL THEN 1
                ELSE 0 END)                                             AS x_chain_depth,
           CASE WHEN COALESCE(t1.agent_id,t2.agent_id,t3.agent_id,
                              t4.agent_id,t5.agent_id) IS NOT NULL
                THEN 1 ELSE 0 END                                        AS f_testline
    FROM x_ranked b
    LEFT JOIN x_testagent t1 ON t1.agent_id = b.bet18
    LEFT JOIN x_testagent t2 ON t2.agent_id = b.bet19
    LEFT JOIN x_testagent t3 ON t3.agent_id = b.bet20
    LEFT JOIN x_testagent t4 ON t4.agent_id = b.bet21
    LEFT JOIN x_testagent t5 ON t5.agent_id = b.bet22
    WHERE b.x_rn = 1
      AND b.category='1' AND UPPER(TRIM(b.bet38))='N'
      AND CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8)) > 0
  ),
  x_mk AS (
    SELECT s.*,
           CASE WHEN s.f_testline = 0 THEN 1 ELSE 0 END                 AS is_clean
    FROM x_bs0 s
  ),
  x_agg AS (
    SELECT s.x_member                                                        AS x_key,
           COUNT(*) AS n_bets, COUNT(DISTINCT s.x_round) AS n_rounds,
           COUNT(DISTINCT s.x_date) AS active_days, COUNT(DISTINCT s.x_tblshoe) AS active_shoes,
           COUNT(DISTINCT CONCAT_WS('|', s.x_date, s.x_table)) AS active_sessions,
           COUNT(DISTINCT s.x_table) AS n_tables, COUNT(DISTINCT s.x_dealer) AS n_dealers,
           COUNT(DISTINCT s.x_ip) AS n_ips, COUNT(DISTINCT s.x_product) AS n_products,
           MIN(s.x_date) AS first_seen_d, MAX(s.x_date) AS last_seen_d,
           SUM(s.x_stake) AS stake, SUM(s.x_valid) AS valid, SUM(s.x_rebate) AS rebate,
           SUM(s.x_net) AS net, SUM(-s.x_net *(100.0-s.x_agpct)/100.0) AS agent_cost,
           AVG(100.0-s.x_agpct)                   AS agent_pct,
           AVG(s.x_agpct)                         AS company_retain_pct,
           SUM(-s.x_net *s.x_agpct/100.0)         AS agent_cost_a_legacy,
           SUM(s.x_valid*s.x_agpct/100.0)         AS agent_cost_valid_base_legacy,
          AVG(COALESCE(s.x_rate1,100)) AS retain_pct_lv1, AVG(COALESCE(s.x_rate2,100)) AS retain_pct_lv2,
          AVG(COALESCE(s.x_rate3,100)) AS retain_pct_lv3, AVG(COALESCE(s.x_rate4,100)) AS retain_pct_lv4,
          AVG(COALESCE(s.x_rate5,100)) AS retain_pct_lv5, AVG(s.x_chain_depth) AS chain_depth_avg,
          AVG(COALESCE(100.0-s.x_rate1,0)) AS agent_pct_lv1, AVG(COALESCE(100.0-s.x_rate2,0)) AS agent_pct_lv2,
          AVG(COALESCE(100.0-s.x_rate3,0)) AS agent_pct_lv3, AVG(COALESCE(100.0-s.x_rate4,0)) AS agent_pct_lv4,
          AVG(COALESCE(100.0-s.x_rate5,0)) AS agent_pct_lv5,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate1,0)/100.0)                        AS agent_cost_lv1,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate2,0)/100.0)                        AS agent_cost_lv2,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate3,0)/100.0)                        AS agent_cost_lv3,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate4,0)/100.0)                        AS agent_cost_lv4,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate5,0)/100.0)                        AS agent_cost_lv5,
          SUM(-s.x_net*(COALESCE(100.0-s.x_rate1,0)+COALESCE(100.0-s.x_rate2,0)
                       +COALESCE(100.0-s.x_rate3,0)+COALESCE(100.0-s.x_rate4,0)
                       +COALESCE(100.0-s.x_rate5,0))/100.0)                   AS agent_cost_chain_additive,
          SUM(-s.x_net*(1.0 - CAST(COALESCE(s.x_rate1,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate2,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate3,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate4,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate5,100) AS DOUBLE)/100.0))
                                                                       AS agent_cost_chain_nested,
           AVG(s.x_rbpct) AS rbpct, AVG(s.x_freecomm*1.0) AS freecomm_rate,
           PERCENTILE_APPROX(s.x_stake,0.25) AS p25, PERCENTILE_APPROX(s.x_stake,0.50) AS p50,
           PERCENTILE_APPROX(s.x_stake,0.75) AS p75, PERCENTILE_APPROX(s.x_stake,0.90) AS p90,
           PERCENTILE_APPROX(s.x_stake,0.95) AS p95, PERCENTILE_APPROX(s.x_stake,0.99) AS p99,
           PERCENTILE_APPROX(s.x_valid,0.50) AS p50_valid,
           PERCENTILE_APPROX(s.x_net,0.50)   AS p50_profit,
           SUM(CASE WHEN s.x_rec = 1 THEN s.x_stake ELSE 0 END) AS st_in,
           SUM(CASE WHEN s.x_rec = 1 THEN 1 ELSE 0 END)         AS nb_in,
           SUM(CASE WHEN s.x_rec = 1 THEN s.x_net ELSE 0 END)   AS net_in,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN s.x_stake ELSE 0 END) AS st_out,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN 1 ELSE 0 END)         AS nb_out,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN s.x_net ELSE 0 END)   AS net_out,
           SUM(CASE WHEN s.x_rec=1 THEN s.x_stake ELSE 0 END) AS st_rec,
           SUM(CASE WHEN s.x_rec=1 THEN 1 ELSE 0 END)         AS nb_rec
    FROM x_mk s
    WHERE s.is_clean = 1
      AND s.x_member IS NOT NULL AND TRIM(CAST(s.x_member AS STRING)) <> ''
    GROUP BY s.x_member
  ),
  x_win AS (
    SELECT            COUNT(*) AS n_bets, COUNT(DISTINCT s.x_round) AS n_rounds,
           COUNT(DISTINCT s.x_date) AS active_days, COUNT(DISTINCT s.x_tblshoe) AS active_shoes,
           COUNT(DISTINCT CONCAT_WS('|', s.x_date, s.x_table)) AS active_sessions,
           COUNT(DISTINCT s.x_table) AS n_tables, COUNT(DISTINCT s.x_dealer) AS n_dealers,
           COUNT(DISTINCT s.x_ip) AS n_ips, COUNT(DISTINCT s.x_product) AS n_products,
           MIN(s.x_date) AS first_seen_d, MAX(s.x_date) AS last_seen_d,
           SUM(s.x_stake) AS stake, SUM(s.x_valid) AS valid, SUM(s.x_rebate) AS rebate,
           SUM(s.x_net) AS net, SUM(-s.x_net *(100.0-s.x_agpct)/100.0) AS agent_cost,
           AVG(100.0-s.x_agpct)                   AS agent_pct,
           AVG(s.x_agpct)                         AS company_retain_pct,
           SUM(-s.x_net *s.x_agpct/100.0)         AS agent_cost_a_legacy,
           SUM(s.x_valid*s.x_agpct/100.0)         AS agent_cost_valid_base_legacy,
          AVG(COALESCE(s.x_rate1,100)) AS retain_pct_lv1, AVG(COALESCE(s.x_rate2,100)) AS retain_pct_lv2,
          AVG(COALESCE(s.x_rate3,100)) AS retain_pct_lv3, AVG(COALESCE(s.x_rate4,100)) AS retain_pct_lv4,
          AVG(COALESCE(s.x_rate5,100)) AS retain_pct_lv5, AVG(s.x_chain_depth) AS chain_depth_avg,
          AVG(COALESCE(100.0-s.x_rate1,0)) AS agent_pct_lv1, AVG(COALESCE(100.0-s.x_rate2,0)) AS agent_pct_lv2,
          AVG(COALESCE(100.0-s.x_rate3,0)) AS agent_pct_lv3, AVG(COALESCE(100.0-s.x_rate4,0)) AS agent_pct_lv4,
          AVG(COALESCE(100.0-s.x_rate5,0)) AS agent_pct_lv5,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate1,0)/100.0)                        AS agent_cost_lv1,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate2,0)/100.0)                        AS agent_cost_lv2,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate3,0)/100.0)                        AS agent_cost_lv3,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate4,0)/100.0)                        AS agent_cost_lv4,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate5,0)/100.0)                        AS agent_cost_lv5,
          SUM(-s.x_net*(COALESCE(100.0-s.x_rate1,0)+COALESCE(100.0-s.x_rate2,0)
                       +COALESCE(100.0-s.x_rate3,0)+COALESCE(100.0-s.x_rate4,0)
                       +COALESCE(100.0-s.x_rate5,0))/100.0)                   AS agent_cost_chain_additive,
          SUM(-s.x_net*(1.0 - CAST(COALESCE(s.x_rate1,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate2,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate3,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate4,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate5,100) AS DOUBLE)/100.0))
                                                                       AS agent_cost_chain_nested,
           AVG(s.x_rbpct) AS rbpct, AVG(s.x_freecomm*1.0) AS freecomm_rate,
           PERCENTILE_APPROX(s.x_stake,0.25) AS p25, PERCENTILE_APPROX(s.x_stake,0.50) AS p50,
           PERCENTILE_APPROX(s.x_stake,0.75) AS p75, PERCENTILE_APPROX(s.x_stake,0.90) AS p90,
           PERCENTILE_APPROX(s.x_stake,0.95) AS p95, PERCENTILE_APPROX(s.x_stake,0.99) AS p99,
           PERCENTILE_APPROX(s.x_valid,0.50) AS p50_valid,
           PERCENTILE_APPROX(s.x_net,0.50)   AS p50_profit,
           SUM(CASE WHEN s.x_rec = 1 THEN s.x_stake ELSE 0 END) AS st_in,
           SUM(CASE WHEN s.x_rec = 1 THEN 1 ELSE 0 END)         AS nb_in,
           SUM(CASE WHEN s.x_rec = 1 THEN s.x_net ELSE 0 END)   AS net_in,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN s.x_stake ELSE 0 END) AS st_out,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN 1 ELSE 0 END)         AS nb_out,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN s.x_net ELSE 0 END)   AS net_out,
           SUM(CASE WHEN s.x_rec=1 THEN s.x_stake ELSE 0 END) AS st_rec,
           SUM(CASE WHEN s.x_rec=1 THEN 1 ELSE 0 END)         AS nb_rec
    FROM x_mk s
    WHERE s.is_clean = 1
      AND s.x_member IS NOT NULL AND TRIM(CAST(s.x_member AS STRING)) <> ''
  ),
      q AS (
        WITH ranked AS (                                                                                    -- 公共表表达式：开启中间结果集 ranked——口径与 §R03 一字不差（§R03-inv）
          SELECT b.bet01, b.bet03, b.bet04, b.bet39, b.bet05, b.bet09, b.bet11,                             -- 取列：起始取列子句，涉 bet03（靴号）、bet04（局内序号）、bet39（桌号）、bet05（会员号）
                 b.bet13, b.bet14, b.bet38, b.eid,                                                          -- 续行：接续上一取列子句，涉 bet13（下注金额）、bet14（派彩金额）、bet38（重對）
                 ROW_NUMBER() OVER (PARTITION BY b.bet01                                                    -- 行号窗口表达式：按注单号开窗取最终态
                   ORDER BY b.updatetime DESC, b.sync_time DESC, b.dt DESC) AS rn                           -- 排序：取最新一版，产出「rn」
          FROM ods_mariadb_2b.ods_a168_bet02 b                                                              -- 取数来源：取自注单明细表
          WHERE b.dt >= '2026-03-21' AND b.dt < '2026-08-07'                                                -- 过滤条件：限定 E1 全局窗，涉 dt（营业日）
            AND b.bet02 = '101'
      AND b.sync_time <= '2026-08-27 09:00:00' AND b.category = '1'                                                        -- 并列条件：限定百家乐产品大类，涉 bet02（游戏类别）
        ),                                                                                                  -- 续行：收束上方的子查询或函数括号（§R03-inv）
        base AS (                                                                                           -- 公共表表达式：开启中间结果集 base——有效注单，哨兵**标注不删**（§R03-inv）
          SELECT r.bet05 AS member_id, r.eid AS dealer_id,                                                  -- 取列：起始取列子句，涉 bet05（会员号）、eid（荷官工号）
                 CASE WHEN TRIM(r.eid) IN ('-1','0') THEN 1 ELSE 0 END AS is_sentinel_dealer,               -- 取值表达式：哨兵标记，产出「is_sentinel_dealer」
                 CONCAT_WS('|', r.bet03, r.bet04, r.bet39) AS round_key,                                    -- 取值表达式：三键拼物理局键，产出「round_key」
                 (CAST(NULLIF(TRIM(r.bet14),'') AS DECIMAL(20,4))                                           -- 取值表达式：派彩额起算，涉 bet14（派彩金额）
                  - CAST(NULLIF(TRIM(r.bet13),'') AS DECIMAL(20,4)))                                        -- 续行：减投注额得游戏净输赢，涉 bet13（下注金额）
                  / CAST(NULLIF(TRIM(r.bet11),'') AS DECIMAL(20,8)) AS game_pnl                             -- 续行：折汇率归一，产出「game_pnl」
          FROM ranked r                                                                                     -- 取数来源：取自本条自建的中间结果集 ranked
          WHERE r.rn = 1 AND UPPER(TRIM(r.bet38)) = 'N'                                                     -- 过滤条件：只取每注最终态且非测试单，涉 bet38（重對）
            AND CAST(NULLIF(TRIM(r.bet05),'') AS BIGINT) > 0                                                -- 并列条件：剔除无效会员号，涉 bet05（会员号）
            AND CAST(NULLIF(TRIM(r.bet11),'') AS DECIMAL(20,8)) > 0                                         -- 并列条件：汇率须为正，涉 bet11（汇率）
            AND NULLIF(TRIM(r.eid),'') IS NOT NULL                                                          -- 并列条件：荷官号非空——空号无从归属，不构成关系
            AND UPPER(TRIM(r.bet09)) NOT LIKE 'TIP\\_1\\_%'                                                 -- 并列条件：排除小费单，涉 bet09（玩法）
        ),                                                                                                  -- 续行：收束上方的子查询或函数括号（§R03-inv）
        pr AS (                                                                                             -- 公共表表达式：开启中间结果集 pr——同局多注折成一局（§R03-inv）
          SELECT member_id, dealer_id, is_sentinel_dealer, round_key,                                       -- 取列：起始取列子句，本行先列四键
                 SUM(game_pnl) AS game_pnl                                                                  -- 聚合：局内合计游戏净输赢，产出「game_pnl」
          FROM base GROUP BY member_id, dealer_id, is_sentinel_dealer, round_key                            -- 分组：按会员×荷官×哨兵标记×物理局汇总
        ),                                                                                                  -- 续行：收束上方的子查询或函数括号（§R03-inv）
        pd AS (                                                                                             -- 公共表表达式：开启中间结果集 pd——玩家×荷官关系级（§R03-inv）
          SELECT member_id, dealer_id, is_sentinel_dealer,                                                  -- 取列：起始取列子句，本行先列三键
                 COUNT(*)                                          AS n_rounds_eff,                         -- 计数表达式：有效局数，产出「n_rounds_eff」
                 SUM(CASE WHEN game_pnl <> 0 THEN 1 ELSE 0 END)    AS n_dec                                 -- 聚合：决胜局数（退还局不入），产出「n_dec」
          FROM pr GROUP BY member_id, dealer_id, is_sentinel_dealer                                         -- 分组：按会员×荷官×哨兵标记汇总
        )                                                                                                   -- 续行：收束上方的子查询或函数括号（§R03-inv）
        SELECT  CASE WHEN is_sentinel_dealer = 1 THEN 'SENTINEL_DEALER'                                     -- 取值表达式：资格分档起算——与 §R03 的 eligibility_status 逐字同口径
                     WHEN n_dec = 0              THEN 'NO_DECISIVE_ROUND'                                   -- 续行：全为退还局
                     WHEN n_rounds_eff < 30      THEN 'INSUFFICIENT_N'                                      -- 续行：局数不足 30
                     ELSE 'ELIGIBLE' END                           AS eligibility_status,                   -- 续行：产出「eligibility_status」
                CASE WHEN n_rounds_eff = 1 THEN '01_n=1'                                                    -- 取值表达式：稀疏分层起算——长尾的形状此前被 WHERE 藏起，今逐层点清
                     WHEN n_rounds_eff <= 2  THEN '02_n=2'                                                  -- 续行：n 等于 2
                     WHEN n_rounds_eff <= 5  THEN '03_n=3~5'                                                -- 续行：n 介于 3 至 5
                     WHEN n_rounds_eff <= 10 THEN '04_n=6~10'                                               -- 续行：n 介于 6 至 10
                     WHEN n_rounds_eff <= 29 THEN '05_n=11~29'                                              -- 续行：n 介于 11 至 29
                     WHEN n_rounds_eff <= 100 THEN '06_n=30~100'                                            -- 续行：n 介于 30 至 100
                     ELSE '07_n>100' END                           AS n_bucket,                             -- 续行：产出「n_bucket」
                COUNT(*)                                          AS n_pairs,                               -- 计数表达式：该格的玩家×荷官关系数，产出「n_pairs」
                COUNT(DISTINCT member_id)                         AS n_members,                             -- 计数表达式：涉及会员数（去重），产出「n_members」
                COUNT(DISTINCT dealer_id)                         AS n_dealers,                             -- 计数表达式：涉及荷官数（去重），产出「n_dealers」
                SUM(n_rounds_eff)                                 AS n_rounds_total                         -- 聚合：该格的有效局合计，产出「n_rounds_total」
        FROM    pd                                                                                          -- 取数来源：取自本条自建的中间结果集 pd
        GROUP BY 1, 2                                                                                       -- 分组：按资格分档与稀疏分层汇总
      )
    SELECT q.*,
           -- 一·经济层
           ROUND(e.stake,4) AS stake, ROUND(e.valid,4) AS valid_bet,
           ROUND(-e.net,4) AS profit, e.n_bets, e.n_rounds,
           ROUND(e.net/NULLIF(e.stake,0),8) AS roi,
           ROUND(e.net_in/NULLIF(e.st_in,0),8) AS roi_recent,
           ROUND(e.net_out/NULLIF(e.st_out,0),8) AS roi_non_recent,
           ROUND((e.net-e.rebate)/NULLIF(e.stake,0),8) AS roi_ex_rebate,
           ROUND(e.net,4) AS roi_numerator, ROUND(e.stake,4) AS roi_denominator,
           CASE WHEN e.stake IS NULL THEN 'NULL_DENOM' WHEN e.stake<=0 THEN 'ZERO_DENOM'
                WHEN e.n_bets<30 THEN 'THIN_EXPOSURE' ELSE 'OK' END AS roi_denominator_status,
           ROUND(e.rebate,4) AS rebate_cost, ROUND(e.agent_cost,4)                           AS cost_complement_b,
       ROUND(e.agent_pct,4)                            AS pct_complement,
       ROUND(e.company_retain_pct,4)                   AS pct_top_bet23,
       'AG03-UNRESOLVED'                                     AS agent_formula_version,
      'ALL5_LEVELS_bet23_to_bet27'                    AS agent_level_scope,
      ROUND(e.agent_cost_lv1,4) AS agent_cost_lv1, ROUND(e.agent_cost_lv2,4) AS agent_cost_lv2,
      ROUND(e.agent_cost_lv3,4) AS agent_cost_lv3, ROUND(e.agent_cost_lv4,4) AS agent_cost_lv4,
      ROUND(e.agent_cost_lv5,4) AS agent_cost_lv5,
      ROUND(e.agent_pct_lv1,6) AS agent_pct_lv1, ROUND(e.agent_pct_lv2,6) AS agent_pct_lv2,
      ROUND(e.agent_pct_lv3,6) AS agent_pct_lv3, ROUND(e.agent_pct_lv4,6) AS agent_pct_lv4,
      ROUND(e.agent_pct_lv5,6) AS agent_pct_lv5,
      ROUND(e.retain_pct_lv1,6) AS retain_pct_lv1, ROUND(e.retain_pct_lv2,6) AS retain_pct_lv2,
      ROUND(e.retain_pct_lv3,6) AS retain_pct_lv3, ROUND(e.retain_pct_lv4,6) AS retain_pct_lv4,
      ROUND(e.retain_pct_lv5,6) AS retain_pct_lv5, ROUND(e.chain_depth_avg,4) AS chain_depth_avg,
      ROUND(e.agent_cost_chain_additive,4)            AS agent_cost_chain_additive,
      ROUND(e.agent_cost_chain_nested,4)              AS agent_cost_chain_nested,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_additive,4) AS residual_chain_additive,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_nested,4)   AS residual_chain_nested,
      'PENDING_AG03'                                  AS decision_status,
      'FALSE'                                         AS admit_to_risk_decision,
      'NOT_FOR_ENFORCEMENT'                           AS deliverable_class,
       ROUND(e.agent_cost_a_legacy,4)                  AS agent_cost_a_legacy,
       ROUND(e.agent_cost_valid_base_legacy,4)         AS agent_cost_valid_base_legacy,
           ROUND(-e.net-e.rebate,4)                        AS ngr,
       ROUND(-e.net-e.rebate-e.agent_cost,4)           AS residual_b,
       ROUND(-e.net-e.rebate-e.agent_cost_a_legacy,4)  AS residual_a,
           ROUND((-e.net-e.rebate)/NULLIF(e.stake,0),8)    AS ngr_rate,
       ROUND((-e.net-e.rebate-e.agent_cost)/NULLIF(e.stake,0),8)   AS residual_b_rate,
      -- 【HF9c · canonical accounting contract】
      --   以下 canonical 字段只增加明确 scope；不删除、不覆盖既有字段。
      --   formal_bet23_* 保持 HF9b 当前生产公式及其 NULL/0 语义；
      --   lv1~lv5 / additive / nested 则分别采用各自原始 e.* 成本字段，
      --   rate 一律从未舍入的 e.* 分子 / e.stake 计算，禁止由展示值反算。
      ROUND(e.agent_cost,4) AS agent_cost_bet23_formal_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost,4) AS net_margin_bet23_formal_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost)/NULLIF(e.stake,0),8) AS net_margin_bet23_formal_rate_canonical,
      ROUND(e.agent_cost_lv1,4) AS agent_cost_lv1_bet23_canonical,
      ROUND(e.agent_cost_lv2,4) AS agent_cost_lv2_bet24_canonical,
      ROUND(e.agent_cost_lv3,4) AS agent_cost_lv3_bet25_canonical,
      ROUND(e.agent_cost_lv4,4) AS agent_cost_lv4_bet26_canonical,
      ROUND(e.agent_cost_lv5,4) AS agent_cost_lv5_bet27_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_lv1,4) AS net_margin_lv1_bet23_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_lv1)/NULLIF(e.stake,0),8) AS net_margin_lv1_bet23_rate_canonical,
      ROUND(e.agent_cost_chain_additive,4) AS agent_cost_chain_additive_canonical,
      ROUND(e.agent_cost_chain_nested,4) AS agent_cost_chain_nested_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_additive,4) AS net_margin_chain_additive_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_nested,4) AS net_margin_chain_nested_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_chain_additive)/NULLIF(e.stake,0),8) AS net_margin_chain_additive_rate_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_chain_nested)/NULLIF(e.stake,0),8) AS net_margin_chain_nested_rate_canonical,
       ROUND((-e.net-e.rebate-e.agent_cost_a_legacy)/NULLIF(e.stake,0),8) AS residual_a_rate,
           -- 二·分布层
           ROUND(e.stake/NULLIF(e.n_bets,0),4) AS avg_stake_per_bet,
           ROUND(e.valid/NULLIF(e.n_rounds,0),4) AS avg_valid_bet_per_round,
           ROUND(-e.net/NULLIF(e.n_rounds,0),4) AS avg_profit_per_round,
           ROUND(-e.net/NULLIF(e.active_days,0),4) AS avg_profit_per_day,
           ROUND(-e.net/NULLIF(e.active_shoes,0),4) AS avg_profit_per_shoe,
           ROUND(e.stake/NULLIF(e.active_days,0),4) AS avg_stake_per_active_day,
           ROUND(e.n_rounds*1.0/NULLIF(e.active_days,0),4) AS avg_rounds_per_active_day,
           ROUND(e.st_in/NULLIF(e.nb_in,0),4) AS avg_stake_recent,
           ROUND(e.st_out/NULLIF(e.nb_out,0),4) AS avg_stake_non_recent,
           ROUND(e.p25,4) AS p25_stake, ROUND(e.p50,4) AS p50_stake, ROUND(e.p75,4) AS p75_stake,
           ROUND(e.p90,4) AS p90_stake, ROUND(e.p95,4) AS p95_stake, ROUND(e.p99,4) AS p99_stake,
           ROUND(e.p50_valid,4) AS p50_valid_bet, ROUND(e.p50_profit,4) AS p50_profit,
           ROUND(e.p95/NULLIF(e.p50,0),6) AS p95_over_p50,
           ROUND(e.p99/NULLIF(e.p50,0),6) AS p99_over_p50,
           ROUND((e.stake/NULLIF(e.n_bets,0))/NULLIF(e.p50,0),6) AS avg_over_p50,
           -- 三·关系层
           e.n_tables AS common_table_count, e.n_dealers AS common_dealer_count,
           e.n_ips AS common_ip_count, e.n_products AS common_product_count,
           ROUND(e.st_in/NULLIF(e.stake,0),8) AS share_recent,
           -- 四·rate 层
           ROUND(-e.net/NULLIF(e.stake,0),8) AS hold_rate,
           ROUND(-e.net_in/NULLIF(e.st_in,0),8) AS hold_rate_recent,
           ROUND(e.rebate/NULLIF(e.valid,0),8) AS rebate_rate_actual,
           ROUND(e.rbpct,6) AS rebate_pct_config,
           ROUND(e.valid/NULLIF(e.stake,0),6) AS turnover_multiple,
           ROUND(e.freecomm_rate,6) AS free_comm_rate,
           ROUND(e.net_in/NULLIF(e.st_in,0)-e.net_out/NULLIF(e.st_out,0),8) AS roi_delta_recent,
           -- 五·动态层
           e.first_seen_d AS first_seen, e.last_seen_d AS last_seen,
           e.active_days, e.active_shoes, e.active_sessions,
           DATEDIFF(e.last_seen_d, e.first_seen_d)+1 AS span_days,
           ROUND(e.active_days*1.0/NULLIF(DATEDIFF(e.last_seen_d,e.first_seen_d)+1,0),6) AS persistence,
           ROUND((e.st_in/NULLIF(e.nb_in,0))/NULLIF(e.st_out/NULLIF(e.nb_out,0),0),6) AS ramp_recent_vs_prior,
           ROUND((e.st_rec/NULLIF(e.nb_rec,0))/NULLIF(e.stake/NULLIF(e.n_bets,0),0),6) AS ramp_recent_vs_all,
           ROUND((e.st_rec/NULLIF(e.stake,0))/0.30,6) AS stake_ramp,
           -- 六·决策层（HF9g-P5 · D-14 斧正 —— 本件属【全窗基线族】，相对刻度与决策标签一律 NULL）
           --   病灶：x_win 系全窗单行聚合（无 GROUP BY，恒 1 行，此为设计使然，非缺陷），
           --         经 CROSS JOIN 接入后 e.* 全行同值；六层之 NTILE / PERCENT_RANK 施于常数即退化，
           --         PERCENT_RANK 恒 0 ⇒ action_priority 恒判 A，全件 100% 误标。
           --   ★ 斧正原则：不给 x_win 补 GROUP BY —— 那会改变其「全窗基线」语义，属退化。
           --     正解与 #018 之 G-05／G-06 同治：范围外之行不得接受任何下游评分与决策标签。
           --   ★ 本件之 e.* 仍照常供其它列作全窗基线使用，仅六层相对刻度与决策标签置 NULL。
           CAST(NULL AS INT)                                              AS vip_tier,                        -- 空值取值：全窗基线族无实体可分档，置 NULL（NULL＝不适用，非 0）
           CAST(NULL AS DOUBLE)                                           AS economic_value,                  -- 空值取值：同上，禁以常数百分位冒充经济价值
           CAST(NULL AS DOUBLE)                                           AS roi_pr_global,                   -- 空值取值：同上
           CAST(NULL AS DOUBLE)                                           AS risk_value,                      -- 空值取值：兼容列，同上
           CAST(NULL AS DOUBLE)                                           AS pr_stake,                        -- 空值取值：兼容列，同上
           CAST(NULL AS DOUBLE)                                           AS pr_global,                       -- 空值取值：同上
           CAST(NULL AS DOUBLE)                                           AS pr_qualified,                    -- 空值取值：同上
           'GLOBAL_BASELINE_NO_ENTITY_RANKING'                            AS pr_qualified_population,         -- 字面取值：血统 —— 明示本件为全窗基线族，无实体排序总体
           CAST(NULL AS BIGINT)                                           AS pr_global_population_n,          -- 空值取值：血统 —— 不适用
           CAST(NULL AS BIGINT)                                           AS pr_qualified_population_n,       -- 空值取值：血统 —— 不适用
           'NOT_APPLICABLE_GLOBAL_BASELINE'                               AS pr_calculation_method,           -- 字面取值：血统 —— 算法不适用
           'HF9g-P5'                                                      AS pr_calculation_version,          -- 字面取值：血统 —— 算法版本
           CAST(NULL AS STRING)                                           AS evidence_flag,                   -- 空值取值：证据旗标不适用于全窗基线
           CAST(NULL AS STRING)                                           AS evidence_rate,                   -- 空值取值：同上
           CAST(NULL AS DOUBLE)                                           AS hold_ci_halfwidth_approx,        -- 空值取值：同上
           'X 全窗基线 · 不参与实体赏罚'                                    AS action_priority                  -- 字面取值：★ D-14 斧正 —— 本族恒不入赏罚，取代原 100% 误标之「A」
    FROM q
    CROSS JOIN x_win e
  ) y
) z
-- ── 逐批 WHERE 阶梯（★ 口诀：上界 ＝ 下界 ＋ 100000，两数同进）──
--    本件 T_true 未测，无需先跑 T_true；以 0 / 100000 控制本批返回区间，末批由实际行数 < 100000 判定
--    WHERE z.audit_rn >        0 AND z.audit_rn <=   100000   -- 第 1 批
--    WHERE z.audit_rn >   100000 AND z.audit_rn <=   200000   -- 第 2 批
--    WHERE z.audit_rn >   200000 AND z.audit_rn <=   300000   -- 第 3 批
--    WHERE z.audit_rn >   300000 AND z.audit_rn <=   400000   -- 第 4 批
--    WHERE z.audit_rn >   400000 AND z.audit_rn <=   500000   -- 第 5 批
--    WHERE z.audit_rn >   500000 AND z.audit_rn <=   600000   -- 第 6 批
--    WHERE z.audit_rn >   600000 AND z.audit_rn <=   700000   -- 第 7 批
--    …余批类推。第 k 批：WHERE z.audit_rn > (k-1)*100000 AND z.audit_rn <= k*100000
--    某批返回 < 100000 行即为末批，其后不再取。
--
--    ⚠ 常见误写（务必避开）：只推下界而上界不动 ——
--        WHERE z.audit_rn > 100000 AND z.audit_rn <= 100000   ← 自相矛盾，恒为假，返回空集
--        WHERE z.audit_rn > 200000 AND z.audit_rn <= 100000   ← 同上，空集
--      两个数必须**同时**前进，且始终相差 100000。
--      下界 ＝ 上一批之上界；上界 ＝ 本批之上界。
WHERE z.audit_rn > 0 AND z.audit_rn <= 100000 -- ★ HF9c 本批区间
ORDER BY z.audit_rn;


-- ══════════════════════════════════════════════════════════════════════════════════════════════
--  74. R_rebate_dist.csv   [总包行 1489~1492 · 原 3 列 ＋六层约 60 列]
--     典型学：M05 退水套利　派生旗标：hiturn（s.x_valid > s.x_stake · 仅供 CASE 条件聚合，全包无任何 WHERE/AND/HAVING 以此过滤）　连接：全窗基线
-- ══════════════════════════════════════════════════════════════════════════════════════════════
-- ★ W-64 · D-14 警示（本件属 x_win 族 · 66 件之一 · 详见 §Z 段 D-14 全案）
--   本件以 `CROSS JOIN x_win e` 接入全局基线，x_win 无 GROUP BY ⇒ 恒 1 行 ⇒ e.* 全行同值。
--   故：economic_value / roi_pr_global / risk_value / pr_stake / pr_global 恒为 0；
--       action_priority 每一行皆为「A 净亏最大十分位 · 优先复核」（Z 分支永不触发）；
--       evidence_rate 恒为最高档；vip_tier 由常数键分档 ⇒ 无信息且非确定。
--   ⇒ 本件决策层三列 **NOT_FOR_DECISION**，裁定前不得用于排班、抽查或汇报。
-- ── ① 先跑 T_true 留档（不足 100000 者一次导全，不必分批）──
-- ── ① T_true：HF9c 不再强制预跑完整 COUNT。
--    本批实际返回行数 < 100000 即判定为末批；全批完成后以各批 n_rows / audit_rn 范围核对总量。

-- ── ② 分批取数：第 1 批。第 k 批只改末行两数为 (k-1)*100000 与 k*100000 ──
--    审计字段二（REDTEAM 2026-08-24 裁定 · 四锁）：
--      audit_rn  全局观测坐标 —— 由**与原版审计版逐字同一**之排序键所生，两版可逐行对账
--      batch_id  物理分批信息 —— 该行所属批次，由 audit_rn 算得，非引擎所赋
--    ★ 锁三：二者皆为审计字段，**不得进入任何业务指标计算**。
--    ★ 锁四：两版经 audit_rn 逐行字段核验后，方可宣布输出完全一致。

-- ── ③ 每批取回后自证四数（任一不符即停手回报，禁止放行）──
--    n_rows        = COUNT(*)      须等于 COUNT(DISTINCT audit_rn)   （批内无重复）
--    audit_rn_min  = MIN(audit_rn) 须等于 (k-1)*100000 + 1           （与上批严丝合缝）
--    audit_rn_max  = MAX(audit_rn) 须等于 min + n_rows - 1           （批内无缺口）
--    全批取毕再验：各批 audit_rn 之并集 = 1 .. T_true，无缺号、无重号。
--     ★ 首行＝平台真净亏最多者（已扣退水与代理占成）。
--
SELECT z.*,
       CAST(FLOOR((z.audit_rn - 1) / 100000) + 1 AS INT)          AS batch_id,
       'A168_HF9F_20260827_0900' AS run_id,
       '2026-08-27 09:00:00' AS snapshot_sync_time
FROM (
  SELECT y.*,
         ROW_NUMBER() OVER (ORDER BY y.`residual_b` ASC, y.`roi` DESC, y.`rebate_rate`, y.`n_member`, y.`pct`) AS audit_rn
  FROM (
    WITH
      x_ranked AS (
    SELECT b.bet01, b.bet03, b.bet04, b.bet05, b.bet09, b.bet11, b.bet13,
           b.bet15, b.bet16, b.bet17, b.bet18, b.bet19, b.bet20, b.bet21,
           b.bet22, b.bet23, b.bet24, b.bet25, b.bet26, b.bet27, b.bet38, b.bet39, b.category, b.commission,
           b.dt, b.eid, b.ip, b.validbet, b.updatetime, b.sync_time,
           ROW_NUMBER() OVER (
             PARTITION BY b.bet01
             ORDER BY b.updatetime DESC, b.sync_time DESC, b.dt DESC)      AS x_rn
    FROM ods_mariadb_2b.ods_a168_bet02 b
    WHERE b.dt >= '2026-03-21' AND b.dt < '2026-08-07'
      AND b.bet02 = '101'
      AND b.sync_time <= '2026-08-27 09:00:00'
  ),
    x_testagent AS (
    SELECT age001 AS agent_id FROM ods_mariadb_2b.ods_a168_agent WHERE age022 = '1'
  ),
    x_bs0 AS (
    SELECT b.bet05 AS x_member, b.eid AS x_dealer, b.bet39 AS x_table,
           b.bet03 AS x_shoe, b.ip AS x_ip, b.bet09 AS x_product, b.dt AS x_date,
           CONCAT_WS('|', b.bet03, b.bet04, b.bet39)                      AS x_round,
           CONCAT_WS('|', b.bet39, b.bet03)                               AS x_tblshoe,
           CAST(NULLIF(TRIM(b.bet04),'') AS INT)                          AS x_rno,
           CASE WHEN b.dt >= '2026-07-08' THEN 1 ELSE 0 END               AS x_rec,
           CASE WHEN TRIM(b.commission)='1' THEN 1 ELSE 0 END             AS x_freecomm,
           CAST(NULLIF(TRIM(b.bet13),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_stake,
           CAST(NULLIF(TRIM(b.validbet),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_valid,
           CAST(NULLIF(TRIM(b.bet16),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_rebate,
           CAST(NULLIF(TRIM(b.bet17),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_net,
           CAST(NULLIF(TRIM(b.bet15),'') AS DECIMAL(20,6))                AS x_rbpct,
           COALESCE(CAST(NULLIF(TRIM(b.bet23),'') AS DECIMAL(20,6)),0)   AS x_agpct,
          NULLIF(CAST(NULLIF(TRIM(b.bet23),'') AS DECIMAL(20,6)),0)     AS x_rate1,
          NULLIF(CAST(NULLIF(TRIM(b.bet24),'') AS DECIMAL(20,6)),0)     AS x_rate2,
          NULLIF(CAST(NULLIF(TRIM(b.bet25),'') AS DECIMAL(20,6)),0)     AS x_rate3,
          NULLIF(CAST(NULLIF(TRIM(b.bet26),'') AS DECIMAL(20,6)),0)     AS x_rate4,
          NULLIF(CAST(NULLIF(TRIM(b.bet27),'') AS DECIMAL(20,6)),0)     AS x_rate5,
          (CASE WHEN NULLIF(CAST(NULLIF(TRIM(b.bet22),'') AS BIGINT),0) IS NOT NULL THEN 5
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet21),'') AS BIGINT),0) IS NOT NULL THEN 4
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet20),'') AS BIGINT),0) IS NOT NULL THEN 3
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet19),'') AS BIGINT),0) IS NOT NULL THEN 2
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet18),'') AS BIGINT),0) IS NOT NULL THEN 1
                ELSE 0 END)                                             AS x_chain_depth,
           CASE WHEN COALESCE(t1.agent_id,t2.agent_id,t3.agent_id,
                              t4.agent_id,t5.agent_id) IS NOT NULL
                THEN 1 ELSE 0 END                                        AS f_testline
    FROM x_ranked b
    LEFT JOIN x_testagent t1 ON t1.agent_id = b.bet18
    LEFT JOIN x_testagent t2 ON t2.agent_id = b.bet19
    LEFT JOIN x_testagent t3 ON t3.agent_id = b.bet20
    LEFT JOIN x_testagent t4 ON t4.agent_id = b.bet21
    LEFT JOIN x_testagent t5 ON t5.agent_id = b.bet22
    WHERE b.x_rn = 1
      AND b.category='1' AND UPPER(TRIM(b.bet38))='N'
      AND CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8)) > 0
  ),
  x_mk AS (
    SELECT s.*,
           CASE WHEN s.f_testline = 0 THEN 1 ELSE 0 END                 AS is_clean
    FROM x_bs0 s
  ),
  x_agg AS (
    SELECT s.x_member                                                        AS x_key,
           COUNT(*) AS n_bets, COUNT(DISTINCT s.x_round) AS n_rounds,
           COUNT(DISTINCT s.x_date) AS active_days, COUNT(DISTINCT s.x_tblshoe) AS active_shoes,
           COUNT(DISTINCT CONCAT_WS('|', s.x_date, s.x_table)) AS active_sessions,
           COUNT(DISTINCT s.x_table) AS n_tables, COUNT(DISTINCT s.x_dealer) AS n_dealers,
           COUNT(DISTINCT s.x_ip) AS n_ips, COUNT(DISTINCT s.x_product) AS n_products,
           MIN(s.x_date) AS first_seen_d, MAX(s.x_date) AS last_seen_d,
           SUM(s.x_stake) AS stake, SUM(s.x_valid) AS valid, SUM(s.x_rebate) AS rebate,
           SUM(s.x_net) AS net, SUM(-s.x_net *(100.0-s.x_agpct)/100.0) AS agent_cost,
           AVG(100.0-s.x_agpct)                   AS agent_pct,
           AVG(s.x_agpct)                         AS company_retain_pct,
           SUM(-s.x_net *s.x_agpct/100.0)         AS agent_cost_a_legacy,
           SUM(s.x_valid*s.x_agpct/100.0)         AS agent_cost_valid_base_legacy,
          AVG(COALESCE(s.x_rate1,100)) AS retain_pct_lv1, AVG(COALESCE(s.x_rate2,100)) AS retain_pct_lv2,
          AVG(COALESCE(s.x_rate3,100)) AS retain_pct_lv3, AVG(COALESCE(s.x_rate4,100)) AS retain_pct_lv4,
          AVG(COALESCE(s.x_rate5,100)) AS retain_pct_lv5, AVG(s.x_chain_depth) AS chain_depth_avg,
          AVG(COALESCE(100.0-s.x_rate1,0)) AS agent_pct_lv1, AVG(COALESCE(100.0-s.x_rate2,0)) AS agent_pct_lv2,
          AVG(COALESCE(100.0-s.x_rate3,0)) AS agent_pct_lv3, AVG(COALESCE(100.0-s.x_rate4,0)) AS agent_pct_lv4,
          AVG(COALESCE(100.0-s.x_rate5,0)) AS agent_pct_lv5,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate1,0)/100.0)                        AS agent_cost_lv1,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate2,0)/100.0)                        AS agent_cost_lv2,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate3,0)/100.0)                        AS agent_cost_lv3,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate4,0)/100.0)                        AS agent_cost_lv4,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate5,0)/100.0)                        AS agent_cost_lv5,
          SUM(-s.x_net*(COALESCE(100.0-s.x_rate1,0)+COALESCE(100.0-s.x_rate2,0)
                       +COALESCE(100.0-s.x_rate3,0)+COALESCE(100.0-s.x_rate4,0)
                       +COALESCE(100.0-s.x_rate5,0))/100.0)                   AS agent_cost_chain_additive,
          SUM(-s.x_net*(1.0 - CAST(COALESCE(s.x_rate1,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate2,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate3,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate4,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate5,100) AS DOUBLE)/100.0))
                                                                       AS agent_cost_chain_nested,
           AVG(s.x_rbpct) AS rbpct, AVG(s.x_freecomm*1.0) AS freecomm_rate,
           PERCENTILE_APPROX(s.x_stake,0.25) AS p25, PERCENTILE_APPROX(s.x_stake,0.50) AS p50,
           PERCENTILE_APPROX(s.x_stake,0.75) AS p75, PERCENTILE_APPROX(s.x_stake,0.90) AS p90,
           PERCENTILE_APPROX(s.x_stake,0.95) AS p95, PERCENTILE_APPROX(s.x_stake,0.99) AS p99,
           PERCENTILE_APPROX(s.x_valid,0.50) AS p50_valid,
           PERCENTILE_APPROX(s.x_net,0.50)   AS p50_profit,
           SUM(CASE WHEN s.x_valid > s.x_stake THEN s.x_stake ELSE 0 END) AS st_in,
           SUM(CASE WHEN s.x_valid > s.x_stake THEN 1 ELSE 0 END)         AS nb_in,
           SUM(CASE WHEN s.x_valid > s.x_stake THEN s.x_net ELSE 0 END)   AS net_in,
           SUM(CASE WHEN NOT (s.x_valid > s.x_stake) THEN s.x_stake ELSE 0 END) AS st_out,
           SUM(CASE WHEN NOT (s.x_valid > s.x_stake) THEN 1 ELSE 0 END)         AS nb_out,
           SUM(CASE WHEN NOT (s.x_valid > s.x_stake) THEN s.x_net ELSE 0 END)   AS net_out,
           SUM(CASE WHEN s.x_rec=1 THEN s.x_stake ELSE 0 END) AS st_rec,
           SUM(CASE WHEN s.x_rec=1 THEN 1 ELSE 0 END)         AS nb_rec
    FROM x_mk s
    WHERE s.is_clean = 1
      AND s.x_member IS NOT NULL AND TRIM(CAST(s.x_member AS STRING)) <> ''
    GROUP BY s.x_member
  ),
  x_win AS (
    SELECT            COUNT(*) AS n_bets, COUNT(DISTINCT s.x_round) AS n_rounds,
           COUNT(DISTINCT s.x_date) AS active_days, COUNT(DISTINCT s.x_tblshoe) AS active_shoes,
           COUNT(DISTINCT CONCAT_WS('|', s.x_date, s.x_table)) AS active_sessions,
           COUNT(DISTINCT s.x_table) AS n_tables, COUNT(DISTINCT s.x_dealer) AS n_dealers,
           COUNT(DISTINCT s.x_ip) AS n_ips, COUNT(DISTINCT s.x_product) AS n_products,
           MIN(s.x_date) AS first_seen_d, MAX(s.x_date) AS last_seen_d,
           SUM(s.x_stake) AS stake, SUM(s.x_valid) AS valid, SUM(s.x_rebate) AS rebate,
           SUM(s.x_net) AS net, SUM(-s.x_net *(100.0-s.x_agpct)/100.0) AS agent_cost,
           AVG(100.0-s.x_agpct)                   AS agent_pct,
           AVG(s.x_agpct)                         AS company_retain_pct,
           SUM(-s.x_net *s.x_agpct/100.0)         AS agent_cost_a_legacy,
           SUM(s.x_valid*s.x_agpct/100.0)         AS agent_cost_valid_base_legacy,
          AVG(COALESCE(s.x_rate1,100)) AS retain_pct_lv1, AVG(COALESCE(s.x_rate2,100)) AS retain_pct_lv2,
          AVG(COALESCE(s.x_rate3,100)) AS retain_pct_lv3, AVG(COALESCE(s.x_rate4,100)) AS retain_pct_lv4,
          AVG(COALESCE(s.x_rate5,100)) AS retain_pct_lv5, AVG(s.x_chain_depth) AS chain_depth_avg,
          AVG(COALESCE(100.0-s.x_rate1,0)) AS agent_pct_lv1, AVG(COALESCE(100.0-s.x_rate2,0)) AS agent_pct_lv2,
          AVG(COALESCE(100.0-s.x_rate3,0)) AS agent_pct_lv3, AVG(COALESCE(100.0-s.x_rate4,0)) AS agent_pct_lv4,
          AVG(COALESCE(100.0-s.x_rate5,0)) AS agent_pct_lv5,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate1,0)/100.0)                        AS agent_cost_lv1,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate2,0)/100.0)                        AS agent_cost_lv2,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate3,0)/100.0)                        AS agent_cost_lv3,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate4,0)/100.0)                        AS agent_cost_lv4,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate5,0)/100.0)                        AS agent_cost_lv5,
          SUM(-s.x_net*(COALESCE(100.0-s.x_rate1,0)+COALESCE(100.0-s.x_rate2,0)
                       +COALESCE(100.0-s.x_rate3,0)+COALESCE(100.0-s.x_rate4,0)
                       +COALESCE(100.0-s.x_rate5,0))/100.0)                   AS agent_cost_chain_additive,
          SUM(-s.x_net*(1.0 - CAST(COALESCE(s.x_rate1,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate2,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate3,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate4,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate5,100) AS DOUBLE)/100.0))
                                                                       AS agent_cost_chain_nested,
           AVG(s.x_rbpct) AS rbpct, AVG(s.x_freecomm*1.0) AS freecomm_rate,
           PERCENTILE_APPROX(s.x_stake,0.25) AS p25, PERCENTILE_APPROX(s.x_stake,0.50) AS p50,
           PERCENTILE_APPROX(s.x_stake,0.75) AS p75, PERCENTILE_APPROX(s.x_stake,0.90) AS p90,
           PERCENTILE_APPROX(s.x_stake,0.95) AS p95, PERCENTILE_APPROX(s.x_stake,0.99) AS p99,
           PERCENTILE_APPROX(s.x_valid,0.50) AS p50_valid,
           PERCENTILE_APPROX(s.x_net,0.50)   AS p50_profit,
           SUM(CASE WHEN s.x_valid > s.x_stake THEN s.x_stake ELSE 0 END) AS st_in,
           SUM(CASE WHEN s.x_valid > s.x_stake THEN 1 ELSE 0 END)         AS nb_in,
           SUM(CASE WHEN s.x_valid > s.x_stake THEN s.x_net ELSE 0 END)   AS net_in,
           SUM(CASE WHEN NOT (s.x_valid > s.x_stake) THEN s.x_stake ELSE 0 END) AS st_out,
           SUM(CASE WHEN NOT (s.x_valid > s.x_stake) THEN 1 ELSE 0 END)         AS nb_out,
           SUM(CASE WHEN NOT (s.x_valid > s.x_stake) THEN s.x_net ELSE 0 END)   AS net_out,
           SUM(CASE WHEN s.x_rec=1 THEN s.x_stake ELSE 0 END) AS st_rec,
           SUM(CASE WHEN s.x_rec=1 THEN 1 ELSE 0 END)         AS nb_rec
    FROM x_mk s
    WHERE s.is_clean = 1
      AND s.x_member IS NOT NULL AND TRIM(CAST(s.x_member AS STRING)) <> ''
  ),
      q AS (
        SELECT mem003 AS rebate_rate, COUNT(*) AS n_member,                                                 -- 取列：起始取列子句，本行先取「n_member」，涉 mem003（会员编号）、n_member（会员数）
               COUNT(*)*1.0/SUM(COUNT(*)) OVER() AS pct                                                     -- 计数表达式：全局窗口，用作占比之分母，产出「pct」
        FROM ods_mariadb_2b.ods_a168_member_dtl                                                             -- 取数来源：取自会员主档明细（注册与账户属性）
        GROUP BY mem003
      )
    SELECT q.*,
           -- 一·经济层
           ROUND(e.stake,4) AS stake, ROUND(e.valid,4) AS valid_bet,
           ROUND(-e.net,4) AS profit, e.n_bets, e.n_rounds,
           ROUND(e.net/NULLIF(e.stake,0),8) AS roi,
           ROUND(e.net_in/NULLIF(e.st_in,0),8) AS roi_hiturn,
           ROUND(e.net_out/NULLIF(e.st_out,0),8) AS roi_non_hiturn,
           ROUND((e.net-e.rebate)/NULLIF(e.stake,0),8) AS roi_ex_rebate,
           ROUND(e.net,4) AS roi_numerator, ROUND(e.stake,4) AS roi_denominator,
           CASE WHEN e.stake IS NULL THEN 'NULL_DENOM' WHEN e.stake<=0 THEN 'ZERO_DENOM'
                WHEN e.n_bets<30 THEN 'THIN_EXPOSURE' ELSE 'OK' END AS roi_denominator_status,
           ROUND(e.rebate,4) AS rebate_cost, ROUND(e.agent_cost,4)                           AS cost_complement_b,
       ROUND(e.agent_pct,4)                            AS pct_complement,
       ROUND(e.company_retain_pct,4)                   AS pct_top_bet23,
       'AG03-UNRESOLVED'                                     AS agent_formula_version,
      'ALL5_LEVELS_bet23_to_bet27'                    AS agent_level_scope,
      ROUND(e.agent_cost_lv1,4) AS agent_cost_lv1, ROUND(e.agent_cost_lv2,4) AS agent_cost_lv2,
      ROUND(e.agent_cost_lv3,4) AS agent_cost_lv3, ROUND(e.agent_cost_lv4,4) AS agent_cost_lv4,
      ROUND(e.agent_cost_lv5,4) AS agent_cost_lv5,
      ROUND(e.agent_pct_lv1,6) AS agent_pct_lv1, ROUND(e.agent_pct_lv2,6) AS agent_pct_lv2,
      ROUND(e.agent_pct_lv3,6) AS agent_pct_lv3, ROUND(e.agent_pct_lv4,6) AS agent_pct_lv4,
      ROUND(e.agent_pct_lv5,6) AS agent_pct_lv5,
      ROUND(e.retain_pct_lv1,6) AS retain_pct_lv1, ROUND(e.retain_pct_lv2,6) AS retain_pct_lv2,
      ROUND(e.retain_pct_lv3,6) AS retain_pct_lv3, ROUND(e.retain_pct_lv4,6) AS retain_pct_lv4,
      ROUND(e.retain_pct_lv5,6) AS retain_pct_lv5, ROUND(e.chain_depth_avg,4) AS chain_depth_avg,
      ROUND(e.agent_cost_chain_additive,4)            AS agent_cost_chain_additive,
      ROUND(e.agent_cost_chain_nested,4)              AS agent_cost_chain_nested,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_additive,4) AS residual_chain_additive,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_nested,4)   AS residual_chain_nested,
      'PENDING_AG03'                                  AS decision_status,
      'FALSE'                                         AS admit_to_risk_decision,
      'NOT_FOR_ENFORCEMENT'                           AS deliverable_class,
       ROUND(e.agent_cost_a_legacy,4)                  AS agent_cost_a_legacy,
       ROUND(e.agent_cost_valid_base_legacy,4)         AS agent_cost_valid_base_legacy,
           ROUND(-e.net-e.rebate,4)                        AS ngr,
       ROUND(-e.net-e.rebate-e.agent_cost,4)           AS residual_b,
       ROUND(-e.net-e.rebate-e.agent_cost_a_legacy,4)  AS residual_a,
           ROUND((-e.net-e.rebate)/NULLIF(e.stake,0),8)    AS ngr_rate,
       ROUND((-e.net-e.rebate-e.agent_cost)/NULLIF(e.stake,0),8)   AS residual_b_rate,
      -- 【HF9c · canonical accounting contract】
      --   以下 canonical 字段只增加明确 scope；不删除、不覆盖既有字段。
      --   formal_bet23_* 保持 HF9b 当前生产公式及其 NULL/0 语义；
      --   lv1~lv5 / additive / nested 则分别采用各自原始 e.* 成本字段，
      --   rate 一律从未舍入的 e.* 分子 / e.stake 计算，禁止由展示值反算。
      ROUND(e.agent_cost,4) AS agent_cost_bet23_formal_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost,4) AS net_margin_bet23_formal_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost)/NULLIF(e.stake,0),8) AS net_margin_bet23_formal_rate_canonical,
      ROUND(e.agent_cost_lv1,4) AS agent_cost_lv1_bet23_canonical,
      ROUND(e.agent_cost_lv2,4) AS agent_cost_lv2_bet24_canonical,
      ROUND(e.agent_cost_lv3,4) AS agent_cost_lv3_bet25_canonical,
      ROUND(e.agent_cost_lv4,4) AS agent_cost_lv4_bet26_canonical,
      ROUND(e.agent_cost_lv5,4) AS agent_cost_lv5_bet27_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_lv1,4) AS net_margin_lv1_bet23_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_lv1)/NULLIF(e.stake,0),8) AS net_margin_lv1_bet23_rate_canonical,
      ROUND(e.agent_cost_chain_additive,4) AS agent_cost_chain_additive_canonical,
      ROUND(e.agent_cost_chain_nested,4) AS agent_cost_chain_nested_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_additive,4) AS net_margin_chain_additive_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_nested,4) AS net_margin_chain_nested_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_chain_additive)/NULLIF(e.stake,0),8) AS net_margin_chain_additive_rate_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_chain_nested)/NULLIF(e.stake,0),8) AS net_margin_chain_nested_rate_canonical,
       ROUND((-e.net-e.rebate-e.agent_cost_a_legacy)/NULLIF(e.stake,0),8) AS residual_a_rate,
           -- 二·分布层
           ROUND(e.stake/NULLIF(e.n_bets,0),4) AS avg_stake_per_bet,
           ROUND(e.valid/NULLIF(e.n_rounds,0),4) AS avg_valid_bet_per_round,
           ROUND(-e.net/NULLIF(e.n_rounds,0),4) AS avg_profit_per_round,
           ROUND(-e.net/NULLIF(e.active_days,0),4) AS avg_profit_per_day,
           ROUND(-e.net/NULLIF(e.active_shoes,0),4) AS avg_profit_per_shoe,
           ROUND(e.stake/NULLIF(e.active_days,0),4) AS avg_stake_per_active_day,
           ROUND(e.n_rounds*1.0/NULLIF(e.active_days,0),4) AS avg_rounds_per_active_day,
           ROUND(e.st_in/NULLIF(e.nb_in,0),4) AS avg_stake_hiturn,
           ROUND(e.st_out/NULLIF(e.nb_out,0),4) AS avg_stake_non_hiturn,
           ROUND(e.p25,4) AS p25_stake, ROUND(e.p50,4) AS p50_stake, ROUND(e.p75,4) AS p75_stake,
           ROUND(e.p90,4) AS p90_stake, ROUND(e.p95,4) AS p95_stake, ROUND(e.p99,4) AS p99_stake,
           ROUND(e.p50_valid,4) AS p50_valid_bet, ROUND(e.p50_profit,4) AS p50_profit,
           ROUND(e.p95/NULLIF(e.p50,0),6) AS p95_over_p50,
           ROUND(e.p99/NULLIF(e.p50,0),6) AS p99_over_p50,
           ROUND((e.stake/NULLIF(e.n_bets,0))/NULLIF(e.p50,0),6) AS avg_over_p50,
           -- 三·关系层
           e.n_tables AS common_table_count, e.n_dealers AS common_dealer_count,
           e.n_ips AS common_ip_count, e.n_products AS common_product_count,
           ROUND(e.st_in/NULLIF(e.stake,0),8) AS share_hiturn,
           -- 四·rate 层
           ROUND(-e.net/NULLIF(e.stake,0),8) AS hold_rate,
           ROUND(-e.net_in/NULLIF(e.st_in,0),8) AS hold_rate_hiturn,
           ROUND(e.rebate/NULLIF(e.valid,0),8) AS rebate_rate_actual,
           ROUND(e.rbpct,6) AS rebate_pct_config,
           ROUND(e.valid/NULLIF(e.stake,0),6) AS turnover_multiple,
           ROUND(e.freecomm_rate,6) AS free_comm_rate,
           ROUND(e.net_in/NULLIF(e.st_in,0)-e.net_out/NULLIF(e.st_out,0),8) AS roi_delta_hiturn,
           -- 五·动态层
           e.first_seen_d AS first_seen, e.last_seen_d AS last_seen,
           e.active_days, e.active_shoes, e.active_sessions,
           DATEDIFF(e.last_seen_d, e.first_seen_d)+1 AS span_days,
           ROUND(e.active_days*1.0/NULLIF(DATEDIFF(e.last_seen_d,e.first_seen_d)+1,0),6) AS persistence,
           ROUND((e.st_in/NULLIF(e.nb_in,0))/NULLIF(e.st_out/NULLIF(e.nb_out,0),0),6) AS ramp_hiturn,
           ROUND((e.st_rec/NULLIF(e.nb_rec,0))/NULLIF(e.stake/NULLIF(e.n_bets,0),0),6) AS ramp_recent,
           ROUND((e.st_rec/NULLIF(e.stake,0))/0.30,6) AS stake_ramp,
           -- 六·决策层（HF9g-P5 · D-14 斧正 —— 本件属【全窗基线族】，相对刻度与决策标签一律 NULL）
           --   病灶：x_win 系全窗单行聚合（无 GROUP BY，恒 1 行，此为设计使然，非缺陷），
           --         经 CROSS JOIN 接入后 e.* 全行同值；六层之 NTILE / PERCENT_RANK 施于常数即退化，
           --         PERCENT_RANK 恒 0 ⇒ action_priority 恒判 A，全件 100% 误标。
           --   ★ 斧正原则：不给 x_win 补 GROUP BY —— 那会改变其「全窗基线」语义，属退化。
           --     正解与 #018 之 G-05／G-06 同治：范围外之行不得接受任何下游评分与决策标签。
           --   ★ 本件之 e.* 仍照常供其它列作全窗基线使用，仅六层相对刻度与决策标签置 NULL。
           CAST(NULL AS INT)                                              AS vip_tier,                        -- 空值取值：全窗基线族无实体可分档，置 NULL（NULL＝不适用，非 0）
           CAST(NULL AS DOUBLE)                                           AS economic_value,                  -- 空值取值：同上，禁以常数百分位冒充经济价值
           CAST(NULL AS DOUBLE)                                           AS roi_pr_global,                   -- 空值取值：同上
           CAST(NULL AS DOUBLE)                                           AS risk_value,                      -- 空值取值：兼容列，同上
           CAST(NULL AS DOUBLE)                                           AS pr_stake,                        -- 空值取值：兼容列，同上
           CAST(NULL AS DOUBLE)                                           AS pr_global,                       -- 空值取值：同上
           CAST(NULL AS DOUBLE)                                           AS pr_qualified,                    -- 空值取值：同上
           'GLOBAL_BASELINE_NO_ENTITY_RANKING'                            AS pr_qualified_population,         -- 字面取值：血统 —— 明示本件为全窗基线族，无实体排序总体
           CAST(NULL AS BIGINT)                                           AS pr_global_population_n,          -- 空值取值：血统 —— 不适用
           CAST(NULL AS BIGINT)                                           AS pr_qualified_population_n,       -- 空值取值：血统 —— 不适用
           'NOT_APPLICABLE_GLOBAL_BASELINE'                               AS pr_calculation_method,           -- 字面取值：血统 —— 算法不适用
           'HF9g-P5'                                                      AS pr_calculation_version,          -- 字面取值：血统 —— 算法版本
           CAST(NULL AS STRING)                                           AS evidence_flag,                   -- 空值取值：证据旗标不适用于全窗基线
           CAST(NULL AS STRING)                                           AS evidence_rate,                   -- 空值取值：同上
           CAST(NULL AS DOUBLE)                                           AS hold_ci_halfwidth_approx,        -- 空值取值：同上
           'X 全窗基线 · 不参与实体赏罚'                                    AS action_priority                  -- 字面取值：★ D-14 斧正 —— 本族恒不入赏罚，取代原 100% 误标之「A」
    FROM q
    CROSS JOIN x_win e
  ) y
) z
-- ── 逐批 WHERE 阶梯（★ 口诀：上界 ＝ 下界 ＋ 100000，两数同进）──
--    本件 T_true 未测，无需先跑 T_true；以 0 / 100000 控制本批返回区间，末批由实际行数 < 100000 判定
--    WHERE z.audit_rn >        0 AND z.audit_rn <=   100000   -- 第 1 批
--    WHERE z.audit_rn >   100000 AND z.audit_rn <=   200000   -- 第 2 批
--    WHERE z.audit_rn >   200000 AND z.audit_rn <=   300000   -- 第 3 批
--    WHERE z.audit_rn >   300000 AND z.audit_rn <=   400000   -- 第 4 批
--    WHERE z.audit_rn >   400000 AND z.audit_rn <=   500000   -- 第 5 批
--    WHERE z.audit_rn >   500000 AND z.audit_rn <=   600000   -- 第 6 批
--    WHERE z.audit_rn >   600000 AND z.audit_rn <=   700000   -- 第 7 批
--    …余批类推。第 k 批：WHERE z.audit_rn > (k-1)*100000 AND z.audit_rn <= k*100000
--    某批返回 < 100000 行即为末批，其后不再取。
--
--    ⚠ 常见误写（务必避开）：只推下界而上界不动 ——
--        WHERE z.audit_rn > 100000 AND z.audit_rn <= 100000   ← 自相矛盾，恒为假，返回空集
--        WHERE z.audit_rn > 200000 AND z.audit_rn <= 100000   ← 同上，空集
--      两个数必须**同时**前进，且始终相差 100000。
--      下界 ＝ 上一批之上界；上界 ＝ 本批之上界。
WHERE z.audit_rn > 0 AND z.audit_rn <= 100000 -- ★ HF9c 本批区间
ORDER BY z.audit_rn;


-- ══════════════════════════════════════════════════════════════════════════════════════════════
--  75. S01_player_score.csv   [总包行 2198~2320 · 原 11 列 ＋六层约 60 列]
--     典型学：M15 活跃周期　派生旗标：recent（s.x_rec = 1 · 仅供 CASE 条件聚合，全包无任何 WHERE/AND/HAVING 以此过滤）　连接：q.`member_id`
-- ══════════════════════════════════════════════════════════════════════════════════════════════
-- ── ① 先跑 T_true 留档（不足 100000 者一次导全，不必分批）──
-- ── ① T_true：HF9c 不再强制预跑完整 COUNT。
--    本批实际返回行数 < 100000 即判定为末批；全批完成后以各批 n_rows / audit_rn 范围核对总量。

-- ── ② 分批取数：第 1 批。第 k 批只改末行两数为 (k-1)*100000 与 k*100000 ──
--    审计字段二（REDTEAM 2026-08-24 裁定 · 四锁）：
--      audit_rn  全局观测坐标 —— 由**与原版审计版逐字同一**之排序键所生，两版可逐行对账
--      batch_id  物理分批信息 —— 该行所属批次，由 audit_rn 算得，非引擎所赋
--    ★ 锁三：二者皆为审计字段，**不得进入任何业务指标计算**。
--    ★ 锁四：两版经 audit_rn 逐行字段核验后，方可宣布输出完全一致。

-- ── ③ 每批取回后自证四数（任一不符即停手回报，禁止放行）──
--    n_rows        = COUNT(*)      须等于 COUNT(DISTINCT audit_rn)   （批内无重复）
--    audit_rn_min  = MIN(audit_rn) 须等于 (k-1)*100000 + 1           （与上批严丝合缝）
--    audit_rn_max  = MAX(audit_rn) 须等于 min + n_rows - 1           （批内无缺口）
--    全批取毕再验：各批 audit_rn 之并集 = 1 .. T_true，无缺号、无重号。
--     ★ 首行＝平台真净亏最多者（已扣退水与代理占成）。
--
SELECT z.*,
       CAST(FLOOR((z.audit_rn - 1) / 100000) + 1 AS INT)          AS batch_id,
       'A168_HF9F_20260827_0900' AS run_id,
       '2026-08-27 09:00:00' AS snapshot_sync_time
FROM (
  SELECT y.*,
         ROW_NUMBER() OVER (ORDER BY y.`residual_b` ASC, y.`roi` DESC, y.`member_id`) AS audit_rn   -- 行号窗口表达式：HF9g-P1 裁剪 —— 实测 (residual_b, roi, member_id) 相异组合数 723,442 ＝ 行数，已构成全序；原第 4~13 共十键永不参与比较，删之排序结果逐位不变，仅省排序缓冲
  FROM (
    WITH
      x_ranked AS (
    SELECT b.bet01, b.bet03, b.bet04, b.bet05, b.bet09, b.bet11, b.bet13,
           b.bet15, b.bet16, b.bet17, b.bet18, b.bet19, b.bet20, b.bet21,
           b.bet22, b.bet23, b.bet24, b.bet25, b.bet26, b.bet27, b.bet38, b.bet39, b.category, b.commission,
           b.dt, b.eid, b.ip, b.validbet, b.updatetime, b.sync_time,
           ROW_NUMBER() OVER (
             PARTITION BY b.bet01
             ORDER BY b.updatetime DESC, b.sync_time DESC, b.dt DESC)      AS x_rn
    FROM ods_mariadb_2b.ods_a168_bet02 b
    WHERE b.dt >= '2026-03-21' AND b.dt < '2026-08-07'
      AND b.bet02 = '101'
      AND b.sync_time <= '2026-08-27 09:00:00'
  ),
    x_testagent AS (
    SELECT age001 AS agent_id FROM ods_mariadb_2b.ods_a168_agent WHERE age022 = '1'
  ),
    x_bs0 AS (
    SELECT b.bet05 AS x_member, b.eid AS x_dealer, b.bet39 AS x_table,
           b.bet03 AS x_shoe, b.ip AS x_ip, b.bet09 AS x_product, b.dt AS x_date,
           CONCAT_WS('|', b.bet03, b.bet04, b.bet39)                      AS x_round,
           CONCAT_WS('|', b.bet39, b.bet03)                               AS x_tblshoe,
           CAST(NULLIF(TRIM(b.bet04),'') AS INT)                          AS x_rno,
           CASE WHEN b.dt >= '2026-07-08' THEN 1 ELSE 0 END               AS x_rec,
           CASE WHEN TRIM(b.commission)='1' THEN 1 ELSE 0 END             AS x_freecomm,
           CAST(NULLIF(TRIM(b.bet13),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_stake,
           CAST(NULLIF(TRIM(b.validbet),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_valid,
           CAST(NULLIF(TRIM(b.bet16),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_rebate,
           CAST(NULLIF(TRIM(b.bet17),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_net,
           CAST(NULLIF(TRIM(b.bet15),'') AS DECIMAL(20,6))                AS x_rbpct,
           COALESCE(CAST(NULLIF(TRIM(b.bet23),'') AS DECIMAL(20,6)),0)   AS x_agpct,
          NULLIF(CAST(NULLIF(TRIM(b.bet23),'') AS DECIMAL(20,6)),0)     AS x_rate1,
          NULLIF(CAST(NULLIF(TRIM(b.bet24),'') AS DECIMAL(20,6)),0)     AS x_rate2,
          NULLIF(CAST(NULLIF(TRIM(b.bet25),'') AS DECIMAL(20,6)),0)     AS x_rate3,
          NULLIF(CAST(NULLIF(TRIM(b.bet26),'') AS DECIMAL(20,6)),0)     AS x_rate4,
          NULLIF(CAST(NULLIF(TRIM(b.bet27),'') AS DECIMAL(20,6)),0)     AS x_rate5,
          (CASE WHEN NULLIF(CAST(NULLIF(TRIM(b.bet22),'') AS BIGINT),0) IS NOT NULL THEN 5
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet21),'') AS BIGINT),0) IS NOT NULL THEN 4
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet20),'') AS BIGINT),0) IS NOT NULL THEN 3
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet19),'') AS BIGINT),0) IS NOT NULL THEN 2
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet18),'') AS BIGINT),0) IS NOT NULL THEN 1
                ELSE 0 END)                                             AS x_chain_depth,
           CASE WHEN COALESCE(t1.agent_id,t2.agent_id,t3.agent_id,
                              t4.agent_id,t5.agent_id) IS NOT NULL
                THEN 1 ELSE 0 END                                        AS f_testline
    FROM x_ranked b
    LEFT JOIN x_testagent t1 ON t1.agent_id = b.bet18
    LEFT JOIN x_testagent t2 ON t2.agent_id = b.bet19
    LEFT JOIN x_testagent t3 ON t3.agent_id = b.bet20
    LEFT JOIN x_testagent t4 ON t4.agent_id = b.bet21
    LEFT JOIN x_testagent t5 ON t5.agent_id = b.bet22
    WHERE b.x_rn = 1
      AND b.category='1' AND UPPER(TRIM(b.bet38))='N'
      AND CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8)) > 0
  ),
  x_mk AS (
    SELECT s.*,
           CASE WHEN s.f_testline = 0 THEN 1 ELSE 0 END                 AS is_clean
    FROM x_bs0 s
  ),
  x_agg AS (
    SELECT s.x_member                                                        AS x_key,
           COUNT(*) AS n_bets, COUNT(DISTINCT s.x_round) AS n_rounds,
           COUNT(DISTINCT s.x_date) AS active_days, COUNT(DISTINCT s.x_tblshoe) AS active_shoes,
           COUNT(DISTINCT CONCAT_WS('|', s.x_date, s.x_table)) AS active_sessions,
           COUNT(DISTINCT s.x_table) AS n_tables, COUNT(DISTINCT s.x_dealer) AS n_dealers,
           COUNT(DISTINCT s.x_ip) AS n_ips, COUNT(DISTINCT s.x_product) AS n_products,
           MIN(s.x_date) AS first_seen_d, MAX(s.x_date) AS last_seen_d,
           SUM(s.x_stake) AS stake, SUM(s.x_valid) AS valid, SUM(s.x_rebate) AS rebate,
           SUM(s.x_net) AS net, SUM(-s.x_net *(100.0-s.x_agpct)/100.0) AS agent_cost,
           AVG(100.0-s.x_agpct)                   AS agent_pct,
           AVG(s.x_agpct)                         AS company_retain_pct,
           SUM(-s.x_net *s.x_agpct/100.0)         AS agent_cost_a_legacy,
           SUM(s.x_valid*s.x_agpct/100.0)         AS agent_cost_valid_base_legacy,
          AVG(COALESCE(s.x_rate1,100)) AS retain_pct_lv1, AVG(COALESCE(s.x_rate2,100)) AS retain_pct_lv2,
          AVG(COALESCE(s.x_rate3,100)) AS retain_pct_lv3, AVG(COALESCE(s.x_rate4,100)) AS retain_pct_lv4,
          AVG(COALESCE(s.x_rate5,100)) AS retain_pct_lv5, AVG(s.x_chain_depth) AS chain_depth_avg,
          AVG(COALESCE(100.0-s.x_rate1,0)) AS agent_pct_lv1, AVG(COALESCE(100.0-s.x_rate2,0)) AS agent_pct_lv2,
          AVG(COALESCE(100.0-s.x_rate3,0)) AS agent_pct_lv3, AVG(COALESCE(100.0-s.x_rate4,0)) AS agent_pct_lv4,
          AVG(COALESCE(100.0-s.x_rate5,0)) AS agent_pct_lv5,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate1,0)/100.0)                        AS agent_cost_lv1,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate2,0)/100.0)                        AS agent_cost_lv2,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate3,0)/100.0)                        AS agent_cost_lv3,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate4,0)/100.0)                        AS agent_cost_lv4,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate5,0)/100.0)                        AS agent_cost_lv5,
          SUM(-s.x_net*(COALESCE(100.0-s.x_rate1,0)+COALESCE(100.0-s.x_rate2,0)
                       +COALESCE(100.0-s.x_rate3,0)+COALESCE(100.0-s.x_rate4,0)
                       +COALESCE(100.0-s.x_rate5,0))/100.0)                   AS agent_cost_chain_additive,
          SUM(-s.x_net*(1.0 - CAST(COALESCE(s.x_rate1,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate2,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate3,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate4,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate5,100) AS DOUBLE)/100.0))
                                                                       AS agent_cost_chain_nested,
           AVG(s.x_rbpct) AS rbpct, AVG(s.x_freecomm*1.0) AS freecomm_rate,
           PERCENTILE_APPROX(s.x_stake,0.25) AS p25, PERCENTILE_APPROX(s.x_stake,0.50) AS p50,
           PERCENTILE_APPROX(s.x_stake,0.75) AS p75, PERCENTILE_APPROX(s.x_stake,0.90) AS p90,
           PERCENTILE_APPROX(s.x_stake,0.95) AS p95, PERCENTILE_APPROX(s.x_stake,0.99) AS p99,
           PERCENTILE_APPROX(s.x_valid,0.50) AS p50_valid,
           PERCENTILE_APPROX(s.x_net,0.50)   AS p50_profit,
           SUM(CASE WHEN s.x_rec = 1 THEN s.x_stake ELSE 0 END) AS st_in,
           SUM(CASE WHEN s.x_rec = 1 THEN 1 ELSE 0 END)         AS nb_in,
           SUM(CASE WHEN s.x_rec = 1 THEN s.x_net ELSE 0 END)   AS net_in,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN s.x_stake ELSE 0 END) AS st_out,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN 1 ELSE 0 END)         AS nb_out,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN s.x_net ELSE 0 END)   AS net_out,
           SUM(CASE WHEN s.x_rec=1 THEN s.x_stake ELSE 0 END) AS st_rec,
           SUM(CASE WHEN s.x_rec=1 THEN 1 ELSE 0 END)         AS nb_rec
    FROM x_mk s
    WHERE s.is_clean = 1
      AND s.x_member IS NOT NULL AND TRIM(CAST(s.x_member AS STRING)) <> ''
    GROUP BY s.x_member
  ),
      q AS (
        WITH ta AS (            -- 公司测试线代理（214 条，跨五级）
          SELECT DISTINCT age001 AS aid                                                                     -- 取列：产出「aid」
          FROM ods_mariadb_2b.ods_a168_agent WHERE age022 = '1'                                             -- 取数来源：取自代理主档（五级代理线归属来源）
        ),                                                                                                  -- 续行：收束上方的子查询或函数括号（交付件 S01_player_score.csv）
        rk AS (                  -- 需求 §3.2：同注单号取最新版本（三级排序去重）
          SELECT b.bet01, b.updatetime, b.sync_time, b.dt, b.bet02,                                         -- 取列：起始取列子句，本行先列 b.bet01, b.updatetime, b.sync_time, b.dt, b.bet02，涉 bet02（游戏类别）、dt（营业日）
                 b.bet03, b.bet04, b.bet05, b.bet08, b.bet09,                                               -- 续行：接续上一取列子句，续列 b.bet03, b.bet04, b.bet05, b.bet08, b.bet09，涉 bet03（靴号）、bet04（局内序号）、bet05（会员号）
                 b.bet11, b.bet13, b.bet14, b.bet16, b.bet17,                                               -- 续行：接续上一取列子句，续列 b.bet11, b.bet13, b.bet14, b.bet16, b.bet17，涉 bet11（汇率）、bet13（下注金额）、bet14（派彩金额）
                 b.bet18, b.bet19, b.bet20, b.bet21, b.bet22,                                               -- 续行：接续上一取列子句，续列 b.bet18, b.bet19, b.bet20, b.bet21, b.bet22，涉 bet18（一级代理线）、bet19（二级代理线）、bet20（三级代理线）
                 b.bet38, b.bet39, b.category, b.eid, b.ip,                                                 -- 续行：接续上一取列子句，续列 b.bet38, b.bet39, b.category, b.eid, b.ip，涉 bet38（重對）、bet39（桌号）、eid（荷官工号）
                 b.validbet,                                                                                -- 续行：接续上一取列子句，续列 b.validbet，涉 validbet（有效投注（洗码量））
                 ROW_NUMBER() OVER (                                                                        -- 行号窗口表达式：以行号窗口取每组头部或去重，免出重复行
                   PARTITION BY b.bet01                                                                     -- 窗口分区：按 b.bet01 分组开窗，组内各自编号或排名
                   ORDER BY b.updatetime DESC, b.sync_time DESC, b.dt DESC) AS rn                           -- 排序：按 b.updatetime（降序）, b.sync_time（降序）, b.dt（降序）) AS rn 排列；导出必带排序，否则分页无稳定序（曾致 36.49% 重复行）
          FROM ods_mariadb_2b.ods_a168_bet02 b                                                              -- 取数来源：取自注单明细表（金额与行为口径的第一料源）
          WHERE b.dt >= '2026-03-21' AND b.dt < '2026-08-07' AND b.bet02 = '101'
      AND b.sync_time <= '2026-08-27 09:00:00'                            -- 过滤条件：限定 b.dt不少于 '2026-03-21'、b.dt小于 '2026-08-07'、b.bet02等于 '101'，涉 bet02（游戏类别）、dt（营业日）
        ),                                                                                                  -- 续行：收束上方的子查询或函数括号（交付件 S01_player_score.csv）
        vd AS (                  -- 有效注单：非测试线、非重对、一般注单
          SELECT r.*                                                                                        -- 取列：整体承接上游结果集的全部字段，不再逐列列举
          FROM rk r                                                                                         -- 取数来源：取自本条自建的中间结果集 rk
          LEFT JOIN ta t1 ON t1.aid = r.bet18                                                               -- 左连接：取自本条自建的中间结果集 ta，连接键为 bet18（一级代理线）
          LEFT JOIN ta t2 ON t2.aid = r.bet19                                                               -- 左连接：取自本条自建的中间结果集 ta，连接键为 bet19（二级代理线）
          LEFT JOIN ta t3 ON t3.aid = r.bet20                                                               -- 左连接：取自本条自建的中间结果集 ta，连接键为 bet20（三级代理线）
          LEFT JOIN ta t4 ON t4.aid = r.bet21                                                               -- 左连接：取自本条自建的中间结果集 ta，连接键为 bet21（四级代理线）
          LEFT JOIN ta t5 ON t5.aid = r.bet22                                                               -- 左连接：取自本条自建的中间结果集 ta，连接键为 bet22（五级代理线）
          WHERE r.rn = 1 AND r.category = '1' AND UPPER(TRIM(r.bet38)) = 'N'                                -- 过滤条件：限定 r.rn等于 1、r.category等于 '1'、UPPER(TRIM(r.bet38))等于 'N'，涉 bet38（重對）
            AND CAST(NULLIF(TRIM(r.bet05),'') AS BIGINT) > 0                                                -- 并列条件：限定 CAST(NULLIF(TRIM(r.bet05),'') AS BIGINT)大于 0，涉 bet05（会员号）
            AND CAST(NULLIF(TRIM(r.bet11),'') AS DECIMAL(20,8)) > 0                                         -- 并列条件：限定 CAST(NULLIF(TRIM(r.bet11),'') AS DECIMAL(20,8))大于 0，涉 bet11（汇率）
            AND NULLIF(TRIM(r.bet08),'') IS NOT NULL                                                        -- 并列条件：限定该值非空，涉 bet08（下注时间）
            AND COALESCE(t1.aid, t2.aid, t3.aid, t4.aid, t5.aid) IS NULL                                    -- 并列条件：限定该值为空——本包以左连接加空值判定替代 EXISTS，因 StarRocks 不支持 EXISTS 配多列 IN
        ),                                                                                                  -- 续行：收束上方的子查询或函数括号（交付件 S01_player_score.csv）
        bs AS (                  -- 金额正名：本金/洗码量/游戏输赢/退水/净输赢（一律÷汇率）
          SELECT v.bet05 AS member_id, v.eid AS dealer_id, v.ip AS bet_ip,                                  -- 取列：起始取列子句，本行先取「bet_ip」，涉 bet05（会员号）、eid（荷官工号）、bet_ip（下注 IP）
                 v.bet18 AS lv1, v.bet19 AS lv2, v.bet20 AS lv3, v.bet21 AS lv4, v.bet22 AS lv5, CONCAT_WS('|', COALESCE(CAST(NULLIF(CAST(NULLIF(TRIM(v.bet18),'') AS BIGINT),0) AS STRING),'-'), COALESCE(CAST(NULLIF(CAST(NULLIF(TRIM(v.bet19),'') AS BIGINT),0) AS STRING),'-'), COALESCE(CAST(NULLIF(CAST(NULLIF(TRIM(v.bet20),'') AS BIGINT),0) AS STRING),'-'), COALESCE(CAST(NULLIF(CAST(NULLIF(TRIM(v.bet21),'') AS BIGINT),0) AS STRING),'-'), COALESCE(CAST(NULLIF(CAST(NULLIF(TRIM(v.bet22),'') AS BIGINT),0) AS STRING),'-')) AS chain_key, v.bet09 AS bet_side, v.dt AS bet_date,                                     -- 取值表达式：取用 bet09（玩法）、bet20（三级代理线）、dt（营业日），产出「bet_date」
                 CONCAT_WS('|', v.bet03, v.bet04, v.bet39) AS round_key,                                    -- 取值表达式：取用 bet03（靴号）、bet04（局内序号）、bet39（桌号），产出「round_key」
                 v.bet39 AS table_id,                                                                       -- 取值表达式：取用 bet39（桌号），产出「table_id」
                 CAST(NULLIF(TRIM(v.bet08),'') AS DATETIME) AS t_bet,                                       -- 取值表达式：先去空白、空串归 NULL，再显式转型——本库字段多为 varchar，不转型即比较失真，产出「t_bet」
                 CAST(NULLIF(TRIM(v.bet13),'') AS DECIMAL(20,4))                                            -- 取值表达式：先去空白、空串归 NULL，再显式转型——本库字段多为 varchar，不转型即比较失真
                   / CAST(NULLIF(TRIM(v.bet11),'') AS DECIMAL(20,8)) AS stake,                              -- 除法或乘法计算：先去空白、空串归 NULL，再显式转型——本库字段多为 varchar，不转型即比较失真，产出「stake」
                 CAST(NULLIF(TRIM(v.validbet),'') AS DECIMAL(20,4))                                         -- 取值表达式：先去空白、空串归 NULL，再显式转型——本库字段多为 varchar，不转型即比较失真
                   / CAST(NULLIF(TRIM(v.bet11),'') AS DECIMAL(20,8)) AS valid_bet,                          -- 除法或乘法计算：先去空白、空串归 NULL，再显式转型——本库字段多为 varchar，不转型即比较失真，产出「valid_bet」
                 (CAST(NULLIF(TRIM(v.bet14),'') AS DECIMAL(20,4))                                           -- 续行：先去空白、空串归 NULL，再显式转型——本库字段多为 varchar，不转型即比较失真
                  - CAST(NULLIF(TRIM(v.bet13),'') AS DECIMAL(20,4)))                                        -- 加减计算：先去空白、空串归 NULL，再显式转型——本库字段多为 varchar，不转型即比较失真
                   / CAST(NULLIF(TRIM(v.bet11),'') AS DECIMAL(20,8)) AS game_pnl,                           -- 除法或乘法计算：先去空白、空串归 NULL，再显式转型——本库字段多为 varchar，不转型即比较失真，产出「game_pnl」
                 CAST(NULLIF(TRIM(v.bet16),'') AS DECIMAL(20,4))                                            -- 取值表达式：先去空白、空串归 NULL，再显式转型——本库字段多为 varchar，不转型即比较失真
                   / CAST(NULLIF(TRIM(v.bet11),'') AS DECIMAL(20,8)) AS rebate,                             -- 除法或乘法计算：先去空白、空串归 NULL，再显式转型——本库字段多为 varchar，不转型即比较失真，产出「rebate」
                 CAST(NULLIF(TRIM(v.bet17),'') AS DECIMAL(20,4))                                            -- 取值表达式：先去空白、空串归 NULL，再显式转型——本库字段多为 varchar，不转型即比较失真
                   / CAST(NULLIF(TRIM(v.bet11),'') AS DECIMAL(20,8)) AS net_pnl                             -- 除法或乘法计算：先去空白、空串归 NULL，再显式转型——本库字段多为 varchar，不转型即比较失真，产出「net_pnl」
          FROM vd v                                                                                         -- 取数来源：取自本条自建的中间结果集 vd
        ),                                                                                                  -- 续行：收束上方的子查询或函数括号（交付件 S01_player_score.csv）
        lab AS (SELECT bet05 AS member_id,                                                                  -- 取值表达式：取用 bet05（会员号）、member_id（会员号），产出「member_id」
                       SUM(CASE WHEN risk='1' THEN 1 ELSE 0 END) AS n_risk_days,                            -- 汇总表达式：产出「n_risk_days」
                       SUM(CASE WHEN orders='1' THEN 1 ELSE 0 END) AS n_order_days                          -- 汇总表达式：产出「n_order_days」
                FROM ods_mariadb_2b.ods_a168_dailyreport_member GROUP BY bet05),                            -- 取数来源：取自会员日结报表（日粒度业绩与风控标记）
        /* ── 扩编维度① 投注产品结构熵 ─────────────────────────────────────
           香农熵：把该会员的投注额按 23 种投注产品拆开，看分散还是集中。
           熵高 = 庄闲和边注都押一点，是娱乐型客人的常态；
           熵低 = 火力集中在少数高赔率边注，是技术型画像的特征之一。
           赏罚方向为「赏」——熵高的客人对平台更安全。 */
        psplit AS (                                                                                         -- 公共表表达式：开启中间结果集 psplit，其后各行为其定义体（交付件 S01_player_score.csv）
          SELECT member_id, bet_side,                                                                       -- 取列：起始取列子句，本行先列 member_id, bet_side，涉 member_id（会员号）
                 SUM(stake) AS s_side,                                                                      -- 汇总表达式：取用 stake（下注额（经汇率归一化）），产出「s_side」
                 SUM(SUM(stake)) OVER (PARTITION BY member_id) AS s_all                                     -- 汇总表达式：取用 stake（下注额（经汇率归一化））、member_id（会员号），产出「s_all」
          FROM bs GROUP BY member_id, bet_side                                                              -- 取数来源：取自本条自建的中间结果集 bs
        ),                                                                                                  -- 续行：收束上方的子查询或函数括号（交付件 S01_player_score.csv）
        ent AS (                                                                                            -- 公共表表达式：开启中间结果集 ent，其后各行为其定义体（交付件 S01_player_score.csv）
          SELECT member_id,                                                                                 -- 取列：起始取列子句，本行先列 member_id，涉 member_id（会员号）
                 -SUM((s_side/s_all) * LN(s_side/s_all)) AS 投注产品结构熵                                         -- 加减计算：香农熵定义式之前置负号，与 GGR 无涉，产出「投注产品结构熵」
          FROM psplit WHERE s_all > 0 AND s_side > 0                                                        -- 取数来源：取自本条自建的中间结果集 psplit
          GROUP BY member_id                                                                                -- 分组：按 member_id 汇总
        ),                                                                                                  -- 续行：收束上方的子查询或函数括号（交付件 S01_player_score.csv）
        /* ── 扩编维度② 索提诺稳定性（会员视角的下行风险调整收益）──────────
           先把注单压成「会员×日」的日 ROI，再算 日ROI均值 ÷ 下行标准差。
           只统计低于 0 那一侧的波动——赢钱时的波动不是风险。
           赏罚方向为「罚」：赢得稳的客人正是 T2 技术型风险用户，
           赢得多但忽输忽赢的反而是正常娱乐客。**不要把方向搞反。** */
        dly AS (                                                                                            -- 公共表表达式：开启中间结果集 dly，其后各行为其定义体（交付件 S01_player_score.csv）
          SELECT member_id, bet_date,                                                                       -- 取列：起始取列子句，本行先列 member_id, bet_date，涉 member_id（会员号）、bet_date（营业日）
                 SUM(game_pnl) AS pnl_d, SUM(stake) AS stake_d                                              -- 汇总表达式：取用 stake（下注额（经汇率归一化））、game_pnl（游戏净输赢），产出「stake_d」
          FROM bs GROUP BY member_id, bet_date                                                              -- 取数来源：取自本条自建的中间结果集 bs
        ),                                                                                                  -- 续行：收束上方的子查询或函数括号（交付件 S01_player_score.csv）
        srt AS (                                                                                            -- 公共表表达式：开启中间结果集 srt，其后各行为其定义体（交付件 S01_player_score.csv）
          SELECT member_id,                                                                                 -- 取列：起始取列子句，本行先列 member_id，涉 member_id（会员号）
                 AVG(pnl_d / NULLIF(stake_d,0))                                  AS mu_roi_d,               -- 求均值表达式：产出「mu_roi_d」
                 SQRT(AVG(POW(LEAST(pnl_d / NULLIF(stake_d,0), 0), 2)))          AS dd_roi_d,               -- 取值表达式：求均值，产出「dd_roi_d」
                 AVG(pnl_d / NULLIF(stake_d,0))                                                             -- 求均值表达式：承接上一子句，构成完整语句，属 交付件 S01_player_score.csv 之取数
                   / NULLIF(SQRT(AVG(POW(LEAST(pnl_d / NULLIF(stake_d,0), 0), 2))), 0)                      -- 除法或乘法计算：求均值
                                                                                  AS 索提诺稳定性                 -- 取值表达式：取用索提诺稳定性（玩家雷达罚侧维），产出「索提诺稳定性」
          FROM dly GROUP BY member_id                                                                       -- 取数来源：取自本条自建的中间结果集 dly
        ),                                                                                                  -- 续行：收束上方的子查询或函数括号（交付件 S01_player_score.csv）
        /* ── 扩编维度③ 生命周期阶段 ──────────────────────────────────────
           首末注单跨度 × 近期活跃衰减，取值越大代表越处于成熟稳定期。
           算法：活跃跨度天数 × (1 − 距窗口右端的静默天数 / 窗口总天数)，
           新客跨度短、流失前兆者静默久，两端都会被压低。窗口 139 天为字面量。
           赏罚方向为「赏」。 */
        lc AS (                                                                                             -- 公共表表达式：开启中间结果集 lc，其后各行为其定义体（交付件 S01_player_score.csv）
          SELECT member_id,                                                                                 -- 取列：起始取列子句，本行先列 member_id，涉 member_id（会员号）
                 DATEDIFF(MAX(bet_date), MIN(bet_date)) + 1 AS span_days,                                   -- 取值表达式：取最大值、取最小值，取用 bet_date（营业日），产出「span_days」
                 DATEDIFF(DATE '2026-08-06', MAX(bet_date)) AS silent_days,                                 -- 取值表达式：取最大值，取用 bet_date（营业日），产出「silent_days」
                 (DATEDIFF(MAX(bet_date), MIN(bet_date)) + 1)                                               -- 续行：取最大值、取最小值，取用 bet_date（营业日）
                   * (1 - DATEDIFF(DATE '2026-08-06', MAX(bet_date)) / 139.0) AS 生命周期阶段                     -- 除法或乘法计算：取最大值，取用 bet_date（营业日）、生命周期阶段（玩家雷达赏侧维），产出「生命周期阶段」
          FROM bs GROUP BY member_id                                                                        -- 取数来源：取自本条自建的中间结果集 bs
        )                                                                                                   -- 续行：收束上方的子查询或函数括号（交付件 S01_player_score.csv）
        SELECT b.member_id,                                                                                 -- 取列：起始取列子句，本行先列 b.member_id，涉 member_id（会员号）
          SUM(b.valid_bet) AS 流水贡献,                                                                         -- 汇总表达式：取用 valid_bet（有效投注（洗码量））、流水贡献（玩家雷达赏侧维），产出「流水贡献」
          -SUM(b.game_pnl) AS 游戏输赢贡献,          -- 会员输=平台赢，取负号
          COUNT(DISTINCT b.bet_date) AS 活跃稳定,                                                               -- 计数表达式：统计去重个数，产出「活跃稳定」
          SUM(b.rebate) AS 退水支出,                                                                            -- 汇总表达式：取用 rebate（退水）、退水支出（退水成本），产出「退水支出」
          COUNT(DISTINCT b.bet_ip) AS n_ip,                                                                 -- 计数表达式：统计去重个数，产出「n_ip」
          COUNT(DISTINCT b.lv3) AS n_chain,                                                                 -- 计数表达式：统计去重个数，产出「n_chain」
          MAX(b.lv1) AS lv1_id, MAX(b.lv2) AS lv2_id, MAX(b.lv3) AS lv3_id,
          MAX(b.lv4) AS lv4_id, MAX(b.lv5) AS lv5_id, MAX(b.chain_key) AS chain_key,
          COUNT(DISTINCT b.chain_key) AS n_chain_key,
          CASE WHEN COUNT(DISTINCT b.chain_key)>1 THEN 1 ELSE 0 END AS f_upline_changed,
          COALESCE(MAX(l.n_risk_days),0)+COALESCE(MAX(l.n_order_days),0) AS 人工标记史,                          -- 取值表达式：取最大值，取用人工标记史（玩家雷达罚侧维），产出「人工标记史」
          -- ★ 扩编三列：报告的玩家雷达按列名取用，列名一字不可改
          MAX(e.投注产品结构熵)  AS 投注产品结构熵,                                                                       -- 取最大值表达式：取用投注产品结构熵（玩家雷达赏侧维），产出「投注产品结构熵」
          MAX(sr.索提诺稳定性)   AS 索提诺稳定性,                                                                       -- 取最大值表达式：取用索提诺稳定性（玩家雷达罚侧维），产出「索提诺稳定性」
          MAX(lcx.生命周期阶段)  AS 生命周期阶段                                                                        -- 取最大值表达式：取用生命周期阶段（玩家雷达赏侧维），产出「生命周期阶段」
        FROM bs b                                                                                           -- 取数来源：取自本条自建的中间结果集 bs
        LEFT JOIN lab l   ON l.member_id  = b.member_id                                                     -- 左连接：取自本条自建的中间结果集 lab，连接键为 member_id（会员号）
        LEFT JOIN ent e   ON e.member_id  = b.member_id                                                     -- 左连接：取自本条自建的中间结果集 ent，连接键为 member_id（会员号）
        LEFT JOIN srt sr  ON sr.member_id = b.member_id                                                     -- 左连接：取自本条自建的中间结果集 srt，连接键为 member_id（会员号）
        LEFT JOIN lc  lcx ON lcx.member_id = b.member_id                                                    -- 左连接：取自本条自建的中间结果集 lc，连接键为 member_id（会员号）
        GROUP BY b.member_id                                                                                -- 分组：按 b.member_id 汇总
--    ★★ HF9e · 宇宙门解除（Ryo Eng 裁定 2026-08-27）★★
--      原句：HAVING COUNT(DISTINCT b.round_key) >= 30            ← 本行已删除
--      语义查证：round_key = CONCAT_WS('|', bet03, bet04, bet39) = 靴号|局号|桌号，即一靴中的一手牌。
--        v1.5 PK1 已 PROVEN：不跨日、不跨桌、不跨靴，max_days_per_rk = 1，全宇宙 6,048,562 个唯一局键。
--        故原门槛之义为：该会员在 139 天窗口内【下注过的不同局】至少 30 局（非注单数，非 100 注）。
--        实测佐证：解除前 CSV 的 n_rounds 最小值 = 30、n_bets 最小值 = 30，且 n_bets >= n_rounds 恒成立。
--      解除理由（三条，皆实测）：
--        ① 静默丢弃：挡掉 562,286 名会员（77.72%）· 4,456,604 笔（3.573%）· 约 4.87 亿注额，
--           与铁律「标记而非丢弃」直接冲突；#078 对测试线即用标记不丢弃，本件应同法。
--        ② 死分支：门槛使 n_bets 恒 >= 30，决策层 'Z 证据不足 · 不动作' 永不触发（CSV 实测印证）。
--           原设计意图本就是【留下并标 Z】，是 HAVING 抢先删掉，二者重复且冲突。
--           ★ 删除本行后，Z 分支【自动复活】，无须改动决策层一字。
--        ③ 和型指标无抽样误差：stake / profit / n_bets 是精确计数，被挡者的钱一分不该少算。
--      解除后须知：本件行数由 161,156 → 723,442（4.49×），分批由 2 批 → 8 批；
--        八项台账锚全部作废重建；率型指标（roi / hold_rate）对低局数会员为噪声，
--        证据分层列（evidence_rate / hold_ci_halfwidth_approx / pr_qualified）待批准后于下一版补入。
      )
    SELECT q.*,
           -- 一·经济层
           ROUND(e.stake,4) AS stake, ROUND(e.valid,4) AS valid_bet,
           ROUND(-e.net,4) AS profit, e.n_bets, e.n_rounds,
           ROUND(e.net/NULLIF(e.stake,0),8) AS roi,
           ROUND(e.net_in/NULLIF(e.st_in,0),8) AS roi_recent,
           ROUND(e.net_out/NULLIF(e.st_out,0),8) AS roi_non_recent,
           ROUND((e.net-e.rebate)/NULLIF(e.stake,0),8) AS roi_ex_rebate,
           ROUND(e.net,4) AS roi_numerator, ROUND(e.stake,4) AS roi_denominator,
           CASE WHEN e.stake IS NULL THEN 'NULL_DENOM' WHEN e.stake<=0 THEN 'ZERO_DENOM'
                WHEN e.n_bets<30 THEN 'THIN_EXPOSURE' ELSE 'OK' END AS roi_denominator_status,
           ROUND(e.rebate,4) AS rebate_cost, ROUND(e.agent_cost,4)                           AS cost_complement_b,
       ROUND(e.agent_pct,4)                            AS pct_complement,
       ROUND(e.company_retain_pct,4)                   AS pct_top_bet23,
       'AG03-UNRESOLVED'                                     AS agent_formula_version,
      'ALL5_LEVELS_bet23_to_bet27'                    AS agent_level_scope,
      ROUND(e.agent_cost_lv1,4) AS agent_cost_lv1, ROUND(e.agent_cost_lv2,4) AS agent_cost_lv2,
      ROUND(e.agent_cost_lv3,4) AS agent_cost_lv3, ROUND(e.agent_cost_lv4,4) AS agent_cost_lv4,
      ROUND(e.agent_cost_lv5,4) AS agent_cost_lv5,
      ROUND(e.agent_pct_lv1,6) AS agent_pct_lv1, ROUND(e.agent_pct_lv2,6) AS agent_pct_lv2,
      ROUND(e.agent_pct_lv3,6) AS agent_pct_lv3, ROUND(e.agent_pct_lv4,6) AS agent_pct_lv4,
      ROUND(e.agent_pct_lv5,6) AS agent_pct_lv5,
      ROUND(e.retain_pct_lv1,6) AS retain_pct_lv1, ROUND(e.retain_pct_lv2,6) AS retain_pct_lv2,
      ROUND(e.retain_pct_lv3,6) AS retain_pct_lv3, ROUND(e.retain_pct_lv4,6) AS retain_pct_lv4,
      ROUND(e.retain_pct_lv5,6) AS retain_pct_lv5, ROUND(e.chain_depth_avg,4) AS chain_depth_avg,
      ROUND(e.agent_cost_chain_additive,4)            AS agent_cost_chain_additive,
      ROUND(e.agent_cost_chain_nested,4)              AS agent_cost_chain_nested,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_additive,4) AS residual_chain_additive,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_nested,4)   AS residual_chain_nested,
      'PENDING_AG03'                                  AS decision_status,
      'FALSE'                                         AS admit_to_risk_decision,
      'NOT_FOR_ENFORCEMENT'                           AS deliverable_class,
       ROUND(e.agent_cost_a_legacy,4)                  AS agent_cost_a_legacy,
       ROUND(e.agent_cost_valid_base_legacy,4)         AS agent_cost_valid_base_legacy,
           ROUND(-e.net-e.rebate,4)                        AS ngr,
       ROUND(-e.net-e.rebate-e.agent_cost,4)           AS residual_b,
       ROUND(-e.net-e.rebate-e.agent_cost_a_legacy,4)  AS residual_a,
           ROUND((-e.net-e.rebate)/NULLIF(e.stake,0),8)    AS ngr_rate,
       ROUND((-e.net-e.rebate-e.agent_cost)/NULLIF(e.stake,0),8)   AS residual_b_rate,
      -- 【HF9c · canonical accounting contract】
      --   以下 canonical 字段只增加明确 scope；不删除、不覆盖既有字段。
      --   formal_bet23_* 保持 HF9b 当前生产公式及其 NULL/0 语义；
      --   lv1~lv5 / additive / nested 则分别采用各自原始 e.* 成本字段，
      --   rate 一律从未舍入的 e.* 分子 / e.stake 计算，禁止由展示值反算。
      ROUND(e.agent_cost,4) AS agent_cost_bet23_formal_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost,4) AS net_margin_bet23_formal_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost)/NULLIF(e.stake,0),8) AS net_margin_bet23_formal_rate_canonical,
      ROUND(e.agent_cost_lv1,4) AS agent_cost_lv1_bet23_canonical,
      ROUND(e.agent_cost_lv2,4) AS agent_cost_lv2_bet24_canonical,
      ROUND(e.agent_cost_lv3,4) AS agent_cost_lv3_bet25_canonical,
      ROUND(e.agent_cost_lv4,4) AS agent_cost_lv4_bet26_canonical,
      ROUND(e.agent_cost_lv5,4) AS agent_cost_lv5_bet27_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_lv1,4) AS net_margin_lv1_bet23_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_lv1)/NULLIF(e.stake,0),8) AS net_margin_lv1_bet23_rate_canonical,
      ROUND(e.agent_cost_chain_additive,4) AS agent_cost_chain_additive_canonical,
      ROUND(e.agent_cost_chain_nested,4) AS agent_cost_chain_nested_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_additive,4) AS net_margin_chain_additive_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_nested,4) AS net_margin_chain_nested_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_chain_additive)/NULLIF(e.stake,0),8) AS net_margin_chain_additive_rate_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_chain_nested)/NULLIF(e.stake,0),8) AS net_margin_chain_nested_rate_canonical,
       ROUND((-e.net-e.rebate-e.agent_cost_a_legacy)/NULLIF(e.stake,0),8) AS residual_a_rate,
           -- 二·分布层
           ROUND(e.stake/NULLIF(e.n_bets,0),4) AS avg_stake_per_bet,
           ROUND(e.valid/NULLIF(e.n_rounds,0),4) AS avg_valid_bet_per_round,
           ROUND(-e.net/NULLIF(e.n_rounds,0),4) AS avg_profit_per_round,
           ROUND(-e.net/NULLIF(e.active_days,0),4) AS avg_profit_per_day,
           ROUND(-e.net/NULLIF(e.active_shoes,0),4) AS avg_profit_per_shoe,
           ROUND(e.stake/NULLIF(e.active_days,0),4) AS avg_stake_per_active_day,
           ROUND(e.n_rounds*1.0/NULLIF(e.active_days,0),4) AS avg_rounds_per_active_day,
           ROUND(e.st_in/NULLIF(e.nb_in,0),4) AS avg_stake_recent,
           ROUND(e.st_out/NULLIF(e.nb_out,0),4) AS avg_stake_non_recent,
           ROUND(e.p25,4) AS p25_stake, ROUND(e.p50,4) AS p50_stake, ROUND(e.p75,4) AS p75_stake,
           ROUND(e.p90,4) AS p90_stake, ROUND(e.p95,4) AS p95_stake, ROUND(e.p99,4) AS p99_stake,
           ROUND(e.p50_valid,4) AS p50_valid_bet, ROUND(e.p50_profit,4) AS p50_profit,
           ROUND(e.p95/NULLIF(e.p50,0),6) AS p95_over_p50,
           ROUND(e.p99/NULLIF(e.p50,0),6) AS p99_over_p50,
           ROUND((e.stake/NULLIF(e.n_bets,0))/NULLIF(e.p50,0),6) AS avg_over_p50,
           -- 三·关系层
           e.n_tables AS common_table_count, e.n_dealers AS common_dealer_count,
           e.n_ips AS common_ip_count, e.n_products AS common_product_count,
           ROUND(e.st_in/NULLIF(e.stake,0),8) AS share_recent,
           -- 四·rate 层
           ROUND(-e.net/NULLIF(e.stake,0),8) AS hold_rate,
           ROUND(-e.net_in/NULLIF(e.st_in,0),8) AS hold_rate_recent,
           ROUND(e.rebate/NULLIF(e.valid,0),8) AS rebate_rate_actual,
           ROUND(e.rbpct,6) AS rebate_pct_config,
           ROUND(e.valid/NULLIF(e.stake,0),6) AS turnover_multiple,
           ROUND(e.freecomm_rate,6) AS free_comm_rate,
           ROUND(e.net_in/NULLIF(e.st_in,0)-e.net_out/NULLIF(e.st_out,0),8) AS roi_delta_recent,
           -- 五·动态层
           e.first_seen_d AS first_seen, e.last_seen_d AS last_seen,
           e.active_days, e.active_shoes, e.active_sessions,
           DATEDIFF(e.last_seen_d, e.first_seen_d)+1 AS span_days,
           ROUND(e.active_days*1.0/NULLIF(DATEDIFF(e.last_seen_d,e.first_seen_d)+1,0),6) AS persistence,
           ROUND((e.st_in/NULLIF(e.nb_in,0))/NULLIF(e.st_out/NULLIF(e.nb_out,0),0),6) AS ramp_recent_vs_prior,
           ROUND((e.st_rec/NULLIF(e.nb_rec,0))/NULLIF(e.stake/NULLIF(e.n_bets,0),0),6) AS ramp_recent_vs_all,
           ROUND((e.st_rec/NULLIF(e.stake,0))/0.30,6) AS stake_ramp,
           -- 六·决策层（HF9f · 详见档头【HF9f 变更说明】；本段两版逐字同一）
           NTILE(5) OVER (ORDER BY e.stake) AS vip_tier,                                                        -- 窗口取值：相对刻度 B 族，全体五等分；须连同下方血统五元组一并解读，禁作硬阈值判型
           PERCENT_RANK() OVER (ORDER BY -e.net-e.rebate-e.agent_cost)    AS economic_value,                    -- 窗口取值：HF9f·F-19 修正 —— HF9e 写作 -(-…) 双负号致方向颠倒（#075 实测 corr(economic_value, residual_b) = -1.0000）；今与 action_priority 排序键归一，值大即平台真净利高
           PERCENT_RANK() OVER (ORDER BY e.net/NULLIF(e.stake,0))         AS roi_pr_global,                     -- 窗口取值：HF9f·F-17 正名 —— 本列实为 ROI（玩家净回报率）之全体百分位，与「风险」无关；旧名 risk_value 见下一行
           PERCENT_RANK() OVER (ORDER BY e.net/NULLIF(e.stake,0))         AS risk_value,                        -- 窗口取值：兼容列，恒等于 roi_pr_global，仅为下游迁移窗保留；HF9g 起废弃，禁新引用
           PERCENT_RANK() OVER (ORDER BY e.stake)                         AS pr_stake,                          -- 窗口取值：兼容列，恒等于 pr_global，原名保留以免断链
           PERCENT_RANK() OVER (ORDER BY e.stake)                         AS pr_global,                         -- 窗口取值：HF9f·F-1 双轨之一 —— 全体口径百分位，参照总体即本件全部输出行
           CASE WHEN e.n_rounds >= 30                                                                           -- 条件分支：起始分支 —— 仅在合格子集内计算合格口径百分位
                  THEN PERCENT_RANK() OVER (PARTITION BY CASE WHEN e.n_rounds >= 30 THEN 1 ELSE 0 END ORDER BY e.stake)  -- 分支取值：以合格与否分区，故本值即 n_rounds>=30 子集内之百分位
                ELSE NULL END                                             AS pr_qualified,                      -- 条件分支：收束上方分支 —— 不合格者留 NULL（NULL＝未测，非 0），产出「pr_qualified」
           'n_rounds>=30'                                                 AS pr_qualified_population,           -- 字面取值：血统 —— 合格子集之定义
           COUNT(*) OVER ()                                               AS pr_global_population_n,            -- 窗口取值：血统 —— 全体口径之参照总体规模，渲染时现算，禁写死
           SUM(CASE WHEN e.n_rounds >= 30 THEN 1 ELSE 0 END) OVER ()      AS pr_qualified_population_n,         -- 窗口取值：血统 —— 合格子集之参照总体规模，现算，禁写死
           'PERCENT_RANK_OVER_ORDER_BY_e_stake'                           AS pr_calculation_method,             -- 字面取值：血统 —— 算法标识
           'HF9f'                                                         AS pr_calculation_version,            -- 字面取值：血统 —— 算法版本
           CASE WHEN e.n_rounds IS NULL OR e.n_rounds < 30 THEN 'THIN_ROUNDS' ELSE 'OK' END AS evidence_flag,   -- 条件分支：HF9f·F-2a 证据旗标 —— THIN_ROUNDS 者禁入执行队列，仅入观察队列
           CASE WHEN e.n_rounds IS NULL       THEN NULL                                                         -- 条件分支：起始分支 —— 未测者留 NULL（自家铁律：NULL ≠ 0）
                WHEN e.n_rounds >= 31483      THEN 'L1_POWERED'                                                 -- 分支判定：MDE 反解第一档
                WHEN e.n_rounds >= 15409      THEN 'L2_CI_1P5'                                                  -- 分支判定：MDE 反解第二档
                WHEN e.n_rounds >=  8668      THEN 'L3_CI_2P0'                                                  -- 分支判定：MDE 反解第三档
                WHEN e.n_rounds >=  3852      THEN 'L4_CI_3P0'                                                  -- 分支判定：MDE 反解第四档
                ELSE 'L5_INSUFFICIENT' END                                AS evidence_rate,                     -- 条件分支：收束上方 —— HF9f·F-3 证据分档，承 HF9e 前议之 MDE 反解五档，须于 F-4 敏感性实验后复核
           ROUND(1.96 * 0.95 / SQRT(NULLIF(CAST(e.n_rounds AS DOUBLE),0)),8) AS hold_ci_halfwidth_approx,       -- 比率表达式：HF9f·F-3 逐行现算之 95% 半宽近似；常数 0.95 为登记值，本轮 #075 实测每局 ROI 隐含 σ 于最薄层为 0.9249，二者差异待 F-4 裁定
           CASE WHEN e.stake IS NULL OR e.stake<=0 OR e.n_bets<30 OR e.n_rounds IS NULL OR e.n_rounds<30 THEN 'Z 证据不足 · 不动作'  -- 条件分支：HF9f·F-2 双条件取严 —— HF9e 仅卡 e.n_bets<30，致 n_bets>=30 而 n_rounds<30 者绕过 Z（#075 实测 18,537 名，其中 8,145 名已入 A/D 待裁）；今两条件并列取严
                WHEN PERCENT_RANK() OVER (ORDER BY -e.net-e.rebate-e.agent_cost)<=0.10                          -- 分支判定：平台真净利之最低十分位
                  THEN 'A 净亏最大十分位 · 优先复核'                                                             -- 分支取值：HF9f·F-20 正名 —— 本档 Σresidual_b 于 #075 实测 = -100,236,896，系平台净亏最大群，旧名「残值最低十分位 · 待裁」名实不符
                WHEN PERCENT_RANK() OVER (ORDER BY -e.net-e.rebate-e.agent_cost)>=0.80                          -- 分支判定：平台真净利之最高二十分位
                  THEN 'D 净利最高二十分位 · 优先留存'                                                           -- 分支取值：HF9f·F-20 正名 —— 本档 Σresidual_b 于 #075 实测 = +281,733,190，系核心利润源；与 A 档方向相反，旧版同标「待裁」属名实不符
                ELSE 'E 常规' END                                          AS action_priority                   -- 条件分支：收束上方判词，产出「action_priority」
    FROM q
    LEFT JOIN x_agg e ON CAST(e.x_key AS STRING) = CAST(q.`member_id` AS STRING)
  ) y
) z
-- ── 逐批 WHERE 阶梯（★ 口诀：上界 ＝ 下界 ＋ 100000，两数同进）──
--    本件 T_true 未测，无需先跑 T_true；以 0 / 100000 控制本批返回区间，末批由实际行数 < 100000 判定
--    WHERE z.audit_rn >        0 AND z.audit_rn <=   100000   -- 第 1 批
--    WHERE z.audit_rn >   100000 AND z.audit_rn <=   200000   -- 第 2 批
--    WHERE z.audit_rn >   200000 AND z.audit_rn <=   300000   -- 第 3 批
--    WHERE z.audit_rn >   300000 AND z.audit_rn <=   400000   -- 第 4 批
--    WHERE z.audit_rn >   400000 AND z.audit_rn <=   500000   -- 第 5 批
--    WHERE z.audit_rn >   500000 AND z.audit_rn <=   600000   -- 第 6 批
--    WHERE z.audit_rn >   600000 AND z.audit_rn <=   700000   -- 第 7 批
--    …余批类推。第 k 批：WHERE z.audit_rn > (k-1)*100000 AND z.audit_rn <= k*100000
--    某批返回 < 100000 行即为末批，其后不再取。
--
--    ⚠ 常见误写（务必避开）：只推下界而上界不动 ——
--        WHERE z.audit_rn > 100000 AND z.audit_rn <= 100000   ← 自相矛盾，恒为假，返回空集
--        WHERE z.audit_rn > 200000 AND z.audit_rn <= 100000   ← 同上，空集
--      两个数必须**同时**前进，且始终相差 100000。
--      下界 ＝ 上一批之上界；上界 ＝ 本批之上界。
WHERE z.audit_rn > 0 AND z.audit_rn <= 100000 -- ★ HF9c 本批区间
ORDER BY z.audit_rn;


-- ══════════════════════════════════════════════════════════════════════════════════════════════
--  76. S02_dealer_score.csv   [总包行 2339~2458 · 原 9 列 ＋六层约 60 列]
--     典型学：M07 荷官关联　派生旗标：recent（s.x_rec = 1 · 仅供 CASE 条件聚合，全包无任何 WHERE/AND/HAVING 以此过滤）　连接：q.`dealer_id`
-- ══════════════════════════════════════════════════════════════════════════════════════════════
-- ── ① 先跑 T_true 留档（不足 100000 者一次导全，不必分批）──
-- ── ① T_true：HF9c 不再强制预跑完整 COUNT。
--    本批实际返回行数 < 100000 即判定为末批；全批完成后以各批 n_rows / audit_rn 范围核对总量。

-- ── ② 分批取数：第 1 批。第 k 批只改末行两数为 (k-1)*100000 与 k*100000 ──
--    审计字段二（REDTEAM 2026-08-24 裁定 · 四锁）：
--      audit_rn  全局观测坐标 —— 由**与原版审计版逐字同一**之排序键所生，两版可逐行对账
--      batch_id  物理分批信息 —— 该行所属批次，由 audit_rn 算得，非引擎所赋
--    ★ 锁三：二者皆为审计字段，**不得进入任何业务指标计算**。
--    ★ 锁四：两版经 audit_rn 逐行字段核验后，方可宣布输出完全一致。

-- ── ③ 每批取回后自证四数（任一不符即停手回报，禁止放行）──
--    n_rows        = COUNT(*)      须等于 COUNT(DISTINCT audit_rn)   （批内无重复）
--    audit_rn_min  = MIN(audit_rn) 须等于 (k-1)*100000 + 1           （与上批严丝合缝）
--    audit_rn_max  = MAX(audit_rn) 须等于 min + n_rows - 1           （批内无缺口）
--    全批取毕再验：各批 audit_rn 之并集 = 1 .. T_true，无缺号、无重号。
--     ★ 首行＝平台真净亏最多者（已扣退水与代理占成）。
--
SELECT z.*,
       CAST(FLOOR((z.audit_rn - 1) / 100000) + 1 AS INT)          AS batch_id,
       'A168_HF9F_20260827_0900' AS run_id,
       '2026-08-27 09:00:00' AS snapshot_sync_time
FROM (
  SELECT y.*,
         ROW_NUMBER() OVER (ORDER BY y.`residual_b` ASC, y.`roi` DESC, y.`dealer_id`, y.`在桌洗码量`, y.`客群广度`, y.`n_rounds`, y.`n_tables`, y.`桌面输赢`, y.`当值时长`, y.`节奏稳定度`, y.`特定玩家复现率`) AS audit_rn
  FROM (
    WITH
      x_ranked AS (
    SELECT b.bet01, b.bet03, b.bet04, b.bet05, b.bet09, b.bet11, b.bet13,
           b.bet15, b.bet16, b.bet17, b.bet18, b.bet19, b.bet20, b.bet21,
           b.bet22, b.bet23, b.bet24, b.bet25, b.bet26, b.bet27, b.bet38, b.bet39, b.category, b.commission,
           b.dt, b.eid, b.ip, b.validbet, b.updatetime, b.sync_time,
           ROW_NUMBER() OVER (
             PARTITION BY b.bet01
             ORDER BY b.updatetime DESC, b.sync_time DESC, b.dt DESC)      AS x_rn
    FROM ods_mariadb_2b.ods_a168_bet02 b
    WHERE b.dt >= '2026-03-21' AND b.dt < '2026-08-07'
      AND b.bet02 = '101'
      AND b.sync_time <= '2026-08-27 09:00:00'
  ),
    x_testagent AS (
    SELECT age001 AS agent_id FROM ods_mariadb_2b.ods_a168_agent WHERE age022 = '1'
  ),
    x_bs0 AS (
    SELECT b.bet05 AS x_member, b.eid AS x_dealer, b.bet39 AS x_table,
           b.bet03 AS x_shoe, b.ip AS x_ip, b.bet09 AS x_product, b.dt AS x_date,
           CONCAT_WS('|', b.bet03, b.bet04, b.bet39)                      AS x_round,
           CONCAT_WS('|', b.bet39, b.bet03)                               AS x_tblshoe,
           CAST(NULLIF(TRIM(b.bet04),'') AS INT)                          AS x_rno,
           CASE WHEN b.dt >= '2026-07-08' THEN 1 ELSE 0 END               AS x_rec,
           CASE WHEN TRIM(b.commission)='1' THEN 1 ELSE 0 END             AS x_freecomm,
           CAST(NULLIF(TRIM(b.bet13),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_stake,
           CAST(NULLIF(TRIM(b.validbet),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_valid,
           CAST(NULLIF(TRIM(b.bet16),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_rebate,
           CAST(NULLIF(TRIM(b.bet17),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_net,
           CAST(NULLIF(TRIM(b.bet15),'') AS DECIMAL(20,6))                AS x_rbpct,
           COALESCE(CAST(NULLIF(TRIM(b.bet23),'') AS DECIMAL(20,6)),0)   AS x_agpct,
          NULLIF(CAST(NULLIF(TRIM(b.bet23),'') AS DECIMAL(20,6)),0)     AS x_rate1,
          NULLIF(CAST(NULLIF(TRIM(b.bet24),'') AS DECIMAL(20,6)),0)     AS x_rate2,
          NULLIF(CAST(NULLIF(TRIM(b.bet25),'') AS DECIMAL(20,6)),0)     AS x_rate3,
          NULLIF(CAST(NULLIF(TRIM(b.bet26),'') AS DECIMAL(20,6)),0)     AS x_rate4,
          NULLIF(CAST(NULLIF(TRIM(b.bet27),'') AS DECIMAL(20,6)),0)     AS x_rate5,
          (CASE WHEN NULLIF(CAST(NULLIF(TRIM(b.bet22),'') AS BIGINT),0) IS NOT NULL THEN 5
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet21),'') AS BIGINT),0) IS NOT NULL THEN 4
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet20),'') AS BIGINT),0) IS NOT NULL THEN 3
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet19),'') AS BIGINT),0) IS NOT NULL THEN 2
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet18),'') AS BIGINT),0) IS NOT NULL THEN 1
                ELSE 0 END)                                             AS x_chain_depth,
           CASE WHEN COALESCE(t1.agent_id,t2.agent_id,t3.agent_id,
                              t4.agent_id,t5.agent_id) IS NOT NULL
                THEN 1 ELSE 0 END                                        AS f_testline
    FROM x_ranked b
    LEFT JOIN x_testagent t1 ON t1.agent_id = b.bet18
    LEFT JOIN x_testagent t2 ON t2.agent_id = b.bet19
    LEFT JOIN x_testagent t3 ON t3.agent_id = b.bet20
    LEFT JOIN x_testagent t4 ON t4.agent_id = b.bet21
    LEFT JOIN x_testagent t5 ON t5.agent_id = b.bet22
    WHERE b.x_rn = 1
      AND b.category='1' AND UPPER(TRIM(b.bet38))='N'
      AND CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8)) > 0
  ),
  x_mk AS (
    SELECT s.*,
           CASE WHEN s.f_testline = 0 THEN 1 ELSE 0 END                 AS is_clean
    FROM x_bs0 s
  ),
  x_agg AS (
    SELECT s.x_dealer                                                        AS x_key,
           COUNT(*) AS n_bets, COUNT(DISTINCT s.x_round) AS n_rounds,
           COUNT(DISTINCT s.x_date) AS active_days, COUNT(DISTINCT s.x_tblshoe) AS active_shoes,
           COUNT(DISTINCT CONCAT_WS('|', s.x_date, s.x_table)) AS active_sessions,
           COUNT(DISTINCT s.x_table) AS n_tables, COUNT(DISTINCT s.x_dealer) AS n_dealers,
           COUNT(DISTINCT s.x_ip) AS n_ips, COUNT(DISTINCT s.x_product) AS n_products,
           MIN(s.x_date) AS first_seen_d, MAX(s.x_date) AS last_seen_d,
           SUM(s.x_stake) AS stake, SUM(s.x_valid) AS valid, SUM(s.x_rebate) AS rebate,
           SUM(s.x_net) AS net, SUM(-s.x_net *(100.0-s.x_agpct)/100.0) AS agent_cost,
           AVG(100.0-s.x_agpct)                   AS agent_pct,
           AVG(s.x_agpct)                         AS company_retain_pct,
           SUM(-s.x_net *s.x_agpct/100.0)         AS agent_cost_a_legacy,
           SUM(s.x_valid*s.x_agpct/100.0)         AS agent_cost_valid_base_legacy,
          AVG(COALESCE(s.x_rate1,100)) AS retain_pct_lv1, AVG(COALESCE(s.x_rate2,100)) AS retain_pct_lv2,
          AVG(COALESCE(s.x_rate3,100)) AS retain_pct_lv3, AVG(COALESCE(s.x_rate4,100)) AS retain_pct_lv4,
          AVG(COALESCE(s.x_rate5,100)) AS retain_pct_lv5, AVG(s.x_chain_depth) AS chain_depth_avg,
          AVG(COALESCE(100.0-s.x_rate1,0)) AS agent_pct_lv1, AVG(COALESCE(100.0-s.x_rate2,0)) AS agent_pct_lv2,
          AVG(COALESCE(100.0-s.x_rate3,0)) AS agent_pct_lv3, AVG(COALESCE(100.0-s.x_rate4,0)) AS agent_pct_lv4,
          AVG(COALESCE(100.0-s.x_rate5,0)) AS agent_pct_lv5,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate1,0)/100.0)                        AS agent_cost_lv1,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate2,0)/100.0)                        AS agent_cost_lv2,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate3,0)/100.0)                        AS agent_cost_lv3,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate4,0)/100.0)                        AS agent_cost_lv4,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate5,0)/100.0)                        AS agent_cost_lv5,
          SUM(-s.x_net*(COALESCE(100.0-s.x_rate1,0)+COALESCE(100.0-s.x_rate2,0)
                       +COALESCE(100.0-s.x_rate3,0)+COALESCE(100.0-s.x_rate4,0)
                       +COALESCE(100.0-s.x_rate5,0))/100.0)                   AS agent_cost_chain_additive,
          SUM(-s.x_net*(1.0 - CAST(COALESCE(s.x_rate1,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate2,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate3,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate4,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate5,100) AS DOUBLE)/100.0))
                                                                       AS agent_cost_chain_nested,
           AVG(s.x_rbpct) AS rbpct, AVG(s.x_freecomm*1.0) AS freecomm_rate,
           PERCENTILE_APPROX(s.x_stake,0.25) AS p25, PERCENTILE_APPROX(s.x_stake,0.50) AS p50,
           PERCENTILE_APPROX(s.x_stake,0.75) AS p75, PERCENTILE_APPROX(s.x_stake,0.90) AS p90,
           PERCENTILE_APPROX(s.x_stake,0.95) AS p95, PERCENTILE_APPROX(s.x_stake,0.99) AS p99,
           PERCENTILE_APPROX(s.x_valid,0.50) AS p50_valid,
           PERCENTILE_APPROX(s.x_net,0.50)   AS p50_profit,
           SUM(CASE WHEN s.x_rec = 1 THEN s.x_stake ELSE 0 END) AS st_in,
           SUM(CASE WHEN s.x_rec = 1 THEN 1 ELSE 0 END)         AS nb_in,
           SUM(CASE WHEN s.x_rec = 1 THEN s.x_net ELSE 0 END)   AS net_in,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN s.x_stake ELSE 0 END) AS st_out,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN 1 ELSE 0 END)         AS nb_out,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN s.x_net ELSE 0 END)   AS net_out,
           SUM(CASE WHEN s.x_rec=1 THEN s.x_stake ELSE 0 END) AS st_rec,
           SUM(CASE WHEN s.x_rec=1 THEN 1 ELSE 0 END)         AS nb_rec
    FROM x_mk s
    WHERE s.is_clean = 1
      AND s.x_dealer IS NOT NULL AND TRIM(CAST(s.x_dealer AS STRING)) <> ''
    GROUP BY s.x_dealer
  ),
      q AS (
        WITH ta AS (            -- 公司测试线代理（214 条，跨五级）
          SELECT DISTINCT age001 AS aid                                                                     -- 取列：产出「aid」
          FROM ods_mariadb_2b.ods_a168_agent WHERE age022 = '1'                                             -- 取数来源：取自代理主档（五级代理线归属来源）
        ),                                                                                                  -- 续行：收束上方的子查询或函数括号（交付件 S02_dealer_score.csv）
        rk AS (                  -- 需求 §3.2：同注单号取最新版本（三级排序去重）
          SELECT b.bet01, b.updatetime, b.sync_time, b.dt,                                                  -- 取列：起始取列子句，本行先列 b.bet01, b.updatetime, b.sync_time, b.dt，涉 dt（营业日）
                 b.category, b.bet38, b.bet05, b.bet11, b.bet08,                                            -- 续行：接续上一取列子句，续列 b.category, b.bet38, b.bet05, b.bet11, b.bet08，涉 bet05（会员号）、bet08（下注时间）、bet11（汇率）
                 b.bet18, b.bet19, b.bet20, b.bet21, b.bet22,                                               -- 续行：接续上一取列子句，续列 b.bet18, b.bet19, b.bet20, b.bet21, b.bet22，涉 bet18（一级代理线）、bet19（二级代理线）、bet20（三级代理线）
                 b.bet03, b.bet04, b.bet39, b.eid,                                                          -- 续行：接续上一取列子句，续列 b.bet03, b.bet04, b.bet39, b.eid，涉 bet03（靴号）、bet04（局内序号）、bet39（桌号）
                 b.validbet, b.bet13, b.bet14,                                                              -- 续行：接续上一取列子句，续列 b.validbet, b.bet13, b.bet14，涉 bet13（下注金额）、bet14（派彩金额）、validbet（有效投注（洗码量））
                 ROW_NUMBER() OVER (                                                                        -- 行号窗口表达式：以行号窗口取每组头部或去重，免出重复行
                   PARTITION BY b.bet01                                                                     -- 窗口分区：按 b.bet01 分组开窗，组内各自编号或排名
                   ORDER BY b.updatetime DESC, b.sync_time DESC, b.dt DESC) AS rn                           -- 排序：按 b.updatetime（降序）, b.sync_time（降序）, b.dt（降序）) AS rn 排列；导出必带排序，否则分页无稳定序（曾致 36.49% 重复行）
          FROM ods_mariadb_2b.ods_a168_bet02 b                                                              -- 取数来源：取自注单明细表（金额与行为口径的第一料源）
          WHERE b.dt >= '2026-03-21' AND b.dt < '2026-08-07' AND b.bet02 = '101'
      AND b.sync_time <= '2026-08-27 09:00:00'                            -- 过滤条件：限定 b.dt不少于 '2026-03-21'、b.dt小于 '2026-08-07'、b.bet02等于 '101'，涉 bet02（游戏类别）、dt（营业日）
        ),                                                                                                  -- 续行：收束上方的子查询或函数括号（交付件 S02_dealer_score.csv）
        vd AS (                  -- 有效注单：非测试线、非重对、一般注单（谓词与原版一字不差）
          SELECT r.*                                                                                        -- 取列：整体承接上游结果集的全部字段，不再逐列列举
          FROM rk r                                                                                         -- 取数来源：取自本条自建的中间结果集 rk
          LEFT JOIN ta t1 ON t1.aid = r.bet18                                                               -- 左连接：取自本条自建的中间结果集 ta，连接键为 bet18（一级代理线）
          LEFT JOIN ta t2 ON t2.aid = r.bet19                                                               -- 左连接：取自本条自建的中间结果集 ta，连接键为 bet19（二级代理线）
          LEFT JOIN ta t3 ON t3.aid = r.bet20                                                               -- 左连接：取自本条自建的中间结果集 ta，连接键为 bet20（三级代理线）
          LEFT JOIN ta t4 ON t4.aid = r.bet21                                                               -- 左连接：取自本条自建的中间结果集 ta，连接键为 bet21（四级代理线）
          LEFT JOIN ta t5 ON t5.aid = r.bet22                                                               -- 左连接：取自本条自建的中间结果集 ta，连接键为 bet22（五级代理线）
          WHERE r.rn = 1 AND r.category = '1' AND UPPER(TRIM(r.bet38)) = 'N'                                -- 过滤条件：限定 r.rn等于 1、r.category等于 '1'、UPPER(TRIM(r.bet38))等于 'N'，涉 bet38（重對）
            AND CAST(NULLIF(TRIM(r.bet05),'') AS BIGINT) > 0                                                -- 并列条件：限定 CAST(NULLIF(TRIM(r.bet05),'') AS BIGINT)大于 0，涉 bet05（会员号）
            AND CAST(NULLIF(TRIM(r.bet11),'') AS DECIMAL(20,8)) > 0                                         -- 并列条件：限定 CAST(NULLIF(TRIM(r.bet11),'') AS DECIMAL(20,8))大于 0，涉 bet11（汇率）
            AND NULLIF(TRIM(r.bet08),'') IS NOT NULL                                                        -- 并列条件：限定该值非空，涉 bet08（下注时间）
            AND COALESCE(t1.aid, t2.aid, t3.aid, t4.aid, t5.aid) IS NULL                                    -- 并列条件：限定该值为空——本包以左连接加空值判定替代 EXISTS，因 StarRocks 不支持 EXISTS 配多列 IN
        ),                                                                                                  -- 续行：收束上方的子查询或函数括号（交付件 S02_dealer_score.csv）
        bs AS (                  -- 金额正名（只保留本查询实际使用的量）
          SELECT v.bet05 AS member_id, v.eid AS dealer_id,                                                  -- 取列：起始取列子句，本行先取「dealer_id」，涉 bet05（会员号）、eid（荷官工号）、member_id（会员号）
                 CONCAT_WS('|', v.bet03, v.bet04, v.bet39) AS round_key,                                    -- 取值表达式：取用 bet03（靴号）、bet04（局内序号）、bet39（桌号），产出「round_key」
                 v.bet39 AS table_id,                                                                       -- 取值表达式：取用 bet39（桌号），产出「table_id」
                 CAST(NULLIF(TRIM(v.validbet),'') AS DECIMAL(20,4))                                         -- 取值表达式：先去空白、空串归 NULL，再显式转型——本库字段多为 varchar，不转型即比较失真
                   / CAST(NULLIF(TRIM(v.bet11),'') AS DECIMAL(20,8)) AS valid_bet,                          -- 除法或乘法计算：先去空白、空串归 NULL，再显式转型——本库字段多为 varchar，不转型即比较失真，产出「valid_bet」
                 (CAST(NULLIF(TRIM(v.bet14),'') AS DECIMAL(20,4))                                           -- 续行：先去空白、空串归 NULL，再显式转型——本库字段多为 varchar，不转型即比较失真
                  - CAST(NULLIF(TRIM(v.bet13),'') AS DECIMAL(20,4)))                                        -- 加减计算：先去空白、空串归 NULL，再显式转型——本库字段多为 varchar，不转型即比较失真
                   / CAST(NULLIF(TRIM(v.bet11),'') AS DECIMAL(20,8)) AS game_pnl                            -- 除法或乘法计算：先去空白、空串归 NULL，再显式转型——本库字段多为 varchar，不转型即比较失真，产出「game_pnl」
          FROM vd v                                                                                         -- 取数来源：取自本条自建的中间结果集 vd
          WHERE NULLIF(TRIM(v.eid),'') IS NOT NULL   -- 空荷官行本就不进任何输出组，前置过滤不改输出
            AND TRIM(v.eid) NOT IN ('-1', '0')       -- 哨兵荷官号一并剔除：-1／0 非真实荷官，不得入评分（2026-08-11 增）
        ),                                                                                                  -- 续行：收束上方的子查询或函数括号（交付件 S02_dealer_score.csv）
        bd AS (                  -- ★ 一次坍缩：荷官×桌×会员×局。bs 全文只被此处引用一次
          SELECT dealer_id, table_id, member_id, round_key,                                                 -- 取列：起始取列子句，本行先列 dealer_id, table_id, member_id, round_key，涉 round_key（局键）、member_id（会员号）、dealer_id（荷官工号）
                 COUNT(*)       AS n_bet_rows,     -- 该组合的注单行数（pace 的权重）
                 SUM(valid_bet) AS v_sum,                                                                   -- 汇总表达式：取用 valid_bet（有效投注（洗码量）），产出「v_sum」
                 SUM(game_pnl)  AS g_sum                                                                    -- 汇总表达式：取用 game_pnl（游戏净输赢），产出「g_sum」
          FROM bs                                                                                           -- 取数来源：取自本条自建的中间结果集 bs
          GROUP BY dealer_id, table_id, member_id, round_key                                                -- 分组：按 dealer_id, table_id, member_id, round_key 汇总
        ),                                                                                                  -- 续行：收束上方的子查询或函数括号（交付件 S02_dealer_score.csv）
        /* ── 扩编维度① 当值时长 ─────────────────────────────────────────
           以「在册局数」为分层基准。不做这一层分层，裸排名的榜首永远是
           上班天数最少的新人——他们样本少、波动大，任何比率指标都会虚高。
           赏罚方向为「赏」。 */
        /* ── 扩编维度② 节奏稳定度：加权矩坍缩版 ─────────────────────────
           原式 = 对「荷官的每笔注单 × 同桌每一局的时长」求 STDDEV_SAMP。
           等价于：每桌局时长以该荷官在该桌的注单行数加权。
           样本标准差只需三个矩：N=Σw·n、S1=Σw·Σx、S2=Σw·Σx²，
           var = (S2 − S1²/N)/(N−1)。桌级统计仅数百行，荷官×桌仅数千行。
           节奏忽快忽慢是操作异常的先兆，也会影响玩家体验。赏罚方向为「赏」。 */
        gi AS (                                                                                             -- 公共表表达式：开启中间结果集 gi，其后各行为其定义体（交付件 S02_dealer_score.csv）
          SELECT gi011 AS table_id,                                                                         -- 取列：起始取列子句，本行先取「table_id」，涉 gi011（桌号）
                 UNIX_TIMESTAMP(gi006) - UNIX_TIMESTAMP(gi004) AS sec_round                                 -- 取值表达式：取用 gi004（局开始时刻）、gi006（开牌时刻），产出「sec_round」
          FROM ods_mariadb_2b.ods_a168_game_info                                                            -- 取数来源：取自局信息表（靴局、开牌与桌号的时序基准）
          WHERE gi001 = '101' AND gi013 = '1'                                                               -- 过滤条件：限定 gi001等于 '101'、gi013等于 '1'，涉 gi001（局主键）
            AND gi004 >= '2026-03-21' AND gi004 < '2026-08-07'                                              -- 并列条件：限定 gi004不少于 '2026-03-21'、gi004小于 '2026-08-07'，涉 gi004（局开始时刻）
        ),                                                                                                  -- 续行：收束上方的子查询或函数括号（交付件 S02_dealer_score.csv）
        git AS (                 -- 每桌三矩（COUNT/SUM 天然忽略 NULL，与 STDDEV_SAMP 同语义）
          SELECT table_id,                                                                                  -- 取列：起始取列子句，本行先列 table_id
                 COUNT(sec_round)                                            AS n_g,                        -- 计数表达式：产出「n_g」
                 SUM(CAST(sec_round AS DOUBLE))                              AS s1,                         -- 汇总表达式：产出「s1」
                 SUM(CAST(sec_round AS DOUBLE) * CAST(sec_round AS DOUBLE))  AS s2                          -- 汇总表达式：产出「s2」
          FROM gi GROUP BY table_id                                                                         -- 取数来源：取自本条自建的中间结果集 gi
        ),                                                                                                  -- 续行：收束上方的子查询或函数括号（交付件 S02_dealer_score.csv）
        dtc AS (                 -- 荷官×桌的注单行数（加权权重）
          SELECT dealer_id, table_id, SUM(n_bet_rows) AS n_rows                                             -- 取列：汇总，取用 dealer_id（荷官工号），产出「n_rows」
          FROM bd GROUP BY dealer_id, table_id                                                              -- 取数来源：取自本条自建的中间结果集 bd
        ),                                                                                                  -- 续行：收束上方的子查询或函数括号（交付件 S02_dealer_score.csv）
        pace AS (                                                                                           -- 公共表表达式：开启中间结果集 pace，其后各行为其定义体（交付件 S02_dealer_score.csv）
          SELECT d.dealer_id,                                                                               -- 取列：起始取列子句，本行先列 d.dealer_id，涉 dealer_id（荷官工号）
                 CASE                                                                                       -- 条件分支：开启分支判定，其后逐行列出条件与取值（交付件 S02_dealer_score.csv）
                   WHEN SUM(d.n_rows * g.n_g) >= 2 THEN                                                     -- 分支判定：汇总
                     1.0 / (1.0 + COALESCE(SQRT(GREATEST(                                                   -- 取值表达式：承接上一子句，构成完整语句，属 交付件 S02_dealer_score.csv 之取数
                       ( SUM(d.n_rows * g.s2)                                                               -- 续行：汇总
                         - SUM(d.n_rows * g.s1) * SUM(d.n_rows * g.s1)                                      -- 加减计算：二阶矩减一阶矩平方 ＝ 方差，与 GGR 无涉
                           / SUM(d.n_rows * CAST(g.n_g AS DOUBLE)) )                                        -- 除法或乘法计算：汇总
                       / (SUM(d.n_rows * CAST(g.n_g AS DOUBLE)) - 1), 0)), 0))                              -- 除法或乘法计算：汇总
                   ELSE 1.0     -- 原版：样本≤1 时 STDDEV_SAMP=NULL → COALESCE 0 → 稳定度 1.0
                 END AS 节奏稳定度                                                                               -- 分支收束：结束条件分支并收敛为单一取值
          FROM dtc d JOIN git g ON g.table_id = d.table_id                                                  -- 取数来源：取自本条自建的中间结果集 dtc，连接键为 g.table_id = d.table_id
          GROUP BY d.dealer_id                                                                              -- 分组：按 d.dealer_id 汇总
        ),                                                                                                  -- 续行：收束上方的子查询或函数括号（交付件 S02_dealer_score.csv）
        /* ── 扩编维度③ 特定玩家复现率：改从 bd 派生，语义不变 ────────────
           该荷官桌上「出现最频繁的那一位会员」占其总局数的比例。
           正常荷官服务的是流动客群，比例低；比例畸高说明有固定的人一直跟着他，
           这是玩家—荷官关联的第一道筛。赏罚方向为「罚」。 */
        mrep AS (                                                                                           -- 公共表表达式：开启中间结果集 mrep，其后各行为其定义体（交付件 S02_dealer_score.csv）
          SELECT dealer_id, member_id, COUNT(DISTINCT round_key) AS n_r                                     -- 取列：统计去重个数，产出「n_r」
          FROM bd GROUP BY dealer_id, member_id                                                             -- 取数来源：取自本条自建的中间结果集 bd
        ),                                                                                                  -- 续行：收束上方的子查询或函数括号（交付件 S02_dealer_score.csv）
        top1 AS (                                                                                           -- 公共表表达式：开启中间结果集 top1，其后各行为其定义体（交付件 S02_dealer_score.csv）
          SELECT dealer_id, MAX(n_r) AS max_member_rounds                                                   -- 取列：取最大值，取用 dealer_id（荷官工号），产出「max_member_rounds」
          FROM mrep GROUP BY dealer_id                                                                      -- 取数来源：取自本条自建的中间结果集 mrep
        )                                                                                                   -- 续行：收束上方的子查询或函数括号（交付件 S02_dealer_score.csv）
        SELECT b.dealer_id,                                                                                 -- 取列：起始取列子句，本行先列 b.dealer_id，涉 dealer_id（荷官工号）
          SUM(b.v_sum) AS 在桌洗码量,                                                                            -- 汇总表达式：取用在桌洗码量（荷官雷达赏侧维），产出「在桌洗码量」
          COUNT(DISTINCT b.member_id) AS 客群广度,                                                              -- 计数表达式：统计去重个数，产出「客群广度」
          COUNT(DISTINCT b.round_key) AS n_rounds,                                                          -- 计数表达式：统计去重个数，产出「n_rounds」
          COUNT(DISTINCT b.table_id) AS n_tables,                                                           -- 计数表达式：统计去重个数，产出「n_tables」
          SUM(b.g_sum) AS 桌面输赢,                                                                             -- 汇总表达式：产出「桌面输赢」
          -- ★ 扩编三列：报告的荷官雷达按列名取用，列名一字不可改
          COUNT(DISTINCT b.round_key) AS 当值时长,                                                              -- 计数表达式：统计去重个数，产出「当值时长」
          MAX(p.节奏稳定度) AS 节奏稳定度,                                                                            -- 取最大值表达式：取用节奏稳定度（荷官雷达赏侧维），产出「节奏稳定度」
          MAX(t.max_member_rounds) * 1.0                                                                    -- 取值表达式：比率之分子，乘 1.0 以避整数除法截断
            / NULLIF(COUNT(DISTINCT b.round_key), 0) AS 特定玩家复现率                                             -- 除法或乘法计算：统计去重个数，产出「特定玩家复现率」
        FROM bd b                                                                                           -- 取数来源：取自本条自建的中间结果集 bd
        LEFT JOIN pace p ON p.dealer_id = b.dealer_id                                                       -- 左连接：取自本条自建的中间结果集 pace，连接键为 dealer_id（荷官工号）
        LEFT JOIN top1 t ON t.dealer_id = b.dealer_id                                                       -- 左连接：取自本条自建的中间结果集 top1，连接键为 dealer_id（荷官工号）
        GROUP BY b.dealer_id
      )
    SELECT q.*,
           -- 一·经济层
           ROUND(e.stake,4) AS stake, ROUND(e.valid,4) AS valid_bet,
           ROUND(-e.net,4) AS profit, e.n_bets, e.n_rounds AS n_rounds_xagg,
           ROUND(e.net/NULLIF(e.stake,0),8) AS roi,
           ROUND(e.net_in/NULLIF(e.st_in,0),8) AS roi_recent,
           ROUND(e.net_out/NULLIF(e.st_out,0),8) AS roi_non_recent,
           ROUND((e.net-e.rebate)/NULLIF(e.stake,0),8) AS roi_ex_rebate,
           ROUND(e.net,4) AS roi_numerator, ROUND(e.stake,4) AS roi_denominator,
           CASE WHEN e.stake IS NULL THEN 'NULL_DENOM' WHEN e.stake<=0 THEN 'ZERO_DENOM'
                WHEN e.n_bets<30 THEN 'THIN_EXPOSURE' ELSE 'OK' END AS roi_denominator_status,
           ROUND(e.rebate,4) AS rebate_cost, ROUND(e.agent_cost,4)                           AS cost_complement_b,
       ROUND(e.agent_pct,4)                            AS pct_complement,
       ROUND(e.company_retain_pct,4)                   AS pct_top_bet23,
       'AG03-UNRESOLVED'                                     AS agent_formula_version,
      'ALL5_LEVELS_bet23_to_bet27'                    AS agent_level_scope,
      ROUND(e.agent_cost_lv1,4) AS agent_cost_lv1, ROUND(e.agent_cost_lv2,4) AS agent_cost_lv2,
      ROUND(e.agent_cost_lv3,4) AS agent_cost_lv3, ROUND(e.agent_cost_lv4,4) AS agent_cost_lv4,
      ROUND(e.agent_cost_lv5,4) AS agent_cost_lv5,
      ROUND(e.agent_pct_lv1,6) AS agent_pct_lv1, ROUND(e.agent_pct_lv2,6) AS agent_pct_lv2,
      ROUND(e.agent_pct_lv3,6) AS agent_pct_lv3, ROUND(e.agent_pct_lv4,6) AS agent_pct_lv4,
      ROUND(e.agent_pct_lv5,6) AS agent_pct_lv5,
      ROUND(e.retain_pct_lv1,6) AS retain_pct_lv1, ROUND(e.retain_pct_lv2,6) AS retain_pct_lv2,
      ROUND(e.retain_pct_lv3,6) AS retain_pct_lv3, ROUND(e.retain_pct_lv4,6) AS retain_pct_lv4,
      ROUND(e.retain_pct_lv5,6) AS retain_pct_lv5, ROUND(e.chain_depth_avg,4) AS chain_depth_avg,
      ROUND(e.agent_cost_chain_additive,4)            AS agent_cost_chain_additive,
      ROUND(e.agent_cost_chain_nested,4)              AS agent_cost_chain_nested,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_additive,4) AS residual_chain_additive,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_nested,4)   AS residual_chain_nested,
      'PENDING_AG03'                                  AS decision_status,
      'FALSE'                                         AS admit_to_risk_decision,
      'NOT_FOR_ENFORCEMENT'                           AS deliverable_class,
       ROUND(e.agent_cost_a_legacy,4)                  AS agent_cost_a_legacy,
       ROUND(e.agent_cost_valid_base_legacy,4)         AS agent_cost_valid_base_legacy,
           ROUND(-e.net-e.rebate,4)                        AS ngr,
       ROUND(-e.net-e.rebate-e.agent_cost,4)           AS residual_b,
       ROUND(-e.net-e.rebate-e.agent_cost_a_legacy,4)  AS residual_a,
           ROUND((-e.net-e.rebate)/NULLIF(e.stake,0),8)    AS ngr_rate,
       ROUND((-e.net-e.rebate-e.agent_cost)/NULLIF(e.stake,0),8)   AS residual_b_rate,
      -- 【HF9c · canonical accounting contract】
      --   以下 canonical 字段只增加明确 scope；不删除、不覆盖既有字段。
      --   formal_bet23_* 保持 HF9b 当前生产公式及其 NULL/0 语义；
      --   lv1~lv5 / additive / nested 则分别采用各自原始 e.* 成本字段，
      --   rate 一律从未舍入的 e.* 分子 / e.stake 计算，禁止由展示值反算。
      ROUND(e.agent_cost,4) AS agent_cost_bet23_formal_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost,4) AS net_margin_bet23_formal_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost)/NULLIF(e.stake,0),8) AS net_margin_bet23_formal_rate_canonical,
      ROUND(e.agent_cost_lv1,4) AS agent_cost_lv1_bet23_canonical,
      ROUND(e.agent_cost_lv2,4) AS agent_cost_lv2_bet24_canonical,
      ROUND(e.agent_cost_lv3,4) AS agent_cost_lv3_bet25_canonical,
      ROUND(e.agent_cost_lv4,4) AS agent_cost_lv4_bet26_canonical,
      ROUND(e.agent_cost_lv5,4) AS agent_cost_lv5_bet27_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_lv1,4) AS net_margin_lv1_bet23_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_lv1)/NULLIF(e.stake,0),8) AS net_margin_lv1_bet23_rate_canonical,
      ROUND(e.agent_cost_chain_additive,4) AS agent_cost_chain_additive_canonical,
      ROUND(e.agent_cost_chain_nested,4) AS agent_cost_chain_nested_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_additive,4) AS net_margin_chain_additive_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_nested,4) AS net_margin_chain_nested_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_chain_additive)/NULLIF(e.stake,0),8) AS net_margin_chain_additive_rate_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_chain_nested)/NULLIF(e.stake,0),8) AS net_margin_chain_nested_rate_canonical,
       ROUND((-e.net-e.rebate-e.agent_cost_a_legacy)/NULLIF(e.stake,0),8) AS residual_a_rate,
           -- 二·分布层
           ROUND(e.stake/NULLIF(e.n_bets,0),4) AS avg_stake_per_bet,
           ROUND(e.valid/NULLIF(e.n_rounds,0),4) AS avg_valid_bet_per_round,
           ROUND(-e.net/NULLIF(e.n_rounds,0),4) AS avg_profit_per_round,
           ROUND(-e.net/NULLIF(e.active_days,0),4) AS avg_profit_per_day,
           ROUND(-e.net/NULLIF(e.active_shoes,0),4) AS avg_profit_per_shoe,
           ROUND(e.stake/NULLIF(e.active_days,0),4) AS avg_stake_per_active_day,
           ROUND(e.n_rounds*1.0/NULLIF(e.active_days,0),4) AS avg_rounds_per_active_day,
           ROUND(e.st_in/NULLIF(e.nb_in,0),4) AS avg_stake_recent,
           ROUND(e.st_out/NULLIF(e.nb_out,0),4) AS avg_stake_non_recent,
           ROUND(e.p25,4) AS p25_stake, ROUND(e.p50,4) AS p50_stake, ROUND(e.p75,4) AS p75_stake,
           ROUND(e.p90,4) AS p90_stake, ROUND(e.p95,4) AS p95_stake, ROUND(e.p99,4) AS p99_stake,
           ROUND(e.p50_valid,4) AS p50_valid_bet, ROUND(e.p50_profit,4) AS p50_profit,
           ROUND(e.p95/NULLIF(e.p50,0),6) AS p95_over_p50,
           ROUND(e.p99/NULLIF(e.p50,0),6) AS p99_over_p50,
           ROUND((e.stake/NULLIF(e.n_bets,0))/NULLIF(e.p50,0),6) AS avg_over_p50,
           -- 三·关系层
           e.n_tables AS common_table_count, e.n_dealers AS common_dealer_count,
           e.n_ips AS common_ip_count, e.n_products AS common_product_count,
           ROUND(e.st_in/NULLIF(e.stake,0),8) AS share_recent,
           -- 四·rate 层
           ROUND(-e.net/NULLIF(e.stake,0),8) AS hold_rate,
           ROUND(-e.net_in/NULLIF(e.st_in,0),8) AS hold_rate_recent,
           ROUND(e.rebate/NULLIF(e.valid,0),8) AS rebate_rate_actual,
           ROUND(e.rbpct,6) AS rebate_pct_config,
           ROUND(e.valid/NULLIF(e.stake,0),6) AS turnover_multiple,
           ROUND(e.freecomm_rate,6) AS free_comm_rate,
           ROUND(e.net_in/NULLIF(e.st_in,0)-e.net_out/NULLIF(e.st_out,0),8) AS roi_delta_recent,
           -- 五·动态层
           e.first_seen_d AS first_seen, e.last_seen_d AS last_seen,
           e.active_days, e.active_shoes, e.active_sessions,
           DATEDIFF(e.last_seen_d, e.first_seen_d)+1 AS span_days,
           ROUND(e.active_days*1.0/NULLIF(DATEDIFF(e.last_seen_d,e.first_seen_d)+1,0),6) AS persistence,
           ROUND((e.st_in/NULLIF(e.nb_in,0))/NULLIF(e.st_out/NULLIF(e.nb_out,0),0),6) AS ramp_recent_vs_prior,
           ROUND((e.st_rec/NULLIF(e.nb_rec,0))/NULLIF(e.stake/NULLIF(e.n_bets,0),0),6) AS ramp_recent_vs_all,
           ROUND((e.st_rec/NULLIF(e.stake,0))/0.30,6) AS stake_ramp,
           -- 六·决策层（HF9f · 详见档头【HF9f 变更说明】；本段两版逐字同一）
           NTILE(5) OVER (ORDER BY e.stake) AS vip_tier,                                                        -- 窗口取值：相对刻度 B 族，全体五等分；须连同下方血统五元组一并解读，禁作硬阈值判型
           PERCENT_RANK() OVER (ORDER BY -e.net-e.rebate-e.agent_cost)    AS economic_value,                    -- 窗口取值：HF9f·F-19 修正 —— HF9e 写作 -(-…) 双负号致方向颠倒（#075 实测 corr(economic_value, residual_b) = -1.0000）；今与 action_priority 排序键归一，值大即平台真净利高
           PERCENT_RANK() OVER (ORDER BY e.net/NULLIF(e.stake,0))         AS roi_pr_global,                     -- 窗口取值：HF9f·F-17 正名 —— 本列实为 ROI（玩家净回报率）之全体百分位，与「风险」无关；旧名 risk_value 见下一行
           PERCENT_RANK() OVER (ORDER BY e.net/NULLIF(e.stake,0))         AS risk_value,                        -- 窗口取值：兼容列，恒等于 roi_pr_global，仅为下游迁移窗保留；HF9g 起废弃，禁新引用
           PERCENT_RANK() OVER (ORDER BY e.stake)                         AS pr_stake,                          -- 窗口取值：兼容列，恒等于 pr_global，原名保留以免断链
           PERCENT_RANK() OVER (ORDER BY e.stake)                         AS pr_global,                         -- 窗口取值：HF9f·F-1 双轨之一 —— 全体口径百分位，参照总体即本件全部输出行
           CASE WHEN e.n_rounds >= 30                                                                           -- 条件分支：起始分支 —— 仅在合格子集内计算合格口径百分位
                  THEN PERCENT_RANK() OVER (PARTITION BY CASE WHEN e.n_rounds >= 30 THEN 1 ELSE 0 END ORDER BY e.stake)  -- 分支取值：以合格与否分区，故本值即 n_rounds>=30 子集内之百分位
                ELSE NULL END                                             AS pr_qualified,                      -- 条件分支：收束上方分支 —— 不合格者留 NULL（NULL＝未测，非 0），产出「pr_qualified」
           'n_rounds>=30'                                                 AS pr_qualified_population,           -- 字面取值：血统 —— 合格子集之定义
           COUNT(*) OVER ()                                               AS pr_global_population_n,            -- 窗口取值：血统 —— 全体口径之参照总体规模，渲染时现算，禁写死
           SUM(CASE WHEN e.n_rounds >= 30 THEN 1 ELSE 0 END) OVER ()      AS pr_qualified_population_n,         -- 窗口取值：血统 —— 合格子集之参照总体规模，现算，禁写死
           'PERCENT_RANK_OVER_ORDER_BY_e_stake'                           AS pr_calculation_method,             -- 字面取值：血统 —— 算法标识
           'HF9f'                                                         AS pr_calculation_version,            -- 字面取值：血统 —— 算法版本
           CASE WHEN e.n_rounds IS NULL OR e.n_rounds < 30 THEN 'THIN_ROUNDS' ELSE 'OK' END AS evidence_flag,   -- 条件分支：HF9f·F-2a 证据旗标 —— THIN_ROUNDS 者禁入执行队列，仅入观察队列
           CASE WHEN e.n_rounds IS NULL       THEN NULL                                                         -- 条件分支：起始分支 —— 未测者留 NULL（自家铁律：NULL ≠ 0）
                WHEN e.n_rounds >= 31483      THEN 'L1_POWERED'                                                 -- 分支判定：MDE 反解第一档
                WHEN e.n_rounds >= 15409      THEN 'L2_CI_1P5'                                                  -- 分支判定：MDE 反解第二档
                WHEN e.n_rounds >=  8668      THEN 'L3_CI_2P0'                                                  -- 分支判定：MDE 反解第三档
                WHEN e.n_rounds >=  3852      THEN 'L4_CI_3P0'                                                  -- 分支判定：MDE 反解第四档
                ELSE 'L5_INSUFFICIENT' END                                AS evidence_rate,                     -- 条件分支：收束上方 —— HF9f·F-3 证据分档，承 HF9e 前议之 MDE 反解五档，须于 F-4 敏感性实验后复核
           ROUND(1.96 * 0.95 / SQRT(NULLIF(CAST(e.n_rounds AS DOUBLE),0)),8) AS hold_ci_halfwidth_approx,       -- 比率表达式：HF9f·F-3 逐行现算之 95% 半宽近似；常数 0.95 为登记值，本轮 #075 实测每局 ROI 隐含 σ 于最薄层为 0.9249，二者差异待 F-4 裁定
           CASE WHEN e.stake IS NULL OR e.stake<=0 OR e.n_bets<30 OR e.n_rounds IS NULL OR e.n_rounds<30 THEN 'Z 证据不足 · 不动作'  -- 条件分支：HF9f·F-2 双条件取严 —— HF9e 仅卡 e.n_bets<30，致 n_bets>=30 而 n_rounds<30 者绕过 Z（#075 实测 18,537 名，其中 8,145 名已入 A/D 待裁）；今两条件并列取严
                WHEN PERCENT_RANK() OVER (ORDER BY -e.net-e.rebate-e.agent_cost)<=0.10                          -- 分支判定：平台真净利之最低十分位
                  THEN 'A 净亏最大十分位 · 优先复核'                                                             -- 分支取值：HF9f·F-20 正名 —— 本档 Σresidual_b 于 #075 实测 = -100,236,896，系平台净亏最大群，旧名「残值最低十分位 · 待裁」名实不符
                WHEN PERCENT_RANK() OVER (ORDER BY -e.net-e.rebate-e.agent_cost)>=0.80                          -- 分支判定：平台真净利之最高二十分位
                  THEN 'D 净利最高二十分位 · 优先留存'                                                           -- 分支取值：HF9f·F-20 正名 —— 本档 Σresidual_b 于 #075 实测 = +281,733,190，系核心利润源；与 A 档方向相反，旧版同标「待裁」属名实不符
                ELSE 'E 常规' END                                          AS action_priority                   -- 条件分支：收束上方判词，产出「action_priority」
    FROM q
    LEFT JOIN x_agg e ON CAST(e.x_key AS STRING) = CAST(q.`dealer_id` AS STRING)
  ) y
) z
-- ── 逐批 WHERE 阶梯（★ 口诀：上界 ＝ 下界 ＋ 100000，两数同进）──
--    本件 T_true 未测，无需先跑 T_true；以 0 / 100000 控制本批返回区间，末批由实际行数 < 100000 判定
--    WHERE z.audit_rn >        0 AND z.audit_rn <=   100000   -- 第 1 批
--    WHERE z.audit_rn >   100000 AND z.audit_rn <=   200000   -- 第 2 批
--    WHERE z.audit_rn >   200000 AND z.audit_rn <=   300000   -- 第 3 批
--    WHERE z.audit_rn >   300000 AND z.audit_rn <=   400000   -- 第 4 批
--    WHERE z.audit_rn >   400000 AND z.audit_rn <=   500000   -- 第 5 批
--    WHERE z.audit_rn >   500000 AND z.audit_rn <=   600000   -- 第 6 批
--    WHERE z.audit_rn >   600000 AND z.audit_rn <=   700000   -- 第 7 批
--    …余批类推。第 k 批：WHERE z.audit_rn > (k-1)*100000 AND z.audit_rn <= k*100000
--    某批返回 < 100000 行即为末批，其后不再取。
--
--    ⚠ 常见误写（务必避开）：只推下界而上界不动 ——
--        WHERE z.audit_rn > 100000 AND z.audit_rn <= 100000   ← 自相矛盾，恒为假，返回空集
--        WHERE z.audit_rn > 200000 AND z.audit_rn <= 100000   ← 同上，空集
--      两个数必须**同时**前进，且始终相差 100000。
--      下界 ＝ 上一批之上界；上界 ＝ 本批之上界。
WHERE z.audit_rn > 0 AND z.audit_rn <= 100000 -- ★ HF9c 本批区间
ORDER BY z.audit_rn;


-- ══════════════════════════════════════════════════════════════════════════════════════════════
--  77. S02b_dealer_pace.csv   [总包行 6390~6447 · 原 3 列 ＋六层约 60 列]
--     典型学：M07 荷官关联　派生旗标：recent（s.x_rec = 1 · 仅供 CASE 条件聚合，全包无任何 WHERE/AND/HAVING 以此过滤）　连接：q.`dealer_id`
-- ══════════════════════════════════════════════════════════════════════════════════════════════
-- ── ① 先跑 T_true 留档（不足 100000 者一次导全，不必分批）──
-- ── ① T_true：HF9c 不再强制预跑完整 COUNT。
--    本批实际返回行数 < 100000 即判定为末批；全批完成后以各批 n_rows / audit_rn 范围核对总量。

-- ── ② 分批取数：第 1 批。第 k 批只改末行两数为 (k-1)*100000 与 k*100000 ──
--    审计字段二（REDTEAM 2026-08-24 裁定 · 四锁）：
--      audit_rn  全局观测坐标 —— 由**与原版审计版逐字同一**之排序键所生，两版可逐行对账
--      batch_id  物理分批信息 —— 该行所属批次，由 audit_rn 算得，非引擎所赋
--    ★ 锁三：二者皆为审计字段，**不得进入任何业务指标计算**。
--    ★ 锁四：两版经 audit_rn 逐行字段核验后，方可宣布输出完全一致。

-- ── ③ 每批取回后自证四数（任一不符即停手回报，禁止放行）──
--    n_rows        = COUNT(*)      须等于 COUNT(DISTINCT audit_rn)   （批内无重复）
--    audit_rn_min  = MIN(audit_rn) 须等于 (k-1)*100000 + 1           （与上批严丝合缝）
--    audit_rn_max  = MAX(audit_rn) 须等于 min + n_rows - 1           （批内无缺口）
--    全批取毕再验：各批 audit_rn 之并集 = 1 .. T_true，无缺号、无重号。
--     ★ 首行＝平台真净亏最多者（已扣退水与代理占成）。
--
SELECT z.*,
       CAST(FLOOR((z.audit_rn - 1) / 100000) + 1 AS INT)          AS batch_id,
       'A168_HF9F_20260827_0900' AS run_id,
       '2026-08-27 09:00:00' AS snapshot_sync_time
FROM (
  SELECT y.*,
         ROW_NUMBER() OVER (ORDER BY y.`residual_b` ASC, y.`roi` DESC, y.`dealer_id`, y.`平均每局秒数`, y.`局速`) AS audit_rn
  FROM (
    WITH
      x_ranked AS (
    SELECT b.bet01, b.bet03, b.bet04, b.bet05, b.bet09, b.bet11, b.bet13,
           b.bet15, b.bet16, b.bet17, b.bet18, b.bet19, b.bet20, b.bet21,
           b.bet22, b.bet23, b.bet24, b.bet25, b.bet26, b.bet27, b.bet38, b.bet39, b.category, b.commission,
           b.dt, b.eid, b.ip, b.validbet, b.updatetime, b.sync_time,
           ROW_NUMBER() OVER (
             PARTITION BY b.bet01
             ORDER BY b.updatetime DESC, b.sync_time DESC, b.dt DESC)      AS x_rn
    FROM ods_mariadb_2b.ods_a168_bet02 b
    WHERE b.dt >= '2026-03-21' AND b.dt < '2026-08-07'
      AND b.bet02 = '101'
      AND b.sync_time <= '2026-08-27 09:00:00'
  ),
    x_testagent AS (
    SELECT age001 AS agent_id FROM ods_mariadb_2b.ods_a168_agent WHERE age022 = '1'
  ),
    x_bs0 AS (
    SELECT b.bet05 AS x_member, b.eid AS x_dealer, b.bet39 AS x_table,
           b.bet03 AS x_shoe, b.ip AS x_ip, b.bet09 AS x_product, b.dt AS x_date,
           CONCAT_WS('|', b.bet03, b.bet04, b.bet39)                      AS x_round,
           CONCAT_WS('|', b.bet39, b.bet03)                               AS x_tblshoe,
           CAST(NULLIF(TRIM(b.bet04),'') AS INT)                          AS x_rno,
           CASE WHEN b.dt >= '2026-07-08' THEN 1 ELSE 0 END               AS x_rec,
           CASE WHEN TRIM(b.commission)='1' THEN 1 ELSE 0 END             AS x_freecomm,
           CAST(NULLIF(TRIM(b.bet13),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_stake,
           CAST(NULLIF(TRIM(b.validbet),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_valid,
           CAST(NULLIF(TRIM(b.bet16),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_rebate,
           CAST(NULLIF(TRIM(b.bet17),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_net,
           CAST(NULLIF(TRIM(b.bet15),'') AS DECIMAL(20,6))                AS x_rbpct,
           COALESCE(CAST(NULLIF(TRIM(b.bet23),'') AS DECIMAL(20,6)),0)   AS x_agpct,
          NULLIF(CAST(NULLIF(TRIM(b.bet23),'') AS DECIMAL(20,6)),0)     AS x_rate1,
          NULLIF(CAST(NULLIF(TRIM(b.bet24),'') AS DECIMAL(20,6)),0)     AS x_rate2,
          NULLIF(CAST(NULLIF(TRIM(b.bet25),'') AS DECIMAL(20,6)),0)     AS x_rate3,
          NULLIF(CAST(NULLIF(TRIM(b.bet26),'') AS DECIMAL(20,6)),0)     AS x_rate4,
          NULLIF(CAST(NULLIF(TRIM(b.bet27),'') AS DECIMAL(20,6)),0)     AS x_rate5,
          (CASE WHEN NULLIF(CAST(NULLIF(TRIM(b.bet22),'') AS BIGINT),0) IS NOT NULL THEN 5
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet21),'') AS BIGINT),0) IS NOT NULL THEN 4
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet20),'') AS BIGINT),0) IS NOT NULL THEN 3
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet19),'') AS BIGINT),0) IS NOT NULL THEN 2
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet18),'') AS BIGINT),0) IS NOT NULL THEN 1
                ELSE 0 END)                                             AS x_chain_depth,
           CASE WHEN COALESCE(t1.agent_id,t2.agent_id,t3.agent_id,
                              t4.agent_id,t5.agent_id) IS NOT NULL
                THEN 1 ELSE 0 END                                        AS f_testline
    FROM x_ranked b
    LEFT JOIN x_testagent t1 ON t1.agent_id = b.bet18
    LEFT JOIN x_testagent t2 ON t2.agent_id = b.bet19
    LEFT JOIN x_testagent t3 ON t3.agent_id = b.bet20
    LEFT JOIN x_testagent t4 ON t4.agent_id = b.bet21
    LEFT JOIN x_testagent t5 ON t5.agent_id = b.bet22
    WHERE b.x_rn = 1
      AND b.category='1' AND UPPER(TRIM(b.bet38))='N'
      AND CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8)) > 0
  ),
  x_mk AS (
    SELECT s.*,
           CASE WHEN s.f_testline = 0 THEN 1 ELSE 0 END                 AS is_clean
    FROM x_bs0 s
  ),
  x_agg AS (
    SELECT s.x_dealer                                                        AS x_key,
           COUNT(*) AS n_bets, COUNT(DISTINCT s.x_round) AS n_rounds,
           COUNT(DISTINCT s.x_date) AS active_days, COUNT(DISTINCT s.x_tblshoe) AS active_shoes,
           COUNT(DISTINCT CONCAT_WS('|', s.x_date, s.x_table)) AS active_sessions,
           COUNT(DISTINCT s.x_table) AS n_tables, COUNT(DISTINCT s.x_dealer) AS n_dealers,
           COUNT(DISTINCT s.x_ip) AS n_ips, COUNT(DISTINCT s.x_product) AS n_products,
           MIN(s.x_date) AS first_seen_d, MAX(s.x_date) AS last_seen_d,
           SUM(s.x_stake) AS stake, SUM(s.x_valid) AS valid, SUM(s.x_rebate) AS rebate,
           SUM(s.x_net) AS net, SUM(-s.x_net *(100.0-s.x_agpct)/100.0) AS agent_cost,
           AVG(100.0-s.x_agpct)                   AS agent_pct,
           AVG(s.x_agpct)                         AS company_retain_pct,
           SUM(-s.x_net *s.x_agpct/100.0)         AS agent_cost_a_legacy,
           SUM(s.x_valid*s.x_agpct/100.0)         AS agent_cost_valid_base_legacy,
          AVG(COALESCE(s.x_rate1,100)) AS retain_pct_lv1, AVG(COALESCE(s.x_rate2,100)) AS retain_pct_lv2,
          AVG(COALESCE(s.x_rate3,100)) AS retain_pct_lv3, AVG(COALESCE(s.x_rate4,100)) AS retain_pct_lv4,
          AVG(COALESCE(s.x_rate5,100)) AS retain_pct_lv5, AVG(s.x_chain_depth) AS chain_depth_avg,
          AVG(COALESCE(100.0-s.x_rate1,0)) AS agent_pct_lv1, AVG(COALESCE(100.0-s.x_rate2,0)) AS agent_pct_lv2,
          AVG(COALESCE(100.0-s.x_rate3,0)) AS agent_pct_lv3, AVG(COALESCE(100.0-s.x_rate4,0)) AS agent_pct_lv4,
          AVG(COALESCE(100.0-s.x_rate5,0)) AS agent_pct_lv5,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate1,0)/100.0)                        AS agent_cost_lv1,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate2,0)/100.0)                        AS agent_cost_lv2,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate3,0)/100.0)                        AS agent_cost_lv3,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate4,0)/100.0)                        AS agent_cost_lv4,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate5,0)/100.0)                        AS agent_cost_lv5,
          SUM(-s.x_net*(COALESCE(100.0-s.x_rate1,0)+COALESCE(100.0-s.x_rate2,0)
                       +COALESCE(100.0-s.x_rate3,0)+COALESCE(100.0-s.x_rate4,0)
                       +COALESCE(100.0-s.x_rate5,0))/100.0)                   AS agent_cost_chain_additive,
          SUM(-s.x_net*(1.0 - CAST(COALESCE(s.x_rate1,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate2,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate3,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate4,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate5,100) AS DOUBLE)/100.0))
                                                                       AS agent_cost_chain_nested,
           AVG(s.x_rbpct) AS rbpct, AVG(s.x_freecomm*1.0) AS freecomm_rate,
           PERCENTILE_APPROX(s.x_stake,0.25) AS p25, PERCENTILE_APPROX(s.x_stake,0.50) AS p50,
           PERCENTILE_APPROX(s.x_stake,0.75) AS p75, PERCENTILE_APPROX(s.x_stake,0.90) AS p90,
           PERCENTILE_APPROX(s.x_stake,0.95) AS p95, PERCENTILE_APPROX(s.x_stake,0.99) AS p99,
           PERCENTILE_APPROX(s.x_valid,0.50) AS p50_valid,
           PERCENTILE_APPROX(s.x_net,0.50)   AS p50_profit,
           SUM(CASE WHEN s.x_rec = 1 THEN s.x_stake ELSE 0 END) AS st_in,
           SUM(CASE WHEN s.x_rec = 1 THEN 1 ELSE 0 END)         AS nb_in,
           SUM(CASE WHEN s.x_rec = 1 THEN s.x_net ELSE 0 END)   AS net_in,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN s.x_stake ELSE 0 END) AS st_out,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN 1 ELSE 0 END)         AS nb_out,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN s.x_net ELSE 0 END)   AS net_out,
           SUM(CASE WHEN s.x_rec=1 THEN s.x_stake ELSE 0 END) AS st_rec,
           SUM(CASE WHEN s.x_rec=1 THEN 1 ELSE 0 END)         AS nb_rec
    FROM x_mk s
    WHERE s.is_clean = 1
      AND s.x_dealer IS NOT NULL AND TRIM(CAST(s.x_dealer AS STRING)) <> ''
    GROUP BY s.x_dealer
  ),
      q AS (
        WITH ta AS (                                                                                        -- 公共表表达式：开启中间结果集 ta，其后各行为其定义体（§EX-05）
          SELECT DISTINCT age001 AS aid                                                                     -- 取列：产出「aid」
          FROM ods_mariadb_2b.ods_a168_agent WHERE age022 = '1'                                             -- 取数来源：取自代理主档（五级代理线归属来源）
        ),                                                                                                  -- 续行：收束上方的子查询或函数括号（§EX-05）
        rk AS (                                                                                             -- 公共表表达式：开启中间结果集 rk，其后各行为其定义体（§EX-05）
          SELECT b.bet01, b.updatetime, b.sync_time, b.dt,                                                  -- 取列：起始取列子句，本行先列 b.bet01, b.updatetime, b.sync_time, b.dt，涉 dt（营业日）
                 b.category, b.bet38, b.bet05, b.bet11, b.bet08,                                            -- 续行：接续上一取列子句，续列 b.category, b.bet38, b.bet05, b.bet11, b.bet08，涉 bet05（会员号）、bet08（下注时间）、bet11（汇率）
                 b.bet18, b.bet19, b.bet20, b.bet21, b.bet22,                                               -- 续行：接续上一取列子句，续列 b.bet18, b.bet19, b.bet20, b.bet21, b.bet22，涉 bet18（一级代理线）、bet19（二级代理线）、bet20（三级代理线）
                 b.bet39, b.eid,                                                                            -- 续行：接续上一取列子句，续列 b.bet39, b.eid，涉 bet39（桌号）、eid（荷官工号）
                 ROW_NUMBER() OVER (                                                                        -- 行号窗口表达式：以行号窗口取每组头部或去重，免出重复行
                   PARTITION BY b.bet01                                                                     -- 窗口分区：按 b.bet01 分组开窗，组内各自编号或排名
                   ORDER BY b.updatetime DESC, b.sync_time DESC, b.dt DESC) AS rn                           -- 排序：按 b.updatetime（降序）, b.sync_time（降序）, b.dt（降序）) AS rn 排列；导出必带排序，否则分页无稳定序（曾致 36.49% 重复行）
          FROM ods_mariadb_2b.ods_a168_bet02 b                                                              -- 取数来源：取自注单明细表（金额与行为口径的第一料源）
          WHERE b.dt >= '2026-03-21' AND b.dt < '2026-08-07' AND b.bet02 = '101'
      AND b.sync_time <= '2026-08-27 09:00:00'                            -- 过滤条件：限定 b.dt不少于 '2026-03-21'、b.dt小于 '2026-08-07'、b.bet02等于 '101'，涉 bet02（游戏类别）、dt（营业日）
        ),                                                                                                  -- 续行：收束上方的子查询或函数括号（§EX-05）
        vd AS (                                                                                             -- 公共表表达式：开启中间结果集 vd，其后各行为其定义体（§EX-05）
          SELECT r.*                                                                                        -- 取列：整体承接上游结果集的全部字段，不再逐列列举
          FROM rk r                                                                                         -- 取数来源：取自本条自建的中间结果集 rk
          LEFT JOIN ta t1 ON t1.aid = r.bet18                                                               -- 左连接：取自本条自建的中间结果集 ta，连接键为 bet18（一级代理线）
          LEFT JOIN ta t2 ON t2.aid = r.bet19                                                               -- 左连接：取自本条自建的中间结果集 ta，连接键为 bet19（二级代理线）
          LEFT JOIN ta t3 ON t3.aid = r.bet20                                                               -- 左连接：取自本条自建的中间结果集 ta，连接键为 bet20（三级代理线）
          LEFT JOIN ta t4 ON t4.aid = r.bet21                                                               -- 左连接：取自本条自建的中间结果集 ta，连接键为 bet21（四级代理线）
          LEFT JOIN ta t5 ON t5.aid = r.bet22                                                               -- 左连接：取自本条自建的中间结果集 ta，连接键为 bet22（五级代理线）
          WHERE r.rn = 1 AND r.category = '1' AND UPPER(TRIM(r.bet38)) = 'N'                                -- 过滤条件：限定 r.rn等于 1、r.category等于 '1'、UPPER(TRIM(r.bet38))等于 'N'，涉 bet38（重對）
            AND CAST(NULLIF(TRIM(r.bet05),'') AS BIGINT) > 0                                                -- 并列条件：限定 CAST(NULLIF(TRIM(r.bet05),'') AS BIGINT)大于 0，涉 bet05（会员号）
            AND CAST(NULLIF(TRIM(r.bet11),'') AS DECIMAL(20,8)) > 0                                         -- 并列条件：限定 CAST(NULLIF(TRIM(r.bet11),'') AS DECIMAL(20,8))大于 0，涉 bet11（汇率）
            AND NULLIF(TRIM(r.bet08),'') IS NOT NULL                                                        -- 并列条件：限定该值非空，涉 bet08（下注时间）
            AND COALESCE(t1.aid, t2.aid, t3.aid, t4.aid, t5.aid) IS NULL                                    -- 并列条件：限定该值为空——本包以左连接加空值判定替代 EXISTS，因 StarRocks 不支持 EXISTS 配多列 IN
            AND NULLIF(TRIM(r.eid),'') IS NOT NULL                                                          -- 并列条件：限定该值非空，涉 eid（荷官工号）
            AND TRIM(r.eid) NOT IN ('-1', '0')                                                              -- 并列条件：剔除哨兵荷官号——-1／0 非真实荷官，入检即污染榜单与多重比较总体（2026-08-11 增）
        ),                                                                                                  -- 续行：收束上方的子查询或函数括号（§EX-05）
        dtc AS (                     -- 荷官×桌的注单行数（与 §S-02 的权重同源）
          SELECT eid AS dealer_id, bet39 AS table_id, COUNT(*) AS n_rows                                    -- 取列：计数，取用 bet39（桌号）、eid（荷官工号）、dealer_id（荷官工号），产出「n_rows」
          FROM vd GROUP BY eid, bet39                                                                       -- 取数来源：取自本条自建的中间结果集 vd
        ),                                                                                                  -- 续行：收束上方的子查询或函数括号（§EX-05）
        gi AS (                      -- 每局秒数，脏值以 BETWEEN 剔除
          SELECT gi011 AS table_id,                                                                         -- 取列：起始取列子句，本行先取「table_id」，涉 gi011（桌号）
                 UNIX_TIMESTAMP(gi006) - UNIX_TIMESTAMP(gi004) AS sec_round                                 -- 取值表达式：取用 gi004（局开始时刻）、gi006（开牌时刻），产出「sec_round」
          FROM ods_mariadb_2b.ods_a168_game_info                                                            -- 取数来源：取自局信息表（靴局、开牌与桌号的时序基准）
          WHERE gi001 = '101' AND gi013 = '1'                                                               -- 过滤条件：限定 gi001等于 '101'、gi013等于 '1'，涉 gi001（局主键）
            AND gi004 >= '2026-03-21' AND gi004 < '2026-08-07'                                              -- 并列条件：限定 gi004不少于 '2026-03-21'、gi004小于 '2026-08-07'，涉 gi004（局开始时刻）
        ),                                                                                                  -- 续行：收束上方的子查询或函数括号（§EX-05）
        git AS (                     -- 每桌两矩：局数与总秒数
          SELECT table_id,                                                                                  -- 取列：起始取列子句，本行先列 table_id
                 COUNT(sec_round)               AS n_g,                                                     -- 计数表达式：产出「n_g」
                 SUM(CAST(sec_round AS DOUBLE)) AS s1                                                       -- 汇总表达式：产出「s1」
          FROM gi                                                                                           -- 取数来源：取自本条自建的中间结果集 gi
          WHERE sec_round BETWEEN 5 AND 600                                                                 -- 过滤条件：限定落入闭区间
          GROUP BY table_id                                                                                 -- 分组：按 table_id 汇总
        )                                                                                                   -- 续行：收束上方的子查询或函数括号（§EX-05）
        SELECT d.dealer_id,                                                                                 -- 取列：起始取列子句，本行先列 d.dealer_id，涉 dealer_id（荷官工号）
               SUM(d.n_rows * g.s1) / NULLIF(SUM(d.n_rows * CAST(g.n_g AS DOUBLE)), 0)                      -- 汇总表达式：承接上一子句，构成完整语句，属 §EX-05 之取数
                 AS 平均每局秒数,                                                                                 -- 取值表达式：产出「平均每局秒数」
               3600.0 * SUM(d.n_rows * CAST(g.n_g AS DOUBLE))                                               -- 取值表达式：汇总
                 / NULLIF(SUM(d.n_rows * g.s1), 0)                        AS 局速                             -- 除法或乘法计算：汇总，产出「局速」
        FROM dtc d JOIN git g ON g.table_id = d.table_id                                                    -- 取数来源：取自本条自建的中间结果集 dtc，连接键为 g.table_id = d.table_id
        GROUP BY d.dealer_id                                                                                -- 分组：按 d.dealer_id 汇总
      )
    SELECT q.*,
           -- 一·经济层
           ROUND(e.stake,4) AS stake, ROUND(e.valid,4) AS valid_bet,
           ROUND(-e.net,4) AS profit, e.n_bets, e.n_rounds,
           ROUND(e.net/NULLIF(e.stake,0),8) AS roi,
           ROUND(e.net_in/NULLIF(e.st_in,0),8) AS roi_recent,
           ROUND(e.net_out/NULLIF(e.st_out,0),8) AS roi_non_recent,
           ROUND((e.net-e.rebate)/NULLIF(e.stake,0),8) AS roi_ex_rebate,
           ROUND(e.net,4) AS roi_numerator, ROUND(e.stake,4) AS roi_denominator,
           CASE WHEN e.stake IS NULL THEN 'NULL_DENOM' WHEN e.stake<=0 THEN 'ZERO_DENOM'
                WHEN e.n_bets<30 THEN 'THIN_EXPOSURE' ELSE 'OK' END AS roi_denominator_status,
           ROUND(e.rebate,4) AS rebate_cost, ROUND(e.agent_cost,4)                           AS cost_complement_b,
       ROUND(e.agent_pct,4)                            AS pct_complement,
       ROUND(e.company_retain_pct,4)                   AS pct_top_bet23,
       'AG03-UNRESOLVED'                                     AS agent_formula_version,
      'ALL5_LEVELS_bet23_to_bet27'                    AS agent_level_scope,
      ROUND(e.agent_cost_lv1,4) AS agent_cost_lv1, ROUND(e.agent_cost_lv2,4) AS agent_cost_lv2,
      ROUND(e.agent_cost_lv3,4) AS agent_cost_lv3, ROUND(e.agent_cost_lv4,4) AS agent_cost_lv4,
      ROUND(e.agent_cost_lv5,4) AS agent_cost_lv5,
      ROUND(e.agent_pct_lv1,6) AS agent_pct_lv1, ROUND(e.agent_pct_lv2,6) AS agent_pct_lv2,
      ROUND(e.agent_pct_lv3,6) AS agent_pct_lv3, ROUND(e.agent_pct_lv4,6) AS agent_pct_lv4,
      ROUND(e.agent_pct_lv5,6) AS agent_pct_lv5,
      ROUND(e.retain_pct_lv1,6) AS retain_pct_lv1, ROUND(e.retain_pct_lv2,6) AS retain_pct_lv2,
      ROUND(e.retain_pct_lv3,6) AS retain_pct_lv3, ROUND(e.retain_pct_lv4,6) AS retain_pct_lv4,
      ROUND(e.retain_pct_lv5,6) AS retain_pct_lv5, ROUND(e.chain_depth_avg,4) AS chain_depth_avg,
      ROUND(e.agent_cost_chain_additive,4)            AS agent_cost_chain_additive,
      ROUND(e.agent_cost_chain_nested,4)              AS agent_cost_chain_nested,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_additive,4) AS residual_chain_additive,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_nested,4)   AS residual_chain_nested,
      'PENDING_AG03'                                  AS decision_status,
      'FALSE'                                         AS admit_to_risk_decision,
      'NOT_FOR_ENFORCEMENT'                           AS deliverable_class,
       ROUND(e.agent_cost_a_legacy,4)                  AS agent_cost_a_legacy,
       ROUND(e.agent_cost_valid_base_legacy,4)         AS agent_cost_valid_base_legacy,
           ROUND(-e.net-e.rebate,4)                        AS ngr,
       ROUND(-e.net-e.rebate-e.agent_cost,4)           AS residual_b,
       ROUND(-e.net-e.rebate-e.agent_cost_a_legacy,4)  AS residual_a,
           ROUND((-e.net-e.rebate)/NULLIF(e.stake,0),8)    AS ngr_rate,
       ROUND((-e.net-e.rebate-e.agent_cost)/NULLIF(e.stake,0),8)   AS residual_b_rate,
      -- 【HF9c · canonical accounting contract】
      --   以下 canonical 字段只增加明确 scope；不删除、不覆盖既有字段。
      --   formal_bet23_* 保持 HF9b 当前生产公式及其 NULL/0 语义；
      --   lv1~lv5 / additive / nested 则分别采用各自原始 e.* 成本字段，
      --   rate 一律从未舍入的 e.* 分子 / e.stake 计算，禁止由展示值反算。
      ROUND(e.agent_cost,4) AS agent_cost_bet23_formal_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost,4) AS net_margin_bet23_formal_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost)/NULLIF(e.stake,0),8) AS net_margin_bet23_formal_rate_canonical,
      ROUND(e.agent_cost_lv1,4) AS agent_cost_lv1_bet23_canonical,
      ROUND(e.agent_cost_lv2,4) AS agent_cost_lv2_bet24_canonical,
      ROUND(e.agent_cost_lv3,4) AS agent_cost_lv3_bet25_canonical,
      ROUND(e.agent_cost_lv4,4) AS agent_cost_lv4_bet26_canonical,
      ROUND(e.agent_cost_lv5,4) AS agent_cost_lv5_bet27_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_lv1,4) AS net_margin_lv1_bet23_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_lv1)/NULLIF(e.stake,0),8) AS net_margin_lv1_bet23_rate_canonical,
      ROUND(e.agent_cost_chain_additive,4) AS agent_cost_chain_additive_canonical,
      ROUND(e.agent_cost_chain_nested,4) AS agent_cost_chain_nested_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_additive,4) AS net_margin_chain_additive_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_nested,4) AS net_margin_chain_nested_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_chain_additive)/NULLIF(e.stake,0),8) AS net_margin_chain_additive_rate_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_chain_nested)/NULLIF(e.stake,0),8) AS net_margin_chain_nested_rate_canonical,
       ROUND((-e.net-e.rebate-e.agent_cost_a_legacy)/NULLIF(e.stake,0),8) AS residual_a_rate,
           -- 二·分布层
           ROUND(e.stake/NULLIF(e.n_bets,0),4) AS avg_stake_per_bet,
           ROUND(e.valid/NULLIF(e.n_rounds,0),4) AS avg_valid_bet_per_round,
           ROUND(-e.net/NULLIF(e.n_rounds,0),4) AS avg_profit_per_round,
           ROUND(-e.net/NULLIF(e.active_days,0),4) AS avg_profit_per_day,
           ROUND(-e.net/NULLIF(e.active_shoes,0),4) AS avg_profit_per_shoe,
           ROUND(e.stake/NULLIF(e.active_days,0),4) AS avg_stake_per_active_day,
           ROUND(e.n_rounds*1.0/NULLIF(e.active_days,0),4) AS avg_rounds_per_active_day,
           ROUND(e.st_in/NULLIF(e.nb_in,0),4) AS avg_stake_recent,
           ROUND(e.st_out/NULLIF(e.nb_out,0),4) AS avg_stake_non_recent,
           ROUND(e.p25,4) AS p25_stake, ROUND(e.p50,4) AS p50_stake, ROUND(e.p75,4) AS p75_stake,
           ROUND(e.p90,4) AS p90_stake, ROUND(e.p95,4) AS p95_stake, ROUND(e.p99,4) AS p99_stake,
           ROUND(e.p50_valid,4) AS p50_valid_bet, ROUND(e.p50_profit,4) AS p50_profit,
           ROUND(e.p95/NULLIF(e.p50,0),6) AS p95_over_p50,
           ROUND(e.p99/NULLIF(e.p50,0),6) AS p99_over_p50,
           ROUND((e.stake/NULLIF(e.n_bets,0))/NULLIF(e.p50,0),6) AS avg_over_p50,
           -- 三·关系层
           e.n_tables AS common_table_count, e.n_dealers AS common_dealer_count,
           e.n_ips AS common_ip_count, e.n_products AS common_product_count,
           ROUND(e.st_in/NULLIF(e.stake,0),8) AS share_recent,
           -- 四·rate 层
           ROUND(-e.net/NULLIF(e.stake,0),8) AS hold_rate,
           ROUND(-e.net_in/NULLIF(e.st_in,0),8) AS hold_rate_recent,
           ROUND(e.rebate/NULLIF(e.valid,0),8) AS rebate_rate_actual,
           ROUND(e.rbpct,6) AS rebate_pct_config,
           ROUND(e.valid/NULLIF(e.stake,0),6) AS turnover_multiple,
           ROUND(e.freecomm_rate,6) AS free_comm_rate,
           ROUND(e.net_in/NULLIF(e.st_in,0)-e.net_out/NULLIF(e.st_out,0),8) AS roi_delta_recent,
           -- 五·动态层
           e.first_seen_d AS first_seen, e.last_seen_d AS last_seen,
           e.active_days, e.active_shoes, e.active_sessions,
           DATEDIFF(e.last_seen_d, e.first_seen_d)+1 AS span_days,
           ROUND(e.active_days*1.0/NULLIF(DATEDIFF(e.last_seen_d,e.first_seen_d)+1,0),6) AS persistence,
           ROUND((e.st_in/NULLIF(e.nb_in,0))/NULLIF(e.st_out/NULLIF(e.nb_out,0),0),6) AS ramp_recent_vs_prior,
           ROUND((e.st_rec/NULLIF(e.nb_rec,0))/NULLIF(e.stake/NULLIF(e.n_bets,0),0),6) AS ramp_recent_vs_all,
           ROUND((e.st_rec/NULLIF(e.stake,0))/0.30,6) AS stake_ramp,
           -- 六·决策层（HF9f · 详见档头【HF9f 变更说明】；本段两版逐字同一）
           NTILE(5) OVER (ORDER BY e.stake) AS vip_tier,                                                        -- 窗口取值：相对刻度 B 族，全体五等分；须连同下方血统五元组一并解读，禁作硬阈值判型
           PERCENT_RANK() OVER (ORDER BY -e.net-e.rebate-e.agent_cost)    AS economic_value,                    -- 窗口取值：HF9f·F-19 修正 —— HF9e 写作 -(-…) 双负号致方向颠倒（#075 实测 corr(economic_value, residual_b) = -1.0000）；今与 action_priority 排序键归一，值大即平台真净利高
           PERCENT_RANK() OVER (ORDER BY e.net/NULLIF(e.stake,0))         AS roi_pr_global,                     -- 窗口取值：HF9f·F-17 正名 —— 本列实为 ROI（玩家净回报率）之全体百分位，与「风险」无关；旧名 risk_value 见下一行
           PERCENT_RANK() OVER (ORDER BY e.net/NULLIF(e.stake,0))         AS risk_value,                        -- 窗口取值：兼容列，恒等于 roi_pr_global，仅为下游迁移窗保留；HF9g 起废弃，禁新引用
           PERCENT_RANK() OVER (ORDER BY e.stake)                         AS pr_stake,                          -- 窗口取值：兼容列，恒等于 pr_global，原名保留以免断链
           PERCENT_RANK() OVER (ORDER BY e.stake)                         AS pr_global,                         -- 窗口取值：HF9f·F-1 双轨之一 —— 全体口径百分位，参照总体即本件全部输出行
           CASE WHEN e.n_rounds >= 30                                                                           -- 条件分支：起始分支 —— 仅在合格子集内计算合格口径百分位
                  THEN PERCENT_RANK() OVER (PARTITION BY CASE WHEN e.n_rounds >= 30 THEN 1 ELSE 0 END ORDER BY e.stake)  -- 分支取值：以合格与否分区，故本值即 n_rounds>=30 子集内之百分位
                ELSE NULL END                                             AS pr_qualified,                      -- 条件分支：收束上方分支 —— 不合格者留 NULL（NULL＝未测，非 0），产出「pr_qualified」
           'n_rounds>=30'                                                 AS pr_qualified_population,           -- 字面取值：血统 —— 合格子集之定义
           COUNT(*) OVER ()                                               AS pr_global_population_n,            -- 窗口取值：血统 —— 全体口径之参照总体规模，渲染时现算，禁写死
           SUM(CASE WHEN e.n_rounds >= 30 THEN 1 ELSE 0 END) OVER ()      AS pr_qualified_population_n,         -- 窗口取值：血统 —— 合格子集之参照总体规模，现算，禁写死
           'PERCENT_RANK_OVER_ORDER_BY_e_stake'                           AS pr_calculation_method,             -- 字面取值：血统 —— 算法标识
           'HF9f'                                                         AS pr_calculation_version,            -- 字面取值：血统 —— 算法版本
           CASE WHEN e.n_rounds IS NULL OR e.n_rounds < 30 THEN 'THIN_ROUNDS' ELSE 'OK' END AS evidence_flag,   -- 条件分支：HF9f·F-2a 证据旗标 —— THIN_ROUNDS 者禁入执行队列，仅入观察队列
           CASE WHEN e.n_rounds IS NULL       THEN NULL                                                         -- 条件分支：起始分支 —— 未测者留 NULL（自家铁律：NULL ≠ 0）
                WHEN e.n_rounds >= 31483      THEN 'L1_POWERED'                                                 -- 分支判定：MDE 反解第一档
                WHEN e.n_rounds >= 15409      THEN 'L2_CI_1P5'                                                  -- 分支判定：MDE 反解第二档
                WHEN e.n_rounds >=  8668      THEN 'L3_CI_2P0'                                                  -- 分支判定：MDE 反解第三档
                WHEN e.n_rounds >=  3852      THEN 'L4_CI_3P0'                                                  -- 分支判定：MDE 反解第四档
                ELSE 'L5_INSUFFICIENT' END                                AS evidence_rate,                     -- 条件分支：收束上方 —— HF9f·F-3 证据分档，承 HF9e 前议之 MDE 反解五档，须于 F-4 敏感性实验后复核
           ROUND(1.96 * 0.95 / SQRT(NULLIF(CAST(e.n_rounds AS DOUBLE),0)),8) AS hold_ci_halfwidth_approx,       -- 比率表达式：HF9f·F-3 逐行现算之 95% 半宽近似；常数 0.95 为登记值，本轮 #075 实测每局 ROI 隐含 σ 于最薄层为 0.9249，二者差异待 F-4 裁定
           CASE WHEN e.stake IS NULL OR e.stake<=0 OR e.n_bets<30 OR e.n_rounds IS NULL OR e.n_rounds<30 THEN 'Z 证据不足 · 不动作'  -- 条件分支：HF9f·F-2 双条件取严 —— HF9e 仅卡 e.n_bets<30，致 n_bets>=30 而 n_rounds<30 者绕过 Z（#075 实测 18,537 名，其中 8,145 名已入 A/D 待裁）；今两条件并列取严
                WHEN PERCENT_RANK() OVER (ORDER BY -e.net-e.rebate-e.agent_cost)<=0.10                          -- 分支判定：平台真净利之最低十分位
                  THEN 'A 净亏最大十分位 · 优先复核'                                                             -- 分支取值：HF9f·F-20 正名 —— 本档 Σresidual_b 于 #075 实测 = -100,236,896，系平台净亏最大群，旧名「残值最低十分位 · 待裁」名实不符
                WHEN PERCENT_RANK() OVER (ORDER BY -e.net-e.rebate-e.agent_cost)>=0.80                          -- 分支判定：平台真净利之最高二十分位
                  THEN 'D 净利最高二十分位 · 优先留存'                                                           -- 分支取值：HF9f·F-20 正名 —— 本档 Σresidual_b 于 #075 实测 = +281,733,190，系核心利润源；与 A 档方向相反，旧版同标「待裁」属名实不符
                ELSE 'E 常规' END                                          AS action_priority                   -- 条件分支：收束上方判词，产出「action_priority」
    FROM q
    LEFT JOIN x_agg e ON CAST(e.x_key AS STRING) = CAST(q.`dealer_id` AS STRING)
  ) y
) z
-- ── 逐批 WHERE 阶梯（★ 口诀：上界 ＝ 下界 ＋ 100000，两数同进）──
--    本件 T_true 未测，无需先跑 T_true；以 0 / 100000 控制本批返回区间，末批由实际行数 < 100000 判定
--    WHERE z.audit_rn >        0 AND z.audit_rn <=   100000   -- 第 1 批
--    WHERE z.audit_rn >   100000 AND z.audit_rn <=   200000   -- 第 2 批
--    WHERE z.audit_rn >   200000 AND z.audit_rn <=   300000   -- 第 3 批
--    WHERE z.audit_rn >   300000 AND z.audit_rn <=   400000   -- 第 4 批
--    WHERE z.audit_rn >   400000 AND z.audit_rn <=   500000   -- 第 5 批
--    WHERE z.audit_rn >   500000 AND z.audit_rn <=   600000   -- 第 6 批
--    WHERE z.audit_rn >   600000 AND z.audit_rn <=   700000   -- 第 7 批
--    …余批类推。第 k 批：WHERE z.audit_rn > (k-1)*100000 AND z.audit_rn <= k*100000
--    某批返回 < 100000 行即为末批，其后不再取。
--
--    ⚠ 常见误写（务必避开）：只推下界而上界不动 ——
--        WHERE z.audit_rn > 100000 AND z.audit_rn <= 100000   ← 自相矛盾，恒为假，返回空集
--        WHERE z.audit_rn > 200000 AND z.audit_rn <= 100000   ← 同上，空集
--      两个数必须**同时**前进，且始终相差 100000。
--      下界 ＝ 上一批之上界；上界 ＝ 本批之上界。
WHERE z.audit_rn > 0 AND z.audit_rn <= 100000 -- ★ HF9c 本批区间
ORDER BY z.audit_rn;
-- ══════════════════════════════════════════════════════════════════════════════════════════════
--  78. S03_agent_score.csv   [总包行 HF6 就地重写 · 原 9 列 → 现 31 列 · 五级全展开]
--     典型学：M06 代理线　粒度：五级代理　清洗：rn=1 去重 ＋ 测试线标记（不混入生产数）
--  ---------------------------------------------------------------------------------------------
--  改动缘由（先生 2026-08-25 指令：真实代理一个不漏）：
--    旧件 q 侧写死 v.bet20 AS lv3，只出第三层代理 455 行，LV1/LV2/LV4/LV5 一层皆无；
--    且六层商业列由 CROSS JOIN x_win 而来，每行皆为全窗常数，非该代理净利。
--  ---------------------------------------------------------------------------------------------
--  ★ 测试线处置（先生裁定：标记后分开计算）
--    is_test_line   该级代理本身在 age022='1' 名单内
--    line_has_test  该注单五级链任一级为测试线
--    生产口径：line_has_test = 0 的行才计入 stake/valid_bet/profit/rebate_cost/ngr
--    审计口径：stake_testline_audit / profit_testline_audit 单列，绝不并入生产数
--  ---------------------------------------------------------------------------------------------
--  ★★ AG-03 未裁定 —— 本件占成相关列一律【中立命名】，不预设归属 ★★
--    pct_top_bet23      = AVG(bet23)          顶层原始值（约 96），归属待裁
--    pct_complement     = AVG(100 - bet23)    其补数（约 4），归属待裁
--    own_share_pct_unw  = AVG(本级差分)x100   各代理【不加权】均值，跨级【不可相加】
--    own_share_pct_w    = 按 ABS(profit) 加权  ★ 可与 pct_top_bet23 对账
--    逐行恒等式（望远镜）：五级本级差分之和 = bet23/100，故加权和约等于 pct_top_bet23
--    不加权均值之和（约 100.37）【不等于】bet23 —— 五级代理数不同（166/226/460/872/2467），
--    对不同母体各取一次算术平均再相加，本就无恒等式可言；此非误差，是口径错配。
--    cost_ownshare_a  / residual_a   读法A：bet23 为代理线合计占成
--    cost_complement_b/ residual_b   读法B：bet23 为公司自留
--    二者不可能同真；AG-03 裁定前，本件经济列禁作商业处置依据。
--  ---------------------------------------------------------------------------------------------
--  ★ 跨级不可相加：每级都对整条线注单摊算一次，五级相加会 5 倍重复计数。
--    比较须在同一 agent_level 内进行。
-- ══════════════════════════════════════════════════════════════════════════════════════════════
-- ── ① 先跑 T_true 留档（不足 100000 者一次导全，不必分批）──
-- ── ① T_true：HF9c 不再强制预跑完整 COUNT。
--    本批实际返回行数 < 100000 即判定为末批；全批完成后以各批 n_rows / audit_rn 范围核对总量。

-- ── ② 分批取数：第 1 批。第 k 批只改末行两数为 (k-1)*100000 与 k*100000 ──
--    审计字段二（REDTEAM 2026-08-24 裁定 · 四锁）：
--      audit_rn  全局观测坐标 —— 由**与原版审计版逐字同一**之排序键所生，两版可逐行对账
--      batch_id  物理分批信息 —— 该行所属批次，由 audit_rn 算得，非引擎所赋
--    ★ 锁三：二者皆为审计字段，**不得进入任何业务指标计算**。
--    ★ 锁四：两版经 audit_rn 逐行字段核验后，方可宣布输出完全一致。
--    ★ 模块头与字段释义见本件 ① 探数块，此处不重出（全包规范）。

-- ── ③ 每批取回后自证四数（任一不符即停手回报，禁止放行）──
--    n_rows        = COUNT(*)      须等于 COUNT(DISTINCT audit_rn)   （批内无重复）
--    audit_rn_min  = MIN(audit_rn) 须等于 (k-1)*100000 + 1           （与上批严丝合缝）
--    audit_rn_max  = MAX(audit_rn) 须等于 min + n_rows - 1           （批内无缺口）
--    全批取毕再验：各批 audit_rn 之并集 = 1 .. T_true，无缺号、无重号。
--     ★ 首行＝ residual_b 最小者（AG-03 未裁定，故不称「平台真净亏最多者」）。
--     ★ 本件另须自证两条恒等式：
--         同一 agent_level 内  Σ own_share_pct_w（按注单加权）≈ pct_top_bet23
--         逐行               pct_top_bet23 + pct_complement = 100
--         n_bets_all = n_bets_prod + n_bets_testline
--
SELECT z.*,
       CAST(FLOOR((z.audit_rn - 1) / 100000) + 1 AS INT)                 AS batch_id,
       'A168_HF9F_20260827_0900' AS run_id,
       '2026-08-27 09:00:00' AS snapshot_sync_time
FROM (
  SELECT y.*,
         ROW_NUMBER() OVER (ORDER BY y.`agent_level`, y.`residual_b` ASC, y.`agent_id`) AS audit_rn
  FROM (
  WITH ta AS (
    SELECT DISTINCT CAST(NULLIF(TRIM(age001),'') AS BIGINT)              AS aid
    FROM ods_mariadb_2b.ods_a168_agent
    WHERE age022 = '1'
  ),
  rk AS (
    SELECT b.bet01, b.bet05, b.bet11, b.bet13, b.bet16, b.bet17, b.validbet,
           b.bet18, b.bet19, b.bet20, b.bet21, b.bet22,
           b.bet23, b.bet24, b.bet25, b.bet26, b.bet27,
           b.dt, b.category, b.bet38,
           ROW_NUMBER() OVER (
             PARTITION BY b.bet01
             ORDER BY b.updatetime DESC, b.sync_time DESC, b.dt DESC)    AS rn
    FROM ods_mariadb_2b.ods_a168_bet02 b
    WHERE b.dt >= '2026-03-21' AND b.dt < '2026-08-07'
      AND b.bet02 = '101'
      AND b.sync_time <= '2026-08-27 09:00:00'
  ),
  vd AS (
    SELECT r.*,
           CASE WHEN t1.aid IS NOT NULL THEN 1 ELSE 0 END                AS lv1_is_test,
           CASE WHEN t2.aid IS NOT NULL THEN 1 ELSE 0 END                AS lv2_is_test,
           CASE WHEN t3.aid IS NOT NULL THEN 1 ELSE 0 END                AS lv3_is_test,
           CASE WHEN t4.aid IS NOT NULL THEN 1 ELSE 0 END                AS lv4_is_test,
           CASE WHEN t5.aid IS NOT NULL THEN 1 ELSE 0 END                AS lv5_is_test,
           CASE WHEN COALESCE(t1.aid,t2.aid,t3.aid,t4.aid,t5.aid) IS NOT NULL
                THEN 1 ELSE 0 END                                        AS line_has_test
    FROM rk r
    LEFT JOIN ta t1 ON t1.aid = CAST(NULLIF(TRIM(r.bet18),'') AS BIGINT)
    LEFT JOIN ta t2 ON t2.aid = CAST(NULLIF(TRIM(r.bet19),'') AS BIGINT)
    LEFT JOIN ta t3 ON t3.aid = CAST(NULLIF(TRIM(r.bet20),'') AS BIGINT)
    LEFT JOIN ta t4 ON t4.aid = CAST(NULLIF(TRIM(r.bet21),'') AS BIGINT)
    LEFT JOIN ta t5 ON t5.aid = CAST(NULLIF(TRIM(r.bet22),'') AS BIGINT)
    WHERE r.rn = 1
      AND r.category = '1' AND UPPER(TRIM(r.bet38)) = 'N'
      AND CAST(NULLIF(TRIM(r.bet05),'') AS BIGINT) > 0
      AND CAST(NULLIF(TRIM(r.bet11),'') AS DECIMAL(20,8)) > 0
  ),
  bs AS (
    SELECT CAST(NULLIF(TRIM(v.bet05),'') AS BIGINT)                      AS member_id,
           v.dt AS bet_date, v.line_has_test,
           CAST(NULLIF(TRIM(v.bet13),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(v.bet11),'') AS DECIMAL(20,8))           AS stake,
           CAST(NULLIF(TRIM(v.validbet),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(v.bet11),'') AS DECIMAL(20,8))           AS valid_bet,
           CAST(NULLIF(TRIM(v.bet16),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(v.bet11),'') AS DECIMAL(20,8))           AS rebate_cost,
           -CAST(NULLIF(TRIM(v.bet17),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(v.bet11),'') AS DECIMAL(20,8))           AS profit,
           COALESCE(CAST(NULLIF(TRIM(v.bet23),'') AS DECIMAL(20,6)),0)   AS pct_lv1,
           COALESCE(CAST(NULLIF(TRIM(v.bet24),'') AS DECIMAL(20,6)),0)   AS pct_lv2,
           COALESCE(CAST(NULLIF(TRIM(v.bet25),'') AS DECIMAL(20,6)),0)   AS pct_lv3,
           COALESCE(CAST(NULLIF(TRIM(v.bet26),'') AS DECIMAL(20,6)),0)   AS pct_lv4,
           COALESCE(CAST(NULLIF(TRIM(v.bet27),'') AS DECIMAL(20,6)),0)   AS pct_lv5,
           CAST(NULLIF(TRIM(v.bet18),'') AS BIGINT) AS a1, v.lv1_is_test,
           CAST(NULLIF(TRIM(v.bet19),'') AS BIGINT) AS a2, v.lv2_is_test,
           CAST(NULLIF(TRIM(v.bet20),'') AS BIGINT) AS a3, v.lv3_is_test,
           CAST(NULLIF(TRIM(v.bet21),'') AS BIGINT) AS a4, v.lv4_is_test,
           CAST(NULLIF(TRIM(v.bet22),'') AS BIGINT) AS a5, v.lv5_is_test
    FROM vd v
  ),
  lvl AS (
    SELECT 1 AS agent_level, a1 AS agent_id, a1 AS lv1_id,
           CAST(NULL AS BIGINT) AS parent_id, lv1_is_test AS is_test_line,
           (pct_lv1 - pct_lv2)/100.0 AS own_share, line_has_test,
           member_id, bet_date, stake, valid_bet, rebate_cost, profit, pct_lv1
    FROM bs WHERE a1 IS NOT NULL
    UNION ALL
    SELECT 2, a2, a1, a1, lv2_is_test, (pct_lv2 - pct_lv3)/100.0, line_has_test,
           member_id, bet_date, stake, valid_bet, rebate_cost, profit, pct_lv1
    FROM bs WHERE a2 IS NOT NULL
    UNION ALL
    SELECT 3, a3, a1, a2, lv3_is_test, (pct_lv3 - pct_lv4)/100.0, line_has_test,
           member_id, bet_date, stake, valid_bet, rebate_cost, profit, pct_lv1
    FROM bs WHERE a3 IS NOT NULL
    UNION ALL
    SELECT 4, a4, a1, a3, lv4_is_test, (pct_lv4 - pct_lv5)/100.0, line_has_test,
           member_id, bet_date, stake, valid_bet, rebate_cost, profit, pct_lv1
    FROM bs WHERE a4 IS NOT NULL
    UNION ALL
    SELECT 5, a5, a1, a4, lv5_is_test, pct_lv5/100.0, line_has_test,
           member_id, bet_date, stake, valid_bet, rebate_cost, profit, pct_lv1
    FROM bs WHERE a5 IS NOT NULL
  ),
  q AS (
    SELECT agent_level, agent_id,
           MAX(lv1_id)                                                   AS top_agent_id,
           MAX(parent_id)                                                AS parent_agent_id,
           MAX(is_test_line)                                             AS is_test_line,
           COUNT(*)                                                      AS n_bets_all,
           SUM(CASE WHEN line_has_test=0 THEN 1 ELSE 0 END)              AS n_bets_prod,
           SUM(CASE WHEN line_has_test=1 THEN 1 ELSE 0 END)              AS n_bets_testline,
           COUNT(DISTINCT member_id)                                     AS n_members_all,
           COUNT(DISTINCT CASE WHEN line_has_test=0 THEN member_id END)  AS n_members_prod,
           COUNT(DISTINCT bet_date)                                      AS active_days,
           MIN(bet_date)                                                 AS first_seen,
           MAX(bet_date)                                                 AS last_seen,
           ROUND(AVG(own_share)*100,6)                                   AS own_share_pct_unw,
           ROUND(SUM(own_share*ABS(profit))
               / NULLIF(SUM(ABS(profit)),0)*100,6)                       AS own_share_pct_w,
           ROUND(AVG(100-pct_lv1),6)                                     AS pct_complement,
           ROUND(AVG(pct_lv1),6)                                         AS pct_top_bet23,
           ROUND(SUM(CASE WHEN line_has_test=0 THEN stake       ELSE 0 END),4) AS stake,
           ROUND(SUM(CASE WHEN line_has_test=0 THEN valid_bet   ELSE 0 END),4) AS valid_bet,
           ROUND(SUM(CASE WHEN line_has_test=0 THEN profit      ELSE 0 END),4) AS profit,
           ROUND(SUM(CASE WHEN line_has_test=0 THEN rebate_cost ELSE 0 END),4) AS rebate_cost,
           ROUND(SUM(CASE WHEN line_has_test=0 THEN profit*(100-pct_lv1)/100.0 ELSE 0 END),4) AS cost_complement_b,
           ROUND(SUM(CASE WHEN line_has_test=0 THEN profit*own_share ELSE 0 END),4)           AS cost_ownshare_a,
           ROUND(SUM(CASE WHEN line_has_test=0 THEN profit - rebate_cost ELSE 0 END),4)       AS ngr,
           ROUND(SUM(CASE WHEN line_has_test=0
                          THEN profit - rebate_cost - profit*(100-pct_lv1)/100.0 ELSE 0 END),4) AS residual_b,
           ROUND(SUM(CASE WHEN line_has_test=0
                          THEN profit - rebate_cost - profit*own_share ELSE 0 END),4)           AS residual_a,
           ROUND(SUM(CASE WHEN line_has_test=0 THEN profit ELSE 0 END)
               / NULLIF(SUM(CASE WHEN line_has_test=0 THEN stake ELSE 0 END),0),8)            AS hold_rate,
           ROUND(SUM(CASE WHEN line_has_test=1 THEN stake  ELSE 0 END),4)  AS stake_testline_audit,
           ROUND(SUM(CASE WHEN line_has_test=1 THEN profit ELSE 0 END),4)  AS profit_testline_audit,
           CASE WHEN MAX(is_test_line)=1 THEN 'TEST_LINE'
                WHEN SUM(CASE WHEN line_has_test=0 THEN 1 ELSE 0 END)=0 THEN 'NO_PROD_ROWS'
                ELSE 'PRODUCTION' END                                    AS agent_status,
           'AG03-UNRESOLVED'                                             AS agent_formula_version
    FROM lvl
    GROUP BY agent_level, agent_id
  )
  SELECT q.* FROM q
) y
) z
-- ── 逐批 WHERE 阶梯（★ 口诀：上界 ＝ 下界 ＋ 100000，两数同进）──
--    本件 T_true 未测，无需先跑 T_true；以 0 / 100000 控制本批返回区间，末批由实际行数 < 100000 判定
--    WHERE z.audit_rn >        0 AND z.audit_rn <=   100000   -- 第 1 批
--    WHERE z.audit_rn >   100000 AND z.audit_rn <=   200000   -- 第 2 批
--    WHERE z.audit_rn >   200000 AND z.audit_rn <=   300000   -- 第 3 批
--    WHERE z.audit_rn >   300000 AND z.audit_rn <=   400000   -- 第 4 批
--    WHERE z.audit_rn >   400000 AND z.audit_rn <=   500000   -- 第 5 批
--    WHERE z.audit_rn >   500000 AND z.audit_rn <=   600000   -- 第 6 批
--    WHERE z.audit_rn >   600000 AND z.audit_rn <=   700000   -- 第 7 批
--    …余批类推。第 k 批：WHERE z.audit_rn > (k-1)*100000 AND z.audit_rn <= k*100000
--    某批返回 < 100000 行即为末批，其后不再取。
--
--    ⚠ 常见误写（务必避开）：只推下界而上界不动 ——
--        WHERE z.audit_rn > 100000 AND z.audit_rn <= 100000   ← 自相矛盾，恒为假，返回空集
--        WHERE z.audit_rn > 200000 AND z.audit_rn <= 100000   ← 同上，空集
--      两个数必须**同时**前进，且始终相差 100000。
--      下界 ＝ 上一批之上界；上界 ＝ 本批之上界。
WHERE z.audit_rn > 0 AND z.audit_rn <= 100000 -- ★ HF9c 本批区间
ORDER BY z.audit_rn;
--     ★ audit_rn 之排序键与原版审计版**逐字同一**（锁一），故两版可逐行对账。


-- ══════════════════════════════════════════════════════════════════════════════════════════════
--  79. S04_analyst_score.csv   [总包行 6277~6302 · 原 7 列 ＋六层约 60 列]
--     典型学：R01 风控专员　派生旗标：recent（s.x_rec = 1 · 仅供 CASE 条件聚合，全包无任何 WHERE/AND/HAVING 以此过滤）　连接：q.`entity_id`
-- ══════════════════════════════════════════════════════════════════════════════════════════════
-- ── ① 先跑 T_true 留档（不足 100000 者一次导全，不必分批）──
-- ── ① T_true：HF9c 不再强制预跑完整 COUNT。
--    本批实际返回行数 < 100000 即判定为末批；全批完成后以各批 n_rows / audit_rn 范围核对总量。

-- ── ② 分批取数：第 1 批。第 k 批只改末行两数为 (k-1)*100000 与 k*100000 ──
--    审计字段二（REDTEAM 2026-08-24 裁定 · 四锁）：
--      audit_rn  全局观测坐标 —— 由**与原版审计版逐字同一**之排序键所生，两版可逐行对账
--      batch_id  物理分批信息 —— 该行所属批次，由 audit_rn 算得，非引擎所赋
--    ★ 锁三：二者皆为审计字段，**不得进入任何业务指标计算**。
--    ★ 锁四：两版经 audit_rn 逐行字段核验后，方可宣布输出完全一致。

-- ── ③ 每批取回后自证四数（任一不符即停手回报，禁止放行）──
--    n_rows        = COUNT(*)      须等于 COUNT(DISTINCT audit_rn)   （批内无重复）
--    audit_rn_min  = MIN(audit_rn) 须等于 (k-1)*100000 + 1           （与上批严丝合缝）
--    audit_rn_max  = MAX(audit_rn) 须等于 min + n_rows - 1           （批内无缺口）
--    全批取毕再验：各批 audit_rn 之并集 = 1 .. T_true，无缺号、无重号。
--     ★ 首行＝平台真净亏最多者（已扣退水与代理占成）。
--
SELECT z.*,
       CAST(FLOOR((z.audit_rn - 1) / 100000) + 1 AS INT)          AS batch_id,
       'A168_HF9F_20260827_0900' AS run_id,
       '2026-08-27 09:00:00' AS snapshot_sync_time
FROM (
  SELECT y.*,
         ROW_NUMBER() OVER (ORDER BY y.`residual_b` ASC, y.`roi` DESC, y.`entity_id`, y.`标注产量`, y.`覆盖IP广度`, y.`判定详尽度`, y.`理由空白数`, y.`首次登记`, y.`最近登记`) AS audit_rn
  FROM (
    WITH
      x_ranked AS (
    SELECT b.bet01, b.bet03, b.bet04, b.bet05, b.bet09, b.bet11, b.bet13,
           b.bet15, b.bet16, b.bet17, b.bet18, b.bet19, b.bet20, b.bet21,
           b.bet22, b.bet23, b.bet24, b.bet25, b.bet26, b.bet27, b.bet38, b.bet39, b.category, b.commission,
           b.dt, b.eid, b.ip, b.validbet, b.updatetime, b.sync_time,
           ROW_NUMBER() OVER (
             PARTITION BY b.bet01
             ORDER BY b.updatetime DESC, b.sync_time DESC, b.dt DESC)      AS x_rn
    FROM ods_mariadb_2b.ods_a168_bet02 b
    WHERE b.dt >= '2026-03-21' AND b.dt < '2026-08-07'
      AND b.bet02 = '101'
      AND b.sync_time <= '2026-08-27 09:00:00'
  ),
    x_testagent AS (
    SELECT age001 AS agent_id FROM ods_mariadb_2b.ods_a168_agent WHERE age022 = '1'
  ),
    x_bs0 AS (
    SELECT b.bet05 AS x_member, b.eid AS x_dealer, b.bet39 AS x_table,
           b.bet03 AS x_shoe, b.ip AS x_ip, b.bet09 AS x_product, b.dt AS x_date,
           CONCAT_WS('|', b.bet03, b.bet04, b.bet39)                      AS x_round,
           CONCAT_WS('|', b.bet39, b.bet03)                               AS x_tblshoe,
           CAST(NULLIF(TRIM(b.bet04),'') AS INT)                          AS x_rno,
           CASE WHEN b.dt >= '2026-07-08' THEN 1 ELSE 0 END               AS x_rec,
           CASE WHEN TRIM(b.commission)='1' THEN 1 ELSE 0 END             AS x_freecomm,
           CAST(NULLIF(TRIM(b.bet13),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_stake,
           CAST(NULLIF(TRIM(b.validbet),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_valid,
           CAST(NULLIF(TRIM(b.bet16),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_rebate,
           CAST(NULLIF(TRIM(b.bet17),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_net,
           CAST(NULLIF(TRIM(b.bet15),'') AS DECIMAL(20,6))                AS x_rbpct,
           COALESCE(CAST(NULLIF(TRIM(b.bet23),'') AS DECIMAL(20,6)),0)   AS x_agpct,
          NULLIF(CAST(NULLIF(TRIM(b.bet23),'') AS DECIMAL(20,6)),0)     AS x_rate1,
          NULLIF(CAST(NULLIF(TRIM(b.bet24),'') AS DECIMAL(20,6)),0)     AS x_rate2,
          NULLIF(CAST(NULLIF(TRIM(b.bet25),'') AS DECIMAL(20,6)),0)     AS x_rate3,
          NULLIF(CAST(NULLIF(TRIM(b.bet26),'') AS DECIMAL(20,6)),0)     AS x_rate4,
          NULLIF(CAST(NULLIF(TRIM(b.bet27),'') AS DECIMAL(20,6)),0)     AS x_rate5,
          (CASE WHEN NULLIF(CAST(NULLIF(TRIM(b.bet22),'') AS BIGINT),0) IS NOT NULL THEN 5
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet21),'') AS BIGINT),0) IS NOT NULL THEN 4
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet20),'') AS BIGINT),0) IS NOT NULL THEN 3
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet19),'') AS BIGINT),0) IS NOT NULL THEN 2
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet18),'') AS BIGINT),0) IS NOT NULL THEN 1
                ELSE 0 END)                                             AS x_chain_depth,
           CASE WHEN COALESCE(t1.agent_id,t2.agent_id,t3.agent_id,
                              t4.agent_id,t5.agent_id) IS NOT NULL
                THEN 1 ELSE 0 END                                        AS f_testline
    FROM x_ranked b
    LEFT JOIN x_testagent t1 ON t1.agent_id = b.bet18
    LEFT JOIN x_testagent t2 ON t2.agent_id = b.bet19
    LEFT JOIN x_testagent t3 ON t3.agent_id = b.bet20
    LEFT JOIN x_testagent t4 ON t4.agent_id = b.bet21
    LEFT JOIN x_testagent t5 ON t5.agent_id = b.bet22
    WHERE b.x_rn = 1
      AND b.category='1' AND UPPER(TRIM(b.bet38))='N'
      AND CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8)) > 0
  ),
  x_mk AS (
    SELECT s.*,
           CASE WHEN s.f_testline = 0 THEN 1 ELSE 0 END                 AS is_clean
    FROM x_bs0 s
  ),
  x_agg AS (
    SELECT s.x_member                                                        AS x_key,
           COUNT(*) AS n_bets, COUNT(DISTINCT s.x_round) AS n_rounds,
           COUNT(DISTINCT s.x_date) AS active_days, COUNT(DISTINCT s.x_tblshoe) AS active_shoes,
           COUNT(DISTINCT CONCAT_WS('|', s.x_date, s.x_table)) AS active_sessions,
           COUNT(DISTINCT s.x_table) AS n_tables, COUNT(DISTINCT s.x_dealer) AS n_dealers,
           COUNT(DISTINCT s.x_ip) AS n_ips, COUNT(DISTINCT s.x_product) AS n_products,
           MIN(s.x_date) AS first_seen_d, MAX(s.x_date) AS last_seen_d,
           SUM(s.x_stake) AS stake, SUM(s.x_valid) AS valid, SUM(s.x_rebate) AS rebate,
           SUM(s.x_net) AS net, SUM(-s.x_net *(100.0-s.x_agpct)/100.0) AS agent_cost,
           AVG(100.0-s.x_agpct)                   AS agent_pct,
           AVG(s.x_agpct)                         AS company_retain_pct,
           SUM(-s.x_net *s.x_agpct/100.0)         AS agent_cost_a_legacy,
           SUM(s.x_valid*s.x_agpct/100.0)         AS agent_cost_valid_base_legacy,
          AVG(COALESCE(s.x_rate1,100)) AS retain_pct_lv1, AVG(COALESCE(s.x_rate2,100)) AS retain_pct_lv2,
          AVG(COALESCE(s.x_rate3,100)) AS retain_pct_lv3, AVG(COALESCE(s.x_rate4,100)) AS retain_pct_lv4,
          AVG(COALESCE(s.x_rate5,100)) AS retain_pct_lv5, AVG(s.x_chain_depth) AS chain_depth_avg,
          AVG(COALESCE(100.0-s.x_rate1,0)) AS agent_pct_lv1, AVG(COALESCE(100.0-s.x_rate2,0)) AS agent_pct_lv2,
          AVG(COALESCE(100.0-s.x_rate3,0)) AS agent_pct_lv3, AVG(COALESCE(100.0-s.x_rate4,0)) AS agent_pct_lv4,
          AVG(COALESCE(100.0-s.x_rate5,0)) AS agent_pct_lv5,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate1,0)/100.0)                        AS agent_cost_lv1,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate2,0)/100.0)                        AS agent_cost_lv2,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate3,0)/100.0)                        AS agent_cost_lv3,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate4,0)/100.0)                        AS agent_cost_lv4,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate5,0)/100.0)                        AS agent_cost_lv5,
          SUM(-s.x_net*(COALESCE(100.0-s.x_rate1,0)+COALESCE(100.0-s.x_rate2,0)
                       +COALESCE(100.0-s.x_rate3,0)+COALESCE(100.0-s.x_rate4,0)
                       +COALESCE(100.0-s.x_rate5,0))/100.0)                   AS agent_cost_chain_additive,
          SUM(-s.x_net*(1.0 - CAST(COALESCE(s.x_rate1,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate2,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate3,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate4,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate5,100) AS DOUBLE)/100.0))
                                                                       AS agent_cost_chain_nested,
           AVG(s.x_rbpct) AS rbpct, AVG(s.x_freecomm*1.0) AS freecomm_rate,
           PERCENTILE_APPROX(s.x_stake,0.25) AS p25, PERCENTILE_APPROX(s.x_stake,0.50) AS p50,
           PERCENTILE_APPROX(s.x_stake,0.75) AS p75, PERCENTILE_APPROX(s.x_stake,0.90) AS p90,
           PERCENTILE_APPROX(s.x_stake,0.95) AS p95, PERCENTILE_APPROX(s.x_stake,0.99) AS p99,
           PERCENTILE_APPROX(s.x_valid,0.50) AS p50_valid,
           PERCENTILE_APPROX(s.x_net,0.50)   AS p50_profit,
           SUM(CASE WHEN s.x_rec = 1 THEN s.x_stake ELSE 0 END) AS st_in,
           SUM(CASE WHEN s.x_rec = 1 THEN 1 ELSE 0 END)         AS nb_in,
           SUM(CASE WHEN s.x_rec = 1 THEN s.x_net ELSE 0 END)   AS net_in,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN s.x_stake ELSE 0 END) AS st_out,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN 1 ELSE 0 END)         AS nb_out,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN s.x_net ELSE 0 END)   AS net_out,
           SUM(CASE WHEN s.x_rec=1 THEN s.x_stake ELSE 0 END) AS st_rec,
           SUM(CASE WHEN s.x_rec=1 THEN 1 ELSE 0 END)         AS nb_rec
    FROM x_mk s
    WHERE s.is_clean = 1
      AND s.x_member IS NOT NULL AND TRIM(CAST(s.x_member AS STRING)) <> ''
    GROUP BY s.x_member
  ),
      q AS (
        SELECT                                                                                              -- 续行：接续上一取列子句，续列 SELECT
          COALESCE(NULLIF(TRIM(creator), ''), '未署名')      AS entity_id,                                     -- 取值表达式：产出「entity_id」
          -- ★ 下面三个列名与报告的风控专员雷达字典严格对应，一字不可改
          COUNT(*)                                            AS 标注产量,                                      -- 计数表达式：产出「标注产量」
          COUNT(DISTINCT TRIM(ip))                            AS 覆盖IP广度,                                    -- 计数表达式：统计去重个数，产出「覆盖IP广度」
          AVG(LENGTH(COALESCE(remarks, '')))                  AS 判定详尽度,                                     -- 求均值表达式：产出「判定详尽度」
          -- ★ 2026-08-14 增列（S1 斧正 · 同名异义之根治）：
          --   「理由空白率」此前在报表侧以代理口径推算（1 − 判定详尽度 ÷ 全体中位详尽度），
          --   该式量的是**理由字数的相对长短**，而非**有没有写理由**——
          --   一名写五百字套话者判为 0，一名写二十字要害者判近 1，名实不符。
          --   今补出真口径之分子。表达式逐字取自 §S-04b（本包第 2,229 行），同表同源，
          --   不新增扫描、不新增连接。报表侧「理由空白率 = 理由空白数 ÷ 标注产量」。
          SUM(CASE WHEN NULLIF(TRIM(remarks),'') IS NULL
                   THEN 1 ELSE 0 END)                         AS 理由空白数,                                     -- 汇总表达式：产出「理由空白数」（理由空白率之分子）
          MIN(addtime)                                        AS 首次登记,                                      -- 取最小值表达式：产出「首次登记」
          MAX(addtime)                                        AS 最近登记                                       -- 取最大值表达式：产出「最近登记」
        FROM ods_mariadb_2b.ods_a168_alert_ip_setting                                                       -- 取数来源：取自风控 IP 名单配置表（人工标记史料源）
        -- ★ 2026-08-14 增补窗口上界（S1 斧正 · 时间一致性）：
        --   实测查出 creator = livegame 之最近登记为 2026-08-09 20:48:43，
        --   晚于本方案分析窗口截止日 2026-08-07——属未来信息。
        --   凡该维参与与窗内结果之对照判定者，未加此界即构成时间一致性违规。
        --   注：alert_ip_setting 为配置类表、无 dt 分区列（见 §EX-00 判据），
        --   故此处以 addtime 施界，不写 dt。
        WHERE addtime < '2026-08-07'                                                                        -- 过滤条件：限定 addtime 小于窗口截止日，杜绝未来信息
        GROUP BY COALESCE(NULLIF(TRIM(creator), ''), '未署名')                                                 -- 分组：按 COALESCE(NULLIF(TRIM(creator), ''), '未署名') 汇总
      )
    SELECT q.*,
           -- 一·经济层
           ROUND(e.stake,4) AS stake, ROUND(e.valid,4) AS valid_bet,
           ROUND(-e.net,4) AS profit, e.n_bets, e.n_rounds,
           ROUND(e.net/NULLIF(e.stake,0),8) AS roi,
           ROUND(e.net_in/NULLIF(e.st_in,0),8) AS roi_recent,
           ROUND(e.net_out/NULLIF(e.st_out,0),8) AS roi_non_recent,
           ROUND((e.net-e.rebate)/NULLIF(e.stake,0),8) AS roi_ex_rebate,
           ROUND(e.net,4) AS roi_numerator, ROUND(e.stake,4) AS roi_denominator,
           CASE WHEN e.stake IS NULL THEN 'NULL_DENOM' WHEN e.stake<=0 THEN 'ZERO_DENOM'
                WHEN e.n_bets<30 THEN 'THIN_EXPOSURE' ELSE 'OK' END AS roi_denominator_status,
           ROUND(e.rebate,4) AS rebate_cost, ROUND(e.agent_cost,4)                           AS cost_complement_b,
       ROUND(e.agent_pct,4)                            AS pct_complement,
       ROUND(e.company_retain_pct,4)                   AS pct_top_bet23,
       'AG03-UNRESOLVED'                                     AS agent_formula_version,
      'ALL5_LEVELS_bet23_to_bet27'                    AS agent_level_scope,
      ROUND(e.agent_cost_lv1,4) AS agent_cost_lv1, ROUND(e.agent_cost_lv2,4) AS agent_cost_lv2,
      ROUND(e.agent_cost_lv3,4) AS agent_cost_lv3, ROUND(e.agent_cost_lv4,4) AS agent_cost_lv4,
      ROUND(e.agent_cost_lv5,4) AS agent_cost_lv5,
      ROUND(e.agent_pct_lv1,6) AS agent_pct_lv1, ROUND(e.agent_pct_lv2,6) AS agent_pct_lv2,
      ROUND(e.agent_pct_lv3,6) AS agent_pct_lv3, ROUND(e.agent_pct_lv4,6) AS agent_pct_lv4,
      ROUND(e.agent_pct_lv5,6) AS agent_pct_lv5,
      ROUND(e.retain_pct_lv1,6) AS retain_pct_lv1, ROUND(e.retain_pct_lv2,6) AS retain_pct_lv2,
      ROUND(e.retain_pct_lv3,6) AS retain_pct_lv3, ROUND(e.retain_pct_lv4,6) AS retain_pct_lv4,
      ROUND(e.retain_pct_lv5,6) AS retain_pct_lv5, ROUND(e.chain_depth_avg,4) AS chain_depth_avg,
      ROUND(e.agent_cost_chain_additive,4)            AS agent_cost_chain_additive,
      ROUND(e.agent_cost_chain_nested,4)              AS agent_cost_chain_nested,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_additive,4) AS residual_chain_additive,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_nested,4)   AS residual_chain_nested,
      'PENDING_AG03'                                  AS decision_status,
      'FALSE'                                         AS admit_to_risk_decision,
      'NOT_FOR_ENFORCEMENT'                           AS deliverable_class,
       ROUND(e.agent_cost_a_legacy,4)                  AS agent_cost_a_legacy,
       ROUND(e.agent_cost_valid_base_legacy,4)         AS agent_cost_valid_base_legacy,
           ROUND(-e.net-e.rebate,4)                        AS ngr,
       ROUND(-e.net-e.rebate-e.agent_cost,4)           AS residual_b,
       ROUND(-e.net-e.rebate-e.agent_cost_a_legacy,4)  AS residual_a,
           ROUND((-e.net-e.rebate)/NULLIF(e.stake,0),8)    AS ngr_rate,
       ROUND((-e.net-e.rebate-e.agent_cost)/NULLIF(e.stake,0),8)   AS residual_b_rate,
      -- 【HF9c · canonical accounting contract】
      --   以下 canonical 字段只增加明确 scope；不删除、不覆盖既有字段。
      --   formal_bet23_* 保持 HF9b 当前生产公式及其 NULL/0 语义；
      --   lv1~lv5 / additive / nested 则分别采用各自原始 e.* 成本字段，
      --   rate 一律从未舍入的 e.* 分子 / e.stake 计算，禁止由展示值反算。
      ROUND(e.agent_cost,4) AS agent_cost_bet23_formal_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost,4) AS net_margin_bet23_formal_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost)/NULLIF(e.stake,0),8) AS net_margin_bet23_formal_rate_canonical,
      ROUND(e.agent_cost_lv1,4) AS agent_cost_lv1_bet23_canonical,
      ROUND(e.agent_cost_lv2,4) AS agent_cost_lv2_bet24_canonical,
      ROUND(e.agent_cost_lv3,4) AS agent_cost_lv3_bet25_canonical,
      ROUND(e.agent_cost_lv4,4) AS agent_cost_lv4_bet26_canonical,
      ROUND(e.agent_cost_lv5,4) AS agent_cost_lv5_bet27_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_lv1,4) AS net_margin_lv1_bet23_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_lv1)/NULLIF(e.stake,0),8) AS net_margin_lv1_bet23_rate_canonical,
      ROUND(e.agent_cost_chain_additive,4) AS agent_cost_chain_additive_canonical,
      ROUND(e.agent_cost_chain_nested,4) AS agent_cost_chain_nested_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_additive,4) AS net_margin_chain_additive_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_nested,4) AS net_margin_chain_nested_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_chain_additive)/NULLIF(e.stake,0),8) AS net_margin_chain_additive_rate_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_chain_nested)/NULLIF(e.stake,0),8) AS net_margin_chain_nested_rate_canonical,
       ROUND((-e.net-e.rebate-e.agent_cost_a_legacy)/NULLIF(e.stake,0),8) AS residual_a_rate,
           -- 二·分布层
           ROUND(e.stake/NULLIF(e.n_bets,0),4) AS avg_stake_per_bet,
           ROUND(e.valid/NULLIF(e.n_rounds,0),4) AS avg_valid_bet_per_round,
           ROUND(-e.net/NULLIF(e.n_rounds,0),4) AS avg_profit_per_round,
           ROUND(-e.net/NULLIF(e.active_days,0),4) AS avg_profit_per_day,
           ROUND(-e.net/NULLIF(e.active_shoes,0),4) AS avg_profit_per_shoe,
           ROUND(e.stake/NULLIF(e.active_days,0),4) AS avg_stake_per_active_day,
           ROUND(e.n_rounds*1.0/NULLIF(e.active_days,0),4) AS avg_rounds_per_active_day,
           ROUND(e.st_in/NULLIF(e.nb_in,0),4) AS avg_stake_recent,
           ROUND(e.st_out/NULLIF(e.nb_out,0),4) AS avg_stake_non_recent,
           ROUND(e.p25,4) AS p25_stake, ROUND(e.p50,4) AS p50_stake, ROUND(e.p75,4) AS p75_stake,
           ROUND(e.p90,4) AS p90_stake, ROUND(e.p95,4) AS p95_stake, ROUND(e.p99,4) AS p99_stake,
           ROUND(e.p50_valid,4) AS p50_valid_bet, ROUND(e.p50_profit,4) AS p50_profit,
           ROUND(e.p95/NULLIF(e.p50,0),6) AS p95_over_p50,
           ROUND(e.p99/NULLIF(e.p50,0),6) AS p99_over_p50,
           ROUND((e.stake/NULLIF(e.n_bets,0))/NULLIF(e.p50,0),6) AS avg_over_p50,
           -- 三·关系层
           e.n_tables AS common_table_count, e.n_dealers AS common_dealer_count,
           e.n_ips AS common_ip_count, e.n_products AS common_product_count,
           ROUND(e.st_in/NULLIF(e.stake,0),8) AS share_recent,
           -- 四·rate 层
           ROUND(-e.net/NULLIF(e.stake,0),8) AS hold_rate,
           ROUND(-e.net_in/NULLIF(e.st_in,0),8) AS hold_rate_recent,
           ROUND(e.rebate/NULLIF(e.valid,0),8) AS rebate_rate_actual,
           ROUND(e.rbpct,6) AS rebate_pct_config,
           ROUND(e.valid/NULLIF(e.stake,0),6) AS turnover_multiple,
           ROUND(e.freecomm_rate,6) AS free_comm_rate,
           ROUND(e.net_in/NULLIF(e.st_in,0)-e.net_out/NULLIF(e.st_out,0),8) AS roi_delta_recent,
           -- 五·动态层
           e.first_seen_d AS first_seen, e.last_seen_d AS last_seen,
           e.active_days, e.active_shoes, e.active_sessions,
           DATEDIFF(e.last_seen_d, e.first_seen_d)+1 AS span_days,
           ROUND(e.active_days*1.0/NULLIF(DATEDIFF(e.last_seen_d,e.first_seen_d)+1,0),6) AS persistence,
           ROUND((e.st_in/NULLIF(e.nb_in,0))/NULLIF(e.st_out/NULLIF(e.nb_out,0),0),6) AS ramp_recent_vs_prior,
           ROUND((e.st_rec/NULLIF(e.nb_rec,0))/NULLIF(e.stake/NULLIF(e.n_bets,0),0),6) AS ramp_recent_vs_all,
           ROUND((e.st_rec/NULLIF(e.stake,0))/0.30,6) AS stake_ramp,
           -- 六·决策层（HF9f · 详见档头【HF9f 变更说明】；本段两版逐字同一）
           NTILE(5) OVER (ORDER BY e.stake) AS vip_tier,                                                        -- 窗口取值：相对刻度 B 族，全体五等分；须连同下方血统五元组一并解读，禁作硬阈值判型
           PERCENT_RANK() OVER (ORDER BY -e.net-e.rebate-e.agent_cost)    AS economic_value,                    -- 窗口取值：HF9f·F-19 修正 —— HF9e 写作 -(-…) 双负号致方向颠倒（#075 实测 corr(economic_value, residual_b) = -1.0000）；今与 action_priority 排序键归一，值大即平台真净利高
           PERCENT_RANK() OVER (ORDER BY e.net/NULLIF(e.stake,0))         AS roi_pr_global,                     -- 窗口取值：HF9f·F-17 正名 —— 本列实为 ROI（玩家净回报率）之全体百分位，与「风险」无关；旧名 risk_value 见下一行
           PERCENT_RANK() OVER (ORDER BY e.net/NULLIF(e.stake,0))         AS risk_value,                        -- 窗口取值：兼容列，恒等于 roi_pr_global，仅为下游迁移窗保留；HF9g 起废弃，禁新引用
           PERCENT_RANK() OVER (ORDER BY e.stake)                         AS pr_stake,                          -- 窗口取值：兼容列，恒等于 pr_global，原名保留以免断链
           PERCENT_RANK() OVER (ORDER BY e.stake)                         AS pr_global,                         -- 窗口取值：HF9f·F-1 双轨之一 —— 全体口径百分位，参照总体即本件全部输出行
           CASE WHEN e.n_rounds >= 30                                                                           -- 条件分支：起始分支 —— 仅在合格子集内计算合格口径百分位
                  THEN PERCENT_RANK() OVER (PARTITION BY CASE WHEN e.n_rounds >= 30 THEN 1 ELSE 0 END ORDER BY e.stake)  -- 分支取值：以合格与否分区，故本值即 n_rounds>=30 子集内之百分位
                ELSE NULL END                                             AS pr_qualified,                      -- 条件分支：收束上方分支 —— 不合格者留 NULL（NULL＝未测，非 0），产出「pr_qualified」
           'n_rounds>=30'                                                 AS pr_qualified_population,           -- 字面取值：血统 —— 合格子集之定义
           COUNT(*) OVER ()                                               AS pr_global_population_n,            -- 窗口取值：血统 —— 全体口径之参照总体规模，渲染时现算，禁写死
           SUM(CASE WHEN e.n_rounds >= 30 THEN 1 ELSE 0 END) OVER ()      AS pr_qualified_population_n,         -- 窗口取值：血统 —— 合格子集之参照总体规模，现算，禁写死
           'PERCENT_RANK_OVER_ORDER_BY_e_stake'                           AS pr_calculation_method,             -- 字面取值：血统 —— 算法标识
           'HF9f'                                                         AS pr_calculation_version,            -- 字面取值：血统 —— 算法版本
           CASE WHEN e.n_rounds IS NULL OR e.n_rounds < 30 THEN 'THIN_ROUNDS' ELSE 'OK' END AS evidence_flag,   -- 条件分支：HF9f·F-2a 证据旗标 —— THIN_ROUNDS 者禁入执行队列，仅入观察队列
           CASE WHEN e.n_rounds IS NULL       THEN NULL                                                         -- 条件分支：起始分支 —— 未测者留 NULL（自家铁律：NULL ≠ 0）
                WHEN e.n_rounds >= 31483      THEN 'L1_POWERED'                                                 -- 分支判定：MDE 反解第一档
                WHEN e.n_rounds >= 15409      THEN 'L2_CI_1P5'                                                  -- 分支判定：MDE 反解第二档
                WHEN e.n_rounds >=  8668      THEN 'L3_CI_2P0'                                                  -- 分支判定：MDE 反解第三档
                WHEN e.n_rounds >=  3852      THEN 'L4_CI_3P0'                                                  -- 分支判定：MDE 反解第四档
                ELSE 'L5_INSUFFICIENT' END                                AS evidence_rate,                     -- 条件分支：收束上方 —— HF9f·F-3 证据分档，承 HF9e 前议之 MDE 反解五档，须于 F-4 敏感性实验后复核
           ROUND(1.96 * 0.95 / SQRT(NULLIF(CAST(e.n_rounds AS DOUBLE),0)),8) AS hold_ci_halfwidth_approx,       -- 比率表达式：HF9f·F-3 逐行现算之 95% 半宽近似；常数 0.95 为登记值，本轮 #075 实测每局 ROI 隐含 σ 于最薄层为 0.9249，二者差异待 F-4 裁定
           CASE WHEN e.stake IS NULL OR e.stake<=0 OR e.n_bets<30 OR e.n_rounds IS NULL OR e.n_rounds<30 THEN 'Z 证据不足 · 不动作'  -- 条件分支：HF9f·F-2 双条件取严 —— HF9e 仅卡 e.n_bets<30，致 n_bets>=30 而 n_rounds<30 者绕过 Z（#075 实测 18,537 名，其中 8,145 名已入 A/D 待裁）；今两条件并列取严
                WHEN PERCENT_RANK() OVER (ORDER BY -e.net-e.rebate-e.agent_cost)<=0.10                          -- 分支判定：平台真净利之最低十分位
                  THEN 'A 净亏最大十分位 · 优先复核'                                                             -- 分支取值：HF9f·F-20 正名 —— 本档 Σresidual_b 于 #075 实测 = -100,236,896，系平台净亏最大群，旧名「残值最低十分位 · 待裁」名实不符
                WHEN PERCENT_RANK() OVER (ORDER BY -e.net-e.rebate-e.agent_cost)>=0.80                          -- 分支判定：平台真净利之最高二十分位
                  THEN 'D 净利最高二十分位 · 优先留存'                                                           -- 分支取值：HF9f·F-20 正名 —— 本档 Σresidual_b 于 #075 实测 = +281,733,190，系核心利润源；与 A 档方向相反，旧版同标「待裁」属名实不符
                ELSE 'E 常规' END                                          AS action_priority                   -- 条件分支：收束上方判词，产出「action_priority」
    FROM q
    LEFT JOIN x_agg e ON CAST(e.x_key AS STRING) = CAST(q.`entity_id` AS STRING)
  ) y
) z
-- ── 逐批 WHERE 阶梯（★ 口诀：上界 ＝ 下界 ＋ 100000，两数同进）──
--    本件 T_true 未测，无需先跑 T_true；以 0 / 100000 控制本批返回区间，末批由实际行数 < 100000 判定
--    WHERE z.audit_rn >        0 AND z.audit_rn <=   100000   -- 第 1 批
--    WHERE z.audit_rn >   100000 AND z.audit_rn <=   200000   -- 第 2 批
--    WHERE z.audit_rn >   200000 AND z.audit_rn <=   300000   -- 第 3 批
--    WHERE z.audit_rn >   300000 AND z.audit_rn <=   400000   -- 第 4 批
--    WHERE z.audit_rn >   400000 AND z.audit_rn <=   500000   -- 第 5 批
--    WHERE z.audit_rn >   500000 AND z.audit_rn <=   600000   -- 第 6 批
--    WHERE z.audit_rn >   600000 AND z.audit_rn <=   700000   -- 第 7 批
--    …余批类推。第 k 批：WHERE z.audit_rn > (k-1)*100000 AND z.audit_rn <= k*100000
--    某批返回 < 100000 行即为末批，其后不再取。
--
--    ⚠ 常见误写（务必避开）：只推下界而上界不动 ——
--        WHERE z.audit_rn > 100000 AND z.audit_rn <= 100000   ← 自相矛盾，恒为假，返回空集
--        WHERE z.audit_rn > 200000 AND z.audit_rn <= 100000   ← 同上，空集
--      两个数必须**同时**前进，且始终相差 100000。
--      下界 ＝ 上一批之上界；上界 ＝ 本批之上界。
WHERE z.audit_rn > 0 AND z.audit_rn <= 100000 -- ★ HF9c 本批区间
ORDER BY z.audit_rn;


-- ══════════════════════════════════════════════════════════════════════════════════════════════
--  80. S05_member_month_panel.csv   [总包行 2614~2678 · 原 10 列 ＋六层约 60 列]
--     典型学：M15 活跃周期　派生旗标：recent（s.x_rec = 1 · 仅供 CASE 条件聚合，全包无任何 WHERE/AND/HAVING 以此过滤）　连接：q.`member_id`
-- ══════════════════════════════════════════════════════════════════════════════════════════════
-- ── ① 先跑 T_true 留档（不足 100000 者一次导全，不必分批）──
-- ── ① T_true：HF9c 不再强制预跑完整 COUNT。
--    本批实际返回行数 < 100000 即判定为末批；全批完成后以各批 n_rows / audit_rn 范围核对总量。

-- ── ② 分批取数：第 1 批。第 k 批只改末行两数为 (k-1)*100000 与 k*100000 ──
--    审计字段二（REDTEAM 2026-08-24 裁定 · 四锁）：
--      audit_rn  全局观测坐标 —— 由**与原版审计版逐字同一**之排序键所生，两版可逐行对账
--      batch_id  物理分批信息 —— 该行所属批次，由 audit_rn 算得，非引擎所赋
--    ★ 锁三：二者皆为审计字段，**不得进入任何业务指标计算**。
--    ★ 锁四：两版经 audit_rn 逐行字段核验后，方可宣布输出完全一致。

-- ── ③ 每批取回后自证四数（任一不符即停手回报，禁止放行）──
--    n_rows        = COUNT(*)      须等于 COUNT(DISTINCT audit_rn)   （批内无重复）
--    audit_rn_min  = MIN(audit_rn) 须等于 (k-1)*100000 + 1           （与上批严丝合缝）
--    audit_rn_max  = MAX(audit_rn) 须等于 min + n_rows - 1           （批内无缺口）
--    全批取毕再验：各批 audit_rn 之并集 = 1 .. T_true，无缺号、无重号。
--     ★ 首行＝平台真净亏最多者（已扣退水与代理占成）。
--
SELECT z.*,
       CAST(FLOOR((z.audit_rn - 1) / 100000) + 1 AS INT)          AS batch_id,
       'A168_HF9F_20260827_0900' AS run_id,
       '2026-08-27 09:00:00' AS snapshot_sync_time
FROM (
  SELECT y.*,
         ROW_NUMBER() OVER (ORDER BY y.`residual_b` ASC, y.`roi` DESC, y.`member_id`, y.`bet_date`, y.`流水贡献`, y.`游戏输赢贡献`, y.`活跃稳定`, y.`退水支出`, y.`n_ip`, y.`n_chain`, y.`round_key`, y.`risk_label`) AS audit_rn
  FROM (
    WITH
      x_ranked AS (
    SELECT b.bet01, b.bet03, b.bet04, b.bet05, b.bet09, b.bet11, b.bet13,
           b.bet15, b.bet16, b.bet17, b.bet18, b.bet19, b.bet20, b.bet21,
           b.bet22, b.bet23, b.bet24, b.bet25, b.bet26, b.bet27, b.bet38, b.bet39, b.category, b.commission,
           b.dt, b.eid, b.ip, b.validbet, b.updatetime, b.sync_time,
           ROW_NUMBER() OVER (
             PARTITION BY b.bet01
             ORDER BY b.updatetime DESC, b.sync_time DESC, b.dt DESC)      AS x_rn
    FROM ods_mariadb_2b.ods_a168_bet02 b
    WHERE b.dt >= '2026-03-21' AND b.dt < '2026-08-07'
      AND b.bet02 = '101'
      AND b.sync_time <= '2026-08-27 09:00:00'
  ),
    x_testagent AS (
    SELECT age001 AS agent_id FROM ods_mariadb_2b.ods_a168_agent WHERE age022 = '1'
  ),
    x_bs0 AS (
    SELECT b.bet05 AS x_member, b.eid AS x_dealer, b.bet39 AS x_table,
           b.bet03 AS x_shoe, b.ip AS x_ip, b.bet09 AS x_product, b.dt AS x_date,
           CONCAT_WS('|', b.bet03, b.bet04, b.bet39)                      AS x_round,
           CONCAT_WS('|', b.bet39, b.bet03)                               AS x_tblshoe,
           CAST(NULLIF(TRIM(b.bet04),'') AS INT)                          AS x_rno,
           CASE WHEN b.dt >= '2026-07-08' THEN 1 ELSE 0 END               AS x_rec,
           CASE WHEN TRIM(b.commission)='1' THEN 1 ELSE 0 END             AS x_freecomm,
           CAST(NULLIF(TRIM(b.bet13),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_stake,
           CAST(NULLIF(TRIM(b.validbet),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_valid,
           CAST(NULLIF(TRIM(b.bet16),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_rebate,
           CAST(NULLIF(TRIM(b.bet17),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_net,
           CAST(NULLIF(TRIM(b.bet15),'') AS DECIMAL(20,6))                AS x_rbpct,
           COALESCE(CAST(NULLIF(TRIM(b.bet23),'') AS DECIMAL(20,6)),0)   AS x_agpct,
          NULLIF(CAST(NULLIF(TRIM(b.bet23),'') AS DECIMAL(20,6)),0)     AS x_rate1,
          NULLIF(CAST(NULLIF(TRIM(b.bet24),'') AS DECIMAL(20,6)),0)     AS x_rate2,
          NULLIF(CAST(NULLIF(TRIM(b.bet25),'') AS DECIMAL(20,6)),0)     AS x_rate3,
          NULLIF(CAST(NULLIF(TRIM(b.bet26),'') AS DECIMAL(20,6)),0)     AS x_rate4,
          NULLIF(CAST(NULLIF(TRIM(b.bet27),'') AS DECIMAL(20,6)),0)     AS x_rate5,
          (CASE WHEN NULLIF(CAST(NULLIF(TRIM(b.bet22),'') AS BIGINT),0) IS NOT NULL THEN 5
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet21),'') AS BIGINT),0) IS NOT NULL THEN 4
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet20),'') AS BIGINT),0) IS NOT NULL THEN 3
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet19),'') AS BIGINT),0) IS NOT NULL THEN 2
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet18),'') AS BIGINT),0) IS NOT NULL THEN 1
                ELSE 0 END)                                             AS x_chain_depth,
           CASE WHEN COALESCE(t1.agent_id,t2.agent_id,t3.agent_id,
                              t4.agent_id,t5.agent_id) IS NOT NULL
                THEN 1 ELSE 0 END                                        AS f_testline
    FROM x_ranked b
    LEFT JOIN x_testagent t1 ON t1.agent_id = b.bet18
    LEFT JOIN x_testagent t2 ON t2.agent_id = b.bet19
    LEFT JOIN x_testagent t3 ON t3.agent_id = b.bet20
    LEFT JOIN x_testagent t4 ON t4.agent_id = b.bet21
    LEFT JOIN x_testagent t5 ON t5.agent_id = b.bet22
    WHERE b.x_rn = 1
      AND b.category='1' AND UPPER(TRIM(b.bet38))='N'
      AND CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8)) > 0
  ),
  x_mk AS (
    SELECT s.*,
           CASE WHEN s.f_testline = 0 THEN 1 ELSE 0 END                 AS is_clean
    FROM x_bs0 s
  ),
  x_agg AS (
    SELECT s.x_member                                                        AS x_key,
           COUNT(*) AS n_bets, COUNT(DISTINCT s.x_round) AS n_rounds,
           COUNT(DISTINCT s.x_date) AS active_days, COUNT(DISTINCT s.x_tblshoe) AS active_shoes,
           COUNT(DISTINCT CONCAT_WS('|', s.x_date, s.x_table)) AS active_sessions,
           COUNT(DISTINCT s.x_table) AS n_tables, COUNT(DISTINCT s.x_dealer) AS n_dealers,
           COUNT(DISTINCT s.x_ip) AS n_ips, COUNT(DISTINCT s.x_product) AS n_products,
           MIN(s.x_date) AS first_seen_d, MAX(s.x_date) AS last_seen_d,
           SUM(s.x_stake) AS stake, SUM(s.x_valid) AS valid, SUM(s.x_rebate) AS rebate,
           SUM(s.x_net) AS net, SUM(-s.x_net *(100.0-s.x_agpct)/100.0) AS agent_cost,
           AVG(100.0-s.x_agpct)                   AS agent_pct,
           AVG(s.x_agpct)                         AS company_retain_pct,
           SUM(-s.x_net *s.x_agpct/100.0)         AS agent_cost_a_legacy,
           SUM(s.x_valid*s.x_agpct/100.0)         AS agent_cost_valid_base_legacy,
          AVG(COALESCE(s.x_rate1,100)) AS retain_pct_lv1, AVG(COALESCE(s.x_rate2,100)) AS retain_pct_lv2,
          AVG(COALESCE(s.x_rate3,100)) AS retain_pct_lv3, AVG(COALESCE(s.x_rate4,100)) AS retain_pct_lv4,
          AVG(COALESCE(s.x_rate5,100)) AS retain_pct_lv5, AVG(s.x_chain_depth) AS chain_depth_avg,
          AVG(COALESCE(100.0-s.x_rate1,0)) AS agent_pct_lv1, AVG(COALESCE(100.0-s.x_rate2,0)) AS agent_pct_lv2,
          AVG(COALESCE(100.0-s.x_rate3,0)) AS agent_pct_lv3, AVG(COALESCE(100.0-s.x_rate4,0)) AS agent_pct_lv4,
          AVG(COALESCE(100.0-s.x_rate5,0)) AS agent_pct_lv5,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate1,0)/100.0)                        AS agent_cost_lv1,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate2,0)/100.0)                        AS agent_cost_lv2,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate3,0)/100.0)                        AS agent_cost_lv3,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate4,0)/100.0)                        AS agent_cost_lv4,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate5,0)/100.0)                        AS agent_cost_lv5,
          SUM(-s.x_net*(COALESCE(100.0-s.x_rate1,0)+COALESCE(100.0-s.x_rate2,0)
                       +COALESCE(100.0-s.x_rate3,0)+COALESCE(100.0-s.x_rate4,0)
                       +COALESCE(100.0-s.x_rate5,0))/100.0)                   AS agent_cost_chain_additive,
          SUM(-s.x_net*(1.0 - CAST(COALESCE(s.x_rate1,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate2,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate3,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate4,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate5,100) AS DOUBLE)/100.0))
                                                                       AS agent_cost_chain_nested,
           AVG(s.x_rbpct) AS rbpct, AVG(s.x_freecomm*1.0) AS freecomm_rate,
           PERCENTILE_APPROX(s.x_stake,0.25) AS p25, PERCENTILE_APPROX(s.x_stake,0.50) AS p50,
           PERCENTILE_APPROX(s.x_stake,0.75) AS p75, PERCENTILE_APPROX(s.x_stake,0.90) AS p90,
           PERCENTILE_APPROX(s.x_stake,0.95) AS p95, PERCENTILE_APPROX(s.x_stake,0.99) AS p99,
           PERCENTILE_APPROX(s.x_valid,0.50) AS p50_valid,
           PERCENTILE_APPROX(s.x_net,0.50)   AS p50_profit,
           SUM(CASE WHEN s.x_rec = 1 THEN s.x_stake ELSE 0 END) AS st_in,
           SUM(CASE WHEN s.x_rec = 1 THEN 1 ELSE 0 END)         AS nb_in,
           SUM(CASE WHEN s.x_rec = 1 THEN s.x_net ELSE 0 END)   AS net_in,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN s.x_stake ELSE 0 END) AS st_out,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN 1 ELSE 0 END)         AS nb_out,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN s.x_net ELSE 0 END)   AS net_out,
           SUM(CASE WHEN s.x_rec=1 THEN s.x_stake ELSE 0 END) AS st_rec,
           SUM(CASE WHEN s.x_rec=1 THEN 1 ELSE 0 END)         AS nb_rec
    FROM x_mk s
    WHERE s.is_clean = 1
      AND s.x_member IS NOT NULL AND TRIM(CAST(s.x_member AS STRING)) <> ''
    GROUP BY s.x_member
  ),
      q AS (
        WITH ta AS (            -- 公司测试线代理（214 条，跨五级）
          SELECT DISTINCT age001 AS aid                                                                     -- 取列：产出「aid」
          FROM ods_mariadb_2b.ods_a168_agent WHERE age022 = '1'                                             -- 取数来源：取自代理主档（五级代理线归属来源）
        ),                                                                                                  -- 续行：收束上方的子查询或函数括号（交付件 S05_member_month_panel.csv）
        rk AS (                  -- 需求 §3.2：同注单号取最新版本（三级排序去重）
          SELECT b.bet01, b.updatetime, b.sync_time, b.dt, b.bet02,                                         -- 取列：起始取列子句，本行先列 b.bet01, b.updatetime, b.sync_time, b.dt, b.bet02，涉 bet02（游戏类别）、dt（营业日）
                 b.bet03, b.bet04, b.bet05, b.bet08, b.bet09,                                               -- 续行：接续上一取列子句，续列 b.bet03, b.bet04, b.bet05, b.bet08, b.bet09，涉 bet03（靴号）、bet04（局内序号）、bet05（会员号）
                 b.bet11, b.bet13, b.bet14, b.bet16, b.bet17,                                               -- 续行：接续上一取列子句，续列 b.bet11, b.bet13, b.bet14, b.bet16, b.bet17，涉 bet11（汇率）、bet13（下注金额）、bet14（派彩金额）
                 b.bet18, b.bet19, b.bet20, b.bet21, b.bet22,                                               -- 续行：接续上一取列子句，续列 b.bet18, b.bet19, b.bet20, b.bet21, b.bet22，涉 bet18（一级代理线）、bet19（二级代理线）、bet20（三级代理线）
                 b.bet38, b.bet39, b.category, b.eid, b.ip,                                                 -- 续行：接续上一取列子句，续列 b.bet38, b.bet39, b.category, b.eid, b.ip，涉 bet38（重對）、bet39（桌号）、eid（荷官工号）
                 b.validbet,                                                                                -- 续行：接续上一取列子句，续列 b.validbet，涉 validbet（有效投注（洗码量））
                 ROW_NUMBER() OVER (                                                                        -- 行号窗口表达式：以行号窗口取每组头部或去重，免出重复行
                   PARTITION BY b.bet01                                                                     -- 窗口分区：按 b.bet01 分组开窗，组内各自编号或排名
                   ORDER BY b.updatetime DESC, b.sync_time DESC, b.dt DESC) AS rn                           -- 排序：按 b.updatetime（降序）, b.sync_time（降序）, b.dt（降序）) AS rn 排列；导出必带排序，否则分页无稳定序（曾致 36.49% 重复行）
          FROM ods_mariadb_2b.ods_a168_bet02 b                                                              -- 取数来源：取自注单明细表（金额与行为口径的第一料源）
          WHERE b.dt >= '2026-03-21' AND b.dt < '2026-08-07' AND b.bet02 = '101'
      AND b.sync_time <= '2026-08-27 09:00:00'                            -- 过滤条件：限定 b.dt不少于 '2026-03-21'、b.dt小于 '2026-08-07'、b.bet02等于 '101'，涉 bet02（游戏类别）、dt（营业日）
        ),                                                                                                  -- 续行：收束上方的子查询或函数括号（交付件 S05_member_month_panel.csv）
        vd AS (                  -- 有效注单：非测试线、非重对、一般注单
          SELECT r.*                                                                                        -- 取列：整体承接上游结果集的全部字段，不再逐列列举
          FROM rk r                                                                                         -- 取数来源：取自本条自建的中间结果集 rk
          LEFT JOIN ta t1 ON t1.aid = r.bet18                                                               -- 左连接：取自本条自建的中间结果集 ta，连接键为 bet18（一级代理线）
          LEFT JOIN ta t2 ON t2.aid = r.bet19                                                               -- 左连接：取自本条自建的中间结果集 ta，连接键为 bet19（二级代理线）
          LEFT JOIN ta t3 ON t3.aid = r.bet20                                                               -- 左连接：取自本条自建的中间结果集 ta，连接键为 bet20（三级代理线）
          LEFT JOIN ta t4 ON t4.aid = r.bet21                                                               -- 左连接：取自本条自建的中间结果集 ta，连接键为 bet21（四级代理线）
          LEFT JOIN ta t5 ON t5.aid = r.bet22                                                               -- 左连接：取自本条自建的中间结果集 ta，连接键为 bet22（五级代理线）
          WHERE r.rn = 1 AND r.category = '1' AND UPPER(TRIM(r.bet38)) = 'N'                                -- 过滤条件：限定 r.rn等于 1、r.category等于 '1'、UPPER(TRIM(r.bet38))等于 'N'，涉 bet38（重對）
            AND CAST(NULLIF(TRIM(r.bet05),'') AS BIGINT) > 0                                                -- 并列条件：限定 CAST(NULLIF(TRIM(r.bet05),'') AS BIGINT)大于 0，涉 bet05（会员号）
            AND CAST(NULLIF(TRIM(r.bet11),'') AS DECIMAL(20,8)) > 0                                         -- 并列条件：限定 CAST(NULLIF(TRIM(r.bet11),'') AS DECIMAL(20,8))大于 0，涉 bet11（汇率）
            AND NULLIF(TRIM(r.bet08),'') IS NOT NULL                                                        -- 并列条件：限定该值非空，涉 bet08（下注时间）
            AND COALESCE(t1.aid, t2.aid, t3.aid, t4.aid, t5.aid) IS NULL                                    -- 并列条件：限定该值为空——本包以左连接加空值判定替代 EXISTS，因 StarRocks 不支持 EXISTS 配多列 IN
        ),                                                                                                  -- 续行：收束上方的子查询或函数括号（交付件 S05_member_month_panel.csv）
        bs AS (                  -- 金额正名：本金/洗码量/游戏输赢/退水/净输赢（一律÷汇率）
          SELECT v.bet05 AS member_id, v.eid AS dealer_id, v.ip AS bet_ip,                                  -- 取列：起始取列子句，本行先取「bet_ip」，涉 bet05（会员号）、eid（荷官工号）、bet_ip（下注 IP）
                 v.bet18 AS lv1, v.bet19 AS lv2, v.bet20 AS lv3, v.bet21 AS lv4, v.bet22 AS lv5, CONCAT_WS('|', COALESCE(CAST(NULLIF(CAST(NULLIF(TRIM(v.bet18),'') AS BIGINT),0) AS STRING),'-'), COALESCE(CAST(NULLIF(CAST(NULLIF(TRIM(v.bet19),'') AS BIGINT),0) AS STRING),'-'), COALESCE(CAST(NULLIF(CAST(NULLIF(TRIM(v.bet20),'') AS BIGINT),0) AS STRING),'-'), COALESCE(CAST(NULLIF(CAST(NULLIF(TRIM(v.bet21),'') AS BIGINT),0) AS STRING),'-'), COALESCE(CAST(NULLIF(CAST(NULLIF(TRIM(v.bet22),'') AS BIGINT),0) AS STRING),'-')) AS chain_key, v.bet09 AS bet_side, v.dt AS bet_date,                                     -- 取值表达式：取用 bet09（玩法）、bet20（三级代理线）、dt（营业日），产出「bet_date」
                 CONCAT_WS('|', v.bet03, v.bet04, v.bet39) AS round_key,                                    -- 取值表达式：取用 bet03（靴号）、bet04（局内序号）、bet39（桌号），产出「round_key」
                 v.bet39 AS table_id,                                                                       -- 取值表达式：取用 bet39（桌号），产出「table_id」
                 CAST(NULLIF(TRIM(v.bet08),'') AS DATETIME) AS t_bet,                                       -- 取值表达式：先去空白、空串归 NULL，再显式转型——本库字段多为 varchar，不转型即比较失真，产出「t_bet」
                 CAST(NULLIF(TRIM(v.bet13),'') AS DECIMAL(20,4))                                            -- 取值表达式：先去空白、空串归 NULL，再显式转型——本库字段多为 varchar，不转型即比较失真
                   / CAST(NULLIF(TRIM(v.bet11),'') AS DECIMAL(20,8)) AS stake,                              -- 除法或乘法计算：先去空白、空串归 NULL，再显式转型——本库字段多为 varchar，不转型即比较失真，产出「stake」
                 CAST(NULLIF(TRIM(v.validbet),'') AS DECIMAL(20,4))                                         -- 取值表达式：先去空白、空串归 NULL，再显式转型——本库字段多为 varchar，不转型即比较失真
                   / CAST(NULLIF(TRIM(v.bet11),'') AS DECIMAL(20,8)) AS valid_bet,                          -- 除法或乘法计算：先去空白、空串归 NULL，再显式转型——本库字段多为 varchar，不转型即比较失真，产出「valid_bet」
                 (CAST(NULLIF(TRIM(v.bet14),'') AS DECIMAL(20,4))                                           -- 续行：先去空白、空串归 NULL，再显式转型——本库字段多为 varchar，不转型即比较失真
                  - CAST(NULLIF(TRIM(v.bet13),'') AS DECIMAL(20,4)))                                        -- 加减计算：先去空白、空串归 NULL，再显式转型——本库字段多为 varchar，不转型即比较失真
                   / CAST(NULLIF(TRIM(v.bet11),'') AS DECIMAL(20,8)) AS game_pnl,                           -- 除法或乘法计算：先去空白、空串归 NULL，再显式转型——本库字段多为 varchar，不转型即比较失真，产出「game_pnl」
                 CAST(NULLIF(TRIM(v.bet16),'') AS DECIMAL(20,4))                                            -- 取值表达式：先去空白、空串归 NULL，再显式转型——本库字段多为 varchar，不转型即比较失真
                   / CAST(NULLIF(TRIM(v.bet11),'') AS DECIMAL(20,8)) AS rebate,                             -- 除法或乘法计算：先去空白、空串归 NULL，再显式转型——本库字段多为 varchar，不转型即比较失真，产出「rebate」
                 CAST(NULLIF(TRIM(v.bet17),'') AS DECIMAL(20,4))                                            -- 取值表达式：先去空白、空串归 NULL，再显式转型——本库字段多为 varchar，不转型即比较失真
                   / CAST(NULLIF(TRIM(v.bet11),'') AS DECIMAL(20,8)) AS net_pnl                             -- 除法或乘法计算：先去空白、空串归 NULL，再显式转型——本库字段多为 varchar，不转型即比较失真，产出「net_pnl」
          FROM vd v                                                                                         -- 取数来源：取自本条自建的中间结果集 vd
        ),                                                                                                  -- 续行：收束上方的子查询或函数括号（交付件 S05_member_month_panel.csv）
        lab AS (SELECT bet05 AS member_id, DATE_TRUNC('month', dt) AS ym,                                   -- 取值表达式：取用 bet05（会员号）、dt（营业日）、member_id（会员号），产出「ym」
                       MAX(CASE WHEN risk='1' THEN 1 ELSE 0 END) AS risk_label                              -- 取最大值表达式：产出「risk_label」
                FROM ods_mariadb_2b.ods_a168_dailyreport_member                                             -- 取数来源：取自会员日结报表（日粒度业绩与风控标记）
                GROUP BY bet05, DATE_TRUNC('month', dt))                                                    -- 分组：按 bet05, DATE_TRUNC('month', dt)) 汇总
        SELECT b.member_id, DATE_TRUNC('month', b.bet_date) AS bet_date,                                    -- 取列：起始取列子句，本行先取「bet_date」，涉 member_id（会员号）、bet_date（营业日）
          SUM(b.valid_bet) AS 流水贡献, -SUM(b.game_pnl) AS 游戏输赢贡献,                                             -- 汇总表达式：汇总后取负号——会员净输赢取负即平台毛利（GGR），产出「游戏输赢贡献」
          COUNT(DISTINCT b.bet_date) AS 活跃稳定, SUM(b.rebate) AS 退水支出,                                        -- 计数表达式：统计去重个数，产出「退水支出」
          COUNT(DISTINCT b.bet_ip) AS n_ip, COUNT(DISTINCT b.lv3) AS n_chain,                               -- 计数表达式：统计去重个数，产出「n_chain」
          MAX(b.lv1) AS lv1_id, MAX(b.lv2) AS lv2_id, MAX(b.lv3) AS lv3_id,
          MAX(b.lv4) AS lv4_id, MAX(b.lv5) AS lv5_id, MAX(b.chain_key) AS chain_key,
          COUNT(DISTINCT b.chain_key) AS n_chain_key,
          CASE WHEN COUNT(DISTINCT b.chain_key)>1 THEN 1 ELSE 0 END AS f_upline_changed,
          MIN(b.round_key) AS round_key,                                                                    -- 取最小值表达式：取用 round_key（局键），产出「round_key」
          COALESCE(MAX(l.risk_label),0) AS risk_label                                                       -- 取值表达式：取最大值，产出「risk_label」
        FROM bs b LEFT JOIN lab l                                                                           -- 取数来源：取自本条自建的中间结果集 bs
          ON l.member_id=b.member_id AND l.ym=DATE_TRUNC('month', b.bet_date)                               -- 连接键：限定 l.member_id等于 b.member_id，涉 member_id（会员号）、bet_date（营业日）
        GROUP BY b.member_id, DATE_TRUNC('month', b.bet_date)                                               -- 分组：按 b.member_id, DATE_TRUNC('month', b.bet_date) 汇总
        HAVING COUNT(*) >= 30                                                                               -- 分组后过滤：限定行数不少于 30
      )
    SELECT q.*,
           -- 一·经济层
           ROUND(e.stake,4) AS stake, ROUND(e.valid,4) AS valid_bet,
           ROUND(-e.net,4) AS profit, e.n_bets, e.n_rounds,
           ROUND(e.net/NULLIF(e.stake,0),8) AS roi,
           ROUND(e.net_in/NULLIF(e.st_in,0),8) AS roi_recent,
           ROUND(e.net_out/NULLIF(e.st_out,0),8) AS roi_non_recent,
           ROUND((e.net-e.rebate)/NULLIF(e.stake,0),8) AS roi_ex_rebate,
           ROUND(e.net,4) AS roi_numerator, ROUND(e.stake,4) AS roi_denominator,
           CASE WHEN e.stake IS NULL THEN 'NULL_DENOM' WHEN e.stake<=0 THEN 'ZERO_DENOM'
                WHEN e.n_bets<30 THEN 'THIN_EXPOSURE' ELSE 'OK' END AS roi_denominator_status,
           ROUND(e.rebate,4) AS rebate_cost, ROUND(e.agent_cost,4)                           AS cost_complement_b,
       ROUND(e.agent_pct,4)                            AS pct_complement,
       ROUND(e.company_retain_pct,4)                   AS pct_top_bet23,
       'AG03-UNRESOLVED'                                     AS agent_formula_version,
      'ALL5_LEVELS_bet23_to_bet27'                    AS agent_level_scope,
      ROUND(e.agent_cost_lv1,4) AS agent_cost_lv1, ROUND(e.agent_cost_lv2,4) AS agent_cost_lv2,
      ROUND(e.agent_cost_lv3,4) AS agent_cost_lv3, ROUND(e.agent_cost_lv4,4) AS agent_cost_lv4,
      ROUND(e.agent_cost_lv5,4) AS agent_cost_lv5,
      ROUND(e.agent_pct_lv1,6) AS agent_pct_lv1, ROUND(e.agent_pct_lv2,6) AS agent_pct_lv2,
      ROUND(e.agent_pct_lv3,6) AS agent_pct_lv3, ROUND(e.agent_pct_lv4,6) AS agent_pct_lv4,
      ROUND(e.agent_pct_lv5,6) AS agent_pct_lv5,
      ROUND(e.retain_pct_lv1,6) AS retain_pct_lv1, ROUND(e.retain_pct_lv2,6) AS retain_pct_lv2,
      ROUND(e.retain_pct_lv3,6) AS retain_pct_lv3, ROUND(e.retain_pct_lv4,6) AS retain_pct_lv4,
      ROUND(e.retain_pct_lv5,6) AS retain_pct_lv5, ROUND(e.chain_depth_avg,4) AS chain_depth_avg,
      ROUND(e.agent_cost_chain_additive,4)            AS agent_cost_chain_additive,
      ROUND(e.agent_cost_chain_nested,4)              AS agent_cost_chain_nested,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_additive,4) AS residual_chain_additive,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_nested,4)   AS residual_chain_nested,
      'PENDING_AG03'                                  AS decision_status,
      'FALSE'                                         AS admit_to_risk_decision,
      'NOT_FOR_ENFORCEMENT'                           AS deliverable_class,
       ROUND(e.agent_cost_a_legacy,4)                  AS agent_cost_a_legacy,
       ROUND(e.agent_cost_valid_base_legacy,4)         AS agent_cost_valid_base_legacy,
           ROUND(-e.net-e.rebate,4)                        AS ngr,
       ROUND(-e.net-e.rebate-e.agent_cost,4)           AS residual_b,
       ROUND(-e.net-e.rebate-e.agent_cost_a_legacy,4)  AS residual_a,
           ROUND((-e.net-e.rebate)/NULLIF(e.stake,0),8)    AS ngr_rate,
       ROUND((-e.net-e.rebate-e.agent_cost)/NULLIF(e.stake,0),8)   AS residual_b_rate,
      -- 【HF9c · canonical accounting contract】
      --   以下 canonical 字段只增加明确 scope；不删除、不覆盖既有字段。
      --   formal_bet23_* 保持 HF9b 当前生产公式及其 NULL/0 语义；
      --   lv1~lv5 / additive / nested 则分别采用各自原始 e.* 成本字段，
      --   rate 一律从未舍入的 e.* 分子 / e.stake 计算，禁止由展示值反算。
      ROUND(e.agent_cost,4) AS agent_cost_bet23_formal_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost,4) AS net_margin_bet23_formal_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost)/NULLIF(e.stake,0),8) AS net_margin_bet23_formal_rate_canonical,
      ROUND(e.agent_cost_lv1,4) AS agent_cost_lv1_bet23_canonical,
      ROUND(e.agent_cost_lv2,4) AS agent_cost_lv2_bet24_canonical,
      ROUND(e.agent_cost_lv3,4) AS agent_cost_lv3_bet25_canonical,
      ROUND(e.agent_cost_lv4,4) AS agent_cost_lv4_bet26_canonical,
      ROUND(e.agent_cost_lv5,4) AS agent_cost_lv5_bet27_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_lv1,4) AS net_margin_lv1_bet23_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_lv1)/NULLIF(e.stake,0),8) AS net_margin_lv1_bet23_rate_canonical,
      ROUND(e.agent_cost_chain_additive,4) AS agent_cost_chain_additive_canonical,
      ROUND(e.agent_cost_chain_nested,4) AS agent_cost_chain_nested_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_additive,4) AS net_margin_chain_additive_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_nested,4) AS net_margin_chain_nested_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_chain_additive)/NULLIF(e.stake,0),8) AS net_margin_chain_additive_rate_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_chain_nested)/NULLIF(e.stake,0),8) AS net_margin_chain_nested_rate_canonical,
       ROUND((-e.net-e.rebate-e.agent_cost_a_legacy)/NULLIF(e.stake,0),8) AS residual_a_rate,
           -- 二·分布层
           ROUND(e.stake/NULLIF(e.n_bets,0),4) AS avg_stake_per_bet,
           ROUND(e.valid/NULLIF(e.n_rounds,0),4) AS avg_valid_bet_per_round,
           ROUND(-e.net/NULLIF(e.n_rounds,0),4) AS avg_profit_per_round,
           ROUND(-e.net/NULLIF(e.active_days,0),4) AS avg_profit_per_day,
           ROUND(-e.net/NULLIF(e.active_shoes,0),4) AS avg_profit_per_shoe,
           ROUND(e.stake/NULLIF(e.active_days,0),4) AS avg_stake_per_active_day,
           ROUND(e.n_rounds*1.0/NULLIF(e.active_days,0),4) AS avg_rounds_per_active_day,
           ROUND(e.st_in/NULLIF(e.nb_in,0),4) AS avg_stake_recent,
           ROUND(e.st_out/NULLIF(e.nb_out,0),4) AS avg_stake_non_recent,
           ROUND(e.p25,4) AS p25_stake, ROUND(e.p50,4) AS p50_stake, ROUND(e.p75,4) AS p75_stake,
           ROUND(e.p90,4) AS p90_stake, ROUND(e.p95,4) AS p95_stake, ROUND(e.p99,4) AS p99_stake,
           ROUND(e.p50_valid,4) AS p50_valid_bet, ROUND(e.p50_profit,4) AS p50_profit,
           ROUND(e.p95/NULLIF(e.p50,0),6) AS p95_over_p50,
           ROUND(e.p99/NULLIF(e.p50,0),6) AS p99_over_p50,
           ROUND((e.stake/NULLIF(e.n_bets,0))/NULLIF(e.p50,0),6) AS avg_over_p50,
           -- 三·关系层
           e.n_tables AS common_table_count, e.n_dealers AS common_dealer_count,
           e.n_ips AS common_ip_count, e.n_products AS common_product_count,
           ROUND(e.st_in/NULLIF(e.stake,0),8) AS share_recent,
           -- 四·rate 层
           ROUND(-e.net/NULLIF(e.stake,0),8) AS hold_rate,
           ROUND(-e.net_in/NULLIF(e.st_in,0),8) AS hold_rate_recent,
           ROUND(e.rebate/NULLIF(e.valid,0),8) AS rebate_rate_actual,
           ROUND(e.rbpct,6) AS rebate_pct_config,
           ROUND(e.valid/NULLIF(e.stake,0),6) AS turnover_multiple,
           ROUND(e.freecomm_rate,6) AS free_comm_rate,
           ROUND(e.net_in/NULLIF(e.st_in,0)-e.net_out/NULLIF(e.st_out,0),8) AS roi_delta_recent,
           -- 五·动态层
           e.first_seen_d AS first_seen, e.last_seen_d AS last_seen,
           e.active_days, e.active_shoes, e.active_sessions,
           DATEDIFF(e.last_seen_d, e.first_seen_d)+1 AS span_days,
           ROUND(e.active_days*1.0/NULLIF(DATEDIFF(e.last_seen_d,e.first_seen_d)+1,0),6) AS persistence,
           ROUND((e.st_in/NULLIF(e.nb_in,0))/NULLIF(e.st_out/NULLIF(e.nb_out,0),0),6) AS ramp_recent_vs_prior,
           ROUND((e.st_rec/NULLIF(e.nb_rec,0))/NULLIF(e.stake/NULLIF(e.n_bets,0),0),6) AS ramp_recent_vs_all,
           ROUND((e.st_rec/NULLIF(e.stake,0))/0.30,6) AS stake_ramp,
           -- 六·决策层（HF9f · 详见档头【HF9f 变更说明】；本段两版逐字同一）
           NTILE(5) OVER (ORDER BY e.stake) AS vip_tier,                                                        -- 窗口取值：相对刻度 B 族，全体五等分；须连同下方血统五元组一并解读，禁作硬阈值判型
           PERCENT_RANK() OVER (ORDER BY -e.net-e.rebate-e.agent_cost)    AS economic_value,                    -- 窗口取值：HF9f·F-19 修正 —— HF9e 写作 -(-…) 双负号致方向颠倒（#075 实测 corr(economic_value, residual_b) = -1.0000）；今与 action_priority 排序键归一，值大即平台真净利高
           PERCENT_RANK() OVER (ORDER BY e.net/NULLIF(e.stake,0))         AS roi_pr_global,                     -- 窗口取值：HF9f·F-17 正名 —— 本列实为 ROI（玩家净回报率）之全体百分位，与「风险」无关；旧名 risk_value 见下一行
           PERCENT_RANK() OVER (ORDER BY e.net/NULLIF(e.stake,0))         AS risk_value,                        -- 窗口取值：兼容列，恒等于 roi_pr_global，仅为下游迁移窗保留；HF9g 起废弃，禁新引用
           PERCENT_RANK() OVER (ORDER BY e.stake)                         AS pr_stake,                          -- 窗口取值：兼容列，恒等于 pr_global，原名保留以免断链
           PERCENT_RANK() OVER (ORDER BY e.stake)                         AS pr_global,                         -- 窗口取值：HF9f·F-1 双轨之一 —— 全体口径百分位，参照总体即本件全部输出行
           CASE WHEN e.n_rounds >= 30                                                                           -- 条件分支：起始分支 —— 仅在合格子集内计算合格口径百分位
                  THEN PERCENT_RANK() OVER (PARTITION BY CASE WHEN e.n_rounds >= 30 THEN 1 ELSE 0 END ORDER BY e.stake)  -- 分支取值：以合格与否分区，故本值即 n_rounds>=30 子集内之百分位
                ELSE NULL END                                             AS pr_qualified,                      -- 条件分支：收束上方分支 —— 不合格者留 NULL（NULL＝未测，非 0），产出「pr_qualified」
           'n_rounds>=30'                                                 AS pr_qualified_population,           -- 字面取值：血统 —— 合格子集之定义
           COUNT(*) OVER ()                                               AS pr_global_population_n,            -- 窗口取值：血统 —— 全体口径之参照总体规模，渲染时现算，禁写死
           SUM(CASE WHEN e.n_rounds >= 30 THEN 1 ELSE 0 END) OVER ()      AS pr_qualified_population_n,         -- 窗口取值：血统 —— 合格子集之参照总体规模，现算，禁写死
           'PERCENT_RANK_OVER_ORDER_BY_e_stake'                           AS pr_calculation_method,             -- 字面取值：血统 —— 算法标识
           'HF9f'                                                         AS pr_calculation_version,            -- 字面取值：血统 —— 算法版本
           CASE WHEN e.n_rounds IS NULL OR e.n_rounds < 30 THEN 'THIN_ROUNDS' ELSE 'OK' END AS evidence_flag,   -- 条件分支：HF9f·F-2a 证据旗标 —— THIN_ROUNDS 者禁入执行队列，仅入观察队列
           CASE WHEN e.n_rounds IS NULL       THEN NULL                                                         -- 条件分支：起始分支 —— 未测者留 NULL（自家铁律：NULL ≠ 0）
                WHEN e.n_rounds >= 31483      THEN 'L1_POWERED'                                                 -- 分支判定：MDE 反解第一档
                WHEN e.n_rounds >= 15409      THEN 'L2_CI_1P5'                                                  -- 分支判定：MDE 反解第二档
                WHEN e.n_rounds >=  8668      THEN 'L3_CI_2P0'                                                  -- 分支判定：MDE 反解第三档
                WHEN e.n_rounds >=  3852      THEN 'L4_CI_3P0'                                                  -- 分支判定：MDE 反解第四档
                ELSE 'L5_INSUFFICIENT' END                                AS evidence_rate,                     -- 条件分支：收束上方 —— HF9f·F-3 证据分档，承 HF9e 前议之 MDE 反解五档，须于 F-4 敏感性实验后复核
           ROUND(1.96 * 0.95 / SQRT(NULLIF(CAST(e.n_rounds AS DOUBLE),0)),8) AS hold_ci_halfwidth_approx,       -- 比率表达式：HF9f·F-3 逐行现算之 95% 半宽近似；常数 0.95 为登记值，本轮 #075 实测每局 ROI 隐含 σ 于最薄层为 0.9249，二者差异待 F-4 裁定
           CASE WHEN e.stake IS NULL OR e.stake<=0 OR e.n_bets<30 OR e.n_rounds IS NULL OR e.n_rounds<30 THEN 'Z 证据不足 · 不动作'  -- 条件分支：HF9f·F-2 双条件取严 —— HF9e 仅卡 e.n_bets<30，致 n_bets>=30 而 n_rounds<30 者绕过 Z（#075 实测 18,537 名，其中 8,145 名已入 A/D 待裁）；今两条件并列取严
                WHEN PERCENT_RANK() OVER (ORDER BY -e.net-e.rebate-e.agent_cost)<=0.10                          -- 分支判定：平台真净利之最低十分位
                  THEN 'A 净亏最大十分位 · 优先复核'                                                             -- 分支取值：HF9f·F-20 正名 —— 本档 Σresidual_b 于 #075 实测 = -100,236,896，系平台净亏最大群，旧名「残值最低十分位 · 待裁」名实不符
                WHEN PERCENT_RANK() OVER (ORDER BY -e.net-e.rebate-e.agent_cost)>=0.80                          -- 分支判定：平台真净利之最高二十分位
                  THEN 'D 净利最高二十分位 · 优先留存'                                                           -- 分支取值：HF9f·F-20 正名 —— 本档 Σresidual_b 于 #075 实测 = +281,733,190，系核心利润源；与 A 档方向相反，旧版同标「待裁」属名实不符
                ELSE 'E 常规' END                                          AS action_priority                   -- 条件分支：收束上方判词，产出「action_priority」
    FROM q
    LEFT JOIN x_agg e ON CAST(e.x_key AS STRING) = CAST(q.`member_id` AS STRING)
  ) y
) z
-- ── 逐批 WHERE 阶梯（★ 口诀：上界 ＝ 下界 ＋ 100000，两数同进）──
--    本件 T_true 未测，无需先跑 T_true；以 0 / 100000 控制本批返回区间，末批由实际行数 < 100000 判定
--    WHERE z.audit_rn >        0 AND z.audit_rn <=   100000   -- 第 1 批
--    WHERE z.audit_rn >   100000 AND z.audit_rn <=   200000   -- 第 2 批
--    WHERE z.audit_rn >   200000 AND z.audit_rn <=   300000   -- 第 3 批
--    WHERE z.audit_rn >   300000 AND z.audit_rn <=   400000   -- 第 4 批
--    WHERE z.audit_rn >   400000 AND z.audit_rn <=   500000   -- 第 5 批
--    WHERE z.audit_rn >   500000 AND z.audit_rn <=   600000   -- 第 6 批
--    WHERE z.audit_rn >   600000 AND z.audit_rn <=   700000   -- 第 7 批
--    …余批类推。第 k 批：WHERE z.audit_rn > (k-1)*100000 AND z.audit_rn <= k*100000
--    某批返回 < 100000 行即为末批，其后不再取。
--
--    ⚠ 常见误写（务必避开）：只推下界而上界不动 ——
--        WHERE z.audit_rn > 100000 AND z.audit_rn <= 100000   ← 自相矛盾，恒为假，返回空集
--        WHERE z.audit_rn > 200000 AND z.audit_rn <= 100000   ← 同上，空集
--      两个数必须**同时**前进，且始终相差 100000。
--      下界 ＝ 上一批之上界；上界 ＝ 本批之上界。
WHERE z.audit_rn > 0 AND z.audit_rn <= 100000 -- ★ HF9c 本批区间
ORDER BY z.audit_rn;


-- ══════════════════════════════════════════════════════════════════════════════════════════════
--  81. S_player_tail.csv   [总包行 2077~2189 · 原 18 列 ＋六层约 60 列]
--     典型学：M15 活跃周期　派生旗标：recent（s.x_rec = 1 · 仅供 CASE 条件聚合，全包无任何 WHERE/AND/HAVING 以此过滤）　连接：q.`member_id`
-- ══════════════════════════════════════════════════════════════════════════════════════════════
-- ── ① 先跑 T_true 留档（不足 100000 者一次导全，不必分批）──
-- ── ① T_true：HF9c 不再强制预跑完整 COUNT。
--    本批实际返回行数 < 100000 即判定为末批；全批完成后以各批 n_rows / audit_rn 范围核对总量。

-- ── ② 分批取数：第 1 批。第 k 批只改末行两数为 (k-1)*100000 与 k*100000 ──
--    审计字段二（REDTEAM 2026-08-24 裁定 · 四锁）：
--      audit_rn  全局观测坐标 —— 由**与原版审计版逐字同一**之排序键所生，两版可逐行对账
--      batch_id  物理分批信息 —— 该行所属批次，由 audit_rn 算得，非引擎所赋
--    ★ 锁三：二者皆为审计字段，**不得进入任何业务指标计算**。
--    ★ 锁四：两版经 audit_rn 逐行字段核验后，方可宣布输出完全一致。

-- ── ③ 每批取回后自证四数（任一不符即停手回报，禁止放行）──
--    n_rows        = COUNT(*)      须等于 COUNT(DISTINCT audit_rn)   （批内无重复）
--    audit_rn_min  = MIN(audit_rn) 须等于 (k-1)*100000 + 1           （与上批严丝合缝）
--    audit_rn_max  = MAX(audit_rn) 须等于 min + n_rows - 1           （批内无缺口）
--    全批取毕再验：各批 audit_rn 之并集 = 1 .. T_true，无缺号、无重号。
--     ★ 首行＝平台真净亏最多者（已扣退水与代理占成）。
--
SELECT z.*,
       CAST(FLOOR((z.audit_rn - 1) / 100000) + 1 AS INT)          AS batch_id,
       'A168_HF9F_20260827_0900' AS run_id,
       '2026-08-27 09:00:00' AS snapshot_sync_time
FROM (
  SELECT y.*,
         ROW_NUMBER() OVER (ORDER BY y.`residual_b` ASC, y.`roi` DESC, y.`member_id`, y.`n_rounds_all`, y.`n_rounds_tail`, y.`tail_share`, y.`tail_win`, y.`tail_lose`, y.`tail_winrate`, y.`norm_winrate`, y.`winrate_diff`, y.`tail_stake`, y.`tail_valid_bet`, y.`tail_game_pnl`, y.`tail_rebate`, y.`tail_net_pnl`, y.`tail_roi`, y.`norm_game_pnl`, y.`norm_roi`, y.`tail_profit_share`) AS audit_rn
  FROM (
    WITH
      x_ranked AS (
    SELECT b.bet01, b.bet03, b.bet04, b.bet05, b.bet09, b.bet11, b.bet13,
           b.bet15, b.bet16, b.bet17, b.bet18, b.bet19, b.bet20, b.bet21,
           b.bet22, b.bet23, b.bet24, b.bet25, b.bet26, b.bet27, b.bet38, b.bet39, b.category, b.commission,
           b.dt, b.eid, b.ip, b.validbet, b.updatetime, b.sync_time,
           ROW_NUMBER() OVER (
             PARTITION BY b.bet01
             ORDER BY b.updatetime DESC, b.sync_time DESC, b.dt DESC)      AS x_rn
    FROM ods_mariadb_2b.ods_a168_bet02 b
    WHERE b.dt >= '2026-03-21' AND b.dt < '2026-08-07'
      AND b.bet02 = '101'
      AND b.sync_time <= '2026-08-27 09:00:00'
  ),
    x_testagent AS (
    SELECT age001 AS agent_id FROM ods_mariadb_2b.ods_a168_agent WHERE age022 = '1'
  ),
    x_bs0 AS (
    SELECT b.bet05 AS x_member, b.eid AS x_dealer, b.bet39 AS x_table,
           b.bet03 AS x_shoe, b.ip AS x_ip, b.bet09 AS x_product, b.dt AS x_date,
           CONCAT_WS('|', b.bet03, b.bet04, b.bet39)                      AS x_round,
           CONCAT_WS('|', b.bet39, b.bet03)                               AS x_tblshoe,
           CAST(NULLIF(TRIM(b.bet04),'') AS INT)                          AS x_rno,
           CASE WHEN b.dt >= '2026-07-08' THEN 1 ELSE 0 END               AS x_rec,
           CASE WHEN TRIM(b.commission)='1' THEN 1 ELSE 0 END             AS x_freecomm,
           CAST(NULLIF(TRIM(b.bet13),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_stake,
           CAST(NULLIF(TRIM(b.validbet),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_valid,
           CAST(NULLIF(TRIM(b.bet16),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_rebate,
           CAST(NULLIF(TRIM(b.bet17),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_net,
           CAST(NULLIF(TRIM(b.bet15),'') AS DECIMAL(20,6))                AS x_rbpct,
           COALESCE(CAST(NULLIF(TRIM(b.bet23),'') AS DECIMAL(20,6)),0)   AS x_agpct,
          NULLIF(CAST(NULLIF(TRIM(b.bet23),'') AS DECIMAL(20,6)),0)     AS x_rate1,
          NULLIF(CAST(NULLIF(TRIM(b.bet24),'') AS DECIMAL(20,6)),0)     AS x_rate2,
          NULLIF(CAST(NULLIF(TRIM(b.bet25),'') AS DECIMAL(20,6)),0)     AS x_rate3,
          NULLIF(CAST(NULLIF(TRIM(b.bet26),'') AS DECIMAL(20,6)),0)     AS x_rate4,
          NULLIF(CAST(NULLIF(TRIM(b.bet27),'') AS DECIMAL(20,6)),0)     AS x_rate5,
          (CASE WHEN NULLIF(CAST(NULLIF(TRIM(b.bet22),'') AS BIGINT),0) IS NOT NULL THEN 5
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet21),'') AS BIGINT),0) IS NOT NULL THEN 4
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet20),'') AS BIGINT),0) IS NOT NULL THEN 3
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet19),'') AS BIGINT),0) IS NOT NULL THEN 2
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet18),'') AS BIGINT),0) IS NOT NULL THEN 1
                ELSE 0 END)                                             AS x_chain_depth,
           CASE WHEN COALESCE(t1.agent_id,t2.agent_id,t3.agent_id,
                              t4.agent_id,t5.agent_id) IS NOT NULL
                THEN 1 ELSE 0 END                                        AS f_testline
    FROM x_ranked b
    LEFT JOIN x_testagent t1 ON t1.agent_id = b.bet18
    LEFT JOIN x_testagent t2 ON t2.agent_id = b.bet19
    LEFT JOIN x_testagent t3 ON t3.agent_id = b.bet20
    LEFT JOIN x_testagent t4 ON t4.agent_id = b.bet21
    LEFT JOIN x_testagent t5 ON t5.agent_id = b.bet22
    WHERE b.x_rn = 1
      AND b.category='1' AND UPPER(TRIM(b.bet38))='N'
      AND CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8)) > 0
  ),
  x_mk AS (
    SELECT s.*,
           CASE WHEN s.f_testline = 0 THEN 1 ELSE 0 END                 AS is_clean
    FROM x_bs0 s
  ),
  x_agg AS (
    SELECT s.x_member                                                        AS x_key,
           COUNT(*) AS n_bets, COUNT(DISTINCT s.x_round) AS n_rounds,
           COUNT(DISTINCT s.x_date) AS active_days, COUNT(DISTINCT s.x_tblshoe) AS active_shoes,
           COUNT(DISTINCT CONCAT_WS('|', s.x_date, s.x_table)) AS active_sessions,
           COUNT(DISTINCT s.x_table) AS n_tables, COUNT(DISTINCT s.x_dealer) AS n_dealers,
           COUNT(DISTINCT s.x_ip) AS n_ips, COUNT(DISTINCT s.x_product) AS n_products,
           MIN(s.x_date) AS first_seen_d, MAX(s.x_date) AS last_seen_d,
           SUM(s.x_stake) AS stake, SUM(s.x_valid) AS valid, SUM(s.x_rebate) AS rebate,
           SUM(s.x_net) AS net, SUM(-s.x_net *(100.0-s.x_agpct)/100.0) AS agent_cost,
           AVG(100.0-s.x_agpct)                   AS agent_pct,
           AVG(s.x_agpct)                         AS company_retain_pct,
           SUM(-s.x_net *s.x_agpct/100.0)         AS agent_cost_a_legacy,
           SUM(s.x_valid*s.x_agpct/100.0)         AS agent_cost_valid_base_legacy,
          AVG(COALESCE(s.x_rate1,100)) AS retain_pct_lv1, AVG(COALESCE(s.x_rate2,100)) AS retain_pct_lv2,
          AVG(COALESCE(s.x_rate3,100)) AS retain_pct_lv3, AVG(COALESCE(s.x_rate4,100)) AS retain_pct_lv4,
          AVG(COALESCE(s.x_rate5,100)) AS retain_pct_lv5, AVG(s.x_chain_depth) AS chain_depth_avg,
          AVG(COALESCE(100.0-s.x_rate1,0)) AS agent_pct_lv1, AVG(COALESCE(100.0-s.x_rate2,0)) AS agent_pct_lv2,
          AVG(COALESCE(100.0-s.x_rate3,0)) AS agent_pct_lv3, AVG(COALESCE(100.0-s.x_rate4,0)) AS agent_pct_lv4,
          AVG(COALESCE(100.0-s.x_rate5,0)) AS agent_pct_lv5,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate1,0)/100.0)                        AS agent_cost_lv1,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate2,0)/100.0)                        AS agent_cost_lv2,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate3,0)/100.0)                        AS agent_cost_lv3,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate4,0)/100.0)                        AS agent_cost_lv4,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate5,0)/100.0)                        AS agent_cost_lv5,
          SUM(-s.x_net*(COALESCE(100.0-s.x_rate1,0)+COALESCE(100.0-s.x_rate2,0)
                       +COALESCE(100.0-s.x_rate3,0)+COALESCE(100.0-s.x_rate4,0)
                       +COALESCE(100.0-s.x_rate5,0))/100.0)                   AS agent_cost_chain_additive,
          SUM(-s.x_net*(1.0 - CAST(COALESCE(s.x_rate1,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate2,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate3,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate4,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate5,100) AS DOUBLE)/100.0))
                                                                       AS agent_cost_chain_nested,
           AVG(s.x_rbpct) AS rbpct, AVG(s.x_freecomm*1.0) AS freecomm_rate,
           PERCENTILE_APPROX(s.x_stake,0.25) AS p25, PERCENTILE_APPROX(s.x_stake,0.50) AS p50,
           PERCENTILE_APPROX(s.x_stake,0.75) AS p75, PERCENTILE_APPROX(s.x_stake,0.90) AS p90,
           PERCENTILE_APPROX(s.x_stake,0.95) AS p95, PERCENTILE_APPROX(s.x_stake,0.99) AS p99,
           PERCENTILE_APPROX(s.x_valid,0.50) AS p50_valid,
           PERCENTILE_APPROX(s.x_net,0.50)   AS p50_profit,
           SUM(CASE WHEN s.x_rec = 1 THEN s.x_stake ELSE 0 END) AS st_in,
           SUM(CASE WHEN s.x_rec = 1 THEN 1 ELSE 0 END)         AS nb_in,
           SUM(CASE WHEN s.x_rec = 1 THEN s.x_net ELSE 0 END)   AS net_in,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN s.x_stake ELSE 0 END) AS st_out,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN 1 ELSE 0 END)         AS nb_out,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN s.x_net ELSE 0 END)   AS net_out,
           SUM(CASE WHEN s.x_rec=1 THEN s.x_stake ELSE 0 END) AS st_rec,
           SUM(CASE WHEN s.x_rec=1 THEN 1 ELSE 0 END)         AS nb_rec
    FROM x_mk s
    WHERE s.is_clean = 1
      AND s.x_member IS NOT NULL AND TRIM(CAST(s.x_member AS STRING)) <> ''
    GROUP BY s.x_member
  ),
      q AS (
        WITH ta AS (                                                                                        -- 公共表表达式：开启中间结果集 ta，其后各行为其定义体（交付件 S_player_tail.csv）
          SELECT DISTINCT age001 AS aid                                                                     -- 取列：产出「aid」
          FROM ods_mariadb_2b.ods_a168_agent WHERE age022 = '1'                                             -- 取数来源：取自代理主档（五级代理线归属来源）
        ),                                                                                                  -- 续行：收束上方的子查询或函数括号（交付件 S_player_tail.csv）
        rk AS (                                                                                             -- 公共表表达式：开启中间结果集 rk，其后各行为其定义体（交付件 S_player_tail.csv）
          SELECT b.bet01, b.updatetime, b.sync_time, b.dt, b.bet02,                                         -- 取列：起始取列子句，本行先列 b.bet01, b.updatetime, b.sync_time, b.dt, b.bet02，涉 bet02（游戏类别）、dt（营业日）
                 b.bet03, b.bet04, b.bet05, b.bet08, b.bet11,                                               -- 续行：接续上一取列子句，续列 b.bet03, b.bet04, b.bet05, b.bet08, b.bet11，涉 bet03（靴号）、bet04（局内序号）、bet05（会员号）
                 b.bet13, b.bet14, b.bet16, b.bet17, b.bet18,                                               -- 续行：接续上一取列子句，续列 b.bet13, b.bet14, b.bet16, b.bet17, b.bet18，涉 bet13（下注金额）、bet14（派彩金额）、bet16（退水金额）
                 b.bet19, b.bet20, b.bet21, b.bet22, b.bet38,                                               -- 续行：接续上一取列子句，续列 b.bet19, b.bet20, b.bet21, b.bet22, b.bet38，涉 bet19（二级代理线）、bet20（三级代理线）、bet21（四级代理线）
                 b.bet39, b.category, b.validbet,                                                           -- 续行：接续上一取列子句，续列 b.bet39, b.category, b.validbet，涉 bet39（桌号）、validbet（有效投注（洗码量））
                 ROW_NUMBER() OVER (                                                                        -- 行号窗口表达式：以行号窗口取每组头部或去重，免出重复行
                   PARTITION BY b.bet01                                                                     -- 窗口分区：按 b.bet01 分组开窗，组内各自编号或排名
                   ORDER BY b.updatetime DESC, b.sync_time DESC, b.dt DESC) AS rn                           -- 排序：按 b.updatetime（降序）, b.sync_time（降序）, b.dt（降序）) AS rn 排列；导出必带排序，否则分页无稳定序（曾致 36.49% 重复行）
          FROM ods_mariadb_2b.ods_a168_bet02 b                                                              -- 取数来源：取自注单明细表（金额与行为口径的第一料源）
          WHERE b.dt >= '2026-03-21' AND b.dt < '2026-08-07' AND b.bet02 = '101'
      AND b.sync_time <= '2026-08-27 09:00:00'                            -- 过滤条件：限定 b.dt不少于 '2026-03-21'、b.dt小于 '2026-08-07'、b.bet02等于 '101'，涉 bet02（游戏类别）、dt（营业日）
        ),                                                                                                  -- 续行：收束上方的子查询或函数括号（交付件 S_player_tail.csv）
        vd AS (                                                                                             -- 公共表表达式：开启中间结果集 vd，其后各行为其定义体（交付件 S_player_tail.csv）
          SELECT r.*                                                                                        -- 取列：整体承接上游结果集的全部字段，不再逐列列举
          FROM rk r                                                                                         -- 取数来源：取自本条自建的中间结果集 rk
          LEFT JOIN ta t1 ON t1.aid = r.bet18                                                               -- 左连接：取自本条自建的中间结果集 ta，连接键为 bet18（一级代理线）
          LEFT JOIN ta t2 ON t2.aid = r.bet19                                                               -- 左连接：取自本条自建的中间结果集 ta，连接键为 bet19（二级代理线）
          LEFT JOIN ta t3 ON t3.aid = r.bet20                                                               -- 左连接：取自本条自建的中间结果集 ta，连接键为 bet20（三级代理线）
          LEFT JOIN ta t4 ON t4.aid = r.bet21                                                               -- 左连接：取自本条自建的中间结果集 ta，连接键为 bet21（四级代理线）
          LEFT JOIN ta t5 ON t5.aid = r.bet22                                                               -- 左连接：取自本条自建的中间结果集 ta，连接键为 bet22（五级代理线）
          WHERE r.rn = 1 AND r.category = '1' AND UPPER(TRIM(r.bet38)) = 'N'                                -- 过滤条件：限定 r.rn等于 1、r.category等于 '1'、UPPER(TRIM(r.bet38))等于 'N'，涉 bet38（重對）
            AND CAST(NULLIF(TRIM(r.bet05),'') AS BIGINT) > 0                                                -- 并列条件：限定 CAST(NULLIF(TRIM(r.bet05),'') AS BIGINT)大于 0，涉 bet05（会员号）
            AND CAST(NULLIF(TRIM(r.bet11),'') AS DECIMAL(20,8)) > 0                                         -- 并列条件：限定 CAST(NULLIF(TRIM(r.bet11),'') AS DECIMAL(20,8))大于 0，涉 bet11（汇率）
            AND NULLIF(TRIM(r.bet08),'') IS NOT NULL                                                        -- 并列条件：限定该值非空，涉 bet08（下注时间）
            AND COALESCE(t1.aid, t2.aid, t3.aid, t4.aid, t5.aid) IS NULL                                    -- 并列条件：限定该值为空——本包以左连接加空值判定替代 EXISTS，因 StarRocks 不支持 EXISTS 配多列 IN
        ),                                                                                                  -- 续行：收束上方的子查询或函数括号（交付件 S_player_tail.csv）
        bs AS (                                                                                             -- 公共表表达式：开启中间结果集 bs，其后各行为其定义体（交付件 S_player_tail.csv）
          SELECT v.bet05 AS member_id,                                                                      -- 取列：起始取列子句，本行先取「member_id」，涉 bet05（会员号）、member_id（会员号）
                 CONCAT_WS('|', v.bet03, v.bet04, v.bet39) AS round_key,                                    -- 取值表达式：取用 bet03（靴号）、bet04（局内序号）、bet39（桌号），产出「round_key」
                                                                                                            -- ⚠ 局键完整性（2026-08-17 实测 · Z08_roundkey_integrity.csv）：曾疑本键缺日期
                                                                                                            --   成分致跨日塌缩（S1 候选）。今实测结案：跨桌局键 0、bet03 跨桌 0、
                                                                                                            --   注单/局键 = 20.73 注/局（塌缩则应达数千）、含哨兵值 103 行（7.8e-7）。
                                                                                                            --   →【塌缩未发生，S1 候选解除】。附：bet03 已单独决定桌号，bet39 于本键属冗余。
                 v.bet39 AS table_id,                                                                       -- 取值表达式：取用 bet39（桌号），产出「table_id」
                 CAST(NULLIF(TRIM(v.bet08),'') AS DATETIME) AS t_bet,                                       -- 取值表达式：先去空白、空串归 NULL，再显式转型——本库字段多为 varchar，不转型即比较失真，产出「t_bet」
                 CAST(NULLIF(TRIM(v.bet13),'') AS DECIMAL(20,4))                                            -- 取值表达式：先去空白、空串归 NULL，再显式转型——本库字段多为 varchar，不转型即比较失真
                   / CAST(NULLIF(TRIM(v.bet11),'') AS DECIMAL(20,8)) AS stake,                              -- 除法或乘法计算：先去空白、空串归 NULL，再显式转型——本库字段多为 varchar，不转型即比较失真，产出「stake」
                 CAST(NULLIF(TRIM(v.validbet),'') AS DECIMAL(20,4))                                         -- 取值表达式：先去空白、空串归 NULL，再显式转型——本库字段多为 varchar，不转型即比较失真
                   / CAST(NULLIF(TRIM(v.bet11),'') AS DECIMAL(20,8)) AS valid_bet,                          -- 除法或乘法计算：先去空白、空串归 NULL，再显式转型——本库字段多为 varchar，不转型即比较失真，产出「valid_bet」
                 (CAST(NULLIF(TRIM(v.bet14),'') AS DECIMAL(20,4))                                           -- 续行：先去空白、空串归 NULL，再显式转型——本库字段多为 varchar，不转型即比较失真
                  - CAST(NULLIF(TRIM(v.bet13),'') AS DECIMAL(20,4)))                                        -- 加减计算：先去空白、空串归 NULL，再显式转型——本库字段多为 varchar，不转型即比较失真
                   / CAST(NULLIF(TRIM(v.bet11),'') AS DECIMAL(20,8)) AS game_pnl,                           -- 除法或乘法计算：先去空白、空串归 NULL，再显式转型——本库字段多为 varchar，不转型即比较失真，产出「game_pnl」
                 CAST(NULLIF(TRIM(v.bet16),'') AS DECIMAL(20,4))                                            -- 取值表达式：先去空白、空串归 NULL，再显式转型——本库字段多为 varchar，不转型即比较失真
                   / CAST(NULLIF(TRIM(v.bet11),'') AS DECIMAL(20,8)) AS rebate,                             -- 除法或乘法计算：先去空白、空串归 NULL，再显式转型——本库字段多为 varchar，不转型即比较失真，产出「rebate」
                 CAST(NULLIF(TRIM(v.bet17),'') AS DECIMAL(20,4))                                            -- 取值表达式：先去空白、空串归 NULL，再显式转型——本库字段多为 varchar，不转型即比较失真
                   / CAST(NULLIF(TRIM(v.bet11),'') AS DECIMAL(20,8)) AS net_pnl                             -- 除法或乘法计算：先去空白、空串归 NULL，再显式转型——本库字段多为 varchar，不转型即比较失真，产出「net_pnl」
          FROM vd v                                                                                         -- 取数来源：取自本条自建的中间结果集 vd
        ),                                                                                                  -- 续行：收束上方的子查询或函数括号（交付件 S_player_tail.csv）
        ord AS (                                                                                            -- 公共表表达式：开启中间结果集 ord，其后各行为其定义体（交付件 S_player_tail.csv）
          SELECT b.*, PERCENT_RANK() OVER (PARTITION BY round_key ORDER BY t_bet) AS pr_in_round,           -- 取列：整体承接上游结果集的全部字段，不再逐列列举
                      COUNT(*)      OVER (PARTITION BY round_key)                 AS n_in_round             -- 计数表达式：取用 round_key（局键），产出「n_in_round」
          FROM bs b                                                                                         -- 取数来源：取自本条自建的中间结果集 bs
        ),                                                                                                  -- 续行：收束上方的子查询或函数括号（交付件 S_player_tail.csv）
        prd AS (                                                                                            -- 公共表表达式：开启中间结果集 prd，其后各行为其定义体（交付件 S_player_tail.csv）
          SELECT member_id, round_key, table_id,                                                            -- 取列：起始取列子句，本行先列 member_id, round_key, table_id，涉 round_key（局键）、member_id（会员号）
                 MAX(pr_in_round) AS max_pr,                                                                -- 取最大值表达式：产出「max_pr」
                 MAX(n_in_round)  AS n_in_round,                                                            -- 取最大值表达式：产出「n_in_round」
                 SUM(stake) AS stake, SUM(valid_bet) AS valid_bet,                                          -- 汇总表达式：取用 stake（下注额（经汇率归一化））、valid_bet（有效投注（洗码量）），产出「valid_bet」
                 SUM(game_pnl) AS game_pnl, SUM(rebate) AS rebate, SUM(net_pnl) AS net_pnl,                 -- 汇总表达式：取用 net_pnl（会员净输赢）、game_pnl（游戏净输赢）、rebate（退水），产出「net_pnl」
                 CASE WHEN SUM(game_pnl) > 0 THEN 1 ELSE 0 END AS is_win,                                   -- 条件分支：汇总，取用 game_pnl（游戏净输赢），产出「is_win」
                 CASE WHEN SUM(game_pnl) < 0 THEN 1 ELSE 0 END AS is_lose                                   -- 条件分支：汇总，取用 game_pnl（游戏净输赢），产出「is_lose」
          FROM ord WHERE n_in_round >= 5                                                                    -- 取数来源：取自本条自建的中间结果集 ord
          GROUP BY member_id, round_key, table_id                                                           -- 分组：按 member_id, round_key, table_id 汇总
        ),                                                                                                  -- 续行：收束上方的子查询或函数括号（交付件 S_player_tail.csv）
        fl AS (                                                                                             -- 公共表表达式：开启中间结果集 fl，其后各行为其定义体（交付件 S_player_tail.csv）
          SELECT p.*, CASE WHEN p.max_pr >= 0.80 THEN 1 ELSE 0 END AS is_tail                               -- 取列：整体承接上游结果集的全部字段，不再逐列列举
                                                                                                            -- ⚠ 阈值溯源（2026-08-17）：【基准】0.80（现行代码），业务启发式非统计推导。
                                                                                                            --   【建议默认】暂无——本阈值当前不具可优化性：① 尾段假说已证伪（p=0.5847，
                                                                                                            --   个体层 winrate_diff>0 仅 49.7%），无有效目标函数，网格搜索即在噪音上过拟合；
                                                                                                            --   ② PERCENT_RANK 离散，曝光率随 n_in_round 在 20.0%~33.3% 振荡，目标函数不连续；
                                                                                                            --   ③ 与 L6 闸 n_in_round>=5 强耦合（n=5 时退化为「严格最后一注」），不可分别调参。
          FROM prd p                                                                                        -- 取数来源：取自本条自建的中间结果集 prd
        )                                                                                                   -- 续行：收束上方的子查询或函数括号（交付件 S_player_tail.csv）
        SELECT member_id,                                                                                   -- 取列：起始取列子句，本行先列 member_id，涉 member_id（会员号）
          COUNT(*)                      AS n_rounds_all,                                                    -- 计数表达式：产出「n_rounds_all」
          SUM(is_tail)                  AS n_rounds_tail,                                                   -- 汇总表达式：产出「n_rounds_tail」
          SUM(is_tail) * 1.0 / COUNT(*) AS tail_share,                                                      -- 汇总表达式：计数，产出「tail_share」
          SUM(is_tail * is_win)  AS tail_win,                                                               -- 汇总表达式：产出「tail_win」
          SUM(is_tail * is_lose) AS tail_lose,                                                              -- 汇总表达式：产出「tail_lose」
          SUM(is_tail * is_win) * 1.0                                                                       -- 取值表达式：比率之分子，乘 1.0 以避整数除法截断
            / NULLIF(SUM(is_tail * is_win) + SUM(is_tail * is_lose), 0) AS tail_winrate,                    -- 除法或乘法计算：汇总，产出「tail_winrate」
          SUM((1 - is_tail) * is_win) * 1.0                                                                 -- 取值表达式：比率之分子，乘 1.0 以避整数除法截断
            / NULLIF(SUM((1 - is_tail) * is_win) + SUM((1 - is_tail) * is_lose), 0) AS norm_winrate,        -- 除法或乘法计算：汇总，产出「norm_winrate」
          SUM(is_tail * is_win) * 1.0                                                                       -- 取值表达式：比率之分子，乘 1.0 以避整数除法截断
            / NULLIF(SUM(is_tail * is_win) + SUM(is_tail * is_lose), 0)                                     -- 除法或乘法计算：汇总
            - SUM((1 - is_tail) * is_win) * 1.0                                                             -- 取值表达式：比率之分子，乘 1.0 以避整数除法截断
            / NULLIF(SUM((1 - is_tail) * is_win) + SUM((1 - is_tail) * is_lose), 0) AS winrate_diff,        -- 除法或乘法计算：汇总，产出「winrate_diff」
          SUM(is_tail * stake)     AS tail_stake,                                                           -- 汇总表达式：取用 stake（下注额（经汇率归一化）），产出「tail_stake」
          SUM(is_tail * valid_bet) AS tail_valid_bet,                                                       -- 汇总表达式：取用 valid_bet（有效投注（洗码量）），产出「tail_valid_bet」
          SUM(is_tail * game_pnl)  AS tail_game_pnl,                                                        -- 汇总表达式：取用 game_pnl（游戏净输赢），产出「tail_game_pnl」
          SUM(is_tail * rebate)    AS tail_rebate,                                                          -- 汇总表达式：取用 rebate（退水），产出「tail_rebate」
          SUM(is_tail * net_pnl)   AS tail_net_pnl,                                                         -- 汇总表达式：取用 net_pnl（会员净输赢），产出「tail_net_pnl」
          SUM(is_tail * game_pnl) / NULLIF(SUM(is_tail * valid_bet), 0) AS tail_roi,                        -- 汇总表达式：取用 valid_bet（有效投注（洗码量））、game_pnl（游戏净输赢），产出「tail_roi」
          SUM((1 - is_tail) * game_pnl) AS norm_game_pnl,                                                   -- 汇总表达式：取用 game_pnl（游戏净输赢），产出「norm_game_pnl」
          SUM((1 - is_tail) * game_pnl)                                                                     -- 汇总表达式：取用 game_pnl（游戏净输赢）
            / NULLIF(SUM((1 - is_tail) * valid_bet), 0) AS norm_roi,                                        -- 除法或乘法计算：汇总，取用 valid_bet（有效投注（洗码量）），产出「norm_roi」
          SUM(CASE WHEN is_tail = 1 AND game_pnl > 0 THEN game_pnl ELSE 0 END)                              -- 汇总表达式：取用 game_pnl（游戏净输赢）
            / NULLIF(SUM(CASE WHEN game_pnl > 0 THEN game_pnl ELSE 0 END), 0) AS tail_profit_share          -- 除法或乘法计算：汇总，取用 game_pnl（游戏净输赢），产出「tail_profit_share」
        FROM fl                                                                                             -- 取数来源：取自本条自建的中间结果集 fl
        GROUP BY member_id                                                                                  -- 分组：按 member_id 汇总
        HAVING COUNT(*) >= 30                                                                               -- 分组后过滤：限定行数不少于 30
                                                                                                            -- ⚠ 阈值溯源（2026-08-17 实测 · S_player_tail.csv）：
                                                                                                            --   【基准】30（现行代码）—— 实测 Wilson 95% 宽度 0.3369，为目标 0.15 的 2.25 倍。
                                                                                                            --   原注「低于此样本量宽度 > 0.15」字面为真但具误导：30 并未使宽度达标，
                                                                                                            --   它是工程折中而非统计闸门。
                                                                                                            --   【建议默认】171 —— 宽度 0.1482 首次达标，业务代价极小：会员 159,603→57,676
                                                                                                            --   （留存 36.1%），但洗码量仅损失 6.09%（留存 93.91%），流失者皆低活跃会员。
                                                                                                            --   各档实测：50→0.2671｜100→0.1923｜171→0.1482。代码改动须裁定，现以基准运行。
      )
    SELECT q.*,
           -- 一·经济层
           ROUND(e.stake,4) AS stake, ROUND(e.valid,4) AS valid_bet,
           ROUND(-e.net,4) AS profit, e.n_bets, e.n_rounds,
           ROUND(e.net/NULLIF(e.stake,0),8) AS roi,
           ROUND(e.net_in/NULLIF(e.st_in,0),8) AS roi_recent,
           ROUND(e.net_out/NULLIF(e.st_out,0),8) AS roi_non_recent,
           ROUND((e.net-e.rebate)/NULLIF(e.stake,0),8) AS roi_ex_rebate,
           ROUND(e.net,4) AS roi_numerator, ROUND(e.stake,4) AS roi_denominator,
           CASE WHEN e.stake IS NULL THEN 'NULL_DENOM' WHEN e.stake<=0 THEN 'ZERO_DENOM'
                WHEN e.n_bets<30 THEN 'THIN_EXPOSURE' ELSE 'OK' END AS roi_denominator_status,
           ROUND(e.rebate,4) AS rebate_cost, ROUND(e.agent_cost,4)                           AS cost_complement_b,
       ROUND(e.agent_pct,4)                            AS pct_complement,
       ROUND(e.company_retain_pct,4)                   AS pct_top_bet23,
       'AG03-UNRESOLVED'                                     AS agent_formula_version,
      'ALL5_LEVELS_bet23_to_bet27'                    AS agent_level_scope,
      ROUND(e.agent_cost_lv1,4) AS agent_cost_lv1, ROUND(e.agent_cost_lv2,4) AS agent_cost_lv2,
      ROUND(e.agent_cost_lv3,4) AS agent_cost_lv3, ROUND(e.agent_cost_lv4,4) AS agent_cost_lv4,
      ROUND(e.agent_cost_lv5,4) AS agent_cost_lv5,
      ROUND(e.agent_pct_lv1,6) AS agent_pct_lv1, ROUND(e.agent_pct_lv2,6) AS agent_pct_lv2,
      ROUND(e.agent_pct_lv3,6) AS agent_pct_lv3, ROUND(e.agent_pct_lv4,6) AS agent_pct_lv4,
      ROUND(e.agent_pct_lv5,6) AS agent_pct_lv5,
      ROUND(e.retain_pct_lv1,6) AS retain_pct_lv1, ROUND(e.retain_pct_lv2,6) AS retain_pct_lv2,
      ROUND(e.retain_pct_lv3,6) AS retain_pct_lv3, ROUND(e.retain_pct_lv4,6) AS retain_pct_lv4,
      ROUND(e.retain_pct_lv5,6) AS retain_pct_lv5, ROUND(e.chain_depth_avg,4) AS chain_depth_avg,
      ROUND(e.agent_cost_chain_additive,4)            AS agent_cost_chain_additive,
      ROUND(e.agent_cost_chain_nested,4)              AS agent_cost_chain_nested,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_additive,4) AS residual_chain_additive,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_nested,4)   AS residual_chain_nested,
      'PENDING_AG03'                                  AS decision_status,
      'FALSE'                                         AS admit_to_risk_decision,
      'NOT_FOR_ENFORCEMENT'                           AS deliverable_class,
       ROUND(e.agent_cost_a_legacy,4)                  AS agent_cost_a_legacy,
       ROUND(e.agent_cost_valid_base_legacy,4)         AS agent_cost_valid_base_legacy,
           ROUND(-e.net-e.rebate,4)                        AS ngr,
       ROUND(-e.net-e.rebate-e.agent_cost,4)           AS residual_b,
       ROUND(-e.net-e.rebate-e.agent_cost_a_legacy,4)  AS residual_a,
           ROUND((-e.net-e.rebate)/NULLIF(e.stake,0),8)    AS ngr_rate,
       ROUND((-e.net-e.rebate-e.agent_cost)/NULLIF(e.stake,0),8)   AS residual_b_rate,
      -- 【HF9c · canonical accounting contract】
      --   以下 canonical 字段只增加明确 scope；不删除、不覆盖既有字段。
      --   formal_bet23_* 保持 HF9b 当前生产公式及其 NULL/0 语义；
      --   lv1~lv5 / additive / nested 则分别采用各自原始 e.* 成本字段，
      --   rate 一律从未舍入的 e.* 分子 / e.stake 计算，禁止由展示值反算。
      ROUND(e.agent_cost,4) AS agent_cost_bet23_formal_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost,4) AS net_margin_bet23_formal_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost)/NULLIF(e.stake,0),8) AS net_margin_bet23_formal_rate_canonical,
      ROUND(e.agent_cost_lv1,4) AS agent_cost_lv1_bet23_canonical,
      ROUND(e.agent_cost_lv2,4) AS agent_cost_lv2_bet24_canonical,
      ROUND(e.agent_cost_lv3,4) AS agent_cost_lv3_bet25_canonical,
      ROUND(e.agent_cost_lv4,4) AS agent_cost_lv4_bet26_canonical,
      ROUND(e.agent_cost_lv5,4) AS agent_cost_lv5_bet27_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_lv1,4) AS net_margin_lv1_bet23_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_lv1)/NULLIF(e.stake,0),8) AS net_margin_lv1_bet23_rate_canonical,
      ROUND(e.agent_cost_chain_additive,4) AS agent_cost_chain_additive_canonical,
      ROUND(e.agent_cost_chain_nested,4) AS agent_cost_chain_nested_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_additive,4) AS net_margin_chain_additive_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_nested,4) AS net_margin_chain_nested_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_chain_additive)/NULLIF(e.stake,0),8) AS net_margin_chain_additive_rate_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_chain_nested)/NULLIF(e.stake,0),8) AS net_margin_chain_nested_rate_canonical,
       ROUND((-e.net-e.rebate-e.agent_cost_a_legacy)/NULLIF(e.stake,0),8) AS residual_a_rate,
           -- 二·分布层
           ROUND(e.stake/NULLIF(e.n_bets,0),4) AS avg_stake_per_bet,
           ROUND(e.valid/NULLIF(e.n_rounds,0),4) AS avg_valid_bet_per_round,
           ROUND(-e.net/NULLIF(e.n_rounds,0),4) AS avg_profit_per_round,
           ROUND(-e.net/NULLIF(e.active_days,0),4) AS avg_profit_per_day,
           ROUND(-e.net/NULLIF(e.active_shoes,0),4) AS avg_profit_per_shoe,
           ROUND(e.stake/NULLIF(e.active_days,0),4) AS avg_stake_per_active_day,
           ROUND(e.n_rounds*1.0/NULLIF(e.active_days,0),4) AS avg_rounds_per_active_day,
           ROUND(e.st_in/NULLIF(e.nb_in,0),4) AS avg_stake_recent,
           ROUND(e.st_out/NULLIF(e.nb_out,0),4) AS avg_stake_non_recent,
           ROUND(e.p25,4) AS p25_stake, ROUND(e.p50,4) AS p50_stake, ROUND(e.p75,4) AS p75_stake,
           ROUND(e.p90,4) AS p90_stake, ROUND(e.p95,4) AS p95_stake, ROUND(e.p99,4) AS p99_stake,
           ROUND(e.p50_valid,4) AS p50_valid_bet, ROUND(e.p50_profit,4) AS p50_profit,
           ROUND(e.p95/NULLIF(e.p50,0),6) AS p95_over_p50,
           ROUND(e.p99/NULLIF(e.p50,0),6) AS p99_over_p50,
           ROUND((e.stake/NULLIF(e.n_bets,0))/NULLIF(e.p50,0),6) AS avg_over_p50,
           -- 三·关系层
           e.n_tables AS common_table_count, e.n_dealers AS common_dealer_count,
           e.n_ips AS common_ip_count, e.n_products AS common_product_count,
           ROUND(e.st_in/NULLIF(e.stake,0),8) AS share_recent,
           -- 四·rate 层
           ROUND(-e.net/NULLIF(e.stake,0),8) AS hold_rate,
           ROUND(-e.net_in/NULLIF(e.st_in,0),8) AS hold_rate_recent,
           ROUND(e.rebate/NULLIF(e.valid,0),8) AS rebate_rate_actual,
           ROUND(e.rbpct,6) AS rebate_pct_config,
           ROUND(e.valid/NULLIF(e.stake,0),6) AS turnover_multiple,
           ROUND(e.freecomm_rate,6) AS free_comm_rate,
           ROUND(e.net_in/NULLIF(e.st_in,0)-e.net_out/NULLIF(e.st_out,0),8) AS roi_delta_recent,
           -- 五·动态层
           e.first_seen_d AS first_seen, e.last_seen_d AS last_seen,
           e.active_days, e.active_shoes, e.active_sessions,
           DATEDIFF(e.last_seen_d, e.first_seen_d)+1 AS span_days,
           ROUND(e.active_days*1.0/NULLIF(DATEDIFF(e.last_seen_d,e.first_seen_d)+1,0),6) AS persistence,
           ROUND((e.st_in/NULLIF(e.nb_in,0))/NULLIF(e.st_out/NULLIF(e.nb_out,0),0),6) AS ramp_recent_vs_prior,
           ROUND((e.st_rec/NULLIF(e.nb_rec,0))/NULLIF(e.stake/NULLIF(e.n_bets,0),0),6) AS ramp_recent_vs_all,
           ROUND((e.st_rec/NULLIF(e.stake,0))/0.30,6) AS stake_ramp,
           -- 六·决策层（HF9f · 详见档头【HF9f 变更说明】；本段两版逐字同一）
           NTILE(5) OVER (ORDER BY e.stake) AS vip_tier,                                                        -- 窗口取值：相对刻度 B 族，全体五等分；须连同下方血统五元组一并解读，禁作硬阈值判型
           PERCENT_RANK() OVER (ORDER BY -e.net-e.rebate-e.agent_cost)    AS economic_value,                    -- 窗口取值：HF9f·F-19 修正 —— HF9e 写作 -(-…) 双负号致方向颠倒（#075 实测 corr(economic_value, residual_b) = -1.0000）；今与 action_priority 排序键归一，值大即平台真净利高
           PERCENT_RANK() OVER (ORDER BY e.net/NULLIF(e.stake,0))         AS roi_pr_global,                     -- 窗口取值：HF9f·F-17 正名 —— 本列实为 ROI（玩家净回报率）之全体百分位，与「风险」无关；旧名 risk_value 见下一行
           PERCENT_RANK() OVER (ORDER BY e.net/NULLIF(e.stake,0))         AS risk_value,                        -- 窗口取值：兼容列，恒等于 roi_pr_global，仅为下游迁移窗保留；HF9g 起废弃，禁新引用
           PERCENT_RANK() OVER (ORDER BY e.stake)                         AS pr_stake,                          -- 窗口取值：兼容列，恒等于 pr_global，原名保留以免断链
           PERCENT_RANK() OVER (ORDER BY e.stake)                         AS pr_global,                         -- 窗口取值：HF9f·F-1 双轨之一 —— 全体口径百分位，参照总体即本件全部输出行
           CASE WHEN e.n_rounds >= 30                                                                           -- 条件分支：起始分支 —— 仅在合格子集内计算合格口径百分位
                  THEN PERCENT_RANK() OVER (PARTITION BY CASE WHEN e.n_rounds >= 30 THEN 1 ELSE 0 END ORDER BY e.stake)  -- 分支取值：以合格与否分区，故本值即 n_rounds>=30 子集内之百分位
                ELSE NULL END                                             AS pr_qualified,                      -- 条件分支：收束上方分支 —— 不合格者留 NULL（NULL＝未测，非 0），产出「pr_qualified」
           'n_rounds>=30'                                                 AS pr_qualified_population,           -- 字面取值：血统 —— 合格子集之定义
           COUNT(*) OVER ()                                               AS pr_global_population_n,            -- 窗口取值：血统 —— 全体口径之参照总体规模，渲染时现算，禁写死
           SUM(CASE WHEN e.n_rounds >= 30 THEN 1 ELSE 0 END) OVER ()      AS pr_qualified_population_n,         -- 窗口取值：血统 —— 合格子集之参照总体规模，现算，禁写死
           'PERCENT_RANK_OVER_ORDER_BY_e_stake'                           AS pr_calculation_method,             -- 字面取值：血统 —— 算法标识
           'HF9f'                                                         AS pr_calculation_version,            -- 字面取值：血统 —— 算法版本
           CASE WHEN e.n_rounds IS NULL OR e.n_rounds < 30 THEN 'THIN_ROUNDS' ELSE 'OK' END AS evidence_flag,   -- 条件分支：HF9f·F-2a 证据旗标 —— THIN_ROUNDS 者禁入执行队列，仅入观察队列
           CASE WHEN e.n_rounds IS NULL       THEN NULL                                                         -- 条件分支：起始分支 —— 未测者留 NULL（自家铁律：NULL ≠ 0）
                WHEN e.n_rounds >= 31483      THEN 'L1_POWERED'                                                 -- 分支判定：MDE 反解第一档
                WHEN e.n_rounds >= 15409      THEN 'L2_CI_1P5'                                                  -- 分支判定：MDE 反解第二档
                WHEN e.n_rounds >=  8668      THEN 'L3_CI_2P0'                                                  -- 分支判定：MDE 反解第三档
                WHEN e.n_rounds >=  3852      THEN 'L4_CI_3P0'                                                  -- 分支判定：MDE 反解第四档
                ELSE 'L5_INSUFFICIENT' END                                AS evidence_rate,                     -- 条件分支：收束上方 —— HF9f·F-3 证据分档，承 HF9e 前议之 MDE 反解五档，须于 F-4 敏感性实验后复核
           ROUND(1.96 * 0.95 / SQRT(NULLIF(CAST(e.n_rounds AS DOUBLE),0)),8) AS hold_ci_halfwidth_approx,       -- 比率表达式：HF9f·F-3 逐行现算之 95% 半宽近似；常数 0.95 为登记值，本轮 #075 实测每局 ROI 隐含 σ 于最薄层为 0.9249，二者差异待 F-4 裁定
           CASE WHEN e.stake IS NULL OR e.stake<=0 OR e.n_bets<30 OR e.n_rounds IS NULL OR e.n_rounds<30 THEN 'Z 证据不足 · 不动作'  -- 条件分支：HF9f·F-2 双条件取严 —— HF9e 仅卡 e.n_bets<30，致 n_bets>=30 而 n_rounds<30 者绕过 Z（#075 实测 18,537 名，其中 8,145 名已入 A/D 待裁）；今两条件并列取严
                WHEN PERCENT_RANK() OVER (ORDER BY -e.net-e.rebate-e.agent_cost)<=0.10                          -- 分支判定：平台真净利之最低十分位
                  THEN 'A 净亏最大十分位 · 优先复核'                                                             -- 分支取值：HF9f·F-20 正名 —— 本档 Σresidual_b 于 #075 实测 = -100,236,896，系平台净亏最大群，旧名「残值最低十分位 · 待裁」名实不符
                WHEN PERCENT_RANK() OVER (ORDER BY -e.net-e.rebate-e.agent_cost)>=0.80                          -- 分支判定：平台真净利之最高二十分位
                  THEN 'D 净利最高二十分位 · 优先留存'                                                           -- 分支取值：HF9f·F-20 正名 —— 本档 Σresidual_b 于 #075 实测 = +281,733,190，系核心利润源；与 A 档方向相反，旧版同标「待裁」属名实不符
                ELSE 'E 常规' END                                          AS action_priority                   -- 条件分支：收束上方判词，产出「action_priority」
    FROM q
    LEFT JOIN x_agg e ON CAST(e.x_key AS STRING) = CAST(q.`member_id` AS STRING)
  ) y
) z
-- ── 逐批 WHERE 阶梯（★ 口诀：上界 ＝ 下界 ＋ 100000，两数同进）──
--    本件 T_true 未测，无需先跑 T_true；以 0 / 100000 控制本批返回区间，末批由实际行数 < 100000 判定
--    WHERE z.audit_rn >        0 AND z.audit_rn <=   100000   -- 第 1 批
--    WHERE z.audit_rn >   100000 AND z.audit_rn <=   200000   -- 第 2 批
--    WHERE z.audit_rn >   200000 AND z.audit_rn <=   300000   -- 第 3 批
--    WHERE z.audit_rn >   300000 AND z.audit_rn <=   400000   -- 第 4 批
--    WHERE z.audit_rn >   400000 AND z.audit_rn <=   500000   -- 第 5 批
--    WHERE z.audit_rn >   500000 AND z.audit_rn <=   600000   -- 第 6 批
--    WHERE z.audit_rn >   600000 AND z.audit_rn <=   700000   -- 第 7 批
--    …余批类推。第 k 批：WHERE z.audit_rn > (k-1)*100000 AND z.audit_rn <= k*100000
--    某批返回 < 100000 行即为末批，其后不再取。
--
--    ⚠ 常见误写（务必避开）：只推下界而上界不动 ——
--        WHERE z.audit_rn > 100000 AND z.audit_rn <= 100000   ← 自相矛盾，恒为假，返回空集
--        WHERE z.audit_rn > 200000 AND z.audit_rn <= 100000   ← 同上，空集
--      两个数必须**同时**前进，且始终相差 100000。
--      下界 ＝ 上一批之上界；上界 ＝ 本批之上界。
WHERE z.audit_rn > 0 AND z.audit_rn <= 100000 -- ★ HF9c 本批区间
ORDER BY z.audit_rn;


-- ══════════════════════════════════════════════════════════════════════════════════════════════
--  82. S_second_dist.csv   [总包行 1914~1982 · 原 8 列 ＋六层约 60 列]
--     典型学：M15 活跃周期　派生旗标：recent（s.x_rec = 1 · 仅供 CASE 条件聚合，全包无任何 WHERE/AND/HAVING 以此过滤）　连接：q.`table_id`
-- ══════════════════════════════════════════════════════════════════════════════════════════════
-- ── ① 先跑 T_true 留档（不足 100000 者一次导全，不必分批）──
-- ── ① T_true：HF9c 不再强制预跑完整 COUNT。
--    本批实际返回行数 < 100000 即判定为末批；全批完成后以各批 n_rows / audit_rn 范围核对总量。

-- ── ② 分批取数：第 1 批。第 k 批只改末行两数为 (k-1)*100000 与 k*100000 ──
--    审计字段二（REDTEAM 2026-08-24 裁定 · 四锁）：
--      audit_rn  全局观测坐标 —— 由**与原版审计版逐字同一**之排序键所生，两版可逐行对账
--      batch_id  物理分批信息 —— 该行所属批次，由 audit_rn 算得，非引擎所赋
--    ★ 锁三：二者皆为审计字段，**不得进入任何业务指标计算**。
--    ★ 锁四：两版经 audit_rn 逐行字段核验后，方可宣布输出完全一致。

-- ── ③ 每批取回后自证四数（任一不符即停手回报，禁止放行）──
--    n_rows        = COUNT(*)      须等于 COUNT(DISTINCT audit_rn)   （批内无重复）
--    audit_rn_min  = MIN(audit_rn) 须等于 (k-1)*100000 + 1           （与上批严丝合缝）
--    audit_rn_max  = MAX(audit_rn) 须等于 min + n_rows - 1           （批内无缺口）
--    全批取毕再验：各批 audit_rn 之并集 = 1 .. T_true，无缺号、无重号。
--     ★ 首行＝平台真净亏最多者（已扣退水与代理占成）。
--
SELECT z.*,
       CAST(FLOOR((z.audit_rn - 1) / 100000) + 1 AS INT)          AS batch_id,
       'A168_HF9F_20260827_0900' AS run_id,
       '2026-08-27 09:00:00' AS snapshot_sync_time
FROM (
  SELECT y.*,
         ROW_NUMBER() OVER (ORDER BY y.`residual_b` ASC, y.`roi` DESC, y.`table_id`, y.`n_orders`, y.`p50`, y.`p75`, y.`p90`, y.`p95`, y.`p99`, y.`max_progress`) AS audit_rn
  FROM (
    WITH
      x_ranked AS (
    SELECT b.bet01, b.bet03, b.bet04, b.bet05, b.bet09, b.bet11, b.bet13,
           b.bet15, b.bet16, b.bet17, b.bet18, b.bet19, b.bet20, b.bet21,
           b.bet22, b.bet23, b.bet24, b.bet25, b.bet26, b.bet27, b.bet38, b.bet39, b.category, b.commission,
           b.dt, b.eid, b.ip, b.validbet, b.updatetime, b.sync_time,
           ROW_NUMBER() OVER (
             PARTITION BY b.bet01
             ORDER BY b.updatetime DESC, b.sync_time DESC, b.dt DESC)      AS x_rn
    FROM ods_mariadb_2b.ods_a168_bet02 b
    WHERE b.dt >= '2026-03-21' AND b.dt < '2026-08-07'
      AND b.bet02 = '101'
      AND b.sync_time <= '2026-08-27 09:00:00'
  ),
    x_testagent AS (
    SELECT age001 AS agent_id FROM ods_mariadb_2b.ods_a168_agent WHERE age022 = '1'
  ),
    x_bs0 AS (
    SELECT b.bet05 AS x_member, b.eid AS x_dealer, b.bet39 AS x_table,
           b.bet03 AS x_shoe, b.ip AS x_ip, b.bet09 AS x_product, b.dt AS x_date,
           CONCAT_WS('|', b.bet03, b.bet04, b.bet39)                      AS x_round,
           CONCAT_WS('|', b.bet39, b.bet03)                               AS x_tblshoe,
           CAST(NULLIF(TRIM(b.bet04),'') AS INT)                          AS x_rno,
           CASE WHEN b.dt >= '2026-07-08' THEN 1 ELSE 0 END               AS x_rec,
           CASE WHEN TRIM(b.commission)='1' THEN 1 ELSE 0 END             AS x_freecomm,
           CAST(NULLIF(TRIM(b.bet13),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_stake,
           CAST(NULLIF(TRIM(b.validbet),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_valid,
           CAST(NULLIF(TRIM(b.bet16),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_rebate,
           CAST(NULLIF(TRIM(b.bet17),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_net,
           CAST(NULLIF(TRIM(b.bet15),'') AS DECIMAL(20,6))                AS x_rbpct,
           COALESCE(CAST(NULLIF(TRIM(b.bet23),'') AS DECIMAL(20,6)),0)   AS x_agpct,
          NULLIF(CAST(NULLIF(TRIM(b.bet23),'') AS DECIMAL(20,6)),0)     AS x_rate1,
          NULLIF(CAST(NULLIF(TRIM(b.bet24),'') AS DECIMAL(20,6)),0)     AS x_rate2,
          NULLIF(CAST(NULLIF(TRIM(b.bet25),'') AS DECIMAL(20,6)),0)     AS x_rate3,
          NULLIF(CAST(NULLIF(TRIM(b.bet26),'') AS DECIMAL(20,6)),0)     AS x_rate4,
          NULLIF(CAST(NULLIF(TRIM(b.bet27),'') AS DECIMAL(20,6)),0)     AS x_rate5,
          (CASE WHEN NULLIF(CAST(NULLIF(TRIM(b.bet22),'') AS BIGINT),0) IS NOT NULL THEN 5
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet21),'') AS BIGINT),0) IS NOT NULL THEN 4
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet20),'') AS BIGINT),0) IS NOT NULL THEN 3
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet19),'') AS BIGINT),0) IS NOT NULL THEN 2
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet18),'') AS BIGINT),0) IS NOT NULL THEN 1
                ELSE 0 END)                                             AS x_chain_depth,
           CASE WHEN COALESCE(t1.agent_id,t2.agent_id,t3.agent_id,
                              t4.agent_id,t5.agent_id) IS NOT NULL
                THEN 1 ELSE 0 END                                        AS f_testline
    FROM x_ranked b
    LEFT JOIN x_testagent t1 ON t1.agent_id = b.bet18
    LEFT JOIN x_testagent t2 ON t2.agent_id = b.bet19
    LEFT JOIN x_testagent t3 ON t3.agent_id = b.bet20
    LEFT JOIN x_testagent t4 ON t4.agent_id = b.bet21
    LEFT JOIN x_testagent t5 ON t5.agent_id = b.bet22
    WHERE b.x_rn = 1
      AND b.category='1' AND UPPER(TRIM(b.bet38))='N'
      AND CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8)) > 0
  ),
  x_mk AS (
    SELECT s.*,
           CASE WHEN s.f_testline = 0 THEN 1 ELSE 0 END                 AS is_clean
    FROM x_bs0 s
  ),
  x_agg AS (
    SELECT s.x_table                                                        AS x_key,
           COUNT(*) AS n_bets, COUNT(DISTINCT s.x_round) AS n_rounds,
           COUNT(DISTINCT s.x_date) AS active_days, COUNT(DISTINCT s.x_tblshoe) AS active_shoes,
           COUNT(DISTINCT CONCAT_WS('|', s.x_date, s.x_table)) AS active_sessions,
           COUNT(DISTINCT s.x_table) AS n_tables, COUNT(DISTINCT s.x_dealer) AS n_dealers,
           COUNT(DISTINCT s.x_ip) AS n_ips, COUNT(DISTINCT s.x_product) AS n_products,
           MIN(s.x_date) AS first_seen_d, MAX(s.x_date) AS last_seen_d,
           SUM(s.x_stake) AS stake, SUM(s.x_valid) AS valid, SUM(s.x_rebate) AS rebate,
           SUM(s.x_net) AS net, SUM(-s.x_net *(100.0-s.x_agpct)/100.0) AS agent_cost,
           AVG(100.0-s.x_agpct)                   AS agent_pct,
           AVG(s.x_agpct)                         AS company_retain_pct,
           SUM(-s.x_net *s.x_agpct/100.0)         AS agent_cost_a_legacy,
           SUM(s.x_valid*s.x_agpct/100.0)         AS agent_cost_valid_base_legacy,
          AVG(COALESCE(s.x_rate1,100)) AS retain_pct_lv1, AVG(COALESCE(s.x_rate2,100)) AS retain_pct_lv2,
          AVG(COALESCE(s.x_rate3,100)) AS retain_pct_lv3, AVG(COALESCE(s.x_rate4,100)) AS retain_pct_lv4,
          AVG(COALESCE(s.x_rate5,100)) AS retain_pct_lv5, AVG(s.x_chain_depth) AS chain_depth_avg,
          AVG(COALESCE(100.0-s.x_rate1,0)) AS agent_pct_lv1, AVG(COALESCE(100.0-s.x_rate2,0)) AS agent_pct_lv2,
          AVG(COALESCE(100.0-s.x_rate3,0)) AS agent_pct_lv3, AVG(COALESCE(100.0-s.x_rate4,0)) AS agent_pct_lv4,
          AVG(COALESCE(100.0-s.x_rate5,0)) AS agent_pct_lv5,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate1,0)/100.0)                        AS agent_cost_lv1,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate2,0)/100.0)                        AS agent_cost_lv2,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate3,0)/100.0)                        AS agent_cost_lv3,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate4,0)/100.0)                        AS agent_cost_lv4,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate5,0)/100.0)                        AS agent_cost_lv5,
          SUM(-s.x_net*(COALESCE(100.0-s.x_rate1,0)+COALESCE(100.0-s.x_rate2,0)
                       +COALESCE(100.0-s.x_rate3,0)+COALESCE(100.0-s.x_rate4,0)
                       +COALESCE(100.0-s.x_rate5,0))/100.0)                   AS agent_cost_chain_additive,
          SUM(-s.x_net*(1.0 - CAST(COALESCE(s.x_rate1,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate2,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate3,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate4,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate5,100) AS DOUBLE)/100.0))
                                                                       AS agent_cost_chain_nested,
           AVG(s.x_rbpct) AS rbpct, AVG(s.x_freecomm*1.0) AS freecomm_rate,
           PERCENTILE_APPROX(s.x_stake,0.25) AS p25, PERCENTILE_APPROX(s.x_stake,0.50) AS p50,
           PERCENTILE_APPROX(s.x_stake,0.75) AS p75, PERCENTILE_APPROX(s.x_stake,0.90) AS p90,
           PERCENTILE_APPROX(s.x_stake,0.95) AS p95, PERCENTILE_APPROX(s.x_stake,0.99) AS p99,
           PERCENTILE_APPROX(s.x_valid,0.50) AS p50_valid,
           PERCENTILE_APPROX(s.x_net,0.50)   AS p50_profit,
           SUM(CASE WHEN s.x_rec = 1 THEN s.x_stake ELSE 0 END) AS st_in,
           SUM(CASE WHEN s.x_rec = 1 THEN 1 ELSE 0 END)         AS nb_in,
           SUM(CASE WHEN s.x_rec = 1 THEN s.x_net ELSE 0 END)   AS net_in,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN s.x_stake ELSE 0 END) AS st_out,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN 1 ELSE 0 END)         AS nb_out,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN s.x_net ELSE 0 END)   AS net_out,
           SUM(CASE WHEN s.x_rec=1 THEN s.x_stake ELSE 0 END) AS st_rec,
           SUM(CASE WHEN s.x_rec=1 THEN 1 ELSE 0 END)         AS nb_rec
    FROM x_mk s
    WHERE s.is_clean = 1
      AND s.x_table IS NOT NULL AND TRIM(CAST(s.x_table AS STRING)) <> ''
    GROUP BY s.x_table
  ),
      q AS (
        WITH ta AS (            -- 公司测试线代理（214 条，跨五级）
          SELECT DISTINCT age001 AS aid                                                                     -- 取列：产出「aid」
          FROM ods_mariadb_2b.ods_a168_agent WHERE age022 = '1'                                             -- 取数来源：取自代理主档（五级代理线归属来源）
        ),                                                                                                  -- 续行：收束上方的子查询或函数括号（交付件 S_second_dist.csv）
        rk AS (                  -- 需求 §3.2：同注单号取最新版本（三级排序去重）
          SELECT b.bet01, b.updatetime, b.sync_time, b.dt, b.bet02,                                         -- 取列：起始取列子句，本行先列 b.bet01, b.updatetime, b.sync_time, b.dt, b.bet02，涉 bet02（游戏类别）、dt（营业日）
                 b.bet03, b.bet04, b.bet05, b.bet08, b.bet09,                                               -- 续行：接续上一取列子句，续列 b.bet03, b.bet04, b.bet05, b.bet08, b.bet09，涉 bet03（靴号）、bet04（局内序号）、bet05（会员号）
                 b.bet11, b.bet13, b.bet14, b.bet16, b.bet17,                                               -- 续行：接续上一取列子句，续列 b.bet11, b.bet13, b.bet14, b.bet16, b.bet17，涉 bet11（汇率）、bet13（下注金额）、bet14（派彩金额）
                 b.bet18, b.bet19, b.bet20, b.bet21, b.bet22,                                               -- 续行：接续上一取列子句，续列 b.bet18, b.bet19, b.bet20, b.bet21, b.bet22，涉 bet18（一级代理线）、bet19（二级代理线）、bet20（三级代理线）
                 b.bet38, b.bet39, b.category, b.eid, b.ip,                                                 -- 续行：接续上一取列子句，续列 b.bet38, b.bet39, b.category, b.eid, b.ip，涉 bet38（重對）、bet39（桌号）、eid（荷官工号）
                 b.validbet,                                                                                -- 续行：接续上一取列子句，续列 b.validbet，涉 validbet（有效投注（洗码量））
                 ROW_NUMBER() OVER (                                                                        -- 行号窗口表达式：以行号窗口取每组头部或去重，免出重复行
                   PARTITION BY b.bet01                                                                     -- 窗口分区：按 b.bet01 分组开窗，组内各自编号或排名
                   ORDER BY b.updatetime DESC, b.sync_time DESC, b.dt DESC) AS rn                           -- 排序：按 b.updatetime（降序）, b.sync_time（降序）, b.dt（降序）) AS rn 排列；导出必带排序，否则分页无稳定序（曾致 36.49% 重复行）
          FROM ods_mariadb_2b.ods_a168_bet02 b                                                              -- 取数来源：取自注单明细表（金额与行为口径的第一料源）
          WHERE b.dt >= '2026-03-21' AND b.dt < '2026-08-07' AND b.bet02 = '101'
      AND b.sync_time <= '2026-08-27 09:00:00'                            -- 过滤条件：限定 b.dt不少于 '2026-03-21'、b.dt小于 '2026-08-07'、b.bet02等于 '101'，涉 bet02（游戏类别）、dt（营业日）
        ),                                                                                                  -- 续行：收束上方的子查询或函数括号（交付件 S_second_dist.csv）
        vd AS (                  -- 有效注单：非测试线、非重对、一般注单
          SELECT r.*                                                                                        -- 取列：整体承接上游结果集的全部字段，不再逐列列举
          FROM rk r                                                                                         -- 取数来源：取自本条自建的中间结果集 rk
          LEFT JOIN ta t1 ON t1.aid = r.bet18                                                               -- 左连接：取自本条自建的中间结果集 ta，连接键为 bet18（一级代理线）
          LEFT JOIN ta t2 ON t2.aid = r.bet19                                                               -- 左连接：取自本条自建的中间结果集 ta，连接键为 bet19（二级代理线）
          LEFT JOIN ta t3 ON t3.aid = r.bet20                                                               -- 左连接：取自本条自建的中间结果集 ta，连接键为 bet20（三级代理线）
          LEFT JOIN ta t4 ON t4.aid = r.bet21                                                               -- 左连接：取自本条自建的中间结果集 ta，连接键为 bet21（四级代理线）
          LEFT JOIN ta t5 ON t5.aid = r.bet22                                                               -- 左连接：取自本条自建的中间结果集 ta，连接键为 bet22（五级代理线）
          WHERE r.rn = 1 AND r.category = '1' AND UPPER(TRIM(r.bet38)) = 'N'                                -- 过滤条件：限定 r.rn等于 1、r.category等于 '1'、UPPER(TRIM(r.bet38))等于 'N'，涉 bet38（重對）
            AND CAST(NULLIF(TRIM(r.bet05),'') AS BIGINT) > 0                                                -- 并列条件：限定 CAST(NULLIF(TRIM(r.bet05),'') AS BIGINT)大于 0，涉 bet05（会员号）
            AND CAST(NULLIF(TRIM(r.bet11),'') AS DECIMAL(20,8)) > 0                                         -- 并列条件：限定 CAST(NULLIF(TRIM(r.bet11),'') AS DECIMAL(20,8))大于 0，涉 bet11（汇率）
            AND NULLIF(TRIM(r.bet08),'') IS NOT NULL                                                        -- 并列条件：限定该值非空，涉 bet08（下注时间）
            AND COALESCE(t1.aid, t2.aid, t3.aid, t4.aid, t5.aid) IS NULL                                    -- 并列条件：限定该值为空——本包以左连接加空值判定替代 EXISTS，因 StarRocks 不支持 EXISTS 配多列 IN
        ),                                                                                                  -- 续行：收束上方的子查询或函数括号（交付件 S_second_dist.csv）
        bs AS (                  -- 金额正名：本金/洗码量/游戏输赢/退水/净输赢（一律÷汇率）
          SELECT v.bet05 AS member_id, v.eid AS dealer_id, v.ip AS bet_ip,                                  -- 取列：起始取列子句，本行先取「bet_ip」，涉 bet05（会员号）、eid（荷官工号）、bet_ip（下注 IP）
                 v.bet18 AS lv1, v.bet19 AS lv2, v.bet20 AS lv3, v.bet21 AS lv4, v.bet22 AS lv5, CONCAT_WS('|', COALESCE(CAST(NULLIF(CAST(NULLIF(TRIM(v.bet18),'') AS BIGINT),0) AS STRING),'-'), COALESCE(CAST(NULLIF(CAST(NULLIF(TRIM(v.bet19),'') AS BIGINT),0) AS STRING),'-'), COALESCE(CAST(NULLIF(CAST(NULLIF(TRIM(v.bet20),'') AS BIGINT),0) AS STRING),'-'), COALESCE(CAST(NULLIF(CAST(NULLIF(TRIM(v.bet21),'') AS BIGINT),0) AS STRING),'-'), COALESCE(CAST(NULLIF(CAST(NULLIF(TRIM(v.bet22),'') AS BIGINT),0) AS STRING),'-')) AS chain_key, v.bet09 AS bet_side, v.dt AS bet_date,                                     -- 取值表达式：取用 bet09（玩法）、bet20（三级代理线）、dt（营业日），产出「bet_date」
                 CONCAT_WS('|', v.bet03, v.bet04, v.bet39) AS round_key,                                    -- 取值表达式：取用 bet03（靴号）、bet04（局内序号）、bet39（桌号），产出「round_key」
                 v.bet39 AS table_id,                                                                       -- 取值表达式：取用 bet39（桌号），产出「table_id」
                 CAST(NULLIF(TRIM(v.bet08),'') AS DATETIME) AS t_bet,                                       -- 取值表达式：先去空白、空串归 NULL，再显式转型——本库字段多为 varchar，不转型即比较失真，产出「t_bet」
                 CAST(NULLIF(TRIM(v.bet13),'') AS DECIMAL(20,4))                                            -- 取值表达式：先去空白、空串归 NULL，再显式转型——本库字段多为 varchar，不转型即比较失真
                   / CAST(NULLIF(TRIM(v.bet11),'') AS DECIMAL(20,8)) AS stake,                              -- 除法或乘法计算：先去空白、空串归 NULL，再显式转型——本库字段多为 varchar，不转型即比较失真，产出「stake」
                 CAST(NULLIF(TRIM(v.validbet),'') AS DECIMAL(20,4))                                         -- 取值表达式：先去空白、空串归 NULL，再显式转型——本库字段多为 varchar，不转型即比较失真
                   / CAST(NULLIF(TRIM(v.bet11),'') AS DECIMAL(20,8)) AS valid_bet,                          -- 除法或乘法计算：先去空白、空串归 NULL，再显式转型——本库字段多为 varchar，不转型即比较失真，产出「valid_bet」
                 (CAST(NULLIF(TRIM(v.bet14),'') AS DECIMAL(20,4))                                           -- 续行：先去空白、空串归 NULL，再显式转型——本库字段多为 varchar，不转型即比较失真
                  - CAST(NULLIF(TRIM(v.bet13),'') AS DECIMAL(20,4)))                                        -- 加减计算：先去空白、空串归 NULL，再显式转型——本库字段多为 varchar，不转型即比较失真
                   / CAST(NULLIF(TRIM(v.bet11),'') AS DECIMAL(20,8)) AS game_pnl,                           -- 除法或乘法计算：先去空白、空串归 NULL，再显式转型——本库字段多为 varchar，不转型即比较失真，产出「game_pnl」
                 CAST(NULLIF(TRIM(v.bet16),'') AS DECIMAL(20,4))                                            -- 取值表达式：先去空白、空串归 NULL，再显式转型——本库字段多为 varchar，不转型即比较失真
                   / CAST(NULLIF(TRIM(v.bet11),'') AS DECIMAL(20,8)) AS rebate,                             -- 除法或乘法计算：先去空白、空串归 NULL，再显式转型——本库字段多为 varchar，不转型即比较失真，产出「rebate」
                 CAST(NULLIF(TRIM(v.bet17),'') AS DECIMAL(20,4))                                            -- 取值表达式：先去空白、空串归 NULL，再显式转型——本库字段多为 varchar，不转型即比较失真
                   / CAST(NULLIF(TRIM(v.bet11),'') AS DECIMAL(20,8)) AS net_pnl                             -- 除法或乘法计算：先去空白、空串归 NULL，再显式转型——本库字段多为 varchar，不转型即比较失真，产出「net_pnl」
          FROM vd v                                                                                         -- 取数来源：取自本条自建的中间结果集 vd
        ),                                                                                                  -- 续行：收束上方的子查询或函数括号（交付件 S_second_dist.csv）
        gi AS (SELECT gi011 AS table_id,                                                                    -- 取值表达式：取用 gi011（桌号），产出「table_id」
                      CONCAT_WS('|', gi002, gi003, gi011) AS round_key,                                     -- 取值表达式：取用 gi011（桌号）、round_key（局键），产出「round_key」
                      gi004 AS t_open, gi006 AS t_reveal                                                    -- 取值表达式：取用 gi004（局开始时刻）、gi006（开牌时刻），产出「t_reveal」
               FROM ods_mariadb_2b.ods_a168_game_info                                                       -- 取数来源：取自局信息表（靴局、开牌与桌号的时序基准）
               WHERE gi001='101' AND gi013='1' AND is_lock='N'                                              -- 过滤条件：限定 gi001等于 '101'、gi013等于 '1'、is_lock等于 'N'，涉 gi001（局主键）
                 AND gi004>='2026-03-21' AND gi004<'2026-08-07'),                                           -- 并列条件：限定 gi004不少于 '2026-03-21'，涉 gi004（局开始时刻）
        pr AS (SELECT b.table_id, b.round_key,                                                              -- 取值表达式：取用 round_key（局键）
                      (UNIX_TIMESTAMP(b.t_bet)-UNIX_TIMESTAMP(g.t_open))*1.0                                -- 取值表达式：比率之分子，乘 1.0 以避整数除法截断
                      /NULLIF(UNIX_TIMESTAMP(g.t_reveal)-UNIX_TIMESTAMP(g.t_open),0) AS progress            -- 除法或乘法计算：产出「progress」
               FROM bs b JOIN gi g ON g.round_key=b.round_key)                                              -- 取数来源：取自本条自建的中间结果集 bs，连接键为 round_key（局键）
        SELECT table_id, COUNT(*) AS n_orders,                                                              -- 取列：起始取列子句，本行先取「n_orders」
               PERCENTILE_APPROX(progress,0.5)  AS p50,                                                     -- 取近似分位数表达式：产出「p50」
               PERCENTILE_APPROX(progress,0.75) AS p75,                                                     -- 取近似分位数表达式：产出「p75」
               PERCENTILE_APPROX(progress,0.9)  AS p90,                                                     -- 取近似分位数表达式：产出「p90」
               PERCENTILE_APPROX(progress,0.95) AS p95,                                                     -- 取近似分位数表达式：产出「p95」
               PERCENTILE_APPROX(progress,0.99) AS p99,                                                     -- 取近似分位数表达式：产出「p99」
               MAX(progress) AS max_progress                                                                -- 取最大值表达式：产出「max_progress」
        FROM pr WHERE progress BETWEEN 0 AND 1.5                                                            -- 取数来源：取自本条自建的中间结果集 pr
        GROUP BY table_id
      )
    SELECT q.*,
           -- 一·经济层
           ROUND(e.stake,4) AS stake, ROUND(e.valid,4) AS valid_bet,
           ROUND(-e.net,4) AS profit, e.n_bets, e.n_rounds,
           ROUND(e.net/NULLIF(e.stake,0),8) AS roi,
           ROUND(e.net_in/NULLIF(e.st_in,0),8) AS roi_recent,
           ROUND(e.net_out/NULLIF(e.st_out,0),8) AS roi_non_recent,
           ROUND((e.net-e.rebate)/NULLIF(e.stake,0),8) AS roi_ex_rebate,
           ROUND(e.net,4) AS roi_numerator, ROUND(e.stake,4) AS roi_denominator,
           CASE WHEN e.stake IS NULL THEN 'NULL_DENOM' WHEN e.stake<=0 THEN 'ZERO_DENOM'
                WHEN e.n_bets<30 THEN 'THIN_EXPOSURE' ELSE 'OK' END AS roi_denominator_status,
           ROUND(e.rebate,4) AS rebate_cost, ROUND(e.agent_cost,4)                           AS cost_complement_b,
       ROUND(e.agent_pct,4)                            AS pct_complement,
       ROUND(e.company_retain_pct,4)                   AS pct_top_bet23,
       'AG03-UNRESOLVED'                                     AS agent_formula_version,
      'ALL5_LEVELS_bet23_to_bet27'                    AS agent_level_scope,
      ROUND(e.agent_cost_lv1,4) AS agent_cost_lv1, ROUND(e.agent_cost_lv2,4) AS agent_cost_lv2,
      ROUND(e.agent_cost_lv3,4) AS agent_cost_lv3, ROUND(e.agent_cost_lv4,4) AS agent_cost_lv4,
      ROUND(e.agent_cost_lv5,4) AS agent_cost_lv5,
      ROUND(e.agent_pct_lv1,6) AS agent_pct_lv1, ROUND(e.agent_pct_lv2,6) AS agent_pct_lv2,
      ROUND(e.agent_pct_lv3,6) AS agent_pct_lv3, ROUND(e.agent_pct_lv4,6) AS agent_pct_lv4,
      ROUND(e.agent_pct_lv5,6) AS agent_pct_lv5,
      ROUND(e.retain_pct_lv1,6) AS retain_pct_lv1, ROUND(e.retain_pct_lv2,6) AS retain_pct_lv2,
      ROUND(e.retain_pct_lv3,6) AS retain_pct_lv3, ROUND(e.retain_pct_lv4,6) AS retain_pct_lv4,
      ROUND(e.retain_pct_lv5,6) AS retain_pct_lv5, ROUND(e.chain_depth_avg,4) AS chain_depth_avg,
      ROUND(e.agent_cost_chain_additive,4)            AS agent_cost_chain_additive,
      ROUND(e.agent_cost_chain_nested,4)              AS agent_cost_chain_nested,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_additive,4) AS residual_chain_additive,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_nested,4)   AS residual_chain_nested,
      'PENDING_AG03'                                  AS decision_status,
      'FALSE'                                         AS admit_to_risk_decision,
      'NOT_FOR_ENFORCEMENT'                           AS deliverable_class,
       ROUND(e.agent_cost_a_legacy,4)                  AS agent_cost_a_legacy,
       ROUND(e.agent_cost_valid_base_legacy,4)         AS agent_cost_valid_base_legacy,
           ROUND(-e.net-e.rebate,4)                        AS ngr,
       ROUND(-e.net-e.rebate-e.agent_cost,4)           AS residual_b,
       ROUND(-e.net-e.rebate-e.agent_cost_a_legacy,4)  AS residual_a,
           ROUND((-e.net-e.rebate)/NULLIF(e.stake,0),8)    AS ngr_rate,
       ROUND((-e.net-e.rebate-e.agent_cost)/NULLIF(e.stake,0),8)   AS residual_b_rate,
      -- 【HF9c · canonical accounting contract】
      --   以下 canonical 字段只增加明确 scope；不删除、不覆盖既有字段。
      --   formal_bet23_* 保持 HF9b 当前生产公式及其 NULL/0 语义；
      --   lv1~lv5 / additive / nested 则分别采用各自原始 e.* 成本字段，
      --   rate 一律从未舍入的 e.* 分子 / e.stake 计算，禁止由展示值反算。
      ROUND(e.agent_cost,4) AS agent_cost_bet23_formal_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost,4) AS net_margin_bet23_formal_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost)/NULLIF(e.stake,0),8) AS net_margin_bet23_formal_rate_canonical,
      ROUND(e.agent_cost_lv1,4) AS agent_cost_lv1_bet23_canonical,
      ROUND(e.agent_cost_lv2,4) AS agent_cost_lv2_bet24_canonical,
      ROUND(e.agent_cost_lv3,4) AS agent_cost_lv3_bet25_canonical,
      ROUND(e.agent_cost_lv4,4) AS agent_cost_lv4_bet26_canonical,
      ROUND(e.agent_cost_lv5,4) AS agent_cost_lv5_bet27_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_lv1,4) AS net_margin_lv1_bet23_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_lv1)/NULLIF(e.stake,0),8) AS net_margin_lv1_bet23_rate_canonical,
      ROUND(e.agent_cost_chain_additive,4) AS agent_cost_chain_additive_canonical,
      ROUND(e.agent_cost_chain_nested,4) AS agent_cost_chain_nested_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_additive,4) AS net_margin_chain_additive_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_nested,4) AS net_margin_chain_nested_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_chain_additive)/NULLIF(e.stake,0),8) AS net_margin_chain_additive_rate_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_chain_nested)/NULLIF(e.stake,0),8) AS net_margin_chain_nested_rate_canonical,
       ROUND((-e.net-e.rebate-e.agent_cost_a_legacy)/NULLIF(e.stake,0),8) AS residual_a_rate,
           -- 二·分布层
           ROUND(e.stake/NULLIF(e.n_bets,0),4) AS avg_stake_per_bet,
           ROUND(e.valid/NULLIF(e.n_rounds,0),4) AS avg_valid_bet_per_round,
           ROUND(-e.net/NULLIF(e.n_rounds,0),4) AS avg_profit_per_round,
           ROUND(-e.net/NULLIF(e.active_days,0),4) AS avg_profit_per_day,
           ROUND(-e.net/NULLIF(e.active_shoes,0),4) AS avg_profit_per_shoe,
           ROUND(e.stake/NULLIF(e.active_days,0),4) AS avg_stake_per_active_day,
           ROUND(e.n_rounds*1.0/NULLIF(e.active_days,0),4) AS avg_rounds_per_active_day,
           ROUND(e.st_in/NULLIF(e.nb_in,0),4) AS avg_stake_recent,
           ROUND(e.st_out/NULLIF(e.nb_out,0),4) AS avg_stake_non_recent,
           ROUND(e.p25,4) AS p25_stake, ROUND(e.p50,4) AS p50_stake, ROUND(e.p75,4) AS p75_stake,
           ROUND(e.p90,4) AS p90_stake, ROUND(e.p95,4) AS p95_stake, ROUND(e.p99,4) AS p99_stake,
           ROUND(e.p50_valid,4) AS p50_valid_bet, ROUND(e.p50_profit,4) AS p50_profit,
           ROUND(e.p95/NULLIF(e.p50,0),6) AS p95_over_p50,
           ROUND(e.p99/NULLIF(e.p50,0),6) AS p99_over_p50,
           ROUND((e.stake/NULLIF(e.n_bets,0))/NULLIF(e.p50,0),6) AS avg_over_p50,
           -- 三·关系层
           e.n_tables AS common_table_count, e.n_dealers AS common_dealer_count,
           e.n_ips AS common_ip_count, e.n_products AS common_product_count,
           ROUND(e.st_in/NULLIF(e.stake,0),8) AS share_recent,
           -- 四·rate 层
           ROUND(-e.net/NULLIF(e.stake,0),8) AS hold_rate,
           ROUND(-e.net_in/NULLIF(e.st_in,0),8) AS hold_rate_recent,
           ROUND(e.rebate/NULLIF(e.valid,0),8) AS rebate_rate_actual,
           ROUND(e.rbpct,6) AS rebate_pct_config,
           ROUND(e.valid/NULLIF(e.stake,0),6) AS turnover_multiple,
           ROUND(e.freecomm_rate,6) AS free_comm_rate,
           ROUND(e.net_in/NULLIF(e.st_in,0)-e.net_out/NULLIF(e.st_out,0),8) AS roi_delta_recent,
           -- 五·动态层
           e.first_seen_d AS first_seen, e.last_seen_d AS last_seen,
           e.active_days, e.active_shoes, e.active_sessions,
           DATEDIFF(e.last_seen_d, e.first_seen_d)+1 AS span_days,
           ROUND(e.active_days*1.0/NULLIF(DATEDIFF(e.last_seen_d,e.first_seen_d)+1,0),6) AS persistence,
           ROUND((e.st_in/NULLIF(e.nb_in,0))/NULLIF(e.st_out/NULLIF(e.nb_out,0),0),6) AS ramp_recent_vs_prior,
           ROUND((e.st_rec/NULLIF(e.nb_rec,0))/NULLIF(e.stake/NULLIF(e.n_bets,0),0),6) AS ramp_recent_vs_all,
           ROUND((e.st_rec/NULLIF(e.stake,0))/0.30,6) AS stake_ramp,
           -- 六·决策层（HF9f · 详见档头【HF9f 变更说明】；本段两版逐字同一）
           NTILE(5) OVER (ORDER BY e.stake) AS vip_tier,                                                        -- 窗口取值：相对刻度 B 族，全体五等分；须连同下方血统五元组一并解读，禁作硬阈值判型
           PERCENT_RANK() OVER (ORDER BY -e.net-e.rebate-e.agent_cost)    AS economic_value,                    -- 窗口取值：HF9f·F-19 修正 —— HF9e 写作 -(-…) 双负号致方向颠倒（#075 实测 corr(economic_value, residual_b) = -1.0000）；今与 action_priority 排序键归一，值大即平台真净利高
           PERCENT_RANK() OVER (ORDER BY e.net/NULLIF(e.stake,0))         AS roi_pr_global,                     -- 窗口取值：HF9f·F-17 正名 —— 本列实为 ROI（玩家净回报率）之全体百分位，与「风险」无关；旧名 risk_value 见下一行
           PERCENT_RANK() OVER (ORDER BY e.net/NULLIF(e.stake,0))         AS risk_value,                        -- 窗口取值：兼容列，恒等于 roi_pr_global，仅为下游迁移窗保留；HF9g 起废弃，禁新引用
           PERCENT_RANK() OVER (ORDER BY e.stake)                         AS pr_stake,                          -- 窗口取值：兼容列，恒等于 pr_global，原名保留以免断链
           PERCENT_RANK() OVER (ORDER BY e.stake)                         AS pr_global,                         -- 窗口取值：HF9f·F-1 双轨之一 —— 全体口径百分位，参照总体即本件全部输出行
           CASE WHEN e.n_rounds >= 30                                                                           -- 条件分支：起始分支 —— 仅在合格子集内计算合格口径百分位
                  THEN PERCENT_RANK() OVER (PARTITION BY CASE WHEN e.n_rounds >= 30 THEN 1 ELSE 0 END ORDER BY e.stake)  -- 分支取值：以合格与否分区，故本值即 n_rounds>=30 子集内之百分位
                ELSE NULL END                                             AS pr_qualified,                      -- 条件分支：收束上方分支 —— 不合格者留 NULL（NULL＝未测，非 0），产出「pr_qualified」
           'n_rounds>=30'                                                 AS pr_qualified_population,           -- 字面取值：血统 —— 合格子集之定义
           COUNT(*) OVER ()                                               AS pr_global_population_n,            -- 窗口取值：血统 —— 全体口径之参照总体规模，渲染时现算，禁写死
           SUM(CASE WHEN e.n_rounds >= 30 THEN 1 ELSE 0 END) OVER ()      AS pr_qualified_population_n,         -- 窗口取值：血统 —— 合格子集之参照总体规模，现算，禁写死
           'PERCENT_RANK_OVER_ORDER_BY_e_stake'                           AS pr_calculation_method,             -- 字面取值：血统 —— 算法标识
           'HF9f'                                                         AS pr_calculation_version,            -- 字面取值：血统 —— 算法版本
           CASE WHEN e.n_rounds IS NULL OR e.n_rounds < 30 THEN 'THIN_ROUNDS' ELSE 'OK' END AS evidence_flag,   -- 条件分支：HF9f·F-2a 证据旗标 —— THIN_ROUNDS 者禁入执行队列，仅入观察队列
           CASE WHEN e.n_rounds IS NULL       THEN NULL                                                         -- 条件分支：起始分支 —— 未测者留 NULL（自家铁律：NULL ≠ 0）
                WHEN e.n_rounds >= 31483      THEN 'L1_POWERED'                                                 -- 分支判定：MDE 反解第一档
                WHEN e.n_rounds >= 15409      THEN 'L2_CI_1P5'                                                  -- 分支判定：MDE 反解第二档
                WHEN e.n_rounds >=  8668      THEN 'L3_CI_2P0'                                                  -- 分支判定：MDE 反解第三档
                WHEN e.n_rounds >=  3852      THEN 'L4_CI_3P0'                                                  -- 分支判定：MDE 反解第四档
                ELSE 'L5_INSUFFICIENT' END                                AS evidence_rate,                     -- 条件分支：收束上方 —— HF9f·F-3 证据分档，承 HF9e 前议之 MDE 反解五档，须于 F-4 敏感性实验后复核
           ROUND(1.96 * 0.95 / SQRT(NULLIF(CAST(e.n_rounds AS DOUBLE),0)),8) AS hold_ci_halfwidth_approx,       -- 比率表达式：HF9f·F-3 逐行现算之 95% 半宽近似；常数 0.95 为登记值，本轮 #075 实测每局 ROI 隐含 σ 于最薄层为 0.9249，二者差异待 F-4 裁定
           CASE WHEN e.stake IS NULL OR e.stake<=0 OR e.n_bets<30 OR e.n_rounds IS NULL OR e.n_rounds<30 THEN 'Z 证据不足 · 不动作'  -- 条件分支：HF9f·F-2 双条件取严 —— HF9e 仅卡 e.n_bets<30，致 n_bets>=30 而 n_rounds<30 者绕过 Z（#075 实测 18,537 名，其中 8,145 名已入 A/D 待裁）；今两条件并列取严
                WHEN PERCENT_RANK() OVER (ORDER BY -e.net-e.rebate-e.agent_cost)<=0.10                          -- 分支判定：平台真净利之最低十分位
                  THEN 'A 净亏最大十分位 · 优先复核'                                                             -- 分支取值：HF9f·F-20 正名 —— 本档 Σresidual_b 于 #075 实测 = -100,236,896，系平台净亏最大群，旧名「残值最低十分位 · 待裁」名实不符
                WHEN PERCENT_RANK() OVER (ORDER BY -e.net-e.rebate-e.agent_cost)>=0.80                          -- 分支判定：平台真净利之最高二十分位
                  THEN 'D 净利最高二十分位 · 优先留存'                                                           -- 分支取值：HF9f·F-20 正名 —— 本档 Σresidual_b 于 #075 实测 = +281,733,190，系核心利润源；与 A 档方向相反，旧版同标「待裁」属名实不符
                ELSE 'E 常规' END                                          AS action_priority                   -- 条件分支：收束上方判词，产出「action_priority」
    FROM q
    LEFT JOIN x_agg e ON CAST(e.x_key AS STRING) = CAST(q.`table_id` AS STRING)
  ) y
) z
-- ── 逐批 WHERE 阶梯（★ 口诀：上界 ＝ 下界 ＋ 100000，两数同进）──
--    本件 T_true 未测，无需先跑 T_true；以 0 / 100000 控制本批返回区间，末批由实际行数 < 100000 判定
--    WHERE z.audit_rn >        0 AND z.audit_rn <=   100000   -- 第 1 批
--    WHERE z.audit_rn >   100000 AND z.audit_rn <=   200000   -- 第 2 批
--    WHERE z.audit_rn >   200000 AND z.audit_rn <=   300000   -- 第 3 批
--    WHERE z.audit_rn >   300000 AND z.audit_rn <=   400000   -- 第 4 批
--    WHERE z.audit_rn >   400000 AND z.audit_rn <=   500000   -- 第 5 批
--    WHERE z.audit_rn >   500000 AND z.audit_rn <=   600000   -- 第 6 批
--    WHERE z.audit_rn >   600000 AND z.audit_rn <=   700000   -- 第 7 批
--    …余批类推。第 k 批：WHERE z.audit_rn > (k-1)*100000 AND z.audit_rn <= k*100000
--    某批返回 < 100000 行即为末批，其后不再取。
--
--    ⚠ 常见误写（务必避开）：只推下界而上界不动 ——
--        WHERE z.audit_rn > 100000 AND z.audit_rn <= 100000   ← 自相矛盾，恒为假，返回空集
--        WHERE z.audit_rn > 200000 AND z.audit_rn <= 100000   ← 同上，空集
--      两个数必须**同时**前进，且始终相差 100000。
--      下界 ＝ 上一批之上界；上界 ＝ 本批之上界。
WHERE z.audit_rn > 0 AND z.audit_rn <= 100000 -- ★ HF9c 本批区间
ORDER BY z.audit_rn;


-- ══════════════════════════════════════════════════════════════════════════════════════════════
--  83. T02_daily_roi.csv   [总包行 5146~5190 · 原 5 列 ＋六层约 60 列]
--     典型学：M15 活跃周期　派生旗标：recent（s.x_rec = 1 · 仅供 CASE 条件聚合，全包无任何 WHERE/AND/HAVING 以此过滤）　连接：q.`member_id`
-- ══════════════════════════════════════════════════════════════════════════════════════════════
-- ── ① 先跑 T_true 留档（不足 100000 者一次导全，不必分批）──
-- ── ① T_true：HF9c 不再强制预跑完整 COUNT。
--    本批实际返回行数 < 100000 即判定为末批；全批完成后以各批 n_rows / audit_rn 范围核对总量。

-- ── ② 分批取数：第 1 批。第 k 批只改末行两数为 (k-1)*100000 与 k*100000 ──
--    审计字段二（REDTEAM 2026-08-24 裁定 · 四锁）：
--      audit_rn  全局观测坐标 —— 由**与原版审计版逐字同一**之排序键所生，两版可逐行对账
--      batch_id  物理分批信息 —— 该行所属批次，由 audit_rn 算得，非引擎所赋
--    ★ 锁三：二者皆为审计字段，**不得进入任何业务指标计算**。
--    ★ 锁四：两版经 audit_rn 逐行字段核验后，方可宣布输出完全一致。

-- ── ③ 每批取回后自证四数（任一不符即停手回报，禁止放行）──
--    n_rows        = COUNT(*)      须等于 COUNT(DISTINCT audit_rn)   （批内无重复）
--    audit_rn_min  = MIN(audit_rn) 须等于 (k-1)*100000 + 1           （与上批严丝合缝）
--    audit_rn_max  = MAX(audit_rn) 须等于 min + n_rows - 1           （批内无缺口）
--    全批取毕再验：各批 audit_rn 之并集 = 1 .. T_true，无缺号、无重号。
--     ★ 首行＝平台真净亏最多者（已扣退水与代理占成）。
--
SELECT z.*,
       CAST(FLOOR((z.audit_rn - 1) / 100000) + 1 AS INT)          AS batch_id,
       'A168_HF9F_20260827_0900' AS run_id,
       '2026-08-27 09:00:00' AS snapshot_sync_time
FROM (
  SELECT y.*,
         ROW_NUMBER() OVER (ORDER BY y.`residual_b` ASC, y.`roi` DESC, y.`member_id`, y.`bet_date`, y.`stake`, y.`game_pnl`, y.`n_rounds`) AS audit_rn
  FROM (
    WITH
      x_ranked AS (
    SELECT b.bet01, b.bet03, b.bet04, b.bet05, b.bet09, b.bet11, b.bet13,
           b.bet15, b.bet16, b.bet17, b.bet18, b.bet19, b.bet20, b.bet21,
           b.bet22, b.bet23, b.bet24, b.bet25, b.bet26, b.bet27, b.bet38, b.bet39, b.category, b.commission,
           b.dt, b.eid, b.ip, b.validbet, b.updatetime, b.sync_time,
           ROW_NUMBER() OVER (
             PARTITION BY b.bet01
             ORDER BY b.updatetime DESC, b.sync_time DESC, b.dt DESC)      AS x_rn
    FROM ods_mariadb_2b.ods_a168_bet02 b
    WHERE b.dt >= '2026-03-21' AND b.dt < '2026-08-07'
      AND b.bet02 = '101'
      AND b.sync_time <= '2026-08-27 09:00:00'
  ),
    x_testagent AS (
    SELECT age001 AS agent_id FROM ods_mariadb_2b.ods_a168_agent WHERE age022 = '1'
  ),
    x_bs0 AS (
    SELECT b.bet05 AS x_member, b.eid AS x_dealer, b.bet39 AS x_table,
           b.bet03 AS x_shoe, b.ip AS x_ip, b.bet09 AS x_product, b.dt AS x_date,
           CONCAT_WS('|', b.bet03, b.bet04, b.bet39)                      AS x_round,
           CONCAT_WS('|', b.bet39, b.bet03)                               AS x_tblshoe,
           CAST(NULLIF(TRIM(b.bet04),'') AS INT)                          AS x_rno,
           CASE WHEN b.dt >= '2026-07-08' THEN 1 ELSE 0 END               AS x_rec,
           CASE WHEN TRIM(b.commission)='1' THEN 1 ELSE 0 END             AS x_freecomm,
           CAST(NULLIF(TRIM(b.bet13),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_stake,
           CAST(NULLIF(TRIM(b.validbet),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_valid,
           CAST(NULLIF(TRIM(b.bet16),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_rebate,
           CAST(NULLIF(TRIM(b.bet17),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_net,
           CAST(NULLIF(TRIM(b.bet15),'') AS DECIMAL(20,6))                AS x_rbpct,
           COALESCE(CAST(NULLIF(TRIM(b.bet23),'') AS DECIMAL(20,6)),0)   AS x_agpct,
          NULLIF(CAST(NULLIF(TRIM(b.bet23),'') AS DECIMAL(20,6)),0)     AS x_rate1,
          NULLIF(CAST(NULLIF(TRIM(b.bet24),'') AS DECIMAL(20,6)),0)     AS x_rate2,
          NULLIF(CAST(NULLIF(TRIM(b.bet25),'') AS DECIMAL(20,6)),0)     AS x_rate3,
          NULLIF(CAST(NULLIF(TRIM(b.bet26),'') AS DECIMAL(20,6)),0)     AS x_rate4,
          NULLIF(CAST(NULLIF(TRIM(b.bet27),'') AS DECIMAL(20,6)),0)     AS x_rate5,
          (CASE WHEN NULLIF(CAST(NULLIF(TRIM(b.bet22),'') AS BIGINT),0) IS NOT NULL THEN 5
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet21),'') AS BIGINT),0) IS NOT NULL THEN 4
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet20),'') AS BIGINT),0) IS NOT NULL THEN 3
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet19),'') AS BIGINT),0) IS NOT NULL THEN 2
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet18),'') AS BIGINT),0) IS NOT NULL THEN 1
                ELSE 0 END)                                             AS x_chain_depth,
           CASE WHEN COALESCE(t1.agent_id,t2.agent_id,t3.agent_id,
                              t4.agent_id,t5.agent_id) IS NOT NULL
                THEN 1 ELSE 0 END                                        AS f_testline
    FROM x_ranked b
    LEFT JOIN x_testagent t1 ON t1.agent_id = b.bet18
    LEFT JOIN x_testagent t2 ON t2.agent_id = b.bet19
    LEFT JOIN x_testagent t3 ON t3.agent_id = b.bet20
    LEFT JOIN x_testagent t4 ON t4.agent_id = b.bet21
    LEFT JOIN x_testagent t5 ON t5.agent_id = b.bet22
    WHERE b.x_rn = 1
      AND b.category='1' AND UPPER(TRIM(b.bet38))='N'
      AND CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8)) > 0
  ),
  x_mk AS (
    SELECT s.*,
           CASE WHEN s.f_testline = 0 THEN 1 ELSE 0 END                 AS is_clean
    FROM x_bs0 s
  ),
  x_agg AS (
    SELECT s.x_member                                                        AS x_key,
           COUNT(*) AS n_bets, COUNT(DISTINCT s.x_round) AS n_rounds,
           COUNT(DISTINCT s.x_date) AS active_days, COUNT(DISTINCT s.x_tblshoe) AS active_shoes,
           COUNT(DISTINCT CONCAT_WS('|', s.x_date, s.x_table)) AS active_sessions,
           COUNT(DISTINCT s.x_table) AS n_tables, COUNT(DISTINCT s.x_dealer) AS n_dealers,
           COUNT(DISTINCT s.x_ip) AS n_ips, COUNT(DISTINCT s.x_product) AS n_products,
           MIN(s.x_date) AS first_seen_d, MAX(s.x_date) AS last_seen_d,
           SUM(s.x_stake) AS stake, SUM(s.x_valid) AS valid, SUM(s.x_rebate) AS rebate,
           SUM(s.x_net) AS net, SUM(-s.x_net *(100.0-s.x_agpct)/100.0) AS agent_cost,
           AVG(100.0-s.x_agpct)                   AS agent_pct,
           AVG(s.x_agpct)                         AS company_retain_pct,
           SUM(-s.x_net *s.x_agpct/100.0)         AS agent_cost_a_legacy,
           SUM(s.x_valid*s.x_agpct/100.0)         AS agent_cost_valid_base_legacy,
          AVG(COALESCE(s.x_rate1,100)) AS retain_pct_lv1, AVG(COALESCE(s.x_rate2,100)) AS retain_pct_lv2,
          AVG(COALESCE(s.x_rate3,100)) AS retain_pct_lv3, AVG(COALESCE(s.x_rate4,100)) AS retain_pct_lv4,
          AVG(COALESCE(s.x_rate5,100)) AS retain_pct_lv5, AVG(s.x_chain_depth) AS chain_depth_avg,
          AVG(COALESCE(100.0-s.x_rate1,0)) AS agent_pct_lv1, AVG(COALESCE(100.0-s.x_rate2,0)) AS agent_pct_lv2,
          AVG(COALESCE(100.0-s.x_rate3,0)) AS agent_pct_lv3, AVG(COALESCE(100.0-s.x_rate4,0)) AS agent_pct_lv4,
          AVG(COALESCE(100.0-s.x_rate5,0)) AS agent_pct_lv5,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate1,0)/100.0)                        AS agent_cost_lv1,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate2,0)/100.0)                        AS agent_cost_lv2,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate3,0)/100.0)                        AS agent_cost_lv3,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate4,0)/100.0)                        AS agent_cost_lv4,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate5,0)/100.0)                        AS agent_cost_lv5,
          SUM(-s.x_net*(COALESCE(100.0-s.x_rate1,0)+COALESCE(100.0-s.x_rate2,0)
                       +COALESCE(100.0-s.x_rate3,0)+COALESCE(100.0-s.x_rate4,0)
                       +COALESCE(100.0-s.x_rate5,0))/100.0)                   AS agent_cost_chain_additive,
          SUM(-s.x_net*(1.0 - CAST(COALESCE(s.x_rate1,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate2,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate3,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate4,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate5,100) AS DOUBLE)/100.0))
                                                                       AS agent_cost_chain_nested,
           AVG(s.x_rbpct) AS rbpct, AVG(s.x_freecomm*1.0) AS freecomm_rate,
           PERCENTILE_APPROX(s.x_stake,0.25) AS p25, PERCENTILE_APPROX(s.x_stake,0.50) AS p50,
           PERCENTILE_APPROX(s.x_stake,0.75) AS p75, PERCENTILE_APPROX(s.x_stake,0.90) AS p90,
           PERCENTILE_APPROX(s.x_stake,0.95) AS p95, PERCENTILE_APPROX(s.x_stake,0.99) AS p99,
           PERCENTILE_APPROX(s.x_valid,0.50) AS p50_valid,
           PERCENTILE_APPROX(s.x_net,0.50)   AS p50_profit,
           SUM(CASE WHEN s.x_rec = 1 THEN s.x_stake ELSE 0 END) AS st_in,
           SUM(CASE WHEN s.x_rec = 1 THEN 1 ELSE 0 END)         AS nb_in,
           SUM(CASE WHEN s.x_rec = 1 THEN s.x_net ELSE 0 END)   AS net_in,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN s.x_stake ELSE 0 END) AS st_out,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN 1 ELSE 0 END)         AS nb_out,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN s.x_net ELSE 0 END)   AS net_out,
           SUM(CASE WHEN s.x_rec=1 THEN s.x_stake ELSE 0 END) AS st_rec,
           SUM(CASE WHEN s.x_rec=1 THEN 1 ELSE 0 END)         AS nb_rec
    FROM x_mk s
    WHERE s.is_clean = 1
      AND s.x_member IS NOT NULL AND TRIM(CAST(s.x_member AS STRING)) <> ''
    GROUP BY s.x_member
  ),
      q AS (
        WITH test_agents AS (                                                                               -- 公共表表达式：开启中间结果集 test_agents，其后各行为其定义体（§T02）
          SELECT age001 AS agent_id FROM ods_mariadb_2b.ods_a168_agent WHERE age022 = '1'                   -- 取列：取用代理主档（五级代理线归属来源），产出「agent_id」
        ),                                                                                                  -- 续行：收束上方的子查询或函数括号（§T02）
        ranked AS (                                                                                         -- 公共表表达式：开启中间结果集 ranked，其后各行为其定义体（§T02）
          SELECT b.bet01, b.updatetime, b.sync_time, b.dt, b.bet02,                                         -- 取列：起始取列子句，本行先列 b.bet01, b.updatetime, b.sync_time, b.dt, b.bet02，涉 bet02（游戏类别）、dt（营业日）
                 b.bet03, b.bet04, b.bet05, b.bet11, b.bet13,                                               -- 续行：接续上一取列子句，续列 b.bet03, b.bet04, b.bet05, b.bet11, b.bet13，涉 bet03（靴号）、bet04（局内序号）、bet05（会员号）
                 b.bet14, b.bet18, b.bet19, b.bet20, b.bet21,                                               -- 续行：接续上一取列子句，续列 b.bet14, b.bet18, b.bet19, b.bet20, b.bet21，涉 bet14（派彩金额）、bet18（一级代理线）、bet19（二级代理线）
                 b.bet22, b.bet38, b.bet39, b.category,                                                     -- 续行：接续上一取列子句，续列 b.bet22, b.bet38, b.bet39, b.category，涉 bet22（五级代理线）、bet38（重對）、bet39（桌号）
                 ROW_NUMBER() OVER (                                                                        -- 行号窗口表达式：以行号窗口取每组头部或去重，免出重复行
                   PARTITION BY b.bet01                                                                     -- 窗口分区：按 b.bet01 分组开窗，组内各自编号或排名
                   ORDER BY b.updatetime DESC, b.sync_time DESC, b.dt DESC) AS rn                           -- 排序：按 b.updatetime（降序）, b.sync_time（降序）, b.dt（降序）) AS rn 排列；导出必带排序，否则分页无稳定序（曾致 36.49% 重复行）
          FROM ods_mariadb_2b.ods_a168_bet02 b            -- ★ 表名开关
          WHERE b.dt >= '2026-03-21' AND b.dt < '2026-08-07'                                                -- 过滤条件：限定 b.dt不少于 '2026-03-21'、b.dt小于 '2026-08-07'，涉 dt（营业日）
            AND b.bet02 = '101'
      AND b.sync_time <= '2026-08-27 09:00:00'                                                                             -- 并列条件：限定 b.bet02等于 '101'，涉 bet02（游戏类别）
        ),                                                                                                  -- 续行：收束上方的子查询或函数括号（§T02）
        ord AS (                                                                                            -- 公共表表达式：开启中间结果集 ord，其后各行为其定义体（§T02）
          SELECT r.bet05 AS member_id, r.dt AS bet_date,                                                    -- 取列：起始取列子句，本行先取「bet_date」，涉 bet05（会员号）、dt（营业日）、member_id（会员号）
                 CONCAT_WS('|', r.bet03, r.bet04, r.bet39) AS round_key,                                    -- 取值表达式：取用 bet03（靴号）、bet04（局内序号）、bet39（桌号），产出「round_key」
                 CAST(NULLIF(TRIM(r.bet13),'') AS DECIMAL(20,4))                                            -- 取值表达式：先去空白、空串归 NULL，再显式转型——本库字段多为 varchar，不转型即比较失真
                   / NULLIF(CAST(NULLIF(TRIM(r.bet11),'') AS DECIMAL(20,8)),0) AS stake,                    -- 除法或乘法计算：先去空白、空串归 NULL，再显式转型——本库字段多为 varchar，不转型即比较失真，产出「stake」
                 (CAST(NULLIF(TRIM(r.bet14),'') AS DECIMAL(20,4))                                           -- 续行：先去空白、空串归 NULL，再显式转型——本库字段多为 varchar，不转型即比较失真
                  - CAST(NULLIF(TRIM(r.bet13),'') AS DECIMAL(20,4)))                                        -- 加减计算：先去空白、空串归 NULL，再显式转型——本库字段多为 varchar，不转型即比较失真
                   / NULLIF(CAST(NULLIF(TRIM(r.bet11),'') AS DECIMAL(20,8)),0) AS game_pnl                  -- 除法或乘法计算：先去空白、空串归 NULL，再显式转型——本库字段多为 varchar，不转型即比较失真，产出「game_pnl」
          FROM ranked r                                                                                     -- 取数来源：取自本条自建的中间结果集 ranked
          LEFT JOIN test_agents t1 ON t1.agent_id = r.bet18                                                 -- 左连接：取自本条自建的中间结果集 test_agents，连接键为 bet18（一级代理线）
          LEFT JOIN test_agents t2 ON t2.agent_id = r.bet19                                                 -- 左连接：取自本条自建的中间结果集 test_agents，连接键为 bet19（二级代理线）
          LEFT JOIN test_agents t3 ON t3.agent_id = r.bet20                                                 -- 左连接：取自本条自建的中间结果集 test_agents，连接键为 bet20（三级代理线）
          LEFT JOIN test_agents t4 ON t4.agent_id = r.bet21                                                 -- 左连接：取自本条自建的中间结果集 test_agents，连接键为 bet21（四级代理线）
          LEFT JOIN test_agents t5 ON t5.agent_id = r.bet22                                                 -- 左连接：取自本条自建的中间结果集 test_agents，连接键为 bet22（五级代理线）
          WHERE r.rn = 1 AND r.category = '1' AND UPPER(TRIM(r.bet38)) = 'N'                                -- 过滤条件：限定 r.rn等于 1、r.category等于 '1'、UPPER(TRIM(r.bet38))等于 'N'，涉 bet38（重對）
            AND CAST(NULLIF(TRIM(r.bet05),'') AS BIGINT) > 0                                                -- 并列条件：限定 CAST(NULLIF(TRIM(r.bet05),'') AS BIGINT)大于 0，涉 bet05（会员号）
            AND CAST(NULLIF(TRIM(r.bet11),'') AS DECIMAL(20,8)) > 0                                         -- 并列条件：限定 CAST(NULLIF(TRIM(r.bet11),'') AS DECIMAL(20,8))大于 0，涉 bet11（汇率）
            AND COALESCE(t1.agent_id,t2.agent_id,t3.agent_id,t4.agent_id,t5.agent_id) IS NULL               -- 并列条件：限定该值为空——本包以左连接加空值判定替代 EXISTS，因 StarRocks 不支持 EXISTS 配多列 IN
        ),                                                                                                  -- 续行：收束上方的子查询或函数括号（§T02）
        act AS (   -- 报告里索提诺要求「活跃日 ≥ 20」，少于 20 天的会员导出来也用不上
          SELECT member_id FROM ord                                                                         -- 取列：取用 member_id（会员号）
          GROUP BY member_id HAVING COUNT(DISTINCT bet_date) >= 20                                          -- 分组：统计去重个数
        )                                                                                                   -- 续行：收束上方的子查询或函数括号（§T02）
        SELECT o.member_id, o.bet_date,                                                                     -- 取列：起始取列子句，本行先列 o.member_id, o.bet_date，涉 member_id（会员号）、bet_date（营业日）
               SUM(o.stake)                     AS stake,                                                   -- 汇总表达式：取用 stake（下注额（经汇率归一化）），产出「stake」
               SUM(o.game_pnl)                  AS game_pnl,                                                -- 汇总表达式：取用 game_pnl（游戏净输赢），产出「game_pnl」
               COUNT(DISTINCT o.round_key)      AS n_rounds                                                 -- 计数表达式：统计去重个数，产出「n_rounds」
        FROM ord o JOIN act a ON a.member_id = o.member_id                                                  -- 取数来源：取自本条自建的中间结果集 ord，连接键为 member_id（会员号）
        GROUP BY o.member_id, o.bet_date                                                                    -- 分组：按 o.member_id, o.bet_date 汇总
      )
    SELECT q.*,
           -- 一·经济层
           ROUND(e.stake,4) AS stake_xagg, ROUND(e.valid,4) AS valid_bet,
           ROUND(-e.net,4) AS profit, e.n_bets, e.n_rounds AS n_rounds_xagg,
           ROUND(e.net/NULLIF(e.stake,0),8) AS roi,
           ROUND(e.net_in/NULLIF(e.st_in,0),8) AS roi_recent,
           ROUND(e.net_out/NULLIF(e.st_out,0),8) AS roi_non_recent,
           ROUND((e.net-e.rebate)/NULLIF(e.stake,0),8) AS roi_ex_rebate,
           ROUND(e.net,4) AS roi_numerator, ROUND(e.stake,4) AS roi_denominator,
           CASE WHEN e.stake IS NULL THEN 'NULL_DENOM' WHEN e.stake<=0 THEN 'ZERO_DENOM'
                WHEN e.n_bets<30 THEN 'THIN_EXPOSURE' ELSE 'OK' END AS roi_denominator_status,
           ROUND(e.rebate,4) AS rebate_cost, ROUND(e.agent_cost,4)                           AS cost_complement_b,
       ROUND(e.agent_pct,4)                            AS pct_complement,
       ROUND(e.company_retain_pct,4)                   AS pct_top_bet23,
       'AG03-UNRESOLVED'                                     AS agent_formula_version,
      'ALL5_LEVELS_bet23_to_bet27'                    AS agent_level_scope,
      ROUND(e.agent_cost_lv1,4) AS agent_cost_lv1, ROUND(e.agent_cost_lv2,4) AS agent_cost_lv2,
      ROUND(e.agent_cost_lv3,4) AS agent_cost_lv3, ROUND(e.agent_cost_lv4,4) AS agent_cost_lv4,
      ROUND(e.agent_cost_lv5,4) AS agent_cost_lv5,
      ROUND(e.agent_pct_lv1,6) AS agent_pct_lv1, ROUND(e.agent_pct_lv2,6) AS agent_pct_lv2,
      ROUND(e.agent_pct_lv3,6) AS agent_pct_lv3, ROUND(e.agent_pct_lv4,6) AS agent_pct_lv4,
      ROUND(e.agent_pct_lv5,6) AS agent_pct_lv5,
      ROUND(e.retain_pct_lv1,6) AS retain_pct_lv1, ROUND(e.retain_pct_lv2,6) AS retain_pct_lv2,
      ROUND(e.retain_pct_lv3,6) AS retain_pct_lv3, ROUND(e.retain_pct_lv4,6) AS retain_pct_lv4,
      ROUND(e.retain_pct_lv5,6) AS retain_pct_lv5, ROUND(e.chain_depth_avg,4) AS chain_depth_avg,
      ROUND(e.agent_cost_chain_additive,4)            AS agent_cost_chain_additive,
      ROUND(e.agent_cost_chain_nested,4)              AS agent_cost_chain_nested,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_additive,4) AS residual_chain_additive,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_nested,4)   AS residual_chain_nested,
      'PENDING_AG03'                                  AS decision_status,
      'FALSE'                                         AS admit_to_risk_decision,
      'NOT_FOR_ENFORCEMENT'                           AS deliverable_class,
       ROUND(e.agent_cost_a_legacy,4)                  AS agent_cost_a_legacy,
       ROUND(e.agent_cost_valid_base_legacy,4)         AS agent_cost_valid_base_legacy,
           ROUND(-e.net-e.rebate,4)                        AS ngr,
       ROUND(-e.net-e.rebate-e.agent_cost,4)           AS residual_b,
       ROUND(-e.net-e.rebate-e.agent_cost_a_legacy,4)  AS residual_a,
           ROUND((-e.net-e.rebate)/NULLIF(e.stake,0),8)    AS ngr_rate,
       ROUND((-e.net-e.rebate-e.agent_cost)/NULLIF(e.stake,0),8)   AS residual_b_rate,
      -- 【HF9c · canonical accounting contract】
      --   以下 canonical 字段只增加明确 scope；不删除、不覆盖既有字段。
      --   formal_bet23_* 保持 HF9b 当前生产公式及其 NULL/0 语义；
      --   lv1~lv5 / additive / nested 则分别采用各自原始 e.* 成本字段，
      --   rate 一律从未舍入的 e.* 分子 / e.stake 计算，禁止由展示值反算。
      ROUND(e.agent_cost,4) AS agent_cost_bet23_formal_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost,4) AS net_margin_bet23_formal_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost)/NULLIF(e.stake,0),8) AS net_margin_bet23_formal_rate_canonical,
      ROUND(e.agent_cost_lv1,4) AS agent_cost_lv1_bet23_canonical,
      ROUND(e.agent_cost_lv2,4) AS agent_cost_lv2_bet24_canonical,
      ROUND(e.agent_cost_lv3,4) AS agent_cost_lv3_bet25_canonical,
      ROUND(e.agent_cost_lv4,4) AS agent_cost_lv4_bet26_canonical,
      ROUND(e.agent_cost_lv5,4) AS agent_cost_lv5_bet27_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_lv1,4) AS net_margin_lv1_bet23_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_lv1)/NULLIF(e.stake,0),8) AS net_margin_lv1_bet23_rate_canonical,
      ROUND(e.agent_cost_chain_additive,4) AS agent_cost_chain_additive_canonical,
      ROUND(e.agent_cost_chain_nested,4) AS agent_cost_chain_nested_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_additive,4) AS net_margin_chain_additive_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_nested,4) AS net_margin_chain_nested_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_chain_additive)/NULLIF(e.stake,0),8) AS net_margin_chain_additive_rate_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_chain_nested)/NULLIF(e.stake,0),8) AS net_margin_chain_nested_rate_canonical,
       ROUND((-e.net-e.rebate-e.agent_cost_a_legacy)/NULLIF(e.stake,0),8) AS residual_a_rate,
           -- 二·分布层
           ROUND(e.stake/NULLIF(e.n_bets,0),4) AS avg_stake_per_bet,
           ROUND(e.valid/NULLIF(e.n_rounds,0),4) AS avg_valid_bet_per_round,
           ROUND(-e.net/NULLIF(e.n_rounds,0),4) AS avg_profit_per_round,
           ROUND(-e.net/NULLIF(e.active_days,0),4) AS avg_profit_per_day,
           ROUND(-e.net/NULLIF(e.active_shoes,0),4) AS avg_profit_per_shoe,
           ROUND(e.stake/NULLIF(e.active_days,0),4) AS avg_stake_per_active_day,
           ROUND(e.n_rounds*1.0/NULLIF(e.active_days,0),4) AS avg_rounds_per_active_day,
           ROUND(e.st_in/NULLIF(e.nb_in,0),4) AS avg_stake_recent,
           ROUND(e.st_out/NULLIF(e.nb_out,0),4) AS avg_stake_non_recent,
           ROUND(e.p25,4) AS p25_stake, ROUND(e.p50,4) AS p50_stake, ROUND(e.p75,4) AS p75_stake,
           ROUND(e.p90,4) AS p90_stake, ROUND(e.p95,4) AS p95_stake, ROUND(e.p99,4) AS p99_stake,
           ROUND(e.p50_valid,4) AS p50_valid_bet, ROUND(e.p50_profit,4) AS p50_profit,
           ROUND(e.p95/NULLIF(e.p50,0),6) AS p95_over_p50,
           ROUND(e.p99/NULLIF(e.p50,0),6) AS p99_over_p50,
           ROUND((e.stake/NULLIF(e.n_bets,0))/NULLIF(e.p50,0),6) AS avg_over_p50,
           -- 三·关系层
           e.n_tables AS common_table_count, e.n_dealers AS common_dealer_count,
           e.n_ips AS common_ip_count, e.n_products AS common_product_count,
           ROUND(e.st_in/NULLIF(e.stake,0),8) AS share_recent,
           -- 四·rate 层
           ROUND(-e.net/NULLIF(e.stake,0),8) AS hold_rate,
           ROUND(-e.net_in/NULLIF(e.st_in,0),8) AS hold_rate_recent,
           ROUND(e.rebate/NULLIF(e.valid,0),8) AS rebate_rate_actual,
           ROUND(e.rbpct,6) AS rebate_pct_config,
           ROUND(e.valid/NULLIF(e.stake,0),6) AS turnover_multiple,
           ROUND(e.freecomm_rate,6) AS free_comm_rate,
           ROUND(e.net_in/NULLIF(e.st_in,0)-e.net_out/NULLIF(e.st_out,0),8) AS roi_delta_recent,
           -- 五·动态层
           e.first_seen_d AS first_seen, e.last_seen_d AS last_seen,
           e.active_days, e.active_shoes, e.active_sessions,
           DATEDIFF(e.last_seen_d, e.first_seen_d)+1 AS span_days,
           ROUND(e.active_days*1.0/NULLIF(DATEDIFF(e.last_seen_d,e.first_seen_d)+1,0),6) AS persistence,
           ROUND((e.st_in/NULLIF(e.nb_in,0))/NULLIF(e.st_out/NULLIF(e.nb_out,0),0),6) AS ramp_recent_vs_prior,
           ROUND((e.st_rec/NULLIF(e.nb_rec,0))/NULLIF(e.stake/NULLIF(e.n_bets,0),0),6) AS ramp_recent_vs_all,
           ROUND((e.st_rec/NULLIF(e.stake,0))/0.30,6) AS stake_ramp,
           -- 六·决策层（HF9f · 详见档头【HF9f 变更说明】；本段两版逐字同一）
           NTILE(5) OVER (ORDER BY e.stake) AS vip_tier,                                                        -- 窗口取值：相对刻度 B 族，全体五等分；须连同下方血统五元组一并解读，禁作硬阈值判型
           PERCENT_RANK() OVER (ORDER BY -e.net-e.rebate-e.agent_cost)    AS economic_value,                    -- 窗口取值：HF9f·F-19 修正 —— HF9e 写作 -(-…) 双负号致方向颠倒（#075 实测 corr(economic_value, residual_b) = -1.0000）；今与 action_priority 排序键归一，值大即平台真净利高
           PERCENT_RANK() OVER (ORDER BY e.net/NULLIF(e.stake,0))         AS roi_pr_global,                     -- 窗口取值：HF9f·F-17 正名 —— 本列实为 ROI（玩家净回报率）之全体百分位，与「风险」无关；旧名 risk_value 见下一行
           PERCENT_RANK() OVER (ORDER BY e.net/NULLIF(e.stake,0))         AS risk_value,                        -- 窗口取值：兼容列，恒等于 roi_pr_global，仅为下游迁移窗保留；HF9g 起废弃，禁新引用
           PERCENT_RANK() OVER (ORDER BY e.stake)                         AS pr_stake,                          -- 窗口取值：兼容列，恒等于 pr_global，原名保留以免断链
           PERCENT_RANK() OVER (ORDER BY e.stake)                         AS pr_global,                         -- 窗口取值：HF9f·F-1 双轨之一 —— 全体口径百分位，参照总体即本件全部输出行
           CASE WHEN e.n_rounds >= 30                                                                           -- 条件分支：起始分支 —— 仅在合格子集内计算合格口径百分位
                  THEN PERCENT_RANK() OVER (PARTITION BY CASE WHEN e.n_rounds >= 30 THEN 1 ELSE 0 END ORDER BY e.stake)  -- 分支取值：以合格与否分区，故本值即 n_rounds>=30 子集内之百分位
                ELSE NULL END                                             AS pr_qualified,                      -- 条件分支：收束上方分支 —— 不合格者留 NULL（NULL＝未测，非 0），产出「pr_qualified」
           'n_rounds>=30'                                                 AS pr_qualified_population,           -- 字面取值：血统 —— 合格子集之定义
           COUNT(*) OVER ()                                               AS pr_global_population_n,            -- 窗口取值：血统 —— 全体口径之参照总体规模，渲染时现算，禁写死
           SUM(CASE WHEN e.n_rounds >= 30 THEN 1 ELSE 0 END) OVER ()      AS pr_qualified_population_n,         -- 窗口取值：血统 —— 合格子集之参照总体规模，现算，禁写死
           'PERCENT_RANK_OVER_ORDER_BY_e_stake'                           AS pr_calculation_method,             -- 字面取值：血统 —— 算法标识
           'HF9f'                                                         AS pr_calculation_version,            -- 字面取值：血统 —— 算法版本
           CASE WHEN e.n_rounds IS NULL OR e.n_rounds < 30 THEN 'THIN_ROUNDS' ELSE 'OK' END AS evidence_flag,   -- 条件分支：HF9f·F-2a 证据旗标 —— THIN_ROUNDS 者禁入执行队列，仅入观察队列
           CASE WHEN e.n_rounds IS NULL       THEN NULL                                                         -- 条件分支：起始分支 —— 未测者留 NULL（自家铁律：NULL ≠ 0）
                WHEN e.n_rounds >= 31483      THEN 'L1_POWERED'                                                 -- 分支判定：MDE 反解第一档
                WHEN e.n_rounds >= 15409      THEN 'L2_CI_1P5'                                                  -- 分支判定：MDE 反解第二档
                WHEN e.n_rounds >=  8668      THEN 'L3_CI_2P0'                                                  -- 分支判定：MDE 反解第三档
                WHEN e.n_rounds >=  3852      THEN 'L4_CI_3P0'                                                  -- 分支判定：MDE 反解第四档
                ELSE 'L5_INSUFFICIENT' END                                AS evidence_rate,                     -- 条件分支：收束上方 —— HF9f·F-3 证据分档，承 HF9e 前议之 MDE 反解五档，须于 F-4 敏感性实验后复核
           ROUND(1.96 * 0.95 / SQRT(NULLIF(CAST(e.n_rounds AS DOUBLE),0)),8) AS hold_ci_halfwidth_approx,       -- 比率表达式：HF9f·F-3 逐行现算之 95% 半宽近似；常数 0.95 为登记值，本轮 #075 实测每局 ROI 隐含 σ 于最薄层为 0.9249，二者差异待 F-4 裁定
           CASE WHEN e.stake IS NULL OR e.stake<=0 OR e.n_bets<30 OR e.n_rounds IS NULL OR e.n_rounds<30 THEN 'Z 证据不足 · 不动作'  -- 条件分支：HF9f·F-2 双条件取严 —— HF9e 仅卡 e.n_bets<30，致 n_bets>=30 而 n_rounds<30 者绕过 Z（#075 实测 18,537 名，其中 8,145 名已入 A/D 待裁）；今两条件并列取严
                WHEN PERCENT_RANK() OVER (ORDER BY -e.net-e.rebate-e.agent_cost)<=0.10                          -- 分支判定：平台真净利之最低十分位
                  THEN 'A 净亏最大十分位 · 优先复核'                                                             -- 分支取值：HF9f·F-20 正名 —— 本档 Σresidual_b 于 #075 实测 = -100,236,896，系平台净亏最大群，旧名「残值最低十分位 · 待裁」名实不符
                WHEN PERCENT_RANK() OVER (ORDER BY -e.net-e.rebate-e.agent_cost)>=0.80                          -- 分支判定：平台真净利之最高二十分位
                  THEN 'D 净利最高二十分位 · 优先留存'                                                           -- 分支取值：HF9f·F-20 正名 —— 本档 Σresidual_b 于 #075 实测 = +281,733,190，系核心利润源；与 A 档方向相反，旧版同标「待裁」属名实不符
                ELSE 'E 常规' END                                          AS action_priority                   -- 条件分支：收束上方判词，产出「action_priority」
    FROM q
    LEFT JOIN x_agg e ON CAST(e.x_key AS STRING) = CAST(q.`member_id` AS STRING)
  ) y
) z
-- ── 逐批 WHERE 阶梯（★ 口诀：上界 ＝ 下界 ＋ 100000，两数同进）──
--    本件 T_true 未测，无需先跑 T_true；以 0 / 100000 控制本批返回区间，末批由实际行数 < 100000 判定
--    WHERE z.audit_rn >        0 AND z.audit_rn <=   100000   -- 第 1 批
--    WHERE z.audit_rn >   100000 AND z.audit_rn <=   200000   -- 第 2 批
--    WHERE z.audit_rn >   200000 AND z.audit_rn <=   300000   -- 第 3 批
--    WHERE z.audit_rn >   300000 AND z.audit_rn <=   400000   -- 第 4 批
--    WHERE z.audit_rn >   400000 AND z.audit_rn <=   500000   -- 第 5 批
--    WHERE z.audit_rn >   500000 AND z.audit_rn <=   600000   -- 第 6 批
--    WHERE z.audit_rn >   600000 AND z.audit_rn <=   700000   -- 第 7 批
--    …余批类推。第 k 批：WHERE z.audit_rn > (k-1)*100000 AND z.audit_rn <= k*100000
--    某批返回 < 100000 行即为末批，其后不再取。
--
--    ⚠ 常见误写（务必避开）：只推下界而上界不动 ——
--        WHERE z.audit_rn > 100000 AND z.audit_rn <= 100000   ← 自相矛盾，恒为假，返回空集
--        WHERE z.audit_rn > 200000 AND z.audit_rn <= 100000   ← 同上，空集
--      两个数必须**同时**前进，且始终相差 100000。
--      下界 ＝ 上一批之上界；上界 ＝ 本批之上界。
WHERE z.audit_rn > 0 AND z.audit_rn <= 100000 -- ★ HF9c 本批区间
ORDER BY z.audit_rn;


-- ══════════════════════════════════════════════════════════════════════════════════════════════
--  84. T03_arbitrage.csv   [总包行 5204~5275 · 原 10 列 ＋六层约 60 列]
--     典型学：M02 对冲对打　派生旗标：hedge（h.n_side >= 2 · 仅供 CASE 条件聚合，全包无任何 WHERE/AND/HAVING 以此过滤）　连接：q.`member_id`
-- ══════════════════════════════════════════════════════════════════════════════════════════════
-- ── ① 先跑 T_true 留档（不足 100000 者一次导全，不必分批）──
-- ── ① T_true：HF9c 不再强制预跑完整 COUNT。
--    本批实际返回行数 < 100000 即判定为末批；全批完成后以各批 n_rows / audit_rn 范围核对总量。

-- ── ② 分批取数：第 1 批。第 k 批只改末行两数为 (k-1)*100000 与 k*100000 ──
--    审计字段二（REDTEAM 2026-08-24 裁定 · 四锁）：
--      audit_rn  全局观测坐标 —— 由**与原版审计版逐字同一**之排序键所生，两版可逐行对账
--      batch_id  物理分批信息 —— 该行所属批次，由 audit_rn 算得，非引擎所赋
--    ★ 锁三：二者皆为审计字段，**不得进入任何业务指标计算**。
--    ★ 锁四：两版经 audit_rn 逐行字段核验后，方可宣布输出完全一致。

-- ── ③ 每批取回后自证四数（任一不符即停手回报，禁止放行）──
--    n_rows        = COUNT(*)      须等于 COUNT(DISTINCT audit_rn)   （批内无重复）
--    audit_rn_min  = MIN(audit_rn) 须等于 (k-1)*100000 + 1           （与上批严丝合缝）
--    audit_rn_max  = MAX(audit_rn) 须等于 min + n_rows - 1           （批内无缺口）
--    全批取毕再验：各批 audit_rn 之并集 = 1 .. T_true，无缺号、无重号。
--     ★ 首行＝平台真净亏最多者（已扣退水与代理占成）。
--
SELECT z.*,
       CAST(FLOOR((z.audit_rn - 1) / 100000) + 1 AS INT)          AS batch_id,
       'A168_HF9F_20260827_0900' AS run_id,
       '2026-08-27 09:00:00' AS snapshot_sync_time
FROM (
  SELECT y.*,
         ROW_NUMBER() OVER (ORDER BY y.`residual_b` ASC, y.`roi` DESC, y.`member_id`, y.`stake`, y.`validbet`, y.`game_pnl`, y.`net_pnl`, y.`rebate`, y.`hedge_rate`, y.`stake_cv`, y.`n_rounds`, y.`n_days`) AS audit_rn
  FROM (
    WITH
      x_ranked AS (
    SELECT b.bet01, b.bet03, b.bet04, b.bet05, b.bet09, b.bet11, b.bet13,
           b.bet15, b.bet16, b.bet17, b.bet18, b.bet19, b.bet20, b.bet21,
           b.bet22, b.bet23, b.bet24, b.bet25, b.bet26, b.bet27, b.bet38, b.bet39, b.category, b.commission,
           b.dt, b.eid, b.ip, b.validbet, b.updatetime, b.sync_time,
           ROW_NUMBER() OVER (
             PARTITION BY b.bet01
             ORDER BY b.updatetime DESC, b.sync_time DESC, b.dt DESC)      AS x_rn
    FROM ods_mariadb_2b.ods_a168_bet02 b
    WHERE b.dt >= '2026-03-21' AND b.dt < '2026-08-07'
      AND b.bet02 = '101'
      AND b.sync_time <= '2026-08-27 09:00:00'
  ),
    x_testagent AS (
    SELECT age001 AS agent_id FROM ods_mariadb_2b.ods_a168_agent WHERE age022 = '1'
  ),
    x_bs0 AS (
    SELECT b.bet05 AS x_member, b.eid AS x_dealer, b.bet39 AS x_table,
           b.bet03 AS x_shoe, b.ip AS x_ip, b.bet09 AS x_product, b.dt AS x_date,
           CONCAT_WS('|', b.bet03, b.bet04, b.bet39)                      AS x_round,
           CONCAT_WS('|', b.bet39, b.bet03)                               AS x_tblshoe,
           CAST(NULLIF(TRIM(b.bet04),'') AS INT)                          AS x_rno,
           CASE WHEN b.dt >= '2026-07-08' THEN 1 ELSE 0 END               AS x_rec,
           CASE WHEN TRIM(b.commission)='1' THEN 1 ELSE 0 END             AS x_freecomm,
           CAST(NULLIF(TRIM(b.bet13),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_stake,
           CAST(NULLIF(TRIM(b.validbet),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_valid,
           CAST(NULLIF(TRIM(b.bet16),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_rebate,
           CAST(NULLIF(TRIM(b.bet17),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_net,
           CAST(NULLIF(TRIM(b.bet15),'') AS DECIMAL(20,6))                AS x_rbpct,
           COALESCE(CAST(NULLIF(TRIM(b.bet23),'') AS DECIMAL(20,6)),0)   AS x_agpct,
          NULLIF(CAST(NULLIF(TRIM(b.bet23),'') AS DECIMAL(20,6)),0)     AS x_rate1,
          NULLIF(CAST(NULLIF(TRIM(b.bet24),'') AS DECIMAL(20,6)),0)     AS x_rate2,
          NULLIF(CAST(NULLIF(TRIM(b.bet25),'') AS DECIMAL(20,6)),0)     AS x_rate3,
          NULLIF(CAST(NULLIF(TRIM(b.bet26),'') AS DECIMAL(20,6)),0)     AS x_rate4,
          NULLIF(CAST(NULLIF(TRIM(b.bet27),'') AS DECIMAL(20,6)),0)     AS x_rate5,
          (CASE WHEN NULLIF(CAST(NULLIF(TRIM(b.bet22),'') AS BIGINT),0) IS NOT NULL THEN 5
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet21),'') AS BIGINT),0) IS NOT NULL THEN 4
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet20),'') AS BIGINT),0) IS NOT NULL THEN 3
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet19),'') AS BIGINT),0) IS NOT NULL THEN 2
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet18),'') AS BIGINT),0) IS NOT NULL THEN 1
                ELSE 0 END)                                             AS x_chain_depth,
           CASE WHEN COALESCE(t1.agent_id,t2.agent_id,t3.agent_id,
                              t4.agent_id,t5.agent_id) IS NOT NULL
                THEN 1 ELSE 0 END                                        AS f_testline
    FROM x_ranked b
    LEFT JOIN x_testagent t1 ON t1.agent_id = b.bet18
    LEFT JOIN x_testagent t2 ON t2.agent_id = b.bet19
    LEFT JOIN x_testagent t3 ON t3.agent_id = b.bet20
    LEFT JOIN x_testagent t4 ON t4.agent_id = b.bet21
    LEFT JOIN x_testagent t5 ON t5.agent_id = b.bet22
    WHERE b.x_rn = 1
      AND b.category='1' AND UPPER(TRIM(b.bet38))='N'
      AND CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8)) > 0
  ),
  x_mk AS (
    SELECT s.*,
           CASE WHEN s.f_testline = 0 THEN 1 ELSE 0 END                 AS is_clean
    FROM x_bs0 s
  ),
  x_hg AS (SELECT x_round, COUNT(DISTINCT x_product) AS n_side FROM x_mk WHERE is_clean = 1 GROUP BY x_round),
  x_agg AS (
    SELECT s.x_member                                                        AS x_key,
           COUNT(*) AS n_bets, COUNT(DISTINCT s.x_round) AS n_rounds,
           COUNT(DISTINCT s.x_date) AS active_days, COUNT(DISTINCT s.x_tblshoe) AS active_shoes,
           COUNT(DISTINCT CONCAT_WS('|', s.x_date, s.x_table)) AS active_sessions,
           COUNT(DISTINCT s.x_table) AS n_tables, COUNT(DISTINCT s.x_dealer) AS n_dealers,
           COUNT(DISTINCT s.x_ip) AS n_ips, COUNT(DISTINCT s.x_product) AS n_products,
           MIN(s.x_date) AS first_seen_d, MAX(s.x_date) AS last_seen_d,
           SUM(s.x_stake) AS stake, SUM(s.x_valid) AS valid, SUM(s.x_rebate) AS rebate,
           SUM(s.x_net) AS net, SUM(-s.x_net *(100.0-s.x_agpct)/100.0) AS agent_cost,
           AVG(100.0-s.x_agpct)                   AS agent_pct,
           AVG(s.x_agpct)                         AS company_retain_pct,
           SUM(-s.x_net *s.x_agpct/100.0)         AS agent_cost_a_legacy,
           SUM(s.x_valid*s.x_agpct/100.0)         AS agent_cost_valid_base_legacy,
          AVG(COALESCE(s.x_rate1,100)) AS retain_pct_lv1, AVG(COALESCE(s.x_rate2,100)) AS retain_pct_lv2,
          AVG(COALESCE(s.x_rate3,100)) AS retain_pct_lv3, AVG(COALESCE(s.x_rate4,100)) AS retain_pct_lv4,
          AVG(COALESCE(s.x_rate5,100)) AS retain_pct_lv5, AVG(s.x_chain_depth) AS chain_depth_avg,
          AVG(COALESCE(100.0-s.x_rate1,0)) AS agent_pct_lv1, AVG(COALESCE(100.0-s.x_rate2,0)) AS agent_pct_lv2,
          AVG(COALESCE(100.0-s.x_rate3,0)) AS agent_pct_lv3, AVG(COALESCE(100.0-s.x_rate4,0)) AS agent_pct_lv4,
          AVG(COALESCE(100.0-s.x_rate5,0)) AS agent_pct_lv5,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate1,0)/100.0)                        AS agent_cost_lv1,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate2,0)/100.0)                        AS agent_cost_lv2,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate3,0)/100.0)                        AS agent_cost_lv3,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate4,0)/100.0)                        AS agent_cost_lv4,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate5,0)/100.0)                        AS agent_cost_lv5,
          SUM(-s.x_net*(COALESCE(100.0-s.x_rate1,0)+COALESCE(100.0-s.x_rate2,0)
                       +COALESCE(100.0-s.x_rate3,0)+COALESCE(100.0-s.x_rate4,0)
                       +COALESCE(100.0-s.x_rate5,0))/100.0)                   AS agent_cost_chain_additive,
          SUM(-s.x_net*(1.0 - CAST(COALESCE(s.x_rate1,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate2,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate3,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate4,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate5,100) AS DOUBLE)/100.0))
                                                                       AS agent_cost_chain_nested,
           AVG(s.x_rbpct) AS rbpct, AVG(s.x_freecomm*1.0) AS freecomm_rate,
           PERCENTILE_APPROX(s.x_stake,0.25) AS p25, PERCENTILE_APPROX(s.x_stake,0.50) AS p50,
           PERCENTILE_APPROX(s.x_stake,0.75) AS p75, PERCENTILE_APPROX(s.x_stake,0.90) AS p90,
           PERCENTILE_APPROX(s.x_stake,0.95) AS p95, PERCENTILE_APPROX(s.x_stake,0.99) AS p99,
           PERCENTILE_APPROX(s.x_valid,0.50) AS p50_valid,
           PERCENTILE_APPROX(s.x_net,0.50)   AS p50_profit,
           SUM(CASE WHEN h.n_side >= 2 THEN s.x_stake ELSE 0 END) AS st_in,
           SUM(CASE WHEN h.n_side >= 2 THEN 1 ELSE 0 END)         AS nb_in,
           SUM(CASE WHEN h.n_side >= 2 THEN s.x_net ELSE 0 END)   AS net_in,
           SUM(CASE WHEN NOT (h.n_side >= 2) THEN s.x_stake ELSE 0 END) AS st_out,
           SUM(CASE WHEN NOT (h.n_side >= 2) THEN 1 ELSE 0 END)         AS nb_out,
           SUM(CASE WHEN NOT (h.n_side >= 2) THEN s.x_net ELSE 0 END)   AS net_out,
           SUM(CASE WHEN s.x_rec=1 THEN s.x_stake ELSE 0 END) AS st_rec,
           SUM(CASE WHEN s.x_rec=1 THEN 1 ELSE 0 END)         AS nb_rec
    FROM x_mk s
    JOIN x_hg h ON h.x_round = s.x_round
    WHERE s.is_clean = 1
      AND s.x_member IS NOT NULL AND TRIM(CAST(s.x_member AS STRING)) <> ''
    GROUP BY s.x_member
  ),
      q AS (
        WITH test_agents AS (                                                                               -- 公共表表达式：开启中间结果集 test_agents，其后各行为其定义体（§T03）
          SELECT age001 AS agent_id FROM ods_mariadb_2b.ods_a168_agent WHERE age022 = '1'                   -- 取列：取用代理主档（五级代理线归属来源），产出「agent_id」
        ),                                                                                                  -- 续行：收束上方的子查询或函数括号（§T03）
        ranked AS (                                                                                         -- 公共表表达式：开启中间结果集 ranked，其后各行为其定义体（§T03）
          SELECT b.bet01, b.updatetime, b.sync_time, b.dt, b.bet02,                                         -- 取列：起始取列子句，本行先列 b.bet01, b.updatetime, b.sync_time, b.dt, b.bet02，涉 bet02（游戏类别）、dt（营业日）
                 b.bet03, b.bet04, b.bet05, b.bet09, b.bet11,                                               -- 续行：接续上一取列子句，续列 b.bet03, b.bet04, b.bet05, b.bet09, b.bet11，涉 bet03（靴号）、bet04（局内序号）、bet05（会员号）
                 b.bet13, b.bet14, b.bet16, b.bet17, b.bet18,                                               -- 续行：接续上一取列子句，续列 b.bet13, b.bet14, b.bet16, b.bet17, b.bet18，涉 bet13（下注金额）、bet14（派彩金额）、bet16（退水金额）
                 b.bet19, b.bet20, b.bet21, b.bet22, b.bet38,                                               -- 续行：接续上一取列子句，续列 b.bet19, b.bet20, b.bet21, b.bet22, b.bet38，涉 bet19（二级代理线）、bet20（三级代理线）、bet21（四级代理线）
                 b.bet39, b.category, b.validbet,                                                           -- 续行：接续上一取列子句，续列 b.bet39, b.category, b.validbet，涉 bet39（桌号）、validbet（有效投注（洗码量））
                 ROW_NUMBER() OVER (                                                                        -- 行号窗口表达式：以行号窗口取每组头部或去重，免出重复行
                   PARTITION BY b.bet01                                                                     -- 窗口分区：按 b.bet01 分组开窗，组内各自编号或排名
                   ORDER BY b.updatetime DESC, b.sync_time DESC, b.dt DESC) AS rn                           -- 排序：按 b.updatetime（降序）, b.sync_time（降序）, b.dt（降序）) AS rn 排列；导出必带排序，否则分页无稳定序（曾致 36.49% 重复行）
          FROM ods_mariadb_2b.ods_a168_bet02 b            -- ★ 表名开关
          WHERE b.dt >= '2026-03-21' AND b.dt < '2026-08-07'                                                -- 过滤条件：限定 b.dt不少于 '2026-03-21'、b.dt小于 '2026-08-07'，涉 dt（营业日）
            AND b.bet02 = '101'
      AND b.sync_time <= '2026-08-27 09:00:00'                                                                             -- 并列条件：限定 b.bet02等于 '101'，涉 bet02（游戏类别）
        ),                                                                                                  -- 续行：收束上方的子查询或函数括号（§T03）
        ord AS (                                                                                            -- 公共表表达式：开启中间结果集 ord，其后各行为其定义体（§T03）
          SELECT r.bet05 AS member_id, r.dt AS bet_date, r.bet09 AS bet_side,                               -- 取列：起始取列子句，本行先取「bet_side」，涉 bet05（会员号）、bet09（玩法）、dt（营业日）
                 CONCAT_WS('|', r.bet03, r.bet04, r.bet39) AS round_key,                                    -- 取值表达式：取用 bet03（靴号）、bet04（局内序号）、bet39（桌号），产出「round_key」
                 CAST(NULLIF(TRIM(r.bet11),'') AS DECIMAL(20,8)) AS fx,                                     -- 取值表达式：先去空白、空串归 NULL，再显式转型——本库字段多为 varchar，不转型即比较失真，产出「fx」
                 CAST(NULLIF(TRIM(r.bet13),'') AS DECIMAL(20,4)) AS stake_raw,                              -- 取值表达式：先去空白、空串归 NULL，再显式转型——本库字段多为 varchar，不转型即比较失真，产出「stake_raw」
                 CAST(NULLIF(TRIM(r.bet14),'') AS DECIMAL(20,4)) AS payout_raw,                             -- 取值表达式：先去空白、空串归 NULL，再显式转型——本库字段多为 varchar，不转型即比较失真，产出「payout_raw」
                 CAST(NULLIF(TRIM(r.bet16),'') AS DECIMAL(20,4)) AS rebate_raw,                             -- 取值表达式：先去空白、空串归 NULL，再显式转型——本库字段多为 varchar，不转型即比较失真，产出「rebate_raw」
                 CAST(NULLIF(TRIM(r.bet17),'') AS DECIMAL(20,4)) AS net_raw,                                -- 取值表达式：先去空白、空串归 NULL，再显式转型——本库字段多为 varchar，不转型即比较失真，产出「net_raw」
                 CAST(NULLIF(TRIM(r.validbet),'') AS DECIMAL(20,4)) AS vb_raw                               -- 取值表达式：先去空白、空串归 NULL，再显式转型——本库字段多为 varchar，不转型即比较失真，产出「vb_raw」
          FROM ranked r                                                                                     -- 取数来源：取自本条自建的中间结果集 ranked
          LEFT JOIN test_agents t1 ON t1.agent_id = r.bet18                                                 -- 左连接：取自本条自建的中间结果集 test_agents，连接键为 bet18（一级代理线）
          LEFT JOIN test_agents t2 ON t2.agent_id = r.bet19                                                 -- 左连接：取自本条自建的中间结果集 test_agents，连接键为 bet19（二级代理线）
          LEFT JOIN test_agents t3 ON t3.agent_id = r.bet20                                                 -- 左连接：取自本条自建的中间结果集 test_agents，连接键为 bet20（三级代理线）
          LEFT JOIN test_agents t4 ON t4.agent_id = r.bet21                                                 -- 左连接：取自本条自建的中间结果集 test_agents，连接键为 bet21（四级代理线）
          LEFT JOIN test_agents t5 ON t5.agent_id = r.bet22                                                 -- 左连接：取自本条自建的中间结果集 test_agents，连接键为 bet22（五级代理线）
          WHERE r.rn = 1 AND r.category = '1' AND UPPER(TRIM(r.bet38)) = 'N'                                -- 过滤条件：限定 r.rn等于 1、r.category等于 '1'、UPPER(TRIM(r.bet38))等于 'N'，涉 bet38（重對）
            AND CAST(NULLIF(TRIM(r.bet05),'') AS BIGINT) > 0                                                -- 并列条件：限定 CAST(NULLIF(TRIM(r.bet05),'') AS BIGINT)大于 0，涉 bet05（会员号）
            AND CAST(NULLIF(TRIM(r.bet11),'') AS DECIMAL(20,8)) > 0                                         -- 并列条件：限定 CAST(NULLIF(TRIM(r.bet11),'') AS DECIMAL(20,8))大于 0，涉 bet11（汇率）
            AND COALESCE(t1.agent_id,t2.agent_id,t3.agent_id,t4.agent_id,t5.agent_id) IS NULL               -- 并列条件：限定该值为空——本包以左连接加空值判定替代 EXISTS，因 StarRocks 不支持 EXISTS 配多列 IN
        ),                                                                                                  -- 续行：收束上方的子查询或函数括号（§T03）
        o2 AS (                                                                                             -- 公共表表达式：开启中间结果集 o2，其后各行为其定义体（§T03）
          SELECT member_id, bet_date, round_key,                                                            -- 取列：起始取列子句，本行先列 member_id, bet_date, round_key，涉 round_key（局键）、member_id（会员号）、bet_date（营业日）
                 stake_raw / fx                AS stake,                                                    -- 取值表达式：取用 stake（下注额（经汇率归一化）），产出「stake」
                 COALESCE(vb_raw,stake_raw)/fx AS validbet,                                                 -- 取值表达式：取用 validbet（有效投注（洗码量）），产出「validbet」
                 (payout_raw - stake_raw)/fx   AS game_pnl,                                                 -- 续行：取用 game_pnl（游戏净输赢），产出「game_pnl」
                 rebate_raw / fx               AS rebate,                                                   -- 取值表达式：取用 rebate（退水），产出「rebate」
                 net_raw / fx                  AS net_pnl,                                                  -- 取值表达式：取用 net_pnl（会员净输赢），产出「net_pnl」
                 /* ★ 2026-08-07 DX-01 实测校准：bet09 为英文玩法名。
                    必须用等值匹配，不能用 LIKE '%BANK%' —— 后者会把
                    BankerDragonBonus(20.7万) 与 BankerNatural(6.2万) 一并算成庄，
                    而那是边注，与主线庄闲不构成对冲关系。 */
                 CASE WHEN TRIM(bet_side) = 'Banker' THEN 1 ELSE 0 END AS is_b,                             -- 条件分支：产出「is_b」
                 CASE WHEN TRIM(bet_side) = 'Player' THEN 1 ELSE 0 END AS is_p                              -- 条件分支：产出「is_p」
          FROM ord                                                                                          -- 取数来源：取自本条自建的中间结果集 ord
        ),                                                                                                  -- 续行：收束上方的子查询或函数括号（§T03）
        rk AS (      -- 局级：该会员本局是否同时押了庄与闲（自对押）
          SELECT member_id, bet_date, round_key,                                                            -- 取列：起始取列子句，本行先列 member_id, bet_date, round_key，涉 round_key（局键）、member_id（会员号）、bet_date（营业日）
                 SUM(stake) AS stake, SUM(validbet) AS validbet,                                            -- 汇总表达式：取用 stake（下注额（经汇率归一化））、validbet（有效投注（洗码量）），产出「validbet」
                 SUM(game_pnl) AS game_pnl, SUM(rebate) AS rebate, SUM(net_pnl) AS net_pnl,                 -- 汇总表达式：取用 net_pnl（会员净输赢）、game_pnl（游戏净输赢）、rebate（退水），产出「net_pnl」
                 CASE WHEN MAX(is_b)=1 AND MAX(is_p)=1 THEN 1 ELSE 0 END AS is_self_hedge                   -- 条件分支：取最大值，产出「is_self_hedge」
          FROM o2 GROUP BY member_id, bet_date, round_key                                                   -- 取数来源：取自本条自建的中间结果集 o2
        )                                                                                                   -- 续行：收束上方的子查询或函数括号（§T03）
        SELECT member_id,                                                                                   -- 取列：起始取列子句，本行先列 member_id，涉 member_id（会员号）
               SUM(stake)                          AS stake,                                                -- 汇总表达式：取用 stake（下注额（经汇率归一化）），产出「stake」
               SUM(validbet)                       AS validbet,                                             -- 汇总表达式：取用 validbet（有效投注（洗码量）），产出「validbet」
               SUM(game_pnl)                       AS game_pnl,                                             -- 汇总表达式：取用 game_pnl（游戏净输赢），产出「game_pnl」
               SUM(net_pnl)                        AS net_pnl,                                              -- 汇总表达式：取用 net_pnl（会员净输赢），产出「net_pnl」
               SUM(rebate)                         AS rebate,                                               -- 汇总表达式：取用 rebate（退水），产出「rebate」
               SUM(is_self_hedge) * 1.0 / COUNT(*) AS hedge_rate,     -- 自对押率
               STDDEV_SAMP(stake) / NULLIF(AVG(stake),0) AS stake_cv, -- 注额变异系数（打水者极低）
               COUNT(*)                            AS n_rounds,                                             -- 计数表达式：产出「n_rounds」
               COUNT(DISTINCT bet_date)            AS n_days                                                -- 计数表达式：统计去重个数，产出「n_days」
        FROM rk                                                                                             -- 取数来源：取自本条自建的中间结果集 rk
        GROUP BY member_id                                                                                  -- 分组：按 member_id 汇总
        HAVING COUNT(*) >= 100                       -- 局数太少算不出稳定的比率
      )
    SELECT q.*,
           -- 一·经济层
           ROUND(e.stake,4) AS stake_xagg, ROUND(e.valid,4) AS valid_bet,
           ROUND(-e.net,4) AS profit, e.n_bets, e.n_rounds AS n_rounds_xagg,
           ROUND(e.net/NULLIF(e.stake,0),8) AS roi,
           ROUND(e.net_in/NULLIF(e.st_in,0),8) AS roi_hedge,
           ROUND(e.net_out/NULLIF(e.st_out,0),8) AS roi_non_hedge,
           ROUND((e.net-e.rebate)/NULLIF(e.stake,0),8) AS roi_ex_rebate,
           ROUND(e.net,4) AS roi_numerator, ROUND(e.stake,4) AS roi_denominator,
           CASE WHEN e.stake IS NULL THEN 'NULL_DENOM' WHEN e.stake<=0 THEN 'ZERO_DENOM'
                WHEN e.n_bets<30 THEN 'THIN_EXPOSURE' ELSE 'OK' END AS roi_denominator_status,
           ROUND(e.rebate,4) AS rebate_cost, ROUND(e.agent_cost,4)                           AS cost_complement_b,
       ROUND(e.agent_pct,4)                            AS pct_complement,
       ROUND(e.company_retain_pct,4)                   AS pct_top_bet23,
       'AG03-UNRESOLVED'                                     AS agent_formula_version,
      'ALL5_LEVELS_bet23_to_bet27'                    AS agent_level_scope,
      ROUND(e.agent_cost_lv1,4) AS agent_cost_lv1, ROUND(e.agent_cost_lv2,4) AS agent_cost_lv2,
      ROUND(e.agent_cost_lv3,4) AS agent_cost_lv3, ROUND(e.agent_cost_lv4,4) AS agent_cost_lv4,
      ROUND(e.agent_cost_lv5,4) AS agent_cost_lv5,
      ROUND(e.agent_pct_lv1,6) AS agent_pct_lv1, ROUND(e.agent_pct_lv2,6) AS agent_pct_lv2,
      ROUND(e.agent_pct_lv3,6) AS agent_pct_lv3, ROUND(e.agent_pct_lv4,6) AS agent_pct_lv4,
      ROUND(e.agent_pct_lv5,6) AS agent_pct_lv5,
      ROUND(e.retain_pct_lv1,6) AS retain_pct_lv1, ROUND(e.retain_pct_lv2,6) AS retain_pct_lv2,
      ROUND(e.retain_pct_lv3,6) AS retain_pct_lv3, ROUND(e.retain_pct_lv4,6) AS retain_pct_lv4,
      ROUND(e.retain_pct_lv5,6) AS retain_pct_lv5, ROUND(e.chain_depth_avg,4) AS chain_depth_avg,
      ROUND(e.agent_cost_chain_additive,4)            AS agent_cost_chain_additive,
      ROUND(e.agent_cost_chain_nested,4)              AS agent_cost_chain_nested,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_additive,4) AS residual_chain_additive,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_nested,4)   AS residual_chain_nested,
      'PENDING_AG03'                                  AS decision_status,
      'FALSE'                                         AS admit_to_risk_decision,
      'NOT_FOR_ENFORCEMENT'                           AS deliverable_class,
       ROUND(e.agent_cost_a_legacy,4)                  AS agent_cost_a_legacy,
       ROUND(e.agent_cost_valid_base_legacy,4)         AS agent_cost_valid_base_legacy,
           ROUND(-e.net-e.rebate,4)                        AS ngr,
       ROUND(-e.net-e.rebate-e.agent_cost,4)           AS residual_b,
       ROUND(-e.net-e.rebate-e.agent_cost_a_legacy,4)  AS residual_a,
           ROUND((-e.net-e.rebate)/NULLIF(e.stake,0),8)    AS ngr_rate,
       ROUND((-e.net-e.rebate-e.agent_cost)/NULLIF(e.stake,0),8)   AS residual_b_rate,
      -- 【HF9c · canonical accounting contract】
      --   以下 canonical 字段只增加明确 scope；不删除、不覆盖既有字段。
      --   formal_bet23_* 保持 HF9b 当前生产公式及其 NULL/0 语义；
      --   lv1~lv5 / additive / nested 则分别采用各自原始 e.* 成本字段，
      --   rate 一律从未舍入的 e.* 分子 / e.stake 计算，禁止由展示值反算。
      ROUND(e.agent_cost,4) AS agent_cost_bet23_formal_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost,4) AS net_margin_bet23_formal_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost)/NULLIF(e.stake,0),8) AS net_margin_bet23_formal_rate_canonical,
      ROUND(e.agent_cost_lv1,4) AS agent_cost_lv1_bet23_canonical,
      ROUND(e.agent_cost_lv2,4) AS agent_cost_lv2_bet24_canonical,
      ROUND(e.agent_cost_lv3,4) AS agent_cost_lv3_bet25_canonical,
      ROUND(e.agent_cost_lv4,4) AS agent_cost_lv4_bet26_canonical,
      ROUND(e.agent_cost_lv5,4) AS agent_cost_lv5_bet27_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_lv1,4) AS net_margin_lv1_bet23_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_lv1)/NULLIF(e.stake,0),8) AS net_margin_lv1_bet23_rate_canonical,
      ROUND(e.agent_cost_chain_additive,4) AS agent_cost_chain_additive_canonical,
      ROUND(e.agent_cost_chain_nested,4) AS agent_cost_chain_nested_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_additive,4) AS net_margin_chain_additive_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_nested,4) AS net_margin_chain_nested_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_chain_additive)/NULLIF(e.stake,0),8) AS net_margin_chain_additive_rate_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_chain_nested)/NULLIF(e.stake,0),8) AS net_margin_chain_nested_rate_canonical,
       ROUND((-e.net-e.rebate-e.agent_cost_a_legacy)/NULLIF(e.stake,0),8) AS residual_a_rate,
           -- 二·分布层
           ROUND(e.stake/NULLIF(e.n_bets,0),4) AS avg_stake_per_bet,
           ROUND(e.valid/NULLIF(e.n_rounds,0),4) AS avg_valid_bet_per_round,
           ROUND(-e.net/NULLIF(e.n_rounds,0),4) AS avg_profit_per_round,
           ROUND(-e.net/NULLIF(e.active_days,0),4) AS avg_profit_per_day,
           ROUND(-e.net/NULLIF(e.active_shoes,0),4) AS avg_profit_per_shoe,
           ROUND(e.stake/NULLIF(e.active_days,0),4) AS avg_stake_per_active_day,
           ROUND(e.n_rounds*1.0/NULLIF(e.active_days,0),4) AS avg_rounds_per_active_day,
           ROUND(e.st_in/NULLIF(e.nb_in,0),4) AS avg_stake_hedge,
           ROUND(e.st_out/NULLIF(e.nb_out,0),4) AS avg_stake_non_hedge,
           ROUND(e.p25,4) AS p25_stake, ROUND(e.p50,4) AS p50_stake, ROUND(e.p75,4) AS p75_stake,
           ROUND(e.p90,4) AS p90_stake, ROUND(e.p95,4) AS p95_stake, ROUND(e.p99,4) AS p99_stake,
           ROUND(e.p50_valid,4) AS p50_valid_bet, ROUND(e.p50_profit,4) AS p50_profit,
           ROUND(e.p95/NULLIF(e.p50,0),6) AS p95_over_p50,
           ROUND(e.p99/NULLIF(e.p50,0),6) AS p99_over_p50,
           ROUND((e.stake/NULLIF(e.n_bets,0))/NULLIF(e.p50,0),6) AS avg_over_p50,
           -- 三·关系层
           e.n_tables AS common_table_count, e.n_dealers AS common_dealer_count,
           e.n_ips AS common_ip_count, e.n_products AS common_product_count,
           ROUND(e.st_in/NULLIF(e.stake,0),8) AS share_hedge,
           -- 四·rate 层
           ROUND(-e.net/NULLIF(e.stake,0),8) AS hold_rate,
           ROUND(-e.net_in/NULLIF(e.st_in,0),8) AS hold_rate_hedge,
           ROUND(e.rebate/NULLIF(e.valid,0),8) AS rebate_rate_actual,
           ROUND(e.rbpct,6) AS rebate_pct_config,
           ROUND(e.valid/NULLIF(e.stake,0),6) AS turnover_multiple,
           ROUND(e.freecomm_rate,6) AS free_comm_rate,
           ROUND(e.net_in/NULLIF(e.st_in,0)-e.net_out/NULLIF(e.st_out,0),8) AS roi_delta_hedge,
           -- 五·动态层
           e.first_seen_d AS first_seen, e.last_seen_d AS last_seen,
           e.active_days, e.active_shoes, e.active_sessions,
           DATEDIFF(e.last_seen_d, e.first_seen_d)+1 AS span_days,
           ROUND(e.active_days*1.0/NULLIF(DATEDIFF(e.last_seen_d,e.first_seen_d)+1,0),6) AS persistence,
           ROUND((e.st_in/NULLIF(e.nb_in,0))/NULLIF(e.st_out/NULLIF(e.nb_out,0),0),6) AS ramp_hedge,
           ROUND((e.st_rec/NULLIF(e.nb_rec,0))/NULLIF(e.stake/NULLIF(e.n_bets,0),0),6) AS ramp_recent,
           ROUND((e.st_rec/NULLIF(e.stake,0))/0.30,6) AS stake_ramp,
           -- 六·决策层（HF9f · 详见档头【HF9f 变更说明】；本段两版逐字同一）
           NTILE(5) OVER (ORDER BY e.stake) AS vip_tier,                                                        -- 窗口取值：相对刻度 B 族，全体五等分；须连同下方血统五元组一并解读，禁作硬阈值判型
           PERCENT_RANK() OVER (ORDER BY -e.net-e.rebate-e.agent_cost)    AS economic_value,                    -- 窗口取值：HF9f·F-19 修正 —— HF9e 写作 -(-…) 双负号致方向颠倒（#075 实测 corr(economic_value, residual_b) = -1.0000）；今与 action_priority 排序键归一，值大即平台真净利高
           PERCENT_RANK() OVER (ORDER BY e.net/NULLIF(e.stake,0))         AS roi_pr_global,                     -- 窗口取值：HF9f·F-17 正名 —— 本列实为 ROI（玩家净回报率）之全体百分位，与「风险」无关；旧名 risk_value 见下一行
           PERCENT_RANK() OVER (ORDER BY e.net/NULLIF(e.stake,0))         AS risk_value,                        -- 窗口取值：兼容列，恒等于 roi_pr_global，仅为下游迁移窗保留；HF9g 起废弃，禁新引用
           PERCENT_RANK() OVER (ORDER BY e.stake)                         AS pr_stake,                          -- 窗口取值：兼容列，恒等于 pr_global，原名保留以免断链
           PERCENT_RANK() OVER (ORDER BY e.stake)                         AS pr_global,                         -- 窗口取值：HF9f·F-1 双轨之一 —— 全体口径百分位，参照总体即本件全部输出行
           CASE WHEN e.n_rounds >= 30                                                                           -- 条件分支：起始分支 —— 仅在合格子集内计算合格口径百分位
                  THEN PERCENT_RANK() OVER (PARTITION BY CASE WHEN e.n_rounds >= 30 THEN 1 ELSE 0 END ORDER BY e.stake)  -- 分支取值：以合格与否分区，故本值即 n_rounds>=30 子集内之百分位
                ELSE NULL END                                             AS pr_qualified,                      -- 条件分支：收束上方分支 —— 不合格者留 NULL（NULL＝未测，非 0），产出「pr_qualified」
           'n_rounds>=30'                                                 AS pr_qualified_population,           -- 字面取值：血统 —— 合格子集之定义
           COUNT(*) OVER ()                                               AS pr_global_population_n,            -- 窗口取值：血统 —— 全体口径之参照总体规模，渲染时现算，禁写死
           SUM(CASE WHEN e.n_rounds >= 30 THEN 1 ELSE 0 END) OVER ()      AS pr_qualified_population_n,         -- 窗口取值：血统 —— 合格子集之参照总体规模，现算，禁写死
           'PERCENT_RANK_OVER_ORDER_BY_e_stake'                           AS pr_calculation_method,             -- 字面取值：血统 —— 算法标识
           'HF9f'                                                         AS pr_calculation_version,            -- 字面取值：血统 —— 算法版本
           CASE WHEN e.n_rounds IS NULL OR e.n_rounds < 30 THEN 'THIN_ROUNDS' ELSE 'OK' END AS evidence_flag,   -- 条件分支：HF9f·F-2a 证据旗标 —— THIN_ROUNDS 者禁入执行队列，仅入观察队列
           CASE WHEN e.n_rounds IS NULL       THEN NULL                                                         -- 条件分支：起始分支 —— 未测者留 NULL（自家铁律：NULL ≠ 0）
                WHEN e.n_rounds >= 31483      THEN 'L1_POWERED'                                                 -- 分支判定：MDE 反解第一档
                WHEN e.n_rounds >= 15409      THEN 'L2_CI_1P5'                                                  -- 分支判定：MDE 反解第二档
                WHEN e.n_rounds >=  8668      THEN 'L3_CI_2P0'                                                  -- 分支判定：MDE 反解第三档
                WHEN e.n_rounds >=  3852      THEN 'L4_CI_3P0'                                                  -- 分支判定：MDE 反解第四档
                ELSE 'L5_INSUFFICIENT' END                                AS evidence_rate,                     -- 条件分支：收束上方 —— HF9f·F-3 证据分档，承 HF9e 前议之 MDE 反解五档，须于 F-4 敏感性实验后复核
           ROUND(1.96 * 0.95 / SQRT(NULLIF(CAST(e.n_rounds AS DOUBLE),0)),8) AS hold_ci_halfwidth_approx,       -- 比率表达式：HF9f·F-3 逐行现算之 95% 半宽近似；常数 0.95 为登记值，本轮 #075 实测每局 ROI 隐含 σ 于最薄层为 0.9249，二者差异待 F-4 裁定
           CASE WHEN e.stake IS NULL OR e.stake<=0 OR e.n_bets<30 OR e.n_rounds IS NULL OR e.n_rounds<30 THEN 'Z 证据不足 · 不动作'  -- 条件分支：HF9f·F-2 双条件取严 —— HF9e 仅卡 e.n_bets<30，致 n_bets>=30 而 n_rounds<30 者绕过 Z（#075 实测 18,537 名，其中 8,145 名已入 A/D 待裁）；今两条件并列取严
                WHEN PERCENT_RANK() OVER (ORDER BY -e.net-e.rebate-e.agent_cost)<=0.10                          -- 分支判定：平台真净利之最低十分位
                  THEN 'A 净亏最大十分位 · 优先复核'                                                             -- 分支取值：HF9f·F-20 正名 —— 本档 Σresidual_b 于 #075 实测 = -100,236,896，系平台净亏最大群，旧名「残值最低十分位 · 待裁」名实不符
                WHEN PERCENT_RANK() OVER (ORDER BY -e.net-e.rebate-e.agent_cost)>=0.80                          -- 分支判定：平台真净利之最高二十分位
                  THEN 'D 净利最高二十分位 · 优先留存'                                                           -- 分支取值：HF9f·F-20 正名 —— 本档 Σresidual_b 于 #075 实测 = +281,733,190，系核心利润源；与 A 档方向相反，旧版同标「待裁」属名实不符
                ELSE 'E 常规' END                                          AS action_priority                   -- 条件分支：收束上方判词，产出「action_priority」
    FROM q
    LEFT JOIN x_agg e ON CAST(e.x_key AS STRING) = CAST(q.`member_id` AS STRING)
  ) y
) z
-- ── 逐批 WHERE 阶梯（★ 口诀：上界 ＝ 下界 ＋ 100000，两数同进）──
--    本件 T_true 未测，无需先跑 T_true；以 0 / 100000 控制本批返回区间，末批由实际行数 < 100000 判定
--    WHERE z.audit_rn >        0 AND z.audit_rn <=   100000   -- 第 1 批
--    WHERE z.audit_rn >   100000 AND z.audit_rn <=   200000   -- 第 2 批
--    WHERE z.audit_rn >   200000 AND z.audit_rn <=   300000   -- 第 3 批
--    WHERE z.audit_rn >   300000 AND z.audit_rn <=   400000   -- 第 4 批
--    WHERE z.audit_rn >   400000 AND z.audit_rn <=   500000   -- 第 5 批
--    WHERE z.audit_rn >   500000 AND z.audit_rn <=   600000   -- 第 6 批
--    WHERE z.audit_rn >   600000 AND z.audit_rn <=   700000   -- 第 7 批
--    …余批类推。第 k 批：WHERE z.audit_rn > (k-1)*100000 AND z.audit_rn <= k*100000
--    某批返回 < 100000 行即为末批，其后不再取。
--
--    ⚠ 常见误写（务必避开）：只推下界而上界不动 ——
--        WHERE z.audit_rn > 100000 AND z.audit_rn <= 100000   ← 自相矛盾，恒为假，返回空集
--        WHERE z.audit_rn > 200000 AND z.audit_rn <= 100000   ← 同上，空集
--      两个数必须**同时**前进，且始终相差 100000。
--      下界 ＝ 上一批之上界；上界 ＝ 本批之上界。
WHERE z.audit_rn > 0 AND z.audit_rn <= 100000 -- ★ HF9c 本批区间
ORDER BY z.audit_rn;


-- ══════════════════════════════════════════════════════════════════════════════════════════════
--  85. TL00_table_inventory.csv   [总包行 8168~8215 · 原 5 列 ＋六层约 60 列]
--     典型学：Z00 基建/元数据　派生旗标：recent（s.x_rec = 1 · 仅供 CASE 条件聚合，全包无任何 WHERE/AND/HAVING 以此过滤）　连接：全窗基线
-- ══════════════════════════════════════════════════════════════════════════════════════════════
-- ★ W-64 · D-14 警示（本件属 x_win 族 · 66 件之一 · 详见 §Z 段 D-14 全案）
--   本件以 `CROSS JOIN x_win e` 接入全局基线，x_win 无 GROUP BY ⇒ 恒 1 行 ⇒ e.* 全行同值。
--   故：economic_value / roi_pr_global / risk_value / pr_stake / pr_global 恒为 0；
--       action_priority 每一行皆为「A 净亏最大十分位 · 优先复核」（Z 分支永不触发）；
--       evidence_rate 恒为最高档；vip_tier 由常数键分档 ⇒ 无信息且非确定。
--   ⇒ 本件决策层三列 **NOT_FOR_DECISION**，裁定前不得用于排班、抽查或汇报。
-- ── ① 先跑 T_true 留档（不足 100000 者一次导全，不必分批）──
-- ── ① T_true：HF9c 不再强制预跑完整 COUNT。
--    本批实际返回行数 < 100000 即判定为末批；全批完成后以各批 n_rows / audit_rn 范围核对总量。

-- ── ② 分批取数：第 1 批。第 k 批只改末行两数为 (k-1)*100000 与 k*100000 ──
--    审计字段二（REDTEAM 2026-08-24 裁定 · 四锁）：
--      audit_rn  全局观测坐标 —— 由**与原版审计版逐字同一**之排序键所生，两版可逐行对账
--      batch_id  物理分批信息 —— 该行所属批次，由 audit_rn 算得，非引擎所赋
--    ★ 锁三：二者皆为审计字段，**不得进入任何业务指标计算**。
--    ★ 锁四：两版经 audit_rn 逐行字段核验后，方可宣布输出完全一致。

-- ── ③ 每批取回后自证四数（任一不符即停手回报，禁止放行）──
--    n_rows        = COUNT(*)      须等于 COUNT(DISTINCT audit_rn)   （批内无重复）
--    audit_rn_min  = MIN(audit_rn) 须等于 (k-1)*100000 + 1           （与上批严丝合缝）
--    audit_rn_max  = MAX(audit_rn) 须等于 min + n_rows - 1           （批内无缺口）
--    全批取毕再验：各批 audit_rn 之并集 = 1 .. T_true，无缺号、无重号。
--     ★ 首行＝平台真净亏最多者（已扣退水与代理占成）。
--
SELECT z.*,
       CAST(FLOOR((z.audit_rn - 1) / 100000) + 1 AS INT)          AS batch_id,
       'A168_HF9F_20260827_0900' AS run_id,
       '2026-08-27 09:00:00' AS snapshot_sync_time
FROM (
  SELECT y.*,
         ROW_NUMBER() OVER (ORDER BY y.`residual_b` ASC, y.`roi` DESC, y.`TABLE_NAME`, y.`列数`, y.`时间列数`, y.`处置类列数`, y.`定日类列数`) AS audit_rn
  FROM (
    WITH
      x_ranked AS (
    SELECT b.bet01, b.bet03, b.bet04, b.bet05, b.bet09, b.bet11, b.bet13,
           b.bet15, b.bet16, b.bet17, b.bet18, b.bet19, b.bet20, b.bet21,
           b.bet22, b.bet23, b.bet24, b.bet25, b.bet26, b.bet27, b.bet38, b.bet39, b.category, b.commission,
           b.dt, b.eid, b.ip, b.validbet, b.updatetime, b.sync_time,
           ROW_NUMBER() OVER (
             PARTITION BY b.bet01
             ORDER BY b.updatetime DESC, b.sync_time DESC, b.dt DESC)      AS x_rn
    FROM ods_mariadb_2b.ods_a168_bet02 b
    WHERE b.dt >= '2026-03-21' AND b.dt < '2026-08-07'
      AND b.bet02 = '101'
      AND b.sync_time <= '2026-08-27 09:00:00'
  ),
    x_testagent AS (
    SELECT age001 AS agent_id FROM ods_mariadb_2b.ods_a168_agent WHERE age022 = '1'
  ),
    x_bs0 AS (
    SELECT b.bet05 AS x_member, b.eid AS x_dealer, b.bet39 AS x_table,
           b.bet03 AS x_shoe, b.ip AS x_ip, b.bet09 AS x_product, b.dt AS x_date,
           CONCAT_WS('|', b.bet03, b.bet04, b.bet39)                      AS x_round,
           CONCAT_WS('|', b.bet39, b.bet03)                               AS x_tblshoe,
           CAST(NULLIF(TRIM(b.bet04),'') AS INT)                          AS x_rno,
           CASE WHEN b.dt >= '2026-07-08' THEN 1 ELSE 0 END               AS x_rec,
           CASE WHEN TRIM(b.commission)='1' THEN 1 ELSE 0 END             AS x_freecomm,
           CAST(NULLIF(TRIM(b.bet13),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_stake,
           CAST(NULLIF(TRIM(b.validbet),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_valid,
           CAST(NULLIF(TRIM(b.bet16),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_rebate,
           CAST(NULLIF(TRIM(b.bet17),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_net,
           CAST(NULLIF(TRIM(b.bet15),'') AS DECIMAL(20,6))                AS x_rbpct,
           COALESCE(CAST(NULLIF(TRIM(b.bet23),'') AS DECIMAL(20,6)),0)   AS x_agpct,
          NULLIF(CAST(NULLIF(TRIM(b.bet23),'') AS DECIMAL(20,6)),0)     AS x_rate1,
          NULLIF(CAST(NULLIF(TRIM(b.bet24),'') AS DECIMAL(20,6)),0)     AS x_rate2,
          NULLIF(CAST(NULLIF(TRIM(b.bet25),'') AS DECIMAL(20,6)),0)     AS x_rate3,
          NULLIF(CAST(NULLIF(TRIM(b.bet26),'') AS DECIMAL(20,6)),0)     AS x_rate4,
          NULLIF(CAST(NULLIF(TRIM(b.bet27),'') AS DECIMAL(20,6)),0)     AS x_rate5,
          (CASE WHEN NULLIF(CAST(NULLIF(TRIM(b.bet22),'') AS BIGINT),0) IS NOT NULL THEN 5
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet21),'') AS BIGINT),0) IS NOT NULL THEN 4
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet20),'') AS BIGINT),0) IS NOT NULL THEN 3
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet19),'') AS BIGINT),0) IS NOT NULL THEN 2
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet18),'') AS BIGINT),0) IS NOT NULL THEN 1
                ELSE 0 END)                                             AS x_chain_depth,
           CASE WHEN COALESCE(t1.agent_id,t2.agent_id,t3.agent_id,
                              t4.agent_id,t5.agent_id) IS NOT NULL
                THEN 1 ELSE 0 END                                        AS f_testline
    FROM x_ranked b
    LEFT JOIN x_testagent t1 ON t1.agent_id = b.bet18
    LEFT JOIN x_testagent t2 ON t2.agent_id = b.bet19
    LEFT JOIN x_testagent t3 ON t3.agent_id = b.bet20
    LEFT JOIN x_testagent t4 ON t4.agent_id = b.bet21
    LEFT JOIN x_testagent t5 ON t5.agent_id = b.bet22
    WHERE b.x_rn = 1
      AND b.category='1' AND UPPER(TRIM(b.bet38))='N'
      AND CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8)) > 0
  ),
  x_mk AS (
    SELECT s.*,
           CASE WHEN s.f_testline = 0 THEN 1 ELSE 0 END                 AS is_clean
    FROM x_bs0 s
  ),
  x_agg AS (
    SELECT s.x_member                                                        AS x_key,
           COUNT(*) AS n_bets, COUNT(DISTINCT s.x_round) AS n_rounds,
           COUNT(DISTINCT s.x_date) AS active_days, COUNT(DISTINCT s.x_tblshoe) AS active_shoes,
           COUNT(DISTINCT CONCAT_WS('|', s.x_date, s.x_table)) AS active_sessions,
           COUNT(DISTINCT s.x_table) AS n_tables, COUNT(DISTINCT s.x_dealer) AS n_dealers,
           COUNT(DISTINCT s.x_ip) AS n_ips, COUNT(DISTINCT s.x_product) AS n_products,
           MIN(s.x_date) AS first_seen_d, MAX(s.x_date) AS last_seen_d,
           SUM(s.x_stake) AS stake, SUM(s.x_valid) AS valid, SUM(s.x_rebate) AS rebate,
           SUM(s.x_net) AS net, SUM(-s.x_net *(100.0-s.x_agpct)/100.0) AS agent_cost,
           AVG(100.0-s.x_agpct)                   AS agent_pct,
           AVG(s.x_agpct)                         AS company_retain_pct,
           SUM(-s.x_net *s.x_agpct/100.0)         AS agent_cost_a_legacy,
           SUM(s.x_valid*s.x_agpct/100.0)         AS agent_cost_valid_base_legacy,
          AVG(COALESCE(s.x_rate1,100)) AS retain_pct_lv1, AVG(COALESCE(s.x_rate2,100)) AS retain_pct_lv2,
          AVG(COALESCE(s.x_rate3,100)) AS retain_pct_lv3, AVG(COALESCE(s.x_rate4,100)) AS retain_pct_lv4,
          AVG(COALESCE(s.x_rate5,100)) AS retain_pct_lv5, AVG(s.x_chain_depth) AS chain_depth_avg,
          AVG(COALESCE(100.0-s.x_rate1,0)) AS agent_pct_lv1, AVG(COALESCE(100.0-s.x_rate2,0)) AS agent_pct_lv2,
          AVG(COALESCE(100.0-s.x_rate3,0)) AS agent_pct_lv3, AVG(COALESCE(100.0-s.x_rate4,0)) AS agent_pct_lv4,
          AVG(COALESCE(100.0-s.x_rate5,0)) AS agent_pct_lv5,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate1,0)/100.0)                        AS agent_cost_lv1,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate2,0)/100.0)                        AS agent_cost_lv2,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate3,0)/100.0)                        AS agent_cost_lv3,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate4,0)/100.0)                        AS agent_cost_lv4,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate5,0)/100.0)                        AS agent_cost_lv5,
          SUM(-s.x_net*(COALESCE(100.0-s.x_rate1,0)+COALESCE(100.0-s.x_rate2,0)
                       +COALESCE(100.0-s.x_rate3,0)+COALESCE(100.0-s.x_rate4,0)
                       +COALESCE(100.0-s.x_rate5,0))/100.0)                   AS agent_cost_chain_additive,
          SUM(-s.x_net*(1.0 - CAST(COALESCE(s.x_rate1,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate2,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate3,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate4,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate5,100) AS DOUBLE)/100.0))
                                                                       AS agent_cost_chain_nested,
           AVG(s.x_rbpct) AS rbpct, AVG(s.x_freecomm*1.0) AS freecomm_rate,
           PERCENTILE_APPROX(s.x_stake,0.25) AS p25, PERCENTILE_APPROX(s.x_stake,0.50) AS p50,
           PERCENTILE_APPROX(s.x_stake,0.75) AS p75, PERCENTILE_APPROX(s.x_stake,0.90) AS p90,
           PERCENTILE_APPROX(s.x_stake,0.95) AS p95, PERCENTILE_APPROX(s.x_stake,0.99) AS p99,
           PERCENTILE_APPROX(s.x_valid,0.50) AS p50_valid,
           PERCENTILE_APPROX(s.x_net,0.50)   AS p50_profit,
           SUM(CASE WHEN s.x_rec = 1 THEN s.x_stake ELSE 0 END) AS st_in,
           SUM(CASE WHEN s.x_rec = 1 THEN 1 ELSE 0 END)         AS nb_in,
           SUM(CASE WHEN s.x_rec = 1 THEN s.x_net ELSE 0 END)   AS net_in,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN s.x_stake ELSE 0 END) AS st_out,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN 1 ELSE 0 END)         AS nb_out,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN s.x_net ELSE 0 END)   AS net_out,
           SUM(CASE WHEN s.x_rec=1 THEN s.x_stake ELSE 0 END) AS st_rec,
           SUM(CASE WHEN s.x_rec=1 THEN 1 ELSE 0 END)         AS nb_rec
    FROM x_mk s
    WHERE s.is_clean = 1
      AND s.x_member IS NOT NULL AND TRIM(CAST(s.x_member AS STRING)) <> ''
    GROUP BY s.x_member
  ),
  x_win AS (
    SELECT            COUNT(*) AS n_bets, COUNT(DISTINCT s.x_round) AS n_rounds,
           COUNT(DISTINCT s.x_date) AS active_days, COUNT(DISTINCT s.x_tblshoe) AS active_shoes,
           COUNT(DISTINCT CONCAT_WS('|', s.x_date, s.x_table)) AS active_sessions,
           COUNT(DISTINCT s.x_table) AS n_tables, COUNT(DISTINCT s.x_dealer) AS n_dealers,
           COUNT(DISTINCT s.x_ip) AS n_ips, COUNT(DISTINCT s.x_product) AS n_products,
           MIN(s.x_date) AS first_seen_d, MAX(s.x_date) AS last_seen_d,
           SUM(s.x_stake) AS stake, SUM(s.x_valid) AS valid, SUM(s.x_rebate) AS rebate,
           SUM(s.x_net) AS net, SUM(-s.x_net *(100.0-s.x_agpct)/100.0) AS agent_cost,
           AVG(100.0-s.x_agpct)                   AS agent_pct,
           AVG(s.x_agpct)                         AS company_retain_pct,
           SUM(-s.x_net *s.x_agpct/100.0)         AS agent_cost_a_legacy,
           SUM(s.x_valid*s.x_agpct/100.0)         AS agent_cost_valid_base_legacy,
          AVG(COALESCE(s.x_rate1,100)) AS retain_pct_lv1, AVG(COALESCE(s.x_rate2,100)) AS retain_pct_lv2,
          AVG(COALESCE(s.x_rate3,100)) AS retain_pct_lv3, AVG(COALESCE(s.x_rate4,100)) AS retain_pct_lv4,
          AVG(COALESCE(s.x_rate5,100)) AS retain_pct_lv5, AVG(s.x_chain_depth) AS chain_depth_avg,
          AVG(COALESCE(100.0-s.x_rate1,0)) AS agent_pct_lv1, AVG(COALESCE(100.0-s.x_rate2,0)) AS agent_pct_lv2,
          AVG(COALESCE(100.0-s.x_rate3,0)) AS agent_pct_lv3, AVG(COALESCE(100.0-s.x_rate4,0)) AS agent_pct_lv4,
          AVG(COALESCE(100.0-s.x_rate5,0)) AS agent_pct_lv5,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate1,0)/100.0)                        AS agent_cost_lv1,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate2,0)/100.0)                        AS agent_cost_lv2,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate3,0)/100.0)                        AS agent_cost_lv3,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate4,0)/100.0)                        AS agent_cost_lv4,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate5,0)/100.0)                        AS agent_cost_lv5,
          SUM(-s.x_net*(COALESCE(100.0-s.x_rate1,0)+COALESCE(100.0-s.x_rate2,0)
                       +COALESCE(100.0-s.x_rate3,0)+COALESCE(100.0-s.x_rate4,0)
                       +COALESCE(100.0-s.x_rate5,0))/100.0)                   AS agent_cost_chain_additive,
          SUM(-s.x_net*(1.0 - CAST(COALESCE(s.x_rate1,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate2,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate3,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate4,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate5,100) AS DOUBLE)/100.0))
                                                                       AS agent_cost_chain_nested,
           AVG(s.x_rbpct) AS rbpct, AVG(s.x_freecomm*1.0) AS freecomm_rate,
           PERCENTILE_APPROX(s.x_stake,0.25) AS p25, PERCENTILE_APPROX(s.x_stake,0.50) AS p50,
           PERCENTILE_APPROX(s.x_stake,0.75) AS p75, PERCENTILE_APPROX(s.x_stake,0.90) AS p90,
           PERCENTILE_APPROX(s.x_stake,0.95) AS p95, PERCENTILE_APPROX(s.x_stake,0.99) AS p99,
           PERCENTILE_APPROX(s.x_valid,0.50) AS p50_valid,
           PERCENTILE_APPROX(s.x_net,0.50)   AS p50_profit,
           SUM(CASE WHEN s.x_rec = 1 THEN s.x_stake ELSE 0 END) AS st_in,
           SUM(CASE WHEN s.x_rec = 1 THEN 1 ELSE 0 END)         AS nb_in,
           SUM(CASE WHEN s.x_rec = 1 THEN s.x_net ELSE 0 END)   AS net_in,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN s.x_stake ELSE 0 END) AS st_out,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN 1 ELSE 0 END)         AS nb_out,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN s.x_net ELSE 0 END)   AS net_out,
           SUM(CASE WHEN s.x_rec=1 THEN s.x_stake ELSE 0 END) AS st_rec,
           SUM(CASE WHEN s.x_rec=1 THEN 1 ELSE 0 END)         AS nb_rec
    FROM x_mk s
    WHERE s.is_clean = 1
      AND s.x_member IS NOT NULL AND TRIM(CAST(s.x_member AS STRING)) <> ''
  ),
      q AS (
        SELECT  c.TABLE_NAME,
                COUNT(*)                                                   AS 列数,
                SUM(CASE WHEN c.DATA_TYPE IN ('date','datetime') THEN 1 ELSE 0 END) AS 时间列数,
                SUM(CASE WHEN c.COLUMN_COMMENT LIKE '%限額%'
                           OR c.COLUMN_COMMENT LIKE '%限红%'
                           OR c.COLUMN_COMMENT LIKE '%限紅%'
                           OR c.COLUMN_COMMENT LIKE '%退水%'
                           OR c.COLUMN_COMMENT LIKE '%凍結%'
                           OR c.COLUMN_COMMENT LIKE '%冻结%'
                           OR c.COLUMN_COMMENT LIKE '%停用%'
                           OR c.COLUMN_COMMENT LIKE '%狀態%'
                           OR c.COLUMN_COMMENT LIKE '%状态%'
                           OR c.COLUMN_COMMENT LIKE '%審核%'
                           OR c.COLUMN_COMMENT LIKE '%审核%'
                           OR c.COLUMN_COMMENT LIKE '%處理%'
                           OR c.COLUMN_COMMENT LIKE '%处理%'
                           OR c.COLUMN_COMMENT LIKE '%操作%'
                           OR c.COLUMN_COMMENT LIKE '%備註%'
                           OR c.COLUMN_COMMENT LIKE '%备注%'
                         THEN 1 ELSE 0 END)                                AS 处置类列数,
                SUM(CASE WHEN c.COLUMN_COMMENT LIKE '%時間%'
                           OR c.COLUMN_COMMENT LIKE '%时间%'
                           OR c.COLUMN_COMMENT LIKE '%日期%'
                           OR c.COLUMN_NAME   LIKE '%time%'
                           OR c.COLUMN_NAME   LIKE '%date%'
                         THEN 1 ELSE 0 END)                                AS 定日类列数
        FROM    information_schema.columns c
        WHERE   c.TABLE_SCHEMA = 'ods_mariadb_2b'
          AND   c.TABLE_NAME LIKE 'ods_a168_%'
        GROUP BY c.TABLE_NAME
        HAVING  SUM(CASE WHEN c.COLUMN_COMMENT LIKE '%限額%'
                           OR c.COLUMN_COMMENT LIKE '%限红%'
                           OR c.COLUMN_COMMENT LIKE '%限紅%'
                           OR c.COLUMN_COMMENT LIKE '%退水%'
                           OR c.COLUMN_COMMENT LIKE '%凍結%'
                           OR c.COLUMN_COMMENT LIKE '%冻结%'
                           OR c.COLUMN_COMMENT LIKE '%停用%'
                           OR c.COLUMN_COMMENT LIKE '%狀態%'
                           OR c.COLUMN_COMMENT LIKE '%状态%'
                           OR c.COLUMN_COMMENT LIKE '%審核%'
                           OR c.COLUMN_COMMENT LIKE '%审核%'
                           OR c.COLUMN_COMMENT LIKE '%處理%'
                           OR c.COLUMN_COMMENT LIKE '%处理%'
                           OR c.COLUMN_COMMENT LIKE '%操作%'
                           OR c.COLUMN_COMMENT LIKE '%備註%'
                           OR c.COLUMN_COMMENT LIKE '%备注%'
                         THEN 1 ELSE 0 END) > 0
      )
    SELECT q.*,
           -- 一·经济层
           ROUND(e.stake,4) AS stake, ROUND(e.valid,4) AS valid_bet,
           ROUND(-e.net,4) AS profit, e.n_bets, e.n_rounds,
           ROUND(e.net/NULLIF(e.stake,0),8) AS roi,
           ROUND(e.net_in/NULLIF(e.st_in,0),8) AS roi_recent,
           ROUND(e.net_out/NULLIF(e.st_out,0),8) AS roi_non_recent,
           ROUND((e.net-e.rebate)/NULLIF(e.stake,0),8) AS roi_ex_rebate,
           ROUND(e.net,4) AS roi_numerator, ROUND(e.stake,4) AS roi_denominator,
           CASE WHEN e.stake IS NULL THEN 'NULL_DENOM' WHEN e.stake<=0 THEN 'ZERO_DENOM'
                WHEN e.n_bets<30 THEN 'THIN_EXPOSURE' ELSE 'OK' END AS roi_denominator_status,
           ROUND(e.rebate,4) AS rebate_cost, ROUND(e.agent_cost,4)                           AS cost_complement_b,
       ROUND(e.agent_pct,4)                            AS pct_complement,
       ROUND(e.company_retain_pct,4)                   AS pct_top_bet23,
       'AG03-UNRESOLVED'                                     AS agent_formula_version,
      'ALL5_LEVELS_bet23_to_bet27'                    AS agent_level_scope,
      ROUND(e.agent_cost_lv1,4) AS agent_cost_lv1, ROUND(e.agent_cost_lv2,4) AS agent_cost_lv2,
      ROUND(e.agent_cost_lv3,4) AS agent_cost_lv3, ROUND(e.agent_cost_lv4,4) AS agent_cost_lv4,
      ROUND(e.agent_cost_lv5,4) AS agent_cost_lv5,
      ROUND(e.agent_pct_lv1,6) AS agent_pct_lv1, ROUND(e.agent_pct_lv2,6) AS agent_pct_lv2,
      ROUND(e.agent_pct_lv3,6) AS agent_pct_lv3, ROUND(e.agent_pct_lv4,6) AS agent_pct_lv4,
      ROUND(e.agent_pct_lv5,6) AS agent_pct_lv5,
      ROUND(e.retain_pct_lv1,6) AS retain_pct_lv1, ROUND(e.retain_pct_lv2,6) AS retain_pct_lv2,
      ROUND(e.retain_pct_lv3,6) AS retain_pct_lv3, ROUND(e.retain_pct_lv4,6) AS retain_pct_lv4,
      ROUND(e.retain_pct_lv5,6) AS retain_pct_lv5, ROUND(e.chain_depth_avg,4) AS chain_depth_avg,
      ROUND(e.agent_cost_chain_additive,4)            AS agent_cost_chain_additive,
      ROUND(e.agent_cost_chain_nested,4)              AS agent_cost_chain_nested,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_additive,4) AS residual_chain_additive,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_nested,4)   AS residual_chain_nested,
      'PENDING_AG03'                                  AS decision_status,
      'FALSE'                                         AS admit_to_risk_decision,
      'NOT_FOR_ENFORCEMENT'                           AS deliverable_class,
       ROUND(e.agent_cost_a_legacy,4)                  AS agent_cost_a_legacy,
       ROUND(e.agent_cost_valid_base_legacy,4)         AS agent_cost_valid_base_legacy,
           ROUND(-e.net-e.rebate,4)                        AS ngr,
       ROUND(-e.net-e.rebate-e.agent_cost,4)           AS residual_b,
       ROUND(-e.net-e.rebate-e.agent_cost_a_legacy,4)  AS residual_a,
           ROUND((-e.net-e.rebate)/NULLIF(e.stake,0),8)    AS ngr_rate,
       ROUND((-e.net-e.rebate-e.agent_cost)/NULLIF(e.stake,0),8)   AS residual_b_rate,
      -- 【HF9c · canonical accounting contract】
      --   以下 canonical 字段只增加明确 scope；不删除、不覆盖既有字段。
      --   formal_bet23_* 保持 HF9b 当前生产公式及其 NULL/0 语义；
      --   lv1~lv5 / additive / nested 则分别采用各自原始 e.* 成本字段，
      --   rate 一律从未舍入的 e.* 分子 / e.stake 计算，禁止由展示值反算。
      ROUND(e.agent_cost,4) AS agent_cost_bet23_formal_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost,4) AS net_margin_bet23_formal_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost)/NULLIF(e.stake,0),8) AS net_margin_bet23_formal_rate_canonical,
      ROUND(e.agent_cost_lv1,4) AS agent_cost_lv1_bet23_canonical,
      ROUND(e.agent_cost_lv2,4) AS agent_cost_lv2_bet24_canonical,
      ROUND(e.agent_cost_lv3,4) AS agent_cost_lv3_bet25_canonical,
      ROUND(e.agent_cost_lv4,4) AS agent_cost_lv4_bet26_canonical,
      ROUND(e.agent_cost_lv5,4) AS agent_cost_lv5_bet27_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_lv1,4) AS net_margin_lv1_bet23_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_lv1)/NULLIF(e.stake,0),8) AS net_margin_lv1_bet23_rate_canonical,
      ROUND(e.agent_cost_chain_additive,4) AS agent_cost_chain_additive_canonical,
      ROUND(e.agent_cost_chain_nested,4) AS agent_cost_chain_nested_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_additive,4) AS net_margin_chain_additive_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_nested,4) AS net_margin_chain_nested_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_chain_additive)/NULLIF(e.stake,0),8) AS net_margin_chain_additive_rate_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_chain_nested)/NULLIF(e.stake,0),8) AS net_margin_chain_nested_rate_canonical,
       ROUND((-e.net-e.rebate-e.agent_cost_a_legacy)/NULLIF(e.stake,0),8) AS residual_a_rate,
           -- 二·分布层
           ROUND(e.stake/NULLIF(e.n_bets,0),4) AS avg_stake_per_bet,
           ROUND(e.valid/NULLIF(e.n_rounds,0),4) AS avg_valid_bet_per_round,
           ROUND(-e.net/NULLIF(e.n_rounds,0),4) AS avg_profit_per_round,
           ROUND(-e.net/NULLIF(e.active_days,0),4) AS avg_profit_per_day,
           ROUND(-e.net/NULLIF(e.active_shoes,0),4) AS avg_profit_per_shoe,
           ROUND(e.stake/NULLIF(e.active_days,0),4) AS avg_stake_per_active_day,
           ROUND(e.n_rounds*1.0/NULLIF(e.active_days,0),4) AS avg_rounds_per_active_day,
           ROUND(e.st_in/NULLIF(e.nb_in,0),4) AS avg_stake_recent,
           ROUND(e.st_out/NULLIF(e.nb_out,0),4) AS avg_stake_non_recent,
           ROUND(e.p25,4) AS p25_stake, ROUND(e.p50,4) AS p50_stake, ROUND(e.p75,4) AS p75_stake,
           ROUND(e.p90,4) AS p90_stake, ROUND(e.p95,4) AS p95_stake, ROUND(e.p99,4) AS p99_stake,
           ROUND(e.p50_valid,4) AS p50_valid_bet, ROUND(e.p50_profit,4) AS p50_profit,
           ROUND(e.p95/NULLIF(e.p50,0),6) AS p95_over_p50,
           ROUND(e.p99/NULLIF(e.p50,0),6) AS p99_over_p50,
           ROUND((e.stake/NULLIF(e.n_bets,0))/NULLIF(e.p50,0),6) AS avg_over_p50,
           -- 三·关系层
           e.n_tables AS common_table_count, e.n_dealers AS common_dealer_count,
           e.n_ips AS common_ip_count, e.n_products AS common_product_count,
           ROUND(e.st_in/NULLIF(e.stake,0),8) AS share_recent,
           -- 四·rate 层
           ROUND(-e.net/NULLIF(e.stake,0),8) AS hold_rate,
           ROUND(-e.net_in/NULLIF(e.st_in,0),8) AS hold_rate_recent,
           ROUND(e.rebate/NULLIF(e.valid,0),8) AS rebate_rate_actual,
           ROUND(e.rbpct,6) AS rebate_pct_config,
           ROUND(e.valid/NULLIF(e.stake,0),6) AS turnover_multiple,
           ROUND(e.freecomm_rate,6) AS free_comm_rate,
           ROUND(e.net_in/NULLIF(e.st_in,0)-e.net_out/NULLIF(e.st_out,0),8) AS roi_delta_recent,
           -- 五·动态层
           e.first_seen_d AS first_seen, e.last_seen_d AS last_seen,
           e.active_days, e.active_shoes, e.active_sessions,
           DATEDIFF(e.last_seen_d, e.first_seen_d)+1 AS span_days,
           ROUND(e.active_days*1.0/NULLIF(DATEDIFF(e.last_seen_d,e.first_seen_d)+1,0),6) AS persistence,
           ROUND((e.st_in/NULLIF(e.nb_in,0))/NULLIF(e.st_out/NULLIF(e.nb_out,0),0),6) AS ramp_recent_vs_prior,
           ROUND((e.st_rec/NULLIF(e.nb_rec,0))/NULLIF(e.stake/NULLIF(e.n_bets,0),0),6) AS ramp_recent_vs_all,
           ROUND((e.st_rec/NULLIF(e.stake,0))/0.30,6) AS stake_ramp,
           -- 六·决策层（HF9g-P5 · D-14 斧正 —— 本件属【全窗基线族】，相对刻度与决策标签一律 NULL）
           --   病灶：x_win 系全窗单行聚合（无 GROUP BY，恒 1 行，此为设计使然，非缺陷），
           --         经 CROSS JOIN 接入后 e.* 全行同值；六层之 NTILE / PERCENT_RANK 施于常数即退化，
           --         PERCENT_RANK 恒 0 ⇒ action_priority 恒判 A，全件 100% 误标。
           --   ★ 斧正原则：不给 x_win 补 GROUP BY —— 那会改变其「全窗基线」语义，属退化。
           --     正解与 #018 之 G-05／G-06 同治：范围外之行不得接受任何下游评分与决策标签。
           --   ★ 本件之 e.* 仍照常供其它列作全窗基线使用，仅六层相对刻度与决策标签置 NULL。
           CAST(NULL AS INT)                                              AS vip_tier,                        -- 空值取值：全窗基线族无实体可分档，置 NULL（NULL＝不适用，非 0）
           CAST(NULL AS DOUBLE)                                           AS economic_value,                  -- 空值取值：同上，禁以常数百分位冒充经济价值
           CAST(NULL AS DOUBLE)                                           AS roi_pr_global,                   -- 空值取值：同上
           CAST(NULL AS DOUBLE)                                           AS risk_value,                      -- 空值取值：兼容列，同上
           CAST(NULL AS DOUBLE)                                           AS pr_stake,                        -- 空值取值：兼容列，同上
           CAST(NULL AS DOUBLE)                                           AS pr_global,                       -- 空值取值：同上
           CAST(NULL AS DOUBLE)                                           AS pr_qualified,                    -- 空值取值：同上
           'GLOBAL_BASELINE_NO_ENTITY_RANKING'                            AS pr_qualified_population,         -- 字面取值：血统 —— 明示本件为全窗基线族，无实体排序总体
           CAST(NULL AS BIGINT)                                           AS pr_global_population_n,          -- 空值取值：血统 —— 不适用
           CAST(NULL AS BIGINT)                                           AS pr_qualified_population_n,       -- 空值取值：血统 —— 不适用
           'NOT_APPLICABLE_GLOBAL_BASELINE'                               AS pr_calculation_method,           -- 字面取值：血统 —— 算法不适用
           'HF9g-P5'                                                      AS pr_calculation_version,          -- 字面取值：血统 —— 算法版本
           CAST(NULL AS STRING)                                           AS evidence_flag,                   -- 空值取值：证据旗标不适用于全窗基线
           CAST(NULL AS STRING)                                           AS evidence_rate,                   -- 空值取值：同上
           CAST(NULL AS DOUBLE)                                           AS hold_ci_halfwidth_approx,        -- 空值取值：同上
           'X 全窗基线 · 不参与实体赏罚'                                    AS action_priority                  -- 字面取值：★ D-14 斧正 —— 本族恒不入赏罚，取代原 100% 误标之「A」
    FROM q
    CROSS JOIN x_win e
  ) y
) z
-- ── 逐批 WHERE 阶梯（★ 口诀：上界 ＝ 下界 ＋ 100000，两数同进）──
--    本件 T_true 未测，无需先跑 T_true；以 0 / 100000 控制本批返回区间，末批由实际行数 < 100000 判定
--    WHERE z.audit_rn >        0 AND z.audit_rn <=   100000   -- 第 1 批
--    WHERE z.audit_rn >   100000 AND z.audit_rn <=   200000   -- 第 2 批
--    WHERE z.audit_rn >   200000 AND z.audit_rn <=   300000   -- 第 3 批
--    WHERE z.audit_rn >   300000 AND z.audit_rn <=   400000   -- 第 4 批
--    WHERE z.audit_rn >   400000 AND z.audit_rn <=   500000   -- 第 5 批
--    WHERE z.audit_rn >   500000 AND z.audit_rn <=   600000   -- 第 6 批
--    WHERE z.audit_rn >   600000 AND z.audit_rn <=   700000   -- 第 7 批
--    …余批类推。第 k 批：WHERE z.audit_rn > (k-1)*100000 AND z.audit_rn <= k*100000
--    某批返回 < 100000 行即为末批，其后不再取。
--
--    ⚠ 常见误写（务必避开）：只推下界而上界不动 ——
--        WHERE z.audit_rn > 100000 AND z.audit_rn <= 100000   ← 自相矛盾，恒为假，返回空集
--        WHERE z.audit_rn > 200000 AND z.audit_rn <= 100000   ← 同上，空集
--      两个数必须**同时**前进，且始终相差 100000。
--      下界 ＝ 上一批之上界；上界 ＝ 本批之上界。
WHERE z.audit_rn > 0 AND z.audit_rn <= 100000 -- ★ HF9c 本批区间
ORDER BY z.audit_rn;


-- ══════════════════════════════════════════════════════════════════════════════════════════════
--  86. TL02_config_change.csv   [总包行 8238~8269 · 原 4 列 ＋六层约 60 列]
--     典型学：M09 处置限额　派生旗标：post（s.x_rec = 1 · 仅供 CASE 条件聚合，全包无任何 WHERE/AND/HAVING 以此过滤）　连接：全窗基线
-- ══════════════════════════════════════════════════════════════════════════════════════════════
-- ★ W-64 · D-14 警示（本件属 x_win 族 · 66 件之一 · 详见 §Z 段 D-14 全案）
--   本件以 `CROSS JOIN x_win e` 接入全局基线，x_win 无 GROUP BY ⇒ 恒 1 行 ⇒ e.* 全行同值。
--   故：economic_value / roi_pr_global / risk_value / pr_stake / pr_global 恒为 0；
--       action_priority 每一行皆为「A 净亏最大十分位 · 优先复核」（Z 分支永不触发）；
--       evidence_rate 恒为最高档；vip_tier 由常数键分档 ⇒ 无信息且非确定。
--   ⇒ 本件决策层三列 **NOT_FOR_DECISION**，裁定前不得用于排班、抽查或汇报。
-- ── ① 先跑 T_true 留档（不足 100000 者一次导全，不必分批）──
-- ── ① T_true：HF9c 不再强制预跑完整 COUNT。
--    本批实际返回行数 < 100000 即判定为末批；全批完成后以各批 n_rows / audit_rn 范围核对总量。

-- ── ② 分批取数：第 1 批。第 k 批只改末行两数为 (k-1)*100000 与 k*100000 ──
--    审计字段二（REDTEAM 2026-08-24 裁定 · 四锁）：
--      audit_rn  全局观测坐标 —— 由**与原版审计版逐字同一**之排序键所生，两版可逐行对账
--      batch_id  物理分批信息 —— 该行所属批次，由 audit_rn 算得，非引擎所赋
--    ★ 锁三：二者皆为审计字段，**不得进入任何业务指标计算**。
--    ★ 锁四：两版经 audit_rn 逐行字段核验后，方可宣布输出完全一致。

-- ── ③ 每批取回后自证四数（任一不符即停手回报，禁止放行）──
--    n_rows        = COUNT(*)      须等于 COUNT(DISTINCT audit_rn)   （批内无重复）
--    audit_rn_min  = MIN(audit_rn) 须等于 (k-1)*100000 + 1           （与上批严丝合缝）
--    audit_rn_max  = MAX(audit_rn) 须等于 min + n_rows - 1           （批内无缺口）
--    全批取毕再验：各批 audit_rn 之并集 = 1 .. T_true，无缺号、无重号。
--     ★ 首行＝平台真净亏最多者（已扣退水与代理占成）。
--
SELECT z.*,
       CAST(FLOOR((z.audit_rn - 1) / 100000) + 1 AS INT)          AS batch_id,
       'A168_HF9F_20260827_0900' AS run_id,
       '2026-08-27 09:00:00' AS snapshot_sync_time
FROM (
  SELECT y.*,
         ROW_NUMBER() OVER (ORDER BY y.`residual_b` ASC, y.`roi` DESC, y.`变更列`, y.`发生变更的会员数`, y.`在册会员数`, y.`变更率`) AS audit_rn
  FROM (
    WITH
      x_ranked AS (
    SELECT b.bet01, b.bet03, b.bet04, b.bet05, b.bet09, b.bet11, b.bet13,
           b.bet15, b.bet16, b.bet17, b.bet18, b.bet19, b.bet20, b.bet21,
           b.bet22, b.bet23, b.bet24, b.bet25, b.bet26, b.bet27, b.bet38, b.bet39, b.category, b.commission,
           b.dt, b.eid, b.ip, b.validbet, b.updatetime, b.sync_time,
           ROW_NUMBER() OVER (
             PARTITION BY b.bet01
             ORDER BY b.updatetime DESC, b.sync_time DESC, b.dt DESC)      AS x_rn
    FROM ods_mariadb_2b.ods_a168_bet02 b
    WHERE b.dt >= '2026-03-21' AND b.dt < '2026-08-07'
      AND b.bet02 = '101'
      AND b.sync_time <= '2026-08-27 09:00:00'
  ),
    x_testagent AS (
    SELECT age001 AS agent_id FROM ods_mariadb_2b.ods_a168_agent WHERE age022 = '1'
  ),
    x_bs0 AS (
    SELECT b.bet05 AS x_member, b.eid AS x_dealer, b.bet39 AS x_table,
           b.bet03 AS x_shoe, b.ip AS x_ip, b.bet09 AS x_product, b.dt AS x_date,
           CONCAT_WS('|', b.bet03, b.bet04, b.bet39)                      AS x_round,
           CONCAT_WS('|', b.bet39, b.bet03)                               AS x_tblshoe,
           CAST(NULLIF(TRIM(b.bet04),'') AS INT)                          AS x_rno,
           CASE WHEN b.dt >= '2026-07-08' THEN 1 ELSE 0 END               AS x_rec,
           CASE WHEN TRIM(b.commission)='1' THEN 1 ELSE 0 END             AS x_freecomm,
           CAST(NULLIF(TRIM(b.bet13),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_stake,
           CAST(NULLIF(TRIM(b.validbet),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_valid,
           CAST(NULLIF(TRIM(b.bet16),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_rebate,
           CAST(NULLIF(TRIM(b.bet17),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_net,
           CAST(NULLIF(TRIM(b.bet15),'') AS DECIMAL(20,6))                AS x_rbpct,
           COALESCE(CAST(NULLIF(TRIM(b.bet23),'') AS DECIMAL(20,6)),0)   AS x_agpct,
          NULLIF(CAST(NULLIF(TRIM(b.bet23),'') AS DECIMAL(20,6)),0)     AS x_rate1,
          NULLIF(CAST(NULLIF(TRIM(b.bet24),'') AS DECIMAL(20,6)),0)     AS x_rate2,
          NULLIF(CAST(NULLIF(TRIM(b.bet25),'') AS DECIMAL(20,6)),0)     AS x_rate3,
          NULLIF(CAST(NULLIF(TRIM(b.bet26),'') AS DECIMAL(20,6)),0)     AS x_rate4,
          NULLIF(CAST(NULLIF(TRIM(b.bet27),'') AS DECIMAL(20,6)),0)     AS x_rate5,
          (CASE WHEN NULLIF(CAST(NULLIF(TRIM(b.bet22),'') AS BIGINT),0) IS NOT NULL THEN 5
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet21),'') AS BIGINT),0) IS NOT NULL THEN 4
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet20),'') AS BIGINT),0) IS NOT NULL THEN 3
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet19),'') AS BIGINT),0) IS NOT NULL THEN 2
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet18),'') AS BIGINT),0) IS NOT NULL THEN 1
                ELSE 0 END)                                             AS x_chain_depth,
           CASE WHEN COALESCE(t1.agent_id,t2.agent_id,t3.agent_id,
                              t4.agent_id,t5.agent_id) IS NOT NULL
                THEN 1 ELSE 0 END                                        AS f_testline
    FROM x_ranked b
    LEFT JOIN x_testagent t1 ON t1.agent_id = b.bet18
    LEFT JOIN x_testagent t2 ON t2.agent_id = b.bet19
    LEFT JOIN x_testagent t3 ON t3.agent_id = b.bet20
    LEFT JOIN x_testagent t4 ON t4.agent_id = b.bet21
    LEFT JOIN x_testagent t5 ON t5.agent_id = b.bet22
    WHERE b.x_rn = 1
      AND b.category='1' AND UPPER(TRIM(b.bet38))='N'
      AND CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8)) > 0
  ),
  x_mk AS (
    SELECT s.*,
           CASE WHEN s.f_testline = 0 THEN 1 ELSE 0 END                 AS is_clean
    FROM x_bs0 s
  ),
  x_agg AS (
    SELECT s.x_member                                                        AS x_key,
           COUNT(*) AS n_bets, COUNT(DISTINCT s.x_round) AS n_rounds,
           COUNT(DISTINCT s.x_date) AS active_days, COUNT(DISTINCT s.x_tblshoe) AS active_shoes,
           COUNT(DISTINCT CONCAT_WS('|', s.x_date, s.x_table)) AS active_sessions,
           COUNT(DISTINCT s.x_table) AS n_tables, COUNT(DISTINCT s.x_dealer) AS n_dealers,
           COUNT(DISTINCT s.x_ip) AS n_ips, COUNT(DISTINCT s.x_product) AS n_products,
           MIN(s.x_date) AS first_seen_d, MAX(s.x_date) AS last_seen_d,
           SUM(s.x_stake) AS stake, SUM(s.x_valid) AS valid, SUM(s.x_rebate) AS rebate,
           SUM(s.x_net) AS net, SUM(-s.x_net *(100.0-s.x_agpct)/100.0) AS agent_cost,
           AVG(100.0-s.x_agpct)                   AS agent_pct,
           AVG(s.x_agpct)                         AS company_retain_pct,
           SUM(-s.x_net *s.x_agpct/100.0)         AS agent_cost_a_legacy,
           SUM(s.x_valid*s.x_agpct/100.0)         AS agent_cost_valid_base_legacy,
          AVG(COALESCE(s.x_rate1,100)) AS retain_pct_lv1, AVG(COALESCE(s.x_rate2,100)) AS retain_pct_lv2,
          AVG(COALESCE(s.x_rate3,100)) AS retain_pct_lv3, AVG(COALESCE(s.x_rate4,100)) AS retain_pct_lv4,
          AVG(COALESCE(s.x_rate5,100)) AS retain_pct_lv5, AVG(s.x_chain_depth) AS chain_depth_avg,
          AVG(COALESCE(100.0-s.x_rate1,0)) AS agent_pct_lv1, AVG(COALESCE(100.0-s.x_rate2,0)) AS agent_pct_lv2,
          AVG(COALESCE(100.0-s.x_rate3,0)) AS agent_pct_lv3, AVG(COALESCE(100.0-s.x_rate4,0)) AS agent_pct_lv4,
          AVG(COALESCE(100.0-s.x_rate5,0)) AS agent_pct_lv5,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate1,0)/100.0)                        AS agent_cost_lv1,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate2,0)/100.0)                        AS agent_cost_lv2,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate3,0)/100.0)                        AS agent_cost_lv3,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate4,0)/100.0)                        AS agent_cost_lv4,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate5,0)/100.0)                        AS agent_cost_lv5,
          SUM(-s.x_net*(COALESCE(100.0-s.x_rate1,0)+COALESCE(100.0-s.x_rate2,0)
                       +COALESCE(100.0-s.x_rate3,0)+COALESCE(100.0-s.x_rate4,0)
                       +COALESCE(100.0-s.x_rate5,0))/100.0)                   AS agent_cost_chain_additive,
          SUM(-s.x_net*(1.0 - CAST(COALESCE(s.x_rate1,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate2,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate3,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate4,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate5,100) AS DOUBLE)/100.0))
                                                                       AS agent_cost_chain_nested,
           AVG(s.x_rbpct) AS rbpct, AVG(s.x_freecomm*1.0) AS freecomm_rate,
           PERCENTILE_APPROX(s.x_stake,0.25) AS p25, PERCENTILE_APPROX(s.x_stake,0.50) AS p50,
           PERCENTILE_APPROX(s.x_stake,0.75) AS p75, PERCENTILE_APPROX(s.x_stake,0.90) AS p90,
           PERCENTILE_APPROX(s.x_stake,0.95) AS p95, PERCENTILE_APPROX(s.x_stake,0.99) AS p99,
           PERCENTILE_APPROX(s.x_valid,0.50) AS p50_valid,
           PERCENTILE_APPROX(s.x_net,0.50)   AS p50_profit,
           SUM(CASE WHEN s.x_rec = 1 THEN s.x_stake ELSE 0 END) AS st_in,
           SUM(CASE WHEN s.x_rec = 1 THEN 1 ELSE 0 END)         AS nb_in,
           SUM(CASE WHEN s.x_rec = 1 THEN s.x_net ELSE 0 END)   AS net_in,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN s.x_stake ELSE 0 END) AS st_out,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN 1 ELSE 0 END)         AS nb_out,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN s.x_net ELSE 0 END)   AS net_out,
           SUM(CASE WHEN s.x_rec=1 THEN s.x_stake ELSE 0 END) AS st_rec,
           SUM(CASE WHEN s.x_rec=1 THEN 1 ELSE 0 END)         AS nb_rec
    FROM x_mk s
    WHERE s.is_clean = 1
      AND s.x_member IS NOT NULL AND TRIM(CAST(s.x_member AS STRING)) <> ''
    GROUP BY s.x_member
  ),
  x_win AS (
    SELECT            COUNT(*) AS n_bets, COUNT(DISTINCT s.x_round) AS n_rounds,
           COUNT(DISTINCT s.x_date) AS active_days, COUNT(DISTINCT s.x_tblshoe) AS active_shoes,
           COUNT(DISTINCT CONCAT_WS('|', s.x_date, s.x_table)) AS active_sessions,
           COUNT(DISTINCT s.x_table) AS n_tables, COUNT(DISTINCT s.x_dealer) AS n_dealers,
           COUNT(DISTINCT s.x_ip) AS n_ips, COUNT(DISTINCT s.x_product) AS n_products,
           MIN(s.x_date) AS first_seen_d, MAX(s.x_date) AS last_seen_d,
           SUM(s.x_stake) AS stake, SUM(s.x_valid) AS valid, SUM(s.x_rebate) AS rebate,
           SUM(s.x_net) AS net, SUM(-s.x_net *(100.0-s.x_agpct)/100.0) AS agent_cost,
           AVG(100.0-s.x_agpct)                   AS agent_pct,
           AVG(s.x_agpct)                         AS company_retain_pct,
           SUM(-s.x_net *s.x_agpct/100.0)         AS agent_cost_a_legacy,
           SUM(s.x_valid*s.x_agpct/100.0)         AS agent_cost_valid_base_legacy,
          AVG(COALESCE(s.x_rate1,100)) AS retain_pct_lv1, AVG(COALESCE(s.x_rate2,100)) AS retain_pct_lv2,
          AVG(COALESCE(s.x_rate3,100)) AS retain_pct_lv3, AVG(COALESCE(s.x_rate4,100)) AS retain_pct_lv4,
          AVG(COALESCE(s.x_rate5,100)) AS retain_pct_lv5, AVG(s.x_chain_depth) AS chain_depth_avg,
          AVG(COALESCE(100.0-s.x_rate1,0)) AS agent_pct_lv1, AVG(COALESCE(100.0-s.x_rate2,0)) AS agent_pct_lv2,
          AVG(COALESCE(100.0-s.x_rate3,0)) AS agent_pct_lv3, AVG(COALESCE(100.0-s.x_rate4,0)) AS agent_pct_lv4,
          AVG(COALESCE(100.0-s.x_rate5,0)) AS agent_pct_lv5,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate1,0)/100.0)                        AS agent_cost_lv1,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate2,0)/100.0)                        AS agent_cost_lv2,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate3,0)/100.0)                        AS agent_cost_lv3,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate4,0)/100.0)                        AS agent_cost_lv4,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate5,0)/100.0)                        AS agent_cost_lv5,
          SUM(-s.x_net*(COALESCE(100.0-s.x_rate1,0)+COALESCE(100.0-s.x_rate2,0)
                       +COALESCE(100.0-s.x_rate3,0)+COALESCE(100.0-s.x_rate4,0)
                       +COALESCE(100.0-s.x_rate5,0))/100.0)                   AS agent_cost_chain_additive,
          SUM(-s.x_net*(1.0 - CAST(COALESCE(s.x_rate1,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate2,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate3,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate4,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate5,100) AS DOUBLE)/100.0))
                                                                       AS agent_cost_chain_nested,
           AVG(s.x_rbpct) AS rbpct, AVG(s.x_freecomm*1.0) AS freecomm_rate,
           PERCENTILE_APPROX(s.x_stake,0.25) AS p25, PERCENTILE_APPROX(s.x_stake,0.50) AS p50,
           PERCENTILE_APPROX(s.x_stake,0.75) AS p75, PERCENTILE_APPROX(s.x_stake,0.90) AS p90,
           PERCENTILE_APPROX(s.x_stake,0.95) AS p95, PERCENTILE_APPROX(s.x_stake,0.99) AS p99,
           PERCENTILE_APPROX(s.x_valid,0.50) AS p50_valid,
           PERCENTILE_APPROX(s.x_net,0.50)   AS p50_profit,
           SUM(CASE WHEN s.x_rec = 1 THEN s.x_stake ELSE 0 END) AS st_in,
           SUM(CASE WHEN s.x_rec = 1 THEN 1 ELSE 0 END)         AS nb_in,
           SUM(CASE WHEN s.x_rec = 1 THEN s.x_net ELSE 0 END)   AS net_in,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN s.x_stake ELSE 0 END) AS st_out,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN 1 ELSE 0 END)         AS nb_out,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN s.x_net ELSE 0 END)   AS net_out,
           SUM(CASE WHEN s.x_rec=1 THEN s.x_stake ELSE 0 END) AS st_rec,
           SUM(CASE WHEN s.x_rec=1 THEN 1 ELSE 0 END)         AS nb_rec
    FROM x_mk s
    WHERE s.is_clean = 1
      AND s.x_member IS NOT NULL AND TRIM(CAST(s.x_member AS STRING)) <> ''
  ),
      q AS (
        SELECT  变更列,
                SUM(CASE WHEN 取值数 > 1 THEN 1 ELSE 0 END)        AS 发生变更的会员数,
                COUNT(*)                                          AS 在册会员数,
                SUM(CASE WHEN 取值数 > 1 THEN 1 ELSE 0 END) * 1.0 / COUNT(*) AS 变更率
        FROM (
            SELECT  '退水 mem003' AS 变更列, CAST(mem001 AS STRING) AS mem,
                    COUNT(DISTINCT CAST(mem003 AS STRING)) AS 取值数
            FROM ods_mariadb_2b.ods_a168_member_dtl
            WHERE dt >= '2026-03-21' AND dt < '2026-08-07' GROUP BY 1, 2
            UNION ALL
            SELECT  '最大押分 mem009', CAST(mem001 AS STRING),
                    COUNT(DISTINCT CAST(mem009 AS STRING))
            FROM ods_mariadb_2b.ods_a168_member_dtl
            WHERE dt >= '2026-03-21' AND dt < '2026-08-07' GROUP BY 1, 2
            UNION ALL
            SELECT  '新版限額 mem015', CAST(mem001 AS STRING),
                    COUNT(DISTINCT CAST(mem015 AS STRING))
            FROM ods_mariadb_2b.ods_a168_member_dtl
            WHERE dt >= '2026-03-21' AND dt < '2026-08-07' GROUP BY 1, 2
            UNION ALL
            SELECT  '最大可贏 mem012', CAST(mem001 AS STRING),
                    COUNT(DISTINCT CAST(mem012 AS STRING))
            FROM ods_mariadb_2b.ods_a168_member_dtl
            WHERE dt >= '2026-03-21' AND dt < '2026-08-07' GROUP BY 1, 2
            UNION ALL
            SELECT  '可贏可輸起算 mem013', CAST(mem001 AS STRING),
                    COUNT(DISTINCT CAST(mem013 AS STRING))
            FROM ods_mariadb_2b.ods_a168_member_dtl
            WHERE dt >= '2026-03-21' AND dt < '2026-08-07' GROUP BY 1, 2
        ) t
        GROUP BY 变更列
      )
    SELECT q.*,
           -- 一·经济层
           ROUND(e.stake,4) AS stake, ROUND(e.valid,4) AS valid_bet,
           ROUND(-e.net,4) AS profit, e.n_bets, e.n_rounds,
           ROUND(e.net/NULLIF(e.stake,0),8) AS roi,
           ROUND(e.net_in/NULLIF(e.st_in,0),8) AS roi_post,
           ROUND(e.net_out/NULLIF(e.st_out,0),8) AS roi_non_post,
           ROUND((e.net-e.rebate)/NULLIF(e.stake,0),8) AS roi_ex_rebate,
           ROUND(e.net,4) AS roi_numerator, ROUND(e.stake,4) AS roi_denominator,
           CASE WHEN e.stake IS NULL THEN 'NULL_DENOM' WHEN e.stake<=0 THEN 'ZERO_DENOM'
                WHEN e.n_bets<30 THEN 'THIN_EXPOSURE' ELSE 'OK' END AS roi_denominator_status,
           ROUND(e.rebate,4) AS rebate_cost, ROUND(e.agent_cost,4)                           AS cost_complement_b,
       ROUND(e.agent_pct,4)                            AS pct_complement,
       ROUND(e.company_retain_pct,4)                   AS pct_top_bet23,
       'AG03-UNRESOLVED'                                     AS agent_formula_version,
      'ALL5_LEVELS_bet23_to_bet27'                    AS agent_level_scope,
      ROUND(e.agent_cost_lv1,4) AS agent_cost_lv1, ROUND(e.agent_cost_lv2,4) AS agent_cost_lv2,
      ROUND(e.agent_cost_lv3,4) AS agent_cost_lv3, ROUND(e.agent_cost_lv4,4) AS agent_cost_lv4,
      ROUND(e.agent_cost_lv5,4) AS agent_cost_lv5,
      ROUND(e.agent_pct_lv1,6) AS agent_pct_lv1, ROUND(e.agent_pct_lv2,6) AS agent_pct_lv2,
      ROUND(e.agent_pct_lv3,6) AS agent_pct_lv3, ROUND(e.agent_pct_lv4,6) AS agent_pct_lv4,
      ROUND(e.agent_pct_lv5,6) AS agent_pct_lv5,
      ROUND(e.retain_pct_lv1,6) AS retain_pct_lv1, ROUND(e.retain_pct_lv2,6) AS retain_pct_lv2,
      ROUND(e.retain_pct_lv3,6) AS retain_pct_lv3, ROUND(e.retain_pct_lv4,6) AS retain_pct_lv4,
      ROUND(e.retain_pct_lv5,6) AS retain_pct_lv5, ROUND(e.chain_depth_avg,4) AS chain_depth_avg,
      ROUND(e.agent_cost_chain_additive,4)            AS agent_cost_chain_additive,
      ROUND(e.agent_cost_chain_nested,4)              AS agent_cost_chain_nested,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_additive,4) AS residual_chain_additive,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_nested,4)   AS residual_chain_nested,
      'PENDING_AG03'                                  AS decision_status,
      'FALSE'                                         AS admit_to_risk_decision,
      'NOT_FOR_ENFORCEMENT'                           AS deliverable_class,
       ROUND(e.agent_cost_a_legacy,4)                  AS agent_cost_a_legacy,
       ROUND(e.agent_cost_valid_base_legacy,4)         AS agent_cost_valid_base_legacy,
           ROUND(-e.net-e.rebate,4)                        AS ngr,
       ROUND(-e.net-e.rebate-e.agent_cost,4)           AS residual_b,
       ROUND(-e.net-e.rebate-e.agent_cost_a_legacy,4)  AS residual_a,
           ROUND((-e.net-e.rebate)/NULLIF(e.stake,0),8)    AS ngr_rate,
       ROUND((-e.net-e.rebate-e.agent_cost)/NULLIF(e.stake,0),8)   AS residual_b_rate,
      -- 【HF9c · canonical accounting contract】
      --   以下 canonical 字段只增加明确 scope；不删除、不覆盖既有字段。
      --   formal_bet23_* 保持 HF9b 当前生产公式及其 NULL/0 语义；
      --   lv1~lv5 / additive / nested 则分别采用各自原始 e.* 成本字段，
      --   rate 一律从未舍入的 e.* 分子 / e.stake 计算，禁止由展示值反算。
      ROUND(e.agent_cost,4) AS agent_cost_bet23_formal_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost,4) AS net_margin_bet23_formal_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost)/NULLIF(e.stake,0),8) AS net_margin_bet23_formal_rate_canonical,
      ROUND(e.agent_cost_lv1,4) AS agent_cost_lv1_bet23_canonical,
      ROUND(e.agent_cost_lv2,4) AS agent_cost_lv2_bet24_canonical,
      ROUND(e.agent_cost_lv3,4) AS agent_cost_lv3_bet25_canonical,
      ROUND(e.agent_cost_lv4,4) AS agent_cost_lv4_bet26_canonical,
      ROUND(e.agent_cost_lv5,4) AS agent_cost_lv5_bet27_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_lv1,4) AS net_margin_lv1_bet23_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_lv1)/NULLIF(e.stake,0),8) AS net_margin_lv1_bet23_rate_canonical,
      ROUND(e.agent_cost_chain_additive,4) AS agent_cost_chain_additive_canonical,
      ROUND(e.agent_cost_chain_nested,4) AS agent_cost_chain_nested_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_additive,4) AS net_margin_chain_additive_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_nested,4) AS net_margin_chain_nested_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_chain_additive)/NULLIF(e.stake,0),8) AS net_margin_chain_additive_rate_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_chain_nested)/NULLIF(e.stake,0),8) AS net_margin_chain_nested_rate_canonical,
       ROUND((-e.net-e.rebate-e.agent_cost_a_legacy)/NULLIF(e.stake,0),8) AS residual_a_rate,
           -- 二·分布层
           ROUND(e.stake/NULLIF(e.n_bets,0),4) AS avg_stake_per_bet,
           ROUND(e.valid/NULLIF(e.n_rounds,0),4) AS avg_valid_bet_per_round,
           ROUND(-e.net/NULLIF(e.n_rounds,0),4) AS avg_profit_per_round,
           ROUND(-e.net/NULLIF(e.active_days,0),4) AS avg_profit_per_day,
           ROUND(-e.net/NULLIF(e.active_shoes,0),4) AS avg_profit_per_shoe,
           ROUND(e.stake/NULLIF(e.active_days,0),4) AS avg_stake_per_active_day,
           ROUND(e.n_rounds*1.0/NULLIF(e.active_days,0),4) AS avg_rounds_per_active_day,
           ROUND(e.st_in/NULLIF(e.nb_in,0),4) AS avg_stake_post,
           ROUND(e.st_out/NULLIF(e.nb_out,0),4) AS avg_stake_non_post,
           ROUND(e.p25,4) AS p25_stake, ROUND(e.p50,4) AS p50_stake, ROUND(e.p75,4) AS p75_stake,
           ROUND(e.p90,4) AS p90_stake, ROUND(e.p95,4) AS p95_stake, ROUND(e.p99,4) AS p99_stake,
           ROUND(e.p50_valid,4) AS p50_valid_bet, ROUND(e.p50_profit,4) AS p50_profit,
           ROUND(e.p95/NULLIF(e.p50,0),6) AS p95_over_p50,
           ROUND(e.p99/NULLIF(e.p50,0),6) AS p99_over_p50,
           ROUND((e.stake/NULLIF(e.n_bets,0))/NULLIF(e.p50,0),6) AS avg_over_p50,
           -- 三·关系层
           e.n_tables AS common_table_count, e.n_dealers AS common_dealer_count,
           e.n_ips AS common_ip_count, e.n_products AS common_product_count,
           ROUND(e.st_in/NULLIF(e.stake,0),8) AS share_post,
           -- 四·rate 层
           ROUND(-e.net/NULLIF(e.stake,0),8) AS hold_rate,
           ROUND(-e.net_in/NULLIF(e.st_in,0),8) AS hold_rate_post,
           ROUND(e.rebate/NULLIF(e.valid,0),8) AS rebate_rate_actual,
           ROUND(e.rbpct,6) AS rebate_pct_config,
           ROUND(e.valid/NULLIF(e.stake,0),6) AS turnover_multiple,
           ROUND(e.freecomm_rate,6) AS free_comm_rate,
           ROUND(e.net_in/NULLIF(e.st_in,0)-e.net_out/NULLIF(e.st_out,0),8) AS roi_delta_post,
           -- 五·动态层
           e.first_seen_d AS first_seen, e.last_seen_d AS last_seen,
           e.active_days, e.active_shoes, e.active_sessions,
           DATEDIFF(e.last_seen_d, e.first_seen_d)+1 AS span_days,
           ROUND(e.active_days*1.0/NULLIF(DATEDIFF(e.last_seen_d,e.first_seen_d)+1,0),6) AS persistence,
           ROUND((e.st_in/NULLIF(e.nb_in,0))/NULLIF(e.st_out/NULLIF(e.nb_out,0),0),6) AS ramp_post,
           ROUND((e.st_rec/NULLIF(e.nb_rec,0))/NULLIF(e.stake/NULLIF(e.n_bets,0),0),6) AS ramp_recent,
           ROUND((e.st_rec/NULLIF(e.stake,0))/0.30,6) AS stake_ramp,
           -- 六·决策层（HF9g-P5 · D-14 斧正 —— 本件属【全窗基线族】，相对刻度与决策标签一律 NULL）
           --   病灶：x_win 系全窗单行聚合（无 GROUP BY，恒 1 行，此为设计使然，非缺陷），
           --         经 CROSS JOIN 接入后 e.* 全行同值；六层之 NTILE / PERCENT_RANK 施于常数即退化，
           --         PERCENT_RANK 恒 0 ⇒ action_priority 恒判 A，全件 100% 误标。
           --   ★ 斧正原则：不给 x_win 补 GROUP BY —— 那会改变其「全窗基线」语义，属退化。
           --     正解与 #018 之 G-05／G-06 同治：范围外之行不得接受任何下游评分与决策标签。
           --   ★ 本件之 e.* 仍照常供其它列作全窗基线使用，仅六层相对刻度与决策标签置 NULL。
           CAST(NULL AS INT)                                              AS vip_tier,                        -- 空值取值：全窗基线族无实体可分档，置 NULL（NULL＝不适用，非 0）
           CAST(NULL AS DOUBLE)                                           AS economic_value,                  -- 空值取值：同上，禁以常数百分位冒充经济价值
           CAST(NULL AS DOUBLE)                                           AS roi_pr_global,                   -- 空值取值：同上
           CAST(NULL AS DOUBLE)                                           AS risk_value,                      -- 空值取值：兼容列，同上
           CAST(NULL AS DOUBLE)                                           AS pr_stake,                        -- 空值取值：兼容列，同上
           CAST(NULL AS DOUBLE)                                           AS pr_global,                       -- 空值取值：同上
           CAST(NULL AS DOUBLE)                                           AS pr_qualified,                    -- 空值取值：同上
           'GLOBAL_BASELINE_NO_ENTITY_RANKING'                            AS pr_qualified_population,         -- 字面取值：血统 —— 明示本件为全窗基线族，无实体排序总体
           CAST(NULL AS BIGINT)                                           AS pr_global_population_n,          -- 空值取值：血统 —— 不适用
           CAST(NULL AS BIGINT)                                           AS pr_qualified_population_n,       -- 空值取值：血统 —— 不适用
           'NOT_APPLICABLE_GLOBAL_BASELINE'                               AS pr_calculation_method,           -- 字面取值：血统 —— 算法不适用
           'HF9g-P5'                                                      AS pr_calculation_version,          -- 字面取值：血统 —— 算法版本
           CAST(NULL AS STRING)                                           AS evidence_flag,                   -- 空值取值：证据旗标不适用于全窗基线
           CAST(NULL AS STRING)                                           AS evidence_rate,                   -- 空值取值：同上
           CAST(NULL AS DOUBLE)                                           AS hold_ci_halfwidth_approx,        -- 空值取值：同上
           'X 全窗基线 · 不参与实体赏罚'                                    AS action_priority                  -- 字面取值：★ D-14 斧正 —— 本族恒不入赏罚，取代原 100% 误标之「A」
    FROM q
    CROSS JOIN x_win e
  ) y
) z
-- ── 逐批 WHERE 阶梯（★ 口诀：上界 ＝ 下界 ＋ 100000，两数同进）──
--    本件 T_true 未测，无需先跑 T_true；以 0 / 100000 控制本批返回区间，末批由实际行数 < 100000 判定
--    WHERE z.audit_rn >        0 AND z.audit_rn <=   100000   -- 第 1 批
--    WHERE z.audit_rn >   100000 AND z.audit_rn <=   200000   -- 第 2 批
--    WHERE z.audit_rn >   200000 AND z.audit_rn <=   300000   -- 第 3 批
--    WHERE z.audit_rn >   300000 AND z.audit_rn <=   400000   -- 第 4 批
--    WHERE z.audit_rn >   400000 AND z.audit_rn <=   500000   -- 第 5 批
--    WHERE z.audit_rn >   500000 AND z.audit_rn <=   600000   -- 第 6 批
--    WHERE z.audit_rn >   600000 AND z.audit_rn <=   700000   -- 第 7 批
--    …余批类推。第 k 批：WHERE z.audit_rn > (k-1)*100000 AND z.audit_rn <= k*100000
--    某批返回 < 100000 行即为末批，其后不再取。
--
--    ⚠ 常见误写（务必避开）：只推下界而上界不动 ——
--        WHERE z.audit_rn > 100000 AND z.audit_rn <= 100000   ← 自相矛盾，恒为假，返回空集
--        WHERE z.audit_rn > 200000 AND z.audit_rn <= 100000   ← 同上，空集
--      两个数必须**同时**前进，且始终相差 100000。
--      下界 ＝ 上一批之上界；上界 ＝ 本批之上界。
WHERE z.audit_rn > 0 AND z.audit_rn <= 100000 -- ★ HF9c 本批区间
ORDER BY z.audit_rn;


-- ══════════════════════════════════════════════════════════════════════════════════════════════
--  87. TL03_pseudo_treatment.csv   [总包行 8276~8324 · 原 6 列 ＋六层约 60 列]
--     典型学：M09 处置限额　派生旗标：post（s.x_rec = 1 · 仅供 CASE 条件聚合，全包无任何 WHERE/AND/HAVING 以此过滤）　连接：q.`member_id`
-- ══════════════════════════════════════════════════════════════════════════════════════════════
-- ── ① 先跑 T_true 留档（不足 100000 者一次导全，不必分批）──
-- ── ① T_true：HF9c 不再强制预跑完整 COUNT。
--    本批实际返回行数 < 100000 即判定为末批；全批完成后以各批 n_rows / audit_rn 范围核对总量。

-- ── ② 分批取数：第 1 批。第 k 批只改末行两数为 (k-1)*100000 与 k*100000 ──
--    审计字段二（REDTEAM 2026-08-24 裁定 · 四锁）：
--      audit_rn  全局观测坐标 —— 由**与原版审计版逐字同一**之排序键所生，两版可逐行对账
--      batch_id  物理分批信息 —— 该行所属批次，由 audit_rn 算得，非引擎所赋
--    ★ 锁三：二者皆为审计字段，**不得进入任何业务指标计算**。
--    ★ 锁四：两版经 audit_rn 逐行字段核验后，方可宣布输出完全一致。

-- ── ③ 每批取回后自证四数（任一不符即停手回报，禁止放行）──
--    n_rows        = COUNT(*)      须等于 COUNT(DISTINCT audit_rn)   （批内无重复）
--    audit_rn_min  = MIN(audit_rn) 须等于 (k-1)*100000 + 1           （与上批严丝合缝）
--    audit_rn_max  = MAX(audit_rn) 须等于 min + n_rows - 1           （批内无缺口）
--    全批取毕再验：各批 audit_rn 之并集 = 1 .. T_true，无缺号、无重号。
--     ★ 首行＝平台真净亏最多者（已扣退水与代理占成）。
--
SELECT z.*,
       CAST(FLOOR((z.audit_rn - 1) / 100000) + 1 AS INT)          AS batch_id,
       'A168_HF9F_20260827_0900' AS run_id,
       '2026-08-27 09:00:00' AS snapshot_sync_time
FROM (
  SELECT y.*,
         ROW_NUMBER() OVER (ORDER BY y.`residual_b` ASC, y.`roi` DESC, y.`member_id`, y.`change_date`, y.`action_type`, y.`value_before`, y.`value_after`, y.`direction`) AS audit_rn
  FROM (
    WITH
      x_ranked AS (
    SELECT b.bet01, b.bet03, b.bet04, b.bet05, b.bet09, b.bet11, b.bet13,
           b.bet15, b.bet16, b.bet17, b.bet18, b.bet19, b.bet20, b.bet21,
           b.bet22, b.bet23, b.bet24, b.bet25, b.bet26, b.bet27, b.bet38, b.bet39, b.category, b.commission,
           b.dt, b.eid, b.ip, b.validbet, b.updatetime, b.sync_time,
           ROW_NUMBER() OVER (
             PARTITION BY b.bet01
             ORDER BY b.updatetime DESC, b.sync_time DESC, b.dt DESC)      AS x_rn
    FROM ods_mariadb_2b.ods_a168_bet02 b
    WHERE b.dt >= '2026-03-21' AND b.dt < '2026-08-07'
      AND b.bet02 = '101'
      AND b.sync_time <= '2026-08-27 09:00:00'
  ),
    x_testagent AS (
    SELECT age001 AS agent_id FROM ods_mariadb_2b.ods_a168_agent WHERE age022 = '1'
  ),
    x_bs0 AS (
    SELECT b.bet05 AS x_member, b.eid AS x_dealer, b.bet39 AS x_table,
           b.bet03 AS x_shoe, b.ip AS x_ip, b.bet09 AS x_product, b.dt AS x_date,
           CONCAT_WS('|', b.bet03, b.bet04, b.bet39)                      AS x_round,
           CONCAT_WS('|', b.bet39, b.bet03)                               AS x_tblshoe,
           CAST(NULLIF(TRIM(b.bet04),'') AS INT)                          AS x_rno,
           CASE WHEN b.dt >= '2026-07-08' THEN 1 ELSE 0 END               AS x_rec,
           CASE WHEN TRIM(b.commission)='1' THEN 1 ELSE 0 END             AS x_freecomm,
           CAST(NULLIF(TRIM(b.bet13),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_stake,
           CAST(NULLIF(TRIM(b.validbet),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_valid,
           CAST(NULLIF(TRIM(b.bet16),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_rebate,
           CAST(NULLIF(TRIM(b.bet17),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_net,
           CAST(NULLIF(TRIM(b.bet15),'') AS DECIMAL(20,6))                AS x_rbpct,
           COALESCE(CAST(NULLIF(TRIM(b.bet23),'') AS DECIMAL(20,6)),0)   AS x_agpct,
          NULLIF(CAST(NULLIF(TRIM(b.bet23),'') AS DECIMAL(20,6)),0)     AS x_rate1,
          NULLIF(CAST(NULLIF(TRIM(b.bet24),'') AS DECIMAL(20,6)),0)     AS x_rate2,
          NULLIF(CAST(NULLIF(TRIM(b.bet25),'') AS DECIMAL(20,6)),0)     AS x_rate3,
          NULLIF(CAST(NULLIF(TRIM(b.bet26),'') AS DECIMAL(20,6)),0)     AS x_rate4,
          NULLIF(CAST(NULLIF(TRIM(b.bet27),'') AS DECIMAL(20,6)),0)     AS x_rate5,
          (CASE WHEN NULLIF(CAST(NULLIF(TRIM(b.bet22),'') AS BIGINT),0) IS NOT NULL THEN 5
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet21),'') AS BIGINT),0) IS NOT NULL THEN 4
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet20),'') AS BIGINT),0) IS NOT NULL THEN 3
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet19),'') AS BIGINT),0) IS NOT NULL THEN 2
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet18),'') AS BIGINT),0) IS NOT NULL THEN 1
                ELSE 0 END)                                             AS x_chain_depth,
           CASE WHEN COALESCE(t1.agent_id,t2.agent_id,t3.agent_id,
                              t4.agent_id,t5.agent_id) IS NOT NULL
                THEN 1 ELSE 0 END                                        AS f_testline
    FROM x_ranked b
    LEFT JOIN x_testagent t1 ON t1.agent_id = b.bet18
    LEFT JOIN x_testagent t2 ON t2.agent_id = b.bet19
    LEFT JOIN x_testagent t3 ON t3.agent_id = b.bet20
    LEFT JOIN x_testagent t4 ON t4.agent_id = b.bet21
    LEFT JOIN x_testagent t5 ON t5.agent_id = b.bet22
    WHERE b.x_rn = 1
      AND b.category='1' AND UPPER(TRIM(b.bet38))='N'
      AND CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8)) > 0
  ),
  x_mk AS (
    SELECT s.*,
           CASE WHEN s.f_testline = 0 THEN 1 ELSE 0 END                 AS is_clean
    FROM x_bs0 s
  ),
  x_agg AS (
    SELECT s.x_member                                                        AS x_key,
           COUNT(*) AS n_bets, COUNT(DISTINCT s.x_round) AS n_rounds,
           COUNT(DISTINCT s.x_date) AS active_days, COUNT(DISTINCT s.x_tblshoe) AS active_shoes,
           COUNT(DISTINCT CONCAT_WS('|', s.x_date, s.x_table)) AS active_sessions,
           COUNT(DISTINCT s.x_table) AS n_tables, COUNT(DISTINCT s.x_dealer) AS n_dealers,
           COUNT(DISTINCT s.x_ip) AS n_ips, COUNT(DISTINCT s.x_product) AS n_products,
           MIN(s.x_date) AS first_seen_d, MAX(s.x_date) AS last_seen_d,
           SUM(s.x_stake) AS stake, SUM(s.x_valid) AS valid, SUM(s.x_rebate) AS rebate,
           SUM(s.x_net) AS net, SUM(-s.x_net *(100.0-s.x_agpct)/100.0) AS agent_cost,
           AVG(100.0-s.x_agpct)                   AS agent_pct,
           AVG(s.x_agpct)                         AS company_retain_pct,
           SUM(-s.x_net *s.x_agpct/100.0)         AS agent_cost_a_legacy,
           SUM(s.x_valid*s.x_agpct/100.0)         AS agent_cost_valid_base_legacy,
          AVG(COALESCE(s.x_rate1,100)) AS retain_pct_lv1, AVG(COALESCE(s.x_rate2,100)) AS retain_pct_lv2,
          AVG(COALESCE(s.x_rate3,100)) AS retain_pct_lv3, AVG(COALESCE(s.x_rate4,100)) AS retain_pct_lv4,
          AVG(COALESCE(s.x_rate5,100)) AS retain_pct_lv5, AVG(s.x_chain_depth) AS chain_depth_avg,
          AVG(COALESCE(100.0-s.x_rate1,0)) AS agent_pct_lv1, AVG(COALESCE(100.0-s.x_rate2,0)) AS agent_pct_lv2,
          AVG(COALESCE(100.0-s.x_rate3,0)) AS agent_pct_lv3, AVG(COALESCE(100.0-s.x_rate4,0)) AS agent_pct_lv4,
          AVG(COALESCE(100.0-s.x_rate5,0)) AS agent_pct_lv5,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate1,0)/100.0)                        AS agent_cost_lv1,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate2,0)/100.0)                        AS agent_cost_lv2,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate3,0)/100.0)                        AS agent_cost_lv3,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate4,0)/100.0)                        AS agent_cost_lv4,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate5,0)/100.0)                        AS agent_cost_lv5,
          SUM(-s.x_net*(COALESCE(100.0-s.x_rate1,0)+COALESCE(100.0-s.x_rate2,0)
                       +COALESCE(100.0-s.x_rate3,0)+COALESCE(100.0-s.x_rate4,0)
                       +COALESCE(100.0-s.x_rate5,0))/100.0)                   AS agent_cost_chain_additive,
          SUM(-s.x_net*(1.0 - CAST(COALESCE(s.x_rate1,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate2,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate3,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate4,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate5,100) AS DOUBLE)/100.0))
                                                                       AS agent_cost_chain_nested,
           AVG(s.x_rbpct) AS rbpct, AVG(s.x_freecomm*1.0) AS freecomm_rate,
           PERCENTILE_APPROX(s.x_stake,0.25) AS p25, PERCENTILE_APPROX(s.x_stake,0.50) AS p50,
           PERCENTILE_APPROX(s.x_stake,0.75) AS p75, PERCENTILE_APPROX(s.x_stake,0.90) AS p90,
           PERCENTILE_APPROX(s.x_stake,0.95) AS p95, PERCENTILE_APPROX(s.x_stake,0.99) AS p99,
           PERCENTILE_APPROX(s.x_valid,0.50) AS p50_valid,
           PERCENTILE_APPROX(s.x_net,0.50)   AS p50_profit,
           SUM(CASE WHEN s.x_rec = 1 THEN s.x_stake ELSE 0 END) AS st_in,
           SUM(CASE WHEN s.x_rec = 1 THEN 1 ELSE 0 END)         AS nb_in,
           SUM(CASE WHEN s.x_rec = 1 THEN s.x_net ELSE 0 END)   AS net_in,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN s.x_stake ELSE 0 END) AS st_out,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN 1 ELSE 0 END)         AS nb_out,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN s.x_net ELSE 0 END)   AS net_out,
           SUM(CASE WHEN s.x_rec=1 THEN s.x_stake ELSE 0 END) AS st_rec,
           SUM(CASE WHEN s.x_rec=1 THEN 1 ELSE 0 END)         AS nb_rec
    FROM x_mk s
    WHERE s.is_clean = 1
      AND s.x_member IS NOT NULL AND TRIM(CAST(s.x_member AS STRING)) <> ''
    GROUP BY s.x_member
  ),
      q AS (
        WITH snap AS (
            SELECT  CAST(mem001 AS STRING)                        AS member_id,
                    dt,
                    CAST(NULLIF(TRIM(mem003), '') AS DOUBLE)      AS rebate,
                    CAST(NULLIF(TRIM(mem009), '') AS DOUBLE)      AS maxbet,
                    CAST(NULLIF(TRIM(mem012), '') AS DOUBLE)      AS maxwin,
                    CAST(NULLIF(TRIM(mem014), '') AS DOUBLE)      AS maxloss
            FROM    ods_mariadb_2b.ods_a168_member_dtl
            WHERE   dt >= '2026-03-21'
              AND   dt <  '2026-08-07'
              AND   CAST(mem002 AS STRING) = '1'
        ),
        lagged AS (
            SELECT  member_id, dt, rebate, maxbet, maxwin, maxloss,
                    LAG(rebate)  OVER (PARTITION BY member_id ORDER BY dt) AS rebate_prev,
                    LAG(maxbet)  OVER (PARTITION BY member_id ORDER BY dt) AS maxbet_prev,
                    LAG(maxwin)  OVER (PARTITION BY member_id ORDER BY dt) AS maxwin_prev,
                    LAG(maxloss) OVER (PARTITION BY member_id ORDER BY dt) AS maxloss_prev
            FROM    snap
        )
        SELECT  member_id,
                dt                                                AS change_date,
                CASE WHEN rebate <> rebate_prev THEN '退水'
                     WHEN maxbet <> maxbet_prev THEN '最大押分'
                     WHEN maxwin <> maxwin_prev THEN '最大可贏'
                     ELSE '最大可輸' END                           AS action_type,
                CASE WHEN rebate <> rebate_prev THEN rebate_prev
                     WHEN maxbet <> maxbet_prev THEN maxbet_prev
                     WHEN maxwin <> maxwin_prev THEN maxwin_prev
                     ELSE maxloss_prev END                         AS value_before,
                CASE WHEN rebate <> rebate_prev THEN rebate
                     WHEN maxbet <> maxbet_prev THEN maxbet
                     WHEN maxwin <> maxwin_prev THEN maxwin
                     ELSE maxloss END                              AS value_after,
                CASE WHEN rebate <> rebate_prev THEN
                          CASE WHEN rebate < rebate_prev THEN '收紧' ELSE '放宽' END
                     WHEN maxbet <> maxbet_prev THEN
                          CASE WHEN maxbet < maxbet_prev THEN '收紧' ELSE '放宽' END
                     WHEN maxwin <> maxwin_prev THEN
                          CASE WHEN maxwin < maxwin_prev THEN '收紧' ELSE '放宽' END
                     ELSE CASE WHEN maxloss < maxloss_prev THEN '收紧' ELSE '放宽' END
                END                                                AS direction
        FROM    lagged
        WHERE   rebate_prev IS NOT NULL
          AND   (rebate  <> rebate_prev
             OR  maxbet  <> maxbet_prev
             OR  maxwin  <> maxwin_prev
             OR  maxloss <> maxloss_prev)
      )
    SELECT q.*,
           -- 一·经济层
           ROUND(e.stake,4) AS stake, ROUND(e.valid,4) AS valid_bet,
           ROUND(-e.net,4) AS profit, e.n_bets, e.n_rounds,
           ROUND(e.net/NULLIF(e.stake,0),8) AS roi,
           ROUND(e.net_in/NULLIF(e.st_in,0),8) AS roi_post,
           ROUND(e.net_out/NULLIF(e.st_out,0),8) AS roi_non_post,
           ROUND((e.net-e.rebate)/NULLIF(e.stake,0),8) AS roi_ex_rebate,
           ROUND(e.net,4) AS roi_numerator, ROUND(e.stake,4) AS roi_denominator,
           CASE WHEN e.stake IS NULL THEN 'NULL_DENOM' WHEN e.stake<=0 THEN 'ZERO_DENOM'
                WHEN e.n_bets<30 THEN 'THIN_EXPOSURE' ELSE 'OK' END AS roi_denominator_status,
           ROUND(e.rebate,4) AS rebate_cost, ROUND(e.agent_cost,4)                           AS cost_complement_b,
       ROUND(e.agent_pct,4)                            AS pct_complement,
       ROUND(e.company_retain_pct,4)                   AS pct_top_bet23,
       'AG03-UNRESOLVED'                                     AS agent_formula_version,
      'ALL5_LEVELS_bet23_to_bet27'                    AS agent_level_scope,
      ROUND(e.agent_cost_lv1,4) AS agent_cost_lv1, ROUND(e.agent_cost_lv2,4) AS agent_cost_lv2,
      ROUND(e.agent_cost_lv3,4) AS agent_cost_lv3, ROUND(e.agent_cost_lv4,4) AS agent_cost_lv4,
      ROUND(e.agent_cost_lv5,4) AS agent_cost_lv5,
      ROUND(e.agent_pct_lv1,6) AS agent_pct_lv1, ROUND(e.agent_pct_lv2,6) AS agent_pct_lv2,
      ROUND(e.agent_pct_lv3,6) AS agent_pct_lv3, ROUND(e.agent_pct_lv4,6) AS agent_pct_lv4,
      ROUND(e.agent_pct_lv5,6) AS agent_pct_lv5,
      ROUND(e.retain_pct_lv1,6) AS retain_pct_lv1, ROUND(e.retain_pct_lv2,6) AS retain_pct_lv2,
      ROUND(e.retain_pct_lv3,6) AS retain_pct_lv3, ROUND(e.retain_pct_lv4,6) AS retain_pct_lv4,
      ROUND(e.retain_pct_lv5,6) AS retain_pct_lv5, ROUND(e.chain_depth_avg,4) AS chain_depth_avg,
      ROUND(e.agent_cost_chain_additive,4)            AS agent_cost_chain_additive,
      ROUND(e.agent_cost_chain_nested,4)              AS agent_cost_chain_nested,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_additive,4) AS residual_chain_additive,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_nested,4)   AS residual_chain_nested,
      'PENDING_AG03'                                  AS decision_status,
      'FALSE'                                         AS admit_to_risk_decision,
      'NOT_FOR_ENFORCEMENT'                           AS deliverable_class,
       ROUND(e.agent_cost_a_legacy,4)                  AS agent_cost_a_legacy,
       ROUND(e.agent_cost_valid_base_legacy,4)         AS agent_cost_valid_base_legacy,
           ROUND(-e.net-e.rebate,4)                        AS ngr,
       ROUND(-e.net-e.rebate-e.agent_cost,4)           AS residual_b,
       ROUND(-e.net-e.rebate-e.agent_cost_a_legacy,4)  AS residual_a,
           ROUND((-e.net-e.rebate)/NULLIF(e.stake,0),8)    AS ngr_rate,
       ROUND((-e.net-e.rebate-e.agent_cost)/NULLIF(e.stake,0),8)   AS residual_b_rate,
      -- 【HF9c · canonical accounting contract】
      --   以下 canonical 字段只增加明确 scope；不删除、不覆盖既有字段。
      --   formal_bet23_* 保持 HF9b 当前生产公式及其 NULL/0 语义；
      --   lv1~lv5 / additive / nested 则分别采用各自原始 e.* 成本字段，
      --   rate 一律从未舍入的 e.* 分子 / e.stake 计算，禁止由展示值反算。
      ROUND(e.agent_cost,4) AS agent_cost_bet23_formal_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost,4) AS net_margin_bet23_formal_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost)/NULLIF(e.stake,0),8) AS net_margin_bet23_formal_rate_canonical,
      ROUND(e.agent_cost_lv1,4) AS agent_cost_lv1_bet23_canonical,
      ROUND(e.agent_cost_lv2,4) AS agent_cost_lv2_bet24_canonical,
      ROUND(e.agent_cost_lv3,4) AS agent_cost_lv3_bet25_canonical,
      ROUND(e.agent_cost_lv4,4) AS agent_cost_lv4_bet26_canonical,
      ROUND(e.agent_cost_lv5,4) AS agent_cost_lv5_bet27_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_lv1,4) AS net_margin_lv1_bet23_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_lv1)/NULLIF(e.stake,0),8) AS net_margin_lv1_bet23_rate_canonical,
      ROUND(e.agent_cost_chain_additive,4) AS agent_cost_chain_additive_canonical,
      ROUND(e.agent_cost_chain_nested,4) AS agent_cost_chain_nested_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_additive,4) AS net_margin_chain_additive_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_nested,4) AS net_margin_chain_nested_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_chain_additive)/NULLIF(e.stake,0),8) AS net_margin_chain_additive_rate_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_chain_nested)/NULLIF(e.stake,0),8) AS net_margin_chain_nested_rate_canonical,
       ROUND((-e.net-e.rebate-e.agent_cost_a_legacy)/NULLIF(e.stake,0),8) AS residual_a_rate,
           -- 二·分布层
           ROUND(e.stake/NULLIF(e.n_bets,0),4) AS avg_stake_per_bet,
           ROUND(e.valid/NULLIF(e.n_rounds,0),4) AS avg_valid_bet_per_round,
           ROUND(-e.net/NULLIF(e.n_rounds,0),4) AS avg_profit_per_round,
           ROUND(-e.net/NULLIF(e.active_days,0),4) AS avg_profit_per_day,
           ROUND(-e.net/NULLIF(e.active_shoes,0),4) AS avg_profit_per_shoe,
           ROUND(e.stake/NULLIF(e.active_days,0),4) AS avg_stake_per_active_day,
           ROUND(e.n_rounds*1.0/NULLIF(e.active_days,0),4) AS avg_rounds_per_active_day,
           ROUND(e.st_in/NULLIF(e.nb_in,0),4) AS avg_stake_post,
           ROUND(e.st_out/NULLIF(e.nb_out,0),4) AS avg_stake_non_post,
           ROUND(e.p25,4) AS p25_stake, ROUND(e.p50,4) AS p50_stake, ROUND(e.p75,4) AS p75_stake,
           ROUND(e.p90,4) AS p90_stake, ROUND(e.p95,4) AS p95_stake, ROUND(e.p99,4) AS p99_stake,
           ROUND(e.p50_valid,4) AS p50_valid_bet, ROUND(e.p50_profit,4) AS p50_profit,
           ROUND(e.p95/NULLIF(e.p50,0),6) AS p95_over_p50,
           ROUND(e.p99/NULLIF(e.p50,0),6) AS p99_over_p50,
           ROUND((e.stake/NULLIF(e.n_bets,0))/NULLIF(e.p50,0),6) AS avg_over_p50,
           -- 三·关系层
           e.n_tables AS common_table_count, e.n_dealers AS common_dealer_count,
           e.n_ips AS common_ip_count, e.n_products AS common_product_count,
           ROUND(e.st_in/NULLIF(e.stake,0),8) AS share_post,
           -- 四·rate 层
           ROUND(-e.net/NULLIF(e.stake,0),8) AS hold_rate,
           ROUND(-e.net_in/NULLIF(e.st_in,0),8) AS hold_rate_post,
           ROUND(e.rebate/NULLIF(e.valid,0),8) AS rebate_rate_actual,
           ROUND(e.rbpct,6) AS rebate_pct_config,
           ROUND(e.valid/NULLIF(e.stake,0),6) AS turnover_multiple,
           ROUND(e.freecomm_rate,6) AS free_comm_rate,
           ROUND(e.net_in/NULLIF(e.st_in,0)-e.net_out/NULLIF(e.st_out,0),8) AS roi_delta_post,
           -- 五·动态层
           e.first_seen_d AS first_seen, e.last_seen_d AS last_seen,
           e.active_days, e.active_shoes, e.active_sessions,
           DATEDIFF(e.last_seen_d, e.first_seen_d)+1 AS span_days,
           ROUND(e.active_days*1.0/NULLIF(DATEDIFF(e.last_seen_d,e.first_seen_d)+1,0),6) AS persistence,
           ROUND((e.st_in/NULLIF(e.nb_in,0))/NULLIF(e.st_out/NULLIF(e.nb_out,0),0),6) AS ramp_post,
           ROUND((e.st_rec/NULLIF(e.nb_rec,0))/NULLIF(e.stake/NULLIF(e.n_bets,0),0),6) AS ramp_recent,
           ROUND((e.st_rec/NULLIF(e.stake,0))/0.30,6) AS stake_ramp,
           -- 六·决策层（HF9f · 详见档头【HF9f 变更说明】；本段两版逐字同一）
           NTILE(5) OVER (ORDER BY e.stake) AS vip_tier,                                                        -- 窗口取值：相对刻度 B 族，全体五等分；须连同下方血统五元组一并解读，禁作硬阈值判型
           PERCENT_RANK() OVER (ORDER BY -e.net-e.rebate-e.agent_cost)    AS economic_value,                    -- 窗口取值：HF9f·F-19 修正 —— HF9e 写作 -(-…) 双负号致方向颠倒（#075 实测 corr(economic_value, residual_b) = -1.0000）；今与 action_priority 排序键归一，值大即平台真净利高
           PERCENT_RANK() OVER (ORDER BY e.net/NULLIF(e.stake,0))         AS roi_pr_global,                     -- 窗口取值：HF9f·F-17 正名 —— 本列实为 ROI（玩家净回报率）之全体百分位，与「风险」无关；旧名 risk_value 见下一行
           PERCENT_RANK() OVER (ORDER BY e.net/NULLIF(e.stake,0))         AS risk_value,                        -- 窗口取值：兼容列，恒等于 roi_pr_global，仅为下游迁移窗保留；HF9g 起废弃，禁新引用
           PERCENT_RANK() OVER (ORDER BY e.stake)                         AS pr_stake,                          -- 窗口取值：兼容列，恒等于 pr_global，原名保留以免断链
           PERCENT_RANK() OVER (ORDER BY e.stake)                         AS pr_global,                         -- 窗口取值：HF9f·F-1 双轨之一 —— 全体口径百分位，参照总体即本件全部输出行
           CASE WHEN e.n_rounds >= 30                                                                           -- 条件分支：起始分支 —— 仅在合格子集内计算合格口径百分位
                  THEN PERCENT_RANK() OVER (PARTITION BY CASE WHEN e.n_rounds >= 30 THEN 1 ELSE 0 END ORDER BY e.stake)  -- 分支取值：以合格与否分区，故本值即 n_rounds>=30 子集内之百分位
                ELSE NULL END                                             AS pr_qualified,                      -- 条件分支：收束上方分支 —— 不合格者留 NULL（NULL＝未测，非 0），产出「pr_qualified」
           'n_rounds>=30'                                                 AS pr_qualified_population,           -- 字面取值：血统 —— 合格子集之定义
           COUNT(*) OVER ()                                               AS pr_global_population_n,            -- 窗口取值：血统 —— 全体口径之参照总体规模，渲染时现算，禁写死
           SUM(CASE WHEN e.n_rounds >= 30 THEN 1 ELSE 0 END) OVER ()      AS pr_qualified_population_n,         -- 窗口取值：血统 —— 合格子集之参照总体规模，现算，禁写死
           'PERCENT_RANK_OVER_ORDER_BY_e_stake'                           AS pr_calculation_method,             -- 字面取值：血统 —— 算法标识
           'HF9f'                                                         AS pr_calculation_version,            -- 字面取值：血统 —— 算法版本
           CASE WHEN e.n_rounds IS NULL OR e.n_rounds < 30 THEN 'THIN_ROUNDS' ELSE 'OK' END AS evidence_flag,   -- 条件分支：HF9f·F-2a 证据旗标 —— THIN_ROUNDS 者禁入执行队列，仅入观察队列
           CASE WHEN e.n_rounds IS NULL       THEN NULL                                                         -- 条件分支：起始分支 —— 未测者留 NULL（自家铁律：NULL ≠ 0）
                WHEN e.n_rounds >= 31483      THEN 'L1_POWERED'                                                 -- 分支判定：MDE 反解第一档
                WHEN e.n_rounds >= 15409      THEN 'L2_CI_1P5'                                                  -- 分支判定：MDE 反解第二档
                WHEN e.n_rounds >=  8668      THEN 'L3_CI_2P0'                                                  -- 分支判定：MDE 反解第三档
                WHEN e.n_rounds >=  3852      THEN 'L4_CI_3P0'                                                  -- 分支判定：MDE 反解第四档
                ELSE 'L5_INSUFFICIENT' END                                AS evidence_rate,                     -- 条件分支：收束上方 —— HF9f·F-3 证据分档，承 HF9e 前议之 MDE 反解五档，须于 F-4 敏感性实验后复核
           ROUND(1.96 * 0.95 / SQRT(NULLIF(CAST(e.n_rounds AS DOUBLE),0)),8) AS hold_ci_halfwidth_approx,       -- 比率表达式：HF9f·F-3 逐行现算之 95% 半宽近似；常数 0.95 为登记值，本轮 #075 实测每局 ROI 隐含 σ 于最薄层为 0.9249，二者差异待 F-4 裁定
           CASE WHEN e.stake IS NULL OR e.stake<=0 OR e.n_bets<30 OR e.n_rounds IS NULL OR e.n_rounds<30 THEN 'Z 证据不足 · 不动作'  -- 条件分支：HF9f·F-2 双条件取严 —— HF9e 仅卡 e.n_bets<30，致 n_bets>=30 而 n_rounds<30 者绕过 Z（#075 实测 18,537 名，其中 8,145 名已入 A/D 待裁）；今两条件并列取严
                WHEN PERCENT_RANK() OVER (ORDER BY -e.net-e.rebate-e.agent_cost)<=0.10                          -- 分支判定：平台真净利之最低十分位
                  THEN 'A 净亏最大十分位 · 优先复核'                                                             -- 分支取值：HF9f·F-20 正名 —— 本档 Σresidual_b 于 #075 实测 = -100,236,896，系平台净亏最大群，旧名「残值最低十分位 · 待裁」名实不符
                WHEN PERCENT_RANK() OVER (ORDER BY -e.net-e.rebate-e.agent_cost)>=0.80                          -- 分支判定：平台真净利之最高二十分位
                  THEN 'D 净利最高二十分位 · 优先留存'                                                           -- 分支取值：HF9f·F-20 正名 —— 本档 Σresidual_b 于 #075 实测 = +281,733,190，系核心利润源；与 A 档方向相反，旧版同标「待裁」属名实不符
                ELSE 'E 常规' END                                          AS action_priority                   -- 条件分支：收束上方判词，产出「action_priority」
    FROM q
    LEFT JOIN x_agg e ON CAST(e.x_key AS STRING) = CAST(q.`member_id` AS STRING)
  ) y
) z
-- ── 逐批 WHERE 阶梯（★ 口诀：上界 ＝ 下界 ＋ 100000，两数同进）──
--    本件 T_true 未测，无需先跑 T_true；以 0 / 100000 控制本批返回区间，末批由实际行数 < 100000 判定
--    WHERE z.audit_rn >        0 AND z.audit_rn <=   100000   -- 第 1 批
--    WHERE z.audit_rn >   100000 AND z.audit_rn <=   200000   -- 第 2 批
--    WHERE z.audit_rn >   200000 AND z.audit_rn <=   300000   -- 第 3 批
--    WHERE z.audit_rn >   300000 AND z.audit_rn <=   400000   -- 第 4 批
--    WHERE z.audit_rn >   400000 AND z.audit_rn <=   500000   -- 第 5 批
--    WHERE z.audit_rn >   500000 AND z.audit_rn <=   600000   -- 第 6 批
--    WHERE z.audit_rn >   600000 AND z.audit_rn <=   700000   -- 第 7 批
--    …余批类推。第 k 批：WHERE z.audit_rn > (k-1)*100000 AND z.audit_rn <= k*100000
--    某批返回 < 100000 行即为末批，其后不再取。
--
--    ⚠ 常见误写（务必避开）：只推下界而上界不动 ——
--        WHERE z.audit_rn > 100000 AND z.audit_rn <= 100000   ← 自相矛盾，恒为假，返回空集
--        WHERE z.audit_rn > 200000 AND z.audit_rn <= 100000   ← 同上，空集
--      两个数必须**同时**前进，且始终相差 100000。
--      下界 ＝ 上一批之上界；上界 ＝ 本批之上界。
WHERE z.audit_rn > 0 AND z.audit_rn <= 100000 -- ★ HF9c 本批区间
ORDER BY z.audit_rn;


-- ══════════════════════════════════════════════════════════════════════════════════════════════
--  88. TL03b_pseudo_treatment.csv   [总包行 8417~8466 · 原 8 列 ＋六层约 60 列]
--     典型学：M09 处置限额　派生旗标：post（s.x_rec = 1 · 仅供 CASE 条件聚合，全包无任何 WHERE/AND/HAVING 以此过滤）　连接：q.`member_id`
-- ══════════════════════════════════════════════════════════════════════════════════════════════
-- ── ① 先跑 T_true 留档（不足 100000 者一次导全，不必分批）──
-- ── ① T_true：HF9c 不再强制预跑完整 COUNT。
--    本批实际返回行数 < 100000 即判定为末批；全批完成后以各批 n_rows / audit_rn 范围核对总量。

-- ── ② 分批取数：第 1 批。第 k 批只改末行两数为 (k-1)*100000 与 k*100000 ──
--    审计字段二（REDTEAM 2026-08-24 裁定 · 四锁）：
--      audit_rn  全局观测坐标 —— 由**与原版审计版逐字同一**之排序键所生，两版可逐行对账
--      batch_id  物理分批信息 —— 该行所属批次，由 audit_rn 算得，非引擎所赋
--    ★ 锁三：二者皆为审计字段，**不得进入任何业务指标计算**。
--    ★ 锁四：两版经 audit_rn 逐行字段核验后，方可宣布输出完全一致。

-- ── ③ 每批取回后自证四数（任一不符即停手回报，禁止放行）──
--    n_rows        = COUNT(*)      须等于 COUNT(DISTINCT audit_rn)   （批内无重复）
--    audit_rn_min  = MIN(audit_rn) 须等于 (k-1)*100000 + 1           （与上批严丝合缝）
--    audit_rn_max  = MAX(audit_rn) 须等于 min + n_rows - 1           （批内无缺口）
--    全批取毕再验：各批 audit_rn 之并集 = 1 .. T_true，无缺号、无重号。
--     ★ 首行＝平台真净亏最多者（已扣退水与代理占成）。
--
SELECT z.*,
       CAST(FLOOR((z.audit_rn - 1) / 100000) + 1 AS INT)          AS batch_id,
       'A168_HF9F_20260827_0900' AS run_id,
       '2026-08-27 09:00:00' AS snapshot_sync_time
FROM (
  SELECT y.*,
         ROW_NUMBER() OVER (ORDER BY y.`residual_b` ASC, y.`roi` DESC, y.`member_id`, y.`cate`, y.`prev_date`, y.`change_date`, y.`action_type`, y.`value_before`, y.`value_after`, y.`direction`) AS audit_rn
  FROM (
    WITH
      x_ranked AS (
    SELECT b.bet01, b.bet03, b.bet04, b.bet05, b.bet09, b.bet11, b.bet13,
           b.bet15, b.bet16, b.bet17, b.bet18, b.bet19, b.bet20, b.bet21,
           b.bet22, b.bet23, b.bet24, b.bet25, b.bet26, b.bet27, b.bet38, b.bet39, b.category, b.commission,
           b.dt, b.eid, b.ip, b.validbet, b.updatetime, b.sync_time,
           ROW_NUMBER() OVER (
             PARTITION BY b.bet01
             ORDER BY b.updatetime DESC, b.sync_time DESC, b.dt DESC)      AS x_rn
    FROM ods_mariadb_2b.ods_a168_bet02 b
    WHERE b.dt >= '2026-03-21' AND b.dt < '2026-08-07'
      AND b.bet02 = '101'
      AND b.sync_time <= '2026-08-27 09:00:00'
  ),
    x_testagent AS (
    SELECT age001 AS agent_id FROM ods_mariadb_2b.ods_a168_agent WHERE age022 = '1'
  ),
    x_bs0 AS (
    SELECT b.bet05 AS x_member, b.eid AS x_dealer, b.bet39 AS x_table,
           b.bet03 AS x_shoe, b.ip AS x_ip, b.bet09 AS x_product, b.dt AS x_date,
           CONCAT_WS('|', b.bet03, b.bet04, b.bet39)                      AS x_round,
           CONCAT_WS('|', b.bet39, b.bet03)                               AS x_tblshoe,
           CAST(NULLIF(TRIM(b.bet04),'') AS INT)                          AS x_rno,
           CASE WHEN b.dt >= '2026-07-08' THEN 1 ELSE 0 END               AS x_rec,
           CASE WHEN TRIM(b.commission)='1' THEN 1 ELSE 0 END             AS x_freecomm,
           CAST(NULLIF(TRIM(b.bet13),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_stake,
           CAST(NULLIF(TRIM(b.validbet),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_valid,
           CAST(NULLIF(TRIM(b.bet16),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_rebate,
           CAST(NULLIF(TRIM(b.bet17),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_net,
           CAST(NULLIF(TRIM(b.bet15),'') AS DECIMAL(20,6))                AS x_rbpct,
           COALESCE(CAST(NULLIF(TRIM(b.bet23),'') AS DECIMAL(20,6)),0)   AS x_agpct,
          NULLIF(CAST(NULLIF(TRIM(b.bet23),'') AS DECIMAL(20,6)),0)     AS x_rate1,
          NULLIF(CAST(NULLIF(TRIM(b.bet24),'') AS DECIMAL(20,6)),0)     AS x_rate2,
          NULLIF(CAST(NULLIF(TRIM(b.bet25),'') AS DECIMAL(20,6)),0)     AS x_rate3,
          NULLIF(CAST(NULLIF(TRIM(b.bet26),'') AS DECIMAL(20,6)),0)     AS x_rate4,
          NULLIF(CAST(NULLIF(TRIM(b.bet27),'') AS DECIMAL(20,6)),0)     AS x_rate5,
          (CASE WHEN NULLIF(CAST(NULLIF(TRIM(b.bet22),'') AS BIGINT),0) IS NOT NULL THEN 5
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet21),'') AS BIGINT),0) IS NOT NULL THEN 4
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet20),'') AS BIGINT),0) IS NOT NULL THEN 3
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet19),'') AS BIGINT),0) IS NOT NULL THEN 2
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet18),'') AS BIGINT),0) IS NOT NULL THEN 1
                ELSE 0 END)                                             AS x_chain_depth,
           CASE WHEN COALESCE(t1.agent_id,t2.agent_id,t3.agent_id,
                              t4.agent_id,t5.agent_id) IS NOT NULL
                THEN 1 ELSE 0 END                                        AS f_testline
    FROM x_ranked b
    LEFT JOIN x_testagent t1 ON t1.agent_id = b.bet18
    LEFT JOIN x_testagent t2 ON t2.agent_id = b.bet19
    LEFT JOIN x_testagent t3 ON t3.agent_id = b.bet20
    LEFT JOIN x_testagent t4 ON t4.agent_id = b.bet21
    LEFT JOIN x_testagent t5 ON t5.agent_id = b.bet22
    WHERE b.x_rn = 1
      AND b.category='1' AND UPPER(TRIM(b.bet38))='N'
      AND CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8)) > 0
  ),
  x_mk AS (
    SELECT s.*,
           CASE WHEN s.f_testline = 0 THEN 1 ELSE 0 END                 AS is_clean
    FROM x_bs0 s
  ),
  x_agg AS (
    SELECT s.x_member                                                        AS x_key,
           COUNT(*) AS n_bets, COUNT(DISTINCT s.x_round) AS n_rounds,
           COUNT(DISTINCT s.x_date) AS active_days, COUNT(DISTINCT s.x_tblshoe) AS active_shoes,
           COUNT(DISTINCT CONCAT_WS('|', s.x_date, s.x_table)) AS active_sessions,
           COUNT(DISTINCT s.x_table) AS n_tables, COUNT(DISTINCT s.x_dealer) AS n_dealers,
           COUNT(DISTINCT s.x_ip) AS n_ips, COUNT(DISTINCT s.x_product) AS n_products,
           MIN(s.x_date) AS first_seen_d, MAX(s.x_date) AS last_seen_d,
           SUM(s.x_stake) AS stake, SUM(s.x_valid) AS valid, SUM(s.x_rebate) AS rebate,
           SUM(s.x_net) AS net, SUM(-s.x_net *(100.0-s.x_agpct)/100.0) AS agent_cost,
           AVG(100.0-s.x_agpct)                   AS agent_pct,
           AVG(s.x_agpct)                         AS company_retain_pct,
           SUM(-s.x_net *s.x_agpct/100.0)         AS agent_cost_a_legacy,
           SUM(s.x_valid*s.x_agpct/100.0)         AS agent_cost_valid_base_legacy,
          AVG(COALESCE(s.x_rate1,100)) AS retain_pct_lv1, AVG(COALESCE(s.x_rate2,100)) AS retain_pct_lv2,
          AVG(COALESCE(s.x_rate3,100)) AS retain_pct_lv3, AVG(COALESCE(s.x_rate4,100)) AS retain_pct_lv4,
          AVG(COALESCE(s.x_rate5,100)) AS retain_pct_lv5, AVG(s.x_chain_depth) AS chain_depth_avg,
          AVG(COALESCE(100.0-s.x_rate1,0)) AS agent_pct_lv1, AVG(COALESCE(100.0-s.x_rate2,0)) AS agent_pct_lv2,
          AVG(COALESCE(100.0-s.x_rate3,0)) AS agent_pct_lv3, AVG(COALESCE(100.0-s.x_rate4,0)) AS agent_pct_lv4,
          AVG(COALESCE(100.0-s.x_rate5,0)) AS agent_pct_lv5,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate1,0)/100.0)                        AS agent_cost_lv1,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate2,0)/100.0)                        AS agent_cost_lv2,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate3,0)/100.0)                        AS agent_cost_lv3,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate4,0)/100.0)                        AS agent_cost_lv4,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate5,0)/100.0)                        AS agent_cost_lv5,
          SUM(-s.x_net*(COALESCE(100.0-s.x_rate1,0)+COALESCE(100.0-s.x_rate2,0)
                       +COALESCE(100.0-s.x_rate3,0)+COALESCE(100.0-s.x_rate4,0)
                       +COALESCE(100.0-s.x_rate5,0))/100.0)                   AS agent_cost_chain_additive,
          SUM(-s.x_net*(1.0 - CAST(COALESCE(s.x_rate1,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate2,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate3,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate4,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate5,100) AS DOUBLE)/100.0))
                                                                       AS agent_cost_chain_nested,
           AVG(s.x_rbpct) AS rbpct, AVG(s.x_freecomm*1.0) AS freecomm_rate,
           PERCENTILE_APPROX(s.x_stake,0.25) AS p25, PERCENTILE_APPROX(s.x_stake,0.50) AS p50,
           PERCENTILE_APPROX(s.x_stake,0.75) AS p75, PERCENTILE_APPROX(s.x_stake,0.90) AS p90,
           PERCENTILE_APPROX(s.x_stake,0.95) AS p95, PERCENTILE_APPROX(s.x_stake,0.99) AS p99,
           PERCENTILE_APPROX(s.x_valid,0.50) AS p50_valid,
           PERCENTILE_APPROX(s.x_net,0.50)   AS p50_profit,
           SUM(CASE WHEN s.x_rec = 1 THEN s.x_stake ELSE 0 END) AS st_in,
           SUM(CASE WHEN s.x_rec = 1 THEN 1 ELSE 0 END)         AS nb_in,
           SUM(CASE WHEN s.x_rec = 1 THEN s.x_net ELSE 0 END)   AS net_in,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN s.x_stake ELSE 0 END) AS st_out,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN 1 ELSE 0 END)         AS nb_out,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN s.x_net ELSE 0 END)   AS net_out,
           SUM(CASE WHEN s.x_rec=1 THEN s.x_stake ELSE 0 END) AS st_rec,
           SUM(CASE WHEN s.x_rec=1 THEN 1 ELSE 0 END)         AS nb_rec
    FROM x_mk s
    WHERE s.is_clean = 1
      AND s.x_member IS NOT NULL AND TRIM(CAST(s.x_member AS STRING)) <> ''
    GROUP BY s.x_member
  ),
      q AS (
        WITH snap AS (
            SELECT  CAST(mem001 AS STRING)                        AS member_id,
                    CAST(mem002 AS STRING)                        AS cate,
                    dt,
                    COALESCE(CAST(NULLIF(TRIM(mem003), '') AS DOUBLE), -999999) AS rebate,
                    COALESCE(CAST(NULLIF(TRIM(mem009), '') AS DOUBLE), -999999) AS maxbet,
                    COALESCE(CAST(NULLIF(TRIM(mem012), '') AS DOUBLE), -999999) AS maxwin,
                    COALESCE(CAST(NULLIF(TRIM(mem014), '') AS DOUBLE), -999999) AS maxloss
            FROM    ods_mariadb_2b.ods_a168_member_dtl
            WHERE   dt >= '2026-03-21'
              AND   dt <= '2026-07-18'
              AND   dt NOT IN ('2026-05-21', '2026-07-18')
        ),
        lagged AS (
            SELECT  member_id, cate, dt, rebate, maxbet, maxwin, maxloss,
                    LAG(rebate)  OVER (PARTITION BY member_id, cate ORDER BY dt) AS rebate_p,
                    LAG(maxbet)  OVER (PARTITION BY member_id, cate ORDER BY dt) AS maxbet_p,
                    LAG(maxwin)  OVER (PARTITION BY member_id, cate ORDER BY dt) AS maxwin_p,
                    LAG(maxloss) OVER (PARTITION BY member_id, cate ORDER BY dt) AS maxloss_p,
                    LAG(dt)      OVER (PARTITION BY member_id, cate ORDER BY dt) AS dt_p
            FROM    snap
        )
        SELECT  member_id,
                cate,
                dt_p                                              AS prev_date,
                dt                                                AS change_date,
                CASE WHEN rebate  <> rebate_p  THEN '退水'
                     WHEN maxbet  <> maxbet_p  THEN '最大押分'
                     WHEN maxwin  <> maxwin_p  THEN '最大可贏'
                     ELSE '最大可輸' END                           AS action_type,
                CASE WHEN rebate  <> rebate_p  THEN rebate_p
                     WHEN maxbet  <> maxbet_p  THEN maxbet_p
                     WHEN maxwin  <> maxwin_p  THEN maxwin_p
                     ELSE maxloss_p END                            AS value_before,
                CASE WHEN rebate  <> rebate_p  THEN rebate
                     WHEN maxbet  <> maxbet_p  THEN maxbet
                     WHEN maxwin  <> maxwin_p  THEN maxwin
                     ELSE maxloss END                              AS value_after,
                CASE WHEN rebate  <> rebate_p  THEN CASE WHEN rebate  < rebate_p  THEN '收紧' ELSE '放宽' END
                     WHEN maxbet  <> maxbet_p  THEN CASE WHEN maxbet  < maxbet_p  THEN '收紧' ELSE '放宽' END
                     WHEN maxwin  <> maxwin_p  THEN CASE WHEN maxwin  < maxwin_p  THEN '收紧' ELSE '放宽' END
                     ELSE CASE WHEN maxloss < maxloss_p THEN '收紧' ELSE '放宽' END
                END                                                AS direction
        FROM    lagged
        WHERE   dt_p IS NOT NULL
          AND  (rebate  <> rebate_p
             OR maxbet  <> maxbet_p
             OR maxwin  <> maxwin_p
             OR maxloss <> maxloss_p)
      )
    SELECT q.*,
           -- 一·经济层
           ROUND(e.stake,4) AS stake, ROUND(e.valid,4) AS valid_bet,
           ROUND(-e.net,4) AS profit, e.n_bets, e.n_rounds,
           ROUND(e.net/NULLIF(e.stake,0),8) AS roi,
           ROUND(e.net_in/NULLIF(e.st_in,0),8) AS roi_post,
           ROUND(e.net_out/NULLIF(e.st_out,0),8) AS roi_non_post,
           ROUND((e.net-e.rebate)/NULLIF(e.stake,0),8) AS roi_ex_rebate,
           ROUND(e.net,4) AS roi_numerator, ROUND(e.stake,4) AS roi_denominator,
           CASE WHEN e.stake IS NULL THEN 'NULL_DENOM' WHEN e.stake<=0 THEN 'ZERO_DENOM'
                WHEN e.n_bets<30 THEN 'THIN_EXPOSURE' ELSE 'OK' END AS roi_denominator_status,
           ROUND(e.rebate,4) AS rebate_cost, ROUND(e.agent_cost,4)                           AS cost_complement_b,
       ROUND(e.agent_pct,4)                            AS pct_complement,
       ROUND(e.company_retain_pct,4)                   AS pct_top_bet23,
       'AG03-UNRESOLVED'                                     AS agent_formula_version,
      'ALL5_LEVELS_bet23_to_bet27'                    AS agent_level_scope,
      ROUND(e.agent_cost_lv1,4) AS agent_cost_lv1, ROUND(e.agent_cost_lv2,4) AS agent_cost_lv2,
      ROUND(e.agent_cost_lv3,4) AS agent_cost_lv3, ROUND(e.agent_cost_lv4,4) AS agent_cost_lv4,
      ROUND(e.agent_cost_lv5,4) AS agent_cost_lv5,
      ROUND(e.agent_pct_lv1,6) AS agent_pct_lv1, ROUND(e.agent_pct_lv2,6) AS agent_pct_lv2,
      ROUND(e.agent_pct_lv3,6) AS agent_pct_lv3, ROUND(e.agent_pct_lv4,6) AS agent_pct_lv4,
      ROUND(e.agent_pct_lv5,6) AS agent_pct_lv5,
      ROUND(e.retain_pct_lv1,6) AS retain_pct_lv1, ROUND(e.retain_pct_lv2,6) AS retain_pct_lv2,
      ROUND(e.retain_pct_lv3,6) AS retain_pct_lv3, ROUND(e.retain_pct_lv4,6) AS retain_pct_lv4,
      ROUND(e.retain_pct_lv5,6) AS retain_pct_lv5, ROUND(e.chain_depth_avg,4) AS chain_depth_avg,
      ROUND(e.agent_cost_chain_additive,4)            AS agent_cost_chain_additive,
      ROUND(e.agent_cost_chain_nested,4)              AS agent_cost_chain_nested,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_additive,4) AS residual_chain_additive,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_nested,4)   AS residual_chain_nested,
      'PENDING_AG03'                                  AS decision_status,
      'FALSE'                                         AS admit_to_risk_decision,
      'NOT_FOR_ENFORCEMENT'                           AS deliverable_class,
       ROUND(e.agent_cost_a_legacy,4)                  AS agent_cost_a_legacy,
       ROUND(e.agent_cost_valid_base_legacy,4)         AS agent_cost_valid_base_legacy,
           ROUND(-e.net-e.rebate,4)                        AS ngr,
       ROUND(-e.net-e.rebate-e.agent_cost,4)           AS residual_b,
       ROUND(-e.net-e.rebate-e.agent_cost_a_legacy,4)  AS residual_a,
           ROUND((-e.net-e.rebate)/NULLIF(e.stake,0),8)    AS ngr_rate,
       ROUND((-e.net-e.rebate-e.agent_cost)/NULLIF(e.stake,0),8)   AS residual_b_rate,
      -- 【HF9c · canonical accounting contract】
      --   以下 canonical 字段只增加明确 scope；不删除、不覆盖既有字段。
      --   formal_bet23_* 保持 HF9b 当前生产公式及其 NULL/0 语义；
      --   lv1~lv5 / additive / nested 则分别采用各自原始 e.* 成本字段，
      --   rate 一律从未舍入的 e.* 分子 / e.stake 计算，禁止由展示值反算。
      ROUND(e.agent_cost,4) AS agent_cost_bet23_formal_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost,4) AS net_margin_bet23_formal_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost)/NULLIF(e.stake,0),8) AS net_margin_bet23_formal_rate_canonical,
      ROUND(e.agent_cost_lv1,4) AS agent_cost_lv1_bet23_canonical,
      ROUND(e.agent_cost_lv2,4) AS agent_cost_lv2_bet24_canonical,
      ROUND(e.agent_cost_lv3,4) AS agent_cost_lv3_bet25_canonical,
      ROUND(e.agent_cost_lv4,4) AS agent_cost_lv4_bet26_canonical,
      ROUND(e.agent_cost_lv5,4) AS agent_cost_lv5_bet27_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_lv1,4) AS net_margin_lv1_bet23_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_lv1)/NULLIF(e.stake,0),8) AS net_margin_lv1_bet23_rate_canonical,
      ROUND(e.agent_cost_chain_additive,4) AS agent_cost_chain_additive_canonical,
      ROUND(e.agent_cost_chain_nested,4) AS agent_cost_chain_nested_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_additive,4) AS net_margin_chain_additive_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_nested,4) AS net_margin_chain_nested_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_chain_additive)/NULLIF(e.stake,0),8) AS net_margin_chain_additive_rate_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_chain_nested)/NULLIF(e.stake,0),8) AS net_margin_chain_nested_rate_canonical,
       ROUND((-e.net-e.rebate-e.agent_cost_a_legacy)/NULLIF(e.stake,0),8) AS residual_a_rate,
           -- 二·分布层
           ROUND(e.stake/NULLIF(e.n_bets,0),4) AS avg_stake_per_bet,
           ROUND(e.valid/NULLIF(e.n_rounds,0),4) AS avg_valid_bet_per_round,
           ROUND(-e.net/NULLIF(e.n_rounds,0),4) AS avg_profit_per_round,
           ROUND(-e.net/NULLIF(e.active_days,0),4) AS avg_profit_per_day,
           ROUND(-e.net/NULLIF(e.active_shoes,0),4) AS avg_profit_per_shoe,
           ROUND(e.stake/NULLIF(e.active_days,0),4) AS avg_stake_per_active_day,
           ROUND(e.n_rounds*1.0/NULLIF(e.active_days,0),4) AS avg_rounds_per_active_day,
           ROUND(e.st_in/NULLIF(e.nb_in,0),4) AS avg_stake_post,
           ROUND(e.st_out/NULLIF(e.nb_out,0),4) AS avg_stake_non_post,
           ROUND(e.p25,4) AS p25_stake, ROUND(e.p50,4) AS p50_stake, ROUND(e.p75,4) AS p75_stake,
           ROUND(e.p90,4) AS p90_stake, ROUND(e.p95,4) AS p95_stake, ROUND(e.p99,4) AS p99_stake,
           ROUND(e.p50_valid,4) AS p50_valid_bet, ROUND(e.p50_profit,4) AS p50_profit,
           ROUND(e.p95/NULLIF(e.p50,0),6) AS p95_over_p50,
           ROUND(e.p99/NULLIF(e.p50,0),6) AS p99_over_p50,
           ROUND((e.stake/NULLIF(e.n_bets,0))/NULLIF(e.p50,0),6) AS avg_over_p50,
           -- 三·关系层
           e.n_tables AS common_table_count, e.n_dealers AS common_dealer_count,
           e.n_ips AS common_ip_count, e.n_products AS common_product_count,
           ROUND(e.st_in/NULLIF(e.stake,0),8) AS share_post,
           -- 四·rate 层
           ROUND(-e.net/NULLIF(e.stake,0),8) AS hold_rate,
           ROUND(-e.net_in/NULLIF(e.st_in,0),8) AS hold_rate_post,
           ROUND(e.rebate/NULLIF(e.valid,0),8) AS rebate_rate_actual,
           ROUND(e.rbpct,6) AS rebate_pct_config,
           ROUND(e.valid/NULLIF(e.stake,0),6) AS turnover_multiple,
           ROUND(e.freecomm_rate,6) AS free_comm_rate,
           ROUND(e.net_in/NULLIF(e.st_in,0)-e.net_out/NULLIF(e.st_out,0),8) AS roi_delta_post,
           -- 五·动态层
           e.first_seen_d AS first_seen, e.last_seen_d AS last_seen,
           e.active_days, e.active_shoes, e.active_sessions,
           DATEDIFF(e.last_seen_d, e.first_seen_d)+1 AS span_days,
           ROUND(e.active_days*1.0/NULLIF(DATEDIFF(e.last_seen_d,e.first_seen_d)+1,0),6) AS persistence,
           ROUND((e.st_in/NULLIF(e.nb_in,0))/NULLIF(e.st_out/NULLIF(e.nb_out,0),0),6) AS ramp_post,
           ROUND((e.st_rec/NULLIF(e.nb_rec,0))/NULLIF(e.stake/NULLIF(e.n_bets,0),0),6) AS ramp_recent,
           ROUND((e.st_rec/NULLIF(e.stake,0))/0.30,6) AS stake_ramp,
           -- 六·决策层（HF9f · 详见档头【HF9f 变更说明】；本段两版逐字同一）
           NTILE(5) OVER (ORDER BY e.stake) AS vip_tier,                                                        -- 窗口取值：相对刻度 B 族，全体五等分；须连同下方血统五元组一并解读，禁作硬阈值判型
           PERCENT_RANK() OVER (ORDER BY -e.net-e.rebate-e.agent_cost)    AS economic_value,                    -- 窗口取值：HF9f·F-19 修正 —— HF9e 写作 -(-…) 双负号致方向颠倒（#075 实测 corr(economic_value, residual_b) = -1.0000）；今与 action_priority 排序键归一，值大即平台真净利高
           PERCENT_RANK() OVER (ORDER BY e.net/NULLIF(e.stake,0))         AS roi_pr_global,                     -- 窗口取值：HF9f·F-17 正名 —— 本列实为 ROI（玩家净回报率）之全体百分位，与「风险」无关；旧名 risk_value 见下一行
           PERCENT_RANK() OVER (ORDER BY e.net/NULLIF(e.stake,0))         AS risk_value,                        -- 窗口取值：兼容列，恒等于 roi_pr_global，仅为下游迁移窗保留；HF9g 起废弃，禁新引用
           PERCENT_RANK() OVER (ORDER BY e.stake)                         AS pr_stake,                          -- 窗口取值：兼容列，恒等于 pr_global，原名保留以免断链
           PERCENT_RANK() OVER (ORDER BY e.stake)                         AS pr_global,                         -- 窗口取值：HF9f·F-1 双轨之一 —— 全体口径百分位，参照总体即本件全部输出行
           CASE WHEN e.n_rounds >= 30                                                                           -- 条件分支：起始分支 —— 仅在合格子集内计算合格口径百分位
                  THEN PERCENT_RANK() OVER (PARTITION BY CASE WHEN e.n_rounds >= 30 THEN 1 ELSE 0 END ORDER BY e.stake)  -- 分支取值：以合格与否分区，故本值即 n_rounds>=30 子集内之百分位
                ELSE NULL END                                             AS pr_qualified,                      -- 条件分支：收束上方分支 —— 不合格者留 NULL（NULL＝未测，非 0），产出「pr_qualified」
           'n_rounds>=30'                                                 AS pr_qualified_population,           -- 字面取值：血统 —— 合格子集之定义
           COUNT(*) OVER ()                                               AS pr_global_population_n,            -- 窗口取值：血统 —— 全体口径之参照总体规模，渲染时现算，禁写死
           SUM(CASE WHEN e.n_rounds >= 30 THEN 1 ELSE 0 END) OVER ()      AS pr_qualified_population_n,         -- 窗口取值：血统 —— 合格子集之参照总体规模，现算，禁写死
           'PERCENT_RANK_OVER_ORDER_BY_e_stake'                           AS pr_calculation_method,             -- 字面取值：血统 —— 算法标识
           'HF9f'                                                         AS pr_calculation_version,            -- 字面取值：血统 —— 算法版本
           CASE WHEN e.n_rounds IS NULL OR e.n_rounds < 30 THEN 'THIN_ROUNDS' ELSE 'OK' END AS evidence_flag,   -- 条件分支：HF9f·F-2a 证据旗标 —— THIN_ROUNDS 者禁入执行队列，仅入观察队列
           CASE WHEN e.n_rounds IS NULL       THEN NULL                                                         -- 条件分支：起始分支 —— 未测者留 NULL（自家铁律：NULL ≠ 0）
                WHEN e.n_rounds >= 31483      THEN 'L1_POWERED'                                                 -- 分支判定：MDE 反解第一档
                WHEN e.n_rounds >= 15409      THEN 'L2_CI_1P5'                                                  -- 分支判定：MDE 反解第二档
                WHEN e.n_rounds >=  8668      THEN 'L3_CI_2P0'                                                  -- 分支判定：MDE 反解第三档
                WHEN e.n_rounds >=  3852      THEN 'L4_CI_3P0'                                                  -- 分支判定：MDE 反解第四档
                ELSE 'L5_INSUFFICIENT' END                                AS evidence_rate,                     -- 条件分支：收束上方 —— HF9f·F-3 证据分档，承 HF9e 前议之 MDE 反解五档，须于 F-4 敏感性实验后复核
           ROUND(1.96 * 0.95 / SQRT(NULLIF(CAST(e.n_rounds AS DOUBLE),0)),8) AS hold_ci_halfwidth_approx,       -- 比率表达式：HF9f·F-3 逐行现算之 95% 半宽近似；常数 0.95 为登记值，本轮 #075 实测每局 ROI 隐含 σ 于最薄层为 0.9249，二者差异待 F-4 裁定
           CASE WHEN e.stake IS NULL OR e.stake<=0 OR e.n_bets<30 OR e.n_rounds IS NULL OR e.n_rounds<30 THEN 'Z 证据不足 · 不动作'  -- 条件分支：HF9f·F-2 双条件取严 —— HF9e 仅卡 e.n_bets<30，致 n_bets>=30 而 n_rounds<30 者绕过 Z（#075 实测 18,537 名，其中 8,145 名已入 A/D 待裁）；今两条件并列取严
                WHEN PERCENT_RANK() OVER (ORDER BY -e.net-e.rebate-e.agent_cost)<=0.10                          -- 分支判定：平台真净利之最低十分位
                  THEN 'A 净亏最大十分位 · 优先复核'                                                             -- 分支取值：HF9f·F-20 正名 —— 本档 Σresidual_b 于 #075 实测 = -100,236,896，系平台净亏最大群，旧名「残值最低十分位 · 待裁」名实不符
                WHEN PERCENT_RANK() OVER (ORDER BY -e.net-e.rebate-e.agent_cost)>=0.80                          -- 分支判定：平台真净利之最高二十分位
                  THEN 'D 净利最高二十分位 · 优先留存'                                                           -- 分支取值：HF9f·F-20 正名 —— 本档 Σresidual_b 于 #075 实测 = +281,733,190，系核心利润源；与 A 档方向相反，旧版同标「待裁」属名实不符
                ELSE 'E 常规' END                                          AS action_priority                   -- 条件分支：收束上方判词，产出「action_priority」
    FROM q
    LEFT JOIN x_agg e ON CAST(e.x_key AS STRING) = CAST(q.`member_id` AS STRING)
  ) y
) z
-- ── 逐批 WHERE 阶梯（★ 口诀：上界 ＝ 下界 ＋ 100000，两数同进）──
--    本件 T_true 未测，无需先跑 T_true；以 0 / 100000 控制本批返回区间，末批由实际行数 < 100000 判定
--    WHERE z.audit_rn >        0 AND z.audit_rn <=   100000   -- 第 1 批
--    WHERE z.audit_rn >   100000 AND z.audit_rn <=   200000   -- 第 2 批
--    WHERE z.audit_rn >   200000 AND z.audit_rn <=   300000   -- 第 3 批
--    WHERE z.audit_rn >   300000 AND z.audit_rn <=   400000   -- 第 4 批
--    WHERE z.audit_rn >   400000 AND z.audit_rn <=   500000   -- 第 5 批
--    WHERE z.audit_rn >   500000 AND z.audit_rn <=   600000   -- 第 6 批
--    WHERE z.audit_rn >   600000 AND z.audit_rn <=   700000   -- 第 7 批
--    …余批类推。第 k 批：WHERE z.audit_rn > (k-1)*100000 AND z.audit_rn <= k*100000
--    某批返回 < 100000 行即为末批，其后不再取。
--
--    ⚠ 常见误写（务必避开）：只推下界而上界不动 ——
--        WHERE z.audit_rn > 100000 AND z.audit_rn <= 100000   ← 自相矛盾，恒为假，返回空集
--        WHERE z.audit_rn > 200000 AND z.audit_rn <= 100000   ← 同上，空集
--      两个数必须**同时**前进，且始终相差 100000。
--      下界 ＝ 上一批之上界；上界 ＝ 本批之上界。
WHERE z.audit_rn > 0 AND z.audit_rn <= 100000 -- ★ HF9c 本批区间
ORDER BY z.audit_rn;


-- ══════════════════════════════════════════════════════════════════════════════════════════════
--  89. TL04_log_schema.csv   [总包行 8383~8389 · 原 5 列 ＋六层约 60 列]
--     典型学：Z00 基建/元数据　派生旗标：recent（s.x_rec = 1 · 仅供 CASE 条件聚合，全包无任何 WHERE/AND/HAVING 以此过滤）　连接：全窗基线
-- ══════════════════════════════════════════════════════════════════════════════════════════════
-- ★ W-64 · D-14 警示（本件属 x_win 族 · 66 件之一 · 详见 §Z 段 D-14 全案）
--   本件以 `CROSS JOIN x_win e` 接入全局基线，x_win 无 GROUP BY ⇒ 恒 1 行 ⇒ e.* 全行同值。
--   故：economic_value / roi_pr_global / risk_value / pr_stake / pr_global 恒为 0；
--       action_priority 每一行皆为「A 净亏最大十分位 · 优先复核」（Z 分支永不触发）；
--       evidence_rate 恒为最高档；vip_tier 由常数键分档 ⇒ 无信息且非确定。
--   ⇒ 本件决策层三列 **NOT_FOR_DECISION**，裁定前不得用于排班、抽查或汇报。
-- ── ① 先跑 T_true 留档（不足 100000 者一次导全，不必分批）──
-- ── ① T_true：HF9c 不再强制预跑完整 COUNT。
--    本批实际返回行数 < 100000 即判定为末批；全批完成后以各批 n_rows / audit_rn 范围核对总量。

-- ── ② 分批取数：第 1 批。第 k 批只改末行两数为 (k-1)*100000 与 k*100000 ──
--    审计字段二（REDTEAM 2026-08-24 裁定 · 四锁）：
--      audit_rn  全局观测坐标 —— 由**与原版审计版逐字同一**之排序键所生，两版可逐行对账
--      batch_id  物理分批信息 —— 该行所属批次，由 audit_rn 算得，非引擎所赋
--    ★ 锁三：二者皆为审计字段，**不得进入任何业务指标计算**。
--    ★ 锁四：两版经 audit_rn 逐行字段核验后，方可宣布输出完全一致。

-- ── ③ 每批取回后自证四数（任一不符即停手回报，禁止放行）──
--    n_rows        = COUNT(*)      须等于 COUNT(DISTINCT audit_rn)   （批内无重复）
--    audit_rn_min  = MIN(audit_rn) 须等于 (k-1)*100000 + 1           （与上批严丝合缝）
--    audit_rn_max  = MAX(audit_rn) 须等于 min + n_rows - 1           （批内无缺口）
--    全批取毕再验：各批 audit_rn 之并集 = 1 .. T_true，无缺号、无重号。
--     ★ 首行＝平台真净亏最多者（已扣退水与代理占成）。
--
SELECT z.*,
       CAST(FLOOR((z.audit_rn - 1) / 100000) + 1 AS INT)          AS batch_id,
       'A168_HF9F_20260827_0900' AS run_id,
       '2026-08-27 09:00:00' AS snapshot_sync_time
FROM (
  SELECT y.*,
         ROW_NUMBER() OVER (ORDER BY y.`residual_b` ASC, y.`roi` DESC, y.`TABLE_NAME`, y.`ORDINAL_POSITION`, y.`COLUMN_NAME`, y.`DATA_TYPE`, y.`COLUMN_COMMENT`) AS audit_rn
  FROM (
    WITH
      x_ranked AS (
    SELECT b.bet01, b.bet03, b.bet04, b.bet05, b.bet09, b.bet11, b.bet13,
           b.bet15, b.bet16, b.bet17, b.bet18, b.bet19, b.bet20, b.bet21,
           b.bet22, b.bet23, b.bet24, b.bet25, b.bet26, b.bet27, b.bet38, b.bet39, b.category, b.commission,
           b.dt, b.eid, b.ip, b.validbet, b.updatetime, b.sync_time,
           ROW_NUMBER() OVER (
             PARTITION BY b.bet01
             ORDER BY b.updatetime DESC, b.sync_time DESC, b.dt DESC)      AS x_rn
    FROM ods_mariadb_2b.ods_a168_bet02 b
    WHERE b.dt >= '2026-03-21' AND b.dt < '2026-08-07'
      AND b.bet02 = '101'
      AND b.sync_time <= '2026-08-27 09:00:00'
  ),
    x_testagent AS (
    SELECT age001 AS agent_id FROM ods_mariadb_2b.ods_a168_agent WHERE age022 = '1'
  ),
    x_bs0 AS (
    SELECT b.bet05 AS x_member, b.eid AS x_dealer, b.bet39 AS x_table,
           b.bet03 AS x_shoe, b.ip AS x_ip, b.bet09 AS x_product, b.dt AS x_date,
           CONCAT_WS('|', b.bet03, b.bet04, b.bet39)                      AS x_round,
           CONCAT_WS('|', b.bet39, b.bet03)                               AS x_tblshoe,
           CAST(NULLIF(TRIM(b.bet04),'') AS INT)                          AS x_rno,
           CASE WHEN b.dt >= '2026-07-08' THEN 1 ELSE 0 END               AS x_rec,
           CASE WHEN TRIM(b.commission)='1' THEN 1 ELSE 0 END             AS x_freecomm,
           CAST(NULLIF(TRIM(b.bet13),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_stake,
           CAST(NULLIF(TRIM(b.validbet),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_valid,
           CAST(NULLIF(TRIM(b.bet16),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_rebate,
           CAST(NULLIF(TRIM(b.bet17),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_net,
           CAST(NULLIF(TRIM(b.bet15),'') AS DECIMAL(20,6))                AS x_rbpct,
           COALESCE(CAST(NULLIF(TRIM(b.bet23),'') AS DECIMAL(20,6)),0)   AS x_agpct,
          NULLIF(CAST(NULLIF(TRIM(b.bet23),'') AS DECIMAL(20,6)),0)     AS x_rate1,
          NULLIF(CAST(NULLIF(TRIM(b.bet24),'') AS DECIMAL(20,6)),0)     AS x_rate2,
          NULLIF(CAST(NULLIF(TRIM(b.bet25),'') AS DECIMAL(20,6)),0)     AS x_rate3,
          NULLIF(CAST(NULLIF(TRIM(b.bet26),'') AS DECIMAL(20,6)),0)     AS x_rate4,
          NULLIF(CAST(NULLIF(TRIM(b.bet27),'') AS DECIMAL(20,6)),0)     AS x_rate5,
          (CASE WHEN NULLIF(CAST(NULLIF(TRIM(b.bet22),'') AS BIGINT),0) IS NOT NULL THEN 5
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet21),'') AS BIGINT),0) IS NOT NULL THEN 4
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet20),'') AS BIGINT),0) IS NOT NULL THEN 3
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet19),'') AS BIGINT),0) IS NOT NULL THEN 2
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet18),'') AS BIGINT),0) IS NOT NULL THEN 1
                ELSE 0 END)                                             AS x_chain_depth,
           CASE WHEN COALESCE(t1.agent_id,t2.agent_id,t3.agent_id,
                              t4.agent_id,t5.agent_id) IS NOT NULL
                THEN 1 ELSE 0 END                                        AS f_testline
    FROM x_ranked b
    LEFT JOIN x_testagent t1 ON t1.agent_id = b.bet18
    LEFT JOIN x_testagent t2 ON t2.agent_id = b.bet19
    LEFT JOIN x_testagent t3 ON t3.agent_id = b.bet20
    LEFT JOIN x_testagent t4 ON t4.agent_id = b.bet21
    LEFT JOIN x_testagent t5 ON t5.agent_id = b.bet22
    WHERE b.x_rn = 1
      AND b.category='1' AND UPPER(TRIM(b.bet38))='N'
      AND CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8)) > 0
  ),
  x_mk AS (
    SELECT s.*,
           CASE WHEN s.f_testline = 0 THEN 1 ELSE 0 END                 AS is_clean
    FROM x_bs0 s
  ),
  x_agg AS (
    SELECT s.x_member                                                        AS x_key,
           COUNT(*) AS n_bets, COUNT(DISTINCT s.x_round) AS n_rounds,
           COUNT(DISTINCT s.x_date) AS active_days, COUNT(DISTINCT s.x_tblshoe) AS active_shoes,
           COUNT(DISTINCT CONCAT_WS('|', s.x_date, s.x_table)) AS active_sessions,
           COUNT(DISTINCT s.x_table) AS n_tables, COUNT(DISTINCT s.x_dealer) AS n_dealers,
           COUNT(DISTINCT s.x_ip) AS n_ips, COUNT(DISTINCT s.x_product) AS n_products,
           MIN(s.x_date) AS first_seen_d, MAX(s.x_date) AS last_seen_d,
           SUM(s.x_stake) AS stake, SUM(s.x_valid) AS valid, SUM(s.x_rebate) AS rebate,
           SUM(s.x_net) AS net, SUM(-s.x_net *(100.0-s.x_agpct)/100.0) AS agent_cost,
           AVG(100.0-s.x_agpct)                   AS agent_pct,
           AVG(s.x_agpct)                         AS company_retain_pct,
           SUM(-s.x_net *s.x_agpct/100.0)         AS agent_cost_a_legacy,
           SUM(s.x_valid*s.x_agpct/100.0)         AS agent_cost_valid_base_legacy,
          AVG(COALESCE(s.x_rate1,100)) AS retain_pct_lv1, AVG(COALESCE(s.x_rate2,100)) AS retain_pct_lv2,
          AVG(COALESCE(s.x_rate3,100)) AS retain_pct_lv3, AVG(COALESCE(s.x_rate4,100)) AS retain_pct_lv4,
          AVG(COALESCE(s.x_rate5,100)) AS retain_pct_lv5, AVG(s.x_chain_depth) AS chain_depth_avg,
          AVG(COALESCE(100.0-s.x_rate1,0)) AS agent_pct_lv1, AVG(COALESCE(100.0-s.x_rate2,0)) AS agent_pct_lv2,
          AVG(COALESCE(100.0-s.x_rate3,0)) AS agent_pct_lv3, AVG(COALESCE(100.0-s.x_rate4,0)) AS agent_pct_lv4,
          AVG(COALESCE(100.0-s.x_rate5,0)) AS agent_pct_lv5,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate1,0)/100.0)                        AS agent_cost_lv1,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate2,0)/100.0)                        AS agent_cost_lv2,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate3,0)/100.0)                        AS agent_cost_lv3,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate4,0)/100.0)                        AS agent_cost_lv4,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate5,0)/100.0)                        AS agent_cost_lv5,
          SUM(-s.x_net*(COALESCE(100.0-s.x_rate1,0)+COALESCE(100.0-s.x_rate2,0)
                       +COALESCE(100.0-s.x_rate3,0)+COALESCE(100.0-s.x_rate4,0)
                       +COALESCE(100.0-s.x_rate5,0))/100.0)                   AS agent_cost_chain_additive,
          SUM(-s.x_net*(1.0 - CAST(COALESCE(s.x_rate1,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate2,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate3,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate4,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate5,100) AS DOUBLE)/100.0))
                                                                       AS agent_cost_chain_nested,
           AVG(s.x_rbpct) AS rbpct, AVG(s.x_freecomm*1.0) AS freecomm_rate,
           PERCENTILE_APPROX(s.x_stake,0.25) AS p25, PERCENTILE_APPROX(s.x_stake,0.50) AS p50,
           PERCENTILE_APPROX(s.x_stake,0.75) AS p75, PERCENTILE_APPROX(s.x_stake,0.90) AS p90,
           PERCENTILE_APPROX(s.x_stake,0.95) AS p95, PERCENTILE_APPROX(s.x_stake,0.99) AS p99,
           PERCENTILE_APPROX(s.x_valid,0.50) AS p50_valid,
           PERCENTILE_APPROX(s.x_net,0.50)   AS p50_profit,
           SUM(CASE WHEN s.x_rec = 1 THEN s.x_stake ELSE 0 END) AS st_in,
           SUM(CASE WHEN s.x_rec = 1 THEN 1 ELSE 0 END)         AS nb_in,
           SUM(CASE WHEN s.x_rec = 1 THEN s.x_net ELSE 0 END)   AS net_in,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN s.x_stake ELSE 0 END) AS st_out,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN 1 ELSE 0 END)         AS nb_out,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN s.x_net ELSE 0 END)   AS net_out,
           SUM(CASE WHEN s.x_rec=1 THEN s.x_stake ELSE 0 END) AS st_rec,
           SUM(CASE WHEN s.x_rec=1 THEN 1 ELSE 0 END)         AS nb_rec
    FROM x_mk s
    WHERE s.is_clean = 1
      AND s.x_member IS NOT NULL AND TRIM(CAST(s.x_member AS STRING)) <> ''
    GROUP BY s.x_member
  ),
  x_win AS (
    SELECT            COUNT(*) AS n_bets, COUNT(DISTINCT s.x_round) AS n_rounds,
           COUNT(DISTINCT s.x_date) AS active_days, COUNT(DISTINCT s.x_tblshoe) AS active_shoes,
           COUNT(DISTINCT CONCAT_WS('|', s.x_date, s.x_table)) AS active_sessions,
           COUNT(DISTINCT s.x_table) AS n_tables, COUNT(DISTINCT s.x_dealer) AS n_dealers,
           COUNT(DISTINCT s.x_ip) AS n_ips, COUNT(DISTINCT s.x_product) AS n_products,
           MIN(s.x_date) AS first_seen_d, MAX(s.x_date) AS last_seen_d,
           SUM(s.x_stake) AS stake, SUM(s.x_valid) AS valid, SUM(s.x_rebate) AS rebate,
           SUM(s.x_net) AS net, SUM(-s.x_net *(100.0-s.x_agpct)/100.0) AS agent_cost,
           AVG(100.0-s.x_agpct)                   AS agent_pct,
           AVG(s.x_agpct)                         AS company_retain_pct,
           SUM(-s.x_net *s.x_agpct/100.0)         AS agent_cost_a_legacy,
           SUM(s.x_valid*s.x_agpct/100.0)         AS agent_cost_valid_base_legacy,
          AVG(COALESCE(s.x_rate1,100)) AS retain_pct_lv1, AVG(COALESCE(s.x_rate2,100)) AS retain_pct_lv2,
          AVG(COALESCE(s.x_rate3,100)) AS retain_pct_lv3, AVG(COALESCE(s.x_rate4,100)) AS retain_pct_lv4,
          AVG(COALESCE(s.x_rate5,100)) AS retain_pct_lv5, AVG(s.x_chain_depth) AS chain_depth_avg,
          AVG(COALESCE(100.0-s.x_rate1,0)) AS agent_pct_lv1, AVG(COALESCE(100.0-s.x_rate2,0)) AS agent_pct_lv2,
          AVG(COALESCE(100.0-s.x_rate3,0)) AS agent_pct_lv3, AVG(COALESCE(100.0-s.x_rate4,0)) AS agent_pct_lv4,
          AVG(COALESCE(100.0-s.x_rate5,0)) AS agent_pct_lv5,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate1,0)/100.0)                        AS agent_cost_lv1,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate2,0)/100.0)                        AS agent_cost_lv2,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate3,0)/100.0)                        AS agent_cost_lv3,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate4,0)/100.0)                        AS agent_cost_lv4,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate5,0)/100.0)                        AS agent_cost_lv5,
          SUM(-s.x_net*(COALESCE(100.0-s.x_rate1,0)+COALESCE(100.0-s.x_rate2,0)
                       +COALESCE(100.0-s.x_rate3,0)+COALESCE(100.0-s.x_rate4,0)
                       +COALESCE(100.0-s.x_rate5,0))/100.0)                   AS agent_cost_chain_additive,
          SUM(-s.x_net*(1.0 - CAST(COALESCE(s.x_rate1,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate2,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate3,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate4,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate5,100) AS DOUBLE)/100.0))
                                                                       AS agent_cost_chain_nested,
           AVG(s.x_rbpct) AS rbpct, AVG(s.x_freecomm*1.0) AS freecomm_rate,
           PERCENTILE_APPROX(s.x_stake,0.25) AS p25, PERCENTILE_APPROX(s.x_stake,0.50) AS p50,
           PERCENTILE_APPROX(s.x_stake,0.75) AS p75, PERCENTILE_APPROX(s.x_stake,0.90) AS p90,
           PERCENTILE_APPROX(s.x_stake,0.95) AS p95, PERCENTILE_APPROX(s.x_stake,0.99) AS p99,
           PERCENTILE_APPROX(s.x_valid,0.50) AS p50_valid,
           PERCENTILE_APPROX(s.x_net,0.50)   AS p50_profit,
           SUM(CASE WHEN s.x_rec = 1 THEN s.x_stake ELSE 0 END) AS st_in,
           SUM(CASE WHEN s.x_rec = 1 THEN 1 ELSE 0 END)         AS nb_in,
           SUM(CASE WHEN s.x_rec = 1 THEN s.x_net ELSE 0 END)   AS net_in,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN s.x_stake ELSE 0 END) AS st_out,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN 1 ELSE 0 END)         AS nb_out,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN s.x_net ELSE 0 END)   AS net_out,
           SUM(CASE WHEN s.x_rec=1 THEN s.x_stake ELSE 0 END) AS st_rec,
           SUM(CASE WHEN s.x_rec=1 THEN 1 ELSE 0 END)         AS nb_rec
    FROM x_mk s
    WHERE s.is_clean = 1
      AND s.x_member IS NOT NULL AND TRIM(CAST(s.x_member AS STRING)) <> ''
  ),
      q AS (
        SELECT  TABLE_NAME, ORDINAL_POSITION, COLUMN_NAME, DATA_TYPE, COLUMN_COMMENT
        FROM    information_schema.columns
        WHERE   TABLE_SCHEMA = 'ods_mariadb_2b'
          AND   TABLE_NAME IN ('ods_a168_log_mem_change',
                               'ods_a168_change_log',
                               'ods_a168_log_age_cash_change')
      )
    SELECT q.*,
           -- 一·经济层
           ROUND(e.stake,4) AS stake, ROUND(e.valid,4) AS valid_bet,
           ROUND(-e.net,4) AS profit, e.n_bets, e.n_rounds,
           ROUND(e.net/NULLIF(e.stake,0),8) AS roi,
           ROUND(e.net_in/NULLIF(e.st_in,0),8) AS roi_recent,
           ROUND(e.net_out/NULLIF(e.st_out,0),8) AS roi_non_recent,
           ROUND((e.net-e.rebate)/NULLIF(e.stake,0),8) AS roi_ex_rebate,
           ROUND(e.net,4) AS roi_numerator, ROUND(e.stake,4) AS roi_denominator,
           CASE WHEN e.stake IS NULL THEN 'NULL_DENOM' WHEN e.stake<=0 THEN 'ZERO_DENOM'
                WHEN e.n_bets<30 THEN 'THIN_EXPOSURE' ELSE 'OK' END AS roi_denominator_status,
           ROUND(e.rebate,4) AS rebate_cost, ROUND(e.agent_cost,4)                           AS cost_complement_b,
       ROUND(e.agent_pct,4)                            AS pct_complement,
       ROUND(e.company_retain_pct,4)                   AS pct_top_bet23,
       'AG03-UNRESOLVED'                                     AS agent_formula_version,
      'ALL5_LEVELS_bet23_to_bet27'                    AS agent_level_scope,
      ROUND(e.agent_cost_lv1,4) AS agent_cost_lv1, ROUND(e.agent_cost_lv2,4) AS agent_cost_lv2,
      ROUND(e.agent_cost_lv3,4) AS agent_cost_lv3, ROUND(e.agent_cost_lv4,4) AS agent_cost_lv4,
      ROUND(e.agent_cost_lv5,4) AS agent_cost_lv5,
      ROUND(e.agent_pct_lv1,6) AS agent_pct_lv1, ROUND(e.agent_pct_lv2,6) AS agent_pct_lv2,
      ROUND(e.agent_pct_lv3,6) AS agent_pct_lv3, ROUND(e.agent_pct_lv4,6) AS agent_pct_lv4,
      ROUND(e.agent_pct_lv5,6) AS agent_pct_lv5,
      ROUND(e.retain_pct_lv1,6) AS retain_pct_lv1, ROUND(e.retain_pct_lv2,6) AS retain_pct_lv2,
      ROUND(e.retain_pct_lv3,6) AS retain_pct_lv3, ROUND(e.retain_pct_lv4,6) AS retain_pct_lv4,
      ROUND(e.retain_pct_lv5,6) AS retain_pct_lv5, ROUND(e.chain_depth_avg,4) AS chain_depth_avg,
      ROUND(e.agent_cost_chain_additive,4)            AS agent_cost_chain_additive,
      ROUND(e.agent_cost_chain_nested,4)              AS agent_cost_chain_nested,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_additive,4) AS residual_chain_additive,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_nested,4)   AS residual_chain_nested,
      'PENDING_AG03'                                  AS decision_status,
      'FALSE'                                         AS admit_to_risk_decision,
      'NOT_FOR_ENFORCEMENT'                           AS deliverable_class,
       ROUND(e.agent_cost_a_legacy,4)                  AS agent_cost_a_legacy,
       ROUND(e.agent_cost_valid_base_legacy,4)         AS agent_cost_valid_base_legacy,
           ROUND(-e.net-e.rebate,4)                        AS ngr,
       ROUND(-e.net-e.rebate-e.agent_cost,4)           AS residual_b,
       ROUND(-e.net-e.rebate-e.agent_cost_a_legacy,4)  AS residual_a,
           ROUND((-e.net-e.rebate)/NULLIF(e.stake,0),8)    AS ngr_rate,
       ROUND((-e.net-e.rebate-e.agent_cost)/NULLIF(e.stake,0),8)   AS residual_b_rate,
      -- 【HF9c · canonical accounting contract】
      --   以下 canonical 字段只增加明确 scope；不删除、不覆盖既有字段。
      --   formal_bet23_* 保持 HF9b 当前生产公式及其 NULL/0 语义；
      --   lv1~lv5 / additive / nested 则分别采用各自原始 e.* 成本字段，
      --   rate 一律从未舍入的 e.* 分子 / e.stake 计算，禁止由展示值反算。
      ROUND(e.agent_cost,4) AS agent_cost_bet23_formal_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost,4) AS net_margin_bet23_formal_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost)/NULLIF(e.stake,0),8) AS net_margin_bet23_formal_rate_canonical,
      ROUND(e.agent_cost_lv1,4) AS agent_cost_lv1_bet23_canonical,
      ROUND(e.agent_cost_lv2,4) AS agent_cost_lv2_bet24_canonical,
      ROUND(e.agent_cost_lv3,4) AS agent_cost_lv3_bet25_canonical,
      ROUND(e.agent_cost_lv4,4) AS agent_cost_lv4_bet26_canonical,
      ROUND(e.agent_cost_lv5,4) AS agent_cost_lv5_bet27_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_lv1,4) AS net_margin_lv1_bet23_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_lv1)/NULLIF(e.stake,0),8) AS net_margin_lv1_bet23_rate_canonical,
      ROUND(e.agent_cost_chain_additive,4) AS agent_cost_chain_additive_canonical,
      ROUND(e.agent_cost_chain_nested,4) AS agent_cost_chain_nested_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_additive,4) AS net_margin_chain_additive_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_nested,4) AS net_margin_chain_nested_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_chain_additive)/NULLIF(e.stake,0),8) AS net_margin_chain_additive_rate_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_chain_nested)/NULLIF(e.stake,0),8) AS net_margin_chain_nested_rate_canonical,
       ROUND((-e.net-e.rebate-e.agent_cost_a_legacy)/NULLIF(e.stake,0),8) AS residual_a_rate,
           -- 二·分布层
           ROUND(e.stake/NULLIF(e.n_bets,0),4) AS avg_stake_per_bet,
           ROUND(e.valid/NULLIF(e.n_rounds,0),4) AS avg_valid_bet_per_round,
           ROUND(-e.net/NULLIF(e.n_rounds,0),4) AS avg_profit_per_round,
           ROUND(-e.net/NULLIF(e.active_days,0),4) AS avg_profit_per_day,
           ROUND(-e.net/NULLIF(e.active_shoes,0),4) AS avg_profit_per_shoe,
           ROUND(e.stake/NULLIF(e.active_days,0),4) AS avg_stake_per_active_day,
           ROUND(e.n_rounds*1.0/NULLIF(e.active_days,0),4) AS avg_rounds_per_active_day,
           ROUND(e.st_in/NULLIF(e.nb_in,0),4) AS avg_stake_recent,
           ROUND(e.st_out/NULLIF(e.nb_out,0),4) AS avg_stake_non_recent,
           ROUND(e.p25,4) AS p25_stake, ROUND(e.p50,4) AS p50_stake, ROUND(e.p75,4) AS p75_stake,
           ROUND(e.p90,4) AS p90_stake, ROUND(e.p95,4) AS p95_stake, ROUND(e.p99,4) AS p99_stake,
           ROUND(e.p50_valid,4) AS p50_valid_bet, ROUND(e.p50_profit,4) AS p50_profit,
           ROUND(e.p95/NULLIF(e.p50,0),6) AS p95_over_p50,
           ROUND(e.p99/NULLIF(e.p50,0),6) AS p99_over_p50,
           ROUND((e.stake/NULLIF(e.n_bets,0))/NULLIF(e.p50,0),6) AS avg_over_p50,
           -- 三·关系层
           e.n_tables AS common_table_count, e.n_dealers AS common_dealer_count,
           e.n_ips AS common_ip_count, e.n_products AS common_product_count,
           ROUND(e.st_in/NULLIF(e.stake,0),8) AS share_recent,
           -- 四·rate 层
           ROUND(-e.net/NULLIF(e.stake,0),8) AS hold_rate,
           ROUND(-e.net_in/NULLIF(e.st_in,0),8) AS hold_rate_recent,
           ROUND(e.rebate/NULLIF(e.valid,0),8) AS rebate_rate_actual,
           ROUND(e.rbpct,6) AS rebate_pct_config,
           ROUND(e.valid/NULLIF(e.stake,0),6) AS turnover_multiple,
           ROUND(e.freecomm_rate,6) AS free_comm_rate,
           ROUND(e.net_in/NULLIF(e.st_in,0)-e.net_out/NULLIF(e.st_out,0),8) AS roi_delta_recent,
           -- 五·动态层
           e.first_seen_d AS first_seen, e.last_seen_d AS last_seen,
           e.active_days, e.active_shoes, e.active_sessions,
           DATEDIFF(e.last_seen_d, e.first_seen_d)+1 AS span_days,
           ROUND(e.active_days*1.0/NULLIF(DATEDIFF(e.last_seen_d,e.first_seen_d)+1,0),6) AS persistence,
           ROUND((e.st_in/NULLIF(e.nb_in,0))/NULLIF(e.st_out/NULLIF(e.nb_out,0),0),6) AS ramp_recent_vs_prior,
           ROUND((e.st_rec/NULLIF(e.nb_rec,0))/NULLIF(e.stake/NULLIF(e.n_bets,0),0),6) AS ramp_recent_vs_all,
           ROUND((e.st_rec/NULLIF(e.stake,0))/0.30,6) AS stake_ramp,
           -- 六·决策层（HF9g-P5 · D-14 斧正 —— 本件属【全窗基线族】，相对刻度与决策标签一律 NULL）
           --   病灶：x_win 系全窗单行聚合（无 GROUP BY，恒 1 行，此为设计使然，非缺陷），
           --         经 CROSS JOIN 接入后 e.* 全行同值；六层之 NTILE / PERCENT_RANK 施于常数即退化，
           --         PERCENT_RANK 恒 0 ⇒ action_priority 恒判 A，全件 100% 误标。
           --   ★ 斧正原则：不给 x_win 补 GROUP BY —— 那会改变其「全窗基线」语义，属退化。
           --     正解与 #018 之 G-05／G-06 同治：范围外之行不得接受任何下游评分与决策标签。
           --   ★ 本件之 e.* 仍照常供其它列作全窗基线使用，仅六层相对刻度与决策标签置 NULL。
           CAST(NULL AS INT)                                              AS vip_tier,                        -- 空值取值：全窗基线族无实体可分档，置 NULL（NULL＝不适用，非 0）
           CAST(NULL AS DOUBLE)                                           AS economic_value,                  -- 空值取值：同上，禁以常数百分位冒充经济价值
           CAST(NULL AS DOUBLE)                                           AS roi_pr_global,                   -- 空值取值：同上
           CAST(NULL AS DOUBLE)                                           AS risk_value,                      -- 空值取值：兼容列，同上
           CAST(NULL AS DOUBLE)                                           AS pr_stake,                        -- 空值取值：兼容列，同上
           CAST(NULL AS DOUBLE)                                           AS pr_global,                       -- 空值取值：同上
           CAST(NULL AS DOUBLE)                                           AS pr_qualified,                    -- 空值取值：同上
           'GLOBAL_BASELINE_NO_ENTITY_RANKING'                            AS pr_qualified_population,         -- 字面取值：血统 —— 明示本件为全窗基线族，无实体排序总体
           CAST(NULL AS BIGINT)                                           AS pr_global_population_n,          -- 空值取值：血统 —— 不适用
           CAST(NULL AS BIGINT)                                           AS pr_qualified_population_n,       -- 空值取值：血统 —— 不适用
           'NOT_APPLICABLE_GLOBAL_BASELINE'                               AS pr_calculation_method,           -- 字面取值：血统 —— 算法不适用
           'HF9g-P5'                                                      AS pr_calculation_version,          -- 字面取值：血统 —— 算法版本
           CAST(NULL AS STRING)                                           AS evidence_flag,                   -- 空值取值：证据旗标不适用于全窗基线
           CAST(NULL AS STRING)                                           AS evidence_rate,                   -- 空值取值：同上
           CAST(NULL AS DOUBLE)                                           AS hold_ci_halfwidth_approx,        -- 空值取值：同上
           'X 全窗基线 · 不参与实体赏罚'                                    AS action_priority                  -- 字面取值：★ D-14 斧正 —— 本族恒不入赏罚，取代原 100% 误标之「A」
    FROM q
    CROSS JOIN x_win e
  ) y
) z
-- ── 逐批 WHERE 阶梯（★ 口诀：上界 ＝ 下界 ＋ 100000，两数同进）──
--    本件 T_true 未测，无需先跑 T_true；以 0 / 100000 控制本批返回区间，末批由实际行数 < 100000 判定
--    WHERE z.audit_rn >        0 AND z.audit_rn <=   100000   -- 第 1 批
--    WHERE z.audit_rn >   100000 AND z.audit_rn <=   200000   -- 第 2 批
--    WHERE z.audit_rn >   200000 AND z.audit_rn <=   300000   -- 第 3 批
--    WHERE z.audit_rn >   300000 AND z.audit_rn <=   400000   -- 第 4 批
--    WHERE z.audit_rn >   400000 AND z.audit_rn <=   500000   -- 第 5 批
--    WHERE z.audit_rn >   500000 AND z.audit_rn <=   600000   -- 第 6 批
--    WHERE z.audit_rn >   600000 AND z.audit_rn <=   700000   -- 第 7 批
--    …余批类推。第 k 批：WHERE z.audit_rn > (k-1)*100000 AND z.audit_rn <= k*100000
--    某批返回 < 100000 行即为末批，其后不再取。
--
--    ⚠ 常见误写（务必避开）：只推下界而上界不动 ——
--        WHERE z.audit_rn > 100000 AND z.audit_rn <= 100000   ← 自相矛盾，恒为假，返回空集
--        WHERE z.audit_rn > 200000 AND z.audit_rn <= 100000   ← 同上，空集
--      两个数必须**同时**前进，且始终相差 100000。
--      下界 ＝ 上一批之上界；上界 ＝ 本批之上界。
WHERE z.audit_rn > 0 AND z.audit_rn <= 100000 -- ★ HF9c 本批区间
ORDER BY z.audit_rn;


-- ══════════════════════════════════════════════════════════════════════════════════════════════
--  90. TL06_log_mem_change.csv   [总包行 8473~8479 · 原 2 列 ＋六层约 60 列]
--     典型学：Z00 基建/元数据　派生旗标：recent（s.x_rec = 1 · 仅供 CASE 条件聚合，全包无任何 WHERE/AND/HAVING 以此过滤）　连接：q.`dt`
-- ══════════════════════════════════════════════════════════════════════════════════════════════
-- ── ① 先跑 T_true 留档（不足 100000 者一次导全，不必分批）──
-- ── ① T_true：HF9c 不再强制预跑完整 COUNT。
--    本批实际返回行数 < 100000 即判定为末批；全批完成后以各批 n_rows / audit_rn 范围核对总量。

-- ── ② 分批取数：第 1 批。第 k 批只改末行两数为 (k-1)*100000 与 k*100000 ──
--    审计字段二（REDTEAM 2026-08-24 裁定 · 四锁）：
--      audit_rn  全局观测坐标 —— 由**与原版审计版逐字同一**之排序键所生，两版可逐行对账
--      batch_id  物理分批信息 —— 该行所属批次，由 audit_rn 算得，非引擎所赋
--    ★ 锁三：二者皆为审计字段，**不得进入任何业务指标计算**。
--    ★ 锁四：两版经 audit_rn 逐行字段核验后，方可宣布输出完全一致。

-- ── ③ 每批取回后自证四数（任一不符即停手回报，禁止放行）──
--    n_rows        = COUNT(*)      须等于 COUNT(DISTINCT audit_rn)   （批内无重复）
--    audit_rn_min  = MIN(audit_rn) 须等于 (k-1)*100000 + 1           （与上批严丝合缝）
--    audit_rn_max  = MAX(audit_rn) 须等于 min + n_rows - 1           （批内无缺口）
--    全批取毕再验：各批 audit_rn 之并集 = 1 .. T_true，无缺号、无重号。
--     ★ 首行＝平台真净亏最多者（已扣退水与代理占成）。
--
SELECT z.*,
       CAST(FLOOR((z.audit_rn - 1) / 100000) + 1 AS INT)          AS batch_id,
       'A168_HF9F_20260827_0900' AS run_id,
       '2026-08-27 09:00:00' AS snapshot_sync_time
FROM (
  SELECT y.*,
         ROW_NUMBER() OVER (ORDER BY y.`residual_b` ASC, y.`roi` DESC, y.`dt`, y.`行数`) AS audit_rn
  FROM (
    WITH
      x_ranked AS (
    SELECT b.bet01, b.bet03, b.bet04, b.bet05, b.bet09, b.bet11, b.bet13,
           b.bet15, b.bet16, b.bet17, b.bet18, b.bet19, b.bet20, b.bet21,
           b.bet22, b.bet23, b.bet24, b.bet25, b.bet26, b.bet27, b.bet38, b.bet39, b.category, b.commission,
           b.dt, b.eid, b.ip, b.validbet, b.updatetime, b.sync_time,
           ROW_NUMBER() OVER (
             PARTITION BY b.bet01
             ORDER BY b.updatetime DESC, b.sync_time DESC, b.dt DESC)      AS x_rn
    FROM ods_mariadb_2b.ods_a168_bet02 b
    WHERE b.dt >= '2026-03-21' AND b.dt < '2026-08-07'
      AND b.bet02 = '101'
      AND b.sync_time <= '2026-08-27 09:00:00'
  ),
    x_testagent AS (
    SELECT age001 AS agent_id FROM ods_mariadb_2b.ods_a168_agent WHERE age022 = '1'
  ),
    x_bs0 AS (
    SELECT b.bet05 AS x_member, b.eid AS x_dealer, b.bet39 AS x_table,
           b.bet03 AS x_shoe, b.ip AS x_ip, b.bet09 AS x_product, b.dt AS x_date,
           CONCAT_WS('|', b.bet03, b.bet04, b.bet39)                      AS x_round,
           CONCAT_WS('|', b.bet39, b.bet03)                               AS x_tblshoe,
           CAST(NULLIF(TRIM(b.bet04),'') AS INT)                          AS x_rno,
           CASE WHEN b.dt >= '2026-07-08' THEN 1 ELSE 0 END               AS x_rec,
           CASE WHEN TRIM(b.commission)='1' THEN 1 ELSE 0 END             AS x_freecomm,
           CAST(NULLIF(TRIM(b.bet13),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_stake,
           CAST(NULLIF(TRIM(b.validbet),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_valid,
           CAST(NULLIF(TRIM(b.bet16),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_rebate,
           CAST(NULLIF(TRIM(b.bet17),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_net,
           CAST(NULLIF(TRIM(b.bet15),'') AS DECIMAL(20,6))                AS x_rbpct,
           COALESCE(CAST(NULLIF(TRIM(b.bet23),'') AS DECIMAL(20,6)),0)   AS x_agpct,
          NULLIF(CAST(NULLIF(TRIM(b.bet23),'') AS DECIMAL(20,6)),0)     AS x_rate1,
          NULLIF(CAST(NULLIF(TRIM(b.bet24),'') AS DECIMAL(20,6)),0)     AS x_rate2,
          NULLIF(CAST(NULLIF(TRIM(b.bet25),'') AS DECIMAL(20,6)),0)     AS x_rate3,
          NULLIF(CAST(NULLIF(TRIM(b.bet26),'') AS DECIMAL(20,6)),0)     AS x_rate4,
          NULLIF(CAST(NULLIF(TRIM(b.bet27),'') AS DECIMAL(20,6)),0)     AS x_rate5,
          (CASE WHEN NULLIF(CAST(NULLIF(TRIM(b.bet22),'') AS BIGINT),0) IS NOT NULL THEN 5
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet21),'') AS BIGINT),0) IS NOT NULL THEN 4
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet20),'') AS BIGINT),0) IS NOT NULL THEN 3
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet19),'') AS BIGINT),0) IS NOT NULL THEN 2
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet18),'') AS BIGINT),0) IS NOT NULL THEN 1
                ELSE 0 END)                                             AS x_chain_depth,
           CASE WHEN COALESCE(t1.agent_id,t2.agent_id,t3.agent_id,
                              t4.agent_id,t5.agent_id) IS NOT NULL
                THEN 1 ELSE 0 END                                        AS f_testline
    FROM x_ranked b
    LEFT JOIN x_testagent t1 ON t1.agent_id = b.bet18
    LEFT JOIN x_testagent t2 ON t2.agent_id = b.bet19
    LEFT JOIN x_testagent t3 ON t3.agent_id = b.bet20
    LEFT JOIN x_testagent t4 ON t4.agent_id = b.bet21
    LEFT JOIN x_testagent t5 ON t5.agent_id = b.bet22
    WHERE b.x_rn = 1
      AND b.category='1' AND UPPER(TRIM(b.bet38))='N'
      AND CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8)) > 0
  ),
  x_mk AS (
    SELECT s.*,
           CASE WHEN s.f_testline = 0 THEN 1 ELSE 0 END                 AS is_clean
    FROM x_bs0 s
  ),
  x_agg AS (
    SELECT s.x_date                                                        AS x_key,
           COUNT(*) AS n_bets, COUNT(DISTINCT s.x_round) AS n_rounds,
           COUNT(DISTINCT s.x_date) AS active_days, COUNT(DISTINCT s.x_tblshoe) AS active_shoes,
           COUNT(DISTINCT CONCAT_WS('|', s.x_date, s.x_table)) AS active_sessions,
           COUNT(DISTINCT s.x_table) AS n_tables, COUNT(DISTINCT s.x_dealer) AS n_dealers,
           COUNT(DISTINCT s.x_ip) AS n_ips, COUNT(DISTINCT s.x_product) AS n_products,
           MIN(s.x_date) AS first_seen_d, MAX(s.x_date) AS last_seen_d,
           SUM(s.x_stake) AS stake, SUM(s.x_valid) AS valid, SUM(s.x_rebate) AS rebate,
           SUM(s.x_net) AS net, SUM(-s.x_net *(100.0-s.x_agpct)/100.0) AS agent_cost,
           AVG(100.0-s.x_agpct)                   AS agent_pct,
           AVG(s.x_agpct)                         AS company_retain_pct,
           SUM(-s.x_net *s.x_agpct/100.0)         AS agent_cost_a_legacy,
           SUM(s.x_valid*s.x_agpct/100.0)         AS agent_cost_valid_base_legacy,
          AVG(COALESCE(s.x_rate1,100)) AS retain_pct_lv1, AVG(COALESCE(s.x_rate2,100)) AS retain_pct_lv2,
          AVG(COALESCE(s.x_rate3,100)) AS retain_pct_lv3, AVG(COALESCE(s.x_rate4,100)) AS retain_pct_lv4,
          AVG(COALESCE(s.x_rate5,100)) AS retain_pct_lv5, AVG(s.x_chain_depth) AS chain_depth_avg,
          AVG(COALESCE(100.0-s.x_rate1,0)) AS agent_pct_lv1, AVG(COALESCE(100.0-s.x_rate2,0)) AS agent_pct_lv2,
          AVG(COALESCE(100.0-s.x_rate3,0)) AS agent_pct_lv3, AVG(COALESCE(100.0-s.x_rate4,0)) AS agent_pct_lv4,
          AVG(COALESCE(100.0-s.x_rate5,0)) AS agent_pct_lv5,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate1,0)/100.0)                        AS agent_cost_lv1,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate2,0)/100.0)                        AS agent_cost_lv2,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate3,0)/100.0)                        AS agent_cost_lv3,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate4,0)/100.0)                        AS agent_cost_lv4,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate5,0)/100.0)                        AS agent_cost_lv5,
          SUM(-s.x_net*(COALESCE(100.0-s.x_rate1,0)+COALESCE(100.0-s.x_rate2,0)
                       +COALESCE(100.0-s.x_rate3,0)+COALESCE(100.0-s.x_rate4,0)
                       +COALESCE(100.0-s.x_rate5,0))/100.0)                   AS agent_cost_chain_additive,
          SUM(-s.x_net*(1.0 - CAST(COALESCE(s.x_rate1,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate2,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate3,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate4,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate5,100) AS DOUBLE)/100.0))
                                                                       AS agent_cost_chain_nested,
           AVG(s.x_rbpct) AS rbpct, AVG(s.x_freecomm*1.0) AS freecomm_rate,
           PERCENTILE_APPROX(s.x_stake,0.25) AS p25, PERCENTILE_APPROX(s.x_stake,0.50) AS p50,
           PERCENTILE_APPROX(s.x_stake,0.75) AS p75, PERCENTILE_APPROX(s.x_stake,0.90) AS p90,
           PERCENTILE_APPROX(s.x_stake,0.95) AS p95, PERCENTILE_APPROX(s.x_stake,0.99) AS p99,
           PERCENTILE_APPROX(s.x_valid,0.50) AS p50_valid,
           PERCENTILE_APPROX(s.x_net,0.50)   AS p50_profit,
           SUM(CASE WHEN s.x_rec = 1 THEN s.x_stake ELSE 0 END) AS st_in,
           SUM(CASE WHEN s.x_rec = 1 THEN 1 ELSE 0 END)         AS nb_in,
           SUM(CASE WHEN s.x_rec = 1 THEN s.x_net ELSE 0 END)   AS net_in,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN s.x_stake ELSE 0 END) AS st_out,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN 1 ELSE 0 END)         AS nb_out,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN s.x_net ELSE 0 END)   AS net_out,
           SUM(CASE WHEN s.x_rec=1 THEN s.x_stake ELSE 0 END) AS st_rec,
           SUM(CASE WHEN s.x_rec=1 THEN 1 ELSE 0 END)         AS nb_rec
    FROM x_mk s
    WHERE s.is_clean = 1
      AND s.x_date IS NOT NULL AND TRIM(CAST(s.x_date AS STRING)) <> ''
    GROUP BY s.x_date
  ),
      q AS (
        SELECT  dt,
                COUNT(*)                                          AS 行数
        FROM    ods_mariadb_2b.ods_a168_log_mem_change
        WHERE   dt >= '2026-03-21'
          AND   dt <  '2026-08-07'
        GROUP BY dt
      )
    SELECT q.*,
           -- 一·经济层
           ROUND(e.stake,4) AS stake, ROUND(e.valid,4) AS valid_bet,
           ROUND(-e.net,4) AS profit, e.n_bets, e.n_rounds,
           ROUND(e.net/NULLIF(e.stake,0),8) AS roi,
           ROUND(e.net_in/NULLIF(e.st_in,0),8) AS roi_recent,
           ROUND(e.net_out/NULLIF(e.st_out,0),8) AS roi_non_recent,
           ROUND((e.net-e.rebate)/NULLIF(e.stake,0),8) AS roi_ex_rebate,
           ROUND(e.net,4) AS roi_numerator, ROUND(e.stake,4) AS roi_denominator,
           CASE WHEN e.stake IS NULL THEN 'NULL_DENOM' WHEN e.stake<=0 THEN 'ZERO_DENOM'
                WHEN e.n_bets<30 THEN 'THIN_EXPOSURE' ELSE 'OK' END AS roi_denominator_status,
           ROUND(e.rebate,4) AS rebate_cost, ROUND(e.agent_cost,4)                           AS cost_complement_b,
       ROUND(e.agent_pct,4)                            AS pct_complement,
       ROUND(e.company_retain_pct,4)                   AS pct_top_bet23,
       'AG03-UNRESOLVED'                                     AS agent_formula_version,
      'ALL5_LEVELS_bet23_to_bet27'                    AS agent_level_scope,
      ROUND(e.agent_cost_lv1,4) AS agent_cost_lv1, ROUND(e.agent_cost_lv2,4) AS agent_cost_lv2,
      ROUND(e.agent_cost_lv3,4) AS agent_cost_lv3, ROUND(e.agent_cost_lv4,4) AS agent_cost_lv4,
      ROUND(e.agent_cost_lv5,4) AS agent_cost_lv5,
      ROUND(e.agent_pct_lv1,6) AS agent_pct_lv1, ROUND(e.agent_pct_lv2,6) AS agent_pct_lv2,
      ROUND(e.agent_pct_lv3,6) AS agent_pct_lv3, ROUND(e.agent_pct_lv4,6) AS agent_pct_lv4,
      ROUND(e.agent_pct_lv5,6) AS agent_pct_lv5,
      ROUND(e.retain_pct_lv1,6) AS retain_pct_lv1, ROUND(e.retain_pct_lv2,6) AS retain_pct_lv2,
      ROUND(e.retain_pct_lv3,6) AS retain_pct_lv3, ROUND(e.retain_pct_lv4,6) AS retain_pct_lv4,
      ROUND(e.retain_pct_lv5,6) AS retain_pct_lv5, ROUND(e.chain_depth_avg,4) AS chain_depth_avg,
      ROUND(e.agent_cost_chain_additive,4)            AS agent_cost_chain_additive,
      ROUND(e.agent_cost_chain_nested,4)              AS agent_cost_chain_nested,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_additive,4) AS residual_chain_additive,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_nested,4)   AS residual_chain_nested,
      'PENDING_AG03'                                  AS decision_status,
      'FALSE'                                         AS admit_to_risk_decision,
      'NOT_FOR_ENFORCEMENT'                           AS deliverable_class,
       ROUND(e.agent_cost_a_legacy,4)                  AS agent_cost_a_legacy,
       ROUND(e.agent_cost_valid_base_legacy,4)         AS agent_cost_valid_base_legacy,
           ROUND(-e.net-e.rebate,4)                        AS ngr,
       ROUND(-e.net-e.rebate-e.agent_cost,4)           AS residual_b,
       ROUND(-e.net-e.rebate-e.agent_cost_a_legacy,4)  AS residual_a,
           ROUND((-e.net-e.rebate)/NULLIF(e.stake,0),8)    AS ngr_rate,
       ROUND((-e.net-e.rebate-e.agent_cost)/NULLIF(e.stake,0),8)   AS residual_b_rate,
      -- 【HF9c · canonical accounting contract】
      --   以下 canonical 字段只增加明确 scope；不删除、不覆盖既有字段。
      --   formal_bet23_* 保持 HF9b 当前生产公式及其 NULL/0 语义；
      --   lv1~lv5 / additive / nested 则分别采用各自原始 e.* 成本字段，
      --   rate 一律从未舍入的 e.* 分子 / e.stake 计算，禁止由展示值反算。
      ROUND(e.agent_cost,4) AS agent_cost_bet23_formal_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost,4) AS net_margin_bet23_formal_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost)/NULLIF(e.stake,0),8) AS net_margin_bet23_formal_rate_canonical,
      ROUND(e.agent_cost_lv1,4) AS agent_cost_lv1_bet23_canonical,
      ROUND(e.agent_cost_lv2,4) AS agent_cost_lv2_bet24_canonical,
      ROUND(e.agent_cost_lv3,4) AS agent_cost_lv3_bet25_canonical,
      ROUND(e.agent_cost_lv4,4) AS agent_cost_lv4_bet26_canonical,
      ROUND(e.agent_cost_lv5,4) AS agent_cost_lv5_bet27_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_lv1,4) AS net_margin_lv1_bet23_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_lv1)/NULLIF(e.stake,0),8) AS net_margin_lv1_bet23_rate_canonical,
      ROUND(e.agent_cost_chain_additive,4) AS agent_cost_chain_additive_canonical,
      ROUND(e.agent_cost_chain_nested,4) AS agent_cost_chain_nested_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_additive,4) AS net_margin_chain_additive_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_nested,4) AS net_margin_chain_nested_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_chain_additive)/NULLIF(e.stake,0),8) AS net_margin_chain_additive_rate_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_chain_nested)/NULLIF(e.stake,0),8) AS net_margin_chain_nested_rate_canonical,
       ROUND((-e.net-e.rebate-e.agent_cost_a_legacy)/NULLIF(e.stake,0),8) AS residual_a_rate,
           -- 二·分布层
           ROUND(e.stake/NULLIF(e.n_bets,0),4) AS avg_stake_per_bet,
           ROUND(e.valid/NULLIF(e.n_rounds,0),4) AS avg_valid_bet_per_round,
           ROUND(-e.net/NULLIF(e.n_rounds,0),4) AS avg_profit_per_round,
           ROUND(-e.net/NULLIF(e.active_days,0),4) AS avg_profit_per_day,
           ROUND(-e.net/NULLIF(e.active_shoes,0),4) AS avg_profit_per_shoe,
           ROUND(e.stake/NULLIF(e.active_days,0),4) AS avg_stake_per_active_day,
           ROUND(e.n_rounds*1.0/NULLIF(e.active_days,0),4) AS avg_rounds_per_active_day,
           ROUND(e.st_in/NULLIF(e.nb_in,0),4) AS avg_stake_recent,
           ROUND(e.st_out/NULLIF(e.nb_out,0),4) AS avg_stake_non_recent,
           ROUND(e.p25,4) AS p25_stake, ROUND(e.p50,4) AS p50_stake, ROUND(e.p75,4) AS p75_stake,
           ROUND(e.p90,4) AS p90_stake, ROUND(e.p95,4) AS p95_stake, ROUND(e.p99,4) AS p99_stake,
           ROUND(e.p50_valid,4) AS p50_valid_bet, ROUND(e.p50_profit,4) AS p50_profit,
           ROUND(e.p95/NULLIF(e.p50,0),6) AS p95_over_p50,
           ROUND(e.p99/NULLIF(e.p50,0),6) AS p99_over_p50,
           ROUND((e.stake/NULLIF(e.n_bets,0))/NULLIF(e.p50,0),6) AS avg_over_p50,
           -- 三·关系层
           e.n_tables AS common_table_count, e.n_dealers AS common_dealer_count,
           e.n_ips AS common_ip_count, e.n_products AS common_product_count,
           ROUND(e.st_in/NULLIF(e.stake,0),8) AS share_recent,
           -- 四·rate 层
           ROUND(-e.net/NULLIF(e.stake,0),8) AS hold_rate,
           ROUND(-e.net_in/NULLIF(e.st_in,0),8) AS hold_rate_recent,
           ROUND(e.rebate/NULLIF(e.valid,0),8) AS rebate_rate_actual,
           ROUND(e.rbpct,6) AS rebate_pct_config,
           ROUND(e.valid/NULLIF(e.stake,0),6) AS turnover_multiple,
           ROUND(e.freecomm_rate,6) AS free_comm_rate,
           ROUND(e.net_in/NULLIF(e.st_in,0)-e.net_out/NULLIF(e.st_out,0),8) AS roi_delta_recent,
           -- 五·动态层
           e.first_seen_d AS first_seen, e.last_seen_d AS last_seen,
           e.active_days, e.active_shoes, e.active_sessions,
           DATEDIFF(e.last_seen_d, e.first_seen_d)+1 AS span_days,
           ROUND(e.active_days*1.0/NULLIF(DATEDIFF(e.last_seen_d,e.first_seen_d)+1,0),6) AS persistence,
           ROUND((e.st_in/NULLIF(e.nb_in,0))/NULLIF(e.st_out/NULLIF(e.nb_out,0),0),6) AS ramp_recent_vs_prior,
           ROUND((e.st_rec/NULLIF(e.nb_rec,0))/NULLIF(e.stake/NULLIF(e.n_bets,0),0),6) AS ramp_recent_vs_all,
           ROUND((e.st_rec/NULLIF(e.stake,0))/0.30,6) AS stake_ramp,
           -- 六·决策层（HF9f · 详见档头【HF9f 变更说明】；本段两版逐字同一）
           NTILE(5) OVER (ORDER BY e.stake) AS vip_tier,                                                        -- 窗口取值：相对刻度 B 族，全体五等分；须连同下方血统五元组一并解读，禁作硬阈值判型
           PERCENT_RANK() OVER (ORDER BY -e.net-e.rebate-e.agent_cost)    AS economic_value,                    -- 窗口取值：HF9f·F-19 修正 —— HF9e 写作 -(-…) 双负号致方向颠倒（#075 实测 corr(economic_value, residual_b) = -1.0000）；今与 action_priority 排序键归一，值大即平台真净利高
           PERCENT_RANK() OVER (ORDER BY e.net/NULLIF(e.stake,0))         AS roi_pr_global,                     -- 窗口取值：HF9f·F-17 正名 —— 本列实为 ROI（玩家净回报率）之全体百分位，与「风险」无关；旧名 risk_value 见下一行
           PERCENT_RANK() OVER (ORDER BY e.net/NULLIF(e.stake,0))         AS risk_value,                        -- 窗口取值：兼容列，恒等于 roi_pr_global，仅为下游迁移窗保留；HF9g 起废弃，禁新引用
           PERCENT_RANK() OVER (ORDER BY e.stake)                         AS pr_stake,                          -- 窗口取值：兼容列，恒等于 pr_global，原名保留以免断链
           PERCENT_RANK() OVER (ORDER BY e.stake)                         AS pr_global,                         -- 窗口取值：HF9f·F-1 双轨之一 —— 全体口径百分位，参照总体即本件全部输出行
           CASE WHEN e.n_rounds >= 30                                                                           -- 条件分支：起始分支 —— 仅在合格子集内计算合格口径百分位
                  THEN PERCENT_RANK() OVER (PARTITION BY CASE WHEN e.n_rounds >= 30 THEN 1 ELSE 0 END ORDER BY e.stake)  -- 分支取值：以合格与否分区，故本值即 n_rounds>=30 子集内之百分位
                ELSE NULL END                                             AS pr_qualified,                      -- 条件分支：收束上方分支 —— 不合格者留 NULL（NULL＝未测，非 0），产出「pr_qualified」
           'n_rounds>=30'                                                 AS pr_qualified_population,           -- 字面取值：血统 —— 合格子集之定义
           COUNT(*) OVER ()                                               AS pr_global_population_n,            -- 窗口取值：血统 —— 全体口径之参照总体规模，渲染时现算，禁写死
           SUM(CASE WHEN e.n_rounds >= 30 THEN 1 ELSE 0 END) OVER ()      AS pr_qualified_population_n,         -- 窗口取值：血统 —— 合格子集之参照总体规模，现算，禁写死
           'PERCENT_RANK_OVER_ORDER_BY_e_stake'                           AS pr_calculation_method,             -- 字面取值：血统 —— 算法标识
           'HF9f'                                                         AS pr_calculation_version,            -- 字面取值：血统 —— 算法版本
           CASE WHEN e.n_rounds IS NULL OR e.n_rounds < 30 THEN 'THIN_ROUNDS' ELSE 'OK' END AS evidence_flag,   -- 条件分支：HF9f·F-2a 证据旗标 —— THIN_ROUNDS 者禁入执行队列，仅入观察队列
           CASE WHEN e.n_rounds IS NULL       THEN NULL                                                         -- 条件分支：起始分支 —— 未测者留 NULL（自家铁律：NULL ≠ 0）
                WHEN e.n_rounds >= 31483      THEN 'L1_POWERED'                                                 -- 分支判定：MDE 反解第一档
                WHEN e.n_rounds >= 15409      THEN 'L2_CI_1P5'                                                  -- 分支判定：MDE 反解第二档
                WHEN e.n_rounds >=  8668      THEN 'L3_CI_2P0'                                                  -- 分支判定：MDE 反解第三档
                WHEN e.n_rounds >=  3852      THEN 'L4_CI_3P0'                                                  -- 分支判定：MDE 反解第四档
                ELSE 'L5_INSUFFICIENT' END                                AS evidence_rate,                     -- 条件分支：收束上方 —— HF9f·F-3 证据分档，承 HF9e 前议之 MDE 反解五档，须于 F-4 敏感性实验后复核
           ROUND(1.96 * 0.95 / SQRT(NULLIF(CAST(e.n_rounds AS DOUBLE),0)),8) AS hold_ci_halfwidth_approx,       -- 比率表达式：HF9f·F-3 逐行现算之 95% 半宽近似；常数 0.95 为登记值，本轮 #075 实测每局 ROI 隐含 σ 于最薄层为 0.9249，二者差异待 F-4 裁定
           CASE WHEN e.stake IS NULL OR e.stake<=0 OR e.n_bets<30 OR e.n_rounds IS NULL OR e.n_rounds<30 THEN 'Z 证据不足 · 不动作'  -- 条件分支：HF9f·F-2 双条件取严 —— HF9e 仅卡 e.n_bets<30，致 n_bets>=30 而 n_rounds<30 者绕过 Z（#075 实测 18,537 名，其中 8,145 名已入 A/D 待裁）；今两条件并列取严
                WHEN PERCENT_RANK() OVER (ORDER BY -e.net-e.rebate-e.agent_cost)<=0.10                          -- 分支判定：平台真净利之最低十分位
                  THEN 'A 净亏最大十分位 · 优先复核'                                                             -- 分支取值：HF9f·F-20 正名 —— 本档 Σresidual_b 于 #075 实测 = -100,236,896，系平台净亏最大群，旧名「残值最低十分位 · 待裁」名实不符
                WHEN PERCENT_RANK() OVER (ORDER BY -e.net-e.rebate-e.agent_cost)>=0.80                          -- 分支判定：平台真净利之最高二十分位
                  THEN 'D 净利最高二十分位 · 优先留存'                                                           -- 分支取值：HF9f·F-20 正名 —— 本档 Σresidual_b 于 #075 实测 = +281,733,190，系核心利润源；与 A 档方向相反，旧版同标「待裁」属名实不符
                ELSE 'E 常规' END                                          AS action_priority                   -- 条件分支：收束上方判词，产出「action_priority」
    FROM q
    LEFT JOIN x_agg e ON CAST(e.x_key AS STRING) = CAST(q.`dt` AS STRING)
  ) y
) z
-- ── 逐批 WHERE 阶梯（★ 口诀：上界 ＝ 下界 ＋ 100000，两数同进）──
--    本件 T_true 未测，无需先跑 T_true；以 0 / 100000 控制本批返回区间，末批由实际行数 < 100000 判定
--    WHERE z.audit_rn >        0 AND z.audit_rn <=   100000   -- 第 1 批
--    WHERE z.audit_rn >   100000 AND z.audit_rn <=   200000   -- 第 2 批
--    WHERE z.audit_rn >   200000 AND z.audit_rn <=   300000   -- 第 3 批
--    WHERE z.audit_rn >   300000 AND z.audit_rn <=   400000   -- 第 4 批
--    WHERE z.audit_rn >   400000 AND z.audit_rn <=   500000   -- 第 5 批
--    WHERE z.audit_rn >   500000 AND z.audit_rn <=   600000   -- 第 6 批
--    WHERE z.audit_rn >   600000 AND z.audit_rn <=   700000   -- 第 7 批
--    …余批类推。第 k 批：WHERE z.audit_rn > (k-1)*100000 AND z.audit_rn <= k*100000
--    某批返回 < 100000 行即为末批，其后不再取。
--
--    ⚠ 常见误写（务必避开）：只推下界而上界不动 ——
--        WHERE z.audit_rn > 100000 AND z.audit_rn <= 100000   ← 自相矛盾，恒为假，返回空集
--        WHERE z.audit_rn > 200000 AND z.audit_rn <= 100000   ← 同上，空集
--      两个数必须**同时**前进，且始终相差 100000。
--      下界 ＝ 上一批之上界；上界 ＝ 本批之上界。
WHERE z.audit_rn > 0 AND z.audit_rn <= 100000 -- ★ HF9c 本批区间
ORDER BY z.audit_rn;


-- ══════════════════════════════════════════════════════════════════════════════════════════════
--  91. TL07_mem_change_shape.csv   [总包行 8519~8533 · 原 10 列 ＋六层约 60 列]
--     典型学：M09 处置限额　派生旗标：post（s.x_rec = 1 · 仅供 CASE 条件聚合，全包无任何 WHERE/AND/HAVING 以此过滤）　连接：全窗基线
-- ══════════════════════════════════════════════════════════════════════════════════════════════
-- ★ W-64 · D-14 警示（本件属 x_win 族 · 66 件之一 · 详见 §Z 段 D-14 全案）
--   本件以 `CROSS JOIN x_win e` 接入全局基线，x_win 无 GROUP BY ⇒ 恒 1 行 ⇒ e.* 全行同值。
--   故：economic_value / roi_pr_global / risk_value / pr_stake / pr_global 恒为 0；
--       action_priority 每一行皆为「A 净亏最大十分位 · 优先复核」（Z 分支永不触发）；
--       evidence_rate 恒为最高档；vip_tier 由常数键分档 ⇒ 无信息且非确定。
--   ⇒ 本件决策层三列 **NOT_FOR_DECISION**，裁定前不得用于排班、抽查或汇报。
-- ── ① 先跑 T_true 留档（不足 100000 者一次导全，不必分批）──
-- ── ① T_true：HF9c 不再强制预跑完整 COUNT。
--    本批实际返回行数 < 100000 即判定为末批；全批完成后以各批 n_rows / audit_rn 范围核对总量。

-- ── ② 分批取数：第 1 批。第 k 批只改末行两数为 (k-1)*100000 与 k*100000 ──
--    审计字段二（REDTEAM 2026-08-24 裁定 · 四锁）：
--      audit_rn  全局观测坐标 —— 由**与原版审计版逐字同一**之排序键所生，两版可逐行对账
--      batch_id  物理分批信息 —— 该行所属批次，由 audit_rn 算得，非引擎所赋
--    ★ 锁三：二者皆为审计字段，**不得进入任何业务指标计算**。
--    ★ 锁四：两版经 audit_rn 逐行字段核验后，方可宣布输出完全一致。

-- ── ③ 每批取回后自证四数（任一不符即停手回报，禁止放行）──
--    n_rows        = COUNT(*)      须等于 COUNT(DISTINCT audit_rn)   （批内无重复）
--    audit_rn_min  = MIN(audit_rn) 须等于 (k-1)*100000 + 1           （与上批严丝合缝）
--    audit_rn_max  = MAX(audit_rn) 须等于 min + n_rows - 1           （批内无缺口）
--    全批取毕再验：各批 audit_rn 之并集 = 1 .. T_true，无缺号、无重号。
--     ★ 首行＝平台真净亏最多者（已扣退水与代理占成）。
--
SELECT z.*,
       CAST(FLOOR((z.audit_rn - 1) / 100000) + 1 AS INT)          AS batch_id,
       'A168_HF9F_20260827_0900' AS run_id,
       '2026-08-27 09:00:00' AS snapshot_sync_time
FROM (
  SELECT y.*,
         ROW_NUMBER() OVER (ORDER BY y.`residual_b` ASC, y.`roi` DESC, y.`类别`, y.`条数`, y.`涉及会员数`, y.`操作者数`, y.`最早异动`, y.`最晚异动`, y.`内容平均长度`, y.`内容样例`, y.`SQL平均长度`, y.`SQL样例`) AS audit_rn
  FROM (
    WITH
      x_ranked AS (
    SELECT b.bet01, b.bet03, b.bet04, b.bet05, b.bet09, b.bet11, b.bet13,
           b.bet15, b.bet16, b.bet17, b.bet18, b.bet19, b.bet20, b.bet21,
           b.bet22, b.bet23, b.bet24, b.bet25, b.bet26, b.bet27, b.bet38, b.bet39, b.category, b.commission,
           b.dt, b.eid, b.ip, b.validbet, b.updatetime, b.sync_time,
           ROW_NUMBER() OVER (
             PARTITION BY b.bet01
             ORDER BY b.updatetime DESC, b.sync_time DESC, b.dt DESC)      AS x_rn
    FROM ods_mariadb_2b.ods_a168_bet02 b
    WHERE b.dt >= '2026-03-21' AND b.dt < '2026-08-07'
      AND b.bet02 = '101'
      AND b.sync_time <= '2026-08-27 09:00:00'
  ),
    x_testagent AS (
    SELECT age001 AS agent_id FROM ods_mariadb_2b.ods_a168_agent WHERE age022 = '1'
  ),
    x_bs0 AS (
    SELECT b.bet05 AS x_member, b.eid AS x_dealer, b.bet39 AS x_table,
           b.bet03 AS x_shoe, b.ip AS x_ip, b.bet09 AS x_product, b.dt AS x_date,
           CONCAT_WS('|', b.bet03, b.bet04, b.bet39)                      AS x_round,
           CONCAT_WS('|', b.bet39, b.bet03)                               AS x_tblshoe,
           CAST(NULLIF(TRIM(b.bet04),'') AS INT)                          AS x_rno,
           CASE WHEN b.dt >= '2026-07-08' THEN 1 ELSE 0 END               AS x_rec,
           CASE WHEN TRIM(b.commission)='1' THEN 1 ELSE 0 END             AS x_freecomm,
           CAST(NULLIF(TRIM(b.bet13),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_stake,
           CAST(NULLIF(TRIM(b.validbet),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_valid,
           CAST(NULLIF(TRIM(b.bet16),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_rebate,
           CAST(NULLIF(TRIM(b.bet17),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_net,
           CAST(NULLIF(TRIM(b.bet15),'') AS DECIMAL(20,6))                AS x_rbpct,
           COALESCE(CAST(NULLIF(TRIM(b.bet23),'') AS DECIMAL(20,6)),0)   AS x_agpct,
          NULLIF(CAST(NULLIF(TRIM(b.bet23),'') AS DECIMAL(20,6)),0)     AS x_rate1,
          NULLIF(CAST(NULLIF(TRIM(b.bet24),'') AS DECIMAL(20,6)),0)     AS x_rate2,
          NULLIF(CAST(NULLIF(TRIM(b.bet25),'') AS DECIMAL(20,6)),0)     AS x_rate3,
          NULLIF(CAST(NULLIF(TRIM(b.bet26),'') AS DECIMAL(20,6)),0)     AS x_rate4,
          NULLIF(CAST(NULLIF(TRIM(b.bet27),'') AS DECIMAL(20,6)),0)     AS x_rate5,
          (CASE WHEN NULLIF(CAST(NULLIF(TRIM(b.bet22),'') AS BIGINT),0) IS NOT NULL THEN 5
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet21),'') AS BIGINT),0) IS NOT NULL THEN 4
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet20),'') AS BIGINT),0) IS NOT NULL THEN 3
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet19),'') AS BIGINT),0) IS NOT NULL THEN 2
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet18),'') AS BIGINT),0) IS NOT NULL THEN 1
                ELSE 0 END)                                             AS x_chain_depth,
           CASE WHEN COALESCE(t1.agent_id,t2.agent_id,t3.agent_id,
                              t4.agent_id,t5.agent_id) IS NOT NULL
                THEN 1 ELSE 0 END                                        AS f_testline
    FROM x_ranked b
    LEFT JOIN x_testagent t1 ON t1.agent_id = b.bet18
    LEFT JOIN x_testagent t2 ON t2.agent_id = b.bet19
    LEFT JOIN x_testagent t3 ON t3.agent_id = b.bet20
    LEFT JOIN x_testagent t4 ON t4.agent_id = b.bet21
    LEFT JOIN x_testagent t5 ON t5.agent_id = b.bet22
    WHERE b.x_rn = 1
      AND b.category='1' AND UPPER(TRIM(b.bet38))='N'
      AND CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8)) > 0
  ),
  x_mk AS (
    SELECT s.*,
           CASE WHEN s.f_testline = 0 THEN 1 ELSE 0 END                 AS is_clean
    FROM x_bs0 s
  ),
  x_agg AS (
    SELECT s.x_member                                                        AS x_key,
           COUNT(*) AS n_bets, COUNT(DISTINCT s.x_round) AS n_rounds,
           COUNT(DISTINCT s.x_date) AS active_days, COUNT(DISTINCT s.x_tblshoe) AS active_shoes,
           COUNT(DISTINCT CONCAT_WS('|', s.x_date, s.x_table)) AS active_sessions,
           COUNT(DISTINCT s.x_table) AS n_tables, COUNT(DISTINCT s.x_dealer) AS n_dealers,
           COUNT(DISTINCT s.x_ip) AS n_ips, COUNT(DISTINCT s.x_product) AS n_products,
           MIN(s.x_date) AS first_seen_d, MAX(s.x_date) AS last_seen_d,
           SUM(s.x_stake) AS stake, SUM(s.x_valid) AS valid, SUM(s.x_rebate) AS rebate,
           SUM(s.x_net) AS net, SUM(-s.x_net *(100.0-s.x_agpct)/100.0) AS agent_cost,
           AVG(100.0-s.x_agpct)                   AS agent_pct,
           AVG(s.x_agpct)                         AS company_retain_pct,
           SUM(-s.x_net *s.x_agpct/100.0)         AS agent_cost_a_legacy,
           SUM(s.x_valid*s.x_agpct/100.0)         AS agent_cost_valid_base_legacy,
          AVG(COALESCE(s.x_rate1,100)) AS retain_pct_lv1, AVG(COALESCE(s.x_rate2,100)) AS retain_pct_lv2,
          AVG(COALESCE(s.x_rate3,100)) AS retain_pct_lv3, AVG(COALESCE(s.x_rate4,100)) AS retain_pct_lv4,
          AVG(COALESCE(s.x_rate5,100)) AS retain_pct_lv5, AVG(s.x_chain_depth) AS chain_depth_avg,
          AVG(COALESCE(100.0-s.x_rate1,0)) AS agent_pct_lv1, AVG(COALESCE(100.0-s.x_rate2,0)) AS agent_pct_lv2,
          AVG(COALESCE(100.0-s.x_rate3,0)) AS agent_pct_lv3, AVG(COALESCE(100.0-s.x_rate4,0)) AS agent_pct_lv4,
          AVG(COALESCE(100.0-s.x_rate5,0)) AS agent_pct_lv5,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate1,0)/100.0)                        AS agent_cost_lv1,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate2,0)/100.0)                        AS agent_cost_lv2,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate3,0)/100.0)                        AS agent_cost_lv3,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate4,0)/100.0)                        AS agent_cost_lv4,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate5,0)/100.0)                        AS agent_cost_lv5,
          SUM(-s.x_net*(COALESCE(100.0-s.x_rate1,0)+COALESCE(100.0-s.x_rate2,0)
                       +COALESCE(100.0-s.x_rate3,0)+COALESCE(100.0-s.x_rate4,0)
                       +COALESCE(100.0-s.x_rate5,0))/100.0)                   AS agent_cost_chain_additive,
          SUM(-s.x_net*(1.0 - CAST(COALESCE(s.x_rate1,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate2,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate3,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate4,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate5,100) AS DOUBLE)/100.0))
                                                                       AS agent_cost_chain_nested,
           AVG(s.x_rbpct) AS rbpct, AVG(s.x_freecomm*1.0) AS freecomm_rate,
           PERCENTILE_APPROX(s.x_stake,0.25) AS p25, PERCENTILE_APPROX(s.x_stake,0.50) AS p50,
           PERCENTILE_APPROX(s.x_stake,0.75) AS p75, PERCENTILE_APPROX(s.x_stake,0.90) AS p90,
           PERCENTILE_APPROX(s.x_stake,0.95) AS p95, PERCENTILE_APPROX(s.x_stake,0.99) AS p99,
           PERCENTILE_APPROX(s.x_valid,0.50) AS p50_valid,
           PERCENTILE_APPROX(s.x_net,0.50)   AS p50_profit,
           SUM(CASE WHEN s.x_rec = 1 THEN s.x_stake ELSE 0 END) AS st_in,
           SUM(CASE WHEN s.x_rec = 1 THEN 1 ELSE 0 END)         AS nb_in,
           SUM(CASE WHEN s.x_rec = 1 THEN s.x_net ELSE 0 END)   AS net_in,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN s.x_stake ELSE 0 END) AS st_out,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN 1 ELSE 0 END)         AS nb_out,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN s.x_net ELSE 0 END)   AS net_out,
           SUM(CASE WHEN s.x_rec=1 THEN s.x_stake ELSE 0 END) AS st_rec,
           SUM(CASE WHEN s.x_rec=1 THEN 1 ELSE 0 END)         AS nb_rec
    FROM x_mk s
    WHERE s.is_clean = 1
      AND s.x_member IS NOT NULL AND TRIM(CAST(s.x_member AS STRING)) <> ''
    GROUP BY s.x_member
  ),
  x_win AS (
    SELECT            COUNT(*) AS n_bets, COUNT(DISTINCT s.x_round) AS n_rounds,
           COUNT(DISTINCT s.x_date) AS active_days, COUNT(DISTINCT s.x_tblshoe) AS active_shoes,
           COUNT(DISTINCT CONCAT_WS('|', s.x_date, s.x_table)) AS active_sessions,
           COUNT(DISTINCT s.x_table) AS n_tables, COUNT(DISTINCT s.x_dealer) AS n_dealers,
           COUNT(DISTINCT s.x_ip) AS n_ips, COUNT(DISTINCT s.x_product) AS n_products,
           MIN(s.x_date) AS first_seen_d, MAX(s.x_date) AS last_seen_d,
           SUM(s.x_stake) AS stake, SUM(s.x_valid) AS valid, SUM(s.x_rebate) AS rebate,
           SUM(s.x_net) AS net, SUM(-s.x_net *(100.0-s.x_agpct)/100.0) AS agent_cost,
           AVG(100.0-s.x_agpct)                   AS agent_pct,
           AVG(s.x_agpct)                         AS company_retain_pct,
           SUM(-s.x_net *s.x_agpct/100.0)         AS agent_cost_a_legacy,
           SUM(s.x_valid*s.x_agpct/100.0)         AS agent_cost_valid_base_legacy,
          AVG(COALESCE(s.x_rate1,100)) AS retain_pct_lv1, AVG(COALESCE(s.x_rate2,100)) AS retain_pct_lv2,
          AVG(COALESCE(s.x_rate3,100)) AS retain_pct_lv3, AVG(COALESCE(s.x_rate4,100)) AS retain_pct_lv4,
          AVG(COALESCE(s.x_rate5,100)) AS retain_pct_lv5, AVG(s.x_chain_depth) AS chain_depth_avg,
          AVG(COALESCE(100.0-s.x_rate1,0)) AS agent_pct_lv1, AVG(COALESCE(100.0-s.x_rate2,0)) AS agent_pct_lv2,
          AVG(COALESCE(100.0-s.x_rate3,0)) AS agent_pct_lv3, AVG(COALESCE(100.0-s.x_rate4,0)) AS agent_pct_lv4,
          AVG(COALESCE(100.0-s.x_rate5,0)) AS agent_pct_lv5,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate1,0)/100.0)                        AS agent_cost_lv1,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate2,0)/100.0)                        AS agent_cost_lv2,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate3,0)/100.0)                        AS agent_cost_lv3,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate4,0)/100.0)                        AS agent_cost_lv4,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate5,0)/100.0)                        AS agent_cost_lv5,
          SUM(-s.x_net*(COALESCE(100.0-s.x_rate1,0)+COALESCE(100.0-s.x_rate2,0)
                       +COALESCE(100.0-s.x_rate3,0)+COALESCE(100.0-s.x_rate4,0)
                       +COALESCE(100.0-s.x_rate5,0))/100.0)                   AS agent_cost_chain_additive,
          SUM(-s.x_net*(1.0 - CAST(COALESCE(s.x_rate1,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate2,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate3,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate4,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate5,100) AS DOUBLE)/100.0))
                                                                       AS agent_cost_chain_nested,
           AVG(s.x_rbpct) AS rbpct, AVG(s.x_freecomm*1.0) AS freecomm_rate,
           PERCENTILE_APPROX(s.x_stake,0.25) AS p25, PERCENTILE_APPROX(s.x_stake,0.50) AS p50,
           PERCENTILE_APPROX(s.x_stake,0.75) AS p75, PERCENTILE_APPROX(s.x_stake,0.90) AS p90,
           PERCENTILE_APPROX(s.x_stake,0.95) AS p95, PERCENTILE_APPROX(s.x_stake,0.99) AS p99,
           PERCENTILE_APPROX(s.x_valid,0.50) AS p50_valid,
           PERCENTILE_APPROX(s.x_net,0.50)   AS p50_profit,
           SUM(CASE WHEN s.x_rec = 1 THEN s.x_stake ELSE 0 END) AS st_in,
           SUM(CASE WHEN s.x_rec = 1 THEN 1 ELSE 0 END)         AS nb_in,
           SUM(CASE WHEN s.x_rec = 1 THEN s.x_net ELSE 0 END)   AS net_in,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN s.x_stake ELSE 0 END) AS st_out,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN 1 ELSE 0 END)         AS nb_out,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN s.x_net ELSE 0 END)   AS net_out,
           SUM(CASE WHEN s.x_rec=1 THEN s.x_stake ELSE 0 END) AS st_rec,
           SUM(CASE WHEN s.x_rec=1 THEN 1 ELSE 0 END)         AS nb_rec
    FROM x_mk s
    WHERE s.is_clean = 1
      AND s.x_member IS NOT NULL AND TRIM(CAST(s.x_member AS STRING)) <> ''
  ),
      q AS (
        SELECT  CAST(lmc04 AS STRING)                             AS 类别,
                COUNT(*)                                          AS 条数,
                COUNT(DISTINCT CAST(lmc02 AS STRING))             AS 涉及会员数,
                COUNT(DISTINCT CAST(lmc06 AS STRING))             AS 操作者数,
                MIN(CAST(lmc08 AS STRING))                        AS 最早异动,
                MAX(CAST(lmc08 AS STRING))                        AS 最晚异动,
                AVG(LENGTH(CAST(lmc05 AS STRING)))                AS 内容平均长度,
                MAX(CAST(lmc05 AS STRING))                        AS 内容样例,
                AVG(LENGTH(CAST(lmc09 AS STRING)))                AS SQL平均长度,
                MAX(CAST(lmc09 AS STRING))                        AS SQL样例
        FROM    ods_mariadb_2b.ods_a168_log_mem_change
        WHERE   dt >= '2026-03-21'
          AND   dt <  '2026-08-07'
        GROUP BY 1
      )
    SELECT q.*,
           -- 一·经济层
           ROUND(e.stake,4) AS stake, ROUND(e.valid,4) AS valid_bet,
           ROUND(-e.net,4) AS profit, e.n_bets, e.n_rounds,
           ROUND(e.net/NULLIF(e.stake,0),8) AS roi,
           ROUND(e.net_in/NULLIF(e.st_in,0),8) AS roi_post,
           ROUND(e.net_out/NULLIF(e.st_out,0),8) AS roi_non_post,
           ROUND((e.net-e.rebate)/NULLIF(e.stake,0),8) AS roi_ex_rebate,
           ROUND(e.net,4) AS roi_numerator, ROUND(e.stake,4) AS roi_denominator,
           CASE WHEN e.stake IS NULL THEN 'NULL_DENOM' WHEN e.stake<=0 THEN 'ZERO_DENOM'
                WHEN e.n_bets<30 THEN 'THIN_EXPOSURE' ELSE 'OK' END AS roi_denominator_status,
           ROUND(e.rebate,4) AS rebate_cost, ROUND(e.agent_cost,4)                           AS cost_complement_b,
       ROUND(e.agent_pct,4)                            AS pct_complement,
       ROUND(e.company_retain_pct,4)                   AS pct_top_bet23,
       'AG03-UNRESOLVED'                                     AS agent_formula_version,
      'ALL5_LEVELS_bet23_to_bet27'                    AS agent_level_scope,
      ROUND(e.agent_cost_lv1,4) AS agent_cost_lv1, ROUND(e.agent_cost_lv2,4) AS agent_cost_lv2,
      ROUND(e.agent_cost_lv3,4) AS agent_cost_lv3, ROUND(e.agent_cost_lv4,4) AS agent_cost_lv4,
      ROUND(e.agent_cost_lv5,4) AS agent_cost_lv5,
      ROUND(e.agent_pct_lv1,6) AS agent_pct_lv1, ROUND(e.agent_pct_lv2,6) AS agent_pct_lv2,
      ROUND(e.agent_pct_lv3,6) AS agent_pct_lv3, ROUND(e.agent_pct_lv4,6) AS agent_pct_lv4,
      ROUND(e.agent_pct_lv5,6) AS agent_pct_lv5,
      ROUND(e.retain_pct_lv1,6) AS retain_pct_lv1, ROUND(e.retain_pct_lv2,6) AS retain_pct_lv2,
      ROUND(e.retain_pct_lv3,6) AS retain_pct_lv3, ROUND(e.retain_pct_lv4,6) AS retain_pct_lv4,
      ROUND(e.retain_pct_lv5,6) AS retain_pct_lv5, ROUND(e.chain_depth_avg,4) AS chain_depth_avg,
      ROUND(e.agent_cost_chain_additive,4)            AS agent_cost_chain_additive,
      ROUND(e.agent_cost_chain_nested,4)              AS agent_cost_chain_nested,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_additive,4) AS residual_chain_additive,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_nested,4)   AS residual_chain_nested,
      'PENDING_AG03'                                  AS decision_status,
      'FALSE'                                         AS admit_to_risk_decision,
      'NOT_FOR_ENFORCEMENT'                           AS deliverable_class,
       ROUND(e.agent_cost_a_legacy,4)                  AS agent_cost_a_legacy,
       ROUND(e.agent_cost_valid_base_legacy,4)         AS agent_cost_valid_base_legacy,
           ROUND(-e.net-e.rebate,4)                        AS ngr,
       ROUND(-e.net-e.rebate-e.agent_cost,4)           AS residual_b,
       ROUND(-e.net-e.rebate-e.agent_cost_a_legacy,4)  AS residual_a,
           ROUND((-e.net-e.rebate)/NULLIF(e.stake,0),8)    AS ngr_rate,
       ROUND((-e.net-e.rebate-e.agent_cost)/NULLIF(e.stake,0),8)   AS residual_b_rate,
      -- 【HF9c · canonical accounting contract】
      --   以下 canonical 字段只增加明确 scope；不删除、不覆盖既有字段。
      --   formal_bet23_* 保持 HF9b 当前生产公式及其 NULL/0 语义；
      --   lv1~lv5 / additive / nested 则分别采用各自原始 e.* 成本字段，
      --   rate 一律从未舍入的 e.* 分子 / e.stake 计算，禁止由展示值反算。
      ROUND(e.agent_cost,4) AS agent_cost_bet23_formal_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost,4) AS net_margin_bet23_formal_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost)/NULLIF(e.stake,0),8) AS net_margin_bet23_formal_rate_canonical,
      ROUND(e.agent_cost_lv1,4) AS agent_cost_lv1_bet23_canonical,
      ROUND(e.agent_cost_lv2,4) AS agent_cost_lv2_bet24_canonical,
      ROUND(e.agent_cost_lv3,4) AS agent_cost_lv3_bet25_canonical,
      ROUND(e.agent_cost_lv4,4) AS agent_cost_lv4_bet26_canonical,
      ROUND(e.agent_cost_lv5,4) AS agent_cost_lv5_bet27_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_lv1,4) AS net_margin_lv1_bet23_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_lv1)/NULLIF(e.stake,0),8) AS net_margin_lv1_bet23_rate_canonical,
      ROUND(e.agent_cost_chain_additive,4) AS agent_cost_chain_additive_canonical,
      ROUND(e.agent_cost_chain_nested,4) AS agent_cost_chain_nested_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_additive,4) AS net_margin_chain_additive_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_nested,4) AS net_margin_chain_nested_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_chain_additive)/NULLIF(e.stake,0),8) AS net_margin_chain_additive_rate_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_chain_nested)/NULLIF(e.stake,0),8) AS net_margin_chain_nested_rate_canonical,
       ROUND((-e.net-e.rebate-e.agent_cost_a_legacy)/NULLIF(e.stake,0),8) AS residual_a_rate,
           -- 二·分布层
           ROUND(e.stake/NULLIF(e.n_bets,0),4) AS avg_stake_per_bet,
           ROUND(e.valid/NULLIF(e.n_rounds,0),4) AS avg_valid_bet_per_round,
           ROUND(-e.net/NULLIF(e.n_rounds,0),4) AS avg_profit_per_round,
           ROUND(-e.net/NULLIF(e.active_days,0),4) AS avg_profit_per_day,
           ROUND(-e.net/NULLIF(e.active_shoes,0),4) AS avg_profit_per_shoe,
           ROUND(e.stake/NULLIF(e.active_days,0),4) AS avg_stake_per_active_day,
           ROUND(e.n_rounds*1.0/NULLIF(e.active_days,0),4) AS avg_rounds_per_active_day,
           ROUND(e.st_in/NULLIF(e.nb_in,0),4) AS avg_stake_post,
           ROUND(e.st_out/NULLIF(e.nb_out,0),4) AS avg_stake_non_post,
           ROUND(e.p25,4) AS p25_stake, ROUND(e.p50,4) AS p50_stake, ROUND(e.p75,4) AS p75_stake,
           ROUND(e.p90,4) AS p90_stake, ROUND(e.p95,4) AS p95_stake, ROUND(e.p99,4) AS p99_stake,
           ROUND(e.p50_valid,4) AS p50_valid_bet, ROUND(e.p50_profit,4) AS p50_profit,
           ROUND(e.p95/NULLIF(e.p50,0),6) AS p95_over_p50,
           ROUND(e.p99/NULLIF(e.p50,0),6) AS p99_over_p50,
           ROUND((e.stake/NULLIF(e.n_bets,0))/NULLIF(e.p50,0),6) AS avg_over_p50,
           -- 三·关系层
           e.n_tables AS common_table_count, e.n_dealers AS common_dealer_count,
           e.n_ips AS common_ip_count, e.n_products AS common_product_count,
           ROUND(e.st_in/NULLIF(e.stake,0),8) AS share_post,
           -- 四·rate 层
           ROUND(-e.net/NULLIF(e.stake,0),8) AS hold_rate,
           ROUND(-e.net_in/NULLIF(e.st_in,0),8) AS hold_rate_post,
           ROUND(e.rebate/NULLIF(e.valid,0),8) AS rebate_rate_actual,
           ROUND(e.rbpct,6) AS rebate_pct_config,
           ROUND(e.valid/NULLIF(e.stake,0),6) AS turnover_multiple,
           ROUND(e.freecomm_rate,6) AS free_comm_rate,
           ROUND(e.net_in/NULLIF(e.st_in,0)-e.net_out/NULLIF(e.st_out,0),8) AS roi_delta_post,
           -- 五·动态层
           e.first_seen_d AS first_seen, e.last_seen_d AS last_seen,
           e.active_days, e.active_shoes, e.active_sessions,
           DATEDIFF(e.last_seen_d, e.first_seen_d)+1 AS span_days,
           ROUND(e.active_days*1.0/NULLIF(DATEDIFF(e.last_seen_d,e.first_seen_d)+1,0),6) AS persistence,
           ROUND((e.st_in/NULLIF(e.nb_in,0))/NULLIF(e.st_out/NULLIF(e.nb_out,0),0),6) AS ramp_post,
           ROUND((e.st_rec/NULLIF(e.nb_rec,0))/NULLIF(e.stake/NULLIF(e.n_bets,0),0),6) AS ramp_recent,
           ROUND((e.st_rec/NULLIF(e.stake,0))/0.30,6) AS stake_ramp,
           -- 六·决策层（HF9g-P5 · D-14 斧正 —— 本件属【全窗基线族】，相对刻度与决策标签一律 NULL）
           --   病灶：x_win 系全窗单行聚合（无 GROUP BY，恒 1 行，此为设计使然，非缺陷），
           --         经 CROSS JOIN 接入后 e.* 全行同值；六层之 NTILE / PERCENT_RANK 施于常数即退化，
           --         PERCENT_RANK 恒 0 ⇒ action_priority 恒判 A，全件 100% 误标。
           --   ★ 斧正原则：不给 x_win 补 GROUP BY —— 那会改变其「全窗基线」语义，属退化。
           --     正解与 #018 之 G-05／G-06 同治：范围外之行不得接受任何下游评分与决策标签。
           --   ★ 本件之 e.* 仍照常供其它列作全窗基线使用，仅六层相对刻度与决策标签置 NULL。
           CAST(NULL AS INT)                                              AS vip_tier,                        -- 空值取值：全窗基线族无实体可分档，置 NULL（NULL＝不适用，非 0）
           CAST(NULL AS DOUBLE)                                           AS economic_value,                  -- 空值取值：同上，禁以常数百分位冒充经济价值
           CAST(NULL AS DOUBLE)                                           AS roi_pr_global,                   -- 空值取值：同上
           CAST(NULL AS DOUBLE)                                           AS risk_value,                      -- 空值取值：兼容列，同上
           CAST(NULL AS DOUBLE)                                           AS pr_stake,                        -- 空值取值：兼容列，同上
           CAST(NULL AS DOUBLE)                                           AS pr_global,                       -- 空值取值：同上
           CAST(NULL AS DOUBLE)                                           AS pr_qualified,                    -- 空值取值：同上
           'GLOBAL_BASELINE_NO_ENTITY_RANKING'                            AS pr_qualified_population,         -- 字面取值：血统 —— 明示本件为全窗基线族，无实体排序总体
           CAST(NULL AS BIGINT)                                           AS pr_global_population_n,          -- 空值取值：血统 —— 不适用
           CAST(NULL AS BIGINT)                                           AS pr_qualified_population_n,       -- 空值取值：血统 —— 不适用
           'NOT_APPLICABLE_GLOBAL_BASELINE'                               AS pr_calculation_method,           -- 字面取值：血统 —— 算法不适用
           'HF9g-P5'                                                      AS pr_calculation_version,          -- 字面取值：血统 —— 算法版本
           CAST(NULL AS STRING)                                           AS evidence_flag,                   -- 空值取值：证据旗标不适用于全窗基线
           CAST(NULL AS STRING)                                           AS evidence_rate,                   -- 空值取值：同上
           CAST(NULL AS DOUBLE)                                           AS hold_ci_halfwidth_approx,        -- 空值取值：同上
           'X 全窗基线 · 不参与实体赏罚'                                    AS action_priority                  -- 字面取值：★ D-14 斧正 —— 本族恒不入赏罚，取代原 100% 误标之「A」
    FROM q
    CROSS JOIN x_win e
  ) y
) z
-- ── 逐批 WHERE 阶梯（★ 口诀：上界 ＝ 下界 ＋ 100000，两数同进）──
--    本件 T_true 未测，无需先跑 T_true；以 0 / 100000 控制本批返回区间，末批由实际行数 < 100000 判定
--    WHERE z.audit_rn >        0 AND z.audit_rn <=   100000   -- 第 1 批
--    WHERE z.audit_rn >   100000 AND z.audit_rn <=   200000   -- 第 2 批
--    WHERE z.audit_rn >   200000 AND z.audit_rn <=   300000   -- 第 3 批
--    WHERE z.audit_rn >   300000 AND z.audit_rn <=   400000   -- 第 4 批
--    WHERE z.audit_rn >   400000 AND z.audit_rn <=   500000   -- 第 5 批
--    WHERE z.audit_rn >   500000 AND z.audit_rn <=   600000   -- 第 6 批
--    WHERE z.audit_rn >   600000 AND z.audit_rn <=   700000   -- 第 7 批
--    …余批类推。第 k 批：WHERE z.audit_rn > (k-1)*100000 AND z.audit_rn <= k*100000
--    某批返回 < 100000 行即为末批，其后不再取。
--
--    ⚠ 常见误写（务必避开）：只推下界而上界不动 ——
--        WHERE z.audit_rn > 100000 AND z.audit_rn <= 100000   ← 自相矛盾，恒为假，返回空集
--        WHERE z.audit_rn > 200000 AND z.audit_rn <= 100000   ← 同上，空集
--      两个数必须**同时**前进，且始终相差 100000。
--      下界 ＝ 上一批之上界；上界 ＝ 本批之上界。
WHERE z.audit_rn > 0 AND z.audit_rn <= 100000 -- ★ HF9c 本批区间
ORDER BY z.audit_rn;


-- ══════════════════════════════════════════════════════════════════════════════════════════════
--  92. TL08_treatment_events.csv   [总包行 8541~8572 · 原 9 列 ＋六层约 60 列]
--     典型学：M09 处置限额　派生旗标：post（s.x_rec = 1 · 仅供 CASE 条件聚合，全包无任何 WHERE/AND/HAVING 以此过滤）　连接：q.`member_id`
-- ══════════════════════════════════════════════════════════════════════════════════════════════
-- ── ① 先跑 T_true 留档（不足 100000 者一次导全，不必分批）──
-- ── ① T_true：HF9c 不再强制预跑完整 COUNT。
--    本批实际返回行数 < 100000 即判定为末批；全批完成后以各批 n_rows / audit_rn 范围核对总量。

-- ── ② 分批取数：第 1 批。第 k 批只改末行两数为 (k-1)*100000 与 k*100000 ──
--    审计字段二（REDTEAM 2026-08-24 裁定 · 四锁）：
--      audit_rn  全局观测坐标 —— 由**与原版审计版逐字同一**之排序键所生，两版可逐行对账
--      batch_id  物理分批信息 —— 该行所属批次，由 audit_rn 算得，非引擎所赋
--    ★ 锁三：二者皆为审计字段，**不得进入任何业务指标计算**。
--    ★ 锁四：两版经 audit_rn 逐行字段核验后，方可宣布输出完全一致。

-- ── ③ 每批取回后自证四数（任一不符即停手回报，禁止放行）──
--    n_rows        = COUNT(*)      须等于 COUNT(DISTINCT audit_rn)   （批内无重复）
--    audit_rn_min  = MIN(audit_rn) 须等于 (k-1)*100000 + 1           （与上批严丝合缝）
--    audit_rn_max  = MAX(audit_rn) 须等于 min + n_rows - 1           （批内无缺口）
--    全批取毕再验：各批 audit_rn 之并集 = 1 .. T_true，无缺号、无重号。
--     ★ 首行＝平台真净亏最多者（已扣退水与代理占成）。
--
SELECT z.*,
       CAST(FLOOR((z.audit_rn - 1) / 100000) + 1 AS INT)          AS batch_id,
       'A168_HF9F_20260827_0900' AS run_id,
       '2026-08-27 09:00:00' AS snapshot_sync_time
FROM (
  SELECT y.*,
         ROW_NUMBER() OVER (ORDER BY y.`residual_b` ASC, y.`roi` DESC, y.`member_id`, y.`action_date`, y.`action_time`, y.`action_class`, y.`operator_id`, y.`operator_lv`, y.`content`, y.`raw_sql`, y.`is_baccarat_member`) AS audit_rn
  FROM (
    WITH
      x_ranked AS (
    SELECT b.bet01, b.bet03, b.bet04, b.bet05, b.bet09, b.bet11, b.bet13,
           b.bet15, b.bet16, b.bet17, b.bet18, b.bet19, b.bet20, b.bet21,
           b.bet22, b.bet23, b.bet24, b.bet25, b.bet26, b.bet27, b.bet38, b.bet39, b.category, b.commission,
           b.dt, b.eid, b.ip, b.validbet, b.updatetime, b.sync_time,
           ROW_NUMBER() OVER (
             PARTITION BY b.bet01
             ORDER BY b.updatetime DESC, b.sync_time DESC, b.dt DESC)      AS x_rn
    FROM ods_mariadb_2b.ods_a168_bet02 b
    WHERE b.dt >= '2026-03-21' AND b.dt < '2026-08-07'
      AND b.bet02 = '101'
      AND b.sync_time <= '2026-08-27 09:00:00'
  ),
    x_testagent AS (
    SELECT age001 AS agent_id FROM ods_mariadb_2b.ods_a168_agent WHERE age022 = '1'
  ),
    x_bs0 AS (
    SELECT b.bet05 AS x_member, b.eid AS x_dealer, b.bet39 AS x_table,
           b.bet03 AS x_shoe, b.ip AS x_ip, b.bet09 AS x_product, b.dt AS x_date,
           CONCAT_WS('|', b.bet03, b.bet04, b.bet39)                      AS x_round,
           CONCAT_WS('|', b.bet39, b.bet03)                               AS x_tblshoe,
           CAST(NULLIF(TRIM(b.bet04),'') AS INT)                          AS x_rno,
           CASE WHEN b.dt >= '2026-07-08' THEN 1 ELSE 0 END               AS x_rec,
           CASE WHEN TRIM(b.commission)='1' THEN 1 ELSE 0 END             AS x_freecomm,
           CAST(NULLIF(TRIM(b.bet13),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_stake,
           CAST(NULLIF(TRIM(b.validbet),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_valid,
           CAST(NULLIF(TRIM(b.bet16),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_rebate,
           CAST(NULLIF(TRIM(b.bet17),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_net,
           CAST(NULLIF(TRIM(b.bet15),'') AS DECIMAL(20,6))                AS x_rbpct,
           COALESCE(CAST(NULLIF(TRIM(b.bet23),'') AS DECIMAL(20,6)),0)   AS x_agpct,
          NULLIF(CAST(NULLIF(TRIM(b.bet23),'') AS DECIMAL(20,6)),0)     AS x_rate1,
          NULLIF(CAST(NULLIF(TRIM(b.bet24),'') AS DECIMAL(20,6)),0)     AS x_rate2,
          NULLIF(CAST(NULLIF(TRIM(b.bet25),'') AS DECIMAL(20,6)),0)     AS x_rate3,
          NULLIF(CAST(NULLIF(TRIM(b.bet26),'') AS DECIMAL(20,6)),0)     AS x_rate4,
          NULLIF(CAST(NULLIF(TRIM(b.bet27),'') AS DECIMAL(20,6)),0)     AS x_rate5,
          (CASE WHEN NULLIF(CAST(NULLIF(TRIM(b.bet22),'') AS BIGINT),0) IS NOT NULL THEN 5
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet21),'') AS BIGINT),0) IS NOT NULL THEN 4
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet20),'') AS BIGINT),0) IS NOT NULL THEN 3
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet19),'') AS BIGINT),0) IS NOT NULL THEN 2
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet18),'') AS BIGINT),0) IS NOT NULL THEN 1
                ELSE 0 END)                                             AS x_chain_depth,
           CASE WHEN COALESCE(t1.agent_id,t2.agent_id,t3.agent_id,
                              t4.agent_id,t5.agent_id) IS NOT NULL
                THEN 1 ELSE 0 END                                        AS f_testline
    FROM x_ranked b
    LEFT JOIN x_testagent t1 ON t1.agent_id = b.bet18
    LEFT JOIN x_testagent t2 ON t2.agent_id = b.bet19
    LEFT JOIN x_testagent t3 ON t3.agent_id = b.bet20
    LEFT JOIN x_testagent t4 ON t4.agent_id = b.bet21
    LEFT JOIN x_testagent t5 ON t5.agent_id = b.bet22
    WHERE b.x_rn = 1
      AND b.category='1' AND UPPER(TRIM(b.bet38))='N'
      AND CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8)) > 0
  ),
  x_mk AS (
    SELECT s.*,
           CASE WHEN s.f_testline = 0 THEN 1 ELSE 0 END                 AS is_clean
    FROM x_bs0 s
  ),
  x_agg AS (
    SELECT s.x_member                                                        AS x_key,
           COUNT(*) AS n_bets, COUNT(DISTINCT s.x_round) AS n_rounds,
           COUNT(DISTINCT s.x_date) AS active_days, COUNT(DISTINCT s.x_tblshoe) AS active_shoes,
           COUNT(DISTINCT CONCAT_WS('|', s.x_date, s.x_table)) AS active_sessions,
           COUNT(DISTINCT s.x_table) AS n_tables, COUNT(DISTINCT s.x_dealer) AS n_dealers,
           COUNT(DISTINCT s.x_ip) AS n_ips, COUNT(DISTINCT s.x_product) AS n_products,
           MIN(s.x_date) AS first_seen_d, MAX(s.x_date) AS last_seen_d,
           SUM(s.x_stake) AS stake, SUM(s.x_valid) AS valid, SUM(s.x_rebate) AS rebate,
           SUM(s.x_net) AS net, SUM(-s.x_net *(100.0-s.x_agpct)/100.0) AS agent_cost,
           AVG(100.0-s.x_agpct)                   AS agent_pct,
           AVG(s.x_agpct)                         AS company_retain_pct,
           SUM(-s.x_net *s.x_agpct/100.0)         AS agent_cost_a_legacy,
           SUM(s.x_valid*s.x_agpct/100.0)         AS agent_cost_valid_base_legacy,
          AVG(COALESCE(s.x_rate1,100)) AS retain_pct_lv1, AVG(COALESCE(s.x_rate2,100)) AS retain_pct_lv2,
          AVG(COALESCE(s.x_rate3,100)) AS retain_pct_lv3, AVG(COALESCE(s.x_rate4,100)) AS retain_pct_lv4,
          AVG(COALESCE(s.x_rate5,100)) AS retain_pct_lv5, AVG(s.x_chain_depth) AS chain_depth_avg,
          AVG(COALESCE(100.0-s.x_rate1,0)) AS agent_pct_lv1, AVG(COALESCE(100.0-s.x_rate2,0)) AS agent_pct_lv2,
          AVG(COALESCE(100.0-s.x_rate3,0)) AS agent_pct_lv3, AVG(COALESCE(100.0-s.x_rate4,0)) AS agent_pct_lv4,
          AVG(COALESCE(100.0-s.x_rate5,0)) AS agent_pct_lv5,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate1,0)/100.0)                        AS agent_cost_lv1,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate2,0)/100.0)                        AS agent_cost_lv2,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate3,0)/100.0)                        AS agent_cost_lv3,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate4,0)/100.0)                        AS agent_cost_lv4,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate5,0)/100.0)                        AS agent_cost_lv5,
          SUM(-s.x_net*(COALESCE(100.0-s.x_rate1,0)+COALESCE(100.0-s.x_rate2,0)
                       +COALESCE(100.0-s.x_rate3,0)+COALESCE(100.0-s.x_rate4,0)
                       +COALESCE(100.0-s.x_rate5,0))/100.0)                   AS agent_cost_chain_additive,
          SUM(-s.x_net*(1.0 - CAST(COALESCE(s.x_rate1,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate2,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate3,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate4,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate5,100) AS DOUBLE)/100.0))
                                                                       AS agent_cost_chain_nested,
           AVG(s.x_rbpct) AS rbpct, AVG(s.x_freecomm*1.0) AS freecomm_rate,
           PERCENTILE_APPROX(s.x_stake,0.25) AS p25, PERCENTILE_APPROX(s.x_stake,0.50) AS p50,
           PERCENTILE_APPROX(s.x_stake,0.75) AS p75, PERCENTILE_APPROX(s.x_stake,0.90) AS p90,
           PERCENTILE_APPROX(s.x_stake,0.95) AS p95, PERCENTILE_APPROX(s.x_stake,0.99) AS p99,
           PERCENTILE_APPROX(s.x_valid,0.50) AS p50_valid,
           PERCENTILE_APPROX(s.x_net,0.50)   AS p50_profit,
           SUM(CASE WHEN s.x_rec = 1 THEN s.x_stake ELSE 0 END) AS st_in,
           SUM(CASE WHEN s.x_rec = 1 THEN 1 ELSE 0 END)         AS nb_in,
           SUM(CASE WHEN s.x_rec = 1 THEN s.x_net ELSE 0 END)   AS net_in,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN s.x_stake ELSE 0 END) AS st_out,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN 1 ELSE 0 END)         AS nb_out,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN s.x_net ELSE 0 END)   AS net_out,
           SUM(CASE WHEN s.x_rec=1 THEN s.x_stake ELSE 0 END) AS st_rec,
           SUM(CASE WHEN s.x_rec=1 THEN 1 ELSE 0 END)         AS nb_rec
    FROM x_mk s
    WHERE s.is_clean = 1
      AND s.x_member IS NOT NULL AND TRIM(CAST(s.x_member AS STRING)) <> ''
    GROUP BY s.x_member
  ),
      q AS (
        WITH ev AS (
            SELECT  CAST(lmc02 AS STRING)                         AS member_id,
                    CAST(lmc04 AS STRING)                         AS action_class,
                    SUBSTR(CAST(lmc08 AS STRING), 1, 10)          AS action_date,
                    CAST(lmc08 AS STRING)                         AS action_time,
                    CAST(lmc06 AS STRING)                         AS operator_id,
                    CAST(lmc07 AS STRING)                         AS operator_lv,
                    CAST(lmc05 AS STRING)                         AS content,
                    CAST(lmc09 AS STRING)                         AS raw_sql
            FROM    ods_mariadb_2b.ods_a168_log_mem_change
            WHERE   dt >= '2026-03-21'
              AND   dt <  '2026-08-07'
        ),
        bl AS (
            SELECT  DISTINCT CAST(bet05 AS STRING)                AS member_id
            FROM    ods_mariadb_2b.ods_a168_bet02
            WHERE   dt >= '2026-03-21'
              AND sync_time <= '2026-08-27 09:00:00'
              AND   dt <  '2026-08-07'
              AND   CAST(bet02 AS STRING) = '101'
        )
        SELECT  ev.member_id,
                ev.action_date,
                ev.action_time,
                ev.action_class,
                ev.operator_id,
                ev.operator_lv,
                ev.content,
                ev.raw_sql,
                CASE WHEN bl.member_id IS NULL THEN 0 ELSE 1 END  AS is_baccarat_member
        FROM        ev
        LEFT JOIN   bl ON bl.member_id = ev.member_id
      )
    SELECT q.*,
           -- 一·经济层
           ROUND(e.stake,4) AS stake, ROUND(e.valid,4) AS valid_bet,
           ROUND(-e.net,4) AS profit, e.n_bets, e.n_rounds,
           ROUND(e.net/NULLIF(e.stake,0),8) AS roi,
           ROUND(e.net_in/NULLIF(e.st_in,0),8) AS roi_post,
           ROUND(e.net_out/NULLIF(e.st_out,0),8) AS roi_non_post,
           ROUND((e.net-e.rebate)/NULLIF(e.stake,0),8) AS roi_ex_rebate,
           ROUND(e.net,4) AS roi_numerator, ROUND(e.stake,4) AS roi_denominator,
           CASE WHEN e.stake IS NULL THEN 'NULL_DENOM' WHEN e.stake<=0 THEN 'ZERO_DENOM'
                WHEN e.n_bets<30 THEN 'THIN_EXPOSURE' ELSE 'OK' END AS roi_denominator_status,
           ROUND(e.rebate,4) AS rebate_cost, ROUND(e.agent_cost,4)                           AS cost_complement_b,
       ROUND(e.agent_pct,4)                            AS pct_complement,
       ROUND(e.company_retain_pct,4)                   AS pct_top_bet23,
       'AG03-UNRESOLVED'                                     AS agent_formula_version,
      'ALL5_LEVELS_bet23_to_bet27'                    AS agent_level_scope,
      ROUND(e.agent_cost_lv1,4) AS agent_cost_lv1, ROUND(e.agent_cost_lv2,4) AS agent_cost_lv2,
      ROUND(e.agent_cost_lv3,4) AS agent_cost_lv3, ROUND(e.agent_cost_lv4,4) AS agent_cost_lv4,
      ROUND(e.agent_cost_lv5,4) AS agent_cost_lv5,
      ROUND(e.agent_pct_lv1,6) AS agent_pct_lv1, ROUND(e.agent_pct_lv2,6) AS agent_pct_lv2,
      ROUND(e.agent_pct_lv3,6) AS agent_pct_lv3, ROUND(e.agent_pct_lv4,6) AS agent_pct_lv4,
      ROUND(e.agent_pct_lv5,6) AS agent_pct_lv5,
      ROUND(e.retain_pct_lv1,6) AS retain_pct_lv1, ROUND(e.retain_pct_lv2,6) AS retain_pct_lv2,
      ROUND(e.retain_pct_lv3,6) AS retain_pct_lv3, ROUND(e.retain_pct_lv4,6) AS retain_pct_lv4,
      ROUND(e.retain_pct_lv5,6) AS retain_pct_lv5, ROUND(e.chain_depth_avg,4) AS chain_depth_avg,
      ROUND(e.agent_cost_chain_additive,4)            AS agent_cost_chain_additive,
      ROUND(e.agent_cost_chain_nested,4)              AS agent_cost_chain_nested,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_additive,4) AS residual_chain_additive,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_nested,4)   AS residual_chain_nested,
      'PENDING_AG03'                                  AS decision_status,
      'FALSE'                                         AS admit_to_risk_decision,
      'NOT_FOR_ENFORCEMENT'                           AS deliverable_class,
       ROUND(e.agent_cost_a_legacy,4)                  AS agent_cost_a_legacy,
       ROUND(e.agent_cost_valid_base_legacy,4)         AS agent_cost_valid_base_legacy,
           ROUND(-e.net-e.rebate,4)                        AS ngr,
       ROUND(-e.net-e.rebate-e.agent_cost,4)           AS residual_b,
       ROUND(-e.net-e.rebate-e.agent_cost_a_legacy,4)  AS residual_a,
           ROUND((-e.net-e.rebate)/NULLIF(e.stake,0),8)    AS ngr_rate,
       ROUND((-e.net-e.rebate-e.agent_cost)/NULLIF(e.stake,0),8)   AS residual_b_rate,
      -- 【HF9c · canonical accounting contract】
      --   以下 canonical 字段只增加明确 scope；不删除、不覆盖既有字段。
      --   formal_bet23_* 保持 HF9b 当前生产公式及其 NULL/0 语义；
      --   lv1~lv5 / additive / nested 则分别采用各自原始 e.* 成本字段，
      --   rate 一律从未舍入的 e.* 分子 / e.stake 计算，禁止由展示值反算。
      ROUND(e.agent_cost,4) AS agent_cost_bet23_formal_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost,4) AS net_margin_bet23_formal_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost)/NULLIF(e.stake,0),8) AS net_margin_bet23_formal_rate_canonical,
      ROUND(e.agent_cost_lv1,4) AS agent_cost_lv1_bet23_canonical,
      ROUND(e.agent_cost_lv2,4) AS agent_cost_lv2_bet24_canonical,
      ROUND(e.agent_cost_lv3,4) AS agent_cost_lv3_bet25_canonical,
      ROUND(e.agent_cost_lv4,4) AS agent_cost_lv4_bet26_canonical,
      ROUND(e.agent_cost_lv5,4) AS agent_cost_lv5_bet27_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_lv1,4) AS net_margin_lv1_bet23_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_lv1)/NULLIF(e.stake,0),8) AS net_margin_lv1_bet23_rate_canonical,
      ROUND(e.agent_cost_chain_additive,4) AS agent_cost_chain_additive_canonical,
      ROUND(e.agent_cost_chain_nested,4) AS agent_cost_chain_nested_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_additive,4) AS net_margin_chain_additive_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_nested,4) AS net_margin_chain_nested_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_chain_additive)/NULLIF(e.stake,0),8) AS net_margin_chain_additive_rate_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_chain_nested)/NULLIF(e.stake,0),8) AS net_margin_chain_nested_rate_canonical,
       ROUND((-e.net-e.rebate-e.agent_cost_a_legacy)/NULLIF(e.stake,0),8) AS residual_a_rate,
           -- 二·分布层
           ROUND(e.stake/NULLIF(e.n_bets,0),4) AS avg_stake_per_bet,
           ROUND(e.valid/NULLIF(e.n_rounds,0),4) AS avg_valid_bet_per_round,
           ROUND(-e.net/NULLIF(e.n_rounds,0),4) AS avg_profit_per_round,
           ROUND(-e.net/NULLIF(e.active_days,0),4) AS avg_profit_per_day,
           ROUND(-e.net/NULLIF(e.active_shoes,0),4) AS avg_profit_per_shoe,
           ROUND(e.stake/NULLIF(e.active_days,0),4) AS avg_stake_per_active_day,
           ROUND(e.n_rounds*1.0/NULLIF(e.active_days,0),4) AS avg_rounds_per_active_day,
           ROUND(e.st_in/NULLIF(e.nb_in,0),4) AS avg_stake_post,
           ROUND(e.st_out/NULLIF(e.nb_out,0),4) AS avg_stake_non_post,
           ROUND(e.p25,4) AS p25_stake, ROUND(e.p50,4) AS p50_stake, ROUND(e.p75,4) AS p75_stake,
           ROUND(e.p90,4) AS p90_stake, ROUND(e.p95,4) AS p95_stake, ROUND(e.p99,4) AS p99_stake,
           ROUND(e.p50_valid,4) AS p50_valid_bet, ROUND(e.p50_profit,4) AS p50_profit,
           ROUND(e.p95/NULLIF(e.p50,0),6) AS p95_over_p50,
           ROUND(e.p99/NULLIF(e.p50,0),6) AS p99_over_p50,
           ROUND((e.stake/NULLIF(e.n_bets,0))/NULLIF(e.p50,0),6) AS avg_over_p50,
           -- 三·关系层
           e.n_tables AS common_table_count, e.n_dealers AS common_dealer_count,
           e.n_ips AS common_ip_count, e.n_products AS common_product_count,
           ROUND(e.st_in/NULLIF(e.stake,0),8) AS share_post,
           -- 四·rate 层
           ROUND(-e.net/NULLIF(e.stake,0),8) AS hold_rate,
           ROUND(-e.net_in/NULLIF(e.st_in,0),8) AS hold_rate_post,
           ROUND(e.rebate/NULLIF(e.valid,0),8) AS rebate_rate_actual,
           ROUND(e.rbpct,6) AS rebate_pct_config,
           ROUND(e.valid/NULLIF(e.stake,0),6) AS turnover_multiple,
           ROUND(e.freecomm_rate,6) AS free_comm_rate,
           ROUND(e.net_in/NULLIF(e.st_in,0)-e.net_out/NULLIF(e.st_out,0),8) AS roi_delta_post,
           -- 五·动态层
           e.first_seen_d AS first_seen, e.last_seen_d AS last_seen,
           e.active_days, e.active_shoes, e.active_sessions,
           DATEDIFF(e.last_seen_d, e.first_seen_d)+1 AS span_days,
           ROUND(e.active_days*1.0/NULLIF(DATEDIFF(e.last_seen_d,e.first_seen_d)+1,0),6) AS persistence,
           ROUND((e.st_in/NULLIF(e.nb_in,0))/NULLIF(e.st_out/NULLIF(e.nb_out,0),0),6) AS ramp_post,
           ROUND((e.st_rec/NULLIF(e.nb_rec,0))/NULLIF(e.stake/NULLIF(e.n_bets,0),0),6) AS ramp_recent,
           ROUND((e.st_rec/NULLIF(e.stake,0))/0.30,6) AS stake_ramp,
           -- 六·决策层（HF9f · 详见档头【HF9f 变更说明】；本段两版逐字同一）
           NTILE(5) OVER (ORDER BY e.stake) AS vip_tier,                                                        -- 窗口取值：相对刻度 B 族，全体五等分；须连同下方血统五元组一并解读，禁作硬阈值判型
           PERCENT_RANK() OVER (ORDER BY -e.net-e.rebate-e.agent_cost)    AS economic_value,                    -- 窗口取值：HF9f·F-19 修正 —— HF9e 写作 -(-…) 双负号致方向颠倒（#075 实测 corr(economic_value, residual_b) = -1.0000）；今与 action_priority 排序键归一，值大即平台真净利高
           PERCENT_RANK() OVER (ORDER BY e.net/NULLIF(e.stake,0))         AS roi_pr_global,                     -- 窗口取值：HF9f·F-17 正名 —— 本列实为 ROI（玩家净回报率）之全体百分位，与「风险」无关；旧名 risk_value 见下一行
           PERCENT_RANK() OVER (ORDER BY e.net/NULLIF(e.stake,0))         AS risk_value,                        -- 窗口取值：兼容列，恒等于 roi_pr_global，仅为下游迁移窗保留；HF9g 起废弃，禁新引用
           PERCENT_RANK() OVER (ORDER BY e.stake)                         AS pr_stake,                          -- 窗口取值：兼容列，恒等于 pr_global，原名保留以免断链
           PERCENT_RANK() OVER (ORDER BY e.stake)                         AS pr_global,                         -- 窗口取值：HF9f·F-1 双轨之一 —— 全体口径百分位，参照总体即本件全部输出行
           CASE WHEN e.n_rounds >= 30                                                                           -- 条件分支：起始分支 —— 仅在合格子集内计算合格口径百分位
                  THEN PERCENT_RANK() OVER (PARTITION BY CASE WHEN e.n_rounds >= 30 THEN 1 ELSE 0 END ORDER BY e.stake)  -- 分支取值：以合格与否分区，故本值即 n_rounds>=30 子集内之百分位
                ELSE NULL END                                             AS pr_qualified,                      -- 条件分支：收束上方分支 —— 不合格者留 NULL（NULL＝未测，非 0），产出「pr_qualified」
           'n_rounds>=30'                                                 AS pr_qualified_population,           -- 字面取值：血统 —— 合格子集之定义
           COUNT(*) OVER ()                                               AS pr_global_population_n,            -- 窗口取值：血统 —— 全体口径之参照总体规模，渲染时现算，禁写死
           SUM(CASE WHEN e.n_rounds >= 30 THEN 1 ELSE 0 END) OVER ()      AS pr_qualified_population_n,         -- 窗口取值：血统 —— 合格子集之参照总体规模，现算，禁写死
           'PERCENT_RANK_OVER_ORDER_BY_e_stake'                           AS pr_calculation_method,             -- 字面取值：血统 —— 算法标识
           'HF9f'                                                         AS pr_calculation_version,            -- 字面取值：血统 —— 算法版本
           CASE WHEN e.n_rounds IS NULL OR e.n_rounds < 30 THEN 'THIN_ROUNDS' ELSE 'OK' END AS evidence_flag,   -- 条件分支：HF9f·F-2a 证据旗标 —— THIN_ROUNDS 者禁入执行队列，仅入观察队列
           CASE WHEN e.n_rounds IS NULL       THEN NULL                                                         -- 条件分支：起始分支 —— 未测者留 NULL（自家铁律：NULL ≠ 0）
                WHEN e.n_rounds >= 31483      THEN 'L1_POWERED'                                                 -- 分支判定：MDE 反解第一档
                WHEN e.n_rounds >= 15409      THEN 'L2_CI_1P5'                                                  -- 分支判定：MDE 反解第二档
                WHEN e.n_rounds >=  8668      THEN 'L3_CI_2P0'                                                  -- 分支判定：MDE 反解第三档
                WHEN e.n_rounds >=  3852      THEN 'L4_CI_3P0'                                                  -- 分支判定：MDE 反解第四档
                ELSE 'L5_INSUFFICIENT' END                                AS evidence_rate,                     -- 条件分支：收束上方 —— HF9f·F-3 证据分档，承 HF9e 前议之 MDE 反解五档，须于 F-4 敏感性实验后复核
           ROUND(1.96 * 0.95 / SQRT(NULLIF(CAST(e.n_rounds AS DOUBLE),0)),8) AS hold_ci_halfwidth_approx,       -- 比率表达式：HF9f·F-3 逐行现算之 95% 半宽近似；常数 0.95 为登记值，本轮 #075 实测每局 ROI 隐含 σ 于最薄层为 0.9249，二者差异待 F-4 裁定
           CASE WHEN e.stake IS NULL OR e.stake<=0 OR e.n_bets<30 OR e.n_rounds IS NULL OR e.n_rounds<30 THEN 'Z 证据不足 · 不动作'  -- 条件分支：HF9f·F-2 双条件取严 —— HF9e 仅卡 e.n_bets<30，致 n_bets>=30 而 n_rounds<30 者绕过 Z（#075 实测 18,537 名，其中 8,145 名已入 A/D 待裁）；今两条件并列取严
                WHEN PERCENT_RANK() OVER (ORDER BY -e.net-e.rebate-e.agent_cost)<=0.10                          -- 分支判定：平台真净利之最低十分位
                  THEN 'A 净亏最大十分位 · 优先复核'                                                             -- 分支取值：HF9f·F-20 正名 —— 本档 Σresidual_b 于 #075 实测 = -100,236,896，系平台净亏最大群，旧名「残值最低十分位 · 待裁」名实不符
                WHEN PERCENT_RANK() OVER (ORDER BY -e.net-e.rebate-e.agent_cost)>=0.80                          -- 分支判定：平台真净利之最高二十分位
                  THEN 'D 净利最高二十分位 · 优先留存'                                                           -- 分支取值：HF9f·F-20 正名 —— 本档 Σresidual_b 于 #075 实测 = +281,733,190，系核心利润源；与 A 档方向相反，旧版同标「待裁」属名实不符
                ELSE 'E 常规' END                                          AS action_priority                   -- 条件分支：收束上方判词，产出「action_priority」
    FROM q
    LEFT JOIN x_agg e ON CAST(e.x_key AS STRING) = CAST(q.`member_id` AS STRING)
  ) y
) z
-- ── 逐批 WHERE 阶梯（★ 口诀：上界 ＝ 下界 ＋ 100000，两数同进）──
--    本件 T_true 未测，无需先跑 T_true；以 0 / 100000 控制本批返回区间，末批由实际行数 < 100000 判定
--    WHERE z.audit_rn >        0 AND z.audit_rn <=   100000   -- 第 1 批
--    WHERE z.audit_rn >   100000 AND z.audit_rn <=   200000   -- 第 2 批
--    WHERE z.audit_rn >   200000 AND z.audit_rn <=   300000   -- 第 3 批
--    WHERE z.audit_rn >   300000 AND z.audit_rn <=   400000   -- 第 4 批
--    WHERE z.audit_rn >   400000 AND z.audit_rn <=   500000   -- 第 5 批
--    WHERE z.audit_rn >   500000 AND z.audit_rn <=   600000   -- 第 6 批
--    WHERE z.audit_rn >   600000 AND z.audit_rn <=   700000   -- 第 7 批
--    …余批类推。第 k 批：WHERE z.audit_rn > (k-1)*100000 AND z.audit_rn <= k*100000
--    某批返回 < 100000 行即为末批，其后不再取。
--
--    ⚠ 常见误写（务必避开）：只推下界而上界不动 ——
--        WHERE z.audit_rn > 100000 AND z.audit_rn <= 100000   ← 自相矛盾，恒为假，返回空集
--        WHERE z.audit_rn > 200000 AND z.audit_rn <= 100000   ← 同上，空集
--      两个数必须**同时**前进，且始终相差 100000。
--      下界 ＝ 上一批之上界；上界 ＝ 本批之上界。
WHERE z.audit_rn > 0 AND z.audit_rn <= 100000 -- ★ HF9c 本批区间
ORDER BY z.audit_rn;


-- ══════════════════════════════════════════════════════════════════════════════════════════════
--  93. TL09_member_schema.csv   [总包行 8603~8607 · 原 4 列 ＋六层约 60 列]
--     典型学：Z00 基建/元数据　派生旗标：recent（s.x_rec = 1 · 仅供 CASE 条件聚合，全包无任何 WHERE/AND/HAVING 以此过滤）　连接：全窗基线
-- ══════════════════════════════════════════════════════════════════════════════════════════════
-- ★ W-64 · D-14 警示（本件属 x_win 族 · 66 件之一 · 详见 §Z 段 D-14 全案）
--   本件以 `CROSS JOIN x_win e` 接入全局基线，x_win 无 GROUP BY ⇒ 恒 1 行 ⇒ e.* 全行同值。
--   故：economic_value / roi_pr_global / risk_value / pr_stake / pr_global 恒为 0；
--       action_priority 每一行皆为「A 净亏最大十分位 · 优先复核」（Z 分支永不触发）；
--       evidence_rate 恒为最高档；vip_tier 由常数键分档 ⇒ 无信息且非确定。
--   ⇒ 本件决策层三列 **NOT_FOR_DECISION**，裁定前不得用于排班、抽查或汇报。
-- ── ① 先跑 T_true 留档（不足 100000 者一次导全，不必分批）──
-- ── ① T_true：HF9c 不再强制预跑完整 COUNT。
--    本批实际返回行数 < 100000 即判定为末批；全批完成后以各批 n_rows / audit_rn 范围核对总量。

-- ── ② 分批取数：第 1 批。第 k 批只改末行两数为 (k-1)*100000 与 k*100000 ──
--    审计字段二（REDTEAM 2026-08-24 裁定 · 四锁）：
--      audit_rn  全局观测坐标 —— 由**与原版审计版逐字同一**之排序键所生，两版可逐行对账
--      batch_id  物理分批信息 —— 该行所属批次，由 audit_rn 算得，非引擎所赋
--    ★ 锁三：二者皆为审计字段，**不得进入任何业务指标计算**。
--    ★ 锁四：两版经 audit_rn 逐行字段核验后，方可宣布输出完全一致。

-- ── ③ 每批取回后自证四数（任一不符即停手回报，禁止放行）──
--    n_rows        = COUNT(*)      须等于 COUNT(DISTINCT audit_rn)   （批内无重复）
--    audit_rn_min  = MIN(audit_rn) 须等于 (k-1)*100000 + 1           （与上批严丝合缝）
--    audit_rn_max  = MAX(audit_rn) 须等于 min + n_rows - 1           （批内无缺口）
--    全批取毕再验：各批 audit_rn 之并集 = 1 .. T_true，无缺号、无重号。
--     ★ 首行＝平台真净亏最多者（已扣退水与代理占成）。
--
SELECT z.*,
       CAST(FLOOR((z.audit_rn - 1) / 100000) + 1 AS INT)          AS batch_id,
       'A168_HF9F_20260827_0900' AS run_id,
       '2026-08-27 09:00:00' AS snapshot_sync_time
FROM (
  SELECT y.*,
         ROW_NUMBER() OVER (ORDER BY y.`residual_b` ASC, y.`roi` DESC, y.`ORDINAL_POSITION`, y.`COLUMN_NAME`, y.`DATA_TYPE`, y.`COLUMN_COMMENT`) AS audit_rn
  FROM (
    WITH
      x_ranked AS (
    SELECT b.bet01, b.bet03, b.bet04, b.bet05, b.bet09, b.bet11, b.bet13,
           b.bet15, b.bet16, b.bet17, b.bet18, b.bet19, b.bet20, b.bet21,
           b.bet22, b.bet23, b.bet24, b.bet25, b.bet26, b.bet27, b.bet38, b.bet39, b.category, b.commission,
           b.dt, b.eid, b.ip, b.validbet, b.updatetime, b.sync_time,
           ROW_NUMBER() OVER (
             PARTITION BY b.bet01
             ORDER BY b.updatetime DESC, b.sync_time DESC, b.dt DESC)      AS x_rn
    FROM ods_mariadb_2b.ods_a168_bet02 b
    WHERE b.dt >= '2026-03-21' AND b.dt < '2026-08-07'
      AND b.bet02 = '101'
      AND b.sync_time <= '2026-08-27 09:00:00'
  ),
    x_testagent AS (
    SELECT age001 AS agent_id FROM ods_mariadb_2b.ods_a168_agent WHERE age022 = '1'
  ),
    x_bs0 AS (
    SELECT b.bet05 AS x_member, b.eid AS x_dealer, b.bet39 AS x_table,
           b.bet03 AS x_shoe, b.ip AS x_ip, b.bet09 AS x_product, b.dt AS x_date,
           CONCAT_WS('|', b.bet03, b.bet04, b.bet39)                      AS x_round,
           CONCAT_WS('|', b.bet39, b.bet03)                               AS x_tblshoe,
           CAST(NULLIF(TRIM(b.bet04),'') AS INT)                          AS x_rno,
           CASE WHEN b.dt >= '2026-07-08' THEN 1 ELSE 0 END               AS x_rec,
           CASE WHEN TRIM(b.commission)='1' THEN 1 ELSE 0 END             AS x_freecomm,
           CAST(NULLIF(TRIM(b.bet13),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_stake,
           CAST(NULLIF(TRIM(b.validbet),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_valid,
           CAST(NULLIF(TRIM(b.bet16),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_rebate,
           CAST(NULLIF(TRIM(b.bet17),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_net,
           CAST(NULLIF(TRIM(b.bet15),'') AS DECIMAL(20,6))                AS x_rbpct,
           COALESCE(CAST(NULLIF(TRIM(b.bet23),'') AS DECIMAL(20,6)),0)   AS x_agpct,
          NULLIF(CAST(NULLIF(TRIM(b.bet23),'') AS DECIMAL(20,6)),0)     AS x_rate1,
          NULLIF(CAST(NULLIF(TRIM(b.bet24),'') AS DECIMAL(20,6)),0)     AS x_rate2,
          NULLIF(CAST(NULLIF(TRIM(b.bet25),'') AS DECIMAL(20,6)),0)     AS x_rate3,
          NULLIF(CAST(NULLIF(TRIM(b.bet26),'') AS DECIMAL(20,6)),0)     AS x_rate4,
          NULLIF(CAST(NULLIF(TRIM(b.bet27),'') AS DECIMAL(20,6)),0)     AS x_rate5,
          (CASE WHEN NULLIF(CAST(NULLIF(TRIM(b.bet22),'') AS BIGINT),0) IS NOT NULL THEN 5
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet21),'') AS BIGINT),0) IS NOT NULL THEN 4
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet20),'') AS BIGINT),0) IS NOT NULL THEN 3
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet19),'') AS BIGINT),0) IS NOT NULL THEN 2
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet18),'') AS BIGINT),0) IS NOT NULL THEN 1
                ELSE 0 END)                                             AS x_chain_depth,
           CASE WHEN COALESCE(t1.agent_id,t2.agent_id,t3.agent_id,
                              t4.agent_id,t5.agent_id) IS NOT NULL
                THEN 1 ELSE 0 END                                        AS f_testline
    FROM x_ranked b
    LEFT JOIN x_testagent t1 ON t1.agent_id = b.bet18
    LEFT JOIN x_testagent t2 ON t2.agent_id = b.bet19
    LEFT JOIN x_testagent t3 ON t3.agent_id = b.bet20
    LEFT JOIN x_testagent t4 ON t4.agent_id = b.bet21
    LEFT JOIN x_testagent t5 ON t5.agent_id = b.bet22
    WHERE b.x_rn = 1
      AND b.category='1' AND UPPER(TRIM(b.bet38))='N'
      AND CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8)) > 0
  ),
  x_mk AS (
    SELECT s.*,
           CASE WHEN s.f_testline = 0 THEN 1 ELSE 0 END                 AS is_clean
    FROM x_bs0 s
  ),
  x_agg AS (
    SELECT s.x_member                                                        AS x_key,
           COUNT(*) AS n_bets, COUNT(DISTINCT s.x_round) AS n_rounds,
           COUNT(DISTINCT s.x_date) AS active_days, COUNT(DISTINCT s.x_tblshoe) AS active_shoes,
           COUNT(DISTINCT CONCAT_WS('|', s.x_date, s.x_table)) AS active_sessions,
           COUNT(DISTINCT s.x_table) AS n_tables, COUNT(DISTINCT s.x_dealer) AS n_dealers,
           COUNT(DISTINCT s.x_ip) AS n_ips, COUNT(DISTINCT s.x_product) AS n_products,
           MIN(s.x_date) AS first_seen_d, MAX(s.x_date) AS last_seen_d,
           SUM(s.x_stake) AS stake, SUM(s.x_valid) AS valid, SUM(s.x_rebate) AS rebate,
           SUM(s.x_net) AS net, SUM(-s.x_net *(100.0-s.x_agpct)/100.0) AS agent_cost,
           AVG(100.0-s.x_agpct)                   AS agent_pct,
           AVG(s.x_agpct)                         AS company_retain_pct,
           SUM(-s.x_net *s.x_agpct/100.0)         AS agent_cost_a_legacy,
           SUM(s.x_valid*s.x_agpct/100.0)         AS agent_cost_valid_base_legacy,
          AVG(COALESCE(s.x_rate1,100)) AS retain_pct_lv1, AVG(COALESCE(s.x_rate2,100)) AS retain_pct_lv2,
          AVG(COALESCE(s.x_rate3,100)) AS retain_pct_lv3, AVG(COALESCE(s.x_rate4,100)) AS retain_pct_lv4,
          AVG(COALESCE(s.x_rate5,100)) AS retain_pct_lv5, AVG(s.x_chain_depth) AS chain_depth_avg,
          AVG(COALESCE(100.0-s.x_rate1,0)) AS agent_pct_lv1, AVG(COALESCE(100.0-s.x_rate2,0)) AS agent_pct_lv2,
          AVG(COALESCE(100.0-s.x_rate3,0)) AS agent_pct_lv3, AVG(COALESCE(100.0-s.x_rate4,0)) AS agent_pct_lv4,
          AVG(COALESCE(100.0-s.x_rate5,0)) AS agent_pct_lv5,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate1,0)/100.0)                        AS agent_cost_lv1,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate2,0)/100.0)                        AS agent_cost_lv2,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate3,0)/100.0)                        AS agent_cost_lv3,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate4,0)/100.0)                        AS agent_cost_lv4,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate5,0)/100.0)                        AS agent_cost_lv5,
          SUM(-s.x_net*(COALESCE(100.0-s.x_rate1,0)+COALESCE(100.0-s.x_rate2,0)
                       +COALESCE(100.0-s.x_rate3,0)+COALESCE(100.0-s.x_rate4,0)
                       +COALESCE(100.0-s.x_rate5,0))/100.0)                   AS agent_cost_chain_additive,
          SUM(-s.x_net*(1.0 - CAST(COALESCE(s.x_rate1,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate2,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate3,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate4,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate5,100) AS DOUBLE)/100.0))
                                                                       AS agent_cost_chain_nested,
           AVG(s.x_rbpct) AS rbpct, AVG(s.x_freecomm*1.0) AS freecomm_rate,
           PERCENTILE_APPROX(s.x_stake,0.25) AS p25, PERCENTILE_APPROX(s.x_stake,0.50) AS p50,
           PERCENTILE_APPROX(s.x_stake,0.75) AS p75, PERCENTILE_APPROX(s.x_stake,0.90) AS p90,
           PERCENTILE_APPROX(s.x_stake,0.95) AS p95, PERCENTILE_APPROX(s.x_stake,0.99) AS p99,
           PERCENTILE_APPROX(s.x_valid,0.50) AS p50_valid,
           PERCENTILE_APPROX(s.x_net,0.50)   AS p50_profit,
           SUM(CASE WHEN s.x_rec = 1 THEN s.x_stake ELSE 0 END) AS st_in,
           SUM(CASE WHEN s.x_rec = 1 THEN 1 ELSE 0 END)         AS nb_in,
           SUM(CASE WHEN s.x_rec = 1 THEN s.x_net ELSE 0 END)   AS net_in,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN s.x_stake ELSE 0 END) AS st_out,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN 1 ELSE 0 END)         AS nb_out,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN s.x_net ELSE 0 END)   AS net_out,
           SUM(CASE WHEN s.x_rec=1 THEN s.x_stake ELSE 0 END) AS st_rec,
           SUM(CASE WHEN s.x_rec=1 THEN 1 ELSE 0 END)         AS nb_rec
    FROM x_mk s
    WHERE s.is_clean = 1
      AND s.x_member IS NOT NULL AND TRIM(CAST(s.x_member AS STRING)) <> ''
    GROUP BY s.x_member
  ),
  x_win AS (
    SELECT            COUNT(*) AS n_bets, COUNT(DISTINCT s.x_round) AS n_rounds,
           COUNT(DISTINCT s.x_date) AS active_days, COUNT(DISTINCT s.x_tblshoe) AS active_shoes,
           COUNT(DISTINCT CONCAT_WS('|', s.x_date, s.x_table)) AS active_sessions,
           COUNT(DISTINCT s.x_table) AS n_tables, COUNT(DISTINCT s.x_dealer) AS n_dealers,
           COUNT(DISTINCT s.x_ip) AS n_ips, COUNT(DISTINCT s.x_product) AS n_products,
           MIN(s.x_date) AS first_seen_d, MAX(s.x_date) AS last_seen_d,
           SUM(s.x_stake) AS stake, SUM(s.x_valid) AS valid, SUM(s.x_rebate) AS rebate,
           SUM(s.x_net) AS net, SUM(-s.x_net *(100.0-s.x_agpct)/100.0) AS agent_cost,
           AVG(100.0-s.x_agpct)                   AS agent_pct,
           AVG(s.x_agpct)                         AS company_retain_pct,
           SUM(-s.x_net *s.x_agpct/100.0)         AS agent_cost_a_legacy,
           SUM(s.x_valid*s.x_agpct/100.0)         AS agent_cost_valid_base_legacy,
          AVG(COALESCE(s.x_rate1,100)) AS retain_pct_lv1, AVG(COALESCE(s.x_rate2,100)) AS retain_pct_lv2,
          AVG(COALESCE(s.x_rate3,100)) AS retain_pct_lv3, AVG(COALESCE(s.x_rate4,100)) AS retain_pct_lv4,
          AVG(COALESCE(s.x_rate5,100)) AS retain_pct_lv5, AVG(s.x_chain_depth) AS chain_depth_avg,
          AVG(COALESCE(100.0-s.x_rate1,0)) AS agent_pct_lv1, AVG(COALESCE(100.0-s.x_rate2,0)) AS agent_pct_lv2,
          AVG(COALESCE(100.0-s.x_rate3,0)) AS agent_pct_lv3, AVG(COALESCE(100.0-s.x_rate4,0)) AS agent_pct_lv4,
          AVG(COALESCE(100.0-s.x_rate5,0)) AS agent_pct_lv5,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate1,0)/100.0)                        AS agent_cost_lv1,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate2,0)/100.0)                        AS agent_cost_lv2,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate3,0)/100.0)                        AS agent_cost_lv3,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate4,0)/100.0)                        AS agent_cost_lv4,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate5,0)/100.0)                        AS agent_cost_lv5,
          SUM(-s.x_net*(COALESCE(100.0-s.x_rate1,0)+COALESCE(100.0-s.x_rate2,0)
                       +COALESCE(100.0-s.x_rate3,0)+COALESCE(100.0-s.x_rate4,0)
                       +COALESCE(100.0-s.x_rate5,0))/100.0)                   AS agent_cost_chain_additive,
          SUM(-s.x_net*(1.0 - CAST(COALESCE(s.x_rate1,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate2,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate3,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate4,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate5,100) AS DOUBLE)/100.0))
                                                                       AS agent_cost_chain_nested,
           AVG(s.x_rbpct) AS rbpct, AVG(s.x_freecomm*1.0) AS freecomm_rate,
           PERCENTILE_APPROX(s.x_stake,0.25) AS p25, PERCENTILE_APPROX(s.x_stake,0.50) AS p50,
           PERCENTILE_APPROX(s.x_stake,0.75) AS p75, PERCENTILE_APPROX(s.x_stake,0.90) AS p90,
           PERCENTILE_APPROX(s.x_stake,0.95) AS p95, PERCENTILE_APPROX(s.x_stake,0.99) AS p99,
           PERCENTILE_APPROX(s.x_valid,0.50) AS p50_valid,
           PERCENTILE_APPROX(s.x_net,0.50)   AS p50_profit,
           SUM(CASE WHEN s.x_rec = 1 THEN s.x_stake ELSE 0 END) AS st_in,
           SUM(CASE WHEN s.x_rec = 1 THEN 1 ELSE 0 END)         AS nb_in,
           SUM(CASE WHEN s.x_rec = 1 THEN s.x_net ELSE 0 END)   AS net_in,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN s.x_stake ELSE 0 END) AS st_out,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN 1 ELSE 0 END)         AS nb_out,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN s.x_net ELSE 0 END)   AS net_out,
           SUM(CASE WHEN s.x_rec=1 THEN s.x_stake ELSE 0 END) AS st_rec,
           SUM(CASE WHEN s.x_rec=1 THEN 1 ELSE 0 END)         AS nb_rec
    FROM x_mk s
    WHERE s.is_clean = 1
      AND s.x_member IS NOT NULL AND TRIM(CAST(s.x_member AS STRING)) <> ''
  ),
      q AS (
        SELECT  ORDINAL_POSITION, COLUMN_NAME, DATA_TYPE, COLUMN_COMMENT
        FROM    information_schema.columns
        WHERE   TABLE_SCHEMA = 'ods_mariadb_2b'
          AND   TABLE_NAME   = 'ods_a168_member'
      )
    SELECT q.*,
           -- 一·经济层
           ROUND(e.stake,4) AS stake, ROUND(e.valid,4) AS valid_bet,
           ROUND(-e.net,4) AS profit, e.n_bets, e.n_rounds,
           ROUND(e.net/NULLIF(e.stake,0),8) AS roi,
           ROUND(e.net_in/NULLIF(e.st_in,0),8) AS roi_recent,
           ROUND(e.net_out/NULLIF(e.st_out,0),8) AS roi_non_recent,
           ROUND((e.net-e.rebate)/NULLIF(e.stake,0),8) AS roi_ex_rebate,
           ROUND(e.net,4) AS roi_numerator, ROUND(e.stake,4) AS roi_denominator,
           CASE WHEN e.stake IS NULL THEN 'NULL_DENOM' WHEN e.stake<=0 THEN 'ZERO_DENOM'
                WHEN e.n_bets<30 THEN 'THIN_EXPOSURE' ELSE 'OK' END AS roi_denominator_status,
           ROUND(e.rebate,4) AS rebate_cost, ROUND(e.agent_cost,4)                           AS cost_complement_b,
       ROUND(e.agent_pct,4)                            AS pct_complement,
       ROUND(e.company_retain_pct,4)                   AS pct_top_bet23,
       'AG03-UNRESOLVED'                                     AS agent_formula_version,
      'ALL5_LEVELS_bet23_to_bet27'                    AS agent_level_scope,
      ROUND(e.agent_cost_lv1,4) AS agent_cost_lv1, ROUND(e.agent_cost_lv2,4) AS agent_cost_lv2,
      ROUND(e.agent_cost_lv3,4) AS agent_cost_lv3, ROUND(e.agent_cost_lv4,4) AS agent_cost_lv4,
      ROUND(e.agent_cost_lv5,4) AS agent_cost_lv5,
      ROUND(e.agent_pct_lv1,6) AS agent_pct_lv1, ROUND(e.agent_pct_lv2,6) AS agent_pct_lv2,
      ROUND(e.agent_pct_lv3,6) AS agent_pct_lv3, ROUND(e.agent_pct_lv4,6) AS agent_pct_lv4,
      ROUND(e.agent_pct_lv5,6) AS agent_pct_lv5,
      ROUND(e.retain_pct_lv1,6) AS retain_pct_lv1, ROUND(e.retain_pct_lv2,6) AS retain_pct_lv2,
      ROUND(e.retain_pct_lv3,6) AS retain_pct_lv3, ROUND(e.retain_pct_lv4,6) AS retain_pct_lv4,
      ROUND(e.retain_pct_lv5,6) AS retain_pct_lv5, ROUND(e.chain_depth_avg,4) AS chain_depth_avg,
      ROUND(e.agent_cost_chain_additive,4)            AS agent_cost_chain_additive,
      ROUND(e.agent_cost_chain_nested,4)              AS agent_cost_chain_nested,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_additive,4) AS residual_chain_additive,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_nested,4)   AS residual_chain_nested,
      'PENDING_AG03'                                  AS decision_status,
      'FALSE'                                         AS admit_to_risk_decision,
      'NOT_FOR_ENFORCEMENT'                           AS deliverable_class,
       ROUND(e.agent_cost_a_legacy,4)                  AS agent_cost_a_legacy,
       ROUND(e.agent_cost_valid_base_legacy,4)         AS agent_cost_valid_base_legacy,
           ROUND(-e.net-e.rebate,4)                        AS ngr,
       ROUND(-e.net-e.rebate-e.agent_cost,4)           AS residual_b,
       ROUND(-e.net-e.rebate-e.agent_cost_a_legacy,4)  AS residual_a,
           ROUND((-e.net-e.rebate)/NULLIF(e.stake,0),8)    AS ngr_rate,
       ROUND((-e.net-e.rebate-e.agent_cost)/NULLIF(e.stake,0),8)   AS residual_b_rate,
      -- 【HF9c · canonical accounting contract】
      --   以下 canonical 字段只增加明确 scope；不删除、不覆盖既有字段。
      --   formal_bet23_* 保持 HF9b 当前生产公式及其 NULL/0 语义；
      --   lv1~lv5 / additive / nested 则分别采用各自原始 e.* 成本字段，
      --   rate 一律从未舍入的 e.* 分子 / e.stake 计算，禁止由展示值反算。
      ROUND(e.agent_cost,4) AS agent_cost_bet23_formal_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost,4) AS net_margin_bet23_formal_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost)/NULLIF(e.stake,0),8) AS net_margin_bet23_formal_rate_canonical,
      ROUND(e.agent_cost_lv1,4) AS agent_cost_lv1_bet23_canonical,
      ROUND(e.agent_cost_lv2,4) AS agent_cost_lv2_bet24_canonical,
      ROUND(e.agent_cost_lv3,4) AS agent_cost_lv3_bet25_canonical,
      ROUND(e.agent_cost_lv4,4) AS agent_cost_lv4_bet26_canonical,
      ROUND(e.agent_cost_lv5,4) AS agent_cost_lv5_bet27_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_lv1,4) AS net_margin_lv1_bet23_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_lv1)/NULLIF(e.stake,0),8) AS net_margin_lv1_bet23_rate_canonical,
      ROUND(e.agent_cost_chain_additive,4) AS agent_cost_chain_additive_canonical,
      ROUND(e.agent_cost_chain_nested,4) AS agent_cost_chain_nested_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_additive,4) AS net_margin_chain_additive_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_nested,4) AS net_margin_chain_nested_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_chain_additive)/NULLIF(e.stake,0),8) AS net_margin_chain_additive_rate_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_chain_nested)/NULLIF(e.stake,0),8) AS net_margin_chain_nested_rate_canonical,
       ROUND((-e.net-e.rebate-e.agent_cost_a_legacy)/NULLIF(e.stake,0),8) AS residual_a_rate,
           -- 二·分布层
           ROUND(e.stake/NULLIF(e.n_bets,0),4) AS avg_stake_per_bet,
           ROUND(e.valid/NULLIF(e.n_rounds,0),4) AS avg_valid_bet_per_round,
           ROUND(-e.net/NULLIF(e.n_rounds,0),4) AS avg_profit_per_round,
           ROUND(-e.net/NULLIF(e.active_days,0),4) AS avg_profit_per_day,
           ROUND(-e.net/NULLIF(e.active_shoes,0),4) AS avg_profit_per_shoe,
           ROUND(e.stake/NULLIF(e.active_days,0),4) AS avg_stake_per_active_day,
           ROUND(e.n_rounds*1.0/NULLIF(e.active_days,0),4) AS avg_rounds_per_active_day,
           ROUND(e.st_in/NULLIF(e.nb_in,0),4) AS avg_stake_recent,
           ROUND(e.st_out/NULLIF(e.nb_out,0),4) AS avg_stake_non_recent,
           ROUND(e.p25,4) AS p25_stake, ROUND(e.p50,4) AS p50_stake, ROUND(e.p75,4) AS p75_stake,
           ROUND(e.p90,4) AS p90_stake, ROUND(e.p95,4) AS p95_stake, ROUND(e.p99,4) AS p99_stake,
           ROUND(e.p50_valid,4) AS p50_valid_bet, ROUND(e.p50_profit,4) AS p50_profit,
           ROUND(e.p95/NULLIF(e.p50,0),6) AS p95_over_p50,
           ROUND(e.p99/NULLIF(e.p50,0),6) AS p99_over_p50,
           ROUND((e.stake/NULLIF(e.n_bets,0))/NULLIF(e.p50,0),6) AS avg_over_p50,
           -- 三·关系层
           e.n_tables AS common_table_count, e.n_dealers AS common_dealer_count,
           e.n_ips AS common_ip_count, e.n_products AS common_product_count,
           ROUND(e.st_in/NULLIF(e.stake,0),8) AS share_recent,
           -- 四·rate 层
           ROUND(-e.net/NULLIF(e.stake,0),8) AS hold_rate,
           ROUND(-e.net_in/NULLIF(e.st_in,0),8) AS hold_rate_recent,
           ROUND(e.rebate/NULLIF(e.valid,0),8) AS rebate_rate_actual,
           ROUND(e.rbpct,6) AS rebate_pct_config,
           ROUND(e.valid/NULLIF(e.stake,0),6) AS turnover_multiple,
           ROUND(e.freecomm_rate,6) AS free_comm_rate,
           ROUND(e.net_in/NULLIF(e.st_in,0)-e.net_out/NULLIF(e.st_out,0),8) AS roi_delta_recent,
           -- 五·动态层
           e.first_seen_d AS first_seen, e.last_seen_d AS last_seen,
           e.active_days, e.active_shoes, e.active_sessions,
           DATEDIFF(e.last_seen_d, e.first_seen_d)+1 AS span_days,
           ROUND(e.active_days*1.0/NULLIF(DATEDIFF(e.last_seen_d,e.first_seen_d)+1,0),6) AS persistence,
           ROUND((e.st_in/NULLIF(e.nb_in,0))/NULLIF(e.st_out/NULLIF(e.nb_out,0),0),6) AS ramp_recent_vs_prior,
           ROUND((e.st_rec/NULLIF(e.nb_rec,0))/NULLIF(e.stake/NULLIF(e.n_bets,0),0),6) AS ramp_recent_vs_all,
           ROUND((e.st_rec/NULLIF(e.stake,0))/0.30,6) AS stake_ramp,
           -- 六·决策层（HF9g-P5 · D-14 斧正 —— 本件属【全窗基线族】，相对刻度与决策标签一律 NULL）
           --   病灶：x_win 系全窗单行聚合（无 GROUP BY，恒 1 行，此为设计使然，非缺陷），
           --         经 CROSS JOIN 接入后 e.* 全行同值；六层之 NTILE / PERCENT_RANK 施于常数即退化，
           --         PERCENT_RANK 恒 0 ⇒ action_priority 恒判 A，全件 100% 误标。
           --   ★ 斧正原则：不给 x_win 补 GROUP BY —— 那会改变其「全窗基线」语义，属退化。
           --     正解与 #018 之 G-05／G-06 同治：范围外之行不得接受任何下游评分与决策标签。
           --   ★ 本件之 e.* 仍照常供其它列作全窗基线使用，仅六层相对刻度与决策标签置 NULL。
           CAST(NULL AS INT)                                              AS vip_tier,                        -- 空值取值：全窗基线族无实体可分档，置 NULL（NULL＝不适用，非 0）
           CAST(NULL AS DOUBLE)                                           AS economic_value,                  -- 空值取值：同上，禁以常数百分位冒充经济价值
           CAST(NULL AS DOUBLE)                                           AS roi_pr_global,                   -- 空值取值：同上
           CAST(NULL AS DOUBLE)                                           AS risk_value,                      -- 空值取值：兼容列，同上
           CAST(NULL AS DOUBLE)                                           AS pr_stake,                        -- 空值取值：兼容列，同上
           CAST(NULL AS DOUBLE)                                           AS pr_global,                       -- 空值取值：同上
           CAST(NULL AS DOUBLE)                                           AS pr_qualified,                    -- 空值取值：同上
           'GLOBAL_BASELINE_NO_ENTITY_RANKING'                            AS pr_qualified_population,         -- 字面取值：血统 —— 明示本件为全窗基线族，无实体排序总体
           CAST(NULL AS BIGINT)                                           AS pr_global_population_n,          -- 空值取值：血统 —— 不适用
           CAST(NULL AS BIGINT)                                           AS pr_qualified_population_n,       -- 空值取值：血统 —— 不适用
           'NOT_APPLICABLE_GLOBAL_BASELINE'                               AS pr_calculation_method,           -- 字面取值：血统 —— 算法不适用
           'HF9g-P5'                                                      AS pr_calculation_version,          -- 字面取值：血统 —— 算法版本
           CAST(NULL AS STRING)                                           AS evidence_flag,                   -- 空值取值：证据旗标不适用于全窗基线
           CAST(NULL AS STRING)                                           AS evidence_rate,                   -- 空值取值：同上
           CAST(NULL AS DOUBLE)                                           AS hold_ci_halfwidth_approx,        -- 空值取值：同上
           'X 全窗基线 · 不参与实体赏罚'                                    AS action_priority                  -- 字面取值：★ D-14 斧正 —— 本族恒不入赏罚，取代原 100% 误标之「A」
    FROM q
    CROSS JOIN x_win e
  ) y
) z
-- ── 逐批 WHERE 阶梯（★ 口诀：上界 ＝ 下界 ＋ 100000，两数同进）──
--    本件 T_true 未测，无需先跑 T_true；以 0 / 100000 控制本批返回区间，末批由实际行数 < 100000 判定
--    WHERE z.audit_rn >        0 AND z.audit_rn <=   100000   -- 第 1 批
--    WHERE z.audit_rn >   100000 AND z.audit_rn <=   200000   -- 第 2 批
--    WHERE z.audit_rn >   200000 AND z.audit_rn <=   300000   -- 第 3 批
--    WHERE z.audit_rn >   300000 AND z.audit_rn <=   400000   -- 第 4 批
--    WHERE z.audit_rn >   400000 AND z.audit_rn <=   500000   -- 第 5 批
--    WHERE z.audit_rn >   500000 AND z.audit_rn <=   600000   -- 第 6 批
--    WHERE z.audit_rn >   600000 AND z.audit_rn <=   700000   -- 第 7 批
--    …余批类推。第 k 批：WHERE z.audit_rn > (k-1)*100000 AND z.audit_rn <= k*100000
--    某批返回 < 100000 行即为末批，其后不再取。
--
--    ⚠ 常见误写（务必避开）：只推下界而上界不动 ——
--        WHERE z.audit_rn > 100000 AND z.audit_rn <= 100000   ← 自相矛盾，恒为假，返回空集
--        WHERE z.audit_rn > 200000 AND z.audit_rn <= 100000   ← 同上，空集
--      两个数必须**同时**前进，且始终相差 100000。
--      下界 ＝ 上一批之上界；上界 ＝ 本批之上界。
WHERE z.audit_rn > 0 AND z.audit_rn <= 100000 -- ★ HF9c 本批区间
ORDER BY z.audit_rn;


-- ══════════════════════════════════════════════════════════════════════════════════════════════
--  94. TL10_treatment_ledger.csv   [总包行 8615~8675 · 原 10 列 ＋六层约 60 列]
--     典型学：M09 处置限额　派生旗标：post（s.x_rec = 1 · 仅供 CASE 条件聚合，全包无任何 WHERE/AND/HAVING 以此过滤）　连接：q.`member_id`
-- ══════════════════════════════════════════════════════════════════════════════════════════════
-- ── ① 先跑 T_true 留档（不足 100000 者一次导全，不必分批）──
-- ── ① T_true：HF9c 不再强制预跑完整 COUNT。
--    本批实际返回行数 < 100000 即判定为末批；全批完成后以各批 n_rows / audit_rn 范围核对总量。

-- ── ② 分批取数：第 1 批。第 k 批只改末行两数为 (k-1)*100000 与 k*100000 ──
--    审计字段二（REDTEAM 2026-08-24 裁定 · 四锁）：
--      audit_rn  全局观测坐标 —— 由**与原版审计版逐字同一**之排序键所生，两版可逐行对账
--      batch_id  物理分批信息 —— 该行所属批次，由 audit_rn 算得，非引擎所赋
--    ★ 锁三：二者皆为审计字段，**不得进入任何业务指标计算**。
--    ★ 锁四：两版经 audit_rn 逐行字段核验后，方可宣布输出完全一致。

-- ── ③ 每批取回后自证四数（任一不符即停手回报，禁止放行）──
--    n_rows        = COUNT(*)      须等于 COUNT(DISTINCT audit_rn)   （批内无重复）
--    audit_rn_min  = MIN(audit_rn) 须等于 (k-1)*100000 + 1           （与上批严丝合缝）
--    audit_rn_max  = MAX(audit_rn) 须等于 min + n_rows - 1           （批内无缺口）
--    全批取毕再验：各批 audit_rn 之并集 = 1 .. T_true，无缺号、无重号。
--     ★ 首行＝平台真净亏最多者（已扣退水与代理占成）。
--
SELECT z.*,
       CAST(FLOOR((z.audit_rn - 1) / 100000) + 1 AS INT)          AS batch_id,
       'A168_HF9F_20260827_0900' AS run_id,
       '2026-08-27 09:00:00' AS snapshot_sync_time
FROM (
  SELECT y.*,
         ROW_NUMBER() OVER (ORDER BY y.`residual_b` ASC, y.`roi` DESC, y.`member_id`, y.`action_date`, y.`action_time`, y.`action_class`, y.`field_name`, y.`value_before`, y.`value_after`, y.`operator_id`, y.`operator_lv`, y.`is_baccarat_member`) AS audit_rn
  FROM (
    WITH
      x_ranked AS (
    SELECT b.bet01, b.bet03, b.bet04, b.bet05, b.bet09, b.bet11, b.bet13,
           b.bet15, b.bet16, b.bet17, b.bet18, b.bet19, b.bet20, b.bet21,
           b.bet22, b.bet23, b.bet24, b.bet25, b.bet26, b.bet27, b.bet38, b.bet39, b.category, b.commission,
           b.dt, b.eid, b.ip, b.validbet, b.updatetime, b.sync_time,
           ROW_NUMBER() OVER (
             PARTITION BY b.bet01
             ORDER BY b.updatetime DESC, b.sync_time DESC, b.dt DESC)      AS x_rn
    FROM ods_mariadb_2b.ods_a168_bet02 b
    WHERE b.dt >= '2026-03-21' AND b.dt < '2026-08-07'
      AND b.bet02 = '101'
      AND b.sync_time <= '2026-08-27 09:00:00'
  ),
    x_testagent AS (
    SELECT age001 AS agent_id FROM ods_mariadb_2b.ods_a168_agent WHERE age022 = '1'
  ),
    x_bs0 AS (
    SELECT b.bet05 AS x_member, b.eid AS x_dealer, b.bet39 AS x_table,
           b.bet03 AS x_shoe, b.ip AS x_ip, b.bet09 AS x_product, b.dt AS x_date,
           CONCAT_WS('|', b.bet03, b.bet04, b.bet39)                      AS x_round,
           CONCAT_WS('|', b.bet39, b.bet03)                               AS x_tblshoe,
           CAST(NULLIF(TRIM(b.bet04),'') AS INT)                          AS x_rno,
           CASE WHEN b.dt >= '2026-07-08' THEN 1 ELSE 0 END               AS x_rec,
           CASE WHEN TRIM(b.commission)='1' THEN 1 ELSE 0 END             AS x_freecomm,
           CAST(NULLIF(TRIM(b.bet13),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_stake,
           CAST(NULLIF(TRIM(b.validbet),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_valid,
           CAST(NULLIF(TRIM(b.bet16),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_rebate,
           CAST(NULLIF(TRIM(b.bet17),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_net,
           CAST(NULLIF(TRIM(b.bet15),'') AS DECIMAL(20,6))                AS x_rbpct,
           COALESCE(CAST(NULLIF(TRIM(b.bet23),'') AS DECIMAL(20,6)),0)   AS x_agpct,
          NULLIF(CAST(NULLIF(TRIM(b.bet23),'') AS DECIMAL(20,6)),0)     AS x_rate1,
          NULLIF(CAST(NULLIF(TRIM(b.bet24),'') AS DECIMAL(20,6)),0)     AS x_rate2,
          NULLIF(CAST(NULLIF(TRIM(b.bet25),'') AS DECIMAL(20,6)),0)     AS x_rate3,
          NULLIF(CAST(NULLIF(TRIM(b.bet26),'') AS DECIMAL(20,6)),0)     AS x_rate4,
          NULLIF(CAST(NULLIF(TRIM(b.bet27),'') AS DECIMAL(20,6)),0)     AS x_rate5,
          (CASE WHEN NULLIF(CAST(NULLIF(TRIM(b.bet22),'') AS BIGINT),0) IS NOT NULL THEN 5
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet21),'') AS BIGINT),0) IS NOT NULL THEN 4
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet20),'') AS BIGINT),0) IS NOT NULL THEN 3
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet19),'') AS BIGINT),0) IS NOT NULL THEN 2
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet18),'') AS BIGINT),0) IS NOT NULL THEN 1
                ELSE 0 END)                                             AS x_chain_depth,
           CASE WHEN COALESCE(t1.agent_id,t2.agent_id,t3.agent_id,
                              t4.agent_id,t5.agent_id) IS NOT NULL
                THEN 1 ELSE 0 END                                        AS f_testline
    FROM x_ranked b
    LEFT JOIN x_testagent t1 ON t1.agent_id = b.bet18
    LEFT JOIN x_testagent t2 ON t2.agent_id = b.bet19
    LEFT JOIN x_testagent t3 ON t3.agent_id = b.bet20
    LEFT JOIN x_testagent t4 ON t4.agent_id = b.bet21
    LEFT JOIN x_testagent t5 ON t5.agent_id = b.bet22
    WHERE b.x_rn = 1
      AND b.category='1' AND UPPER(TRIM(b.bet38))='N'
      AND CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8)) > 0
  ),
  x_mk AS (
    SELECT s.*,
           CASE WHEN s.f_testline = 0 THEN 1 ELSE 0 END                 AS is_clean
    FROM x_bs0 s
  ),
  x_agg AS (
    SELECT s.x_member                                                        AS x_key,
           COUNT(*) AS n_bets, COUNT(DISTINCT s.x_round) AS n_rounds,
           COUNT(DISTINCT s.x_date) AS active_days, COUNT(DISTINCT s.x_tblshoe) AS active_shoes,
           COUNT(DISTINCT CONCAT_WS('|', s.x_date, s.x_table)) AS active_sessions,
           COUNT(DISTINCT s.x_table) AS n_tables, COUNT(DISTINCT s.x_dealer) AS n_dealers,
           COUNT(DISTINCT s.x_ip) AS n_ips, COUNT(DISTINCT s.x_product) AS n_products,
           MIN(s.x_date) AS first_seen_d, MAX(s.x_date) AS last_seen_d,
           SUM(s.x_stake) AS stake, SUM(s.x_valid) AS valid, SUM(s.x_rebate) AS rebate,
           SUM(s.x_net) AS net, SUM(-s.x_net *(100.0-s.x_agpct)/100.0) AS agent_cost,
           AVG(100.0-s.x_agpct)                   AS agent_pct,
           AVG(s.x_agpct)                         AS company_retain_pct,
           SUM(-s.x_net *s.x_agpct/100.0)         AS agent_cost_a_legacy,
           SUM(s.x_valid*s.x_agpct/100.0)         AS agent_cost_valid_base_legacy,
          AVG(COALESCE(s.x_rate1,100)) AS retain_pct_lv1, AVG(COALESCE(s.x_rate2,100)) AS retain_pct_lv2,
          AVG(COALESCE(s.x_rate3,100)) AS retain_pct_lv3, AVG(COALESCE(s.x_rate4,100)) AS retain_pct_lv4,
          AVG(COALESCE(s.x_rate5,100)) AS retain_pct_lv5, AVG(s.x_chain_depth) AS chain_depth_avg,
          AVG(COALESCE(100.0-s.x_rate1,0)) AS agent_pct_lv1, AVG(COALESCE(100.0-s.x_rate2,0)) AS agent_pct_lv2,
          AVG(COALESCE(100.0-s.x_rate3,0)) AS agent_pct_lv3, AVG(COALESCE(100.0-s.x_rate4,0)) AS agent_pct_lv4,
          AVG(COALESCE(100.0-s.x_rate5,0)) AS agent_pct_lv5,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate1,0)/100.0)                        AS agent_cost_lv1,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate2,0)/100.0)                        AS agent_cost_lv2,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate3,0)/100.0)                        AS agent_cost_lv3,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate4,0)/100.0)                        AS agent_cost_lv4,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate5,0)/100.0)                        AS agent_cost_lv5,
          SUM(-s.x_net*(COALESCE(100.0-s.x_rate1,0)+COALESCE(100.0-s.x_rate2,0)
                       +COALESCE(100.0-s.x_rate3,0)+COALESCE(100.0-s.x_rate4,0)
                       +COALESCE(100.0-s.x_rate5,0))/100.0)                   AS agent_cost_chain_additive,
          SUM(-s.x_net*(1.0 - CAST(COALESCE(s.x_rate1,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate2,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate3,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate4,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate5,100) AS DOUBLE)/100.0))
                                                                       AS agent_cost_chain_nested,
           AVG(s.x_rbpct) AS rbpct, AVG(s.x_freecomm*1.0) AS freecomm_rate,
           PERCENTILE_APPROX(s.x_stake,0.25) AS p25, PERCENTILE_APPROX(s.x_stake,0.50) AS p50,
           PERCENTILE_APPROX(s.x_stake,0.75) AS p75, PERCENTILE_APPROX(s.x_stake,0.90) AS p90,
           PERCENTILE_APPROX(s.x_stake,0.95) AS p95, PERCENTILE_APPROX(s.x_stake,0.99) AS p99,
           PERCENTILE_APPROX(s.x_valid,0.50) AS p50_valid,
           PERCENTILE_APPROX(s.x_net,0.50)   AS p50_profit,
           SUM(CASE WHEN s.x_rec = 1 THEN s.x_stake ELSE 0 END) AS st_in,
           SUM(CASE WHEN s.x_rec = 1 THEN 1 ELSE 0 END)         AS nb_in,
           SUM(CASE WHEN s.x_rec = 1 THEN s.x_net ELSE 0 END)   AS net_in,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN s.x_stake ELSE 0 END) AS st_out,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN 1 ELSE 0 END)         AS nb_out,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN s.x_net ELSE 0 END)   AS net_out,
           SUM(CASE WHEN s.x_rec=1 THEN s.x_stake ELSE 0 END) AS st_rec,
           SUM(CASE WHEN s.x_rec=1 THEN 1 ELSE 0 END)         AS nb_rec
    FROM x_mk s
    WHERE s.is_clean = 1
      AND s.x_member IS NOT NULL AND TRIM(CAST(s.x_member AS STRING)) <> ''
    GROUP BY s.x_member
  ),
      q AS (
        WITH ev AS (
            SELECT  CAST(lmc02 AS STRING)                         AS member_id,
                    CAST(lmc04 AS STRING)                         AS action_class,
                    SUBSTR(CAST(lmc08 AS STRING), 1, 10)          AS action_date,
                    CAST(lmc08 AS STRING)                         AS action_time,
                    CAST(lmc06 AS STRING)                         AS operator_id,
                    CAST(lmc07 AS STRING)                         AS operator_lv,
                    CAST(lmc05 AS STRING)                         AS content
            FROM    ods_mariadb_2b.ods_a168_log_mem_change
            WHERE   dt >= '2026-03-21'
              AND   dt <  '2026-08-07'
              AND   CAST(lmc04 AS STRING) IN ('edit', 'changestatus')
        ),
        seg AS (
            SELECT  e.member_id, e.action_class, e.action_date, e.action_time,
                    e.operator_id, e.operator_lv,
                    TRIM(s.piece)                                 AS piece
            FROM    ev e, unnest(split(e.content, ';')) AS s(piece)
        ),
        parsed AS (
            SELECT  member_id, action_class, action_date, action_time,
                    operator_id, operator_lv, piece,
                    TRIM(SPLIT_PART(piece, ':', 1))               AS field_name,
                    TRIM(SPLIT_PART(SPLIT_PART(piece, ':', 2), '=>', 1)) AS value_before,
                    TRIM(SPLIT_PART(SPLIT_PART(piece, ':', 2), '=>', 2)) AS value_after
            FROM    seg
            WHERE   piece LIKE '%=>%'
              AND   piece LIKE '%:%'
        ),
        guarded AS (
            -- 护栏：另有一类 edit 内容形如「skyname=>…, Gateway_url=>https://…」，
            -- 其 URL 里的冒号会骗过上面的两个 LIKE，解析出一整串垃圾作列名。
            -- 故加数道限制——列名须短、须无空格、须不含箭头与斜杠；实测所见列名皆形如 memNNN 或 tip。
            SELECT  *
            FROM    parsed
            WHERE   LENGTH(field_name) BETWEEN 2 AND 12
              AND   field_name NOT LIKE '% %'
              AND   field_name NOT LIKE '%=>%'
              AND   field_name NOT LIKE '%/%'
              AND   value_after NOT LIKE '%//%'
        ),
        bl AS (
            SELECT  DISTINCT CAST(bet05 AS STRING)                AS member_id
            FROM    ods_mariadb_2b.ods_a168_bet02
            WHERE   dt >= '2026-03-21'
              AND sync_time <= '2026-08-27 09:00:00'
              AND   dt <  '2026-08-07'
              AND   CAST(bet02 AS STRING) = '101'
        )
        SELECT  p.member_id,
                p.action_date,
                p.action_time,
                p.action_class,
                p.field_name,
                p.value_before,
                p.value_after,
                p.operator_id,
                p.operator_lv,
                CASE WHEN bl.member_id IS NULL THEN 0 ELSE 1 END  AS is_baccarat_member
        FROM        guarded p
        LEFT JOIN   bl ON bl.member_id = p.member_id
      )
    SELECT q.*,
           -- 一·经济层
           ROUND(e.stake,4) AS stake, ROUND(e.valid,4) AS valid_bet,
           ROUND(-e.net,4) AS profit, e.n_bets, e.n_rounds,
           ROUND(e.net/NULLIF(e.stake,0),8) AS roi,
           ROUND(e.net_in/NULLIF(e.st_in,0),8) AS roi_post,
           ROUND(e.net_out/NULLIF(e.st_out,0),8) AS roi_non_post,
           ROUND((e.net-e.rebate)/NULLIF(e.stake,0),8) AS roi_ex_rebate,
           ROUND(e.net,4) AS roi_numerator, ROUND(e.stake,4) AS roi_denominator,
           CASE WHEN e.stake IS NULL THEN 'NULL_DENOM' WHEN e.stake<=0 THEN 'ZERO_DENOM'
                WHEN e.n_bets<30 THEN 'THIN_EXPOSURE' ELSE 'OK' END AS roi_denominator_status,
           ROUND(e.rebate,4) AS rebate_cost, ROUND(e.agent_cost,4)                           AS cost_complement_b,
       ROUND(e.agent_pct,4)                            AS pct_complement,
       ROUND(e.company_retain_pct,4)                   AS pct_top_bet23,
       'AG03-UNRESOLVED'                                     AS agent_formula_version,
      'ALL5_LEVELS_bet23_to_bet27'                    AS agent_level_scope,
      ROUND(e.agent_cost_lv1,4) AS agent_cost_lv1, ROUND(e.agent_cost_lv2,4) AS agent_cost_lv2,
      ROUND(e.agent_cost_lv3,4) AS agent_cost_lv3, ROUND(e.agent_cost_lv4,4) AS agent_cost_lv4,
      ROUND(e.agent_cost_lv5,4) AS agent_cost_lv5,
      ROUND(e.agent_pct_lv1,6) AS agent_pct_lv1, ROUND(e.agent_pct_lv2,6) AS agent_pct_lv2,
      ROUND(e.agent_pct_lv3,6) AS agent_pct_lv3, ROUND(e.agent_pct_lv4,6) AS agent_pct_lv4,
      ROUND(e.agent_pct_lv5,6) AS agent_pct_lv5,
      ROUND(e.retain_pct_lv1,6) AS retain_pct_lv1, ROUND(e.retain_pct_lv2,6) AS retain_pct_lv2,
      ROUND(e.retain_pct_lv3,6) AS retain_pct_lv3, ROUND(e.retain_pct_lv4,6) AS retain_pct_lv4,
      ROUND(e.retain_pct_lv5,6) AS retain_pct_lv5, ROUND(e.chain_depth_avg,4) AS chain_depth_avg,
      ROUND(e.agent_cost_chain_additive,4)            AS agent_cost_chain_additive,
      ROUND(e.agent_cost_chain_nested,4)              AS agent_cost_chain_nested,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_additive,4) AS residual_chain_additive,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_nested,4)   AS residual_chain_nested,
      'PENDING_AG03'                                  AS decision_status,
      'FALSE'                                         AS admit_to_risk_decision,
      'NOT_FOR_ENFORCEMENT'                           AS deliverable_class,
       ROUND(e.agent_cost_a_legacy,4)                  AS agent_cost_a_legacy,
       ROUND(e.agent_cost_valid_base_legacy,4)         AS agent_cost_valid_base_legacy,
           ROUND(-e.net-e.rebate,4)                        AS ngr,
       ROUND(-e.net-e.rebate-e.agent_cost,4)           AS residual_b,
       ROUND(-e.net-e.rebate-e.agent_cost_a_legacy,4)  AS residual_a,
           ROUND((-e.net-e.rebate)/NULLIF(e.stake,0),8)    AS ngr_rate,
       ROUND((-e.net-e.rebate-e.agent_cost)/NULLIF(e.stake,0),8)   AS residual_b_rate,
      -- 【HF9c · canonical accounting contract】
      --   以下 canonical 字段只增加明确 scope；不删除、不覆盖既有字段。
      --   formal_bet23_* 保持 HF9b 当前生产公式及其 NULL/0 语义；
      --   lv1~lv5 / additive / nested 则分别采用各自原始 e.* 成本字段，
      --   rate 一律从未舍入的 e.* 分子 / e.stake 计算，禁止由展示值反算。
      ROUND(e.agent_cost,4) AS agent_cost_bet23_formal_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost,4) AS net_margin_bet23_formal_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost)/NULLIF(e.stake,0),8) AS net_margin_bet23_formal_rate_canonical,
      ROUND(e.agent_cost_lv1,4) AS agent_cost_lv1_bet23_canonical,
      ROUND(e.agent_cost_lv2,4) AS agent_cost_lv2_bet24_canonical,
      ROUND(e.agent_cost_lv3,4) AS agent_cost_lv3_bet25_canonical,
      ROUND(e.agent_cost_lv4,4) AS agent_cost_lv4_bet26_canonical,
      ROUND(e.agent_cost_lv5,4) AS agent_cost_lv5_bet27_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_lv1,4) AS net_margin_lv1_bet23_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_lv1)/NULLIF(e.stake,0),8) AS net_margin_lv1_bet23_rate_canonical,
      ROUND(e.agent_cost_chain_additive,4) AS agent_cost_chain_additive_canonical,
      ROUND(e.agent_cost_chain_nested,4) AS agent_cost_chain_nested_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_additive,4) AS net_margin_chain_additive_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_nested,4) AS net_margin_chain_nested_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_chain_additive)/NULLIF(e.stake,0),8) AS net_margin_chain_additive_rate_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_chain_nested)/NULLIF(e.stake,0),8) AS net_margin_chain_nested_rate_canonical,
       ROUND((-e.net-e.rebate-e.agent_cost_a_legacy)/NULLIF(e.stake,0),8) AS residual_a_rate,
           -- 二·分布层
           ROUND(e.stake/NULLIF(e.n_bets,0),4) AS avg_stake_per_bet,
           ROUND(e.valid/NULLIF(e.n_rounds,0),4) AS avg_valid_bet_per_round,
           ROUND(-e.net/NULLIF(e.n_rounds,0),4) AS avg_profit_per_round,
           ROUND(-e.net/NULLIF(e.active_days,0),4) AS avg_profit_per_day,
           ROUND(-e.net/NULLIF(e.active_shoes,0),4) AS avg_profit_per_shoe,
           ROUND(e.stake/NULLIF(e.active_days,0),4) AS avg_stake_per_active_day,
           ROUND(e.n_rounds*1.0/NULLIF(e.active_days,0),4) AS avg_rounds_per_active_day,
           ROUND(e.st_in/NULLIF(e.nb_in,0),4) AS avg_stake_post,
           ROUND(e.st_out/NULLIF(e.nb_out,0),4) AS avg_stake_non_post,
           ROUND(e.p25,4) AS p25_stake, ROUND(e.p50,4) AS p50_stake, ROUND(e.p75,4) AS p75_stake,
           ROUND(e.p90,4) AS p90_stake, ROUND(e.p95,4) AS p95_stake, ROUND(e.p99,4) AS p99_stake,
           ROUND(e.p50_valid,4) AS p50_valid_bet, ROUND(e.p50_profit,4) AS p50_profit,
           ROUND(e.p95/NULLIF(e.p50,0),6) AS p95_over_p50,
           ROUND(e.p99/NULLIF(e.p50,0),6) AS p99_over_p50,
           ROUND((e.stake/NULLIF(e.n_bets,0))/NULLIF(e.p50,0),6) AS avg_over_p50,
           -- 三·关系层
           e.n_tables AS common_table_count, e.n_dealers AS common_dealer_count,
           e.n_ips AS common_ip_count, e.n_products AS common_product_count,
           ROUND(e.st_in/NULLIF(e.stake,0),8) AS share_post,
           -- 四·rate 层
           ROUND(-e.net/NULLIF(e.stake,0),8) AS hold_rate,
           ROUND(-e.net_in/NULLIF(e.st_in,0),8) AS hold_rate_post,
           ROUND(e.rebate/NULLIF(e.valid,0),8) AS rebate_rate_actual,
           ROUND(e.rbpct,6) AS rebate_pct_config,
           ROUND(e.valid/NULLIF(e.stake,0),6) AS turnover_multiple,
           ROUND(e.freecomm_rate,6) AS free_comm_rate,
           ROUND(e.net_in/NULLIF(e.st_in,0)-e.net_out/NULLIF(e.st_out,0),8) AS roi_delta_post,
           -- 五·动态层
           e.first_seen_d AS first_seen, e.last_seen_d AS last_seen,
           e.active_days, e.active_shoes, e.active_sessions,
           DATEDIFF(e.last_seen_d, e.first_seen_d)+1 AS span_days,
           ROUND(e.active_days*1.0/NULLIF(DATEDIFF(e.last_seen_d,e.first_seen_d)+1,0),6) AS persistence,
           ROUND((e.st_in/NULLIF(e.nb_in,0))/NULLIF(e.st_out/NULLIF(e.nb_out,0),0),6) AS ramp_post,
           ROUND((e.st_rec/NULLIF(e.nb_rec,0))/NULLIF(e.stake/NULLIF(e.n_bets,0),0),6) AS ramp_recent,
           ROUND((e.st_rec/NULLIF(e.stake,0))/0.30,6) AS stake_ramp,
           -- 六·决策层（HF9f · 详见档头【HF9f 变更说明】；本段两版逐字同一）
           NTILE(5) OVER (ORDER BY e.stake) AS vip_tier,                                                        -- 窗口取值：相对刻度 B 族，全体五等分；须连同下方血统五元组一并解读，禁作硬阈值判型
           PERCENT_RANK() OVER (ORDER BY -e.net-e.rebate-e.agent_cost)    AS economic_value,                    -- 窗口取值：HF9f·F-19 修正 —— HF9e 写作 -(-…) 双负号致方向颠倒（#075 实测 corr(economic_value, residual_b) = -1.0000）；今与 action_priority 排序键归一，值大即平台真净利高
           PERCENT_RANK() OVER (ORDER BY e.net/NULLIF(e.stake,0))         AS roi_pr_global,                     -- 窗口取值：HF9f·F-17 正名 —— 本列实为 ROI（玩家净回报率）之全体百分位，与「风险」无关；旧名 risk_value 见下一行
           PERCENT_RANK() OVER (ORDER BY e.net/NULLIF(e.stake,0))         AS risk_value,                        -- 窗口取值：兼容列，恒等于 roi_pr_global，仅为下游迁移窗保留；HF9g 起废弃，禁新引用
           PERCENT_RANK() OVER (ORDER BY e.stake)                         AS pr_stake,                          -- 窗口取值：兼容列，恒等于 pr_global，原名保留以免断链
           PERCENT_RANK() OVER (ORDER BY e.stake)                         AS pr_global,                         -- 窗口取值：HF9f·F-1 双轨之一 —— 全体口径百分位，参照总体即本件全部输出行
           CASE WHEN e.n_rounds >= 30                                                                           -- 条件分支：起始分支 —— 仅在合格子集内计算合格口径百分位
                  THEN PERCENT_RANK() OVER (PARTITION BY CASE WHEN e.n_rounds >= 30 THEN 1 ELSE 0 END ORDER BY e.stake)  -- 分支取值：以合格与否分区，故本值即 n_rounds>=30 子集内之百分位
                ELSE NULL END                                             AS pr_qualified,                      -- 条件分支：收束上方分支 —— 不合格者留 NULL（NULL＝未测，非 0），产出「pr_qualified」
           'n_rounds>=30'                                                 AS pr_qualified_population,           -- 字面取值：血统 —— 合格子集之定义
           COUNT(*) OVER ()                                               AS pr_global_population_n,            -- 窗口取值：血统 —— 全体口径之参照总体规模，渲染时现算，禁写死
           SUM(CASE WHEN e.n_rounds >= 30 THEN 1 ELSE 0 END) OVER ()      AS pr_qualified_population_n,         -- 窗口取值：血统 —— 合格子集之参照总体规模，现算，禁写死
           'PERCENT_RANK_OVER_ORDER_BY_e_stake'                           AS pr_calculation_method,             -- 字面取值：血统 —— 算法标识
           'HF9f'                                                         AS pr_calculation_version,            -- 字面取值：血统 —— 算法版本
           CASE WHEN e.n_rounds IS NULL OR e.n_rounds < 30 THEN 'THIN_ROUNDS' ELSE 'OK' END AS evidence_flag,   -- 条件分支：HF9f·F-2a 证据旗标 —— THIN_ROUNDS 者禁入执行队列，仅入观察队列
           CASE WHEN e.n_rounds IS NULL       THEN NULL                                                         -- 条件分支：起始分支 —— 未测者留 NULL（自家铁律：NULL ≠ 0）
                WHEN e.n_rounds >= 31483      THEN 'L1_POWERED'                                                 -- 分支判定：MDE 反解第一档
                WHEN e.n_rounds >= 15409      THEN 'L2_CI_1P5'                                                  -- 分支判定：MDE 反解第二档
                WHEN e.n_rounds >=  8668      THEN 'L3_CI_2P0'                                                  -- 分支判定：MDE 反解第三档
                WHEN e.n_rounds >=  3852      THEN 'L4_CI_3P0'                                                  -- 分支判定：MDE 反解第四档
                ELSE 'L5_INSUFFICIENT' END                                AS evidence_rate,                     -- 条件分支：收束上方 —— HF9f·F-3 证据分档，承 HF9e 前议之 MDE 反解五档，须于 F-4 敏感性实验后复核
           ROUND(1.96 * 0.95 / SQRT(NULLIF(CAST(e.n_rounds AS DOUBLE),0)),8) AS hold_ci_halfwidth_approx,       -- 比率表达式：HF9f·F-3 逐行现算之 95% 半宽近似；常数 0.95 为登记值，本轮 #075 实测每局 ROI 隐含 σ 于最薄层为 0.9249，二者差异待 F-4 裁定
           CASE WHEN e.stake IS NULL OR e.stake<=0 OR e.n_bets<30 OR e.n_rounds IS NULL OR e.n_rounds<30 THEN 'Z 证据不足 · 不动作'  -- 条件分支：HF9f·F-2 双条件取严 —— HF9e 仅卡 e.n_bets<30，致 n_bets>=30 而 n_rounds<30 者绕过 Z（#075 实测 18,537 名，其中 8,145 名已入 A/D 待裁）；今两条件并列取严
                WHEN PERCENT_RANK() OVER (ORDER BY -e.net-e.rebate-e.agent_cost)<=0.10                          -- 分支判定：平台真净利之最低十分位
                  THEN 'A 净亏最大十分位 · 优先复核'                                                             -- 分支取值：HF9f·F-20 正名 —— 本档 Σresidual_b 于 #075 实测 = -100,236,896，系平台净亏最大群，旧名「残值最低十分位 · 待裁」名实不符
                WHEN PERCENT_RANK() OVER (ORDER BY -e.net-e.rebate-e.agent_cost)>=0.80                          -- 分支判定：平台真净利之最高二十分位
                  THEN 'D 净利最高二十分位 · 优先留存'                                                           -- 分支取值：HF9f·F-20 正名 —— 本档 Σresidual_b 于 #075 实测 = +281,733,190，系核心利润源；与 A 档方向相反，旧版同标「待裁」属名实不符
                ELSE 'E 常规' END                                          AS action_priority                   -- 条件分支：收束上方判词，产出「action_priority」
    FROM q
    LEFT JOIN x_agg e ON CAST(e.x_key AS STRING) = CAST(q.`member_id` AS STRING)
  ) y
) z
-- ── 逐批 WHERE 阶梯（★ 口诀：上界 ＝ 下界 ＋ 100000，两数同进）──
--    本件 T_true 未测，无需先跑 T_true；以 0 / 100000 控制本批返回区间，末批由实际行数 < 100000 判定
--    WHERE z.audit_rn >        0 AND z.audit_rn <=   100000   -- 第 1 批
--    WHERE z.audit_rn >   100000 AND z.audit_rn <=   200000   -- 第 2 批
--    WHERE z.audit_rn >   200000 AND z.audit_rn <=   300000   -- 第 3 批
--    WHERE z.audit_rn >   300000 AND z.audit_rn <=   400000   -- 第 4 批
--    WHERE z.audit_rn >   400000 AND z.audit_rn <=   500000   -- 第 5 批
--    WHERE z.audit_rn >   500000 AND z.audit_rn <=   600000   -- 第 6 批
--    WHERE z.audit_rn >   600000 AND z.audit_rn <=   700000   -- 第 7 批
--    …余批类推。第 k 批：WHERE z.audit_rn > (k-1)*100000 AND z.audit_rn <= k*100000
--    某批返回 < 100000 行即为末批，其后不再取。
--
--    ⚠ 常见误写（务必避开）：只推下界而上界不动 ——
--        WHERE z.audit_rn > 100000 AND z.audit_rn <= 100000   ← 自相矛盾，恒为假，返回空集
--        WHERE z.audit_rn > 200000 AND z.audit_rn <= 100000   ← 同上，空集
--      两个数必须**同时**前进，且始终相差 100000。
--      下界 ＝ 上一批之上界；上界 ＝ 本批之上界。
WHERE z.audit_rn > 0 AND z.audit_rn <= 100000 -- ★ HF9c 本批区间
ORDER BY z.audit_rn;


-- ══════════════════════════════════════════════════════════════════════════════════════════════
--  95. TL11_treatment_episode.csv   [总包行 8706~8832 · 原 24 列 ＋六层约 60 列]
--     典型学：M09 处置限额　派生旗标：post（s.x_rec = 1 · 仅供 CASE 条件聚合，全包无任何 WHERE/AND/HAVING 以此过滤）　连接：q.`member_id`
-- ══════════════════════════════════════════════════════════════════════════════════════════════
-- ── ① 先跑 T_true 留档（不足 100000 者一次导全，不必分批）──
-- ── ① T_true：HF9c 不再强制预跑完整 COUNT。
--    本批实际返回行数 < 100000 即判定为末批；全批完成后以各批 n_rows / audit_rn 范围核对总量。

-- ── ② 分批取数：第 1 批。第 k 批只改末行两数为 (k-1)*100000 与 k*100000 ──
--    审计字段二（REDTEAM 2026-08-24 裁定 · 四锁）：
--      audit_rn  全局观测坐标 —— 由**与原版审计版逐字同一**之排序键所生，两版可逐行对账
--      batch_id  物理分批信息 —— 该行所属批次，由 audit_rn 算得，非引擎所赋
--    ★ 锁三：二者皆为审计字段，**不得进入任何业务指标计算**。
--    ★ 锁四：两版经 audit_rn 逐行字段核验后，方可宣布输出完全一致。

-- ── ③ 每批取回后自证四数（任一不符即停手回报，禁止放行）──
--    n_rows        = COUNT(*)      须等于 COUNT(DISTINCT audit_rn)   （批内无重复）
--    audit_rn_min  = MIN(audit_rn) 须等于 (k-1)*100000 + 1           （与上批严丝合缝）
--    audit_rn_max  = MAX(audit_rn) 须等于 min + n_rows - 1           （批内无缺口）
--    全批取毕再验：各批 audit_rn 之并集 = 1 .. T_true，无缺号、无重号。
--     ★ 首行＝平台真净亏最多者（已扣退水与代理占成）。
--
SELECT z.*,
       CAST(FLOOR((z.audit_rn - 1) / 100000) + 1 AS INT)          AS batch_id,
       'A168_HF9F_20260827_0900' AS run_id,
       '2026-08-27 09:00:00' AS snapshot_sync_time
FROM (
  SELECT y.*,
         ROW_NUMBER() OVER (ORDER BY y.`residual_b` ASC, y.`roi` DESC, y.`member_id`, y.`field_name`, y.`business_field`, y.`enforcement_type`, y.`is_baccarat_member`, y.`episode_id`, y.`start_date`, y.`start_time`, y.`value_before`, y.`value_after`, y.`start_operator`, y.`start_operator_lv`, y.`parse_sep`, y.`parse_status`, y.`release_date`, y.`censored`, y.`last_bet_date`, y.`n_bets_in_window`, y.`last_config_time`, y.`days_since_last_bet`, y.`censor_cutoff_days`, y.`censor_reason`, y.`duration_days`, y.`episode_seq`) AS audit_rn
  FROM (
    WITH
      x_ranked AS (
    SELECT b.bet01, b.bet03, b.bet04, b.bet05, b.bet09, b.bet11, b.bet13,
           b.bet15, b.bet16, b.bet17, b.bet18, b.bet19, b.bet20, b.bet21,
           b.bet22, b.bet23, b.bet24, b.bet25, b.bet26, b.bet27, b.bet38, b.bet39, b.category, b.commission,
           b.dt, b.eid, b.ip, b.validbet, b.updatetime, b.sync_time,
           ROW_NUMBER() OVER (
             PARTITION BY b.bet01
             ORDER BY b.updatetime DESC, b.sync_time DESC, b.dt DESC)      AS x_rn
    FROM ods_mariadb_2b.ods_a168_bet02 b
    WHERE b.dt >= '2026-03-21' AND b.dt < '2026-08-07'
      AND b.bet02 = '101'
      AND b.sync_time <= '2026-08-27 09:00:00'
  ),
    x_testagent AS (
    SELECT age001 AS agent_id FROM ods_mariadb_2b.ods_a168_agent WHERE age022 = '1'
  ),
    x_bs0 AS (
    SELECT b.bet05 AS x_member, b.eid AS x_dealer, b.bet39 AS x_table,
           b.bet03 AS x_shoe, b.ip AS x_ip, b.bet09 AS x_product, b.dt AS x_date,
           CONCAT_WS('|', b.bet03, b.bet04, b.bet39)                      AS x_round,
           CONCAT_WS('|', b.bet39, b.bet03)                               AS x_tblshoe,
           CAST(NULLIF(TRIM(b.bet04),'') AS INT)                          AS x_rno,
           CASE WHEN b.dt >= '2026-07-08' THEN 1 ELSE 0 END               AS x_rec,
           CASE WHEN TRIM(b.commission)='1' THEN 1 ELSE 0 END             AS x_freecomm,
           CAST(NULLIF(TRIM(b.bet13),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_stake,
           CAST(NULLIF(TRIM(b.validbet),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_valid,
           CAST(NULLIF(TRIM(b.bet16),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_rebate,
           CAST(NULLIF(TRIM(b.bet17),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_net,
           CAST(NULLIF(TRIM(b.bet15),'') AS DECIMAL(20,6))                AS x_rbpct,
           COALESCE(CAST(NULLIF(TRIM(b.bet23),'') AS DECIMAL(20,6)),0)   AS x_agpct,
          NULLIF(CAST(NULLIF(TRIM(b.bet23),'') AS DECIMAL(20,6)),0)     AS x_rate1,
          NULLIF(CAST(NULLIF(TRIM(b.bet24),'') AS DECIMAL(20,6)),0)     AS x_rate2,
          NULLIF(CAST(NULLIF(TRIM(b.bet25),'') AS DECIMAL(20,6)),0)     AS x_rate3,
          NULLIF(CAST(NULLIF(TRIM(b.bet26),'') AS DECIMAL(20,6)),0)     AS x_rate4,
          NULLIF(CAST(NULLIF(TRIM(b.bet27),'') AS DECIMAL(20,6)),0)     AS x_rate5,
          (CASE WHEN NULLIF(CAST(NULLIF(TRIM(b.bet22),'') AS BIGINT),0) IS NOT NULL THEN 5
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet21),'') AS BIGINT),0) IS NOT NULL THEN 4
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet20),'') AS BIGINT),0) IS NOT NULL THEN 3
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet19),'') AS BIGINT),0) IS NOT NULL THEN 2
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet18),'') AS BIGINT),0) IS NOT NULL THEN 1
                ELSE 0 END)                                             AS x_chain_depth,
           CASE WHEN COALESCE(t1.agent_id,t2.agent_id,t3.agent_id,
                              t4.agent_id,t5.agent_id) IS NOT NULL
                THEN 1 ELSE 0 END                                        AS f_testline
    FROM x_ranked b
    LEFT JOIN x_testagent t1 ON t1.agent_id = b.bet18
    LEFT JOIN x_testagent t2 ON t2.agent_id = b.bet19
    LEFT JOIN x_testagent t3 ON t3.agent_id = b.bet20
    LEFT JOIN x_testagent t4 ON t4.agent_id = b.bet21
    LEFT JOIN x_testagent t5 ON t5.agent_id = b.bet22
    WHERE b.x_rn = 1
      AND b.category='1' AND UPPER(TRIM(b.bet38))='N'
      AND CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8)) > 0
  ),
  x_mk AS (
    SELECT s.*,
           CASE WHEN s.f_testline = 0 THEN 1 ELSE 0 END                 AS is_clean
    FROM x_bs0 s
  ),
  x_agg AS (
    SELECT s.x_member                                                        AS x_key,
           COUNT(*) AS n_bets, COUNT(DISTINCT s.x_round) AS n_rounds,
           COUNT(DISTINCT s.x_date) AS active_days, COUNT(DISTINCT s.x_tblshoe) AS active_shoes,
           COUNT(DISTINCT CONCAT_WS('|', s.x_date, s.x_table)) AS active_sessions,
           COUNT(DISTINCT s.x_table) AS n_tables, COUNT(DISTINCT s.x_dealer) AS n_dealers,
           COUNT(DISTINCT s.x_ip) AS n_ips, COUNT(DISTINCT s.x_product) AS n_products,
           MIN(s.x_date) AS first_seen_d, MAX(s.x_date) AS last_seen_d,
           SUM(s.x_stake) AS stake, SUM(s.x_valid) AS valid, SUM(s.x_rebate) AS rebate,
           SUM(s.x_net) AS net, SUM(-s.x_net *(100.0-s.x_agpct)/100.0) AS agent_cost,
           AVG(100.0-s.x_agpct)                   AS agent_pct,
           AVG(s.x_agpct)                         AS company_retain_pct,
           SUM(-s.x_net *s.x_agpct/100.0)         AS agent_cost_a_legacy,
           SUM(s.x_valid*s.x_agpct/100.0)         AS agent_cost_valid_base_legacy,
          AVG(COALESCE(s.x_rate1,100)) AS retain_pct_lv1, AVG(COALESCE(s.x_rate2,100)) AS retain_pct_lv2,
          AVG(COALESCE(s.x_rate3,100)) AS retain_pct_lv3, AVG(COALESCE(s.x_rate4,100)) AS retain_pct_lv4,
          AVG(COALESCE(s.x_rate5,100)) AS retain_pct_lv5, AVG(s.x_chain_depth) AS chain_depth_avg,
          AVG(COALESCE(100.0-s.x_rate1,0)) AS agent_pct_lv1, AVG(COALESCE(100.0-s.x_rate2,0)) AS agent_pct_lv2,
          AVG(COALESCE(100.0-s.x_rate3,0)) AS agent_pct_lv3, AVG(COALESCE(100.0-s.x_rate4,0)) AS agent_pct_lv4,
          AVG(COALESCE(100.0-s.x_rate5,0)) AS agent_pct_lv5,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate1,0)/100.0)                        AS agent_cost_lv1,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate2,0)/100.0)                        AS agent_cost_lv2,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate3,0)/100.0)                        AS agent_cost_lv3,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate4,0)/100.0)                        AS agent_cost_lv4,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate5,0)/100.0)                        AS agent_cost_lv5,
          SUM(-s.x_net*(COALESCE(100.0-s.x_rate1,0)+COALESCE(100.0-s.x_rate2,0)
                       +COALESCE(100.0-s.x_rate3,0)+COALESCE(100.0-s.x_rate4,0)
                       +COALESCE(100.0-s.x_rate5,0))/100.0)                   AS agent_cost_chain_additive,
          SUM(-s.x_net*(1.0 - CAST(COALESCE(s.x_rate1,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate2,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate3,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate4,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate5,100) AS DOUBLE)/100.0))
                                                                       AS agent_cost_chain_nested,
           AVG(s.x_rbpct) AS rbpct, AVG(s.x_freecomm*1.0) AS freecomm_rate,
           PERCENTILE_APPROX(s.x_stake,0.25) AS p25, PERCENTILE_APPROX(s.x_stake,0.50) AS p50,
           PERCENTILE_APPROX(s.x_stake,0.75) AS p75, PERCENTILE_APPROX(s.x_stake,0.90) AS p90,
           PERCENTILE_APPROX(s.x_stake,0.95) AS p95, PERCENTILE_APPROX(s.x_stake,0.99) AS p99,
           PERCENTILE_APPROX(s.x_valid,0.50) AS p50_valid,
           PERCENTILE_APPROX(s.x_net,0.50)   AS p50_profit,
           SUM(CASE WHEN s.x_rec = 1 THEN s.x_stake ELSE 0 END) AS st_in,
           SUM(CASE WHEN s.x_rec = 1 THEN 1 ELSE 0 END)         AS nb_in,
           SUM(CASE WHEN s.x_rec = 1 THEN s.x_net ELSE 0 END)   AS net_in,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN s.x_stake ELSE 0 END) AS st_out,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN 1 ELSE 0 END)         AS nb_out,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN s.x_net ELSE 0 END)   AS net_out,
           SUM(CASE WHEN s.x_rec=1 THEN s.x_stake ELSE 0 END) AS st_rec,
           SUM(CASE WHEN s.x_rec=1 THEN 1 ELSE 0 END)         AS nb_rec
    FROM x_mk s
    WHERE s.is_clean = 1
      AND s.x_member IS NOT NULL AND TRIM(CAST(s.x_member AS STRING)) <> ''
    GROUP BY s.x_member
  ),
      q AS (
        WITH ev AS (                                                                                        -- 公共表表达式：开启中间结果集 ev——变更日志原始事件，口径与 §TL-10 一致（§TL-11）
            SELECT  CAST(lmc02 AS STRING)                         AS member_id,                             -- 取值表达式：取用 lmc02（被改会员号），产出「member_id」
                    SUBSTR(CAST(lmc08 AS STRING), 1, 10)          AS action_date,                           -- 取值表达式：取用 lmc08（操作时间）之日期段，产出「action_date」
                    CAST(lmc08 AS STRING)                         AS action_time,                           -- 取值表达式：取用 lmc08（操作时间），产出「action_time」
                    CAST(lmc06 AS STRING)                         AS operator_id,                           -- 取值表达式：取用 lmc06（操作人账号），产出「operator_id」——审计轨迹之「谁」
                    CAST(lmc07 AS STRING)                         AS operator_lv,                           -- 取值表达式：取用 lmc07（操作人层级），产出「operator_lv」
                    CAST(lmc05 AS STRING)                         AS content                                -- 取值表达式：取用 lmc05（变更内容串），产出「content」
            FROM    ods_mariadb_2b.ods_a168_log_mem_change                                                  -- 取数来源：取自会员变更日志表（处置痕迹的正主）
            WHERE   dt >= '2026-03-21'                                                                      -- 过滤条件：限定 dt不少于 '2026-03-21'，涉 dt（营业日）——E1 全局窗起点
              AND   dt <  '2026-08-07'                                                                      -- 并列条件：限定 dt小于 '2026-08-07'——E1 全局窗终点（冻结字面量）
              AND   CAST(lmc04 AS STRING) IN ('edit', 'changestatus')                                       -- 并列条件：只留配置修改与状态变更；add 系新增账户与处置无涉
        ),                                                                                                  -- 续行：收束上方的子查询或函数括号（§TL-11）
        seg AS (                                                                                            -- 公共表表达式：开启中间结果集 seg——把多段 content 逐段拆开（§TL-11）
            SELECT  e.member_id, e.action_date, e.action_time,                                              -- 取列：起始取列子句，本行先列 member_id, action_date, action_time
                    e.operator_id, e.operator_lv,                                                           -- 续行：接续上一取列子句，续列 operator_id, operator_lv
                    TRIM(s.piece)                                 AS piece                                  -- 取值表达式：逐段去空白，产出「piece」
            FROM ev e, unnest(split(e.content, ';')) AS s(piece)                                            -- 行展开：以 unnest(split(…)) 把分号分隔的多段变更逐段成行（StarRocks 已验语法）
        ),                                                                                                  -- 续行：收束上方的子查询或函数括号（§TL-11）
        norm AS (                                                                                           -- 公共表表达式：开启中间结果集 norm——两式并收：冒号式与空格式统一为「列|旧|新」（§TL-11）
            SELECT  member_id, action_date, action_time, operator_id, operator_lv, piece,                   -- 取列：起始取列子句，透传六要素与原始片段
                    CASE WHEN piece LIKE '%:%' THEN 'COLON' ELSE 'SPACE' END AS parse_sep,                  -- 取值表达式：记明所用分隔符，产出「parse_sep」——★ 使丢弃永不静默
                    CASE WHEN piece LIKE '%:%'                                                              -- 取值表达式：列名解析起算——冒号式取冒号前段
                         THEN TRIM(SPLIT_PART(piece, ':', 1))                                               -- 续行：冒号式列名
                         ELSE TRIM(SPLIT_PART(piece, ' ', 1)) END      AS field_name,                       -- 续行：空格式取首个空格前段（如「mem020 Y=>N」），产出「field_name」
                    CASE WHEN piece LIKE '%:%'                                                              -- 取值表达式：旧值解析起算
                         THEN TRIM(SPLIT_PART(SPLIT_PART(piece, ':', 2), '=>', 1))                          -- 续行：冒号式旧值
                         ELSE TRIM(SPLIT_PART(SPLIT_PART(piece, ' ', 2), '=>', 1)) END AS value_before,     -- 续行：空格式旧值，产出「value_before」
                    TRIM(SPLIT_PART(piece, '=>', 2))              AS value_after                            -- 取值表达式：新值一律取箭头后段（两式同形），产出「value_after」
            FROM    seg                                                                                     -- 取数来源：取自本条自建的中间结果集 seg
            WHERE   piece LIKE '%=>%'                                                                       -- 过滤条件：须含箭头方为有效变更段——两式共有的唯一必要标志
        ),                                                                                                  -- 续行：收束上方的子查询或函数括号（§TL-11）
        enf AS (                                                                                            -- 公共表表达式：开启中间结果集 enf——只留已译定的处置字段并判方向与类别（§TL-11）
            SELECT  member_id, field_name, action_date, action_time,                                        -- 取列：起始取列子句，透传节要素之前四
                    value_before, value_after, operator_id, operator_lv, parse_sep,                         -- 续行：接续上一取列子句，续列前后值、操作人与分隔符
                    CASE WHEN field_name = 'mem017' THEN 'CANBET_下注权限'                                      -- 取值表达式：处置类别起算——mem017 系下注权限（§TL-09 列义）
                         WHEN field_name = 'mem016' THEN 'ENABLE_账户启停'                                      -- 续行：mem016 系账户启停
                         ELSE 'OTHER' END                     AS enforcement_type,                          -- 续行：产出「enforcement_type」——外部审计所要的处置类别列
                    CASE WHEN field_name = 'mem017' THEN 'canbet'                                           -- 取值表达式：业务列名起算——代号译为业务名，免下游再查字典
                         WHEN field_name = 'mem016' THEN 'enable'                                           -- 续行：mem016 之业务名
                         ELSE 'unknown' END                   AS business_field,                            -- 续行：产出「business_field」
                    CASE WHEN TRIM(value_after) IN ('N', '0') THEN 'TIGHTEN'                                -- 取值表达式：新值为 N／0 判收紧——禁投或停用
                         WHEN TRIM(value_after) IN ('Y', '1') THEN 'RELEASE'                                -- 续行：新值为 Y／1 判解除
                         ELSE 'OTHER' END                     AS direction,                                 -- 续行：其余取值不明记 OTHER，不入节（宁缺毋滥），产出「direction」
                    'OK'                                     AS parse_status                                -- 取值表达式：解析状态，产出「parse_status」——本 CTE 所留者皆已解析成功
            FROM    norm                                                                                    -- 取数来源：取自本条自建的中间结果集 norm
            WHERE   field_name IN ('mem016', 'mem017')                                                      -- 过滤条件：只认已译定的处置字段——mem015 已证为 login_error，非处置，一律不入
        ),                                                                                                  -- 续行：收束上方的子查询或函数括号（§TL-11）
        dedup AS (                                                                                          -- 公共表表达式：开启中间结果集 dedup——同刻重复写入只计一次（去重键四元组）
            SELECT  *,                                                                                      -- 取列：整体承接上游结果集的全部字段，不再逐列列举
                    ROW_NUMBER() OVER (PARTITION BY member_id, field_name, action_time,                     -- 行号窗口表达式：按去重键 member×field×时刻×前后值 分组编号
                                       value_before, value_after ORDER BY operator_id) AS rn                -- 续行：键内任取其一（按操作人序），产出「rn」
            FROM    enf                                                                                     -- 取数来源：取自本条自建的中间结果集 enf
            WHERE   direction <> 'OTHER'                                                                    -- 过滤条件：方向不明者不入节
        ),                                                                                                  -- 续行：收束上方的子查询或函数括号（§TL-11）
        tight AS (                                                                                          -- 公共表表达式：开启中间结果集 tight——全部收紧事件，每行是一节的起点（§TL-11）
            SELECT * FROM dedup WHERE rn = 1 AND direction = 'TIGHTEN'                                      -- 取数来源：去重后的收紧事件
        ),                                                                                                  -- 续行：收束上方的子查询或函数括号（§TL-11）
        rel AS (                                                                                            -- 公共表表达式：开启中间结果集 rel——全部解除事件，用以为每节寻其后首个解除（§TL-11）
            SELECT * FROM dedup WHERE rn = 1 AND direction = 'RELEASE'                                      -- 取数来源：去重后的解除事件
        ),                                                                                                  -- 续行：收束上方的子查询或函数括号（§TL-11）
        bl AS (                                                                                             -- 公共表表达式：开启中间结果集 bl——本方案口径的百家乐投注会员名单（§TL-11 补列所需）
            SELECT  DISTINCT CAST(bet05 AS STRING)                AS member_id                              -- 取值表达式：取用 bet05（会员号）去重，产出「member_id」
            FROM    ods_mariadb_2b.ods_a168_bet02                                                           -- 取数来源：取自注单明细表
            WHERE   dt >= '2026-03-21' AND dt < '2026-08-07'                                                -- 过滤条件：限定 E1 全局窗，涉 dt（营业日）
              AND   CAST(bet02 AS STRING) = '101'                                                           -- 并列条件：限定百家乐产品大类，涉 bet02（游戏类别）
        ),                                                                                                  -- 续行：收束上方的子查询或函数括号（§TL-11）
        la AS (                                                                                             -- 公共表表达式：开启中间结果集 la——每会员窗内最末一次**投注**，供删失成因分类（§TL-11）
            SELECT  CAST(bet05 AS STRING)                         AS member_id,                             -- 取值表达式：取用 bet05（会员号），产出「member_id」
                    MAX(dt)                                       AS last_bet_date,                         -- 聚合：该会员窗内最末一次投注之营业日，产出「last_bet_date」
                    COUNT(*)                                      AS n_bets_in_window                       -- 计数表达式：窗内注单数，产出「n_bets_in_window」——覆盖率证据，供删失分类追溯
            FROM    ods_mariadb_2b.ods_a168_bet02                                                           -- 取数来源：取自注单明细表——★ 2026-08-11 斧正：旧版以「最末一次出现于变更日志」为凭
            WHERE   dt >= '2026-03-21' AND dt < '2026-08-07'                                                -- 过滤条件：限定 E1 全局窗——而变更日志之缺席只说明未再改配置，不说明人已不在
              AND sync_time <= '2026-08-27 09:00:00'
            GROUP BY CAST(bet05 AS STRING)                                                                  -- 分组：按会员汇总——投注活动方是「仍在观察」的正当凭据
        ),                                                                                                  -- 续行：收束上方的子查询或函数括号（§TL-11）
        lc AS (                                                                                             -- 公共表表达式：开启中间结果集 lc——每会员末次配置变更时刻（§TL-11）
            SELECT  member_id, MAX(action_time)                   AS last_config_time                       -- 聚合：末次出现于变更日志之时刻，产出「last_config_time」
            FROM    norm GROUP BY member_id                                                                 -- 取数来源：取自本条自建的中间结果集 norm——★ 此量仅作证据留档，**不再用作删失判据**
        ),                                                                                                  -- 续行：收束上方的子查询或函数括号（§TL-11）
        ep AS (                                                                                             -- 公共表表达式：开启中间结果集 ep——为每次收紧配其后首个解除（§TL-11）
            SELECT  t.member_id, t.field_name, t.business_field, t.enforcement_type,                        -- 取列：起始取列子句，节起点要素与两枚新增类别列
                    t.action_date, t.action_time, t.value_before, t.value_after,                            -- 续行：接续上一取列子句，续列时点与前后值
                    t.operator_id, t.operator_lv, t.parse_sep, t.parse_status,                              -- 续行：续列操作人、层级与解析两列
                    MIN(r.action_time)                            AS release_time                           -- 聚合：其后（同人同字段）首个解除时刻，无则空，产出「release_time」
            FROM        tight t                                                                             -- 取数来源：取自本条自建的中间结果集 tight
            LEFT JOIN   rel   r                                                                             -- 左连接：取自本条自建的中间结果集 rel——解除可缺席（右删失），故用左连接
                   ON   r.member_id  = t.member_id                                                          -- 连接键：同一会员
                  AND   r.field_name = t.field_name                                                         -- 并列键：同一处置字段——canbet 之节不由 enable 之解除关闭
                  AND   r.action_time > t.action_time                                                       -- 并列键：解除须晚于收紧——只认其后者
            GROUP BY t.member_id, t.field_name, t.business_field, t.enforcement_type,                       -- 分组：按节起点全键汇总，使 MIN 取到「首个」解除
                     t.action_date, t.action_time, t.value_before, t.value_after,                           -- 续行：分组键补齐
                     t.operator_id, t.operator_lv, t.parse_sep, t.parse_status                              -- 续行：分组键补齐
        )                                                                                                   -- 续行：收束上方的子查询或函数括号（§TL-11）
        SELECT  p.member_id,                                                                                -- 取列：起始取列子句，本行先取「member_id」——节属谁
                p.field_name,                                                                               -- 取值表达式：处置字段代号
                p.business_field,                                                                           -- 取值表达式：业务列名（canbet／enable）——★ 补列，免下游再查字典
                p.enforcement_type,                                                                         -- 取值表达式：处置类别——★ 补列，区分下注权限与账户启停
                CASE WHEN bl.member_id IS NULL THEN 0 ELSE 1 END  AS is_baccarat_member,                    -- 取值表达式：是否本方案口径的百家乐会员——★ 补列，准实验总体由此界定
                CONCAT_WS('#', p.member_id, p.field_name, p.action_time) AS episode_id,                     -- 取值表达式：三键拼节号，产出「episode_id」——审计轨迹与准实验共用的主键
                p.action_date                                 AS start_date,                                -- 取值表达式：节起日，产出「start_date」
                p.action_time                                 AS start_time,                                -- 取值表达式：节起时刻，产出「start_time」
                p.value_before,                                                                             -- 取值表达式：收紧前取值——留痕以备申诉复核
                p.value_after,                                                                              -- 取值表达式：收紧后取值
                p.operator_id                                 AS start_operator,                            -- 取值表达式：收紧操作人，产出「start_operator」——审计轨迹之「谁」
                p.operator_lv                                 AS start_operator_lv,                         -- 取值表达式：操作人层级，产出「start_operator_lv」
                p.parse_sep,                                                                                -- 取值表达式：本行所用分隔符（COLON／SPACE）——★ 补列，两式并收之凭据
                p.parse_status,                                                                             -- 取值表达式：解析状态——★ 补列，恒为 OK；丢弃者见 §TL-11b 对账
                COALESCE(SUBSTR(p.release_time, 1, 10), '2026-08-07') AS release_date,                      -- 取值表达式：解除日；缺席者以窗末顶替（配合下行 censored 判读），产出「release_date」
                CASE WHEN p.release_time IS NULL THEN 1 ELSE 0 END    AS censored,                          -- 取值表达式：右删失标志——1 谓至窗末仍收紧，产出「censored」
                la.last_bet_date,                                                                           -- 取值表达式：末次投注营业日——★ 删失分类之原始证据，供逐节追溯
                la.n_bets_in_window,                                                                        -- 取值表达式：窗内注单数——★ 覆盖率证据
                lc.last_config_time,                                                                        -- 取值表达式：末次配置变更时刻——★ 第二重证据（旧判据留档，已不作分类依据）
                DATEDIFF(DATE '2026-08-06', CAST(la.last_bet_date AS DATE)) AS days_since_last_bet,         -- 取值表达式：末次投注距窗末天数——★ **连续原始量**，供 3D／7D／14D 敏感性，免回访原表
                7                                             AS censor_cutoff_days,                        -- 取值表达式：本次分类所用的运营切点（日）——★ 显式化：7 日是**工程约定**，非统计真理
                CASE WHEN p.release_time IS NOT NULL THEN 'NOT_CENSORED'                                    -- 取值表达式：删失成因分类起算——★ KM 无偏性之前提
                     WHEN la.last_bet_date IS NULL THEN 'NO_BET_ACTIVITY'                                   -- 续行：窗内全无投注 → 无从判其去留（先判此项，免 NULL 落入比较而误分）
                     WHEN DATEDIFF(DATE '2026-08-06', CAST(la.last_bet_date AS DATE)) <= 7                  -- 续行：末次投注距窗末不逾切点 → 人尚在、处置尚在
                          THEN 'WINDOW_END'                                                                 -- 续行：属真窗口右删失
                     ELSE 'INACTIVE_BEFORE_END' END                    AS censor_reason,                    -- 续行：投注早止 → 疑为流失或账户终止型**假删失**，产出「censor_reason」
                DATEDIFF(CAST(COALESCE(SUBSTR(p.release_time, 1, 10), '2026-08-07') AS DATE),               -- 取值表达式：节时长起算——解除日（或窗末）
                         CAST(p.action_date AS DATE))         AS duration_days,                             -- 续行：减节起日得持续天数，产出「duration_days」——生存分析之时间轴
                ROW_NUMBER() OVER (PARTITION BY p.member_id                                                 -- 行号窗口表达式：按会员为其节编序
                                   ORDER BY p.action_time)    AS episode_seq                                -- 续行：产出「episode_seq」——主分析取 1（首次处置设计），其余入敏感性
        FROM        ep p                                                                                    -- 取数来源：取自本条自建的中间结果集 ep
        LEFT JOIN   bl ON bl.member_id = p.member_id                                                        -- 左连接：取自本条自建的中间结果集 bl，连接键为 member_id（会员号）——标注百家乐口径
        LEFT JOIN   la ON la.member_id = p.member_id                                                        -- 左连接：取自本条自建的中间结果集 la（末次投注日），连接键为 member_id（会员号）
        LEFT JOIN   lc ON lc.member_id = p.member_id                                                        -- 左连接：取自本条自建的中间结果集 lc（末次配置变更），连接键为 member_id（会员号）
      )
    SELECT q.*,
           -- 一·经济层
           ROUND(e.stake,4) AS stake, ROUND(e.valid,4) AS valid_bet,
           ROUND(-e.net,4) AS profit, e.n_bets, e.n_rounds,
           ROUND(e.net/NULLIF(e.stake,0),8) AS roi,
           ROUND(e.net_in/NULLIF(e.st_in,0),8) AS roi_post,
           ROUND(e.net_out/NULLIF(e.st_out,0),8) AS roi_non_post,
           ROUND((e.net-e.rebate)/NULLIF(e.stake,0),8) AS roi_ex_rebate,
           ROUND(e.net,4) AS roi_numerator, ROUND(e.stake,4) AS roi_denominator,
           CASE WHEN e.stake IS NULL THEN 'NULL_DENOM' WHEN e.stake<=0 THEN 'ZERO_DENOM'
                WHEN e.n_bets<30 THEN 'THIN_EXPOSURE' ELSE 'OK' END AS roi_denominator_status,
           ROUND(e.rebate,4) AS rebate_cost, ROUND(e.agent_cost,4)                           AS cost_complement_b,
       ROUND(e.agent_pct,4)                            AS pct_complement,
       ROUND(e.company_retain_pct,4)                   AS pct_top_bet23,
       'AG03-UNRESOLVED'                                     AS agent_formula_version,
      'ALL5_LEVELS_bet23_to_bet27'                    AS agent_level_scope,
      ROUND(e.agent_cost_lv1,4) AS agent_cost_lv1, ROUND(e.agent_cost_lv2,4) AS agent_cost_lv2,
      ROUND(e.agent_cost_lv3,4) AS agent_cost_lv3, ROUND(e.agent_cost_lv4,4) AS agent_cost_lv4,
      ROUND(e.agent_cost_lv5,4) AS agent_cost_lv5,
      ROUND(e.agent_pct_lv1,6) AS agent_pct_lv1, ROUND(e.agent_pct_lv2,6) AS agent_pct_lv2,
      ROUND(e.agent_pct_lv3,6) AS agent_pct_lv3, ROUND(e.agent_pct_lv4,6) AS agent_pct_lv4,
      ROUND(e.agent_pct_lv5,6) AS agent_pct_lv5,
      ROUND(e.retain_pct_lv1,6) AS retain_pct_lv1, ROUND(e.retain_pct_lv2,6) AS retain_pct_lv2,
      ROUND(e.retain_pct_lv3,6) AS retain_pct_lv3, ROUND(e.retain_pct_lv4,6) AS retain_pct_lv4,
      ROUND(e.retain_pct_lv5,6) AS retain_pct_lv5, ROUND(e.chain_depth_avg,4) AS chain_depth_avg,
      ROUND(e.agent_cost_chain_additive,4)            AS agent_cost_chain_additive,
      ROUND(e.agent_cost_chain_nested,4)              AS agent_cost_chain_nested,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_additive,4) AS residual_chain_additive,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_nested,4)   AS residual_chain_nested,
      'PENDING_AG03'                                  AS decision_status,
      'FALSE'                                         AS admit_to_risk_decision,
      'NOT_FOR_ENFORCEMENT'                           AS deliverable_class,
       ROUND(e.agent_cost_a_legacy,4)                  AS agent_cost_a_legacy,
       ROUND(e.agent_cost_valid_base_legacy,4)         AS agent_cost_valid_base_legacy,
           ROUND(-e.net-e.rebate,4)                        AS ngr,
       ROUND(-e.net-e.rebate-e.agent_cost,4)           AS residual_b,
       ROUND(-e.net-e.rebate-e.agent_cost_a_legacy,4)  AS residual_a,
           ROUND((-e.net-e.rebate)/NULLIF(e.stake,0),8)    AS ngr_rate,
       ROUND((-e.net-e.rebate-e.agent_cost)/NULLIF(e.stake,0),8)   AS residual_b_rate,
      -- 【HF9c · canonical accounting contract】
      --   以下 canonical 字段只增加明确 scope；不删除、不覆盖既有字段。
      --   formal_bet23_* 保持 HF9b 当前生产公式及其 NULL/0 语义；
      --   lv1~lv5 / additive / nested 则分别采用各自原始 e.* 成本字段，
      --   rate 一律从未舍入的 e.* 分子 / e.stake 计算，禁止由展示值反算。
      ROUND(e.agent_cost,4) AS agent_cost_bet23_formal_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost,4) AS net_margin_bet23_formal_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost)/NULLIF(e.stake,0),8) AS net_margin_bet23_formal_rate_canonical,
      ROUND(e.agent_cost_lv1,4) AS agent_cost_lv1_bet23_canonical,
      ROUND(e.agent_cost_lv2,4) AS agent_cost_lv2_bet24_canonical,
      ROUND(e.agent_cost_lv3,4) AS agent_cost_lv3_bet25_canonical,
      ROUND(e.agent_cost_lv4,4) AS agent_cost_lv4_bet26_canonical,
      ROUND(e.agent_cost_lv5,4) AS agent_cost_lv5_bet27_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_lv1,4) AS net_margin_lv1_bet23_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_lv1)/NULLIF(e.stake,0),8) AS net_margin_lv1_bet23_rate_canonical,
      ROUND(e.agent_cost_chain_additive,4) AS agent_cost_chain_additive_canonical,
      ROUND(e.agent_cost_chain_nested,4) AS agent_cost_chain_nested_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_additive,4) AS net_margin_chain_additive_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_nested,4) AS net_margin_chain_nested_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_chain_additive)/NULLIF(e.stake,0),8) AS net_margin_chain_additive_rate_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_chain_nested)/NULLIF(e.stake,0),8) AS net_margin_chain_nested_rate_canonical,
       ROUND((-e.net-e.rebate-e.agent_cost_a_legacy)/NULLIF(e.stake,0),8) AS residual_a_rate,
           -- 二·分布层
           ROUND(e.stake/NULLIF(e.n_bets,0),4) AS avg_stake_per_bet,
           ROUND(e.valid/NULLIF(e.n_rounds,0),4) AS avg_valid_bet_per_round,
           ROUND(-e.net/NULLIF(e.n_rounds,0),4) AS avg_profit_per_round,
           ROUND(-e.net/NULLIF(e.active_days,0),4) AS avg_profit_per_day,
           ROUND(-e.net/NULLIF(e.active_shoes,0),4) AS avg_profit_per_shoe,
           ROUND(e.stake/NULLIF(e.active_days,0),4) AS avg_stake_per_active_day,
           ROUND(e.n_rounds*1.0/NULLIF(e.active_days,0),4) AS avg_rounds_per_active_day,
           ROUND(e.st_in/NULLIF(e.nb_in,0),4) AS avg_stake_post,
           ROUND(e.st_out/NULLIF(e.nb_out,0),4) AS avg_stake_non_post,
           ROUND(e.p25,4) AS p25_stake, ROUND(e.p50,4) AS p50_stake, ROUND(e.p75,4) AS p75_stake,
           ROUND(e.p90,4) AS p90_stake, ROUND(e.p95,4) AS p95_stake, ROUND(e.p99,4) AS p99_stake,
           ROUND(e.p50_valid,4) AS p50_valid_bet, ROUND(e.p50_profit,4) AS p50_profit,
           ROUND(e.p95/NULLIF(e.p50,0),6) AS p95_over_p50,
           ROUND(e.p99/NULLIF(e.p50,0),6) AS p99_over_p50,
           ROUND((e.stake/NULLIF(e.n_bets,0))/NULLIF(e.p50,0),6) AS avg_over_p50,
           -- 三·关系层
           e.n_tables AS common_table_count, e.n_dealers AS common_dealer_count,
           e.n_ips AS common_ip_count, e.n_products AS common_product_count,
           ROUND(e.st_in/NULLIF(e.stake,0),8) AS share_post,
           -- 四·rate 层
           ROUND(-e.net/NULLIF(e.stake,0),8) AS hold_rate,
           ROUND(-e.net_in/NULLIF(e.st_in,0),8) AS hold_rate_post,
           ROUND(e.rebate/NULLIF(e.valid,0),8) AS rebate_rate_actual,
           ROUND(e.rbpct,6) AS rebate_pct_config,
           ROUND(e.valid/NULLIF(e.stake,0),6) AS turnover_multiple,
           ROUND(e.freecomm_rate,6) AS free_comm_rate,
           ROUND(e.net_in/NULLIF(e.st_in,0)-e.net_out/NULLIF(e.st_out,0),8) AS roi_delta_post,
           -- 五·动态层
           e.first_seen_d AS first_seen, e.last_seen_d AS last_seen,
           e.active_days, e.active_shoes, e.active_sessions,
           DATEDIFF(e.last_seen_d, e.first_seen_d)+1 AS span_days,
           ROUND(e.active_days*1.0/NULLIF(DATEDIFF(e.last_seen_d,e.first_seen_d)+1,0),6) AS persistence,
           ROUND((e.st_in/NULLIF(e.nb_in,0))/NULLIF(e.st_out/NULLIF(e.nb_out,0),0),6) AS ramp_post,
           ROUND((e.st_rec/NULLIF(e.nb_rec,0))/NULLIF(e.stake/NULLIF(e.n_bets,0),0),6) AS ramp_recent,
           ROUND((e.st_rec/NULLIF(e.stake,0))/0.30,6) AS stake_ramp,
           -- 六·决策层（HF9f · 详见档头【HF9f 变更说明】；本段两版逐字同一）
           NTILE(5) OVER (ORDER BY e.stake) AS vip_tier,                                                        -- 窗口取值：相对刻度 B 族，全体五等分；须连同下方血统五元组一并解读，禁作硬阈值判型
           PERCENT_RANK() OVER (ORDER BY -e.net-e.rebate-e.agent_cost)    AS economic_value,                    -- 窗口取值：HF9f·F-19 修正 —— HF9e 写作 -(-…) 双负号致方向颠倒（#075 实测 corr(economic_value, residual_b) = -1.0000）；今与 action_priority 排序键归一，值大即平台真净利高
           PERCENT_RANK() OVER (ORDER BY e.net/NULLIF(e.stake,0))         AS roi_pr_global,                     -- 窗口取值：HF9f·F-17 正名 —— 本列实为 ROI（玩家净回报率）之全体百分位，与「风险」无关；旧名 risk_value 见下一行
           PERCENT_RANK() OVER (ORDER BY e.net/NULLIF(e.stake,0))         AS risk_value,                        -- 窗口取值：兼容列，恒等于 roi_pr_global，仅为下游迁移窗保留；HF9g 起废弃，禁新引用
           PERCENT_RANK() OVER (ORDER BY e.stake)                         AS pr_stake,                          -- 窗口取值：兼容列，恒等于 pr_global，原名保留以免断链
           PERCENT_RANK() OVER (ORDER BY e.stake)                         AS pr_global,                         -- 窗口取值：HF9f·F-1 双轨之一 —— 全体口径百分位，参照总体即本件全部输出行
           CASE WHEN e.n_rounds >= 30                                                                           -- 条件分支：起始分支 —— 仅在合格子集内计算合格口径百分位
                  THEN PERCENT_RANK() OVER (PARTITION BY CASE WHEN e.n_rounds >= 30 THEN 1 ELSE 0 END ORDER BY e.stake)  -- 分支取值：以合格与否分区，故本值即 n_rounds>=30 子集内之百分位
                ELSE NULL END                                             AS pr_qualified,                      -- 条件分支：收束上方分支 —— 不合格者留 NULL（NULL＝未测，非 0），产出「pr_qualified」
           'n_rounds>=30'                                                 AS pr_qualified_population,           -- 字面取值：血统 —— 合格子集之定义
           COUNT(*) OVER ()                                               AS pr_global_population_n,            -- 窗口取值：血统 —— 全体口径之参照总体规模，渲染时现算，禁写死
           SUM(CASE WHEN e.n_rounds >= 30 THEN 1 ELSE 0 END) OVER ()      AS pr_qualified_population_n,         -- 窗口取值：血统 —— 合格子集之参照总体规模，现算，禁写死
           'PERCENT_RANK_OVER_ORDER_BY_e_stake'                           AS pr_calculation_method,             -- 字面取值：血统 —— 算法标识
           'HF9f'                                                         AS pr_calculation_version,            -- 字面取值：血统 —— 算法版本
           CASE WHEN e.n_rounds IS NULL OR e.n_rounds < 30 THEN 'THIN_ROUNDS' ELSE 'OK' END AS evidence_flag,   -- 条件分支：HF9f·F-2a 证据旗标 —— THIN_ROUNDS 者禁入执行队列，仅入观察队列
           CASE WHEN e.n_rounds IS NULL       THEN NULL                                                         -- 条件分支：起始分支 —— 未测者留 NULL（自家铁律：NULL ≠ 0）
                WHEN e.n_rounds >= 31483      THEN 'L1_POWERED'                                                 -- 分支判定：MDE 反解第一档
                WHEN e.n_rounds >= 15409      THEN 'L2_CI_1P5'                                                  -- 分支判定：MDE 反解第二档
                WHEN e.n_rounds >=  8668      THEN 'L3_CI_2P0'                                                  -- 分支判定：MDE 反解第三档
                WHEN e.n_rounds >=  3852      THEN 'L4_CI_3P0'                                                  -- 分支判定：MDE 反解第四档
                ELSE 'L5_INSUFFICIENT' END                                AS evidence_rate,                     -- 条件分支：收束上方 —— HF9f·F-3 证据分档，承 HF9e 前议之 MDE 反解五档，须于 F-4 敏感性实验后复核
           ROUND(1.96 * 0.95 / SQRT(NULLIF(CAST(e.n_rounds AS DOUBLE),0)),8) AS hold_ci_halfwidth_approx,       -- 比率表达式：HF9f·F-3 逐行现算之 95% 半宽近似；常数 0.95 为登记值，本轮 #075 实测每局 ROI 隐含 σ 于最薄层为 0.9249，二者差异待 F-4 裁定
           CASE WHEN e.stake IS NULL OR e.stake<=0 OR e.n_bets<30 OR e.n_rounds IS NULL OR e.n_rounds<30 THEN 'Z 证据不足 · 不动作'  -- 条件分支：HF9f·F-2 双条件取严 —— HF9e 仅卡 e.n_bets<30，致 n_bets>=30 而 n_rounds<30 者绕过 Z（#075 实测 18,537 名，其中 8,145 名已入 A/D 待裁）；今两条件并列取严
                WHEN PERCENT_RANK() OVER (ORDER BY -e.net-e.rebate-e.agent_cost)<=0.10                          -- 分支判定：平台真净利之最低十分位
                  THEN 'A 净亏最大十分位 · 优先复核'                                                             -- 分支取值：HF9f·F-20 正名 —— 本档 Σresidual_b 于 #075 实测 = -100,236,896，系平台净亏最大群，旧名「残值最低十分位 · 待裁」名实不符
                WHEN PERCENT_RANK() OVER (ORDER BY -e.net-e.rebate-e.agent_cost)>=0.80                          -- 分支判定：平台真净利之最高二十分位
                  THEN 'D 净利最高二十分位 · 优先留存'                                                           -- 分支取值：HF9f·F-20 正名 —— 本档 Σresidual_b 于 #075 实测 = +281,733,190，系核心利润源；与 A 档方向相反，旧版同标「待裁」属名实不符
                ELSE 'E 常规' END                                          AS action_priority                   -- 条件分支：收束上方判词，产出「action_priority」
    FROM q
    LEFT JOIN x_agg e ON CAST(e.x_key AS STRING) = CAST(q.`member_id` AS STRING)
  ) y
) z
-- ── 逐批 WHERE 阶梯（★ 口诀：上界 ＝ 下界 ＋ 100000，两数同进）──
--    本件 T_true 未测，无需先跑 T_true；以 0 / 100000 控制本批返回区间，末批由实际行数 < 100000 判定
--    WHERE z.audit_rn >        0 AND z.audit_rn <=   100000   -- 第 1 批
--    WHERE z.audit_rn >   100000 AND z.audit_rn <=   200000   -- 第 2 批
--    WHERE z.audit_rn >   200000 AND z.audit_rn <=   300000   -- 第 3 批
--    WHERE z.audit_rn >   300000 AND z.audit_rn <=   400000   -- 第 4 批
--    WHERE z.audit_rn >   400000 AND z.audit_rn <=   500000   -- 第 5 批
--    WHERE z.audit_rn >   500000 AND z.audit_rn <=   600000   -- 第 6 批
--    WHERE z.audit_rn >   600000 AND z.audit_rn <=   700000   -- 第 7 批
--    …余批类推。第 k 批：WHERE z.audit_rn > (k-1)*100000 AND z.audit_rn <= k*100000
--    某批返回 < 100000 行即为末批，其后不再取。
--
--    ⚠ 常见误写（务必避开）：只推下界而上界不动 ——
--        WHERE z.audit_rn > 100000 AND z.audit_rn <= 100000   ← 自相矛盾，恒为假，返回空集
--        WHERE z.audit_rn > 200000 AND z.audit_rn <= 100000   ← 同上，空集
--      两个数必须**同时**前进，且始终相差 100000。
--      下界 ＝ 上一批之上界；上界 ＝ 本批之上界。
WHERE z.audit_rn > 0 AND z.audit_rn <= 100000 -- ★ HF9c 本批区间
ORDER BY z.audit_rn;


-- ══════════════════════════════════════════════════════════════════════════════════════════════
--  96. TL11c_population_reconcile.csv   [总包行 8969~9055 · 原 7 列 ＋六层约 60 列]
--     典型学：M09 处置限额　派生旗标：post（s.x_rec = 1 · 仅供 CASE 条件聚合，全包无任何 WHERE/AND/HAVING 以此过滤）　连接：全窗基线
-- ══════════════════════════════════════════════════════════════════════════════════════════════
-- ★ W-64 · D-14 警示（本件属 x_win 族 · 66 件之一 · 详见 §Z 段 D-14 全案）
--   本件以 `CROSS JOIN x_win e` 接入全局基线，x_win 无 GROUP BY ⇒ 恒 1 行 ⇒ e.* 全行同值。
--   故：economic_value / roi_pr_global / risk_value / pr_stake / pr_global 恒为 0；
--       action_priority 每一行皆为「A 净亏最大十分位 · 优先复核」（Z 分支永不触发）；
--       evidence_rate 恒为最高档；vip_tier 由常数键分档 ⇒ 无信息且非确定。
--   ⇒ 本件决策层三列 **NOT_FOR_DECISION**，裁定前不得用于排班、抽查或汇报。
-- ── ① 先跑 T_true 留档（不足 100000 者一次导全，不必分批）──
-- ── ① T_true：HF9c 不再强制预跑完整 COUNT。
--    本批实际返回行数 < 100000 即判定为末批；全批完成后以各批 n_rows / audit_rn 范围核对总量。

-- ── ② 分批取数：第 1 批。第 k 批只改末行两数为 (k-1)*100000 与 k*100000 ──
--    审计字段二（REDTEAM 2026-08-24 裁定 · 四锁）：
--      audit_rn  全局观测坐标 —— 由**与原版审计版逐字同一**之排序键所生，两版可逐行对账
--      batch_id  物理分批信息 —— 该行所属批次，由 audit_rn 算得，非引擎所赋
--    ★ 锁三：二者皆为审计字段，**不得进入任何业务指标计算**。
--    ★ 锁四：两版经 audit_rn 逐行字段核验后，方可宣布输出完全一致。

-- ── ③ 每批取回后自证四数（任一不符即停手回报，禁止放行）──
--    n_rows        = COUNT(*)      须等于 COUNT(DISTINCT audit_rn)   （批内无重复）
--    audit_rn_min  = MIN(audit_rn) 须等于 (k-1)*100000 + 1           （与上批严丝合缝）
--    audit_rn_max  = MAX(audit_rn) 须等于 min + n_rows - 1           （批内无缺口）
--    全批取毕再验：各批 audit_rn 之并集 = 1 .. T_true，无缺号、无重号。
--     ★ 首行＝平台真净亏最多者（已扣退水与代理占成）。
--
SELECT z.*,
       CAST(FLOOR((z.audit_rn - 1) / 100000) + 1 AS INT)          AS batch_id,
       'A168_HF9F_20260827_0900' AS run_id,
       '2026-08-27 09:00:00' AS snapshot_sync_time
FROM (
  SELECT y.*,
         ROW_NUMBER() OVER (ORDER BY y.`residual_b` ASC, y.`roi` DESC) AS audit_rn
  FROM (
    WITH
      x_ranked AS (
    SELECT b.bet01, b.bet03, b.bet04, b.bet05, b.bet09, b.bet11, b.bet13,
           b.bet15, b.bet16, b.bet17, b.bet18, b.bet19, b.bet20, b.bet21,
           b.bet22, b.bet23, b.bet24, b.bet25, b.bet26, b.bet27, b.bet38, b.bet39, b.category, b.commission,
           b.dt, b.eid, b.ip, b.validbet, b.updatetime, b.sync_time,
           ROW_NUMBER() OVER (
             PARTITION BY b.bet01
             ORDER BY b.updatetime DESC, b.sync_time DESC, b.dt DESC)      AS x_rn
    FROM ods_mariadb_2b.ods_a168_bet02 b
    WHERE b.dt >= '2026-03-21' AND b.dt < '2026-08-07'
      AND b.bet02 = '101'
      AND b.sync_time <= '2026-08-27 09:00:00'
  ),
    x_testagent AS (
    SELECT age001 AS agent_id FROM ods_mariadb_2b.ods_a168_agent WHERE age022 = '1'
  ),
    x_bs0 AS (
    SELECT b.bet05 AS x_member, b.eid AS x_dealer, b.bet39 AS x_table,
           b.bet03 AS x_shoe, b.ip AS x_ip, b.bet09 AS x_product, b.dt AS x_date,
           CONCAT_WS('|', b.bet03, b.bet04, b.bet39)                      AS x_round,
           CONCAT_WS('|', b.bet39, b.bet03)                               AS x_tblshoe,
           CAST(NULLIF(TRIM(b.bet04),'') AS INT)                          AS x_rno,
           CASE WHEN b.dt >= '2026-07-08' THEN 1 ELSE 0 END               AS x_rec,
           CASE WHEN TRIM(b.commission)='1' THEN 1 ELSE 0 END             AS x_freecomm,
           CAST(NULLIF(TRIM(b.bet13),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_stake,
           CAST(NULLIF(TRIM(b.validbet),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_valid,
           CAST(NULLIF(TRIM(b.bet16),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_rebate,
           CAST(NULLIF(TRIM(b.bet17),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_net,
           CAST(NULLIF(TRIM(b.bet15),'') AS DECIMAL(20,6))                AS x_rbpct,
           COALESCE(CAST(NULLIF(TRIM(b.bet23),'') AS DECIMAL(20,6)),0)   AS x_agpct,
          NULLIF(CAST(NULLIF(TRIM(b.bet23),'') AS DECIMAL(20,6)),0)     AS x_rate1,
          NULLIF(CAST(NULLIF(TRIM(b.bet24),'') AS DECIMAL(20,6)),0)     AS x_rate2,
          NULLIF(CAST(NULLIF(TRIM(b.bet25),'') AS DECIMAL(20,6)),0)     AS x_rate3,
          NULLIF(CAST(NULLIF(TRIM(b.bet26),'') AS DECIMAL(20,6)),0)     AS x_rate4,
          NULLIF(CAST(NULLIF(TRIM(b.bet27),'') AS DECIMAL(20,6)),0)     AS x_rate5,
          (CASE WHEN NULLIF(CAST(NULLIF(TRIM(b.bet22),'') AS BIGINT),0) IS NOT NULL THEN 5
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet21),'') AS BIGINT),0) IS NOT NULL THEN 4
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet20),'') AS BIGINT),0) IS NOT NULL THEN 3
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet19),'') AS BIGINT),0) IS NOT NULL THEN 2
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet18),'') AS BIGINT),0) IS NOT NULL THEN 1
                ELSE 0 END)                                             AS x_chain_depth,
           CASE WHEN COALESCE(t1.agent_id,t2.agent_id,t3.agent_id,
                              t4.agent_id,t5.agent_id) IS NOT NULL
                THEN 1 ELSE 0 END                                        AS f_testline
    FROM x_ranked b
    LEFT JOIN x_testagent t1 ON t1.agent_id = b.bet18
    LEFT JOIN x_testagent t2 ON t2.agent_id = b.bet19
    LEFT JOIN x_testagent t3 ON t3.agent_id = b.bet20
    LEFT JOIN x_testagent t4 ON t4.agent_id = b.bet21
    LEFT JOIN x_testagent t5 ON t5.agent_id = b.bet22
    WHERE b.x_rn = 1
      AND b.category='1' AND UPPER(TRIM(b.bet38))='N'
      AND CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8)) > 0
  ),
  x_mk AS (
    SELECT s.*,
           CASE WHEN s.f_testline = 0 THEN 1 ELSE 0 END                 AS is_clean
    FROM x_bs0 s
  ),
  x_agg AS (
    SELECT s.x_member                                                        AS x_key,
           COUNT(*) AS n_bets, COUNT(DISTINCT s.x_round) AS n_rounds,
           COUNT(DISTINCT s.x_date) AS active_days, COUNT(DISTINCT s.x_tblshoe) AS active_shoes,
           COUNT(DISTINCT CONCAT_WS('|', s.x_date, s.x_table)) AS active_sessions,
           COUNT(DISTINCT s.x_table) AS n_tables, COUNT(DISTINCT s.x_dealer) AS n_dealers,
           COUNT(DISTINCT s.x_ip) AS n_ips, COUNT(DISTINCT s.x_product) AS n_products,
           MIN(s.x_date) AS first_seen_d, MAX(s.x_date) AS last_seen_d,
           SUM(s.x_stake) AS stake, SUM(s.x_valid) AS valid, SUM(s.x_rebate) AS rebate,
           SUM(s.x_net) AS net, SUM(-s.x_net *(100.0-s.x_agpct)/100.0) AS agent_cost,
           AVG(100.0-s.x_agpct)                   AS agent_pct,
           AVG(s.x_agpct)                         AS company_retain_pct,
           SUM(-s.x_net *s.x_agpct/100.0)         AS agent_cost_a_legacy,
           SUM(s.x_valid*s.x_agpct/100.0)         AS agent_cost_valid_base_legacy,
          AVG(COALESCE(s.x_rate1,100)) AS retain_pct_lv1, AVG(COALESCE(s.x_rate2,100)) AS retain_pct_lv2,
          AVG(COALESCE(s.x_rate3,100)) AS retain_pct_lv3, AVG(COALESCE(s.x_rate4,100)) AS retain_pct_lv4,
          AVG(COALESCE(s.x_rate5,100)) AS retain_pct_lv5, AVG(s.x_chain_depth) AS chain_depth_avg,
          AVG(COALESCE(100.0-s.x_rate1,0)) AS agent_pct_lv1, AVG(COALESCE(100.0-s.x_rate2,0)) AS agent_pct_lv2,
          AVG(COALESCE(100.0-s.x_rate3,0)) AS agent_pct_lv3, AVG(COALESCE(100.0-s.x_rate4,0)) AS agent_pct_lv4,
          AVG(COALESCE(100.0-s.x_rate5,0)) AS agent_pct_lv5,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate1,0)/100.0)                        AS agent_cost_lv1,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate2,0)/100.0)                        AS agent_cost_lv2,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate3,0)/100.0)                        AS agent_cost_lv3,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate4,0)/100.0)                        AS agent_cost_lv4,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate5,0)/100.0)                        AS agent_cost_lv5,
          SUM(-s.x_net*(COALESCE(100.0-s.x_rate1,0)+COALESCE(100.0-s.x_rate2,0)
                       +COALESCE(100.0-s.x_rate3,0)+COALESCE(100.0-s.x_rate4,0)
                       +COALESCE(100.0-s.x_rate5,0))/100.0)                   AS agent_cost_chain_additive,
          SUM(-s.x_net*(1.0 - CAST(COALESCE(s.x_rate1,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate2,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate3,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate4,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate5,100) AS DOUBLE)/100.0))
                                                                       AS agent_cost_chain_nested,
           AVG(s.x_rbpct) AS rbpct, AVG(s.x_freecomm*1.0) AS freecomm_rate,
           PERCENTILE_APPROX(s.x_stake,0.25) AS p25, PERCENTILE_APPROX(s.x_stake,0.50) AS p50,
           PERCENTILE_APPROX(s.x_stake,0.75) AS p75, PERCENTILE_APPROX(s.x_stake,0.90) AS p90,
           PERCENTILE_APPROX(s.x_stake,0.95) AS p95, PERCENTILE_APPROX(s.x_stake,0.99) AS p99,
           PERCENTILE_APPROX(s.x_valid,0.50) AS p50_valid,
           PERCENTILE_APPROX(s.x_net,0.50)   AS p50_profit,
           SUM(CASE WHEN s.x_rec = 1 THEN s.x_stake ELSE 0 END) AS st_in,
           SUM(CASE WHEN s.x_rec = 1 THEN 1 ELSE 0 END)         AS nb_in,
           SUM(CASE WHEN s.x_rec = 1 THEN s.x_net ELSE 0 END)   AS net_in,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN s.x_stake ELSE 0 END) AS st_out,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN 1 ELSE 0 END)         AS nb_out,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN s.x_net ELSE 0 END)   AS net_out,
           SUM(CASE WHEN s.x_rec=1 THEN s.x_stake ELSE 0 END) AS st_rec,
           SUM(CASE WHEN s.x_rec=1 THEN 1 ELSE 0 END)         AS nb_rec
    FROM x_mk s
    WHERE s.is_clean = 1
      AND s.x_member IS NOT NULL AND TRIM(CAST(s.x_member AS STRING)) <> ''
    GROUP BY s.x_member
  ),
  x_win AS (
    SELECT            COUNT(*) AS n_bets, COUNT(DISTINCT s.x_round) AS n_rounds,
           COUNT(DISTINCT s.x_date) AS active_days, COUNT(DISTINCT s.x_tblshoe) AS active_shoes,
           COUNT(DISTINCT CONCAT_WS('|', s.x_date, s.x_table)) AS active_sessions,
           COUNT(DISTINCT s.x_table) AS n_tables, COUNT(DISTINCT s.x_dealer) AS n_dealers,
           COUNT(DISTINCT s.x_ip) AS n_ips, COUNT(DISTINCT s.x_product) AS n_products,
           MIN(s.x_date) AS first_seen_d, MAX(s.x_date) AS last_seen_d,
           SUM(s.x_stake) AS stake, SUM(s.x_valid) AS valid, SUM(s.x_rebate) AS rebate,
           SUM(s.x_net) AS net, SUM(-s.x_net *(100.0-s.x_agpct)/100.0) AS agent_cost,
           AVG(100.0-s.x_agpct)                   AS agent_pct,
           AVG(s.x_agpct)                         AS company_retain_pct,
           SUM(-s.x_net *s.x_agpct/100.0)         AS agent_cost_a_legacy,
           SUM(s.x_valid*s.x_agpct/100.0)         AS agent_cost_valid_base_legacy,
          AVG(COALESCE(s.x_rate1,100)) AS retain_pct_lv1, AVG(COALESCE(s.x_rate2,100)) AS retain_pct_lv2,
          AVG(COALESCE(s.x_rate3,100)) AS retain_pct_lv3, AVG(COALESCE(s.x_rate4,100)) AS retain_pct_lv4,
          AVG(COALESCE(s.x_rate5,100)) AS retain_pct_lv5, AVG(s.x_chain_depth) AS chain_depth_avg,
          AVG(COALESCE(100.0-s.x_rate1,0)) AS agent_pct_lv1, AVG(COALESCE(100.0-s.x_rate2,0)) AS agent_pct_lv2,
          AVG(COALESCE(100.0-s.x_rate3,0)) AS agent_pct_lv3, AVG(COALESCE(100.0-s.x_rate4,0)) AS agent_pct_lv4,
          AVG(COALESCE(100.0-s.x_rate5,0)) AS agent_pct_lv5,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate1,0)/100.0)                        AS agent_cost_lv1,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate2,0)/100.0)                        AS agent_cost_lv2,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate3,0)/100.0)                        AS agent_cost_lv3,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate4,0)/100.0)                        AS agent_cost_lv4,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate5,0)/100.0)                        AS agent_cost_lv5,
          SUM(-s.x_net*(COALESCE(100.0-s.x_rate1,0)+COALESCE(100.0-s.x_rate2,0)
                       +COALESCE(100.0-s.x_rate3,0)+COALESCE(100.0-s.x_rate4,0)
                       +COALESCE(100.0-s.x_rate5,0))/100.0)                   AS agent_cost_chain_additive,
          SUM(-s.x_net*(1.0 - CAST(COALESCE(s.x_rate1,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate2,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate3,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate4,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate5,100) AS DOUBLE)/100.0))
                                                                       AS agent_cost_chain_nested,
           AVG(s.x_rbpct) AS rbpct, AVG(s.x_freecomm*1.0) AS freecomm_rate,
           PERCENTILE_APPROX(s.x_stake,0.25) AS p25, PERCENTILE_APPROX(s.x_stake,0.50) AS p50,
           PERCENTILE_APPROX(s.x_stake,0.75) AS p75, PERCENTILE_APPROX(s.x_stake,0.90) AS p90,
           PERCENTILE_APPROX(s.x_stake,0.95) AS p95, PERCENTILE_APPROX(s.x_stake,0.99) AS p99,
           PERCENTILE_APPROX(s.x_valid,0.50) AS p50_valid,
           PERCENTILE_APPROX(s.x_net,0.50)   AS p50_profit,
           SUM(CASE WHEN s.x_rec = 1 THEN s.x_stake ELSE 0 END) AS st_in,
           SUM(CASE WHEN s.x_rec = 1 THEN 1 ELSE 0 END)         AS nb_in,
           SUM(CASE WHEN s.x_rec = 1 THEN s.x_net ELSE 0 END)   AS net_in,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN s.x_stake ELSE 0 END) AS st_out,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN 1 ELSE 0 END)         AS nb_out,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN s.x_net ELSE 0 END)   AS net_out,
           SUM(CASE WHEN s.x_rec=1 THEN s.x_stake ELSE 0 END) AS st_rec,
           SUM(CASE WHEN s.x_rec=1 THEN 1 ELSE 0 END)         AS nb_rec
    FROM x_mk s
    WHERE s.is_clean = 1
      AND s.x_member IS NOT NULL AND TRIM(CAST(s.x_member AS STRING)) <> ''
  ),
      q AS (
        WITH ev AS (                                                                                        -- 公共表表达式：开启中间结果集 ev——与 §TL-11 同源同窗（§TL-11c）
            SELECT  CAST(lmc02 AS STRING) AS member_id, CAST(lmc05 AS STRING) AS content                    -- 取值表达式：取用 lmc02（被改会员号）与 lmc05（变更内容串）
            FROM    ods_mariadb_2b.ods_a168_log_mem_change                                                  -- 取数来源：取自会员变更日志表
            WHERE   dt >= '2026-03-21' AND dt < '2026-08-07'                                                -- 过滤条件：限定 E1 全局窗，涉 dt（营业日）
              AND   CAST(lmc04 AS STRING) IN ('edit', 'changestatus')                                       -- 并列条件：只留配置修改与状态变更两类
        ),                                                                                                  -- 续行：收束上方的子查询或函数括号（§TL-11c）
        pieces AS (                                                                                         -- 公共表表达式：开启中间结果集 pieces——第一级：原始片段（§TL-11c）
            SELECT  e.member_id, TRIM(s.piece) AS piece                                                     -- 取值表达式：逐段去空白，产出「piece」
            FROM ev e, unnest(split(e.content, ';')) AS s(piece)                                            -- 行展开：以 unnest(split(…)) 把分号分隔的多段逐段成行
        ),                                                                                                  -- 续行：收束上方的子查询或函数括号（§TL-11c）
        enf AS (                                                                                            -- 公共表表达式：开启中间结果集 enf——第二级：已确认处置的解析事件（§TL-11c）
            SELECT  member_id, piece,                                                                       -- 取列：起始取列子句，本行先列 member_id, piece
                    CASE WHEN TRIM(SPLIT_PART(piece, '=>', 2)) IN ('N','0') THEN 'TIGHTEN'                  -- 取值表达式：方向判定起算——新值 N／0 为收紧
                         WHEN TRIM(SPLIT_PART(piece, '=>', 2)) IN ('Y','1') THEN 'RELEASE'                  -- 续行：新值 Y／1 为解除
                         ELSE 'OTHER' END                          AS direction                             -- 续行：产出「direction」
            FROM    pieces                                                                                  -- 取数来源：取自本条自建的中间结果集 pieces
            WHERE   piece LIKE '%=>%'                                                                       -- 过滤条件：须含箭头方为有效变更段
              AND ( piece LIKE 'mem016%' OR piece LIKE 'mem017%' )                                          -- 并列条件：只认语义已确认的两枚处置字段（mem015 已证非处置，封案）
        ),                                                                                                  -- 续行：收束上方的子查询或函数括号（§TL-11c）
        bl AS (                                                                                             -- 公共表表达式：开启中间结果集 bl——本方案口径的百家乐投注会员名单（§TL-11c）
            SELECT  DISTINCT CAST(bet05 AS STRING) AS member_id                                             -- 取值表达式：取用 bet05（会员号）去重，产出「member_id」
            FROM    ods_mariadb_2b.ods_a168_bet02                                                           -- 取数来源：取自注单明细表
            WHERE   dt >= '2026-03-21' AND dt < '2026-08-07'                                                -- 过滤条件：限定 E1 全局窗，涉 dt（营业日）
              AND sync_time <= '2026-08-27 09:00:00'
              AND   CAST(bet02 AS STRING) = '101'                                                           -- 并列条件：限定百家乐产品大类，涉 bet02（游戏类别）
        )                                                                                                   -- 续行：收束上方的子查询或函数括号（§TL-11c）
        SELECT  1 AS lvl, '① 原始片段（raw mutation pieces）' AS level_name,                                      -- 取值表达式：第一级序号与名称，产出「lvl」「level_name」
                COUNT(*) AS n_all,                                                                          -- 计数表达式：全体计数，产出「n_all」
                SUM(CASE WHEN bl.member_id IS NULL THEN 0 ELSE 1 END) AS n_baccarat,                        -- 聚合：其中百家乐会员之计数，产出「n_baccarat」
                COUNT(DISTINCT p.member_id) AS n_member_all,                                                -- 计数表达式：涉及会员数（去重），产出「n_member_all」
                COUNT(DISTINCT CASE WHEN bl.member_id IS NOT NULL THEN p.member_id END) AS n_member_bac,    -- 计数表达式：其中百家乐会员数，产出「n_member_bac」
                '变更日志 content 按分号拆开后的每一段' AS definition                                                     -- 取值表达式：本级定义，产出「definition」——逐级递减须由定义解释得通
        FROM        pieces p                                                                                -- 取数来源：取自本条自建的中间结果集 pieces
        LEFT JOIN   bl ON bl.member_id = p.member_id                                                        -- 左连接：取自本条自建的中间结果集 bl，连接键为 member_id（会员号）
        UNION ALL                                                                                           -- 集合运算：纵向拼接下一级
        SELECT  2, '② 处置事件（enforcement events）',                                                            -- 取值表达式：第二级序号与名称
                COUNT(*),                                                                                   -- 计数表达式：全体计数
                SUM(CASE WHEN bl.member_id IS NULL THEN 0 ELSE 1 END),                                      -- 聚合：其中百家乐会员之计数
                COUNT(DISTINCT e.member_id),                                                                -- 计数表达式：涉及会员数（去重）
                COUNT(DISTINCT CASE WHEN bl.member_id IS NOT NULL THEN e.member_id END),                    -- 计数表达式：其中百家乐会员数
                '解析成功且语义经字典确认为处置者（mem016／mem017），含收紧与解除两向'                                                  -- 取值表达式：本级定义
        FROM        enf e                                                                                   -- 取数来源：取自本条自建的中间结果集 enf
        LEFT JOIN   bl ON bl.member_id = e.member_id                                                        -- 左连接：取自本条自建的中间结果集 bl，连接键为 member_id（会员号）
        UNION ALL                                                                                           -- 集合运算：纵向拼接下一级
        SELECT  3, '③ 收紧事件（episode starts）',                                                                -- 取值表达式：第三级序号与名称
                COUNT(*),                                                                                   -- 计数表达式：全体计数
                SUM(CASE WHEN bl.member_id IS NULL THEN 0 ELSE 1 END),                                      -- 聚合：其中百家乐会员之计数
                COUNT(DISTINCT e.member_id),                                                                -- 计数表达式：涉及会员数（去重）
                COUNT(DISTINCT CASE WHEN bl.member_id IS NOT NULL THEN e.member_id END),                    -- 计数表达式：其中百家乐会员数——★ 此即处置节口径的唯一处置会员数
                '处置事件中方向为收紧者；每一条起一个处置节，故其数即处置节数'                                                            -- 取值表达式：本级定义
        FROM        enf e                                                                                   -- 取数来源：取自本条自建的中间结果集 enf
        LEFT JOIN   bl ON bl.member_id = e.member_id                                                        -- 左连接：取自本条自建的中间结果集 bl，连接键为 member_id（会员号）
        WHERE   e.direction = 'TIGHTEN'                                                                     -- 过滤条件：只留收紧方向
        UNION ALL                                                                                           -- 集合运算：纵向拼接下一级
        SELECT  4, '④ 解除事件（episode ends）',                                                                  -- 取值表达式：第四级序号与名称
                COUNT(*),                                                                                   -- 计数表达式：全体计数
                SUM(CASE WHEN bl.member_id IS NULL THEN 0 ELSE 1 END),                                      -- 聚合：其中百家乐会员之计数
                COUNT(DISTINCT e.member_id),                                                                -- 计数表达式：涉及会员数（去重）
                COUNT(DISTINCT CASE WHEN bl.member_id IS NOT NULL THEN e.member_id END),                    -- 计数表达式：其中百家乐会员数
                '处置事件中方向为解除者；未必与收紧一一对应，故删失由此而生'                                                             -- 取值表达式：本级定义
        FROM        enf e                                                                                   -- 取数来源：取自本条自建的中间结果集 enf
        LEFT JOIN   bl ON bl.member_id = e.member_id                                                        -- 左连接：取自本条自建的中间结果集 bl，连接键为 member_id（会员号）
        WHERE   e.direction = 'RELEASE'                                                                     -- 过滤条件：只留解除方向
        UNION ALL                                                                                           -- 集合运算：纵向拼接下一级
        SELECT  5, '⑤ 左截断：只见解除而未见收紧之会员',                                                                    -- 取值表达式：第五级——★ 2026-08-11 增，解释 ④ 多于 ③ 之差
                0, 0,                                                                                       -- 计数表达式：本级只计会员，条数置零以免与事件级混淆
                COUNT(DISTINCT r.member_id),                                                                -- 计数表达式：全体——其收紧发生于窗口之前，本窗只见尾巴
                COUNT(DISTINCT CASE WHEN bl.member_id IS NOT NULL THEN r.member_id END),                    -- 计数表达式：其中百家乐会员数
                '窗内有解除而无收紧者：处置起于观察窗之前（左截断），无 T0 故不入处置节，亦不入 KM'                                              -- 取值表达式：本级定义——**须明写，否则 ④ 与 ③ 之差无从解释**
        FROM        ( SELECT DISTINCT member_id FROM enf WHERE direction = 'RELEASE' ) r                    -- 取数来源：解除方会员集合
        LEFT JOIN   ( SELECT DISTINCT member_id FROM enf WHERE direction = 'TIGHTEN' ) t                    -- 左连接：收紧方会员集合
               ON   t.member_id = r.member_id                                                               -- 连接键：同一会员
        LEFT JOIN   bl ON bl.member_id = r.member_id                                                        -- 左连接：取自本条自建的中间结果集 bl，连接键为 member_id（会员号）
        WHERE   t.member_id IS NULL                                                                         -- 过滤条件：只留在收紧集合中查无此人者——即左截断
        UNION ALL                                                                                           -- 集合运算：纵向拼接下一级
        SELECT  6, '⑥ 语义待定：解析成功而列义未经字典确认',                                                                  -- 取值表达式：第六级——★ 2026-08-11 增，与 §TL-11b 的 semantic_status 对齐
                COUNT(*),                                                                                   -- 计数表达式：全体计数
                SUM(CASE WHEN bl.member_id IS NULL THEN 0 ELSE 1 END),                                      -- 聚合：其中百家乐会员之计数
                COUNT(DISTINCT q.member_id),                                                                -- 计数表达式：涉及会员数（去重）
                COUNT(DISTINCT CASE WHEN bl.member_id IS NOT NULL THEN q.member_id END),                    -- 计数表达式：其中百家乐会员数
                '含箭头而非 mem015／mem016／mem017 者，如 mem020 与 101-mem015——PENDING，不入处置总体'                        -- 取值表达式：本级定义
        FROM        pieces q                                                                                -- 取数来源：取自本条自建的中间结果集 pieces
        LEFT JOIN   bl ON bl.member_id = q.member_id                                                        -- 左连接：取自本条自建的中间结果集 bl，连接键为 member_id（会员号）
        WHERE   q.piece LIKE '%=>%'                                                                         -- 过滤条件：须为有效变更段
          AND   q.piece NOT LIKE 'mem015%'                                                                  -- 并列条件：mem015 已封案（login_error），另计
          AND   q.piece NOT LIKE 'mem016%'                                                                  -- 并列条件：mem016 已确认为处置，另计
          AND   q.piece NOT LIKE 'mem017%'                                                                  -- 并列条件：mem017 已确认为处置，另计
      )
    SELECT q.*,
           -- 一·经济层
           ROUND(e.stake,4) AS stake, ROUND(e.valid,4) AS valid_bet,
           ROUND(-e.net,4) AS profit, e.n_bets, e.n_rounds,
           ROUND(e.net/NULLIF(e.stake,0),8) AS roi,
           ROUND(e.net_in/NULLIF(e.st_in,0),8) AS roi_post,
           ROUND(e.net_out/NULLIF(e.st_out,0),8) AS roi_non_post,
           ROUND((e.net-e.rebate)/NULLIF(e.stake,0),8) AS roi_ex_rebate,
           ROUND(e.net,4) AS roi_numerator, ROUND(e.stake,4) AS roi_denominator,
           CASE WHEN e.stake IS NULL THEN 'NULL_DENOM' WHEN e.stake<=0 THEN 'ZERO_DENOM'
                WHEN e.n_bets<30 THEN 'THIN_EXPOSURE' ELSE 'OK' END AS roi_denominator_status,
           ROUND(e.rebate,4) AS rebate_cost, ROUND(e.agent_cost,4)                           AS cost_complement_b,
       ROUND(e.agent_pct,4)                            AS pct_complement,
       ROUND(e.company_retain_pct,4)                   AS pct_top_bet23,
       'AG03-UNRESOLVED'                                     AS agent_formula_version,
      'ALL5_LEVELS_bet23_to_bet27'                    AS agent_level_scope,
      ROUND(e.agent_cost_lv1,4) AS agent_cost_lv1, ROUND(e.agent_cost_lv2,4) AS agent_cost_lv2,
      ROUND(e.agent_cost_lv3,4) AS agent_cost_lv3, ROUND(e.agent_cost_lv4,4) AS agent_cost_lv4,
      ROUND(e.agent_cost_lv5,4) AS agent_cost_lv5,
      ROUND(e.agent_pct_lv1,6) AS agent_pct_lv1, ROUND(e.agent_pct_lv2,6) AS agent_pct_lv2,
      ROUND(e.agent_pct_lv3,6) AS agent_pct_lv3, ROUND(e.agent_pct_lv4,6) AS agent_pct_lv4,
      ROUND(e.agent_pct_lv5,6) AS agent_pct_lv5,
      ROUND(e.retain_pct_lv1,6) AS retain_pct_lv1, ROUND(e.retain_pct_lv2,6) AS retain_pct_lv2,
      ROUND(e.retain_pct_lv3,6) AS retain_pct_lv3, ROUND(e.retain_pct_lv4,6) AS retain_pct_lv4,
      ROUND(e.retain_pct_lv5,6) AS retain_pct_lv5, ROUND(e.chain_depth_avg,4) AS chain_depth_avg,
      ROUND(e.agent_cost_chain_additive,4)            AS agent_cost_chain_additive,
      ROUND(e.agent_cost_chain_nested,4)              AS agent_cost_chain_nested,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_additive,4) AS residual_chain_additive,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_nested,4)   AS residual_chain_nested,
      'PENDING_AG03'                                  AS decision_status,
      'FALSE'                                         AS admit_to_risk_decision,
      'NOT_FOR_ENFORCEMENT'                           AS deliverable_class,
       ROUND(e.agent_cost_a_legacy,4)                  AS agent_cost_a_legacy,
       ROUND(e.agent_cost_valid_base_legacy,4)         AS agent_cost_valid_base_legacy,
           ROUND(-e.net-e.rebate,4)                        AS ngr,
       ROUND(-e.net-e.rebate-e.agent_cost,4)           AS residual_b,
       ROUND(-e.net-e.rebate-e.agent_cost_a_legacy,4)  AS residual_a,
           ROUND((-e.net-e.rebate)/NULLIF(e.stake,0),8)    AS ngr_rate,
       ROUND((-e.net-e.rebate-e.agent_cost)/NULLIF(e.stake,0),8)   AS residual_b_rate,
      -- 【HF9c · canonical accounting contract】
      --   以下 canonical 字段只增加明确 scope；不删除、不覆盖既有字段。
      --   formal_bet23_* 保持 HF9b 当前生产公式及其 NULL/0 语义；
      --   lv1~lv5 / additive / nested 则分别采用各自原始 e.* 成本字段，
      --   rate 一律从未舍入的 e.* 分子 / e.stake 计算，禁止由展示值反算。
      ROUND(e.agent_cost,4) AS agent_cost_bet23_formal_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost,4) AS net_margin_bet23_formal_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost)/NULLIF(e.stake,0),8) AS net_margin_bet23_formal_rate_canonical,
      ROUND(e.agent_cost_lv1,4) AS agent_cost_lv1_bet23_canonical,
      ROUND(e.agent_cost_lv2,4) AS agent_cost_lv2_bet24_canonical,
      ROUND(e.agent_cost_lv3,4) AS agent_cost_lv3_bet25_canonical,
      ROUND(e.agent_cost_lv4,4) AS agent_cost_lv4_bet26_canonical,
      ROUND(e.agent_cost_lv5,4) AS agent_cost_lv5_bet27_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_lv1,4) AS net_margin_lv1_bet23_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_lv1)/NULLIF(e.stake,0),8) AS net_margin_lv1_bet23_rate_canonical,
      ROUND(e.agent_cost_chain_additive,4) AS agent_cost_chain_additive_canonical,
      ROUND(e.agent_cost_chain_nested,4) AS agent_cost_chain_nested_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_additive,4) AS net_margin_chain_additive_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_nested,4) AS net_margin_chain_nested_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_chain_additive)/NULLIF(e.stake,0),8) AS net_margin_chain_additive_rate_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_chain_nested)/NULLIF(e.stake,0),8) AS net_margin_chain_nested_rate_canonical,
       ROUND((-e.net-e.rebate-e.agent_cost_a_legacy)/NULLIF(e.stake,0),8) AS residual_a_rate,
           -- 二·分布层
           ROUND(e.stake/NULLIF(e.n_bets,0),4) AS avg_stake_per_bet,
           ROUND(e.valid/NULLIF(e.n_rounds,0),4) AS avg_valid_bet_per_round,
           ROUND(-e.net/NULLIF(e.n_rounds,0),4) AS avg_profit_per_round,
           ROUND(-e.net/NULLIF(e.active_days,0),4) AS avg_profit_per_day,
           ROUND(-e.net/NULLIF(e.active_shoes,0),4) AS avg_profit_per_shoe,
           ROUND(e.stake/NULLIF(e.active_days,0),4) AS avg_stake_per_active_day,
           ROUND(e.n_rounds*1.0/NULLIF(e.active_days,0),4) AS avg_rounds_per_active_day,
           ROUND(e.st_in/NULLIF(e.nb_in,0),4) AS avg_stake_post,
           ROUND(e.st_out/NULLIF(e.nb_out,0),4) AS avg_stake_non_post,
           ROUND(e.p25,4) AS p25_stake, ROUND(e.p50,4) AS p50_stake, ROUND(e.p75,4) AS p75_stake,
           ROUND(e.p90,4) AS p90_stake, ROUND(e.p95,4) AS p95_stake, ROUND(e.p99,4) AS p99_stake,
           ROUND(e.p50_valid,4) AS p50_valid_bet, ROUND(e.p50_profit,4) AS p50_profit,
           ROUND(e.p95/NULLIF(e.p50,0),6) AS p95_over_p50,
           ROUND(e.p99/NULLIF(e.p50,0),6) AS p99_over_p50,
           ROUND((e.stake/NULLIF(e.n_bets,0))/NULLIF(e.p50,0),6) AS avg_over_p50,
           -- 三·关系层
           e.n_tables AS common_table_count, e.n_dealers AS common_dealer_count,
           e.n_ips AS common_ip_count, e.n_products AS common_product_count,
           ROUND(e.st_in/NULLIF(e.stake,0),8) AS share_post,
           -- 四·rate 层
           ROUND(-e.net/NULLIF(e.stake,0),8) AS hold_rate,
           ROUND(-e.net_in/NULLIF(e.st_in,0),8) AS hold_rate_post,
           ROUND(e.rebate/NULLIF(e.valid,0),8) AS rebate_rate_actual,
           ROUND(e.rbpct,6) AS rebate_pct_config,
           ROUND(e.valid/NULLIF(e.stake,0),6) AS turnover_multiple,
           ROUND(e.freecomm_rate,6) AS free_comm_rate,
           ROUND(e.net_in/NULLIF(e.st_in,0)-e.net_out/NULLIF(e.st_out,0),8) AS roi_delta_post,
           -- 五·动态层
           e.first_seen_d AS first_seen, e.last_seen_d AS last_seen,
           e.active_days, e.active_shoes, e.active_sessions,
           DATEDIFF(e.last_seen_d, e.first_seen_d)+1 AS span_days,
           ROUND(e.active_days*1.0/NULLIF(DATEDIFF(e.last_seen_d,e.first_seen_d)+1,0),6) AS persistence,
           ROUND((e.st_in/NULLIF(e.nb_in,0))/NULLIF(e.st_out/NULLIF(e.nb_out,0),0),6) AS ramp_post,
           ROUND((e.st_rec/NULLIF(e.nb_rec,0))/NULLIF(e.stake/NULLIF(e.n_bets,0),0),6) AS ramp_recent,
           ROUND((e.st_rec/NULLIF(e.stake,0))/0.30,6) AS stake_ramp,
           -- 六·决策层（HF9g-P5 · D-14 斧正 —— 本件属【全窗基线族】，相对刻度与决策标签一律 NULL）
           --   病灶：x_win 系全窗单行聚合（无 GROUP BY，恒 1 行，此为设计使然，非缺陷），
           --         经 CROSS JOIN 接入后 e.* 全行同值；六层之 NTILE / PERCENT_RANK 施于常数即退化，
           --         PERCENT_RANK 恒 0 ⇒ action_priority 恒判 A，全件 100% 误标。
           --   ★ 斧正原则：不给 x_win 补 GROUP BY —— 那会改变其「全窗基线」语义，属退化。
           --     正解与 #018 之 G-05／G-06 同治：范围外之行不得接受任何下游评分与决策标签。
           --   ★ 本件之 e.* 仍照常供其它列作全窗基线使用，仅六层相对刻度与决策标签置 NULL。
           CAST(NULL AS INT)                                              AS vip_tier,                        -- 空值取值：全窗基线族无实体可分档，置 NULL（NULL＝不适用，非 0）
           CAST(NULL AS DOUBLE)                                           AS economic_value,                  -- 空值取值：同上，禁以常数百分位冒充经济价值
           CAST(NULL AS DOUBLE)                                           AS roi_pr_global,                   -- 空值取值：同上
           CAST(NULL AS DOUBLE)                                           AS risk_value,                      -- 空值取值：兼容列，同上
           CAST(NULL AS DOUBLE)                                           AS pr_stake,                        -- 空值取值：兼容列，同上
           CAST(NULL AS DOUBLE)                                           AS pr_global,                       -- 空值取值：同上
           CAST(NULL AS DOUBLE)                                           AS pr_qualified,                    -- 空值取值：同上
           'GLOBAL_BASELINE_NO_ENTITY_RANKING'                            AS pr_qualified_population,         -- 字面取值：血统 —— 明示本件为全窗基线族，无实体排序总体
           CAST(NULL AS BIGINT)                                           AS pr_global_population_n,          -- 空值取值：血统 —— 不适用
           CAST(NULL AS BIGINT)                                           AS pr_qualified_population_n,       -- 空值取值：血统 —— 不适用
           'NOT_APPLICABLE_GLOBAL_BASELINE'                               AS pr_calculation_method,           -- 字面取值：血统 —— 算法不适用
           'HF9g-P5'                                                      AS pr_calculation_version,          -- 字面取值：血统 —— 算法版本
           CAST(NULL AS STRING)                                           AS evidence_flag,                   -- 空值取值：证据旗标不适用于全窗基线
           CAST(NULL AS STRING)                                           AS evidence_rate,                   -- 空值取值：同上
           CAST(NULL AS DOUBLE)                                           AS hold_ci_halfwidth_approx,        -- 空值取值：同上
           'X 全窗基线 · 不参与实体赏罚'                                    AS action_priority                  -- 字面取值：★ D-14 斧正 —— 本族恒不入赏罚，取代原 100% 误标之「A」
    FROM q
    CROSS JOIN x_win e
  ) y
) z
-- ── 逐批 WHERE 阶梯（★ 口诀：上界 ＝ 下界 ＋ 100000，两数同进）──
--    本件 T_true 未测，无需先跑 T_true；以 0 / 100000 控制本批返回区间，末批由实际行数 < 100000 判定
--    WHERE z.audit_rn >        0 AND z.audit_rn <=   100000   -- 第 1 批
--    WHERE z.audit_rn >   100000 AND z.audit_rn <=   200000   -- 第 2 批
--    WHERE z.audit_rn >   200000 AND z.audit_rn <=   300000   -- 第 3 批
--    WHERE z.audit_rn >   300000 AND z.audit_rn <=   400000   -- 第 4 批
--    WHERE z.audit_rn >   400000 AND z.audit_rn <=   500000   -- 第 5 批
--    WHERE z.audit_rn >   500000 AND z.audit_rn <=   600000   -- 第 6 批
--    WHERE z.audit_rn >   600000 AND z.audit_rn <=   700000   -- 第 7 批
--    …余批类推。第 k 批：WHERE z.audit_rn > (k-1)*100000 AND z.audit_rn <= k*100000
--    某批返回 < 100000 行即为末批，其后不再取。
--
--    ⚠ 常见误写（务必避开）：只推下界而上界不动 ——
--        WHERE z.audit_rn > 100000 AND z.audit_rn <= 100000   ← 自相矛盾，恒为假，返回空集
--        WHERE z.audit_rn > 200000 AND z.audit_rn <= 100000   ← 同上，空集
--      两个数必须**同时**前进，且始终相差 100000。
--      下界 ＝ 上一批之上界；上界 ＝ 本批之上界。
WHERE z.audit_rn > 0 AND z.audit_rn <= 100000 -- ★ HF9c 本批区间
ORDER BY z.audit_rn;


-- ══════════════════════════════════════════════════════════════════════════════════════════════
--  97. TL14_limit_treatment.csv   [总包行 5058~5136 · 原 15 列 ＋六层约 60 列]
--     典型学：M09 处置限额　派生旗标：post（s.x_rec = 1 · 仅供 CASE 条件聚合，全包无任何 WHERE/AND/HAVING 以此过滤）　连接：q.`member_id`
-- ══════════════════════════════════════════════════════════════════════════════════════════════
-- ── ① 先跑 T_true 留档（不足 100000 者一次导全，不必分批）──
-- ── ① T_true：HF9c 不再强制预跑完整 COUNT。
--    本批实际返回行数 < 100000 即判定为末批；全批完成后以各批 n_rows / audit_rn 范围核对总量。

-- ── ② 分批取数：第 1 批。第 k 批只改末行两数为 (k-1)*100000 与 k*100000 ──
--    审计字段二（REDTEAM 2026-08-24 裁定 · 四锁）：
--      audit_rn  全局观测坐标 —— 由**与原版审计版逐字同一**之排序键所生，两版可逐行对账
--      batch_id  物理分批信息 —— 该行所属批次，由 audit_rn 算得，非引擎所赋
--    ★ 锁三：二者皆为审计字段，**不得进入任何业务指标计算**。
--    ★ 锁四：两版经 audit_rn 逐行字段核验后，方可宣布输出完全一致。

-- ── ③ 每批取回后自证四数（任一不符即停手回报，禁止放行）──
--    n_rows        = COUNT(*)      须等于 COUNT(DISTINCT audit_rn)   （批内无重复）
--    audit_rn_min  = MIN(audit_rn) 须等于 (k-1)*100000 + 1           （与上批严丝合缝）
--    audit_rn_max  = MAX(audit_rn) 须等于 min + n_rows - 1           （批内无缺口）
--    全批取毕再验：各批 audit_rn 之并集 = 1 .. T_true，无缺号、无重号。
--     ★ 首行＝平台真净亏最多者（已扣退水与代理占成）。
--
SELECT z.*,
       CAST(FLOOR((z.audit_rn - 1) / 100000) + 1 AS INT)          AS batch_id,
       'A168_HF9F_20260827_0900' AS run_id,
       '2026-08-27 09:00:00' AS snapshot_sync_time
FROM (
  SELECT y.*,
         ROW_NUMBER() OVER (ORDER BY y.`residual_b` ASC, y.`roi` DESC, y.`member_id`, y.`action_date`, y.`action_time`, y.`operator_id`, y.`operator_lv`, y.`grp_before`, y.`grp_after`, y.`max_hi_before`, y.`max_hi_after`, y.`n_grp_before`, y.`n_grp_after`, y.`direction`, y.`has_zero_group`, y.`is_baccarat_member`, y.`filter_rule_version`) AS audit_rn
  FROM (
    WITH
      x_ranked AS (
    SELECT b.bet01, b.bet03, b.bet04, b.bet05, b.bet09, b.bet11, b.bet13,
           b.bet15, b.bet16, b.bet17, b.bet18, b.bet19, b.bet20, b.bet21,
           b.bet22, b.bet23, b.bet24, b.bet25, b.bet26, b.bet27, b.bet38, b.bet39, b.category, b.commission,
           b.dt, b.eid, b.ip, b.validbet, b.updatetime, b.sync_time,
           ROW_NUMBER() OVER (
             PARTITION BY b.bet01
             ORDER BY b.updatetime DESC, b.sync_time DESC, b.dt DESC)      AS x_rn
    FROM ods_mariadb_2b.ods_a168_bet02 b
    WHERE b.dt >= '2026-03-21' AND b.dt < '2026-08-07'
      AND b.bet02 = '101'
      AND b.sync_time <= '2026-08-27 09:00:00'
  ),
    x_testagent AS (
    SELECT age001 AS agent_id FROM ods_mariadb_2b.ods_a168_agent WHERE age022 = '1'
  ),
    x_bs0 AS (
    SELECT b.bet05 AS x_member, b.eid AS x_dealer, b.bet39 AS x_table,
           b.bet03 AS x_shoe, b.ip AS x_ip, b.bet09 AS x_product, b.dt AS x_date,
           CONCAT_WS('|', b.bet03, b.bet04, b.bet39)                      AS x_round,
           CONCAT_WS('|', b.bet39, b.bet03)                               AS x_tblshoe,
           CAST(NULLIF(TRIM(b.bet04),'') AS INT)                          AS x_rno,
           CASE WHEN b.dt >= '2026-07-08' THEN 1 ELSE 0 END               AS x_rec,
           CASE WHEN TRIM(b.commission)='1' THEN 1 ELSE 0 END             AS x_freecomm,
           CAST(NULLIF(TRIM(b.bet13),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_stake,
           CAST(NULLIF(TRIM(b.validbet),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_valid,
           CAST(NULLIF(TRIM(b.bet16),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_rebate,
           CAST(NULLIF(TRIM(b.bet17),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_net,
           CAST(NULLIF(TRIM(b.bet15),'') AS DECIMAL(20,6))                AS x_rbpct,
           COALESCE(CAST(NULLIF(TRIM(b.bet23),'') AS DECIMAL(20,6)),0)   AS x_agpct,
          NULLIF(CAST(NULLIF(TRIM(b.bet23),'') AS DECIMAL(20,6)),0)     AS x_rate1,
          NULLIF(CAST(NULLIF(TRIM(b.bet24),'') AS DECIMAL(20,6)),0)     AS x_rate2,
          NULLIF(CAST(NULLIF(TRIM(b.bet25),'') AS DECIMAL(20,6)),0)     AS x_rate3,
          NULLIF(CAST(NULLIF(TRIM(b.bet26),'') AS DECIMAL(20,6)),0)     AS x_rate4,
          NULLIF(CAST(NULLIF(TRIM(b.bet27),'') AS DECIMAL(20,6)),0)     AS x_rate5,
          (CASE WHEN NULLIF(CAST(NULLIF(TRIM(b.bet22),'') AS BIGINT),0) IS NOT NULL THEN 5
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet21),'') AS BIGINT),0) IS NOT NULL THEN 4
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet20),'') AS BIGINT),0) IS NOT NULL THEN 3
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet19),'') AS BIGINT),0) IS NOT NULL THEN 2
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet18),'') AS BIGINT),0) IS NOT NULL THEN 1
                ELSE 0 END)                                             AS x_chain_depth,
           CASE WHEN COALESCE(t1.agent_id,t2.agent_id,t3.agent_id,
                              t4.agent_id,t5.agent_id) IS NOT NULL
                THEN 1 ELSE 0 END                                        AS f_testline
    FROM x_ranked b
    LEFT JOIN x_testagent t1 ON t1.agent_id = b.bet18
    LEFT JOIN x_testagent t2 ON t2.agent_id = b.bet19
    LEFT JOIN x_testagent t3 ON t3.agent_id = b.bet20
    LEFT JOIN x_testagent t4 ON t4.agent_id = b.bet21
    LEFT JOIN x_testagent t5 ON t5.agent_id = b.bet22
    WHERE b.x_rn = 1
      AND b.category='1' AND UPPER(TRIM(b.bet38))='N'
      AND CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8)) > 0
  ),
  x_mk AS (
    SELECT s.*,
           CASE WHEN s.f_testline = 0 THEN 1 ELSE 0 END                 AS is_clean
    FROM x_bs0 s
  ),
  x_agg AS (
    SELECT s.x_member                                                        AS x_key,
           COUNT(*) AS n_bets, COUNT(DISTINCT s.x_round) AS n_rounds,
           COUNT(DISTINCT s.x_date) AS active_days, COUNT(DISTINCT s.x_tblshoe) AS active_shoes,
           COUNT(DISTINCT CONCAT_WS('|', s.x_date, s.x_table)) AS active_sessions,
           COUNT(DISTINCT s.x_table) AS n_tables, COUNT(DISTINCT s.x_dealer) AS n_dealers,
           COUNT(DISTINCT s.x_ip) AS n_ips, COUNT(DISTINCT s.x_product) AS n_products,
           MIN(s.x_date) AS first_seen_d, MAX(s.x_date) AS last_seen_d,
           SUM(s.x_stake) AS stake, SUM(s.x_valid) AS valid, SUM(s.x_rebate) AS rebate,
           SUM(s.x_net) AS net, SUM(-s.x_net *(100.0-s.x_agpct)/100.0) AS agent_cost,
           AVG(100.0-s.x_agpct)                   AS agent_pct,
           AVG(s.x_agpct)                         AS company_retain_pct,
           SUM(-s.x_net *s.x_agpct/100.0)         AS agent_cost_a_legacy,
           SUM(s.x_valid*s.x_agpct/100.0)         AS agent_cost_valid_base_legacy,
          AVG(COALESCE(s.x_rate1,100)) AS retain_pct_lv1, AVG(COALESCE(s.x_rate2,100)) AS retain_pct_lv2,
          AVG(COALESCE(s.x_rate3,100)) AS retain_pct_lv3, AVG(COALESCE(s.x_rate4,100)) AS retain_pct_lv4,
          AVG(COALESCE(s.x_rate5,100)) AS retain_pct_lv5, AVG(s.x_chain_depth) AS chain_depth_avg,
          AVG(COALESCE(100.0-s.x_rate1,0)) AS agent_pct_lv1, AVG(COALESCE(100.0-s.x_rate2,0)) AS agent_pct_lv2,
          AVG(COALESCE(100.0-s.x_rate3,0)) AS agent_pct_lv3, AVG(COALESCE(100.0-s.x_rate4,0)) AS agent_pct_lv4,
          AVG(COALESCE(100.0-s.x_rate5,0)) AS agent_pct_lv5,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate1,0)/100.0)                        AS agent_cost_lv1,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate2,0)/100.0)                        AS agent_cost_lv2,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate3,0)/100.0)                        AS agent_cost_lv3,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate4,0)/100.0)                        AS agent_cost_lv4,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate5,0)/100.0)                        AS agent_cost_lv5,
          SUM(-s.x_net*(COALESCE(100.0-s.x_rate1,0)+COALESCE(100.0-s.x_rate2,0)
                       +COALESCE(100.0-s.x_rate3,0)+COALESCE(100.0-s.x_rate4,0)
                       +COALESCE(100.0-s.x_rate5,0))/100.0)                   AS agent_cost_chain_additive,
          SUM(-s.x_net*(1.0 - CAST(COALESCE(s.x_rate1,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate2,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate3,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate4,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate5,100) AS DOUBLE)/100.0))
                                                                       AS agent_cost_chain_nested,
           AVG(s.x_rbpct) AS rbpct, AVG(s.x_freecomm*1.0) AS freecomm_rate,
           PERCENTILE_APPROX(s.x_stake,0.25) AS p25, PERCENTILE_APPROX(s.x_stake,0.50) AS p50,
           PERCENTILE_APPROX(s.x_stake,0.75) AS p75, PERCENTILE_APPROX(s.x_stake,0.90) AS p90,
           PERCENTILE_APPROX(s.x_stake,0.95) AS p95, PERCENTILE_APPROX(s.x_stake,0.99) AS p99,
           PERCENTILE_APPROX(s.x_valid,0.50) AS p50_valid,
           PERCENTILE_APPROX(s.x_net,0.50)   AS p50_profit,
           SUM(CASE WHEN s.x_rec = 1 THEN s.x_stake ELSE 0 END) AS st_in,
           SUM(CASE WHEN s.x_rec = 1 THEN 1 ELSE 0 END)         AS nb_in,
           SUM(CASE WHEN s.x_rec = 1 THEN s.x_net ELSE 0 END)   AS net_in,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN s.x_stake ELSE 0 END) AS st_out,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN 1 ELSE 0 END)         AS nb_out,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN s.x_net ELSE 0 END)   AS net_out,
           SUM(CASE WHEN s.x_rec=1 THEN s.x_stake ELSE 0 END) AS st_rec,
           SUM(CASE WHEN s.x_rec=1 THEN 1 ELSE 0 END)         AS nb_rec
    FROM x_mk s
    WHERE s.is_clean = 1
      AND s.x_member IS NOT NULL AND TRIM(CAST(s.x_member AS STRING)) <> ''
    GROUP BY s.x_member
  ),
      q AS (
        WITH dict AS (                                                                                      -- 公共表表达式：开启中间结果集 dict——百家乐限额组字典（§TL-14）
            SELECT  CAST(id AS STRING)                            AS grp_id,                                -- 取值表达式：取用组号并转字符，产出「grp_id」——与变更日志内的字面值同型方能连上
                    CAST(NULLIF(TRIM(SPLIT_PART(set01, ',', 1)),'') AS DECIMAL(20,2)) AS lo,                -- 取值表达式：set01 逗号前段为下限，产出「lo」
                    CAST(NULLIF(TRIM(SPLIT_PART(set01, ',', 2)),'') AS DECIMAL(20,2)) AS hi                 -- 取值表达式：set01 逗号后段为上限，产出「hi」——方向判定之凭据
            FROM    ods_mariadb_2b.ods_a168_bet_limit_default                                               -- 取数来源：取自限额组定义表（§TL-13 查得）
            WHERE   gtype = '101'                                                                           -- 过滤条件：限定百家乐，与本方案 bet02 = '101' 同口径
              AND   dt = ( SELECT MAX(dt) FROM ods_mariadb_2b.ods_a168_bet_limit_default )                  -- 并列条件：只取最新一版快照，免同组多版重复
        ),                                                                                                  -- 续行：收束上方的子查询或函数括号（§TL-14）
        ev AS (                                                                                             -- 公共表表达式：开启中间结果集 ev——变更日志原始事件，口径与 §TL-11 一致（§TL-14）
            SELECT  CAST(lmc02 AS STRING)                         AS member_id,                             -- 取值表达式：取用 lmc02（被改会员号），产出「member_id」
                    SUBSTR(CAST(lmc08 AS STRING), 1, 10)          AS action_date,                           -- 取值表达式：取用 lmc08（操作时间）之日期段，产出「action_date」
                    CAST(lmc08 AS STRING)                         AS action_time,                           -- 取值表达式：取用 lmc08（操作时间），产出「action_time」
                    CAST(lmc06 AS STRING)                         AS operator_id,                           -- 取值表达式：取用 lmc06（操作人账号），产出「operator_id」
                    CAST(lmc07 AS STRING)                         AS operator_lv,                           -- 取值表达式：取用 lmc07（操作人层级），产出「operator_lv」
                    CAST(lmc05 AS STRING)                         AS content                                -- 取值表达式：取用 lmc05（变更内容串），产出「content」
            FROM    ods_mariadb_2b.ods_a168_log_mem_change                                                  -- 取数来源：取自会员变更日志表
            WHERE   dt >= '2026-03-21' AND dt < '2026-08-07'                                                -- 过滤条件：限定 E1 全局窗，涉 dt（营业日）
              AND   CAST(lmc04 AS STRING) IN ('edit', 'changestatus')                                       -- 并列条件：只留配置修改与状态变更两类
        ),                                                                                                  -- 续行：收束上方的子查询或函数括号（§TL-14）
        seg AS (                                                                                            -- 公共表表达式：开启中间结果集 seg——把多段 content 逐段拆开（§TL-14）
            SELECT  e.member_id, e.action_date, e.action_time, e.operator_id, e.operator_lv,                -- 取列：起始取列子句，透传五要素
                    TRIM(s.piece)                                 AS piece                                  -- 取值表达式：逐段去空白，产出「piece」
            FROM ev e, unnest(split(e.content, ';')) AS s(piece)                                            -- 行展开：以 unnest(split(…)) 把分号分隔的多段逐段成行
        ),                                                                                                  -- 续行：收束上方的子查询或函数括号（§TL-14）
        lim AS (                                                                                            -- 公共表表达式：开启中间结果集 lim——只留百家乐限额变更段（§TL-14）
            SELECT  member_id, action_date, action_time, operator_id, operator_lv,                          -- 取列：起始取列子句，透传五要素
                    TRIM(SPLIT_PART(SPLIT_PART(piece, ':', 2), '=>', 1)) AS grp_before,                     -- 取值表达式：箭头前段为旧组清单，产出「grp_before」
                    TRIM(SPLIT_PART(piece, '=>', 2))              AS grp_after,                             -- 取值表达式：箭头后段为新组清单，产出「grp_after」
                    CONCAT_WS('#', member_id, action_time)        AS ev_key                                 -- 取值表达式：会员×时刻拼事件键，产出「ev_key」——供两侧展开后回接
            FROM    seg                                                                                     -- 取数来源：取自本条自建的中间结果集 seg
            WHERE   piece LIKE '101-mem015:%'                                                               -- 过滤条件：只认百家乐的新版限額段——★ 不得与 member.mem015（login_error）相混
              AND   piece LIKE '%=>%'                                                                       -- 并列条件：须含箭头方为有效变更段
        ),                                                                                                  -- 续行：收束上方的子查询或函数括号（§TL-14）
        bfr AS (                                                                                            -- 公共表表达式：开启中间结果集 bfr——旧组清单逐组展开后取最高上限（§TL-14）
            SELECT  l.ev_key,                                                                               -- 取列：起始取列子句，本行先取事件键
                    MAX(d.hi)                                     AS max_hi_before,                         -- 聚合：旧清单之最高上限，产出「max_hi_before」
                    SUM(CASE WHEN d.hi = 0 THEN 1 ELSE 0 END)     AS zero_before,                           -- 聚合：旧清单含「0,0」组之个数，产出「zero_before」——歧义标记之料
                    COUNT(d.grp_id)                               AS n_grp_before                           -- 计数表达式：旧清单中能连上字典的组数，产出「n_grp_before」
            FROM        lim l                                                                               -- 取数来源：取自本条自建的中间结果集 lim
            CROSS JOIN  unnest(split(l.grp_before, ',')) AS g(grp)                                          -- 行展开：把逗号分隔的组清单逐组成行
            LEFT JOIN   dict d ON d.grp_id = TRIM(g.grp)                                                    -- 左连接：取自本条自建的中间结果集 dict，连接键为组号——连不上者留空，不以 0 顶替
            GROUP BY l.ev_key                                                                               -- 分组：按事件键汇总
        ),                                                                                                  -- 续行：收束上方的子查询或函数括号（§TL-14）
        aft AS (                                                                                            -- 公共表表达式：开启中间结果集 aft——新组清单同法（§TL-14）
            SELECT  l.ev_key,                                                                               -- 取列：起始取列子句，本行先取事件键
                    MAX(d.hi)                                     AS max_hi_after,                          -- 聚合：新清单之最高上限，产出「max_hi_after」
                    SUM(CASE WHEN d.hi = 0 THEN 1 ELSE 0 END)     AS zero_after,                            -- 聚合：新清单含「0,0」组之个数，产出「zero_after」
                    COUNT(d.grp_id)                               AS n_grp_after                            -- 计数表达式：新清单中能连上字典的组数，产出「n_grp_after」
            FROM        lim l                                                                               -- 取数来源：取自本条自建的中间结果集 lim
            CROSS JOIN  unnest(split(l.grp_after, ',')) AS g(grp)                                           -- 行展开：把逗号分隔的组清单逐组成行
            LEFT JOIN   dict d ON d.grp_id = TRIM(g.grp)                                                    -- 左连接：取自本条自建的中间结果集 dict，连接键为组号
            GROUP BY l.ev_key                                                                               -- 分组：按事件键汇总
        ),                                                                                                  -- 续行：收束上方的子查询或函数括号（§TL-14）
        bl AS (                                                                                             -- 公共表表达式：开启中间结果集 bl——本方案口径的百家乐投注会员名单（§TL-14）
            SELECT  DISTINCT CAST(bet05 AS STRING)                AS member_id                              -- 取值表达式：取用 bet05（会员号）去重，产出「member_id」
            FROM    ods_mariadb_2b.ods_a168_bet02                                                           -- 取数来源：取自注单明细表
            WHERE   dt >= '2026-03-21' AND dt < '2026-08-07'                                                -- 过滤条件：限定 E1 全局窗，涉 dt（营业日）
              AND sync_time <= '2026-08-27 09:00:00'
              AND   CAST(bet02 AS STRING) = '101'                                                           -- 并列条件：限定百家乐产品大类，涉 bet02（游戏类别）
        )                                                                                                   -- 续行：收束上方的子查询或函数括号（§TL-14）
        SELECT  l.member_id,                                                                                -- 取列：起始取列子句，本行先取「member_id」
                l.action_date, l.action_time,                                                               -- 取值表达式：事件之日与时刻
                l.operator_id, l.operator_lv,                                                               -- 取值表达式：操作人与其层级——审计轨迹之「谁」
                l.grp_before, l.grp_after,                                                                  -- 取值表达式：新旧限额组清单原文，留档以备复核
                b.max_hi_before, f.max_hi_after,                                                            -- 取值表达式：新旧清单之最高上限——方向判定之两端
                b.n_grp_before, f.n_grp_after,                                                              -- 取值表达式：两侧能连上字典的组数——连不上者即字典外之组，须查
                CASE WHEN b.max_hi_before IS NULL OR f.max_hi_after IS NULL                                 -- 取值表达式：方向判定起算——任一端无从取上限即判不明
                     THEN 'UNKNOWN_NO_DICT'                                                                 -- 续行：组号不在字典内，方向不明
                     WHEN f.max_hi_after < b.max_hi_before THEN 'TIGHTEN'                                   -- 续行：上限调低即收紧——**限红处置**
                     WHEN f.max_hi_after > b.max_hi_before THEN 'RELEASE'                                   -- 续行：上限调高即放宽
                     ELSE 'FLAT' END                              AS direction,                             -- 续行：持平——清单变而上限未变，不入处置节，产出「direction」
                CASE WHEN COALESCE(b.zero_before,0) + COALESCE(f.zero_after,0) > 0                          -- 取值表达式：歧义标记起算——含「0,0」组者
                     THEN 1 ELSE 0 END                            AS has_zero_group,                        -- 续行：产出「has_zero_group」——★ 为 1 者方向判定须人工复核，不得径入处置总体
                CASE WHEN bl.member_id IS NULL THEN 0 ELSE 1 END  AS is_baccarat_member,                    -- 取值表达式：是否本方案口径的百家乐会员
                'v2026-08-11'                                     AS filter_rule_version                    -- 取值表达式：规则版本号——改判定规则须改版本并记入变更日志
        FROM        lim l                                                                                   -- 取数来源：取自本条自建的中间结果集 lim
        LEFT JOIN   bfr b  ON b.ev_key = l.ev_key                                                           -- 左连接：取自本条自建的中间结果集 bfr，连接键为事件键
        LEFT JOIN   aft f  ON f.ev_key = l.ev_key                                                           -- 左连接：取自本条自建的中间结果集 aft，连接键为事件键
        LEFT JOIN   bl     ON bl.member_id = l.member_id                                                    -- 左连接：取自本条自建的中间结果集 bl，连接键为 member_id（会员号）
      )
    SELECT q.*,
           -- 一·经济层
           ROUND(e.stake,4) AS stake, ROUND(e.valid,4) AS valid_bet,
           ROUND(-e.net,4) AS profit, e.n_bets, e.n_rounds,
           ROUND(e.net/NULLIF(e.stake,0),8) AS roi,
           ROUND(e.net_in/NULLIF(e.st_in,0),8) AS roi_post,
           ROUND(e.net_out/NULLIF(e.st_out,0),8) AS roi_non_post,
           ROUND((e.net-e.rebate)/NULLIF(e.stake,0),8) AS roi_ex_rebate,
           ROUND(e.net,4) AS roi_numerator, ROUND(e.stake,4) AS roi_denominator,
           CASE WHEN e.stake IS NULL THEN 'NULL_DENOM' WHEN e.stake<=0 THEN 'ZERO_DENOM'
                WHEN e.n_bets<30 THEN 'THIN_EXPOSURE' ELSE 'OK' END AS roi_denominator_status,
           ROUND(e.rebate,4) AS rebate_cost, ROUND(e.agent_cost,4)                           AS cost_complement_b,
       ROUND(e.agent_pct,4)                            AS pct_complement,
       ROUND(e.company_retain_pct,4)                   AS pct_top_bet23,
       'AG03-UNRESOLVED'                                     AS agent_formula_version,
      'ALL5_LEVELS_bet23_to_bet27'                    AS agent_level_scope,
      ROUND(e.agent_cost_lv1,4) AS agent_cost_lv1, ROUND(e.agent_cost_lv2,4) AS agent_cost_lv2,
      ROUND(e.agent_cost_lv3,4) AS agent_cost_lv3, ROUND(e.agent_cost_lv4,4) AS agent_cost_lv4,
      ROUND(e.agent_cost_lv5,4) AS agent_cost_lv5,
      ROUND(e.agent_pct_lv1,6) AS agent_pct_lv1, ROUND(e.agent_pct_lv2,6) AS agent_pct_lv2,
      ROUND(e.agent_pct_lv3,6) AS agent_pct_lv3, ROUND(e.agent_pct_lv4,6) AS agent_pct_lv4,
      ROUND(e.agent_pct_lv5,6) AS agent_pct_lv5,
      ROUND(e.retain_pct_lv1,6) AS retain_pct_lv1, ROUND(e.retain_pct_lv2,6) AS retain_pct_lv2,
      ROUND(e.retain_pct_lv3,6) AS retain_pct_lv3, ROUND(e.retain_pct_lv4,6) AS retain_pct_lv4,
      ROUND(e.retain_pct_lv5,6) AS retain_pct_lv5, ROUND(e.chain_depth_avg,4) AS chain_depth_avg,
      ROUND(e.agent_cost_chain_additive,4)            AS agent_cost_chain_additive,
      ROUND(e.agent_cost_chain_nested,4)              AS agent_cost_chain_nested,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_additive,4) AS residual_chain_additive,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_nested,4)   AS residual_chain_nested,
      'PENDING_AG03'                                  AS decision_status,
      'FALSE'                                         AS admit_to_risk_decision,
      'NOT_FOR_ENFORCEMENT'                           AS deliverable_class,
       ROUND(e.agent_cost_a_legacy,4)                  AS agent_cost_a_legacy,
       ROUND(e.agent_cost_valid_base_legacy,4)         AS agent_cost_valid_base_legacy,
           ROUND(-e.net-e.rebate,4)                        AS ngr,
       ROUND(-e.net-e.rebate-e.agent_cost,4)           AS residual_b,
       ROUND(-e.net-e.rebate-e.agent_cost_a_legacy,4)  AS residual_a,
           ROUND((-e.net-e.rebate)/NULLIF(e.stake,0),8)    AS ngr_rate,
       ROUND((-e.net-e.rebate-e.agent_cost)/NULLIF(e.stake,0),8)   AS residual_b_rate,
      -- 【HF9c · canonical accounting contract】
      --   以下 canonical 字段只增加明确 scope；不删除、不覆盖既有字段。
      --   formal_bet23_* 保持 HF9b 当前生产公式及其 NULL/0 语义；
      --   lv1~lv5 / additive / nested 则分别采用各自原始 e.* 成本字段，
      --   rate 一律从未舍入的 e.* 分子 / e.stake 计算，禁止由展示值反算。
      ROUND(e.agent_cost,4) AS agent_cost_bet23_formal_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost,4) AS net_margin_bet23_formal_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost)/NULLIF(e.stake,0),8) AS net_margin_bet23_formal_rate_canonical,
      ROUND(e.agent_cost_lv1,4) AS agent_cost_lv1_bet23_canonical,
      ROUND(e.agent_cost_lv2,4) AS agent_cost_lv2_bet24_canonical,
      ROUND(e.agent_cost_lv3,4) AS agent_cost_lv3_bet25_canonical,
      ROUND(e.agent_cost_lv4,4) AS agent_cost_lv4_bet26_canonical,
      ROUND(e.agent_cost_lv5,4) AS agent_cost_lv5_bet27_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_lv1,4) AS net_margin_lv1_bet23_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_lv1)/NULLIF(e.stake,0),8) AS net_margin_lv1_bet23_rate_canonical,
      ROUND(e.agent_cost_chain_additive,4) AS agent_cost_chain_additive_canonical,
      ROUND(e.agent_cost_chain_nested,4) AS agent_cost_chain_nested_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_additive,4) AS net_margin_chain_additive_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_nested,4) AS net_margin_chain_nested_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_chain_additive)/NULLIF(e.stake,0),8) AS net_margin_chain_additive_rate_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_chain_nested)/NULLIF(e.stake,0),8) AS net_margin_chain_nested_rate_canonical,
       ROUND((-e.net-e.rebate-e.agent_cost_a_legacy)/NULLIF(e.stake,0),8) AS residual_a_rate,
           -- 二·分布层
           ROUND(e.stake/NULLIF(e.n_bets,0),4) AS avg_stake_per_bet,
           ROUND(e.valid/NULLIF(e.n_rounds,0),4) AS avg_valid_bet_per_round,
           ROUND(-e.net/NULLIF(e.n_rounds,0),4) AS avg_profit_per_round,
           ROUND(-e.net/NULLIF(e.active_days,0),4) AS avg_profit_per_day,
           ROUND(-e.net/NULLIF(e.active_shoes,0),4) AS avg_profit_per_shoe,
           ROUND(e.stake/NULLIF(e.active_days,0),4) AS avg_stake_per_active_day,
           ROUND(e.n_rounds*1.0/NULLIF(e.active_days,0),4) AS avg_rounds_per_active_day,
           ROUND(e.st_in/NULLIF(e.nb_in,0),4) AS avg_stake_post,
           ROUND(e.st_out/NULLIF(e.nb_out,0),4) AS avg_stake_non_post,
           ROUND(e.p25,4) AS p25_stake, ROUND(e.p50,4) AS p50_stake, ROUND(e.p75,4) AS p75_stake,
           ROUND(e.p90,4) AS p90_stake, ROUND(e.p95,4) AS p95_stake, ROUND(e.p99,4) AS p99_stake,
           ROUND(e.p50_valid,4) AS p50_valid_bet, ROUND(e.p50_profit,4) AS p50_profit,
           ROUND(e.p95/NULLIF(e.p50,0),6) AS p95_over_p50,
           ROUND(e.p99/NULLIF(e.p50,0),6) AS p99_over_p50,
           ROUND((e.stake/NULLIF(e.n_bets,0))/NULLIF(e.p50,0),6) AS avg_over_p50,
           -- 三·关系层
           e.n_tables AS common_table_count, e.n_dealers AS common_dealer_count,
           e.n_ips AS common_ip_count, e.n_products AS common_product_count,
           ROUND(e.st_in/NULLIF(e.stake,0),8) AS share_post,
           -- 四·rate 层
           ROUND(-e.net/NULLIF(e.stake,0),8) AS hold_rate,
           ROUND(-e.net_in/NULLIF(e.st_in,0),8) AS hold_rate_post,
           ROUND(e.rebate/NULLIF(e.valid,0),8) AS rebate_rate_actual,
           ROUND(e.rbpct,6) AS rebate_pct_config,
           ROUND(e.valid/NULLIF(e.stake,0),6) AS turnover_multiple,
           ROUND(e.freecomm_rate,6) AS free_comm_rate,
           ROUND(e.net_in/NULLIF(e.st_in,0)-e.net_out/NULLIF(e.st_out,0),8) AS roi_delta_post,
           -- 五·动态层
           e.first_seen_d AS first_seen, e.last_seen_d AS last_seen,
           e.active_days, e.active_shoes, e.active_sessions,
           DATEDIFF(e.last_seen_d, e.first_seen_d)+1 AS span_days,
           ROUND(e.active_days*1.0/NULLIF(DATEDIFF(e.last_seen_d,e.first_seen_d)+1,0),6) AS persistence,
           ROUND((e.st_in/NULLIF(e.nb_in,0))/NULLIF(e.st_out/NULLIF(e.nb_out,0),0),6) AS ramp_post,
           ROUND((e.st_rec/NULLIF(e.nb_rec,0))/NULLIF(e.stake/NULLIF(e.n_bets,0),0),6) AS ramp_recent,
           ROUND((e.st_rec/NULLIF(e.stake,0))/0.30,6) AS stake_ramp,
           -- 六·决策层（HF9f · 详见档头【HF9f 变更说明】；本段两版逐字同一）
           NTILE(5) OVER (ORDER BY e.stake) AS vip_tier,                                                        -- 窗口取值：相对刻度 B 族，全体五等分；须连同下方血统五元组一并解读，禁作硬阈值判型
           PERCENT_RANK() OVER (ORDER BY -e.net-e.rebate-e.agent_cost)    AS economic_value,                    -- 窗口取值：HF9f·F-19 修正 —— HF9e 写作 -(-…) 双负号致方向颠倒（#075 实测 corr(economic_value, residual_b) = -1.0000）；今与 action_priority 排序键归一，值大即平台真净利高
           PERCENT_RANK() OVER (ORDER BY e.net/NULLIF(e.stake,0))         AS roi_pr_global,                     -- 窗口取值：HF9f·F-17 正名 —— 本列实为 ROI（玩家净回报率）之全体百分位，与「风险」无关；旧名 risk_value 见下一行
           PERCENT_RANK() OVER (ORDER BY e.net/NULLIF(e.stake,0))         AS risk_value,                        -- 窗口取值：兼容列，恒等于 roi_pr_global，仅为下游迁移窗保留；HF9g 起废弃，禁新引用
           PERCENT_RANK() OVER (ORDER BY e.stake)                         AS pr_stake,                          -- 窗口取值：兼容列，恒等于 pr_global，原名保留以免断链
           PERCENT_RANK() OVER (ORDER BY e.stake)                         AS pr_global,                         -- 窗口取值：HF9f·F-1 双轨之一 —— 全体口径百分位，参照总体即本件全部输出行
           CASE WHEN e.n_rounds >= 30                                                                           -- 条件分支：起始分支 —— 仅在合格子集内计算合格口径百分位
                  THEN PERCENT_RANK() OVER (PARTITION BY CASE WHEN e.n_rounds >= 30 THEN 1 ELSE 0 END ORDER BY e.stake)  -- 分支取值：以合格与否分区，故本值即 n_rounds>=30 子集内之百分位
                ELSE NULL END                                             AS pr_qualified,                      -- 条件分支：收束上方分支 —— 不合格者留 NULL（NULL＝未测，非 0），产出「pr_qualified」
           'n_rounds>=30'                                                 AS pr_qualified_population,           -- 字面取值：血统 —— 合格子集之定义
           COUNT(*) OVER ()                                               AS pr_global_population_n,            -- 窗口取值：血统 —— 全体口径之参照总体规模，渲染时现算，禁写死
           SUM(CASE WHEN e.n_rounds >= 30 THEN 1 ELSE 0 END) OVER ()      AS pr_qualified_population_n,         -- 窗口取值：血统 —— 合格子集之参照总体规模，现算，禁写死
           'PERCENT_RANK_OVER_ORDER_BY_e_stake'                           AS pr_calculation_method,             -- 字面取值：血统 —— 算法标识
           'HF9f'                                                         AS pr_calculation_version,            -- 字面取值：血统 —— 算法版本
           CASE WHEN e.n_rounds IS NULL OR e.n_rounds < 30 THEN 'THIN_ROUNDS' ELSE 'OK' END AS evidence_flag,   -- 条件分支：HF9f·F-2a 证据旗标 —— THIN_ROUNDS 者禁入执行队列，仅入观察队列
           CASE WHEN e.n_rounds IS NULL       THEN NULL                                                         -- 条件分支：起始分支 —— 未测者留 NULL（自家铁律：NULL ≠ 0）
                WHEN e.n_rounds >= 31483      THEN 'L1_POWERED'                                                 -- 分支判定：MDE 反解第一档
                WHEN e.n_rounds >= 15409      THEN 'L2_CI_1P5'                                                  -- 分支判定：MDE 反解第二档
                WHEN e.n_rounds >=  8668      THEN 'L3_CI_2P0'                                                  -- 分支判定：MDE 反解第三档
                WHEN e.n_rounds >=  3852      THEN 'L4_CI_3P0'                                                  -- 分支判定：MDE 反解第四档
                ELSE 'L5_INSUFFICIENT' END                                AS evidence_rate,                     -- 条件分支：收束上方 —— HF9f·F-3 证据分档，承 HF9e 前议之 MDE 反解五档，须于 F-4 敏感性实验后复核
           ROUND(1.96 * 0.95 / SQRT(NULLIF(CAST(e.n_rounds AS DOUBLE),0)),8) AS hold_ci_halfwidth_approx,       -- 比率表达式：HF9f·F-3 逐行现算之 95% 半宽近似；常数 0.95 为登记值，本轮 #075 实测每局 ROI 隐含 σ 于最薄层为 0.9249，二者差异待 F-4 裁定
           CASE WHEN e.stake IS NULL OR e.stake<=0 OR e.n_bets<30 OR e.n_rounds IS NULL OR e.n_rounds<30 THEN 'Z 证据不足 · 不动作'  -- 条件分支：HF9f·F-2 双条件取严 —— HF9e 仅卡 e.n_bets<30，致 n_bets>=30 而 n_rounds<30 者绕过 Z（#075 实测 18,537 名，其中 8,145 名已入 A/D 待裁）；今两条件并列取严
                WHEN PERCENT_RANK() OVER (ORDER BY -e.net-e.rebate-e.agent_cost)<=0.10                          -- 分支判定：平台真净利之最低十分位
                  THEN 'A 净亏最大十分位 · 优先复核'                                                             -- 分支取值：HF9f·F-20 正名 —— 本档 Σresidual_b 于 #075 实测 = -100,236,896，系平台净亏最大群，旧名「残值最低十分位 · 待裁」名实不符
                WHEN PERCENT_RANK() OVER (ORDER BY -e.net-e.rebate-e.agent_cost)>=0.80                          -- 分支判定：平台真净利之最高二十分位
                  THEN 'D 净利最高二十分位 · 优先留存'                                                           -- 分支取值：HF9f·F-20 正名 —— 本档 Σresidual_b 于 #075 实测 = +281,733,190，系核心利润源；与 A 档方向相反，旧版同标「待裁」属名实不符
                ELSE 'E 常规' END                                          AS action_priority                   -- 条件分支：收束上方判词，产出「action_priority」
    FROM q
    LEFT JOIN x_agg e ON CAST(e.x_key AS STRING) = CAST(q.`member_id` AS STRING)
  ) y
) z
-- ── 逐批 WHERE 阶梯（★ 口诀：上界 ＝ 下界 ＋ 100000，两数同进）──
--    本件 T_true 未测，无需先跑 T_true；以 0 / 100000 控制本批返回区间，末批由实际行数 < 100000 判定
--    WHERE z.audit_rn >        0 AND z.audit_rn <=   100000   -- 第 1 批
--    WHERE z.audit_rn >   100000 AND z.audit_rn <=   200000   -- 第 2 批
--    WHERE z.audit_rn >   200000 AND z.audit_rn <=   300000   -- 第 3 批
--    WHERE z.audit_rn >   300000 AND z.audit_rn <=   400000   -- 第 4 批
--    WHERE z.audit_rn >   400000 AND z.audit_rn <=   500000   -- 第 5 批
--    WHERE z.audit_rn >   500000 AND z.audit_rn <=   600000   -- 第 6 批
--    WHERE z.audit_rn >   600000 AND z.audit_rn <=   700000   -- 第 7 批
--    …余批类推。第 k 批：WHERE z.audit_rn > (k-1)*100000 AND z.audit_rn <= k*100000
--    某批返回 < 100000 行即为末批，其后不再取。
--
--    ⚠ 常见误写（务必避开）：只推下界而上界不动 ——
--        WHERE z.audit_rn > 100000 AND z.audit_rn <= 100000   ← 自相矛盾，恒为假，返回空集
--        WHERE z.audit_rn > 200000 AND z.audit_rn <= 100000   ← 同上，空集
--      两个数必须**同时**前进，且始终相差 100000。
--      下界 ＝ 上一批之上界；上界 ＝ 本批之上界。
WHERE z.audit_rn > 0 AND z.audit_rn <= 100000 -- ★ HF9c 本批区间
ORDER BY z.audit_rn;


-- ══════════════════════════════════════════════════════════════════════════════════════════════
--  98. T_table_span.csv   [总包行 1447~1455 · 原 6 列 ＋六层约 60 列]
--     典型学：M15 活跃周期　派生旗标：recent（s.x_rec = 1 · 仅供 CASE 条件聚合，全包无任何 WHERE/AND/HAVING 以此过滤）　连接：q.`table_id`
-- ══════════════════════════════════════════════════════════════════════════════════════════════
-- ── ① 先跑 T_true 留档（不足 100000 者一次导全，不必分批）──
-- ── ① T_true：HF9c 不再强制预跑完整 COUNT。
--    本批实际返回行数 < 100000 即判定为末批；全批完成后以各批 n_rows / audit_rn 范围核对总量。

-- ── ② 分批取数：第 1 批。第 k 批只改末行两数为 (k-1)*100000 与 k*100000 ──
--    审计字段二（REDTEAM 2026-08-24 裁定 · 四锁）：
--      audit_rn  全局观测坐标 —— 由**与原版审计版逐字同一**之排序键所生，两版可逐行对账
--      batch_id  物理分批信息 —— 该行所属批次，由 audit_rn 算得，非引擎所赋
--    ★ 锁三：二者皆为审计字段，**不得进入任何业务指标计算**。
--    ★ 锁四：两版经 audit_rn 逐行字段核验后，方可宣布输出完全一致。

-- ── ③ 每批取回后自证四数（任一不符即停手回报，禁止放行）──
--    n_rows        = COUNT(*)      须等于 COUNT(DISTINCT audit_rn)   （批内无重复）
--    audit_rn_min  = MIN(audit_rn) 须等于 (k-1)*100000 + 1           （与上批严丝合缝）
--    audit_rn_max  = MAX(audit_rn) 须等于 min + n_rows - 1           （批内无缺口）
--    全批取毕再验：各批 audit_rn 之并集 = 1 .. T_true，无缺号、无重号。
--     ★ 首行＝平台真净亏最多者（已扣退水与代理占成）。
--
SELECT z.*,
       CAST(FLOOR((z.audit_rn - 1) / 100000) + 1 AS INT)          AS batch_id,
       'A168_HF9F_20260827_0900' AS run_id,
       '2026-08-27 09:00:00' AS snapshot_sync_time
FROM (
  SELECT y.*,
         ROW_NUMBER() OVER (ORDER BY y.`residual_b` ASC, y.`roi` DESC, y.`table_id`, y.`n_rounds`, y.`mean_sec`, y.`p50`, y.`p90`, y.`p99`) AS audit_rn
  FROM (
    WITH
      x_ranked AS (
    SELECT b.bet01, b.bet03, b.bet04, b.bet05, b.bet09, b.bet11, b.bet13,
           b.bet15, b.bet16, b.bet17, b.bet18, b.bet19, b.bet20, b.bet21,
           b.bet22, b.bet23, b.bet24, b.bet25, b.bet26, b.bet27, b.bet38, b.bet39, b.category, b.commission,
           b.dt, b.eid, b.ip, b.validbet, b.updatetime, b.sync_time,
           ROW_NUMBER() OVER (
             PARTITION BY b.bet01
             ORDER BY b.updatetime DESC, b.sync_time DESC, b.dt DESC)      AS x_rn
    FROM ods_mariadb_2b.ods_a168_bet02 b
    WHERE b.dt >= '2026-03-21' AND b.dt < '2026-08-07'
      AND b.bet02 = '101'
      AND b.sync_time <= '2026-08-27 09:00:00'
  ),
    x_testagent AS (
    SELECT age001 AS agent_id FROM ods_mariadb_2b.ods_a168_agent WHERE age022 = '1'
  ),
    x_bs0 AS (
    SELECT b.bet05 AS x_member, b.eid AS x_dealer, b.bet39 AS x_table,
           b.bet03 AS x_shoe, b.ip AS x_ip, b.bet09 AS x_product, b.dt AS x_date,
           CONCAT_WS('|', b.bet03, b.bet04, b.bet39)                      AS x_round,
           CONCAT_WS('|', b.bet39, b.bet03)                               AS x_tblshoe,
           CAST(NULLIF(TRIM(b.bet04),'') AS INT)                          AS x_rno,
           CASE WHEN b.dt >= '2026-07-08' THEN 1 ELSE 0 END               AS x_rec,
           CASE WHEN TRIM(b.commission)='1' THEN 1 ELSE 0 END             AS x_freecomm,
           CAST(NULLIF(TRIM(b.bet13),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_stake,
           CAST(NULLIF(TRIM(b.validbet),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_valid,
           CAST(NULLIF(TRIM(b.bet16),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_rebate,
           CAST(NULLIF(TRIM(b.bet17),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_net,
           CAST(NULLIF(TRIM(b.bet15),'') AS DECIMAL(20,6))                AS x_rbpct,
           COALESCE(CAST(NULLIF(TRIM(b.bet23),'') AS DECIMAL(20,6)),0)   AS x_agpct,
          NULLIF(CAST(NULLIF(TRIM(b.bet23),'') AS DECIMAL(20,6)),0)     AS x_rate1,
          NULLIF(CAST(NULLIF(TRIM(b.bet24),'') AS DECIMAL(20,6)),0)     AS x_rate2,
          NULLIF(CAST(NULLIF(TRIM(b.bet25),'') AS DECIMAL(20,6)),0)     AS x_rate3,
          NULLIF(CAST(NULLIF(TRIM(b.bet26),'') AS DECIMAL(20,6)),0)     AS x_rate4,
          NULLIF(CAST(NULLIF(TRIM(b.bet27),'') AS DECIMAL(20,6)),0)     AS x_rate5,
          (CASE WHEN NULLIF(CAST(NULLIF(TRIM(b.bet22),'') AS BIGINT),0) IS NOT NULL THEN 5
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet21),'') AS BIGINT),0) IS NOT NULL THEN 4
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet20),'') AS BIGINT),0) IS NOT NULL THEN 3
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet19),'') AS BIGINT),0) IS NOT NULL THEN 2
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet18),'') AS BIGINT),0) IS NOT NULL THEN 1
                ELSE 0 END)                                             AS x_chain_depth,
           CASE WHEN COALESCE(t1.agent_id,t2.agent_id,t3.agent_id,
                              t4.agent_id,t5.agent_id) IS NOT NULL
                THEN 1 ELSE 0 END                                        AS f_testline
    FROM x_ranked b
    LEFT JOIN x_testagent t1 ON t1.agent_id = b.bet18
    LEFT JOIN x_testagent t2 ON t2.agent_id = b.bet19
    LEFT JOIN x_testagent t3 ON t3.agent_id = b.bet20
    LEFT JOIN x_testagent t4 ON t4.agent_id = b.bet21
    LEFT JOIN x_testagent t5 ON t5.agent_id = b.bet22
    WHERE b.x_rn = 1
      AND b.category='1' AND UPPER(TRIM(b.bet38))='N'
      AND CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8)) > 0
  ),
  x_mk AS (
    SELECT s.*,
           CASE WHEN s.f_testline = 0 THEN 1 ELSE 0 END                 AS is_clean
    FROM x_bs0 s
  ),
  x_agg AS (
    SELECT s.x_table                                                        AS x_key,
           COUNT(*) AS n_bets, COUNT(DISTINCT s.x_round) AS n_rounds,
           COUNT(DISTINCT s.x_date) AS active_days, COUNT(DISTINCT s.x_tblshoe) AS active_shoes,
           COUNT(DISTINCT CONCAT_WS('|', s.x_date, s.x_table)) AS active_sessions,
           COUNT(DISTINCT s.x_table) AS n_tables, COUNT(DISTINCT s.x_dealer) AS n_dealers,
           COUNT(DISTINCT s.x_ip) AS n_ips, COUNT(DISTINCT s.x_product) AS n_products,
           MIN(s.x_date) AS first_seen_d, MAX(s.x_date) AS last_seen_d,
           SUM(s.x_stake) AS stake, SUM(s.x_valid) AS valid, SUM(s.x_rebate) AS rebate,
           SUM(s.x_net) AS net, SUM(-s.x_net *(100.0-s.x_agpct)/100.0) AS agent_cost,
           AVG(100.0-s.x_agpct)                   AS agent_pct,
           AVG(s.x_agpct)                         AS company_retain_pct,
           SUM(-s.x_net *s.x_agpct/100.0)         AS agent_cost_a_legacy,
           SUM(s.x_valid*s.x_agpct/100.0)         AS agent_cost_valid_base_legacy,
          AVG(COALESCE(s.x_rate1,100)) AS retain_pct_lv1, AVG(COALESCE(s.x_rate2,100)) AS retain_pct_lv2,
          AVG(COALESCE(s.x_rate3,100)) AS retain_pct_lv3, AVG(COALESCE(s.x_rate4,100)) AS retain_pct_lv4,
          AVG(COALESCE(s.x_rate5,100)) AS retain_pct_lv5, AVG(s.x_chain_depth) AS chain_depth_avg,
          AVG(COALESCE(100.0-s.x_rate1,0)) AS agent_pct_lv1, AVG(COALESCE(100.0-s.x_rate2,0)) AS agent_pct_lv2,
          AVG(COALESCE(100.0-s.x_rate3,0)) AS agent_pct_lv3, AVG(COALESCE(100.0-s.x_rate4,0)) AS agent_pct_lv4,
          AVG(COALESCE(100.0-s.x_rate5,0)) AS agent_pct_lv5,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate1,0)/100.0)                        AS agent_cost_lv1,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate2,0)/100.0)                        AS agent_cost_lv2,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate3,0)/100.0)                        AS agent_cost_lv3,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate4,0)/100.0)                        AS agent_cost_lv4,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate5,0)/100.0)                        AS agent_cost_lv5,
          SUM(-s.x_net*(COALESCE(100.0-s.x_rate1,0)+COALESCE(100.0-s.x_rate2,0)
                       +COALESCE(100.0-s.x_rate3,0)+COALESCE(100.0-s.x_rate4,0)
                       +COALESCE(100.0-s.x_rate5,0))/100.0)                   AS agent_cost_chain_additive,
          SUM(-s.x_net*(1.0 - CAST(COALESCE(s.x_rate1,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate2,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate3,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate4,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate5,100) AS DOUBLE)/100.0))
                                                                       AS agent_cost_chain_nested,
           AVG(s.x_rbpct) AS rbpct, AVG(s.x_freecomm*1.0) AS freecomm_rate,
           PERCENTILE_APPROX(s.x_stake,0.25) AS p25, PERCENTILE_APPROX(s.x_stake,0.50) AS p50,
           PERCENTILE_APPROX(s.x_stake,0.75) AS p75, PERCENTILE_APPROX(s.x_stake,0.90) AS p90,
           PERCENTILE_APPROX(s.x_stake,0.95) AS p95, PERCENTILE_APPROX(s.x_stake,0.99) AS p99,
           PERCENTILE_APPROX(s.x_valid,0.50) AS p50_valid,
           PERCENTILE_APPROX(s.x_net,0.50)   AS p50_profit,
           SUM(CASE WHEN s.x_rec = 1 THEN s.x_stake ELSE 0 END) AS st_in,
           SUM(CASE WHEN s.x_rec = 1 THEN 1 ELSE 0 END)         AS nb_in,
           SUM(CASE WHEN s.x_rec = 1 THEN s.x_net ELSE 0 END)   AS net_in,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN s.x_stake ELSE 0 END) AS st_out,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN 1 ELSE 0 END)         AS nb_out,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN s.x_net ELSE 0 END)   AS net_out,
           SUM(CASE WHEN s.x_rec=1 THEN s.x_stake ELSE 0 END) AS st_rec,
           SUM(CASE WHEN s.x_rec=1 THEN 1 ELSE 0 END)         AS nb_rec
    FROM x_mk s
    WHERE s.is_clean = 1
      AND s.x_table IS NOT NULL AND TRIM(CAST(s.x_table AS STRING)) <> ''
    GROUP BY s.x_table
  ),
      q AS (
        SELECT gi011 AS table_id, COUNT(*) AS n_rounds,                                                     -- 取列：起始取列子句，本行先取「n_rounds」，涉 gi011（桌号）
               AVG(UNIX_TIMESTAMP(gi006)-UNIX_TIMESTAMP(gi004))  AS mean_sec,                               -- 求均值表达式：取用 gi004（局开始时刻）、gi006（开牌时刻），产出「mean_sec」
               PERCENTILE_APPROX(UNIX_TIMESTAMP(gi006)-UNIX_TIMESTAMP(gi004),0.5) AS p50,                   -- 取近似分位数表达式：取用 gi004（局开始时刻）、gi006（开牌时刻），产出「p50」
               PERCENTILE_APPROX(UNIX_TIMESTAMP(gi006)-UNIX_TIMESTAMP(gi004),0.9) AS p90,                   -- 取近似分位数表达式：取用 gi004（局开始时刻）、gi006（开牌时刻），产出「p90」
               PERCENTILE_APPROX(UNIX_TIMESTAMP(gi006)-UNIX_TIMESTAMP(gi004),0.99) AS p99                   -- 取近似分位数表达式：取用 gi004（局开始时刻）、gi006（开牌时刻），产出「p99」
        FROM ods_mariadb_2b.ods_a168_game_info                                                              -- 取数来源：取自局信息表（靴局、开牌与桌号的时序基准）
        WHERE gi001='101' AND gi013='1' AND is_lock='N'                                                     -- 过滤条件：限定 gi001等于 '101'、gi013等于 '1'、is_lock等于 'N'，涉 gi001（局主键）
          AND gi004>='2026-03-21' AND gi004<'2026-08-07'                                                    -- 并列条件：限定 gi004不少于 '2026-03-21'、gi004小于 '2026-08-07'，涉 gi004（局开始时刻）
        GROUP BY gi011
      )
    SELECT q.*,
           -- 一·经济层
           ROUND(e.stake,4) AS stake, ROUND(e.valid,4) AS valid_bet,
           ROUND(-e.net,4) AS profit, e.n_bets, e.n_rounds AS n_rounds_xagg,
           ROUND(e.net/NULLIF(e.stake,0),8) AS roi,
           ROUND(e.net_in/NULLIF(e.st_in,0),8) AS roi_recent,
           ROUND(e.net_out/NULLIF(e.st_out,0),8) AS roi_non_recent,
           ROUND((e.net-e.rebate)/NULLIF(e.stake,0),8) AS roi_ex_rebate,
           ROUND(e.net,4) AS roi_numerator, ROUND(e.stake,4) AS roi_denominator,
           CASE WHEN e.stake IS NULL THEN 'NULL_DENOM' WHEN e.stake<=0 THEN 'ZERO_DENOM'
                WHEN e.n_bets<30 THEN 'THIN_EXPOSURE' ELSE 'OK' END AS roi_denominator_status,
           ROUND(e.rebate,4) AS rebate_cost, ROUND(e.agent_cost,4)                           AS cost_complement_b,
       ROUND(e.agent_pct,4)                            AS pct_complement,
       ROUND(e.company_retain_pct,4)                   AS pct_top_bet23,
       'AG03-UNRESOLVED'                                     AS agent_formula_version,
      'ALL5_LEVELS_bet23_to_bet27'                    AS agent_level_scope,
      ROUND(e.agent_cost_lv1,4) AS agent_cost_lv1, ROUND(e.agent_cost_lv2,4) AS agent_cost_lv2,
      ROUND(e.agent_cost_lv3,4) AS agent_cost_lv3, ROUND(e.agent_cost_lv4,4) AS agent_cost_lv4,
      ROUND(e.agent_cost_lv5,4) AS agent_cost_lv5,
      ROUND(e.agent_pct_lv1,6) AS agent_pct_lv1, ROUND(e.agent_pct_lv2,6) AS agent_pct_lv2,
      ROUND(e.agent_pct_lv3,6) AS agent_pct_lv3, ROUND(e.agent_pct_lv4,6) AS agent_pct_lv4,
      ROUND(e.agent_pct_lv5,6) AS agent_pct_lv5,
      ROUND(e.retain_pct_lv1,6) AS retain_pct_lv1, ROUND(e.retain_pct_lv2,6) AS retain_pct_lv2,
      ROUND(e.retain_pct_lv3,6) AS retain_pct_lv3, ROUND(e.retain_pct_lv4,6) AS retain_pct_lv4,
      ROUND(e.retain_pct_lv5,6) AS retain_pct_lv5, ROUND(e.chain_depth_avg,4) AS chain_depth_avg,
      ROUND(e.agent_cost_chain_additive,4)            AS agent_cost_chain_additive,
      ROUND(e.agent_cost_chain_nested,4)              AS agent_cost_chain_nested,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_additive,4) AS residual_chain_additive,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_nested,4)   AS residual_chain_nested,
      'PENDING_AG03'                                  AS decision_status,
      'FALSE'                                         AS admit_to_risk_decision,
      'NOT_FOR_ENFORCEMENT'                           AS deliverable_class,
       ROUND(e.agent_cost_a_legacy,4)                  AS agent_cost_a_legacy,
       ROUND(e.agent_cost_valid_base_legacy,4)         AS agent_cost_valid_base_legacy,
           ROUND(-e.net-e.rebate,4)                        AS ngr,
       ROUND(-e.net-e.rebate-e.agent_cost,4)           AS residual_b,
       ROUND(-e.net-e.rebate-e.agent_cost_a_legacy,4)  AS residual_a,
           ROUND((-e.net-e.rebate)/NULLIF(e.stake,0),8)    AS ngr_rate,
       ROUND((-e.net-e.rebate-e.agent_cost)/NULLIF(e.stake,0),8)   AS residual_b_rate,
      -- 【HF9c · canonical accounting contract】
      --   以下 canonical 字段只增加明确 scope；不删除、不覆盖既有字段。
      --   formal_bet23_* 保持 HF9b 当前生产公式及其 NULL/0 语义；
      --   lv1~lv5 / additive / nested 则分别采用各自原始 e.* 成本字段，
      --   rate 一律从未舍入的 e.* 分子 / e.stake 计算，禁止由展示值反算。
      ROUND(e.agent_cost,4) AS agent_cost_bet23_formal_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost,4) AS net_margin_bet23_formal_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost)/NULLIF(e.stake,0),8) AS net_margin_bet23_formal_rate_canonical,
      ROUND(e.agent_cost_lv1,4) AS agent_cost_lv1_bet23_canonical,
      ROUND(e.agent_cost_lv2,4) AS agent_cost_lv2_bet24_canonical,
      ROUND(e.agent_cost_lv3,4) AS agent_cost_lv3_bet25_canonical,
      ROUND(e.agent_cost_lv4,4) AS agent_cost_lv4_bet26_canonical,
      ROUND(e.agent_cost_lv5,4) AS agent_cost_lv5_bet27_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_lv1,4) AS net_margin_lv1_bet23_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_lv1)/NULLIF(e.stake,0),8) AS net_margin_lv1_bet23_rate_canonical,
      ROUND(e.agent_cost_chain_additive,4) AS agent_cost_chain_additive_canonical,
      ROUND(e.agent_cost_chain_nested,4) AS agent_cost_chain_nested_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_additive,4) AS net_margin_chain_additive_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_nested,4) AS net_margin_chain_nested_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_chain_additive)/NULLIF(e.stake,0),8) AS net_margin_chain_additive_rate_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_chain_nested)/NULLIF(e.stake,0),8) AS net_margin_chain_nested_rate_canonical,
       ROUND((-e.net-e.rebate-e.agent_cost_a_legacy)/NULLIF(e.stake,0),8) AS residual_a_rate,
           -- 二·分布层
           ROUND(e.stake/NULLIF(e.n_bets,0),4) AS avg_stake_per_bet,
           ROUND(e.valid/NULLIF(e.n_rounds,0),4) AS avg_valid_bet_per_round,
           ROUND(-e.net/NULLIF(e.n_rounds,0),4) AS avg_profit_per_round,
           ROUND(-e.net/NULLIF(e.active_days,0),4) AS avg_profit_per_day,
           ROUND(-e.net/NULLIF(e.active_shoes,0),4) AS avg_profit_per_shoe,
           ROUND(e.stake/NULLIF(e.active_days,0),4) AS avg_stake_per_active_day,
           ROUND(e.n_rounds*1.0/NULLIF(e.active_days,0),4) AS avg_rounds_per_active_day,
           ROUND(e.st_in/NULLIF(e.nb_in,0),4) AS avg_stake_recent,
           ROUND(e.st_out/NULLIF(e.nb_out,0),4) AS avg_stake_non_recent,
           ROUND(e.p25,4) AS p25_stake, ROUND(e.p50,4) AS p50_stake, ROUND(e.p75,4) AS p75_stake,
           ROUND(e.p90,4) AS p90_stake, ROUND(e.p95,4) AS p95_stake, ROUND(e.p99,4) AS p99_stake,
           ROUND(e.p50_valid,4) AS p50_valid_bet, ROUND(e.p50_profit,4) AS p50_profit,
           ROUND(e.p95/NULLIF(e.p50,0),6) AS p95_over_p50,
           ROUND(e.p99/NULLIF(e.p50,0),6) AS p99_over_p50,
           ROUND((e.stake/NULLIF(e.n_bets,0))/NULLIF(e.p50,0),6) AS avg_over_p50,
           -- 三·关系层
           e.n_tables AS common_table_count, e.n_dealers AS common_dealer_count,
           e.n_ips AS common_ip_count, e.n_products AS common_product_count,
           ROUND(e.st_in/NULLIF(e.stake,0),8) AS share_recent,
           -- 四·rate 层
           ROUND(-e.net/NULLIF(e.stake,0),8) AS hold_rate,
           ROUND(-e.net_in/NULLIF(e.st_in,0),8) AS hold_rate_recent,
           ROUND(e.rebate/NULLIF(e.valid,0),8) AS rebate_rate_actual,
           ROUND(e.rbpct,6) AS rebate_pct_config,
           ROUND(e.valid/NULLIF(e.stake,0),6) AS turnover_multiple,
           ROUND(e.freecomm_rate,6) AS free_comm_rate,
           ROUND(e.net_in/NULLIF(e.st_in,0)-e.net_out/NULLIF(e.st_out,0),8) AS roi_delta_recent,
           -- 五·动态层
           e.first_seen_d AS first_seen, e.last_seen_d AS last_seen,
           e.active_days, e.active_shoes, e.active_sessions,
           DATEDIFF(e.last_seen_d, e.first_seen_d)+1 AS span_days,
           ROUND(e.active_days*1.0/NULLIF(DATEDIFF(e.last_seen_d,e.first_seen_d)+1,0),6) AS persistence,
           ROUND((e.st_in/NULLIF(e.nb_in,0))/NULLIF(e.st_out/NULLIF(e.nb_out,0),0),6) AS ramp_recent_vs_prior,
           ROUND((e.st_rec/NULLIF(e.nb_rec,0))/NULLIF(e.stake/NULLIF(e.n_bets,0),0),6) AS ramp_recent_vs_all,
           ROUND((e.st_rec/NULLIF(e.stake,0))/0.30,6) AS stake_ramp,
           -- 六·决策层（HF9f · 详见档头【HF9f 变更说明】；本段两版逐字同一）
           NTILE(5) OVER (ORDER BY e.stake) AS vip_tier,                                                        -- 窗口取值：相对刻度 B 族，全体五等分；须连同下方血统五元组一并解读，禁作硬阈值判型
           PERCENT_RANK() OVER (ORDER BY -e.net-e.rebate-e.agent_cost)    AS economic_value,                    -- 窗口取值：HF9f·F-19 修正 —— HF9e 写作 -(-…) 双负号致方向颠倒（#075 实测 corr(economic_value, residual_b) = -1.0000）；今与 action_priority 排序键归一，值大即平台真净利高
           PERCENT_RANK() OVER (ORDER BY e.net/NULLIF(e.stake,0))         AS roi_pr_global,                     -- 窗口取值：HF9f·F-17 正名 —— 本列实为 ROI（玩家净回报率）之全体百分位，与「风险」无关；旧名 risk_value 见下一行
           PERCENT_RANK() OVER (ORDER BY e.net/NULLIF(e.stake,0))         AS risk_value,                        -- 窗口取值：兼容列，恒等于 roi_pr_global，仅为下游迁移窗保留；HF9g 起废弃，禁新引用
           PERCENT_RANK() OVER (ORDER BY e.stake)                         AS pr_stake,                          -- 窗口取值：兼容列，恒等于 pr_global，原名保留以免断链
           PERCENT_RANK() OVER (ORDER BY e.stake)                         AS pr_global,                         -- 窗口取值：HF9f·F-1 双轨之一 —— 全体口径百分位，参照总体即本件全部输出行
           CASE WHEN e.n_rounds >= 30                                                                           -- 条件分支：起始分支 —— 仅在合格子集内计算合格口径百分位
                  THEN PERCENT_RANK() OVER (PARTITION BY CASE WHEN e.n_rounds >= 30 THEN 1 ELSE 0 END ORDER BY e.stake)  -- 分支取值：以合格与否分区，故本值即 n_rounds>=30 子集内之百分位
                ELSE NULL END                                             AS pr_qualified,                      -- 条件分支：收束上方分支 —— 不合格者留 NULL（NULL＝未测，非 0），产出「pr_qualified」
           'n_rounds>=30'                                                 AS pr_qualified_population,           -- 字面取值：血统 —— 合格子集之定义
           COUNT(*) OVER ()                                               AS pr_global_population_n,            -- 窗口取值：血统 —— 全体口径之参照总体规模，渲染时现算，禁写死
           SUM(CASE WHEN e.n_rounds >= 30 THEN 1 ELSE 0 END) OVER ()      AS pr_qualified_population_n,         -- 窗口取值：血统 —— 合格子集之参照总体规模，现算，禁写死
           'PERCENT_RANK_OVER_ORDER_BY_e_stake'                           AS pr_calculation_method,             -- 字面取值：血统 —— 算法标识
           'HF9f'                                                         AS pr_calculation_version,            -- 字面取值：血统 —— 算法版本
           CASE WHEN e.n_rounds IS NULL OR e.n_rounds < 30 THEN 'THIN_ROUNDS' ELSE 'OK' END AS evidence_flag,   -- 条件分支：HF9f·F-2a 证据旗标 —— THIN_ROUNDS 者禁入执行队列，仅入观察队列
           CASE WHEN e.n_rounds IS NULL       THEN NULL                                                         -- 条件分支：起始分支 —— 未测者留 NULL（自家铁律：NULL ≠ 0）
                WHEN e.n_rounds >= 31483      THEN 'L1_POWERED'                                                 -- 分支判定：MDE 反解第一档
                WHEN e.n_rounds >= 15409      THEN 'L2_CI_1P5'                                                  -- 分支判定：MDE 反解第二档
                WHEN e.n_rounds >=  8668      THEN 'L3_CI_2P0'                                                  -- 分支判定：MDE 反解第三档
                WHEN e.n_rounds >=  3852      THEN 'L4_CI_3P0'                                                  -- 分支判定：MDE 反解第四档
                ELSE 'L5_INSUFFICIENT' END                                AS evidence_rate,                     -- 条件分支：收束上方 —— HF9f·F-3 证据分档，承 HF9e 前议之 MDE 反解五档，须于 F-4 敏感性实验后复核
           ROUND(1.96 * 0.95 / SQRT(NULLIF(CAST(e.n_rounds AS DOUBLE),0)),8) AS hold_ci_halfwidth_approx,       -- 比率表达式：HF9f·F-3 逐行现算之 95% 半宽近似；常数 0.95 为登记值，本轮 #075 实测每局 ROI 隐含 σ 于最薄层为 0.9249，二者差异待 F-4 裁定
           CASE WHEN e.stake IS NULL OR e.stake<=0 OR e.n_bets<30 OR e.n_rounds IS NULL OR e.n_rounds<30 THEN 'Z 证据不足 · 不动作'  -- 条件分支：HF9f·F-2 双条件取严 —— HF9e 仅卡 e.n_bets<30，致 n_bets>=30 而 n_rounds<30 者绕过 Z（#075 实测 18,537 名，其中 8,145 名已入 A/D 待裁）；今两条件并列取严
                WHEN PERCENT_RANK() OVER (ORDER BY -e.net-e.rebate-e.agent_cost)<=0.10                          -- 分支判定：平台真净利之最低十分位
                  THEN 'A 净亏最大十分位 · 优先复核'                                                             -- 分支取值：HF9f·F-20 正名 —— 本档 Σresidual_b 于 #075 实测 = -100,236,896，系平台净亏最大群，旧名「残值最低十分位 · 待裁」名实不符
                WHEN PERCENT_RANK() OVER (ORDER BY -e.net-e.rebate-e.agent_cost)>=0.80                          -- 分支判定：平台真净利之最高二十分位
                  THEN 'D 净利最高二十分位 · 优先留存'                                                           -- 分支取值：HF9f·F-20 正名 —— 本档 Σresidual_b 于 #075 实测 = +281,733,190，系核心利润源；与 A 档方向相反，旧版同标「待裁」属名实不符
                ELSE 'E 常规' END                                          AS action_priority                   -- 条件分支：收束上方判词，产出「action_priority」
    FROM q
    LEFT JOIN x_agg e ON CAST(e.x_key AS STRING) = CAST(q.`table_id` AS STRING)
  ) y
) z
-- ── 逐批 WHERE 阶梯（★ 口诀：上界 ＝ 下界 ＋ 100000，两数同进）──
--    本件 T_true 未测，无需先跑 T_true；以 0 / 100000 控制本批返回区间，末批由实际行数 < 100000 判定
--    WHERE z.audit_rn >        0 AND z.audit_rn <=   100000   -- 第 1 批
--    WHERE z.audit_rn >   100000 AND z.audit_rn <=   200000   -- 第 2 批
--    WHERE z.audit_rn >   200000 AND z.audit_rn <=   300000   -- 第 3 批
--    WHERE z.audit_rn >   300000 AND z.audit_rn <=   400000   -- 第 4 批
--    WHERE z.audit_rn >   400000 AND z.audit_rn <=   500000   -- 第 5 批
--    WHERE z.audit_rn >   500000 AND z.audit_rn <=   600000   -- 第 6 批
--    WHERE z.audit_rn >   600000 AND z.audit_rn <=   700000   -- 第 7 批
--    …余批类推。第 k 批：WHERE z.audit_rn > (k-1)*100000 AND z.audit_rn <= k*100000
--    某批返回 < 100000 行即为末批，其后不再取。
--
--    ⚠ 常见误写（务必避开）：只推下界而上界不动 ——
--        WHERE z.audit_rn > 100000 AND z.audit_rn <= 100000   ← 自相矛盾，恒为假，返回空集
--        WHERE z.audit_rn > 200000 AND z.audit_rn <= 100000   ← 同上，空集
--      两个数必须**同时**前进，且始终相差 100000。
--      下界 ＝ 上一批之上界；上界 ＝ 本批之上界。
WHERE z.audit_rn > 0 AND z.audit_rn <= 100000 -- ★ HF9c 本批区间
ORDER BY z.audit_rn;


-- ══════════════════════════════════════════════════════════════════════════════════════════════
--  99. VB_00_validbet_contract.csv   [总包行 10675~10697 · 原 13 列 ＋六层约 60 列]
--     典型学：M05 退水套利　派生旗标：hiturn（s.x_valid > s.x_stake · 仅供 CASE 条件聚合，全包无任何 WHERE/AND/HAVING 以此过滤）　连接：全窗基线
-- ══════════════════════════════════════════════════════════════════════════════════════════════
-- ★ W-64 · D-14 警示（本件属 x_win 族 · 66 件之一 · 详见 §Z 段 D-14 全案）
--   本件以 `CROSS JOIN x_win e` 接入全局基线，x_win 无 GROUP BY ⇒ 恒 1 行 ⇒ e.* 全行同值。
--   故：economic_value / roi_pr_global / risk_value / pr_stake / pr_global 恒为 0；
--       action_priority 每一行皆为「A 净亏最大十分位 · 优先复核」（Z 分支永不触发）；
--       evidence_rate 恒为最高档；vip_tier 由常数键分档 ⇒ 无信息且非确定。
--   ⇒ 本件决策层三列 **NOT_FOR_DECISION**，裁定前不得用于排班、抽查或汇报。
-- ── ① 先跑 T_true 留档（不足 100000 者一次导全，不必分批）──
-- ── ① T_true：HF9c 不再强制预跑完整 COUNT。
--    本批实际返回行数 < 100000 即判定为末批；全批完成后以各批 n_rows / audit_rn 范围核对总量。

-- ── ② 分批取数：第 1 批。第 k 批只改末行两数为 (k-1)*100000 与 k*100000 ──
--    审计字段二（REDTEAM 2026-08-24 裁定 · 四锁）：
--      audit_rn  全局观测坐标 —— 由**与原版审计版逐字同一**之排序键所生，两版可逐行对账
--      batch_id  物理分批信息 —— 该行所属批次，由 audit_rn 算得，非引擎所赋
--    ★ 锁三：二者皆为审计字段，**不得进入任何业务指标计算**。
--    ★ 锁四：两版经 audit_rn 逐行字段核验后，方可宣布输出完全一致。

-- ── ③ 每批取回后自证四数（任一不符即停手回报，禁止放行）──
--    n_rows        = COUNT(*)      须等于 COUNT(DISTINCT audit_rn)   （批内无重复）
--    audit_rn_min  = MIN(audit_rn) 须等于 (k-1)*100000 + 1           （与上批严丝合缝）
--    audit_rn_max  = MAX(audit_rn) 须等于 min + n_rows - 1           （批内无缺口）
--    全批取毕再验：各批 audit_rn 之并集 = 1 .. T_true，无缺号、无重号。
--     ★ 首行＝平台真净亏最多者（已扣退水与代理占成）。
--
SELECT z.*,
       CAST(FLOOR((z.audit_rn - 1) / 100000) + 1 AS INT)          AS batch_id,
       'A168_HF9F_20260827_0900' AS run_id,
       '2026-08-27 09:00:00' AS snapshot_sync_time
FROM (
  SELECT y.*,
         ROW_NUMBER() OVER (ORDER BY y.`residual_b` ASC, y.`roi` DESC, y.`scope`, y.`n_rows`, y.`n_vb_null`, y.`n_vb_blank`, y.`n_vb_zero`, y.`n_vb_pos`, y.`n_vb_neg`, y.`null_rate_pct`, y.`n_fallback_also_null`, y.`vb_sum`, y.`b13_sum`, y.`b41_sum`, y.`verdict_contract`) AS audit_rn
  FROM (
    WITH
      x_ranked AS (
    SELECT b.bet01, b.bet03, b.bet04, b.bet05, b.bet09, b.bet11, b.bet13,
           b.bet15, b.bet16, b.bet17, b.bet18, b.bet19, b.bet20, b.bet21,
           b.bet22, b.bet23, b.bet24, b.bet25, b.bet26, b.bet27, b.bet38, b.bet39, b.category, b.commission,
           b.dt, b.eid, b.ip, b.validbet, b.updatetime, b.sync_time,
           ROW_NUMBER() OVER (
             PARTITION BY b.bet01
             ORDER BY b.updatetime DESC, b.sync_time DESC, b.dt DESC)      AS x_rn
    FROM ods_mariadb_2b.ods_a168_bet02 b
    WHERE b.dt >= '2026-03-21' AND b.dt < '2026-08-07'
      AND b.bet02 = '101'
      AND b.sync_time <= '2026-08-27 09:00:00'
  ),
    x_testagent AS (
    SELECT age001 AS agent_id FROM ods_mariadb_2b.ods_a168_agent WHERE age022 = '1'
  ),
    x_bs0 AS (
    SELECT b.bet05 AS x_member, b.eid AS x_dealer, b.bet39 AS x_table,
           b.bet03 AS x_shoe, b.ip AS x_ip, b.bet09 AS x_product, b.dt AS x_date,
           CONCAT_WS('|', b.bet03, b.bet04, b.bet39)                      AS x_round,
           CONCAT_WS('|', b.bet39, b.bet03)                               AS x_tblshoe,
           CAST(NULLIF(TRIM(b.bet04),'') AS INT)                          AS x_rno,
           CASE WHEN b.dt >= '2026-07-08' THEN 1 ELSE 0 END               AS x_rec,
           CASE WHEN TRIM(b.commission)='1' THEN 1 ELSE 0 END             AS x_freecomm,
           CAST(NULLIF(TRIM(b.bet13),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_stake,
           CAST(NULLIF(TRIM(b.validbet),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_valid,
           CAST(NULLIF(TRIM(b.bet16),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_rebate,
           CAST(NULLIF(TRIM(b.bet17),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_net,
           CAST(NULLIF(TRIM(b.bet15),'') AS DECIMAL(20,6))                AS x_rbpct,
           COALESCE(CAST(NULLIF(TRIM(b.bet23),'') AS DECIMAL(20,6)),0)   AS x_agpct,
          NULLIF(CAST(NULLIF(TRIM(b.bet23),'') AS DECIMAL(20,6)),0)     AS x_rate1,
          NULLIF(CAST(NULLIF(TRIM(b.bet24),'') AS DECIMAL(20,6)),0)     AS x_rate2,
          NULLIF(CAST(NULLIF(TRIM(b.bet25),'') AS DECIMAL(20,6)),0)     AS x_rate3,
          NULLIF(CAST(NULLIF(TRIM(b.bet26),'') AS DECIMAL(20,6)),0)     AS x_rate4,
          NULLIF(CAST(NULLIF(TRIM(b.bet27),'') AS DECIMAL(20,6)),0)     AS x_rate5,
          (CASE WHEN NULLIF(CAST(NULLIF(TRIM(b.bet22),'') AS BIGINT),0) IS NOT NULL THEN 5
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet21),'') AS BIGINT),0) IS NOT NULL THEN 4
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet20),'') AS BIGINT),0) IS NOT NULL THEN 3
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet19),'') AS BIGINT),0) IS NOT NULL THEN 2
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet18),'') AS BIGINT),0) IS NOT NULL THEN 1
                ELSE 0 END)                                             AS x_chain_depth,
           CASE WHEN COALESCE(t1.agent_id,t2.agent_id,t3.agent_id,
                              t4.agent_id,t5.agent_id) IS NOT NULL
                THEN 1 ELSE 0 END                                        AS f_testline
    FROM x_ranked b
    LEFT JOIN x_testagent t1 ON t1.agent_id = b.bet18
    LEFT JOIN x_testagent t2 ON t2.agent_id = b.bet19
    LEFT JOIN x_testagent t3 ON t3.agent_id = b.bet20
    LEFT JOIN x_testagent t4 ON t4.agent_id = b.bet21
    LEFT JOIN x_testagent t5 ON t5.agent_id = b.bet22
    WHERE b.x_rn = 1
      AND b.category='1' AND UPPER(TRIM(b.bet38))='N'
      AND CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8)) > 0
  ),
  x_mk AS (
    SELECT s.*,
           CASE WHEN s.f_testline = 0 THEN 1 ELSE 0 END                 AS is_clean
    FROM x_bs0 s
  ),
  x_agg AS (
    SELECT s.x_member                                                        AS x_key,
           COUNT(*) AS n_bets, COUNT(DISTINCT s.x_round) AS n_rounds,
           COUNT(DISTINCT s.x_date) AS active_days, COUNT(DISTINCT s.x_tblshoe) AS active_shoes,
           COUNT(DISTINCT CONCAT_WS('|', s.x_date, s.x_table)) AS active_sessions,
           COUNT(DISTINCT s.x_table) AS n_tables, COUNT(DISTINCT s.x_dealer) AS n_dealers,
           COUNT(DISTINCT s.x_ip) AS n_ips, COUNT(DISTINCT s.x_product) AS n_products,
           MIN(s.x_date) AS first_seen_d, MAX(s.x_date) AS last_seen_d,
           SUM(s.x_stake) AS stake, SUM(s.x_valid) AS valid, SUM(s.x_rebate) AS rebate,
           SUM(s.x_net) AS net, SUM(-s.x_net *(100.0-s.x_agpct)/100.0) AS agent_cost,
           AVG(100.0-s.x_agpct)                   AS agent_pct,
           AVG(s.x_agpct)                         AS company_retain_pct,
           SUM(-s.x_net *s.x_agpct/100.0)         AS agent_cost_a_legacy,
           SUM(s.x_valid*s.x_agpct/100.0)         AS agent_cost_valid_base_legacy,
          AVG(COALESCE(s.x_rate1,100)) AS retain_pct_lv1, AVG(COALESCE(s.x_rate2,100)) AS retain_pct_lv2,
          AVG(COALESCE(s.x_rate3,100)) AS retain_pct_lv3, AVG(COALESCE(s.x_rate4,100)) AS retain_pct_lv4,
          AVG(COALESCE(s.x_rate5,100)) AS retain_pct_lv5, AVG(s.x_chain_depth) AS chain_depth_avg,
          AVG(COALESCE(100.0-s.x_rate1,0)) AS agent_pct_lv1, AVG(COALESCE(100.0-s.x_rate2,0)) AS agent_pct_lv2,
          AVG(COALESCE(100.0-s.x_rate3,0)) AS agent_pct_lv3, AVG(COALESCE(100.0-s.x_rate4,0)) AS agent_pct_lv4,
          AVG(COALESCE(100.0-s.x_rate5,0)) AS agent_pct_lv5,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate1,0)/100.0)                        AS agent_cost_lv1,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate2,0)/100.0)                        AS agent_cost_lv2,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate3,0)/100.0)                        AS agent_cost_lv3,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate4,0)/100.0)                        AS agent_cost_lv4,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate5,0)/100.0)                        AS agent_cost_lv5,
          SUM(-s.x_net*(COALESCE(100.0-s.x_rate1,0)+COALESCE(100.0-s.x_rate2,0)
                       +COALESCE(100.0-s.x_rate3,0)+COALESCE(100.0-s.x_rate4,0)
                       +COALESCE(100.0-s.x_rate5,0))/100.0)                   AS agent_cost_chain_additive,
          SUM(-s.x_net*(1.0 - CAST(COALESCE(s.x_rate1,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate2,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate3,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate4,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate5,100) AS DOUBLE)/100.0))
                                                                       AS agent_cost_chain_nested,
           AVG(s.x_rbpct) AS rbpct, AVG(s.x_freecomm*1.0) AS freecomm_rate,
           PERCENTILE_APPROX(s.x_stake,0.25) AS p25, PERCENTILE_APPROX(s.x_stake,0.50) AS p50,
           PERCENTILE_APPROX(s.x_stake,0.75) AS p75, PERCENTILE_APPROX(s.x_stake,0.90) AS p90,
           PERCENTILE_APPROX(s.x_stake,0.95) AS p95, PERCENTILE_APPROX(s.x_stake,0.99) AS p99,
           PERCENTILE_APPROX(s.x_valid,0.50) AS p50_valid,
           PERCENTILE_APPROX(s.x_net,0.50)   AS p50_profit,
           SUM(CASE WHEN s.x_valid > s.x_stake THEN s.x_stake ELSE 0 END) AS st_in,
           SUM(CASE WHEN s.x_valid > s.x_stake THEN 1 ELSE 0 END)         AS nb_in,
           SUM(CASE WHEN s.x_valid > s.x_stake THEN s.x_net ELSE 0 END)   AS net_in,
           SUM(CASE WHEN NOT (s.x_valid > s.x_stake) THEN s.x_stake ELSE 0 END) AS st_out,
           SUM(CASE WHEN NOT (s.x_valid > s.x_stake) THEN 1 ELSE 0 END)         AS nb_out,
           SUM(CASE WHEN NOT (s.x_valid > s.x_stake) THEN s.x_net ELSE 0 END)   AS net_out,
           SUM(CASE WHEN s.x_rec=1 THEN s.x_stake ELSE 0 END) AS st_rec,
           SUM(CASE WHEN s.x_rec=1 THEN 1 ELSE 0 END)         AS nb_rec
    FROM x_mk s
    WHERE s.is_clean = 1
      AND s.x_member IS NOT NULL AND TRIM(CAST(s.x_member AS STRING)) <> ''
    GROUP BY s.x_member
  ),
  x_win AS (
    SELECT            COUNT(*) AS n_bets, COUNT(DISTINCT s.x_round) AS n_rounds,
           COUNT(DISTINCT s.x_date) AS active_days, COUNT(DISTINCT s.x_tblshoe) AS active_shoes,
           COUNT(DISTINCT CONCAT_WS('|', s.x_date, s.x_table)) AS active_sessions,
           COUNT(DISTINCT s.x_table) AS n_tables, COUNT(DISTINCT s.x_dealer) AS n_dealers,
           COUNT(DISTINCT s.x_ip) AS n_ips, COUNT(DISTINCT s.x_product) AS n_products,
           MIN(s.x_date) AS first_seen_d, MAX(s.x_date) AS last_seen_d,
           SUM(s.x_stake) AS stake, SUM(s.x_valid) AS valid, SUM(s.x_rebate) AS rebate,
           SUM(s.x_net) AS net, SUM(-s.x_net *(100.0-s.x_agpct)/100.0) AS agent_cost,
           AVG(100.0-s.x_agpct)                   AS agent_pct,
           AVG(s.x_agpct)                         AS company_retain_pct,
           SUM(-s.x_net *s.x_agpct/100.0)         AS agent_cost_a_legacy,
           SUM(s.x_valid*s.x_agpct/100.0)         AS agent_cost_valid_base_legacy,
          AVG(COALESCE(s.x_rate1,100)) AS retain_pct_lv1, AVG(COALESCE(s.x_rate2,100)) AS retain_pct_lv2,
          AVG(COALESCE(s.x_rate3,100)) AS retain_pct_lv3, AVG(COALESCE(s.x_rate4,100)) AS retain_pct_lv4,
          AVG(COALESCE(s.x_rate5,100)) AS retain_pct_lv5, AVG(s.x_chain_depth) AS chain_depth_avg,
          AVG(COALESCE(100.0-s.x_rate1,0)) AS agent_pct_lv1, AVG(COALESCE(100.0-s.x_rate2,0)) AS agent_pct_lv2,
          AVG(COALESCE(100.0-s.x_rate3,0)) AS agent_pct_lv3, AVG(COALESCE(100.0-s.x_rate4,0)) AS agent_pct_lv4,
          AVG(COALESCE(100.0-s.x_rate5,0)) AS agent_pct_lv5,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate1,0)/100.0)                        AS agent_cost_lv1,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate2,0)/100.0)                        AS agent_cost_lv2,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate3,0)/100.0)                        AS agent_cost_lv3,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate4,0)/100.0)                        AS agent_cost_lv4,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate5,0)/100.0)                        AS agent_cost_lv5,
          SUM(-s.x_net*(COALESCE(100.0-s.x_rate1,0)+COALESCE(100.0-s.x_rate2,0)
                       +COALESCE(100.0-s.x_rate3,0)+COALESCE(100.0-s.x_rate4,0)
                       +COALESCE(100.0-s.x_rate5,0))/100.0)                   AS agent_cost_chain_additive,
          SUM(-s.x_net*(1.0 - CAST(COALESCE(s.x_rate1,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate2,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate3,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate4,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate5,100) AS DOUBLE)/100.0))
                                                                       AS agent_cost_chain_nested,
           AVG(s.x_rbpct) AS rbpct, AVG(s.x_freecomm*1.0) AS freecomm_rate,
           PERCENTILE_APPROX(s.x_stake,0.25) AS p25, PERCENTILE_APPROX(s.x_stake,0.50) AS p50,
           PERCENTILE_APPROX(s.x_stake,0.75) AS p75, PERCENTILE_APPROX(s.x_stake,0.90) AS p90,
           PERCENTILE_APPROX(s.x_stake,0.95) AS p95, PERCENTILE_APPROX(s.x_stake,0.99) AS p99,
           PERCENTILE_APPROX(s.x_valid,0.50) AS p50_valid,
           PERCENTILE_APPROX(s.x_net,0.50)   AS p50_profit,
           SUM(CASE WHEN s.x_valid > s.x_stake THEN s.x_stake ELSE 0 END) AS st_in,
           SUM(CASE WHEN s.x_valid > s.x_stake THEN 1 ELSE 0 END)         AS nb_in,
           SUM(CASE WHEN s.x_valid > s.x_stake THEN s.x_net ELSE 0 END)   AS net_in,
           SUM(CASE WHEN NOT (s.x_valid > s.x_stake) THEN s.x_stake ELSE 0 END) AS st_out,
           SUM(CASE WHEN NOT (s.x_valid > s.x_stake) THEN 1 ELSE 0 END)         AS nb_out,
           SUM(CASE WHEN NOT (s.x_valid > s.x_stake) THEN s.x_net ELSE 0 END)   AS net_out,
           SUM(CASE WHEN s.x_rec=1 THEN s.x_stake ELSE 0 END) AS st_rec,
           SUM(CASE WHEN s.x_rec=1 THEN 1 ELSE 0 END)         AS nb_rec
    FROM x_mk s
    WHERE s.is_clean = 1
      AND s.x_member IS NOT NULL AND TRIM(CAST(s.x_member AS STRING)) <> ''
  ),
      q AS (
        SELECT                                                                                              -- 取列：起始取列子句
          'validbet 契约普查（全窗 · 百家乐）'                                    AS scope,                  -- 字面取值：受检范围
          COUNT(*)                                                               AS n_rows,                 -- 计数表达式：总行数
          SUM(CASE WHEN validbet IS NULL THEN 1 ELSE 0 END)                      AS n_vb_null,              -- 条件计数：raw 为空值
          SUM(CASE WHEN validbet IS NOT NULL AND TRIM(validbet) = '' THEN 1 ELSE 0 END) AS n_vb_blank,      -- 条件计数：raw 为空串
          SUM(CASE WHEN CAST(NULLIF(TRIM(validbet), '') AS DECIMAL(20,8)) = 0 THEN 1 ELSE 0 END) AS n_vb_zero, -- 条件计数：raw 为零
          SUM(CASE WHEN CAST(NULLIF(TRIM(validbet), '') AS DECIMAL(20,8)) > 0 THEN 1 ELSE 0 END) AS n_vb_pos,  -- 条件计数：raw 为正
          SUM(CASE WHEN CAST(NULLIF(TRIM(validbet), '') AS DECIMAL(20,8)) < 0 THEN 1 ELSE 0 END) AS n_vb_neg,  -- 条件计数：★ raw 为负——若非零须追成因
          ROUND(SUM(CASE WHEN NULLIF(TRIM(validbet), '') IS NULL THEN 1 ELSE 0 END) * 100.0
                / NULLIF(COUNT(*), 0), 8)                                        AS null_rate_pct,          -- 比率表达式：★★ 回退触发率——二式分歧之量
          SUM(CASE WHEN NULLIF(TRIM(validbet), '') IS NULL
                     AND NULLIF(TRIM(bet13), '') IS NULL THEN 1 ELSE 0 END)      AS n_fallback_also_null,   -- 条件计数：★ 回退源 bet13 亦空——契约在此失效
          ROUND(SUM(CAST(NULLIF(TRIM(validbet), '') AS DECIMAL(20,8))), 2)       AS vb_sum,                 -- 汇总表达式：raw 总额
          ROUND(SUM(CAST(NULLIF(TRIM(bet13), '') AS DECIMAL(20,8))), 2)          AS b13_sum,                -- 汇总表达式：本金总额——与 vb 对照
          ROUND(SUM(CAST(NULLIF(TRIM(bet41), '') AS DECIMAL(20,8))), 2)          AS b41_sum,                -- 汇总表达式：bet41 总额
          CASE                                                                                              -- 条件分支：起始分支——契约裁定
            WHEN SUM(CASE WHEN NULLIF(TRIM(validbet), '') IS NULL THEN 1 ELSE 0 END) = 0
              THEN '◐ 本窗口内 null_rate = 0 —— 直取与 COALESCE 二式**数据条件等价**（★ 非设计等价，换窗须重验）' -- 分支判定：暂时等价
            ELSE '❌ 二式分歧 —— 须立唯一契约 validbet_effective，禁各章各自为政'                              -- 分支判定：须立契约
          END                                                                    AS verdict_contract        -- 条件分支：收束上方判词，产出「verdict_contract」
        FROM ods_mariadb_2b.ods_a168_bet02                                                                  -- 取数来源：取自注单主表
        WHERE dt >= '2026-03-21' AND dt < '2026-08-07'                                                      -- 过滤条件：限定分析窗
          AND sync_time <= '2026-08-27 09:00:00'
          AND CAST(bet02 AS STRING) = '101'                                                                -- 并列条件：限定百家乐
      )
    SELECT q.*,
           -- 一·经济层
           ROUND(e.stake,4) AS stake, ROUND(e.valid,4) AS valid_bet,
           ROUND(-e.net,4) AS profit, e.n_bets, e.n_rounds,
           ROUND(e.net/NULLIF(e.stake,0),8) AS roi,
           ROUND(e.net_in/NULLIF(e.st_in,0),8) AS roi_hiturn,
           ROUND(e.net_out/NULLIF(e.st_out,0),8) AS roi_non_hiturn,
           ROUND((e.net-e.rebate)/NULLIF(e.stake,0),8) AS roi_ex_rebate,
           ROUND(e.net,4) AS roi_numerator, ROUND(e.stake,4) AS roi_denominator,
           CASE WHEN e.stake IS NULL THEN 'NULL_DENOM' WHEN e.stake<=0 THEN 'ZERO_DENOM'
                WHEN e.n_bets<30 THEN 'THIN_EXPOSURE' ELSE 'OK' END AS roi_denominator_status,
           ROUND(e.rebate,4) AS rebate_cost, ROUND(e.agent_cost,4)                           AS cost_complement_b,
       ROUND(e.agent_pct,4)                            AS pct_complement,
       ROUND(e.company_retain_pct,4)                   AS pct_top_bet23,
       'AG03-UNRESOLVED'                                     AS agent_formula_version,
      'ALL5_LEVELS_bet23_to_bet27'                    AS agent_level_scope,
      ROUND(e.agent_cost_lv1,4) AS agent_cost_lv1, ROUND(e.agent_cost_lv2,4) AS agent_cost_lv2,
      ROUND(e.agent_cost_lv3,4) AS agent_cost_lv3, ROUND(e.agent_cost_lv4,4) AS agent_cost_lv4,
      ROUND(e.agent_cost_lv5,4) AS agent_cost_lv5,
      ROUND(e.agent_pct_lv1,6) AS agent_pct_lv1, ROUND(e.agent_pct_lv2,6) AS agent_pct_lv2,
      ROUND(e.agent_pct_lv3,6) AS agent_pct_lv3, ROUND(e.agent_pct_lv4,6) AS agent_pct_lv4,
      ROUND(e.agent_pct_lv5,6) AS agent_pct_lv5,
      ROUND(e.retain_pct_lv1,6) AS retain_pct_lv1, ROUND(e.retain_pct_lv2,6) AS retain_pct_lv2,
      ROUND(e.retain_pct_lv3,6) AS retain_pct_lv3, ROUND(e.retain_pct_lv4,6) AS retain_pct_lv4,
      ROUND(e.retain_pct_lv5,6) AS retain_pct_lv5, ROUND(e.chain_depth_avg,4) AS chain_depth_avg,
      ROUND(e.agent_cost_chain_additive,4)            AS agent_cost_chain_additive,
      ROUND(e.agent_cost_chain_nested,4)              AS agent_cost_chain_nested,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_additive,4) AS residual_chain_additive,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_nested,4)   AS residual_chain_nested,
      'PENDING_AG03'                                  AS decision_status,
      'FALSE'                                         AS admit_to_risk_decision,
      'NOT_FOR_ENFORCEMENT'                           AS deliverable_class,
       ROUND(e.agent_cost_a_legacy,4)                  AS agent_cost_a_legacy,
       ROUND(e.agent_cost_valid_base_legacy,4)         AS agent_cost_valid_base_legacy,
           ROUND(-e.net-e.rebate,4)                        AS ngr,
       ROUND(-e.net-e.rebate-e.agent_cost,4)           AS residual_b,
       ROUND(-e.net-e.rebate-e.agent_cost_a_legacy,4)  AS residual_a,
           ROUND((-e.net-e.rebate)/NULLIF(e.stake,0),8)    AS ngr_rate,
       ROUND((-e.net-e.rebate-e.agent_cost)/NULLIF(e.stake,0),8)   AS residual_b_rate,
      -- 【HF9c · canonical accounting contract】
      --   以下 canonical 字段只增加明确 scope；不删除、不覆盖既有字段。
      --   formal_bet23_* 保持 HF9b 当前生产公式及其 NULL/0 语义；
      --   lv1~lv5 / additive / nested 则分别采用各自原始 e.* 成本字段，
      --   rate 一律从未舍入的 e.* 分子 / e.stake 计算，禁止由展示值反算。
      ROUND(e.agent_cost,4) AS agent_cost_bet23_formal_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost,4) AS net_margin_bet23_formal_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost)/NULLIF(e.stake,0),8) AS net_margin_bet23_formal_rate_canonical,
      ROUND(e.agent_cost_lv1,4) AS agent_cost_lv1_bet23_canonical,
      ROUND(e.agent_cost_lv2,4) AS agent_cost_lv2_bet24_canonical,
      ROUND(e.agent_cost_lv3,4) AS agent_cost_lv3_bet25_canonical,
      ROUND(e.agent_cost_lv4,4) AS agent_cost_lv4_bet26_canonical,
      ROUND(e.agent_cost_lv5,4) AS agent_cost_lv5_bet27_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_lv1,4) AS net_margin_lv1_bet23_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_lv1)/NULLIF(e.stake,0),8) AS net_margin_lv1_bet23_rate_canonical,
      ROUND(e.agent_cost_chain_additive,4) AS agent_cost_chain_additive_canonical,
      ROUND(e.agent_cost_chain_nested,4) AS agent_cost_chain_nested_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_additive,4) AS net_margin_chain_additive_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_nested,4) AS net_margin_chain_nested_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_chain_additive)/NULLIF(e.stake,0),8) AS net_margin_chain_additive_rate_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_chain_nested)/NULLIF(e.stake,0),8) AS net_margin_chain_nested_rate_canonical,
       ROUND((-e.net-e.rebate-e.agent_cost_a_legacy)/NULLIF(e.stake,0),8) AS residual_a_rate,
           -- 二·分布层
           ROUND(e.stake/NULLIF(e.n_bets,0),4) AS avg_stake_per_bet,
           ROUND(e.valid/NULLIF(e.n_rounds,0),4) AS avg_valid_bet_per_round,
           ROUND(-e.net/NULLIF(e.n_rounds,0),4) AS avg_profit_per_round,
           ROUND(-e.net/NULLIF(e.active_days,0),4) AS avg_profit_per_day,
           ROUND(-e.net/NULLIF(e.active_shoes,0),4) AS avg_profit_per_shoe,
           ROUND(e.stake/NULLIF(e.active_days,0),4) AS avg_stake_per_active_day,
           ROUND(e.n_rounds*1.0/NULLIF(e.active_days,0),4) AS avg_rounds_per_active_day,
           ROUND(e.st_in/NULLIF(e.nb_in,0),4) AS avg_stake_hiturn,
           ROUND(e.st_out/NULLIF(e.nb_out,0),4) AS avg_stake_non_hiturn,
           ROUND(e.p25,4) AS p25_stake, ROUND(e.p50,4) AS p50_stake, ROUND(e.p75,4) AS p75_stake,
           ROUND(e.p90,4) AS p90_stake, ROUND(e.p95,4) AS p95_stake, ROUND(e.p99,4) AS p99_stake,
           ROUND(e.p50_valid,4) AS p50_valid_bet, ROUND(e.p50_profit,4) AS p50_profit,
           ROUND(e.p95/NULLIF(e.p50,0),6) AS p95_over_p50,
           ROUND(e.p99/NULLIF(e.p50,0),6) AS p99_over_p50,
           ROUND((e.stake/NULLIF(e.n_bets,0))/NULLIF(e.p50,0),6) AS avg_over_p50,
           -- 三·关系层
           e.n_tables AS common_table_count, e.n_dealers AS common_dealer_count,
           e.n_ips AS common_ip_count, e.n_products AS common_product_count,
           ROUND(e.st_in/NULLIF(e.stake,0),8) AS share_hiturn,
           -- 四·rate 层
           ROUND(-e.net/NULLIF(e.stake,0),8) AS hold_rate,
           ROUND(-e.net_in/NULLIF(e.st_in,0),8) AS hold_rate_hiturn,
           ROUND(e.rebate/NULLIF(e.valid,0),8) AS rebate_rate_actual,
           ROUND(e.rbpct,6) AS rebate_pct_config,
           ROUND(e.valid/NULLIF(e.stake,0),6) AS turnover_multiple,
           ROUND(e.freecomm_rate,6) AS free_comm_rate,
           ROUND(e.net_in/NULLIF(e.st_in,0)-e.net_out/NULLIF(e.st_out,0),8) AS roi_delta_hiturn,
           -- 五·动态层
           e.first_seen_d AS first_seen, e.last_seen_d AS last_seen,
           e.active_days, e.active_shoes, e.active_sessions,
           DATEDIFF(e.last_seen_d, e.first_seen_d)+1 AS span_days,
           ROUND(e.active_days*1.0/NULLIF(DATEDIFF(e.last_seen_d,e.first_seen_d)+1,0),6) AS persistence,
           ROUND((e.st_in/NULLIF(e.nb_in,0))/NULLIF(e.st_out/NULLIF(e.nb_out,0),0),6) AS ramp_hiturn,
           ROUND((e.st_rec/NULLIF(e.nb_rec,0))/NULLIF(e.stake/NULLIF(e.n_bets,0),0),6) AS ramp_recent,
           ROUND((e.st_rec/NULLIF(e.stake,0))/0.30,6) AS stake_ramp,
           -- 六·决策层（HF9g-P5 · D-14 斧正 —— 本件属【全窗基线族】，相对刻度与决策标签一律 NULL）
           --   病灶：x_win 系全窗单行聚合（无 GROUP BY，恒 1 行，此为设计使然，非缺陷），
           --         经 CROSS JOIN 接入后 e.* 全行同值；六层之 NTILE / PERCENT_RANK 施于常数即退化，
           --         PERCENT_RANK 恒 0 ⇒ action_priority 恒判 A，全件 100% 误标。
           --   ★ 斧正原则：不给 x_win 补 GROUP BY —— 那会改变其「全窗基线」语义，属退化。
           --     正解与 #018 之 G-05／G-06 同治：范围外之行不得接受任何下游评分与决策标签。
           --   ★ 本件之 e.* 仍照常供其它列作全窗基线使用，仅六层相对刻度与决策标签置 NULL。
           CAST(NULL AS INT)                                              AS vip_tier,                        -- 空值取值：全窗基线族无实体可分档，置 NULL（NULL＝不适用，非 0）
           CAST(NULL AS DOUBLE)                                           AS economic_value,                  -- 空值取值：同上，禁以常数百分位冒充经济价值
           CAST(NULL AS DOUBLE)                                           AS roi_pr_global,                   -- 空值取值：同上
           CAST(NULL AS DOUBLE)                                           AS risk_value,                      -- 空值取值：兼容列，同上
           CAST(NULL AS DOUBLE)                                           AS pr_stake,                        -- 空值取值：兼容列，同上
           CAST(NULL AS DOUBLE)                                           AS pr_global,                       -- 空值取值：同上
           CAST(NULL AS DOUBLE)                                           AS pr_qualified,                    -- 空值取值：同上
           'GLOBAL_BASELINE_NO_ENTITY_RANKING'                            AS pr_qualified_population,         -- 字面取值：血统 —— 明示本件为全窗基线族，无实体排序总体
           CAST(NULL AS BIGINT)                                           AS pr_global_population_n,          -- 空值取值：血统 —— 不适用
           CAST(NULL AS BIGINT)                                           AS pr_qualified_population_n,       -- 空值取值：血统 —— 不适用
           'NOT_APPLICABLE_GLOBAL_BASELINE'                               AS pr_calculation_method,           -- 字面取值：血统 —— 算法不适用
           'HF9g-P5'                                                      AS pr_calculation_version,          -- 字面取值：血统 —— 算法版本
           CAST(NULL AS STRING)                                           AS evidence_flag,                   -- 空值取值：证据旗标不适用于全窗基线
           CAST(NULL AS STRING)                                           AS evidence_rate,                   -- 空值取值：同上
           CAST(NULL AS DOUBLE)                                           AS hold_ci_halfwidth_approx,        -- 空值取值：同上
           'X 全窗基线 · 不参与实体赏罚'                                    AS action_priority                  -- 字面取值：★ D-14 斧正 —— 本族恒不入赏罚，取代原 100% 误标之「A」
    FROM q
    CROSS JOIN x_win e
  ) y
) z
-- ── 逐批 WHERE 阶梯（★ 口诀：上界 ＝ 下界 ＋ 100000，两数同进）──
--    本件 T_true 未测，无需先跑 T_true；以 0 / 100000 控制本批返回区间，末批由实际行数 < 100000 判定
--    WHERE z.audit_rn >        0 AND z.audit_rn <=   100000   -- 第 1 批
--    WHERE z.audit_rn >   100000 AND z.audit_rn <=   200000   -- 第 2 批
--    WHERE z.audit_rn >   200000 AND z.audit_rn <=   300000   -- 第 3 批
--    WHERE z.audit_rn >   300000 AND z.audit_rn <=   400000   -- 第 4 批
--    WHERE z.audit_rn >   400000 AND z.audit_rn <=   500000   -- 第 5 批
--    WHERE z.audit_rn >   500000 AND z.audit_rn <=   600000   -- 第 6 批
--    WHERE z.audit_rn >   600000 AND z.audit_rn <=   700000   -- 第 7 批
--    …余批类推。第 k 批：WHERE z.audit_rn > (k-1)*100000 AND z.audit_rn <= k*100000
--    某批返回 < 100000 行即为末批，其后不再取。
--
--    ⚠ 常见误写（务必避开）：只推下界而上界不动 ——
--        WHERE z.audit_rn > 100000 AND z.audit_rn <= 100000   ← 自相矛盾，恒为假，返回空集
--        WHERE z.audit_rn > 200000 AND z.audit_rn <= 100000   ← 同上，空集
--      两个数必须**同时**前进，且始终相差 100000。
--      下界 ＝ 上一批之上界；上界 ＝ 本批之上界。
WHERE z.audit_rn > 0 AND z.audit_rn <= 100000 -- ★ HF9c 本批区间
ORDER BY z.audit_rn;


-- ══════════════════════════════════════════════════════════════════════════════════════════════
-- 100. VB_00b_zero_five_rates.csv   [总包行 10801~10869 · 原 18 列 ＋六层约 60 列]
--     典型学：M05 退水套利　派生旗标：hiturn（s.x_valid > s.x_stake · 仅供 CASE 条件聚合，全包无任何 WHERE/AND/HAVING 以此过滤）　连接：全窗基线
-- ══════════════════════════════════════════════════════════════════════════════════════════════
-- ★ W-64 · D-14 警示（本件属 x_win 族 · 66 件之一 · 详见 §Z 段 D-14 全案）
--   本件以 `CROSS JOIN x_win e` 接入全局基线，x_win 无 GROUP BY ⇒ 恒 1 行 ⇒ e.* 全行同值。
--   故：economic_value / roi_pr_global / risk_value / pr_stake / pr_global 恒为 0；
--       action_priority 每一行皆为「A 净亏最大十分位 · 优先复核」（Z 分支永不触发）；
--       evidence_rate 恒为最高档；vip_tier 由常数键分档 ⇒ 无信息且非确定。
--   ⇒ 本件决策层三列 **NOT_FOR_DECISION**，裁定前不得用于排班、抽查或汇报。
-- ── ① 先跑 T_true 留档（不足 100000 者一次导全，不必分批）──
-- ── ① T_true：HF9c 不再强制预跑完整 COUNT。
--    本批实际返回行数 < 100000 即判定为末批；全批完成后以各批 n_rows / audit_rn 范围核对总量。

-- ── ② 分批取数：第 1 批。第 k 批只改末行两数为 (k-1)*100000 与 k*100000 ──
--    审计字段二（REDTEAM 2026-08-24 裁定 · 四锁）：
--      audit_rn  全局观测坐标 —— 由**与原版审计版逐字同一**之排序键所生，两版可逐行对账
--      batch_id  物理分批信息 —— 该行所属批次，由 audit_rn 算得，非引擎所赋
--    ★ 锁三：二者皆为审计字段，**不得进入任何业务指标计算**。
--    ★ 锁四：两版经 audit_rn 逐行字段核验后，方可宣布输出完全一致。

-- ── ③ 每批取回后自证四数（任一不符即停手回报，禁止放行）──
--    n_rows        = COUNT(*)      须等于 COUNT(DISTINCT audit_rn)   （批内无重复）
--    audit_rn_min  = MIN(audit_rn) 须等于 (k-1)*100000 + 1           （与上批严丝合缝）
--    audit_rn_max  = MAX(audit_rn) 须等于 min + n_rows - 1           （批内无缺口）
--    全批取毕再验：各批 audit_rn 之并集 = 1 .. T_true，无缺号、无重号。
--     ★ 首行＝平台真净亏最多者（已扣退水与代理占成）。
--
SELECT z.*,
       CAST(FLOOR((z.audit_rn - 1) / 100000) + 1 AS INT)          AS batch_id,
       'A168_HF9F_20260827_0900' AS run_id,
       '2026-08-27 09:00:00' AS snapshot_sync_time
FROM (
  SELECT y.*,
         ROW_NUMBER() OVER (ORDER BY y.`residual_b` ASC, y.`roi` DESC, y.`scope`, y.`n_base_rows`, y.`n_active_member`, y.`n_zero_rows`, y.`n_zero_member`, y.`zero_record_rate_pct`, y.`zero_amount_rate_pct`, y.`zero_member_rate_pct`, y.`zero_profit_rate_pct`, y.`zero_active_rate_pct`, y.`zero_stake_sum`, y.`zero_ggr_sum`, y.`all_stake_sum`, y.`all_ggr_sum`, y.`zero_mu0_pct`, y.`base_mu0_pct`, y.`n_zero_both`, y.`verdict_zero`) AS audit_rn
  FROM (
    WITH
      x_ranked AS (
    SELECT b.bet01, b.bet03, b.bet04, b.bet05, b.bet09, b.bet11, b.bet13,
           b.bet15, b.bet16, b.bet17, b.bet18, b.bet19, b.bet20, b.bet21,
           b.bet22, b.bet23, b.bet24, b.bet25, b.bet26, b.bet27, b.bet38, b.bet39, b.category, b.commission,
           b.dt, b.eid, b.ip, b.validbet, b.updatetime, b.sync_time,
           ROW_NUMBER() OVER (
             PARTITION BY b.bet01
             ORDER BY b.updatetime DESC, b.sync_time DESC, b.dt DESC)      AS x_rn
    FROM ods_mariadb_2b.ods_a168_bet02 b
    WHERE b.dt >= '2026-03-21' AND b.dt < '2026-08-07'
      AND b.bet02 = '101'
      AND b.sync_time <= '2026-08-27 09:00:00'
  ),
    x_testagent AS (
    SELECT age001 AS agent_id FROM ods_mariadb_2b.ods_a168_agent WHERE age022 = '1'
  ),
    x_bs0 AS (
    SELECT b.bet05 AS x_member, b.eid AS x_dealer, b.bet39 AS x_table,
           b.bet03 AS x_shoe, b.ip AS x_ip, b.bet09 AS x_product, b.dt AS x_date,
           CONCAT_WS('|', b.bet03, b.bet04, b.bet39)                      AS x_round,
           CONCAT_WS('|', b.bet39, b.bet03)                               AS x_tblshoe,
           CAST(NULLIF(TRIM(b.bet04),'') AS INT)                          AS x_rno,
           CASE WHEN b.dt >= '2026-07-08' THEN 1 ELSE 0 END               AS x_rec,
           CASE WHEN TRIM(b.commission)='1' THEN 1 ELSE 0 END             AS x_freecomm,
           CAST(NULLIF(TRIM(b.bet13),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_stake,
           CAST(NULLIF(TRIM(b.validbet),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_valid,
           CAST(NULLIF(TRIM(b.bet16),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_rebate,
           CAST(NULLIF(TRIM(b.bet17),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_net,
           CAST(NULLIF(TRIM(b.bet15),'') AS DECIMAL(20,6))                AS x_rbpct,
           COALESCE(CAST(NULLIF(TRIM(b.bet23),'') AS DECIMAL(20,6)),0)   AS x_agpct,
          NULLIF(CAST(NULLIF(TRIM(b.bet23),'') AS DECIMAL(20,6)),0)     AS x_rate1,
          NULLIF(CAST(NULLIF(TRIM(b.bet24),'') AS DECIMAL(20,6)),0)     AS x_rate2,
          NULLIF(CAST(NULLIF(TRIM(b.bet25),'') AS DECIMAL(20,6)),0)     AS x_rate3,
          NULLIF(CAST(NULLIF(TRIM(b.bet26),'') AS DECIMAL(20,6)),0)     AS x_rate4,
          NULLIF(CAST(NULLIF(TRIM(b.bet27),'') AS DECIMAL(20,6)),0)     AS x_rate5,
          (CASE WHEN NULLIF(CAST(NULLIF(TRIM(b.bet22),'') AS BIGINT),0) IS NOT NULL THEN 5
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet21),'') AS BIGINT),0) IS NOT NULL THEN 4
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet20),'') AS BIGINT),0) IS NOT NULL THEN 3
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet19),'') AS BIGINT),0) IS NOT NULL THEN 2
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet18),'') AS BIGINT),0) IS NOT NULL THEN 1
                ELSE 0 END)                                             AS x_chain_depth,
           CASE WHEN COALESCE(t1.agent_id,t2.agent_id,t3.agent_id,
                              t4.agent_id,t5.agent_id) IS NOT NULL
                THEN 1 ELSE 0 END                                        AS f_testline
    FROM x_ranked b
    LEFT JOIN x_testagent t1 ON t1.agent_id = b.bet18
    LEFT JOIN x_testagent t2 ON t2.agent_id = b.bet19
    LEFT JOIN x_testagent t3 ON t3.agent_id = b.bet20
    LEFT JOIN x_testagent t4 ON t4.agent_id = b.bet21
    LEFT JOIN x_testagent t5 ON t5.agent_id = b.bet22
    WHERE b.x_rn = 1
      AND b.category='1' AND UPPER(TRIM(b.bet38))='N'
      AND CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8)) > 0
  ),
  x_mk AS (
    SELECT s.*,
           CASE WHEN s.f_testline = 0 THEN 1 ELSE 0 END                 AS is_clean
    FROM x_bs0 s
  ),
  x_agg AS (
    SELECT s.x_member                                                        AS x_key,
           COUNT(*) AS n_bets, COUNT(DISTINCT s.x_round) AS n_rounds,
           COUNT(DISTINCT s.x_date) AS active_days, COUNT(DISTINCT s.x_tblshoe) AS active_shoes,
           COUNT(DISTINCT CONCAT_WS('|', s.x_date, s.x_table)) AS active_sessions,
           COUNT(DISTINCT s.x_table) AS n_tables, COUNT(DISTINCT s.x_dealer) AS n_dealers,
           COUNT(DISTINCT s.x_ip) AS n_ips, COUNT(DISTINCT s.x_product) AS n_products,
           MIN(s.x_date) AS first_seen_d, MAX(s.x_date) AS last_seen_d,
           SUM(s.x_stake) AS stake, SUM(s.x_valid) AS valid, SUM(s.x_rebate) AS rebate,
           SUM(s.x_net) AS net, SUM(-s.x_net *(100.0-s.x_agpct)/100.0) AS agent_cost,
           AVG(100.0-s.x_agpct)                   AS agent_pct,
           AVG(s.x_agpct)                         AS company_retain_pct,
           SUM(-s.x_net *s.x_agpct/100.0)         AS agent_cost_a_legacy,
           SUM(s.x_valid*s.x_agpct/100.0)         AS agent_cost_valid_base_legacy,
          AVG(COALESCE(s.x_rate1,100)) AS retain_pct_lv1, AVG(COALESCE(s.x_rate2,100)) AS retain_pct_lv2,
          AVG(COALESCE(s.x_rate3,100)) AS retain_pct_lv3, AVG(COALESCE(s.x_rate4,100)) AS retain_pct_lv4,
          AVG(COALESCE(s.x_rate5,100)) AS retain_pct_lv5, AVG(s.x_chain_depth) AS chain_depth_avg,
          AVG(COALESCE(100.0-s.x_rate1,0)) AS agent_pct_lv1, AVG(COALESCE(100.0-s.x_rate2,0)) AS agent_pct_lv2,
          AVG(COALESCE(100.0-s.x_rate3,0)) AS agent_pct_lv3, AVG(COALESCE(100.0-s.x_rate4,0)) AS agent_pct_lv4,
          AVG(COALESCE(100.0-s.x_rate5,0)) AS agent_pct_lv5,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate1,0)/100.0)                        AS agent_cost_lv1,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate2,0)/100.0)                        AS agent_cost_lv2,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate3,0)/100.0)                        AS agent_cost_lv3,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate4,0)/100.0)                        AS agent_cost_lv4,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate5,0)/100.0)                        AS agent_cost_lv5,
          SUM(-s.x_net*(COALESCE(100.0-s.x_rate1,0)+COALESCE(100.0-s.x_rate2,0)
                       +COALESCE(100.0-s.x_rate3,0)+COALESCE(100.0-s.x_rate4,0)
                       +COALESCE(100.0-s.x_rate5,0))/100.0)                   AS agent_cost_chain_additive,
          SUM(-s.x_net*(1.0 - CAST(COALESCE(s.x_rate1,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate2,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate3,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate4,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate5,100) AS DOUBLE)/100.0))
                                                                       AS agent_cost_chain_nested,
           AVG(s.x_rbpct) AS rbpct, AVG(s.x_freecomm*1.0) AS freecomm_rate,
           PERCENTILE_APPROX(s.x_stake,0.25) AS p25, PERCENTILE_APPROX(s.x_stake,0.50) AS p50,
           PERCENTILE_APPROX(s.x_stake,0.75) AS p75, PERCENTILE_APPROX(s.x_stake,0.90) AS p90,
           PERCENTILE_APPROX(s.x_stake,0.95) AS p95, PERCENTILE_APPROX(s.x_stake,0.99) AS p99,
           PERCENTILE_APPROX(s.x_valid,0.50) AS p50_valid,
           PERCENTILE_APPROX(s.x_net,0.50)   AS p50_profit,
           SUM(CASE WHEN s.x_valid > s.x_stake THEN s.x_stake ELSE 0 END) AS st_in,
           SUM(CASE WHEN s.x_valid > s.x_stake THEN 1 ELSE 0 END)         AS nb_in,
           SUM(CASE WHEN s.x_valid > s.x_stake THEN s.x_net ELSE 0 END)   AS net_in,
           SUM(CASE WHEN NOT (s.x_valid > s.x_stake) THEN s.x_stake ELSE 0 END) AS st_out,
           SUM(CASE WHEN NOT (s.x_valid > s.x_stake) THEN 1 ELSE 0 END)         AS nb_out,
           SUM(CASE WHEN NOT (s.x_valid > s.x_stake) THEN s.x_net ELSE 0 END)   AS net_out,
           SUM(CASE WHEN s.x_rec=1 THEN s.x_stake ELSE 0 END) AS st_rec,
           SUM(CASE WHEN s.x_rec=1 THEN 1 ELSE 0 END)         AS nb_rec
    FROM x_mk s
    WHERE s.is_clean = 1
      AND s.x_member IS NOT NULL AND TRIM(CAST(s.x_member AS STRING)) <> ''
    GROUP BY s.x_member
  ),
  x_win AS (
    SELECT            COUNT(*) AS n_bets, COUNT(DISTINCT s.x_round) AS n_rounds,
           COUNT(DISTINCT s.x_date) AS active_days, COUNT(DISTINCT s.x_tblshoe) AS active_shoes,
           COUNT(DISTINCT CONCAT_WS('|', s.x_date, s.x_table)) AS active_sessions,
           COUNT(DISTINCT s.x_table) AS n_tables, COUNT(DISTINCT s.x_dealer) AS n_dealers,
           COUNT(DISTINCT s.x_ip) AS n_ips, COUNT(DISTINCT s.x_product) AS n_products,
           MIN(s.x_date) AS first_seen_d, MAX(s.x_date) AS last_seen_d,
           SUM(s.x_stake) AS stake, SUM(s.x_valid) AS valid, SUM(s.x_rebate) AS rebate,
           SUM(s.x_net) AS net, SUM(-s.x_net *(100.0-s.x_agpct)/100.0) AS agent_cost,
           AVG(100.0-s.x_agpct)                   AS agent_pct,
           AVG(s.x_agpct)                         AS company_retain_pct,
           SUM(-s.x_net *s.x_agpct/100.0)         AS agent_cost_a_legacy,
           SUM(s.x_valid*s.x_agpct/100.0)         AS agent_cost_valid_base_legacy,
          AVG(COALESCE(s.x_rate1,100)) AS retain_pct_lv1, AVG(COALESCE(s.x_rate2,100)) AS retain_pct_lv2,
          AVG(COALESCE(s.x_rate3,100)) AS retain_pct_lv3, AVG(COALESCE(s.x_rate4,100)) AS retain_pct_lv4,
          AVG(COALESCE(s.x_rate5,100)) AS retain_pct_lv5, AVG(s.x_chain_depth) AS chain_depth_avg,
          AVG(COALESCE(100.0-s.x_rate1,0)) AS agent_pct_lv1, AVG(COALESCE(100.0-s.x_rate2,0)) AS agent_pct_lv2,
          AVG(COALESCE(100.0-s.x_rate3,0)) AS agent_pct_lv3, AVG(COALESCE(100.0-s.x_rate4,0)) AS agent_pct_lv4,
          AVG(COALESCE(100.0-s.x_rate5,0)) AS agent_pct_lv5,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate1,0)/100.0)                        AS agent_cost_lv1,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate2,0)/100.0)                        AS agent_cost_lv2,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate3,0)/100.0)                        AS agent_cost_lv3,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate4,0)/100.0)                        AS agent_cost_lv4,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate5,0)/100.0)                        AS agent_cost_lv5,
          SUM(-s.x_net*(COALESCE(100.0-s.x_rate1,0)+COALESCE(100.0-s.x_rate2,0)
                       +COALESCE(100.0-s.x_rate3,0)+COALESCE(100.0-s.x_rate4,0)
                       +COALESCE(100.0-s.x_rate5,0))/100.0)                   AS agent_cost_chain_additive,
          SUM(-s.x_net*(1.0 - CAST(COALESCE(s.x_rate1,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate2,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate3,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate4,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate5,100) AS DOUBLE)/100.0))
                                                                       AS agent_cost_chain_nested,
           AVG(s.x_rbpct) AS rbpct, AVG(s.x_freecomm*1.0) AS freecomm_rate,
           PERCENTILE_APPROX(s.x_stake,0.25) AS p25, PERCENTILE_APPROX(s.x_stake,0.50) AS p50,
           PERCENTILE_APPROX(s.x_stake,0.75) AS p75, PERCENTILE_APPROX(s.x_stake,0.90) AS p90,
           PERCENTILE_APPROX(s.x_stake,0.95) AS p95, PERCENTILE_APPROX(s.x_stake,0.99) AS p99,
           PERCENTILE_APPROX(s.x_valid,0.50) AS p50_valid,
           PERCENTILE_APPROX(s.x_net,0.50)   AS p50_profit,
           SUM(CASE WHEN s.x_valid > s.x_stake THEN s.x_stake ELSE 0 END) AS st_in,
           SUM(CASE WHEN s.x_valid > s.x_stake THEN 1 ELSE 0 END)         AS nb_in,
           SUM(CASE WHEN s.x_valid > s.x_stake THEN s.x_net ELSE 0 END)   AS net_in,
           SUM(CASE WHEN NOT (s.x_valid > s.x_stake) THEN s.x_stake ELSE 0 END) AS st_out,
           SUM(CASE WHEN NOT (s.x_valid > s.x_stake) THEN 1 ELSE 0 END)         AS nb_out,
           SUM(CASE WHEN NOT (s.x_valid > s.x_stake) THEN s.x_net ELSE 0 END)   AS net_out,
           SUM(CASE WHEN s.x_rec=1 THEN s.x_stake ELSE 0 END) AS st_rec,
           SUM(CASE WHEN s.x_rec=1 THEN 1 ELSE 0 END)         AS nb_rec
    FROM x_mk s
    WHERE s.is_clean = 1
      AND s.x_member IS NOT NULL AND TRIM(CAST(s.x_member AS STRING)) <> ''
  ),
      q AS (
        WITH ta AS (                                                                                        -- 公共表表达式：开启中间结果集 ta——公司测试线代理
          SELECT DISTINCT age001 AS aid FROM ods_mariadb_2b.ods_a168_agent WHERE age022 = '1'               -- 取列与过滤：铁律④b——公司测试线
        ),                                                                                                  -- 续行：收束上方的子查询或函数括号
        rk AS (                                                                                             -- 公共表表达式：开启中间结果集 rk——同注单号取最新版本
          SELECT b.bet05, b.bet09, b.bet13, b.bet14, b.bet11, b.validbet, b.bet41,                          -- 取列：会员、注型、本金、派彩、汇率、洗码、bet41
                 b.bet18, b.bet19, b.bet20, b.bet21, b.bet22, b.category, b.bet38,                          -- 续行：五级代理、类别、重对标记
                 ROW_NUMBER() OVER (PARTITION BY b.bet01
                   ORDER BY b.updatetime DESC, b.sync_time DESC, b.dt DESC)      AS rn                      -- 行号窗口表达式：三级排序取最新（§M0-6 已证唯一）
          FROM ods_mariadb_2b.ods_a168_bet02 b                                                              -- 取数来源：取自注单主表
          WHERE b.dt >= '2026-03-21' AND b.dt < '2026-08-07'                                                -- 过滤条件：限定分析窗
            AND CAST(b.bet02 AS STRING) = '101'
      AND b.sync_time <= '2026-08-27 09:00:00'                                                             -- 并列条件：限定百家乐
        ),                                                                                                  -- 续行：收束上方的子查询或函数括号
        base AS (                                                                                           -- 公共表表达式：开启中间结果集 base——过基础闸之母体
          SELECT TRIM(r.bet05)                                                   AS mid,                    -- 取列：会员编号
                 TRIM(r.bet09)                                                   AS g9,                     -- 取列：注型
                 CAST(NULLIF(TRIM(r.bet13), '') AS DECIMAL(20,8))
                   / NULLIF(CAST(NULLIF(TRIM(r.bet11), '') AS DECIMAL(20,8)), 0) AS stake,                  -- 取值表达式：本金归一
                 (CAST(NULLIF(TRIM(r.bet13), '') AS DECIMAL(20,8))
                - CAST(NULLIF(TRIM(r.bet14), '') AS DECIMAL(20,8)))
                   / NULLIF(CAST(NULLIF(TRIM(r.bet11), '') AS DECIMAL(20,8)), 0) AS ggr,                    -- 取值表达式：毛利归一（本金减派彩）
                 CAST(NULLIF(TRIM(r.validbet), '') AS DECIMAL(20,8))             AS vb,                     -- 取列：洗码量原值
                 CAST(NULLIF(TRIM(r.bet41), '')    AS DECIMAL(20,8))             AS v41                     -- 取列：bet41 原值
          FROM rk r                                                                                         -- 取数来源：取自本条自建的中间结果集 rk
          LEFT JOIN ta t1 ON t1.aid = r.bet18                                                               -- 左连接：一级代理是否测试线
          LEFT JOIN ta t2 ON t2.aid = r.bet19                                                               -- 左连接：二级代理是否测试线
          LEFT JOIN ta t3 ON t3.aid = r.bet20                                                               -- 左连接：三级代理是否测试线
          LEFT JOIN ta t4 ON t4.aid = r.bet21                                                               -- 左连接：四级代理是否测试线
          LEFT JOIN ta t5 ON t5.aid = r.bet22                                                               -- 左连接：五级代理是否测试线
          WHERE r.rn = 1                                                                                    -- 过滤条件：基础闸①——最新版本
            AND r.category = '1'                                                                            -- 并列条件：基础闸②——一般注单
            AND UPPER(TRIM(r.bet38)) = 'N'                                                                  -- 并列条件：基础闸③——非重对
            AND COALESCE(t1.aid, t2.aid, t3.aid, t4.aid, t5.aid) IS NULL                                    -- 并列条件：基础闸④——非测试线
            AND CAST(NULLIF(TRIM(r.bet11), '') AS DECIMAL(20,8)) > 0                                        -- 并列条件：基础闸⑤——汇率为正
            AND CAST(NULLIF(TRIM(r.bet13), '') AS DECIMAL(20,8)) > 0                                        -- 并列条件：基础闸⑥——本金为正
        )                                                                                                   -- 续行：收束上方的子查询或函数括号
        SELECT                                                                                              -- 取列：起始取列子句
          'validbet 零值 · 五类平行分母（过基础闸之母体）'                          AS scope,                  -- 字面取值：受检范围
          COUNT(*)                                                               AS n_base_rows,            -- 计数表达式：母体记录数
          COUNT(DISTINCT mid)                                                    AS n_active_member,        -- 计数表达式：★ active_member——本件所立之定义
          SUM(CASE WHEN vb = 0 THEN 1 ELSE 0 END)                                AS n_zero_rows,            -- 条件计数：零值记录数
          COUNT(DISTINCT CASE WHEN vb = 0 THEN mid END)                          AS n_zero_member,          -- 条件去重计数：曾现零值之会员数
          ROUND(SUM(CASE WHEN vb = 0 THEN 1 ELSE 0 END) * 100.0
                / NULLIF(COUNT(*), 0), 6)                                        AS zero_record_rate_pct,   -- 比率表达式：①记录率——分母＝全部记录
          ROUND(SUM(CASE WHEN vb = 0 THEN stake ELSE 0 END) * 100.0
                / NULLIF(SUM(stake), 0), 6)                                      AS zero_amount_rate_pct,   -- 比率表达式：②金额率——分母＝全部本金
          ROUND(COUNT(DISTINCT CASE WHEN vb = 0 THEN mid END) * 100.0
                / NULLIF(COUNT(DISTINCT mid), 0), 6)                             AS zero_member_rate_pct,   -- 比率表达式：③会员率——分母＝有效会员
          ROUND(SUM(CASE WHEN vb = 0 THEN ABS(ggr) ELSE 0 END) * 100.0
                / NULLIF(SUM(ABS(ggr)), 0), 6)                                   AS zero_profit_rate_pct,   -- 比率表达式：④毛利率——分母＝全部毛利绝对值
          ROUND(COUNT(DISTINCT CASE WHEN vb = 0 THEN mid END) * 100.0
                / NULLIF(COUNT(DISTINCT mid), 0), 6)                             AS zero_active_rate_pct,   -- 比率表达式：⑤★ 活跃会员率——分母＝active_member，禁用全会员
          ROUND(SUM(CASE WHEN vb = 0 THEN stake ELSE 0 END), 2)                  AS zero_stake_sum,         -- 条件汇总：零值群之本金总额
          ROUND(SUM(CASE WHEN vb = 0 THEN ggr   ELSE 0 END), 2)                  AS zero_ggr_sum,           -- 条件汇总：零值群之毛利总额
          ROUND(SUM(stake), 2)                                                   AS all_stake_sum,          -- 汇总表达式：母体本金总额
          ROUND(SUM(ggr), 2)                                                     AS all_ggr_sum,            -- 汇总表达式：母体毛利总额
          ROUND(-1 * SUM(CASE WHEN vb = 0 THEN ggr ELSE 0 END) * 100.0
                / NULLIF(SUM(CASE WHEN vb = 0 THEN stake ELSE 0 END), 0), 6)     AS zero_mu0_pct,           -- 比率表达式：★ 零值群之 μ0——与母体 μ0 对照可判其性质
          ROUND(-1 * SUM(ggr) * 100.0 / NULLIF(SUM(stake), 0), 6)                AS base_mu0_pct,           -- 比率表达式：母体 μ0——基准
          SUM(CASE WHEN vb = 0 AND v41 = 0 THEN 1 ELSE 0 END)                    AS n_zero_both,            -- 条件计数：★ 二列皆零者——与 964 笔之交集判别
          CASE                                                                                              -- 条件分支：起始分支——五率一致性裁定
            WHEN ABS(SUM(CASE WHEN vb = 0 THEN 1 ELSE 0 END) * 100.0 / NULLIF(COUNT(*), 0)
                   - SUM(CASE WHEN vb = 0 THEN stake ELSE 0 END) * 100.0 / NULLIF(SUM(stake), 0)) > 5
              THEN '★ 记录率与金额率相差逾 5pp —— 零值集中于特定金额段，须按金额分层复验'                       -- 分支判定：金额偏斜
            WHEN ABS(SUM(CASE WHEN vb = 0 THEN 1 ELSE 0 END) * 100.0 / NULLIF(COUNT(*), 0)
                   - COUNT(DISTINCT CASE WHEN vb = 0 THEN mid END) * 100.0 / NULLIF(COUNT(DISTINCT mid), 0)) > 20
              THEN '★ 记录率与会员率相差逾 20pp —— 零值集中于少数会员或普及于多数会员，须按会员分层复验'          -- 分支判定：会员偏斜
            ELSE '◐ 五率量级相近 —— 零值形似结构性均匀分布（★ 仍须按注型复验，未可径断）'                        -- 分支判定：形似均匀
          END                                                                    AS verdict_zero            -- 条件分支：收束上方判词，产出「verdict_zero」
        FROM base                                                                                          -- 取数来源：取自本条自建的中间结果集 base
      )
    SELECT q.*,
           -- 一·经济层
           ROUND(e.stake,4) AS stake, ROUND(e.valid,4) AS valid_bet,
           ROUND(-e.net,4) AS profit, e.n_bets, e.n_rounds,
           ROUND(e.net/NULLIF(e.stake,0),8) AS roi,
           ROUND(e.net_in/NULLIF(e.st_in,0),8) AS roi_hiturn,
           ROUND(e.net_out/NULLIF(e.st_out,0),8) AS roi_non_hiturn,
           ROUND((e.net-e.rebate)/NULLIF(e.stake,0),8) AS roi_ex_rebate,
           ROUND(e.net,4) AS roi_numerator, ROUND(e.stake,4) AS roi_denominator,
           CASE WHEN e.stake IS NULL THEN 'NULL_DENOM' WHEN e.stake<=0 THEN 'ZERO_DENOM'
                WHEN e.n_bets<30 THEN 'THIN_EXPOSURE' ELSE 'OK' END AS roi_denominator_status,
           ROUND(e.rebate,4) AS rebate_cost, ROUND(e.agent_cost,4)                           AS cost_complement_b,
       ROUND(e.agent_pct,4)                            AS pct_complement,
       ROUND(e.company_retain_pct,4)                   AS pct_top_bet23,
       'AG03-UNRESOLVED'                                     AS agent_formula_version,
      'ALL5_LEVELS_bet23_to_bet27'                    AS agent_level_scope,
      ROUND(e.agent_cost_lv1,4) AS agent_cost_lv1, ROUND(e.agent_cost_lv2,4) AS agent_cost_lv2,
      ROUND(e.agent_cost_lv3,4) AS agent_cost_lv3, ROUND(e.agent_cost_lv4,4) AS agent_cost_lv4,
      ROUND(e.agent_cost_lv5,4) AS agent_cost_lv5,
      ROUND(e.agent_pct_lv1,6) AS agent_pct_lv1, ROUND(e.agent_pct_lv2,6) AS agent_pct_lv2,
      ROUND(e.agent_pct_lv3,6) AS agent_pct_lv3, ROUND(e.agent_pct_lv4,6) AS agent_pct_lv4,
      ROUND(e.agent_pct_lv5,6) AS agent_pct_lv5,
      ROUND(e.retain_pct_lv1,6) AS retain_pct_lv1, ROUND(e.retain_pct_lv2,6) AS retain_pct_lv2,
      ROUND(e.retain_pct_lv3,6) AS retain_pct_lv3, ROUND(e.retain_pct_lv4,6) AS retain_pct_lv4,
      ROUND(e.retain_pct_lv5,6) AS retain_pct_lv5, ROUND(e.chain_depth_avg,4) AS chain_depth_avg,
      ROUND(e.agent_cost_chain_additive,4)            AS agent_cost_chain_additive,
      ROUND(e.agent_cost_chain_nested,4)              AS agent_cost_chain_nested,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_additive,4) AS residual_chain_additive,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_nested,4)   AS residual_chain_nested,
      'PENDING_AG03'                                  AS decision_status,
      'FALSE'                                         AS admit_to_risk_decision,
      'NOT_FOR_ENFORCEMENT'                           AS deliverable_class,
       ROUND(e.agent_cost_a_legacy,4)                  AS agent_cost_a_legacy,
       ROUND(e.agent_cost_valid_base_legacy,4)         AS agent_cost_valid_base_legacy,
           ROUND(-e.net-e.rebate,4)                        AS ngr,
       ROUND(-e.net-e.rebate-e.agent_cost,4)           AS residual_b,
       ROUND(-e.net-e.rebate-e.agent_cost_a_legacy,4)  AS residual_a,
           ROUND((-e.net-e.rebate)/NULLIF(e.stake,0),8)    AS ngr_rate,
       ROUND((-e.net-e.rebate-e.agent_cost)/NULLIF(e.stake,0),8)   AS residual_b_rate,
      -- 【HF9c · canonical accounting contract】
      --   以下 canonical 字段只增加明确 scope；不删除、不覆盖既有字段。
      --   formal_bet23_* 保持 HF9b 当前生产公式及其 NULL/0 语义；
      --   lv1~lv5 / additive / nested 则分别采用各自原始 e.* 成本字段，
      --   rate 一律从未舍入的 e.* 分子 / e.stake 计算，禁止由展示值反算。
      ROUND(e.agent_cost,4) AS agent_cost_bet23_formal_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost,4) AS net_margin_bet23_formal_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost)/NULLIF(e.stake,0),8) AS net_margin_bet23_formal_rate_canonical,
      ROUND(e.agent_cost_lv1,4) AS agent_cost_lv1_bet23_canonical,
      ROUND(e.agent_cost_lv2,4) AS agent_cost_lv2_bet24_canonical,
      ROUND(e.agent_cost_lv3,4) AS agent_cost_lv3_bet25_canonical,
      ROUND(e.agent_cost_lv4,4) AS agent_cost_lv4_bet26_canonical,
      ROUND(e.agent_cost_lv5,4) AS agent_cost_lv5_bet27_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_lv1,4) AS net_margin_lv1_bet23_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_lv1)/NULLIF(e.stake,0),8) AS net_margin_lv1_bet23_rate_canonical,
      ROUND(e.agent_cost_chain_additive,4) AS agent_cost_chain_additive_canonical,
      ROUND(e.agent_cost_chain_nested,4) AS agent_cost_chain_nested_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_additive,4) AS net_margin_chain_additive_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_nested,4) AS net_margin_chain_nested_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_chain_additive)/NULLIF(e.stake,0),8) AS net_margin_chain_additive_rate_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_chain_nested)/NULLIF(e.stake,0),8) AS net_margin_chain_nested_rate_canonical,
       ROUND((-e.net-e.rebate-e.agent_cost_a_legacy)/NULLIF(e.stake,0),8) AS residual_a_rate,
           -- 二·分布层
           ROUND(e.stake/NULLIF(e.n_bets,0),4) AS avg_stake_per_bet,
           ROUND(e.valid/NULLIF(e.n_rounds,0),4) AS avg_valid_bet_per_round,
           ROUND(-e.net/NULLIF(e.n_rounds,0),4) AS avg_profit_per_round,
           ROUND(-e.net/NULLIF(e.active_days,0),4) AS avg_profit_per_day,
           ROUND(-e.net/NULLIF(e.active_shoes,0),4) AS avg_profit_per_shoe,
           ROUND(e.stake/NULLIF(e.active_days,0),4) AS avg_stake_per_active_day,
           ROUND(e.n_rounds*1.0/NULLIF(e.active_days,0),4) AS avg_rounds_per_active_day,
           ROUND(e.st_in/NULLIF(e.nb_in,0),4) AS avg_stake_hiturn,
           ROUND(e.st_out/NULLIF(e.nb_out,0),4) AS avg_stake_non_hiturn,
           ROUND(e.p25,4) AS p25_stake, ROUND(e.p50,4) AS p50_stake, ROUND(e.p75,4) AS p75_stake,
           ROUND(e.p90,4) AS p90_stake, ROUND(e.p95,4) AS p95_stake, ROUND(e.p99,4) AS p99_stake,
           ROUND(e.p50_valid,4) AS p50_valid_bet, ROUND(e.p50_profit,4) AS p50_profit,
           ROUND(e.p95/NULLIF(e.p50,0),6) AS p95_over_p50,
           ROUND(e.p99/NULLIF(e.p50,0),6) AS p99_over_p50,
           ROUND((e.stake/NULLIF(e.n_bets,0))/NULLIF(e.p50,0),6) AS avg_over_p50,
           -- 三·关系层
           e.n_tables AS common_table_count, e.n_dealers AS common_dealer_count,
           e.n_ips AS common_ip_count, e.n_products AS common_product_count,
           ROUND(e.st_in/NULLIF(e.stake,0),8) AS share_hiturn,
           -- 四·rate 层
           ROUND(-e.net/NULLIF(e.stake,0),8) AS hold_rate,
           ROUND(-e.net_in/NULLIF(e.st_in,0),8) AS hold_rate_hiturn,
           ROUND(e.rebate/NULLIF(e.valid,0),8) AS rebate_rate_actual,
           ROUND(e.rbpct,6) AS rebate_pct_config,
           ROUND(e.valid/NULLIF(e.stake,0),6) AS turnover_multiple,
           ROUND(e.freecomm_rate,6) AS free_comm_rate,
           ROUND(e.net_in/NULLIF(e.st_in,0)-e.net_out/NULLIF(e.st_out,0),8) AS roi_delta_hiturn,
           -- 五·动态层
           e.first_seen_d AS first_seen, e.last_seen_d AS last_seen,
           e.active_days, e.active_shoes, e.active_sessions,
           DATEDIFF(e.last_seen_d, e.first_seen_d)+1 AS span_days,
           ROUND(e.active_days*1.0/NULLIF(DATEDIFF(e.last_seen_d,e.first_seen_d)+1,0),6) AS persistence,
           ROUND((e.st_in/NULLIF(e.nb_in,0))/NULLIF(e.st_out/NULLIF(e.nb_out,0),0),6) AS ramp_hiturn,
           ROUND((e.st_rec/NULLIF(e.nb_rec,0))/NULLIF(e.stake/NULLIF(e.n_bets,0),0),6) AS ramp_recent,
           ROUND((e.st_rec/NULLIF(e.stake,0))/0.30,6) AS stake_ramp,
           -- 六·决策层（HF9g-P5 · D-14 斧正 —— 本件属【全窗基线族】，相对刻度与决策标签一律 NULL）
           --   病灶：x_win 系全窗单行聚合（无 GROUP BY，恒 1 行，此为设计使然，非缺陷），
           --         经 CROSS JOIN 接入后 e.* 全行同值；六层之 NTILE / PERCENT_RANK 施于常数即退化，
           --         PERCENT_RANK 恒 0 ⇒ action_priority 恒判 A，全件 100% 误标。
           --   ★ 斧正原则：不给 x_win 补 GROUP BY —— 那会改变其「全窗基线」语义，属退化。
           --     正解与 #018 之 G-05／G-06 同治：范围外之行不得接受任何下游评分与决策标签。
           --   ★ 本件之 e.* 仍照常供其它列作全窗基线使用，仅六层相对刻度与决策标签置 NULL。
           CAST(NULL AS INT)                                              AS vip_tier,                        -- 空值取值：全窗基线族无实体可分档，置 NULL（NULL＝不适用，非 0）
           CAST(NULL AS DOUBLE)                                           AS economic_value,                  -- 空值取值：同上，禁以常数百分位冒充经济价值
           CAST(NULL AS DOUBLE)                                           AS roi_pr_global,                   -- 空值取值：同上
           CAST(NULL AS DOUBLE)                                           AS risk_value,                      -- 空值取值：兼容列，同上
           CAST(NULL AS DOUBLE)                                           AS pr_stake,                        -- 空值取值：兼容列，同上
           CAST(NULL AS DOUBLE)                                           AS pr_global,                       -- 空值取值：同上
           CAST(NULL AS DOUBLE)                                           AS pr_qualified,                    -- 空值取值：同上
           'GLOBAL_BASELINE_NO_ENTITY_RANKING'                            AS pr_qualified_population,         -- 字面取值：血统 —— 明示本件为全窗基线族，无实体排序总体
           CAST(NULL AS BIGINT)                                           AS pr_global_population_n,          -- 空值取值：血统 —— 不适用
           CAST(NULL AS BIGINT)                                           AS pr_qualified_population_n,       -- 空值取值：血统 —— 不适用
           'NOT_APPLICABLE_GLOBAL_BASELINE'                               AS pr_calculation_method,           -- 字面取值：血统 —— 算法不适用
           'HF9g-P5'                                                      AS pr_calculation_version,          -- 字面取值：血统 —— 算法版本
           CAST(NULL AS STRING)                                           AS evidence_flag,                   -- 空值取值：证据旗标不适用于全窗基线
           CAST(NULL AS STRING)                                           AS evidence_rate,                   -- 空值取值：同上
           CAST(NULL AS DOUBLE)                                           AS hold_ci_halfwidth_approx,        -- 空值取值：同上
           'X 全窗基线 · 不参与实体赏罚'                                    AS action_priority                  -- 字面取值：★ D-14 斧正 —— 本族恒不入赏罚，取代原 100% 误标之「A」
    FROM q
    CROSS JOIN x_win e
  ) y
) z
-- ── 逐批 WHERE 阶梯（★ 口诀：上界 ＝ 下界 ＋ 100000，两数同进）──
--    本件 T_true 未测，无需先跑 T_true；以 0 / 100000 控制本批返回区间，末批由实际行数 < 100000 判定
--    WHERE z.audit_rn >        0 AND z.audit_rn <=   100000   -- 第 1 批
--    WHERE z.audit_rn >   100000 AND z.audit_rn <=   200000   -- 第 2 批
--    WHERE z.audit_rn >   200000 AND z.audit_rn <=   300000   -- 第 3 批
--    WHERE z.audit_rn >   300000 AND z.audit_rn <=   400000   -- 第 4 批
--    WHERE z.audit_rn >   400000 AND z.audit_rn <=   500000   -- 第 5 批
--    WHERE z.audit_rn >   500000 AND z.audit_rn <=   600000   -- 第 6 批
--    WHERE z.audit_rn >   600000 AND z.audit_rn <=   700000   -- 第 7 批
--    …余批类推。第 k 批：WHERE z.audit_rn > (k-1)*100000 AND z.audit_rn <= k*100000
--    某批返回 < 100000 行即为末批，其后不再取。
--
--    ⚠ 常见误写（务必避开）：只推下界而上界不动 ——
--        WHERE z.audit_rn > 100000 AND z.audit_rn <= 100000   ← 自相矛盾，恒为假，返回空集
--        WHERE z.audit_rn > 200000 AND z.audit_rn <= 100000   ← 同上，空集
--      两个数必须**同时**前进，且始终相差 100000。
--      下界 ＝ 上一批之上界；上界 ＝ 本批之上界。
WHERE z.audit_rn > 0 AND z.audit_rn <= 100000 -- ★ HF9c 本批区间
ORDER BY z.audit_rn;


-- ══════════════════════════════════════════════════════════════════════════════════════════════
-- 101. VB_41_identity_global.csv   [总包行 10716~10750 · 原 17 列 ＋六层约 60 列]
--     典型学：M05 退水套利　派生旗标：hiturn（s.x_valid > s.x_stake · 仅供 CASE 条件聚合，全包无任何 WHERE/AND/HAVING 以此过滤）　连接：全窗基线
-- ══════════════════════════════════════════════════════════════════════════════════════════════
-- ★ W-64 · D-14 警示（本件属 x_win 族 · 66 件之一 · 详见 §Z 段 D-14 全案）
--   本件以 `CROSS JOIN x_win e` 接入全局基线，x_win 无 GROUP BY ⇒ 恒 1 行 ⇒ e.* 全行同值。
--   故：economic_value / roi_pr_global / risk_value / pr_stake / pr_global 恒为 0；
--       action_priority 每一行皆为「A 净亏最大十分位 · 优先复核」（Z 分支永不触发）；
--       evidence_rate 恒为最高档；vip_tier 由常数键分档 ⇒ 无信息且非确定。
--   ⇒ 本件决策层三列 **NOT_FOR_DECISION**，裁定前不得用于排班、抽查或汇报。
-- ── ① 先跑 T_true 留档（不足 100000 者一次导全，不必分批）──
-- ── ① T_true：HF9c 不再强制预跑完整 COUNT。
--    本批实际返回行数 < 100000 即判定为末批；全批完成后以各批 n_rows / audit_rn 范围核对总量。

-- ── ② 分批取数：第 1 批。第 k 批只改末行两数为 (k-1)*100000 与 k*100000 ──
--    审计字段二（REDTEAM 2026-08-24 裁定 · 四锁）：
--      audit_rn  全局观测坐标 —— 由**与原版审计版逐字同一**之排序键所生，两版可逐行对账
--      batch_id  物理分批信息 —— 该行所属批次，由 audit_rn 算得，非引擎所赋
--    ★ 锁三：二者皆为审计字段，**不得进入任何业务指标计算**。
--    ★ 锁四：两版经 audit_rn 逐行字段核验后，方可宣布输出完全一致。

-- ── ③ 每批取回后自证四数（任一不符即停手回报，禁止放行）──
--    n_rows        = COUNT(*)      须等于 COUNT(DISTINCT audit_rn)   （批内无重复）
--    audit_rn_min  = MIN(audit_rn) 须等于 (k-1)*100000 + 1           （与上批严丝合缝）
--    audit_rn_max  = MAX(audit_rn) 须等于 min + n_rows - 1           （批内无缺口）
--    全批取毕再验：各批 audit_rn 之并集 = 1 .. T_true，无缺号、无重号。
--     ★ 首行＝平台真净亏最多者（已扣退水与代理占成）。
--
SELECT z.*,
       CAST(FLOOR((z.audit_rn - 1) / 100000) + 1 AS INT)          AS batch_id,
       'A168_HF9F_20260827_0900' AS run_id,
       '2026-08-27 09:00:00' AS snapshot_sync_time
FROM (
  SELECT y.*,
         ROW_NUMBER() OVER (ORDER BY y.`residual_b` ASC, y.`roi` DESC, y.`test`, y.`n_rows`, y.`n_both_null`, y.`n_null_asym`, y.`n_exact_equal`, y.`n_value_diff`, y.`pct_exact_equal`, y.`max_abs_diff`, y.`sum_abs_diff`, y.`d_min`, y.`d_p01`, y.`d_p05`, y.`d_p50`, y.`d_p95`, y.`d_p99`, y.`d_max`, y.`verdict_identity`) AS audit_rn
  FROM (
    WITH
      x_ranked AS (
    SELECT b.bet01, b.bet03, b.bet04, b.bet05, b.bet09, b.bet11, b.bet13,
           b.bet15, b.bet16, b.bet17, b.bet18, b.bet19, b.bet20, b.bet21,
           b.bet22, b.bet23, b.bet24, b.bet25, b.bet26, b.bet27, b.bet38, b.bet39, b.category, b.commission,
           b.dt, b.eid, b.ip, b.validbet, b.updatetime, b.sync_time,
           ROW_NUMBER() OVER (
             PARTITION BY b.bet01
             ORDER BY b.updatetime DESC, b.sync_time DESC, b.dt DESC)      AS x_rn
    FROM ods_mariadb_2b.ods_a168_bet02 b
    WHERE b.dt >= '2026-03-21' AND b.dt < '2026-08-07'
      AND b.bet02 = '101'
      AND b.sync_time <= '2026-08-27 09:00:00'
  ),
    x_testagent AS (
    SELECT age001 AS agent_id FROM ods_mariadb_2b.ods_a168_agent WHERE age022 = '1'
  ),
    x_bs0 AS (
    SELECT b.bet05 AS x_member, b.eid AS x_dealer, b.bet39 AS x_table,
           b.bet03 AS x_shoe, b.ip AS x_ip, b.bet09 AS x_product, b.dt AS x_date,
           CONCAT_WS('|', b.bet03, b.bet04, b.bet39)                      AS x_round,
           CONCAT_WS('|', b.bet39, b.bet03)                               AS x_tblshoe,
           CAST(NULLIF(TRIM(b.bet04),'') AS INT)                          AS x_rno,
           CASE WHEN b.dt >= '2026-07-08' THEN 1 ELSE 0 END               AS x_rec,
           CASE WHEN TRIM(b.commission)='1' THEN 1 ELSE 0 END             AS x_freecomm,
           CAST(NULLIF(TRIM(b.bet13),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_stake,
           CAST(NULLIF(TRIM(b.validbet),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_valid,
           CAST(NULLIF(TRIM(b.bet16),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_rebate,
           CAST(NULLIF(TRIM(b.bet17),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_net,
           CAST(NULLIF(TRIM(b.bet15),'') AS DECIMAL(20,6))                AS x_rbpct,
           COALESCE(CAST(NULLIF(TRIM(b.bet23),'') AS DECIMAL(20,6)),0)   AS x_agpct,
          NULLIF(CAST(NULLIF(TRIM(b.bet23),'') AS DECIMAL(20,6)),0)     AS x_rate1,
          NULLIF(CAST(NULLIF(TRIM(b.bet24),'') AS DECIMAL(20,6)),0)     AS x_rate2,
          NULLIF(CAST(NULLIF(TRIM(b.bet25),'') AS DECIMAL(20,6)),0)     AS x_rate3,
          NULLIF(CAST(NULLIF(TRIM(b.bet26),'') AS DECIMAL(20,6)),0)     AS x_rate4,
          NULLIF(CAST(NULLIF(TRIM(b.bet27),'') AS DECIMAL(20,6)),0)     AS x_rate5,
          (CASE WHEN NULLIF(CAST(NULLIF(TRIM(b.bet22),'') AS BIGINT),0) IS NOT NULL THEN 5
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet21),'') AS BIGINT),0) IS NOT NULL THEN 4
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet20),'') AS BIGINT),0) IS NOT NULL THEN 3
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet19),'') AS BIGINT),0) IS NOT NULL THEN 2
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet18),'') AS BIGINT),0) IS NOT NULL THEN 1
                ELSE 0 END)                                             AS x_chain_depth,
           CASE WHEN COALESCE(t1.agent_id,t2.agent_id,t3.agent_id,
                              t4.agent_id,t5.agent_id) IS NOT NULL
                THEN 1 ELSE 0 END                                        AS f_testline
    FROM x_ranked b
    LEFT JOIN x_testagent t1 ON t1.agent_id = b.bet18
    LEFT JOIN x_testagent t2 ON t2.agent_id = b.bet19
    LEFT JOIN x_testagent t3 ON t3.agent_id = b.bet20
    LEFT JOIN x_testagent t4 ON t4.agent_id = b.bet21
    LEFT JOIN x_testagent t5 ON t5.agent_id = b.bet22
    WHERE b.x_rn = 1
      AND b.category='1' AND UPPER(TRIM(b.bet38))='N'
      AND CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8)) > 0
  ),
  x_mk AS (
    SELECT s.*,
           CASE WHEN s.f_testline = 0 THEN 1 ELSE 0 END                 AS is_clean
    FROM x_bs0 s
  ),
  x_agg AS (
    SELECT s.x_member                                                        AS x_key,
           COUNT(*) AS n_bets, COUNT(DISTINCT s.x_round) AS n_rounds,
           COUNT(DISTINCT s.x_date) AS active_days, COUNT(DISTINCT s.x_tblshoe) AS active_shoes,
           COUNT(DISTINCT CONCAT_WS('|', s.x_date, s.x_table)) AS active_sessions,
           COUNT(DISTINCT s.x_table) AS n_tables, COUNT(DISTINCT s.x_dealer) AS n_dealers,
           COUNT(DISTINCT s.x_ip) AS n_ips, COUNT(DISTINCT s.x_product) AS n_products,
           MIN(s.x_date) AS first_seen_d, MAX(s.x_date) AS last_seen_d,
           SUM(s.x_stake) AS stake, SUM(s.x_valid) AS valid, SUM(s.x_rebate) AS rebate,
           SUM(s.x_net) AS net, SUM(-s.x_net *(100.0-s.x_agpct)/100.0) AS agent_cost,
           AVG(100.0-s.x_agpct)                   AS agent_pct,
           AVG(s.x_agpct)                         AS company_retain_pct,
           SUM(-s.x_net *s.x_agpct/100.0)         AS agent_cost_a_legacy,
           SUM(s.x_valid*s.x_agpct/100.0)         AS agent_cost_valid_base_legacy,
          AVG(COALESCE(s.x_rate1,100)) AS retain_pct_lv1, AVG(COALESCE(s.x_rate2,100)) AS retain_pct_lv2,
          AVG(COALESCE(s.x_rate3,100)) AS retain_pct_lv3, AVG(COALESCE(s.x_rate4,100)) AS retain_pct_lv4,
          AVG(COALESCE(s.x_rate5,100)) AS retain_pct_lv5, AVG(s.x_chain_depth) AS chain_depth_avg,
          AVG(COALESCE(100.0-s.x_rate1,0)) AS agent_pct_lv1, AVG(COALESCE(100.0-s.x_rate2,0)) AS agent_pct_lv2,
          AVG(COALESCE(100.0-s.x_rate3,0)) AS agent_pct_lv3, AVG(COALESCE(100.0-s.x_rate4,0)) AS agent_pct_lv4,
          AVG(COALESCE(100.0-s.x_rate5,0)) AS agent_pct_lv5,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate1,0)/100.0)                        AS agent_cost_lv1,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate2,0)/100.0)                        AS agent_cost_lv2,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate3,0)/100.0)                        AS agent_cost_lv3,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate4,0)/100.0)                        AS agent_cost_lv4,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate5,0)/100.0)                        AS agent_cost_lv5,
          SUM(-s.x_net*(COALESCE(100.0-s.x_rate1,0)+COALESCE(100.0-s.x_rate2,0)
                       +COALESCE(100.0-s.x_rate3,0)+COALESCE(100.0-s.x_rate4,0)
                       +COALESCE(100.0-s.x_rate5,0))/100.0)                   AS agent_cost_chain_additive,
          SUM(-s.x_net*(1.0 - CAST(COALESCE(s.x_rate1,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate2,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate3,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate4,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate5,100) AS DOUBLE)/100.0))
                                                                       AS agent_cost_chain_nested,
           AVG(s.x_rbpct) AS rbpct, AVG(s.x_freecomm*1.0) AS freecomm_rate,
           PERCENTILE_APPROX(s.x_stake,0.25) AS p25, PERCENTILE_APPROX(s.x_stake,0.50) AS p50,
           PERCENTILE_APPROX(s.x_stake,0.75) AS p75, PERCENTILE_APPROX(s.x_stake,0.90) AS p90,
           PERCENTILE_APPROX(s.x_stake,0.95) AS p95, PERCENTILE_APPROX(s.x_stake,0.99) AS p99,
           PERCENTILE_APPROX(s.x_valid,0.50) AS p50_valid,
           PERCENTILE_APPROX(s.x_net,0.50)   AS p50_profit,
           SUM(CASE WHEN s.x_valid > s.x_stake THEN s.x_stake ELSE 0 END) AS st_in,
           SUM(CASE WHEN s.x_valid > s.x_stake THEN 1 ELSE 0 END)         AS nb_in,
           SUM(CASE WHEN s.x_valid > s.x_stake THEN s.x_net ELSE 0 END)   AS net_in,
           SUM(CASE WHEN NOT (s.x_valid > s.x_stake) THEN s.x_stake ELSE 0 END) AS st_out,
           SUM(CASE WHEN NOT (s.x_valid > s.x_stake) THEN 1 ELSE 0 END)         AS nb_out,
           SUM(CASE WHEN NOT (s.x_valid > s.x_stake) THEN s.x_net ELSE 0 END)   AS net_out,
           SUM(CASE WHEN s.x_rec=1 THEN s.x_stake ELSE 0 END) AS st_rec,
           SUM(CASE WHEN s.x_rec=1 THEN 1 ELSE 0 END)         AS nb_rec
    FROM x_mk s
    WHERE s.is_clean = 1
      AND s.x_member IS NOT NULL AND TRIM(CAST(s.x_member AS STRING)) <> ''
    GROUP BY s.x_member
  ),
  x_win AS (
    SELECT            COUNT(*) AS n_bets, COUNT(DISTINCT s.x_round) AS n_rounds,
           COUNT(DISTINCT s.x_date) AS active_days, COUNT(DISTINCT s.x_tblshoe) AS active_shoes,
           COUNT(DISTINCT CONCAT_WS('|', s.x_date, s.x_table)) AS active_sessions,
           COUNT(DISTINCT s.x_table) AS n_tables, COUNT(DISTINCT s.x_dealer) AS n_dealers,
           COUNT(DISTINCT s.x_ip) AS n_ips, COUNT(DISTINCT s.x_product) AS n_products,
           MIN(s.x_date) AS first_seen_d, MAX(s.x_date) AS last_seen_d,
           SUM(s.x_stake) AS stake, SUM(s.x_valid) AS valid, SUM(s.x_rebate) AS rebate,
           SUM(s.x_net) AS net, SUM(-s.x_net *(100.0-s.x_agpct)/100.0) AS agent_cost,
           AVG(100.0-s.x_agpct)                   AS agent_pct,
           AVG(s.x_agpct)                         AS company_retain_pct,
           SUM(-s.x_net *s.x_agpct/100.0)         AS agent_cost_a_legacy,
           SUM(s.x_valid*s.x_agpct/100.0)         AS agent_cost_valid_base_legacy,
          AVG(COALESCE(s.x_rate1,100)) AS retain_pct_lv1, AVG(COALESCE(s.x_rate2,100)) AS retain_pct_lv2,
          AVG(COALESCE(s.x_rate3,100)) AS retain_pct_lv3, AVG(COALESCE(s.x_rate4,100)) AS retain_pct_lv4,
          AVG(COALESCE(s.x_rate5,100)) AS retain_pct_lv5, AVG(s.x_chain_depth) AS chain_depth_avg,
          AVG(COALESCE(100.0-s.x_rate1,0)) AS agent_pct_lv1, AVG(COALESCE(100.0-s.x_rate2,0)) AS agent_pct_lv2,
          AVG(COALESCE(100.0-s.x_rate3,0)) AS agent_pct_lv3, AVG(COALESCE(100.0-s.x_rate4,0)) AS agent_pct_lv4,
          AVG(COALESCE(100.0-s.x_rate5,0)) AS agent_pct_lv5,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate1,0)/100.0)                        AS agent_cost_lv1,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate2,0)/100.0)                        AS agent_cost_lv2,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate3,0)/100.0)                        AS agent_cost_lv3,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate4,0)/100.0)                        AS agent_cost_lv4,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate5,0)/100.0)                        AS agent_cost_lv5,
          SUM(-s.x_net*(COALESCE(100.0-s.x_rate1,0)+COALESCE(100.0-s.x_rate2,0)
                       +COALESCE(100.0-s.x_rate3,0)+COALESCE(100.0-s.x_rate4,0)
                       +COALESCE(100.0-s.x_rate5,0))/100.0)                   AS agent_cost_chain_additive,
          SUM(-s.x_net*(1.0 - CAST(COALESCE(s.x_rate1,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate2,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate3,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate4,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate5,100) AS DOUBLE)/100.0))
                                                                       AS agent_cost_chain_nested,
           AVG(s.x_rbpct) AS rbpct, AVG(s.x_freecomm*1.0) AS freecomm_rate,
           PERCENTILE_APPROX(s.x_stake,0.25) AS p25, PERCENTILE_APPROX(s.x_stake,0.50) AS p50,
           PERCENTILE_APPROX(s.x_stake,0.75) AS p75, PERCENTILE_APPROX(s.x_stake,0.90) AS p90,
           PERCENTILE_APPROX(s.x_stake,0.95) AS p95, PERCENTILE_APPROX(s.x_stake,0.99) AS p99,
           PERCENTILE_APPROX(s.x_valid,0.50) AS p50_valid,
           PERCENTILE_APPROX(s.x_net,0.50)   AS p50_profit,
           SUM(CASE WHEN s.x_valid > s.x_stake THEN s.x_stake ELSE 0 END) AS st_in,
           SUM(CASE WHEN s.x_valid > s.x_stake THEN 1 ELSE 0 END)         AS nb_in,
           SUM(CASE WHEN s.x_valid > s.x_stake THEN s.x_net ELSE 0 END)   AS net_in,
           SUM(CASE WHEN NOT (s.x_valid > s.x_stake) THEN s.x_stake ELSE 0 END) AS st_out,
           SUM(CASE WHEN NOT (s.x_valid > s.x_stake) THEN 1 ELSE 0 END)         AS nb_out,
           SUM(CASE WHEN NOT (s.x_valid > s.x_stake) THEN s.x_net ELSE 0 END)   AS net_out,
           SUM(CASE WHEN s.x_rec=1 THEN s.x_stake ELSE 0 END) AS st_rec,
           SUM(CASE WHEN s.x_rec=1 THEN 1 ELSE 0 END)         AS nb_rec
    FROM x_mk s
    WHERE s.is_clean = 1
      AND s.x_member IS NOT NULL AND TRIM(CAST(s.x_member AS STRING)) <> ''
  ),
      q AS (
        WITH vb AS (                                                                                        -- 公共表表达式：开启中间结果集 vb——两列并置与差值
          SELECT CAST(NULLIF(TRIM(bet41), '')    AS DECIMAL(20,8))               AS v41,                    -- 取列：bet41 转数值
                 CAST(NULLIF(TRIM(validbet), '') AS DECIMAL(20,8))               AS vvb,                    -- 取列：validbet 转数值
                 CAST(NULLIF(TRIM(bet41), '')    AS DECIMAL(20,8))
                   - CAST(NULLIF(TRIM(validbet), '') AS DECIMAL(20,8))           AS d                       -- 取值表达式：★ 差值 D ＝ bet41 − validbet
          FROM ods_mariadb_2b.ods_a168_bet02                                                                -- 取数来源：取自注单主表
          WHERE dt >= '2026-03-21' AND dt < '2026-08-07'                                                    -- 过滤条件：限定分析窗
            AND sync_time <= '2026-08-27 09:00:00'
            AND CAST(bet02 AS STRING) = '101'                                                               -- 并列条件：限定百家乐
        )                                                                                                   -- 续行：收束上方的子查询或函数括号
        SELECT                                                                                              -- 取列：起始取列子句
          'bet41 ≡ validbet（全窗 · 百家乐）'                                    AS test,                   -- 字面取值：受检命题
          COUNT(*)                                                               AS n_rows,                 -- 计数表达式：总行数
          SUM(CASE WHEN v41 IS NULL AND vvb IS NULL THEN 1 ELSE 0 END)           AS n_both_null,            -- 条件计数：★ 象限一——二者皆空
          SUM(CASE WHEN (v41 IS NULL) <> (vvb IS NULL) THEN 1 ELSE 0 END)        AS n_null_asym,            -- 条件计数：★★ 象限二——空值非对称，最危险
          SUM(CASE WHEN v41 IS NOT NULL AND vvb IS NOT NULL AND v41 = vvb THEN 1 ELSE 0 END) AS n_exact_equal, -- 条件计数：★ 象限三——皆非空且相等
          SUM(CASE WHEN v41 IS NOT NULL AND vvb IS NOT NULL AND v41 <> vvb THEN 1 ELSE 0 END) AS n_value_diff, -- 条件计数：★ 象限四——皆非空而不等
          ROUND(SUM(CASE WHEN v41 IS NOT NULL AND vvb IS NOT NULL AND v41 = vvb THEN 1 ELSE 0 END) * 100.0
                / NULLIF(SUM(CASE WHEN v41 IS NOT NULL AND vvb IS NOT NULL THEN 1 ELSE 0 END), 0), 8) AS pct_exact_equal, -- 比率表达式：★★ 皆非空者中之相等率
          ROUND(MAX(ABS(d)), 8)                                                  AS max_abs_diff,           -- 聚合取值：★ 最大绝对差——判是否仅浮点误差
          ROUND(SUM(ABS(d)), 8)                                                  AS sum_abs_diff,           -- 汇总表达式：绝对差之和
          ROUND(MIN(d), 8)                                                       AS d_min,                  -- 聚合取值：差值下界
          ROUND(PERCENTILE_APPROX(d, 0.01), 8)                                   AS d_p01,                  -- 取近似分位数表达式：差值 1 分位
          ROUND(PERCENTILE_APPROX(d, 0.05), 8)                                   AS d_p05,                  -- 取近似分位数表达式：差值 5 分位
          ROUND(PERCENTILE_APPROX(d, 0.50), 8)                                   AS d_p50,                  -- 取近似分位数表达式：差值中位
          ROUND(PERCENTILE_APPROX(d, 0.95), 8)                                   AS d_p95,                  -- 取近似分位数表达式：差值 95 分位
          ROUND(PERCENTILE_APPROX(d, 0.99), 8)                                   AS d_p99,                  -- 取近似分位数表达式：差值 99 分位
          ROUND(MAX(d), 8)                                                       AS d_max,                  -- 聚合取值：差值上界
          CASE                                                                                              -- 条件分支：起始分支——恒等裁定（三态）
            WHEN SUM(CASE WHEN (v41 IS NULL) <> (vvb IS NULL) THEN 1 ELSE 0 END) > 0
              THEN '❌ NOT_IDENTICAL —— 空值语义不同（非对称空），二列不可互代'                                 -- 分支判定：空值非对称
            WHEN SUM(CASE WHEN v41 IS NOT NULL AND vvb IS NOT NULL AND v41 <> vvb THEN 1 ELSE 0 END) > 0
              THEN '◐ CONDITIONAL —— 存在数值差异，须并读 max_abs_diff 判其系浮点抑或量纲之别'                 -- 分支判定：有数值差
            ELSE '✅ IDENTICAL（★ 措辞锁：只得书「本窗口本产品下二列取值相同」，禁书「bet41 就是 validbet」）'     -- 分支判定：本窗口相同
          END                                                                    AS verdict_identity        -- 条件分支：收束上方判词，产出「verdict_identity」
        FROM vb                                                                                            -- 取数来源：取自本条自建的中间结果集 vb
      )
    SELECT q.*,
           -- 一·经济层
           ROUND(e.stake,4) AS stake, ROUND(e.valid,4) AS valid_bet,
           ROUND(-e.net,4) AS profit, e.n_bets, e.n_rounds,
           ROUND(e.net/NULLIF(e.stake,0),8) AS roi,
           ROUND(e.net_in/NULLIF(e.st_in,0),8) AS roi_hiturn,
           ROUND(e.net_out/NULLIF(e.st_out,0),8) AS roi_non_hiturn,
           ROUND((e.net-e.rebate)/NULLIF(e.stake,0),8) AS roi_ex_rebate,
           ROUND(e.net,4) AS roi_numerator, ROUND(e.stake,4) AS roi_denominator,
           CASE WHEN e.stake IS NULL THEN 'NULL_DENOM' WHEN e.stake<=0 THEN 'ZERO_DENOM'
                WHEN e.n_bets<30 THEN 'THIN_EXPOSURE' ELSE 'OK' END AS roi_denominator_status,
           ROUND(e.rebate,4) AS rebate_cost, ROUND(e.agent_cost,4)                           AS cost_complement_b,
       ROUND(e.agent_pct,4)                            AS pct_complement,
       ROUND(e.company_retain_pct,4)                   AS pct_top_bet23,
       'AG03-UNRESOLVED'                                     AS agent_formula_version,
      'ALL5_LEVELS_bet23_to_bet27'                    AS agent_level_scope,
      ROUND(e.agent_cost_lv1,4) AS agent_cost_lv1, ROUND(e.agent_cost_lv2,4) AS agent_cost_lv2,
      ROUND(e.agent_cost_lv3,4) AS agent_cost_lv3, ROUND(e.agent_cost_lv4,4) AS agent_cost_lv4,
      ROUND(e.agent_cost_lv5,4) AS agent_cost_lv5,
      ROUND(e.agent_pct_lv1,6) AS agent_pct_lv1, ROUND(e.agent_pct_lv2,6) AS agent_pct_lv2,
      ROUND(e.agent_pct_lv3,6) AS agent_pct_lv3, ROUND(e.agent_pct_lv4,6) AS agent_pct_lv4,
      ROUND(e.agent_pct_lv5,6) AS agent_pct_lv5,
      ROUND(e.retain_pct_lv1,6) AS retain_pct_lv1, ROUND(e.retain_pct_lv2,6) AS retain_pct_lv2,
      ROUND(e.retain_pct_lv3,6) AS retain_pct_lv3, ROUND(e.retain_pct_lv4,6) AS retain_pct_lv4,
      ROUND(e.retain_pct_lv5,6) AS retain_pct_lv5, ROUND(e.chain_depth_avg,4) AS chain_depth_avg,
      ROUND(e.agent_cost_chain_additive,4)            AS agent_cost_chain_additive,
      ROUND(e.agent_cost_chain_nested,4)              AS agent_cost_chain_nested,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_additive,4) AS residual_chain_additive,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_nested,4)   AS residual_chain_nested,
      'PENDING_AG03'                                  AS decision_status,
      'FALSE'                                         AS admit_to_risk_decision,
      'NOT_FOR_ENFORCEMENT'                           AS deliverable_class,
       ROUND(e.agent_cost_a_legacy,4)                  AS agent_cost_a_legacy,
       ROUND(e.agent_cost_valid_base_legacy,4)         AS agent_cost_valid_base_legacy,
           ROUND(-e.net-e.rebate,4)                        AS ngr,
       ROUND(-e.net-e.rebate-e.agent_cost,4)           AS residual_b,
       ROUND(-e.net-e.rebate-e.agent_cost_a_legacy,4)  AS residual_a,
           ROUND((-e.net-e.rebate)/NULLIF(e.stake,0),8)    AS ngr_rate,
       ROUND((-e.net-e.rebate-e.agent_cost)/NULLIF(e.stake,0),8)   AS residual_b_rate,
      -- 【HF9c · canonical accounting contract】
      --   以下 canonical 字段只增加明确 scope；不删除、不覆盖既有字段。
      --   formal_bet23_* 保持 HF9b 当前生产公式及其 NULL/0 语义；
      --   lv1~lv5 / additive / nested 则分别采用各自原始 e.* 成本字段，
      --   rate 一律从未舍入的 e.* 分子 / e.stake 计算，禁止由展示值反算。
      ROUND(e.agent_cost,4) AS agent_cost_bet23_formal_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost,4) AS net_margin_bet23_formal_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost)/NULLIF(e.stake,0),8) AS net_margin_bet23_formal_rate_canonical,
      ROUND(e.agent_cost_lv1,4) AS agent_cost_lv1_bet23_canonical,
      ROUND(e.agent_cost_lv2,4) AS agent_cost_lv2_bet24_canonical,
      ROUND(e.agent_cost_lv3,4) AS agent_cost_lv3_bet25_canonical,
      ROUND(e.agent_cost_lv4,4) AS agent_cost_lv4_bet26_canonical,
      ROUND(e.agent_cost_lv5,4) AS agent_cost_lv5_bet27_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_lv1,4) AS net_margin_lv1_bet23_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_lv1)/NULLIF(e.stake,0),8) AS net_margin_lv1_bet23_rate_canonical,
      ROUND(e.agent_cost_chain_additive,4) AS agent_cost_chain_additive_canonical,
      ROUND(e.agent_cost_chain_nested,4) AS agent_cost_chain_nested_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_additive,4) AS net_margin_chain_additive_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_nested,4) AS net_margin_chain_nested_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_chain_additive)/NULLIF(e.stake,0),8) AS net_margin_chain_additive_rate_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_chain_nested)/NULLIF(e.stake,0),8) AS net_margin_chain_nested_rate_canonical,
       ROUND((-e.net-e.rebate-e.agent_cost_a_legacy)/NULLIF(e.stake,0),8) AS residual_a_rate,
           -- 二·分布层
           ROUND(e.stake/NULLIF(e.n_bets,0),4) AS avg_stake_per_bet,
           ROUND(e.valid/NULLIF(e.n_rounds,0),4) AS avg_valid_bet_per_round,
           ROUND(-e.net/NULLIF(e.n_rounds,0),4) AS avg_profit_per_round,
           ROUND(-e.net/NULLIF(e.active_days,0),4) AS avg_profit_per_day,
           ROUND(-e.net/NULLIF(e.active_shoes,0),4) AS avg_profit_per_shoe,
           ROUND(e.stake/NULLIF(e.active_days,0),4) AS avg_stake_per_active_day,
           ROUND(e.n_rounds*1.0/NULLIF(e.active_days,0),4) AS avg_rounds_per_active_day,
           ROUND(e.st_in/NULLIF(e.nb_in,0),4) AS avg_stake_hiturn,
           ROUND(e.st_out/NULLIF(e.nb_out,0),4) AS avg_stake_non_hiturn,
           ROUND(e.p25,4) AS p25_stake, ROUND(e.p50,4) AS p50_stake, ROUND(e.p75,4) AS p75_stake,
           ROUND(e.p90,4) AS p90_stake, ROUND(e.p95,4) AS p95_stake, ROUND(e.p99,4) AS p99_stake,
           ROUND(e.p50_valid,4) AS p50_valid_bet, ROUND(e.p50_profit,4) AS p50_profit,
           ROUND(e.p95/NULLIF(e.p50,0),6) AS p95_over_p50,
           ROUND(e.p99/NULLIF(e.p50,0),6) AS p99_over_p50,
           ROUND((e.stake/NULLIF(e.n_bets,0))/NULLIF(e.p50,0),6) AS avg_over_p50,
           -- 三·关系层
           e.n_tables AS common_table_count, e.n_dealers AS common_dealer_count,
           e.n_ips AS common_ip_count, e.n_products AS common_product_count,
           ROUND(e.st_in/NULLIF(e.stake,0),8) AS share_hiturn,
           -- 四·rate 层
           ROUND(-e.net/NULLIF(e.stake,0),8) AS hold_rate,
           ROUND(-e.net_in/NULLIF(e.st_in,0),8) AS hold_rate_hiturn,
           ROUND(e.rebate/NULLIF(e.valid,0),8) AS rebate_rate_actual,
           ROUND(e.rbpct,6) AS rebate_pct_config,
           ROUND(e.valid/NULLIF(e.stake,0),6) AS turnover_multiple,
           ROUND(e.freecomm_rate,6) AS free_comm_rate,
           ROUND(e.net_in/NULLIF(e.st_in,0)-e.net_out/NULLIF(e.st_out,0),8) AS roi_delta_hiturn,
           -- 五·动态层
           e.first_seen_d AS first_seen, e.last_seen_d AS last_seen,
           e.active_days, e.active_shoes, e.active_sessions,
           DATEDIFF(e.last_seen_d, e.first_seen_d)+1 AS span_days,
           ROUND(e.active_days*1.0/NULLIF(DATEDIFF(e.last_seen_d,e.first_seen_d)+1,0),6) AS persistence,
           ROUND((e.st_in/NULLIF(e.nb_in,0))/NULLIF(e.st_out/NULLIF(e.nb_out,0),0),6) AS ramp_hiturn,
           ROUND((e.st_rec/NULLIF(e.nb_rec,0))/NULLIF(e.stake/NULLIF(e.n_bets,0),0),6) AS ramp_recent,
           ROUND((e.st_rec/NULLIF(e.stake,0))/0.30,6) AS stake_ramp,
           -- 六·决策层（HF9g-P5 · D-14 斧正 —— 本件属【全窗基线族】，相对刻度与决策标签一律 NULL）
           --   病灶：x_win 系全窗单行聚合（无 GROUP BY，恒 1 行，此为设计使然，非缺陷），
           --         经 CROSS JOIN 接入后 e.* 全行同值；六层之 NTILE / PERCENT_RANK 施于常数即退化，
           --         PERCENT_RANK 恒 0 ⇒ action_priority 恒判 A，全件 100% 误标。
           --   ★ 斧正原则：不给 x_win 补 GROUP BY —— 那会改变其「全窗基线」语义，属退化。
           --     正解与 #018 之 G-05／G-06 同治：范围外之行不得接受任何下游评分与决策标签。
           --   ★ 本件之 e.* 仍照常供其它列作全窗基线使用，仅六层相对刻度与决策标签置 NULL。
           CAST(NULL AS INT)                                              AS vip_tier,                        -- 空值取值：全窗基线族无实体可分档，置 NULL（NULL＝不适用，非 0）
           CAST(NULL AS DOUBLE)                                           AS economic_value,                  -- 空值取值：同上，禁以常数百分位冒充经济价值
           CAST(NULL AS DOUBLE)                                           AS roi_pr_global,                   -- 空值取值：同上
           CAST(NULL AS DOUBLE)                                           AS risk_value,                      -- 空值取值：兼容列，同上
           CAST(NULL AS DOUBLE)                                           AS pr_stake,                        -- 空值取值：兼容列，同上
           CAST(NULL AS DOUBLE)                                           AS pr_global,                       -- 空值取值：同上
           CAST(NULL AS DOUBLE)                                           AS pr_qualified,                    -- 空值取值：同上
           'GLOBAL_BASELINE_NO_ENTITY_RANKING'                            AS pr_qualified_population,         -- 字面取值：血统 —— 明示本件为全窗基线族，无实体排序总体
           CAST(NULL AS BIGINT)                                           AS pr_global_population_n,          -- 空值取值：血统 —— 不适用
           CAST(NULL AS BIGINT)                                           AS pr_qualified_population_n,       -- 空值取值：血统 —— 不适用
           'NOT_APPLICABLE_GLOBAL_BASELINE'                               AS pr_calculation_method,           -- 字面取值：血统 —— 算法不适用
           'HF9g-P5'                                                      AS pr_calculation_version,          -- 字面取值：血统 —— 算法版本
           CAST(NULL AS STRING)                                           AS evidence_flag,                   -- 空值取值：证据旗标不适用于全窗基线
           CAST(NULL AS STRING)                                           AS evidence_rate,                   -- 空值取值：同上
           CAST(NULL AS DOUBLE)                                           AS hold_ci_halfwidth_approx,        -- 空值取值：同上
           'X 全窗基线 · 不参与实体赏罚'                                    AS action_priority                  -- 字面取值：★ D-14 斧正 —— 本族恒不入赏罚，取代原 100% 误标之「A」
    FROM q
    CROSS JOIN x_win e
  ) y
) z
-- ── 逐批 WHERE 阶梯（★ 口诀：上界 ＝ 下界 ＋ 100000，两数同进）──
--    本件 T_true 未测，无需先跑 T_true；以 0 / 100000 控制本批返回区间，末批由实际行数 < 100000 判定
--    WHERE z.audit_rn >        0 AND z.audit_rn <=   100000   -- 第 1 批
--    WHERE z.audit_rn >   100000 AND z.audit_rn <=   200000   -- 第 2 批
--    WHERE z.audit_rn >   200000 AND z.audit_rn <=   300000   -- 第 3 批
--    WHERE z.audit_rn >   300000 AND z.audit_rn <=   400000   -- 第 4 批
--    WHERE z.audit_rn >   400000 AND z.audit_rn <=   500000   -- 第 5 批
--    WHERE z.audit_rn >   500000 AND z.audit_rn <=   600000   -- 第 6 批
--    WHERE z.audit_rn >   600000 AND z.audit_rn <=   700000   -- 第 7 批
--    …余批类推。第 k 批：WHERE z.audit_rn > (k-1)*100000 AND z.audit_rn <= k*100000
--    某批返回 < 100000 行即为末批，其后不再取。
--
--    ⚠ 常见误写（务必避开）：只推下界而上界不动 ——
--        WHERE z.audit_rn > 100000 AND z.audit_rn <= 100000   ← 自相矛盾，恒为假，返回空集
--        WHERE z.audit_rn > 200000 AND z.audit_rn <= 100000   ← 同上，空集
--      两个数必须**同时**前进，且始终相差 100000。
--      下界 ＝ 上一批之上界；上界 ＝ 本批之上界。
WHERE z.audit_rn > 0 AND z.audit_rn <= 100000 -- ★ HF9c 本批区间
ORDER BY z.audit_rn;


-- ══════════════════════════════════════════════════════════════════════════════════════════════
-- 102. VB_41b_identity_strata.csv   [总包行 10761~10792 · 原 10 列 ＋六层约 60 列]
--     典型学：M05 退水套利　派生旗标：hiturn（s.x_valid > s.x_stake · 仅供 CASE 条件聚合，全包无任何 WHERE/AND/HAVING 以此过滤）　连接：q.`bet09_value`
-- ══════════════════════════════════════════════════════════════════════════════════════════════
-- ── ① 先跑 T_true 留档（不足 100000 者一次导全，不必分批）──
-- ── ① T_true：HF9c 不再强制预跑完整 COUNT。
--    本批实际返回行数 < 100000 即判定为末批；全批完成后以各批 n_rows / audit_rn 范围核对总量。

-- ── ② 分批取数：第 1 批。第 k 批只改末行两数为 (k-1)*100000 与 k*100000 ──
--    审计字段二（REDTEAM 2026-08-24 裁定 · 四锁）：
--      audit_rn  全局观测坐标 —— 由**与原版审计版逐字同一**之排序键所生，两版可逐行对账
--      batch_id  物理分批信息 —— 该行所属批次，由 audit_rn 算得，非引擎所赋
--    ★ 锁三：二者皆为审计字段，**不得进入任何业务指标计算**。
--    ★ 锁四：两版经 audit_rn 逐行字段核验后，方可宣布输出完全一致。

-- ── ③ 每批取回后自证四数（任一不符即停手回报，禁止放行）──
--    n_rows        = COUNT(*)      须等于 COUNT(DISTINCT audit_rn)   （批内无重复）
--    audit_rn_min  = MIN(audit_rn) 须等于 (k-1)*100000 + 1           （与上批严丝合缝）
--    audit_rn_max  = MAX(audit_rn) 须等于 min + n_rows - 1           （批内无缺口）
--    全批取毕再验：各批 audit_rn 之并集 = 1 .. T_true，无缺号、无重号。
--     ★ 首行＝平台真净亏最多者（已扣退水与代理占成）。
--
SELECT z.*,
       CAST(FLOOR((z.audit_rn - 1) / 100000) + 1 AS INT)          AS batch_id,
       'A168_HF9F_20260827_0900' AS run_id,
       '2026-08-27 09:00:00' AS snapshot_sync_time
FROM (
  SELECT y.*,
         ROW_NUMBER() OVER (ORDER BY y.`residual_b` ASC, y.`roi` DESC, y.`bet09_value`, y.`commission_value`, y.`n_rows`, y.`n_both_null`, y.`n_null_asym`, y.`n_value_diff`, y.`max_abs_diff`, y.`b41_sum`, y.`vb_sum`, y.`verdict_stratum`) AS audit_rn
  FROM (
    WITH
      x_ranked AS (
    SELECT b.bet01, b.bet03, b.bet04, b.bet05, b.bet09, b.bet11, b.bet13,
           b.bet15, b.bet16, b.bet17, b.bet18, b.bet19, b.bet20, b.bet21,
           b.bet22, b.bet23, b.bet24, b.bet25, b.bet26, b.bet27, b.bet38, b.bet39, b.category, b.commission,
           b.dt, b.eid, b.ip, b.validbet, b.updatetime, b.sync_time,
           ROW_NUMBER() OVER (
             PARTITION BY b.bet01
             ORDER BY b.updatetime DESC, b.sync_time DESC, b.dt DESC)      AS x_rn
    FROM ods_mariadb_2b.ods_a168_bet02 b
    WHERE b.dt >= '2026-03-21' AND b.dt < '2026-08-07'
      AND b.bet02 = '101'
      AND b.sync_time <= '2026-08-27 09:00:00'
  ),
    x_testagent AS (
    SELECT age001 AS agent_id FROM ods_mariadb_2b.ods_a168_agent WHERE age022 = '1'
  ),
    x_bs0 AS (
    SELECT b.bet05 AS x_member, b.eid AS x_dealer, b.bet39 AS x_table,
           b.bet03 AS x_shoe, b.ip AS x_ip, b.bet09 AS x_product, b.dt AS x_date,
           CONCAT_WS('|', b.bet03, b.bet04, b.bet39)                      AS x_round,
           CONCAT_WS('|', b.bet39, b.bet03)                               AS x_tblshoe,
           CAST(NULLIF(TRIM(b.bet04),'') AS INT)                          AS x_rno,
           CASE WHEN b.dt >= '2026-07-08' THEN 1 ELSE 0 END               AS x_rec,
           CASE WHEN TRIM(b.commission)='1' THEN 1 ELSE 0 END             AS x_freecomm,
           CAST(NULLIF(TRIM(b.bet13),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_stake,
           CAST(NULLIF(TRIM(b.validbet),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_valid,
           CAST(NULLIF(TRIM(b.bet16),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_rebate,
           CAST(NULLIF(TRIM(b.bet17),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_net,
           CAST(NULLIF(TRIM(b.bet15),'') AS DECIMAL(20,6))                AS x_rbpct,
           COALESCE(CAST(NULLIF(TRIM(b.bet23),'') AS DECIMAL(20,6)),0)   AS x_agpct,
          NULLIF(CAST(NULLIF(TRIM(b.bet23),'') AS DECIMAL(20,6)),0)     AS x_rate1,
          NULLIF(CAST(NULLIF(TRIM(b.bet24),'') AS DECIMAL(20,6)),0)     AS x_rate2,
          NULLIF(CAST(NULLIF(TRIM(b.bet25),'') AS DECIMAL(20,6)),0)     AS x_rate3,
          NULLIF(CAST(NULLIF(TRIM(b.bet26),'') AS DECIMAL(20,6)),0)     AS x_rate4,
          NULLIF(CAST(NULLIF(TRIM(b.bet27),'') AS DECIMAL(20,6)),0)     AS x_rate5,
          (CASE WHEN NULLIF(CAST(NULLIF(TRIM(b.bet22),'') AS BIGINT),0) IS NOT NULL THEN 5
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet21),'') AS BIGINT),0) IS NOT NULL THEN 4
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet20),'') AS BIGINT),0) IS NOT NULL THEN 3
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet19),'') AS BIGINT),0) IS NOT NULL THEN 2
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet18),'') AS BIGINT),0) IS NOT NULL THEN 1
                ELSE 0 END)                                             AS x_chain_depth,
           CASE WHEN COALESCE(t1.agent_id,t2.agent_id,t3.agent_id,
                              t4.agent_id,t5.agent_id) IS NOT NULL
                THEN 1 ELSE 0 END                                        AS f_testline
    FROM x_ranked b
    LEFT JOIN x_testagent t1 ON t1.agent_id = b.bet18
    LEFT JOIN x_testagent t2 ON t2.agent_id = b.bet19
    LEFT JOIN x_testagent t3 ON t3.agent_id = b.bet20
    LEFT JOIN x_testagent t4 ON t4.agent_id = b.bet21
    LEFT JOIN x_testagent t5 ON t5.agent_id = b.bet22
    WHERE b.x_rn = 1
      AND b.category='1' AND UPPER(TRIM(b.bet38))='N'
      AND CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8)) > 0
  ),
  x_mk AS (
    SELECT s.*,
           CASE WHEN s.f_testline = 0 THEN 1 ELSE 0 END                 AS is_clean
    FROM x_bs0 s
  ),
  x_agg AS (
    SELECT s.x_product                                                        AS x_key,
           COUNT(*) AS n_bets, COUNT(DISTINCT s.x_round) AS n_rounds,
           COUNT(DISTINCT s.x_date) AS active_days, COUNT(DISTINCT s.x_tblshoe) AS active_shoes,
           COUNT(DISTINCT CONCAT_WS('|', s.x_date, s.x_table)) AS active_sessions,
           COUNT(DISTINCT s.x_table) AS n_tables, COUNT(DISTINCT s.x_dealer) AS n_dealers,
           COUNT(DISTINCT s.x_ip) AS n_ips, COUNT(DISTINCT s.x_product) AS n_products,
           MIN(s.x_date) AS first_seen_d, MAX(s.x_date) AS last_seen_d,
           SUM(s.x_stake) AS stake, SUM(s.x_valid) AS valid, SUM(s.x_rebate) AS rebate,
           SUM(s.x_net) AS net, SUM(-s.x_net *(100.0-s.x_agpct)/100.0) AS agent_cost,
           AVG(100.0-s.x_agpct)                   AS agent_pct,
           AVG(s.x_agpct)                         AS company_retain_pct,
           SUM(-s.x_net *s.x_agpct/100.0)         AS agent_cost_a_legacy,
           SUM(s.x_valid*s.x_agpct/100.0)         AS agent_cost_valid_base_legacy,
          AVG(COALESCE(s.x_rate1,100)) AS retain_pct_lv1, AVG(COALESCE(s.x_rate2,100)) AS retain_pct_lv2,
          AVG(COALESCE(s.x_rate3,100)) AS retain_pct_lv3, AVG(COALESCE(s.x_rate4,100)) AS retain_pct_lv4,
          AVG(COALESCE(s.x_rate5,100)) AS retain_pct_lv5, AVG(s.x_chain_depth) AS chain_depth_avg,
          AVG(COALESCE(100.0-s.x_rate1,0)) AS agent_pct_lv1, AVG(COALESCE(100.0-s.x_rate2,0)) AS agent_pct_lv2,
          AVG(COALESCE(100.0-s.x_rate3,0)) AS agent_pct_lv3, AVG(COALESCE(100.0-s.x_rate4,0)) AS agent_pct_lv4,
          AVG(COALESCE(100.0-s.x_rate5,0)) AS agent_pct_lv5,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate1,0)/100.0)                        AS agent_cost_lv1,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate2,0)/100.0)                        AS agent_cost_lv2,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate3,0)/100.0)                        AS agent_cost_lv3,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate4,0)/100.0)                        AS agent_cost_lv4,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate5,0)/100.0)                        AS agent_cost_lv5,
          SUM(-s.x_net*(COALESCE(100.0-s.x_rate1,0)+COALESCE(100.0-s.x_rate2,0)
                       +COALESCE(100.0-s.x_rate3,0)+COALESCE(100.0-s.x_rate4,0)
                       +COALESCE(100.0-s.x_rate5,0))/100.0)                   AS agent_cost_chain_additive,
          SUM(-s.x_net*(1.0 - CAST(COALESCE(s.x_rate1,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate2,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate3,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate4,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate5,100) AS DOUBLE)/100.0))
                                                                       AS agent_cost_chain_nested,
           AVG(s.x_rbpct) AS rbpct, AVG(s.x_freecomm*1.0) AS freecomm_rate,
           PERCENTILE_APPROX(s.x_stake,0.25) AS p25, PERCENTILE_APPROX(s.x_stake,0.50) AS p50,
           PERCENTILE_APPROX(s.x_stake,0.75) AS p75, PERCENTILE_APPROX(s.x_stake,0.90) AS p90,
           PERCENTILE_APPROX(s.x_stake,0.95) AS p95, PERCENTILE_APPROX(s.x_stake,0.99) AS p99,
           PERCENTILE_APPROX(s.x_valid,0.50) AS p50_valid,
           PERCENTILE_APPROX(s.x_net,0.50)   AS p50_profit,
           SUM(CASE WHEN s.x_valid > s.x_stake THEN s.x_stake ELSE 0 END) AS st_in,
           SUM(CASE WHEN s.x_valid > s.x_stake THEN 1 ELSE 0 END)         AS nb_in,
           SUM(CASE WHEN s.x_valid > s.x_stake THEN s.x_net ELSE 0 END)   AS net_in,
           SUM(CASE WHEN NOT (s.x_valid > s.x_stake) THEN s.x_stake ELSE 0 END) AS st_out,
           SUM(CASE WHEN NOT (s.x_valid > s.x_stake) THEN 1 ELSE 0 END)         AS nb_out,
           SUM(CASE WHEN NOT (s.x_valid > s.x_stake) THEN s.x_net ELSE 0 END)   AS net_out,
           SUM(CASE WHEN s.x_rec=1 THEN s.x_stake ELSE 0 END) AS st_rec,
           SUM(CASE WHEN s.x_rec=1 THEN 1 ELSE 0 END)         AS nb_rec
    FROM x_mk s
    WHERE s.is_clean = 1
      AND s.x_product IS NOT NULL AND TRIM(CAST(s.x_product AS STRING)) <> ''
    GROUP BY s.x_product
  ),
      q AS (
        SELECT                                                                                              -- 取列：起始取列子句
          TRIM(bet09)                                                            AS bet09_value,            -- 取列：注型组
          TRIM(commission)                                                       AS commission_value,       -- 取列：佣金标记
          COUNT(*)                                                               AS n_rows,                 -- 计数表达式：该层行数
          SUM(CASE WHEN NULLIF(TRIM(bet41), '') IS NULL
                     AND NULLIF(TRIM(validbet), '') IS NULL THEN 1 ELSE 0 END)   AS n_both_null,            -- 条件计数：象限一
          SUM(CASE WHEN (NULLIF(TRIM(bet41), '') IS NULL)
                    <> (NULLIF(TRIM(validbet), '') IS NULL) THEN 1 ELSE 0 END)   AS n_null_asym,            -- 条件计数：★ 象限二
          SUM(CASE WHEN NULLIF(TRIM(bet41), '') IS NOT NULL
                     AND NULLIF(TRIM(validbet), '') IS NOT NULL
                     AND CAST(TRIM(bet41) AS DECIMAL(20,8))
                       <> CAST(TRIM(validbet) AS DECIMAL(20,8)) THEN 1 ELSE 0 END) AS n_value_diff,         -- 条件计数：★ 象限四
          ROUND(MAX(ABS(CAST(NULLIF(TRIM(bet41), '') AS DECIMAL(20,8))
                        - CAST(NULLIF(TRIM(validbet), '') AS DECIMAL(20,8)))), 8) AS max_abs_diff,          -- 聚合取值：该层最大绝对差
          ROUND(SUM(CAST(NULLIF(TRIM(bet41), '') AS DECIMAL(20,8))), 2)          AS b41_sum,                -- 汇总表达式：该层 bet41 总额
          ROUND(SUM(CAST(NULLIF(TRIM(validbet), '') AS DECIMAL(20,8))), 2)       AS vb_sum,                 -- 汇总表达式：该层 validbet 总额
          CASE                                                                                              -- 条件分支：起始分支——逐层裁定
            WHEN SUM(CASE WHEN (NULLIF(TRIM(bet41), '') IS NULL)
                           <> (NULLIF(TRIM(validbet), '') IS NULL) THEN 1 ELSE 0 END) > 0
              THEN '❌ 本层空值非对称'                                                                       -- 分支判定：空值非对称
            WHEN SUM(CASE WHEN NULLIF(TRIM(bet41), '') IS NOT NULL
                            AND NULLIF(TRIM(validbet), '') IS NOT NULL
                            AND CAST(TRIM(bet41) AS DECIMAL(20,8))
                              <> CAST(TRIM(validbet) AS DECIMAL(20,8)) THEN 1 ELSE 0 END) > 0
              THEN '◐ 本层有数值差'                                                                         -- 分支判定：有数值差
            ELSE '✅ 本层相同'                                                                              -- 分支判定：本层相同
          END                                                                    AS verdict_stratum         -- 条件分支：收束上方判词，产出「verdict_stratum」
        FROM ods_mariadb_2b.ods_a168_bet02                                                                  -- 取数来源：取自注单主表
        WHERE dt >= '2026-03-21' AND dt < '2026-08-07'                                                      -- 过滤条件：限定分析窗
          AND sync_time <= '2026-08-27 09:00:00'
          AND CAST(bet02 AS STRING) = '101'                                                                 -- 并列条件：限定百家乐
        GROUP BY TRIM(bet09), TRIM(commission)                                                              -- 分组：按注型与佣金制分层
      )
    SELECT q.*,
           -- 一·经济层
           ROUND(e.stake,4) AS stake, ROUND(e.valid,4) AS valid_bet,
           ROUND(-e.net,4) AS profit, e.n_bets, e.n_rounds,
           ROUND(e.net/NULLIF(e.stake,0),8) AS roi,
           ROUND(e.net_in/NULLIF(e.st_in,0),8) AS roi_hiturn,
           ROUND(e.net_out/NULLIF(e.st_out,0),8) AS roi_non_hiturn,
           ROUND((e.net-e.rebate)/NULLIF(e.stake,0),8) AS roi_ex_rebate,
           ROUND(e.net,4) AS roi_numerator, ROUND(e.stake,4) AS roi_denominator,
           CASE WHEN e.stake IS NULL THEN 'NULL_DENOM' WHEN e.stake<=0 THEN 'ZERO_DENOM'
                WHEN e.n_bets<30 THEN 'THIN_EXPOSURE' ELSE 'OK' END AS roi_denominator_status,
           ROUND(e.rebate,4) AS rebate_cost, ROUND(e.agent_cost,4)                           AS cost_complement_b,
       ROUND(e.agent_pct,4)                            AS pct_complement,
       ROUND(e.company_retain_pct,4)                   AS pct_top_bet23,
       'AG03-UNRESOLVED'                                     AS agent_formula_version,
      'ALL5_LEVELS_bet23_to_bet27'                    AS agent_level_scope,
      ROUND(e.agent_cost_lv1,4) AS agent_cost_lv1, ROUND(e.agent_cost_lv2,4) AS agent_cost_lv2,
      ROUND(e.agent_cost_lv3,4) AS agent_cost_lv3, ROUND(e.agent_cost_lv4,4) AS agent_cost_lv4,
      ROUND(e.agent_cost_lv5,4) AS agent_cost_lv5,
      ROUND(e.agent_pct_lv1,6) AS agent_pct_lv1, ROUND(e.agent_pct_lv2,6) AS agent_pct_lv2,
      ROUND(e.agent_pct_lv3,6) AS agent_pct_lv3, ROUND(e.agent_pct_lv4,6) AS agent_pct_lv4,
      ROUND(e.agent_pct_lv5,6) AS agent_pct_lv5,
      ROUND(e.retain_pct_lv1,6) AS retain_pct_lv1, ROUND(e.retain_pct_lv2,6) AS retain_pct_lv2,
      ROUND(e.retain_pct_lv3,6) AS retain_pct_lv3, ROUND(e.retain_pct_lv4,6) AS retain_pct_lv4,
      ROUND(e.retain_pct_lv5,6) AS retain_pct_lv5, ROUND(e.chain_depth_avg,4) AS chain_depth_avg,
      ROUND(e.agent_cost_chain_additive,4)            AS agent_cost_chain_additive,
      ROUND(e.agent_cost_chain_nested,4)              AS agent_cost_chain_nested,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_additive,4) AS residual_chain_additive,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_nested,4)   AS residual_chain_nested,
      'PENDING_AG03'                                  AS decision_status,
      'FALSE'                                         AS admit_to_risk_decision,
      'NOT_FOR_ENFORCEMENT'                           AS deliverable_class,
       ROUND(e.agent_cost_a_legacy,4)                  AS agent_cost_a_legacy,
       ROUND(e.agent_cost_valid_base_legacy,4)         AS agent_cost_valid_base_legacy,
           ROUND(-e.net-e.rebate,4)                        AS ngr,
       ROUND(-e.net-e.rebate-e.agent_cost,4)           AS residual_b,
       ROUND(-e.net-e.rebate-e.agent_cost_a_legacy,4)  AS residual_a,
           ROUND((-e.net-e.rebate)/NULLIF(e.stake,0),8)    AS ngr_rate,
       ROUND((-e.net-e.rebate-e.agent_cost)/NULLIF(e.stake,0),8)   AS residual_b_rate,
      -- 【HF9c · canonical accounting contract】
      --   以下 canonical 字段只增加明确 scope；不删除、不覆盖既有字段。
      --   formal_bet23_* 保持 HF9b 当前生产公式及其 NULL/0 语义；
      --   lv1~lv5 / additive / nested 则分别采用各自原始 e.* 成本字段，
      --   rate 一律从未舍入的 e.* 分子 / e.stake 计算，禁止由展示值反算。
      ROUND(e.agent_cost,4) AS agent_cost_bet23_formal_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost,4) AS net_margin_bet23_formal_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost)/NULLIF(e.stake,0),8) AS net_margin_bet23_formal_rate_canonical,
      ROUND(e.agent_cost_lv1,4) AS agent_cost_lv1_bet23_canonical,
      ROUND(e.agent_cost_lv2,4) AS agent_cost_lv2_bet24_canonical,
      ROUND(e.agent_cost_lv3,4) AS agent_cost_lv3_bet25_canonical,
      ROUND(e.agent_cost_lv4,4) AS agent_cost_lv4_bet26_canonical,
      ROUND(e.agent_cost_lv5,4) AS agent_cost_lv5_bet27_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_lv1,4) AS net_margin_lv1_bet23_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_lv1)/NULLIF(e.stake,0),8) AS net_margin_lv1_bet23_rate_canonical,
      ROUND(e.agent_cost_chain_additive,4) AS agent_cost_chain_additive_canonical,
      ROUND(e.agent_cost_chain_nested,4) AS agent_cost_chain_nested_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_additive,4) AS net_margin_chain_additive_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_nested,4) AS net_margin_chain_nested_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_chain_additive)/NULLIF(e.stake,0),8) AS net_margin_chain_additive_rate_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_chain_nested)/NULLIF(e.stake,0),8) AS net_margin_chain_nested_rate_canonical,
       ROUND((-e.net-e.rebate-e.agent_cost_a_legacy)/NULLIF(e.stake,0),8) AS residual_a_rate,
           -- 二·分布层
           ROUND(e.stake/NULLIF(e.n_bets,0),4) AS avg_stake_per_bet,
           ROUND(e.valid/NULLIF(e.n_rounds,0),4) AS avg_valid_bet_per_round,
           ROUND(-e.net/NULLIF(e.n_rounds,0),4) AS avg_profit_per_round,
           ROUND(-e.net/NULLIF(e.active_days,0),4) AS avg_profit_per_day,
           ROUND(-e.net/NULLIF(e.active_shoes,0),4) AS avg_profit_per_shoe,
           ROUND(e.stake/NULLIF(e.active_days,0),4) AS avg_stake_per_active_day,
           ROUND(e.n_rounds*1.0/NULLIF(e.active_days,0),4) AS avg_rounds_per_active_day,
           ROUND(e.st_in/NULLIF(e.nb_in,0),4) AS avg_stake_hiturn,
           ROUND(e.st_out/NULLIF(e.nb_out,0),4) AS avg_stake_non_hiturn,
           ROUND(e.p25,4) AS p25_stake, ROUND(e.p50,4) AS p50_stake, ROUND(e.p75,4) AS p75_stake,
           ROUND(e.p90,4) AS p90_stake, ROUND(e.p95,4) AS p95_stake, ROUND(e.p99,4) AS p99_stake,
           ROUND(e.p50_valid,4) AS p50_valid_bet, ROUND(e.p50_profit,4) AS p50_profit,
           ROUND(e.p95/NULLIF(e.p50,0),6) AS p95_over_p50,
           ROUND(e.p99/NULLIF(e.p50,0),6) AS p99_over_p50,
           ROUND((e.stake/NULLIF(e.n_bets,0))/NULLIF(e.p50,0),6) AS avg_over_p50,
           -- 三·关系层
           e.n_tables AS common_table_count, e.n_dealers AS common_dealer_count,
           e.n_ips AS common_ip_count, e.n_products AS common_product_count,
           ROUND(e.st_in/NULLIF(e.stake,0),8) AS share_hiturn,
           -- 四·rate 层
           ROUND(-e.net/NULLIF(e.stake,0),8) AS hold_rate,
           ROUND(-e.net_in/NULLIF(e.st_in,0),8) AS hold_rate_hiturn,
           ROUND(e.rebate/NULLIF(e.valid,0),8) AS rebate_rate_actual,
           ROUND(e.rbpct,6) AS rebate_pct_config,
           ROUND(e.valid/NULLIF(e.stake,0),6) AS turnover_multiple,
           ROUND(e.freecomm_rate,6) AS free_comm_rate,
           ROUND(e.net_in/NULLIF(e.st_in,0)-e.net_out/NULLIF(e.st_out,0),8) AS roi_delta_hiturn,
           -- 五·动态层
           e.first_seen_d AS first_seen, e.last_seen_d AS last_seen,
           e.active_days, e.active_shoes, e.active_sessions,
           DATEDIFF(e.last_seen_d, e.first_seen_d)+1 AS span_days,
           ROUND(e.active_days*1.0/NULLIF(DATEDIFF(e.last_seen_d,e.first_seen_d)+1,0),6) AS persistence,
           ROUND((e.st_in/NULLIF(e.nb_in,0))/NULLIF(e.st_out/NULLIF(e.nb_out,0),0),6) AS ramp_hiturn,
           ROUND((e.st_rec/NULLIF(e.nb_rec,0))/NULLIF(e.stake/NULLIF(e.n_bets,0),0),6) AS ramp_recent,
           ROUND((e.st_rec/NULLIF(e.stake,0))/0.30,6) AS stake_ramp,
           -- 六·决策层（HF9f · 详见档头【HF9f 变更说明】；本段两版逐字同一）
           NTILE(5) OVER (ORDER BY e.stake) AS vip_tier,                                                        -- 窗口取值：相对刻度 B 族，全体五等分；须连同下方血统五元组一并解读，禁作硬阈值判型
           PERCENT_RANK() OVER (ORDER BY -e.net-e.rebate-e.agent_cost)    AS economic_value,                    -- 窗口取值：HF9f·F-19 修正 —— HF9e 写作 -(-…) 双负号致方向颠倒（#075 实测 corr(economic_value, residual_b) = -1.0000）；今与 action_priority 排序键归一，值大即平台真净利高
           PERCENT_RANK() OVER (ORDER BY e.net/NULLIF(e.stake,0))         AS roi_pr_global,                     -- 窗口取值：HF9f·F-17 正名 —— 本列实为 ROI（玩家净回报率）之全体百分位，与「风险」无关；旧名 risk_value 见下一行
           PERCENT_RANK() OVER (ORDER BY e.net/NULLIF(e.stake,0))         AS risk_value,                        -- 窗口取值：兼容列，恒等于 roi_pr_global，仅为下游迁移窗保留；HF9g 起废弃，禁新引用
           PERCENT_RANK() OVER (ORDER BY e.stake)                         AS pr_stake,                          -- 窗口取值：兼容列，恒等于 pr_global，原名保留以免断链
           PERCENT_RANK() OVER (ORDER BY e.stake)                         AS pr_global,                         -- 窗口取值：HF9f·F-1 双轨之一 —— 全体口径百分位，参照总体即本件全部输出行
           CASE WHEN e.n_rounds >= 30                                                                           -- 条件分支：起始分支 —— 仅在合格子集内计算合格口径百分位
                  THEN PERCENT_RANK() OVER (PARTITION BY CASE WHEN e.n_rounds >= 30 THEN 1 ELSE 0 END ORDER BY e.stake)  -- 分支取值：以合格与否分区，故本值即 n_rounds>=30 子集内之百分位
                ELSE NULL END                                             AS pr_qualified,                      -- 条件分支：收束上方分支 —— 不合格者留 NULL（NULL＝未测，非 0），产出「pr_qualified」
           'n_rounds>=30'                                                 AS pr_qualified_population,           -- 字面取值：血统 —— 合格子集之定义
           COUNT(*) OVER ()                                               AS pr_global_population_n,            -- 窗口取值：血统 —— 全体口径之参照总体规模，渲染时现算，禁写死
           SUM(CASE WHEN e.n_rounds >= 30 THEN 1 ELSE 0 END) OVER ()      AS pr_qualified_population_n,         -- 窗口取值：血统 —— 合格子集之参照总体规模，现算，禁写死
           'PERCENT_RANK_OVER_ORDER_BY_e_stake'                           AS pr_calculation_method,             -- 字面取值：血统 —— 算法标识
           'HF9f'                                                         AS pr_calculation_version,            -- 字面取值：血统 —— 算法版本
           CASE WHEN e.n_rounds IS NULL OR e.n_rounds < 30 THEN 'THIN_ROUNDS' ELSE 'OK' END AS evidence_flag,   -- 条件分支：HF9f·F-2a 证据旗标 —— THIN_ROUNDS 者禁入执行队列，仅入观察队列
           CASE WHEN e.n_rounds IS NULL       THEN NULL                                                         -- 条件分支：起始分支 —— 未测者留 NULL（自家铁律：NULL ≠ 0）
                WHEN e.n_rounds >= 31483      THEN 'L1_POWERED'                                                 -- 分支判定：MDE 反解第一档
                WHEN e.n_rounds >= 15409      THEN 'L2_CI_1P5'                                                  -- 分支判定：MDE 反解第二档
                WHEN e.n_rounds >=  8668      THEN 'L3_CI_2P0'                                                  -- 分支判定：MDE 反解第三档
                WHEN e.n_rounds >=  3852      THEN 'L4_CI_3P0'                                                  -- 分支判定：MDE 反解第四档
                ELSE 'L5_INSUFFICIENT' END                                AS evidence_rate,                     -- 条件分支：收束上方 —— HF9f·F-3 证据分档，承 HF9e 前议之 MDE 反解五档，须于 F-4 敏感性实验后复核
           ROUND(1.96 * 0.95 / SQRT(NULLIF(CAST(e.n_rounds AS DOUBLE),0)),8) AS hold_ci_halfwidth_approx,       -- 比率表达式：HF9f·F-3 逐行现算之 95% 半宽近似；常数 0.95 为登记值，本轮 #075 实测每局 ROI 隐含 σ 于最薄层为 0.9249，二者差异待 F-4 裁定
           CASE WHEN e.stake IS NULL OR e.stake<=0 OR e.n_bets<30 OR e.n_rounds IS NULL OR e.n_rounds<30 THEN 'Z 证据不足 · 不动作'  -- 条件分支：HF9f·F-2 双条件取严 —— HF9e 仅卡 e.n_bets<30，致 n_bets>=30 而 n_rounds<30 者绕过 Z（#075 实测 18,537 名，其中 8,145 名已入 A/D 待裁）；今两条件并列取严
                WHEN PERCENT_RANK() OVER (ORDER BY -e.net-e.rebate-e.agent_cost)<=0.10                          -- 分支判定：平台真净利之最低十分位
                  THEN 'A 净亏最大十分位 · 优先复核'                                                             -- 分支取值：HF9f·F-20 正名 —— 本档 Σresidual_b 于 #075 实测 = -100,236,896，系平台净亏最大群，旧名「残值最低十分位 · 待裁」名实不符
                WHEN PERCENT_RANK() OVER (ORDER BY -e.net-e.rebate-e.agent_cost)>=0.80                          -- 分支判定：平台真净利之最高二十分位
                  THEN 'D 净利最高二十分位 · 优先留存'                                                           -- 分支取值：HF9f·F-20 正名 —— 本档 Σresidual_b 于 #075 实测 = +281,733,190，系核心利润源；与 A 档方向相反，旧版同标「待裁」属名实不符
                ELSE 'E 常规' END                                          AS action_priority                   -- 条件分支：收束上方判词，产出「action_priority」
    FROM q
    LEFT JOIN x_agg e ON CAST(e.x_key AS STRING) = CAST(q.`bet09_value` AS STRING)
  ) y
) z
-- ── 逐批 WHERE 阶梯（★ 口诀：上界 ＝ 下界 ＋ 100000，两数同进）──
--    本件 T_true 未测，无需先跑 T_true；以 0 / 100000 控制本批返回区间，末批由实际行数 < 100000 判定
--    WHERE z.audit_rn >        0 AND z.audit_rn <=   100000   -- 第 1 批
--    WHERE z.audit_rn >   100000 AND z.audit_rn <=   200000   -- 第 2 批
--    WHERE z.audit_rn >   200000 AND z.audit_rn <=   300000   -- 第 3 批
--    WHERE z.audit_rn >   300000 AND z.audit_rn <=   400000   -- 第 4 批
--    WHERE z.audit_rn >   400000 AND z.audit_rn <=   500000   -- 第 5 批
--    WHERE z.audit_rn >   500000 AND z.audit_rn <=   600000   -- 第 6 批
--    WHERE z.audit_rn >   600000 AND z.audit_rn <=   700000   -- 第 7 批
--    …余批类推。第 k 批：WHERE z.audit_rn > (k-1)*100000 AND z.audit_rn <= k*100000
--    某批返回 < 100000 行即为末批，其后不再取。
--
--    ⚠ 常见误写（务必避开）：只推下界而上界不动 ——
--        WHERE z.audit_rn > 100000 AND z.audit_rn <= 100000   ← 自相矛盾，恒为假，返回空集
--        WHERE z.audit_rn > 200000 AND z.audit_rn <= 100000   ← 同上，空集
--      两个数必须**同时**前进，且始终相差 100000。
--      下界 ＝ 上一批之上界；上界 ＝ 本批之上界。
WHERE z.audit_rn > 0 AND z.audit_rn <= 100000 -- ★ HF9c 本批区间
ORDER BY z.audit_rn;


-- ══════════════════════════════════════════════════════════════════════════════════════════════
-- 103. VB_41b_identity_strata_v18b.csv   [总包行 10876~10930 · 原 18 列 ＋六层约 60 列]
--     典型学：M05 退水套利　派生旗标：hiturn（s.x_valid > s.x_stake · 仅供 CASE 条件聚合，全包无任何 WHERE/AND/HAVING 以此过滤）　连接：q.`bet09_value`
-- ══════════════════════════════════════════════════════════════════════════════════════════════
-- ── ① 先跑 T_true 留档（不足 100000 者一次导全，不必分批）──
-- ── ① T_true：HF9c 不再强制预跑完整 COUNT。
--    本批实际返回行数 < 100000 即判定为末批；全批完成后以各批 n_rows / audit_rn 范围核对总量。

-- ── ② 分批取数：第 1 批。第 k 批只改末行两数为 (k-1)*100000 与 k*100000 ──
--    审计字段二（REDTEAM 2026-08-24 裁定 · 四锁）：
--      audit_rn  全局观测坐标 —— 由**与原版审计版逐字同一**之排序键所生，两版可逐行对账
--      batch_id  物理分批信息 —— 该行所属批次，由 audit_rn 算得，非引擎所赋
--    ★ 锁三：二者皆为审计字段，**不得进入任何业务指标计算**。
--    ★ 锁四：两版经 audit_rn 逐行字段核验后，方可宣布输出完全一致。

-- ── ③ 每批取回后自证四数（任一不符即停手回报，禁止放行）──
--    n_rows        = COUNT(*)      须等于 COUNT(DISTINCT audit_rn)   （批内无重复）
--    audit_rn_min  = MIN(audit_rn) 须等于 (k-1)*100000 + 1           （与上批严丝合缝）
--    audit_rn_max  = MAX(audit_rn) 须等于 min + n_rows - 1           （批内无缺口）
--    全批取毕再验：各批 audit_rn 之并集 = 1 .. T_true，无缺号、无重号。
--     ★ 首行＝平台真净亏最多者（已扣退水与代理占成）。
--
SELECT z.*,
       CAST(FLOOR((z.audit_rn - 1) / 100000) + 1 AS INT)          AS batch_id,
       'A168_HF9F_20260827_0900' AS run_id,
       '2026-08-27 09:00:00' AS snapshot_sync_time
FROM (
  SELECT y.*,
         ROW_NUMBER() OVER (ORDER BY y.`residual_b` ASC, y.`roi` DESC, y.`bet09_value`, y.`commission_value`, y.`n_rows`, y.`n_both_null`, y.`n_null_asym`, y.`n_value_diff`, y.`pct_value_diff`, y.`max_abs_diff`, y.`d_min`, y.`d_max`, y.`sum_abs_diff`, y.`n_both_zero`, y.`n_b41_zero_vb_pos`, y.`n_b41_pos_vb_zero`, y.`d_sign_uniform`, y.`b41_sum`, y.`vb_sum`, y.`verdict_stratum`) AS audit_rn
  FROM (
    WITH
      x_ranked AS (
    SELECT b.bet01, b.bet03, b.bet04, b.bet05, b.bet09, b.bet11, b.bet13,
           b.bet15, b.bet16, b.bet17, b.bet18, b.bet19, b.bet20, b.bet21,
           b.bet22, b.bet23, b.bet24, b.bet25, b.bet26, b.bet27, b.bet38, b.bet39, b.category, b.commission,
           b.dt, b.eid, b.ip, b.validbet, b.updatetime, b.sync_time,
           ROW_NUMBER() OVER (
             PARTITION BY b.bet01
             ORDER BY b.updatetime DESC, b.sync_time DESC, b.dt DESC)      AS x_rn
    FROM ods_mariadb_2b.ods_a168_bet02 b
    WHERE b.dt >= '2026-03-21' AND b.dt < '2026-08-07'
      AND b.bet02 = '101'
      AND b.sync_time <= '2026-08-27 09:00:00'
  ),
    x_testagent AS (
    SELECT age001 AS agent_id FROM ods_mariadb_2b.ods_a168_agent WHERE age022 = '1'
  ),
    x_bs0 AS (
    SELECT b.bet05 AS x_member, b.eid AS x_dealer, b.bet39 AS x_table,
           b.bet03 AS x_shoe, b.ip AS x_ip, b.bet09 AS x_product, b.dt AS x_date,
           CONCAT_WS('|', b.bet03, b.bet04, b.bet39)                      AS x_round,
           CONCAT_WS('|', b.bet39, b.bet03)                               AS x_tblshoe,
           CAST(NULLIF(TRIM(b.bet04),'') AS INT)                          AS x_rno,
           CASE WHEN b.dt >= '2026-07-08' THEN 1 ELSE 0 END               AS x_rec,
           CASE WHEN TRIM(b.commission)='1' THEN 1 ELSE 0 END             AS x_freecomm,
           CAST(NULLIF(TRIM(b.bet13),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_stake,
           CAST(NULLIF(TRIM(b.validbet),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_valid,
           CAST(NULLIF(TRIM(b.bet16),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_rebate,
           CAST(NULLIF(TRIM(b.bet17),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_net,
           CAST(NULLIF(TRIM(b.bet15),'') AS DECIMAL(20,6))                AS x_rbpct,
           COALESCE(CAST(NULLIF(TRIM(b.bet23),'') AS DECIMAL(20,6)),0)   AS x_agpct,
          NULLIF(CAST(NULLIF(TRIM(b.bet23),'') AS DECIMAL(20,6)),0)     AS x_rate1,
          NULLIF(CAST(NULLIF(TRIM(b.bet24),'') AS DECIMAL(20,6)),0)     AS x_rate2,
          NULLIF(CAST(NULLIF(TRIM(b.bet25),'') AS DECIMAL(20,6)),0)     AS x_rate3,
          NULLIF(CAST(NULLIF(TRIM(b.bet26),'') AS DECIMAL(20,6)),0)     AS x_rate4,
          NULLIF(CAST(NULLIF(TRIM(b.bet27),'') AS DECIMAL(20,6)),0)     AS x_rate5,
          (CASE WHEN NULLIF(CAST(NULLIF(TRIM(b.bet22),'') AS BIGINT),0) IS NOT NULL THEN 5
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet21),'') AS BIGINT),0) IS NOT NULL THEN 4
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet20),'') AS BIGINT),0) IS NOT NULL THEN 3
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet19),'') AS BIGINT),0) IS NOT NULL THEN 2
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet18),'') AS BIGINT),0) IS NOT NULL THEN 1
                ELSE 0 END)                                             AS x_chain_depth,
           CASE WHEN COALESCE(t1.agent_id,t2.agent_id,t3.agent_id,
                              t4.agent_id,t5.agent_id) IS NOT NULL
                THEN 1 ELSE 0 END                                        AS f_testline
    FROM x_ranked b
    LEFT JOIN x_testagent t1 ON t1.agent_id = b.bet18
    LEFT JOIN x_testagent t2 ON t2.agent_id = b.bet19
    LEFT JOIN x_testagent t3 ON t3.agent_id = b.bet20
    LEFT JOIN x_testagent t4 ON t4.agent_id = b.bet21
    LEFT JOIN x_testagent t5 ON t5.agent_id = b.bet22
    WHERE b.x_rn = 1
      AND b.category='1' AND UPPER(TRIM(b.bet38))='N'
      AND CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8)) > 0
  ),
  x_mk AS (
    SELECT s.*,
           CASE WHEN s.f_testline = 0 THEN 1 ELSE 0 END                 AS is_clean
    FROM x_bs0 s
  ),
  x_agg AS (
    SELECT s.x_product                                                        AS x_key,
           COUNT(*) AS n_bets, COUNT(DISTINCT s.x_round) AS n_rounds,
           COUNT(DISTINCT s.x_date) AS active_days, COUNT(DISTINCT s.x_tblshoe) AS active_shoes,
           COUNT(DISTINCT CONCAT_WS('|', s.x_date, s.x_table)) AS active_sessions,
           COUNT(DISTINCT s.x_table) AS n_tables, COUNT(DISTINCT s.x_dealer) AS n_dealers,
           COUNT(DISTINCT s.x_ip) AS n_ips, COUNT(DISTINCT s.x_product) AS n_products,
           MIN(s.x_date) AS first_seen_d, MAX(s.x_date) AS last_seen_d,
           SUM(s.x_stake) AS stake, SUM(s.x_valid) AS valid, SUM(s.x_rebate) AS rebate,
           SUM(s.x_net) AS net, SUM(-s.x_net *(100.0-s.x_agpct)/100.0) AS agent_cost,
           AVG(100.0-s.x_agpct)                   AS agent_pct,
           AVG(s.x_agpct)                         AS company_retain_pct,
           SUM(-s.x_net *s.x_agpct/100.0)         AS agent_cost_a_legacy,
           SUM(s.x_valid*s.x_agpct/100.0)         AS agent_cost_valid_base_legacy,
          AVG(COALESCE(s.x_rate1,100)) AS retain_pct_lv1, AVG(COALESCE(s.x_rate2,100)) AS retain_pct_lv2,
          AVG(COALESCE(s.x_rate3,100)) AS retain_pct_lv3, AVG(COALESCE(s.x_rate4,100)) AS retain_pct_lv4,
          AVG(COALESCE(s.x_rate5,100)) AS retain_pct_lv5, AVG(s.x_chain_depth) AS chain_depth_avg,
          AVG(COALESCE(100.0-s.x_rate1,0)) AS agent_pct_lv1, AVG(COALESCE(100.0-s.x_rate2,0)) AS agent_pct_lv2,
          AVG(COALESCE(100.0-s.x_rate3,0)) AS agent_pct_lv3, AVG(COALESCE(100.0-s.x_rate4,0)) AS agent_pct_lv4,
          AVG(COALESCE(100.0-s.x_rate5,0)) AS agent_pct_lv5,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate1,0)/100.0)                        AS agent_cost_lv1,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate2,0)/100.0)                        AS agent_cost_lv2,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate3,0)/100.0)                        AS agent_cost_lv3,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate4,0)/100.0)                        AS agent_cost_lv4,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate5,0)/100.0)                        AS agent_cost_lv5,
          SUM(-s.x_net*(COALESCE(100.0-s.x_rate1,0)+COALESCE(100.0-s.x_rate2,0)
                       +COALESCE(100.0-s.x_rate3,0)+COALESCE(100.0-s.x_rate4,0)
                       +COALESCE(100.0-s.x_rate5,0))/100.0)                   AS agent_cost_chain_additive,
          SUM(-s.x_net*(1.0 - CAST(COALESCE(s.x_rate1,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate2,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate3,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate4,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate5,100) AS DOUBLE)/100.0))
                                                                       AS agent_cost_chain_nested,
           AVG(s.x_rbpct) AS rbpct, AVG(s.x_freecomm*1.0) AS freecomm_rate,
           PERCENTILE_APPROX(s.x_stake,0.25) AS p25, PERCENTILE_APPROX(s.x_stake,0.50) AS p50,
           PERCENTILE_APPROX(s.x_stake,0.75) AS p75, PERCENTILE_APPROX(s.x_stake,0.90) AS p90,
           PERCENTILE_APPROX(s.x_stake,0.95) AS p95, PERCENTILE_APPROX(s.x_stake,0.99) AS p99,
           PERCENTILE_APPROX(s.x_valid,0.50) AS p50_valid,
           PERCENTILE_APPROX(s.x_net,0.50)   AS p50_profit,
           SUM(CASE WHEN s.x_valid > s.x_stake THEN s.x_stake ELSE 0 END) AS st_in,
           SUM(CASE WHEN s.x_valid > s.x_stake THEN 1 ELSE 0 END)         AS nb_in,
           SUM(CASE WHEN s.x_valid > s.x_stake THEN s.x_net ELSE 0 END)   AS net_in,
           SUM(CASE WHEN NOT (s.x_valid > s.x_stake) THEN s.x_stake ELSE 0 END) AS st_out,
           SUM(CASE WHEN NOT (s.x_valid > s.x_stake) THEN 1 ELSE 0 END)         AS nb_out,
           SUM(CASE WHEN NOT (s.x_valid > s.x_stake) THEN s.x_net ELSE 0 END)   AS net_out,
           SUM(CASE WHEN s.x_rec=1 THEN s.x_stake ELSE 0 END) AS st_rec,
           SUM(CASE WHEN s.x_rec=1 THEN 1 ELSE 0 END)         AS nb_rec
    FROM x_mk s
    WHERE s.is_clean = 1
      AND s.x_product IS NOT NULL AND TRIM(CAST(s.x_product AS STRING)) <> ''
    GROUP BY s.x_product
  ),
      q AS (
        WITH src AS (                                                                                       -- 公共表表达式：开启中间结果集 src——逐行取二列与差值
          SELECT TRIM(bet09)                                                     AS g,                      -- 取列：注型组
                 TRIM(commission)                                                AS comm,                   -- 取列：佣金标记
                 CAST(NULLIF(TRIM(bet41), '')    AS DECIMAL(20,8))               AS v41,                    -- 取列：bet41 转数值
                 CAST(NULLIF(TRIM(validbet), '') AS DECIMAL(20,8))               AS vvb,                    -- 取列：validbet 转数值
                 CAST(NULLIF(TRIM(bet41), '')    AS DECIMAL(20,8))
                   - CAST(NULLIF(TRIM(validbet), '') AS DECIMAL(20,8))           AS d                       -- 取值表达式：差值 D ＝ bet41 − validbet
          FROM ods_mariadb_2b.ods_a168_bet02                                                                -- 取数来源：取自注单主表
          WHERE dt >= '2026-03-21' AND dt < '2026-08-07'                                                    -- 过滤条件：限定分析窗
            AND sync_time <= '2026-08-27 09:00:00'
            AND CAST(bet02 AS STRING) = '101'                                                               -- 并列条件：限定百家乐
        )                                                                                                   -- 续行：收束上方的子查询或函数括号
        SELECT                                                                                              -- 取列：起始取列子句
          g                                                                      AS bet09_value,            -- 取列：〔01〕注型
          comm                                                                   AS commission_value,       -- 取列：〔02〕佣金制
          COUNT(*)                                                               AS n_rows,                 -- 计数表达式：〔03〕该层行数
          SUM(CASE WHEN v41 IS NULL AND vvb IS NULL THEN 1 ELSE 0 END)           AS n_both_null,            -- 条件计数：〔04〕二者皆空
          SUM(CASE WHEN (v41 IS NULL) <> (vvb IS NULL) THEN 1 ELSE 0 END)        AS n_null_asym,            -- 条件计数：〔05〕空值非对称
          SUM(CASE WHEN v41 IS NOT NULL AND vvb IS NOT NULL AND v41 <> vvb THEN 1 ELSE 0 END) AS n_value_diff, -- 条件计数：〔06〕数值不等
          ROUND(SUM(CASE WHEN v41 IS NOT NULL AND vvb IS NOT NULL AND v41 <> vvb THEN 1 ELSE 0 END) * 100.0
                / NULLIF(COUNT(*), 0), 8)                                        AS pct_value_diff,         -- 比率表达式：〔07〕差异占该层之比
          ROUND(MAX(ABS(d)), 8)                                                  AS max_abs_diff,           -- 聚合取值：〔08〕最大绝对差
          ROUND(MIN(d), 8)                                                       AS d_min,                  -- 聚合取值：〔09〕差值下界
          ROUND(MAX(d), 8)                                                       AS d_max,                  -- 聚合取值：〔10〕差值上界
          ROUND(SUM(ABS(d)), 8)                                                  AS sum_abs_diff,           -- 汇总表达式：〔11〕绝对差之和
          SUM(CASE WHEN v41 = 0 AND vvb = 0 THEN 1 ELSE 0 END)                   AS n_both_zero,            -- 条件计数：〔12〕零对零
          SUM(CASE WHEN v41 = 0 AND vvb > 0 THEN 1 ELSE 0 END)                   AS n_b41_zero_vb_pos,      -- 条件计数：〔13〕bet41 零而 validbet 正
          SUM(CASE WHEN v41 > 0 AND vvb = 0 THEN 1 ELSE 0 END)                   AS n_b41_pos_vb_zero,      -- 条件计数：〔14〕反向
          CASE                                                                                              -- 条件分支：〔15〕起始分支——★ 六态穷尽（本版之核心）
            WHEN MIN(d) IS NULL OR MAX(d) IS NULL                       THEN 'NO_DATA'                      -- 分支判定：该层无可比之行
            WHEN MIN(d) = 0 AND MAX(d) = 0                              THEN 'NO_DIFFERENCE'                -- 分支判定：a=0 ∧ b=0——差值恒零
            WHEN MIN(d) < 0 AND MAX(d) < 0 AND MIN(d) = MAX(d)          THEN 'B41_LE_VB_CONSTANT'           -- 分支判定：★ a=b<0——恒定负差
            WHEN MIN(d) > 0 AND MAX(d) > 0 AND MIN(d) = MAX(d)          THEN 'B41_GE_VB_CONSTANT'           -- 分支判定：★ a=b>0——恒定正差
            WHEN MIN(d) < 0 AND MAX(d) <= 0                             THEN 'B41_LE_VB_UNIFORM'            -- 分支判定：a<0 ∧ b≤0——单向非正
            WHEN MIN(d) >= 0 AND MAX(d) > 0                             THEN 'B41_GE_VB_UNIFORM'            -- 分支判定：a≥0 ∧ b>0——单向非负
            WHEN MIN(d) < 0 AND MAX(d) > 0                              THEN 'BIDIRECTIONAL'                -- 分支判定：a<0 ∧ b>0——双向
            ELSE 'UNCLASSIFIED'                                                                             -- 分支判定：★★ 穷举锁——跑毕须为 0，非零即判词空间仍有缺口
          END                                                                    AS d_sign_uniform,         -- 条件分支：收束上方判词，产出「d_sign_uniform」
          ROUND(SUM(v41), 2)                                                     AS b41_sum,                -- 汇总表达式：〔16〕该层 bet41 总额
          ROUND(SUM(vvb), 2)                                                     AS vb_sum,                 -- 汇总表达式：〔17〕该层 validbet 总额
          CASE                                                                                              -- 条件分支：〔18〕起始分支——五态裁定（承 v1.0.2，不改）
            WHEN SUM(CASE WHEN (v41 IS NULL) <> (vvb IS NULL) THEN 1 ELSE 0 END) > 0
              THEN 'FAIL'                                                                                   -- 分支判定：空值语义不同
            WHEN COUNT(*) = SUM(CASE WHEN v41 = 0 AND vvb = 0 THEN 1 ELSE 0 END)
              THEN 'NO_COMPARABLE_VALUE'                                                                    -- 分支判定：二列皆恒为零，无可比之量
            WHEN SUM(CASE WHEN v41 IS NOT NULL AND vvb IS NOT NULL AND v41 <> vvb THEN 1 ELSE 0 END) = 0
             AND (SUM(v41) > 0 OR SUM(vvb) > 0)
              THEN 'IDENTICAL_NONZERO'                                                                      -- 分支判定：无差异且有正值
            WHEN SUM(CASE WHEN v41 IS NOT NULL AND vvb IS NOT NULL AND v41 <> vvb THEN 1 ELSE 0 END) = 0
             AND COALESCE(SUM(v41), 0) = 0 AND COALESCE(SUM(vvb), 0) = 0
              THEN 'IDENTICAL_ZERO_ONLY'                                                                    -- 分支判定：无差异惟总额皆零
            ELSE 'CONDITIONAL'                                                                              -- 分支判定：有数值差异
          END                                                                    AS verdict_stratum         -- 条件分支：收束上方判词，产出「verdict_stratum」
        FROM src                                                                                            -- 取数来源：取自本条自建的中间结果集 src
        GROUP BY g, comm                                                                                    -- 分组：按注型与佣金制分层
      )
    SELECT q.*,
           -- 一·经济层
           ROUND(e.stake,4) AS stake, ROUND(e.valid,4) AS valid_bet,
           ROUND(-e.net,4) AS profit, e.n_bets, e.n_rounds,
           ROUND(e.net/NULLIF(e.stake,0),8) AS roi,
           ROUND(e.net_in/NULLIF(e.st_in,0),8) AS roi_hiturn,
           ROUND(e.net_out/NULLIF(e.st_out,0),8) AS roi_non_hiturn,
           ROUND((e.net-e.rebate)/NULLIF(e.stake,0),8) AS roi_ex_rebate,
           ROUND(e.net,4) AS roi_numerator, ROUND(e.stake,4) AS roi_denominator,
           CASE WHEN e.stake IS NULL THEN 'NULL_DENOM' WHEN e.stake<=0 THEN 'ZERO_DENOM'
                WHEN e.n_bets<30 THEN 'THIN_EXPOSURE' ELSE 'OK' END AS roi_denominator_status,
           ROUND(e.rebate,4) AS rebate_cost, ROUND(e.agent_cost,4)                           AS cost_complement_b,
       ROUND(e.agent_pct,4)                            AS pct_complement,
       ROUND(e.company_retain_pct,4)                   AS pct_top_bet23,
       'AG03-UNRESOLVED'                                     AS agent_formula_version,
      'ALL5_LEVELS_bet23_to_bet27'                    AS agent_level_scope,
      ROUND(e.agent_cost_lv1,4) AS agent_cost_lv1, ROUND(e.agent_cost_lv2,4) AS agent_cost_lv2,
      ROUND(e.agent_cost_lv3,4) AS agent_cost_lv3, ROUND(e.agent_cost_lv4,4) AS agent_cost_lv4,
      ROUND(e.agent_cost_lv5,4) AS agent_cost_lv5,
      ROUND(e.agent_pct_lv1,6) AS agent_pct_lv1, ROUND(e.agent_pct_lv2,6) AS agent_pct_lv2,
      ROUND(e.agent_pct_lv3,6) AS agent_pct_lv3, ROUND(e.agent_pct_lv4,6) AS agent_pct_lv4,
      ROUND(e.agent_pct_lv5,6) AS agent_pct_lv5,
      ROUND(e.retain_pct_lv1,6) AS retain_pct_lv1, ROUND(e.retain_pct_lv2,6) AS retain_pct_lv2,
      ROUND(e.retain_pct_lv3,6) AS retain_pct_lv3, ROUND(e.retain_pct_lv4,6) AS retain_pct_lv4,
      ROUND(e.retain_pct_lv5,6) AS retain_pct_lv5, ROUND(e.chain_depth_avg,4) AS chain_depth_avg,
      ROUND(e.agent_cost_chain_additive,4)            AS agent_cost_chain_additive,
      ROUND(e.agent_cost_chain_nested,4)              AS agent_cost_chain_nested,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_additive,4) AS residual_chain_additive,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_nested,4)   AS residual_chain_nested,
      'PENDING_AG03'                                  AS decision_status,
      'FALSE'                                         AS admit_to_risk_decision,
      'NOT_FOR_ENFORCEMENT'                           AS deliverable_class,
       ROUND(e.agent_cost_a_legacy,4)                  AS agent_cost_a_legacy,
       ROUND(e.agent_cost_valid_base_legacy,4)         AS agent_cost_valid_base_legacy,
           ROUND(-e.net-e.rebate,4)                        AS ngr,
       ROUND(-e.net-e.rebate-e.agent_cost,4)           AS residual_b,
       ROUND(-e.net-e.rebate-e.agent_cost_a_legacy,4)  AS residual_a,
           ROUND((-e.net-e.rebate)/NULLIF(e.stake,0),8)    AS ngr_rate,
       ROUND((-e.net-e.rebate-e.agent_cost)/NULLIF(e.stake,0),8)   AS residual_b_rate,
      -- 【HF9c · canonical accounting contract】
      --   以下 canonical 字段只增加明确 scope；不删除、不覆盖既有字段。
      --   formal_bet23_* 保持 HF9b 当前生产公式及其 NULL/0 语义；
      --   lv1~lv5 / additive / nested 则分别采用各自原始 e.* 成本字段，
      --   rate 一律从未舍入的 e.* 分子 / e.stake 计算，禁止由展示值反算。
      ROUND(e.agent_cost,4) AS agent_cost_bet23_formal_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost,4) AS net_margin_bet23_formal_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost)/NULLIF(e.stake,0),8) AS net_margin_bet23_formal_rate_canonical,
      ROUND(e.agent_cost_lv1,4) AS agent_cost_lv1_bet23_canonical,
      ROUND(e.agent_cost_lv2,4) AS agent_cost_lv2_bet24_canonical,
      ROUND(e.agent_cost_lv3,4) AS agent_cost_lv3_bet25_canonical,
      ROUND(e.agent_cost_lv4,4) AS agent_cost_lv4_bet26_canonical,
      ROUND(e.agent_cost_lv5,4) AS agent_cost_lv5_bet27_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_lv1,4) AS net_margin_lv1_bet23_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_lv1)/NULLIF(e.stake,0),8) AS net_margin_lv1_bet23_rate_canonical,
      ROUND(e.agent_cost_chain_additive,4) AS agent_cost_chain_additive_canonical,
      ROUND(e.agent_cost_chain_nested,4) AS agent_cost_chain_nested_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_additive,4) AS net_margin_chain_additive_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_nested,4) AS net_margin_chain_nested_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_chain_additive)/NULLIF(e.stake,0),8) AS net_margin_chain_additive_rate_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_chain_nested)/NULLIF(e.stake,0),8) AS net_margin_chain_nested_rate_canonical,
       ROUND((-e.net-e.rebate-e.agent_cost_a_legacy)/NULLIF(e.stake,0),8) AS residual_a_rate,
           -- 二·分布层
           ROUND(e.stake/NULLIF(e.n_bets,0),4) AS avg_stake_per_bet,
           ROUND(e.valid/NULLIF(e.n_rounds,0),4) AS avg_valid_bet_per_round,
           ROUND(-e.net/NULLIF(e.n_rounds,0),4) AS avg_profit_per_round,
           ROUND(-e.net/NULLIF(e.active_days,0),4) AS avg_profit_per_day,
           ROUND(-e.net/NULLIF(e.active_shoes,0),4) AS avg_profit_per_shoe,
           ROUND(e.stake/NULLIF(e.active_days,0),4) AS avg_stake_per_active_day,
           ROUND(e.n_rounds*1.0/NULLIF(e.active_days,0),4) AS avg_rounds_per_active_day,
           ROUND(e.st_in/NULLIF(e.nb_in,0),4) AS avg_stake_hiturn,
           ROUND(e.st_out/NULLIF(e.nb_out,0),4) AS avg_stake_non_hiturn,
           ROUND(e.p25,4) AS p25_stake, ROUND(e.p50,4) AS p50_stake, ROUND(e.p75,4) AS p75_stake,
           ROUND(e.p90,4) AS p90_stake, ROUND(e.p95,4) AS p95_stake, ROUND(e.p99,4) AS p99_stake,
           ROUND(e.p50_valid,4) AS p50_valid_bet, ROUND(e.p50_profit,4) AS p50_profit,
           ROUND(e.p95/NULLIF(e.p50,0),6) AS p95_over_p50,
           ROUND(e.p99/NULLIF(e.p50,0),6) AS p99_over_p50,
           ROUND((e.stake/NULLIF(e.n_bets,0))/NULLIF(e.p50,0),6) AS avg_over_p50,
           -- 三·关系层
           e.n_tables AS common_table_count, e.n_dealers AS common_dealer_count,
           e.n_ips AS common_ip_count, e.n_products AS common_product_count,
           ROUND(e.st_in/NULLIF(e.stake,0),8) AS share_hiturn,
           -- 四·rate 层
           ROUND(-e.net/NULLIF(e.stake,0),8) AS hold_rate,
           ROUND(-e.net_in/NULLIF(e.st_in,0),8) AS hold_rate_hiturn,
           ROUND(e.rebate/NULLIF(e.valid,0),8) AS rebate_rate_actual,
           ROUND(e.rbpct,6) AS rebate_pct_config,
           ROUND(e.valid/NULLIF(e.stake,0),6) AS turnover_multiple,
           ROUND(e.freecomm_rate,6) AS free_comm_rate,
           ROUND(e.net_in/NULLIF(e.st_in,0)-e.net_out/NULLIF(e.st_out,0),8) AS roi_delta_hiturn,
           -- 五·动态层
           e.first_seen_d AS first_seen, e.last_seen_d AS last_seen,
           e.active_days, e.active_shoes, e.active_sessions,
           DATEDIFF(e.last_seen_d, e.first_seen_d)+1 AS span_days,
           ROUND(e.active_days*1.0/NULLIF(DATEDIFF(e.last_seen_d,e.first_seen_d)+1,0),6) AS persistence,
           ROUND((e.st_in/NULLIF(e.nb_in,0))/NULLIF(e.st_out/NULLIF(e.nb_out,0),0),6) AS ramp_hiturn,
           ROUND((e.st_rec/NULLIF(e.nb_rec,0))/NULLIF(e.stake/NULLIF(e.n_bets,0),0),6) AS ramp_recent,
           ROUND((e.st_rec/NULLIF(e.stake,0))/0.30,6) AS stake_ramp,
           -- 六·决策层（HF9f · 详见档头【HF9f 变更说明】；本段两版逐字同一）
           NTILE(5) OVER (ORDER BY e.stake) AS vip_tier,                                                        -- 窗口取值：相对刻度 B 族，全体五等分；须连同下方血统五元组一并解读，禁作硬阈值判型
           PERCENT_RANK() OVER (ORDER BY -e.net-e.rebate-e.agent_cost)    AS economic_value,                    -- 窗口取值：HF9f·F-19 修正 —— HF9e 写作 -(-…) 双负号致方向颠倒（#075 实测 corr(economic_value, residual_b) = -1.0000）；今与 action_priority 排序键归一，值大即平台真净利高
           PERCENT_RANK() OVER (ORDER BY e.net/NULLIF(e.stake,0))         AS roi_pr_global,                     -- 窗口取值：HF9f·F-17 正名 —— 本列实为 ROI（玩家净回报率）之全体百分位，与「风险」无关；旧名 risk_value 见下一行
           PERCENT_RANK() OVER (ORDER BY e.net/NULLIF(e.stake,0))         AS risk_value,                        -- 窗口取值：兼容列，恒等于 roi_pr_global，仅为下游迁移窗保留；HF9g 起废弃，禁新引用
           PERCENT_RANK() OVER (ORDER BY e.stake)                         AS pr_stake,                          -- 窗口取值：兼容列，恒等于 pr_global，原名保留以免断链
           PERCENT_RANK() OVER (ORDER BY e.stake)                         AS pr_global,                         -- 窗口取值：HF9f·F-1 双轨之一 —— 全体口径百分位，参照总体即本件全部输出行
           CASE WHEN e.n_rounds >= 30                                                                           -- 条件分支：起始分支 —— 仅在合格子集内计算合格口径百分位
                  THEN PERCENT_RANK() OVER (PARTITION BY CASE WHEN e.n_rounds >= 30 THEN 1 ELSE 0 END ORDER BY e.stake)  -- 分支取值：以合格与否分区，故本值即 n_rounds>=30 子集内之百分位
                ELSE NULL END                                             AS pr_qualified,                      -- 条件分支：收束上方分支 —— 不合格者留 NULL（NULL＝未测，非 0），产出「pr_qualified」
           'n_rounds>=30'                                                 AS pr_qualified_population,           -- 字面取值：血统 —— 合格子集之定义
           COUNT(*) OVER ()                                               AS pr_global_population_n,            -- 窗口取值：血统 —— 全体口径之参照总体规模，渲染时现算，禁写死
           SUM(CASE WHEN e.n_rounds >= 30 THEN 1 ELSE 0 END) OVER ()      AS pr_qualified_population_n,         -- 窗口取值：血统 —— 合格子集之参照总体规模，现算，禁写死
           'PERCENT_RANK_OVER_ORDER_BY_e_stake'                           AS pr_calculation_method,             -- 字面取值：血统 —— 算法标识
           'HF9f'                                                         AS pr_calculation_version,            -- 字面取值：血统 —— 算法版本
           CASE WHEN e.n_rounds IS NULL OR e.n_rounds < 30 THEN 'THIN_ROUNDS' ELSE 'OK' END AS evidence_flag,   -- 条件分支：HF9f·F-2a 证据旗标 —— THIN_ROUNDS 者禁入执行队列，仅入观察队列
           CASE WHEN e.n_rounds IS NULL       THEN NULL                                                         -- 条件分支：起始分支 —— 未测者留 NULL（自家铁律：NULL ≠ 0）
                WHEN e.n_rounds >= 31483      THEN 'L1_POWERED'                                                 -- 分支判定：MDE 反解第一档
                WHEN e.n_rounds >= 15409      THEN 'L2_CI_1P5'                                                  -- 分支判定：MDE 反解第二档
                WHEN e.n_rounds >=  8668      THEN 'L3_CI_2P0'                                                  -- 分支判定：MDE 反解第三档
                WHEN e.n_rounds >=  3852      THEN 'L4_CI_3P0'                                                  -- 分支判定：MDE 反解第四档
                ELSE 'L5_INSUFFICIENT' END                                AS evidence_rate,                     -- 条件分支：收束上方 —— HF9f·F-3 证据分档，承 HF9e 前议之 MDE 反解五档，须于 F-4 敏感性实验后复核
           ROUND(1.96 * 0.95 / SQRT(NULLIF(CAST(e.n_rounds AS DOUBLE),0)),8) AS hold_ci_halfwidth_approx,       -- 比率表达式：HF9f·F-3 逐行现算之 95% 半宽近似；常数 0.95 为登记值，本轮 #075 实测每局 ROI 隐含 σ 于最薄层为 0.9249，二者差异待 F-4 裁定
           CASE WHEN e.stake IS NULL OR e.stake<=0 OR e.n_bets<30 OR e.n_rounds IS NULL OR e.n_rounds<30 THEN 'Z 证据不足 · 不动作'  -- 条件分支：HF9f·F-2 双条件取严 —— HF9e 仅卡 e.n_bets<30，致 n_bets>=30 而 n_rounds<30 者绕过 Z（#075 实测 18,537 名，其中 8,145 名已入 A/D 待裁）；今两条件并列取严
                WHEN PERCENT_RANK() OVER (ORDER BY -e.net-e.rebate-e.agent_cost)<=0.10                          -- 分支判定：平台真净利之最低十分位
                  THEN 'A 净亏最大十分位 · 优先复核'                                                             -- 分支取值：HF9f·F-20 正名 —— 本档 Σresidual_b 于 #075 实测 = -100,236,896，系平台净亏最大群，旧名「残值最低十分位 · 待裁」名实不符
                WHEN PERCENT_RANK() OVER (ORDER BY -e.net-e.rebate-e.agent_cost)>=0.80                          -- 分支判定：平台真净利之最高二十分位
                  THEN 'D 净利最高二十分位 · 优先留存'                                                           -- 分支取值：HF9f·F-20 正名 —— 本档 Σresidual_b 于 #075 实测 = +281,733,190，系核心利润源；与 A 档方向相反，旧版同标「待裁」属名实不符
                ELSE 'E 常规' END                                          AS action_priority                   -- 条件分支：收束上方判词，产出「action_priority」
    FROM q
    LEFT JOIN x_agg e ON CAST(e.x_key AS STRING) = CAST(q.`bet09_value` AS STRING)
  ) y
) z
-- ── 逐批 WHERE 阶梯（★ 口诀：上界 ＝ 下界 ＋ 100000，两数同进）──
--    本件 T_true 未测，无需先跑 T_true；以 0 / 100000 控制本批返回区间，末批由实际行数 < 100000 判定
--    WHERE z.audit_rn >        0 AND z.audit_rn <=   100000   -- 第 1 批
--    WHERE z.audit_rn >   100000 AND z.audit_rn <=   200000   -- 第 2 批
--    WHERE z.audit_rn >   200000 AND z.audit_rn <=   300000   -- 第 3 批
--    WHERE z.audit_rn >   300000 AND z.audit_rn <=   400000   -- 第 4 批
--    WHERE z.audit_rn >   400000 AND z.audit_rn <=   500000   -- 第 5 批
--    WHERE z.audit_rn >   500000 AND z.audit_rn <=   600000   -- 第 6 批
--    WHERE z.audit_rn >   600000 AND z.audit_rn <=   700000   -- 第 7 批
--    …余批类推。第 k 批：WHERE z.audit_rn > (k-1)*100000 AND z.audit_rn <= k*100000
--    某批返回 < 100000 行即为末批，其后不再取。
--
--    ⚠ 常见误写（务必避开）：只推下界而上界不动 ——
--        WHERE z.audit_rn > 100000 AND z.audit_rn <= 100000   ← 自相矛盾，恒为假，返回空集
--        WHERE z.audit_rn > 200000 AND z.audit_rn <= 100000   ← 同上，空集
--      两个数必须**同时**前进，且始终相差 100000。
--      下界 ＝ 上一批之上界；上界 ＝ 本批之上界。
WHERE z.audit_rn > 0 AND z.audit_rn <= 100000 -- ★ HF9c 本批区间
ORDER BY z.audit_rn;


-- ══════════════════════════════════════════════════════════════════════════════════════════════
-- 104. VB_41c1_964_detail.csv   [总包行 10939~10970 · 原 22 列 ＋六层约 60 列]
--     典型学：M05 退水套利　派生旗标：hiturn（s.x_valid > s.x_stake · 仅供 CASE 条件聚合，全包无任何 WHERE/AND/HAVING 以此过滤）　连接：q.`member_id`
-- ══════════════════════════════════════════════════════════════════════════════════════════════
-- ── ① 先跑 T_true 留档（不足 100000 者一次导全，不必分批）──
-- ── ① T_true：HF9c 不再强制预跑完整 COUNT。
--    本批实际返回行数 < 100000 即判定为末批；全批完成后以各批 n_rows / audit_rn 范围核对总量。

-- ── ② 分批取数：第 1 批。第 k 批只改末行两数为 (k-1)*100000 与 k*100000 ──
--    审计字段二（REDTEAM 2026-08-24 裁定 · 四锁）：
--      audit_rn  全局观测坐标 —— 由**与原版审计版逐字同一**之排序键所生，两版可逐行对账
--      batch_id  物理分批信息 —— 该行所属批次，由 audit_rn 算得，非引擎所赋
--    ★ 锁三：二者皆为审计字段，**不得进入任何业务指标计算**。
--    ★ 锁四：两版经 audit_rn 逐行字段核验后，方可宣布输出完全一致。

-- ── ③ 每批取回后自证四数（任一不符即停手回报，禁止放行）──
--    n_rows        = COUNT(*)      须等于 COUNT(DISTINCT audit_rn)   （批内无重复）
--    audit_rn_min  = MIN(audit_rn) 须等于 (k-1)*100000 + 1           （与上批严丝合缝）
--    audit_rn_max  = MAX(audit_rn) 须等于 min + n_rows - 1           （批内无缺口）
--    全批取毕再验：各批 audit_rn 之并集 = 1 .. T_true，无缺号、无重号。
--     ★ 首行＝平台真净亏最多者（已扣退水与代理占成）。
--
SELECT z.*,
       CAST(FLOOR((z.audit_rn - 1) / 100000) + 1 AS INT)          AS batch_id,
       'A168_HF9F_20260827_0900' AS run_id,
       '2026-08-27 09:00:00' AS snapshot_sync_time
FROM (
  SELECT y.*,
         ROW_NUMBER() OVER (ORDER BY y.`residual_b` ASC, y.`roi` DESC, y.`grp`, y.`bet01`, y.`member_id`, y.`dt`, y.`bet_time`, y.`table_id`, y.`shoe_id`, y.`bet09`, y.`commission`, y.`category`, y.`rebet_flag`, y.`agent_lv1`, y.`stake_raw`, y.`fx_rate`, y.`payout_raw`, y.`rebate_raw`, y.`net_raw`, y.`bet41`, y.`validbet`, y.`diff_vb_minus_b41`, y.`updatetime`, y.`sync_time`) AS audit_rn
  FROM (
    WITH
      x_ranked AS (
    SELECT b.bet01, b.bet03, b.bet04, b.bet05, b.bet09, b.bet11, b.bet13,
           b.bet15, b.bet16, b.bet17, b.bet18, b.bet19, b.bet20, b.bet21,
           b.bet22, b.bet23, b.bet24, b.bet25, b.bet26, b.bet27, b.bet38, b.bet39, b.category, b.commission,
           b.dt, b.eid, b.ip, b.validbet, b.updatetime, b.sync_time,
           ROW_NUMBER() OVER (
             PARTITION BY b.bet01
             ORDER BY b.updatetime DESC, b.sync_time DESC, b.dt DESC)      AS x_rn
    FROM ods_mariadb_2b.ods_a168_bet02 b
    WHERE b.dt >= '2026-03-21' AND b.dt < '2026-08-07'
      AND b.bet02 = '101'
      AND b.sync_time <= '2026-08-27 09:00:00'
  ),
    x_testagent AS (
    SELECT age001 AS agent_id FROM ods_mariadb_2b.ods_a168_agent WHERE age022 = '1'
  ),
    x_bs0 AS (
    SELECT b.bet05 AS x_member, b.eid AS x_dealer, b.bet39 AS x_table,
           b.bet03 AS x_shoe, b.ip AS x_ip, b.bet09 AS x_product, b.dt AS x_date,
           CONCAT_WS('|', b.bet03, b.bet04, b.bet39)                      AS x_round,
           CONCAT_WS('|', b.bet39, b.bet03)                               AS x_tblshoe,
           CAST(NULLIF(TRIM(b.bet04),'') AS INT)                          AS x_rno,
           CASE WHEN b.dt >= '2026-07-08' THEN 1 ELSE 0 END               AS x_rec,
           CASE WHEN TRIM(b.commission)='1' THEN 1 ELSE 0 END             AS x_freecomm,
           CAST(NULLIF(TRIM(b.bet13),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_stake,
           CAST(NULLIF(TRIM(b.validbet),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_valid,
           CAST(NULLIF(TRIM(b.bet16),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_rebate,
           CAST(NULLIF(TRIM(b.bet17),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_net,
           CAST(NULLIF(TRIM(b.bet15),'') AS DECIMAL(20,6))                AS x_rbpct,
           COALESCE(CAST(NULLIF(TRIM(b.bet23),'') AS DECIMAL(20,6)),0)   AS x_agpct,
          NULLIF(CAST(NULLIF(TRIM(b.bet23),'') AS DECIMAL(20,6)),0)     AS x_rate1,
          NULLIF(CAST(NULLIF(TRIM(b.bet24),'') AS DECIMAL(20,6)),0)     AS x_rate2,
          NULLIF(CAST(NULLIF(TRIM(b.bet25),'') AS DECIMAL(20,6)),0)     AS x_rate3,
          NULLIF(CAST(NULLIF(TRIM(b.bet26),'') AS DECIMAL(20,6)),0)     AS x_rate4,
          NULLIF(CAST(NULLIF(TRIM(b.bet27),'') AS DECIMAL(20,6)),0)     AS x_rate5,
          (CASE WHEN NULLIF(CAST(NULLIF(TRIM(b.bet22),'') AS BIGINT),0) IS NOT NULL THEN 5
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet21),'') AS BIGINT),0) IS NOT NULL THEN 4
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet20),'') AS BIGINT),0) IS NOT NULL THEN 3
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet19),'') AS BIGINT),0) IS NOT NULL THEN 2
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet18),'') AS BIGINT),0) IS NOT NULL THEN 1
                ELSE 0 END)                                             AS x_chain_depth,
           CASE WHEN COALESCE(t1.agent_id,t2.agent_id,t3.agent_id,
                              t4.agent_id,t5.agent_id) IS NOT NULL
                THEN 1 ELSE 0 END                                        AS f_testline
    FROM x_ranked b
    LEFT JOIN x_testagent t1 ON t1.agent_id = b.bet18
    LEFT JOIN x_testagent t2 ON t2.agent_id = b.bet19
    LEFT JOIN x_testagent t3 ON t3.agent_id = b.bet20
    LEFT JOIN x_testagent t4 ON t4.agent_id = b.bet21
    LEFT JOIN x_testagent t5 ON t5.agent_id = b.bet22
    WHERE b.x_rn = 1
      AND b.category='1' AND UPPER(TRIM(b.bet38))='N'
      AND CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8)) > 0
  ),
  x_mk AS (
    SELECT s.*,
           CASE WHEN s.f_testline = 0 THEN 1 ELSE 0 END                 AS is_clean
    FROM x_bs0 s
  ),
  x_agg AS (
    SELECT s.x_member                                                        AS x_key,
           COUNT(*) AS n_bets, COUNT(DISTINCT s.x_round) AS n_rounds,
           COUNT(DISTINCT s.x_date) AS active_days, COUNT(DISTINCT s.x_tblshoe) AS active_shoes,
           COUNT(DISTINCT CONCAT_WS('|', s.x_date, s.x_table)) AS active_sessions,
           COUNT(DISTINCT s.x_table) AS n_tables, COUNT(DISTINCT s.x_dealer) AS n_dealers,
           COUNT(DISTINCT s.x_ip) AS n_ips, COUNT(DISTINCT s.x_product) AS n_products,
           MIN(s.x_date) AS first_seen_d, MAX(s.x_date) AS last_seen_d,
           SUM(s.x_stake) AS stake, SUM(s.x_valid) AS valid, SUM(s.x_rebate) AS rebate,
           SUM(s.x_net) AS net, SUM(-s.x_net *(100.0-s.x_agpct)/100.0) AS agent_cost,
           AVG(100.0-s.x_agpct)                   AS agent_pct,
           AVG(s.x_agpct)                         AS company_retain_pct,
           SUM(-s.x_net *s.x_agpct/100.0)         AS agent_cost_a_legacy,
           SUM(s.x_valid*s.x_agpct/100.0)         AS agent_cost_valid_base_legacy,
          AVG(COALESCE(s.x_rate1,100)) AS retain_pct_lv1, AVG(COALESCE(s.x_rate2,100)) AS retain_pct_lv2,
          AVG(COALESCE(s.x_rate3,100)) AS retain_pct_lv3, AVG(COALESCE(s.x_rate4,100)) AS retain_pct_lv4,
          AVG(COALESCE(s.x_rate5,100)) AS retain_pct_lv5, AVG(s.x_chain_depth) AS chain_depth_avg,
          AVG(COALESCE(100.0-s.x_rate1,0)) AS agent_pct_lv1, AVG(COALESCE(100.0-s.x_rate2,0)) AS agent_pct_lv2,
          AVG(COALESCE(100.0-s.x_rate3,0)) AS agent_pct_lv3, AVG(COALESCE(100.0-s.x_rate4,0)) AS agent_pct_lv4,
          AVG(COALESCE(100.0-s.x_rate5,0)) AS agent_pct_lv5,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate1,0)/100.0)                        AS agent_cost_lv1,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate2,0)/100.0)                        AS agent_cost_lv2,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate3,0)/100.0)                        AS agent_cost_lv3,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate4,0)/100.0)                        AS agent_cost_lv4,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate5,0)/100.0)                        AS agent_cost_lv5,
          SUM(-s.x_net*(COALESCE(100.0-s.x_rate1,0)+COALESCE(100.0-s.x_rate2,0)
                       +COALESCE(100.0-s.x_rate3,0)+COALESCE(100.0-s.x_rate4,0)
                       +COALESCE(100.0-s.x_rate5,0))/100.0)                   AS agent_cost_chain_additive,
          SUM(-s.x_net*(1.0 - CAST(COALESCE(s.x_rate1,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate2,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate3,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate4,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate5,100) AS DOUBLE)/100.0))
                                                                       AS agent_cost_chain_nested,
           AVG(s.x_rbpct) AS rbpct, AVG(s.x_freecomm*1.0) AS freecomm_rate,
           PERCENTILE_APPROX(s.x_stake,0.25) AS p25, PERCENTILE_APPROX(s.x_stake,0.50) AS p50,
           PERCENTILE_APPROX(s.x_stake,0.75) AS p75, PERCENTILE_APPROX(s.x_stake,0.90) AS p90,
           PERCENTILE_APPROX(s.x_stake,0.95) AS p95, PERCENTILE_APPROX(s.x_stake,0.99) AS p99,
           PERCENTILE_APPROX(s.x_valid,0.50) AS p50_valid,
           PERCENTILE_APPROX(s.x_net,0.50)   AS p50_profit,
           SUM(CASE WHEN s.x_valid > s.x_stake THEN s.x_stake ELSE 0 END) AS st_in,
           SUM(CASE WHEN s.x_valid > s.x_stake THEN 1 ELSE 0 END)         AS nb_in,
           SUM(CASE WHEN s.x_valid > s.x_stake THEN s.x_net ELSE 0 END)   AS net_in,
           SUM(CASE WHEN NOT (s.x_valid > s.x_stake) THEN s.x_stake ELSE 0 END) AS st_out,
           SUM(CASE WHEN NOT (s.x_valid > s.x_stake) THEN 1 ELSE 0 END)         AS nb_out,
           SUM(CASE WHEN NOT (s.x_valid > s.x_stake) THEN s.x_net ELSE 0 END)   AS net_out,
           SUM(CASE WHEN s.x_rec=1 THEN s.x_stake ELSE 0 END) AS st_rec,
           SUM(CASE WHEN s.x_rec=1 THEN 1 ELSE 0 END)         AS nb_rec
    FROM x_mk s
    WHERE s.is_clean = 1
      AND s.x_member IS NOT NULL AND TRIM(CAST(s.x_member AS STRING)) <> ''
    GROUP BY s.x_member
  ),
      q AS (
        SELECT                                                                                              -- 取列：起始取列子句
          CASE WHEN TRIM(bet09) IN ('Bear8', 'Lucky7TwoCard', 'SmallTiger',
                                    'SuperTie4', 'SuperTie5', 'SuperTie8', 'SuperTie9')
               THEN 'B_上线测试型' ELSE 'A_主群' END                                AS grp,                    -- 条件取值：★ 证据分群，承锁二十六
          TRIM(bet01)                                                            AS bet01,                  -- 取列：注单唯一键
          TRIM(bet05)                                                            AS member_id,              -- 取列：会员编号
          dt                                                                     AS dt,                     -- 取列：分区日
          TRIM(bet08)                                                            AS bet_time,               -- 取列：投注时间
          TRIM(bet39)                                                            AS table_id,               -- 取列：桌号
          TRIM(bet03)                                                            AS shoe_id,                -- 取列：靴号
          TRIM(bet09)                                                            AS bet09,                  -- 取列：注型
          TRIM(commission)                                                       AS commission,             -- 取列：佣金标记
          TRIM(category)                                                         AS category,               -- 取列：注单类别
          TRIM(bet38)                                                            AS rebet_flag,             -- 取列：重对标记
          TRIM(bet18)                                                            AS agent_lv1,              -- 取列：一级代理——判是否测试线
          CAST(NULLIF(TRIM(bet13), '') AS DECIMAL(20,8))                         AS stake_raw,              -- 取列：本金（原币）
          CAST(NULLIF(TRIM(bet11), '') AS DECIMAL(20,8))                         AS fx_rate,                -- 取列：汇率
          CAST(NULLIF(TRIM(bet14), '') AS DECIMAL(20,8))                         AS payout_raw,             -- 取列：派彩（原币）
          CAST(NULLIF(TRIM(bet16), '') AS DECIMAL(20,8))                         AS rebate_raw,             -- 取列：退水（原币）
          CAST(NULLIF(TRIM(bet17), '') AS DECIMAL(20,8))                         AS net_raw,                -- 取列：会员净额（原币）
          CAST(NULLIF(TRIM(bet41), '') AS DECIMAL(20,8))                         AS bet41,                  -- 取列：★ 恒为 0
          CAST(NULLIF(TRIM(validbet), '') AS DECIMAL(20,8))                      AS validbet,               -- 取列：★ 恒为正
          CAST(NULLIF(TRIM(validbet), '') AS DECIMAL(20,8))
            - CAST(NULLIF(TRIM(bet41), '') AS DECIMAL(20,8))                     AS diff_vb_minus_b41,      -- 取值表达式：★ 缺失额 ＝ validbet − bet41
          TRIM(updatetime)                                                       AS updatetime,             -- 取列：★ 更新时间——判是否结算后方写入（候选成因③）
          TRIM(sync_time)                                                        AS sync_time               -- 取列：★ 同步时间——判是否 ETL 环节所致（候选成因⑤）
        FROM ods_mariadb_2b.ods_a168_bet02                                                                  -- 取数来源：取自注单主表
        WHERE dt >= '2026-03-21' AND dt < '2026-08-07'                                                      -- 过滤条件：限定分析窗
          AND sync_time <= '2026-08-27 09:00:00'
          AND CAST(bet02 AS STRING) = '101'                                                                 -- 并列条件：限定百家乐
          AND CAST(NULLIF(TRIM(bet41), '')    AS DECIMAL(20,8)) = 0                                         -- 并列条件：★ bet41 恰为零
          AND CAST(NULLIF(TRIM(validbet), '') AS DECIMAL(20,8)) > 0                                         -- 并列条件：★ validbet 为正
      )
    SELECT q.*,
           -- 一·经济层
           ROUND(e.stake,4) AS stake, ROUND(e.valid,4) AS valid_bet,
           ROUND(-e.net,4) AS profit, e.n_bets, e.n_rounds,
           ROUND(e.net/NULLIF(e.stake,0),8) AS roi,
           ROUND(e.net_in/NULLIF(e.st_in,0),8) AS roi_hiturn,
           ROUND(e.net_out/NULLIF(e.st_out,0),8) AS roi_non_hiturn,
           ROUND((e.net-e.rebate)/NULLIF(e.stake,0),8) AS roi_ex_rebate,
           ROUND(e.net,4) AS roi_numerator, ROUND(e.stake,4) AS roi_denominator,
           CASE WHEN e.stake IS NULL THEN 'NULL_DENOM' WHEN e.stake<=0 THEN 'ZERO_DENOM'
                WHEN e.n_bets<30 THEN 'THIN_EXPOSURE' ELSE 'OK' END AS roi_denominator_status,
           ROUND(e.rebate,4) AS rebate_cost, ROUND(e.agent_cost,4)                           AS cost_complement_b,
       ROUND(e.agent_pct,4)                            AS pct_complement,
       ROUND(e.company_retain_pct,4)                   AS pct_top_bet23,
       'AG03-UNRESOLVED'                                     AS agent_formula_version,
      'ALL5_LEVELS_bet23_to_bet27'                    AS agent_level_scope,
      ROUND(e.agent_cost_lv1,4) AS agent_cost_lv1, ROUND(e.agent_cost_lv2,4) AS agent_cost_lv2,
      ROUND(e.agent_cost_lv3,4) AS agent_cost_lv3, ROUND(e.agent_cost_lv4,4) AS agent_cost_lv4,
      ROUND(e.agent_cost_lv5,4) AS agent_cost_lv5,
      ROUND(e.agent_pct_lv1,6) AS agent_pct_lv1, ROUND(e.agent_pct_lv2,6) AS agent_pct_lv2,
      ROUND(e.agent_pct_lv3,6) AS agent_pct_lv3, ROUND(e.agent_pct_lv4,6) AS agent_pct_lv4,
      ROUND(e.agent_pct_lv5,6) AS agent_pct_lv5,
      ROUND(e.retain_pct_lv1,6) AS retain_pct_lv1, ROUND(e.retain_pct_lv2,6) AS retain_pct_lv2,
      ROUND(e.retain_pct_lv3,6) AS retain_pct_lv3, ROUND(e.retain_pct_lv4,6) AS retain_pct_lv4,
      ROUND(e.retain_pct_lv5,6) AS retain_pct_lv5, ROUND(e.chain_depth_avg,4) AS chain_depth_avg,
      ROUND(e.agent_cost_chain_additive,4)            AS agent_cost_chain_additive,
      ROUND(e.agent_cost_chain_nested,4)              AS agent_cost_chain_nested,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_additive,4) AS residual_chain_additive,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_nested,4)   AS residual_chain_nested,
      'PENDING_AG03'                                  AS decision_status,
      'FALSE'                                         AS admit_to_risk_decision,
      'NOT_FOR_ENFORCEMENT'                           AS deliverable_class,
       ROUND(e.agent_cost_a_legacy,4)                  AS agent_cost_a_legacy,
       ROUND(e.agent_cost_valid_base_legacy,4)         AS agent_cost_valid_base_legacy,
           ROUND(-e.net-e.rebate,4)                        AS ngr,
       ROUND(-e.net-e.rebate-e.agent_cost,4)           AS residual_b,
       ROUND(-e.net-e.rebate-e.agent_cost_a_legacy,4)  AS residual_a,
           ROUND((-e.net-e.rebate)/NULLIF(e.stake,0),8)    AS ngr_rate,
       ROUND((-e.net-e.rebate-e.agent_cost)/NULLIF(e.stake,0),8)   AS residual_b_rate,
      -- 【HF9c · canonical accounting contract】
      --   以下 canonical 字段只增加明确 scope；不删除、不覆盖既有字段。
      --   formal_bet23_* 保持 HF9b 当前生产公式及其 NULL/0 语义；
      --   lv1~lv5 / additive / nested 则分别采用各自原始 e.* 成本字段，
      --   rate 一律从未舍入的 e.* 分子 / e.stake 计算，禁止由展示值反算。
      ROUND(e.agent_cost,4) AS agent_cost_bet23_formal_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost,4) AS net_margin_bet23_formal_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost)/NULLIF(e.stake,0),8) AS net_margin_bet23_formal_rate_canonical,
      ROUND(e.agent_cost_lv1,4) AS agent_cost_lv1_bet23_canonical,
      ROUND(e.agent_cost_lv2,4) AS agent_cost_lv2_bet24_canonical,
      ROUND(e.agent_cost_lv3,4) AS agent_cost_lv3_bet25_canonical,
      ROUND(e.agent_cost_lv4,4) AS agent_cost_lv4_bet26_canonical,
      ROUND(e.agent_cost_lv5,4) AS agent_cost_lv5_bet27_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_lv1,4) AS net_margin_lv1_bet23_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_lv1)/NULLIF(e.stake,0),8) AS net_margin_lv1_bet23_rate_canonical,
      ROUND(e.agent_cost_chain_additive,4) AS agent_cost_chain_additive_canonical,
      ROUND(e.agent_cost_chain_nested,4) AS agent_cost_chain_nested_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_additive,4) AS net_margin_chain_additive_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_nested,4) AS net_margin_chain_nested_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_chain_additive)/NULLIF(e.stake,0),8) AS net_margin_chain_additive_rate_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_chain_nested)/NULLIF(e.stake,0),8) AS net_margin_chain_nested_rate_canonical,
       ROUND((-e.net-e.rebate-e.agent_cost_a_legacy)/NULLIF(e.stake,0),8) AS residual_a_rate,
           -- 二·分布层
           ROUND(e.stake/NULLIF(e.n_bets,0),4) AS avg_stake_per_bet,
           ROUND(e.valid/NULLIF(e.n_rounds,0),4) AS avg_valid_bet_per_round,
           ROUND(-e.net/NULLIF(e.n_rounds,0),4) AS avg_profit_per_round,
           ROUND(-e.net/NULLIF(e.active_days,0),4) AS avg_profit_per_day,
           ROUND(-e.net/NULLIF(e.active_shoes,0),4) AS avg_profit_per_shoe,
           ROUND(e.stake/NULLIF(e.active_days,0),4) AS avg_stake_per_active_day,
           ROUND(e.n_rounds*1.0/NULLIF(e.active_days,0),4) AS avg_rounds_per_active_day,
           ROUND(e.st_in/NULLIF(e.nb_in,0),4) AS avg_stake_hiturn,
           ROUND(e.st_out/NULLIF(e.nb_out,0),4) AS avg_stake_non_hiturn,
           ROUND(e.p25,4) AS p25_stake, ROUND(e.p50,4) AS p50_stake, ROUND(e.p75,4) AS p75_stake,
           ROUND(e.p90,4) AS p90_stake, ROUND(e.p95,4) AS p95_stake, ROUND(e.p99,4) AS p99_stake,
           ROUND(e.p50_valid,4) AS p50_valid_bet, ROUND(e.p50_profit,4) AS p50_profit,
           ROUND(e.p95/NULLIF(e.p50,0),6) AS p95_over_p50,
           ROUND(e.p99/NULLIF(e.p50,0),6) AS p99_over_p50,
           ROUND((e.stake/NULLIF(e.n_bets,0))/NULLIF(e.p50,0),6) AS avg_over_p50,
           -- 三·关系层
           e.n_tables AS common_table_count, e.n_dealers AS common_dealer_count,
           e.n_ips AS common_ip_count, e.n_products AS common_product_count,
           ROUND(e.st_in/NULLIF(e.stake,0),8) AS share_hiturn,
           -- 四·rate 层
           ROUND(-e.net/NULLIF(e.stake,0),8) AS hold_rate,
           ROUND(-e.net_in/NULLIF(e.st_in,0),8) AS hold_rate_hiturn,
           ROUND(e.rebate/NULLIF(e.valid,0),8) AS rebate_rate_actual,
           ROUND(e.rbpct,6) AS rebate_pct_config,
           ROUND(e.valid/NULLIF(e.stake,0),6) AS turnover_multiple,
           ROUND(e.freecomm_rate,6) AS free_comm_rate,
           ROUND(e.net_in/NULLIF(e.st_in,0)-e.net_out/NULLIF(e.st_out,0),8) AS roi_delta_hiturn,
           -- 五·动态层
           e.first_seen_d AS first_seen, e.last_seen_d AS last_seen,
           e.active_days, e.active_shoes, e.active_sessions,
           DATEDIFF(e.last_seen_d, e.first_seen_d)+1 AS span_days,
           ROUND(e.active_days*1.0/NULLIF(DATEDIFF(e.last_seen_d,e.first_seen_d)+1,0),6) AS persistence,
           ROUND((e.st_in/NULLIF(e.nb_in,0))/NULLIF(e.st_out/NULLIF(e.nb_out,0),0),6) AS ramp_hiturn,
           ROUND((e.st_rec/NULLIF(e.nb_rec,0))/NULLIF(e.stake/NULLIF(e.n_bets,0),0),6) AS ramp_recent,
           ROUND((e.st_rec/NULLIF(e.stake,0))/0.30,6) AS stake_ramp,
           -- 六·决策层（HF9f · 详见档头【HF9f 变更说明】；本段两版逐字同一）
           NTILE(5) OVER (ORDER BY e.stake) AS vip_tier,                                                        -- 窗口取值：相对刻度 B 族，全体五等分；须连同下方血统五元组一并解读，禁作硬阈值判型
           PERCENT_RANK() OVER (ORDER BY -e.net-e.rebate-e.agent_cost)    AS economic_value,                    -- 窗口取值：HF9f·F-19 修正 —— HF9e 写作 -(-…) 双负号致方向颠倒（#075 实测 corr(economic_value, residual_b) = -1.0000）；今与 action_priority 排序键归一，值大即平台真净利高
           PERCENT_RANK() OVER (ORDER BY e.net/NULLIF(e.stake,0))         AS roi_pr_global,                     -- 窗口取值：HF9f·F-17 正名 —— 本列实为 ROI（玩家净回报率）之全体百分位，与「风险」无关；旧名 risk_value 见下一行
           PERCENT_RANK() OVER (ORDER BY e.net/NULLIF(e.stake,0))         AS risk_value,                        -- 窗口取值：兼容列，恒等于 roi_pr_global，仅为下游迁移窗保留；HF9g 起废弃，禁新引用
           PERCENT_RANK() OVER (ORDER BY e.stake)                         AS pr_stake,                          -- 窗口取值：兼容列，恒等于 pr_global，原名保留以免断链
           PERCENT_RANK() OVER (ORDER BY e.stake)                         AS pr_global,                         -- 窗口取值：HF9f·F-1 双轨之一 —— 全体口径百分位，参照总体即本件全部输出行
           CASE WHEN e.n_rounds >= 30                                                                           -- 条件分支：起始分支 —— 仅在合格子集内计算合格口径百分位
                  THEN PERCENT_RANK() OVER (PARTITION BY CASE WHEN e.n_rounds >= 30 THEN 1 ELSE 0 END ORDER BY e.stake)  -- 分支取值：以合格与否分区，故本值即 n_rounds>=30 子集内之百分位
                ELSE NULL END                                             AS pr_qualified,                      -- 条件分支：收束上方分支 —— 不合格者留 NULL（NULL＝未测，非 0），产出「pr_qualified」
           'n_rounds>=30'                                                 AS pr_qualified_population,           -- 字面取值：血统 —— 合格子集之定义
           COUNT(*) OVER ()                                               AS pr_global_population_n,            -- 窗口取值：血统 —— 全体口径之参照总体规模，渲染时现算，禁写死
           SUM(CASE WHEN e.n_rounds >= 30 THEN 1 ELSE 0 END) OVER ()      AS pr_qualified_population_n,         -- 窗口取值：血统 —— 合格子集之参照总体规模，现算，禁写死
           'PERCENT_RANK_OVER_ORDER_BY_e_stake'                           AS pr_calculation_method,             -- 字面取值：血统 —— 算法标识
           'HF9f'                                                         AS pr_calculation_version,            -- 字面取值：血统 —— 算法版本
           CASE WHEN e.n_rounds IS NULL OR e.n_rounds < 30 THEN 'THIN_ROUNDS' ELSE 'OK' END AS evidence_flag,   -- 条件分支：HF9f·F-2a 证据旗标 —— THIN_ROUNDS 者禁入执行队列，仅入观察队列
           CASE WHEN e.n_rounds IS NULL       THEN NULL                                                         -- 条件分支：起始分支 —— 未测者留 NULL（自家铁律：NULL ≠ 0）
                WHEN e.n_rounds >= 31483      THEN 'L1_POWERED'                                                 -- 分支判定：MDE 反解第一档
                WHEN e.n_rounds >= 15409      THEN 'L2_CI_1P5'                                                  -- 分支判定：MDE 反解第二档
                WHEN e.n_rounds >=  8668      THEN 'L3_CI_2P0'                                                  -- 分支判定：MDE 反解第三档
                WHEN e.n_rounds >=  3852      THEN 'L4_CI_3P0'                                                  -- 分支判定：MDE 反解第四档
                ELSE 'L5_INSUFFICIENT' END                                AS evidence_rate,                     -- 条件分支：收束上方 —— HF9f·F-3 证据分档，承 HF9e 前议之 MDE 反解五档，须于 F-4 敏感性实验后复核
           ROUND(1.96 * 0.95 / SQRT(NULLIF(CAST(e.n_rounds AS DOUBLE),0)),8) AS hold_ci_halfwidth_approx,       -- 比率表达式：HF9f·F-3 逐行现算之 95% 半宽近似；常数 0.95 为登记值，本轮 #075 实测每局 ROI 隐含 σ 于最薄层为 0.9249，二者差异待 F-4 裁定
           CASE WHEN e.stake IS NULL OR e.stake<=0 OR e.n_bets<30 OR e.n_rounds IS NULL OR e.n_rounds<30 THEN 'Z 证据不足 · 不动作'  -- 条件分支：HF9f·F-2 双条件取严 —— HF9e 仅卡 e.n_bets<30，致 n_bets>=30 而 n_rounds<30 者绕过 Z（#075 实测 18,537 名，其中 8,145 名已入 A/D 待裁）；今两条件并列取严
                WHEN PERCENT_RANK() OVER (ORDER BY -e.net-e.rebate-e.agent_cost)<=0.10                          -- 分支判定：平台真净利之最低十分位
                  THEN 'A 净亏最大十分位 · 优先复核'                                                             -- 分支取值：HF9f·F-20 正名 —— 本档 Σresidual_b 于 #075 实测 = -100,236,896，系平台净亏最大群，旧名「残值最低十分位 · 待裁」名实不符
                WHEN PERCENT_RANK() OVER (ORDER BY -e.net-e.rebate-e.agent_cost)>=0.80                          -- 分支判定：平台真净利之最高二十分位
                  THEN 'D 净利最高二十分位 · 优先留存'                                                           -- 分支取值：HF9f·F-20 正名 —— 本档 Σresidual_b 于 #075 实测 = +281,733,190，系核心利润源；与 A 档方向相反，旧版同标「待裁」属名实不符
                ELSE 'E 常规' END                                          AS action_priority                   -- 条件分支：收束上方判词，产出「action_priority」
    FROM q
    LEFT JOIN x_agg e ON CAST(e.x_key AS STRING) = CAST(q.`member_id` AS STRING)
  ) y
) z
-- ── 逐批 WHERE 阶梯（★ 口诀：上界 ＝ 下界 ＋ 100000，两数同进）──
--    本件 T_true 未测，无需先跑 T_true；以 0 / 100000 控制本批返回区间，末批由实际行数 < 100000 判定
--    WHERE z.audit_rn >        0 AND z.audit_rn <=   100000   -- 第 1 批
--    WHERE z.audit_rn >   100000 AND z.audit_rn <=   200000   -- 第 2 批
--    WHERE z.audit_rn >   200000 AND z.audit_rn <=   300000   -- 第 3 批
--    WHERE z.audit_rn >   300000 AND z.audit_rn <=   400000   -- 第 4 批
--    WHERE z.audit_rn >   400000 AND z.audit_rn <=   500000   -- 第 5 批
--    WHERE z.audit_rn >   500000 AND z.audit_rn <=   600000   -- 第 6 批
--    WHERE z.audit_rn >   600000 AND z.audit_rn <=   700000   -- 第 7 批
--    …余批类推。第 k 批：WHERE z.audit_rn > (k-1)*100000 AND z.audit_rn <= k*100000
--    某批返回 < 100000 行即为末批，其后不再取。
--
--    ⚠ 常见误写（务必避开）：只推下界而上界不动 ——
--        WHERE z.audit_rn > 100000 AND z.audit_rn <= 100000   ← 自相矛盾，恒为假，返回空集
--        WHERE z.audit_rn > 200000 AND z.audit_rn <= 100000   ← 同上，空集
--      两个数必须**同时**前进，且始终相差 100000。
--      下界 ＝ 上一批之上界；上界 ＝ 本批之上界。
WHERE z.audit_rn > 0 AND z.audit_rn <= 100000 -- ★ HF9c 本批区间
ORDER BY z.audit_rn;


-- ══════════════════════════════════════════════════════════════════════════════════════════════
-- 105. VB_41c2_concentration.csv   [总包行 10982~11045 · 原 20 列 ＋六层约 60 列]
--     典型学：M05 退水套利　派生旗标：hiturn（s.x_valid > s.x_stake · 仅供 CASE 条件聚合，全包无任何 WHERE/AND/HAVING 以此过滤）　连接：全窗基线
-- ══════════════════════════════════════════════════════════════════════════════════════════════
-- ★ W-64 · D-14 警示（本件属 x_win 族 · 66 件之一 · 详见 §Z 段 D-14 全案）
--   本件以 `CROSS JOIN x_win e` 接入全局基线，x_win 无 GROUP BY ⇒ 恒 1 行 ⇒ e.* 全行同值。
--   故：economic_value / roi_pr_global / risk_value / pr_stake / pr_global 恒为 0；
--       action_priority 每一行皆为「A 净亏最大十分位 · 优先复核」（Z 分支永不触发）；
--       evidence_rate 恒为最高档；vip_tier 由常数键分档 ⇒ 无信息且非确定。
--   ⇒ 本件决策层三列 **NOT_FOR_DECISION**，裁定前不得用于排班、抽查或汇报。
-- ── ① 先跑 T_true 留档（不足 100000 者一次导全，不必分批）──
-- ── ① T_true：HF9c 不再强制预跑完整 COUNT。
--    本批实际返回行数 < 100000 即判定为末批；全批完成后以各批 n_rows / audit_rn 范围核对总量。

-- ── ② 分批取数：第 1 批。第 k 批只改末行两数为 (k-1)*100000 与 k*100000 ──
--    审计字段二（REDTEAM 2026-08-24 裁定 · 四锁）：
--      audit_rn  全局观测坐标 —— 由**与原版审计版逐字同一**之排序键所生，两版可逐行对账
--      batch_id  物理分批信息 —— 该行所属批次，由 audit_rn 算得，非引擎所赋
--    ★ 锁三：二者皆为审计字段，**不得进入任何业务指标计算**。
--    ★ 锁四：两版经 audit_rn 逐行字段核验后，方可宣布输出完全一致。

-- ── ③ 每批取回后自证四数（任一不符即停手回报，禁止放行）──
--    n_rows        = COUNT(*)      须等于 COUNT(DISTINCT audit_rn)   （批内无重复）
--    audit_rn_min  = MIN(audit_rn) 须等于 (k-1)*100000 + 1           （与上批严丝合缝）
--    audit_rn_max  = MAX(audit_rn) 须等于 min + n_rows - 1           （批内无缺口）
--    全批取毕再验：各批 audit_rn 之并集 = 1 .. T_true，无缺号、无重号。
--     ★ 首行＝平台真净亏最多者（已扣退水与代理占成）。
--
SELECT z.*,
       CAST(FLOOR((z.audit_rn - 1) / 100000) + 1 AS INT)          AS batch_id,
       'A168_HF9F_20260827_0900' AS run_id,
       '2026-08-27 09:00:00' AS snapshot_sync_time
FROM (
  SELECT y.*,
         ROW_NUMBER() OVER (ORDER BY y.`residual_b` ASC, y.`roi` DESC, y.`grp`, y.`n_rows`, y.`n_members`, y.`top1_member_share_pct`, y.`top1_member_n`, y.`max_member_diff_sum`, y.`n_dates`, y.`min_date`, y.`max_date`, y.`top_date_n`, y.`top_date_share_pct`, y.`n_tables`, y.`top_table_share_pct`, y.`n_bet09`, y.`n_commission`, y.`sum_stake`, y.`sum_validbet`, y.`min_stake`, y.`max_stake`, y.`verdict_concentration`) AS audit_rn
  FROM (
    WITH
      x_ranked AS (
    SELECT b.bet01, b.bet03, b.bet04, b.bet05, b.bet09, b.bet11, b.bet13,
           b.bet15, b.bet16, b.bet17, b.bet18, b.bet19, b.bet20, b.bet21,
           b.bet22, b.bet23, b.bet24, b.bet25, b.bet26, b.bet27, b.bet38, b.bet39, b.category, b.commission,
           b.dt, b.eid, b.ip, b.validbet, b.updatetime, b.sync_time,
           ROW_NUMBER() OVER (
             PARTITION BY b.bet01
             ORDER BY b.updatetime DESC, b.sync_time DESC, b.dt DESC)      AS x_rn
    FROM ods_mariadb_2b.ods_a168_bet02 b
    WHERE b.dt >= '2026-03-21' AND b.dt < '2026-08-07'
      AND b.bet02 = '101'
      AND b.sync_time <= '2026-08-27 09:00:00'
  ),
    x_testagent AS (
    SELECT age001 AS agent_id FROM ods_mariadb_2b.ods_a168_agent WHERE age022 = '1'
  ),
    x_bs0 AS (
    SELECT b.bet05 AS x_member, b.eid AS x_dealer, b.bet39 AS x_table,
           b.bet03 AS x_shoe, b.ip AS x_ip, b.bet09 AS x_product, b.dt AS x_date,
           CONCAT_WS('|', b.bet03, b.bet04, b.bet39)                      AS x_round,
           CONCAT_WS('|', b.bet39, b.bet03)                               AS x_tblshoe,
           CAST(NULLIF(TRIM(b.bet04),'') AS INT)                          AS x_rno,
           CASE WHEN b.dt >= '2026-07-08' THEN 1 ELSE 0 END               AS x_rec,
           CASE WHEN TRIM(b.commission)='1' THEN 1 ELSE 0 END             AS x_freecomm,
           CAST(NULLIF(TRIM(b.bet13),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_stake,
           CAST(NULLIF(TRIM(b.validbet),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_valid,
           CAST(NULLIF(TRIM(b.bet16),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_rebate,
           CAST(NULLIF(TRIM(b.bet17),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_net,
           CAST(NULLIF(TRIM(b.bet15),'') AS DECIMAL(20,6))                AS x_rbpct,
           COALESCE(CAST(NULLIF(TRIM(b.bet23),'') AS DECIMAL(20,6)),0)   AS x_agpct,
          NULLIF(CAST(NULLIF(TRIM(b.bet23),'') AS DECIMAL(20,6)),0)     AS x_rate1,
          NULLIF(CAST(NULLIF(TRIM(b.bet24),'') AS DECIMAL(20,6)),0)     AS x_rate2,
          NULLIF(CAST(NULLIF(TRIM(b.bet25),'') AS DECIMAL(20,6)),0)     AS x_rate3,
          NULLIF(CAST(NULLIF(TRIM(b.bet26),'') AS DECIMAL(20,6)),0)     AS x_rate4,
          NULLIF(CAST(NULLIF(TRIM(b.bet27),'') AS DECIMAL(20,6)),0)     AS x_rate5,
          (CASE WHEN NULLIF(CAST(NULLIF(TRIM(b.bet22),'') AS BIGINT),0) IS NOT NULL THEN 5
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet21),'') AS BIGINT),0) IS NOT NULL THEN 4
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet20),'') AS BIGINT),0) IS NOT NULL THEN 3
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet19),'') AS BIGINT),0) IS NOT NULL THEN 2
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet18),'') AS BIGINT),0) IS NOT NULL THEN 1
                ELSE 0 END)                                             AS x_chain_depth,
           CASE WHEN COALESCE(t1.agent_id,t2.agent_id,t3.agent_id,
                              t4.agent_id,t5.agent_id) IS NOT NULL
                THEN 1 ELSE 0 END                                        AS f_testline
    FROM x_ranked b
    LEFT JOIN x_testagent t1 ON t1.agent_id = b.bet18
    LEFT JOIN x_testagent t2 ON t2.agent_id = b.bet19
    LEFT JOIN x_testagent t3 ON t3.agent_id = b.bet20
    LEFT JOIN x_testagent t4 ON t4.agent_id = b.bet21
    LEFT JOIN x_testagent t5 ON t5.agent_id = b.bet22
    WHERE b.x_rn = 1
      AND b.category='1' AND UPPER(TRIM(b.bet38))='N'
      AND CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8)) > 0
  ),
  x_mk AS (
    SELECT s.*,
           CASE WHEN s.f_testline = 0 THEN 1 ELSE 0 END                 AS is_clean
    FROM x_bs0 s
  ),
  x_agg AS (
    SELECT s.x_member                                                        AS x_key,
           COUNT(*) AS n_bets, COUNT(DISTINCT s.x_round) AS n_rounds,
           COUNT(DISTINCT s.x_date) AS active_days, COUNT(DISTINCT s.x_tblshoe) AS active_shoes,
           COUNT(DISTINCT CONCAT_WS('|', s.x_date, s.x_table)) AS active_sessions,
           COUNT(DISTINCT s.x_table) AS n_tables, COUNT(DISTINCT s.x_dealer) AS n_dealers,
           COUNT(DISTINCT s.x_ip) AS n_ips, COUNT(DISTINCT s.x_product) AS n_products,
           MIN(s.x_date) AS first_seen_d, MAX(s.x_date) AS last_seen_d,
           SUM(s.x_stake) AS stake, SUM(s.x_valid) AS valid, SUM(s.x_rebate) AS rebate,
           SUM(s.x_net) AS net, SUM(-s.x_net *(100.0-s.x_agpct)/100.0) AS agent_cost,
           AVG(100.0-s.x_agpct)                   AS agent_pct,
           AVG(s.x_agpct)                         AS company_retain_pct,
           SUM(-s.x_net *s.x_agpct/100.0)         AS agent_cost_a_legacy,
           SUM(s.x_valid*s.x_agpct/100.0)         AS agent_cost_valid_base_legacy,
          AVG(COALESCE(s.x_rate1,100)) AS retain_pct_lv1, AVG(COALESCE(s.x_rate2,100)) AS retain_pct_lv2,
          AVG(COALESCE(s.x_rate3,100)) AS retain_pct_lv3, AVG(COALESCE(s.x_rate4,100)) AS retain_pct_lv4,
          AVG(COALESCE(s.x_rate5,100)) AS retain_pct_lv5, AVG(s.x_chain_depth) AS chain_depth_avg,
          AVG(COALESCE(100.0-s.x_rate1,0)) AS agent_pct_lv1, AVG(COALESCE(100.0-s.x_rate2,0)) AS agent_pct_lv2,
          AVG(COALESCE(100.0-s.x_rate3,0)) AS agent_pct_lv3, AVG(COALESCE(100.0-s.x_rate4,0)) AS agent_pct_lv4,
          AVG(COALESCE(100.0-s.x_rate5,0)) AS agent_pct_lv5,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate1,0)/100.0)                        AS agent_cost_lv1,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate2,0)/100.0)                        AS agent_cost_lv2,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate3,0)/100.0)                        AS agent_cost_lv3,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate4,0)/100.0)                        AS agent_cost_lv4,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate5,0)/100.0)                        AS agent_cost_lv5,
          SUM(-s.x_net*(COALESCE(100.0-s.x_rate1,0)+COALESCE(100.0-s.x_rate2,0)
                       +COALESCE(100.0-s.x_rate3,0)+COALESCE(100.0-s.x_rate4,0)
                       +COALESCE(100.0-s.x_rate5,0))/100.0)                   AS agent_cost_chain_additive,
          SUM(-s.x_net*(1.0 - CAST(COALESCE(s.x_rate1,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate2,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate3,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate4,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate5,100) AS DOUBLE)/100.0))
                                                                       AS agent_cost_chain_nested,
           AVG(s.x_rbpct) AS rbpct, AVG(s.x_freecomm*1.0) AS freecomm_rate,
           PERCENTILE_APPROX(s.x_stake,0.25) AS p25, PERCENTILE_APPROX(s.x_stake,0.50) AS p50,
           PERCENTILE_APPROX(s.x_stake,0.75) AS p75, PERCENTILE_APPROX(s.x_stake,0.90) AS p90,
           PERCENTILE_APPROX(s.x_stake,0.95) AS p95, PERCENTILE_APPROX(s.x_stake,0.99) AS p99,
           PERCENTILE_APPROX(s.x_valid,0.50) AS p50_valid,
           PERCENTILE_APPROX(s.x_net,0.50)   AS p50_profit,
           SUM(CASE WHEN s.x_valid > s.x_stake THEN s.x_stake ELSE 0 END) AS st_in,
           SUM(CASE WHEN s.x_valid > s.x_stake THEN 1 ELSE 0 END)         AS nb_in,
           SUM(CASE WHEN s.x_valid > s.x_stake THEN s.x_net ELSE 0 END)   AS net_in,
           SUM(CASE WHEN NOT (s.x_valid > s.x_stake) THEN s.x_stake ELSE 0 END) AS st_out,
           SUM(CASE WHEN NOT (s.x_valid > s.x_stake) THEN 1 ELSE 0 END)         AS nb_out,
           SUM(CASE WHEN NOT (s.x_valid > s.x_stake) THEN s.x_net ELSE 0 END)   AS net_out,
           SUM(CASE WHEN s.x_rec=1 THEN s.x_stake ELSE 0 END) AS st_rec,
           SUM(CASE WHEN s.x_rec=1 THEN 1 ELSE 0 END)         AS nb_rec
    FROM x_mk s
    WHERE s.is_clean = 1
      AND s.x_member IS NOT NULL AND TRIM(CAST(s.x_member AS STRING)) <> ''
    GROUP BY s.x_member
  ),
  x_win AS (
    SELECT            COUNT(*) AS n_bets, COUNT(DISTINCT s.x_round) AS n_rounds,
           COUNT(DISTINCT s.x_date) AS active_days, COUNT(DISTINCT s.x_tblshoe) AS active_shoes,
           COUNT(DISTINCT CONCAT_WS('|', s.x_date, s.x_table)) AS active_sessions,
           COUNT(DISTINCT s.x_table) AS n_tables, COUNT(DISTINCT s.x_dealer) AS n_dealers,
           COUNT(DISTINCT s.x_ip) AS n_ips, COUNT(DISTINCT s.x_product) AS n_products,
           MIN(s.x_date) AS first_seen_d, MAX(s.x_date) AS last_seen_d,
           SUM(s.x_stake) AS stake, SUM(s.x_valid) AS valid, SUM(s.x_rebate) AS rebate,
           SUM(s.x_net) AS net, SUM(-s.x_net *(100.0-s.x_agpct)/100.0) AS agent_cost,
           AVG(100.0-s.x_agpct)                   AS agent_pct,
           AVG(s.x_agpct)                         AS company_retain_pct,
           SUM(-s.x_net *s.x_agpct/100.0)         AS agent_cost_a_legacy,
           SUM(s.x_valid*s.x_agpct/100.0)         AS agent_cost_valid_base_legacy,
          AVG(COALESCE(s.x_rate1,100)) AS retain_pct_lv1, AVG(COALESCE(s.x_rate2,100)) AS retain_pct_lv2,
          AVG(COALESCE(s.x_rate3,100)) AS retain_pct_lv3, AVG(COALESCE(s.x_rate4,100)) AS retain_pct_lv4,
          AVG(COALESCE(s.x_rate5,100)) AS retain_pct_lv5, AVG(s.x_chain_depth) AS chain_depth_avg,
          AVG(COALESCE(100.0-s.x_rate1,0)) AS agent_pct_lv1, AVG(COALESCE(100.0-s.x_rate2,0)) AS agent_pct_lv2,
          AVG(COALESCE(100.0-s.x_rate3,0)) AS agent_pct_lv3, AVG(COALESCE(100.0-s.x_rate4,0)) AS agent_pct_lv4,
          AVG(COALESCE(100.0-s.x_rate5,0)) AS agent_pct_lv5,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate1,0)/100.0)                        AS agent_cost_lv1,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate2,0)/100.0)                        AS agent_cost_lv2,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate3,0)/100.0)                        AS agent_cost_lv3,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate4,0)/100.0)                        AS agent_cost_lv4,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate5,0)/100.0)                        AS agent_cost_lv5,
          SUM(-s.x_net*(COALESCE(100.0-s.x_rate1,0)+COALESCE(100.0-s.x_rate2,0)
                       +COALESCE(100.0-s.x_rate3,0)+COALESCE(100.0-s.x_rate4,0)
                       +COALESCE(100.0-s.x_rate5,0))/100.0)                   AS agent_cost_chain_additive,
          SUM(-s.x_net*(1.0 - CAST(COALESCE(s.x_rate1,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate2,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate3,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate4,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate5,100) AS DOUBLE)/100.0))
                                                                       AS agent_cost_chain_nested,
           AVG(s.x_rbpct) AS rbpct, AVG(s.x_freecomm*1.0) AS freecomm_rate,
           PERCENTILE_APPROX(s.x_stake,0.25) AS p25, PERCENTILE_APPROX(s.x_stake,0.50) AS p50,
           PERCENTILE_APPROX(s.x_stake,0.75) AS p75, PERCENTILE_APPROX(s.x_stake,0.90) AS p90,
           PERCENTILE_APPROX(s.x_stake,0.95) AS p95, PERCENTILE_APPROX(s.x_stake,0.99) AS p99,
           PERCENTILE_APPROX(s.x_valid,0.50) AS p50_valid,
           PERCENTILE_APPROX(s.x_net,0.50)   AS p50_profit,
           SUM(CASE WHEN s.x_valid > s.x_stake THEN s.x_stake ELSE 0 END) AS st_in,
           SUM(CASE WHEN s.x_valid > s.x_stake THEN 1 ELSE 0 END)         AS nb_in,
           SUM(CASE WHEN s.x_valid > s.x_stake THEN s.x_net ELSE 0 END)   AS net_in,
           SUM(CASE WHEN NOT (s.x_valid > s.x_stake) THEN s.x_stake ELSE 0 END) AS st_out,
           SUM(CASE WHEN NOT (s.x_valid > s.x_stake) THEN 1 ELSE 0 END)         AS nb_out,
           SUM(CASE WHEN NOT (s.x_valid > s.x_stake) THEN s.x_net ELSE 0 END)   AS net_out,
           SUM(CASE WHEN s.x_rec=1 THEN s.x_stake ELSE 0 END) AS st_rec,
           SUM(CASE WHEN s.x_rec=1 THEN 1 ELSE 0 END)         AS nb_rec
    FROM x_mk s
    WHERE s.is_clean = 1
      AND s.x_member IS NOT NULL AND TRIM(CAST(s.x_member AS STRING)) <> ''
  ),
      q AS (
        WITH tgt AS (                                                                                       -- 公共表表达式：开启中间结果集 tgt——964 笔之目标集
          SELECT CASE WHEN TRIM(bet09) IN ('Bear8', 'Lucky7TwoCard', 'SmallTiger',
                                           'SuperTie4', 'SuperTie5', 'SuperTie8', 'SuperTie9')
                      THEN 'B_上线测试型' ELSE 'A_主群' END                       AS grp,                    -- 条件取值：证据分群
                 TRIM(bet05)                                                     AS mid,                    -- 取列：会员编号
                 dt                                                              AS dt,                     -- 取列：分区日
                 TRIM(bet04)                                                     AS tbl,                    -- 取列：桌号
                 TRIM(bet09)                                                     AS g9,                     -- 取列：注型
                 TRIM(commission)                                                AS comm,                   -- 取列：佣金标记
                 CAST(NULLIF(TRIM(bet13), '') AS DECIMAL(20,8))                  AS stake,                  -- 取列：本金
                 CAST(NULLIF(TRIM(validbet), '') AS DECIMAL(20,8))               AS vvb                     -- 取列：validbet
          FROM ods_mariadb_2b.ods_a168_bet02                                                                -- 取数来源：取自注单主表
          WHERE dt >= '2026-03-21' AND dt < '2026-08-07'                                                    -- 过滤条件：限定分析窗
            AND sync_time <= '2026-08-27 09:00:00'
            AND CAST(bet02 AS STRING) = '101'                                                               -- 并列条件：限定百家乐
            AND CAST(NULLIF(TRIM(bet41), '')    AS DECIMAL(20,8)) = 0                                       -- 并列条件：bet41 恰为零
            AND CAST(NULLIF(TRIM(validbet), '') AS DECIMAL(20,8)) > 0                                       -- 并列条件：validbet 为正
        ),                                                                                                  -- 续行：收束上方的子查询或函数括号
        by_mid AS (                                                                                         -- 公共表表达式：开启中间结果集 by_mid——逐会员计数
          SELECT grp, mid, COUNT(*) AS n, SUM(vvb) AS s                                                     -- 取列与汇总：会员、笔数、缺失额
          FROM tgt GROUP BY grp, mid                                                                        -- 分组：按群与会员汇总
        ),                                                                                                  -- 续行：收束上方的子查询或函数括号
        by_dt AS (                                                                                          -- 公共表表达式：开启中间结果集 by_dt——逐日计数
          SELECT grp, dt, COUNT(*) AS n FROM tgt GROUP BY grp, dt                                           -- 取列与汇总：群、日、笔数
        ),                                                                                                  -- 续行：收束上方的子查询或函数括号
        by_tbl AS (                                                                                         -- 公共表表达式：开启中间结果集 by_tbl——逐桌计数
          SELECT grp, tbl, COUNT(*) AS n FROM tgt GROUP BY grp, tbl                                         -- 取列与汇总：群、桌、笔数
        )                                                                                                   -- 续行：收束上方的子查询或函数括号
        SELECT                                                                                              -- 取列：起始取列子句
          t.grp                                                                  AS grp,                    -- 取列：证据群
          COUNT(*)                                                               AS n_rows,                 -- 计数表达式：该群笔数
          COUNT(DISTINCT t.mid)                                                  AS n_members,              -- 计数表达式：★ A 维——涉及会员数
          ROUND((SELECT MAX(n) FROM by_mid m WHERE m.grp = t.grp) * 100.0
                / NULLIF(COUNT(*), 0), 4)                                        AS top1_member_share_pct,  -- 比率表达式：★★ 首位会员占比——集中度之判据
          (SELECT MAX(n) FROM by_mid m WHERE m.grp = t.grp)                      AS top1_member_n,          -- 标量子查询：首位会员之笔数
          ROUND((SELECT MAX(s) FROM by_mid m WHERE m.grp = t.grp), 2)            AS max_member_diff_sum,    -- 标量子查询：单一会员之最大缺失额
          COUNT(DISTINCT t.dt)                                                   AS n_dates,                -- 计数表达式：★ B 维——涉及天数（对照全窗 139）
          MIN(t.dt)                                                              AS min_date,               -- 聚合取值：首现日
          MAX(t.dt)                                                              AS max_date,               -- 聚合取值：末现日
          (SELECT MAX(n) FROM by_dt d WHERE d.grp = t.grp)                       AS top_date_n,             -- 标量子查询：单日最多笔数
          ROUND((SELECT MAX(n) FROM by_dt d WHERE d.grp = t.grp) * 100.0
                / NULLIF(COUNT(*), 0), 4)                                        AS top_date_share_pct,     -- 比率表达式：★ 首位日期占比
          COUNT(DISTINCT t.tbl)                                                  AS n_tables,               -- 计数表达式：★ C 维——涉及桌数
          ROUND((SELECT MAX(n) FROM by_tbl b WHERE b.grp = t.grp) * 100.0
                / NULLIF(COUNT(*), 0), 4)                                        AS top_table_share_pct,    -- 比率表达式：首位桌台占比
          COUNT(DISTINCT t.g9)                                                   AS n_bet09,                -- 计数表达式：★ E 维——涉及注型数
          COUNT(DISTINCT t.comm)                                                 AS n_commission,           -- 计数表达式：涉及佣金制数
          ROUND(SUM(t.stake), 2)                                                 AS sum_stake,              -- 汇总表达式：★ D 维——本金总额
          ROUND(SUM(t.vvb), 2)                                                   AS sum_validbet,           -- 汇总表达式：validbet 总额（＝ 缺失额，因 bet41 恒零）
          ROUND(MIN(t.stake), 2)                                                 AS min_stake,              -- 聚合取值：最小本金
          ROUND(MAX(t.stake), 2)                                                 AS max_stake,              -- 聚合取值：最大本金
          CASE                                                                                              -- 条件分支：起始分支——集中度裁定
            WHEN (SELECT MAX(n) FROM by_mid m WHERE m.grp = t.grp) * 1.0
                 / NULLIF(COUNT(*), 0) >= 0.30
              THEN '★ 高度集中于少数会员 —— 属风控线索，须逐会员追'                                             -- 分支判定：会员集中
            WHEN COUNT(DISTINCT t.dt) * 1.0 / 139 >= 0.50
              THEN '◐ 散布全窗过半天数 —— 倾向系统性规则或持续漏记，非单次事件'                                   -- 分支判定：时间散布
            WHEN (SELECT MAX(n) FROM by_dt d WHERE d.grp = t.grp) * 1.0
                 / NULLIF(COUNT(*), 0) >= 0.30
              THEN '◐ 集中于少数日期 —— 须核该期是否有变更、上线或重同步'                                        -- 分支判定：时间集中
            ELSE '◐ 无单一维度显著集中 —— 须并读五维方可判'                                                    -- 分支判定：无显著集中
          END                                                                    AS verdict_concentration   -- 条件分支：收束上方判词，产出「verdict_concentration」
        FROM tgt t                                                                                          -- 取数来源：取自本条自建的中间结果集 tgt
        GROUP BY t.grp                                                                                      -- 分组：按证据群汇总
      )
    SELECT q.*,
           -- 一·经济层
           ROUND(e.stake,4) AS stake, ROUND(e.valid,4) AS valid_bet,
           ROUND(-e.net,4) AS profit, e.n_bets, e.n_rounds,
           ROUND(e.net/NULLIF(e.stake,0),8) AS roi,
           ROUND(e.net_in/NULLIF(e.st_in,0),8) AS roi_hiturn,
           ROUND(e.net_out/NULLIF(e.st_out,0),8) AS roi_non_hiturn,
           ROUND((e.net-e.rebate)/NULLIF(e.stake,0),8) AS roi_ex_rebate,
           ROUND(e.net,4) AS roi_numerator, ROUND(e.stake,4) AS roi_denominator,
           CASE WHEN e.stake IS NULL THEN 'NULL_DENOM' WHEN e.stake<=0 THEN 'ZERO_DENOM'
                WHEN e.n_bets<30 THEN 'THIN_EXPOSURE' ELSE 'OK' END AS roi_denominator_status,
           ROUND(e.rebate,4) AS rebate_cost, ROUND(e.agent_cost,4)                           AS cost_complement_b,
       ROUND(e.agent_pct,4)                            AS pct_complement,
       ROUND(e.company_retain_pct,4)                   AS pct_top_bet23,
       'AG03-UNRESOLVED'                                     AS agent_formula_version,
      'ALL5_LEVELS_bet23_to_bet27'                    AS agent_level_scope,
      ROUND(e.agent_cost_lv1,4) AS agent_cost_lv1, ROUND(e.agent_cost_lv2,4) AS agent_cost_lv2,
      ROUND(e.agent_cost_lv3,4) AS agent_cost_lv3, ROUND(e.agent_cost_lv4,4) AS agent_cost_lv4,
      ROUND(e.agent_cost_lv5,4) AS agent_cost_lv5,
      ROUND(e.agent_pct_lv1,6) AS agent_pct_lv1, ROUND(e.agent_pct_lv2,6) AS agent_pct_lv2,
      ROUND(e.agent_pct_lv3,6) AS agent_pct_lv3, ROUND(e.agent_pct_lv4,6) AS agent_pct_lv4,
      ROUND(e.agent_pct_lv5,6) AS agent_pct_lv5,
      ROUND(e.retain_pct_lv1,6) AS retain_pct_lv1, ROUND(e.retain_pct_lv2,6) AS retain_pct_lv2,
      ROUND(e.retain_pct_lv3,6) AS retain_pct_lv3, ROUND(e.retain_pct_lv4,6) AS retain_pct_lv4,
      ROUND(e.retain_pct_lv5,6) AS retain_pct_lv5, ROUND(e.chain_depth_avg,4) AS chain_depth_avg,
      ROUND(e.agent_cost_chain_additive,4)            AS agent_cost_chain_additive,
      ROUND(e.agent_cost_chain_nested,4)              AS agent_cost_chain_nested,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_additive,4) AS residual_chain_additive,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_nested,4)   AS residual_chain_nested,
      'PENDING_AG03'                                  AS decision_status,
      'FALSE'                                         AS admit_to_risk_decision,
      'NOT_FOR_ENFORCEMENT'                           AS deliverable_class,
       ROUND(e.agent_cost_a_legacy,4)                  AS agent_cost_a_legacy,
       ROUND(e.agent_cost_valid_base_legacy,4)         AS agent_cost_valid_base_legacy,
           ROUND(-e.net-e.rebate,4)                        AS ngr,
       ROUND(-e.net-e.rebate-e.agent_cost,4)           AS residual_b,
       ROUND(-e.net-e.rebate-e.agent_cost_a_legacy,4)  AS residual_a,
           ROUND((-e.net-e.rebate)/NULLIF(e.stake,0),8)    AS ngr_rate,
       ROUND((-e.net-e.rebate-e.agent_cost)/NULLIF(e.stake,0),8)   AS residual_b_rate,
      -- 【HF9c · canonical accounting contract】
      --   以下 canonical 字段只增加明确 scope；不删除、不覆盖既有字段。
      --   formal_bet23_* 保持 HF9b 当前生产公式及其 NULL/0 语义；
      --   lv1~lv5 / additive / nested 则分别采用各自原始 e.* 成本字段，
      --   rate 一律从未舍入的 e.* 分子 / e.stake 计算，禁止由展示值反算。
      ROUND(e.agent_cost,4) AS agent_cost_bet23_formal_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost,4) AS net_margin_bet23_formal_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost)/NULLIF(e.stake,0),8) AS net_margin_bet23_formal_rate_canonical,
      ROUND(e.agent_cost_lv1,4) AS agent_cost_lv1_bet23_canonical,
      ROUND(e.agent_cost_lv2,4) AS agent_cost_lv2_bet24_canonical,
      ROUND(e.agent_cost_lv3,4) AS agent_cost_lv3_bet25_canonical,
      ROUND(e.agent_cost_lv4,4) AS agent_cost_lv4_bet26_canonical,
      ROUND(e.agent_cost_lv5,4) AS agent_cost_lv5_bet27_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_lv1,4) AS net_margin_lv1_bet23_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_lv1)/NULLIF(e.stake,0),8) AS net_margin_lv1_bet23_rate_canonical,
      ROUND(e.agent_cost_chain_additive,4) AS agent_cost_chain_additive_canonical,
      ROUND(e.agent_cost_chain_nested,4) AS agent_cost_chain_nested_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_additive,4) AS net_margin_chain_additive_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_nested,4) AS net_margin_chain_nested_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_chain_additive)/NULLIF(e.stake,0),8) AS net_margin_chain_additive_rate_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_chain_nested)/NULLIF(e.stake,0),8) AS net_margin_chain_nested_rate_canonical,
       ROUND((-e.net-e.rebate-e.agent_cost_a_legacy)/NULLIF(e.stake,0),8) AS residual_a_rate,
           -- 二·分布层
           ROUND(e.stake/NULLIF(e.n_bets,0),4) AS avg_stake_per_bet,
           ROUND(e.valid/NULLIF(e.n_rounds,0),4) AS avg_valid_bet_per_round,
           ROUND(-e.net/NULLIF(e.n_rounds,0),4) AS avg_profit_per_round,
           ROUND(-e.net/NULLIF(e.active_days,0),4) AS avg_profit_per_day,
           ROUND(-e.net/NULLIF(e.active_shoes,0),4) AS avg_profit_per_shoe,
           ROUND(e.stake/NULLIF(e.active_days,0),4) AS avg_stake_per_active_day,
           ROUND(e.n_rounds*1.0/NULLIF(e.active_days,0),4) AS avg_rounds_per_active_day,
           ROUND(e.st_in/NULLIF(e.nb_in,0),4) AS avg_stake_hiturn,
           ROUND(e.st_out/NULLIF(e.nb_out,0),4) AS avg_stake_non_hiturn,
           ROUND(e.p25,4) AS p25_stake, ROUND(e.p50,4) AS p50_stake, ROUND(e.p75,4) AS p75_stake,
           ROUND(e.p90,4) AS p90_stake, ROUND(e.p95,4) AS p95_stake, ROUND(e.p99,4) AS p99_stake,
           ROUND(e.p50_valid,4) AS p50_valid_bet, ROUND(e.p50_profit,4) AS p50_profit,
           ROUND(e.p95/NULLIF(e.p50,0),6) AS p95_over_p50,
           ROUND(e.p99/NULLIF(e.p50,0),6) AS p99_over_p50,
           ROUND((e.stake/NULLIF(e.n_bets,0))/NULLIF(e.p50,0),6) AS avg_over_p50,
           -- 三·关系层
           e.n_tables AS common_table_count, e.n_dealers AS common_dealer_count,
           e.n_ips AS common_ip_count, e.n_products AS common_product_count,
           ROUND(e.st_in/NULLIF(e.stake,0),8) AS share_hiturn,
           -- 四·rate 层
           ROUND(-e.net/NULLIF(e.stake,0),8) AS hold_rate,
           ROUND(-e.net_in/NULLIF(e.st_in,0),8) AS hold_rate_hiturn,
           ROUND(e.rebate/NULLIF(e.valid,0),8) AS rebate_rate_actual,
           ROUND(e.rbpct,6) AS rebate_pct_config,
           ROUND(e.valid/NULLIF(e.stake,0),6) AS turnover_multiple,
           ROUND(e.freecomm_rate,6) AS free_comm_rate,
           ROUND(e.net_in/NULLIF(e.st_in,0)-e.net_out/NULLIF(e.st_out,0),8) AS roi_delta_hiturn,
           -- 五·动态层
           e.first_seen_d AS first_seen, e.last_seen_d AS last_seen,
           e.active_days, e.active_shoes, e.active_sessions,
           DATEDIFF(e.last_seen_d, e.first_seen_d)+1 AS span_days,
           ROUND(e.active_days*1.0/NULLIF(DATEDIFF(e.last_seen_d,e.first_seen_d)+1,0),6) AS persistence,
           ROUND((e.st_in/NULLIF(e.nb_in,0))/NULLIF(e.st_out/NULLIF(e.nb_out,0),0),6) AS ramp_hiturn,
           ROUND((e.st_rec/NULLIF(e.nb_rec,0))/NULLIF(e.stake/NULLIF(e.n_bets,0),0),6) AS ramp_recent,
           ROUND((e.st_rec/NULLIF(e.stake,0))/0.30,6) AS stake_ramp,
           -- 六·决策层（HF9g-P5 · D-14 斧正 —— 本件属【全窗基线族】，相对刻度与决策标签一律 NULL）
           --   病灶：x_win 系全窗单行聚合（无 GROUP BY，恒 1 行，此为设计使然，非缺陷），
           --         经 CROSS JOIN 接入后 e.* 全行同值；六层之 NTILE / PERCENT_RANK 施于常数即退化，
           --         PERCENT_RANK 恒 0 ⇒ action_priority 恒判 A，全件 100% 误标。
           --   ★ 斧正原则：不给 x_win 补 GROUP BY —— 那会改变其「全窗基线」语义，属退化。
           --     正解与 #018 之 G-05／G-06 同治：范围外之行不得接受任何下游评分与决策标签。
           --   ★ 本件之 e.* 仍照常供其它列作全窗基线使用，仅六层相对刻度与决策标签置 NULL。
           CAST(NULL AS INT)                                              AS vip_tier,                        -- 空值取值：全窗基线族无实体可分档，置 NULL（NULL＝不适用，非 0）
           CAST(NULL AS DOUBLE)                                           AS economic_value,                  -- 空值取值：同上，禁以常数百分位冒充经济价值
           CAST(NULL AS DOUBLE)                                           AS roi_pr_global,                   -- 空值取值：同上
           CAST(NULL AS DOUBLE)                                           AS risk_value,                      -- 空值取值：兼容列，同上
           CAST(NULL AS DOUBLE)                                           AS pr_stake,                        -- 空值取值：兼容列，同上
           CAST(NULL AS DOUBLE)                                           AS pr_global,                       -- 空值取值：同上
           CAST(NULL AS DOUBLE)                                           AS pr_qualified,                    -- 空值取值：同上
           'GLOBAL_BASELINE_NO_ENTITY_RANKING'                            AS pr_qualified_population,         -- 字面取值：血统 —— 明示本件为全窗基线族，无实体排序总体
           CAST(NULL AS BIGINT)                                           AS pr_global_population_n,          -- 空值取值：血统 —— 不适用
           CAST(NULL AS BIGINT)                                           AS pr_qualified_population_n,       -- 空值取值：血统 —— 不适用
           'NOT_APPLICABLE_GLOBAL_BASELINE'                               AS pr_calculation_method,           -- 字面取值：血统 —— 算法不适用
           'HF9g-P5'                                                      AS pr_calculation_version,          -- 字面取值：血统 —— 算法版本
           CAST(NULL AS STRING)                                           AS evidence_flag,                   -- 空值取值：证据旗标不适用于全窗基线
           CAST(NULL AS STRING)                                           AS evidence_rate,                   -- 空值取值：同上
           CAST(NULL AS DOUBLE)                                           AS hold_ci_halfwidth_approx,        -- 空值取值：同上
           'X 全窗基线 · 不参与实体赏罚'                                    AS action_priority                  -- 字面取值：★ D-14 斧正 —— 本族恒不入赏罚，取代原 100% 误标之「A」
    FROM q
    CROSS JOIN x_win e
  ) y
) z
-- ── 逐批 WHERE 阶梯（★ 口诀：上界 ＝ 下界 ＋ 100000，两数同进）──
--    本件 T_true 未测，无需先跑 T_true；以 0 / 100000 控制本批返回区间，末批由实际行数 < 100000 判定
--    WHERE z.audit_rn >        0 AND z.audit_rn <=   100000   -- 第 1 批
--    WHERE z.audit_rn >   100000 AND z.audit_rn <=   200000   -- 第 2 批
--    WHERE z.audit_rn >   200000 AND z.audit_rn <=   300000   -- 第 3 批
--    WHERE z.audit_rn >   300000 AND z.audit_rn <=   400000   -- 第 4 批
--    WHERE z.audit_rn >   400000 AND z.audit_rn <=   500000   -- 第 5 批
--    WHERE z.audit_rn >   500000 AND z.audit_rn <=   600000   -- 第 6 批
--    WHERE z.audit_rn >   600000 AND z.audit_rn <=   700000   -- 第 7 批
--    …余批类推。第 k 批：WHERE z.audit_rn > (k-1)*100000 AND z.audit_rn <= k*100000
--    某批返回 < 100000 行即为末批，其后不再取。
--
--    ⚠ 常见误写（务必避开）：只推下界而上界不动 ——
--        WHERE z.audit_rn > 100000 AND z.audit_rn <= 100000   ← 自相矛盾，恒为假，返回空集
--        WHERE z.audit_rn > 200000 AND z.audit_rn <= 100000   ← 同上，空集
--      两个数必须**同时**前进，且始终相差 100000。
--      下界 ＝ 上一批之上界；上界 ＝ 本批之上界。
WHERE z.audit_rn > 0 AND z.audit_rn <= 100000 -- ★ HF9c 本批区间
ORDER BY z.audit_rn;


-- ══════════════════════════════════════════════════════════════════════════════════════════════
-- 106. VB_41c2_concentration_v2.csv   [总包行 11052~11140 · 原 20 列 ＋六层约 60 列]
--     典型学：M05 退水套利　派生旗标：hiturn（s.x_valid > s.x_stake · 仅供 CASE 条件聚合，全包无任何 WHERE/AND/HAVING 以此过滤）　连接：全窗基线
-- ══════════════════════════════════════════════════════════════════════════════════════════════
-- ★ W-64 · D-14 警示（本件属 x_win 族 · 66 件之一 · 详见 §Z 段 D-14 全案）
--   本件以 `CROSS JOIN x_win e` 接入全局基线，x_win 无 GROUP BY ⇒ 恒 1 行 ⇒ e.* 全行同值。
--   故：economic_value / roi_pr_global / risk_value / pr_stake / pr_global 恒为 0；
--       action_priority 每一行皆为「A 净亏最大十分位 · 优先复核」（Z 分支永不触发）；
--       evidence_rate 恒为最高档；vip_tier 由常数键分档 ⇒ 无信息且非确定。
--   ⇒ 本件决策层三列 **NOT_FOR_DECISION**，裁定前不得用于排班、抽查或汇报。
-- ── ① 先跑 T_true 留档（不足 100000 者一次导全，不必分批）──
-- ── ① T_true：HF9c 不再强制预跑完整 COUNT。
--    本批实际返回行数 < 100000 即判定为末批；全批完成后以各批 n_rows / audit_rn 范围核对总量。

-- ── ② 分批取数：第 1 批。第 k 批只改末行两数为 (k-1)*100000 与 k*100000 ──
--    审计字段二（REDTEAM 2026-08-24 裁定 · 四锁）：
--      audit_rn  全局观测坐标 —— 由**与原版审计版逐字同一**之排序键所生，两版可逐行对账
--      batch_id  物理分批信息 —— 该行所属批次，由 audit_rn 算得，非引擎所赋
--    ★ 锁三：二者皆为审计字段，**不得进入任何业务指标计算**。
--    ★ 锁四：两版经 audit_rn 逐行字段核验后，方可宣布输出完全一致。

-- ── ③ 每批取回后自证四数（任一不符即停手回报，禁止放行）──
--    n_rows        = COUNT(*)      须等于 COUNT(DISTINCT audit_rn)   （批内无重复）
--    audit_rn_min  = MIN(audit_rn) 须等于 (k-1)*100000 + 1           （与上批严丝合缝）
--    audit_rn_max  = MAX(audit_rn) 须等于 min + n_rows - 1           （批内无缺口）
--    全批取毕再验：各批 audit_rn 之并集 = 1 .. T_true，无缺号、无重号。
--     ★ 首行＝平台真净亏最多者（已扣退水与代理占成）。
--
SELECT z.*,
       CAST(FLOOR((z.audit_rn - 1) / 100000) + 1 AS INT)          AS batch_id,
       'A168_HF9F_20260827_0900' AS run_id,
       '2026-08-27 09:00:00' AS snapshot_sync_time
FROM (
  SELECT y.*,
         ROW_NUMBER() OVER (ORDER BY y.`residual_b` ASC, y.`roi` DESC, y.`grp`, y.`n_rows`, y.`n_members`, y.`n_dates`, y.`n_tables`, y.`n_bet09`, y.`top1_member_share_pct`, y.`top_date_share_pct`, y.`top_table_share_pct`, y.`top_bet09_share_pct`, y.`top_stake_share_pct`, y.`st_member`, y.`st_date`, y.`st_table`, y.`st_bet09`, y.`st_stake`, y.`n_dims_high`, y.`n_dims_near_or_high`, y.`verdict_concentration`, y.`sum_stake`) AS audit_rn
  FROM (
    WITH
      x_ranked AS (
    SELECT b.bet01, b.bet03, b.bet04, b.bet05, b.bet09, b.bet11, b.bet13,
           b.bet15, b.bet16, b.bet17, b.bet18, b.bet19, b.bet20, b.bet21,
           b.bet22, b.bet23, b.bet24, b.bet25, b.bet26, b.bet27, b.bet38, b.bet39, b.category, b.commission,
           b.dt, b.eid, b.ip, b.validbet, b.updatetime, b.sync_time,
           ROW_NUMBER() OVER (
             PARTITION BY b.bet01
             ORDER BY b.updatetime DESC, b.sync_time DESC, b.dt DESC)      AS x_rn
    FROM ods_mariadb_2b.ods_a168_bet02 b
    WHERE b.dt >= '2026-03-21' AND b.dt < '2026-08-07'
      AND b.bet02 = '101'
      AND b.sync_time <= '2026-08-27 09:00:00'
  ),
    x_testagent AS (
    SELECT age001 AS agent_id FROM ods_mariadb_2b.ods_a168_agent WHERE age022 = '1'
  ),
    x_bs0 AS (
    SELECT b.bet05 AS x_member, b.eid AS x_dealer, b.bet39 AS x_table,
           b.bet03 AS x_shoe, b.ip AS x_ip, b.bet09 AS x_product, b.dt AS x_date,
           CONCAT_WS('|', b.bet03, b.bet04, b.bet39)                      AS x_round,
           CONCAT_WS('|', b.bet39, b.bet03)                               AS x_tblshoe,
           CAST(NULLIF(TRIM(b.bet04),'') AS INT)                          AS x_rno,
           CASE WHEN b.dt >= '2026-07-08' THEN 1 ELSE 0 END               AS x_rec,
           CASE WHEN TRIM(b.commission)='1' THEN 1 ELSE 0 END             AS x_freecomm,
           CAST(NULLIF(TRIM(b.bet13),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_stake,
           CAST(NULLIF(TRIM(b.validbet),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_valid,
           CAST(NULLIF(TRIM(b.bet16),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_rebate,
           CAST(NULLIF(TRIM(b.bet17),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_net,
           CAST(NULLIF(TRIM(b.bet15),'') AS DECIMAL(20,6))                AS x_rbpct,
           COALESCE(CAST(NULLIF(TRIM(b.bet23),'') AS DECIMAL(20,6)),0)   AS x_agpct,
          NULLIF(CAST(NULLIF(TRIM(b.bet23),'') AS DECIMAL(20,6)),0)     AS x_rate1,
          NULLIF(CAST(NULLIF(TRIM(b.bet24),'') AS DECIMAL(20,6)),0)     AS x_rate2,
          NULLIF(CAST(NULLIF(TRIM(b.bet25),'') AS DECIMAL(20,6)),0)     AS x_rate3,
          NULLIF(CAST(NULLIF(TRIM(b.bet26),'') AS DECIMAL(20,6)),0)     AS x_rate4,
          NULLIF(CAST(NULLIF(TRIM(b.bet27),'') AS DECIMAL(20,6)),0)     AS x_rate5,
          (CASE WHEN NULLIF(CAST(NULLIF(TRIM(b.bet22),'') AS BIGINT),0) IS NOT NULL THEN 5
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet21),'') AS BIGINT),0) IS NOT NULL THEN 4
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet20),'') AS BIGINT),0) IS NOT NULL THEN 3
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet19),'') AS BIGINT),0) IS NOT NULL THEN 2
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet18),'') AS BIGINT),0) IS NOT NULL THEN 1
                ELSE 0 END)                                             AS x_chain_depth,
           CASE WHEN COALESCE(t1.agent_id,t2.agent_id,t3.agent_id,
                              t4.agent_id,t5.agent_id) IS NOT NULL
                THEN 1 ELSE 0 END                                        AS f_testline
    FROM x_ranked b
    LEFT JOIN x_testagent t1 ON t1.agent_id = b.bet18
    LEFT JOIN x_testagent t2 ON t2.agent_id = b.bet19
    LEFT JOIN x_testagent t3 ON t3.agent_id = b.bet20
    LEFT JOIN x_testagent t4 ON t4.agent_id = b.bet21
    LEFT JOIN x_testagent t5 ON t5.agent_id = b.bet22
    WHERE b.x_rn = 1
      AND b.category='1' AND UPPER(TRIM(b.bet38))='N'
      AND CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8)) > 0
  ),
  x_mk AS (
    SELECT s.*,
           CASE WHEN s.f_testline = 0 THEN 1 ELSE 0 END                 AS is_clean
    FROM x_bs0 s
  ),
  x_agg AS (
    SELECT s.x_member                                                        AS x_key,
           COUNT(*) AS n_bets, COUNT(DISTINCT s.x_round) AS n_rounds,
           COUNT(DISTINCT s.x_date) AS active_days, COUNT(DISTINCT s.x_tblshoe) AS active_shoes,
           COUNT(DISTINCT CONCAT_WS('|', s.x_date, s.x_table)) AS active_sessions,
           COUNT(DISTINCT s.x_table) AS n_tables, COUNT(DISTINCT s.x_dealer) AS n_dealers,
           COUNT(DISTINCT s.x_ip) AS n_ips, COUNT(DISTINCT s.x_product) AS n_products,
           MIN(s.x_date) AS first_seen_d, MAX(s.x_date) AS last_seen_d,
           SUM(s.x_stake) AS stake, SUM(s.x_valid) AS valid, SUM(s.x_rebate) AS rebate,
           SUM(s.x_net) AS net, SUM(-s.x_net *(100.0-s.x_agpct)/100.0) AS agent_cost,
           AVG(100.0-s.x_agpct)                   AS agent_pct,
           AVG(s.x_agpct)                         AS company_retain_pct,
           SUM(-s.x_net *s.x_agpct/100.0)         AS agent_cost_a_legacy,
           SUM(s.x_valid*s.x_agpct/100.0)         AS agent_cost_valid_base_legacy,
          AVG(COALESCE(s.x_rate1,100)) AS retain_pct_lv1, AVG(COALESCE(s.x_rate2,100)) AS retain_pct_lv2,
          AVG(COALESCE(s.x_rate3,100)) AS retain_pct_lv3, AVG(COALESCE(s.x_rate4,100)) AS retain_pct_lv4,
          AVG(COALESCE(s.x_rate5,100)) AS retain_pct_lv5, AVG(s.x_chain_depth) AS chain_depth_avg,
          AVG(COALESCE(100.0-s.x_rate1,0)) AS agent_pct_lv1, AVG(COALESCE(100.0-s.x_rate2,0)) AS agent_pct_lv2,
          AVG(COALESCE(100.0-s.x_rate3,0)) AS agent_pct_lv3, AVG(COALESCE(100.0-s.x_rate4,0)) AS agent_pct_lv4,
          AVG(COALESCE(100.0-s.x_rate5,0)) AS agent_pct_lv5,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate1,0)/100.0)                        AS agent_cost_lv1,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate2,0)/100.0)                        AS agent_cost_lv2,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate3,0)/100.0)                        AS agent_cost_lv3,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate4,0)/100.0)                        AS agent_cost_lv4,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate5,0)/100.0)                        AS agent_cost_lv5,
          SUM(-s.x_net*(COALESCE(100.0-s.x_rate1,0)+COALESCE(100.0-s.x_rate2,0)
                       +COALESCE(100.0-s.x_rate3,0)+COALESCE(100.0-s.x_rate4,0)
                       +COALESCE(100.0-s.x_rate5,0))/100.0)                   AS agent_cost_chain_additive,
          SUM(-s.x_net*(1.0 - CAST(COALESCE(s.x_rate1,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate2,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate3,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate4,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate5,100) AS DOUBLE)/100.0))
                                                                       AS agent_cost_chain_nested,
           AVG(s.x_rbpct) AS rbpct, AVG(s.x_freecomm*1.0) AS freecomm_rate,
           PERCENTILE_APPROX(s.x_stake,0.25) AS p25, PERCENTILE_APPROX(s.x_stake,0.50) AS p50,
           PERCENTILE_APPROX(s.x_stake,0.75) AS p75, PERCENTILE_APPROX(s.x_stake,0.90) AS p90,
           PERCENTILE_APPROX(s.x_stake,0.95) AS p95, PERCENTILE_APPROX(s.x_stake,0.99) AS p99,
           PERCENTILE_APPROX(s.x_valid,0.50) AS p50_valid,
           PERCENTILE_APPROX(s.x_net,0.50)   AS p50_profit,
           SUM(CASE WHEN s.x_valid > s.x_stake THEN s.x_stake ELSE 0 END) AS st_in,
           SUM(CASE WHEN s.x_valid > s.x_stake THEN 1 ELSE 0 END)         AS nb_in,
           SUM(CASE WHEN s.x_valid > s.x_stake THEN s.x_net ELSE 0 END)   AS net_in,
           SUM(CASE WHEN NOT (s.x_valid > s.x_stake) THEN s.x_stake ELSE 0 END) AS st_out,
           SUM(CASE WHEN NOT (s.x_valid > s.x_stake) THEN 1 ELSE 0 END)         AS nb_out,
           SUM(CASE WHEN NOT (s.x_valid > s.x_stake) THEN s.x_net ELSE 0 END)   AS net_out,
           SUM(CASE WHEN s.x_rec=1 THEN s.x_stake ELSE 0 END) AS st_rec,
           SUM(CASE WHEN s.x_rec=1 THEN 1 ELSE 0 END)         AS nb_rec
    FROM x_mk s
    WHERE s.is_clean = 1
      AND s.x_member IS NOT NULL AND TRIM(CAST(s.x_member AS STRING)) <> ''
    GROUP BY s.x_member
  ),
  x_win AS (
    SELECT            COUNT(*) AS n_bets, COUNT(DISTINCT s.x_round) AS n_rounds,
           COUNT(DISTINCT s.x_date) AS active_days, COUNT(DISTINCT s.x_tblshoe) AS active_shoes,
           COUNT(DISTINCT CONCAT_WS('|', s.x_date, s.x_table)) AS active_sessions,
           COUNT(DISTINCT s.x_table) AS n_tables, COUNT(DISTINCT s.x_dealer) AS n_dealers,
           COUNT(DISTINCT s.x_ip) AS n_ips, COUNT(DISTINCT s.x_product) AS n_products,
           MIN(s.x_date) AS first_seen_d, MAX(s.x_date) AS last_seen_d,
           SUM(s.x_stake) AS stake, SUM(s.x_valid) AS valid, SUM(s.x_rebate) AS rebate,
           SUM(s.x_net) AS net, SUM(-s.x_net *(100.0-s.x_agpct)/100.0) AS agent_cost,
           AVG(100.0-s.x_agpct)                   AS agent_pct,
           AVG(s.x_agpct)                         AS company_retain_pct,
           SUM(-s.x_net *s.x_agpct/100.0)         AS agent_cost_a_legacy,
           SUM(s.x_valid*s.x_agpct/100.0)         AS agent_cost_valid_base_legacy,
          AVG(COALESCE(s.x_rate1,100)) AS retain_pct_lv1, AVG(COALESCE(s.x_rate2,100)) AS retain_pct_lv2,
          AVG(COALESCE(s.x_rate3,100)) AS retain_pct_lv3, AVG(COALESCE(s.x_rate4,100)) AS retain_pct_lv4,
          AVG(COALESCE(s.x_rate5,100)) AS retain_pct_lv5, AVG(s.x_chain_depth) AS chain_depth_avg,
          AVG(COALESCE(100.0-s.x_rate1,0)) AS agent_pct_lv1, AVG(COALESCE(100.0-s.x_rate2,0)) AS agent_pct_lv2,
          AVG(COALESCE(100.0-s.x_rate3,0)) AS agent_pct_lv3, AVG(COALESCE(100.0-s.x_rate4,0)) AS agent_pct_lv4,
          AVG(COALESCE(100.0-s.x_rate5,0)) AS agent_pct_lv5,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate1,0)/100.0)                        AS agent_cost_lv1,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate2,0)/100.0)                        AS agent_cost_lv2,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate3,0)/100.0)                        AS agent_cost_lv3,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate4,0)/100.0)                        AS agent_cost_lv4,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate5,0)/100.0)                        AS agent_cost_lv5,
          SUM(-s.x_net*(COALESCE(100.0-s.x_rate1,0)+COALESCE(100.0-s.x_rate2,0)
                       +COALESCE(100.0-s.x_rate3,0)+COALESCE(100.0-s.x_rate4,0)
                       +COALESCE(100.0-s.x_rate5,0))/100.0)                   AS agent_cost_chain_additive,
          SUM(-s.x_net*(1.0 - CAST(COALESCE(s.x_rate1,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate2,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate3,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate4,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate5,100) AS DOUBLE)/100.0))
                                                                       AS agent_cost_chain_nested,
           AVG(s.x_rbpct) AS rbpct, AVG(s.x_freecomm*1.0) AS freecomm_rate,
           PERCENTILE_APPROX(s.x_stake,0.25) AS p25, PERCENTILE_APPROX(s.x_stake,0.50) AS p50,
           PERCENTILE_APPROX(s.x_stake,0.75) AS p75, PERCENTILE_APPROX(s.x_stake,0.90) AS p90,
           PERCENTILE_APPROX(s.x_stake,0.95) AS p95, PERCENTILE_APPROX(s.x_stake,0.99) AS p99,
           PERCENTILE_APPROX(s.x_valid,0.50) AS p50_valid,
           PERCENTILE_APPROX(s.x_net,0.50)   AS p50_profit,
           SUM(CASE WHEN s.x_valid > s.x_stake THEN s.x_stake ELSE 0 END) AS st_in,
           SUM(CASE WHEN s.x_valid > s.x_stake THEN 1 ELSE 0 END)         AS nb_in,
           SUM(CASE WHEN s.x_valid > s.x_stake THEN s.x_net ELSE 0 END)   AS net_in,
           SUM(CASE WHEN NOT (s.x_valid > s.x_stake) THEN s.x_stake ELSE 0 END) AS st_out,
           SUM(CASE WHEN NOT (s.x_valid > s.x_stake) THEN 1 ELSE 0 END)         AS nb_out,
           SUM(CASE WHEN NOT (s.x_valid > s.x_stake) THEN s.x_net ELSE 0 END)   AS net_out,
           SUM(CASE WHEN s.x_rec=1 THEN s.x_stake ELSE 0 END) AS st_rec,
           SUM(CASE WHEN s.x_rec=1 THEN 1 ELSE 0 END)         AS nb_rec
    FROM x_mk s
    WHERE s.is_clean = 1
      AND s.x_member IS NOT NULL AND TRIM(CAST(s.x_member AS STRING)) <> ''
  ),
      q AS (
        WITH tgt AS (                                                                                       -- 公共表表达式：开启中间结果集 tgt——964 笔之目标集
          SELECT CASE WHEN TRIM(bet09) IN ('Bear8', 'Lucky7TwoCard', 'SmallTiger',
                                           'SuperTie4', 'SuperTie5', 'SuperTie8', 'SuperTie9')
                      THEN 'B_上线测试型' ELSE 'A_主群' END                       AS grp,                    -- 条件取值：证据分群，禁合并解释
                 TRIM(bet05)                                                     AS mid,                    -- 取列：会员编号
                 dt                                                              AS dt,                     -- 取列：分区日
                 TRIM(bet04)                                                     AS tbl,                    -- 取列：桌号
                 TRIM(bet09)                                                     AS g9,                     -- 取列：注型
                 CAST(NULLIF(TRIM(bet13), '') AS DECIMAL(20,8))                  AS stake                   -- 取列：本金
          FROM ods_mariadb_2b.ods_a168_bet02                                                                -- 取数来源：取自注单主表
          WHERE dt >= '2026-03-21' AND dt < '2026-08-07'                                                    -- 过滤条件：限定分析窗
            AND sync_time <= '2026-08-27 09:00:00'
            AND CAST(bet02 AS STRING) = '101'                                                               -- 并列条件：限定百家乐
            AND CAST(NULLIF(TRIM(bet41), '')    AS DECIMAL(20,8)) = 0                                       -- 并列条件：bet41 恰为零
            AND CAST(NULLIF(TRIM(validbet), '') AS DECIMAL(20,8)) > 0                                       -- 并列条件：validbet 为正
        ),                                                                                                  -- 续行：收束上方的子查询或函数括号
        tot AS (                                                                                            -- 公共表表达式：开启中间结果集 tot——各群之总量
          SELECT grp, COUNT(*) AS n, SUM(stake) AS s FROM tgt GROUP BY grp                                  -- 取列与汇总：群、笔数、本金总额
        ),                                                                                                  -- 续行：收束上方的子查询或函数括号
        mx AS (                                                                                             -- 公共表表达式：开启中间结果集 mx——五维之首位占量
          SELECT t.grp                                                           AS grp,                    -- 取列：证据群
                 (SELECT MAX(c) FROM (SELECT grp AS g2, mid, COUNT(*) AS c FROM tgt GROUP BY grp, mid) x
                   WHERE x.g2 = t.grp)                                           AS top_member_n,           -- 标量子查询：首位会员之笔数
                 (SELECT MAX(c) FROM (SELECT grp AS g2, dt, COUNT(*) AS c FROM tgt GROUP BY grp, dt) x
                   WHERE x.g2 = t.grp)                                           AS top_date_n,             -- 标量子查询：首位日期之笔数
                 (SELECT MAX(c) FROM (SELECT grp AS g2, tbl, COUNT(*) AS c FROM tgt GROUP BY grp, tbl) x
                   WHERE x.g2 = t.grp)                                           AS top_table_n,            -- 标量子查询：首位桌台之笔数
                 (SELECT MAX(c) FROM (SELECT grp AS g2, g9, COUNT(*) AS c FROM tgt GROUP BY grp, g9) x
                   WHERE x.g2 = t.grp)                                           AS top_bet09_n,            -- 标量子查询：首位注型之笔数
                 (SELECT MAX(c) FROM (SELECT grp AS g2, mid, SUM(stake) AS c FROM tgt GROUP BY grp, mid) x
                   WHERE x.g2 = t.grp)                                           AS top_stake_amt           -- 标量子查询：★ 单一会员之最大本金和——金额维
          FROM (SELECT DISTINCT grp FROM tgt) t                                                             -- 取数来源：各群一行
        )                                                                                                   -- 续行：收束上方的子查询或函数括号
        SELECT                                                                                              -- 取列：起始取列子句
          o.grp                                                                  AS grp,                    -- 取列：证据群
          o.n                                                                    AS n_rows,                 -- 取列：该群笔数
          (SELECT COUNT(DISTINCT mid) FROM tgt z WHERE z.grp = o.grp)            AS n_members,              -- 标量子查询：涉及会员数
          (SELECT COUNT(DISTINCT dt)  FROM tgt z WHERE z.grp = o.grp)            AS n_dates,                -- 标量子查询：涉及天数
          (SELECT COUNT(DISTINCT tbl) FROM tgt z WHERE z.grp = o.grp)            AS n_tables,               -- 标量子查询：涉及桌数
          (SELECT COUNT(DISTINCT g9)  FROM tgt z WHERE z.grp = o.grp)            AS n_bet09,                -- 标量子查询：涉及注型数
          ROUND(m.top_member_n * 100.0 / NULLIF(o.n, 0), 4)                      AS top1_member_share_pct,  -- 比率表达式：〔一层〕首位会员占比
          ROUND(m.top_date_n   * 100.0 / NULLIF(o.n, 0), 4)                      AS top_date_share_pct,     -- 比率表达式：〔一层〕首位日期占比
          ROUND(m.top_table_n  * 100.0 / NULLIF(o.n, 0), 4)                      AS top_table_share_pct,    -- 比率表达式：〔一层〕首位桌台占比
          ROUND(m.top_bet09_n  * 100.0 / NULLIF(o.n, 0), 4)                      AS top_bet09_share_pct,    -- 比率表达式：〔一层〕首位注型占比
          ROUND(m.top_stake_amt * 100.0 / NULLIF(o.s, 0), 4)                     AS top_stake_share_pct,    -- 比率表达式：〔一层〕★ 首位会员之本金占比——金额维
          CASE WHEN m.top_member_n  * 100.0 / NULLIF(o.n, 0) >= 30 THEN 'HIGH'
               WHEN m.top_member_n  * 100.0 / NULLIF(o.n, 0) >= 29 THEN 'NEAR' ELSE 'NORMAL' END AS st_member, -- 条件分支：〔二层〕会员维之三态
          CASE WHEN m.top_date_n    * 100.0 / NULLIF(o.n, 0) >= 30 THEN 'HIGH'
               WHEN m.top_date_n    * 100.0 / NULLIF(o.n, 0) >= 29 THEN 'NEAR' ELSE 'NORMAL' END AS st_date,   -- 条件分支：〔二层〕日期维之三态
          CASE WHEN m.top_table_n   * 100.0 / NULLIF(o.n, 0) >= 30 THEN 'HIGH'
               WHEN m.top_table_n   * 100.0 / NULLIF(o.n, 0) >= 29 THEN 'NEAR' ELSE 'NORMAL' END AS st_table,  -- 条件分支：〔二层〕桌台维之三态
          CASE WHEN m.top_bet09_n   * 100.0 / NULLIF(o.n, 0) >= 30 THEN 'HIGH'
               WHEN m.top_bet09_n   * 100.0 / NULLIF(o.n, 0) >= 29 THEN 'NEAR' ELSE 'NORMAL' END AS st_bet09,  -- 条件分支：〔二层〕注型维之三态
          CASE WHEN m.top_stake_amt * 100.0 / NULLIF(o.s, 0) >= 30 THEN 'HIGH'
               WHEN m.top_stake_amt * 100.0 / NULLIF(o.s, 0) >= 29 THEN 'NEAR' ELSE 'NORMAL' END AS st_stake,  -- 条件分支：〔二层〕金额维之三态
          (CASE WHEN m.top_member_n  * 100.0 / NULLIF(o.n, 0) >= 30 THEN 1 ELSE 0 END
         + CASE WHEN m.top_date_n    * 100.0 / NULLIF(o.n, 0) >= 30 THEN 1 ELSE 0 END
         + CASE WHEN m.top_table_n   * 100.0 / NULLIF(o.n, 0) >= 30 THEN 1 ELSE 0 END
         + CASE WHEN m.top_bet09_n   * 100.0 / NULLIF(o.n, 0) >= 30 THEN 1 ELSE 0 END
         + CASE WHEN m.top_stake_amt * 100.0 / NULLIF(o.s, 0) >= 30 THEN 1 ELSE 0 END) AS n_dims_high,      -- 计算表达式：〔三层〕★ 高集中之维数
          (CASE WHEN m.top_member_n  * 100.0 / NULLIF(o.n, 0) >= 29 THEN 1 ELSE 0 END
         + CASE WHEN m.top_date_n    * 100.0 / NULLIF(o.n, 0) >= 29 THEN 1 ELSE 0 END
         + CASE WHEN m.top_table_n   * 100.0 / NULLIF(o.n, 0) >= 29 THEN 1 ELSE 0 END
         + CASE WHEN m.top_bet09_n   * 100.0 / NULLIF(o.n, 0) >= 29 THEN 1 ELSE 0 END
         + CASE WHEN m.top_stake_amt * 100.0 / NULLIF(o.s, 0) >= 29 THEN 1 ELSE 0 END) AS n_dims_near_or_high, -- 计算表达式：〔三层〕★ 高或近之维数
          CASE                                                                                              -- 条件分支：〔三层〕起始分支——四态联合判词
            WHEN (CASE WHEN m.top_member_n  * 100.0 / NULLIF(o.n, 0) >= 30 THEN 1 ELSE 0 END
                + CASE WHEN m.top_date_n    * 100.0 / NULLIF(o.n, 0) >= 30 THEN 1 ELSE 0 END
                + CASE WHEN m.top_table_n   * 100.0 / NULLIF(o.n, 0) >= 30 THEN 1 ELSE 0 END
                + CASE WHEN m.top_bet09_n   * 100.0 / NULLIF(o.n, 0) >= 30 THEN 1 ELSE 0 END
                + CASE WHEN m.top_stake_amt * 100.0 / NULLIF(o.s, 0) >= 30 THEN 1 ELSE 0 END) >= 2
              THEN 'MULTI_DIMENSION_SIGNAL'                                                                 -- 分支判定：二维以上为高
            WHEN (CASE WHEN m.top_member_n  * 100.0 / NULLIF(o.n, 0) >= 29 THEN 1 ELSE 0 END
                + CASE WHEN m.top_date_n    * 100.0 / NULLIF(o.n, 0) >= 29 THEN 1 ELSE 0 END
                + CASE WHEN m.top_table_n   * 100.0 / NULLIF(o.n, 0) >= 29 THEN 1 ELSE 0 END
                + CASE WHEN m.top_bet09_n   * 100.0 / NULLIF(o.n, 0) >= 29 THEN 1 ELSE 0 END
                + CASE WHEN m.top_stake_amt * 100.0 / NULLIF(o.s, 0) >= 29 THEN 1 ELSE 0 END) >= 2
              THEN 'MULTI_DIMENSION_NEAR_THRESHOLD'                                                         -- 分支判定：★ 二维以上为近——本版所补之缺口
            WHEN (CASE WHEN m.top_member_n  * 100.0 / NULLIF(o.n, 0) >= 30 THEN 1 ELSE 0 END
                + CASE WHEN m.top_date_n    * 100.0 / NULLIF(o.n, 0) >= 30 THEN 1 ELSE 0 END
                + CASE WHEN m.top_table_n   * 100.0 / NULLIF(o.n, 0) >= 30 THEN 1 ELSE 0 END
                + CASE WHEN m.top_bet09_n   * 100.0 / NULLIF(o.n, 0) >= 30 THEN 1 ELSE 0 END
                + CASE WHEN m.top_stake_amt * 100.0 / NULLIF(o.s, 0) >= 30 THEN 1 ELSE 0 END) = 1
              THEN 'SINGLE_DIMENSION_SIGNAL'                                                                -- 分支判定：恰一维为高
            ELSE 'NO_CONCENTRATION_SIGNAL'                                                                  -- 分支判定：无高无近
          END                                                                    AS verdict_concentration,  -- 条件分支：收束上方判词，产出「verdict_concentration」
          ROUND(o.s, 2)                                                          AS sum_stake               -- 取列：该群本金总额
        FROM tot o                                                                                          -- 取数来源：取自本条自建的中间结果集 tot
        JOIN mx m ON m.grp = o.grp                                                                          -- 连接：按证据群接首位占量
      )
    SELECT q.*,
           -- 一·经济层
           ROUND(e.stake,4) AS stake, ROUND(e.valid,4) AS valid_bet,
           ROUND(-e.net,4) AS profit, e.n_bets, e.n_rounds,
           ROUND(e.net/NULLIF(e.stake,0),8) AS roi,
           ROUND(e.net_in/NULLIF(e.st_in,0),8) AS roi_hiturn,
           ROUND(e.net_out/NULLIF(e.st_out,0),8) AS roi_non_hiturn,
           ROUND((e.net-e.rebate)/NULLIF(e.stake,0),8) AS roi_ex_rebate,
           ROUND(e.net,4) AS roi_numerator, ROUND(e.stake,4) AS roi_denominator,
           CASE WHEN e.stake IS NULL THEN 'NULL_DENOM' WHEN e.stake<=0 THEN 'ZERO_DENOM'
                WHEN e.n_bets<30 THEN 'THIN_EXPOSURE' ELSE 'OK' END AS roi_denominator_status,
           ROUND(e.rebate,4) AS rebate_cost, ROUND(e.agent_cost,4)                           AS cost_complement_b,
       ROUND(e.agent_pct,4)                            AS pct_complement,
       ROUND(e.company_retain_pct,4)                   AS pct_top_bet23,
       'AG03-UNRESOLVED'                                     AS agent_formula_version,
      'ALL5_LEVELS_bet23_to_bet27'                    AS agent_level_scope,
      ROUND(e.agent_cost_lv1,4) AS agent_cost_lv1, ROUND(e.agent_cost_lv2,4) AS agent_cost_lv2,
      ROUND(e.agent_cost_lv3,4) AS agent_cost_lv3, ROUND(e.agent_cost_lv4,4) AS agent_cost_lv4,
      ROUND(e.agent_cost_lv5,4) AS agent_cost_lv5,
      ROUND(e.agent_pct_lv1,6) AS agent_pct_lv1, ROUND(e.agent_pct_lv2,6) AS agent_pct_lv2,
      ROUND(e.agent_pct_lv3,6) AS agent_pct_lv3, ROUND(e.agent_pct_lv4,6) AS agent_pct_lv4,
      ROUND(e.agent_pct_lv5,6) AS agent_pct_lv5,
      ROUND(e.retain_pct_lv1,6) AS retain_pct_lv1, ROUND(e.retain_pct_lv2,6) AS retain_pct_lv2,
      ROUND(e.retain_pct_lv3,6) AS retain_pct_lv3, ROUND(e.retain_pct_lv4,6) AS retain_pct_lv4,
      ROUND(e.retain_pct_lv5,6) AS retain_pct_lv5, ROUND(e.chain_depth_avg,4) AS chain_depth_avg,
      ROUND(e.agent_cost_chain_additive,4)            AS agent_cost_chain_additive,
      ROUND(e.agent_cost_chain_nested,4)              AS agent_cost_chain_nested,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_additive,4) AS residual_chain_additive,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_nested,4)   AS residual_chain_nested,
      'PENDING_AG03'                                  AS decision_status,
      'FALSE'                                         AS admit_to_risk_decision,
      'NOT_FOR_ENFORCEMENT'                           AS deliverable_class,
       ROUND(e.agent_cost_a_legacy,4)                  AS agent_cost_a_legacy,
       ROUND(e.agent_cost_valid_base_legacy,4)         AS agent_cost_valid_base_legacy,
           ROUND(-e.net-e.rebate,4)                        AS ngr,
       ROUND(-e.net-e.rebate-e.agent_cost,4)           AS residual_b,
       ROUND(-e.net-e.rebate-e.agent_cost_a_legacy,4)  AS residual_a,
           ROUND((-e.net-e.rebate)/NULLIF(e.stake,0),8)    AS ngr_rate,
       ROUND((-e.net-e.rebate-e.agent_cost)/NULLIF(e.stake,0),8)   AS residual_b_rate,
      -- 【HF9c · canonical accounting contract】
      --   以下 canonical 字段只增加明确 scope；不删除、不覆盖既有字段。
      --   formal_bet23_* 保持 HF9b 当前生产公式及其 NULL/0 语义；
      --   lv1~lv5 / additive / nested 则分别采用各自原始 e.* 成本字段，
      --   rate 一律从未舍入的 e.* 分子 / e.stake 计算，禁止由展示值反算。
      ROUND(e.agent_cost,4) AS agent_cost_bet23_formal_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost,4) AS net_margin_bet23_formal_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost)/NULLIF(e.stake,0),8) AS net_margin_bet23_formal_rate_canonical,
      ROUND(e.agent_cost_lv1,4) AS agent_cost_lv1_bet23_canonical,
      ROUND(e.agent_cost_lv2,4) AS agent_cost_lv2_bet24_canonical,
      ROUND(e.agent_cost_lv3,4) AS agent_cost_lv3_bet25_canonical,
      ROUND(e.agent_cost_lv4,4) AS agent_cost_lv4_bet26_canonical,
      ROUND(e.agent_cost_lv5,4) AS agent_cost_lv5_bet27_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_lv1,4) AS net_margin_lv1_bet23_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_lv1)/NULLIF(e.stake,0),8) AS net_margin_lv1_bet23_rate_canonical,
      ROUND(e.agent_cost_chain_additive,4) AS agent_cost_chain_additive_canonical,
      ROUND(e.agent_cost_chain_nested,4) AS agent_cost_chain_nested_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_additive,4) AS net_margin_chain_additive_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_nested,4) AS net_margin_chain_nested_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_chain_additive)/NULLIF(e.stake,0),8) AS net_margin_chain_additive_rate_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_chain_nested)/NULLIF(e.stake,0),8) AS net_margin_chain_nested_rate_canonical,
       ROUND((-e.net-e.rebate-e.agent_cost_a_legacy)/NULLIF(e.stake,0),8) AS residual_a_rate,
           -- 二·分布层
           ROUND(e.stake/NULLIF(e.n_bets,0),4) AS avg_stake_per_bet,
           ROUND(e.valid/NULLIF(e.n_rounds,0),4) AS avg_valid_bet_per_round,
           ROUND(-e.net/NULLIF(e.n_rounds,0),4) AS avg_profit_per_round,
           ROUND(-e.net/NULLIF(e.active_days,0),4) AS avg_profit_per_day,
           ROUND(-e.net/NULLIF(e.active_shoes,0),4) AS avg_profit_per_shoe,
           ROUND(e.stake/NULLIF(e.active_days,0),4) AS avg_stake_per_active_day,
           ROUND(e.n_rounds*1.0/NULLIF(e.active_days,0),4) AS avg_rounds_per_active_day,
           ROUND(e.st_in/NULLIF(e.nb_in,0),4) AS avg_stake_hiturn,
           ROUND(e.st_out/NULLIF(e.nb_out,0),4) AS avg_stake_non_hiturn,
           ROUND(e.p25,4) AS p25_stake, ROUND(e.p50,4) AS p50_stake, ROUND(e.p75,4) AS p75_stake,
           ROUND(e.p90,4) AS p90_stake, ROUND(e.p95,4) AS p95_stake, ROUND(e.p99,4) AS p99_stake,
           ROUND(e.p50_valid,4) AS p50_valid_bet, ROUND(e.p50_profit,4) AS p50_profit,
           ROUND(e.p95/NULLIF(e.p50,0),6) AS p95_over_p50,
           ROUND(e.p99/NULLIF(e.p50,0),6) AS p99_over_p50,
           ROUND((e.stake/NULLIF(e.n_bets,0))/NULLIF(e.p50,0),6) AS avg_over_p50,
           -- 三·关系层
           e.n_tables AS common_table_count, e.n_dealers AS common_dealer_count,
           e.n_ips AS common_ip_count, e.n_products AS common_product_count,
           ROUND(e.st_in/NULLIF(e.stake,0),8) AS share_hiturn,
           -- 四·rate 层
           ROUND(-e.net/NULLIF(e.stake,0),8) AS hold_rate,
           ROUND(-e.net_in/NULLIF(e.st_in,0),8) AS hold_rate_hiturn,
           ROUND(e.rebate/NULLIF(e.valid,0),8) AS rebate_rate_actual,
           ROUND(e.rbpct,6) AS rebate_pct_config,
           ROUND(e.valid/NULLIF(e.stake,0),6) AS turnover_multiple,
           ROUND(e.freecomm_rate,6) AS free_comm_rate,
           ROUND(e.net_in/NULLIF(e.st_in,0)-e.net_out/NULLIF(e.st_out,0),8) AS roi_delta_hiturn,
           -- 五·动态层
           e.first_seen_d AS first_seen, e.last_seen_d AS last_seen,
           e.active_days, e.active_shoes, e.active_sessions,
           DATEDIFF(e.last_seen_d, e.first_seen_d)+1 AS span_days,
           ROUND(e.active_days*1.0/NULLIF(DATEDIFF(e.last_seen_d,e.first_seen_d)+1,0),6) AS persistence,
           ROUND((e.st_in/NULLIF(e.nb_in,0))/NULLIF(e.st_out/NULLIF(e.nb_out,0),0),6) AS ramp_hiturn,
           ROUND((e.st_rec/NULLIF(e.nb_rec,0))/NULLIF(e.stake/NULLIF(e.n_bets,0),0),6) AS ramp_recent,
           ROUND((e.st_rec/NULLIF(e.stake,0))/0.30,6) AS stake_ramp,
           -- 六·决策层（HF9g-P5 · D-14 斧正 —— 本件属【全窗基线族】，相对刻度与决策标签一律 NULL）
           --   病灶：x_win 系全窗单行聚合（无 GROUP BY，恒 1 行，此为设计使然，非缺陷），
           --         经 CROSS JOIN 接入后 e.* 全行同值；六层之 NTILE / PERCENT_RANK 施于常数即退化，
           --         PERCENT_RANK 恒 0 ⇒ action_priority 恒判 A，全件 100% 误标。
           --   ★ 斧正原则：不给 x_win 补 GROUP BY —— 那会改变其「全窗基线」语义，属退化。
           --     正解与 #018 之 G-05／G-06 同治：范围外之行不得接受任何下游评分与决策标签。
           --   ★ 本件之 e.* 仍照常供其它列作全窗基线使用，仅六层相对刻度与决策标签置 NULL。
           CAST(NULL AS INT)                                              AS vip_tier,                        -- 空值取值：全窗基线族无实体可分档，置 NULL（NULL＝不适用，非 0）
           CAST(NULL AS DOUBLE)                                           AS economic_value,                  -- 空值取值：同上，禁以常数百分位冒充经济价值
           CAST(NULL AS DOUBLE)                                           AS roi_pr_global,                   -- 空值取值：同上
           CAST(NULL AS DOUBLE)                                           AS risk_value,                      -- 空值取值：兼容列，同上
           CAST(NULL AS DOUBLE)                                           AS pr_stake,                        -- 空值取值：兼容列，同上
           CAST(NULL AS DOUBLE)                                           AS pr_global,                       -- 空值取值：同上
           CAST(NULL AS DOUBLE)                                           AS pr_qualified,                    -- 空值取值：同上
           'GLOBAL_BASELINE_NO_ENTITY_RANKING'                            AS pr_qualified_population,         -- 字面取值：血统 —— 明示本件为全窗基线族，无实体排序总体
           CAST(NULL AS BIGINT)                                           AS pr_global_population_n,          -- 空值取值：血统 —— 不适用
           CAST(NULL AS BIGINT)                                           AS pr_qualified_population_n,       -- 空值取值：血统 —— 不适用
           'NOT_APPLICABLE_GLOBAL_BASELINE'                               AS pr_calculation_method,           -- 字面取值：血统 —— 算法不适用
           'HF9g-P5'                                                      AS pr_calculation_version,          -- 字面取值：血统 —— 算法版本
           CAST(NULL AS STRING)                                           AS evidence_flag,                   -- 空值取值：证据旗标不适用于全窗基线
           CAST(NULL AS STRING)                                           AS evidence_rate,                   -- 空值取值：同上
           CAST(NULL AS DOUBLE)                                           AS hold_ci_halfwidth_approx,        -- 空值取值：同上
           'X 全窗基线 · 不参与实体赏罚'                                    AS action_priority                  -- 字面取值：★ D-14 斧正 —— 本族恒不入赏罚，取代原 100% 误标之「A」
    FROM q
    CROSS JOIN x_win e
  ) y
) z
-- ── 逐批 WHERE 阶梯（★ 口诀：上界 ＝ 下界 ＋ 100000，两数同进）──
--    本件 T_true 未测，无需先跑 T_true；以 0 / 100000 控制本批返回区间，末批由实际行数 < 100000 判定
--    WHERE z.audit_rn >        0 AND z.audit_rn <=   100000   -- 第 1 批
--    WHERE z.audit_rn >   100000 AND z.audit_rn <=   200000   -- 第 2 批
--    WHERE z.audit_rn >   200000 AND z.audit_rn <=   300000   -- 第 3 批
--    WHERE z.audit_rn >   300000 AND z.audit_rn <=   400000   -- 第 4 批
--    WHERE z.audit_rn >   400000 AND z.audit_rn <=   500000   -- 第 5 批
--    WHERE z.audit_rn >   500000 AND z.audit_rn <=   600000   -- 第 6 批
--    WHERE z.audit_rn >   600000 AND z.audit_rn <=   700000   -- 第 7 批
--    …余批类推。第 k 批：WHERE z.audit_rn > (k-1)*100000 AND z.audit_rn <= k*100000
--    某批返回 < 100000 行即为末批，其后不再取。
--
--    ⚠ 常见误写（务必避开）：只推下界而上界不动 ——
--        WHERE z.audit_rn > 100000 AND z.audit_rn <= 100000   ← 自相矛盾，恒为假，返回空集
--        WHERE z.audit_rn > 200000 AND z.audit_rn <= 100000   ← 同上，空集
--      两个数必须**同时**前进，且始终相差 100000。
--      下界 ＝ 上一批之上界；上界 ＝ 本批之上界。
WHERE z.audit_rn > 0 AND z.audit_rn <= 100000 -- ★ HF9c 本批区间
ORDER BY z.audit_rn;


-- ══════════════════════════════════════════════════════════════════════════════════════════════
-- 107. V_ipmatch.csv   [总包行 3017~3029 · 原 5 列 ＋六层约 60 列]
--     典型学：M04 IP 聚集　派生旗标：recent（s.x_rec = 1 · 仅供 CASE 条件聚合，全包无任何 WHERE/AND/HAVING 以此过滤）　连接：q.`ip`
-- ══════════════════════════════════════════════════════════════════════════════════════════════
-- ── ① 先跑 T_true 留档（不足 100000 者一次导全，不必分批）──
-- ── ① T_true：HF9c 不再强制预跑完整 COUNT。
--    本批实际返回行数 < 100000 即判定为末批；全批完成后以各批 n_rows / audit_rn 范围核对总量。

-- ── ② 分批取数：第 1 批。第 k 批只改末行两数为 (k-1)*100000 与 k*100000 ──
--    审计字段二（REDTEAM 2026-08-24 裁定 · 四锁）：
--      audit_rn  全局观测坐标 —— 由**与原版审计版逐字同一**之排序键所生，两版可逐行对账
--      batch_id  物理分批信息 —— 该行所属批次，由 audit_rn 算得，非引擎所赋
--    ★ 锁三：二者皆为审计字段，**不得进入任何业务指标计算**。
--    ★ 锁四：两版经 audit_rn 逐行字段核验后，方可宣布输出完全一致。

-- ── ③ 每批取回后自证四数（任一不符即停手回报，禁止放行）──
--    n_rows        = COUNT(*)      须等于 COUNT(DISTINCT audit_rn)   （批内无重复）
--    audit_rn_min  = MIN(audit_rn) 须等于 (k-1)*100000 + 1           （与上批严丝合缝）
--    audit_rn_max  = MAX(audit_rn) 须等于 min + n_rows - 1           （批内无缺口）
--    全批取毕再验：各批 audit_rn 之并集 = 1 .. T_true，无缺号、无重号。
--     ★ 首行＝平台真净亏最多者（已扣退水与代理占成）。
--
SELECT z.*,
       CAST(FLOOR((z.audit_rn - 1) / 100000) + 1 AS INT)          AS batch_id,
       'A168_HF9F_20260827_0900' AS run_id,
       '2026-08-27 09:00:00' AS snapshot_sync_time
FROM (
  SELECT y.*,
         ROW_NUMBER() OVER (ORDER BY y.`residual_b` ASC, y.`roi` DESC, y.`ip`, y.`n_member_log`, y.`country`, y.`city`, y.`in_bet_ip`) AS audit_rn
  FROM (
    WITH
      x_ranked AS (
    SELECT b.bet01, b.bet03, b.bet04, b.bet05, b.bet09, b.bet11, b.bet13,
           b.bet15, b.bet16, b.bet17, b.bet18, b.bet19, b.bet20, b.bet21,
           b.bet22, b.bet23, b.bet24, b.bet25, b.bet26, b.bet27, b.bet38, b.bet39, b.category, b.commission,
           b.dt, b.eid, b.ip, b.validbet, b.updatetime, b.sync_time,
           ROW_NUMBER() OVER (
             PARTITION BY b.bet01
             ORDER BY b.updatetime DESC, b.sync_time DESC, b.dt DESC)      AS x_rn
    FROM ods_mariadb_2b.ods_a168_bet02 b
    WHERE b.dt >= '2026-03-21' AND b.dt < '2026-08-07'
      AND b.bet02 = '101'
      AND b.sync_time <= '2026-08-27 09:00:00'
  ),
    x_testagent AS (
    SELECT age001 AS agent_id FROM ods_mariadb_2b.ods_a168_agent WHERE age022 = '1'
  ),
    x_bs0 AS (
    SELECT b.bet05 AS x_member, b.eid AS x_dealer, b.bet39 AS x_table,
           b.bet03 AS x_shoe, b.ip AS x_ip, b.bet09 AS x_product, b.dt AS x_date,
           CONCAT_WS('|', b.bet03, b.bet04, b.bet39)                      AS x_round,
           CONCAT_WS('|', b.bet39, b.bet03)                               AS x_tblshoe,
           CAST(NULLIF(TRIM(b.bet04),'') AS INT)                          AS x_rno,
           CASE WHEN b.dt >= '2026-07-08' THEN 1 ELSE 0 END               AS x_rec,
           CASE WHEN TRIM(b.commission)='1' THEN 1 ELSE 0 END             AS x_freecomm,
           CAST(NULLIF(TRIM(b.bet13),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_stake,
           CAST(NULLIF(TRIM(b.validbet),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_valid,
           CAST(NULLIF(TRIM(b.bet16),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_rebate,
           CAST(NULLIF(TRIM(b.bet17),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_net,
           CAST(NULLIF(TRIM(b.bet15),'') AS DECIMAL(20,6))                AS x_rbpct,
           COALESCE(CAST(NULLIF(TRIM(b.bet23),'') AS DECIMAL(20,6)),0)   AS x_agpct,
          NULLIF(CAST(NULLIF(TRIM(b.bet23),'') AS DECIMAL(20,6)),0)     AS x_rate1,
          NULLIF(CAST(NULLIF(TRIM(b.bet24),'') AS DECIMAL(20,6)),0)     AS x_rate2,
          NULLIF(CAST(NULLIF(TRIM(b.bet25),'') AS DECIMAL(20,6)),0)     AS x_rate3,
          NULLIF(CAST(NULLIF(TRIM(b.bet26),'') AS DECIMAL(20,6)),0)     AS x_rate4,
          NULLIF(CAST(NULLIF(TRIM(b.bet27),'') AS DECIMAL(20,6)),0)     AS x_rate5,
          (CASE WHEN NULLIF(CAST(NULLIF(TRIM(b.bet22),'') AS BIGINT),0) IS NOT NULL THEN 5
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet21),'') AS BIGINT),0) IS NOT NULL THEN 4
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet20),'') AS BIGINT),0) IS NOT NULL THEN 3
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet19),'') AS BIGINT),0) IS NOT NULL THEN 2
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet18),'') AS BIGINT),0) IS NOT NULL THEN 1
                ELSE 0 END)                                             AS x_chain_depth,
           CASE WHEN COALESCE(t1.agent_id,t2.agent_id,t3.agent_id,
                              t4.agent_id,t5.agent_id) IS NOT NULL
                THEN 1 ELSE 0 END                                        AS f_testline
    FROM x_ranked b
    LEFT JOIN x_testagent t1 ON t1.agent_id = b.bet18
    LEFT JOIN x_testagent t2 ON t2.agent_id = b.bet19
    LEFT JOIN x_testagent t3 ON t3.agent_id = b.bet20
    LEFT JOIN x_testagent t4 ON t4.agent_id = b.bet21
    LEFT JOIN x_testagent t5 ON t5.agent_id = b.bet22
    WHERE b.x_rn = 1
      AND b.category='1' AND UPPER(TRIM(b.bet38))='N'
      AND CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8)) > 0
  ),
  x_mk AS (
    SELECT s.*,
           CASE WHEN s.f_testline = 0 THEN 1 ELSE 0 END                 AS is_clean
    FROM x_bs0 s
  ),
  x_agg AS (
    SELECT s.x_ip                                                        AS x_key,
           COUNT(*) AS n_bets, COUNT(DISTINCT s.x_round) AS n_rounds,
           COUNT(DISTINCT s.x_date) AS active_days, COUNT(DISTINCT s.x_tblshoe) AS active_shoes,
           COUNT(DISTINCT CONCAT_WS('|', s.x_date, s.x_table)) AS active_sessions,
           COUNT(DISTINCT s.x_table) AS n_tables, COUNT(DISTINCT s.x_dealer) AS n_dealers,
           COUNT(DISTINCT s.x_ip) AS n_ips, COUNT(DISTINCT s.x_product) AS n_products,
           MIN(s.x_date) AS first_seen_d, MAX(s.x_date) AS last_seen_d,
           SUM(s.x_stake) AS stake, SUM(s.x_valid) AS valid, SUM(s.x_rebate) AS rebate,
           SUM(s.x_net) AS net, SUM(-s.x_net *(100.0-s.x_agpct)/100.0) AS agent_cost,
           AVG(100.0-s.x_agpct)                   AS agent_pct,
           AVG(s.x_agpct)                         AS company_retain_pct,
           SUM(-s.x_net *s.x_agpct/100.0)         AS agent_cost_a_legacy,
           SUM(s.x_valid*s.x_agpct/100.0)         AS agent_cost_valid_base_legacy,
          AVG(COALESCE(s.x_rate1,100)) AS retain_pct_lv1, AVG(COALESCE(s.x_rate2,100)) AS retain_pct_lv2,
          AVG(COALESCE(s.x_rate3,100)) AS retain_pct_lv3, AVG(COALESCE(s.x_rate4,100)) AS retain_pct_lv4,
          AVG(COALESCE(s.x_rate5,100)) AS retain_pct_lv5, AVG(s.x_chain_depth) AS chain_depth_avg,
          AVG(COALESCE(100.0-s.x_rate1,0)) AS agent_pct_lv1, AVG(COALESCE(100.0-s.x_rate2,0)) AS agent_pct_lv2,
          AVG(COALESCE(100.0-s.x_rate3,0)) AS agent_pct_lv3, AVG(COALESCE(100.0-s.x_rate4,0)) AS agent_pct_lv4,
          AVG(COALESCE(100.0-s.x_rate5,0)) AS agent_pct_lv5,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate1,0)/100.0)                        AS agent_cost_lv1,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate2,0)/100.0)                        AS agent_cost_lv2,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate3,0)/100.0)                        AS agent_cost_lv3,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate4,0)/100.0)                        AS agent_cost_lv4,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate5,0)/100.0)                        AS agent_cost_lv5,
          SUM(-s.x_net*(COALESCE(100.0-s.x_rate1,0)+COALESCE(100.0-s.x_rate2,0)
                       +COALESCE(100.0-s.x_rate3,0)+COALESCE(100.0-s.x_rate4,0)
                       +COALESCE(100.0-s.x_rate5,0))/100.0)                   AS agent_cost_chain_additive,
          SUM(-s.x_net*(1.0 - CAST(COALESCE(s.x_rate1,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate2,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate3,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate4,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate5,100) AS DOUBLE)/100.0))
                                                                       AS agent_cost_chain_nested,
           AVG(s.x_rbpct) AS rbpct, AVG(s.x_freecomm*1.0) AS freecomm_rate,
           PERCENTILE_APPROX(s.x_stake,0.25) AS p25, PERCENTILE_APPROX(s.x_stake,0.50) AS p50,
           PERCENTILE_APPROX(s.x_stake,0.75) AS p75, PERCENTILE_APPROX(s.x_stake,0.90) AS p90,
           PERCENTILE_APPROX(s.x_stake,0.95) AS p95, PERCENTILE_APPROX(s.x_stake,0.99) AS p99,
           PERCENTILE_APPROX(s.x_valid,0.50) AS p50_valid,
           PERCENTILE_APPROX(s.x_net,0.50)   AS p50_profit,
           SUM(CASE WHEN s.x_rec = 1 THEN s.x_stake ELSE 0 END) AS st_in,
           SUM(CASE WHEN s.x_rec = 1 THEN 1 ELSE 0 END)         AS nb_in,
           SUM(CASE WHEN s.x_rec = 1 THEN s.x_net ELSE 0 END)   AS net_in,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN s.x_stake ELSE 0 END) AS st_out,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN 1 ELSE 0 END)         AS nb_out,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN s.x_net ELSE 0 END)   AS net_out,
           SUM(CASE WHEN s.x_rec=1 THEN s.x_stake ELSE 0 END) AS st_rec,
           SUM(CASE WHEN s.x_rec=1 THEN 1 ELSE 0 END)         AS nb_rec
    FROM x_mk s
    WHERE s.is_clean = 1
      AND s.x_ip IS NOT NULL AND TRIM(CAST(s.x_ip AS STRING)) <> ''
    GROUP BY s.x_ip
  ),
      q AS (
        WITH a AS (SELECT DISTINCT TRIM(ip) AS ip FROM ods_mariadb_2b.ods_a168_bet02                        -- 公共表表达式：取用注单明细表（金额与行为口径的第一料源），产出「ip」
                   WHERE dt>='2026-03-21' AND dt<'2026-08-07' AND bet02='101'                               -- 过滤条件：限定 dt不少于 '2026-03-21'、dt小于 '2026-08-07'、bet02等于 '101'，涉 bet02（游戏类别）、dt（营业日）
                     AND sync_time <= '2026-08-27 09:00:00'
                     AND NULLIF(TRIM(ip),'') IS NOT NULL),                                                  -- 并列条件：限定该值非空
             b AS (SELECT TRIM(ip) AS ip, COUNT(DISTINCT mid) AS n_member_log,                              -- 取值表达式：统计去重个数，产出「n_member_log」
                          MAX(country_code) AS country, MAX(city) AS city                                   -- 取最大值表达式：产出「city」
                   FROM ods_mariadb_2b.ods_a168_game_log                                                    -- 取数来源：取自局流水日志（局级过程记录）
                   WHERE dt>='2026-03-21' AND dt<'2026-08-07'                                               -- 过滤条件：限定 dt不少于 '2026-03-21'、dt小于 '2026-08-07'，涉 dt（营业日）
                     AND NULLIF(TRIM(ip),'') IS NOT NULL                                                    -- 并列条件：限定该值非空
                   GROUP BY TRIM(ip))                                                                       -- 分组：按 TRIM(ip)) 汇总
        SELECT b.ip, b.n_member_log, b.country, b.city,                                                     -- 取列：起始取列子句，本行先列 b.ip, b.n_member_log, b.country, b.city
               CASE WHEN a.ip IS NULL THEN 0 ELSE 1 END AS in_bet_ip                                        -- 条件分支：产出「in_bet_ip」
        FROM b LEFT JOIN a ON a.ip=b.ip                                                                     -- 取数来源：取自本条自建的中间结果集 b，连接键为 a.ip=b.ip
      )
    SELECT q.*,
           -- 一·经济层
           ROUND(e.stake,4) AS stake, ROUND(e.valid,4) AS valid_bet,
           ROUND(-e.net,4) AS profit, e.n_bets, e.n_rounds,
           ROUND(e.net/NULLIF(e.stake,0),8) AS roi,
           ROUND(e.net_in/NULLIF(e.st_in,0),8) AS roi_recent,
           ROUND(e.net_out/NULLIF(e.st_out,0),8) AS roi_non_recent,
           ROUND((e.net-e.rebate)/NULLIF(e.stake,0),8) AS roi_ex_rebate,
           ROUND(e.net,4) AS roi_numerator, ROUND(e.stake,4) AS roi_denominator,
           CASE WHEN e.stake IS NULL THEN 'NULL_DENOM' WHEN e.stake<=0 THEN 'ZERO_DENOM'
                WHEN e.n_bets<30 THEN 'THIN_EXPOSURE' ELSE 'OK' END AS roi_denominator_status,
           ROUND(e.rebate,4) AS rebate_cost, ROUND(e.agent_cost,4)                           AS cost_complement_b,
       ROUND(e.agent_pct,4)                            AS pct_complement,
       ROUND(e.company_retain_pct,4)                   AS pct_top_bet23,
       'AG03-UNRESOLVED'                                     AS agent_formula_version,
      'ALL5_LEVELS_bet23_to_bet27'                    AS agent_level_scope,
      ROUND(e.agent_cost_lv1,4) AS agent_cost_lv1, ROUND(e.agent_cost_lv2,4) AS agent_cost_lv2,
      ROUND(e.agent_cost_lv3,4) AS agent_cost_lv3, ROUND(e.agent_cost_lv4,4) AS agent_cost_lv4,
      ROUND(e.agent_cost_lv5,4) AS agent_cost_lv5,
      ROUND(e.agent_pct_lv1,6) AS agent_pct_lv1, ROUND(e.agent_pct_lv2,6) AS agent_pct_lv2,
      ROUND(e.agent_pct_lv3,6) AS agent_pct_lv3, ROUND(e.agent_pct_lv4,6) AS agent_pct_lv4,
      ROUND(e.agent_pct_lv5,6) AS agent_pct_lv5,
      ROUND(e.retain_pct_lv1,6) AS retain_pct_lv1, ROUND(e.retain_pct_lv2,6) AS retain_pct_lv2,
      ROUND(e.retain_pct_lv3,6) AS retain_pct_lv3, ROUND(e.retain_pct_lv4,6) AS retain_pct_lv4,
      ROUND(e.retain_pct_lv5,6) AS retain_pct_lv5, ROUND(e.chain_depth_avg,4) AS chain_depth_avg,
      ROUND(e.agent_cost_chain_additive,4)            AS agent_cost_chain_additive,
      ROUND(e.agent_cost_chain_nested,4)              AS agent_cost_chain_nested,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_additive,4) AS residual_chain_additive,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_nested,4)   AS residual_chain_nested,
      'PENDING_AG03'                                  AS decision_status,
      'FALSE'                                         AS admit_to_risk_decision,
      'NOT_FOR_ENFORCEMENT'                           AS deliverable_class,
       ROUND(e.agent_cost_a_legacy,4)                  AS agent_cost_a_legacy,
       ROUND(e.agent_cost_valid_base_legacy,4)         AS agent_cost_valid_base_legacy,
           ROUND(-e.net-e.rebate,4)                        AS ngr,
       ROUND(-e.net-e.rebate-e.agent_cost,4)           AS residual_b,
       ROUND(-e.net-e.rebate-e.agent_cost_a_legacy,4)  AS residual_a,
           ROUND((-e.net-e.rebate)/NULLIF(e.stake,0),8)    AS ngr_rate,
       ROUND((-e.net-e.rebate-e.agent_cost)/NULLIF(e.stake,0),8)   AS residual_b_rate,
      -- 【HF9c · canonical accounting contract】
      --   以下 canonical 字段只增加明确 scope；不删除、不覆盖既有字段。
      --   formal_bet23_* 保持 HF9b 当前生产公式及其 NULL/0 语义；
      --   lv1~lv5 / additive / nested 则分别采用各自原始 e.* 成本字段，
      --   rate 一律从未舍入的 e.* 分子 / e.stake 计算，禁止由展示值反算。
      ROUND(e.agent_cost,4) AS agent_cost_bet23_formal_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost,4) AS net_margin_bet23_formal_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost)/NULLIF(e.stake,0),8) AS net_margin_bet23_formal_rate_canonical,
      ROUND(e.agent_cost_lv1,4) AS agent_cost_lv1_bet23_canonical,
      ROUND(e.agent_cost_lv2,4) AS agent_cost_lv2_bet24_canonical,
      ROUND(e.agent_cost_lv3,4) AS agent_cost_lv3_bet25_canonical,
      ROUND(e.agent_cost_lv4,4) AS agent_cost_lv4_bet26_canonical,
      ROUND(e.agent_cost_lv5,4) AS agent_cost_lv5_bet27_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_lv1,4) AS net_margin_lv1_bet23_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_lv1)/NULLIF(e.stake,0),8) AS net_margin_lv1_bet23_rate_canonical,
      ROUND(e.agent_cost_chain_additive,4) AS agent_cost_chain_additive_canonical,
      ROUND(e.agent_cost_chain_nested,4) AS agent_cost_chain_nested_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_additive,4) AS net_margin_chain_additive_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_nested,4) AS net_margin_chain_nested_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_chain_additive)/NULLIF(e.stake,0),8) AS net_margin_chain_additive_rate_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_chain_nested)/NULLIF(e.stake,0),8) AS net_margin_chain_nested_rate_canonical,
       ROUND((-e.net-e.rebate-e.agent_cost_a_legacy)/NULLIF(e.stake,0),8) AS residual_a_rate,
           -- 二·分布层
           ROUND(e.stake/NULLIF(e.n_bets,0),4) AS avg_stake_per_bet,
           ROUND(e.valid/NULLIF(e.n_rounds,0),4) AS avg_valid_bet_per_round,
           ROUND(-e.net/NULLIF(e.n_rounds,0),4) AS avg_profit_per_round,
           ROUND(-e.net/NULLIF(e.active_days,0),4) AS avg_profit_per_day,
           ROUND(-e.net/NULLIF(e.active_shoes,0),4) AS avg_profit_per_shoe,
           ROUND(e.stake/NULLIF(e.active_days,0),4) AS avg_stake_per_active_day,
           ROUND(e.n_rounds*1.0/NULLIF(e.active_days,0),4) AS avg_rounds_per_active_day,
           ROUND(e.st_in/NULLIF(e.nb_in,0),4) AS avg_stake_recent,
           ROUND(e.st_out/NULLIF(e.nb_out,0),4) AS avg_stake_non_recent,
           ROUND(e.p25,4) AS p25_stake, ROUND(e.p50,4) AS p50_stake, ROUND(e.p75,4) AS p75_stake,
           ROUND(e.p90,4) AS p90_stake, ROUND(e.p95,4) AS p95_stake, ROUND(e.p99,4) AS p99_stake,
           ROUND(e.p50_valid,4) AS p50_valid_bet, ROUND(e.p50_profit,4) AS p50_profit,
           ROUND(e.p95/NULLIF(e.p50,0),6) AS p95_over_p50,
           ROUND(e.p99/NULLIF(e.p50,0),6) AS p99_over_p50,
           ROUND((e.stake/NULLIF(e.n_bets,0))/NULLIF(e.p50,0),6) AS avg_over_p50,
           -- 三·关系层
           e.n_tables AS common_table_count, e.n_dealers AS common_dealer_count,
           e.n_ips AS common_ip_count, e.n_products AS common_product_count,
           ROUND(e.st_in/NULLIF(e.stake,0),8) AS share_recent,
           -- 四·rate 层
           ROUND(-e.net/NULLIF(e.stake,0),8) AS hold_rate,
           ROUND(-e.net_in/NULLIF(e.st_in,0),8) AS hold_rate_recent,
           ROUND(e.rebate/NULLIF(e.valid,0),8) AS rebate_rate_actual,
           ROUND(e.rbpct,6) AS rebate_pct_config,
           ROUND(e.valid/NULLIF(e.stake,0),6) AS turnover_multiple,
           ROUND(e.freecomm_rate,6) AS free_comm_rate,
           ROUND(e.net_in/NULLIF(e.st_in,0)-e.net_out/NULLIF(e.st_out,0),8) AS roi_delta_recent,
           -- 五·动态层
           e.first_seen_d AS first_seen, e.last_seen_d AS last_seen,
           e.active_days, e.active_shoes, e.active_sessions,
           DATEDIFF(e.last_seen_d, e.first_seen_d)+1 AS span_days,
           ROUND(e.active_days*1.0/NULLIF(DATEDIFF(e.last_seen_d,e.first_seen_d)+1,0),6) AS persistence,
           ROUND((e.st_in/NULLIF(e.nb_in,0))/NULLIF(e.st_out/NULLIF(e.nb_out,0),0),6) AS ramp_recent_vs_prior,
           ROUND((e.st_rec/NULLIF(e.nb_rec,0))/NULLIF(e.stake/NULLIF(e.n_bets,0),0),6) AS ramp_recent_vs_all,
           ROUND((e.st_rec/NULLIF(e.stake,0))/0.30,6) AS stake_ramp,
           -- 六·决策层（HF9f · 详见档头【HF9f 变更说明】；本段两版逐字同一）
           NTILE(5) OVER (ORDER BY e.stake) AS vip_tier,                                                        -- 窗口取值：相对刻度 B 族，全体五等分；须连同下方血统五元组一并解读，禁作硬阈值判型
           PERCENT_RANK() OVER (ORDER BY -e.net-e.rebate-e.agent_cost)    AS economic_value,                    -- 窗口取值：HF9f·F-19 修正 —— HF9e 写作 -(-…) 双负号致方向颠倒（#075 实测 corr(economic_value, residual_b) = -1.0000）；今与 action_priority 排序键归一，值大即平台真净利高
           PERCENT_RANK() OVER (ORDER BY e.net/NULLIF(e.stake,0))         AS roi_pr_global,                     -- 窗口取值：HF9f·F-17 正名 —— 本列实为 ROI（玩家净回报率）之全体百分位，与「风险」无关；旧名 risk_value 见下一行
           PERCENT_RANK() OVER (ORDER BY e.net/NULLIF(e.stake,0))         AS risk_value,                        -- 窗口取值：兼容列，恒等于 roi_pr_global，仅为下游迁移窗保留；HF9g 起废弃，禁新引用
           PERCENT_RANK() OVER (ORDER BY e.stake)                         AS pr_stake,                          -- 窗口取值：兼容列，恒等于 pr_global，原名保留以免断链
           PERCENT_RANK() OVER (ORDER BY e.stake)                         AS pr_global,                         -- 窗口取值：HF9f·F-1 双轨之一 —— 全体口径百分位，参照总体即本件全部输出行
           CASE WHEN e.n_rounds >= 30                                                                           -- 条件分支：起始分支 —— 仅在合格子集内计算合格口径百分位
                  THEN PERCENT_RANK() OVER (PARTITION BY CASE WHEN e.n_rounds >= 30 THEN 1 ELSE 0 END ORDER BY e.stake)  -- 分支取值：以合格与否分区，故本值即 n_rounds>=30 子集内之百分位
                ELSE NULL END                                             AS pr_qualified,                      -- 条件分支：收束上方分支 —— 不合格者留 NULL（NULL＝未测，非 0），产出「pr_qualified」
           'n_rounds>=30'                                                 AS pr_qualified_population,           -- 字面取值：血统 —— 合格子集之定义
           COUNT(*) OVER ()                                               AS pr_global_population_n,            -- 窗口取值：血统 —— 全体口径之参照总体规模，渲染时现算，禁写死
           SUM(CASE WHEN e.n_rounds >= 30 THEN 1 ELSE 0 END) OVER ()      AS pr_qualified_population_n,         -- 窗口取值：血统 —— 合格子集之参照总体规模，现算，禁写死
           'PERCENT_RANK_OVER_ORDER_BY_e_stake'                           AS pr_calculation_method,             -- 字面取值：血统 —— 算法标识
           'HF9f'                                                         AS pr_calculation_version,            -- 字面取值：血统 —— 算法版本
           CASE WHEN e.n_rounds IS NULL OR e.n_rounds < 30 THEN 'THIN_ROUNDS' ELSE 'OK' END AS evidence_flag,   -- 条件分支：HF9f·F-2a 证据旗标 —— THIN_ROUNDS 者禁入执行队列，仅入观察队列
           CASE WHEN e.n_rounds IS NULL       THEN NULL                                                         -- 条件分支：起始分支 —— 未测者留 NULL（自家铁律：NULL ≠ 0）
                WHEN e.n_rounds >= 31483      THEN 'L1_POWERED'                                                 -- 分支判定：MDE 反解第一档
                WHEN e.n_rounds >= 15409      THEN 'L2_CI_1P5'                                                  -- 分支判定：MDE 反解第二档
                WHEN e.n_rounds >=  8668      THEN 'L3_CI_2P0'                                                  -- 分支判定：MDE 反解第三档
                WHEN e.n_rounds >=  3852      THEN 'L4_CI_3P0'                                                  -- 分支判定：MDE 反解第四档
                ELSE 'L5_INSUFFICIENT' END                                AS evidence_rate,                     -- 条件分支：收束上方 —— HF9f·F-3 证据分档，承 HF9e 前议之 MDE 反解五档，须于 F-4 敏感性实验后复核
           ROUND(1.96 * 0.95 / SQRT(NULLIF(CAST(e.n_rounds AS DOUBLE),0)),8) AS hold_ci_halfwidth_approx,       -- 比率表达式：HF9f·F-3 逐行现算之 95% 半宽近似；常数 0.95 为登记值，本轮 #075 实测每局 ROI 隐含 σ 于最薄层为 0.9249，二者差异待 F-4 裁定
           CASE WHEN e.stake IS NULL OR e.stake<=0 OR e.n_bets<30 OR e.n_rounds IS NULL OR e.n_rounds<30 THEN 'Z 证据不足 · 不动作'  -- 条件分支：HF9f·F-2 双条件取严 —— HF9e 仅卡 e.n_bets<30，致 n_bets>=30 而 n_rounds<30 者绕过 Z（#075 实测 18,537 名，其中 8,145 名已入 A/D 待裁）；今两条件并列取严
                WHEN PERCENT_RANK() OVER (ORDER BY -e.net-e.rebate-e.agent_cost)<=0.10                          -- 分支判定：平台真净利之最低十分位
                  THEN 'A 净亏最大十分位 · 优先复核'                                                             -- 分支取值：HF9f·F-20 正名 —— 本档 Σresidual_b 于 #075 实测 = -100,236,896，系平台净亏最大群，旧名「残值最低十分位 · 待裁」名实不符
                WHEN PERCENT_RANK() OVER (ORDER BY -e.net-e.rebate-e.agent_cost)>=0.80                          -- 分支判定：平台真净利之最高二十分位
                  THEN 'D 净利最高二十分位 · 优先留存'                                                           -- 分支取值：HF9f·F-20 正名 —— 本档 Σresidual_b 于 #075 实测 = +281,733,190，系核心利润源；与 A 档方向相反，旧版同标「待裁」属名实不符
                ELSE 'E 常规' END                                          AS action_priority                   -- 条件分支：收束上方判词，产出「action_priority」
    FROM q
    LEFT JOIN x_agg e ON CAST(e.x_key AS STRING) = CAST(q.`ip` AS STRING)
  ) y
) z
-- ── 逐批 WHERE 阶梯（★ 口诀：上界 ＝ 下界 ＋ 100000，两数同进）──
--    本件 T_true 未测，无需先跑 T_true；以 0 / 100000 控制本批返回区间，末批由实际行数 < 100000 判定
--    WHERE z.audit_rn >        0 AND z.audit_rn <=   100000   -- 第 1 批
--    WHERE z.audit_rn >   100000 AND z.audit_rn <=   200000   -- 第 2 批
--    WHERE z.audit_rn >   200000 AND z.audit_rn <=   300000   -- 第 3 批
--    WHERE z.audit_rn >   300000 AND z.audit_rn <=   400000   -- 第 4 批
--    WHERE z.audit_rn >   400000 AND z.audit_rn <=   500000   -- 第 5 批
--    WHERE z.audit_rn >   500000 AND z.audit_rn <=   600000   -- 第 6 批
--    WHERE z.audit_rn >   600000 AND z.audit_rn <=   700000   -- 第 7 批
--    …余批类推。第 k 批：WHERE z.audit_rn > (k-1)*100000 AND z.audit_rn <= k*100000
--    某批返回 < 100000 行即为末批，其后不再取。
--
--    ⚠ 常见误写（务必避开）：只推下界而上界不动 ——
--        WHERE z.audit_rn > 100000 AND z.audit_rn <= 100000   ← 自相矛盾，恒为假，返回空集
--        WHERE z.audit_rn > 200000 AND z.audit_rn <= 100000   ← 同上，空集
--      两个数必须**同时**前进，且始终相差 100000。
--      下界 ＝ 上一批之上界；上界 ＝ 本批之上界。
WHERE z.audit_rn > 0 AND z.audit_rn <= 100000 -- ★ HF9c 本批区间
ORDER BY z.audit_rn;


-- ══════════════════════════════════════════════════════════════════════════════════════════════
-- 108. V_recon.csv   [总包行 1506~1576 · 原 12 列 ＋六层约 60 列]
--     典型学：Z00 基建/元数据　派生旗标：recent（s.x_rec = 1 · 仅供 CASE 条件聚合，全包无任何 WHERE/AND/HAVING 以此过滤）　连接：全窗基线
-- ══════════════════════════════════════════════════════════════════════════════════════════════
-- ★ W-64 · D-14 警示（本件属 x_win 族 · 66 件之一 · 详见 §Z 段 D-14 全案）
--   本件以 `CROSS JOIN x_win e` 接入全局基线，x_win 无 GROUP BY ⇒ 恒 1 行 ⇒ e.* 全行同值。
--   故：economic_value / roi_pr_global / risk_value / pr_stake / pr_global 恒为 0；
--       action_priority 每一行皆为「A 净亏最大十分位 · 优先复核」（Z 分支永不触发）；
--       evidence_rate 恒为最高档；vip_tier 由常数键分档 ⇒ 无信息且非确定。
--   ⇒ 本件决策层三列 **NOT_FOR_DECISION**，裁定前不得用于排班、抽查或汇报。
-- ── ① 先跑 T_true 留档（不足 100000 者一次导全，不必分批）──
-- ── ① T_true：HF9c 不再强制预跑完整 COUNT。
--    本批实际返回行数 < 100000 即判定为末批；全批完成后以各批 n_rows / audit_rn 范围核对总量。

-- ── ② 分批取数：第 1 批。第 k 批只改末行两数为 (k-1)*100000 与 k*100000 ──
--    审计字段二（REDTEAM 2026-08-24 裁定 · 四锁）：
--      audit_rn  全局观测坐标 —— 由**与原版审计版逐字同一**之排序键所生，两版可逐行对账
--      batch_id  物理分批信息 —— 该行所属批次，由 audit_rn 算得，非引擎所赋
--    ★ 锁三：二者皆为审计字段，**不得进入任何业务指标计算**。
--    ★ 锁四：两版经 audit_rn 逐行字段核验后，方可宣布输出完全一致。

-- ── ③ 每批取回后自证四数（任一不符即停手回报，禁止放行）──
--    n_rows        = COUNT(*)      须等于 COUNT(DISTINCT audit_rn)   （批内无重复）
--    audit_rn_min  = MIN(audit_rn) 须等于 (k-1)*100000 + 1           （与上批严丝合缝）
--    audit_rn_max  = MAX(audit_rn) 须等于 min + n_rows - 1           （批内无缺口）
--    全批取毕再验：各批 audit_rn 之并集 = 1 .. T_true，无缺号、无重号。
--     ★ 首行＝平台真净亏最多者（已扣退水与代理占成）。
--
SELECT z.*,
       CAST(FLOOR((z.audit_rn - 1) / 100000) + 1 AS INT)          AS batch_id,
       'A168_HF9F_20260827_0900' AS run_id,
       '2026-08-27 09:00:00' AS snapshot_sync_time
FROM (
  SELECT y.*,
         ROW_NUMBER() OVER (ORDER BY y.`residual_b` ASC, y.`roi` DESC, y.`n_matched_round`, y.`mae_turnover`, y.`mae_rebate`, y.`mae_net`, y.`scale_turnover`, y.`scale_rebate`, y.`scale_net`, y.`mase_turnover`, y.`mase_rebate`, y.`mase_net`, y.`pct_exact_turnover`, y.`pct_exact_net`) AS audit_rn
  FROM (
    WITH
      x_ranked AS (
    SELECT b.bet01, b.bet03, b.bet04, b.bet05, b.bet09, b.bet11, b.bet13,
           b.bet15, b.bet16, b.bet17, b.bet18, b.bet19, b.bet20, b.bet21,
           b.bet22, b.bet23, b.bet24, b.bet25, b.bet26, b.bet27, b.bet38, b.bet39, b.category, b.commission,
           b.dt, b.eid, b.ip, b.validbet, b.updatetime, b.sync_time,
           ROW_NUMBER() OVER (
             PARTITION BY b.bet01
             ORDER BY b.updatetime DESC, b.sync_time DESC, b.dt DESC)      AS x_rn
    FROM ods_mariadb_2b.ods_a168_bet02 b
    WHERE b.dt >= '2026-03-21' AND b.dt < '2026-08-07'
      AND b.bet02 = '101'
      AND b.sync_time <= '2026-08-27 09:00:00'
  ),
    x_testagent AS (
    SELECT age001 AS agent_id FROM ods_mariadb_2b.ods_a168_agent WHERE age022 = '1'
  ),
    x_bs0 AS (
    SELECT b.bet05 AS x_member, b.eid AS x_dealer, b.bet39 AS x_table,
           b.bet03 AS x_shoe, b.ip AS x_ip, b.bet09 AS x_product, b.dt AS x_date,
           CONCAT_WS('|', b.bet03, b.bet04, b.bet39)                      AS x_round,
           CONCAT_WS('|', b.bet39, b.bet03)                               AS x_tblshoe,
           CAST(NULLIF(TRIM(b.bet04),'') AS INT)                          AS x_rno,
           CASE WHEN b.dt >= '2026-07-08' THEN 1 ELSE 0 END               AS x_rec,
           CASE WHEN TRIM(b.commission)='1' THEN 1 ELSE 0 END             AS x_freecomm,
           CAST(NULLIF(TRIM(b.bet13),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_stake,
           CAST(NULLIF(TRIM(b.validbet),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_valid,
           CAST(NULLIF(TRIM(b.bet16),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_rebate,
           CAST(NULLIF(TRIM(b.bet17),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_net,
           CAST(NULLIF(TRIM(b.bet15),'') AS DECIMAL(20,6))                AS x_rbpct,
           COALESCE(CAST(NULLIF(TRIM(b.bet23),'') AS DECIMAL(20,6)),0)   AS x_agpct,
          NULLIF(CAST(NULLIF(TRIM(b.bet23),'') AS DECIMAL(20,6)),0)     AS x_rate1,
          NULLIF(CAST(NULLIF(TRIM(b.bet24),'') AS DECIMAL(20,6)),0)     AS x_rate2,
          NULLIF(CAST(NULLIF(TRIM(b.bet25),'') AS DECIMAL(20,6)),0)     AS x_rate3,
          NULLIF(CAST(NULLIF(TRIM(b.bet26),'') AS DECIMAL(20,6)),0)     AS x_rate4,
          NULLIF(CAST(NULLIF(TRIM(b.bet27),'') AS DECIMAL(20,6)),0)     AS x_rate5,
          (CASE WHEN NULLIF(CAST(NULLIF(TRIM(b.bet22),'') AS BIGINT),0) IS NOT NULL THEN 5
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet21),'') AS BIGINT),0) IS NOT NULL THEN 4
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet20),'') AS BIGINT),0) IS NOT NULL THEN 3
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet19),'') AS BIGINT),0) IS NOT NULL THEN 2
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet18),'') AS BIGINT),0) IS NOT NULL THEN 1
                ELSE 0 END)                                             AS x_chain_depth,
           CASE WHEN COALESCE(t1.agent_id,t2.agent_id,t3.agent_id,
                              t4.agent_id,t5.agent_id) IS NOT NULL
                THEN 1 ELSE 0 END                                        AS f_testline
    FROM x_ranked b
    LEFT JOIN x_testagent t1 ON t1.agent_id = b.bet18
    LEFT JOIN x_testagent t2 ON t2.agent_id = b.bet19
    LEFT JOIN x_testagent t3 ON t3.agent_id = b.bet20
    LEFT JOIN x_testagent t4 ON t4.agent_id = b.bet21
    LEFT JOIN x_testagent t5 ON t5.agent_id = b.bet22
    WHERE b.x_rn = 1
      AND b.category='1' AND UPPER(TRIM(b.bet38))='N'
      AND CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8)) > 0
  ),
  x_mk AS (
    SELECT s.*,
           CASE WHEN s.f_testline = 0 THEN 1 ELSE 0 END                 AS is_clean
    FROM x_bs0 s
  ),
  x_agg AS (
    SELECT s.x_member                                                        AS x_key,
           COUNT(*) AS n_bets, COUNT(DISTINCT s.x_round) AS n_rounds,
           COUNT(DISTINCT s.x_date) AS active_days, COUNT(DISTINCT s.x_tblshoe) AS active_shoes,
           COUNT(DISTINCT CONCAT_WS('|', s.x_date, s.x_table)) AS active_sessions,
           COUNT(DISTINCT s.x_table) AS n_tables, COUNT(DISTINCT s.x_dealer) AS n_dealers,
           COUNT(DISTINCT s.x_ip) AS n_ips, COUNT(DISTINCT s.x_product) AS n_products,
           MIN(s.x_date) AS first_seen_d, MAX(s.x_date) AS last_seen_d,
           SUM(s.x_stake) AS stake, SUM(s.x_valid) AS valid, SUM(s.x_rebate) AS rebate,
           SUM(s.x_net) AS net, SUM(-s.x_net *(100.0-s.x_agpct)/100.0) AS agent_cost,
           AVG(100.0-s.x_agpct)                   AS agent_pct,
           AVG(s.x_agpct)                         AS company_retain_pct,
           SUM(-s.x_net *s.x_agpct/100.0)         AS agent_cost_a_legacy,
           SUM(s.x_valid*s.x_agpct/100.0)         AS agent_cost_valid_base_legacy,
          AVG(COALESCE(s.x_rate1,100)) AS retain_pct_lv1, AVG(COALESCE(s.x_rate2,100)) AS retain_pct_lv2,
          AVG(COALESCE(s.x_rate3,100)) AS retain_pct_lv3, AVG(COALESCE(s.x_rate4,100)) AS retain_pct_lv4,
          AVG(COALESCE(s.x_rate5,100)) AS retain_pct_lv5, AVG(s.x_chain_depth) AS chain_depth_avg,
          AVG(COALESCE(100.0-s.x_rate1,0)) AS agent_pct_lv1, AVG(COALESCE(100.0-s.x_rate2,0)) AS agent_pct_lv2,
          AVG(COALESCE(100.0-s.x_rate3,0)) AS agent_pct_lv3, AVG(COALESCE(100.0-s.x_rate4,0)) AS agent_pct_lv4,
          AVG(COALESCE(100.0-s.x_rate5,0)) AS agent_pct_lv5,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate1,0)/100.0)                        AS agent_cost_lv1,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate2,0)/100.0)                        AS agent_cost_lv2,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate3,0)/100.0)                        AS agent_cost_lv3,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate4,0)/100.0)                        AS agent_cost_lv4,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate5,0)/100.0)                        AS agent_cost_lv5,
          SUM(-s.x_net*(COALESCE(100.0-s.x_rate1,0)+COALESCE(100.0-s.x_rate2,0)
                       +COALESCE(100.0-s.x_rate3,0)+COALESCE(100.0-s.x_rate4,0)
                       +COALESCE(100.0-s.x_rate5,0))/100.0)                   AS agent_cost_chain_additive,
          SUM(-s.x_net*(1.0 - CAST(COALESCE(s.x_rate1,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate2,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate3,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate4,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate5,100) AS DOUBLE)/100.0))
                                                                       AS agent_cost_chain_nested,
           AVG(s.x_rbpct) AS rbpct, AVG(s.x_freecomm*1.0) AS freecomm_rate,
           PERCENTILE_APPROX(s.x_stake,0.25) AS p25, PERCENTILE_APPROX(s.x_stake,0.50) AS p50,
           PERCENTILE_APPROX(s.x_stake,0.75) AS p75, PERCENTILE_APPROX(s.x_stake,0.90) AS p90,
           PERCENTILE_APPROX(s.x_stake,0.95) AS p95, PERCENTILE_APPROX(s.x_stake,0.99) AS p99,
           PERCENTILE_APPROX(s.x_valid,0.50) AS p50_valid,
           PERCENTILE_APPROX(s.x_net,0.50)   AS p50_profit,
           SUM(CASE WHEN s.x_rec = 1 THEN s.x_stake ELSE 0 END) AS st_in,
           SUM(CASE WHEN s.x_rec = 1 THEN 1 ELSE 0 END)         AS nb_in,
           SUM(CASE WHEN s.x_rec = 1 THEN s.x_net ELSE 0 END)   AS net_in,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN s.x_stake ELSE 0 END) AS st_out,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN 1 ELSE 0 END)         AS nb_out,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN s.x_net ELSE 0 END)   AS net_out,
           SUM(CASE WHEN s.x_rec=1 THEN s.x_stake ELSE 0 END) AS st_rec,
           SUM(CASE WHEN s.x_rec=1 THEN 1 ELSE 0 END)         AS nb_rec
    FROM x_mk s
    WHERE s.is_clean = 1
      AND s.x_member IS NOT NULL AND TRIM(CAST(s.x_member AS STRING)) <> ''
    GROUP BY s.x_member
  ),
  x_win AS (
    SELECT            COUNT(*) AS n_bets, COUNT(DISTINCT s.x_round) AS n_rounds,
           COUNT(DISTINCT s.x_date) AS active_days, COUNT(DISTINCT s.x_tblshoe) AS active_shoes,
           COUNT(DISTINCT CONCAT_WS('|', s.x_date, s.x_table)) AS active_sessions,
           COUNT(DISTINCT s.x_table) AS n_tables, COUNT(DISTINCT s.x_dealer) AS n_dealers,
           COUNT(DISTINCT s.x_ip) AS n_ips, COUNT(DISTINCT s.x_product) AS n_products,
           MIN(s.x_date) AS first_seen_d, MAX(s.x_date) AS last_seen_d,
           SUM(s.x_stake) AS stake, SUM(s.x_valid) AS valid, SUM(s.x_rebate) AS rebate,
           SUM(s.x_net) AS net, SUM(-s.x_net *(100.0-s.x_agpct)/100.0) AS agent_cost,
           AVG(100.0-s.x_agpct)                   AS agent_pct,
           AVG(s.x_agpct)                         AS company_retain_pct,
           SUM(-s.x_net *s.x_agpct/100.0)         AS agent_cost_a_legacy,
           SUM(s.x_valid*s.x_agpct/100.0)         AS agent_cost_valid_base_legacy,
          AVG(COALESCE(s.x_rate1,100)) AS retain_pct_lv1, AVG(COALESCE(s.x_rate2,100)) AS retain_pct_lv2,
          AVG(COALESCE(s.x_rate3,100)) AS retain_pct_lv3, AVG(COALESCE(s.x_rate4,100)) AS retain_pct_lv4,
          AVG(COALESCE(s.x_rate5,100)) AS retain_pct_lv5, AVG(s.x_chain_depth) AS chain_depth_avg,
          AVG(COALESCE(100.0-s.x_rate1,0)) AS agent_pct_lv1, AVG(COALESCE(100.0-s.x_rate2,0)) AS agent_pct_lv2,
          AVG(COALESCE(100.0-s.x_rate3,0)) AS agent_pct_lv3, AVG(COALESCE(100.0-s.x_rate4,0)) AS agent_pct_lv4,
          AVG(COALESCE(100.0-s.x_rate5,0)) AS agent_pct_lv5,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate1,0)/100.0)                        AS agent_cost_lv1,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate2,0)/100.0)                        AS agent_cost_lv2,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate3,0)/100.0)                        AS agent_cost_lv3,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate4,0)/100.0)                        AS agent_cost_lv4,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate5,0)/100.0)                        AS agent_cost_lv5,
          SUM(-s.x_net*(COALESCE(100.0-s.x_rate1,0)+COALESCE(100.0-s.x_rate2,0)
                       +COALESCE(100.0-s.x_rate3,0)+COALESCE(100.0-s.x_rate4,0)
                       +COALESCE(100.0-s.x_rate5,0))/100.0)                   AS agent_cost_chain_additive,
          SUM(-s.x_net*(1.0 - CAST(COALESCE(s.x_rate1,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate2,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate3,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate4,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate5,100) AS DOUBLE)/100.0))
                                                                       AS agent_cost_chain_nested,
           AVG(s.x_rbpct) AS rbpct, AVG(s.x_freecomm*1.0) AS freecomm_rate,
           PERCENTILE_APPROX(s.x_stake,0.25) AS p25, PERCENTILE_APPROX(s.x_stake,0.50) AS p50,
           PERCENTILE_APPROX(s.x_stake,0.75) AS p75, PERCENTILE_APPROX(s.x_stake,0.90) AS p90,
           PERCENTILE_APPROX(s.x_stake,0.95) AS p95, PERCENTILE_APPROX(s.x_stake,0.99) AS p99,
           PERCENTILE_APPROX(s.x_valid,0.50) AS p50_valid,
           PERCENTILE_APPROX(s.x_net,0.50)   AS p50_profit,
           SUM(CASE WHEN s.x_rec = 1 THEN s.x_stake ELSE 0 END) AS st_in,
           SUM(CASE WHEN s.x_rec = 1 THEN 1 ELSE 0 END)         AS nb_in,
           SUM(CASE WHEN s.x_rec = 1 THEN s.x_net ELSE 0 END)   AS net_in,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN s.x_stake ELSE 0 END) AS st_out,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN 1 ELSE 0 END)         AS nb_out,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN s.x_net ELSE 0 END)   AS net_out,
           SUM(CASE WHEN s.x_rec=1 THEN s.x_stake ELSE 0 END) AS st_rec,
           SUM(CASE WHEN s.x_rec=1 THEN 1 ELSE 0 END)         AS nb_rec
    FROM x_mk s
    WHERE s.is_clean = 1
      AND s.x_member IS NOT NULL AND TRIM(CAST(s.x_member AS STRING)) <> ''
  ),
      q AS (
        WITH ta AS (                                                                                        -- 公共表表达式：开启中间结果集 ta，其后各行为其定义体（交付件 V_recon.csv）
          SELECT DISTINCT age001 AS aid                                                                     -- 取列：产出「aid」
          FROM ods_mariadb_2b.ods_a168_agent WHERE age022 = '1'                                             -- 取数来源：取自代理主档（五级代理线归属来源）
        ),                                                                                                  -- 续行：收束上方的子查询或函数括号（交付件 V_recon.csv）
        rk AS (                                                                                             -- 公共表表达式：开启中间结果集 rk，其后各行为其定义体（交付件 V_recon.csv）
          SELECT b.bet01, b.bet03, b.bet04, b.bet05, b.bet11, b.bet13, b.bet16, b.bet17,                    -- 取列：起始取列子句，本行先列 b.bet01, b.bet03, b.bet04, b.bet05, b.bet11, b.bet13, b.bet16, b.bet17，涉 bet03（靴号）、bet04（局内序号）、bet05（会员号）
                 b.bet38, b.bet39, b.category,                                                              -- 续行：接续上一取列子句，续列 b.bet38, b.bet39, b.category，涉 bet38（重對）、bet39（桌号）
                 b.bet18, b.bet19, b.bet20, b.bet21, b.bet22,                                               -- 续行：接续上一取列子句，续列 b.bet18, b.bet19, b.bet20, b.bet21, b.bet22，涉 bet18（一级代理线）、bet19（二级代理线）、bet20（三级代理线）
                 ROW_NUMBER() OVER (                                                                        -- 行号窗口表达式：以行号窗口取每组头部或去重，免出重复行
                   PARTITION BY b.bet01                                                                     -- 窗口分区：按 b.bet01 分组开窗，组内各自编号或排名
                   ORDER BY b.updatetime DESC, b.sync_time DESC, b.dt DESC) AS rn                           -- 排序：按 b.updatetime（降序）, b.sync_time（降序）, b.dt（降序）) AS rn 排列；导出必带排序，否则分页无稳定序（曾致 36.49% 重复行）
          FROM ods_mariadb_2b.ods_a168_bet02 b                                                              -- 取数来源：取自注单明细表（金额与行为口径的第一料源）
          WHERE b.dt >= '2026-03-21' AND b.dt < '2026-08-07' AND b.bet02 = '101'
      AND b.sync_time <= '2026-08-27 09:00:00'                            -- 过滤条件：限定 b.dt不少于 '2026-03-21'、b.dt小于 '2026-08-07'、b.bet02等于 '101'，涉 bet02（游戏类别）、dt（营业日）
        ),                                                                                                  -- 续行：收束上方的子查询或函数括号（交付件 V_recon.csv）
        br AS (                                                                                             -- 公共表表达式：开启中间结果集 br，其后各行为其定义体（交付件 V_recon.csv）
          SELECT r.bet03 AS sh, r.bet04 AS rd, r.bet39 AS tb,                                               -- 取列：起始取列子句，本行先取「tb」，涉 bet03（靴号）、bet04（局内序号）、bet39（桌号）
            SUM(CAST(NULLIF(TRIM(r.bet13),'') AS DECIMAL(20,4))                                             -- 汇总表达式：先去空白、空串归 NULL，再显式转型——本库字段多为 varchar，不转型即比较失真
                / CAST(NULLIF(TRIM(r.bet11),'') AS DECIMAL(20,8))) AS turnover,                             -- 除法或乘法计算：先去空白、空串归 NULL，再显式转型——本库字段多为 varchar，不转型即比较失真，产出「turnover」
            SUM(CAST(NULLIF(TRIM(r.bet16),'') AS DECIMAL(20,4))                                             -- 汇总表达式：先去空白、空串归 NULL，再显式转型——本库字段多为 varchar，不转型即比较失真
                / CAST(NULLIF(TRIM(r.bet11),'') AS DECIMAL(20,8))) AS rebate,                               -- 除法或乘法计算：先去空白、空串归 NULL，再显式转型——本库字段多为 varchar，不转型即比较失真，产出「rebate」
            SUM(CAST(NULLIF(TRIM(r.bet17),'') AS DECIMAL(20,4))                                             -- 汇总表达式：先去空白、空串归 NULL，再显式转型——本库字段多为 varchar，不转型即比较失真
                / CAST(NULLIF(TRIM(r.bet11),'') AS DECIMAL(20,8))) AS net_pnl                               -- 除法或乘法计算：先去空白、空串归 NULL，再显式转型——本库字段多为 varchar，不转型即比较失真，产出「net_pnl」
          FROM rk r                                                                                         -- 取数来源：取自本条自建的中间结果集 rk
          LEFT JOIN ta t1 ON t1.aid = r.bet18                                                               -- 左连接：取自本条自建的中间结果集 ta，连接键为 bet18（一级代理线）
          LEFT JOIN ta t2 ON t2.aid = r.bet19                                                               -- 左连接：取自本条自建的中间结果集 ta，连接键为 bet19（二级代理线）
          LEFT JOIN ta t3 ON t3.aid = r.bet20                                                               -- 左连接：取自本条自建的中间结果集 ta，连接键为 bet20（三级代理线）
          LEFT JOIN ta t4 ON t4.aid = r.bet21                                                               -- 左连接：取自本条自建的中间结果集 ta，连接键为 bet21（四级代理线）
          LEFT JOIN ta t5 ON t5.aid = r.bet22                                                               -- 左连接：取自本条自建的中间结果集 ta，连接键为 bet22（五级代理线）
          WHERE r.rn = 1 AND r.category = '1' AND UPPER(TRIM(r.bet38)) = 'N'                                -- 过滤条件：限定 r.rn等于 1、r.category等于 '1'、UPPER(TRIM(r.bet38))等于 'N'，涉 bet38（重對）
            AND CAST(NULLIF(TRIM(r.bet05),'') AS BIGINT) > 0                                                -- 并列条件：限定 CAST(NULLIF(TRIM(r.bet05),'') AS BIGINT)大于 0，涉 bet05（会员号）
            AND CAST(NULLIF(TRIM(r.bet11),'') AS DECIMAL(20,8)) > 0                                         -- 并列条件：限定 CAST(NULLIF(TRIM(r.bet11),'') AS DECIMAL(20,8))大于 0，涉 bet11（汇率）
            AND COALESCE(t1.aid, t2.aid, t3.aid, t4.aid, t5.aid) IS NULL                                    -- 并列条件：限定该值为空——本包以左连接加空值判定替代 EXISTS，因 StarRocks 不支持 EXISTS 配多列 IN
          GROUP BY r.bet03, r.bet04, r.bet39                                                                -- 分组：按 r.bet03, r.bet04, r.bet39 汇总
        ),                                                                                                  -- 续行：收束上方的子查询或函数括号（交付件 V_recon.csv）
        gi AS (                                                                                             -- 公共表表达式：开启中间结果集 gi，其后各行为其定义体（交付件 V_recon.csv）
          SELECT gi002 AS sh, gi003 AS rd, gi011 AS tb,                                                     -- 取列：起始取列子句，本行先取「tb」，涉 gi011（桌号）
                 CAST(NULLIF(TRIM(gi004),'') AS DATETIME)     AS t_open,                                    -- 取值表达式：先去空白、空串归 NULL，再显式转型——本库字段多为 varchar，不转型即比较失真，产出「t_open」
                 CAST(NULLIF(TRIM(gi005),'') AS DECIMAL(20,4)) AS gi_turnover,                              -- 取值表达式：先去空白、空串归 NULL，再显式转型——本库字段多为 varchar，不转型即比较失真，产出「gi_turnover」
                 CAST(NULLIF(TRIM(gi009),'') AS DECIMAL(20,4)) AS gi_rebate,                                -- 取值表达式：先去空白、空串归 NULL，再显式转型——本库字段多为 varchar，不转型即比较失真，产出「gi_rebate」
                 CAST(NULLIF(TRIM(gi010),'') AS DECIMAL(20,4)) AS gi_net                                    -- 取值表达式：先去空白、空串归 NULL，再显式转型——本库字段多为 varchar，不转型即比较失真，产出「gi_net」
          FROM ods_mariadb_2b.ods_a168_game_info                                                            -- 取数来源：取自局信息表（靴局、开牌与桌号的时序基准）
          WHERE dt >= '2026-03-21' AND dt < '2026-08-07' AND gi001 = '101'                                  -- 过滤条件：限定 dt不少于 '2026-03-21'、dt小于 '2026-08-07'、gi001等于 '101'，涉 dt（营业日）、gi001（局主键）
            AND gi013 = '1' AND is_lock = 'N'                                                               -- 并列条件：限定 gi013等于 '1'、is_lock等于 'N'
        ),                                                                                                  -- 续行：收束上方的子查询或函数括号（交付件 V_recon.csv）
        j AS (                                                                                              -- 公共表表达式：开启中间结果集 j，其后各行为其定义体（交付件 V_recon.csv）
          SELECT g.tb, g.t_open,                                                                            -- 取列：起始取列子句，本行先列 g.tb, g.t_open
                 ABS(b.turnover - g.gi_turnover) AS ae_turnover,                                            -- 取值表达式：取用 turnover（洗码量），产出「ae_turnover」
                 ABS(b.rebate   - g.gi_rebate)   AS ae_rebate,                                              -- 取值表达式：取用 rebate（退水），产出「ae_rebate」
                 ABS(b.net_pnl  - g.gi_net)      AS ae_net,                                                 -- 取值表达式：取用 net_pnl（会员净输赢），产出「ae_net」
                 g.gi_turnover, g.gi_rebate, g.gi_net,                                                      -- 续行：接续上一取列子句，续列 g.gi_turnover, g.gi_rebate, g.gi_net
                 LAG(g.gi_turnover) OVER (PARTITION BY g.tb ORDER BY g.t_open) AS lag_turnover,             -- 取前一行表达式：产出「lag_turnover」
                 LAG(g.gi_rebate)   OVER (PARTITION BY g.tb ORDER BY g.t_open) AS lag_rebate,               -- 取前一行表达式：产出「lag_rebate」
                 LAG(g.gi_net)      OVER (PARTITION BY g.tb ORDER BY g.t_open) AS lag_net                   -- 取前一行表达式：产出「lag_net」
          FROM br b                                                                                         -- 取数来源：取自本条自建的中间结果集 br
          JOIN gi g ON b.sh = g.sh AND b.rd = g.rd AND b.tb = g.tb                                          -- 连接：取自本条自建的中间结果集 gi，连接键为 b.sh = g.sh AND b.rd = g.rd AND b.tb = g.tb
        )                                                                                                   -- 续行：收束上方的子查询或函数括号（交付件 V_recon.csv）
        SELECT                                                                                              -- 续行：接续上一取列子句，续列 SELECT
          COUNT(*)                                            AS n_matched_round,                           -- 计数表达式：产出「n_matched_round」
          AVG(ae_turnover)                                    AS mae_turnover,                              -- 求均值表达式：产出「mae_turnover」
          AVG(ae_rebate)                                      AS mae_rebate,                                -- 求均值表达式：产出「mae_rebate」
          AVG(ae_net)                                         AS mae_net,                                   -- 求均值表达式：产出「mae_net」
          AVG(ABS(gi_turnover - lag_turnover))                AS scale_turnover,                            -- 求均值表达式：产出「scale_turnover」
          AVG(ABS(gi_rebate   - lag_rebate))                  AS scale_rebate,                              -- 求均值表达式：产出「scale_rebate」
          AVG(ABS(gi_net      - lag_net))                     AS scale_net,                                 -- 求均值表达式：产出「scale_net」
          AVG(ae_turnover) / NULLIF(AVG(ABS(gi_turnover - lag_turnover)), 0) AS mase_turnover,              -- 求均值表达式：产出「mase_turnover」
          AVG(ae_rebate)   / NULLIF(AVG(ABS(gi_rebate   - lag_rebate)),   0) AS mase_rebate,                -- 求均值表达式：产出「mase_rebate」
          AVG(ae_net)      / NULLIF(AVG(ABS(gi_net      - lag_net)),      0) AS mase_net,                   -- 求均值表达式：产出「mase_net」
          SUM(CASE WHEN ae_turnover <= 0.01 THEN 1 ELSE 0 END) * 1.0 / COUNT(*) AS pct_exact_turnover,      -- 汇总表达式：计数，产出「pct_exact_turnover」
          SUM(CASE WHEN ae_net      <= 0.01 THEN 1 ELSE 0 END) * 1.0 / COUNT(*) AS pct_exact_net            -- 汇总表达式：计数，产出「pct_exact_net」
        FROM j                                                                                              -- 取数来源：取自本条自建的中间结果集 j
        WHERE lag_turnover IS NOT NULL                                                                     -- 过滤条件：限定该值非空
      )
    SELECT q.*,
           -- 一·经济层
           ROUND(e.stake,4) AS stake, ROUND(e.valid,4) AS valid_bet,
           ROUND(-e.net,4) AS profit, e.n_bets, e.n_rounds,
           ROUND(e.net/NULLIF(e.stake,0),8) AS roi,
           ROUND(e.net_in/NULLIF(e.st_in,0),8) AS roi_recent,
           ROUND(e.net_out/NULLIF(e.st_out,0),8) AS roi_non_recent,
           ROUND((e.net-e.rebate)/NULLIF(e.stake,0),8) AS roi_ex_rebate,
           ROUND(e.net,4) AS roi_numerator, ROUND(e.stake,4) AS roi_denominator,
           CASE WHEN e.stake IS NULL THEN 'NULL_DENOM' WHEN e.stake<=0 THEN 'ZERO_DENOM'
                WHEN e.n_bets<30 THEN 'THIN_EXPOSURE' ELSE 'OK' END AS roi_denominator_status,
           ROUND(e.rebate,4) AS rebate_cost, ROUND(e.agent_cost,4)                           AS cost_complement_b,
       ROUND(e.agent_pct,4)                            AS pct_complement,
       ROUND(e.company_retain_pct,4)                   AS pct_top_bet23,
       'AG03-UNRESOLVED'                                     AS agent_formula_version,
      'ALL5_LEVELS_bet23_to_bet27'                    AS agent_level_scope,
      ROUND(e.agent_cost_lv1,4) AS agent_cost_lv1, ROUND(e.agent_cost_lv2,4) AS agent_cost_lv2,
      ROUND(e.agent_cost_lv3,4) AS agent_cost_lv3, ROUND(e.agent_cost_lv4,4) AS agent_cost_lv4,
      ROUND(e.agent_cost_lv5,4) AS agent_cost_lv5,
      ROUND(e.agent_pct_lv1,6) AS agent_pct_lv1, ROUND(e.agent_pct_lv2,6) AS agent_pct_lv2,
      ROUND(e.agent_pct_lv3,6) AS agent_pct_lv3, ROUND(e.agent_pct_lv4,6) AS agent_pct_lv4,
      ROUND(e.agent_pct_lv5,6) AS agent_pct_lv5,
      ROUND(e.retain_pct_lv1,6) AS retain_pct_lv1, ROUND(e.retain_pct_lv2,6) AS retain_pct_lv2,
      ROUND(e.retain_pct_lv3,6) AS retain_pct_lv3, ROUND(e.retain_pct_lv4,6) AS retain_pct_lv4,
      ROUND(e.retain_pct_lv5,6) AS retain_pct_lv5, ROUND(e.chain_depth_avg,4) AS chain_depth_avg,
      ROUND(e.agent_cost_chain_additive,4)            AS agent_cost_chain_additive,
      ROUND(e.agent_cost_chain_nested,4)              AS agent_cost_chain_nested,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_additive,4) AS residual_chain_additive,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_nested,4)   AS residual_chain_nested,
      'PENDING_AG03'                                  AS decision_status,
      'FALSE'                                         AS admit_to_risk_decision,
      'NOT_FOR_ENFORCEMENT'                           AS deliverable_class,
       ROUND(e.agent_cost_a_legacy,4)                  AS agent_cost_a_legacy,
       ROUND(e.agent_cost_valid_base_legacy,4)         AS agent_cost_valid_base_legacy,
           ROUND(-e.net-e.rebate,4)                        AS ngr,
       ROUND(-e.net-e.rebate-e.agent_cost,4)           AS residual_b,
       ROUND(-e.net-e.rebate-e.agent_cost_a_legacy,4)  AS residual_a,
           ROUND((-e.net-e.rebate)/NULLIF(e.stake,0),8)    AS ngr_rate,
       ROUND((-e.net-e.rebate-e.agent_cost)/NULLIF(e.stake,0),8)   AS residual_b_rate,
      -- 【HF9c · canonical accounting contract】
      --   以下 canonical 字段只增加明确 scope；不删除、不覆盖既有字段。
      --   formal_bet23_* 保持 HF9b 当前生产公式及其 NULL/0 语义；
      --   lv1~lv5 / additive / nested 则分别采用各自原始 e.* 成本字段，
      --   rate 一律从未舍入的 e.* 分子 / e.stake 计算，禁止由展示值反算。
      ROUND(e.agent_cost,4) AS agent_cost_bet23_formal_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost,4) AS net_margin_bet23_formal_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost)/NULLIF(e.stake,0),8) AS net_margin_bet23_formal_rate_canonical,
      ROUND(e.agent_cost_lv1,4) AS agent_cost_lv1_bet23_canonical,
      ROUND(e.agent_cost_lv2,4) AS agent_cost_lv2_bet24_canonical,
      ROUND(e.agent_cost_lv3,4) AS agent_cost_lv3_bet25_canonical,
      ROUND(e.agent_cost_lv4,4) AS agent_cost_lv4_bet26_canonical,
      ROUND(e.agent_cost_lv5,4) AS agent_cost_lv5_bet27_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_lv1,4) AS net_margin_lv1_bet23_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_lv1)/NULLIF(e.stake,0),8) AS net_margin_lv1_bet23_rate_canonical,
      ROUND(e.agent_cost_chain_additive,4) AS agent_cost_chain_additive_canonical,
      ROUND(e.agent_cost_chain_nested,4) AS agent_cost_chain_nested_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_additive,4) AS net_margin_chain_additive_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_nested,4) AS net_margin_chain_nested_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_chain_additive)/NULLIF(e.stake,0),8) AS net_margin_chain_additive_rate_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_chain_nested)/NULLIF(e.stake,0),8) AS net_margin_chain_nested_rate_canonical,
       ROUND((-e.net-e.rebate-e.agent_cost_a_legacy)/NULLIF(e.stake,0),8) AS residual_a_rate,
           -- 二·分布层
           ROUND(e.stake/NULLIF(e.n_bets,0),4) AS avg_stake_per_bet,
           ROUND(e.valid/NULLIF(e.n_rounds,0),4) AS avg_valid_bet_per_round,
           ROUND(-e.net/NULLIF(e.n_rounds,0),4) AS avg_profit_per_round,
           ROUND(-e.net/NULLIF(e.active_days,0),4) AS avg_profit_per_day,
           ROUND(-e.net/NULLIF(e.active_shoes,0),4) AS avg_profit_per_shoe,
           ROUND(e.stake/NULLIF(e.active_days,0),4) AS avg_stake_per_active_day,
           ROUND(e.n_rounds*1.0/NULLIF(e.active_days,0),4) AS avg_rounds_per_active_day,
           ROUND(e.st_in/NULLIF(e.nb_in,0),4) AS avg_stake_recent,
           ROUND(e.st_out/NULLIF(e.nb_out,0),4) AS avg_stake_non_recent,
           ROUND(e.p25,4) AS p25_stake, ROUND(e.p50,4) AS p50_stake, ROUND(e.p75,4) AS p75_stake,
           ROUND(e.p90,4) AS p90_stake, ROUND(e.p95,4) AS p95_stake, ROUND(e.p99,4) AS p99_stake,
           ROUND(e.p50_valid,4) AS p50_valid_bet, ROUND(e.p50_profit,4) AS p50_profit,
           ROUND(e.p95/NULLIF(e.p50,0),6) AS p95_over_p50,
           ROUND(e.p99/NULLIF(e.p50,0),6) AS p99_over_p50,
           ROUND((e.stake/NULLIF(e.n_bets,0))/NULLIF(e.p50,0),6) AS avg_over_p50,
           -- 三·关系层
           e.n_tables AS common_table_count, e.n_dealers AS common_dealer_count,
           e.n_ips AS common_ip_count, e.n_products AS common_product_count,
           ROUND(e.st_in/NULLIF(e.stake,0),8) AS share_recent,
           -- 四·rate 层
           ROUND(-e.net/NULLIF(e.stake,0),8) AS hold_rate,
           ROUND(-e.net_in/NULLIF(e.st_in,0),8) AS hold_rate_recent,
           ROUND(e.rebate/NULLIF(e.valid,0),8) AS rebate_rate_actual,
           ROUND(e.rbpct,6) AS rebate_pct_config,
           ROUND(e.valid/NULLIF(e.stake,0),6) AS turnover_multiple,
           ROUND(e.freecomm_rate,6) AS free_comm_rate,
           ROUND(e.net_in/NULLIF(e.st_in,0)-e.net_out/NULLIF(e.st_out,0),8) AS roi_delta_recent,
           -- 五·动态层
           e.first_seen_d AS first_seen, e.last_seen_d AS last_seen,
           e.active_days, e.active_shoes, e.active_sessions,
           DATEDIFF(e.last_seen_d, e.first_seen_d)+1 AS span_days,
           ROUND(e.active_days*1.0/NULLIF(DATEDIFF(e.last_seen_d,e.first_seen_d)+1,0),6) AS persistence,
           ROUND((e.st_in/NULLIF(e.nb_in,0))/NULLIF(e.st_out/NULLIF(e.nb_out,0),0),6) AS ramp_recent_vs_prior,
           ROUND((e.st_rec/NULLIF(e.nb_rec,0))/NULLIF(e.stake/NULLIF(e.n_bets,0),0),6) AS ramp_recent_vs_all,
           ROUND((e.st_rec/NULLIF(e.stake,0))/0.30,6) AS stake_ramp,
           -- 六·决策层（HF9g-P5 · D-14 斧正 —— 本件属【全窗基线族】，相对刻度与决策标签一律 NULL）
           --   病灶：x_win 系全窗单行聚合（无 GROUP BY，恒 1 行，此为设计使然，非缺陷），
           --         经 CROSS JOIN 接入后 e.* 全行同值；六层之 NTILE / PERCENT_RANK 施于常数即退化，
           --         PERCENT_RANK 恒 0 ⇒ action_priority 恒判 A，全件 100% 误标。
           --   ★ 斧正原则：不给 x_win 补 GROUP BY —— 那会改变其「全窗基线」语义，属退化。
           --     正解与 #018 之 G-05／G-06 同治：范围外之行不得接受任何下游评分与决策标签。
           --   ★ 本件之 e.* 仍照常供其它列作全窗基线使用，仅六层相对刻度与决策标签置 NULL。
           CAST(NULL AS INT)                                              AS vip_tier,                        -- 空值取值：全窗基线族无实体可分档，置 NULL（NULL＝不适用，非 0）
           CAST(NULL AS DOUBLE)                                           AS economic_value,                  -- 空值取值：同上，禁以常数百分位冒充经济价值
           CAST(NULL AS DOUBLE)                                           AS roi_pr_global,                   -- 空值取值：同上
           CAST(NULL AS DOUBLE)                                           AS risk_value,                      -- 空值取值：兼容列，同上
           CAST(NULL AS DOUBLE)                                           AS pr_stake,                        -- 空值取值：兼容列，同上
           CAST(NULL AS DOUBLE)                                           AS pr_global,                       -- 空值取值：同上
           CAST(NULL AS DOUBLE)                                           AS pr_qualified,                    -- 空值取值：同上
           'GLOBAL_BASELINE_NO_ENTITY_RANKING'                            AS pr_qualified_population,         -- 字面取值：血统 —— 明示本件为全窗基线族，无实体排序总体
           CAST(NULL AS BIGINT)                                           AS pr_global_population_n,          -- 空值取值：血统 —— 不适用
           CAST(NULL AS BIGINT)                                           AS pr_qualified_population_n,       -- 空值取值：血统 —— 不适用
           'NOT_APPLICABLE_GLOBAL_BASELINE'                               AS pr_calculation_method,           -- 字面取值：血统 —— 算法不适用
           'HF9g-P5'                                                      AS pr_calculation_version,          -- 字面取值：血统 —— 算法版本
           CAST(NULL AS STRING)                                           AS evidence_flag,                   -- 空值取值：证据旗标不适用于全窗基线
           CAST(NULL AS STRING)                                           AS evidence_rate,                   -- 空值取值：同上
           CAST(NULL AS DOUBLE)                                           AS hold_ci_halfwidth_approx,        -- 空值取值：同上
           'X 全窗基线 · 不参与实体赏罚'                                    AS action_priority                  -- 字面取值：★ D-14 斧正 —— 本族恒不入赏罚，取代原 100% 误标之「A」
    FROM q
    CROSS JOIN x_win e
  ) y
) z
-- ── 逐批 WHERE 阶梯（★ 口诀：上界 ＝ 下界 ＋ 100000，两数同进）──
--    本件 T_true 未测，无需先跑 T_true；以 0 / 100000 控制本批返回区间，末批由实际行数 < 100000 判定
--    WHERE z.audit_rn >        0 AND z.audit_rn <=   100000   -- 第 1 批
--    WHERE z.audit_rn >   100000 AND z.audit_rn <=   200000   -- 第 2 批
--    WHERE z.audit_rn >   200000 AND z.audit_rn <=   300000   -- 第 3 批
--    WHERE z.audit_rn >   300000 AND z.audit_rn <=   400000   -- 第 4 批
--    WHERE z.audit_rn >   400000 AND z.audit_rn <=   500000   -- 第 5 批
--    WHERE z.audit_rn >   500000 AND z.audit_rn <=   600000   -- 第 6 批
--    WHERE z.audit_rn >   600000 AND z.audit_rn <=   700000   -- 第 7 批
--    …余批类推。第 k 批：WHERE z.audit_rn > (k-1)*100000 AND z.audit_rn <= k*100000
--    某批返回 < 100000 行即为末批，其后不再取。
--
--    ⚠ 常见误写（务必避开）：只推下界而上界不动 ——
--        WHERE z.audit_rn > 100000 AND z.audit_rn <= 100000   ← 自相矛盾，恒为假，返回空集
--        WHERE z.audit_rn > 200000 AND z.audit_rn <= 100000   ← 同上，空集
--      两个数必须**同时**前进，且始终相差 100000。
--      下界 ＝ 上一批之上界；上界 ＝ 本批之上界。
WHERE z.audit_rn > 0 AND z.audit_rn <= 100000 -- ★ HF9c 本批区间
ORDER BY z.audit_rn;


-- ══════════════════════════════════════════════════════════════════════════════════════════════
-- 109. V_table_counts.csv   [总包行 6092~6101 · 原 2 列 ＋六层约 60 列]
--     典型学：Z00 基建/元数据　派生旗标：recent（s.x_rec = 1 · 仅供 CASE 条件聚合，全包无任何 WHERE/AND/HAVING 以此过滤）　连接：全窗基线
-- ══════════════════════════════════════════════════════════════════════════════════════════════
-- ★ W-64 · D-14 警示（本件属 x_win 族 · 66 件之一 · 详见 §Z 段 D-14 全案）
--   本件以 `CROSS JOIN x_win e` 接入全局基线，x_win 无 GROUP BY ⇒ 恒 1 行 ⇒ e.* 全行同值。
--   故：economic_value / roi_pr_global / risk_value / pr_stake / pr_global 恒为 0；
--       action_priority 每一行皆为「A 净亏最大十分位 · 优先复核」（Z 分支永不触发）；
--       evidence_rate 恒为最高档；vip_tier 由常数键分档 ⇒ 无信息且非确定。
--   ⇒ 本件决策层三列 **NOT_FOR_DECISION**，裁定前不得用于排班、抽查或汇报。
-- ── ① 先跑 T_true 留档（不足 100000 者一次导全，不必分批）──
-- ── ① T_true：HF9c 不再强制预跑完整 COUNT。
--    本批实际返回行数 < 100000 即判定为末批；全批完成后以各批 n_rows / audit_rn 范围核对总量。

-- ── ② 分批取数：第 1 批。第 k 批只改末行两数为 (k-1)*100000 与 k*100000 ──
--    审计字段二（REDTEAM 2026-08-24 裁定 · 四锁）：
--      audit_rn  全局观测坐标 —— 由**与原版审计版逐字同一**之排序键所生，两版可逐行对账
--      batch_id  物理分批信息 —— 该行所属批次，由 audit_rn 算得，非引擎所赋
--    ★ 锁三：二者皆为审计字段，**不得进入任何业务指标计算**。
--    ★ 锁四：两版经 audit_rn 逐行字段核验后，方可宣布输出完全一致。

-- ── ③ 每批取回后自证四数（任一不符即停手回报，禁止放行）──
--    n_rows        = COUNT(*)      须等于 COUNT(DISTINCT audit_rn)   （批内无重复）
--    audit_rn_min  = MIN(audit_rn) 须等于 (k-1)*100000 + 1           （与上批严丝合缝）
--    audit_rn_max  = MAX(audit_rn) 须等于 min + n_rows - 1           （批内无缺口）
--    全批取毕再验：各批 audit_rn 之并集 = 1 .. T_true，无缺号、无重号。
--     ★ 首行＝平台真净亏最多者（已扣退水与代理占成）。
--
SELECT z.*,
       CAST(FLOOR((z.audit_rn - 1) / 100000) + 1 AS INT)          AS batch_id,
       'A168_HF9F_20260827_0900' AS run_id,
       '2026-08-27 09:00:00' AS snapshot_sync_time
FROM (
  SELECT y.*,
         ROW_NUMBER() OVER (ORDER BY y.`residual_b` ASC, y.`roi` DESC) AS audit_rn
  FROM (
    WITH
      x_ranked AS (
    SELECT b.bet01, b.bet03, b.bet04, b.bet05, b.bet09, b.bet11, b.bet13,
           b.bet15, b.bet16, b.bet17, b.bet18, b.bet19, b.bet20, b.bet21,
           b.bet22, b.bet23, b.bet24, b.bet25, b.bet26, b.bet27, b.bet38, b.bet39, b.category, b.commission,
           b.dt, b.eid, b.ip, b.validbet, b.updatetime, b.sync_time,
           ROW_NUMBER() OVER (
             PARTITION BY b.bet01
             ORDER BY b.updatetime DESC, b.sync_time DESC, b.dt DESC)      AS x_rn
    FROM ods_mariadb_2b.ods_a168_bet02 b
    WHERE b.dt >= '2026-03-21' AND b.dt < '2026-08-07'
      AND b.bet02 = '101'
      AND b.sync_time <= '2026-08-27 09:00:00'
  ),
    x_testagent AS (
    SELECT age001 AS agent_id FROM ods_mariadb_2b.ods_a168_agent WHERE age022 = '1'
  ),
    x_bs0 AS (
    SELECT b.bet05 AS x_member, b.eid AS x_dealer, b.bet39 AS x_table,
           b.bet03 AS x_shoe, b.ip AS x_ip, b.bet09 AS x_product, b.dt AS x_date,
           CONCAT_WS('|', b.bet03, b.bet04, b.bet39)                      AS x_round,
           CONCAT_WS('|', b.bet39, b.bet03)                               AS x_tblshoe,
           CAST(NULLIF(TRIM(b.bet04),'') AS INT)                          AS x_rno,
           CASE WHEN b.dt >= '2026-07-08' THEN 1 ELSE 0 END               AS x_rec,
           CASE WHEN TRIM(b.commission)='1' THEN 1 ELSE 0 END             AS x_freecomm,
           CAST(NULLIF(TRIM(b.bet13),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_stake,
           CAST(NULLIF(TRIM(b.validbet),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_valid,
           CAST(NULLIF(TRIM(b.bet16),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_rebate,
           CAST(NULLIF(TRIM(b.bet17),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_net,
           CAST(NULLIF(TRIM(b.bet15),'') AS DECIMAL(20,6))                AS x_rbpct,
           COALESCE(CAST(NULLIF(TRIM(b.bet23),'') AS DECIMAL(20,6)),0)   AS x_agpct,
          NULLIF(CAST(NULLIF(TRIM(b.bet23),'') AS DECIMAL(20,6)),0)     AS x_rate1,
          NULLIF(CAST(NULLIF(TRIM(b.bet24),'') AS DECIMAL(20,6)),0)     AS x_rate2,
          NULLIF(CAST(NULLIF(TRIM(b.bet25),'') AS DECIMAL(20,6)),0)     AS x_rate3,
          NULLIF(CAST(NULLIF(TRIM(b.bet26),'') AS DECIMAL(20,6)),0)     AS x_rate4,
          NULLIF(CAST(NULLIF(TRIM(b.bet27),'') AS DECIMAL(20,6)),0)     AS x_rate5,
          (CASE WHEN NULLIF(CAST(NULLIF(TRIM(b.bet22),'') AS BIGINT),0) IS NOT NULL THEN 5
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet21),'') AS BIGINT),0) IS NOT NULL THEN 4
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet20),'') AS BIGINT),0) IS NOT NULL THEN 3
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet19),'') AS BIGINT),0) IS NOT NULL THEN 2
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet18),'') AS BIGINT),0) IS NOT NULL THEN 1
                ELSE 0 END)                                             AS x_chain_depth,
           CASE WHEN COALESCE(t1.agent_id,t2.agent_id,t3.agent_id,
                              t4.agent_id,t5.agent_id) IS NOT NULL
                THEN 1 ELSE 0 END                                        AS f_testline
    FROM x_ranked b
    LEFT JOIN x_testagent t1 ON t1.agent_id = b.bet18
    LEFT JOIN x_testagent t2 ON t2.agent_id = b.bet19
    LEFT JOIN x_testagent t3 ON t3.agent_id = b.bet20
    LEFT JOIN x_testagent t4 ON t4.agent_id = b.bet21
    LEFT JOIN x_testagent t5 ON t5.agent_id = b.bet22
    WHERE b.x_rn = 1
      AND b.category='1' AND UPPER(TRIM(b.bet38))='N'
      AND CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8)) > 0
  ),
  x_mk AS (
    SELECT s.*,
           CASE WHEN s.f_testline = 0 THEN 1 ELSE 0 END                 AS is_clean
    FROM x_bs0 s
  ),
  x_agg AS (
    SELECT s.x_member                                                        AS x_key,
           COUNT(*) AS n_bets, COUNT(DISTINCT s.x_round) AS n_rounds,
           COUNT(DISTINCT s.x_date) AS active_days, COUNT(DISTINCT s.x_tblshoe) AS active_shoes,
           COUNT(DISTINCT CONCAT_WS('|', s.x_date, s.x_table)) AS active_sessions,
           COUNT(DISTINCT s.x_table) AS n_tables, COUNT(DISTINCT s.x_dealer) AS n_dealers,
           COUNT(DISTINCT s.x_ip) AS n_ips, COUNT(DISTINCT s.x_product) AS n_products,
           MIN(s.x_date) AS first_seen_d, MAX(s.x_date) AS last_seen_d,
           SUM(s.x_stake) AS stake, SUM(s.x_valid) AS valid, SUM(s.x_rebate) AS rebate,
           SUM(s.x_net) AS net, SUM(-s.x_net *(100.0-s.x_agpct)/100.0) AS agent_cost,
           AVG(100.0-s.x_agpct)                   AS agent_pct,
           AVG(s.x_agpct)                         AS company_retain_pct,
           SUM(-s.x_net *s.x_agpct/100.0)         AS agent_cost_a_legacy,
           SUM(s.x_valid*s.x_agpct/100.0)         AS agent_cost_valid_base_legacy,
          AVG(COALESCE(s.x_rate1,100)) AS retain_pct_lv1, AVG(COALESCE(s.x_rate2,100)) AS retain_pct_lv2,
          AVG(COALESCE(s.x_rate3,100)) AS retain_pct_lv3, AVG(COALESCE(s.x_rate4,100)) AS retain_pct_lv4,
          AVG(COALESCE(s.x_rate5,100)) AS retain_pct_lv5, AVG(s.x_chain_depth) AS chain_depth_avg,
          AVG(COALESCE(100.0-s.x_rate1,0)) AS agent_pct_lv1, AVG(COALESCE(100.0-s.x_rate2,0)) AS agent_pct_lv2,
          AVG(COALESCE(100.0-s.x_rate3,0)) AS agent_pct_lv3, AVG(COALESCE(100.0-s.x_rate4,0)) AS agent_pct_lv4,
          AVG(COALESCE(100.0-s.x_rate5,0)) AS agent_pct_lv5,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate1,0)/100.0)                        AS agent_cost_lv1,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate2,0)/100.0)                        AS agent_cost_lv2,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate3,0)/100.0)                        AS agent_cost_lv3,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate4,0)/100.0)                        AS agent_cost_lv4,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate5,0)/100.0)                        AS agent_cost_lv5,
          SUM(-s.x_net*(COALESCE(100.0-s.x_rate1,0)+COALESCE(100.0-s.x_rate2,0)
                       +COALESCE(100.0-s.x_rate3,0)+COALESCE(100.0-s.x_rate4,0)
                       +COALESCE(100.0-s.x_rate5,0))/100.0)                   AS agent_cost_chain_additive,
          SUM(-s.x_net*(1.0 - CAST(COALESCE(s.x_rate1,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate2,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate3,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate4,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate5,100) AS DOUBLE)/100.0))
                                                                       AS agent_cost_chain_nested,
           AVG(s.x_rbpct) AS rbpct, AVG(s.x_freecomm*1.0) AS freecomm_rate,
           PERCENTILE_APPROX(s.x_stake,0.25) AS p25, PERCENTILE_APPROX(s.x_stake,0.50) AS p50,
           PERCENTILE_APPROX(s.x_stake,0.75) AS p75, PERCENTILE_APPROX(s.x_stake,0.90) AS p90,
           PERCENTILE_APPROX(s.x_stake,0.95) AS p95, PERCENTILE_APPROX(s.x_stake,0.99) AS p99,
           PERCENTILE_APPROX(s.x_valid,0.50) AS p50_valid,
           PERCENTILE_APPROX(s.x_net,0.50)   AS p50_profit,
           SUM(CASE WHEN s.x_rec = 1 THEN s.x_stake ELSE 0 END) AS st_in,
           SUM(CASE WHEN s.x_rec = 1 THEN 1 ELSE 0 END)         AS nb_in,
           SUM(CASE WHEN s.x_rec = 1 THEN s.x_net ELSE 0 END)   AS net_in,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN s.x_stake ELSE 0 END) AS st_out,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN 1 ELSE 0 END)         AS nb_out,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN s.x_net ELSE 0 END)   AS net_out,
           SUM(CASE WHEN s.x_rec=1 THEN s.x_stake ELSE 0 END) AS st_rec,
           SUM(CASE WHEN s.x_rec=1 THEN 1 ELSE 0 END)         AS nb_rec
    FROM x_mk s
    WHERE s.is_clean = 1
      AND s.x_member IS NOT NULL AND TRIM(CAST(s.x_member AS STRING)) <> ''
    GROUP BY s.x_member
  ),
  x_win AS (
    SELECT            COUNT(*) AS n_bets, COUNT(DISTINCT s.x_round) AS n_rounds,
           COUNT(DISTINCT s.x_date) AS active_days, COUNT(DISTINCT s.x_tblshoe) AS active_shoes,
           COUNT(DISTINCT CONCAT_WS('|', s.x_date, s.x_table)) AS active_sessions,
           COUNT(DISTINCT s.x_table) AS n_tables, COUNT(DISTINCT s.x_dealer) AS n_dealers,
           COUNT(DISTINCT s.x_ip) AS n_ips, COUNT(DISTINCT s.x_product) AS n_products,
           MIN(s.x_date) AS first_seen_d, MAX(s.x_date) AS last_seen_d,
           SUM(s.x_stake) AS stake, SUM(s.x_valid) AS valid, SUM(s.x_rebate) AS rebate,
           SUM(s.x_net) AS net, SUM(-s.x_net *(100.0-s.x_agpct)/100.0) AS agent_cost,
           AVG(100.0-s.x_agpct)                   AS agent_pct,
           AVG(s.x_agpct)                         AS company_retain_pct,
           SUM(-s.x_net *s.x_agpct/100.0)         AS agent_cost_a_legacy,
           SUM(s.x_valid*s.x_agpct/100.0)         AS agent_cost_valid_base_legacy,
          AVG(COALESCE(s.x_rate1,100)) AS retain_pct_lv1, AVG(COALESCE(s.x_rate2,100)) AS retain_pct_lv2,
          AVG(COALESCE(s.x_rate3,100)) AS retain_pct_lv3, AVG(COALESCE(s.x_rate4,100)) AS retain_pct_lv4,
          AVG(COALESCE(s.x_rate5,100)) AS retain_pct_lv5, AVG(s.x_chain_depth) AS chain_depth_avg,
          AVG(COALESCE(100.0-s.x_rate1,0)) AS agent_pct_lv1, AVG(COALESCE(100.0-s.x_rate2,0)) AS agent_pct_lv2,
          AVG(COALESCE(100.0-s.x_rate3,0)) AS agent_pct_lv3, AVG(COALESCE(100.0-s.x_rate4,0)) AS agent_pct_lv4,
          AVG(COALESCE(100.0-s.x_rate5,0)) AS agent_pct_lv5,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate1,0)/100.0)                        AS agent_cost_lv1,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate2,0)/100.0)                        AS agent_cost_lv2,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate3,0)/100.0)                        AS agent_cost_lv3,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate4,0)/100.0)                        AS agent_cost_lv4,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate5,0)/100.0)                        AS agent_cost_lv5,
          SUM(-s.x_net*(COALESCE(100.0-s.x_rate1,0)+COALESCE(100.0-s.x_rate2,0)
                       +COALESCE(100.0-s.x_rate3,0)+COALESCE(100.0-s.x_rate4,0)
                       +COALESCE(100.0-s.x_rate5,0))/100.0)                   AS agent_cost_chain_additive,
          SUM(-s.x_net*(1.0 - CAST(COALESCE(s.x_rate1,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate2,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate3,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate4,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate5,100) AS DOUBLE)/100.0))
                                                                       AS agent_cost_chain_nested,
           AVG(s.x_rbpct) AS rbpct, AVG(s.x_freecomm*1.0) AS freecomm_rate,
           PERCENTILE_APPROX(s.x_stake,0.25) AS p25, PERCENTILE_APPROX(s.x_stake,0.50) AS p50,
           PERCENTILE_APPROX(s.x_stake,0.75) AS p75, PERCENTILE_APPROX(s.x_stake,0.90) AS p90,
           PERCENTILE_APPROX(s.x_stake,0.95) AS p95, PERCENTILE_APPROX(s.x_stake,0.99) AS p99,
           PERCENTILE_APPROX(s.x_valid,0.50) AS p50_valid,
           PERCENTILE_APPROX(s.x_net,0.50)   AS p50_profit,
           SUM(CASE WHEN s.x_rec = 1 THEN s.x_stake ELSE 0 END) AS st_in,
           SUM(CASE WHEN s.x_rec = 1 THEN 1 ELSE 0 END)         AS nb_in,
           SUM(CASE WHEN s.x_rec = 1 THEN s.x_net ELSE 0 END)   AS net_in,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN s.x_stake ELSE 0 END) AS st_out,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN 1 ELSE 0 END)         AS nb_out,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN s.x_net ELSE 0 END)   AS net_out,
           SUM(CASE WHEN s.x_rec=1 THEN s.x_stake ELSE 0 END) AS st_rec,
           SUM(CASE WHEN s.x_rec=1 THEN 1 ELSE 0 END)         AS nb_rec
    FROM x_mk s
    WHERE s.is_clean = 1
      AND s.x_member IS NOT NULL AND TRIM(CAST(s.x_member AS STRING)) <> ''
  ),
      q AS (
        SELECT 'ods_a168_bet02'              AS 表名, COUNT(*) AS 行数 FROM ods_mariadb_2b.ods_a168_bet02 WHERE sync_time <= '2026-08-27 09:00:00'       -- 取列：计数，取用注单明细表（金额与行为口径的第一料源），产出「行数」 WHERE sync_time <= '2026-08-27 09:00:00'
        UNION ALL SELECT 'ods_a168_bet01',              COUNT(*) FROM ods_mariadb_2b.ods_a168_bet01         -- 结果集合并：计数，取用注单主表（仅供比对，不作主用）
        UNION ALL SELECT 'ods_a168_game_info',          COUNT(*) FROM ods_mariadb_2b.ods_a168_game_info     -- 结果集合并：计数，取用局信息表（靴局、开牌与桌号的时序基准）
        UNION ALL SELECT 'ods_a168_agent',              COUNT(*) FROM ods_mariadb_2b.ods_a168_agent         -- 结果集合并：计数，取用代理主档（五级代理线归属来源）
        UNION ALL SELECT 'ods_a168_member_dtl',         COUNT(*) FROM ods_mariadb_2b.ods_a168_member_dtl    -- 结果集合并：计数，取用会员主档明细（注册与账户属性）
        UNION ALL SELECT 'ods_a168_dailyreport_member', COUNT(*) FROM ods_mariadb_2b.ods_a168_dailyreport_member  -- 结果集合并：计数，取用会员日结报表（日粒度业绩与风控标记）
        UNION ALL SELECT 'ods_a168_alert_ip_setting',   COUNT(*) FROM ods_mariadb_2b.ods_a168_alert_ip_setting  -- 结果集合并：计数，取用风控 IP 名单配置表（人工标记史料源）
        UNION ALL SELECT 'ods_a168_employee',           COUNT(*) FROM ods_mariadb_2b.ods_a168_employee      -- 结果集合并：计数，取用员工主档（荷官工号与在职状态）
        UNION ALL SELECT 'ods_a168_game_No',            COUNT(*) FROM ods_mariadb_2b.ods_a168_game_No       -- 结果集合并：计数，取用局号编码表（局键位数核验之用）
      )
    SELECT q.*,
           -- 一·经济层
           ROUND(e.stake,4) AS stake, ROUND(e.valid,4) AS valid_bet,
           ROUND(-e.net,4) AS profit, e.n_bets, e.n_rounds,
           ROUND(e.net/NULLIF(e.stake,0),8) AS roi,
           ROUND(e.net_in/NULLIF(e.st_in,0),8) AS roi_recent,
           ROUND(e.net_out/NULLIF(e.st_out,0),8) AS roi_non_recent,
           ROUND((e.net-e.rebate)/NULLIF(e.stake,0),8) AS roi_ex_rebate,
           ROUND(e.net,4) AS roi_numerator, ROUND(e.stake,4) AS roi_denominator,
           CASE WHEN e.stake IS NULL THEN 'NULL_DENOM' WHEN e.stake<=0 THEN 'ZERO_DENOM'
                WHEN e.n_bets<30 THEN 'THIN_EXPOSURE' ELSE 'OK' END AS roi_denominator_status,
           ROUND(e.rebate,4) AS rebate_cost, ROUND(e.agent_cost,4)                           AS cost_complement_b,
       ROUND(e.agent_pct,4)                            AS pct_complement,
       ROUND(e.company_retain_pct,4)                   AS pct_top_bet23,
       'AG03-UNRESOLVED'                                     AS agent_formula_version,
      'ALL5_LEVELS_bet23_to_bet27'                    AS agent_level_scope,
      ROUND(e.agent_cost_lv1,4) AS agent_cost_lv1, ROUND(e.agent_cost_lv2,4) AS agent_cost_lv2,
      ROUND(e.agent_cost_lv3,4) AS agent_cost_lv3, ROUND(e.agent_cost_lv4,4) AS agent_cost_lv4,
      ROUND(e.agent_cost_lv5,4) AS agent_cost_lv5,
      ROUND(e.agent_pct_lv1,6) AS agent_pct_lv1, ROUND(e.agent_pct_lv2,6) AS agent_pct_lv2,
      ROUND(e.agent_pct_lv3,6) AS agent_pct_lv3, ROUND(e.agent_pct_lv4,6) AS agent_pct_lv4,
      ROUND(e.agent_pct_lv5,6) AS agent_pct_lv5,
      ROUND(e.retain_pct_lv1,6) AS retain_pct_lv1, ROUND(e.retain_pct_lv2,6) AS retain_pct_lv2,
      ROUND(e.retain_pct_lv3,6) AS retain_pct_lv3, ROUND(e.retain_pct_lv4,6) AS retain_pct_lv4,
      ROUND(e.retain_pct_lv5,6) AS retain_pct_lv5, ROUND(e.chain_depth_avg,4) AS chain_depth_avg,
      ROUND(e.agent_cost_chain_additive,4)            AS agent_cost_chain_additive,
      ROUND(e.agent_cost_chain_nested,4)              AS agent_cost_chain_nested,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_additive,4) AS residual_chain_additive,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_nested,4)   AS residual_chain_nested,
      'PENDING_AG03'                                  AS decision_status,
      'FALSE'                                         AS admit_to_risk_decision,
      'NOT_FOR_ENFORCEMENT'                           AS deliverable_class,
       ROUND(e.agent_cost_a_legacy,4)                  AS agent_cost_a_legacy,
       ROUND(e.agent_cost_valid_base_legacy,4)         AS agent_cost_valid_base_legacy,
           ROUND(-e.net-e.rebate,4)                        AS ngr,
       ROUND(-e.net-e.rebate-e.agent_cost,4)           AS residual_b,
       ROUND(-e.net-e.rebate-e.agent_cost_a_legacy,4)  AS residual_a,
           ROUND((-e.net-e.rebate)/NULLIF(e.stake,0),8)    AS ngr_rate,
       ROUND((-e.net-e.rebate-e.agent_cost)/NULLIF(e.stake,0),8)   AS residual_b_rate,
      -- 【HF9c · canonical accounting contract】
      --   以下 canonical 字段只增加明确 scope；不删除、不覆盖既有字段。
      --   formal_bet23_* 保持 HF9b 当前生产公式及其 NULL/0 语义；
      --   lv1~lv5 / additive / nested 则分别采用各自原始 e.* 成本字段，
      --   rate 一律从未舍入的 e.* 分子 / e.stake 计算，禁止由展示值反算。
      ROUND(e.agent_cost,4) AS agent_cost_bet23_formal_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost,4) AS net_margin_bet23_formal_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost)/NULLIF(e.stake,0),8) AS net_margin_bet23_formal_rate_canonical,
      ROUND(e.agent_cost_lv1,4) AS agent_cost_lv1_bet23_canonical,
      ROUND(e.agent_cost_lv2,4) AS agent_cost_lv2_bet24_canonical,
      ROUND(e.agent_cost_lv3,4) AS agent_cost_lv3_bet25_canonical,
      ROUND(e.agent_cost_lv4,4) AS agent_cost_lv4_bet26_canonical,
      ROUND(e.agent_cost_lv5,4) AS agent_cost_lv5_bet27_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_lv1,4) AS net_margin_lv1_bet23_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_lv1)/NULLIF(e.stake,0),8) AS net_margin_lv1_bet23_rate_canonical,
      ROUND(e.agent_cost_chain_additive,4) AS agent_cost_chain_additive_canonical,
      ROUND(e.agent_cost_chain_nested,4) AS agent_cost_chain_nested_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_additive,4) AS net_margin_chain_additive_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_nested,4) AS net_margin_chain_nested_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_chain_additive)/NULLIF(e.stake,0),8) AS net_margin_chain_additive_rate_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_chain_nested)/NULLIF(e.stake,0),8) AS net_margin_chain_nested_rate_canonical,
       ROUND((-e.net-e.rebate-e.agent_cost_a_legacy)/NULLIF(e.stake,0),8) AS residual_a_rate,
           -- 二·分布层
           ROUND(e.stake/NULLIF(e.n_bets,0),4) AS avg_stake_per_bet,
           ROUND(e.valid/NULLIF(e.n_rounds,0),4) AS avg_valid_bet_per_round,
           ROUND(-e.net/NULLIF(e.n_rounds,0),4) AS avg_profit_per_round,
           ROUND(-e.net/NULLIF(e.active_days,0),4) AS avg_profit_per_day,
           ROUND(-e.net/NULLIF(e.active_shoes,0),4) AS avg_profit_per_shoe,
           ROUND(e.stake/NULLIF(e.active_days,0),4) AS avg_stake_per_active_day,
           ROUND(e.n_rounds*1.0/NULLIF(e.active_days,0),4) AS avg_rounds_per_active_day,
           ROUND(e.st_in/NULLIF(e.nb_in,0),4) AS avg_stake_recent,
           ROUND(e.st_out/NULLIF(e.nb_out,0),4) AS avg_stake_non_recent,
           ROUND(e.p25,4) AS p25_stake, ROUND(e.p50,4) AS p50_stake, ROUND(e.p75,4) AS p75_stake,
           ROUND(e.p90,4) AS p90_stake, ROUND(e.p95,4) AS p95_stake, ROUND(e.p99,4) AS p99_stake,
           ROUND(e.p50_valid,4) AS p50_valid_bet, ROUND(e.p50_profit,4) AS p50_profit,
           ROUND(e.p95/NULLIF(e.p50,0),6) AS p95_over_p50,
           ROUND(e.p99/NULLIF(e.p50,0),6) AS p99_over_p50,
           ROUND((e.stake/NULLIF(e.n_bets,0))/NULLIF(e.p50,0),6) AS avg_over_p50,
           -- 三·关系层
           e.n_tables AS common_table_count, e.n_dealers AS common_dealer_count,
           e.n_ips AS common_ip_count, e.n_products AS common_product_count,
           ROUND(e.st_in/NULLIF(e.stake,0),8) AS share_recent,
           -- 四·rate 层
           ROUND(-e.net/NULLIF(e.stake,0),8) AS hold_rate,
           ROUND(-e.net_in/NULLIF(e.st_in,0),8) AS hold_rate_recent,
           ROUND(e.rebate/NULLIF(e.valid,0),8) AS rebate_rate_actual,
           ROUND(e.rbpct,6) AS rebate_pct_config,
           ROUND(e.valid/NULLIF(e.stake,0),6) AS turnover_multiple,
           ROUND(e.freecomm_rate,6) AS free_comm_rate,
           ROUND(e.net_in/NULLIF(e.st_in,0)-e.net_out/NULLIF(e.st_out,0),8) AS roi_delta_recent,
           -- 五·动态层
           e.first_seen_d AS first_seen, e.last_seen_d AS last_seen,
           e.active_days, e.active_shoes, e.active_sessions,
           DATEDIFF(e.last_seen_d, e.first_seen_d)+1 AS span_days,
           ROUND(e.active_days*1.0/NULLIF(DATEDIFF(e.last_seen_d,e.first_seen_d)+1,0),6) AS persistence,
           ROUND((e.st_in/NULLIF(e.nb_in,0))/NULLIF(e.st_out/NULLIF(e.nb_out,0),0),6) AS ramp_recent_vs_prior,
           ROUND((e.st_rec/NULLIF(e.nb_rec,0))/NULLIF(e.stake/NULLIF(e.n_bets,0),0),6) AS ramp_recent_vs_all,
           ROUND((e.st_rec/NULLIF(e.stake,0))/0.30,6) AS stake_ramp,
           -- 六·决策层（HF9g-P5 · D-14 斧正 —— 本件属【全窗基线族】，相对刻度与决策标签一律 NULL）
           --   病灶：x_win 系全窗单行聚合（无 GROUP BY，恒 1 行，此为设计使然，非缺陷），
           --         经 CROSS JOIN 接入后 e.* 全行同值；六层之 NTILE / PERCENT_RANK 施于常数即退化，
           --         PERCENT_RANK 恒 0 ⇒ action_priority 恒判 A，全件 100% 误标。
           --   ★ 斧正原则：不给 x_win 补 GROUP BY —— 那会改变其「全窗基线」语义，属退化。
           --     正解与 #018 之 G-05／G-06 同治：范围外之行不得接受任何下游评分与决策标签。
           --   ★ 本件之 e.* 仍照常供其它列作全窗基线使用，仅六层相对刻度与决策标签置 NULL。
           CAST(NULL AS INT)                                              AS vip_tier,                        -- 空值取值：全窗基线族无实体可分档，置 NULL（NULL＝不适用，非 0）
           CAST(NULL AS DOUBLE)                                           AS economic_value,                  -- 空值取值：同上，禁以常数百分位冒充经济价值
           CAST(NULL AS DOUBLE)                                           AS roi_pr_global,                   -- 空值取值：同上
           CAST(NULL AS DOUBLE)                                           AS risk_value,                      -- 空值取值：兼容列，同上
           CAST(NULL AS DOUBLE)                                           AS pr_stake,                        -- 空值取值：兼容列，同上
           CAST(NULL AS DOUBLE)                                           AS pr_global,                       -- 空值取值：同上
           CAST(NULL AS DOUBLE)                                           AS pr_qualified,                    -- 空值取值：同上
           'GLOBAL_BASELINE_NO_ENTITY_RANKING'                            AS pr_qualified_population,         -- 字面取值：血统 —— 明示本件为全窗基线族，无实体排序总体
           CAST(NULL AS BIGINT)                                           AS pr_global_population_n,          -- 空值取值：血统 —— 不适用
           CAST(NULL AS BIGINT)                                           AS pr_qualified_population_n,       -- 空值取值：血统 —— 不适用
           'NOT_APPLICABLE_GLOBAL_BASELINE'                               AS pr_calculation_method,           -- 字面取值：血统 —— 算法不适用
           'HF9g-P5'                                                      AS pr_calculation_version,          -- 字面取值：血统 —— 算法版本
           CAST(NULL AS STRING)                                           AS evidence_flag,                   -- 空值取值：证据旗标不适用于全窗基线
           CAST(NULL AS STRING)                                           AS evidence_rate,                   -- 空值取值：同上
           CAST(NULL AS DOUBLE)                                           AS hold_ci_halfwidth_approx,        -- 空值取值：同上
           'X 全窗基线 · 不参与实体赏罚'                                    AS action_priority                  -- 字面取值：★ D-14 斧正 —— 本族恒不入赏罚，取代原 100% 误标之「A」
    FROM q
    CROSS JOIN x_win e
  ) y
) z
-- ── 逐批 WHERE 阶梯（★ 口诀：上界 ＝ 下界 ＋ 100000，两数同进）──
--    本件 T_true 未测，无需先跑 T_true；以 0 / 100000 控制本批返回区间，末批由实际行数 < 100000 判定
--    WHERE z.audit_rn >        0 AND z.audit_rn <=   100000   -- 第 1 批
--    WHERE z.audit_rn >   100000 AND z.audit_rn <=   200000   -- 第 2 批
--    WHERE z.audit_rn >   200000 AND z.audit_rn <=   300000   -- 第 3 批
--    WHERE z.audit_rn >   300000 AND z.audit_rn <=   400000   -- 第 4 批
--    WHERE z.audit_rn >   400000 AND z.audit_rn <=   500000   -- 第 5 批
--    WHERE z.audit_rn >   500000 AND z.audit_rn <=   600000   -- 第 6 批
--    WHERE z.audit_rn >   600000 AND z.audit_rn <=   700000   -- 第 7 批
--    …余批类推。第 k 批：WHERE z.audit_rn > (k-1)*100000 AND z.audit_rn <= k*100000
--    某批返回 < 100000 行即为末批，其后不再取。
--
--    ⚠ 常见误写（务必避开）：只推下界而上界不动 ——
--        WHERE z.audit_rn > 100000 AND z.audit_rn <= 100000   ← 自相矛盾，恒为假，返回空集
--        WHERE z.audit_rn > 200000 AND z.audit_rn <= 100000   ← 同上，空集
--      两个数必须**同时**前进，且始终相差 100000。
--      下界 ＝ 上一批之上界；上界 ＝ 本批之上界。
WHERE z.audit_rn > 0 AND z.audit_rn <= 100000 -- ★ HF9c 本批区间
ORDER BY z.audit_rn;


-- ══════════════════════════════════════════════════════════════════════════════════════════════
-- 110. X_combo.csv   [总包行 2776~2857 · 原 6 列 ＋六层约 60 列]
--     典型学：M06 代理线　派生旗标：recent（s.x_rec = 1 · 仅供 CASE 条件聚合，全包无任何 WHERE/AND/HAVING 以此过滤）　连接：全窗基线
-- ══════════════════════════════════════════════════════════════════════════════════════════════
-- ★ W-64 · D-14 警示（本件属 x_win 族 · 66 件之一 · 详见 §Z 段 D-14 全案）
--   本件以 `CROSS JOIN x_win e` 接入全局基线，x_win 无 GROUP BY ⇒ 恒 1 行 ⇒ e.* 全行同值。
--   故：economic_value / roi_pr_global / risk_value / pr_stake / pr_global 恒为 0；
--       action_priority 每一行皆为「A 净亏最大十分位 · 优先复核」（Z 分支永不触发）；
--       evidence_rate 恒为最高档；vip_tier 由常数键分档 ⇒ 无信息且非确定。
--   ⇒ 本件决策层三列 **NOT_FOR_DECISION**，裁定前不得用于排班、抽查或汇报。
-- ── ① 先跑 T_true 留档（不足 100000 者一次导全，不必分批）──
-- ── ① T_true：HF9c 不再强制预跑完整 COUNT。
--    本批实际返回行数 < 100000 即判定为末批；全批完成后以各批 n_rows / audit_rn 范围核对总量。

-- ── ② 分批取数：第 1 批。第 k 批只改末行两数为 (k-1)*100000 与 k*100000 ──
--    审计字段二（REDTEAM 2026-08-24 裁定 · 四锁）：
--      audit_rn  全局观测坐标 —— 由**与原版审计版逐字同一**之排序键所生，两版可逐行对账
--      batch_id  物理分批信息 —— 该行所属批次，由 audit_rn 算得，非引擎所赋
--    ★ 锁三：二者皆为审计字段，**不得进入任何业务指标计算**。
--    ★ 锁四：两版经 audit_rn 逐行字段核验后，方可宣布输出完全一致。

-- ── ③ 每批取回后自证四数（任一不符即停手回报，禁止放行）──
--    n_rows        = COUNT(*)      须等于 COUNT(DISTINCT audit_rn)   （批内无重复）
--    audit_rn_min  = MIN(audit_rn) 须等于 (k-1)*100000 + 1           （与上批严丝合缝）
--    audit_rn_max  = MAX(audit_rn) 须等于 min + n_rows - 1           （批内无缺口）
--    全批取毕再验：各批 audit_rn 之并集 = 1 .. T_true，无缺号、无重号。
--     ★ 首行＝平台真净亏最多者（已扣退水与代理占成）。
--
SELECT z.*,
       CAST(FLOOR((z.audit_rn - 1) / 100000) + 1 AS INT)          AS batch_id,
       'A168_HF9F_20260827_0900' AS run_id,
       '2026-08-27 09:00:00' AS snapshot_sync_time
FROM (
  SELECT y.*,
         ROW_NUMBER() OVER (ORDER BY y.`residual_b` ASC, y.`roi_xagg` DESC, y.`flag_ip`, y.`flag_tail_p90`, y.`n_member`, y.`valid_bet`, y.`game_pnl`, y.`roi`) AS audit_rn
  FROM (
    WITH
      x_ranked AS (
    SELECT b.bet01, b.bet03, b.bet04, b.bet05, b.bet09, b.bet11, b.bet13,
           b.bet15, b.bet16, b.bet17, b.bet18, b.bet19, b.bet20, b.bet21,
           b.bet22, b.bet23, b.bet24, b.bet25, b.bet26, b.bet27, b.bet38, b.bet39, b.category, b.commission,
           b.dt, b.eid, b.ip, b.validbet, b.updatetime, b.sync_time,
           ROW_NUMBER() OVER (
             PARTITION BY b.bet01
             ORDER BY b.updatetime DESC, b.sync_time DESC, b.dt DESC)      AS x_rn
    FROM ods_mariadb_2b.ods_a168_bet02 b
    WHERE b.dt >= '2026-03-21' AND b.dt < '2026-08-07'
      AND b.bet02 = '101'
      AND b.sync_time <= '2026-08-27 09:00:00'
  ),
    x_testagent AS (
    SELECT age001 AS agent_id FROM ods_mariadb_2b.ods_a168_agent WHERE age022 = '1'
  ),
    x_bs0 AS (
    SELECT b.bet05 AS x_member, b.eid AS x_dealer, b.bet39 AS x_table,
           b.bet03 AS x_shoe, b.ip AS x_ip, b.bet09 AS x_product, b.dt AS x_date,
           CONCAT_WS('|', b.bet03, b.bet04, b.bet39)                      AS x_round,
           CONCAT_WS('|', b.bet39, b.bet03)                               AS x_tblshoe,
           CAST(NULLIF(TRIM(b.bet04),'') AS INT)                          AS x_rno,
           CASE WHEN b.dt >= '2026-07-08' THEN 1 ELSE 0 END               AS x_rec,
           CASE WHEN TRIM(b.commission)='1' THEN 1 ELSE 0 END             AS x_freecomm,
           CAST(NULLIF(TRIM(b.bet13),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_stake,
           CAST(NULLIF(TRIM(b.validbet),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_valid,
           CAST(NULLIF(TRIM(b.bet16),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_rebate,
           CAST(NULLIF(TRIM(b.bet17),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_net,
           CAST(NULLIF(TRIM(b.bet15),'') AS DECIMAL(20,6))                AS x_rbpct,
           COALESCE(CAST(NULLIF(TRIM(b.bet23),'') AS DECIMAL(20,6)),0)   AS x_agpct,
          NULLIF(CAST(NULLIF(TRIM(b.bet23),'') AS DECIMAL(20,6)),0)     AS x_rate1,
          NULLIF(CAST(NULLIF(TRIM(b.bet24),'') AS DECIMAL(20,6)),0)     AS x_rate2,
          NULLIF(CAST(NULLIF(TRIM(b.bet25),'') AS DECIMAL(20,6)),0)     AS x_rate3,
          NULLIF(CAST(NULLIF(TRIM(b.bet26),'') AS DECIMAL(20,6)),0)     AS x_rate4,
          NULLIF(CAST(NULLIF(TRIM(b.bet27),'') AS DECIMAL(20,6)),0)     AS x_rate5,
          (CASE WHEN NULLIF(CAST(NULLIF(TRIM(b.bet22),'') AS BIGINT),0) IS NOT NULL THEN 5
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet21),'') AS BIGINT),0) IS NOT NULL THEN 4
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet20),'') AS BIGINT),0) IS NOT NULL THEN 3
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet19),'') AS BIGINT),0) IS NOT NULL THEN 2
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet18),'') AS BIGINT),0) IS NOT NULL THEN 1
                ELSE 0 END)                                             AS x_chain_depth,
           CASE WHEN COALESCE(t1.agent_id,t2.agent_id,t3.agent_id,
                              t4.agent_id,t5.agent_id) IS NOT NULL
                THEN 1 ELSE 0 END                                        AS f_testline
    FROM x_ranked b
    LEFT JOIN x_testagent t1 ON t1.agent_id = b.bet18
    LEFT JOIN x_testagent t2 ON t2.agent_id = b.bet19
    LEFT JOIN x_testagent t3 ON t3.agent_id = b.bet20
    LEFT JOIN x_testagent t4 ON t4.agent_id = b.bet21
    LEFT JOIN x_testagent t5 ON t5.agent_id = b.bet22
    WHERE b.x_rn = 1
      AND b.category='1' AND UPPER(TRIM(b.bet38))='N'
      AND CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8)) > 0
  ),
  x_mk AS (
    SELECT s.*,
           CASE WHEN s.f_testline = 0 THEN 1 ELSE 0 END                 AS is_clean
    FROM x_bs0 s
  ),
  x_agg AS (
    SELECT s.x_member                                                        AS x_key,
           COUNT(*) AS n_bets, COUNT(DISTINCT s.x_round) AS n_rounds,
           COUNT(DISTINCT s.x_date) AS active_days, COUNT(DISTINCT s.x_tblshoe) AS active_shoes,
           COUNT(DISTINCT CONCAT_WS('|', s.x_date, s.x_table)) AS active_sessions,
           COUNT(DISTINCT s.x_table) AS n_tables, COUNT(DISTINCT s.x_dealer) AS n_dealers,
           COUNT(DISTINCT s.x_ip) AS n_ips, COUNT(DISTINCT s.x_product) AS n_products,
           MIN(s.x_date) AS first_seen_d, MAX(s.x_date) AS last_seen_d,
           SUM(s.x_stake) AS stake, SUM(s.x_valid) AS valid, SUM(s.x_rebate) AS rebate,
           SUM(s.x_net) AS net, SUM(-s.x_net *(100.0-s.x_agpct)/100.0) AS agent_cost,
           AVG(100.0-s.x_agpct)                   AS agent_pct,
           AVG(s.x_agpct)                         AS company_retain_pct,
           SUM(-s.x_net *s.x_agpct/100.0)         AS agent_cost_a_legacy,
           SUM(s.x_valid*s.x_agpct/100.0)         AS agent_cost_valid_base_legacy,
          AVG(COALESCE(s.x_rate1,100)) AS retain_pct_lv1, AVG(COALESCE(s.x_rate2,100)) AS retain_pct_lv2,
          AVG(COALESCE(s.x_rate3,100)) AS retain_pct_lv3, AVG(COALESCE(s.x_rate4,100)) AS retain_pct_lv4,
          AVG(COALESCE(s.x_rate5,100)) AS retain_pct_lv5, AVG(s.x_chain_depth) AS chain_depth_avg,
          AVG(COALESCE(100.0-s.x_rate1,0)) AS agent_pct_lv1, AVG(COALESCE(100.0-s.x_rate2,0)) AS agent_pct_lv2,
          AVG(COALESCE(100.0-s.x_rate3,0)) AS agent_pct_lv3, AVG(COALESCE(100.0-s.x_rate4,0)) AS agent_pct_lv4,
          AVG(COALESCE(100.0-s.x_rate5,0)) AS agent_pct_lv5,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate1,0)/100.0)                        AS agent_cost_lv1,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate2,0)/100.0)                        AS agent_cost_lv2,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate3,0)/100.0)                        AS agent_cost_lv3,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate4,0)/100.0)                        AS agent_cost_lv4,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate5,0)/100.0)                        AS agent_cost_lv5,
          SUM(-s.x_net*(COALESCE(100.0-s.x_rate1,0)+COALESCE(100.0-s.x_rate2,0)
                       +COALESCE(100.0-s.x_rate3,0)+COALESCE(100.0-s.x_rate4,0)
                       +COALESCE(100.0-s.x_rate5,0))/100.0)                   AS agent_cost_chain_additive,
          SUM(-s.x_net*(1.0 - CAST(COALESCE(s.x_rate1,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate2,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate3,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate4,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate5,100) AS DOUBLE)/100.0))
                                                                       AS agent_cost_chain_nested,
           AVG(s.x_rbpct) AS rbpct, AVG(s.x_freecomm*1.0) AS freecomm_rate,
           PERCENTILE_APPROX(s.x_stake,0.25) AS p25, PERCENTILE_APPROX(s.x_stake,0.50) AS p50,
           PERCENTILE_APPROX(s.x_stake,0.75) AS p75, PERCENTILE_APPROX(s.x_stake,0.90) AS p90,
           PERCENTILE_APPROX(s.x_stake,0.95) AS p95, PERCENTILE_APPROX(s.x_stake,0.99) AS p99,
           PERCENTILE_APPROX(s.x_valid,0.50) AS p50_valid,
           PERCENTILE_APPROX(s.x_net,0.50)   AS p50_profit,
           SUM(CASE WHEN s.x_rec = 1 THEN s.x_stake ELSE 0 END) AS st_in,
           SUM(CASE WHEN s.x_rec = 1 THEN 1 ELSE 0 END)         AS nb_in,
           SUM(CASE WHEN s.x_rec = 1 THEN s.x_net ELSE 0 END)   AS net_in,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN s.x_stake ELSE 0 END) AS st_out,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN 1 ELSE 0 END)         AS nb_out,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN s.x_net ELSE 0 END)   AS net_out,
           SUM(CASE WHEN s.x_rec=1 THEN s.x_stake ELSE 0 END) AS st_rec,
           SUM(CASE WHEN s.x_rec=1 THEN 1 ELSE 0 END)         AS nb_rec
    FROM x_mk s
    WHERE s.is_clean = 1
      AND s.x_member IS NOT NULL AND TRIM(CAST(s.x_member AS STRING)) <> ''
    GROUP BY s.x_member
  ),
  x_win AS (
    SELECT            COUNT(*) AS n_bets, COUNT(DISTINCT s.x_round) AS n_rounds,
           COUNT(DISTINCT s.x_date) AS active_days, COUNT(DISTINCT s.x_tblshoe) AS active_shoes,
           COUNT(DISTINCT CONCAT_WS('|', s.x_date, s.x_table)) AS active_sessions,
           COUNT(DISTINCT s.x_table) AS n_tables, COUNT(DISTINCT s.x_dealer) AS n_dealers,
           COUNT(DISTINCT s.x_ip) AS n_ips, COUNT(DISTINCT s.x_product) AS n_products,
           MIN(s.x_date) AS first_seen_d, MAX(s.x_date) AS last_seen_d,
           SUM(s.x_stake) AS stake, SUM(s.x_valid) AS valid, SUM(s.x_rebate) AS rebate,
           SUM(s.x_net) AS net, SUM(-s.x_net *(100.0-s.x_agpct)/100.0) AS agent_cost,
           AVG(100.0-s.x_agpct)                   AS agent_pct,
           AVG(s.x_agpct)                         AS company_retain_pct,
           SUM(-s.x_net *s.x_agpct/100.0)         AS agent_cost_a_legacy,
           SUM(s.x_valid*s.x_agpct/100.0)         AS agent_cost_valid_base_legacy,
          AVG(COALESCE(s.x_rate1,100)) AS retain_pct_lv1, AVG(COALESCE(s.x_rate2,100)) AS retain_pct_lv2,
          AVG(COALESCE(s.x_rate3,100)) AS retain_pct_lv3, AVG(COALESCE(s.x_rate4,100)) AS retain_pct_lv4,
          AVG(COALESCE(s.x_rate5,100)) AS retain_pct_lv5, AVG(s.x_chain_depth) AS chain_depth_avg,
          AVG(COALESCE(100.0-s.x_rate1,0)) AS agent_pct_lv1, AVG(COALESCE(100.0-s.x_rate2,0)) AS agent_pct_lv2,
          AVG(COALESCE(100.0-s.x_rate3,0)) AS agent_pct_lv3, AVG(COALESCE(100.0-s.x_rate4,0)) AS agent_pct_lv4,
          AVG(COALESCE(100.0-s.x_rate5,0)) AS agent_pct_lv5,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate1,0)/100.0)                        AS agent_cost_lv1,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate2,0)/100.0)                        AS agent_cost_lv2,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate3,0)/100.0)                        AS agent_cost_lv3,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate4,0)/100.0)                        AS agent_cost_lv4,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate5,0)/100.0)                        AS agent_cost_lv5,
          SUM(-s.x_net*(COALESCE(100.0-s.x_rate1,0)+COALESCE(100.0-s.x_rate2,0)
                       +COALESCE(100.0-s.x_rate3,0)+COALESCE(100.0-s.x_rate4,0)
                       +COALESCE(100.0-s.x_rate5,0))/100.0)                   AS agent_cost_chain_additive,
          SUM(-s.x_net*(1.0 - CAST(COALESCE(s.x_rate1,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate2,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate3,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate4,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate5,100) AS DOUBLE)/100.0))
                                                                       AS agent_cost_chain_nested,
           AVG(s.x_rbpct) AS rbpct, AVG(s.x_freecomm*1.0) AS freecomm_rate,
           PERCENTILE_APPROX(s.x_stake,0.25) AS p25, PERCENTILE_APPROX(s.x_stake,0.50) AS p50,
           PERCENTILE_APPROX(s.x_stake,0.75) AS p75, PERCENTILE_APPROX(s.x_stake,0.90) AS p90,
           PERCENTILE_APPROX(s.x_stake,0.95) AS p95, PERCENTILE_APPROX(s.x_stake,0.99) AS p99,
           PERCENTILE_APPROX(s.x_valid,0.50) AS p50_valid,
           PERCENTILE_APPROX(s.x_net,0.50)   AS p50_profit,
           SUM(CASE WHEN s.x_rec = 1 THEN s.x_stake ELSE 0 END) AS st_in,
           SUM(CASE WHEN s.x_rec = 1 THEN 1 ELSE 0 END)         AS nb_in,
           SUM(CASE WHEN s.x_rec = 1 THEN s.x_net ELSE 0 END)   AS net_in,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN s.x_stake ELSE 0 END) AS st_out,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN 1 ELSE 0 END)         AS nb_out,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN s.x_net ELSE 0 END)   AS net_out,
           SUM(CASE WHEN s.x_rec=1 THEN s.x_stake ELSE 0 END) AS st_rec,
           SUM(CASE WHEN s.x_rec=1 THEN 1 ELSE 0 END)         AS nb_rec
    FROM x_mk s
    WHERE s.is_clean = 1
      AND s.x_member IS NOT NULL AND TRIM(CAST(s.x_member AS STRING)) <> ''
  ),
      q AS (
        WITH ta AS (            -- 公司测试线代理（214 条，跨五级）
          SELECT DISTINCT age001 AS aid                                                                     -- 取列：产出「aid」
          FROM ods_mariadb_2b.ods_a168_agent WHERE age022 = '1'                                             -- 取数来源：取自代理主档（五级代理线归属来源）
        ),                                                                                                  -- 续行：收束上方的子查询或函数括号（交付件 X_combo.csv）
        rk AS (                                                                                             -- 公共表表达式：开启中间结果集 rk，其后各行为其定义体（交付件 X_combo.csv）
          SELECT b.bet01, b.updatetime, b.sync_time, b.dt, b.bet02,                                         -- 取列：起始取列子句，本行先列 b.bet01, b.updatetime, b.sync_time, b.dt, b.bet02，涉 bet02（游戏类别）、dt（营业日）
                 b.bet03, b.bet04, b.bet05, b.bet08, b.bet09,                                               -- 续行：接续上一取列子句，续列 b.bet03, b.bet04, b.bet05, b.bet08, b.bet09，涉 bet03（靴号）、bet04（局内序号）、bet05（会员号）
                 b.bet11, b.bet13, b.bet14, b.bet16, b.bet17,                                               -- 续行：接续上一取列子句，续列 b.bet11, b.bet13, b.bet14, b.bet16, b.bet17，涉 bet11（汇率）、bet13（下注金额）、bet14（派彩金额）
                 b.bet18, b.bet19, b.bet20, b.bet21, b.bet22,                                               -- 续行：接续上一取列子句，续列 b.bet18, b.bet19, b.bet20, b.bet21, b.bet22，涉 bet18（一级代理线）、bet19（二级代理线）、bet20（三级代理线）
                 b.bet38, b.bet39, b.category, b.eid, b.ip,                                                 -- 续行：接续上一取列子句，续列 b.bet38, b.bet39, b.category, b.eid, b.ip，涉 bet38（重對）、bet39（桌号）、eid（荷官工号）
                 b.validbet,                                                                                -- 续行：接续上一取列子句，续列 b.validbet，涉 validbet（有效投注（洗码量））
                 ROW_NUMBER() OVER (                                                                        -- 行号窗口表达式：以行号窗口取每组头部或去重，免出重复行
                   PARTITION BY b.bet01                                                                     -- 窗口分区：按 b.bet01 分组开窗，组内各自编号或排名
                   ORDER BY b.updatetime DESC, b.sync_time DESC, b.dt DESC) AS rn                           -- 排序：按 b.updatetime（降序）, b.sync_time（降序）, b.dt（降序）) AS rn 排列；导出必带排序，否则分页无稳定序（曾致 36.49% 重复行）
          FROM ods_mariadb_2b.ods_a168_bet02 b                                                              -- 取数来源：取自注单明细表（金额与行为口径的第一料源）
          WHERE b.dt >= '2026-03-21' AND b.dt < '2026-08-07' AND b.bet02 = '101'
      AND b.sync_time <= '2026-08-27 09:00:00'                            -- 过滤条件：限定 b.dt不少于 '2026-03-21'、b.dt小于 '2026-08-07'、b.bet02等于 '101'，涉 bet02（游戏类别）、dt（营业日）
        ),                                                                                                  -- 续行：收束上方的子查询或函数括号（交付件 X_combo.csv）
        vd AS (                                                                                             -- 公共表表达式：开启中间结果集 vd，其后各行为其定义体（交付件 X_combo.csv）
          SELECT r.* FROM rk r                                                                              -- 取列：整体承接上游结果集的全部字段，不再逐列列举，取自本条自建的中间结果集 rk
          LEFT JOIN ta t1 ON t1.aid = r.bet18                                                               -- 左连接：取自本条自建的中间结果集 ta，连接键为 bet18（一级代理线）
          LEFT JOIN ta t2 ON t2.aid = r.bet19                                                               -- 左连接：取自本条自建的中间结果集 ta，连接键为 bet19（二级代理线）
          LEFT JOIN ta t3 ON t3.aid = r.bet20                                                               -- 左连接：取自本条自建的中间结果集 ta，连接键为 bet20（三级代理线）
          LEFT JOIN ta t4 ON t4.aid = r.bet21                                                               -- 左连接：取自本条自建的中间结果集 ta，连接键为 bet21（四级代理线）
          LEFT JOIN ta t5 ON t5.aid = r.bet22                                                               -- 左连接：取自本条自建的中间结果集 ta，连接键为 bet22（五级代理线）
          WHERE r.rn = 1 AND r.category = '1' AND UPPER(TRIM(r.bet38)) = 'N'                                -- 过滤条件：限定 r.rn等于 1、r.category等于 '1'、UPPER(TRIM(r.bet38))等于 'N'，涉 bet38（重對）
            AND CAST(NULLIF(TRIM(r.bet05),'') AS BIGINT) > 0                                                -- 并列条件：限定 CAST(NULLIF(TRIM(r.bet05),'') AS BIGINT)大于 0，涉 bet05（会员号）
            AND CAST(NULLIF(TRIM(r.bet11),'') AS DECIMAL(20,8)) > 0                                         -- 并列条件：限定 CAST(NULLIF(TRIM(r.bet11),'') AS DECIMAL(20,8))大于 0，涉 bet11（汇率）
            AND NULLIF(TRIM(r.bet08),'') IS NOT NULL                                                        -- 并列条件：限定该值非空，涉 bet08（下注时间）
            AND COALESCE(t1.aid, t2.aid, t3.aid, t4.aid, t5.aid) IS NULL                                    -- 并列条件：限定该值为空——本包以左连接加空值判定替代 EXISTS，因 StarRocks 不支持 EXISTS 配多列 IN
        ),                                                                                                  -- 续行：收束上方的子查询或函数括号（交付件 X_combo.csv）
        bs AS (                                                                                             -- 公共表表达式：开启中间结果集 bs，其后各行为其定义体（交付件 X_combo.csv）
          SELECT v.bet05 AS member_id, v.eid AS dealer_id, v.ip AS bet_ip,                                  -- 取列：起始取列子句，本行先取「bet_ip」，涉 bet05（会员号）、eid（荷官工号）、bet_ip（下注 IP）
                 v.bet18 AS lv1, v.bet19 AS lv2, v.bet20 AS lv3, v.bet21 AS lv4, v.bet22 AS lv5, CONCAT_WS('|', COALESCE(CAST(NULLIF(CAST(NULLIF(TRIM(v.bet18),'') AS BIGINT),0) AS STRING),'-'), COALESCE(CAST(NULLIF(CAST(NULLIF(TRIM(v.bet19),'') AS BIGINT),0) AS STRING),'-'), COALESCE(CAST(NULLIF(CAST(NULLIF(TRIM(v.bet20),'') AS BIGINT),0) AS STRING),'-'), COALESCE(CAST(NULLIF(CAST(NULLIF(TRIM(v.bet21),'') AS BIGINT),0) AS STRING),'-'), COALESCE(CAST(NULLIF(CAST(NULLIF(TRIM(v.bet22),'') AS BIGINT),0) AS STRING),'-')) AS chain_key, v.bet09 AS bet_side, v.dt AS bet_date,                                     -- 取值表达式：取用 bet09（玩法）、bet20（三级代理线）、dt（营业日），产出「bet_date」
                 CONCAT_WS('|', v.bet03, v.bet04, v.bet39) AS round_key,                                    -- 取值表达式：取用 bet03（靴号）、bet04（局内序号）、bet39（桌号），产出「round_key」
                 v.bet39 AS table_id,                                                                       -- 取值表达式：取用 bet39（桌号），产出「table_id」
                 CAST(NULLIF(TRIM(v.bet08),'') AS DATETIME) AS t_bet,                                       -- 取值表达式：先去空白、空串归 NULL，再显式转型——本库字段多为 varchar，不转型即比较失真，产出「t_bet」
                 CAST(NULLIF(TRIM(v.bet13),'') AS DECIMAL(20,4))                                            -- 取值表达式：先去空白、空串归 NULL，再显式转型——本库字段多为 varchar，不转型即比较失真
                   / CAST(NULLIF(TRIM(v.bet11),'') AS DECIMAL(20,8)) AS stake,                              -- 除法或乘法计算：先去空白、空串归 NULL，再显式转型——本库字段多为 varchar，不转型即比较失真，产出「stake」
                 CAST(NULLIF(TRIM(v.validbet),'') AS DECIMAL(20,4))                                         -- 取值表达式：先去空白、空串归 NULL，再显式转型——本库字段多为 varchar，不转型即比较失真
                   / CAST(NULLIF(TRIM(v.bet11),'') AS DECIMAL(20,8)) AS valid_bet,                          -- 除法或乘法计算：先去空白、空串归 NULL，再显式转型——本库字段多为 varchar，不转型即比较失真，产出「valid_bet」
                 (CAST(NULLIF(TRIM(v.bet14),'') AS DECIMAL(20,4))                                           -- 续行：先去空白、空串归 NULL，再显式转型——本库字段多为 varchar，不转型即比较失真
                  - CAST(NULLIF(TRIM(v.bet13),'') AS DECIMAL(20,4)))                                        -- 加减计算：先去空白、空串归 NULL，再显式转型——本库字段多为 varchar，不转型即比较失真
                   / CAST(NULLIF(TRIM(v.bet11),'') AS DECIMAL(20,8)) AS game_pnl,                           -- 除法或乘法计算：先去空白、空串归 NULL，再显式转型——本库字段多为 varchar，不转型即比较失真，产出「game_pnl」
                 CAST(NULLIF(TRIM(v.bet16),'') AS DECIMAL(20,4))                                            -- 取值表达式：先去空白、空串归 NULL，再显式转型——本库字段多为 varchar，不转型即比较失真
                   / CAST(NULLIF(TRIM(v.bet11),'') AS DECIMAL(20,8)) AS rebate,                             -- 除法或乘法计算：先去空白、空串归 NULL，再显式转型——本库字段多为 varchar，不转型即比较失真，产出「rebate」
                 CAST(NULLIF(TRIM(v.bet17),'') AS DECIMAL(20,4))                                            -- 取值表达式：先去空白、空串归 NULL，再显式转型——本库字段多为 varchar，不转型即比较失真
                   / CAST(NULLIF(TRIM(v.bet11),'') AS DECIMAL(20,8)) AS net_pnl                             -- 除法或乘法计算：先去空白、空串归 NULL，再显式转型——本库字段多为 varchar，不转型即比较失真，产出「net_pnl」
          FROM vd v                                                                                         -- 取数来源：取自本条自建的中间结果集 vd
        ),                                                                                                  -- 续行：收束上方的子查询或函数括号（交付件 X_combo.csv）
        gi AS (SELECT CONCAT_WS('|', gi002, gi003, gi011) AS round_key,                                     -- 取值表达式：取用 gi011（桌号）、round_key（局键），产出「round_key」
                      gi004 AS t_open, gi006 AS t_reveal                                                    -- 取值表达式：取用 gi004（局开始时刻）、gi006（开牌时刻），产出「t_reveal」
               FROM ods_mariadb_2b.ods_a168_game_info                                                       -- 取数来源：取自局信息表（靴局、开牌与桌号的时序基准）
               WHERE gi001='101' AND gi013='1' AND is_lock='N'                                              -- 过滤条件：限定 gi001等于 '101'、gi013等于 '1'、is_lock等于 'N'，涉 gi001（局主键）
                 AND gi004>='2026-03-21' AND gi004<'2026-08-07'),                                           -- 并列条件：限定 gi004不少于 '2026-03-21'，涉 gi004（局开始时刻）
        pr AS (SELECT b.member_id, b.bet_ip, b.valid_bet, b.game_pnl,                                       -- 取值表达式：取用 valid_bet（有效投注（洗码量））、bet_ip（下注 IP）、game_pnl（游戏净输赢）
                      (UNIX_TIMESTAMP(b.t_bet)-UNIX_TIMESTAMP(g.t_open))*1.0                                -- 取值表达式：比率之分子，乘 1.0 以避整数除法截断
                      /NULLIF(UNIX_TIMESTAMP(g.t_reveal)-UNIX_TIMESTAMP(g.t_open),0) AS progress            -- 除法或乘法计算：产出「progress」
               FROM bs b JOIN gi g ON g.round_key=b.round_key),                                             -- 取数来源：取自本条自建的中间结果集 bs，连接键为 round_key（局键）
        ipn AS (SELECT bet_ip, COUNT(DISTINCT member_id) AS n_member_ip                                     -- 取值表达式：统计去重个数，产出「n_member_ip」
                FROM bs WHERE NULLIF(TRIM(bet_ip),'') IS NOT NULL GROUP BY bet_ip),                         -- 取数来源：取自本条自建的中间结果集 bs
        mk AS (SELECT p.member_id,                                                                          -- 取值表达式：取用 member_id（会员号）
                 MAX(CASE WHEN i.n_member_ip >= 20 THEN 1 ELSE 0 END) AS flag_ip,                           -- 取最大值表达式：产出「flag_ip」
                 SUM(CASE WHEN p.progress>=0.90 THEN 1 ELSE 0 END)*1.0/COUNT(*) AS tail_share,              -- 汇总表达式：计数，产出「tail_share」
                                                                                                            -- ⚠ 同名异义警示（2026-08-17）：本处 tail_share 用 progress（物理时间进度）口径，
                                                                                                            --   与 §D-06 用 max_pr（局内注单时序分位）口径的同名字段【不可比、不可互换】；
                                                                                                            --   两者分母亦异：本处为注单数，D-06 为玩家-局数。建议日后正名区分。
                 SUM(p.valid_bet) AS valid_bet, SUM(p.game_pnl) AS game_pnl                                 -- 汇总表达式：取用 valid_bet（有效投注（洗码量））、game_pnl（游戏净输赢），产出「game_pnl」
               FROM pr p LEFT JOIN ipn i ON i.bet_ip=p.bet_ip                                               -- 取数来源：取自本条自建的中间结果集 pr，连接键为 bet_ip（下注 IP）
               WHERE p.progress BETWEEN 0 AND 1.5                                                           -- 过滤条件：限定落入闭区间
               GROUP BY p.member_id HAVING COUNT(*) >= 30)                                                  -- 分组：按 p.member_id HAVING COUNT(*) >= 30) 汇总
        SELECT flag_ip,                                                                                     -- 取列：起始取列子句，本行先列 flag_ip
               CASE WHEN tail_share>=0.47 THEN 1 ELSE 0 END AS flag_tail_p90,                               -- 条件分支：产出「flag_tail_p90」
                                                                                                            -- ⚠ 阈值溯源（2026-08-17 实测）：0.47 为硬编码，别名虽称 p90，但实测
                                                                                                            --   tail_share 的 P90 = 0.4156（S_player_tail.csv 159,603 行），偏差 -11.6%。
                                                                                                            --   按 0.47 切命中 10,763 人（6.74%）；按真 P90 切 15,961 人（10.00%）。
                                                                                                            --   【基准】0.47（现行代码）｜【建议默认】改为渲染时实算 P90，勿写死。
                                                                                                            --   另：tail_share>0.6 命中 3,590 人（2.25%），而实测分布【单峰右偏、无双峰】，
                                                                                                            --   0.6 不对应任何自然分界，作为「极度偏好压哨」判据无统计依据，建议撤销。
               COUNT(*) AS n_member, SUM(valid_bet) AS valid_bet,                                           -- 计数表达式：汇总，取用 valid_bet（有效投注（洗码量））、n_member（会员数），产出「valid_bet」
               SUM(game_pnl) AS game_pnl,                                                                   -- 汇总表达式：取用 game_pnl（游戏净输赢），产出「game_pnl」
               SUM(game_pnl)/NULLIF(SUM(valid_bet),0) AS roi                                                -- 汇总表达式：取用 valid_bet（有效投注（洗码量））、game_pnl（游戏净输赢），产出「roi」
        FROM mk GROUP BY 1,2
      )
    SELECT q.*,
           -- 一·经济层
           ROUND(e.stake,4) AS stake, ROUND(e.valid,4) AS valid_bet_xagg,
           ROUND(-e.net,4) AS profit, e.n_bets, e.n_rounds,
           ROUND(e.net/NULLIF(e.stake,0),8) AS roi_xagg,
           ROUND(e.net_in/NULLIF(e.st_in,0),8) AS roi_recent,
           ROUND(e.net_out/NULLIF(e.st_out,0),8) AS roi_non_recent,
           ROUND((e.net-e.rebate)/NULLIF(e.stake,0),8) AS roi_ex_rebate,
           ROUND(e.net,4) AS roi_numerator, ROUND(e.stake,4) AS roi_denominator,
           CASE WHEN e.stake IS NULL THEN 'NULL_DENOM' WHEN e.stake<=0 THEN 'ZERO_DENOM'
                WHEN e.n_bets<30 THEN 'THIN_EXPOSURE' ELSE 'OK' END AS roi_denominator_status,
           ROUND(e.rebate,4) AS rebate_cost, ROUND(e.agent_cost,4)                           AS cost_complement_b,
       ROUND(e.agent_pct,4)                            AS pct_complement,
       ROUND(e.company_retain_pct,4)                   AS pct_top_bet23,
       'AG03-UNRESOLVED'                                     AS agent_formula_version,
      'ALL5_LEVELS_bet23_to_bet27'                    AS agent_level_scope,
      ROUND(e.agent_cost_lv1,4) AS agent_cost_lv1, ROUND(e.agent_cost_lv2,4) AS agent_cost_lv2,
      ROUND(e.agent_cost_lv3,4) AS agent_cost_lv3, ROUND(e.agent_cost_lv4,4) AS agent_cost_lv4,
      ROUND(e.agent_cost_lv5,4) AS agent_cost_lv5,
      ROUND(e.agent_pct_lv1,6) AS agent_pct_lv1, ROUND(e.agent_pct_lv2,6) AS agent_pct_lv2,
      ROUND(e.agent_pct_lv3,6) AS agent_pct_lv3, ROUND(e.agent_pct_lv4,6) AS agent_pct_lv4,
      ROUND(e.agent_pct_lv5,6) AS agent_pct_lv5,
      ROUND(e.retain_pct_lv1,6) AS retain_pct_lv1, ROUND(e.retain_pct_lv2,6) AS retain_pct_lv2,
      ROUND(e.retain_pct_lv3,6) AS retain_pct_lv3, ROUND(e.retain_pct_lv4,6) AS retain_pct_lv4,
      ROUND(e.retain_pct_lv5,6) AS retain_pct_lv5, ROUND(e.chain_depth_avg,4) AS chain_depth_avg,
      ROUND(e.agent_cost_chain_additive,4)            AS agent_cost_chain_additive,
      ROUND(e.agent_cost_chain_nested,4)              AS agent_cost_chain_nested,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_additive,4) AS residual_chain_additive,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_nested,4)   AS residual_chain_nested,
      'PENDING_AG03'                                  AS decision_status,
      'FALSE'                                         AS admit_to_risk_decision,
      'NOT_FOR_ENFORCEMENT'                           AS deliverable_class,
       ROUND(e.agent_cost_a_legacy,4)                  AS agent_cost_a_legacy,
       ROUND(e.agent_cost_valid_base_legacy,4)         AS agent_cost_valid_base_legacy,
           ROUND(-e.net-e.rebate,4)                        AS ngr,
       ROUND(-e.net-e.rebate-e.agent_cost,4)           AS residual_b,
       ROUND(-e.net-e.rebate-e.agent_cost_a_legacy,4)  AS residual_a,
           ROUND((-e.net-e.rebate)/NULLIF(e.stake,0),8)    AS ngr_rate,
       ROUND((-e.net-e.rebate-e.agent_cost)/NULLIF(e.stake,0),8)   AS residual_b_rate,
      -- 【HF9c · canonical accounting contract】
      --   以下 canonical 字段只增加明确 scope；不删除、不覆盖既有字段。
      --   formal_bet23_* 保持 HF9b 当前生产公式及其 NULL/0 语义；
      --   lv1~lv5 / additive / nested 则分别采用各自原始 e.* 成本字段，
      --   rate 一律从未舍入的 e.* 分子 / e.stake 计算，禁止由展示值反算。
      ROUND(e.agent_cost,4) AS agent_cost_bet23_formal_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost,4) AS net_margin_bet23_formal_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost)/NULLIF(e.stake,0),8) AS net_margin_bet23_formal_rate_canonical,
      ROUND(e.agent_cost_lv1,4) AS agent_cost_lv1_bet23_canonical,
      ROUND(e.agent_cost_lv2,4) AS agent_cost_lv2_bet24_canonical,
      ROUND(e.agent_cost_lv3,4) AS agent_cost_lv3_bet25_canonical,
      ROUND(e.agent_cost_lv4,4) AS agent_cost_lv4_bet26_canonical,
      ROUND(e.agent_cost_lv5,4) AS agent_cost_lv5_bet27_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_lv1,4) AS net_margin_lv1_bet23_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_lv1)/NULLIF(e.stake,0),8) AS net_margin_lv1_bet23_rate_canonical,
      ROUND(e.agent_cost_chain_additive,4) AS agent_cost_chain_additive_canonical,
      ROUND(e.agent_cost_chain_nested,4) AS agent_cost_chain_nested_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_additive,4) AS net_margin_chain_additive_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_nested,4) AS net_margin_chain_nested_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_chain_additive)/NULLIF(e.stake,0),8) AS net_margin_chain_additive_rate_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_chain_nested)/NULLIF(e.stake,0),8) AS net_margin_chain_nested_rate_canonical,
       ROUND((-e.net-e.rebate-e.agent_cost_a_legacy)/NULLIF(e.stake,0),8) AS residual_a_rate,
           -- 二·分布层
           ROUND(e.stake/NULLIF(e.n_bets,0),4) AS avg_stake_per_bet,
           ROUND(e.valid/NULLIF(e.n_rounds,0),4) AS avg_valid_bet_per_round,
           ROUND(-e.net/NULLIF(e.n_rounds,0),4) AS avg_profit_per_round,
           ROUND(-e.net/NULLIF(e.active_days,0),4) AS avg_profit_per_day,
           ROUND(-e.net/NULLIF(e.active_shoes,0),4) AS avg_profit_per_shoe,
           ROUND(e.stake/NULLIF(e.active_days,0),4) AS avg_stake_per_active_day,
           ROUND(e.n_rounds*1.0/NULLIF(e.active_days,0),4) AS avg_rounds_per_active_day,
           ROUND(e.st_in/NULLIF(e.nb_in,0),4) AS avg_stake_recent,
           ROUND(e.st_out/NULLIF(e.nb_out,0),4) AS avg_stake_non_recent,
           ROUND(e.p25,4) AS p25_stake, ROUND(e.p50,4) AS p50_stake, ROUND(e.p75,4) AS p75_stake,
           ROUND(e.p90,4) AS p90_stake, ROUND(e.p95,4) AS p95_stake, ROUND(e.p99,4) AS p99_stake,
           ROUND(e.p50_valid,4) AS p50_valid_bet, ROUND(e.p50_profit,4) AS p50_profit,
           ROUND(e.p95/NULLIF(e.p50,0),6) AS p95_over_p50,
           ROUND(e.p99/NULLIF(e.p50,0),6) AS p99_over_p50,
           ROUND((e.stake/NULLIF(e.n_bets,0))/NULLIF(e.p50,0),6) AS avg_over_p50,
           -- 三·关系层
           e.n_tables AS common_table_count, e.n_dealers AS common_dealer_count,
           e.n_ips AS common_ip_count, e.n_products AS common_product_count,
           ROUND(e.st_in/NULLIF(e.stake,0),8) AS share_recent,
           -- 四·rate 层
           ROUND(-e.net/NULLIF(e.stake,0),8) AS hold_rate,
           ROUND(-e.net_in/NULLIF(e.st_in,0),8) AS hold_rate_recent,
           ROUND(e.rebate/NULLIF(e.valid,0),8) AS rebate_rate_actual,
           ROUND(e.rbpct,6) AS rebate_pct_config,
           ROUND(e.valid/NULLIF(e.stake,0),6) AS turnover_multiple,
           ROUND(e.freecomm_rate,6) AS free_comm_rate,
           ROUND(e.net_in/NULLIF(e.st_in,0)-e.net_out/NULLIF(e.st_out,0),8) AS roi_delta_recent,
           -- 五·动态层
           e.first_seen_d AS first_seen, e.last_seen_d AS last_seen,
           e.active_days, e.active_shoes, e.active_sessions,
           DATEDIFF(e.last_seen_d, e.first_seen_d)+1 AS span_days,
           ROUND(e.active_days*1.0/NULLIF(DATEDIFF(e.last_seen_d,e.first_seen_d)+1,0),6) AS persistence,
           ROUND((e.st_in/NULLIF(e.nb_in,0))/NULLIF(e.st_out/NULLIF(e.nb_out,0),0),6) AS ramp_recent_vs_prior,
           ROUND((e.st_rec/NULLIF(e.nb_rec,0))/NULLIF(e.stake/NULLIF(e.n_bets,0),0),6) AS ramp_recent_vs_all,
           ROUND((e.st_rec/NULLIF(e.stake,0))/0.30,6) AS stake_ramp,
           -- 六·决策层（HF9g-P5 · D-14 斧正 —— 本件属【全窗基线族】，相对刻度与决策标签一律 NULL）
           --   病灶：x_win 系全窗单行聚合（无 GROUP BY，恒 1 行，此为设计使然，非缺陷），
           --         经 CROSS JOIN 接入后 e.* 全行同值；六层之 NTILE / PERCENT_RANK 施于常数即退化，
           --         PERCENT_RANK 恒 0 ⇒ action_priority 恒判 A，全件 100% 误标。
           --   ★ 斧正原则：不给 x_win 补 GROUP BY —— 那会改变其「全窗基线」语义，属退化。
           --     正解与 #018 之 G-05／G-06 同治：范围外之行不得接受任何下游评分与决策标签。
           --   ★ 本件之 e.* 仍照常供其它列作全窗基线使用，仅六层相对刻度与决策标签置 NULL。
           CAST(NULL AS INT)                                              AS vip_tier,                        -- 空值取值：全窗基线族无实体可分档，置 NULL（NULL＝不适用，非 0）
           CAST(NULL AS DOUBLE)                                           AS economic_value,                  -- 空值取值：同上，禁以常数百分位冒充经济价值
           CAST(NULL AS DOUBLE)                                           AS roi_pr_global,                   -- 空值取值：同上
           CAST(NULL AS DOUBLE)                                           AS risk_value,                      -- 空值取值：兼容列，同上
           CAST(NULL AS DOUBLE)                                           AS pr_stake,                        -- 空值取值：兼容列，同上
           CAST(NULL AS DOUBLE)                                           AS pr_global,                       -- 空值取值：同上
           CAST(NULL AS DOUBLE)                                           AS pr_qualified,                    -- 空值取值：同上
           'GLOBAL_BASELINE_NO_ENTITY_RANKING'                            AS pr_qualified_population,         -- 字面取值：血统 —— 明示本件为全窗基线族，无实体排序总体
           CAST(NULL AS BIGINT)                                           AS pr_global_population_n,          -- 空值取值：血统 —— 不适用
           CAST(NULL AS BIGINT)                                           AS pr_qualified_population_n,       -- 空值取值：血统 —— 不适用
           'NOT_APPLICABLE_GLOBAL_BASELINE'                               AS pr_calculation_method,           -- 字面取值：血统 —— 算法不适用
           'HF9g-P5'                                                      AS pr_calculation_version,          -- 字面取值：血统 —— 算法版本
           CAST(NULL AS STRING)                                           AS evidence_flag,                   -- 空值取值：证据旗标不适用于全窗基线
           CAST(NULL AS STRING)                                           AS evidence_rate,                   -- 空值取值：同上
           CAST(NULL AS DOUBLE)                                           AS hold_ci_halfwidth_approx,        -- 空值取值：同上
           'X 全窗基线 · 不参与实体赏罚'                                    AS action_priority                  -- 字面取值：★ D-14 斧正 —— 本族恒不入赏罚，取代原 100% 误标之「A」
    FROM q
    CROSS JOIN x_win e
  ) y
) z
-- ── 逐批 WHERE 阶梯（★ 口诀：上界 ＝ 下界 ＋ 100000，两数同进）──
--    本件 T_true 未测，无需先跑 T_true；以 0 / 100000 控制本批返回区间，末批由实际行数 < 100000 判定
--    WHERE z.audit_rn >        0 AND z.audit_rn <=   100000   -- 第 1 批
--    WHERE z.audit_rn >   100000 AND z.audit_rn <=   200000   -- 第 2 批
--    WHERE z.audit_rn >   200000 AND z.audit_rn <=   300000   -- 第 3 批
--    WHERE z.audit_rn >   300000 AND z.audit_rn <=   400000   -- 第 4 批
--    WHERE z.audit_rn >   400000 AND z.audit_rn <=   500000   -- 第 5 批
--    WHERE z.audit_rn >   500000 AND z.audit_rn <=   600000   -- 第 6 批
--    WHERE z.audit_rn >   600000 AND z.audit_rn <=   700000   -- 第 7 批
--    …余批类推。第 k 批：WHERE z.audit_rn > (k-1)*100000 AND z.audit_rn <= k*100000
--    某批返回 < 100000 行即为末批，其后不再取。
--
--    ⚠ 常见误写（务必避开）：只推下界而上界不动 ——
--        WHERE z.audit_rn > 100000 AND z.audit_rn <= 100000   ← 自相矛盾，恒为假，返回空集
--        WHERE z.audit_rn > 200000 AND z.audit_rn <= 100000   ← 同上，空集
--      两个数必须**同时**前进，且始终相差 100000。
--      下界 ＝ 上一批之上界；上界 ＝ 本批之上界。
WHERE z.audit_rn > 0 AND z.audit_rn <= 100000 -- ★ HF9c 本批区间
ORDER BY z.audit_rn;


-- ══════════════════════════════════════════════════════════════════════════════════════════════
-- 111. Z01_table_inventory.csv   [总包行 561~579 · 原 5 列 ＋六层约 60 列]
--     典型学：Z00 基建/元数据　派生旗标：recent（s.x_rec = 1 · 仅供 CASE 条件聚合，全包无任何 WHERE/AND/HAVING 以此过滤）　连接：全窗基线
-- ══════════════════════════════════════════════════════════════════════════════════════════════
-- ★ W-64 · D-14 警示（本件属 x_win 族 · 66 件之一 · 详见 §Z 段 D-14 全案）
--   本件以 `CROSS JOIN x_win e` 接入全局基线，x_win 无 GROUP BY ⇒ 恒 1 行 ⇒ e.* 全行同值。
--   故：economic_value / roi_pr_global / risk_value / pr_stake / pr_global 恒为 0；
--       action_priority 每一行皆为「A 净亏最大十分位 · 优先复核」（Z 分支永不触发）；
--       evidence_rate 恒为最高档；vip_tier 由常数键分档 ⇒ 无信息且非确定。
--   ⇒ 本件决策层三列 **NOT_FOR_DECISION**，裁定前不得用于排班、抽查或汇报。
-- ── ① 先跑 T_true 留档（不足 100000 者一次导全，不必分批）──
-- ── ① T_true：HF9c 不再强制预跑完整 COUNT。
--    本批实际返回行数 < 100000 即判定为末批；全批完成后以各批 n_rows / audit_rn 范围核对总量。

-- ── ② 分批取数：第 1 批。第 k 批只改末行两数为 (k-1)*100000 与 k*100000 ──
--    审计字段二（REDTEAM 2026-08-24 裁定 · 四锁）：
--      audit_rn  全局观测坐标 —— 由**与原版审计版逐字同一**之排序键所生，两版可逐行对账
--      batch_id  物理分批信息 —— 该行所属批次，由 audit_rn 算得，非引擎所赋
--    ★ 锁三：二者皆为审计字段，**不得进入任何业务指标计算**。
--    ★ 锁四：两版经 audit_rn 逐行字段核验后，方可宣布输出完全一致。

-- ── ③ 每批取回后自证四数（任一不符即停手回报，禁止放行）──
--    n_rows        = COUNT(*)      须等于 COUNT(DISTINCT audit_rn)   （批内无重复）
--    audit_rn_min  = MIN(audit_rn) 须等于 (k-1)*100000 + 1           （与上批严丝合缝）
--    audit_rn_max  = MAX(audit_rn) 须等于 min + n_rows - 1           （批内无缺口）
--    全批取毕再验：各批 audit_rn 之并集 = 1 .. T_true，无缺号、无重号。
--     ★ 首行＝平台真净亏最多者（已扣退水与代理占成）。
--
SELECT z.*,
       CAST(FLOOR((z.audit_rn - 1) / 100000) + 1 AS INT)          AS batch_id,
       'A168_HF9F_20260827_0900' AS run_id,
       '2026-08-27 09:00:00' AS snapshot_sync_time
FROM (
  SELECT y.*,
         ROW_NUMBER() OVER (ORDER BY y.`residual_b` ASC, y.`roi` DESC, y.`表名`, y.`表类型`, y.`估计行数`, y.`表注释`, y.`疑似性质`) AS audit_rn
  FROM (
    WITH
      x_ranked AS (
    SELECT b.bet01, b.bet03, b.bet04, b.bet05, b.bet09, b.bet11, b.bet13,
           b.bet15, b.bet16, b.bet17, b.bet18, b.bet19, b.bet20, b.bet21,
           b.bet22, b.bet23, b.bet24, b.bet25, b.bet26, b.bet27, b.bet38, b.bet39, b.category, b.commission,
           b.dt, b.eid, b.ip, b.validbet, b.updatetime, b.sync_time,
           ROW_NUMBER() OVER (
             PARTITION BY b.bet01
             ORDER BY b.updatetime DESC, b.sync_time DESC, b.dt DESC)      AS x_rn
    FROM ods_mariadb_2b.ods_a168_bet02 b
    WHERE b.dt >= '2026-03-21' AND b.dt < '2026-08-07'
      AND b.bet02 = '101'
      AND b.sync_time <= '2026-08-27 09:00:00'
  ),
    x_testagent AS (
    SELECT age001 AS agent_id FROM ods_mariadb_2b.ods_a168_agent WHERE age022 = '1'
  ),
    x_bs0 AS (
    SELECT b.bet05 AS x_member, b.eid AS x_dealer, b.bet39 AS x_table,
           b.bet03 AS x_shoe, b.ip AS x_ip, b.bet09 AS x_product, b.dt AS x_date,
           CONCAT_WS('|', b.bet03, b.bet04, b.bet39)                      AS x_round,
           CONCAT_WS('|', b.bet39, b.bet03)                               AS x_tblshoe,
           CAST(NULLIF(TRIM(b.bet04),'') AS INT)                          AS x_rno,
           CASE WHEN b.dt >= '2026-07-08' THEN 1 ELSE 0 END               AS x_rec,
           CASE WHEN TRIM(b.commission)='1' THEN 1 ELSE 0 END             AS x_freecomm,
           CAST(NULLIF(TRIM(b.bet13),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_stake,
           CAST(NULLIF(TRIM(b.validbet),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_valid,
           CAST(NULLIF(TRIM(b.bet16),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_rebate,
           CAST(NULLIF(TRIM(b.bet17),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_net,
           CAST(NULLIF(TRIM(b.bet15),'') AS DECIMAL(20,6))                AS x_rbpct,
           COALESCE(CAST(NULLIF(TRIM(b.bet23),'') AS DECIMAL(20,6)),0)   AS x_agpct,
          NULLIF(CAST(NULLIF(TRIM(b.bet23),'') AS DECIMAL(20,6)),0)     AS x_rate1,
          NULLIF(CAST(NULLIF(TRIM(b.bet24),'') AS DECIMAL(20,6)),0)     AS x_rate2,
          NULLIF(CAST(NULLIF(TRIM(b.bet25),'') AS DECIMAL(20,6)),0)     AS x_rate3,
          NULLIF(CAST(NULLIF(TRIM(b.bet26),'') AS DECIMAL(20,6)),0)     AS x_rate4,
          NULLIF(CAST(NULLIF(TRIM(b.bet27),'') AS DECIMAL(20,6)),0)     AS x_rate5,
          (CASE WHEN NULLIF(CAST(NULLIF(TRIM(b.bet22),'') AS BIGINT),0) IS NOT NULL THEN 5
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet21),'') AS BIGINT),0) IS NOT NULL THEN 4
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet20),'') AS BIGINT),0) IS NOT NULL THEN 3
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet19),'') AS BIGINT),0) IS NOT NULL THEN 2
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet18),'') AS BIGINT),0) IS NOT NULL THEN 1
                ELSE 0 END)                                             AS x_chain_depth,
           CASE WHEN COALESCE(t1.agent_id,t2.agent_id,t3.agent_id,
                              t4.agent_id,t5.agent_id) IS NOT NULL
                THEN 1 ELSE 0 END                                        AS f_testline
    FROM x_ranked b
    LEFT JOIN x_testagent t1 ON t1.agent_id = b.bet18
    LEFT JOIN x_testagent t2 ON t2.agent_id = b.bet19
    LEFT JOIN x_testagent t3 ON t3.agent_id = b.bet20
    LEFT JOIN x_testagent t4 ON t4.agent_id = b.bet21
    LEFT JOIN x_testagent t5 ON t5.agent_id = b.bet22
    WHERE b.x_rn = 1
      AND b.category='1' AND UPPER(TRIM(b.bet38))='N'
      AND CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8)) > 0
  ),
  x_mk AS (
    SELECT s.*,
           CASE WHEN s.f_testline = 0 THEN 1 ELSE 0 END                 AS is_clean
    FROM x_bs0 s
  ),
  x_agg AS (
    SELECT s.x_member                                                        AS x_key,
           COUNT(*) AS n_bets, COUNT(DISTINCT s.x_round) AS n_rounds,
           COUNT(DISTINCT s.x_date) AS active_days, COUNT(DISTINCT s.x_tblshoe) AS active_shoes,
           COUNT(DISTINCT CONCAT_WS('|', s.x_date, s.x_table)) AS active_sessions,
           COUNT(DISTINCT s.x_table) AS n_tables, COUNT(DISTINCT s.x_dealer) AS n_dealers,
           COUNT(DISTINCT s.x_ip) AS n_ips, COUNT(DISTINCT s.x_product) AS n_products,
           MIN(s.x_date) AS first_seen_d, MAX(s.x_date) AS last_seen_d,
           SUM(s.x_stake) AS stake, SUM(s.x_valid) AS valid, SUM(s.x_rebate) AS rebate,
           SUM(s.x_net) AS net, SUM(-s.x_net *(100.0-s.x_agpct)/100.0) AS agent_cost,
           AVG(100.0-s.x_agpct)                   AS agent_pct,
           AVG(s.x_agpct)                         AS company_retain_pct,
           SUM(-s.x_net *s.x_agpct/100.0)         AS agent_cost_a_legacy,
           SUM(s.x_valid*s.x_agpct/100.0)         AS agent_cost_valid_base_legacy,
          AVG(COALESCE(s.x_rate1,100)) AS retain_pct_lv1, AVG(COALESCE(s.x_rate2,100)) AS retain_pct_lv2,
          AVG(COALESCE(s.x_rate3,100)) AS retain_pct_lv3, AVG(COALESCE(s.x_rate4,100)) AS retain_pct_lv4,
          AVG(COALESCE(s.x_rate5,100)) AS retain_pct_lv5, AVG(s.x_chain_depth) AS chain_depth_avg,
          AVG(COALESCE(100.0-s.x_rate1,0)) AS agent_pct_lv1, AVG(COALESCE(100.0-s.x_rate2,0)) AS agent_pct_lv2,
          AVG(COALESCE(100.0-s.x_rate3,0)) AS agent_pct_lv3, AVG(COALESCE(100.0-s.x_rate4,0)) AS agent_pct_lv4,
          AVG(COALESCE(100.0-s.x_rate5,0)) AS agent_pct_lv5,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate1,0)/100.0)                        AS agent_cost_lv1,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate2,0)/100.0)                        AS agent_cost_lv2,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate3,0)/100.0)                        AS agent_cost_lv3,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate4,0)/100.0)                        AS agent_cost_lv4,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate5,0)/100.0)                        AS agent_cost_lv5,
          SUM(-s.x_net*(COALESCE(100.0-s.x_rate1,0)+COALESCE(100.0-s.x_rate2,0)
                       +COALESCE(100.0-s.x_rate3,0)+COALESCE(100.0-s.x_rate4,0)
                       +COALESCE(100.0-s.x_rate5,0))/100.0)                   AS agent_cost_chain_additive,
          SUM(-s.x_net*(1.0 - CAST(COALESCE(s.x_rate1,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate2,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate3,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate4,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate5,100) AS DOUBLE)/100.0))
                                                                       AS agent_cost_chain_nested,
           AVG(s.x_rbpct) AS rbpct, AVG(s.x_freecomm*1.0) AS freecomm_rate,
           PERCENTILE_APPROX(s.x_stake,0.25) AS p25, PERCENTILE_APPROX(s.x_stake,0.50) AS p50,
           PERCENTILE_APPROX(s.x_stake,0.75) AS p75, PERCENTILE_APPROX(s.x_stake,0.90) AS p90,
           PERCENTILE_APPROX(s.x_stake,0.95) AS p95, PERCENTILE_APPROX(s.x_stake,0.99) AS p99,
           PERCENTILE_APPROX(s.x_valid,0.50) AS p50_valid,
           PERCENTILE_APPROX(s.x_net,0.50)   AS p50_profit,
           SUM(CASE WHEN s.x_rec = 1 THEN s.x_stake ELSE 0 END) AS st_in,
           SUM(CASE WHEN s.x_rec = 1 THEN 1 ELSE 0 END)         AS nb_in,
           SUM(CASE WHEN s.x_rec = 1 THEN s.x_net ELSE 0 END)   AS net_in,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN s.x_stake ELSE 0 END) AS st_out,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN 1 ELSE 0 END)         AS nb_out,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN s.x_net ELSE 0 END)   AS net_out,
           SUM(CASE WHEN s.x_rec=1 THEN s.x_stake ELSE 0 END) AS st_rec,
           SUM(CASE WHEN s.x_rec=1 THEN 1 ELSE 0 END)         AS nb_rec
    FROM x_mk s
    WHERE s.is_clean = 1
      AND s.x_member IS NOT NULL AND TRIM(CAST(s.x_member AS STRING)) <> ''
    GROUP BY s.x_member
  ),
  x_win AS (
    SELECT            COUNT(*) AS n_bets, COUNT(DISTINCT s.x_round) AS n_rounds,
           COUNT(DISTINCT s.x_date) AS active_days, COUNT(DISTINCT s.x_tblshoe) AS active_shoes,
           COUNT(DISTINCT CONCAT_WS('|', s.x_date, s.x_table)) AS active_sessions,
           COUNT(DISTINCT s.x_table) AS n_tables, COUNT(DISTINCT s.x_dealer) AS n_dealers,
           COUNT(DISTINCT s.x_ip) AS n_ips, COUNT(DISTINCT s.x_product) AS n_products,
           MIN(s.x_date) AS first_seen_d, MAX(s.x_date) AS last_seen_d,
           SUM(s.x_stake) AS stake, SUM(s.x_valid) AS valid, SUM(s.x_rebate) AS rebate,
           SUM(s.x_net) AS net, SUM(-s.x_net *(100.0-s.x_agpct)/100.0) AS agent_cost,
           AVG(100.0-s.x_agpct)                   AS agent_pct,
           AVG(s.x_agpct)                         AS company_retain_pct,
           SUM(-s.x_net *s.x_agpct/100.0)         AS agent_cost_a_legacy,
           SUM(s.x_valid*s.x_agpct/100.0)         AS agent_cost_valid_base_legacy,
          AVG(COALESCE(s.x_rate1,100)) AS retain_pct_lv1, AVG(COALESCE(s.x_rate2,100)) AS retain_pct_lv2,
          AVG(COALESCE(s.x_rate3,100)) AS retain_pct_lv3, AVG(COALESCE(s.x_rate4,100)) AS retain_pct_lv4,
          AVG(COALESCE(s.x_rate5,100)) AS retain_pct_lv5, AVG(s.x_chain_depth) AS chain_depth_avg,
          AVG(COALESCE(100.0-s.x_rate1,0)) AS agent_pct_lv1, AVG(COALESCE(100.0-s.x_rate2,0)) AS agent_pct_lv2,
          AVG(COALESCE(100.0-s.x_rate3,0)) AS agent_pct_lv3, AVG(COALESCE(100.0-s.x_rate4,0)) AS agent_pct_lv4,
          AVG(COALESCE(100.0-s.x_rate5,0)) AS agent_pct_lv5,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate1,0)/100.0)                        AS agent_cost_lv1,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate2,0)/100.0)                        AS agent_cost_lv2,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate3,0)/100.0)                        AS agent_cost_lv3,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate4,0)/100.0)                        AS agent_cost_lv4,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate5,0)/100.0)                        AS agent_cost_lv5,
          SUM(-s.x_net*(COALESCE(100.0-s.x_rate1,0)+COALESCE(100.0-s.x_rate2,0)
                       +COALESCE(100.0-s.x_rate3,0)+COALESCE(100.0-s.x_rate4,0)
                       +COALESCE(100.0-s.x_rate5,0))/100.0)                   AS agent_cost_chain_additive,
          SUM(-s.x_net*(1.0 - CAST(COALESCE(s.x_rate1,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate2,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate3,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate4,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate5,100) AS DOUBLE)/100.0))
                                                                       AS agent_cost_chain_nested,
           AVG(s.x_rbpct) AS rbpct, AVG(s.x_freecomm*1.0) AS freecomm_rate,
           PERCENTILE_APPROX(s.x_stake,0.25) AS p25, PERCENTILE_APPROX(s.x_stake,0.50) AS p50,
           PERCENTILE_APPROX(s.x_stake,0.75) AS p75, PERCENTILE_APPROX(s.x_stake,0.90) AS p90,
           PERCENTILE_APPROX(s.x_stake,0.95) AS p95, PERCENTILE_APPROX(s.x_stake,0.99) AS p99,
           PERCENTILE_APPROX(s.x_valid,0.50) AS p50_valid,
           PERCENTILE_APPROX(s.x_net,0.50)   AS p50_profit,
           SUM(CASE WHEN s.x_rec = 1 THEN s.x_stake ELSE 0 END) AS st_in,
           SUM(CASE WHEN s.x_rec = 1 THEN 1 ELSE 0 END)         AS nb_in,
           SUM(CASE WHEN s.x_rec = 1 THEN s.x_net ELSE 0 END)   AS net_in,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN s.x_stake ELSE 0 END) AS st_out,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN 1 ELSE 0 END)         AS nb_out,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN s.x_net ELSE 0 END)   AS net_out,
           SUM(CASE WHEN s.x_rec=1 THEN s.x_stake ELSE 0 END) AS st_rec,
           SUM(CASE WHEN s.x_rec=1 THEN 1 ELSE 0 END)         AS nb_rec
    FROM x_mk s
    WHERE s.is_clean = 1
      AND s.x_member IS NOT NULL AND TRIM(CAST(s.x_member AS STRING)) <> ''
  ),
      q AS (
        SELECT
            TABLE_NAME                                                   AS 表名,
            TABLE_TYPE                                                   AS 表类型,
            TABLE_ROWS                                                   AS 估计行数,
            TABLE_COMMENT                                                AS 表注释,
            CASE
              WHEN LOWER(TABLE_NAME) LIKE '%_bak%'  THEN '备份'
              WHEN LOWER(TABLE_NAME) LIKE '%bak2%'  THEN '备份'
              WHEN LOWER(TABLE_NAME) LIKE '%_test%' THEN '测试'
              WHEN LOWER(TABLE_NAME) LIKE '%_tmp%'  THEN '临时'
              WHEN LOWER(TABLE_NAME) LIKE '%_old%'  THEN '旧版'
              WHEN LOWER(TABLE_NAME) LIKE '%_copy%' THEN '副本'
              WHEN LOWER(TABLE_NAME) LIKE '%_v1%'   THEN '疑似旧版'
              WHEN LOWER(TABLE_NAME) LIKE '%demo%'  THEN '疑似演示'
              ELSE '生产'
            END                                                          AS 疑似性质
        FROM INFORMATION_SCHEMA.TABLES
        WHERE TABLE_SCHEMA = 'ods_mariadb_2b'
      )
    SELECT q.*,
           -- 一·经济层
           ROUND(e.stake,4) AS stake, ROUND(e.valid,4) AS valid_bet,
           ROUND(-e.net,4) AS profit, e.n_bets, e.n_rounds,
           ROUND(e.net/NULLIF(e.stake,0),8) AS roi,
           ROUND(e.net_in/NULLIF(e.st_in,0),8) AS roi_recent,
           ROUND(e.net_out/NULLIF(e.st_out,0),8) AS roi_non_recent,
           ROUND((e.net-e.rebate)/NULLIF(e.stake,0),8) AS roi_ex_rebate,
           ROUND(e.net,4) AS roi_numerator, ROUND(e.stake,4) AS roi_denominator,
           CASE WHEN e.stake IS NULL THEN 'NULL_DENOM' WHEN e.stake<=0 THEN 'ZERO_DENOM'
                WHEN e.n_bets<30 THEN 'THIN_EXPOSURE' ELSE 'OK' END AS roi_denominator_status,
           ROUND(e.rebate,4) AS rebate_cost, ROUND(e.agent_cost,4)                           AS cost_complement_b,
       ROUND(e.agent_pct,4)                            AS pct_complement,
       ROUND(e.company_retain_pct,4)                   AS pct_top_bet23,
       'AG03-UNRESOLVED'                                     AS agent_formula_version,
      'ALL5_LEVELS_bet23_to_bet27'                    AS agent_level_scope,
      ROUND(e.agent_cost_lv1,4) AS agent_cost_lv1, ROUND(e.agent_cost_lv2,4) AS agent_cost_lv2,
      ROUND(e.agent_cost_lv3,4) AS agent_cost_lv3, ROUND(e.agent_cost_lv4,4) AS agent_cost_lv4,
      ROUND(e.agent_cost_lv5,4) AS agent_cost_lv5,
      ROUND(e.agent_pct_lv1,6) AS agent_pct_lv1, ROUND(e.agent_pct_lv2,6) AS agent_pct_lv2,
      ROUND(e.agent_pct_lv3,6) AS agent_pct_lv3, ROUND(e.agent_pct_lv4,6) AS agent_pct_lv4,
      ROUND(e.agent_pct_lv5,6) AS agent_pct_lv5,
      ROUND(e.retain_pct_lv1,6) AS retain_pct_lv1, ROUND(e.retain_pct_lv2,6) AS retain_pct_lv2,
      ROUND(e.retain_pct_lv3,6) AS retain_pct_lv3, ROUND(e.retain_pct_lv4,6) AS retain_pct_lv4,
      ROUND(e.retain_pct_lv5,6) AS retain_pct_lv5, ROUND(e.chain_depth_avg,4) AS chain_depth_avg,
      ROUND(e.agent_cost_chain_additive,4)            AS agent_cost_chain_additive,
      ROUND(e.agent_cost_chain_nested,4)              AS agent_cost_chain_nested,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_additive,4) AS residual_chain_additive,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_nested,4)   AS residual_chain_nested,
      'PENDING_AG03'                                  AS decision_status,
      'FALSE'                                         AS admit_to_risk_decision,
      'NOT_FOR_ENFORCEMENT'                           AS deliverable_class,
       ROUND(e.agent_cost_a_legacy,4)                  AS agent_cost_a_legacy,
       ROUND(e.agent_cost_valid_base_legacy,4)         AS agent_cost_valid_base_legacy,
           ROUND(-e.net-e.rebate,4)                        AS ngr,
       ROUND(-e.net-e.rebate-e.agent_cost,4)           AS residual_b,
       ROUND(-e.net-e.rebate-e.agent_cost_a_legacy,4)  AS residual_a,
           ROUND((-e.net-e.rebate)/NULLIF(e.stake,0),8)    AS ngr_rate,
       ROUND((-e.net-e.rebate-e.agent_cost)/NULLIF(e.stake,0),8)   AS residual_b_rate,
      -- 【HF9c · canonical accounting contract】
      --   以下 canonical 字段只增加明确 scope；不删除、不覆盖既有字段。
      --   formal_bet23_* 保持 HF9b 当前生产公式及其 NULL/0 语义；
      --   lv1~lv5 / additive / nested 则分别采用各自原始 e.* 成本字段，
      --   rate 一律从未舍入的 e.* 分子 / e.stake 计算，禁止由展示值反算。
      ROUND(e.agent_cost,4) AS agent_cost_bet23_formal_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost,4) AS net_margin_bet23_formal_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost)/NULLIF(e.stake,0),8) AS net_margin_bet23_formal_rate_canonical,
      ROUND(e.agent_cost_lv1,4) AS agent_cost_lv1_bet23_canonical,
      ROUND(e.agent_cost_lv2,4) AS agent_cost_lv2_bet24_canonical,
      ROUND(e.agent_cost_lv3,4) AS agent_cost_lv3_bet25_canonical,
      ROUND(e.agent_cost_lv4,4) AS agent_cost_lv4_bet26_canonical,
      ROUND(e.agent_cost_lv5,4) AS agent_cost_lv5_bet27_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_lv1,4) AS net_margin_lv1_bet23_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_lv1)/NULLIF(e.stake,0),8) AS net_margin_lv1_bet23_rate_canonical,
      ROUND(e.agent_cost_chain_additive,4) AS agent_cost_chain_additive_canonical,
      ROUND(e.agent_cost_chain_nested,4) AS agent_cost_chain_nested_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_additive,4) AS net_margin_chain_additive_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_nested,4) AS net_margin_chain_nested_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_chain_additive)/NULLIF(e.stake,0),8) AS net_margin_chain_additive_rate_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_chain_nested)/NULLIF(e.stake,0),8) AS net_margin_chain_nested_rate_canonical,
       ROUND((-e.net-e.rebate-e.agent_cost_a_legacy)/NULLIF(e.stake,0),8) AS residual_a_rate,
           -- 二·分布层
           ROUND(e.stake/NULLIF(e.n_bets,0),4) AS avg_stake_per_bet,
           ROUND(e.valid/NULLIF(e.n_rounds,0),4) AS avg_valid_bet_per_round,
           ROUND(-e.net/NULLIF(e.n_rounds,0),4) AS avg_profit_per_round,
           ROUND(-e.net/NULLIF(e.active_days,0),4) AS avg_profit_per_day,
           ROUND(-e.net/NULLIF(e.active_shoes,0),4) AS avg_profit_per_shoe,
           ROUND(e.stake/NULLIF(e.active_days,0),4) AS avg_stake_per_active_day,
           ROUND(e.n_rounds*1.0/NULLIF(e.active_days,0),4) AS avg_rounds_per_active_day,
           ROUND(e.st_in/NULLIF(e.nb_in,0),4) AS avg_stake_recent,
           ROUND(e.st_out/NULLIF(e.nb_out,0),4) AS avg_stake_non_recent,
           ROUND(e.p25,4) AS p25_stake, ROUND(e.p50,4) AS p50_stake, ROUND(e.p75,4) AS p75_stake,
           ROUND(e.p90,4) AS p90_stake, ROUND(e.p95,4) AS p95_stake, ROUND(e.p99,4) AS p99_stake,
           ROUND(e.p50_valid,4) AS p50_valid_bet, ROUND(e.p50_profit,4) AS p50_profit,
           ROUND(e.p95/NULLIF(e.p50,0),6) AS p95_over_p50,
           ROUND(e.p99/NULLIF(e.p50,0),6) AS p99_over_p50,
           ROUND((e.stake/NULLIF(e.n_bets,0))/NULLIF(e.p50,0),6) AS avg_over_p50,
           -- 三·关系层
           e.n_tables AS common_table_count, e.n_dealers AS common_dealer_count,
           e.n_ips AS common_ip_count, e.n_products AS common_product_count,
           ROUND(e.st_in/NULLIF(e.stake,0),8) AS share_recent,
           -- 四·rate 层
           ROUND(-e.net/NULLIF(e.stake,0),8) AS hold_rate,
           ROUND(-e.net_in/NULLIF(e.st_in,0),8) AS hold_rate_recent,
           ROUND(e.rebate/NULLIF(e.valid,0),8) AS rebate_rate_actual,
           ROUND(e.rbpct,6) AS rebate_pct_config,
           ROUND(e.valid/NULLIF(e.stake,0),6) AS turnover_multiple,
           ROUND(e.freecomm_rate,6) AS free_comm_rate,
           ROUND(e.net_in/NULLIF(e.st_in,0)-e.net_out/NULLIF(e.st_out,0),8) AS roi_delta_recent,
           -- 五·动态层
           e.first_seen_d AS first_seen, e.last_seen_d AS last_seen,
           e.active_days, e.active_shoes, e.active_sessions,
           DATEDIFF(e.last_seen_d, e.first_seen_d)+1 AS span_days,
           ROUND(e.active_days*1.0/NULLIF(DATEDIFF(e.last_seen_d,e.first_seen_d)+1,0),6) AS persistence,
           ROUND((e.st_in/NULLIF(e.nb_in,0))/NULLIF(e.st_out/NULLIF(e.nb_out,0),0),6) AS ramp_recent_vs_prior,
           ROUND((e.st_rec/NULLIF(e.nb_rec,0))/NULLIF(e.stake/NULLIF(e.n_bets,0),0),6) AS ramp_recent_vs_all,
           ROUND((e.st_rec/NULLIF(e.stake,0))/0.30,6) AS stake_ramp,
           -- 六·决策层（HF9g-P5 · D-14 斧正 —— 本件属【全窗基线族】，相对刻度与决策标签一律 NULL）
           --   病灶：x_win 系全窗单行聚合（无 GROUP BY，恒 1 行，此为设计使然，非缺陷），
           --         经 CROSS JOIN 接入后 e.* 全行同值；六层之 NTILE / PERCENT_RANK 施于常数即退化，
           --         PERCENT_RANK 恒 0 ⇒ action_priority 恒判 A，全件 100% 误标。
           --   ★ 斧正原则：不给 x_win 补 GROUP BY —— 那会改变其「全窗基线」语义，属退化。
           --     正解与 #018 之 G-05／G-06 同治：范围外之行不得接受任何下游评分与决策标签。
           --   ★ 本件之 e.* 仍照常供其它列作全窗基线使用，仅六层相对刻度与决策标签置 NULL。
           CAST(NULL AS INT)                                              AS vip_tier,                        -- 空值取值：全窗基线族无实体可分档，置 NULL（NULL＝不适用，非 0）
           CAST(NULL AS DOUBLE)                                           AS economic_value,                  -- 空值取值：同上，禁以常数百分位冒充经济价值
           CAST(NULL AS DOUBLE)                                           AS roi_pr_global,                   -- 空值取值：同上
           CAST(NULL AS DOUBLE)                                           AS risk_value,                      -- 空值取值：兼容列，同上
           CAST(NULL AS DOUBLE)                                           AS pr_stake,                        -- 空值取值：兼容列，同上
           CAST(NULL AS DOUBLE)                                           AS pr_global,                       -- 空值取值：同上
           CAST(NULL AS DOUBLE)                                           AS pr_qualified,                    -- 空值取值：同上
           'GLOBAL_BASELINE_NO_ENTITY_RANKING'                            AS pr_qualified_population,         -- 字面取值：血统 —— 明示本件为全窗基线族，无实体排序总体
           CAST(NULL AS BIGINT)                                           AS pr_global_population_n,          -- 空值取值：血统 —— 不适用
           CAST(NULL AS BIGINT)                                           AS pr_qualified_population_n,       -- 空值取值：血统 —— 不适用
           'NOT_APPLICABLE_GLOBAL_BASELINE'                               AS pr_calculation_method,           -- 字面取值：血统 —— 算法不适用
           'HF9g-P5'                                                      AS pr_calculation_version,          -- 字面取值：血统 —— 算法版本
           CAST(NULL AS STRING)                                           AS evidence_flag,                   -- 空值取值：证据旗标不适用于全窗基线
           CAST(NULL AS STRING)                                           AS evidence_rate,                   -- 空值取值：同上
           CAST(NULL AS DOUBLE)                                           AS hold_ci_halfwidth_approx,        -- 空值取值：同上
           'X 全窗基线 · 不参与实体赏罚'                                    AS action_priority                  -- 字面取值：★ D-14 斧正 —— 本族恒不入赏罚，取代原 100% 误标之「A」
    FROM q
    CROSS JOIN x_win e
  ) y
) z
-- ── 逐批 WHERE 阶梯（★ 口诀：上界 ＝ 下界 ＋ 100000，两数同进）──
--    本件 T_true 未测，无需先跑 T_true；以 0 / 100000 控制本批返回区间，末批由实际行数 < 100000 判定
--    WHERE z.audit_rn >        0 AND z.audit_rn <=   100000   -- 第 1 批
--    WHERE z.audit_rn >   100000 AND z.audit_rn <=   200000   -- 第 2 批
--    WHERE z.audit_rn >   200000 AND z.audit_rn <=   300000   -- 第 3 批
--    WHERE z.audit_rn >   300000 AND z.audit_rn <=   400000   -- 第 4 批
--    WHERE z.audit_rn >   400000 AND z.audit_rn <=   500000   -- 第 5 批
--    WHERE z.audit_rn >   500000 AND z.audit_rn <=   600000   -- 第 6 批
--    WHERE z.audit_rn >   600000 AND z.audit_rn <=   700000   -- 第 7 批
--    …余批类推。第 k 批：WHERE z.audit_rn > (k-1)*100000 AND z.audit_rn <= k*100000
--    某批返回 < 100000 行即为末批，其后不再取。
--
--    ⚠ 常见误写（务必避开）：只推下界而上界不动 ——
--        WHERE z.audit_rn > 100000 AND z.audit_rn <= 100000   ← 自相矛盾，恒为假，返回空集
--        WHERE z.audit_rn > 200000 AND z.audit_rn <= 100000   ← 同上，空集
--      两个数必须**同时**前进，且始终相差 100000。
--      下界 ＝ 上一批之上界；上界 ＝ 本批之上界。
WHERE z.audit_rn > 0 AND z.audit_rn <= 100000 -- ★ HF9c 本批区间
ORDER BY z.audit_rn;


-- ══════════════════════════════════════════════════════════════════════════════════════════════
-- 112. Z02_excluded_tables.csv   [总包行 589~608 · 原 4 列 ＋六层约 60 列]
--     典型学：Z00 基建/元数据　派生旗标：recent（s.x_rec = 1 · 仅供 CASE 条件聚合，全包无任何 WHERE/AND/HAVING 以此过滤）　连接：全窗基线
-- ══════════════════════════════════════════════════════════════════════════════════════════════
-- ★ W-64 · D-14 警示（本件属 x_win 族 · 66 件之一 · 详见 §Z 段 D-14 全案）
--   本件以 `CROSS JOIN x_win e` 接入全局基线，x_win 无 GROUP BY ⇒ 恒 1 行 ⇒ e.* 全行同值。
--   故：economic_value / roi_pr_global / risk_value / pr_stake / pr_global 恒为 0；
--       action_priority 每一行皆为「A 净亏最大十分位 · 优先复核」（Z 分支永不触发）；
--       evidence_rate 恒为最高档；vip_tier 由常数键分档 ⇒ 无信息且非确定。
--   ⇒ 本件决策层三列 **NOT_FOR_DECISION**，裁定前不得用于排班、抽查或汇报。
-- ── ① 先跑 T_true 留档（不足 100000 者一次导全，不必分批）──
-- ── ① T_true：HF9c 不再强制预跑完整 COUNT。
--    本批实际返回行数 < 100000 即判定为末批；全批完成后以各批 n_rows / audit_rn 范围核对总量。

-- ── ② 分批取数：第 1 批。第 k 批只改末行两数为 (k-1)*100000 与 k*100000 ──
--    审计字段二（REDTEAM 2026-08-24 裁定 · 四锁）：
--      audit_rn  全局观测坐标 —— 由**与原版审计版逐字同一**之排序键所生，两版可逐行对账
--      batch_id  物理分批信息 —— 该行所属批次，由 audit_rn 算得，非引擎所赋
--    ★ 锁三：二者皆为审计字段，**不得进入任何业务指标计算**。
--    ★ 锁四：两版经 audit_rn 逐行字段核验后，方可宣布输出完全一致。

-- ── ③ 每批取回后自证四数（任一不符即停手回报，禁止放行）──
--    n_rows        = COUNT(*)      须等于 COUNT(DISTINCT audit_rn)   （批内无重复）
--    audit_rn_min  = MIN(audit_rn) 须等于 (k-1)*100000 + 1           （与上批严丝合缝）
--    audit_rn_max  = MAX(audit_rn) 须等于 min + n_rows - 1           （批内无缺口）
--    全批取毕再验：各批 audit_rn 之并集 = 1 .. T_true，无缺号、无重号。
--     ★ 首行＝平台真净亏最多者（已扣退水与代理占成）。
--
SELECT z.*,
       CAST(FLOOR((z.audit_rn - 1) / 100000) + 1 AS INT)          AS batch_id,
       'A168_HF9F_20260827_0900' AS run_id,
       '2026-08-27 09:00:00' AS snapshot_sync_time
FROM (
  SELECT y.*,
         ROW_NUMBER() OVER (ORDER BY y.`residual_b` ASC, y.`roi` DESC, y.`表名`, y.`估计行数`, y.`表注释`, y.`处置`) AS audit_rn
  FROM (
    WITH
      x_ranked AS (
    SELECT b.bet01, b.bet03, b.bet04, b.bet05, b.bet09, b.bet11, b.bet13,
           b.bet15, b.bet16, b.bet17, b.bet18, b.bet19, b.bet20, b.bet21,
           b.bet22, b.bet23, b.bet24, b.bet25, b.bet26, b.bet27, b.bet38, b.bet39, b.category, b.commission,
           b.dt, b.eid, b.ip, b.validbet, b.updatetime, b.sync_time,
           ROW_NUMBER() OVER (
             PARTITION BY b.bet01
             ORDER BY b.updatetime DESC, b.sync_time DESC, b.dt DESC)      AS x_rn
    FROM ods_mariadb_2b.ods_a168_bet02 b
    WHERE b.dt >= '2026-03-21' AND b.dt < '2026-08-07'
      AND b.bet02 = '101'
      AND b.sync_time <= '2026-08-27 09:00:00'
  ),
    x_testagent AS (
    SELECT age001 AS agent_id FROM ods_mariadb_2b.ods_a168_agent WHERE age022 = '1'
  ),
    x_bs0 AS (
    SELECT b.bet05 AS x_member, b.eid AS x_dealer, b.bet39 AS x_table,
           b.bet03 AS x_shoe, b.ip AS x_ip, b.bet09 AS x_product, b.dt AS x_date,
           CONCAT_WS('|', b.bet03, b.bet04, b.bet39)                      AS x_round,
           CONCAT_WS('|', b.bet39, b.bet03)                               AS x_tblshoe,
           CAST(NULLIF(TRIM(b.bet04),'') AS INT)                          AS x_rno,
           CASE WHEN b.dt >= '2026-07-08' THEN 1 ELSE 0 END               AS x_rec,
           CASE WHEN TRIM(b.commission)='1' THEN 1 ELSE 0 END             AS x_freecomm,
           CAST(NULLIF(TRIM(b.bet13),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_stake,
           CAST(NULLIF(TRIM(b.validbet),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_valid,
           CAST(NULLIF(TRIM(b.bet16),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_rebate,
           CAST(NULLIF(TRIM(b.bet17),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_net,
           CAST(NULLIF(TRIM(b.bet15),'') AS DECIMAL(20,6))                AS x_rbpct,
           COALESCE(CAST(NULLIF(TRIM(b.bet23),'') AS DECIMAL(20,6)),0)   AS x_agpct,
          NULLIF(CAST(NULLIF(TRIM(b.bet23),'') AS DECIMAL(20,6)),0)     AS x_rate1,
          NULLIF(CAST(NULLIF(TRIM(b.bet24),'') AS DECIMAL(20,6)),0)     AS x_rate2,
          NULLIF(CAST(NULLIF(TRIM(b.bet25),'') AS DECIMAL(20,6)),0)     AS x_rate3,
          NULLIF(CAST(NULLIF(TRIM(b.bet26),'') AS DECIMAL(20,6)),0)     AS x_rate4,
          NULLIF(CAST(NULLIF(TRIM(b.bet27),'') AS DECIMAL(20,6)),0)     AS x_rate5,
          (CASE WHEN NULLIF(CAST(NULLIF(TRIM(b.bet22),'') AS BIGINT),0) IS NOT NULL THEN 5
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet21),'') AS BIGINT),0) IS NOT NULL THEN 4
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet20),'') AS BIGINT),0) IS NOT NULL THEN 3
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet19),'') AS BIGINT),0) IS NOT NULL THEN 2
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet18),'') AS BIGINT),0) IS NOT NULL THEN 1
                ELSE 0 END)                                             AS x_chain_depth,
           CASE WHEN COALESCE(t1.agent_id,t2.agent_id,t3.agent_id,
                              t4.agent_id,t5.agent_id) IS NOT NULL
                THEN 1 ELSE 0 END                                        AS f_testline
    FROM x_ranked b
    LEFT JOIN x_testagent t1 ON t1.agent_id = b.bet18
    LEFT JOIN x_testagent t2 ON t2.agent_id = b.bet19
    LEFT JOIN x_testagent t3 ON t3.agent_id = b.bet20
    LEFT JOIN x_testagent t4 ON t4.agent_id = b.bet21
    LEFT JOIN x_testagent t5 ON t5.agent_id = b.bet22
    WHERE b.x_rn = 1
      AND b.category='1' AND UPPER(TRIM(b.bet38))='N'
      AND CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8)) > 0
  ),
  x_mk AS (
    SELECT s.*,
           CASE WHEN s.f_testline = 0 THEN 1 ELSE 0 END                 AS is_clean
    FROM x_bs0 s
  ),
  x_agg AS (
    SELECT s.x_member                                                        AS x_key,
           COUNT(*) AS n_bets, COUNT(DISTINCT s.x_round) AS n_rounds,
           COUNT(DISTINCT s.x_date) AS active_days, COUNT(DISTINCT s.x_tblshoe) AS active_shoes,
           COUNT(DISTINCT CONCAT_WS('|', s.x_date, s.x_table)) AS active_sessions,
           COUNT(DISTINCT s.x_table) AS n_tables, COUNT(DISTINCT s.x_dealer) AS n_dealers,
           COUNT(DISTINCT s.x_ip) AS n_ips, COUNT(DISTINCT s.x_product) AS n_products,
           MIN(s.x_date) AS first_seen_d, MAX(s.x_date) AS last_seen_d,
           SUM(s.x_stake) AS stake, SUM(s.x_valid) AS valid, SUM(s.x_rebate) AS rebate,
           SUM(s.x_net) AS net, SUM(-s.x_net *(100.0-s.x_agpct)/100.0) AS agent_cost,
           AVG(100.0-s.x_agpct)                   AS agent_pct,
           AVG(s.x_agpct)                         AS company_retain_pct,
           SUM(-s.x_net *s.x_agpct/100.0)         AS agent_cost_a_legacy,
           SUM(s.x_valid*s.x_agpct/100.0)         AS agent_cost_valid_base_legacy,
          AVG(COALESCE(s.x_rate1,100)) AS retain_pct_lv1, AVG(COALESCE(s.x_rate2,100)) AS retain_pct_lv2,
          AVG(COALESCE(s.x_rate3,100)) AS retain_pct_lv3, AVG(COALESCE(s.x_rate4,100)) AS retain_pct_lv4,
          AVG(COALESCE(s.x_rate5,100)) AS retain_pct_lv5, AVG(s.x_chain_depth) AS chain_depth_avg,
          AVG(COALESCE(100.0-s.x_rate1,0)) AS agent_pct_lv1, AVG(COALESCE(100.0-s.x_rate2,0)) AS agent_pct_lv2,
          AVG(COALESCE(100.0-s.x_rate3,0)) AS agent_pct_lv3, AVG(COALESCE(100.0-s.x_rate4,0)) AS agent_pct_lv4,
          AVG(COALESCE(100.0-s.x_rate5,0)) AS agent_pct_lv5,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate1,0)/100.0)                        AS agent_cost_lv1,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate2,0)/100.0)                        AS agent_cost_lv2,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate3,0)/100.0)                        AS agent_cost_lv3,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate4,0)/100.0)                        AS agent_cost_lv4,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate5,0)/100.0)                        AS agent_cost_lv5,
          SUM(-s.x_net*(COALESCE(100.0-s.x_rate1,0)+COALESCE(100.0-s.x_rate2,0)
                       +COALESCE(100.0-s.x_rate3,0)+COALESCE(100.0-s.x_rate4,0)
                       +COALESCE(100.0-s.x_rate5,0))/100.0)                   AS agent_cost_chain_additive,
          SUM(-s.x_net*(1.0 - CAST(COALESCE(s.x_rate1,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate2,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate3,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate4,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate5,100) AS DOUBLE)/100.0))
                                                                       AS agent_cost_chain_nested,
           AVG(s.x_rbpct) AS rbpct, AVG(s.x_freecomm*1.0) AS freecomm_rate,
           PERCENTILE_APPROX(s.x_stake,0.25) AS p25, PERCENTILE_APPROX(s.x_stake,0.50) AS p50,
           PERCENTILE_APPROX(s.x_stake,0.75) AS p75, PERCENTILE_APPROX(s.x_stake,0.90) AS p90,
           PERCENTILE_APPROX(s.x_stake,0.95) AS p95, PERCENTILE_APPROX(s.x_stake,0.99) AS p99,
           PERCENTILE_APPROX(s.x_valid,0.50) AS p50_valid,
           PERCENTILE_APPROX(s.x_net,0.50)   AS p50_profit,
           SUM(CASE WHEN s.x_rec = 1 THEN s.x_stake ELSE 0 END) AS st_in,
           SUM(CASE WHEN s.x_rec = 1 THEN 1 ELSE 0 END)         AS nb_in,
           SUM(CASE WHEN s.x_rec = 1 THEN s.x_net ELSE 0 END)   AS net_in,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN s.x_stake ELSE 0 END) AS st_out,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN 1 ELSE 0 END)         AS nb_out,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN s.x_net ELSE 0 END)   AS net_out,
           SUM(CASE WHEN s.x_rec=1 THEN s.x_stake ELSE 0 END) AS st_rec,
           SUM(CASE WHEN s.x_rec=1 THEN 1 ELSE 0 END)         AS nb_rec
    FROM x_mk s
    WHERE s.is_clean = 1
      AND s.x_member IS NOT NULL AND TRIM(CAST(s.x_member AS STRING)) <> ''
    GROUP BY s.x_member
  ),
  x_win AS (
    SELECT            COUNT(*) AS n_bets, COUNT(DISTINCT s.x_round) AS n_rounds,
           COUNT(DISTINCT s.x_date) AS active_days, COUNT(DISTINCT s.x_tblshoe) AS active_shoes,
           COUNT(DISTINCT CONCAT_WS('|', s.x_date, s.x_table)) AS active_sessions,
           COUNT(DISTINCT s.x_table) AS n_tables, COUNT(DISTINCT s.x_dealer) AS n_dealers,
           COUNT(DISTINCT s.x_ip) AS n_ips, COUNT(DISTINCT s.x_product) AS n_products,
           MIN(s.x_date) AS first_seen_d, MAX(s.x_date) AS last_seen_d,
           SUM(s.x_stake) AS stake, SUM(s.x_valid) AS valid, SUM(s.x_rebate) AS rebate,
           SUM(s.x_net) AS net, SUM(-s.x_net *(100.0-s.x_agpct)/100.0) AS agent_cost,
           AVG(100.0-s.x_agpct)                   AS agent_pct,
           AVG(s.x_agpct)                         AS company_retain_pct,
           SUM(-s.x_net *s.x_agpct/100.0)         AS agent_cost_a_legacy,
           SUM(s.x_valid*s.x_agpct/100.0)         AS agent_cost_valid_base_legacy,
          AVG(COALESCE(s.x_rate1,100)) AS retain_pct_lv1, AVG(COALESCE(s.x_rate2,100)) AS retain_pct_lv2,
          AVG(COALESCE(s.x_rate3,100)) AS retain_pct_lv3, AVG(COALESCE(s.x_rate4,100)) AS retain_pct_lv4,
          AVG(COALESCE(s.x_rate5,100)) AS retain_pct_lv5, AVG(s.x_chain_depth) AS chain_depth_avg,
          AVG(COALESCE(100.0-s.x_rate1,0)) AS agent_pct_lv1, AVG(COALESCE(100.0-s.x_rate2,0)) AS agent_pct_lv2,
          AVG(COALESCE(100.0-s.x_rate3,0)) AS agent_pct_lv3, AVG(COALESCE(100.0-s.x_rate4,0)) AS agent_pct_lv4,
          AVG(COALESCE(100.0-s.x_rate5,0)) AS agent_pct_lv5,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate1,0)/100.0)                        AS agent_cost_lv1,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate2,0)/100.0)                        AS agent_cost_lv2,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate3,0)/100.0)                        AS agent_cost_lv3,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate4,0)/100.0)                        AS agent_cost_lv4,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate5,0)/100.0)                        AS agent_cost_lv5,
          SUM(-s.x_net*(COALESCE(100.0-s.x_rate1,0)+COALESCE(100.0-s.x_rate2,0)
                       +COALESCE(100.0-s.x_rate3,0)+COALESCE(100.0-s.x_rate4,0)
                       +COALESCE(100.0-s.x_rate5,0))/100.0)                   AS agent_cost_chain_additive,
          SUM(-s.x_net*(1.0 - CAST(COALESCE(s.x_rate1,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate2,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate3,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate4,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate5,100) AS DOUBLE)/100.0))
                                                                       AS agent_cost_chain_nested,
           AVG(s.x_rbpct) AS rbpct, AVG(s.x_freecomm*1.0) AS freecomm_rate,
           PERCENTILE_APPROX(s.x_stake,0.25) AS p25, PERCENTILE_APPROX(s.x_stake,0.50) AS p50,
           PERCENTILE_APPROX(s.x_stake,0.75) AS p75, PERCENTILE_APPROX(s.x_stake,0.90) AS p90,
           PERCENTILE_APPROX(s.x_stake,0.95) AS p95, PERCENTILE_APPROX(s.x_stake,0.99) AS p99,
           PERCENTILE_APPROX(s.x_valid,0.50) AS p50_valid,
           PERCENTILE_APPROX(s.x_net,0.50)   AS p50_profit,
           SUM(CASE WHEN s.x_rec = 1 THEN s.x_stake ELSE 0 END) AS st_in,
           SUM(CASE WHEN s.x_rec = 1 THEN 1 ELSE 0 END)         AS nb_in,
           SUM(CASE WHEN s.x_rec = 1 THEN s.x_net ELSE 0 END)   AS net_in,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN s.x_stake ELSE 0 END) AS st_out,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN 1 ELSE 0 END)         AS nb_out,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN s.x_net ELSE 0 END)   AS net_out,
           SUM(CASE WHEN s.x_rec=1 THEN s.x_stake ELSE 0 END) AS st_rec,
           SUM(CASE WHEN s.x_rec=1 THEN 1 ELSE 0 END)         AS nb_rec
    FROM x_mk s
    WHERE s.is_clean = 1
      AND s.x_member IS NOT NULL AND TRIM(CAST(s.x_member AS STRING)) <> ''
  ),
      q AS (
        SELECT
            TABLE_NAME                          AS 表名,
            TABLE_ROWS                          AS 估计行数,
            TABLE_COMMENT                       AS 表注释,
            CASE
              WHEN LOWER(TABLE_NAME) LIKE '%_bak%'  OR LOWER(TABLE_NAME) LIKE '%bak2%' THEN '备份表·禁用'
              WHEN LOWER(TABLE_NAME) LIKE '%_test%' THEN '测试表·禁用'
              WHEN LOWER(TABLE_NAME) LIKE '%_tmp%'  THEN '临时表·禁用'
              WHEN LOWER(TABLE_NAME) LIKE '%_old%'  THEN '旧版表·禁用'
              WHEN LOWER(TABLE_NAME) LIKE '%_copy%' THEN '副本表·禁用'
              WHEN LOWER(TABLE_NAME) LIKE '%demo%'  THEN '演示表·须确认'
              ELSE '其他·须确认'
            END                                 AS 处置
        FROM INFORMATION_SCHEMA.TABLES
        WHERE TABLE_SCHEMA = 'ods_mariadb_2b'
          AND (   LOWER(TABLE_NAME) LIKE '%_bak%'  OR LOWER(TABLE_NAME) LIKE '%bak2%'
               OR LOWER(TABLE_NAME) LIKE '%_test%' OR LOWER(TABLE_NAME) LIKE '%_tmp%'
               OR LOWER(TABLE_NAME) LIKE '%_old%'  OR LOWER(TABLE_NAME) LIKE '%_copy%'
               OR LOWER(TABLE_NAME) LIKE '%demo%')
      )
    SELECT q.*,
           -- 一·经济层
           ROUND(e.stake,4) AS stake, ROUND(e.valid,4) AS valid_bet,
           ROUND(-e.net,4) AS profit, e.n_bets, e.n_rounds,
           ROUND(e.net/NULLIF(e.stake,0),8) AS roi,
           ROUND(e.net_in/NULLIF(e.st_in,0),8) AS roi_recent,
           ROUND(e.net_out/NULLIF(e.st_out,0),8) AS roi_non_recent,
           ROUND((e.net-e.rebate)/NULLIF(e.stake,0),8) AS roi_ex_rebate,
           ROUND(e.net,4) AS roi_numerator, ROUND(e.stake,4) AS roi_denominator,
           CASE WHEN e.stake IS NULL THEN 'NULL_DENOM' WHEN e.stake<=0 THEN 'ZERO_DENOM'
                WHEN e.n_bets<30 THEN 'THIN_EXPOSURE' ELSE 'OK' END AS roi_denominator_status,
           ROUND(e.rebate,4) AS rebate_cost, ROUND(e.agent_cost,4)                           AS cost_complement_b,
       ROUND(e.agent_pct,4)                            AS pct_complement,
       ROUND(e.company_retain_pct,4)                   AS pct_top_bet23,
       'AG03-UNRESOLVED'                                     AS agent_formula_version,
      'ALL5_LEVELS_bet23_to_bet27'                    AS agent_level_scope,
      ROUND(e.agent_cost_lv1,4) AS agent_cost_lv1, ROUND(e.agent_cost_lv2,4) AS agent_cost_lv2,
      ROUND(e.agent_cost_lv3,4) AS agent_cost_lv3, ROUND(e.agent_cost_lv4,4) AS agent_cost_lv4,
      ROUND(e.agent_cost_lv5,4) AS agent_cost_lv5,
      ROUND(e.agent_pct_lv1,6) AS agent_pct_lv1, ROUND(e.agent_pct_lv2,6) AS agent_pct_lv2,
      ROUND(e.agent_pct_lv3,6) AS agent_pct_lv3, ROUND(e.agent_pct_lv4,6) AS agent_pct_lv4,
      ROUND(e.agent_pct_lv5,6) AS agent_pct_lv5,
      ROUND(e.retain_pct_lv1,6) AS retain_pct_lv1, ROUND(e.retain_pct_lv2,6) AS retain_pct_lv2,
      ROUND(e.retain_pct_lv3,6) AS retain_pct_lv3, ROUND(e.retain_pct_lv4,6) AS retain_pct_lv4,
      ROUND(e.retain_pct_lv5,6) AS retain_pct_lv5, ROUND(e.chain_depth_avg,4) AS chain_depth_avg,
      ROUND(e.agent_cost_chain_additive,4)            AS agent_cost_chain_additive,
      ROUND(e.agent_cost_chain_nested,4)              AS agent_cost_chain_nested,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_additive,4) AS residual_chain_additive,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_nested,4)   AS residual_chain_nested,
      'PENDING_AG03'                                  AS decision_status,
      'FALSE'                                         AS admit_to_risk_decision,
      'NOT_FOR_ENFORCEMENT'                           AS deliverable_class,
       ROUND(e.agent_cost_a_legacy,4)                  AS agent_cost_a_legacy,
       ROUND(e.agent_cost_valid_base_legacy,4)         AS agent_cost_valid_base_legacy,
           ROUND(-e.net-e.rebate,4)                        AS ngr,
       ROUND(-e.net-e.rebate-e.agent_cost,4)           AS residual_b,
       ROUND(-e.net-e.rebate-e.agent_cost_a_legacy,4)  AS residual_a,
           ROUND((-e.net-e.rebate)/NULLIF(e.stake,0),8)    AS ngr_rate,
       ROUND((-e.net-e.rebate-e.agent_cost)/NULLIF(e.stake,0),8)   AS residual_b_rate,
      -- 【HF9c · canonical accounting contract】
      --   以下 canonical 字段只增加明确 scope；不删除、不覆盖既有字段。
      --   formal_bet23_* 保持 HF9b 当前生产公式及其 NULL/0 语义；
      --   lv1~lv5 / additive / nested 则分别采用各自原始 e.* 成本字段，
      --   rate 一律从未舍入的 e.* 分子 / e.stake 计算，禁止由展示值反算。
      ROUND(e.agent_cost,4) AS agent_cost_bet23_formal_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost,4) AS net_margin_bet23_formal_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost)/NULLIF(e.stake,0),8) AS net_margin_bet23_formal_rate_canonical,
      ROUND(e.agent_cost_lv1,4) AS agent_cost_lv1_bet23_canonical,
      ROUND(e.agent_cost_lv2,4) AS agent_cost_lv2_bet24_canonical,
      ROUND(e.agent_cost_lv3,4) AS agent_cost_lv3_bet25_canonical,
      ROUND(e.agent_cost_lv4,4) AS agent_cost_lv4_bet26_canonical,
      ROUND(e.agent_cost_lv5,4) AS agent_cost_lv5_bet27_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_lv1,4) AS net_margin_lv1_bet23_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_lv1)/NULLIF(e.stake,0),8) AS net_margin_lv1_bet23_rate_canonical,
      ROUND(e.agent_cost_chain_additive,4) AS agent_cost_chain_additive_canonical,
      ROUND(e.agent_cost_chain_nested,4) AS agent_cost_chain_nested_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_additive,4) AS net_margin_chain_additive_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_nested,4) AS net_margin_chain_nested_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_chain_additive)/NULLIF(e.stake,0),8) AS net_margin_chain_additive_rate_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_chain_nested)/NULLIF(e.stake,0),8) AS net_margin_chain_nested_rate_canonical,
       ROUND((-e.net-e.rebate-e.agent_cost_a_legacy)/NULLIF(e.stake,0),8) AS residual_a_rate,
           -- 二·分布层
           ROUND(e.stake/NULLIF(e.n_bets,0),4) AS avg_stake_per_bet,
           ROUND(e.valid/NULLIF(e.n_rounds,0),4) AS avg_valid_bet_per_round,
           ROUND(-e.net/NULLIF(e.n_rounds,0),4) AS avg_profit_per_round,
           ROUND(-e.net/NULLIF(e.active_days,0),4) AS avg_profit_per_day,
           ROUND(-e.net/NULLIF(e.active_shoes,0),4) AS avg_profit_per_shoe,
           ROUND(e.stake/NULLIF(e.active_days,0),4) AS avg_stake_per_active_day,
           ROUND(e.n_rounds*1.0/NULLIF(e.active_days,0),4) AS avg_rounds_per_active_day,
           ROUND(e.st_in/NULLIF(e.nb_in,0),4) AS avg_stake_recent,
           ROUND(e.st_out/NULLIF(e.nb_out,0),4) AS avg_stake_non_recent,
           ROUND(e.p25,4) AS p25_stake, ROUND(e.p50,4) AS p50_stake, ROUND(e.p75,4) AS p75_stake,
           ROUND(e.p90,4) AS p90_stake, ROUND(e.p95,4) AS p95_stake, ROUND(e.p99,4) AS p99_stake,
           ROUND(e.p50_valid,4) AS p50_valid_bet, ROUND(e.p50_profit,4) AS p50_profit,
           ROUND(e.p95/NULLIF(e.p50,0),6) AS p95_over_p50,
           ROUND(e.p99/NULLIF(e.p50,0),6) AS p99_over_p50,
           ROUND((e.stake/NULLIF(e.n_bets,0))/NULLIF(e.p50,0),6) AS avg_over_p50,
           -- 三·关系层
           e.n_tables AS common_table_count, e.n_dealers AS common_dealer_count,
           e.n_ips AS common_ip_count, e.n_products AS common_product_count,
           ROUND(e.st_in/NULLIF(e.stake,0),8) AS share_recent,
           -- 四·rate 层
           ROUND(-e.net/NULLIF(e.stake,0),8) AS hold_rate,
           ROUND(-e.net_in/NULLIF(e.st_in,0),8) AS hold_rate_recent,
           ROUND(e.rebate/NULLIF(e.valid,0),8) AS rebate_rate_actual,
           ROUND(e.rbpct,6) AS rebate_pct_config,
           ROUND(e.valid/NULLIF(e.stake,0),6) AS turnover_multiple,
           ROUND(e.freecomm_rate,6) AS free_comm_rate,
           ROUND(e.net_in/NULLIF(e.st_in,0)-e.net_out/NULLIF(e.st_out,0),8) AS roi_delta_recent,
           -- 五·动态层
           e.first_seen_d AS first_seen, e.last_seen_d AS last_seen,
           e.active_days, e.active_shoes, e.active_sessions,
           DATEDIFF(e.last_seen_d, e.first_seen_d)+1 AS span_days,
           ROUND(e.active_days*1.0/NULLIF(DATEDIFF(e.last_seen_d,e.first_seen_d)+1,0),6) AS persistence,
           ROUND((e.st_in/NULLIF(e.nb_in,0))/NULLIF(e.st_out/NULLIF(e.nb_out,0),0),6) AS ramp_recent_vs_prior,
           ROUND((e.st_rec/NULLIF(e.nb_rec,0))/NULLIF(e.stake/NULLIF(e.n_bets,0),0),6) AS ramp_recent_vs_all,
           ROUND((e.st_rec/NULLIF(e.stake,0))/0.30,6) AS stake_ramp,
           -- 六·决策层（HF9g-P5 · D-14 斧正 —— 本件属【全窗基线族】，相对刻度与决策标签一律 NULL）
           --   病灶：x_win 系全窗单行聚合（无 GROUP BY，恒 1 行，此为设计使然，非缺陷），
           --         经 CROSS JOIN 接入后 e.* 全行同值；六层之 NTILE / PERCENT_RANK 施于常数即退化，
           --         PERCENT_RANK 恒 0 ⇒ action_priority 恒判 A，全件 100% 误标。
           --   ★ 斧正原则：不给 x_win 补 GROUP BY —— 那会改变其「全窗基线」语义，属退化。
           --     正解与 #018 之 G-05／G-06 同治：范围外之行不得接受任何下游评分与决策标签。
           --   ★ 本件之 e.* 仍照常供其它列作全窗基线使用，仅六层相对刻度与决策标签置 NULL。
           CAST(NULL AS INT)                                              AS vip_tier,                        -- 空值取值：全窗基线族无实体可分档，置 NULL（NULL＝不适用，非 0）
           CAST(NULL AS DOUBLE)                                           AS economic_value,                  -- 空值取值：同上，禁以常数百分位冒充经济价值
           CAST(NULL AS DOUBLE)                                           AS roi_pr_global,                   -- 空值取值：同上
           CAST(NULL AS DOUBLE)                                           AS risk_value,                      -- 空值取值：兼容列，同上
           CAST(NULL AS DOUBLE)                                           AS pr_stake,                        -- 空值取值：兼容列，同上
           CAST(NULL AS DOUBLE)                                           AS pr_global,                       -- 空值取值：同上
           CAST(NULL AS DOUBLE)                                           AS pr_qualified,                    -- 空值取值：同上
           'GLOBAL_BASELINE_NO_ENTITY_RANKING'                            AS pr_qualified_population,         -- 字面取值：血统 —— 明示本件为全窗基线族，无实体排序总体
           CAST(NULL AS BIGINT)                                           AS pr_global_population_n,          -- 空值取值：血统 —— 不适用
           CAST(NULL AS BIGINT)                                           AS pr_qualified_population_n,       -- 空值取值：血统 —— 不适用
           'NOT_APPLICABLE_GLOBAL_BASELINE'                               AS pr_calculation_method,           -- 字面取值：血统 —— 算法不适用
           'HF9g-P5'                                                      AS pr_calculation_version,          -- 字面取值：血统 —— 算法版本
           CAST(NULL AS STRING)                                           AS evidence_flag,                   -- 空值取值：证据旗标不适用于全窗基线
           CAST(NULL AS STRING)                                           AS evidence_rate,                   -- 空值取值：同上
           CAST(NULL AS DOUBLE)                                           AS hold_ci_halfwidth_approx,        -- 空值取值：同上
           'X 全窗基线 · 不参与实体赏罚'                                    AS action_priority                  -- 字面取值：★ D-14 斧正 —— 本族恒不入赏罚，取代原 100% 误标之「A」
    FROM q
    CROSS JOIN x_win e
  ) y
) z
-- ── 逐批 WHERE 阶梯（★ 口诀：上界 ＝ 下界 ＋ 100000，两数同进）──
--    本件 T_true 未测，无需先跑 T_true；以 0 / 100000 控制本批返回区间，末批由实际行数 < 100000 判定
--    WHERE z.audit_rn >        0 AND z.audit_rn <=   100000   -- 第 1 批
--    WHERE z.audit_rn >   100000 AND z.audit_rn <=   200000   -- 第 2 批
--    WHERE z.audit_rn >   200000 AND z.audit_rn <=   300000   -- 第 3 批
--    WHERE z.audit_rn >   300000 AND z.audit_rn <=   400000   -- 第 4 批
--    WHERE z.audit_rn >   400000 AND z.audit_rn <=   500000   -- 第 5 批
--    WHERE z.audit_rn >   500000 AND z.audit_rn <=   600000   -- 第 6 批
--    WHERE z.audit_rn >   600000 AND z.audit_rn <=   700000   -- 第 7 批
--    …余批类推。第 k 批：WHERE z.audit_rn > (k-1)*100000 AND z.audit_rn <= k*100000
--    某批返回 < 100000 行即为末批，其后不再取。
--
--    ⚠ 常见误写（务必避开）：只推下界而上界不动 ——
--        WHERE z.audit_rn > 100000 AND z.audit_rn <= 100000   ← 自相矛盾，恒为假，返回空集
--        WHERE z.audit_rn > 200000 AND z.audit_rn <= 100000   ← 同上，空集
--      两个数必须**同时**前进，且始终相差 100000。
--      下界 ＝ 上一批之上界；上界 ＝ 本批之上界。
WHERE z.audit_rn > 0 AND z.audit_rn <= 100000 -- ★ HF9c 本批区间
ORDER BY z.audit_rn;


-- ══════════════════════════════════════════════════════════════════════════════════════════════
-- 113. Z03_column_dictionary.csv   [总包行 619~630 · 原 8 列 ＋六层约 60 列]
--     典型学：Z00 基建/元数据　派生旗标：recent（s.x_rec = 1 · 仅供 CASE 条件聚合，全包无任何 WHERE/AND/HAVING 以此过滤）　连接：全窗基线
-- ══════════════════════════════════════════════════════════════════════════════════════════════
-- ★ W-64 · D-14 警示（本件属 x_win 族 · 66 件之一 · 详见 §Z 段 D-14 全案）
--   本件以 `CROSS JOIN x_win e` 接入全局基线，x_win 无 GROUP BY ⇒ 恒 1 行 ⇒ e.* 全行同值。
--   故：economic_value / roi_pr_global / risk_value / pr_stake / pr_global 恒为 0；
--       action_priority 每一行皆为「A 净亏最大十分位 · 优先复核」（Z 分支永不触发）；
--       evidence_rate 恒为最高档；vip_tier 由常数键分档 ⇒ 无信息且非确定。
--   ⇒ 本件决策层三列 **NOT_FOR_DECISION**，裁定前不得用于排班、抽查或汇报。
-- ── ① 先跑 T_true 留档（不足 100000 者一次导全，不必分批）──
-- ── ① T_true：HF9c 不再强制预跑完整 COUNT。
--    本批实际返回行数 < 100000 即判定为末批；全批完成后以各批 n_rows / audit_rn 范围核对总量。

-- ── ② 分批取数：第 1 批。第 k 批只改末行两数为 (k-1)*100000 与 k*100000 ──
--    审计字段二（REDTEAM 2026-08-24 裁定 · 四锁）：
--      audit_rn  全局观测坐标 —— 由**与原版审计版逐字同一**之排序键所生，两版可逐行对账
--      batch_id  物理分批信息 —— 该行所属批次，由 audit_rn 算得，非引擎所赋
--    ★ 锁三：二者皆为审计字段，**不得进入任何业务指标计算**。
--    ★ 锁四：两版经 audit_rn 逐行字段核验后，方可宣布输出完全一致。

-- ── ③ 每批取回后自证四数（任一不符即停手回报，禁止放行）──
--    n_rows        = COUNT(*)      须等于 COUNT(DISTINCT audit_rn)   （批内无重复）
--    audit_rn_min  = MIN(audit_rn) 须等于 (k-1)*100000 + 1           （与上批严丝合缝）
--    audit_rn_max  = MAX(audit_rn) 须等于 min + n_rows - 1           （批内无缺口）
--    全批取毕再验：各批 audit_rn 之并集 = 1 .. T_true，无缺号、无重号。
--     ★ 首行＝平台真净亏最多者（已扣退水与代理占成）。
--
SELECT z.*,
       CAST(FLOOR((z.audit_rn - 1) / 100000) + 1 AS INT)          AS batch_id,
       'A168_HF9F_20260827_0900' AS run_id,
       '2026-08-27 09:00:00' AS snapshot_sync_time
FROM (
  SELECT y.*,
         ROW_NUMBER() OVER (ORDER BY y.`residual_b` ASC, y.`roi` DESC, y.`表名`, y.`列序`, y.`列名`, y.`存储类型`, y.`可空`, y.`原始类型`, y.`业务含义`, y.`原始注释`) AS audit_rn
  FROM (
    WITH
      x_ranked AS (
    SELECT b.bet01, b.bet03, b.bet04, b.bet05, b.bet09, b.bet11, b.bet13,
           b.bet15, b.bet16, b.bet17, b.bet18, b.bet19, b.bet20, b.bet21,
           b.bet22, b.bet23, b.bet24, b.bet25, b.bet26, b.bet27, b.bet38, b.bet39, b.category, b.commission,
           b.dt, b.eid, b.ip, b.validbet, b.updatetime, b.sync_time,
           ROW_NUMBER() OVER (
             PARTITION BY b.bet01
             ORDER BY b.updatetime DESC, b.sync_time DESC, b.dt DESC)      AS x_rn
    FROM ods_mariadb_2b.ods_a168_bet02 b
    WHERE b.dt >= '2026-03-21' AND b.dt < '2026-08-07'
      AND b.bet02 = '101'
      AND b.sync_time <= '2026-08-27 09:00:00'
  ),
    x_testagent AS (
    SELECT age001 AS agent_id FROM ods_mariadb_2b.ods_a168_agent WHERE age022 = '1'
  ),
    x_bs0 AS (
    SELECT b.bet05 AS x_member, b.eid AS x_dealer, b.bet39 AS x_table,
           b.bet03 AS x_shoe, b.ip AS x_ip, b.bet09 AS x_product, b.dt AS x_date,
           CONCAT_WS('|', b.bet03, b.bet04, b.bet39)                      AS x_round,
           CONCAT_WS('|', b.bet39, b.bet03)                               AS x_tblshoe,
           CAST(NULLIF(TRIM(b.bet04),'') AS INT)                          AS x_rno,
           CASE WHEN b.dt >= '2026-07-08' THEN 1 ELSE 0 END               AS x_rec,
           CASE WHEN TRIM(b.commission)='1' THEN 1 ELSE 0 END             AS x_freecomm,
           CAST(NULLIF(TRIM(b.bet13),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_stake,
           CAST(NULLIF(TRIM(b.validbet),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_valid,
           CAST(NULLIF(TRIM(b.bet16),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_rebate,
           CAST(NULLIF(TRIM(b.bet17),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_net,
           CAST(NULLIF(TRIM(b.bet15),'') AS DECIMAL(20,6))                AS x_rbpct,
           COALESCE(CAST(NULLIF(TRIM(b.bet23),'') AS DECIMAL(20,6)),0)   AS x_agpct,
          NULLIF(CAST(NULLIF(TRIM(b.bet23),'') AS DECIMAL(20,6)),0)     AS x_rate1,
          NULLIF(CAST(NULLIF(TRIM(b.bet24),'') AS DECIMAL(20,6)),0)     AS x_rate2,
          NULLIF(CAST(NULLIF(TRIM(b.bet25),'') AS DECIMAL(20,6)),0)     AS x_rate3,
          NULLIF(CAST(NULLIF(TRIM(b.bet26),'') AS DECIMAL(20,6)),0)     AS x_rate4,
          NULLIF(CAST(NULLIF(TRIM(b.bet27),'') AS DECIMAL(20,6)),0)     AS x_rate5,
          (CASE WHEN NULLIF(CAST(NULLIF(TRIM(b.bet22),'') AS BIGINT),0) IS NOT NULL THEN 5
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet21),'') AS BIGINT),0) IS NOT NULL THEN 4
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet20),'') AS BIGINT),0) IS NOT NULL THEN 3
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet19),'') AS BIGINT),0) IS NOT NULL THEN 2
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet18),'') AS BIGINT),0) IS NOT NULL THEN 1
                ELSE 0 END)                                             AS x_chain_depth,
           CASE WHEN COALESCE(t1.agent_id,t2.agent_id,t3.agent_id,
                              t4.agent_id,t5.agent_id) IS NOT NULL
                THEN 1 ELSE 0 END                                        AS f_testline
    FROM x_ranked b
    LEFT JOIN x_testagent t1 ON t1.agent_id = b.bet18
    LEFT JOIN x_testagent t2 ON t2.agent_id = b.bet19
    LEFT JOIN x_testagent t3 ON t3.agent_id = b.bet20
    LEFT JOIN x_testagent t4 ON t4.agent_id = b.bet21
    LEFT JOIN x_testagent t5 ON t5.agent_id = b.bet22
    WHERE b.x_rn = 1
      AND b.category='1' AND UPPER(TRIM(b.bet38))='N'
      AND CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8)) > 0
  ),
  x_mk AS (
    SELECT s.*,
           CASE WHEN s.f_testline = 0 THEN 1 ELSE 0 END                 AS is_clean
    FROM x_bs0 s
  ),
  x_agg AS (
    SELECT s.x_member                                                        AS x_key,
           COUNT(*) AS n_bets, COUNT(DISTINCT s.x_round) AS n_rounds,
           COUNT(DISTINCT s.x_date) AS active_days, COUNT(DISTINCT s.x_tblshoe) AS active_shoes,
           COUNT(DISTINCT CONCAT_WS('|', s.x_date, s.x_table)) AS active_sessions,
           COUNT(DISTINCT s.x_table) AS n_tables, COUNT(DISTINCT s.x_dealer) AS n_dealers,
           COUNT(DISTINCT s.x_ip) AS n_ips, COUNT(DISTINCT s.x_product) AS n_products,
           MIN(s.x_date) AS first_seen_d, MAX(s.x_date) AS last_seen_d,
           SUM(s.x_stake) AS stake, SUM(s.x_valid) AS valid, SUM(s.x_rebate) AS rebate,
           SUM(s.x_net) AS net, SUM(-s.x_net *(100.0-s.x_agpct)/100.0) AS agent_cost,
           AVG(100.0-s.x_agpct)                   AS agent_pct,
           AVG(s.x_agpct)                         AS company_retain_pct,
           SUM(-s.x_net *s.x_agpct/100.0)         AS agent_cost_a_legacy,
           SUM(s.x_valid*s.x_agpct/100.0)         AS agent_cost_valid_base_legacy,
          AVG(COALESCE(s.x_rate1,100)) AS retain_pct_lv1, AVG(COALESCE(s.x_rate2,100)) AS retain_pct_lv2,
          AVG(COALESCE(s.x_rate3,100)) AS retain_pct_lv3, AVG(COALESCE(s.x_rate4,100)) AS retain_pct_lv4,
          AVG(COALESCE(s.x_rate5,100)) AS retain_pct_lv5, AVG(s.x_chain_depth) AS chain_depth_avg,
          AVG(COALESCE(100.0-s.x_rate1,0)) AS agent_pct_lv1, AVG(COALESCE(100.0-s.x_rate2,0)) AS agent_pct_lv2,
          AVG(COALESCE(100.0-s.x_rate3,0)) AS agent_pct_lv3, AVG(COALESCE(100.0-s.x_rate4,0)) AS agent_pct_lv4,
          AVG(COALESCE(100.0-s.x_rate5,0)) AS agent_pct_lv5,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate1,0)/100.0)                        AS agent_cost_lv1,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate2,0)/100.0)                        AS agent_cost_lv2,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate3,0)/100.0)                        AS agent_cost_lv3,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate4,0)/100.0)                        AS agent_cost_lv4,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate5,0)/100.0)                        AS agent_cost_lv5,
          SUM(-s.x_net*(COALESCE(100.0-s.x_rate1,0)+COALESCE(100.0-s.x_rate2,0)
                       +COALESCE(100.0-s.x_rate3,0)+COALESCE(100.0-s.x_rate4,0)
                       +COALESCE(100.0-s.x_rate5,0))/100.0)                   AS agent_cost_chain_additive,
          SUM(-s.x_net*(1.0 - CAST(COALESCE(s.x_rate1,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate2,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate3,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate4,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate5,100) AS DOUBLE)/100.0))
                                                                       AS agent_cost_chain_nested,
           AVG(s.x_rbpct) AS rbpct, AVG(s.x_freecomm*1.0) AS freecomm_rate,
           PERCENTILE_APPROX(s.x_stake,0.25) AS p25, PERCENTILE_APPROX(s.x_stake,0.50) AS p50,
           PERCENTILE_APPROX(s.x_stake,0.75) AS p75, PERCENTILE_APPROX(s.x_stake,0.90) AS p90,
           PERCENTILE_APPROX(s.x_stake,0.95) AS p95, PERCENTILE_APPROX(s.x_stake,0.99) AS p99,
           PERCENTILE_APPROX(s.x_valid,0.50) AS p50_valid,
           PERCENTILE_APPROX(s.x_net,0.50)   AS p50_profit,
           SUM(CASE WHEN s.x_rec = 1 THEN s.x_stake ELSE 0 END) AS st_in,
           SUM(CASE WHEN s.x_rec = 1 THEN 1 ELSE 0 END)         AS nb_in,
           SUM(CASE WHEN s.x_rec = 1 THEN s.x_net ELSE 0 END)   AS net_in,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN s.x_stake ELSE 0 END) AS st_out,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN 1 ELSE 0 END)         AS nb_out,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN s.x_net ELSE 0 END)   AS net_out,
           SUM(CASE WHEN s.x_rec=1 THEN s.x_stake ELSE 0 END) AS st_rec,
           SUM(CASE WHEN s.x_rec=1 THEN 1 ELSE 0 END)         AS nb_rec
    FROM x_mk s
    WHERE s.is_clean = 1
      AND s.x_member IS NOT NULL AND TRIM(CAST(s.x_member AS STRING)) <> ''
    GROUP BY s.x_member
  ),
  x_win AS (
    SELECT            COUNT(*) AS n_bets, COUNT(DISTINCT s.x_round) AS n_rounds,
           COUNT(DISTINCT s.x_date) AS active_days, COUNT(DISTINCT s.x_tblshoe) AS active_shoes,
           COUNT(DISTINCT CONCAT_WS('|', s.x_date, s.x_table)) AS active_sessions,
           COUNT(DISTINCT s.x_table) AS n_tables, COUNT(DISTINCT s.x_dealer) AS n_dealers,
           COUNT(DISTINCT s.x_ip) AS n_ips, COUNT(DISTINCT s.x_product) AS n_products,
           MIN(s.x_date) AS first_seen_d, MAX(s.x_date) AS last_seen_d,
           SUM(s.x_stake) AS stake, SUM(s.x_valid) AS valid, SUM(s.x_rebate) AS rebate,
           SUM(s.x_net) AS net, SUM(-s.x_net *(100.0-s.x_agpct)/100.0) AS agent_cost,
           AVG(100.0-s.x_agpct)                   AS agent_pct,
           AVG(s.x_agpct)                         AS company_retain_pct,
           SUM(-s.x_net *s.x_agpct/100.0)         AS agent_cost_a_legacy,
           SUM(s.x_valid*s.x_agpct/100.0)         AS agent_cost_valid_base_legacy,
          AVG(COALESCE(s.x_rate1,100)) AS retain_pct_lv1, AVG(COALESCE(s.x_rate2,100)) AS retain_pct_lv2,
          AVG(COALESCE(s.x_rate3,100)) AS retain_pct_lv3, AVG(COALESCE(s.x_rate4,100)) AS retain_pct_lv4,
          AVG(COALESCE(s.x_rate5,100)) AS retain_pct_lv5, AVG(s.x_chain_depth) AS chain_depth_avg,
          AVG(COALESCE(100.0-s.x_rate1,0)) AS agent_pct_lv1, AVG(COALESCE(100.0-s.x_rate2,0)) AS agent_pct_lv2,
          AVG(COALESCE(100.0-s.x_rate3,0)) AS agent_pct_lv3, AVG(COALESCE(100.0-s.x_rate4,0)) AS agent_pct_lv4,
          AVG(COALESCE(100.0-s.x_rate5,0)) AS agent_pct_lv5,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate1,0)/100.0)                        AS agent_cost_lv1,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate2,0)/100.0)                        AS agent_cost_lv2,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate3,0)/100.0)                        AS agent_cost_lv3,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate4,0)/100.0)                        AS agent_cost_lv4,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate5,0)/100.0)                        AS agent_cost_lv5,
          SUM(-s.x_net*(COALESCE(100.0-s.x_rate1,0)+COALESCE(100.0-s.x_rate2,0)
                       +COALESCE(100.0-s.x_rate3,0)+COALESCE(100.0-s.x_rate4,0)
                       +COALESCE(100.0-s.x_rate5,0))/100.0)                   AS agent_cost_chain_additive,
          SUM(-s.x_net*(1.0 - CAST(COALESCE(s.x_rate1,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate2,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate3,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate4,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate5,100) AS DOUBLE)/100.0))
                                                                       AS agent_cost_chain_nested,
           AVG(s.x_rbpct) AS rbpct, AVG(s.x_freecomm*1.0) AS freecomm_rate,
           PERCENTILE_APPROX(s.x_stake,0.25) AS p25, PERCENTILE_APPROX(s.x_stake,0.50) AS p50,
           PERCENTILE_APPROX(s.x_stake,0.75) AS p75, PERCENTILE_APPROX(s.x_stake,0.90) AS p90,
           PERCENTILE_APPROX(s.x_stake,0.95) AS p95, PERCENTILE_APPROX(s.x_stake,0.99) AS p99,
           PERCENTILE_APPROX(s.x_valid,0.50) AS p50_valid,
           PERCENTILE_APPROX(s.x_net,0.50)   AS p50_profit,
           SUM(CASE WHEN s.x_rec = 1 THEN s.x_stake ELSE 0 END) AS st_in,
           SUM(CASE WHEN s.x_rec = 1 THEN 1 ELSE 0 END)         AS nb_in,
           SUM(CASE WHEN s.x_rec = 1 THEN s.x_net ELSE 0 END)   AS net_in,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN s.x_stake ELSE 0 END) AS st_out,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN 1 ELSE 0 END)         AS nb_out,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN s.x_net ELSE 0 END)   AS net_out,
           SUM(CASE WHEN s.x_rec=1 THEN s.x_stake ELSE 0 END) AS st_rec,
           SUM(CASE WHEN s.x_rec=1 THEN 1 ELSE 0 END)         AS nb_rec
    FROM x_mk s
    WHERE s.is_clean = 1
      AND s.x_member IS NOT NULL AND TRIM(CAST(s.x_member AS STRING)) <> ''
  ),
      q AS (
        SELECT
            TABLE_NAME                                                        AS 表名,
            ORDINAL_POSITION                                                  AS 列序,
            COLUMN_NAME                                                       AS 列名,
            DATA_TYPE                                                         AS 存储类型,
            IS_NULLABLE                                                       AS 可空,
            REGEXP_EXTRACT(COLUMN_COMMENT, 'source_type=([^;]+)', 1)          AS 原始类型,
            TRIM(REGEXP_REPLACE(COLUMN_COMMENT, 'source_type=[^;]+;', ''))    AS 业务含义,
            COLUMN_COMMENT                                                    AS 原始注释
        FROM INFORMATION_SCHEMA.COLUMNS
        WHERE TABLE_SCHEMA = 'ods_mariadb_2b'
      )
    SELECT q.*,
           -- 一·经济层
           ROUND(e.stake,4) AS stake, ROUND(e.valid,4) AS valid_bet,
           ROUND(-e.net,4) AS profit, e.n_bets, e.n_rounds,
           ROUND(e.net/NULLIF(e.stake,0),8) AS roi,
           ROUND(e.net_in/NULLIF(e.st_in,0),8) AS roi_recent,
           ROUND(e.net_out/NULLIF(e.st_out,0),8) AS roi_non_recent,
           ROUND((e.net-e.rebate)/NULLIF(e.stake,0),8) AS roi_ex_rebate,
           ROUND(e.net,4) AS roi_numerator, ROUND(e.stake,4) AS roi_denominator,
           CASE WHEN e.stake IS NULL THEN 'NULL_DENOM' WHEN e.stake<=0 THEN 'ZERO_DENOM'
                WHEN e.n_bets<30 THEN 'THIN_EXPOSURE' ELSE 'OK' END AS roi_denominator_status,
           ROUND(e.rebate,4) AS rebate_cost, ROUND(e.agent_cost,4)                           AS cost_complement_b,
       ROUND(e.agent_pct,4)                            AS pct_complement,
       ROUND(e.company_retain_pct,4)                   AS pct_top_bet23,
       'AG03-UNRESOLVED'                                     AS agent_formula_version,
      'ALL5_LEVELS_bet23_to_bet27'                    AS agent_level_scope,
      ROUND(e.agent_cost_lv1,4) AS agent_cost_lv1, ROUND(e.agent_cost_lv2,4) AS agent_cost_lv2,
      ROUND(e.agent_cost_lv3,4) AS agent_cost_lv3, ROUND(e.agent_cost_lv4,4) AS agent_cost_lv4,
      ROUND(e.agent_cost_lv5,4) AS agent_cost_lv5,
      ROUND(e.agent_pct_lv1,6) AS agent_pct_lv1, ROUND(e.agent_pct_lv2,6) AS agent_pct_lv2,
      ROUND(e.agent_pct_lv3,6) AS agent_pct_lv3, ROUND(e.agent_pct_lv4,6) AS agent_pct_lv4,
      ROUND(e.agent_pct_lv5,6) AS agent_pct_lv5,
      ROUND(e.retain_pct_lv1,6) AS retain_pct_lv1, ROUND(e.retain_pct_lv2,6) AS retain_pct_lv2,
      ROUND(e.retain_pct_lv3,6) AS retain_pct_lv3, ROUND(e.retain_pct_lv4,6) AS retain_pct_lv4,
      ROUND(e.retain_pct_lv5,6) AS retain_pct_lv5, ROUND(e.chain_depth_avg,4) AS chain_depth_avg,
      ROUND(e.agent_cost_chain_additive,4)            AS agent_cost_chain_additive,
      ROUND(e.agent_cost_chain_nested,4)              AS agent_cost_chain_nested,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_additive,4) AS residual_chain_additive,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_nested,4)   AS residual_chain_nested,
      'PENDING_AG03'                                  AS decision_status,
      'FALSE'                                         AS admit_to_risk_decision,
      'NOT_FOR_ENFORCEMENT'                           AS deliverable_class,
       ROUND(e.agent_cost_a_legacy,4)                  AS agent_cost_a_legacy,
       ROUND(e.agent_cost_valid_base_legacy,4)         AS agent_cost_valid_base_legacy,
           ROUND(-e.net-e.rebate,4)                        AS ngr,
       ROUND(-e.net-e.rebate-e.agent_cost,4)           AS residual_b,
       ROUND(-e.net-e.rebate-e.agent_cost_a_legacy,4)  AS residual_a,
           ROUND((-e.net-e.rebate)/NULLIF(e.stake,0),8)    AS ngr_rate,
       ROUND((-e.net-e.rebate-e.agent_cost)/NULLIF(e.stake,0),8)   AS residual_b_rate,
      -- 【HF9c · canonical accounting contract】
      --   以下 canonical 字段只增加明确 scope；不删除、不覆盖既有字段。
      --   formal_bet23_* 保持 HF9b 当前生产公式及其 NULL/0 语义；
      --   lv1~lv5 / additive / nested 则分别采用各自原始 e.* 成本字段，
      --   rate 一律从未舍入的 e.* 分子 / e.stake 计算，禁止由展示值反算。
      ROUND(e.agent_cost,4) AS agent_cost_bet23_formal_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost,4) AS net_margin_bet23_formal_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost)/NULLIF(e.stake,0),8) AS net_margin_bet23_formal_rate_canonical,
      ROUND(e.agent_cost_lv1,4) AS agent_cost_lv1_bet23_canonical,
      ROUND(e.agent_cost_lv2,4) AS agent_cost_lv2_bet24_canonical,
      ROUND(e.agent_cost_lv3,4) AS agent_cost_lv3_bet25_canonical,
      ROUND(e.agent_cost_lv4,4) AS agent_cost_lv4_bet26_canonical,
      ROUND(e.agent_cost_lv5,4) AS agent_cost_lv5_bet27_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_lv1,4) AS net_margin_lv1_bet23_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_lv1)/NULLIF(e.stake,0),8) AS net_margin_lv1_bet23_rate_canonical,
      ROUND(e.agent_cost_chain_additive,4) AS agent_cost_chain_additive_canonical,
      ROUND(e.agent_cost_chain_nested,4) AS agent_cost_chain_nested_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_additive,4) AS net_margin_chain_additive_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_nested,4) AS net_margin_chain_nested_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_chain_additive)/NULLIF(e.stake,0),8) AS net_margin_chain_additive_rate_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_chain_nested)/NULLIF(e.stake,0),8) AS net_margin_chain_nested_rate_canonical,
       ROUND((-e.net-e.rebate-e.agent_cost_a_legacy)/NULLIF(e.stake,0),8) AS residual_a_rate,
           -- 二·分布层
           ROUND(e.stake/NULLIF(e.n_bets,0),4) AS avg_stake_per_bet,
           ROUND(e.valid/NULLIF(e.n_rounds,0),4) AS avg_valid_bet_per_round,
           ROUND(-e.net/NULLIF(e.n_rounds,0),4) AS avg_profit_per_round,
           ROUND(-e.net/NULLIF(e.active_days,0),4) AS avg_profit_per_day,
           ROUND(-e.net/NULLIF(e.active_shoes,0),4) AS avg_profit_per_shoe,
           ROUND(e.stake/NULLIF(e.active_days,0),4) AS avg_stake_per_active_day,
           ROUND(e.n_rounds*1.0/NULLIF(e.active_days,0),4) AS avg_rounds_per_active_day,
           ROUND(e.st_in/NULLIF(e.nb_in,0),4) AS avg_stake_recent,
           ROUND(e.st_out/NULLIF(e.nb_out,0),4) AS avg_stake_non_recent,
           ROUND(e.p25,4) AS p25_stake, ROUND(e.p50,4) AS p50_stake, ROUND(e.p75,4) AS p75_stake,
           ROUND(e.p90,4) AS p90_stake, ROUND(e.p95,4) AS p95_stake, ROUND(e.p99,4) AS p99_stake,
           ROUND(e.p50_valid,4) AS p50_valid_bet, ROUND(e.p50_profit,4) AS p50_profit,
           ROUND(e.p95/NULLIF(e.p50,0),6) AS p95_over_p50,
           ROUND(e.p99/NULLIF(e.p50,0),6) AS p99_over_p50,
           ROUND((e.stake/NULLIF(e.n_bets,0))/NULLIF(e.p50,0),6) AS avg_over_p50,
           -- 三·关系层
           e.n_tables AS common_table_count, e.n_dealers AS common_dealer_count,
           e.n_ips AS common_ip_count, e.n_products AS common_product_count,
           ROUND(e.st_in/NULLIF(e.stake,0),8) AS share_recent,
           -- 四·rate 层
           ROUND(-e.net/NULLIF(e.stake,0),8) AS hold_rate,
           ROUND(-e.net_in/NULLIF(e.st_in,0),8) AS hold_rate_recent,
           ROUND(e.rebate/NULLIF(e.valid,0),8) AS rebate_rate_actual,
           ROUND(e.rbpct,6) AS rebate_pct_config,
           ROUND(e.valid/NULLIF(e.stake,0),6) AS turnover_multiple,
           ROUND(e.freecomm_rate,6) AS free_comm_rate,
           ROUND(e.net_in/NULLIF(e.st_in,0)-e.net_out/NULLIF(e.st_out,0),8) AS roi_delta_recent,
           -- 五·动态层
           e.first_seen_d AS first_seen, e.last_seen_d AS last_seen,
           e.active_days, e.active_shoes, e.active_sessions,
           DATEDIFF(e.last_seen_d, e.first_seen_d)+1 AS span_days,
           ROUND(e.active_days*1.0/NULLIF(DATEDIFF(e.last_seen_d,e.first_seen_d)+1,0),6) AS persistence,
           ROUND((e.st_in/NULLIF(e.nb_in,0))/NULLIF(e.st_out/NULLIF(e.nb_out,0),0),6) AS ramp_recent_vs_prior,
           ROUND((e.st_rec/NULLIF(e.nb_rec,0))/NULLIF(e.stake/NULLIF(e.n_bets,0),0),6) AS ramp_recent_vs_all,
           ROUND((e.st_rec/NULLIF(e.stake,0))/0.30,6) AS stake_ramp,
           -- 六·决策层（HF9g-P5 · D-14 斧正 —— 本件属【全窗基线族】，相对刻度与决策标签一律 NULL）
           --   病灶：x_win 系全窗单行聚合（无 GROUP BY，恒 1 行，此为设计使然，非缺陷），
           --         经 CROSS JOIN 接入后 e.* 全行同值；六层之 NTILE / PERCENT_RANK 施于常数即退化，
           --         PERCENT_RANK 恒 0 ⇒ action_priority 恒判 A，全件 100% 误标。
           --   ★ 斧正原则：不给 x_win 补 GROUP BY —— 那会改变其「全窗基线」语义，属退化。
           --     正解与 #018 之 G-05／G-06 同治：范围外之行不得接受任何下游评分与决策标签。
           --   ★ 本件之 e.* 仍照常供其它列作全窗基线使用，仅六层相对刻度与决策标签置 NULL。
           CAST(NULL AS INT)                                              AS vip_tier,                        -- 空值取值：全窗基线族无实体可分档，置 NULL（NULL＝不适用，非 0）
           CAST(NULL AS DOUBLE)                                           AS economic_value,                  -- 空值取值：同上，禁以常数百分位冒充经济价值
           CAST(NULL AS DOUBLE)                                           AS roi_pr_global,                   -- 空值取值：同上
           CAST(NULL AS DOUBLE)                                           AS risk_value,                      -- 空值取值：兼容列，同上
           CAST(NULL AS DOUBLE)                                           AS pr_stake,                        -- 空值取值：兼容列，同上
           CAST(NULL AS DOUBLE)                                           AS pr_global,                       -- 空值取值：同上
           CAST(NULL AS DOUBLE)                                           AS pr_qualified,                    -- 空值取值：同上
           'GLOBAL_BASELINE_NO_ENTITY_RANKING'                            AS pr_qualified_population,         -- 字面取值：血统 —— 明示本件为全窗基线族，无实体排序总体
           CAST(NULL AS BIGINT)                                           AS pr_global_population_n,          -- 空值取值：血统 —— 不适用
           CAST(NULL AS BIGINT)                                           AS pr_qualified_population_n,       -- 空值取值：血统 —— 不适用
           'NOT_APPLICABLE_GLOBAL_BASELINE'                               AS pr_calculation_method,           -- 字面取值：血统 —— 算法不适用
           'HF9g-P5'                                                      AS pr_calculation_version,          -- 字面取值：血统 —— 算法版本
           CAST(NULL AS STRING)                                           AS evidence_flag,                   -- 空值取值：证据旗标不适用于全窗基线
           CAST(NULL AS STRING)                                           AS evidence_rate,                   -- 空值取值：同上
           CAST(NULL AS DOUBLE)                                           AS hold_ci_halfwidth_approx,        -- 空值取值：同上
           'X 全窗基线 · 不参与实体赏罚'                                    AS action_priority                  -- 字面取值：★ D-14 斧正 —— 本族恒不入赏罚，取代原 100% 误标之「A」
    FROM q
    CROSS JOIN x_win e
  ) y
) z
-- ── 逐批 WHERE 阶梯（★ 口诀：上界 ＝ 下界 ＋ 100000，两数同进）──
--    本件 T_true 未测，无需先跑 T_true；以 0 / 100000 控制本批返回区间，末批由实际行数 < 100000 判定
--    WHERE z.audit_rn >        0 AND z.audit_rn <=   100000   -- 第 1 批
--    WHERE z.audit_rn >   100000 AND z.audit_rn <=   200000   -- 第 2 批
--    WHERE z.audit_rn >   200000 AND z.audit_rn <=   300000   -- 第 3 批
--    WHERE z.audit_rn >   300000 AND z.audit_rn <=   400000   -- 第 4 批
--    WHERE z.audit_rn >   400000 AND z.audit_rn <=   500000   -- 第 5 批
--    WHERE z.audit_rn >   500000 AND z.audit_rn <=   600000   -- 第 6 批
--    WHERE z.audit_rn >   600000 AND z.audit_rn <=   700000   -- 第 7 批
--    …余批类推。第 k 批：WHERE z.audit_rn > (k-1)*100000 AND z.audit_rn <= k*100000
--    某批返回 < 100000 行即为末批，其后不再取。
--
--    ⚠ 常见误写（务必避开）：只推下界而上界不动 ——
--        WHERE z.audit_rn > 100000 AND z.audit_rn <= 100000   ← 自相矛盾，恒为假，返回空集
--        WHERE z.audit_rn > 200000 AND z.audit_rn <= 100000   ← 同上，空集
--      两个数必须**同时**前进，且始终相差 100000。
--      下界 ＝ 上一批之上界；上界 ＝ 本批之上界。
WHERE z.audit_rn > 0 AND z.audit_rn <= 100000 -- ★ HF9c 本批区间
ORDER BY z.audit_rn;


-- ══════════════════════════════════════════════════════════════════════════════════════════════
-- 114. Z04_name_collision.csv   [总包行 644~667 · 原 6 列 ＋六层约 60 列]
--     典型学：Z00 基建/元数据　派生旗标：recent（s.x_rec = 1 · 仅供 CASE 条件聚合，全包无任何 WHERE/AND/HAVING 以此过滤）　连接：全窗基线
-- ══════════════════════════════════════════════════════════════════════════════════════════════
-- ★ W-64 · D-14 警示（本件属 x_win 族 · 66 件之一 · 详见 §Z 段 D-14 全案）
--   本件以 `CROSS JOIN x_win e` 接入全局基线，x_win 无 GROUP BY ⇒ 恒 1 行 ⇒ e.* 全行同值。
--   故：economic_value / roi_pr_global / risk_value / pr_stake / pr_global 恒为 0；
--       action_priority 每一行皆为「A 净亏最大十分位 · 优先复核」（Z 分支永不触发）；
--       evidence_rate 恒为最高档；vip_tier 由常数键分档 ⇒ 无信息且非确定。
--   ⇒ 本件决策层三列 **NOT_FOR_DECISION**，裁定前不得用于排班、抽查或汇报。
-- ── ① 先跑 T_true 留档（不足 100000 者一次导全，不必分批）──
-- ── ① T_true：HF9c 不再强制预跑完整 COUNT。
--    本批实际返回行数 < 100000 即判定为末批；全批完成后以各批 n_rows / audit_rn 范围核对总量。

-- ── ② 分批取数：第 1 批。第 k 批只改末行两数为 (k-1)*100000 与 k*100000 ──
--    审计字段二（REDTEAM 2026-08-24 裁定 · 四锁）：
--      audit_rn  全局观测坐标 —— 由**与原版审计版逐字同一**之排序键所生，两版可逐行对账
--      batch_id  物理分批信息 —— 该行所属批次，由 audit_rn 算得，非引擎所赋
--    ★ 锁三：二者皆为审计字段，**不得进入任何业务指标计算**。
--    ★ 锁四：两版经 audit_rn 逐行字段核验后，方可宣布输出完全一致。

-- ── ③ 每批取回后自证四数（任一不符即停手回报，禁止放行）──
--    n_rows        = COUNT(*)      须等于 COUNT(DISTINCT audit_rn)   （批内无重复）
--    audit_rn_min  = MIN(audit_rn) 须等于 (k-1)*100000 + 1           （与上批严丝合缝）
--    audit_rn_max  = MAX(audit_rn) 须等于 min + n_rows - 1           （批内无缺口）
--    全批取毕再验：各批 audit_rn 之并集 = 1 .. T_true，无缺号、无重号。
--     ★ 首行＝平台真净亏最多者（已扣退水与代理占成）。
--
SELECT z.*,
       CAST(FLOOR((z.audit_rn - 1) / 100000) + 1 AS INT)          AS batch_id,
       'A168_HF9F_20260827_0900' AS run_id,
       '2026-08-27 09:00:00' AS snapshot_sync_time
FROM (
  SELECT y.*,
         ROW_NUMBER() OVER (ORDER BY y.`residual_b` ASC, y.`roi` DESC, y.`列名`, y.`释义数`, y.`类型数`, y.`出现表数`, y.`风险`, y.`明细`) AS audit_rn
  FROM (
    WITH
      x_ranked AS (
    SELECT b.bet01, b.bet03, b.bet04, b.bet05, b.bet09, b.bet11, b.bet13,
           b.bet15, b.bet16, b.bet17, b.bet18, b.bet19, b.bet20, b.bet21,
           b.bet22, b.bet23, b.bet24, b.bet25, b.bet26, b.bet27, b.bet38, b.bet39, b.category, b.commission,
           b.dt, b.eid, b.ip, b.validbet, b.updatetime, b.sync_time,
           ROW_NUMBER() OVER (
             PARTITION BY b.bet01
             ORDER BY b.updatetime DESC, b.sync_time DESC, b.dt DESC)      AS x_rn
    FROM ods_mariadb_2b.ods_a168_bet02 b
    WHERE b.dt >= '2026-03-21' AND b.dt < '2026-08-07'
      AND b.bet02 = '101'
      AND b.sync_time <= '2026-08-27 09:00:00'
  ),
    x_testagent AS (
    SELECT age001 AS agent_id FROM ods_mariadb_2b.ods_a168_agent WHERE age022 = '1'
  ),
    x_bs0 AS (
    SELECT b.bet05 AS x_member, b.eid AS x_dealer, b.bet39 AS x_table,
           b.bet03 AS x_shoe, b.ip AS x_ip, b.bet09 AS x_product, b.dt AS x_date,
           CONCAT_WS('|', b.bet03, b.bet04, b.bet39)                      AS x_round,
           CONCAT_WS('|', b.bet39, b.bet03)                               AS x_tblshoe,
           CAST(NULLIF(TRIM(b.bet04),'') AS INT)                          AS x_rno,
           CASE WHEN b.dt >= '2026-07-08' THEN 1 ELSE 0 END               AS x_rec,
           CASE WHEN TRIM(b.commission)='1' THEN 1 ELSE 0 END             AS x_freecomm,
           CAST(NULLIF(TRIM(b.bet13),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_stake,
           CAST(NULLIF(TRIM(b.validbet),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_valid,
           CAST(NULLIF(TRIM(b.bet16),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_rebate,
           CAST(NULLIF(TRIM(b.bet17),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_net,
           CAST(NULLIF(TRIM(b.bet15),'') AS DECIMAL(20,6))                AS x_rbpct,
           COALESCE(CAST(NULLIF(TRIM(b.bet23),'') AS DECIMAL(20,6)),0)   AS x_agpct,
          NULLIF(CAST(NULLIF(TRIM(b.bet23),'') AS DECIMAL(20,6)),0)     AS x_rate1,
          NULLIF(CAST(NULLIF(TRIM(b.bet24),'') AS DECIMAL(20,6)),0)     AS x_rate2,
          NULLIF(CAST(NULLIF(TRIM(b.bet25),'') AS DECIMAL(20,6)),0)     AS x_rate3,
          NULLIF(CAST(NULLIF(TRIM(b.bet26),'') AS DECIMAL(20,6)),0)     AS x_rate4,
          NULLIF(CAST(NULLIF(TRIM(b.bet27),'') AS DECIMAL(20,6)),0)     AS x_rate5,
          (CASE WHEN NULLIF(CAST(NULLIF(TRIM(b.bet22),'') AS BIGINT),0) IS NOT NULL THEN 5
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet21),'') AS BIGINT),0) IS NOT NULL THEN 4
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet20),'') AS BIGINT),0) IS NOT NULL THEN 3
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet19),'') AS BIGINT),0) IS NOT NULL THEN 2
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet18),'') AS BIGINT),0) IS NOT NULL THEN 1
                ELSE 0 END)                                             AS x_chain_depth,
           CASE WHEN COALESCE(t1.agent_id,t2.agent_id,t3.agent_id,
                              t4.agent_id,t5.agent_id) IS NOT NULL
                THEN 1 ELSE 0 END                                        AS f_testline
    FROM x_ranked b
    LEFT JOIN x_testagent t1 ON t1.agent_id = b.bet18
    LEFT JOIN x_testagent t2 ON t2.agent_id = b.bet19
    LEFT JOIN x_testagent t3 ON t3.agent_id = b.bet20
    LEFT JOIN x_testagent t4 ON t4.agent_id = b.bet21
    LEFT JOIN x_testagent t5 ON t5.agent_id = b.bet22
    WHERE b.x_rn = 1
      AND b.category='1' AND UPPER(TRIM(b.bet38))='N'
      AND CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8)) > 0
  ),
  x_mk AS (
    SELECT s.*,
           CASE WHEN s.f_testline = 0 THEN 1 ELSE 0 END                 AS is_clean
    FROM x_bs0 s
  ),
  x_agg AS (
    SELECT s.x_member                                                        AS x_key,
           COUNT(*) AS n_bets, COUNT(DISTINCT s.x_round) AS n_rounds,
           COUNT(DISTINCT s.x_date) AS active_days, COUNT(DISTINCT s.x_tblshoe) AS active_shoes,
           COUNT(DISTINCT CONCAT_WS('|', s.x_date, s.x_table)) AS active_sessions,
           COUNT(DISTINCT s.x_table) AS n_tables, COUNT(DISTINCT s.x_dealer) AS n_dealers,
           COUNT(DISTINCT s.x_ip) AS n_ips, COUNT(DISTINCT s.x_product) AS n_products,
           MIN(s.x_date) AS first_seen_d, MAX(s.x_date) AS last_seen_d,
           SUM(s.x_stake) AS stake, SUM(s.x_valid) AS valid, SUM(s.x_rebate) AS rebate,
           SUM(s.x_net) AS net, SUM(-s.x_net *(100.0-s.x_agpct)/100.0) AS agent_cost,
           AVG(100.0-s.x_agpct)                   AS agent_pct,
           AVG(s.x_agpct)                         AS company_retain_pct,
           SUM(-s.x_net *s.x_agpct/100.0)         AS agent_cost_a_legacy,
           SUM(s.x_valid*s.x_agpct/100.0)         AS agent_cost_valid_base_legacy,
          AVG(COALESCE(s.x_rate1,100)) AS retain_pct_lv1, AVG(COALESCE(s.x_rate2,100)) AS retain_pct_lv2,
          AVG(COALESCE(s.x_rate3,100)) AS retain_pct_lv3, AVG(COALESCE(s.x_rate4,100)) AS retain_pct_lv4,
          AVG(COALESCE(s.x_rate5,100)) AS retain_pct_lv5, AVG(s.x_chain_depth) AS chain_depth_avg,
          AVG(COALESCE(100.0-s.x_rate1,0)) AS agent_pct_lv1, AVG(COALESCE(100.0-s.x_rate2,0)) AS agent_pct_lv2,
          AVG(COALESCE(100.0-s.x_rate3,0)) AS agent_pct_lv3, AVG(COALESCE(100.0-s.x_rate4,0)) AS agent_pct_lv4,
          AVG(COALESCE(100.0-s.x_rate5,0)) AS agent_pct_lv5,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate1,0)/100.0)                        AS agent_cost_lv1,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate2,0)/100.0)                        AS agent_cost_lv2,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate3,0)/100.0)                        AS agent_cost_lv3,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate4,0)/100.0)                        AS agent_cost_lv4,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate5,0)/100.0)                        AS agent_cost_lv5,
          SUM(-s.x_net*(COALESCE(100.0-s.x_rate1,0)+COALESCE(100.0-s.x_rate2,0)
                       +COALESCE(100.0-s.x_rate3,0)+COALESCE(100.0-s.x_rate4,0)
                       +COALESCE(100.0-s.x_rate5,0))/100.0)                   AS agent_cost_chain_additive,
          SUM(-s.x_net*(1.0 - CAST(COALESCE(s.x_rate1,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate2,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate3,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate4,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate5,100) AS DOUBLE)/100.0))
                                                                       AS agent_cost_chain_nested,
           AVG(s.x_rbpct) AS rbpct, AVG(s.x_freecomm*1.0) AS freecomm_rate,
           PERCENTILE_APPROX(s.x_stake,0.25) AS p25, PERCENTILE_APPROX(s.x_stake,0.50) AS p50,
           PERCENTILE_APPROX(s.x_stake,0.75) AS p75, PERCENTILE_APPROX(s.x_stake,0.90) AS p90,
           PERCENTILE_APPROX(s.x_stake,0.95) AS p95, PERCENTILE_APPROX(s.x_stake,0.99) AS p99,
           PERCENTILE_APPROX(s.x_valid,0.50) AS p50_valid,
           PERCENTILE_APPROX(s.x_net,0.50)   AS p50_profit,
           SUM(CASE WHEN s.x_rec = 1 THEN s.x_stake ELSE 0 END) AS st_in,
           SUM(CASE WHEN s.x_rec = 1 THEN 1 ELSE 0 END)         AS nb_in,
           SUM(CASE WHEN s.x_rec = 1 THEN s.x_net ELSE 0 END)   AS net_in,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN s.x_stake ELSE 0 END) AS st_out,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN 1 ELSE 0 END)         AS nb_out,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN s.x_net ELSE 0 END)   AS net_out,
           SUM(CASE WHEN s.x_rec=1 THEN s.x_stake ELSE 0 END) AS st_rec,
           SUM(CASE WHEN s.x_rec=1 THEN 1 ELSE 0 END)         AS nb_rec
    FROM x_mk s
    WHERE s.is_clean = 1
      AND s.x_member IS NOT NULL AND TRIM(CAST(s.x_member AS STRING)) <> ''
    GROUP BY s.x_member
  ),
  x_win AS (
    SELECT            COUNT(*) AS n_bets, COUNT(DISTINCT s.x_round) AS n_rounds,
           COUNT(DISTINCT s.x_date) AS active_days, COUNT(DISTINCT s.x_tblshoe) AS active_shoes,
           COUNT(DISTINCT CONCAT_WS('|', s.x_date, s.x_table)) AS active_sessions,
           COUNT(DISTINCT s.x_table) AS n_tables, COUNT(DISTINCT s.x_dealer) AS n_dealers,
           COUNT(DISTINCT s.x_ip) AS n_ips, COUNT(DISTINCT s.x_product) AS n_products,
           MIN(s.x_date) AS first_seen_d, MAX(s.x_date) AS last_seen_d,
           SUM(s.x_stake) AS stake, SUM(s.x_valid) AS valid, SUM(s.x_rebate) AS rebate,
           SUM(s.x_net) AS net, SUM(-s.x_net *(100.0-s.x_agpct)/100.0) AS agent_cost,
           AVG(100.0-s.x_agpct)                   AS agent_pct,
           AVG(s.x_agpct)                         AS company_retain_pct,
           SUM(-s.x_net *s.x_agpct/100.0)         AS agent_cost_a_legacy,
           SUM(s.x_valid*s.x_agpct/100.0)         AS agent_cost_valid_base_legacy,
          AVG(COALESCE(s.x_rate1,100)) AS retain_pct_lv1, AVG(COALESCE(s.x_rate2,100)) AS retain_pct_lv2,
          AVG(COALESCE(s.x_rate3,100)) AS retain_pct_lv3, AVG(COALESCE(s.x_rate4,100)) AS retain_pct_lv4,
          AVG(COALESCE(s.x_rate5,100)) AS retain_pct_lv5, AVG(s.x_chain_depth) AS chain_depth_avg,
          AVG(COALESCE(100.0-s.x_rate1,0)) AS agent_pct_lv1, AVG(COALESCE(100.0-s.x_rate2,0)) AS agent_pct_lv2,
          AVG(COALESCE(100.0-s.x_rate3,0)) AS agent_pct_lv3, AVG(COALESCE(100.0-s.x_rate4,0)) AS agent_pct_lv4,
          AVG(COALESCE(100.0-s.x_rate5,0)) AS agent_pct_lv5,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate1,0)/100.0)                        AS agent_cost_lv1,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate2,0)/100.0)                        AS agent_cost_lv2,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate3,0)/100.0)                        AS agent_cost_lv3,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate4,0)/100.0)                        AS agent_cost_lv4,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate5,0)/100.0)                        AS agent_cost_lv5,
          SUM(-s.x_net*(COALESCE(100.0-s.x_rate1,0)+COALESCE(100.0-s.x_rate2,0)
                       +COALESCE(100.0-s.x_rate3,0)+COALESCE(100.0-s.x_rate4,0)
                       +COALESCE(100.0-s.x_rate5,0))/100.0)                   AS agent_cost_chain_additive,
          SUM(-s.x_net*(1.0 - CAST(COALESCE(s.x_rate1,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate2,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate3,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate4,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate5,100) AS DOUBLE)/100.0))
                                                                       AS agent_cost_chain_nested,
           AVG(s.x_rbpct) AS rbpct, AVG(s.x_freecomm*1.0) AS freecomm_rate,
           PERCENTILE_APPROX(s.x_stake,0.25) AS p25, PERCENTILE_APPROX(s.x_stake,0.50) AS p50,
           PERCENTILE_APPROX(s.x_stake,0.75) AS p75, PERCENTILE_APPROX(s.x_stake,0.90) AS p90,
           PERCENTILE_APPROX(s.x_stake,0.95) AS p95, PERCENTILE_APPROX(s.x_stake,0.99) AS p99,
           PERCENTILE_APPROX(s.x_valid,0.50) AS p50_valid,
           PERCENTILE_APPROX(s.x_net,0.50)   AS p50_profit,
           SUM(CASE WHEN s.x_rec = 1 THEN s.x_stake ELSE 0 END) AS st_in,
           SUM(CASE WHEN s.x_rec = 1 THEN 1 ELSE 0 END)         AS nb_in,
           SUM(CASE WHEN s.x_rec = 1 THEN s.x_net ELSE 0 END)   AS net_in,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN s.x_stake ELSE 0 END) AS st_out,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN 1 ELSE 0 END)         AS nb_out,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN s.x_net ELSE 0 END)   AS net_out,
           SUM(CASE WHEN s.x_rec=1 THEN s.x_stake ELSE 0 END) AS st_rec,
           SUM(CASE WHEN s.x_rec=1 THEN 1 ELSE 0 END)         AS nb_rec
    FROM x_mk s
    WHERE s.is_clean = 1
      AND s.x_member IS NOT NULL AND TRIM(CAST(s.x_member AS STRING)) <> ''
  ),
      q AS (
        WITH d AS (
          SELECT
              COLUMN_NAME,
              TABLE_NAME,
              TRIM(REGEXP_REPLACE(COLUMN_COMMENT, 'source_type=[^;]+;', ''))  AS 含义,
              REGEXP_EXTRACT(COLUMN_COMMENT, 'source_type=([^;]+)', 1)        AS 类型
          FROM INFORMATION_SCHEMA.COLUMNS
          WHERE TABLE_SCHEMA = 'ods_mariadb_2b'
            AND COLUMN_COMMENT IS NOT NULL
            AND TRIM(COLUMN_COMMENT) <> ''
        )
        SELECT
            COLUMN_NAME                                  AS 列名,
            COUNT(DISTINCT 含义)                          AS 释义数,
            COUNT(DISTINCT 类型)                          AS 类型数,
            COUNT(DISTINCT TABLE_NAME)                   AS 出现表数,
            CASE WHEN COUNT(DISTINCT 类型) >= 2 THEN '🔴 义异且型异'
                 ELSE '🟠 义异型同' END                   AS 风险,
            GROUP_CONCAT(DISTINCT CONCAT(TABLE_NAME, ' → ', 含义, ' [', 类型, ']')
                         SEPARATOR '  ||  ')             AS 明细
        FROM d
        GROUP BY COLUMN_NAME
        HAVING COUNT(DISTINCT 含义) >= 2
      )
    SELECT q.*,
           -- 一·经济层
           ROUND(e.stake,4) AS stake, ROUND(e.valid,4) AS valid_bet,
           ROUND(-e.net,4) AS profit, e.n_bets, e.n_rounds,
           ROUND(e.net/NULLIF(e.stake,0),8) AS roi,
           ROUND(e.net_in/NULLIF(e.st_in,0),8) AS roi_recent,
           ROUND(e.net_out/NULLIF(e.st_out,0),8) AS roi_non_recent,
           ROUND((e.net-e.rebate)/NULLIF(e.stake,0),8) AS roi_ex_rebate,
           ROUND(e.net,4) AS roi_numerator, ROUND(e.stake,4) AS roi_denominator,
           CASE WHEN e.stake IS NULL THEN 'NULL_DENOM' WHEN e.stake<=0 THEN 'ZERO_DENOM'
                WHEN e.n_bets<30 THEN 'THIN_EXPOSURE' ELSE 'OK' END AS roi_denominator_status,
           ROUND(e.rebate,4) AS rebate_cost, ROUND(e.agent_cost,4)                           AS cost_complement_b,
       ROUND(e.agent_pct,4)                            AS pct_complement,
       ROUND(e.company_retain_pct,4)                   AS pct_top_bet23,
       'AG03-UNRESOLVED'                                     AS agent_formula_version,
      'ALL5_LEVELS_bet23_to_bet27'                    AS agent_level_scope,
      ROUND(e.agent_cost_lv1,4) AS agent_cost_lv1, ROUND(e.agent_cost_lv2,4) AS agent_cost_lv2,
      ROUND(e.agent_cost_lv3,4) AS agent_cost_lv3, ROUND(e.agent_cost_lv4,4) AS agent_cost_lv4,
      ROUND(e.agent_cost_lv5,4) AS agent_cost_lv5,
      ROUND(e.agent_pct_lv1,6) AS agent_pct_lv1, ROUND(e.agent_pct_lv2,6) AS agent_pct_lv2,
      ROUND(e.agent_pct_lv3,6) AS agent_pct_lv3, ROUND(e.agent_pct_lv4,6) AS agent_pct_lv4,
      ROUND(e.agent_pct_lv5,6) AS agent_pct_lv5,
      ROUND(e.retain_pct_lv1,6) AS retain_pct_lv1, ROUND(e.retain_pct_lv2,6) AS retain_pct_lv2,
      ROUND(e.retain_pct_lv3,6) AS retain_pct_lv3, ROUND(e.retain_pct_lv4,6) AS retain_pct_lv4,
      ROUND(e.retain_pct_lv5,6) AS retain_pct_lv5, ROUND(e.chain_depth_avg,4) AS chain_depth_avg,
      ROUND(e.agent_cost_chain_additive,4)            AS agent_cost_chain_additive,
      ROUND(e.agent_cost_chain_nested,4)              AS agent_cost_chain_nested,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_additive,4) AS residual_chain_additive,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_nested,4)   AS residual_chain_nested,
      'PENDING_AG03'                                  AS decision_status,
      'FALSE'                                         AS admit_to_risk_decision,
      'NOT_FOR_ENFORCEMENT'                           AS deliverable_class,
       ROUND(e.agent_cost_a_legacy,4)                  AS agent_cost_a_legacy,
       ROUND(e.agent_cost_valid_base_legacy,4)         AS agent_cost_valid_base_legacy,
           ROUND(-e.net-e.rebate,4)                        AS ngr,
       ROUND(-e.net-e.rebate-e.agent_cost,4)           AS residual_b,
       ROUND(-e.net-e.rebate-e.agent_cost_a_legacy,4)  AS residual_a,
           ROUND((-e.net-e.rebate)/NULLIF(e.stake,0),8)    AS ngr_rate,
       ROUND((-e.net-e.rebate-e.agent_cost)/NULLIF(e.stake,0),8)   AS residual_b_rate,
      -- 【HF9c · canonical accounting contract】
      --   以下 canonical 字段只增加明确 scope；不删除、不覆盖既有字段。
      --   formal_bet23_* 保持 HF9b 当前生产公式及其 NULL/0 语义；
      --   lv1~lv5 / additive / nested 则分别采用各自原始 e.* 成本字段，
      --   rate 一律从未舍入的 e.* 分子 / e.stake 计算，禁止由展示值反算。
      ROUND(e.agent_cost,4) AS agent_cost_bet23_formal_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost,4) AS net_margin_bet23_formal_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost)/NULLIF(e.stake,0),8) AS net_margin_bet23_formal_rate_canonical,
      ROUND(e.agent_cost_lv1,4) AS agent_cost_lv1_bet23_canonical,
      ROUND(e.agent_cost_lv2,4) AS agent_cost_lv2_bet24_canonical,
      ROUND(e.agent_cost_lv3,4) AS agent_cost_lv3_bet25_canonical,
      ROUND(e.agent_cost_lv4,4) AS agent_cost_lv4_bet26_canonical,
      ROUND(e.agent_cost_lv5,4) AS agent_cost_lv5_bet27_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_lv1,4) AS net_margin_lv1_bet23_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_lv1)/NULLIF(e.stake,0),8) AS net_margin_lv1_bet23_rate_canonical,
      ROUND(e.agent_cost_chain_additive,4) AS agent_cost_chain_additive_canonical,
      ROUND(e.agent_cost_chain_nested,4) AS agent_cost_chain_nested_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_additive,4) AS net_margin_chain_additive_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_nested,4) AS net_margin_chain_nested_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_chain_additive)/NULLIF(e.stake,0),8) AS net_margin_chain_additive_rate_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_chain_nested)/NULLIF(e.stake,0),8) AS net_margin_chain_nested_rate_canonical,
       ROUND((-e.net-e.rebate-e.agent_cost_a_legacy)/NULLIF(e.stake,0),8) AS residual_a_rate,
           -- 二·分布层
           ROUND(e.stake/NULLIF(e.n_bets,0),4) AS avg_stake_per_bet,
           ROUND(e.valid/NULLIF(e.n_rounds,0),4) AS avg_valid_bet_per_round,
           ROUND(-e.net/NULLIF(e.n_rounds,0),4) AS avg_profit_per_round,
           ROUND(-e.net/NULLIF(e.active_days,0),4) AS avg_profit_per_day,
           ROUND(-e.net/NULLIF(e.active_shoes,0),4) AS avg_profit_per_shoe,
           ROUND(e.stake/NULLIF(e.active_days,0),4) AS avg_stake_per_active_day,
           ROUND(e.n_rounds*1.0/NULLIF(e.active_days,0),4) AS avg_rounds_per_active_day,
           ROUND(e.st_in/NULLIF(e.nb_in,0),4) AS avg_stake_recent,
           ROUND(e.st_out/NULLIF(e.nb_out,0),4) AS avg_stake_non_recent,
           ROUND(e.p25,4) AS p25_stake, ROUND(e.p50,4) AS p50_stake, ROUND(e.p75,4) AS p75_stake,
           ROUND(e.p90,4) AS p90_stake, ROUND(e.p95,4) AS p95_stake, ROUND(e.p99,4) AS p99_stake,
           ROUND(e.p50_valid,4) AS p50_valid_bet, ROUND(e.p50_profit,4) AS p50_profit,
           ROUND(e.p95/NULLIF(e.p50,0),6) AS p95_over_p50,
           ROUND(e.p99/NULLIF(e.p50,0),6) AS p99_over_p50,
           ROUND((e.stake/NULLIF(e.n_bets,0))/NULLIF(e.p50,0),6) AS avg_over_p50,
           -- 三·关系层
           e.n_tables AS common_table_count, e.n_dealers AS common_dealer_count,
           e.n_ips AS common_ip_count, e.n_products AS common_product_count,
           ROUND(e.st_in/NULLIF(e.stake,0),8) AS share_recent,
           -- 四·rate 层
           ROUND(-e.net/NULLIF(e.stake,0),8) AS hold_rate,
           ROUND(-e.net_in/NULLIF(e.st_in,0),8) AS hold_rate_recent,
           ROUND(e.rebate/NULLIF(e.valid,0),8) AS rebate_rate_actual,
           ROUND(e.rbpct,6) AS rebate_pct_config,
           ROUND(e.valid/NULLIF(e.stake,0),6) AS turnover_multiple,
           ROUND(e.freecomm_rate,6) AS free_comm_rate,
           ROUND(e.net_in/NULLIF(e.st_in,0)-e.net_out/NULLIF(e.st_out,0),8) AS roi_delta_recent,
           -- 五·动态层
           e.first_seen_d AS first_seen, e.last_seen_d AS last_seen,
           e.active_days, e.active_shoes, e.active_sessions,
           DATEDIFF(e.last_seen_d, e.first_seen_d)+1 AS span_days,
           ROUND(e.active_days*1.0/NULLIF(DATEDIFF(e.last_seen_d,e.first_seen_d)+1,0),6) AS persistence,
           ROUND((e.st_in/NULLIF(e.nb_in,0))/NULLIF(e.st_out/NULLIF(e.nb_out,0),0),6) AS ramp_recent_vs_prior,
           ROUND((e.st_rec/NULLIF(e.nb_rec,0))/NULLIF(e.stake/NULLIF(e.n_bets,0),0),6) AS ramp_recent_vs_all,
           ROUND((e.st_rec/NULLIF(e.stake,0))/0.30,6) AS stake_ramp,
           -- 六·决策层（HF9g-P5 · D-14 斧正 —— 本件属【全窗基线族】，相对刻度与决策标签一律 NULL）
           --   病灶：x_win 系全窗单行聚合（无 GROUP BY，恒 1 行，此为设计使然，非缺陷），
           --         经 CROSS JOIN 接入后 e.* 全行同值；六层之 NTILE / PERCENT_RANK 施于常数即退化，
           --         PERCENT_RANK 恒 0 ⇒ action_priority 恒判 A，全件 100% 误标。
           --   ★ 斧正原则：不给 x_win 补 GROUP BY —— 那会改变其「全窗基线」语义，属退化。
           --     正解与 #018 之 G-05／G-06 同治：范围外之行不得接受任何下游评分与决策标签。
           --   ★ 本件之 e.* 仍照常供其它列作全窗基线使用，仅六层相对刻度与决策标签置 NULL。
           CAST(NULL AS INT)                                              AS vip_tier,                        -- 空值取值：全窗基线族无实体可分档，置 NULL（NULL＝不适用，非 0）
           CAST(NULL AS DOUBLE)                                           AS economic_value,                  -- 空值取值：同上，禁以常数百分位冒充经济价值
           CAST(NULL AS DOUBLE)                                           AS roi_pr_global,                   -- 空值取值：同上
           CAST(NULL AS DOUBLE)                                           AS risk_value,                      -- 空值取值：兼容列，同上
           CAST(NULL AS DOUBLE)                                           AS pr_stake,                        -- 空值取值：兼容列，同上
           CAST(NULL AS DOUBLE)                                           AS pr_global,                       -- 空值取值：同上
           CAST(NULL AS DOUBLE)                                           AS pr_qualified,                    -- 空值取值：同上
           'GLOBAL_BASELINE_NO_ENTITY_RANKING'                            AS pr_qualified_population,         -- 字面取值：血统 —— 明示本件为全窗基线族，无实体排序总体
           CAST(NULL AS BIGINT)                                           AS pr_global_population_n,          -- 空值取值：血统 —— 不适用
           CAST(NULL AS BIGINT)                                           AS pr_qualified_population_n,       -- 空值取值：血统 —— 不适用
           'NOT_APPLICABLE_GLOBAL_BASELINE'                               AS pr_calculation_method,           -- 字面取值：血统 —— 算法不适用
           'HF9g-P5'                                                      AS pr_calculation_version,          -- 字面取值：血统 —— 算法版本
           CAST(NULL AS STRING)                                           AS evidence_flag,                   -- 空值取值：证据旗标不适用于全窗基线
           CAST(NULL AS STRING)                                           AS evidence_rate,                   -- 空值取值：同上
           CAST(NULL AS DOUBLE)                                           AS hold_ci_halfwidth_approx,        -- 空值取值：同上
           'X 全窗基线 · 不参与实体赏罚'                                    AS action_priority                  -- 字面取值：★ D-14 斧正 —— 本族恒不入赏罚，取代原 100% 误标之「A」
    FROM q
    CROSS JOIN x_win e
  ) y
) z
-- ── 逐批 WHERE 阶梯（★ 口诀：上界 ＝ 下界 ＋ 100000，两数同进）──
--    本件 T_true 未测，无需先跑 T_true；以 0 / 100000 控制本批返回区间，末批由实际行数 < 100000 判定
--    WHERE z.audit_rn >        0 AND z.audit_rn <=   100000   -- 第 1 批
--    WHERE z.audit_rn >   100000 AND z.audit_rn <=   200000   -- 第 2 批
--    WHERE z.audit_rn >   200000 AND z.audit_rn <=   300000   -- 第 3 批
--    WHERE z.audit_rn >   300000 AND z.audit_rn <=   400000   -- 第 4 批
--    WHERE z.audit_rn >   400000 AND z.audit_rn <=   500000   -- 第 5 批
--    WHERE z.audit_rn >   500000 AND z.audit_rn <=   600000   -- 第 6 批
--    WHERE z.audit_rn >   600000 AND z.audit_rn <=   700000   -- 第 7 批
--    …余批类推。第 k 批：WHERE z.audit_rn > (k-1)*100000 AND z.audit_rn <= k*100000
--    某批返回 < 100000 行即为末批，其后不再取。
--
--    ⚠ 常见误写（务必避开）：只推下界而上界不动 ——
--        WHERE z.audit_rn > 100000 AND z.audit_rn <= 100000   ← 自相矛盾，恒为假，返回空集
--        WHERE z.audit_rn > 200000 AND z.audit_rn <= 100000   ← 同上，空集
--      两个数必须**同时**前进，且始终相差 100000。
--      下界 ＝ 上一批之上界；上界 ＝ 本批之上界。
WHERE z.audit_rn > 0 AND z.audit_rn <= 100000 -- ★ HF9c 本批区间
ORDER BY z.audit_rn;


-- ══════════════════════════════════════════════════════════════════════════════════════════════
-- 115. Z05_missing_typehint.csv   [总包行 676~695 · 原 6 列 ＋六层约 60 列]
--     典型学：Z00 基建/元数据　派生旗标：recent（s.x_rec = 1 · 仅供 CASE 条件聚合，全包无任何 WHERE/AND/HAVING 以此过滤）　连接：全窗基线
-- ══════════════════════════════════════════════════════════════════════════════════════════════
-- ★ W-64 · D-14 警示（本件属 x_win 族 · 66 件之一 · 详见 §Z 段 D-14 全案）
--   本件以 `CROSS JOIN x_win e` 接入全局基线，x_win 无 GROUP BY ⇒ 恒 1 行 ⇒ e.* 全行同值。
--   故：economic_value / roi_pr_global / risk_value / pr_stake / pr_global 恒为 0；
--       action_priority 每一行皆为「A 净亏最大十分位 · 优先复核」（Z 分支永不触发）；
--       evidence_rate 恒为最高档；vip_tier 由常数键分档 ⇒ 无信息且非确定。
--   ⇒ 本件决策层三列 **NOT_FOR_DECISION**，裁定前不得用于排班、抽查或汇报。
-- ── ① 先跑 T_true 留档（不足 100000 者一次导全，不必分批）──
-- ── ① T_true：HF9c 不再强制预跑完整 COUNT。
--    本批实际返回行数 < 100000 即判定为末批；全批完成后以各批 n_rows / audit_rn 范围核对总量。

-- ── ② 分批取数：第 1 批。第 k 批只改末行两数为 (k-1)*100000 与 k*100000 ──
--    审计字段二（REDTEAM 2026-08-24 裁定 · 四锁）：
--      audit_rn  全局观测坐标 —— 由**与原版审计版逐字同一**之排序键所生，两版可逐行对账
--      batch_id  物理分批信息 —— 该行所属批次，由 audit_rn 算得，非引擎所赋
--    ★ 锁三：二者皆为审计字段，**不得进入任何业务指标计算**。
--    ★ 锁四：两版经 audit_rn 逐行字段核验后，方可宣布输出完全一致。

-- ── ③ 每批取回后自证四数（任一不符即停手回报，禁止放行）──
--    n_rows        = COUNT(*)      须等于 COUNT(DISTINCT audit_rn)   （批内无重复）
--    audit_rn_min  = MIN(audit_rn) 须等于 (k-1)*100000 + 1           （与上批严丝合缝）
--    audit_rn_max  = MAX(audit_rn) 须等于 min + n_rows - 1           （批内无缺口）
--    全批取毕再验：各批 audit_rn 之并集 = 1 .. T_true，无缺号、无重号。
--     ★ 首行＝平台真净亏最多者（已扣退水与代理占成）。
--
SELECT z.*,
       CAST(FLOOR((z.audit_rn - 1) / 100000) + 1 AS INT)          AS batch_id,
       'A168_HF9F_20260827_0900' AS run_id,
       '2026-08-27 09:00:00' AS snapshot_sync_time
FROM (
  SELECT y.*,
         ROW_NUMBER() OVER (ORDER BY y.`residual_b` ASC, y.`roi` DESC, y.`表名`, y.`列序`, y.`列名`, y.`存储类型`, y.`原始注释`, y.`状态`) AS audit_rn
  FROM (
    WITH
      x_ranked AS (
    SELECT b.bet01, b.bet03, b.bet04, b.bet05, b.bet09, b.bet11, b.bet13,
           b.bet15, b.bet16, b.bet17, b.bet18, b.bet19, b.bet20, b.bet21,
           b.bet22, b.bet23, b.bet24, b.bet25, b.bet26, b.bet27, b.bet38, b.bet39, b.category, b.commission,
           b.dt, b.eid, b.ip, b.validbet, b.updatetime, b.sync_time,
           ROW_NUMBER() OVER (
             PARTITION BY b.bet01
             ORDER BY b.updatetime DESC, b.sync_time DESC, b.dt DESC)      AS x_rn
    FROM ods_mariadb_2b.ods_a168_bet02 b
    WHERE b.dt >= '2026-03-21' AND b.dt < '2026-08-07'
      AND b.bet02 = '101'
      AND b.sync_time <= '2026-08-27 09:00:00'
  ),
    x_testagent AS (
    SELECT age001 AS agent_id FROM ods_mariadb_2b.ods_a168_agent WHERE age022 = '1'
  ),
    x_bs0 AS (
    SELECT b.bet05 AS x_member, b.eid AS x_dealer, b.bet39 AS x_table,
           b.bet03 AS x_shoe, b.ip AS x_ip, b.bet09 AS x_product, b.dt AS x_date,
           CONCAT_WS('|', b.bet03, b.bet04, b.bet39)                      AS x_round,
           CONCAT_WS('|', b.bet39, b.bet03)                               AS x_tblshoe,
           CAST(NULLIF(TRIM(b.bet04),'') AS INT)                          AS x_rno,
           CASE WHEN b.dt >= '2026-07-08' THEN 1 ELSE 0 END               AS x_rec,
           CASE WHEN TRIM(b.commission)='1' THEN 1 ELSE 0 END             AS x_freecomm,
           CAST(NULLIF(TRIM(b.bet13),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_stake,
           CAST(NULLIF(TRIM(b.validbet),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_valid,
           CAST(NULLIF(TRIM(b.bet16),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_rebate,
           CAST(NULLIF(TRIM(b.bet17),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_net,
           CAST(NULLIF(TRIM(b.bet15),'') AS DECIMAL(20,6))                AS x_rbpct,
           COALESCE(CAST(NULLIF(TRIM(b.bet23),'') AS DECIMAL(20,6)),0)   AS x_agpct,
          NULLIF(CAST(NULLIF(TRIM(b.bet23),'') AS DECIMAL(20,6)),0)     AS x_rate1,
          NULLIF(CAST(NULLIF(TRIM(b.bet24),'') AS DECIMAL(20,6)),0)     AS x_rate2,
          NULLIF(CAST(NULLIF(TRIM(b.bet25),'') AS DECIMAL(20,6)),0)     AS x_rate3,
          NULLIF(CAST(NULLIF(TRIM(b.bet26),'') AS DECIMAL(20,6)),0)     AS x_rate4,
          NULLIF(CAST(NULLIF(TRIM(b.bet27),'') AS DECIMAL(20,6)),0)     AS x_rate5,
          (CASE WHEN NULLIF(CAST(NULLIF(TRIM(b.bet22),'') AS BIGINT),0) IS NOT NULL THEN 5
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet21),'') AS BIGINT),0) IS NOT NULL THEN 4
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet20),'') AS BIGINT),0) IS NOT NULL THEN 3
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet19),'') AS BIGINT),0) IS NOT NULL THEN 2
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet18),'') AS BIGINT),0) IS NOT NULL THEN 1
                ELSE 0 END)                                             AS x_chain_depth,
           CASE WHEN COALESCE(t1.agent_id,t2.agent_id,t3.agent_id,
                              t4.agent_id,t5.agent_id) IS NOT NULL
                THEN 1 ELSE 0 END                                        AS f_testline
    FROM x_ranked b
    LEFT JOIN x_testagent t1 ON t1.agent_id = b.bet18
    LEFT JOIN x_testagent t2 ON t2.agent_id = b.bet19
    LEFT JOIN x_testagent t3 ON t3.agent_id = b.bet20
    LEFT JOIN x_testagent t4 ON t4.agent_id = b.bet21
    LEFT JOIN x_testagent t5 ON t5.agent_id = b.bet22
    WHERE b.x_rn = 1
      AND b.category='1' AND UPPER(TRIM(b.bet38))='N'
      AND CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8)) > 0
  ),
  x_mk AS (
    SELECT s.*,
           CASE WHEN s.f_testline = 0 THEN 1 ELSE 0 END                 AS is_clean
    FROM x_bs0 s
  ),
  x_agg AS (
    SELECT s.x_member                                                        AS x_key,
           COUNT(*) AS n_bets, COUNT(DISTINCT s.x_round) AS n_rounds,
           COUNT(DISTINCT s.x_date) AS active_days, COUNT(DISTINCT s.x_tblshoe) AS active_shoes,
           COUNT(DISTINCT CONCAT_WS('|', s.x_date, s.x_table)) AS active_sessions,
           COUNT(DISTINCT s.x_table) AS n_tables, COUNT(DISTINCT s.x_dealer) AS n_dealers,
           COUNT(DISTINCT s.x_ip) AS n_ips, COUNT(DISTINCT s.x_product) AS n_products,
           MIN(s.x_date) AS first_seen_d, MAX(s.x_date) AS last_seen_d,
           SUM(s.x_stake) AS stake, SUM(s.x_valid) AS valid, SUM(s.x_rebate) AS rebate,
           SUM(s.x_net) AS net, SUM(-s.x_net *(100.0-s.x_agpct)/100.0) AS agent_cost,
           AVG(100.0-s.x_agpct)                   AS agent_pct,
           AVG(s.x_agpct)                         AS company_retain_pct,
           SUM(-s.x_net *s.x_agpct/100.0)         AS agent_cost_a_legacy,
           SUM(s.x_valid*s.x_agpct/100.0)         AS agent_cost_valid_base_legacy,
          AVG(COALESCE(s.x_rate1,100)) AS retain_pct_lv1, AVG(COALESCE(s.x_rate2,100)) AS retain_pct_lv2,
          AVG(COALESCE(s.x_rate3,100)) AS retain_pct_lv3, AVG(COALESCE(s.x_rate4,100)) AS retain_pct_lv4,
          AVG(COALESCE(s.x_rate5,100)) AS retain_pct_lv5, AVG(s.x_chain_depth) AS chain_depth_avg,
          AVG(COALESCE(100.0-s.x_rate1,0)) AS agent_pct_lv1, AVG(COALESCE(100.0-s.x_rate2,0)) AS agent_pct_lv2,
          AVG(COALESCE(100.0-s.x_rate3,0)) AS agent_pct_lv3, AVG(COALESCE(100.0-s.x_rate4,0)) AS agent_pct_lv4,
          AVG(COALESCE(100.0-s.x_rate5,0)) AS agent_pct_lv5,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate1,0)/100.0)                        AS agent_cost_lv1,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate2,0)/100.0)                        AS agent_cost_lv2,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate3,0)/100.0)                        AS agent_cost_lv3,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate4,0)/100.0)                        AS agent_cost_lv4,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate5,0)/100.0)                        AS agent_cost_lv5,
          SUM(-s.x_net*(COALESCE(100.0-s.x_rate1,0)+COALESCE(100.0-s.x_rate2,0)
                       +COALESCE(100.0-s.x_rate3,0)+COALESCE(100.0-s.x_rate4,0)
                       +COALESCE(100.0-s.x_rate5,0))/100.0)                   AS agent_cost_chain_additive,
          SUM(-s.x_net*(1.0 - CAST(COALESCE(s.x_rate1,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate2,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate3,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate4,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate5,100) AS DOUBLE)/100.0))
                                                                       AS agent_cost_chain_nested,
           AVG(s.x_rbpct) AS rbpct, AVG(s.x_freecomm*1.0) AS freecomm_rate,
           PERCENTILE_APPROX(s.x_stake,0.25) AS p25, PERCENTILE_APPROX(s.x_stake,0.50) AS p50,
           PERCENTILE_APPROX(s.x_stake,0.75) AS p75, PERCENTILE_APPROX(s.x_stake,0.90) AS p90,
           PERCENTILE_APPROX(s.x_stake,0.95) AS p95, PERCENTILE_APPROX(s.x_stake,0.99) AS p99,
           PERCENTILE_APPROX(s.x_valid,0.50) AS p50_valid,
           PERCENTILE_APPROX(s.x_net,0.50)   AS p50_profit,
           SUM(CASE WHEN s.x_rec = 1 THEN s.x_stake ELSE 0 END) AS st_in,
           SUM(CASE WHEN s.x_rec = 1 THEN 1 ELSE 0 END)         AS nb_in,
           SUM(CASE WHEN s.x_rec = 1 THEN s.x_net ELSE 0 END)   AS net_in,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN s.x_stake ELSE 0 END) AS st_out,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN 1 ELSE 0 END)         AS nb_out,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN s.x_net ELSE 0 END)   AS net_out,
           SUM(CASE WHEN s.x_rec=1 THEN s.x_stake ELSE 0 END) AS st_rec,
           SUM(CASE WHEN s.x_rec=1 THEN 1 ELSE 0 END)         AS nb_rec
    FROM x_mk s
    WHERE s.is_clean = 1
      AND s.x_member IS NOT NULL AND TRIM(CAST(s.x_member AS STRING)) <> ''
    GROUP BY s.x_member
  ),
  x_win AS (
    SELECT            COUNT(*) AS n_bets, COUNT(DISTINCT s.x_round) AS n_rounds,
           COUNT(DISTINCT s.x_date) AS active_days, COUNT(DISTINCT s.x_tblshoe) AS active_shoes,
           COUNT(DISTINCT CONCAT_WS('|', s.x_date, s.x_table)) AS active_sessions,
           COUNT(DISTINCT s.x_table) AS n_tables, COUNT(DISTINCT s.x_dealer) AS n_dealers,
           COUNT(DISTINCT s.x_ip) AS n_ips, COUNT(DISTINCT s.x_product) AS n_products,
           MIN(s.x_date) AS first_seen_d, MAX(s.x_date) AS last_seen_d,
           SUM(s.x_stake) AS stake, SUM(s.x_valid) AS valid, SUM(s.x_rebate) AS rebate,
           SUM(s.x_net) AS net, SUM(-s.x_net *(100.0-s.x_agpct)/100.0) AS agent_cost,
           AVG(100.0-s.x_agpct)                   AS agent_pct,
           AVG(s.x_agpct)                         AS company_retain_pct,
           SUM(-s.x_net *s.x_agpct/100.0)         AS agent_cost_a_legacy,
           SUM(s.x_valid*s.x_agpct/100.0)         AS agent_cost_valid_base_legacy,
          AVG(COALESCE(s.x_rate1,100)) AS retain_pct_lv1, AVG(COALESCE(s.x_rate2,100)) AS retain_pct_lv2,
          AVG(COALESCE(s.x_rate3,100)) AS retain_pct_lv3, AVG(COALESCE(s.x_rate4,100)) AS retain_pct_lv4,
          AVG(COALESCE(s.x_rate5,100)) AS retain_pct_lv5, AVG(s.x_chain_depth) AS chain_depth_avg,
          AVG(COALESCE(100.0-s.x_rate1,0)) AS agent_pct_lv1, AVG(COALESCE(100.0-s.x_rate2,0)) AS agent_pct_lv2,
          AVG(COALESCE(100.0-s.x_rate3,0)) AS agent_pct_lv3, AVG(COALESCE(100.0-s.x_rate4,0)) AS agent_pct_lv4,
          AVG(COALESCE(100.0-s.x_rate5,0)) AS agent_pct_lv5,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate1,0)/100.0)                        AS agent_cost_lv1,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate2,0)/100.0)                        AS agent_cost_lv2,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate3,0)/100.0)                        AS agent_cost_lv3,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate4,0)/100.0)                        AS agent_cost_lv4,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate5,0)/100.0)                        AS agent_cost_lv5,
          SUM(-s.x_net*(COALESCE(100.0-s.x_rate1,0)+COALESCE(100.0-s.x_rate2,0)
                       +COALESCE(100.0-s.x_rate3,0)+COALESCE(100.0-s.x_rate4,0)
                       +COALESCE(100.0-s.x_rate5,0))/100.0)                   AS agent_cost_chain_additive,
          SUM(-s.x_net*(1.0 - CAST(COALESCE(s.x_rate1,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate2,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate3,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate4,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate5,100) AS DOUBLE)/100.0))
                                                                       AS agent_cost_chain_nested,
           AVG(s.x_rbpct) AS rbpct, AVG(s.x_freecomm*1.0) AS freecomm_rate,
           PERCENTILE_APPROX(s.x_stake,0.25) AS p25, PERCENTILE_APPROX(s.x_stake,0.50) AS p50,
           PERCENTILE_APPROX(s.x_stake,0.75) AS p75, PERCENTILE_APPROX(s.x_stake,0.90) AS p90,
           PERCENTILE_APPROX(s.x_stake,0.95) AS p95, PERCENTILE_APPROX(s.x_stake,0.99) AS p99,
           PERCENTILE_APPROX(s.x_valid,0.50) AS p50_valid,
           PERCENTILE_APPROX(s.x_net,0.50)   AS p50_profit,
           SUM(CASE WHEN s.x_rec = 1 THEN s.x_stake ELSE 0 END) AS st_in,
           SUM(CASE WHEN s.x_rec = 1 THEN 1 ELSE 0 END)         AS nb_in,
           SUM(CASE WHEN s.x_rec = 1 THEN s.x_net ELSE 0 END)   AS net_in,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN s.x_stake ELSE 0 END) AS st_out,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN 1 ELSE 0 END)         AS nb_out,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN s.x_net ELSE 0 END)   AS net_out,
           SUM(CASE WHEN s.x_rec=1 THEN s.x_stake ELSE 0 END) AS st_rec,
           SUM(CASE WHEN s.x_rec=1 THEN 1 ELSE 0 END)         AS nb_rec
    FROM x_mk s
    WHERE s.is_clean = 1
      AND s.x_member IS NOT NULL AND TRIM(CAST(s.x_member AS STRING)) <> ''
  ),
      q AS (
        SELECT
            TABLE_NAME                        AS 表名,
            ORDINAL_POSITION                  AS 列序,
            COLUMN_NAME                       AS 列名,
            DATA_TYPE                         AS 存储类型,
            COLUMN_COMMENT                    AS 原始注释,
            CASE
              WHEN COLUMN_COMMENT IS NULL OR TRIM(COLUMN_COMMENT) = ''      THEN '🔴 无任何注释'
              WHEN COLUMN_COMMENT NOT LIKE '%source_type=%'                 THEN '🟠 缺原始类型'
              WHEN TRIM(REGEXP_REPLACE(COLUMN_COMMENT,'source_type=[^;]+;','')) = ''
                                                                            THEN '🟠 有类型无含义'
              ELSE '🟢 完整'
            END                               AS 状态
        FROM INFORMATION_SCHEMA.COLUMNS
        WHERE TABLE_SCHEMA = 'ods_mariadb_2b'
          AND (COLUMN_COMMENT IS NULL
               OR TRIM(COLUMN_COMMENT) = ''
               OR COLUMN_COMMENT NOT LIKE '%source_type=%'
               OR TRIM(REGEXP_REPLACE(COLUMN_COMMENT,'source_type=[^;]+;','')) = '')
      )
    SELECT q.*,
           -- 一·经济层
           ROUND(e.stake,4) AS stake, ROUND(e.valid,4) AS valid_bet,
           ROUND(-e.net,4) AS profit, e.n_bets, e.n_rounds,
           ROUND(e.net/NULLIF(e.stake,0),8) AS roi,
           ROUND(e.net_in/NULLIF(e.st_in,0),8) AS roi_recent,
           ROUND(e.net_out/NULLIF(e.st_out,0),8) AS roi_non_recent,
           ROUND((e.net-e.rebate)/NULLIF(e.stake,0),8) AS roi_ex_rebate,
           ROUND(e.net,4) AS roi_numerator, ROUND(e.stake,4) AS roi_denominator,
           CASE WHEN e.stake IS NULL THEN 'NULL_DENOM' WHEN e.stake<=0 THEN 'ZERO_DENOM'
                WHEN e.n_bets<30 THEN 'THIN_EXPOSURE' ELSE 'OK' END AS roi_denominator_status,
           ROUND(e.rebate,4) AS rebate_cost, ROUND(e.agent_cost,4)                           AS cost_complement_b,
       ROUND(e.agent_pct,4)                            AS pct_complement,
       ROUND(e.company_retain_pct,4)                   AS pct_top_bet23,
       'AG03-UNRESOLVED'                                     AS agent_formula_version,
      'ALL5_LEVELS_bet23_to_bet27'                    AS agent_level_scope,
      ROUND(e.agent_cost_lv1,4) AS agent_cost_lv1, ROUND(e.agent_cost_lv2,4) AS agent_cost_lv2,
      ROUND(e.agent_cost_lv3,4) AS agent_cost_lv3, ROUND(e.agent_cost_lv4,4) AS agent_cost_lv4,
      ROUND(e.agent_cost_lv5,4) AS agent_cost_lv5,
      ROUND(e.agent_pct_lv1,6) AS agent_pct_lv1, ROUND(e.agent_pct_lv2,6) AS agent_pct_lv2,
      ROUND(e.agent_pct_lv3,6) AS agent_pct_lv3, ROUND(e.agent_pct_lv4,6) AS agent_pct_lv4,
      ROUND(e.agent_pct_lv5,6) AS agent_pct_lv5,
      ROUND(e.retain_pct_lv1,6) AS retain_pct_lv1, ROUND(e.retain_pct_lv2,6) AS retain_pct_lv2,
      ROUND(e.retain_pct_lv3,6) AS retain_pct_lv3, ROUND(e.retain_pct_lv4,6) AS retain_pct_lv4,
      ROUND(e.retain_pct_lv5,6) AS retain_pct_lv5, ROUND(e.chain_depth_avg,4) AS chain_depth_avg,
      ROUND(e.agent_cost_chain_additive,4)            AS agent_cost_chain_additive,
      ROUND(e.agent_cost_chain_nested,4)              AS agent_cost_chain_nested,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_additive,4) AS residual_chain_additive,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_nested,4)   AS residual_chain_nested,
      'PENDING_AG03'                                  AS decision_status,
      'FALSE'                                         AS admit_to_risk_decision,
      'NOT_FOR_ENFORCEMENT'                           AS deliverable_class,
       ROUND(e.agent_cost_a_legacy,4)                  AS agent_cost_a_legacy,
       ROUND(e.agent_cost_valid_base_legacy,4)         AS agent_cost_valid_base_legacy,
           ROUND(-e.net-e.rebate,4)                        AS ngr,
       ROUND(-e.net-e.rebate-e.agent_cost,4)           AS residual_b,
       ROUND(-e.net-e.rebate-e.agent_cost_a_legacy,4)  AS residual_a,
           ROUND((-e.net-e.rebate)/NULLIF(e.stake,0),8)    AS ngr_rate,
       ROUND((-e.net-e.rebate-e.agent_cost)/NULLIF(e.stake,0),8)   AS residual_b_rate,
      -- 【HF9c · canonical accounting contract】
      --   以下 canonical 字段只增加明确 scope；不删除、不覆盖既有字段。
      --   formal_bet23_* 保持 HF9b 当前生产公式及其 NULL/0 语义；
      --   lv1~lv5 / additive / nested 则分别采用各自原始 e.* 成本字段，
      --   rate 一律从未舍入的 e.* 分子 / e.stake 计算，禁止由展示值反算。
      ROUND(e.agent_cost,4) AS agent_cost_bet23_formal_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost,4) AS net_margin_bet23_formal_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost)/NULLIF(e.stake,0),8) AS net_margin_bet23_formal_rate_canonical,
      ROUND(e.agent_cost_lv1,4) AS agent_cost_lv1_bet23_canonical,
      ROUND(e.agent_cost_lv2,4) AS agent_cost_lv2_bet24_canonical,
      ROUND(e.agent_cost_lv3,4) AS agent_cost_lv3_bet25_canonical,
      ROUND(e.agent_cost_lv4,4) AS agent_cost_lv4_bet26_canonical,
      ROUND(e.agent_cost_lv5,4) AS agent_cost_lv5_bet27_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_lv1,4) AS net_margin_lv1_bet23_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_lv1)/NULLIF(e.stake,0),8) AS net_margin_lv1_bet23_rate_canonical,
      ROUND(e.agent_cost_chain_additive,4) AS agent_cost_chain_additive_canonical,
      ROUND(e.agent_cost_chain_nested,4) AS agent_cost_chain_nested_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_additive,4) AS net_margin_chain_additive_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_nested,4) AS net_margin_chain_nested_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_chain_additive)/NULLIF(e.stake,0),8) AS net_margin_chain_additive_rate_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_chain_nested)/NULLIF(e.stake,0),8) AS net_margin_chain_nested_rate_canonical,
       ROUND((-e.net-e.rebate-e.agent_cost_a_legacy)/NULLIF(e.stake,0),8) AS residual_a_rate,
           -- 二·分布层
           ROUND(e.stake/NULLIF(e.n_bets,0),4) AS avg_stake_per_bet,
           ROUND(e.valid/NULLIF(e.n_rounds,0),4) AS avg_valid_bet_per_round,
           ROUND(-e.net/NULLIF(e.n_rounds,0),4) AS avg_profit_per_round,
           ROUND(-e.net/NULLIF(e.active_days,0),4) AS avg_profit_per_day,
           ROUND(-e.net/NULLIF(e.active_shoes,0),4) AS avg_profit_per_shoe,
           ROUND(e.stake/NULLIF(e.active_days,0),4) AS avg_stake_per_active_day,
           ROUND(e.n_rounds*1.0/NULLIF(e.active_days,0),4) AS avg_rounds_per_active_day,
           ROUND(e.st_in/NULLIF(e.nb_in,0),4) AS avg_stake_recent,
           ROUND(e.st_out/NULLIF(e.nb_out,0),4) AS avg_stake_non_recent,
           ROUND(e.p25,4) AS p25_stake, ROUND(e.p50,4) AS p50_stake, ROUND(e.p75,4) AS p75_stake,
           ROUND(e.p90,4) AS p90_stake, ROUND(e.p95,4) AS p95_stake, ROUND(e.p99,4) AS p99_stake,
           ROUND(e.p50_valid,4) AS p50_valid_bet, ROUND(e.p50_profit,4) AS p50_profit,
           ROUND(e.p95/NULLIF(e.p50,0),6) AS p95_over_p50,
           ROUND(e.p99/NULLIF(e.p50,0),6) AS p99_over_p50,
           ROUND((e.stake/NULLIF(e.n_bets,0))/NULLIF(e.p50,0),6) AS avg_over_p50,
           -- 三·关系层
           e.n_tables AS common_table_count, e.n_dealers AS common_dealer_count,
           e.n_ips AS common_ip_count, e.n_products AS common_product_count,
           ROUND(e.st_in/NULLIF(e.stake,0),8) AS share_recent,
           -- 四·rate 层
           ROUND(-e.net/NULLIF(e.stake,0),8) AS hold_rate,
           ROUND(-e.net_in/NULLIF(e.st_in,0),8) AS hold_rate_recent,
           ROUND(e.rebate/NULLIF(e.valid,0),8) AS rebate_rate_actual,
           ROUND(e.rbpct,6) AS rebate_pct_config,
           ROUND(e.valid/NULLIF(e.stake,0),6) AS turnover_multiple,
           ROUND(e.freecomm_rate,6) AS free_comm_rate,
           ROUND(e.net_in/NULLIF(e.st_in,0)-e.net_out/NULLIF(e.st_out,0),8) AS roi_delta_recent,
           -- 五·动态层
           e.first_seen_d AS first_seen, e.last_seen_d AS last_seen,
           e.active_days, e.active_shoes, e.active_sessions,
           DATEDIFF(e.last_seen_d, e.first_seen_d)+1 AS span_days,
           ROUND(e.active_days*1.0/NULLIF(DATEDIFF(e.last_seen_d,e.first_seen_d)+1,0),6) AS persistence,
           ROUND((e.st_in/NULLIF(e.nb_in,0))/NULLIF(e.st_out/NULLIF(e.nb_out,0),0),6) AS ramp_recent_vs_prior,
           ROUND((e.st_rec/NULLIF(e.nb_rec,0))/NULLIF(e.stake/NULLIF(e.n_bets,0),0),6) AS ramp_recent_vs_all,
           ROUND((e.st_rec/NULLIF(e.stake,0))/0.30,6) AS stake_ramp,
           -- 六·决策层（HF9g-P5 · D-14 斧正 —— 本件属【全窗基线族】，相对刻度与决策标签一律 NULL）
           --   病灶：x_win 系全窗单行聚合（无 GROUP BY，恒 1 行，此为设计使然，非缺陷），
           --         经 CROSS JOIN 接入后 e.* 全行同值；六层之 NTILE / PERCENT_RANK 施于常数即退化，
           --         PERCENT_RANK 恒 0 ⇒ action_priority 恒判 A，全件 100% 误标。
           --   ★ 斧正原则：不给 x_win 补 GROUP BY —— 那会改变其「全窗基线」语义，属退化。
           --     正解与 #018 之 G-05／G-06 同治：范围外之行不得接受任何下游评分与决策标签。
           --   ★ 本件之 e.* 仍照常供其它列作全窗基线使用，仅六层相对刻度与决策标签置 NULL。
           CAST(NULL AS INT)                                              AS vip_tier,                        -- 空值取值：全窗基线族无实体可分档，置 NULL（NULL＝不适用，非 0）
           CAST(NULL AS DOUBLE)                                           AS economic_value,                  -- 空值取值：同上，禁以常数百分位冒充经济价值
           CAST(NULL AS DOUBLE)                                           AS roi_pr_global,                   -- 空值取值：同上
           CAST(NULL AS DOUBLE)                                           AS risk_value,                      -- 空值取值：兼容列，同上
           CAST(NULL AS DOUBLE)                                           AS pr_stake,                        -- 空值取值：兼容列，同上
           CAST(NULL AS DOUBLE)                                           AS pr_global,                       -- 空值取值：同上
           CAST(NULL AS DOUBLE)                                           AS pr_qualified,                    -- 空值取值：同上
           'GLOBAL_BASELINE_NO_ENTITY_RANKING'                            AS pr_qualified_population,         -- 字面取值：血统 —— 明示本件为全窗基线族，无实体排序总体
           CAST(NULL AS BIGINT)                                           AS pr_global_population_n,          -- 空值取值：血统 —— 不适用
           CAST(NULL AS BIGINT)                                           AS pr_qualified_population_n,       -- 空值取值：血统 —— 不适用
           'NOT_APPLICABLE_GLOBAL_BASELINE'                               AS pr_calculation_method,           -- 字面取值：血统 —— 算法不适用
           'HF9g-P5'                                                      AS pr_calculation_version,          -- 字面取值：血统 —— 算法版本
           CAST(NULL AS STRING)                                           AS evidence_flag,                   -- 空值取值：证据旗标不适用于全窗基线
           CAST(NULL AS STRING)                                           AS evidence_rate,                   -- 空值取值：同上
           CAST(NULL AS DOUBLE)                                           AS hold_ci_halfwidth_approx,        -- 空值取值：同上
           'X 全窗基线 · 不参与实体赏罚'                                    AS action_priority                  -- 字面取值：★ D-14 斧正 —— 本族恒不入赏罚，取代原 100% 误标之「A」
    FROM q
    CROSS JOIN x_win e
  ) y
) z
-- ── 逐批 WHERE 阶梯（★ 口诀：上界 ＝ 下界 ＋ 100000，两数同进）──
--    本件 T_true 未测，无需先跑 T_true；以 0 / 100000 控制本批返回区间，末批由实际行数 < 100000 判定
--    WHERE z.audit_rn >        0 AND z.audit_rn <=   100000   -- 第 1 批
--    WHERE z.audit_rn >   100000 AND z.audit_rn <=   200000   -- 第 2 批
--    WHERE z.audit_rn >   200000 AND z.audit_rn <=   300000   -- 第 3 批
--    WHERE z.audit_rn >   300000 AND z.audit_rn <=   400000   -- 第 4 批
--    WHERE z.audit_rn >   400000 AND z.audit_rn <=   500000   -- 第 5 批
--    WHERE z.audit_rn >   500000 AND z.audit_rn <=   600000   -- 第 6 批
--    WHERE z.audit_rn >   600000 AND z.audit_rn <=   700000   -- 第 7 批
--    …余批类推。第 k 批：WHERE z.audit_rn > (k-1)*100000 AND z.audit_rn <= k*100000
--    某批返回 < 100000 行即为末批，其后不再取。
--
--    ⚠ 常见误写（务必避开）：只推下界而上界不动 ——
--        WHERE z.audit_rn > 100000 AND z.audit_rn <= 100000   ← 自相矛盾，恒为假，返回空集
--        WHERE z.audit_rn > 200000 AND z.audit_rn <= 100000   ← 同上，空集
--      两个数必须**同时**前进，且始终相差 100000。
--      下界 ＝ 上一批之上界；上界 ＝ 本批之上界。
WHERE z.audit_rn > 0 AND z.audit_rn <= 100000 -- ★ HF9c 本批区间
ORDER BY z.audit_rn;


-- ══════════════════════════════════════════════════════════════════════════════════════════════
-- 116. Z06_generated_probe_sql.csv   [总包行 709~730 · 原 5 列 ＋六层约 60 列]
--     典型学：Z00 基建/元数据　派生旗标：recent（s.x_rec = 1 · 仅供 CASE 条件聚合，全包无任何 WHERE/AND/HAVING 以此过滤）　连接：全窗基线
-- ══════════════════════════════════════════════════════════════════════════════════════════════
-- ★ W-64 · D-14 警示（本件属 x_win 族 · 66 件之一 · 详见 §Z 段 D-14 全案）
--   本件以 `CROSS JOIN x_win e` 接入全局基线，x_win 无 GROUP BY ⇒ 恒 1 行 ⇒ e.* 全行同值。
--   故：economic_value / roi_pr_global / risk_value / pr_stake / pr_global 恒为 0；
--       action_priority 每一行皆为「A 净亏最大十分位 · 优先复核」（Z 分支永不触发）；
--       evidence_rate 恒为最高档；vip_tier 由常数键分档 ⇒ 无信息且非确定。
--   ⇒ 本件决策层三列 **NOT_FOR_DECISION**，裁定前不得用于排班、抽查或汇报。
-- ── ① 先跑 T_true 留档（不足 100000 者一次导全，不必分批）──
-- ── ① T_true：HF9c 不再强制预跑完整 COUNT。
--    本批实际返回行数 < 100000 即判定为末批；全批完成后以各批 n_rows / audit_rn 范围核对总量。

-- ── ② 分批取数：第 1 批。第 k 批只改末行两数为 (k-1)*100000 与 k*100000 ──
--    审计字段二（REDTEAM 2026-08-24 裁定 · 四锁）：
--      audit_rn  全局观测坐标 —— 由**与原版审计版逐字同一**之排序键所生，两版可逐行对账
--      batch_id  物理分批信息 —— 该行所属批次，由 audit_rn 算得，非引擎所赋
--    ★ 锁三：二者皆为审计字段，**不得进入任何业务指标计算**。
--    ★ 锁四：两版经 audit_rn 逐行字段核验后，方可宣布输出完全一致。

-- ── ③ 每批取回后自证四数（任一不符即停手回报，禁止放行）──
--    n_rows        = COUNT(*)      须等于 COUNT(DISTINCT audit_rn)   （批内无重复）
--    audit_rn_min  = MIN(audit_rn) 须等于 (k-1)*100000 + 1           （与上批严丝合缝）
--    audit_rn_max  = MAX(audit_rn) 须等于 min + n_rows - 1           （批内无缺口）
--    全批取毕再验：各批 audit_rn 之并集 = 1 .. T_true，无缺号、无重号。
--     ★ 首行＝平台真净亏最多者（已扣退水与代理占成）。
--
SELECT z.*,
       CAST(FLOOR((z.audit_rn - 1) / 100000) + 1 AS INT)          AS batch_id,
       'A168_HF9F_20260827_0900' AS run_id,
       '2026-08-27 09:00:00' AS snapshot_sync_time
FROM (
  SELECT y.*,
         ROW_NUMBER() OVER (ORDER BY y.`residual_b` ASC, y.`roi` DESC, y.`表名`, y.`列序`, y.`列名`, y.`估计行数`, y.`待执行SQL`) AS audit_rn
  FROM (
    WITH
      x_ranked AS (
    SELECT b.bet01, b.bet03, b.bet04, b.bet05, b.bet09, b.bet11, b.bet13,
           b.bet15, b.bet16, b.bet17, b.bet18, b.bet19, b.bet20, b.bet21,
           b.bet22, b.bet23, b.bet24, b.bet25, b.bet26, b.bet27, b.bet38, b.bet39, b.category, b.commission,
           b.dt, b.eid, b.ip, b.validbet, b.updatetime, b.sync_time,
           ROW_NUMBER() OVER (
             PARTITION BY b.bet01
             ORDER BY b.updatetime DESC, b.sync_time DESC, b.dt DESC)      AS x_rn
    FROM ods_mariadb_2b.ods_a168_bet02 b
    WHERE b.dt >= '2026-03-21' AND b.dt < '2026-08-07'
      AND b.bet02 = '101'
      AND b.sync_time <= '2026-08-27 09:00:00'
  ),
    x_testagent AS (
    SELECT age001 AS agent_id FROM ods_mariadb_2b.ods_a168_agent WHERE age022 = '1'
  ),
    x_bs0 AS (
    SELECT b.bet05 AS x_member, b.eid AS x_dealer, b.bet39 AS x_table,
           b.bet03 AS x_shoe, b.ip AS x_ip, b.bet09 AS x_product, b.dt AS x_date,
           CONCAT_WS('|', b.bet03, b.bet04, b.bet39)                      AS x_round,
           CONCAT_WS('|', b.bet39, b.bet03)                               AS x_tblshoe,
           CAST(NULLIF(TRIM(b.bet04),'') AS INT)                          AS x_rno,
           CASE WHEN b.dt >= '2026-07-08' THEN 1 ELSE 0 END               AS x_rec,
           CASE WHEN TRIM(b.commission)='1' THEN 1 ELSE 0 END             AS x_freecomm,
           CAST(NULLIF(TRIM(b.bet13),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_stake,
           CAST(NULLIF(TRIM(b.validbet),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_valid,
           CAST(NULLIF(TRIM(b.bet16),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_rebate,
           CAST(NULLIF(TRIM(b.bet17),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_net,
           CAST(NULLIF(TRIM(b.bet15),'') AS DECIMAL(20,6))                AS x_rbpct,
           COALESCE(CAST(NULLIF(TRIM(b.bet23),'') AS DECIMAL(20,6)),0)   AS x_agpct,
          NULLIF(CAST(NULLIF(TRIM(b.bet23),'') AS DECIMAL(20,6)),0)     AS x_rate1,
          NULLIF(CAST(NULLIF(TRIM(b.bet24),'') AS DECIMAL(20,6)),0)     AS x_rate2,
          NULLIF(CAST(NULLIF(TRIM(b.bet25),'') AS DECIMAL(20,6)),0)     AS x_rate3,
          NULLIF(CAST(NULLIF(TRIM(b.bet26),'') AS DECIMAL(20,6)),0)     AS x_rate4,
          NULLIF(CAST(NULLIF(TRIM(b.bet27),'') AS DECIMAL(20,6)),0)     AS x_rate5,
          (CASE WHEN NULLIF(CAST(NULLIF(TRIM(b.bet22),'') AS BIGINT),0) IS NOT NULL THEN 5
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet21),'') AS BIGINT),0) IS NOT NULL THEN 4
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet20),'') AS BIGINT),0) IS NOT NULL THEN 3
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet19),'') AS BIGINT),0) IS NOT NULL THEN 2
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet18),'') AS BIGINT),0) IS NOT NULL THEN 1
                ELSE 0 END)                                             AS x_chain_depth,
           CASE WHEN COALESCE(t1.agent_id,t2.agent_id,t3.agent_id,
                              t4.agent_id,t5.agent_id) IS NOT NULL
                THEN 1 ELSE 0 END                                        AS f_testline
    FROM x_ranked b
    LEFT JOIN x_testagent t1 ON t1.agent_id = b.bet18
    LEFT JOIN x_testagent t2 ON t2.agent_id = b.bet19
    LEFT JOIN x_testagent t3 ON t3.agent_id = b.bet20
    LEFT JOIN x_testagent t4 ON t4.agent_id = b.bet21
    LEFT JOIN x_testagent t5 ON t5.agent_id = b.bet22
    WHERE b.x_rn = 1
      AND b.category='1' AND UPPER(TRIM(b.bet38))='N'
      AND CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8)) > 0
  ),
  x_mk AS (
    SELECT s.*,
           CASE WHEN s.f_testline = 0 THEN 1 ELSE 0 END                 AS is_clean
    FROM x_bs0 s
  ),
  x_agg AS (
    SELECT s.x_member                                                        AS x_key,
           COUNT(*) AS n_bets, COUNT(DISTINCT s.x_round) AS n_rounds,
           COUNT(DISTINCT s.x_date) AS active_days, COUNT(DISTINCT s.x_tblshoe) AS active_shoes,
           COUNT(DISTINCT CONCAT_WS('|', s.x_date, s.x_table)) AS active_sessions,
           COUNT(DISTINCT s.x_table) AS n_tables, COUNT(DISTINCT s.x_dealer) AS n_dealers,
           COUNT(DISTINCT s.x_ip) AS n_ips, COUNT(DISTINCT s.x_product) AS n_products,
           MIN(s.x_date) AS first_seen_d, MAX(s.x_date) AS last_seen_d,
           SUM(s.x_stake) AS stake, SUM(s.x_valid) AS valid, SUM(s.x_rebate) AS rebate,
           SUM(s.x_net) AS net, SUM(-s.x_net *(100.0-s.x_agpct)/100.0) AS agent_cost,
           AVG(100.0-s.x_agpct)                   AS agent_pct,
           AVG(s.x_agpct)                         AS company_retain_pct,
           SUM(-s.x_net *s.x_agpct/100.0)         AS agent_cost_a_legacy,
           SUM(s.x_valid*s.x_agpct/100.0)         AS agent_cost_valid_base_legacy,
          AVG(COALESCE(s.x_rate1,100)) AS retain_pct_lv1, AVG(COALESCE(s.x_rate2,100)) AS retain_pct_lv2,
          AVG(COALESCE(s.x_rate3,100)) AS retain_pct_lv3, AVG(COALESCE(s.x_rate4,100)) AS retain_pct_lv4,
          AVG(COALESCE(s.x_rate5,100)) AS retain_pct_lv5, AVG(s.x_chain_depth) AS chain_depth_avg,
          AVG(COALESCE(100.0-s.x_rate1,0)) AS agent_pct_lv1, AVG(COALESCE(100.0-s.x_rate2,0)) AS agent_pct_lv2,
          AVG(COALESCE(100.0-s.x_rate3,0)) AS agent_pct_lv3, AVG(COALESCE(100.0-s.x_rate4,0)) AS agent_pct_lv4,
          AVG(COALESCE(100.0-s.x_rate5,0)) AS agent_pct_lv5,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate1,0)/100.0)                        AS agent_cost_lv1,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate2,0)/100.0)                        AS agent_cost_lv2,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate3,0)/100.0)                        AS agent_cost_lv3,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate4,0)/100.0)                        AS agent_cost_lv4,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate5,0)/100.0)                        AS agent_cost_lv5,
          SUM(-s.x_net*(COALESCE(100.0-s.x_rate1,0)+COALESCE(100.0-s.x_rate2,0)
                       +COALESCE(100.0-s.x_rate3,0)+COALESCE(100.0-s.x_rate4,0)
                       +COALESCE(100.0-s.x_rate5,0))/100.0)                   AS agent_cost_chain_additive,
          SUM(-s.x_net*(1.0 - CAST(COALESCE(s.x_rate1,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate2,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate3,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate4,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate5,100) AS DOUBLE)/100.0))
                                                                       AS agent_cost_chain_nested,
           AVG(s.x_rbpct) AS rbpct, AVG(s.x_freecomm*1.0) AS freecomm_rate,
           PERCENTILE_APPROX(s.x_stake,0.25) AS p25, PERCENTILE_APPROX(s.x_stake,0.50) AS p50,
           PERCENTILE_APPROX(s.x_stake,0.75) AS p75, PERCENTILE_APPROX(s.x_stake,0.90) AS p90,
           PERCENTILE_APPROX(s.x_stake,0.95) AS p95, PERCENTILE_APPROX(s.x_stake,0.99) AS p99,
           PERCENTILE_APPROX(s.x_valid,0.50) AS p50_valid,
           PERCENTILE_APPROX(s.x_net,0.50)   AS p50_profit,
           SUM(CASE WHEN s.x_rec = 1 THEN s.x_stake ELSE 0 END) AS st_in,
           SUM(CASE WHEN s.x_rec = 1 THEN 1 ELSE 0 END)         AS nb_in,
           SUM(CASE WHEN s.x_rec = 1 THEN s.x_net ELSE 0 END)   AS net_in,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN s.x_stake ELSE 0 END) AS st_out,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN 1 ELSE 0 END)         AS nb_out,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN s.x_net ELSE 0 END)   AS net_out,
           SUM(CASE WHEN s.x_rec=1 THEN s.x_stake ELSE 0 END) AS st_rec,
           SUM(CASE WHEN s.x_rec=1 THEN 1 ELSE 0 END)         AS nb_rec
    FROM x_mk s
    WHERE s.is_clean = 1
      AND s.x_member IS NOT NULL AND TRIM(CAST(s.x_member AS STRING)) <> ''
    GROUP BY s.x_member
  ),
  x_win AS (
    SELECT            COUNT(*) AS n_bets, COUNT(DISTINCT s.x_round) AS n_rounds,
           COUNT(DISTINCT s.x_date) AS active_days, COUNT(DISTINCT s.x_tblshoe) AS active_shoes,
           COUNT(DISTINCT CONCAT_WS('|', s.x_date, s.x_table)) AS active_sessions,
           COUNT(DISTINCT s.x_table) AS n_tables, COUNT(DISTINCT s.x_dealer) AS n_dealers,
           COUNT(DISTINCT s.x_ip) AS n_ips, COUNT(DISTINCT s.x_product) AS n_products,
           MIN(s.x_date) AS first_seen_d, MAX(s.x_date) AS last_seen_d,
           SUM(s.x_stake) AS stake, SUM(s.x_valid) AS valid, SUM(s.x_rebate) AS rebate,
           SUM(s.x_net) AS net, SUM(-s.x_net *(100.0-s.x_agpct)/100.0) AS agent_cost,
           AVG(100.0-s.x_agpct)                   AS agent_pct,
           AVG(s.x_agpct)                         AS company_retain_pct,
           SUM(-s.x_net *s.x_agpct/100.0)         AS agent_cost_a_legacy,
           SUM(s.x_valid*s.x_agpct/100.0)         AS agent_cost_valid_base_legacy,
          AVG(COALESCE(s.x_rate1,100)) AS retain_pct_lv1, AVG(COALESCE(s.x_rate2,100)) AS retain_pct_lv2,
          AVG(COALESCE(s.x_rate3,100)) AS retain_pct_lv3, AVG(COALESCE(s.x_rate4,100)) AS retain_pct_lv4,
          AVG(COALESCE(s.x_rate5,100)) AS retain_pct_lv5, AVG(s.x_chain_depth) AS chain_depth_avg,
          AVG(COALESCE(100.0-s.x_rate1,0)) AS agent_pct_lv1, AVG(COALESCE(100.0-s.x_rate2,0)) AS agent_pct_lv2,
          AVG(COALESCE(100.0-s.x_rate3,0)) AS agent_pct_lv3, AVG(COALESCE(100.0-s.x_rate4,0)) AS agent_pct_lv4,
          AVG(COALESCE(100.0-s.x_rate5,0)) AS agent_pct_lv5,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate1,0)/100.0)                        AS agent_cost_lv1,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate2,0)/100.0)                        AS agent_cost_lv2,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate3,0)/100.0)                        AS agent_cost_lv3,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate4,0)/100.0)                        AS agent_cost_lv4,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate5,0)/100.0)                        AS agent_cost_lv5,
          SUM(-s.x_net*(COALESCE(100.0-s.x_rate1,0)+COALESCE(100.0-s.x_rate2,0)
                       +COALESCE(100.0-s.x_rate3,0)+COALESCE(100.0-s.x_rate4,0)
                       +COALESCE(100.0-s.x_rate5,0))/100.0)                   AS agent_cost_chain_additive,
          SUM(-s.x_net*(1.0 - CAST(COALESCE(s.x_rate1,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate2,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate3,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate4,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate5,100) AS DOUBLE)/100.0))
                                                                       AS agent_cost_chain_nested,
           AVG(s.x_rbpct) AS rbpct, AVG(s.x_freecomm*1.0) AS freecomm_rate,
           PERCENTILE_APPROX(s.x_stake,0.25) AS p25, PERCENTILE_APPROX(s.x_stake,0.50) AS p50,
           PERCENTILE_APPROX(s.x_stake,0.75) AS p75, PERCENTILE_APPROX(s.x_stake,0.90) AS p90,
           PERCENTILE_APPROX(s.x_stake,0.95) AS p95, PERCENTILE_APPROX(s.x_stake,0.99) AS p99,
           PERCENTILE_APPROX(s.x_valid,0.50) AS p50_valid,
           PERCENTILE_APPROX(s.x_net,0.50)   AS p50_profit,
           SUM(CASE WHEN s.x_rec = 1 THEN s.x_stake ELSE 0 END) AS st_in,
           SUM(CASE WHEN s.x_rec = 1 THEN 1 ELSE 0 END)         AS nb_in,
           SUM(CASE WHEN s.x_rec = 1 THEN s.x_net ELSE 0 END)   AS net_in,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN s.x_stake ELSE 0 END) AS st_out,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN 1 ELSE 0 END)         AS nb_out,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN s.x_net ELSE 0 END)   AS net_out,
           SUM(CASE WHEN s.x_rec=1 THEN s.x_stake ELSE 0 END) AS st_rec,
           SUM(CASE WHEN s.x_rec=1 THEN 1 ELSE 0 END)         AS nb_rec
    FROM x_mk s
    WHERE s.is_clean = 1
      AND s.x_member IS NOT NULL AND TRIM(CAST(s.x_member AS STRING)) <> ''
  ),
      q AS (
        SELECT
            c.TABLE_NAME                                          AS 表名,
            c.ORDINAL_POSITION                                    AS 列序,
            c.COLUMN_NAME                                         AS 列名,
            t.TABLE_ROWS                                          AS 估计行数,
            CONCAT(
              'SELECT ''', c.TABLE_NAME, ''' AS t, ''', c.COLUMN_NAME, ''' AS c, ',
              'CAST(', c.COLUMN_NAME, ' AS VARCHAR) AS v, COUNT(*) AS n, ',
              'COUNT(*) * 1.0 / SUM(COUNT(*)) OVER () AS pct ',
              'FROM ods_mariadb_2b.', c.TABLE_NAME, ' ',
              'GROUP BY 3 ORDER BY n DESC LIMIT 20;'
            )                                                     AS 待执行SQL
        FROM INFORMATION_SCHEMA.COLUMNS c
        LEFT JOIN INFORMATION_SCHEMA.TABLES t
               ON t.TABLE_SCHEMA = c.TABLE_SCHEMA AND t.TABLE_NAME = c.TABLE_NAME
        WHERE c.TABLE_SCHEMA = 'ods_mariadb_2b'
          AND c.COLUMN_NAME NOT IN ('__source_pk','source_db','source_table',
                                    'ods_table_name','sync_time')
          AND NOT (   LOWER(c.TABLE_NAME) LIKE '%_bak%'  OR LOWER(c.TABLE_NAME) LIKE '%bak2%'
                   OR LOWER(c.TABLE_NAME) LIKE '%_test%' OR LOWER(c.TABLE_NAME) LIKE '%_tmp%'
                   OR LOWER(c.TABLE_NAME) LIKE '%_old%'  OR LOWER(c.TABLE_NAME) LIKE '%_copy%')
      )
    SELECT q.*,
           -- 一·经济层
           ROUND(e.stake,4) AS stake, ROUND(e.valid,4) AS valid_bet,
           ROUND(-e.net,4) AS profit, e.n_bets, e.n_rounds,
           ROUND(e.net/NULLIF(e.stake,0),8) AS roi,
           ROUND(e.net_in/NULLIF(e.st_in,0),8) AS roi_recent,
           ROUND(e.net_out/NULLIF(e.st_out,0),8) AS roi_non_recent,
           ROUND((e.net-e.rebate)/NULLIF(e.stake,0),8) AS roi_ex_rebate,
           ROUND(e.net,4) AS roi_numerator, ROUND(e.stake,4) AS roi_denominator,
           CASE WHEN e.stake IS NULL THEN 'NULL_DENOM' WHEN e.stake<=0 THEN 'ZERO_DENOM'
                WHEN e.n_bets<30 THEN 'THIN_EXPOSURE' ELSE 'OK' END AS roi_denominator_status,
           ROUND(e.rebate,4) AS rebate_cost, ROUND(e.agent_cost,4)                           AS cost_complement_b,
       ROUND(e.agent_pct,4)                            AS pct_complement,
       ROUND(e.company_retain_pct,4)                   AS pct_top_bet23,
       'AG03-UNRESOLVED'                                     AS agent_formula_version,
      'ALL5_LEVELS_bet23_to_bet27'                    AS agent_level_scope,
      ROUND(e.agent_cost_lv1,4) AS agent_cost_lv1, ROUND(e.agent_cost_lv2,4) AS agent_cost_lv2,
      ROUND(e.agent_cost_lv3,4) AS agent_cost_lv3, ROUND(e.agent_cost_lv4,4) AS agent_cost_lv4,
      ROUND(e.agent_cost_lv5,4) AS agent_cost_lv5,
      ROUND(e.agent_pct_lv1,6) AS agent_pct_lv1, ROUND(e.agent_pct_lv2,6) AS agent_pct_lv2,
      ROUND(e.agent_pct_lv3,6) AS agent_pct_lv3, ROUND(e.agent_pct_lv4,6) AS agent_pct_lv4,
      ROUND(e.agent_pct_lv5,6) AS agent_pct_lv5,
      ROUND(e.retain_pct_lv1,6) AS retain_pct_lv1, ROUND(e.retain_pct_lv2,6) AS retain_pct_lv2,
      ROUND(e.retain_pct_lv3,6) AS retain_pct_lv3, ROUND(e.retain_pct_lv4,6) AS retain_pct_lv4,
      ROUND(e.retain_pct_lv5,6) AS retain_pct_lv5, ROUND(e.chain_depth_avg,4) AS chain_depth_avg,
      ROUND(e.agent_cost_chain_additive,4)            AS agent_cost_chain_additive,
      ROUND(e.agent_cost_chain_nested,4)              AS agent_cost_chain_nested,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_additive,4) AS residual_chain_additive,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_nested,4)   AS residual_chain_nested,
      'PENDING_AG03'                                  AS decision_status,
      'FALSE'                                         AS admit_to_risk_decision,
      'NOT_FOR_ENFORCEMENT'                           AS deliverable_class,
       ROUND(e.agent_cost_a_legacy,4)                  AS agent_cost_a_legacy,
       ROUND(e.agent_cost_valid_base_legacy,4)         AS agent_cost_valid_base_legacy,
           ROUND(-e.net-e.rebate,4)                        AS ngr,
       ROUND(-e.net-e.rebate-e.agent_cost,4)           AS residual_b,
       ROUND(-e.net-e.rebate-e.agent_cost_a_legacy,4)  AS residual_a,
           ROUND((-e.net-e.rebate)/NULLIF(e.stake,0),8)    AS ngr_rate,
       ROUND((-e.net-e.rebate-e.agent_cost)/NULLIF(e.stake,0),8)   AS residual_b_rate,
      -- 【HF9c · canonical accounting contract】
      --   以下 canonical 字段只增加明确 scope；不删除、不覆盖既有字段。
      --   formal_bet23_* 保持 HF9b 当前生产公式及其 NULL/0 语义；
      --   lv1~lv5 / additive / nested 则分别采用各自原始 e.* 成本字段，
      --   rate 一律从未舍入的 e.* 分子 / e.stake 计算，禁止由展示值反算。
      ROUND(e.agent_cost,4) AS agent_cost_bet23_formal_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost,4) AS net_margin_bet23_formal_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost)/NULLIF(e.stake,0),8) AS net_margin_bet23_formal_rate_canonical,
      ROUND(e.agent_cost_lv1,4) AS agent_cost_lv1_bet23_canonical,
      ROUND(e.agent_cost_lv2,4) AS agent_cost_lv2_bet24_canonical,
      ROUND(e.agent_cost_lv3,4) AS agent_cost_lv3_bet25_canonical,
      ROUND(e.agent_cost_lv4,4) AS agent_cost_lv4_bet26_canonical,
      ROUND(e.agent_cost_lv5,4) AS agent_cost_lv5_bet27_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_lv1,4) AS net_margin_lv1_bet23_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_lv1)/NULLIF(e.stake,0),8) AS net_margin_lv1_bet23_rate_canonical,
      ROUND(e.agent_cost_chain_additive,4) AS agent_cost_chain_additive_canonical,
      ROUND(e.agent_cost_chain_nested,4) AS agent_cost_chain_nested_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_additive,4) AS net_margin_chain_additive_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_nested,4) AS net_margin_chain_nested_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_chain_additive)/NULLIF(e.stake,0),8) AS net_margin_chain_additive_rate_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_chain_nested)/NULLIF(e.stake,0),8) AS net_margin_chain_nested_rate_canonical,
       ROUND((-e.net-e.rebate-e.agent_cost_a_legacy)/NULLIF(e.stake,0),8) AS residual_a_rate,
           -- 二·分布层
           ROUND(e.stake/NULLIF(e.n_bets,0),4) AS avg_stake_per_bet,
           ROUND(e.valid/NULLIF(e.n_rounds,0),4) AS avg_valid_bet_per_round,
           ROUND(-e.net/NULLIF(e.n_rounds,0),4) AS avg_profit_per_round,
           ROUND(-e.net/NULLIF(e.active_days,0),4) AS avg_profit_per_day,
           ROUND(-e.net/NULLIF(e.active_shoes,0),4) AS avg_profit_per_shoe,
           ROUND(e.stake/NULLIF(e.active_days,0),4) AS avg_stake_per_active_day,
           ROUND(e.n_rounds*1.0/NULLIF(e.active_days,0),4) AS avg_rounds_per_active_day,
           ROUND(e.st_in/NULLIF(e.nb_in,0),4) AS avg_stake_recent,
           ROUND(e.st_out/NULLIF(e.nb_out,0),4) AS avg_stake_non_recent,
           ROUND(e.p25,4) AS p25_stake, ROUND(e.p50,4) AS p50_stake, ROUND(e.p75,4) AS p75_stake,
           ROUND(e.p90,4) AS p90_stake, ROUND(e.p95,4) AS p95_stake, ROUND(e.p99,4) AS p99_stake,
           ROUND(e.p50_valid,4) AS p50_valid_bet, ROUND(e.p50_profit,4) AS p50_profit,
           ROUND(e.p95/NULLIF(e.p50,0),6) AS p95_over_p50,
           ROUND(e.p99/NULLIF(e.p50,0),6) AS p99_over_p50,
           ROUND((e.stake/NULLIF(e.n_bets,0))/NULLIF(e.p50,0),6) AS avg_over_p50,
           -- 三·关系层
           e.n_tables AS common_table_count, e.n_dealers AS common_dealer_count,
           e.n_ips AS common_ip_count, e.n_products AS common_product_count,
           ROUND(e.st_in/NULLIF(e.stake,0),8) AS share_recent,
           -- 四·rate 层
           ROUND(-e.net/NULLIF(e.stake,0),8) AS hold_rate,
           ROUND(-e.net_in/NULLIF(e.st_in,0),8) AS hold_rate_recent,
           ROUND(e.rebate/NULLIF(e.valid,0),8) AS rebate_rate_actual,
           ROUND(e.rbpct,6) AS rebate_pct_config,
           ROUND(e.valid/NULLIF(e.stake,0),6) AS turnover_multiple,
           ROUND(e.freecomm_rate,6) AS free_comm_rate,
           ROUND(e.net_in/NULLIF(e.st_in,0)-e.net_out/NULLIF(e.st_out,0),8) AS roi_delta_recent,
           -- 五·动态层
           e.first_seen_d AS first_seen, e.last_seen_d AS last_seen,
           e.active_days, e.active_shoes, e.active_sessions,
           DATEDIFF(e.last_seen_d, e.first_seen_d)+1 AS span_days,
           ROUND(e.active_days*1.0/NULLIF(DATEDIFF(e.last_seen_d,e.first_seen_d)+1,0),6) AS persistence,
           ROUND((e.st_in/NULLIF(e.nb_in,0))/NULLIF(e.st_out/NULLIF(e.nb_out,0),0),6) AS ramp_recent_vs_prior,
           ROUND((e.st_rec/NULLIF(e.nb_rec,0))/NULLIF(e.stake/NULLIF(e.n_bets,0),0),6) AS ramp_recent_vs_all,
           ROUND((e.st_rec/NULLIF(e.stake,0))/0.30,6) AS stake_ramp,
           -- 六·决策层（HF9g-P5 · D-14 斧正 —— 本件属【全窗基线族】，相对刻度与决策标签一律 NULL）
           --   病灶：x_win 系全窗单行聚合（无 GROUP BY，恒 1 行，此为设计使然，非缺陷），
           --         经 CROSS JOIN 接入后 e.* 全行同值；六层之 NTILE / PERCENT_RANK 施于常数即退化，
           --         PERCENT_RANK 恒 0 ⇒ action_priority 恒判 A，全件 100% 误标。
           --   ★ 斧正原则：不给 x_win 补 GROUP BY —— 那会改变其「全窗基线」语义，属退化。
           --     正解与 #018 之 G-05／G-06 同治：范围外之行不得接受任何下游评分与决策标签。
           --   ★ 本件之 e.* 仍照常供其它列作全窗基线使用，仅六层相对刻度与决策标签置 NULL。
           CAST(NULL AS INT)                                              AS vip_tier,                        -- 空值取值：全窗基线族无实体可分档，置 NULL（NULL＝不适用，非 0）
           CAST(NULL AS DOUBLE)                                           AS economic_value,                  -- 空值取值：同上，禁以常数百分位冒充经济价值
           CAST(NULL AS DOUBLE)                                           AS roi_pr_global,                   -- 空值取值：同上
           CAST(NULL AS DOUBLE)                                           AS risk_value,                      -- 空值取值：兼容列，同上
           CAST(NULL AS DOUBLE)                                           AS pr_stake,                        -- 空值取值：兼容列，同上
           CAST(NULL AS DOUBLE)                                           AS pr_global,                       -- 空值取值：同上
           CAST(NULL AS DOUBLE)                                           AS pr_qualified,                    -- 空值取值：同上
           'GLOBAL_BASELINE_NO_ENTITY_RANKING'                            AS pr_qualified_population,         -- 字面取值：血统 —— 明示本件为全窗基线族，无实体排序总体
           CAST(NULL AS BIGINT)                                           AS pr_global_population_n,          -- 空值取值：血统 —— 不适用
           CAST(NULL AS BIGINT)                                           AS pr_qualified_population_n,       -- 空值取值：血统 —— 不适用
           'NOT_APPLICABLE_GLOBAL_BASELINE'                               AS pr_calculation_method,           -- 字面取值：血统 —— 算法不适用
           'HF9g-P5'                                                      AS pr_calculation_version,          -- 字面取值：血统 —— 算法版本
           CAST(NULL AS STRING)                                           AS evidence_flag,                   -- 空值取值：证据旗标不适用于全窗基线
           CAST(NULL AS STRING)                                           AS evidence_rate,                   -- 空值取值：同上
           CAST(NULL AS DOUBLE)                                           AS hold_ci_halfwidth_approx,        -- 空值取值：同上
           'X 全窗基线 · 不参与实体赏罚'                                    AS action_priority                  -- 字面取值：★ D-14 斧正 —— 本族恒不入赏罚，取代原 100% 误标之「A」
    FROM q
    CROSS JOIN x_win e
  ) y
) z
-- ── 逐批 WHERE 阶梯（★ 口诀：上界 ＝ 下界 ＋ 100000，两数同进）──
--    本件 T_true 未测，无需先跑 T_true；以 0 / 100000 控制本批返回区间，末批由实际行数 < 100000 判定
--    WHERE z.audit_rn >        0 AND z.audit_rn <=   100000   -- 第 1 批
--    WHERE z.audit_rn >   100000 AND z.audit_rn <=   200000   -- 第 2 批
--    WHERE z.audit_rn >   200000 AND z.audit_rn <=   300000   -- 第 3 批
--    WHERE z.audit_rn >   300000 AND z.audit_rn <=   400000   -- 第 4 批
--    WHERE z.audit_rn >   400000 AND z.audit_rn <=   500000   -- 第 5 批
--    WHERE z.audit_rn >   500000 AND z.audit_rn <=   600000   -- 第 6 批
--    WHERE z.audit_rn >   600000 AND z.audit_rn <=   700000   -- 第 7 批
--    …余批类推。第 k 批：WHERE z.audit_rn > (k-1)*100000 AND z.audit_rn <= k*100000
--    某批返回 < 100000 行即为末批，其后不再取。
--
--    ⚠ 常见误写（务必避开）：只推下界而上界不动 ——
--        WHERE z.audit_rn > 100000 AND z.audit_rn <= 100000   ← 自相矛盾，恒为假，返回空集
--        WHERE z.audit_rn > 200000 AND z.audit_rn <= 100000   ← 同上，空集
--      两个数必须**同时**前进，且始终相差 100000。
--      下界 ＝ 上一批之上界；上界 ＝ 本批之上界。
WHERE z.audit_rn > 0 AND z.audit_rn <= 100000 -- ★ HF9c 本批区间
ORDER BY z.audit_rn;


-- ══════════════════════════════════════════════════════════════════════════════════════════════
-- 117. Z07_probe_bet02.csv   [总包行 743~782 · 原 5 列 ＋六层约 60 列]
--     典型学：Z00 基建/元数据　派生旗标：recent（s.x_rec = 1 · 仅供 CASE 条件聚合，全包无任何 WHERE/AND/HAVING 以此过滤）　连接：全窗基线
-- ══════════════════════════════════════════════════════════════════════════════════════════════
-- ★ W-64 · D-14 警示（本件属 x_win 族 · 66 件之一 · 详见 §Z 段 D-14 全案）
--   本件以 `CROSS JOIN x_win e` 接入全局基线，x_win 无 GROUP BY ⇒ 恒 1 行 ⇒ e.* 全行同值。
--   故：economic_value / roi_pr_global / risk_value / pr_stake / pr_global 恒为 0；
--       action_priority 每一行皆为「A 净亏最大十分位 · 优先复核」（Z 分支永不触发）；
--       evidence_rate 恒为最高档；vip_tier 由常数键分档 ⇒ 无信息且非确定。
--   ⇒ 本件决策层三列 **NOT_FOR_DECISION**，裁定前不得用于排班、抽查或汇报。
-- ── ① 先跑 T_true 留档（不足 100000 者一次导全，不必分批）──
-- ── ① T_true：HF9c 不再强制预跑完整 COUNT。
--    本批实际返回行数 < 100000 即判定为末批；全批完成后以各批 n_rows / audit_rn 范围核对总量。

-- ── ② 分批取数：第 1 批。第 k 批只改末行两数为 (k-1)*100000 与 k*100000 ──
--    审计字段二（REDTEAM 2026-08-24 裁定 · 四锁）：
--      audit_rn  全局观测坐标 —— 由**与原版审计版逐字同一**之排序键所生，两版可逐行对账
--      batch_id  物理分批信息 —— 该行所属批次，由 audit_rn 算得，非引擎所赋
--    ★ 锁三：二者皆为审计字段，**不得进入任何业务指标计算**。
--    ★ 锁四：两版经 audit_rn 逐行字段核验后，方可宣布输出完全一致。

-- ── ③ 每批取回后自证四数（任一不符即停手回报，禁止放行）──
--    n_rows        = COUNT(*)      须等于 COUNT(DISTINCT audit_rn)   （批内无重复）
--    audit_rn_min  = MIN(audit_rn) 须等于 (k-1)*100000 + 1           （与上批严丝合缝）
--    audit_rn_max  = MAX(audit_rn) 须等于 min + n_rows - 1           （批内无缺口）
--    全批取毕再验：各批 audit_rn 之并集 = 1 .. T_true，无缺号、无重号。
--     ★ 首行＝平台真净亏最多者（已扣退水与代理占成）。
--
SELECT z.*,
       CAST(FLOOR((z.audit_rn - 1) / 100000) + 1 AS INT)          AS batch_id,
       'A168_HF9F_20260827_0900' AS run_id,
       '2026-08-27 09:00:00' AS snapshot_sync_time
FROM (
  SELECT y.*,
         ROW_NUMBER() OVER (ORDER BY y.`residual_b` ASC, y.`roi` DESC) AS audit_rn
  FROM (
    WITH
      x_ranked AS (
    SELECT b.bet01, b.bet03, b.bet04, b.bet05, b.bet09, b.bet11, b.bet13,
           b.bet15, b.bet16, b.bet17, b.bet18, b.bet19, b.bet20, b.bet21,
           b.bet22, b.bet23, b.bet24, b.bet25, b.bet26, b.bet27, b.bet38, b.bet39, b.category, b.commission,
           b.dt, b.eid, b.ip, b.validbet, b.updatetime, b.sync_time,
           ROW_NUMBER() OVER (
             PARTITION BY b.bet01
             ORDER BY b.updatetime DESC, b.sync_time DESC, b.dt DESC)      AS x_rn
    FROM ods_mariadb_2b.ods_a168_bet02 b
    WHERE b.dt >= '2026-03-21' AND b.dt < '2026-08-07'
      AND b.bet02 = '101'
      AND b.sync_time <= '2026-08-27 09:00:00'
  ),
    x_testagent AS (
    SELECT age001 AS agent_id FROM ods_mariadb_2b.ods_a168_agent WHERE age022 = '1'
  ),
    x_bs0 AS (
    SELECT b.bet05 AS x_member, b.eid AS x_dealer, b.bet39 AS x_table,
           b.bet03 AS x_shoe, b.ip AS x_ip, b.bet09 AS x_product, b.dt AS x_date,
           CONCAT_WS('|', b.bet03, b.bet04, b.bet39)                      AS x_round,
           CONCAT_WS('|', b.bet39, b.bet03)                               AS x_tblshoe,
           CAST(NULLIF(TRIM(b.bet04),'') AS INT)                          AS x_rno,
           CASE WHEN b.dt >= '2026-07-08' THEN 1 ELSE 0 END               AS x_rec,
           CASE WHEN TRIM(b.commission)='1' THEN 1 ELSE 0 END             AS x_freecomm,
           CAST(NULLIF(TRIM(b.bet13),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_stake,
           CAST(NULLIF(TRIM(b.validbet),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_valid,
           CAST(NULLIF(TRIM(b.bet16),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_rebate,
           CAST(NULLIF(TRIM(b.bet17),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_net,
           CAST(NULLIF(TRIM(b.bet15),'') AS DECIMAL(20,6))                AS x_rbpct,
           COALESCE(CAST(NULLIF(TRIM(b.bet23),'') AS DECIMAL(20,6)),0)   AS x_agpct,
          NULLIF(CAST(NULLIF(TRIM(b.bet23),'') AS DECIMAL(20,6)),0)     AS x_rate1,
          NULLIF(CAST(NULLIF(TRIM(b.bet24),'') AS DECIMAL(20,6)),0)     AS x_rate2,
          NULLIF(CAST(NULLIF(TRIM(b.bet25),'') AS DECIMAL(20,6)),0)     AS x_rate3,
          NULLIF(CAST(NULLIF(TRIM(b.bet26),'') AS DECIMAL(20,6)),0)     AS x_rate4,
          NULLIF(CAST(NULLIF(TRIM(b.bet27),'') AS DECIMAL(20,6)),0)     AS x_rate5,
          (CASE WHEN NULLIF(CAST(NULLIF(TRIM(b.bet22),'') AS BIGINT),0) IS NOT NULL THEN 5
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet21),'') AS BIGINT),0) IS NOT NULL THEN 4
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet20),'') AS BIGINT),0) IS NOT NULL THEN 3
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet19),'') AS BIGINT),0) IS NOT NULL THEN 2
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet18),'') AS BIGINT),0) IS NOT NULL THEN 1
                ELSE 0 END)                                             AS x_chain_depth,
           CASE WHEN COALESCE(t1.agent_id,t2.agent_id,t3.agent_id,
                              t4.agent_id,t5.agent_id) IS NOT NULL
                THEN 1 ELSE 0 END                                        AS f_testline
    FROM x_ranked b
    LEFT JOIN x_testagent t1 ON t1.agent_id = b.bet18
    LEFT JOIN x_testagent t2 ON t2.agent_id = b.bet19
    LEFT JOIN x_testagent t3 ON t3.agent_id = b.bet20
    LEFT JOIN x_testagent t4 ON t4.agent_id = b.bet21
    LEFT JOIN x_testagent t5 ON t5.agent_id = b.bet22
    WHERE b.x_rn = 1
      AND b.category='1' AND UPPER(TRIM(b.bet38))='N'
      AND CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8)) > 0
  ),
  x_mk AS (
    SELECT s.*,
           CASE WHEN s.f_testline = 0 THEN 1 ELSE 0 END                 AS is_clean
    FROM x_bs0 s
  ),
  x_agg AS (
    SELECT s.x_member                                                        AS x_key,
           COUNT(*) AS n_bets, COUNT(DISTINCT s.x_round) AS n_rounds,
           COUNT(DISTINCT s.x_date) AS active_days, COUNT(DISTINCT s.x_tblshoe) AS active_shoes,
           COUNT(DISTINCT CONCAT_WS('|', s.x_date, s.x_table)) AS active_sessions,
           COUNT(DISTINCT s.x_table) AS n_tables, COUNT(DISTINCT s.x_dealer) AS n_dealers,
           COUNT(DISTINCT s.x_ip) AS n_ips, COUNT(DISTINCT s.x_product) AS n_products,
           MIN(s.x_date) AS first_seen_d, MAX(s.x_date) AS last_seen_d,
           SUM(s.x_stake) AS stake, SUM(s.x_valid) AS valid, SUM(s.x_rebate) AS rebate,
           SUM(s.x_net) AS net, SUM(-s.x_net *(100.0-s.x_agpct)/100.0) AS agent_cost,
           AVG(100.0-s.x_agpct)                   AS agent_pct,
           AVG(s.x_agpct)                         AS company_retain_pct,
           SUM(-s.x_net *s.x_agpct/100.0)         AS agent_cost_a_legacy,
           SUM(s.x_valid*s.x_agpct/100.0)         AS agent_cost_valid_base_legacy,
          AVG(COALESCE(s.x_rate1,100)) AS retain_pct_lv1, AVG(COALESCE(s.x_rate2,100)) AS retain_pct_lv2,
          AVG(COALESCE(s.x_rate3,100)) AS retain_pct_lv3, AVG(COALESCE(s.x_rate4,100)) AS retain_pct_lv4,
          AVG(COALESCE(s.x_rate5,100)) AS retain_pct_lv5, AVG(s.x_chain_depth) AS chain_depth_avg,
          AVG(COALESCE(100.0-s.x_rate1,0)) AS agent_pct_lv1, AVG(COALESCE(100.0-s.x_rate2,0)) AS agent_pct_lv2,
          AVG(COALESCE(100.0-s.x_rate3,0)) AS agent_pct_lv3, AVG(COALESCE(100.0-s.x_rate4,0)) AS agent_pct_lv4,
          AVG(COALESCE(100.0-s.x_rate5,0)) AS agent_pct_lv5,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate1,0)/100.0)                        AS agent_cost_lv1,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate2,0)/100.0)                        AS agent_cost_lv2,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate3,0)/100.0)                        AS agent_cost_lv3,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate4,0)/100.0)                        AS agent_cost_lv4,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate5,0)/100.0)                        AS agent_cost_lv5,
          SUM(-s.x_net*(COALESCE(100.0-s.x_rate1,0)+COALESCE(100.0-s.x_rate2,0)
                       +COALESCE(100.0-s.x_rate3,0)+COALESCE(100.0-s.x_rate4,0)
                       +COALESCE(100.0-s.x_rate5,0))/100.0)                   AS agent_cost_chain_additive,
          SUM(-s.x_net*(1.0 - CAST(COALESCE(s.x_rate1,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate2,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate3,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate4,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate5,100) AS DOUBLE)/100.0))
                                                                       AS agent_cost_chain_nested,
           AVG(s.x_rbpct) AS rbpct, AVG(s.x_freecomm*1.0) AS freecomm_rate,
           PERCENTILE_APPROX(s.x_stake,0.25) AS p25, PERCENTILE_APPROX(s.x_stake,0.50) AS p50,
           PERCENTILE_APPROX(s.x_stake,0.75) AS p75, PERCENTILE_APPROX(s.x_stake,0.90) AS p90,
           PERCENTILE_APPROX(s.x_stake,0.95) AS p95, PERCENTILE_APPROX(s.x_stake,0.99) AS p99,
           PERCENTILE_APPROX(s.x_valid,0.50) AS p50_valid,
           PERCENTILE_APPROX(s.x_net,0.50)   AS p50_profit,
           SUM(CASE WHEN s.x_rec = 1 THEN s.x_stake ELSE 0 END) AS st_in,
           SUM(CASE WHEN s.x_rec = 1 THEN 1 ELSE 0 END)         AS nb_in,
           SUM(CASE WHEN s.x_rec = 1 THEN s.x_net ELSE 0 END)   AS net_in,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN s.x_stake ELSE 0 END) AS st_out,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN 1 ELSE 0 END)         AS nb_out,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN s.x_net ELSE 0 END)   AS net_out,
           SUM(CASE WHEN s.x_rec=1 THEN s.x_stake ELSE 0 END) AS st_rec,
           SUM(CASE WHEN s.x_rec=1 THEN 1 ELSE 0 END)         AS nb_rec
    FROM x_mk s
    WHERE s.is_clean = 1
      AND s.x_member IS NOT NULL AND TRIM(CAST(s.x_member AS STRING)) <> ''
    GROUP BY s.x_member
  ),
  x_win AS (
    SELECT            COUNT(*) AS n_bets, COUNT(DISTINCT s.x_round) AS n_rounds,
           COUNT(DISTINCT s.x_date) AS active_days, COUNT(DISTINCT s.x_tblshoe) AS active_shoes,
           COUNT(DISTINCT CONCAT_WS('|', s.x_date, s.x_table)) AS active_sessions,
           COUNT(DISTINCT s.x_table) AS n_tables, COUNT(DISTINCT s.x_dealer) AS n_dealers,
           COUNT(DISTINCT s.x_ip) AS n_ips, COUNT(DISTINCT s.x_product) AS n_products,
           MIN(s.x_date) AS first_seen_d, MAX(s.x_date) AS last_seen_d,
           SUM(s.x_stake) AS stake, SUM(s.x_valid) AS valid, SUM(s.x_rebate) AS rebate,
           SUM(s.x_net) AS net, SUM(-s.x_net *(100.0-s.x_agpct)/100.0) AS agent_cost,
           AVG(100.0-s.x_agpct)                   AS agent_pct,
           AVG(s.x_agpct)                         AS company_retain_pct,
           SUM(-s.x_net *s.x_agpct/100.0)         AS agent_cost_a_legacy,
           SUM(s.x_valid*s.x_agpct/100.0)         AS agent_cost_valid_base_legacy,
          AVG(COALESCE(s.x_rate1,100)) AS retain_pct_lv1, AVG(COALESCE(s.x_rate2,100)) AS retain_pct_lv2,
          AVG(COALESCE(s.x_rate3,100)) AS retain_pct_lv3, AVG(COALESCE(s.x_rate4,100)) AS retain_pct_lv4,
          AVG(COALESCE(s.x_rate5,100)) AS retain_pct_lv5, AVG(s.x_chain_depth) AS chain_depth_avg,
          AVG(COALESCE(100.0-s.x_rate1,0)) AS agent_pct_lv1, AVG(COALESCE(100.0-s.x_rate2,0)) AS agent_pct_lv2,
          AVG(COALESCE(100.0-s.x_rate3,0)) AS agent_pct_lv3, AVG(COALESCE(100.0-s.x_rate4,0)) AS agent_pct_lv4,
          AVG(COALESCE(100.0-s.x_rate5,0)) AS agent_pct_lv5,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate1,0)/100.0)                        AS agent_cost_lv1,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate2,0)/100.0)                        AS agent_cost_lv2,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate3,0)/100.0)                        AS agent_cost_lv3,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate4,0)/100.0)                        AS agent_cost_lv4,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate5,0)/100.0)                        AS agent_cost_lv5,
          SUM(-s.x_net*(COALESCE(100.0-s.x_rate1,0)+COALESCE(100.0-s.x_rate2,0)
                       +COALESCE(100.0-s.x_rate3,0)+COALESCE(100.0-s.x_rate4,0)
                       +COALESCE(100.0-s.x_rate5,0))/100.0)                   AS agent_cost_chain_additive,
          SUM(-s.x_net*(1.0 - CAST(COALESCE(s.x_rate1,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate2,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate3,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate4,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate5,100) AS DOUBLE)/100.0))
                                                                       AS agent_cost_chain_nested,
           AVG(s.x_rbpct) AS rbpct, AVG(s.x_freecomm*1.0) AS freecomm_rate,
           PERCENTILE_APPROX(s.x_stake,0.25) AS p25, PERCENTILE_APPROX(s.x_stake,0.50) AS p50,
           PERCENTILE_APPROX(s.x_stake,0.75) AS p75, PERCENTILE_APPROX(s.x_stake,0.90) AS p90,
           PERCENTILE_APPROX(s.x_stake,0.95) AS p95, PERCENTILE_APPROX(s.x_stake,0.99) AS p99,
           PERCENTILE_APPROX(s.x_valid,0.50) AS p50_valid,
           PERCENTILE_APPROX(s.x_net,0.50)   AS p50_profit,
           SUM(CASE WHEN s.x_rec = 1 THEN s.x_stake ELSE 0 END) AS st_in,
           SUM(CASE WHEN s.x_rec = 1 THEN 1 ELSE 0 END)         AS nb_in,
           SUM(CASE WHEN s.x_rec = 1 THEN s.x_net ELSE 0 END)   AS net_in,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN s.x_stake ELSE 0 END) AS st_out,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN 1 ELSE 0 END)         AS nb_out,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN s.x_net ELSE 0 END)   AS net_out,
           SUM(CASE WHEN s.x_rec=1 THEN s.x_stake ELSE 0 END) AS st_rec,
           SUM(CASE WHEN s.x_rec=1 THEN 1 ELSE 0 END)         AS nb_rec
    FROM x_mk s
    WHERE s.is_clean = 1
      AND s.x_member IS NOT NULL AND TRIM(CAST(s.x_member AS STRING)) <> ''
  ),
      q AS (
        SELECT 'ods_a168_bet02' AS t, 'bet03' AS c, CAST(bet03 AS VARCHAR) AS v,
               COUNT(*) AS n, COUNT(*) * 1.0 / SUM(COUNT(*)) OVER () AS pct
        FROM ods_mariadb_2b.ods_a168_bet02 WHERE sync_time <= '2026-08-27 09:00:00' GROUP BY 3
        UNION ALL
        SELECT 'ods_a168_bet02', 'bet04', CAST(bet04 AS VARCHAR),
               COUNT(*), COUNT(*) * 1.0 / SUM(COUNT(*)) OVER ()
        FROM ods_mariadb_2b.ods_a168_bet02 WHERE sync_time <= '2026-08-27 09:00:00' GROUP BY 3
        UNION ALL
        SELECT 'ods_a168_bet02', 'bet39', CAST(bet39 AS VARCHAR),
               COUNT(*), COUNT(*) * 1.0 / SUM(COUNT(*)) OVER ()
        FROM ods_mariadb_2b.ods_a168_bet02 WHERE sync_time <= '2026-08-27 09:00:00' GROUP BY 3
        UNION ALL
        SELECT 'ods_a168_bet02', 'eid', CAST(eid AS VARCHAR),
               COUNT(*), COUNT(*) * 1.0 / SUM(COUNT(*)) OVER ()
        FROM ods_mariadb_2b.ods_a168_bet02 WHERE sync_time <= '2026-08-27 09:00:00' GROUP BY 3
        UNION ALL
        SELECT 'ods_a168_bet02', 'gametype', CAST(gametype AS VARCHAR),
               COUNT(*), COUNT(*) * 1.0 / SUM(COUNT(*)) OVER ()
        FROM ods_mariadb_2b.ods_a168_bet02 WHERE sync_time <= '2026-08-27 09:00:00' GROUP BY 3
        UNION ALL
        SELECT 'ods_a168_bet02', 'commission', CAST(commission AS VARCHAR),
               COUNT(*), COUNT(*) * 1.0 / SUM(COUNT(*)) OVER ()
        FROM ods_mariadb_2b.ods_a168_bet02 WHERE sync_time <= '2026-08-27 09:00:00' GROUP BY 3
        UNION ALL
        SELECT 'ods_a168_bet02', 'category', CAST(category AS VARCHAR),
               COUNT(*), COUNT(*) * 1.0 / SUM(COUNT(*)) OVER ()
        FROM ods_mariadb_2b.ods_a168_bet02 WHERE sync_time <= '2026-08-27 09:00:00' GROUP BY 3
        UNION ALL
        SELECT 'ods_a168_bet02', 'bet09', CAST(bet09 AS VARCHAR),
               COUNT(*), COUNT(*) * 1.0 / SUM(COUNT(*)) OVER ()
        FROM ods_mariadb_2b.ods_a168_bet02 WHERE sync_time <= '2026-08-27 09:00:00' GROUP BY 3
        UNION ALL
        SELECT 'ods_a168_bet02', 'bet10', CAST(bet10 AS VARCHAR),
               COUNT(*), COUNT(*) * 1.0 / SUM(COUNT(*)) OVER ()
        FROM ods_mariadb_2b.ods_a168_bet02 WHERE sync_time <= '2026-08-27 09:00:00' GROUP BY 3
        UNION ALL
        SELECT 'ods_a168_bet02', 'bet11', CAST(bet11 AS VARCHAR),
               COUNT(*), COUNT(*) * 1.0 / SUM(COUNT(*)) OVER ()
        FROM ods_mariadb_2b.ods_a168_bet02 WHERE sync_time <= '2026-08-27 09:00:00' GROUP BY 3
      )
    SELECT q.*,
           -- 一·经济层
           ROUND(e.stake,4) AS stake, ROUND(e.valid,4) AS valid_bet,
           ROUND(-e.net,4) AS profit, e.n_bets, e.n_rounds,
           ROUND(e.net/NULLIF(e.stake,0),8) AS roi,
           ROUND(e.net_in/NULLIF(e.st_in,0),8) AS roi_recent,
           ROUND(e.net_out/NULLIF(e.st_out,0),8) AS roi_non_recent,
           ROUND((e.net-e.rebate)/NULLIF(e.stake,0),8) AS roi_ex_rebate,
           ROUND(e.net,4) AS roi_numerator, ROUND(e.stake,4) AS roi_denominator,
           CASE WHEN e.stake IS NULL THEN 'NULL_DENOM' WHEN e.stake<=0 THEN 'ZERO_DENOM'
                WHEN e.n_bets<30 THEN 'THIN_EXPOSURE' ELSE 'OK' END AS roi_denominator_status,
           ROUND(e.rebate,4) AS rebate_cost, ROUND(e.agent_cost,4)                           AS cost_complement_b,
       ROUND(e.agent_pct,4)                            AS pct_complement,
       ROUND(e.company_retain_pct,4)                   AS pct_top_bet23,
       'AG03-UNRESOLVED'                                     AS agent_formula_version,
      'ALL5_LEVELS_bet23_to_bet27'                    AS agent_level_scope,
      ROUND(e.agent_cost_lv1,4) AS agent_cost_lv1, ROUND(e.agent_cost_lv2,4) AS agent_cost_lv2,
      ROUND(e.agent_cost_lv3,4) AS agent_cost_lv3, ROUND(e.agent_cost_lv4,4) AS agent_cost_lv4,
      ROUND(e.agent_cost_lv5,4) AS agent_cost_lv5,
      ROUND(e.agent_pct_lv1,6) AS agent_pct_lv1, ROUND(e.agent_pct_lv2,6) AS agent_pct_lv2,
      ROUND(e.agent_pct_lv3,6) AS agent_pct_lv3, ROUND(e.agent_pct_lv4,6) AS agent_pct_lv4,
      ROUND(e.agent_pct_lv5,6) AS agent_pct_lv5,
      ROUND(e.retain_pct_lv1,6) AS retain_pct_lv1, ROUND(e.retain_pct_lv2,6) AS retain_pct_lv2,
      ROUND(e.retain_pct_lv3,6) AS retain_pct_lv3, ROUND(e.retain_pct_lv4,6) AS retain_pct_lv4,
      ROUND(e.retain_pct_lv5,6) AS retain_pct_lv5, ROUND(e.chain_depth_avg,4) AS chain_depth_avg,
      ROUND(e.agent_cost_chain_additive,4)            AS agent_cost_chain_additive,
      ROUND(e.agent_cost_chain_nested,4)              AS agent_cost_chain_nested,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_additive,4) AS residual_chain_additive,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_nested,4)   AS residual_chain_nested,
      'PENDING_AG03'                                  AS decision_status,
      'FALSE'                                         AS admit_to_risk_decision,
      'NOT_FOR_ENFORCEMENT'                           AS deliverable_class,
       ROUND(e.agent_cost_a_legacy,4)                  AS agent_cost_a_legacy,
       ROUND(e.agent_cost_valid_base_legacy,4)         AS agent_cost_valid_base_legacy,
           ROUND(-e.net-e.rebate,4)                        AS ngr,
       ROUND(-e.net-e.rebate-e.agent_cost,4)           AS residual_b,
       ROUND(-e.net-e.rebate-e.agent_cost_a_legacy,4)  AS residual_a,
           ROUND((-e.net-e.rebate)/NULLIF(e.stake,0),8)    AS ngr_rate,
       ROUND((-e.net-e.rebate-e.agent_cost)/NULLIF(e.stake,0),8)   AS residual_b_rate,
      -- 【HF9c · canonical accounting contract】
      --   以下 canonical 字段只增加明确 scope；不删除、不覆盖既有字段。
      --   formal_bet23_* 保持 HF9b 当前生产公式及其 NULL/0 语义；
      --   lv1~lv5 / additive / nested 则分别采用各自原始 e.* 成本字段，
      --   rate 一律从未舍入的 e.* 分子 / e.stake 计算，禁止由展示值反算。
      ROUND(e.agent_cost,4) AS agent_cost_bet23_formal_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost,4) AS net_margin_bet23_formal_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost)/NULLIF(e.stake,0),8) AS net_margin_bet23_formal_rate_canonical,
      ROUND(e.agent_cost_lv1,4) AS agent_cost_lv1_bet23_canonical,
      ROUND(e.agent_cost_lv2,4) AS agent_cost_lv2_bet24_canonical,
      ROUND(e.agent_cost_lv3,4) AS agent_cost_lv3_bet25_canonical,
      ROUND(e.agent_cost_lv4,4) AS agent_cost_lv4_bet26_canonical,
      ROUND(e.agent_cost_lv5,4) AS agent_cost_lv5_bet27_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_lv1,4) AS net_margin_lv1_bet23_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_lv1)/NULLIF(e.stake,0),8) AS net_margin_lv1_bet23_rate_canonical,
      ROUND(e.agent_cost_chain_additive,4) AS agent_cost_chain_additive_canonical,
      ROUND(e.agent_cost_chain_nested,4) AS agent_cost_chain_nested_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_additive,4) AS net_margin_chain_additive_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_nested,4) AS net_margin_chain_nested_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_chain_additive)/NULLIF(e.stake,0),8) AS net_margin_chain_additive_rate_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_chain_nested)/NULLIF(e.stake,0),8) AS net_margin_chain_nested_rate_canonical,
       ROUND((-e.net-e.rebate-e.agent_cost_a_legacy)/NULLIF(e.stake,0),8) AS residual_a_rate,
           -- 二·分布层
           ROUND(e.stake/NULLIF(e.n_bets,0),4) AS avg_stake_per_bet,
           ROUND(e.valid/NULLIF(e.n_rounds,0),4) AS avg_valid_bet_per_round,
           ROUND(-e.net/NULLIF(e.n_rounds,0),4) AS avg_profit_per_round,
           ROUND(-e.net/NULLIF(e.active_days,0),4) AS avg_profit_per_day,
           ROUND(-e.net/NULLIF(e.active_shoes,0),4) AS avg_profit_per_shoe,
           ROUND(e.stake/NULLIF(e.active_days,0),4) AS avg_stake_per_active_day,
           ROUND(e.n_rounds*1.0/NULLIF(e.active_days,0),4) AS avg_rounds_per_active_day,
           ROUND(e.st_in/NULLIF(e.nb_in,0),4) AS avg_stake_recent,
           ROUND(e.st_out/NULLIF(e.nb_out,0),4) AS avg_stake_non_recent,
           ROUND(e.p25,4) AS p25_stake, ROUND(e.p50,4) AS p50_stake, ROUND(e.p75,4) AS p75_stake,
           ROUND(e.p90,4) AS p90_stake, ROUND(e.p95,4) AS p95_stake, ROUND(e.p99,4) AS p99_stake,
           ROUND(e.p50_valid,4) AS p50_valid_bet, ROUND(e.p50_profit,4) AS p50_profit,
           ROUND(e.p95/NULLIF(e.p50,0),6) AS p95_over_p50,
           ROUND(e.p99/NULLIF(e.p50,0),6) AS p99_over_p50,
           ROUND((e.stake/NULLIF(e.n_bets,0))/NULLIF(e.p50,0),6) AS avg_over_p50,
           -- 三·关系层
           e.n_tables AS common_table_count, e.n_dealers AS common_dealer_count,
           e.n_ips AS common_ip_count, e.n_products AS common_product_count,
           ROUND(e.st_in/NULLIF(e.stake,0),8) AS share_recent,
           -- 四·rate 层
           ROUND(-e.net/NULLIF(e.stake,0),8) AS hold_rate,
           ROUND(-e.net_in/NULLIF(e.st_in,0),8) AS hold_rate_recent,
           ROUND(e.rebate/NULLIF(e.valid,0),8) AS rebate_rate_actual,
           ROUND(e.rbpct,6) AS rebate_pct_config,
           ROUND(e.valid/NULLIF(e.stake,0),6) AS turnover_multiple,
           ROUND(e.freecomm_rate,6) AS free_comm_rate,
           ROUND(e.net_in/NULLIF(e.st_in,0)-e.net_out/NULLIF(e.st_out,0),8) AS roi_delta_recent,
           -- 五·动态层
           e.first_seen_d AS first_seen, e.last_seen_d AS last_seen,
           e.active_days, e.active_shoes, e.active_sessions,
           DATEDIFF(e.last_seen_d, e.first_seen_d)+1 AS span_days,
           ROUND(e.active_days*1.0/NULLIF(DATEDIFF(e.last_seen_d,e.first_seen_d)+1,0),6) AS persistence,
           ROUND((e.st_in/NULLIF(e.nb_in,0))/NULLIF(e.st_out/NULLIF(e.nb_out,0),0),6) AS ramp_recent_vs_prior,
           ROUND((e.st_rec/NULLIF(e.nb_rec,0))/NULLIF(e.stake/NULLIF(e.n_bets,0),0),6) AS ramp_recent_vs_all,
           ROUND((e.st_rec/NULLIF(e.stake,0))/0.30,6) AS stake_ramp,
           -- 六·决策层（HF9g-P5 · D-14 斧正 —— 本件属【全窗基线族】，相对刻度与决策标签一律 NULL）
           --   病灶：x_win 系全窗单行聚合（无 GROUP BY，恒 1 行，此为设计使然，非缺陷），
           --         经 CROSS JOIN 接入后 e.* 全行同值；六层之 NTILE / PERCENT_RANK 施于常数即退化，
           --         PERCENT_RANK 恒 0 ⇒ action_priority 恒判 A，全件 100% 误标。
           --   ★ 斧正原则：不给 x_win 补 GROUP BY —— 那会改变其「全窗基线」语义，属退化。
           --     正解与 #018 之 G-05／G-06 同治：范围外之行不得接受任何下游评分与决策标签。
           --   ★ 本件之 e.* 仍照常供其它列作全窗基线使用，仅六层相对刻度与决策标签置 NULL。
           CAST(NULL AS INT)                                              AS vip_tier,                        -- 空值取值：全窗基线族无实体可分档，置 NULL（NULL＝不适用，非 0）
           CAST(NULL AS DOUBLE)                                           AS economic_value,                  -- 空值取值：同上，禁以常数百分位冒充经济价值
           CAST(NULL AS DOUBLE)                                           AS roi_pr_global,                   -- 空值取值：同上
           CAST(NULL AS DOUBLE)                                           AS risk_value,                      -- 空值取值：兼容列，同上
           CAST(NULL AS DOUBLE)                                           AS pr_stake,                        -- 空值取值：兼容列，同上
           CAST(NULL AS DOUBLE)                                           AS pr_global,                       -- 空值取值：同上
           CAST(NULL AS DOUBLE)                                           AS pr_qualified,                    -- 空值取值：同上
           'GLOBAL_BASELINE_NO_ENTITY_RANKING'                            AS pr_qualified_population,         -- 字面取值：血统 —— 明示本件为全窗基线族，无实体排序总体
           CAST(NULL AS BIGINT)                                           AS pr_global_population_n,          -- 空值取值：血统 —— 不适用
           CAST(NULL AS BIGINT)                                           AS pr_qualified_population_n,       -- 空值取值：血统 —— 不适用
           'NOT_APPLICABLE_GLOBAL_BASELINE'                               AS pr_calculation_method,           -- 字面取值：血统 —— 算法不适用
           'HF9g-P5'                                                      AS pr_calculation_version,          -- 字面取值：血统 —— 算法版本
           CAST(NULL AS STRING)                                           AS evidence_flag,                   -- 空值取值：证据旗标不适用于全窗基线
           CAST(NULL AS STRING)                                           AS evidence_rate,                   -- 空值取值：同上
           CAST(NULL AS DOUBLE)                                           AS hold_ci_halfwidth_approx,        -- 空值取值：同上
           'X 全窗基线 · 不参与实体赏罚'                                    AS action_priority                  -- 字面取值：★ D-14 斧正 —— 本族恒不入赏罚，取代原 100% 误标之「A」
    FROM q
    CROSS JOIN x_win e
  ) y
) z
-- ── 逐批 WHERE 阶梯（★ 口诀：上界 ＝ 下界 ＋ 100000，两数同进）──
--    本件 T_true 未测，无需先跑 T_true；以 0 / 100000 控制本批返回区间，末批由实际行数 < 100000 判定
--    WHERE z.audit_rn >        0 AND z.audit_rn <=   100000   -- 第 1 批
--    WHERE z.audit_rn >   100000 AND z.audit_rn <=   200000   -- 第 2 批
--    WHERE z.audit_rn >   200000 AND z.audit_rn <=   300000   -- 第 3 批
--    WHERE z.audit_rn >   300000 AND z.audit_rn <=   400000   -- 第 4 批
--    WHERE z.audit_rn >   400000 AND z.audit_rn <=   500000   -- 第 5 批
--    WHERE z.audit_rn >   500000 AND z.audit_rn <=   600000   -- 第 6 批
--    WHERE z.audit_rn >   600000 AND z.audit_rn <=   700000   -- 第 7 批
--    …余批类推。第 k 批：WHERE z.audit_rn > (k-1)*100000 AND z.audit_rn <= k*100000
--    某批返回 < 100000 行即为末批，其后不再取。
--
--    ⚠ 常见误写（务必避开）：只推下界而上界不动 ——
--        WHERE z.audit_rn > 100000 AND z.audit_rn <= 100000   ← 自相矛盾，恒为假，返回空集
--        WHERE z.audit_rn > 200000 AND z.audit_rn <= 100000   ← 同上，空集
--      两个数必须**同时**前进，且始终相差 100000。
--      下界 ＝ 上一批之上界；上界 ＝ 本批之上界。
WHERE z.audit_rn > 0 AND z.audit_rn <= 100000 -- ★ HF9c 本批区间
ORDER BY z.audit_rn;


-- ══════════════════════════════════════════════════════════════════════════════════════════════
-- 118. Z08_roundkey_integrity.csv   [总包行 796~833 · 原 9 列 ＋六层约 60 列]
--     典型学：Z00 基建/元数据　派生旗标：recent（s.x_rec = 1 · 仅供 CASE 条件聚合，全包无任何 WHERE/AND/HAVING 以此过滤）　连接：全窗基线
-- ══════════════════════════════════════════════════════════════════════════════════════════════
-- ★ W-64 · D-14 警示（本件属 x_win 族 · 66 件之一 · 详见 §Z 段 D-14 全案）
--   本件以 `CROSS JOIN x_win e` 接入全局基线，x_win 无 GROUP BY ⇒ 恒 1 行 ⇒ e.* 全行同值。
--   故：economic_value / roi_pr_global / risk_value / pr_stake / pr_global 恒为 0；
--       action_priority 每一行皆为「A 净亏最大十分位 · 优先复核」（Z 分支永不触发）；
--       evidence_rate 恒为最高档；vip_tier 由常数键分档 ⇒ 无信息且非确定。
--   ⇒ 本件决策层三列 **NOT_FOR_DECISION**，裁定前不得用于排班、抽查或汇报。
-- ── ① 先跑 T_true 留档（不足 100000 者一次导全，不必分批）──
-- ── ① T_true：HF9c 不再强制预跑完整 COUNT。
--    本批实际返回行数 < 100000 即判定为末批；全批完成后以各批 n_rows / audit_rn 范围核对总量。

-- ── ② 分批取数：第 1 批。第 k 批只改末行两数为 (k-1)*100000 与 k*100000 ──
--    审计字段二（REDTEAM 2026-08-24 裁定 · 四锁）：
--      audit_rn  全局观测坐标 —— 由**与原版审计版逐字同一**之排序键所生，两版可逐行对账
--      batch_id  物理分批信息 —— 该行所属批次，由 audit_rn 算得，非引擎所赋
--    ★ 锁三：二者皆为审计字段，**不得进入任何业务指标计算**。
--    ★ 锁四：两版经 audit_rn 逐行字段核验后，方可宣布输出完全一致。

-- ── ③ 每批取回后自证四数（任一不符即停手回报，禁止放行）──
--    n_rows        = COUNT(*)      须等于 COUNT(DISTINCT audit_rn)   （批内无重复）
--    audit_rn_min  = MIN(audit_rn) 须等于 (k-1)*100000 + 1           （与上批严丝合缝）
--    audit_rn_max  = MAX(audit_rn) 须等于 min + n_rows - 1           （批内无缺口）
--    全批取毕再验：各批 audit_rn 之并集 = 1 .. T_true，无缺号、无重号。
--     ★ 首行＝平台真净亏最多者（已扣退水与代理占成）。
--
SELECT z.*,
       CAST(FLOOR((z.audit_rn - 1) / 100000) + 1 AS INT)          AS batch_id,
       'A168_HF9F_20260827_0900' AS run_id,
       '2026-08-27 09:00:00' AS snapshot_sync_time
FROM (
  SELECT y.*,
         ROW_NUMBER() OVER (ORDER BY y.`residual_b` ASC, y.`roi` DESC, y.`注单行数`, y.`局键数`, y.`单局最大注单行数`, y.`单局最大会员数`, y.`单局会员数P999`, y.`跨桌局键数_应为0`, y.`bet03跨桌数`, y.`bet03唯一值数`) AS audit_rn
  FROM (
    WITH
      x_ranked AS (
    SELECT b.bet01, b.bet03, b.bet04, b.bet05, b.bet09, b.bet11, b.bet13,
           b.bet15, b.bet16, b.bet17, b.bet18, b.bet19, b.bet20, b.bet21,
           b.bet22, b.bet23, b.bet24, b.bet25, b.bet26, b.bet27, b.bet38, b.bet39, b.category, b.commission,
           b.dt, b.eid, b.ip, b.validbet, b.updatetime, b.sync_time,
           ROW_NUMBER() OVER (
             PARTITION BY b.bet01
             ORDER BY b.updatetime DESC, b.sync_time DESC, b.dt DESC)      AS x_rn
    FROM ods_mariadb_2b.ods_a168_bet02 b
    WHERE b.dt >= '2026-03-21' AND b.dt < '2026-08-07'
      AND b.bet02 = '101'
      AND b.sync_time <= '2026-08-27 09:00:00'
  ),
    x_testagent AS (
    SELECT age001 AS agent_id FROM ods_mariadb_2b.ods_a168_agent WHERE age022 = '1'
  ),
    x_bs0 AS (
    SELECT b.bet05 AS x_member, b.eid AS x_dealer, b.bet39 AS x_table,
           b.bet03 AS x_shoe, b.ip AS x_ip, b.bet09 AS x_product, b.dt AS x_date,
           CONCAT_WS('|', b.bet03, b.bet04, b.bet39)                      AS x_round,
           CONCAT_WS('|', b.bet39, b.bet03)                               AS x_tblshoe,
           CAST(NULLIF(TRIM(b.bet04),'') AS INT)                          AS x_rno,
           CASE WHEN b.dt >= '2026-07-08' THEN 1 ELSE 0 END               AS x_rec,
           CASE WHEN TRIM(b.commission)='1' THEN 1 ELSE 0 END             AS x_freecomm,
           CAST(NULLIF(TRIM(b.bet13),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_stake,
           CAST(NULLIF(TRIM(b.validbet),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_valid,
           CAST(NULLIF(TRIM(b.bet16),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_rebate,
           CAST(NULLIF(TRIM(b.bet17),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_net,
           CAST(NULLIF(TRIM(b.bet15),'') AS DECIMAL(20,6))                AS x_rbpct,
           COALESCE(CAST(NULLIF(TRIM(b.bet23),'') AS DECIMAL(20,6)),0)   AS x_agpct,
          NULLIF(CAST(NULLIF(TRIM(b.bet23),'') AS DECIMAL(20,6)),0)     AS x_rate1,
          NULLIF(CAST(NULLIF(TRIM(b.bet24),'') AS DECIMAL(20,6)),0)     AS x_rate2,
          NULLIF(CAST(NULLIF(TRIM(b.bet25),'') AS DECIMAL(20,6)),0)     AS x_rate3,
          NULLIF(CAST(NULLIF(TRIM(b.bet26),'') AS DECIMAL(20,6)),0)     AS x_rate4,
          NULLIF(CAST(NULLIF(TRIM(b.bet27),'') AS DECIMAL(20,6)),0)     AS x_rate5,
          (CASE WHEN NULLIF(CAST(NULLIF(TRIM(b.bet22),'') AS BIGINT),0) IS NOT NULL THEN 5
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet21),'') AS BIGINT),0) IS NOT NULL THEN 4
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet20),'') AS BIGINT),0) IS NOT NULL THEN 3
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet19),'') AS BIGINT),0) IS NOT NULL THEN 2
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet18),'') AS BIGINT),0) IS NOT NULL THEN 1
                ELSE 0 END)                                             AS x_chain_depth,
           CASE WHEN COALESCE(t1.agent_id,t2.agent_id,t3.agent_id,
                              t4.agent_id,t5.agent_id) IS NOT NULL
                THEN 1 ELSE 0 END                                        AS f_testline
    FROM x_ranked b
    LEFT JOIN x_testagent t1 ON t1.agent_id = b.bet18
    LEFT JOIN x_testagent t2 ON t2.agent_id = b.bet19
    LEFT JOIN x_testagent t3 ON t3.agent_id = b.bet20
    LEFT JOIN x_testagent t4 ON t4.agent_id = b.bet21
    LEFT JOIN x_testagent t5 ON t5.agent_id = b.bet22
    WHERE b.x_rn = 1
      AND b.category='1' AND UPPER(TRIM(b.bet38))='N'
      AND CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8)) > 0
  ),
  x_mk AS (
    SELECT s.*,
           CASE WHEN s.f_testline = 0 THEN 1 ELSE 0 END                 AS is_clean
    FROM x_bs0 s
  ),
  x_agg AS (
    SELECT s.x_member                                                        AS x_key,
           COUNT(*) AS n_bets, COUNT(DISTINCT s.x_round) AS n_rounds,
           COUNT(DISTINCT s.x_date) AS active_days, COUNT(DISTINCT s.x_tblshoe) AS active_shoes,
           COUNT(DISTINCT CONCAT_WS('|', s.x_date, s.x_table)) AS active_sessions,
           COUNT(DISTINCT s.x_table) AS n_tables, COUNT(DISTINCT s.x_dealer) AS n_dealers,
           COUNT(DISTINCT s.x_ip) AS n_ips, COUNT(DISTINCT s.x_product) AS n_products,
           MIN(s.x_date) AS first_seen_d, MAX(s.x_date) AS last_seen_d,
           SUM(s.x_stake) AS stake, SUM(s.x_valid) AS valid, SUM(s.x_rebate) AS rebate,
           SUM(s.x_net) AS net, SUM(-s.x_net *(100.0-s.x_agpct)/100.0) AS agent_cost,
           AVG(100.0-s.x_agpct)                   AS agent_pct,
           AVG(s.x_agpct)                         AS company_retain_pct,
           SUM(-s.x_net *s.x_agpct/100.0)         AS agent_cost_a_legacy,
           SUM(s.x_valid*s.x_agpct/100.0)         AS agent_cost_valid_base_legacy,
          AVG(COALESCE(s.x_rate1,100)) AS retain_pct_lv1, AVG(COALESCE(s.x_rate2,100)) AS retain_pct_lv2,
          AVG(COALESCE(s.x_rate3,100)) AS retain_pct_lv3, AVG(COALESCE(s.x_rate4,100)) AS retain_pct_lv4,
          AVG(COALESCE(s.x_rate5,100)) AS retain_pct_lv5, AVG(s.x_chain_depth) AS chain_depth_avg,
          AVG(COALESCE(100.0-s.x_rate1,0)) AS agent_pct_lv1, AVG(COALESCE(100.0-s.x_rate2,0)) AS agent_pct_lv2,
          AVG(COALESCE(100.0-s.x_rate3,0)) AS agent_pct_lv3, AVG(COALESCE(100.0-s.x_rate4,0)) AS agent_pct_lv4,
          AVG(COALESCE(100.0-s.x_rate5,0)) AS agent_pct_lv5,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate1,0)/100.0)                        AS agent_cost_lv1,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate2,0)/100.0)                        AS agent_cost_lv2,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate3,0)/100.0)                        AS agent_cost_lv3,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate4,0)/100.0)                        AS agent_cost_lv4,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate5,0)/100.0)                        AS agent_cost_lv5,
          SUM(-s.x_net*(COALESCE(100.0-s.x_rate1,0)+COALESCE(100.0-s.x_rate2,0)
                       +COALESCE(100.0-s.x_rate3,0)+COALESCE(100.0-s.x_rate4,0)
                       +COALESCE(100.0-s.x_rate5,0))/100.0)                   AS agent_cost_chain_additive,
          SUM(-s.x_net*(1.0 - CAST(COALESCE(s.x_rate1,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate2,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate3,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate4,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate5,100) AS DOUBLE)/100.0))
                                                                       AS agent_cost_chain_nested,
           AVG(s.x_rbpct) AS rbpct, AVG(s.x_freecomm*1.0) AS freecomm_rate,
           PERCENTILE_APPROX(s.x_stake,0.25) AS p25, PERCENTILE_APPROX(s.x_stake,0.50) AS p50,
           PERCENTILE_APPROX(s.x_stake,0.75) AS p75, PERCENTILE_APPROX(s.x_stake,0.90) AS p90,
           PERCENTILE_APPROX(s.x_stake,0.95) AS p95, PERCENTILE_APPROX(s.x_stake,0.99) AS p99,
           PERCENTILE_APPROX(s.x_valid,0.50) AS p50_valid,
           PERCENTILE_APPROX(s.x_net,0.50)   AS p50_profit,
           SUM(CASE WHEN s.x_rec = 1 THEN s.x_stake ELSE 0 END) AS st_in,
           SUM(CASE WHEN s.x_rec = 1 THEN 1 ELSE 0 END)         AS nb_in,
           SUM(CASE WHEN s.x_rec = 1 THEN s.x_net ELSE 0 END)   AS net_in,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN s.x_stake ELSE 0 END) AS st_out,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN 1 ELSE 0 END)         AS nb_out,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN s.x_net ELSE 0 END)   AS net_out,
           SUM(CASE WHEN s.x_rec=1 THEN s.x_stake ELSE 0 END) AS st_rec,
           SUM(CASE WHEN s.x_rec=1 THEN 1 ELSE 0 END)         AS nb_rec
    FROM x_mk s
    WHERE s.is_clean = 1
      AND s.x_member IS NOT NULL AND TRIM(CAST(s.x_member AS STRING)) <> ''
    GROUP BY s.x_member
  ),
  x_win AS (
    SELECT            COUNT(*) AS n_bets, COUNT(DISTINCT s.x_round) AS n_rounds,
           COUNT(DISTINCT s.x_date) AS active_days, COUNT(DISTINCT s.x_tblshoe) AS active_shoes,
           COUNT(DISTINCT CONCAT_WS('|', s.x_date, s.x_table)) AS active_sessions,
           COUNT(DISTINCT s.x_table) AS n_tables, COUNT(DISTINCT s.x_dealer) AS n_dealers,
           COUNT(DISTINCT s.x_ip) AS n_ips, COUNT(DISTINCT s.x_product) AS n_products,
           MIN(s.x_date) AS first_seen_d, MAX(s.x_date) AS last_seen_d,
           SUM(s.x_stake) AS stake, SUM(s.x_valid) AS valid, SUM(s.x_rebate) AS rebate,
           SUM(s.x_net) AS net, SUM(-s.x_net *(100.0-s.x_agpct)/100.0) AS agent_cost,
           AVG(100.0-s.x_agpct)                   AS agent_pct,
           AVG(s.x_agpct)                         AS company_retain_pct,
           SUM(-s.x_net *s.x_agpct/100.0)         AS agent_cost_a_legacy,
           SUM(s.x_valid*s.x_agpct/100.0)         AS agent_cost_valid_base_legacy,
          AVG(COALESCE(s.x_rate1,100)) AS retain_pct_lv1, AVG(COALESCE(s.x_rate2,100)) AS retain_pct_lv2,
          AVG(COALESCE(s.x_rate3,100)) AS retain_pct_lv3, AVG(COALESCE(s.x_rate4,100)) AS retain_pct_lv4,
          AVG(COALESCE(s.x_rate5,100)) AS retain_pct_lv5, AVG(s.x_chain_depth) AS chain_depth_avg,
          AVG(COALESCE(100.0-s.x_rate1,0)) AS agent_pct_lv1, AVG(COALESCE(100.0-s.x_rate2,0)) AS agent_pct_lv2,
          AVG(COALESCE(100.0-s.x_rate3,0)) AS agent_pct_lv3, AVG(COALESCE(100.0-s.x_rate4,0)) AS agent_pct_lv4,
          AVG(COALESCE(100.0-s.x_rate5,0)) AS agent_pct_lv5,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate1,0)/100.0)                        AS agent_cost_lv1,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate2,0)/100.0)                        AS agent_cost_lv2,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate3,0)/100.0)                        AS agent_cost_lv3,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate4,0)/100.0)                        AS agent_cost_lv4,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate5,0)/100.0)                        AS agent_cost_lv5,
          SUM(-s.x_net*(COALESCE(100.0-s.x_rate1,0)+COALESCE(100.0-s.x_rate2,0)
                       +COALESCE(100.0-s.x_rate3,0)+COALESCE(100.0-s.x_rate4,0)
                       +COALESCE(100.0-s.x_rate5,0))/100.0)                   AS agent_cost_chain_additive,
          SUM(-s.x_net*(1.0 - CAST(COALESCE(s.x_rate1,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate2,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate3,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate4,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate5,100) AS DOUBLE)/100.0))
                                                                       AS agent_cost_chain_nested,
           AVG(s.x_rbpct) AS rbpct, AVG(s.x_freecomm*1.0) AS freecomm_rate,
           PERCENTILE_APPROX(s.x_stake,0.25) AS p25, PERCENTILE_APPROX(s.x_stake,0.50) AS p50,
           PERCENTILE_APPROX(s.x_stake,0.75) AS p75, PERCENTILE_APPROX(s.x_stake,0.90) AS p90,
           PERCENTILE_APPROX(s.x_stake,0.95) AS p95, PERCENTILE_APPROX(s.x_stake,0.99) AS p99,
           PERCENTILE_APPROX(s.x_valid,0.50) AS p50_valid,
           PERCENTILE_APPROX(s.x_net,0.50)   AS p50_profit,
           SUM(CASE WHEN s.x_rec = 1 THEN s.x_stake ELSE 0 END) AS st_in,
           SUM(CASE WHEN s.x_rec = 1 THEN 1 ELSE 0 END)         AS nb_in,
           SUM(CASE WHEN s.x_rec = 1 THEN s.x_net ELSE 0 END)   AS net_in,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN s.x_stake ELSE 0 END) AS st_out,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN 1 ELSE 0 END)         AS nb_out,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN s.x_net ELSE 0 END)   AS net_out,
           SUM(CASE WHEN s.x_rec=1 THEN s.x_stake ELSE 0 END) AS st_rec,
           SUM(CASE WHEN s.x_rec=1 THEN 1 ELSE 0 END)         AS nb_rec
    FROM x_mk s
    WHERE s.is_clean = 1
      AND s.x_member IS NOT NULL AND TRIM(CAST(s.x_member AS STRING)) <> ''
  ),
      q AS (
        WITH v AS (
          SELECT
              CAST(bet03 AS VARCHAR) AS k3,
              CAST(bet04 AS VARCHAR) AS k4,
              CAST(bet39 AS VARCHAR) AS k39,
              CAST(bet05 AS VARCHAR) AS member_id,
              CONCAT_WS('|', CAST(bet03 AS VARCHAR),
                             CAST(bet04 AS VARCHAR),
                             CAST(bet39 AS VARCHAR)) AS round_key
          FROM ods_mariadb_2b.ods_a168_bet02
          WHERE bet02 = '101'
        AND sync_time <= '2026-08-27 09:00:00'
        ),
        per_key AS (
          SELECT round_key,
                 COUNT(*)                  AS n_rows,
                 COUNT(DISTINCT member_id) AS n_member,
                 COUNT(DISTINCT k39)       AS n_table
          FROM v GROUP BY round_key
        ),
        per_k3 AS (
          SELECT k3, COUNT(DISTINCT k39) AS n_table_per_k3,
                     COUNT(DISTINCT k4)  AS n_k4_per_k3
          FROM v GROUP BY k3
        )
        SELECT
            (SELECT COUNT(*) FROM v)                                            AS 注单行数,
            (SELECT COUNT(*) FROM per_key)                                      AS 局键数,
            (SELECT MAX(n_rows)   FROM per_key)                                 AS 单局最大注单行数,
            (SELECT MAX(n_member) FROM per_key)                                 AS 单局最大会员数,
            (SELECT PERCENTILE_APPROX(CAST(n_member AS DOUBLE),0.999) FROM per_key)
                                                                                AS 单局会员数P999,
            (SELECT COUNT(*) FROM per_key WHERE n_table > 1)                    AS 跨桌局键数_应为0,
            (SELECT COUNT(*) FROM per_k3 WHERE n_table_per_k3 > 1)              AS bet03跨桌数,
            (SELECT COUNT(*) FROM per_k3)                                       AS bet03唯一值数,
            (SELECT SUM(CASE WHEN k3 IN ('-1','0','') OR k3 IS NULL
                               OR k4 IN ('-1','0','') OR k4 IS NULL
                               OR k39 IN ('-1','0','') OR k39 IS NULL
                             THEN 1 ELSE 0 END) FROM v)                         AS 局键含哨兵值行数
      )
    SELECT q.*,
           -- 一·经济层
           ROUND(e.stake,4) AS stake, ROUND(e.valid,4) AS valid_bet,
           ROUND(-e.net,4) AS profit, e.n_bets, e.n_rounds,
           ROUND(e.net/NULLIF(e.stake,0),8) AS roi,
           ROUND(e.net_in/NULLIF(e.st_in,0),8) AS roi_recent,
           ROUND(e.net_out/NULLIF(e.st_out,0),8) AS roi_non_recent,
           ROUND((e.net-e.rebate)/NULLIF(e.stake,0),8) AS roi_ex_rebate,
           ROUND(e.net,4) AS roi_numerator, ROUND(e.stake,4) AS roi_denominator,
           CASE WHEN e.stake IS NULL THEN 'NULL_DENOM' WHEN e.stake<=0 THEN 'ZERO_DENOM'
                WHEN e.n_bets<30 THEN 'THIN_EXPOSURE' ELSE 'OK' END AS roi_denominator_status,
           ROUND(e.rebate,4) AS rebate_cost, ROUND(e.agent_cost,4)                           AS cost_complement_b,
       ROUND(e.agent_pct,4)                            AS pct_complement,
       ROUND(e.company_retain_pct,4)                   AS pct_top_bet23,
       'AG03-UNRESOLVED'                                     AS agent_formula_version,
      'ALL5_LEVELS_bet23_to_bet27'                    AS agent_level_scope,
      ROUND(e.agent_cost_lv1,4) AS agent_cost_lv1, ROUND(e.agent_cost_lv2,4) AS agent_cost_lv2,
      ROUND(e.agent_cost_lv3,4) AS agent_cost_lv3, ROUND(e.agent_cost_lv4,4) AS agent_cost_lv4,
      ROUND(e.agent_cost_lv5,4) AS agent_cost_lv5,
      ROUND(e.agent_pct_lv1,6) AS agent_pct_lv1, ROUND(e.agent_pct_lv2,6) AS agent_pct_lv2,
      ROUND(e.agent_pct_lv3,6) AS agent_pct_lv3, ROUND(e.agent_pct_lv4,6) AS agent_pct_lv4,
      ROUND(e.agent_pct_lv5,6) AS agent_pct_lv5,
      ROUND(e.retain_pct_lv1,6) AS retain_pct_lv1, ROUND(e.retain_pct_lv2,6) AS retain_pct_lv2,
      ROUND(e.retain_pct_lv3,6) AS retain_pct_lv3, ROUND(e.retain_pct_lv4,6) AS retain_pct_lv4,
      ROUND(e.retain_pct_lv5,6) AS retain_pct_lv5, ROUND(e.chain_depth_avg,4) AS chain_depth_avg,
      ROUND(e.agent_cost_chain_additive,4)            AS agent_cost_chain_additive,
      ROUND(e.agent_cost_chain_nested,4)              AS agent_cost_chain_nested,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_additive,4) AS residual_chain_additive,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_nested,4)   AS residual_chain_nested,
      'PENDING_AG03'                                  AS decision_status,
      'FALSE'                                         AS admit_to_risk_decision,
      'NOT_FOR_ENFORCEMENT'                           AS deliverable_class,
       ROUND(e.agent_cost_a_legacy,4)                  AS agent_cost_a_legacy,
       ROUND(e.agent_cost_valid_base_legacy,4)         AS agent_cost_valid_base_legacy,
           ROUND(-e.net-e.rebate,4)                        AS ngr,
       ROUND(-e.net-e.rebate-e.agent_cost,4)           AS residual_b,
       ROUND(-e.net-e.rebate-e.agent_cost_a_legacy,4)  AS residual_a,
           ROUND((-e.net-e.rebate)/NULLIF(e.stake,0),8)    AS ngr_rate,
       ROUND((-e.net-e.rebate-e.agent_cost)/NULLIF(e.stake,0),8)   AS residual_b_rate,
      -- 【HF9c · canonical accounting contract】
      --   以下 canonical 字段只增加明确 scope；不删除、不覆盖既有字段。
      --   formal_bet23_* 保持 HF9b 当前生产公式及其 NULL/0 语义；
      --   lv1~lv5 / additive / nested 则分别采用各自原始 e.* 成本字段，
      --   rate 一律从未舍入的 e.* 分子 / e.stake 计算，禁止由展示值反算。
      ROUND(e.agent_cost,4) AS agent_cost_bet23_formal_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost,4) AS net_margin_bet23_formal_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost)/NULLIF(e.stake,0),8) AS net_margin_bet23_formal_rate_canonical,
      ROUND(e.agent_cost_lv1,4) AS agent_cost_lv1_bet23_canonical,
      ROUND(e.agent_cost_lv2,4) AS agent_cost_lv2_bet24_canonical,
      ROUND(e.agent_cost_lv3,4) AS agent_cost_lv3_bet25_canonical,
      ROUND(e.agent_cost_lv4,4) AS agent_cost_lv4_bet26_canonical,
      ROUND(e.agent_cost_lv5,4) AS agent_cost_lv5_bet27_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_lv1,4) AS net_margin_lv1_bet23_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_lv1)/NULLIF(e.stake,0),8) AS net_margin_lv1_bet23_rate_canonical,
      ROUND(e.agent_cost_chain_additive,4) AS agent_cost_chain_additive_canonical,
      ROUND(e.agent_cost_chain_nested,4) AS agent_cost_chain_nested_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_additive,4) AS net_margin_chain_additive_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_nested,4) AS net_margin_chain_nested_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_chain_additive)/NULLIF(e.stake,0),8) AS net_margin_chain_additive_rate_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_chain_nested)/NULLIF(e.stake,0),8) AS net_margin_chain_nested_rate_canonical,
       ROUND((-e.net-e.rebate-e.agent_cost_a_legacy)/NULLIF(e.stake,0),8) AS residual_a_rate,
           -- 二·分布层
           ROUND(e.stake/NULLIF(e.n_bets,0),4) AS avg_stake_per_bet,
           ROUND(e.valid/NULLIF(e.n_rounds,0),4) AS avg_valid_bet_per_round,
           ROUND(-e.net/NULLIF(e.n_rounds,0),4) AS avg_profit_per_round,
           ROUND(-e.net/NULLIF(e.active_days,0),4) AS avg_profit_per_day,
           ROUND(-e.net/NULLIF(e.active_shoes,0),4) AS avg_profit_per_shoe,
           ROUND(e.stake/NULLIF(e.active_days,0),4) AS avg_stake_per_active_day,
           ROUND(e.n_rounds*1.0/NULLIF(e.active_days,0),4) AS avg_rounds_per_active_day,
           ROUND(e.st_in/NULLIF(e.nb_in,0),4) AS avg_stake_recent,
           ROUND(e.st_out/NULLIF(e.nb_out,0),4) AS avg_stake_non_recent,
           ROUND(e.p25,4) AS p25_stake, ROUND(e.p50,4) AS p50_stake, ROUND(e.p75,4) AS p75_stake,
           ROUND(e.p90,4) AS p90_stake, ROUND(e.p95,4) AS p95_stake, ROUND(e.p99,4) AS p99_stake,
           ROUND(e.p50_valid,4) AS p50_valid_bet, ROUND(e.p50_profit,4) AS p50_profit,
           ROUND(e.p95/NULLIF(e.p50,0),6) AS p95_over_p50,
           ROUND(e.p99/NULLIF(e.p50,0),6) AS p99_over_p50,
           ROUND((e.stake/NULLIF(e.n_bets,0))/NULLIF(e.p50,0),6) AS avg_over_p50,
           -- 三·关系层
           e.n_tables AS common_table_count, e.n_dealers AS common_dealer_count,
           e.n_ips AS common_ip_count, e.n_products AS common_product_count,
           ROUND(e.st_in/NULLIF(e.stake,0),8) AS share_recent,
           -- 四·rate 层
           ROUND(-e.net/NULLIF(e.stake,0),8) AS hold_rate,
           ROUND(-e.net_in/NULLIF(e.st_in,0),8) AS hold_rate_recent,
           ROUND(e.rebate/NULLIF(e.valid,0),8) AS rebate_rate_actual,
           ROUND(e.rbpct,6) AS rebate_pct_config,
           ROUND(e.valid/NULLIF(e.stake,0),6) AS turnover_multiple,
           ROUND(e.freecomm_rate,6) AS free_comm_rate,
           ROUND(e.net_in/NULLIF(e.st_in,0)-e.net_out/NULLIF(e.st_out,0),8) AS roi_delta_recent,
           -- 五·动态层
           e.first_seen_d AS first_seen, e.last_seen_d AS last_seen,
           e.active_days, e.active_shoes, e.active_sessions,
           DATEDIFF(e.last_seen_d, e.first_seen_d)+1 AS span_days,
           ROUND(e.active_days*1.0/NULLIF(DATEDIFF(e.last_seen_d,e.first_seen_d)+1,0),6) AS persistence,
           ROUND((e.st_in/NULLIF(e.nb_in,0))/NULLIF(e.st_out/NULLIF(e.nb_out,0),0),6) AS ramp_recent_vs_prior,
           ROUND((e.st_rec/NULLIF(e.nb_rec,0))/NULLIF(e.stake/NULLIF(e.n_bets,0),0),6) AS ramp_recent_vs_all,
           ROUND((e.st_rec/NULLIF(e.stake,0))/0.30,6) AS stake_ramp,
           -- 六·决策层（HF9g-P5 · D-14 斧正 —— 本件属【全窗基线族】，相对刻度与决策标签一律 NULL）
           --   病灶：x_win 系全窗单行聚合（无 GROUP BY，恒 1 行，此为设计使然，非缺陷），
           --         经 CROSS JOIN 接入后 e.* 全行同值；六层之 NTILE / PERCENT_RANK 施于常数即退化，
           --         PERCENT_RANK 恒 0 ⇒ action_priority 恒判 A，全件 100% 误标。
           --   ★ 斧正原则：不给 x_win 补 GROUP BY —— 那会改变其「全窗基线」语义，属退化。
           --     正解与 #018 之 G-05／G-06 同治：范围外之行不得接受任何下游评分与决策标签。
           --   ★ 本件之 e.* 仍照常供其它列作全窗基线使用，仅六层相对刻度与决策标签置 NULL。
           CAST(NULL AS INT)                                              AS vip_tier,                        -- 空值取值：全窗基线族无实体可分档，置 NULL（NULL＝不适用，非 0）
           CAST(NULL AS DOUBLE)                                           AS economic_value,                  -- 空值取值：同上，禁以常数百分位冒充经济价值
           CAST(NULL AS DOUBLE)                                           AS roi_pr_global,                   -- 空值取值：同上
           CAST(NULL AS DOUBLE)                                           AS risk_value,                      -- 空值取值：兼容列，同上
           CAST(NULL AS DOUBLE)                                           AS pr_stake,                        -- 空值取值：兼容列，同上
           CAST(NULL AS DOUBLE)                                           AS pr_global,                       -- 空值取值：同上
           CAST(NULL AS DOUBLE)                                           AS pr_qualified,                    -- 空值取值：同上
           'GLOBAL_BASELINE_NO_ENTITY_RANKING'                            AS pr_qualified_population,         -- 字面取值：血统 —— 明示本件为全窗基线族，无实体排序总体
           CAST(NULL AS BIGINT)                                           AS pr_global_population_n,          -- 空值取值：血统 —— 不适用
           CAST(NULL AS BIGINT)                                           AS pr_qualified_population_n,       -- 空值取值：血统 —— 不适用
           'NOT_APPLICABLE_GLOBAL_BASELINE'                               AS pr_calculation_method,           -- 字面取值：血统 —— 算法不适用
           'HF9g-P5'                                                      AS pr_calculation_version,          -- 字面取值：血统 —— 算法版本
           CAST(NULL AS STRING)                                           AS evidence_flag,                   -- 空值取值：证据旗标不适用于全窗基线
           CAST(NULL AS STRING)                                           AS evidence_rate,                   -- 空值取值：同上
           CAST(NULL AS DOUBLE)                                           AS hold_ci_halfwidth_approx,        -- 空值取值：同上
           'X 全窗基线 · 不参与实体赏罚'                                    AS action_priority                  -- 字面取值：★ D-14 斧正 —— 本族恒不入赏罚，取代原 100% 误标之「A」
    FROM q
    CROSS JOIN x_win e
  ) y
) z
-- ── 逐批 WHERE 阶梯（★ 口诀：上界 ＝ 下界 ＋ 100000，两数同进）──
--    本件 T_true 未测，无需先跑 T_true；以 0 / 100000 控制本批返回区间，末批由实际行数 < 100000 判定
--    WHERE z.audit_rn >        0 AND z.audit_rn <=   100000   -- 第 1 批
--    WHERE z.audit_rn >   100000 AND z.audit_rn <=   200000   -- 第 2 批
--    WHERE z.audit_rn >   200000 AND z.audit_rn <=   300000   -- 第 3 批
--    WHERE z.audit_rn >   300000 AND z.audit_rn <=   400000   -- 第 4 批
--    WHERE z.audit_rn >   400000 AND z.audit_rn <=   500000   -- 第 5 批
--    WHERE z.audit_rn >   500000 AND z.audit_rn <=   600000   -- 第 6 批
--    WHERE z.audit_rn >   600000 AND z.audit_rn <=   700000   -- 第 7 批
--    …余批类推。第 k 批：WHERE z.audit_rn > (k-1)*100000 AND z.audit_rn <= k*100000
--    某批返回 < 100000 行即为末批，其后不再取。
--
--    ⚠ 常见误写（务必避开）：只推下界而上界不动 ——
--        WHERE z.audit_rn > 100000 AND z.audit_rn <= 100000   ← 自相矛盾，恒为假，返回空集
--        WHERE z.audit_rn > 200000 AND z.audit_rn <= 100000   ← 同上，空集
--      两个数必须**同时**前进，且始终相差 100000。
--      下界 ＝ 上一批之上界；上界 ＝ 本批之上界。
WHERE z.audit_rn > 0 AND z.audit_rn <= 100000 -- ★ HF9c 本批区间
ORDER BY z.audit_rn;


-- ══════════════════════════════════════════════════════════════════════════════════════════════
-- 119. Z09_time_axis_recon.csv   [总包行 854~885 · 原 17 列 ＋六层约 60 列]
--     典型学：Z00 基建/元数据　派生旗标：recent（s.x_rec = 1 · 仅供 CASE 条件聚合，全包无任何 WHERE/AND/HAVING 以此过滤）　连接：全窗基线
-- ══════════════════════════════════════════════════════════════════════════════════════════════
-- ★ W-64 · D-14 警示（本件属 x_win 族 · 66 件之一 · 详见 §Z 段 D-14 全案）
--   本件以 `CROSS JOIN x_win e` 接入全局基线，x_win 无 GROUP BY ⇒ 恒 1 行 ⇒ e.* 全行同值。
--   故：economic_value / roi_pr_global / risk_value / pr_stake / pr_global 恒为 0；
--       action_priority 每一行皆为「A 净亏最大十分位 · 优先复核」（Z 分支永不触发）；
--       evidence_rate 恒为最高档；vip_tier 由常数键分档 ⇒ 无信息且非确定。
--   ⇒ 本件决策层三列 **NOT_FOR_DECISION**，裁定前不得用于排班、抽查或汇报。
-- ── ① 先跑 T_true 留档（不足 100000 者一次导全，不必分批）──
-- ── ① T_true：HF9c 不再强制预跑完整 COUNT。
--    本批实际返回行数 < 100000 即判定为末批；全批完成后以各批 n_rows / audit_rn 范围核对总量。

-- ── ② 分批取数：第 1 批。第 k 批只改末行两数为 (k-1)*100000 与 k*100000 ──
--    审计字段二（REDTEAM 2026-08-24 裁定 · 四锁）：
--      audit_rn  全局观测坐标 —— 由**与原版审计版逐字同一**之排序键所生，两版可逐行对账
--      batch_id  物理分批信息 —— 该行所属批次，由 audit_rn 算得，非引擎所赋
--    ★ 锁三：二者皆为审计字段，**不得进入任何业务指标计算**。
--    ★ 锁四：两版经 audit_rn 逐行字段核验后，方可宣布输出完全一致。

-- ── ③ 每批取回后自证四数（任一不符即停手回报，禁止放行）──
--    n_rows        = COUNT(*)      须等于 COUNT(DISTINCT audit_rn)   （批内无重复）
--    audit_rn_min  = MIN(audit_rn) 须等于 (k-1)*100000 + 1           （与上批严丝合缝）
--    audit_rn_max  = MAX(audit_rn) 须等于 min + n_rows - 1           （批内无缺口）
--    全批取毕再验：各批 audit_rn 之并集 = 1 .. T_true，无缺号、无重号。
--     ★ 首行＝平台真净亏最多者（已扣退水与代理占成）。
--
SELECT z.*,
       CAST(FLOOR((z.audit_rn - 1) / 100000) + 1 AS INT)          AS batch_id,
       'A168_HF9F_20260827_0900' AS run_id,
       '2026-08-27 09:00:00' AS snapshot_sync_time
FROM (
  SELECT y.*,
         ROW_NUMBER() OVER (ORDER BY y.`residual_b` ASC, y.`roi` DESC, y.`行数`, y.`dt等于账务日`, y.`dt等于下注日`, y.`账务日等于下注日`, y.`账务日不可用`, y.`开局时间不可用`, y.`下注时间不可用`, y.`下注时间纪元哨兵`, y.`开局时间纪元哨兵`, y.`账务日最小`, y.`账务日最大`, y.`下注早于开局_时序异常`, y.`下注距开局秒_最小`, y.`下注距开局秒_P50`, y.`下注距开局秒_P99`, y.`下注距开局秒_P999`, y.`下注距开局秒_最大`) AS audit_rn
  FROM (
    WITH
      x_ranked AS (
    SELECT b.bet01, b.bet03, b.bet04, b.bet05, b.bet09, b.bet11, b.bet13,
           b.bet15, b.bet16, b.bet17, b.bet18, b.bet19, b.bet20, b.bet21,
           b.bet22, b.bet23, b.bet24, b.bet25, b.bet26, b.bet27, b.bet38, b.bet39, b.category, b.commission,
           b.dt, b.eid, b.ip, b.validbet, b.updatetime, b.sync_time,
           ROW_NUMBER() OVER (
             PARTITION BY b.bet01
             ORDER BY b.updatetime DESC, b.sync_time DESC, b.dt DESC)      AS x_rn
    FROM ods_mariadb_2b.ods_a168_bet02 b
    WHERE b.dt >= '2026-03-21' AND b.dt < '2026-08-07'
      AND b.bet02 = '101'
      AND b.sync_time <= '2026-08-27 09:00:00'
  ),
    x_testagent AS (
    SELECT age001 AS agent_id FROM ods_mariadb_2b.ods_a168_agent WHERE age022 = '1'
  ),
    x_bs0 AS (
    SELECT b.bet05 AS x_member, b.eid AS x_dealer, b.bet39 AS x_table,
           b.bet03 AS x_shoe, b.ip AS x_ip, b.bet09 AS x_product, b.dt AS x_date,
           CONCAT_WS('|', b.bet03, b.bet04, b.bet39)                      AS x_round,
           CONCAT_WS('|', b.bet39, b.bet03)                               AS x_tblshoe,
           CAST(NULLIF(TRIM(b.bet04),'') AS INT)                          AS x_rno,
           CASE WHEN b.dt >= '2026-07-08' THEN 1 ELSE 0 END               AS x_rec,
           CASE WHEN TRIM(b.commission)='1' THEN 1 ELSE 0 END             AS x_freecomm,
           CAST(NULLIF(TRIM(b.bet13),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_stake,
           CAST(NULLIF(TRIM(b.validbet),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_valid,
           CAST(NULLIF(TRIM(b.bet16),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_rebate,
           CAST(NULLIF(TRIM(b.bet17),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_net,
           CAST(NULLIF(TRIM(b.bet15),'') AS DECIMAL(20,6))                AS x_rbpct,
           COALESCE(CAST(NULLIF(TRIM(b.bet23),'') AS DECIMAL(20,6)),0)   AS x_agpct,
          NULLIF(CAST(NULLIF(TRIM(b.bet23),'') AS DECIMAL(20,6)),0)     AS x_rate1,
          NULLIF(CAST(NULLIF(TRIM(b.bet24),'') AS DECIMAL(20,6)),0)     AS x_rate2,
          NULLIF(CAST(NULLIF(TRIM(b.bet25),'') AS DECIMAL(20,6)),0)     AS x_rate3,
          NULLIF(CAST(NULLIF(TRIM(b.bet26),'') AS DECIMAL(20,6)),0)     AS x_rate4,
          NULLIF(CAST(NULLIF(TRIM(b.bet27),'') AS DECIMAL(20,6)),0)     AS x_rate5,
          (CASE WHEN NULLIF(CAST(NULLIF(TRIM(b.bet22),'') AS BIGINT),0) IS NOT NULL THEN 5
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet21),'') AS BIGINT),0) IS NOT NULL THEN 4
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet20),'') AS BIGINT),0) IS NOT NULL THEN 3
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet19),'') AS BIGINT),0) IS NOT NULL THEN 2
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet18),'') AS BIGINT),0) IS NOT NULL THEN 1
                ELSE 0 END)                                             AS x_chain_depth,
           CASE WHEN COALESCE(t1.agent_id,t2.agent_id,t3.agent_id,
                              t4.agent_id,t5.agent_id) IS NOT NULL
                THEN 1 ELSE 0 END                                        AS f_testline
    FROM x_ranked b
    LEFT JOIN x_testagent t1 ON t1.agent_id = b.bet18
    LEFT JOIN x_testagent t2 ON t2.agent_id = b.bet19
    LEFT JOIN x_testagent t3 ON t3.agent_id = b.bet20
    LEFT JOIN x_testagent t4 ON t4.agent_id = b.bet21
    LEFT JOIN x_testagent t5 ON t5.agent_id = b.bet22
    WHERE b.x_rn = 1
      AND b.category='1' AND UPPER(TRIM(b.bet38))='N'
      AND CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8)) > 0
  ),
  x_mk AS (
    SELECT s.*,
           CASE WHEN s.f_testline = 0 THEN 1 ELSE 0 END                 AS is_clean
    FROM x_bs0 s
  ),
  x_agg AS (
    SELECT s.x_member                                                        AS x_key,
           COUNT(*) AS n_bets, COUNT(DISTINCT s.x_round) AS n_rounds,
           COUNT(DISTINCT s.x_date) AS active_days, COUNT(DISTINCT s.x_tblshoe) AS active_shoes,
           COUNT(DISTINCT CONCAT_WS('|', s.x_date, s.x_table)) AS active_sessions,
           COUNT(DISTINCT s.x_table) AS n_tables, COUNT(DISTINCT s.x_dealer) AS n_dealers,
           COUNT(DISTINCT s.x_ip) AS n_ips, COUNT(DISTINCT s.x_product) AS n_products,
           MIN(s.x_date) AS first_seen_d, MAX(s.x_date) AS last_seen_d,
           SUM(s.x_stake) AS stake, SUM(s.x_valid) AS valid, SUM(s.x_rebate) AS rebate,
           SUM(s.x_net) AS net, SUM(-s.x_net *(100.0-s.x_agpct)/100.0) AS agent_cost,
           AVG(100.0-s.x_agpct)                   AS agent_pct,
           AVG(s.x_agpct)                         AS company_retain_pct,
           SUM(-s.x_net *s.x_agpct/100.0)         AS agent_cost_a_legacy,
           SUM(s.x_valid*s.x_agpct/100.0)         AS agent_cost_valid_base_legacy,
          AVG(COALESCE(s.x_rate1,100)) AS retain_pct_lv1, AVG(COALESCE(s.x_rate2,100)) AS retain_pct_lv2,
          AVG(COALESCE(s.x_rate3,100)) AS retain_pct_lv3, AVG(COALESCE(s.x_rate4,100)) AS retain_pct_lv4,
          AVG(COALESCE(s.x_rate5,100)) AS retain_pct_lv5, AVG(s.x_chain_depth) AS chain_depth_avg,
          AVG(COALESCE(100.0-s.x_rate1,0)) AS agent_pct_lv1, AVG(COALESCE(100.0-s.x_rate2,0)) AS agent_pct_lv2,
          AVG(COALESCE(100.0-s.x_rate3,0)) AS agent_pct_lv3, AVG(COALESCE(100.0-s.x_rate4,0)) AS agent_pct_lv4,
          AVG(COALESCE(100.0-s.x_rate5,0)) AS agent_pct_lv5,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate1,0)/100.0)                        AS agent_cost_lv1,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate2,0)/100.0)                        AS agent_cost_lv2,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate3,0)/100.0)                        AS agent_cost_lv3,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate4,0)/100.0)                        AS agent_cost_lv4,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate5,0)/100.0)                        AS agent_cost_lv5,
          SUM(-s.x_net*(COALESCE(100.0-s.x_rate1,0)+COALESCE(100.0-s.x_rate2,0)
                       +COALESCE(100.0-s.x_rate3,0)+COALESCE(100.0-s.x_rate4,0)
                       +COALESCE(100.0-s.x_rate5,0))/100.0)                   AS agent_cost_chain_additive,
          SUM(-s.x_net*(1.0 - CAST(COALESCE(s.x_rate1,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate2,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate3,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate4,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate5,100) AS DOUBLE)/100.0))
                                                                       AS agent_cost_chain_nested,
           AVG(s.x_rbpct) AS rbpct, AVG(s.x_freecomm*1.0) AS freecomm_rate,
           PERCENTILE_APPROX(s.x_stake,0.25) AS p25, PERCENTILE_APPROX(s.x_stake,0.50) AS p50,
           PERCENTILE_APPROX(s.x_stake,0.75) AS p75, PERCENTILE_APPROX(s.x_stake,0.90) AS p90,
           PERCENTILE_APPROX(s.x_stake,0.95) AS p95, PERCENTILE_APPROX(s.x_stake,0.99) AS p99,
           PERCENTILE_APPROX(s.x_valid,0.50) AS p50_valid,
           PERCENTILE_APPROX(s.x_net,0.50)   AS p50_profit,
           SUM(CASE WHEN s.x_rec = 1 THEN s.x_stake ELSE 0 END) AS st_in,
           SUM(CASE WHEN s.x_rec = 1 THEN 1 ELSE 0 END)         AS nb_in,
           SUM(CASE WHEN s.x_rec = 1 THEN s.x_net ELSE 0 END)   AS net_in,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN s.x_stake ELSE 0 END) AS st_out,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN 1 ELSE 0 END)         AS nb_out,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN s.x_net ELSE 0 END)   AS net_out,
           SUM(CASE WHEN s.x_rec=1 THEN s.x_stake ELSE 0 END) AS st_rec,
           SUM(CASE WHEN s.x_rec=1 THEN 1 ELSE 0 END)         AS nb_rec
    FROM x_mk s
    WHERE s.is_clean = 1
      AND s.x_member IS NOT NULL AND TRIM(CAST(s.x_member AS STRING)) <> ''
    GROUP BY s.x_member
  ),
  x_win AS (
    SELECT            COUNT(*) AS n_bets, COUNT(DISTINCT s.x_round) AS n_rounds,
           COUNT(DISTINCT s.x_date) AS active_days, COUNT(DISTINCT s.x_tblshoe) AS active_shoes,
           COUNT(DISTINCT CONCAT_WS('|', s.x_date, s.x_table)) AS active_sessions,
           COUNT(DISTINCT s.x_table) AS n_tables, COUNT(DISTINCT s.x_dealer) AS n_dealers,
           COUNT(DISTINCT s.x_ip) AS n_ips, COUNT(DISTINCT s.x_product) AS n_products,
           MIN(s.x_date) AS first_seen_d, MAX(s.x_date) AS last_seen_d,
           SUM(s.x_stake) AS stake, SUM(s.x_valid) AS valid, SUM(s.x_rebate) AS rebate,
           SUM(s.x_net) AS net, SUM(-s.x_net *(100.0-s.x_agpct)/100.0) AS agent_cost,
           AVG(100.0-s.x_agpct)                   AS agent_pct,
           AVG(s.x_agpct)                         AS company_retain_pct,
           SUM(-s.x_net *s.x_agpct/100.0)         AS agent_cost_a_legacy,
           SUM(s.x_valid*s.x_agpct/100.0)         AS agent_cost_valid_base_legacy,
          AVG(COALESCE(s.x_rate1,100)) AS retain_pct_lv1, AVG(COALESCE(s.x_rate2,100)) AS retain_pct_lv2,
          AVG(COALESCE(s.x_rate3,100)) AS retain_pct_lv3, AVG(COALESCE(s.x_rate4,100)) AS retain_pct_lv4,
          AVG(COALESCE(s.x_rate5,100)) AS retain_pct_lv5, AVG(s.x_chain_depth) AS chain_depth_avg,
          AVG(COALESCE(100.0-s.x_rate1,0)) AS agent_pct_lv1, AVG(COALESCE(100.0-s.x_rate2,0)) AS agent_pct_lv2,
          AVG(COALESCE(100.0-s.x_rate3,0)) AS agent_pct_lv3, AVG(COALESCE(100.0-s.x_rate4,0)) AS agent_pct_lv4,
          AVG(COALESCE(100.0-s.x_rate5,0)) AS agent_pct_lv5,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate1,0)/100.0)                        AS agent_cost_lv1,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate2,0)/100.0)                        AS agent_cost_lv2,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate3,0)/100.0)                        AS agent_cost_lv3,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate4,0)/100.0)                        AS agent_cost_lv4,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate5,0)/100.0)                        AS agent_cost_lv5,
          SUM(-s.x_net*(COALESCE(100.0-s.x_rate1,0)+COALESCE(100.0-s.x_rate2,0)
                       +COALESCE(100.0-s.x_rate3,0)+COALESCE(100.0-s.x_rate4,0)
                       +COALESCE(100.0-s.x_rate5,0))/100.0)                   AS agent_cost_chain_additive,
          SUM(-s.x_net*(1.0 - CAST(COALESCE(s.x_rate1,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate2,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate3,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate4,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate5,100) AS DOUBLE)/100.0))
                                                                       AS agent_cost_chain_nested,
           AVG(s.x_rbpct) AS rbpct, AVG(s.x_freecomm*1.0) AS freecomm_rate,
           PERCENTILE_APPROX(s.x_stake,0.25) AS p25, PERCENTILE_APPROX(s.x_stake,0.50) AS p50,
           PERCENTILE_APPROX(s.x_stake,0.75) AS p75, PERCENTILE_APPROX(s.x_stake,0.90) AS p90,
           PERCENTILE_APPROX(s.x_stake,0.95) AS p95, PERCENTILE_APPROX(s.x_stake,0.99) AS p99,
           PERCENTILE_APPROX(s.x_valid,0.50) AS p50_valid,
           PERCENTILE_APPROX(s.x_net,0.50)   AS p50_profit,
           SUM(CASE WHEN s.x_rec = 1 THEN s.x_stake ELSE 0 END) AS st_in,
           SUM(CASE WHEN s.x_rec = 1 THEN 1 ELSE 0 END)         AS nb_in,
           SUM(CASE WHEN s.x_rec = 1 THEN s.x_net ELSE 0 END)   AS net_in,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN s.x_stake ELSE 0 END) AS st_out,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN 1 ELSE 0 END)         AS nb_out,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN s.x_net ELSE 0 END)   AS net_out,
           SUM(CASE WHEN s.x_rec=1 THEN s.x_stake ELSE 0 END) AS st_rec,
           SUM(CASE WHEN s.x_rec=1 THEN 1 ELSE 0 END)         AS nb_rec
    FROM x_mk s
    WHERE s.is_clean = 1
      AND s.x_member IS NOT NULL AND TRIM(CAST(s.x_member AS STRING)) <> ''
  ),
      q AS (
        WITH v AS (
          SELECT
              dt,
              CAST(NULLIF(TRIM(bet07),'') AS DATE)      AS d_acct,
              CAST(NULLIF(TRIM(bet06),'') AS DATETIME)  AS t_open,
              CAST(NULLIF(TRIM(bet08),'') AS DATETIME)  AS t_bet
          FROM ods_mariadb_2b.ods_a168_bet02
          WHERE bet02 = '101'
        AND sync_time <= '2026-08-27 09:00:00'
        )
        SELECT
            COUNT(*)                                                        AS 行数,
            SUM(CASE WHEN dt = d_acct THEN 1 ELSE 0 END)                    AS dt等于账务日,
            SUM(CASE WHEN dt = DATE(t_bet) THEN 1 ELSE 0 END)               AS dt等于下注日,
            SUM(CASE WHEN d_acct = DATE(t_bet) THEN 1 ELSE 0 END)           AS 账务日等于下注日,
            SUM(CASE WHEN d_acct IS NULL THEN 1 ELSE 0 END)                 AS 账务日不可用,
            SUM(CASE WHEN t_open IS NULL THEN 1 ELSE 0 END)                 AS 开局时间不可用,
            SUM(CASE WHEN t_bet  IS NULL THEN 1 ELSE 0 END)                 AS 下注时间不可用,
            SUM(CASE WHEN t_bet <= '1971-01-01 00:00:00' THEN 1 ELSE 0 END) AS 下注时间纪元哨兵,
            SUM(CASE WHEN t_open <= '1971-01-01 00:00:00' THEN 1 ELSE 0 END) AS 开局时间纪元哨兵,
            MIN(d_acct)                                                     AS 账务日最小,
            MAX(d_acct)                                                     AS 账务日最大,
            SUM(CASE WHEN TIMESTAMPDIFF(SECOND, t_open, t_bet) <  0 THEN 1 ELSE 0 END)
                                                                            AS 下注早于开局_时序异常,
            MIN(TIMESTAMPDIFF(SECOND, t_open, t_bet))                       AS 下注距开局秒_最小,
            PERCENTILE_APPROX(CAST(TIMESTAMPDIFF(SECOND, t_open, t_bet) AS DOUBLE), 0.50)
                                                                            AS 下注距开局秒_P50,
            PERCENTILE_APPROX(CAST(TIMESTAMPDIFF(SECOND, t_open, t_bet) AS DOUBLE), 0.99)
                                                                            AS 下注距开局秒_P99,
            PERCENTILE_APPROX(CAST(TIMESTAMPDIFF(SECOND, t_open, t_bet) AS DOUBLE), 0.999)
                                                                            AS 下注距开局秒_P999,
            MAX(TIMESTAMPDIFF(SECOND, t_open, t_bet))                       AS 下注距开局秒_最大
        FROM v
      )
    SELECT q.*,
           -- 一·经济层
           ROUND(e.stake,4) AS stake, ROUND(e.valid,4) AS valid_bet,
           ROUND(-e.net,4) AS profit, e.n_bets, e.n_rounds,
           ROUND(e.net/NULLIF(e.stake,0),8) AS roi,
           ROUND(e.net_in/NULLIF(e.st_in,0),8) AS roi_recent,
           ROUND(e.net_out/NULLIF(e.st_out,0),8) AS roi_non_recent,
           ROUND((e.net-e.rebate)/NULLIF(e.stake,0),8) AS roi_ex_rebate,
           ROUND(e.net,4) AS roi_numerator, ROUND(e.stake,4) AS roi_denominator,
           CASE WHEN e.stake IS NULL THEN 'NULL_DENOM' WHEN e.stake<=0 THEN 'ZERO_DENOM'
                WHEN e.n_bets<30 THEN 'THIN_EXPOSURE' ELSE 'OK' END AS roi_denominator_status,
           ROUND(e.rebate,4) AS rebate_cost, ROUND(e.agent_cost,4)                           AS cost_complement_b,
       ROUND(e.agent_pct,4)                            AS pct_complement,
       ROUND(e.company_retain_pct,4)                   AS pct_top_bet23,
       'AG03-UNRESOLVED'                                     AS agent_formula_version,
      'ALL5_LEVELS_bet23_to_bet27'                    AS agent_level_scope,
      ROUND(e.agent_cost_lv1,4) AS agent_cost_lv1, ROUND(e.agent_cost_lv2,4) AS agent_cost_lv2,
      ROUND(e.agent_cost_lv3,4) AS agent_cost_lv3, ROUND(e.agent_cost_lv4,4) AS agent_cost_lv4,
      ROUND(e.agent_cost_lv5,4) AS agent_cost_lv5,
      ROUND(e.agent_pct_lv1,6) AS agent_pct_lv1, ROUND(e.agent_pct_lv2,6) AS agent_pct_lv2,
      ROUND(e.agent_pct_lv3,6) AS agent_pct_lv3, ROUND(e.agent_pct_lv4,6) AS agent_pct_lv4,
      ROUND(e.agent_pct_lv5,6) AS agent_pct_lv5,
      ROUND(e.retain_pct_lv1,6) AS retain_pct_lv1, ROUND(e.retain_pct_lv2,6) AS retain_pct_lv2,
      ROUND(e.retain_pct_lv3,6) AS retain_pct_lv3, ROUND(e.retain_pct_lv4,6) AS retain_pct_lv4,
      ROUND(e.retain_pct_lv5,6) AS retain_pct_lv5, ROUND(e.chain_depth_avg,4) AS chain_depth_avg,
      ROUND(e.agent_cost_chain_additive,4)            AS agent_cost_chain_additive,
      ROUND(e.agent_cost_chain_nested,4)              AS agent_cost_chain_nested,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_additive,4) AS residual_chain_additive,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_nested,4)   AS residual_chain_nested,
      'PENDING_AG03'                                  AS decision_status,
      'FALSE'                                         AS admit_to_risk_decision,
      'NOT_FOR_ENFORCEMENT'                           AS deliverable_class,
       ROUND(e.agent_cost_a_legacy,4)                  AS agent_cost_a_legacy,
       ROUND(e.agent_cost_valid_base_legacy,4)         AS agent_cost_valid_base_legacy,
           ROUND(-e.net-e.rebate,4)                        AS ngr,
       ROUND(-e.net-e.rebate-e.agent_cost,4)           AS residual_b,
       ROUND(-e.net-e.rebate-e.agent_cost_a_legacy,4)  AS residual_a,
           ROUND((-e.net-e.rebate)/NULLIF(e.stake,0),8)    AS ngr_rate,
       ROUND((-e.net-e.rebate-e.agent_cost)/NULLIF(e.stake,0),8)   AS residual_b_rate,
      -- 【HF9c · canonical accounting contract】
      --   以下 canonical 字段只增加明确 scope；不删除、不覆盖既有字段。
      --   formal_bet23_* 保持 HF9b 当前生产公式及其 NULL/0 语义；
      --   lv1~lv5 / additive / nested 则分别采用各自原始 e.* 成本字段，
      --   rate 一律从未舍入的 e.* 分子 / e.stake 计算，禁止由展示值反算。
      ROUND(e.agent_cost,4) AS agent_cost_bet23_formal_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost,4) AS net_margin_bet23_formal_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost)/NULLIF(e.stake,0),8) AS net_margin_bet23_formal_rate_canonical,
      ROUND(e.agent_cost_lv1,4) AS agent_cost_lv1_bet23_canonical,
      ROUND(e.agent_cost_lv2,4) AS agent_cost_lv2_bet24_canonical,
      ROUND(e.agent_cost_lv3,4) AS agent_cost_lv3_bet25_canonical,
      ROUND(e.agent_cost_lv4,4) AS agent_cost_lv4_bet26_canonical,
      ROUND(e.agent_cost_lv5,4) AS agent_cost_lv5_bet27_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_lv1,4) AS net_margin_lv1_bet23_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_lv1)/NULLIF(e.stake,0),8) AS net_margin_lv1_bet23_rate_canonical,
      ROUND(e.agent_cost_chain_additive,4) AS agent_cost_chain_additive_canonical,
      ROUND(e.agent_cost_chain_nested,4) AS agent_cost_chain_nested_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_additive,4) AS net_margin_chain_additive_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_nested,4) AS net_margin_chain_nested_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_chain_additive)/NULLIF(e.stake,0),8) AS net_margin_chain_additive_rate_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_chain_nested)/NULLIF(e.stake,0),8) AS net_margin_chain_nested_rate_canonical,
       ROUND((-e.net-e.rebate-e.agent_cost_a_legacy)/NULLIF(e.stake,0),8) AS residual_a_rate,
           -- 二·分布层
           ROUND(e.stake/NULLIF(e.n_bets,0),4) AS avg_stake_per_bet,
           ROUND(e.valid/NULLIF(e.n_rounds,0),4) AS avg_valid_bet_per_round,
           ROUND(-e.net/NULLIF(e.n_rounds,0),4) AS avg_profit_per_round,
           ROUND(-e.net/NULLIF(e.active_days,0),4) AS avg_profit_per_day,
           ROUND(-e.net/NULLIF(e.active_shoes,0),4) AS avg_profit_per_shoe,
           ROUND(e.stake/NULLIF(e.active_days,0),4) AS avg_stake_per_active_day,
           ROUND(e.n_rounds*1.0/NULLIF(e.active_days,0),4) AS avg_rounds_per_active_day,
           ROUND(e.st_in/NULLIF(e.nb_in,0),4) AS avg_stake_recent,
           ROUND(e.st_out/NULLIF(e.nb_out,0),4) AS avg_stake_non_recent,
           ROUND(e.p25,4) AS p25_stake, ROUND(e.p50,4) AS p50_stake, ROUND(e.p75,4) AS p75_stake,
           ROUND(e.p90,4) AS p90_stake, ROUND(e.p95,4) AS p95_stake, ROUND(e.p99,4) AS p99_stake,
           ROUND(e.p50_valid,4) AS p50_valid_bet, ROUND(e.p50_profit,4) AS p50_profit,
           ROUND(e.p95/NULLIF(e.p50,0),6) AS p95_over_p50,
           ROUND(e.p99/NULLIF(e.p50,0),6) AS p99_over_p50,
           ROUND((e.stake/NULLIF(e.n_bets,0))/NULLIF(e.p50,0),6) AS avg_over_p50,
           -- 三·关系层
           e.n_tables AS common_table_count, e.n_dealers AS common_dealer_count,
           e.n_ips AS common_ip_count, e.n_products AS common_product_count,
           ROUND(e.st_in/NULLIF(e.stake,0),8) AS share_recent,
           -- 四·rate 层
           ROUND(-e.net/NULLIF(e.stake,0),8) AS hold_rate,
           ROUND(-e.net_in/NULLIF(e.st_in,0),8) AS hold_rate_recent,
           ROUND(e.rebate/NULLIF(e.valid,0),8) AS rebate_rate_actual,
           ROUND(e.rbpct,6) AS rebate_pct_config,
           ROUND(e.valid/NULLIF(e.stake,0),6) AS turnover_multiple,
           ROUND(e.freecomm_rate,6) AS free_comm_rate,
           ROUND(e.net_in/NULLIF(e.st_in,0)-e.net_out/NULLIF(e.st_out,0),8) AS roi_delta_recent,
           -- 五·动态层
           e.first_seen_d AS first_seen, e.last_seen_d AS last_seen,
           e.active_days, e.active_shoes, e.active_sessions,
           DATEDIFF(e.last_seen_d, e.first_seen_d)+1 AS span_days,
           ROUND(e.active_days*1.0/NULLIF(DATEDIFF(e.last_seen_d,e.first_seen_d)+1,0),6) AS persistence,
           ROUND((e.st_in/NULLIF(e.nb_in,0))/NULLIF(e.st_out/NULLIF(e.nb_out,0),0),6) AS ramp_recent_vs_prior,
           ROUND((e.st_rec/NULLIF(e.nb_rec,0))/NULLIF(e.stake/NULLIF(e.n_bets,0),0),6) AS ramp_recent_vs_all,
           ROUND((e.st_rec/NULLIF(e.stake,0))/0.30,6) AS stake_ramp,
           -- 六·决策层（HF9g-P5 · D-14 斧正 —— 本件属【全窗基线族】，相对刻度与决策标签一律 NULL）
           --   病灶：x_win 系全窗单行聚合（无 GROUP BY，恒 1 行，此为设计使然，非缺陷），
           --         经 CROSS JOIN 接入后 e.* 全行同值；六层之 NTILE / PERCENT_RANK 施于常数即退化，
           --         PERCENT_RANK 恒 0 ⇒ action_priority 恒判 A，全件 100% 误标。
           --   ★ 斧正原则：不给 x_win 补 GROUP BY —— 那会改变其「全窗基线」语义，属退化。
           --     正解与 #018 之 G-05／G-06 同治：范围外之行不得接受任何下游评分与决策标签。
           --   ★ 本件之 e.* 仍照常供其它列作全窗基线使用，仅六层相对刻度与决策标签置 NULL。
           CAST(NULL AS INT)                                              AS vip_tier,                        -- 空值取值：全窗基线族无实体可分档，置 NULL（NULL＝不适用，非 0）
           CAST(NULL AS DOUBLE)                                           AS economic_value,                  -- 空值取值：同上，禁以常数百分位冒充经济价值
           CAST(NULL AS DOUBLE)                                           AS roi_pr_global,                   -- 空值取值：同上
           CAST(NULL AS DOUBLE)                                           AS risk_value,                      -- 空值取值：兼容列，同上
           CAST(NULL AS DOUBLE)                                           AS pr_stake,                        -- 空值取值：兼容列，同上
           CAST(NULL AS DOUBLE)                                           AS pr_global,                       -- 空值取值：同上
           CAST(NULL AS DOUBLE)                                           AS pr_qualified,                    -- 空值取值：同上
           'GLOBAL_BASELINE_NO_ENTITY_RANKING'                            AS pr_qualified_population,         -- 字面取值：血统 —— 明示本件为全窗基线族，无实体排序总体
           CAST(NULL AS BIGINT)                                           AS pr_global_population_n,          -- 空值取值：血统 —— 不适用
           CAST(NULL AS BIGINT)                                           AS pr_qualified_population_n,       -- 空值取值：血统 —— 不适用
           'NOT_APPLICABLE_GLOBAL_BASELINE'                               AS pr_calculation_method,           -- 字面取值：血统 —— 算法不适用
           'HF9g-P5'                                                      AS pr_calculation_version,          -- 字面取值：血统 —— 算法版本
           CAST(NULL AS STRING)                                           AS evidence_flag,                   -- 空值取值：证据旗标不适用于全窗基线
           CAST(NULL AS STRING)                                           AS evidence_rate,                   -- 空值取值：同上
           CAST(NULL AS DOUBLE)                                           AS hold_ci_halfwidth_approx,        -- 空值取值：同上
           'X 全窗基线 · 不参与实体赏罚'                                    AS action_priority                  -- 字面取值：★ D-14 斧正 —— 本族恒不入赏罚，取代原 100% 误标之「A」
    FROM q
    CROSS JOIN x_win e
  ) y
) z
-- ── 逐批 WHERE 阶梯（★ 口诀：上界 ＝ 下界 ＋ 100000，两数同进）──
--    本件 T_true 未测，无需先跑 T_true；以 0 / 100000 控制本批返回区间，末批由实际行数 < 100000 判定
--    WHERE z.audit_rn >        0 AND z.audit_rn <=   100000   -- 第 1 批
--    WHERE z.audit_rn >   100000 AND z.audit_rn <=   200000   -- 第 2 批
--    WHERE z.audit_rn >   200000 AND z.audit_rn <=   300000   -- 第 3 批
--    WHERE z.audit_rn >   300000 AND z.audit_rn <=   400000   -- 第 4 批
--    WHERE z.audit_rn >   400000 AND z.audit_rn <=   500000   -- 第 5 批
--    WHERE z.audit_rn >   500000 AND z.audit_rn <=   600000   -- 第 6 批
--    WHERE z.audit_rn >   600000 AND z.audit_rn <=   700000   -- 第 7 批
--    …余批类推。第 k 批：WHERE z.audit_rn > (k-1)*100000 AND z.audit_rn <= k*100000
--    某批返回 < 100000 行即为末批，其后不再取。
--
--    ⚠ 常见误写（务必避开）：只推下界而上界不动 ——
--        WHERE z.audit_rn > 100000 AND z.audit_rn <= 100000   ← 自相矛盾，恒为假，返回空集
--        WHERE z.audit_rn > 200000 AND z.audit_rn <= 100000   ← 同上，空集
--      两个数必须**同时**前进，且始终相差 100000。
--      下界 ＝ 上一批之上界；上界 ＝ 本批之上界。
WHERE z.audit_rn > 0 AND z.audit_rn <= 100000 -- ★ HF9c 本批区间
ORDER BY z.audit_rn;


-- ══════════════════════════════════════════════════════════════════════════════════════════════
-- 120. Z11_sentinel_impact.csv   [总包行 919~957 · 原 13 列 ＋六层约 60 列]
--     典型学：M09 处置限额　派生旗标：post（s.x_rec = 1 · 仅供 CASE 条件聚合，全包无任何 WHERE/AND/HAVING 以此过滤）　连接：全窗基线
-- ══════════════════════════════════════════════════════════════════════════════════════════════
-- ★ W-64 · D-14 警示（本件属 x_win 族 · 66 件之一 · 详见 §Z 段 D-14 全案）
--   本件以 `CROSS JOIN x_win e` 接入全局基线，x_win 无 GROUP BY ⇒ 恒 1 行 ⇒ e.* 全行同值。
--   故：economic_value / roi_pr_global / risk_value / pr_stake / pr_global 恒为 0；
--       action_priority 每一行皆为「A 净亏最大十分位 · 优先复核」（Z 分支永不触发）；
--       evidence_rate 恒为最高档；vip_tier 由常数键分档 ⇒ 无信息且非确定。
--   ⇒ 本件决策层三列 **NOT_FOR_DECISION**，裁定前不得用于排班、抽查或汇报。
-- ── ① 先跑 T_true 留档（不足 100000 者一次导全，不必分批）──
-- ── ① T_true：HF9c 不再强制预跑完整 COUNT。
--    本批实际返回行数 < 100000 即判定为末批；全批完成后以各批 n_rows / audit_rn 范围核对总量。

-- ── ② 分批取数：第 1 批。第 k 批只改末行两数为 (k-1)*100000 与 k*100000 ──
--    审计字段二（REDTEAM 2026-08-24 裁定 · 四锁）：
--      audit_rn  全局观测坐标 —— 由**与原版审计版逐字同一**之排序键所生，两版可逐行对账
--      batch_id  物理分批信息 —— 该行所属批次，由 audit_rn 算得，非引擎所赋
--    ★ 锁三：二者皆为审计字段，**不得进入任何业务指标计算**。
--    ★ 锁四：两版经 audit_rn 逐行字段核验后，方可宣布输出完全一致。

-- ── ③ 每批取回后自证四数（任一不符即停手回报，禁止放行）──
--    n_rows        = COUNT(*)      须等于 COUNT(DISTINCT audit_rn)   （批内无重复）
--    audit_rn_min  = MIN(audit_rn) 须等于 (k-1)*100000 + 1           （与上批严丝合缝）
--    audit_rn_max  = MAX(audit_rn) 须等于 min + n_rows - 1           （批内无缺口）
--    全批取毕再验：各批 audit_rn 之并集 = 1 .. T_true，无缺号、无重号。
--     ★ 首行＝平台真净亏最多者（已扣退水与代理占成）。
--
SELECT z.*,
       CAST(FLOOR((z.audit_rn - 1) / 100000) + 1 AS INT)          AS batch_id,
       'A168_HF9F_20260827_0900' AS run_id,
       '2026-08-27 09:00:00' AS snapshot_sync_time
FROM (
  SELECT y.*,
         ROW_NUMBER() OVER (ORDER BY y.`residual_b` ASC, y.`roi` DESC, y.`未处置_注单行数`, y.`已处置_注单行数`, y.`未处置_局键数`, y.`已处置_局键数`, y.`未处置_会员数`, y.`已处置_会员数`, y.`未处置_IP数`, y.`已处置_IP数`, y.`未处置_单局最大会员数`, y.`已处置_单局最大会员数`, y.`单局最大会员数_差额`, y.`剔除行数`, y.`剔除占比`) AS audit_rn
  FROM (
    WITH
      x_ranked AS (
    SELECT b.bet01, b.bet03, b.bet04, b.bet05, b.bet09, b.bet11, b.bet13,
           b.bet15, b.bet16, b.bet17, b.bet18, b.bet19, b.bet20, b.bet21,
           b.bet22, b.bet23, b.bet24, b.bet25, b.bet26, b.bet27, b.bet38, b.bet39, b.category, b.commission,
           b.dt, b.eid, b.ip, b.validbet, b.updatetime, b.sync_time,
           ROW_NUMBER() OVER (
             PARTITION BY b.bet01
             ORDER BY b.updatetime DESC, b.sync_time DESC, b.dt DESC)      AS x_rn
    FROM ods_mariadb_2b.ods_a168_bet02 b
    WHERE b.dt >= '2026-03-21' AND b.dt < '2026-08-07'
      AND b.bet02 = '101'
      AND b.sync_time <= '2026-08-27 09:00:00'
  ),
    x_testagent AS (
    SELECT age001 AS agent_id FROM ods_mariadb_2b.ods_a168_agent WHERE age022 = '1'
  ),
    x_bs0 AS (
    SELECT b.bet05 AS x_member, b.eid AS x_dealer, b.bet39 AS x_table,
           b.bet03 AS x_shoe, b.ip AS x_ip, b.bet09 AS x_product, b.dt AS x_date,
           CONCAT_WS('|', b.bet03, b.bet04, b.bet39)                      AS x_round,
           CONCAT_WS('|', b.bet39, b.bet03)                               AS x_tblshoe,
           CAST(NULLIF(TRIM(b.bet04),'') AS INT)                          AS x_rno,
           CASE WHEN b.dt >= '2026-07-08' THEN 1 ELSE 0 END               AS x_rec,
           CASE WHEN TRIM(b.commission)='1' THEN 1 ELSE 0 END             AS x_freecomm,
           CAST(NULLIF(TRIM(b.bet13),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_stake,
           CAST(NULLIF(TRIM(b.validbet),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_valid,
           CAST(NULLIF(TRIM(b.bet16),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_rebate,
           CAST(NULLIF(TRIM(b.bet17),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_net,
           CAST(NULLIF(TRIM(b.bet15),'') AS DECIMAL(20,6))                AS x_rbpct,
           COALESCE(CAST(NULLIF(TRIM(b.bet23),'') AS DECIMAL(20,6)),0)   AS x_agpct,
          NULLIF(CAST(NULLIF(TRIM(b.bet23),'') AS DECIMAL(20,6)),0)     AS x_rate1,
          NULLIF(CAST(NULLIF(TRIM(b.bet24),'') AS DECIMAL(20,6)),0)     AS x_rate2,
          NULLIF(CAST(NULLIF(TRIM(b.bet25),'') AS DECIMAL(20,6)),0)     AS x_rate3,
          NULLIF(CAST(NULLIF(TRIM(b.bet26),'') AS DECIMAL(20,6)),0)     AS x_rate4,
          NULLIF(CAST(NULLIF(TRIM(b.bet27),'') AS DECIMAL(20,6)),0)     AS x_rate5,
          (CASE WHEN NULLIF(CAST(NULLIF(TRIM(b.bet22),'') AS BIGINT),0) IS NOT NULL THEN 5
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet21),'') AS BIGINT),0) IS NOT NULL THEN 4
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet20),'') AS BIGINT),0) IS NOT NULL THEN 3
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet19),'') AS BIGINT),0) IS NOT NULL THEN 2
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet18),'') AS BIGINT),0) IS NOT NULL THEN 1
                ELSE 0 END)                                             AS x_chain_depth,
           CASE WHEN COALESCE(t1.agent_id,t2.agent_id,t3.agent_id,
                              t4.agent_id,t5.agent_id) IS NOT NULL
                THEN 1 ELSE 0 END                                        AS f_testline
    FROM x_ranked b
    LEFT JOIN x_testagent t1 ON t1.agent_id = b.bet18
    LEFT JOIN x_testagent t2 ON t2.agent_id = b.bet19
    LEFT JOIN x_testagent t3 ON t3.agent_id = b.bet20
    LEFT JOIN x_testagent t4 ON t4.agent_id = b.bet21
    LEFT JOIN x_testagent t5 ON t5.agent_id = b.bet22
    WHERE b.x_rn = 1
      AND b.category='1' AND UPPER(TRIM(b.bet38))='N'
      AND CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8)) > 0
  ),
  x_mk AS (
    SELECT s.*,
           CASE WHEN s.f_testline = 0 THEN 1 ELSE 0 END                 AS is_clean
    FROM x_bs0 s
  ),
  x_agg AS (
    SELECT s.x_member                                                        AS x_key,
           COUNT(*) AS n_bets, COUNT(DISTINCT s.x_round) AS n_rounds,
           COUNT(DISTINCT s.x_date) AS active_days, COUNT(DISTINCT s.x_tblshoe) AS active_shoes,
           COUNT(DISTINCT CONCAT_WS('|', s.x_date, s.x_table)) AS active_sessions,
           COUNT(DISTINCT s.x_table) AS n_tables, COUNT(DISTINCT s.x_dealer) AS n_dealers,
           COUNT(DISTINCT s.x_ip) AS n_ips, COUNT(DISTINCT s.x_product) AS n_products,
           MIN(s.x_date) AS first_seen_d, MAX(s.x_date) AS last_seen_d,
           SUM(s.x_stake) AS stake, SUM(s.x_valid) AS valid, SUM(s.x_rebate) AS rebate,
           SUM(s.x_net) AS net, SUM(-s.x_net *(100.0-s.x_agpct)/100.0) AS agent_cost,
           AVG(100.0-s.x_agpct)                   AS agent_pct,
           AVG(s.x_agpct)                         AS company_retain_pct,
           SUM(-s.x_net *s.x_agpct/100.0)         AS agent_cost_a_legacy,
           SUM(s.x_valid*s.x_agpct/100.0)         AS agent_cost_valid_base_legacy,
          AVG(COALESCE(s.x_rate1,100)) AS retain_pct_lv1, AVG(COALESCE(s.x_rate2,100)) AS retain_pct_lv2,
          AVG(COALESCE(s.x_rate3,100)) AS retain_pct_lv3, AVG(COALESCE(s.x_rate4,100)) AS retain_pct_lv4,
          AVG(COALESCE(s.x_rate5,100)) AS retain_pct_lv5, AVG(s.x_chain_depth) AS chain_depth_avg,
          AVG(COALESCE(100.0-s.x_rate1,0)) AS agent_pct_lv1, AVG(COALESCE(100.0-s.x_rate2,0)) AS agent_pct_lv2,
          AVG(COALESCE(100.0-s.x_rate3,0)) AS agent_pct_lv3, AVG(COALESCE(100.0-s.x_rate4,0)) AS agent_pct_lv4,
          AVG(COALESCE(100.0-s.x_rate5,0)) AS agent_pct_lv5,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate1,0)/100.0)                        AS agent_cost_lv1,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate2,0)/100.0)                        AS agent_cost_lv2,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate3,0)/100.0)                        AS agent_cost_lv3,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate4,0)/100.0)                        AS agent_cost_lv4,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate5,0)/100.0)                        AS agent_cost_lv5,
          SUM(-s.x_net*(COALESCE(100.0-s.x_rate1,0)+COALESCE(100.0-s.x_rate2,0)
                       +COALESCE(100.0-s.x_rate3,0)+COALESCE(100.0-s.x_rate4,0)
                       +COALESCE(100.0-s.x_rate5,0))/100.0)                   AS agent_cost_chain_additive,
          SUM(-s.x_net*(1.0 - CAST(COALESCE(s.x_rate1,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate2,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate3,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate4,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate5,100) AS DOUBLE)/100.0))
                                                                       AS agent_cost_chain_nested,
           AVG(s.x_rbpct) AS rbpct, AVG(s.x_freecomm*1.0) AS freecomm_rate,
           PERCENTILE_APPROX(s.x_stake,0.25) AS p25, PERCENTILE_APPROX(s.x_stake,0.50) AS p50,
           PERCENTILE_APPROX(s.x_stake,0.75) AS p75, PERCENTILE_APPROX(s.x_stake,0.90) AS p90,
           PERCENTILE_APPROX(s.x_stake,0.95) AS p95, PERCENTILE_APPROX(s.x_stake,0.99) AS p99,
           PERCENTILE_APPROX(s.x_valid,0.50) AS p50_valid,
           PERCENTILE_APPROX(s.x_net,0.50)   AS p50_profit,
           SUM(CASE WHEN s.x_rec = 1 THEN s.x_stake ELSE 0 END) AS st_in,
           SUM(CASE WHEN s.x_rec = 1 THEN 1 ELSE 0 END)         AS nb_in,
           SUM(CASE WHEN s.x_rec = 1 THEN s.x_net ELSE 0 END)   AS net_in,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN s.x_stake ELSE 0 END) AS st_out,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN 1 ELSE 0 END)         AS nb_out,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN s.x_net ELSE 0 END)   AS net_out,
           SUM(CASE WHEN s.x_rec=1 THEN s.x_stake ELSE 0 END) AS st_rec,
           SUM(CASE WHEN s.x_rec=1 THEN 1 ELSE 0 END)         AS nb_rec
    FROM x_mk s
    WHERE s.is_clean = 1
      AND s.x_member IS NOT NULL AND TRIM(CAST(s.x_member AS STRING)) <> ''
    GROUP BY s.x_member
  ),
  x_win AS (
    SELECT            COUNT(*) AS n_bets, COUNT(DISTINCT s.x_round) AS n_rounds,
           COUNT(DISTINCT s.x_date) AS active_days, COUNT(DISTINCT s.x_tblshoe) AS active_shoes,
           COUNT(DISTINCT CONCAT_WS('|', s.x_date, s.x_table)) AS active_sessions,
           COUNT(DISTINCT s.x_table) AS n_tables, COUNT(DISTINCT s.x_dealer) AS n_dealers,
           COUNT(DISTINCT s.x_ip) AS n_ips, COUNT(DISTINCT s.x_product) AS n_products,
           MIN(s.x_date) AS first_seen_d, MAX(s.x_date) AS last_seen_d,
           SUM(s.x_stake) AS stake, SUM(s.x_valid) AS valid, SUM(s.x_rebate) AS rebate,
           SUM(s.x_net) AS net, SUM(-s.x_net *(100.0-s.x_agpct)/100.0) AS agent_cost,
           AVG(100.0-s.x_agpct)                   AS agent_pct,
           AVG(s.x_agpct)                         AS company_retain_pct,
           SUM(-s.x_net *s.x_agpct/100.0)         AS agent_cost_a_legacy,
           SUM(s.x_valid*s.x_agpct/100.0)         AS agent_cost_valid_base_legacy,
          AVG(COALESCE(s.x_rate1,100)) AS retain_pct_lv1, AVG(COALESCE(s.x_rate2,100)) AS retain_pct_lv2,
          AVG(COALESCE(s.x_rate3,100)) AS retain_pct_lv3, AVG(COALESCE(s.x_rate4,100)) AS retain_pct_lv4,
          AVG(COALESCE(s.x_rate5,100)) AS retain_pct_lv5, AVG(s.x_chain_depth) AS chain_depth_avg,
          AVG(COALESCE(100.0-s.x_rate1,0)) AS agent_pct_lv1, AVG(COALESCE(100.0-s.x_rate2,0)) AS agent_pct_lv2,
          AVG(COALESCE(100.0-s.x_rate3,0)) AS agent_pct_lv3, AVG(COALESCE(100.0-s.x_rate4,0)) AS agent_pct_lv4,
          AVG(COALESCE(100.0-s.x_rate5,0)) AS agent_pct_lv5,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate1,0)/100.0)                        AS agent_cost_lv1,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate2,0)/100.0)                        AS agent_cost_lv2,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate3,0)/100.0)                        AS agent_cost_lv3,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate4,0)/100.0)                        AS agent_cost_lv4,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate5,0)/100.0)                        AS agent_cost_lv5,
          SUM(-s.x_net*(COALESCE(100.0-s.x_rate1,0)+COALESCE(100.0-s.x_rate2,0)
                       +COALESCE(100.0-s.x_rate3,0)+COALESCE(100.0-s.x_rate4,0)
                       +COALESCE(100.0-s.x_rate5,0))/100.0)                   AS agent_cost_chain_additive,
          SUM(-s.x_net*(1.0 - CAST(COALESCE(s.x_rate1,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate2,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate3,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate4,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate5,100) AS DOUBLE)/100.0))
                                                                       AS agent_cost_chain_nested,
           AVG(s.x_rbpct) AS rbpct, AVG(s.x_freecomm*1.0) AS freecomm_rate,
           PERCENTILE_APPROX(s.x_stake,0.25) AS p25, PERCENTILE_APPROX(s.x_stake,0.50) AS p50,
           PERCENTILE_APPROX(s.x_stake,0.75) AS p75, PERCENTILE_APPROX(s.x_stake,0.90) AS p90,
           PERCENTILE_APPROX(s.x_stake,0.95) AS p95, PERCENTILE_APPROX(s.x_stake,0.99) AS p99,
           PERCENTILE_APPROX(s.x_valid,0.50) AS p50_valid,
           PERCENTILE_APPROX(s.x_net,0.50)   AS p50_profit,
           SUM(CASE WHEN s.x_rec = 1 THEN s.x_stake ELSE 0 END) AS st_in,
           SUM(CASE WHEN s.x_rec = 1 THEN 1 ELSE 0 END)         AS nb_in,
           SUM(CASE WHEN s.x_rec = 1 THEN s.x_net ELSE 0 END)   AS net_in,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN s.x_stake ELSE 0 END) AS st_out,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN 1 ELSE 0 END)         AS nb_out,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN s.x_net ELSE 0 END)   AS net_out,
           SUM(CASE WHEN s.x_rec=1 THEN s.x_stake ELSE 0 END) AS st_rec,
           SUM(CASE WHEN s.x_rec=1 THEN 1 ELSE 0 END)         AS nb_rec
    FROM x_mk s
    WHERE s.is_clean = 1
      AND s.x_member IS NOT NULL AND TRIM(CAST(s.x_member AS STRING)) <> ''
  ),
      q AS (
        WITH v AS (
          SELECT
              CAST(bet05 AS VARCHAR) AS member_id,
              CAST(ip    AS VARCHAR) AS ip_addr,
              CONCAT_WS('|', CAST(bet03 AS VARCHAR),
                             CAST(bet04 AS VARCHAR),
                             CAST(bet39 AS VARCHAR)) AS round_key,
              CASE WHEN CAST(bet03 AS VARCHAR) IN ('-1','0','') OR bet03 IS NULL
                        OR CAST(bet04 AS VARCHAR) IN ('-1','0','') OR bet04 IS NULL
                        OR CAST(bet39 AS VARCHAR) IN ('-1','0','') OR bet39 IS NULL
                   THEN 1 ELSE 0 END AS is_sentinel_key
          FROM ods_mariadb_2b.ods_a168_bet02
          WHERE bet02 = '101'
        AND sync_time <= '2026-08-27 09:00:00'
        ),
        a AS (
          SELECT COUNT(*) AS n_rows, COUNT(DISTINCT round_key) AS n_key,
                 COUNT(DISTINCT member_id) AS n_member, COUNT(DISTINCT ip_addr) AS n_ip
          FROM v
        ),
        b AS (
          SELECT COUNT(*) AS n_rows, COUNT(DISTINCT round_key) AS n_key,
                 COUNT(DISTINCT member_id) AS n_member, COUNT(DISTINCT ip_addr) AS n_ip
          FROM v WHERE is_sentinel_key = 0
        ),
        ma AS (SELECT MAX(c) AS m FROM (SELECT round_key, COUNT(DISTINCT member_id) AS c
                                        FROM v GROUP BY round_key) x),
        mb AS (SELECT MAX(c) AS m FROM (SELECT round_key, COUNT(DISTINCT member_id) AS c
                                        FROM v WHERE is_sentinel_key = 0 GROUP BY round_key) y)
        SELECT
            a.n_rows   AS 未处置_注单行数,  b.n_rows   AS 已处置_注单行数,
            a.n_key    AS 未处置_局键数,    b.n_key    AS 已处置_局键数,
            a.n_member AS 未处置_会员数,    b.n_member AS 已处置_会员数,
            a.n_ip     AS 未处置_IP数,      b.n_ip     AS 已处置_IP数,
            ma.m       AS 未处置_单局最大会员数,
            mb.m       AS 已处置_单局最大会员数,
            ma.m - mb.m                                       AS 单局最大会员数_差额,
            a.n_rows - b.n_rows                               AS 剔除行数,
            (a.n_rows - b.n_rows) * 1.0 / NULLIF(a.n_rows, 0) AS 剔除占比
        FROM a CROSS JOIN b CROSS JOIN ma CROSS JOIN mb
      )
    SELECT q.*,
           -- 一·经济层
           ROUND(e.stake,4) AS stake, ROUND(e.valid,4) AS valid_bet,
           ROUND(-e.net,4) AS profit, e.n_bets, e.n_rounds,
           ROUND(e.net/NULLIF(e.stake,0),8) AS roi,
           ROUND(e.net_in/NULLIF(e.st_in,0),8) AS roi_post,
           ROUND(e.net_out/NULLIF(e.st_out,0),8) AS roi_non_post,
           ROUND((e.net-e.rebate)/NULLIF(e.stake,0),8) AS roi_ex_rebate,
           ROUND(e.net,4) AS roi_numerator, ROUND(e.stake,4) AS roi_denominator,
           CASE WHEN e.stake IS NULL THEN 'NULL_DENOM' WHEN e.stake<=0 THEN 'ZERO_DENOM'
                WHEN e.n_bets<30 THEN 'THIN_EXPOSURE' ELSE 'OK' END AS roi_denominator_status,
           ROUND(e.rebate,4) AS rebate_cost, ROUND(e.agent_cost,4)                           AS cost_complement_b,
       ROUND(e.agent_pct,4)                            AS pct_complement,
       ROUND(e.company_retain_pct,4)                   AS pct_top_bet23,
       'AG03-UNRESOLVED'                                     AS agent_formula_version,
      'ALL5_LEVELS_bet23_to_bet27'                    AS agent_level_scope,
      ROUND(e.agent_cost_lv1,4) AS agent_cost_lv1, ROUND(e.agent_cost_lv2,4) AS agent_cost_lv2,
      ROUND(e.agent_cost_lv3,4) AS agent_cost_lv3, ROUND(e.agent_cost_lv4,4) AS agent_cost_lv4,
      ROUND(e.agent_cost_lv5,4) AS agent_cost_lv5,
      ROUND(e.agent_pct_lv1,6) AS agent_pct_lv1, ROUND(e.agent_pct_lv2,6) AS agent_pct_lv2,
      ROUND(e.agent_pct_lv3,6) AS agent_pct_lv3, ROUND(e.agent_pct_lv4,6) AS agent_pct_lv4,
      ROUND(e.agent_pct_lv5,6) AS agent_pct_lv5,
      ROUND(e.retain_pct_lv1,6) AS retain_pct_lv1, ROUND(e.retain_pct_lv2,6) AS retain_pct_lv2,
      ROUND(e.retain_pct_lv3,6) AS retain_pct_lv3, ROUND(e.retain_pct_lv4,6) AS retain_pct_lv4,
      ROUND(e.retain_pct_lv5,6) AS retain_pct_lv5, ROUND(e.chain_depth_avg,4) AS chain_depth_avg,
      ROUND(e.agent_cost_chain_additive,4)            AS agent_cost_chain_additive,
      ROUND(e.agent_cost_chain_nested,4)              AS agent_cost_chain_nested,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_additive,4) AS residual_chain_additive,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_nested,4)   AS residual_chain_nested,
      'PENDING_AG03'                                  AS decision_status,
      'FALSE'                                         AS admit_to_risk_decision,
      'NOT_FOR_ENFORCEMENT'                           AS deliverable_class,
       ROUND(e.agent_cost_a_legacy,4)                  AS agent_cost_a_legacy,
       ROUND(e.agent_cost_valid_base_legacy,4)         AS agent_cost_valid_base_legacy,
           ROUND(-e.net-e.rebate,4)                        AS ngr,
       ROUND(-e.net-e.rebate-e.agent_cost,4)           AS residual_b,
       ROUND(-e.net-e.rebate-e.agent_cost_a_legacy,4)  AS residual_a,
           ROUND((-e.net-e.rebate)/NULLIF(e.stake,0),8)    AS ngr_rate,
       ROUND((-e.net-e.rebate-e.agent_cost)/NULLIF(e.stake,0),8)   AS residual_b_rate,
      -- 【HF9c · canonical accounting contract】
      --   以下 canonical 字段只增加明确 scope；不删除、不覆盖既有字段。
      --   formal_bet23_* 保持 HF9b 当前生产公式及其 NULL/0 语义；
      --   lv1~lv5 / additive / nested 则分别采用各自原始 e.* 成本字段，
      --   rate 一律从未舍入的 e.* 分子 / e.stake 计算，禁止由展示值反算。
      ROUND(e.agent_cost,4) AS agent_cost_bet23_formal_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost,4) AS net_margin_bet23_formal_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost)/NULLIF(e.stake,0),8) AS net_margin_bet23_formal_rate_canonical,
      ROUND(e.agent_cost_lv1,4) AS agent_cost_lv1_bet23_canonical,
      ROUND(e.agent_cost_lv2,4) AS agent_cost_lv2_bet24_canonical,
      ROUND(e.agent_cost_lv3,4) AS agent_cost_lv3_bet25_canonical,
      ROUND(e.agent_cost_lv4,4) AS agent_cost_lv4_bet26_canonical,
      ROUND(e.agent_cost_lv5,4) AS agent_cost_lv5_bet27_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_lv1,4) AS net_margin_lv1_bet23_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_lv1)/NULLIF(e.stake,0),8) AS net_margin_lv1_bet23_rate_canonical,
      ROUND(e.agent_cost_chain_additive,4) AS agent_cost_chain_additive_canonical,
      ROUND(e.agent_cost_chain_nested,4) AS agent_cost_chain_nested_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_additive,4) AS net_margin_chain_additive_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_nested,4) AS net_margin_chain_nested_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_chain_additive)/NULLIF(e.stake,0),8) AS net_margin_chain_additive_rate_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_chain_nested)/NULLIF(e.stake,0),8) AS net_margin_chain_nested_rate_canonical,
       ROUND((-e.net-e.rebate-e.agent_cost_a_legacy)/NULLIF(e.stake,0),8) AS residual_a_rate,
           -- 二·分布层
           ROUND(e.stake/NULLIF(e.n_bets,0),4) AS avg_stake_per_bet,
           ROUND(e.valid/NULLIF(e.n_rounds,0),4) AS avg_valid_bet_per_round,
           ROUND(-e.net/NULLIF(e.n_rounds,0),4) AS avg_profit_per_round,
           ROUND(-e.net/NULLIF(e.active_days,0),4) AS avg_profit_per_day,
           ROUND(-e.net/NULLIF(e.active_shoes,0),4) AS avg_profit_per_shoe,
           ROUND(e.stake/NULLIF(e.active_days,0),4) AS avg_stake_per_active_day,
           ROUND(e.n_rounds*1.0/NULLIF(e.active_days,0),4) AS avg_rounds_per_active_day,
           ROUND(e.st_in/NULLIF(e.nb_in,0),4) AS avg_stake_post,
           ROUND(e.st_out/NULLIF(e.nb_out,0),4) AS avg_stake_non_post,
           ROUND(e.p25,4) AS p25_stake, ROUND(e.p50,4) AS p50_stake, ROUND(e.p75,4) AS p75_stake,
           ROUND(e.p90,4) AS p90_stake, ROUND(e.p95,4) AS p95_stake, ROUND(e.p99,4) AS p99_stake,
           ROUND(e.p50_valid,4) AS p50_valid_bet, ROUND(e.p50_profit,4) AS p50_profit,
           ROUND(e.p95/NULLIF(e.p50,0),6) AS p95_over_p50,
           ROUND(e.p99/NULLIF(e.p50,0),6) AS p99_over_p50,
           ROUND((e.stake/NULLIF(e.n_bets,0))/NULLIF(e.p50,0),6) AS avg_over_p50,
           -- 三·关系层
           e.n_tables AS common_table_count, e.n_dealers AS common_dealer_count,
           e.n_ips AS common_ip_count, e.n_products AS common_product_count,
           ROUND(e.st_in/NULLIF(e.stake,0),8) AS share_post,
           -- 四·rate 层
           ROUND(-e.net/NULLIF(e.stake,0),8) AS hold_rate,
           ROUND(-e.net_in/NULLIF(e.st_in,0),8) AS hold_rate_post,
           ROUND(e.rebate/NULLIF(e.valid,0),8) AS rebate_rate_actual,
           ROUND(e.rbpct,6) AS rebate_pct_config,
           ROUND(e.valid/NULLIF(e.stake,0),6) AS turnover_multiple,
           ROUND(e.freecomm_rate,6) AS free_comm_rate,
           ROUND(e.net_in/NULLIF(e.st_in,0)-e.net_out/NULLIF(e.st_out,0),8) AS roi_delta_post,
           -- 五·动态层
           e.first_seen_d AS first_seen, e.last_seen_d AS last_seen,
           e.active_days, e.active_shoes, e.active_sessions,
           DATEDIFF(e.last_seen_d, e.first_seen_d)+1 AS span_days,
           ROUND(e.active_days*1.0/NULLIF(DATEDIFF(e.last_seen_d,e.first_seen_d)+1,0),6) AS persistence,
           ROUND((e.st_in/NULLIF(e.nb_in,0))/NULLIF(e.st_out/NULLIF(e.nb_out,0),0),6) AS ramp_post,
           ROUND((e.st_rec/NULLIF(e.nb_rec,0))/NULLIF(e.stake/NULLIF(e.n_bets,0),0),6) AS ramp_recent,
           ROUND((e.st_rec/NULLIF(e.stake,0))/0.30,6) AS stake_ramp,
           -- 六·决策层（HF9g-P5 · D-14 斧正 —— 本件属【全窗基线族】，相对刻度与决策标签一律 NULL）
           --   病灶：x_win 系全窗单行聚合（无 GROUP BY，恒 1 行，此为设计使然，非缺陷），
           --         经 CROSS JOIN 接入后 e.* 全行同值；六层之 NTILE / PERCENT_RANK 施于常数即退化，
           --         PERCENT_RANK 恒 0 ⇒ action_priority 恒判 A，全件 100% 误标。
           --   ★ 斧正原则：不给 x_win 补 GROUP BY —— 那会改变其「全窗基线」语义，属退化。
           --     正解与 #018 之 G-05／G-06 同治：范围外之行不得接受任何下游评分与决策标签。
           --   ★ 本件之 e.* 仍照常供其它列作全窗基线使用，仅六层相对刻度与决策标签置 NULL。
           CAST(NULL AS INT)                                              AS vip_tier,                        -- 空值取值：全窗基线族无实体可分档，置 NULL（NULL＝不适用，非 0）
           CAST(NULL AS DOUBLE)                                           AS economic_value,                  -- 空值取值：同上，禁以常数百分位冒充经济价值
           CAST(NULL AS DOUBLE)                                           AS roi_pr_global,                   -- 空值取值：同上
           CAST(NULL AS DOUBLE)                                           AS risk_value,                      -- 空值取值：兼容列，同上
           CAST(NULL AS DOUBLE)                                           AS pr_stake,                        -- 空值取值：兼容列，同上
           CAST(NULL AS DOUBLE)                                           AS pr_global,                       -- 空值取值：同上
           CAST(NULL AS DOUBLE)                                           AS pr_qualified,                    -- 空值取值：同上
           'GLOBAL_BASELINE_NO_ENTITY_RANKING'                            AS pr_qualified_population,         -- 字面取值：血统 —— 明示本件为全窗基线族，无实体排序总体
           CAST(NULL AS BIGINT)                                           AS pr_global_population_n,          -- 空值取值：血统 —— 不适用
           CAST(NULL AS BIGINT)                                           AS pr_qualified_population_n,       -- 空值取值：血统 —— 不适用
           'NOT_APPLICABLE_GLOBAL_BASELINE'                               AS pr_calculation_method,           -- 字面取值：血统 —— 算法不适用
           'HF9g-P5'                                                      AS pr_calculation_version,          -- 字面取值：血统 —— 算法版本
           CAST(NULL AS STRING)                                           AS evidence_flag,                   -- 空值取值：证据旗标不适用于全窗基线
           CAST(NULL AS STRING)                                           AS evidence_rate,                   -- 空值取值：同上
           CAST(NULL AS DOUBLE)                                           AS hold_ci_halfwidth_approx,        -- 空值取值：同上
           'X 全窗基线 · 不参与实体赏罚'                                    AS action_priority                  -- 字面取值：★ D-14 斧正 —— 本族恒不入赏罚，取代原 100% 误标之「A」
    FROM q
    CROSS JOIN x_win e
  ) y
) z
-- ── 逐批 WHERE 阶梯（★ 口诀：上界 ＝ 下界 ＋ 100000，两数同进）──
--    本件 T_true 未测，无需先跑 T_true；以 0 / 100000 控制本批返回区间，末批由实际行数 < 100000 判定
--    WHERE z.audit_rn >        0 AND z.audit_rn <=   100000   -- 第 1 批
--    WHERE z.audit_rn >   100000 AND z.audit_rn <=   200000   -- 第 2 批
--    WHERE z.audit_rn >   200000 AND z.audit_rn <=   300000   -- 第 3 批
--    WHERE z.audit_rn >   300000 AND z.audit_rn <=   400000   -- 第 4 批
--    WHERE z.audit_rn >   400000 AND z.audit_rn <=   500000   -- 第 5 批
--    WHERE z.audit_rn >   500000 AND z.audit_rn <=   600000   -- 第 6 批
--    WHERE z.audit_rn >   600000 AND z.audit_rn <=   700000   -- 第 7 批
--    …余批类推。第 k 批：WHERE z.audit_rn > (k-1)*100000 AND z.audit_rn <= k*100000
--    某批返回 < 100000 行即为末批，其后不再取。
--
--    ⚠ 常见误写（务必避开）：只推下界而上界不动 ——
--        WHERE z.audit_rn > 100000 AND z.audit_rn <= 100000   ← 自相矛盾，恒为假，返回空集
--        WHERE z.audit_rn > 200000 AND z.audit_rn <= 100000   ← 同上，空集
--      两个数必须**同时**前进，且始终相差 100000。
--      下界 ＝ 上一批之上界；上界 ＝ 本批之上界。
WHERE z.audit_rn > 0 AND z.audit_rn <= 100000 -- ★ HF9c 本批区间
ORDER BY z.audit_rn;


-- ══════════════════════════════════════════════════════════════════════════════════════════════
-- 121. Z14_zero_month_diagnosis.csv   [总包行 1026~1130 · 原 23 列 ＋六层约 60 列]
--     典型学：M12 资金轨迹　派生旗标：recent（s.x_rec = 1 · 仅供 CASE 条件聚合，全包无任何 WHERE/AND/HAVING 以此过滤）　连接：q.`member_id`
-- ══════════════════════════════════════════════════════════════════════════════════════════════
-- ── ① 先跑 T_true 留档（不足 100000 者一次导全，不必分批）──
-- ── ① T_true：HF9c 不再强制预跑完整 COUNT。
--    本批实际返回行数 < 100000 即判定为末批；全批完成后以各批 n_rows / audit_rn 范围核对总量。

-- ── ② 分批取数：第 1 批。第 k 批只改末行两数为 (k-1)*100000 与 k*100000 ──
--    审计字段二（REDTEAM 2026-08-24 裁定 · 四锁）：
--      audit_rn  全局观测坐标 —— 由**与原版审计版逐字同一**之排序键所生，两版可逐行对账
--      batch_id  物理分批信息 —— 该行所属批次，由 audit_rn 算得，非引擎所赋
--    ★ 锁三：二者皆为审计字段，**不得进入任何业务指标计算**。
--    ★ 锁四：两版经 audit_rn 逐行字段核验后，方可宣布输出完全一致。

-- ── ③ 每批取回后自证四数（任一不符即停手回报，禁止放行）──
--    n_rows        = COUNT(*)      须等于 COUNT(DISTINCT audit_rn)   （批内无重复）
--    audit_rn_min  = MIN(audit_rn) 须等于 (k-1)*100000 + 1           （与上批严丝合缝）
--    audit_rn_max  = MAX(audit_rn) 须等于 min + n_rows - 1           （批内无缺口）
--    全批取毕再验：各批 audit_rn 之并集 = 1 .. T_true，无缺号、无重号。
--     ★ 首行＝平台真净亏最多者（已扣退水与代理占成）。
--
SELECT z.*,
       CAST(FLOOR((z.audit_rn - 1) / 100000) + 1 AS INT)          AS batch_id,
       'A168_HF9F_20260827_0900' AS run_id,
       '2026-08-27 09:00:00' AS snapshot_sync_time
FROM (
  SELECT y.*,
         ROW_NUMBER() OVER (ORDER BY y.`residual_b` ASC, y.`roi` DESC, y.`member_id`, y.`bet_month`, y.`zero_kind`, y.`vb_sum_state`, y.`n_orders`, y.`n_rounds_month`, y.`n_days_month`, y.`n_tables_month`, y.`n_vb_null`, y.`n_vb_blank`, y.`n_vb_true_zero`, y.`n_vb_positive`, y.`vb_null_share`, y.`sum_valid_bet`, y.`sum_stake`, y.`sum_game_pnl`, y.`sum_rebate`, y.`n_order_nocomm`, y.`n_hedge_rounds`, y.`n_hedge_eq`, y.`n_zero_pnl_rounds`, y.`hedge_eq_share`, y.`verdict_hint`) AS audit_rn
  FROM (
    WITH
      x_ranked AS (
    SELECT b.bet01, b.bet03, b.bet04, b.bet05, b.bet09, b.bet11, b.bet13,
           b.bet15, b.bet16, b.bet17, b.bet18, b.bet19, b.bet20, b.bet21,
           b.bet22, b.bet23, b.bet24, b.bet25, b.bet26, b.bet27, b.bet38, b.bet39, b.category, b.commission,
           b.dt, b.eid, b.ip, b.validbet, b.updatetime, b.sync_time,
           ROW_NUMBER() OVER (
             PARTITION BY b.bet01
             ORDER BY b.updatetime DESC, b.sync_time DESC, b.dt DESC)      AS x_rn
    FROM ods_mariadb_2b.ods_a168_bet02 b
    WHERE b.dt >= '2026-03-21' AND b.dt < '2026-08-07'
      AND b.bet02 = '101'
      AND b.sync_time <= '2026-08-27 09:00:00'
  ),
    x_testagent AS (
    SELECT age001 AS agent_id FROM ods_mariadb_2b.ods_a168_agent WHERE age022 = '1'
  ),
    x_bs0 AS (
    SELECT b.bet05 AS x_member, b.eid AS x_dealer, b.bet39 AS x_table,
           b.bet03 AS x_shoe, b.ip AS x_ip, b.bet09 AS x_product, b.dt AS x_date,
           CONCAT_WS('|', b.bet03, b.bet04, b.bet39)                      AS x_round,
           CONCAT_WS('|', b.bet39, b.bet03)                               AS x_tblshoe,
           CAST(NULLIF(TRIM(b.bet04),'') AS INT)                          AS x_rno,
           CASE WHEN b.dt >= '2026-07-08' THEN 1 ELSE 0 END               AS x_rec,
           CASE WHEN TRIM(b.commission)='1' THEN 1 ELSE 0 END             AS x_freecomm,
           CAST(NULLIF(TRIM(b.bet13),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_stake,
           CAST(NULLIF(TRIM(b.validbet),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_valid,
           CAST(NULLIF(TRIM(b.bet16),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_rebate,
           CAST(NULLIF(TRIM(b.bet17),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_net,
           CAST(NULLIF(TRIM(b.bet15),'') AS DECIMAL(20,6))                AS x_rbpct,
           COALESCE(CAST(NULLIF(TRIM(b.bet23),'') AS DECIMAL(20,6)),0)   AS x_agpct,
          NULLIF(CAST(NULLIF(TRIM(b.bet23),'') AS DECIMAL(20,6)),0)     AS x_rate1,
          NULLIF(CAST(NULLIF(TRIM(b.bet24),'') AS DECIMAL(20,6)),0)     AS x_rate2,
          NULLIF(CAST(NULLIF(TRIM(b.bet25),'') AS DECIMAL(20,6)),0)     AS x_rate3,
          NULLIF(CAST(NULLIF(TRIM(b.bet26),'') AS DECIMAL(20,6)),0)     AS x_rate4,
          NULLIF(CAST(NULLIF(TRIM(b.bet27),'') AS DECIMAL(20,6)),0)     AS x_rate5,
          (CASE WHEN NULLIF(CAST(NULLIF(TRIM(b.bet22),'') AS BIGINT),0) IS NOT NULL THEN 5
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet21),'') AS BIGINT),0) IS NOT NULL THEN 4
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet20),'') AS BIGINT),0) IS NOT NULL THEN 3
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet19),'') AS BIGINT),0) IS NOT NULL THEN 2
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet18),'') AS BIGINT),0) IS NOT NULL THEN 1
                ELSE 0 END)                                             AS x_chain_depth,
           CASE WHEN COALESCE(t1.agent_id,t2.agent_id,t3.agent_id,
                              t4.agent_id,t5.agent_id) IS NOT NULL
                THEN 1 ELSE 0 END                                        AS f_testline
    FROM x_ranked b
    LEFT JOIN x_testagent t1 ON t1.agent_id = b.bet18
    LEFT JOIN x_testagent t2 ON t2.agent_id = b.bet19
    LEFT JOIN x_testagent t3 ON t3.agent_id = b.bet20
    LEFT JOIN x_testagent t4 ON t4.agent_id = b.bet21
    LEFT JOIN x_testagent t5 ON t5.agent_id = b.bet22
    WHERE b.x_rn = 1
      AND b.category='1' AND UPPER(TRIM(b.bet38))='N'
      AND CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8)) > 0
  ),
  x_mk AS (
    SELECT s.*,
           CASE WHEN s.f_testline = 0 THEN 1 ELSE 0 END                 AS is_clean
    FROM x_bs0 s
  ),
  x_agg AS (
    SELECT s.x_member                                                        AS x_key,
           COUNT(*) AS n_bets, COUNT(DISTINCT s.x_round) AS n_rounds,
           COUNT(DISTINCT s.x_date) AS active_days, COUNT(DISTINCT s.x_tblshoe) AS active_shoes,
           COUNT(DISTINCT CONCAT_WS('|', s.x_date, s.x_table)) AS active_sessions,
           COUNT(DISTINCT s.x_table) AS n_tables, COUNT(DISTINCT s.x_dealer) AS n_dealers,
           COUNT(DISTINCT s.x_ip) AS n_ips, COUNT(DISTINCT s.x_product) AS n_products,
           MIN(s.x_date) AS first_seen_d, MAX(s.x_date) AS last_seen_d,
           SUM(s.x_stake) AS stake, SUM(s.x_valid) AS valid, SUM(s.x_rebate) AS rebate,
           SUM(s.x_net) AS net, SUM(-s.x_net *(100.0-s.x_agpct)/100.0) AS agent_cost,
           AVG(100.0-s.x_agpct)                   AS agent_pct,
           AVG(s.x_agpct)                         AS company_retain_pct,
           SUM(-s.x_net *s.x_agpct/100.0)         AS agent_cost_a_legacy,
           SUM(s.x_valid*s.x_agpct/100.0)         AS agent_cost_valid_base_legacy,
          AVG(COALESCE(s.x_rate1,100)) AS retain_pct_lv1, AVG(COALESCE(s.x_rate2,100)) AS retain_pct_lv2,
          AVG(COALESCE(s.x_rate3,100)) AS retain_pct_lv3, AVG(COALESCE(s.x_rate4,100)) AS retain_pct_lv4,
          AVG(COALESCE(s.x_rate5,100)) AS retain_pct_lv5, AVG(s.x_chain_depth) AS chain_depth_avg,
          AVG(COALESCE(100.0-s.x_rate1,0)) AS agent_pct_lv1, AVG(COALESCE(100.0-s.x_rate2,0)) AS agent_pct_lv2,
          AVG(COALESCE(100.0-s.x_rate3,0)) AS agent_pct_lv3, AVG(COALESCE(100.0-s.x_rate4,0)) AS agent_pct_lv4,
          AVG(COALESCE(100.0-s.x_rate5,0)) AS agent_pct_lv5,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate1,0)/100.0)                        AS agent_cost_lv1,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate2,0)/100.0)                        AS agent_cost_lv2,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate3,0)/100.0)                        AS agent_cost_lv3,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate4,0)/100.0)                        AS agent_cost_lv4,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate5,0)/100.0)                        AS agent_cost_lv5,
          SUM(-s.x_net*(COALESCE(100.0-s.x_rate1,0)+COALESCE(100.0-s.x_rate2,0)
                       +COALESCE(100.0-s.x_rate3,0)+COALESCE(100.0-s.x_rate4,0)
                       +COALESCE(100.0-s.x_rate5,0))/100.0)                   AS agent_cost_chain_additive,
          SUM(-s.x_net*(1.0 - CAST(COALESCE(s.x_rate1,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate2,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate3,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate4,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate5,100) AS DOUBLE)/100.0))
                                                                       AS agent_cost_chain_nested,
           AVG(s.x_rbpct) AS rbpct, AVG(s.x_freecomm*1.0) AS freecomm_rate,
           PERCENTILE_APPROX(s.x_stake,0.25) AS p25, PERCENTILE_APPROX(s.x_stake,0.50) AS p50,
           PERCENTILE_APPROX(s.x_stake,0.75) AS p75, PERCENTILE_APPROX(s.x_stake,0.90) AS p90,
           PERCENTILE_APPROX(s.x_stake,0.95) AS p95, PERCENTILE_APPROX(s.x_stake,0.99) AS p99,
           PERCENTILE_APPROX(s.x_valid,0.50) AS p50_valid,
           PERCENTILE_APPROX(s.x_net,0.50)   AS p50_profit,
           SUM(CASE WHEN s.x_rec = 1 THEN s.x_stake ELSE 0 END) AS st_in,
           SUM(CASE WHEN s.x_rec = 1 THEN 1 ELSE 0 END)         AS nb_in,
           SUM(CASE WHEN s.x_rec = 1 THEN s.x_net ELSE 0 END)   AS net_in,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN s.x_stake ELSE 0 END) AS st_out,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN 1 ELSE 0 END)         AS nb_out,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN s.x_net ELSE 0 END)   AS net_out,
           SUM(CASE WHEN s.x_rec=1 THEN s.x_stake ELSE 0 END) AS st_rec,
           SUM(CASE WHEN s.x_rec=1 THEN 1 ELSE 0 END)         AS nb_rec
    FROM x_mk s
    WHERE s.is_clean = 1
      AND s.x_member IS NOT NULL AND TRIM(CAST(s.x_member AS STRING)) <> ''
    GROUP BY s.x_member
  ),
      q AS (
        WITH ta AS (
          SELECT DISTINCT CAST(NULLIF(TRIM(age001),'') AS BIGINT) AS agent_id
          FROM ods_mariadb_2b.ods_a168_agent
          WHERE age022 = '1'
        ),
        ranked AS (
          SELECT b.bet01, b.bet03, b.bet04, b.bet05, b.bet09, b.bet11,
                 b.bet13, b.bet14, b.bet16, b.bet17, b.bet38, b.bet39,
                 b.bet18, b.bet19, b.bet20, b.bet21, b.bet22,
                 b.validbet, b.commission, b.category, b.dt,
                 ROW_NUMBER() OVER (PARTITION BY b.bet01
                   ORDER BY b.updatetime DESC, b.sync_time DESC, b.dt DESC) AS rn
          FROM ods_mariadb_2b.ods_a168_bet02 b
          WHERE b.dt >= '2026-03-21' AND b.dt < '2026-08-07'
            AND b.bet02 = '101'
      AND b.sync_time <= '2026-08-27 09:00:00'
        ),
        base AS (
          SELECT CAST(NULLIF(TRIM(r.bet05),'') AS BIGINT)            AS member_id,
                 DATE_TRUNC('month', r.dt)                           AS bet_month,
                 r.dt                                                AS dt,
                 r.bet39                                             AS table_id,
                 CONCAT_WS('|', r.bet03, r.bet04, r.bet39)           AS round_key,
                 TRIM(r.bet09)                                       AS bet_side,
                 TRIM(r.commission)                                  AS commission,
                 r.validbet                                          AS vb_txt,
                 CAST(NULLIF(TRIM(r.validbet),'') AS DECIMAL(20,4))  AS vb_raw,
                 CAST(NULLIF(TRIM(r.bet13),'')    AS DECIMAL(20,4))  AS stake_raw,
                 CAST(NULLIF(TRIM(r.bet14),'')    AS DECIMAL(20,4))  AS payout_raw,
                 CAST(NULLIF(TRIM(r.bet16),'')    AS DECIMAL(20,4))  AS rebate_raw,
                 CAST(NULLIF(TRIM(r.bet11),'')    AS DECIMAL(20,8))  AS fx
          FROM ranked r
          LEFT JOIN ta t1 ON t1.agent_id = CAST(NULLIF(TRIM(r.bet18),'') AS BIGINT)
          LEFT JOIN ta t2 ON t2.agent_id = CAST(NULLIF(TRIM(r.bet19),'') AS BIGINT)
          LEFT JOIN ta t3 ON t3.agent_id = CAST(NULLIF(TRIM(r.bet20),'') AS BIGINT)
          LEFT JOIN ta t4 ON t4.agent_id = CAST(NULLIF(TRIM(r.bet21),'') AS BIGINT)
          LEFT JOIN ta t5 ON t5.agent_id = CAST(NULLIF(TRIM(r.bet22),'') AS BIGINT)
          WHERE r.rn = 1
            AND r.category = '1'
            AND UPPER(TRIM(r.bet38)) = 'N'
            AND CAST(NULLIF(TRIM(r.bet05),'') AS BIGINT) > 0
            AND CAST(NULLIF(TRIM(r.bet11),'') AS DECIMAL(20,8)) > 0
            AND COALESCE(t1.agent_id,t2.agent_id,t3.agent_id,t4.agent_id,t5.agent_id) IS NULL
        ),
        rnd AS (
          SELECT member_id, bet_month, round_key,
                 MAX(CASE WHEN bet_side = 'Banker' THEN 1 ELSE 0 END) AS has_b,
                 MAX(CASE WHEN bet_side = 'Player' THEN 1 ELSE 0 END) AS has_p,
                 SUM(CASE WHEN bet_side = 'Banker' THEN stake_raw/fx ELSE 0 END) AS stk_b,
                 SUM(CASE WHEN bet_side = 'Player' THEN stake_raw/fx ELSE 0 END) AS stk_p,
                 SUM((payout_raw - stake_raw)/fx)                                AS pnl_rnd
          FROM base
          GROUP BY member_id, bet_month, round_key
        ),
        mm AS (
          SELECT member_id, bet_month,
                 COUNT(*)                                                          AS n_orders,
                 COUNT(DISTINCT round_key)                                         AS n_rounds_month,
                 COUNT(DISTINCT dt)                                                AS n_days_month,
                 COUNT(DISTINCT table_id)                                          AS n_tables_month,
                 SUM(CASE WHEN vb_txt IS NULL THEN 1 ELSE 0 END)                   AS n_vb_null,
                 SUM(CASE WHEN vb_txt IS NOT NULL AND TRIM(vb_txt) = '' THEN 1 ELSE 0 END)
                                                                                   AS n_vb_blank,
                 SUM(CASE WHEN vb_raw = 0 THEN 1 ELSE 0 END)                       AS n_vb_true_zero,
                 SUM(CASE WHEN vb_raw > 0 THEN 1 ELSE 0 END)                       AS n_vb_positive,
                 SUM(vb_raw / fx)                                                  AS sum_valid_bet,
                 SUM(stake_raw / fx)                                               AS sum_stake,
                 SUM((payout_raw - stake_raw) / fx)                                AS sum_game_pnl,
                 SUM(rebate_raw / fx)                                              AS sum_rebate,
                 SUM(CASE WHEN commission = '1' THEN 1 ELSE 0 END)                 AS n_order_nocomm
          FROM base
          GROUP BY member_id, bet_month
        ),
        hg AS (
          SELECT member_id, bet_month,
                 SUM(CASE WHEN has_b = 1 AND has_p = 1 THEN 1 ELSE 0 END)          AS n_hedge_rounds,
                 SUM(CASE WHEN has_b = 1 AND has_p = 1 AND stk_b = stk_p
                          THEN 1 ELSE 0 END)                                       AS n_hedge_eq,
                 SUM(CASE WHEN pnl_rnd = 0 THEN 1 ELSE 0 END)                       AS n_zero_pnl_rounds
          FROM rnd
          GROUP BY member_id, bet_month
        )
        SELECT m.member_id                                                         AS member_id,
               m.bet_month                                                         AS bet_month,
               CASE WHEN COALESCE(m.sum_valid_bet,0) = 0 AND COALESCE(m.sum_game_pnl,0) = 0
                         THEN '洗码与输赢皆为零'
                    WHEN COALESCE(m.sum_valid_bet,0) = 0 THEN '洗码贡献为零'
                    ELSE '游戏输赢为零' END                                          AS zero_kind,
               CASE WHEN m.sum_valid_bet IS NULL THEN 'NULL' ELSE '有值' END        AS vb_sum_state,
               m.n_orders, m.n_rounds_month, m.n_days_month, m.n_tables_month,
               m.n_vb_null, m.n_vb_blank, m.n_vb_true_zero, m.n_vb_positive,
               m.n_vb_null * 1.0 / NULLIF(m.n_orders,0)                            AS vb_null_share,
               m.sum_valid_bet, m.sum_stake, m.sum_game_pnl, m.sum_rebate,
               m.n_order_nocomm,
               h.n_hedge_rounds, h.n_hedge_eq, h.n_zero_pnl_rounds,
               h.n_hedge_eq * 1.0 / NULLIF(m.n_rounds_month,0)                     AS hedge_eq_share,
               CASE WHEN COALESCE(m.n_vb_null,0) + COALESCE(m.n_vb_blank,0) > 0 THEN '支持①NULL抹平'
                    WHEN COALESCE(h.n_hedge_eq,0) > 0                              THEN '支持②自对押真实零'
                    ELSE '两者皆低·判UNKNOWN' END                                    AS verdict_hint
        FROM mm m
        JOIN hg h ON h.member_id = m.member_id AND h.bet_month = m.bet_month
        WHERE COALESCE(m.sum_valid_bet,0) = 0
           OR m.sum_valid_bet IS NULL
           OR m.sum_game_pnl = 0
           OR m.sum_game_pnl IS NULL
      )
    SELECT q.*,
           -- 一·经济层
           ROUND(e.stake,4) AS stake, ROUND(e.valid,4) AS valid_bet,
           ROUND(-e.net,4) AS profit, e.n_bets, e.n_rounds,
           ROUND(e.net/NULLIF(e.stake,0),8) AS roi,
           ROUND(e.net_in/NULLIF(e.st_in,0),8) AS roi_recent,
           ROUND(e.net_out/NULLIF(e.st_out,0),8) AS roi_non_recent,
           ROUND((e.net-e.rebate)/NULLIF(e.stake,0),8) AS roi_ex_rebate,
           ROUND(e.net,4) AS roi_numerator, ROUND(e.stake,4) AS roi_denominator,
           CASE WHEN e.stake IS NULL THEN 'NULL_DENOM' WHEN e.stake<=0 THEN 'ZERO_DENOM'
                WHEN e.n_bets<30 THEN 'THIN_EXPOSURE' ELSE 'OK' END AS roi_denominator_status,
           ROUND(e.rebate,4) AS rebate_cost, ROUND(e.agent_cost,4)                           AS cost_complement_b,
       ROUND(e.agent_pct,4)                            AS pct_complement,
       ROUND(e.company_retain_pct,4)                   AS pct_top_bet23,
       'AG03-UNRESOLVED'                                     AS agent_formula_version,
      'ALL5_LEVELS_bet23_to_bet27'                    AS agent_level_scope,
      ROUND(e.agent_cost_lv1,4) AS agent_cost_lv1, ROUND(e.agent_cost_lv2,4) AS agent_cost_lv2,
      ROUND(e.agent_cost_lv3,4) AS agent_cost_lv3, ROUND(e.agent_cost_lv4,4) AS agent_cost_lv4,
      ROUND(e.agent_cost_lv5,4) AS agent_cost_lv5,
      ROUND(e.agent_pct_lv1,6) AS agent_pct_lv1, ROUND(e.agent_pct_lv2,6) AS agent_pct_lv2,
      ROUND(e.agent_pct_lv3,6) AS agent_pct_lv3, ROUND(e.agent_pct_lv4,6) AS agent_pct_lv4,
      ROUND(e.agent_pct_lv5,6) AS agent_pct_lv5,
      ROUND(e.retain_pct_lv1,6) AS retain_pct_lv1, ROUND(e.retain_pct_lv2,6) AS retain_pct_lv2,
      ROUND(e.retain_pct_lv3,6) AS retain_pct_lv3, ROUND(e.retain_pct_lv4,6) AS retain_pct_lv4,
      ROUND(e.retain_pct_lv5,6) AS retain_pct_lv5, ROUND(e.chain_depth_avg,4) AS chain_depth_avg,
      ROUND(e.agent_cost_chain_additive,4)            AS agent_cost_chain_additive,
      ROUND(e.agent_cost_chain_nested,4)              AS agent_cost_chain_nested,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_additive,4) AS residual_chain_additive,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_nested,4)   AS residual_chain_nested,
      'PENDING_AG03'                                  AS decision_status,
      'FALSE'                                         AS admit_to_risk_decision,
      'NOT_FOR_ENFORCEMENT'                           AS deliverable_class,
       ROUND(e.agent_cost_a_legacy,4)                  AS agent_cost_a_legacy,
       ROUND(e.agent_cost_valid_base_legacy,4)         AS agent_cost_valid_base_legacy,
           ROUND(-e.net-e.rebate,4)                        AS ngr,
       ROUND(-e.net-e.rebate-e.agent_cost,4)           AS residual_b,
       ROUND(-e.net-e.rebate-e.agent_cost_a_legacy,4)  AS residual_a,
           ROUND((-e.net-e.rebate)/NULLIF(e.stake,0),8)    AS ngr_rate,
       ROUND((-e.net-e.rebate-e.agent_cost)/NULLIF(e.stake,0),8)   AS residual_b_rate,
      -- 【HF9c · canonical accounting contract】
      --   以下 canonical 字段只增加明确 scope；不删除、不覆盖既有字段。
      --   formal_bet23_* 保持 HF9b 当前生产公式及其 NULL/0 语义；
      --   lv1~lv5 / additive / nested 则分别采用各自原始 e.* 成本字段，
      --   rate 一律从未舍入的 e.* 分子 / e.stake 计算，禁止由展示值反算。
      ROUND(e.agent_cost,4) AS agent_cost_bet23_formal_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost,4) AS net_margin_bet23_formal_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost)/NULLIF(e.stake,0),8) AS net_margin_bet23_formal_rate_canonical,
      ROUND(e.agent_cost_lv1,4) AS agent_cost_lv1_bet23_canonical,
      ROUND(e.agent_cost_lv2,4) AS agent_cost_lv2_bet24_canonical,
      ROUND(e.agent_cost_lv3,4) AS agent_cost_lv3_bet25_canonical,
      ROUND(e.agent_cost_lv4,4) AS agent_cost_lv4_bet26_canonical,
      ROUND(e.agent_cost_lv5,4) AS agent_cost_lv5_bet27_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_lv1,4) AS net_margin_lv1_bet23_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_lv1)/NULLIF(e.stake,0),8) AS net_margin_lv1_bet23_rate_canonical,
      ROUND(e.agent_cost_chain_additive,4) AS agent_cost_chain_additive_canonical,
      ROUND(e.agent_cost_chain_nested,4) AS agent_cost_chain_nested_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_additive,4) AS net_margin_chain_additive_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_nested,4) AS net_margin_chain_nested_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_chain_additive)/NULLIF(e.stake,0),8) AS net_margin_chain_additive_rate_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_chain_nested)/NULLIF(e.stake,0),8) AS net_margin_chain_nested_rate_canonical,
       ROUND((-e.net-e.rebate-e.agent_cost_a_legacy)/NULLIF(e.stake,0),8) AS residual_a_rate,
           -- 二·分布层
           ROUND(e.stake/NULLIF(e.n_bets,0),4) AS avg_stake_per_bet,
           ROUND(e.valid/NULLIF(e.n_rounds,0),4) AS avg_valid_bet_per_round,
           ROUND(-e.net/NULLIF(e.n_rounds,0),4) AS avg_profit_per_round,
           ROUND(-e.net/NULLIF(e.active_days,0),4) AS avg_profit_per_day,
           ROUND(-e.net/NULLIF(e.active_shoes,0),4) AS avg_profit_per_shoe,
           ROUND(e.stake/NULLIF(e.active_days,0),4) AS avg_stake_per_active_day,
           ROUND(e.n_rounds*1.0/NULLIF(e.active_days,0),4) AS avg_rounds_per_active_day,
           ROUND(e.st_in/NULLIF(e.nb_in,0),4) AS avg_stake_recent,
           ROUND(e.st_out/NULLIF(e.nb_out,0),4) AS avg_stake_non_recent,
           ROUND(e.p25,4) AS p25_stake, ROUND(e.p50,4) AS p50_stake, ROUND(e.p75,4) AS p75_stake,
           ROUND(e.p90,4) AS p90_stake, ROUND(e.p95,4) AS p95_stake, ROUND(e.p99,4) AS p99_stake,
           ROUND(e.p50_valid,4) AS p50_valid_bet, ROUND(e.p50_profit,4) AS p50_profit,
           ROUND(e.p95/NULLIF(e.p50,0),6) AS p95_over_p50,
           ROUND(e.p99/NULLIF(e.p50,0),6) AS p99_over_p50,
           ROUND((e.stake/NULLIF(e.n_bets,0))/NULLIF(e.p50,0),6) AS avg_over_p50,
           -- 三·关系层
           e.n_tables AS common_table_count, e.n_dealers AS common_dealer_count,
           e.n_ips AS common_ip_count, e.n_products AS common_product_count,
           ROUND(e.st_in/NULLIF(e.stake,0),8) AS share_recent,
           -- 四·rate 层
           ROUND(-e.net/NULLIF(e.stake,0),8) AS hold_rate,
           ROUND(-e.net_in/NULLIF(e.st_in,0),8) AS hold_rate_recent,
           ROUND(e.rebate/NULLIF(e.valid,0),8) AS rebate_rate_actual,
           ROUND(e.rbpct,6) AS rebate_pct_config,
           ROUND(e.valid/NULLIF(e.stake,0),6) AS turnover_multiple,
           ROUND(e.freecomm_rate,6) AS free_comm_rate,
           ROUND(e.net_in/NULLIF(e.st_in,0)-e.net_out/NULLIF(e.st_out,0),8) AS roi_delta_recent,
           -- 五·动态层
           e.first_seen_d AS first_seen, e.last_seen_d AS last_seen,
           e.active_days, e.active_shoes, e.active_sessions,
           DATEDIFF(e.last_seen_d, e.first_seen_d)+1 AS span_days,
           ROUND(e.active_days*1.0/NULLIF(DATEDIFF(e.last_seen_d,e.first_seen_d)+1,0),6) AS persistence,
           ROUND((e.st_in/NULLIF(e.nb_in,0))/NULLIF(e.st_out/NULLIF(e.nb_out,0),0),6) AS ramp_recent_vs_prior,
           ROUND((e.st_rec/NULLIF(e.nb_rec,0))/NULLIF(e.stake/NULLIF(e.n_bets,0),0),6) AS ramp_recent_vs_all,
           ROUND((e.st_rec/NULLIF(e.stake,0))/0.30,6) AS stake_ramp,
           -- 六·决策层（HF9f · 详见档头【HF9f 变更说明】；本段两版逐字同一）
           NTILE(5) OVER (ORDER BY e.stake) AS vip_tier,                                                        -- 窗口取值：相对刻度 B 族，全体五等分；须连同下方血统五元组一并解读，禁作硬阈值判型
           PERCENT_RANK() OVER (ORDER BY -e.net-e.rebate-e.agent_cost)    AS economic_value,                    -- 窗口取值：HF9f·F-19 修正 —— HF9e 写作 -(-…) 双负号致方向颠倒（#075 实测 corr(economic_value, residual_b) = -1.0000）；今与 action_priority 排序键归一，值大即平台真净利高
           PERCENT_RANK() OVER (ORDER BY e.net/NULLIF(e.stake,0))         AS roi_pr_global,                     -- 窗口取值：HF9f·F-17 正名 —— 本列实为 ROI（玩家净回报率）之全体百分位，与「风险」无关；旧名 risk_value 见下一行
           PERCENT_RANK() OVER (ORDER BY e.net/NULLIF(e.stake,0))         AS risk_value,                        -- 窗口取值：兼容列，恒等于 roi_pr_global，仅为下游迁移窗保留；HF9g 起废弃，禁新引用
           PERCENT_RANK() OVER (ORDER BY e.stake)                         AS pr_stake,                          -- 窗口取值：兼容列，恒等于 pr_global，原名保留以免断链
           PERCENT_RANK() OVER (ORDER BY e.stake)                         AS pr_global,                         -- 窗口取值：HF9f·F-1 双轨之一 —— 全体口径百分位，参照总体即本件全部输出行
           CASE WHEN e.n_rounds >= 30                                                                           -- 条件分支：起始分支 —— 仅在合格子集内计算合格口径百分位
                  THEN PERCENT_RANK() OVER (PARTITION BY CASE WHEN e.n_rounds >= 30 THEN 1 ELSE 0 END ORDER BY e.stake)  -- 分支取值：以合格与否分区，故本值即 n_rounds>=30 子集内之百分位
                ELSE NULL END                                             AS pr_qualified,                      -- 条件分支：收束上方分支 —— 不合格者留 NULL（NULL＝未测，非 0），产出「pr_qualified」
           'n_rounds>=30'                                                 AS pr_qualified_population,           -- 字面取值：血统 —— 合格子集之定义
           COUNT(*) OVER ()                                               AS pr_global_population_n,            -- 窗口取值：血统 —— 全体口径之参照总体规模，渲染时现算，禁写死
           SUM(CASE WHEN e.n_rounds >= 30 THEN 1 ELSE 0 END) OVER ()      AS pr_qualified_population_n,         -- 窗口取值：血统 —— 合格子集之参照总体规模，现算，禁写死
           'PERCENT_RANK_OVER_ORDER_BY_e_stake'                           AS pr_calculation_method,             -- 字面取值：血统 —— 算法标识
           'HF9f'                                                         AS pr_calculation_version,            -- 字面取值：血统 —— 算法版本
           CASE WHEN e.n_rounds IS NULL OR e.n_rounds < 30 THEN 'THIN_ROUNDS' ELSE 'OK' END AS evidence_flag,   -- 条件分支：HF9f·F-2a 证据旗标 —— THIN_ROUNDS 者禁入执行队列，仅入观察队列
           CASE WHEN e.n_rounds IS NULL       THEN NULL                                                         -- 条件分支：起始分支 —— 未测者留 NULL（自家铁律：NULL ≠ 0）
                WHEN e.n_rounds >= 31483      THEN 'L1_POWERED'                                                 -- 分支判定：MDE 反解第一档
                WHEN e.n_rounds >= 15409      THEN 'L2_CI_1P5'                                                  -- 分支判定：MDE 反解第二档
                WHEN e.n_rounds >=  8668      THEN 'L3_CI_2P0'                                                  -- 分支判定：MDE 反解第三档
                WHEN e.n_rounds >=  3852      THEN 'L4_CI_3P0'                                                  -- 分支判定：MDE 反解第四档
                ELSE 'L5_INSUFFICIENT' END                                AS evidence_rate,                     -- 条件分支：收束上方 —— HF9f·F-3 证据分档，承 HF9e 前议之 MDE 反解五档，须于 F-4 敏感性实验后复核
           ROUND(1.96 * 0.95 / SQRT(NULLIF(CAST(e.n_rounds AS DOUBLE),0)),8) AS hold_ci_halfwidth_approx,       -- 比率表达式：HF9f·F-3 逐行现算之 95% 半宽近似；常数 0.95 为登记值，本轮 #075 实测每局 ROI 隐含 σ 于最薄层为 0.9249，二者差异待 F-4 裁定
           CASE WHEN e.stake IS NULL OR e.stake<=0 OR e.n_bets<30 OR e.n_rounds IS NULL OR e.n_rounds<30 THEN 'Z 证据不足 · 不动作'  -- 条件分支：HF9f·F-2 双条件取严 —— HF9e 仅卡 e.n_bets<30，致 n_bets>=30 而 n_rounds<30 者绕过 Z（#075 实测 18,537 名，其中 8,145 名已入 A/D 待裁）；今两条件并列取严
                WHEN PERCENT_RANK() OVER (ORDER BY -e.net-e.rebate-e.agent_cost)<=0.10                          -- 分支判定：平台真净利之最低十分位
                  THEN 'A 净亏最大十分位 · 优先复核'                                                             -- 分支取值：HF9f·F-20 正名 —— 本档 Σresidual_b 于 #075 实测 = -100,236,896，系平台净亏最大群，旧名「残值最低十分位 · 待裁」名实不符
                WHEN PERCENT_RANK() OVER (ORDER BY -e.net-e.rebate-e.agent_cost)>=0.80                          -- 分支判定：平台真净利之最高二十分位
                  THEN 'D 净利最高二十分位 · 优先留存'                                                           -- 分支取值：HF9f·F-20 正名 —— 本档 Σresidual_b 于 #075 实测 = +281,733,190，系核心利润源；与 A 档方向相反，旧版同标「待裁」属名实不符
                ELSE 'E 常规' END                                          AS action_priority                   -- 条件分支：收束上方判词，产出「action_priority」
    FROM q
    LEFT JOIN x_agg e ON CAST(e.x_key AS STRING) = CAST(q.`member_id` AS STRING)
  ) y
) z
-- ── 逐批 WHERE 阶梯（★ 口诀：上界 ＝ 下界 ＋ 100000，两数同进）──
--    本件 T_true 未测，无需先跑 T_true；以 0 / 100000 控制本批返回区间，末批由实际行数 < 100000 判定
--    WHERE z.audit_rn >        0 AND z.audit_rn <=   100000   -- 第 1 批
--    WHERE z.audit_rn >   100000 AND z.audit_rn <=   200000   -- 第 2 批
--    WHERE z.audit_rn >   200000 AND z.audit_rn <=   300000   -- 第 3 批
--    WHERE z.audit_rn >   300000 AND z.audit_rn <=   400000   -- 第 4 批
--    WHERE z.audit_rn >   400000 AND z.audit_rn <=   500000   -- 第 5 批
--    WHERE z.audit_rn >   500000 AND z.audit_rn <=   600000   -- 第 6 批
--    WHERE z.audit_rn >   600000 AND z.audit_rn <=   700000   -- 第 7 批
--    …余批类推。第 k 批：WHERE z.audit_rn > (k-1)*100000 AND z.audit_rn <= k*100000
--    某批返回 < 100000 行即为末批，其后不再取。
--
--    ⚠ 常见误写（务必避开）：只推下界而上界不动 ——
--        WHERE z.audit_rn > 100000 AND z.audit_rn <= 100000   ← 自相矛盾，恒为假，返回空集
--        WHERE z.audit_rn > 200000 AND z.audit_rn <= 100000   ← 同上，空集
--      两个数必须**同时**前进，且始终相差 100000。
--      下界 ＝ 上一批之上界；上界 ＝ 本批之上界。
WHERE z.audit_rn > 0 AND z.audit_rn <= 100000 -- ★ HF9c 本批区间
ORDER BY z.audit_rn;


-- ══════════════════════════════════════════════════════════════════════════════════════════════
-- 122. _P12b-pre.csv   [总包行 9791~9799 · 原 4 列 ＋六层约 60 列]
--     典型学：M09 处置限额　派生旗标：post（s.x_rec = 1 · 仅供 CASE 条件聚合，全包无任何 WHERE/AND/HAVING 以此过滤）　连接：q.`member_id`
-- ══════════════════════════════════════════════════════════════════════════════════════════════
-- ── ① 先跑 T_true 留档（不足 100000 者一次导全，不必分批）──
-- ── ① T_true：HF9c 不再强制预跑完整 COUNT。
--    本批实际返回行数 < 100000 即判定为末批；全批完成后以各批 n_rows / audit_rn 范围核对总量。

-- ── ② 分批取数：第 1 批。第 k 批只改末行两数为 (k-1)*100000 与 k*100000 ──
--    审计字段二（REDTEAM 2026-08-24 裁定 · 四锁）：
--      audit_rn  全局观测坐标 —— 由**与原版审计版逐字同一**之排序键所生，两版可逐行对账
--      batch_id  物理分批信息 —— 该行所属批次，由 audit_rn 算得，非引擎所赋
--    ★ 锁三：二者皆为审计字段，**不得进入任何业务指标计算**。
--    ★ 锁四：两版经 audit_rn 逐行字段核验后，方可宣布输出完全一致。

-- ── ③ 每批取回后自证四数（任一不符即停手回报，禁止放行）──
--    n_rows        = COUNT(*)      须等于 COUNT(DISTINCT audit_rn)   （批内无重复）
--    audit_rn_min  = MIN(audit_rn) 须等于 (k-1)*100000 + 1           （与上批严丝合缝）
--    audit_rn_max  = MAX(audit_rn) 须等于 min + n_rows - 1           （批内无缺口）
--    全批取毕再验：各批 audit_rn 之并集 = 1 .. T_true，无缺号、无重号。
--     ★ 首行＝平台真净亏最多者（已扣退水与代理占成）。
--
SELECT z.*,
       CAST(FLOOR((z.audit_rn - 1) / 100000) + 1 AS INT)          AS batch_id,
       'A168_HF9F_20260827_0900' AS run_id,
       '2026-08-27 09:00:00' AS snapshot_sync_time
FROM (
  SELECT y.*,
         ROW_NUMBER() OVER (ORDER BY y.`residual_b` ASC, y.`roi` DESC, y.`member_id`, y.`action`, y.`content`, y.`action_time`) AS audit_rn
  FROM (
    WITH
      x_ranked AS (
    SELECT b.bet01, b.bet03, b.bet04, b.bet05, b.bet09, b.bet11, b.bet13,
           b.bet15, b.bet16, b.bet17, b.bet18, b.bet19, b.bet20, b.bet21,
           b.bet22, b.bet23, b.bet24, b.bet25, b.bet26, b.bet27, b.bet38, b.bet39, b.category, b.commission,
           b.dt, b.eid, b.ip, b.validbet, b.updatetime, b.sync_time,
           ROW_NUMBER() OVER (
             PARTITION BY b.bet01
             ORDER BY b.updatetime DESC, b.sync_time DESC, b.dt DESC)      AS x_rn
    FROM ods_mariadb_2b.ods_a168_bet02 b
    WHERE b.dt >= '2026-03-21' AND b.dt < '2026-08-07'
      AND b.bet02 = '101'
      AND b.sync_time <= '2026-08-27 09:00:00'
  ),
    x_testagent AS (
    SELECT age001 AS agent_id FROM ods_mariadb_2b.ods_a168_agent WHERE age022 = '1'
  ),
    x_bs0 AS (
    SELECT b.bet05 AS x_member, b.eid AS x_dealer, b.bet39 AS x_table,
           b.bet03 AS x_shoe, b.ip AS x_ip, b.bet09 AS x_product, b.dt AS x_date,
           CONCAT_WS('|', b.bet03, b.bet04, b.bet39)                      AS x_round,
           CONCAT_WS('|', b.bet39, b.bet03)                               AS x_tblshoe,
           CAST(NULLIF(TRIM(b.bet04),'') AS INT)                          AS x_rno,
           CASE WHEN b.dt >= '2026-07-08' THEN 1 ELSE 0 END               AS x_rec,
           CASE WHEN TRIM(b.commission)='1' THEN 1 ELSE 0 END             AS x_freecomm,
           CAST(NULLIF(TRIM(b.bet13),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_stake,
           CAST(NULLIF(TRIM(b.validbet),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_valid,
           CAST(NULLIF(TRIM(b.bet16),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_rebate,
           CAST(NULLIF(TRIM(b.bet17),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_net,
           CAST(NULLIF(TRIM(b.bet15),'') AS DECIMAL(20,6))                AS x_rbpct,
           COALESCE(CAST(NULLIF(TRIM(b.bet23),'') AS DECIMAL(20,6)),0)   AS x_agpct,
          NULLIF(CAST(NULLIF(TRIM(b.bet23),'') AS DECIMAL(20,6)),0)     AS x_rate1,
          NULLIF(CAST(NULLIF(TRIM(b.bet24),'') AS DECIMAL(20,6)),0)     AS x_rate2,
          NULLIF(CAST(NULLIF(TRIM(b.bet25),'') AS DECIMAL(20,6)),0)     AS x_rate3,
          NULLIF(CAST(NULLIF(TRIM(b.bet26),'') AS DECIMAL(20,6)),0)     AS x_rate4,
          NULLIF(CAST(NULLIF(TRIM(b.bet27),'') AS DECIMAL(20,6)),0)     AS x_rate5,
          (CASE WHEN NULLIF(CAST(NULLIF(TRIM(b.bet22),'') AS BIGINT),0) IS NOT NULL THEN 5
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet21),'') AS BIGINT),0) IS NOT NULL THEN 4
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet20),'') AS BIGINT),0) IS NOT NULL THEN 3
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet19),'') AS BIGINT),0) IS NOT NULL THEN 2
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet18),'') AS BIGINT),0) IS NOT NULL THEN 1
                ELSE 0 END)                                             AS x_chain_depth,
           CASE WHEN COALESCE(t1.agent_id,t2.agent_id,t3.agent_id,
                              t4.agent_id,t5.agent_id) IS NOT NULL
                THEN 1 ELSE 0 END                                        AS f_testline
    FROM x_ranked b
    LEFT JOIN x_testagent t1 ON t1.agent_id = b.bet18
    LEFT JOIN x_testagent t2 ON t2.agent_id = b.bet19
    LEFT JOIN x_testagent t3 ON t3.agent_id = b.bet20
    LEFT JOIN x_testagent t4 ON t4.agent_id = b.bet21
    LEFT JOIN x_testagent t5 ON t5.agent_id = b.bet22
    WHERE b.x_rn = 1
      AND b.category='1' AND UPPER(TRIM(b.bet38))='N'
      AND CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8)) > 0
  ),
  x_mk AS (
    SELECT s.*,
           CASE WHEN s.f_testline = 0 THEN 1 ELSE 0 END                 AS is_clean
    FROM x_bs0 s
  ),
  x_agg AS (
    SELECT s.x_member                                                        AS x_key,
           COUNT(*) AS n_bets, COUNT(DISTINCT s.x_round) AS n_rounds,
           COUNT(DISTINCT s.x_date) AS active_days, COUNT(DISTINCT s.x_tblshoe) AS active_shoes,
           COUNT(DISTINCT CONCAT_WS('|', s.x_date, s.x_table)) AS active_sessions,
           COUNT(DISTINCT s.x_table) AS n_tables, COUNT(DISTINCT s.x_dealer) AS n_dealers,
           COUNT(DISTINCT s.x_ip) AS n_ips, COUNT(DISTINCT s.x_product) AS n_products,
           MIN(s.x_date) AS first_seen_d, MAX(s.x_date) AS last_seen_d,
           SUM(s.x_stake) AS stake, SUM(s.x_valid) AS valid, SUM(s.x_rebate) AS rebate,
           SUM(s.x_net) AS net, SUM(-s.x_net *(100.0-s.x_agpct)/100.0) AS agent_cost,
           AVG(100.0-s.x_agpct)                   AS agent_pct,
           AVG(s.x_agpct)                         AS company_retain_pct,
           SUM(-s.x_net *s.x_agpct/100.0)         AS agent_cost_a_legacy,
           SUM(s.x_valid*s.x_agpct/100.0)         AS agent_cost_valid_base_legacy,
          AVG(COALESCE(s.x_rate1,100)) AS retain_pct_lv1, AVG(COALESCE(s.x_rate2,100)) AS retain_pct_lv2,
          AVG(COALESCE(s.x_rate3,100)) AS retain_pct_lv3, AVG(COALESCE(s.x_rate4,100)) AS retain_pct_lv4,
          AVG(COALESCE(s.x_rate5,100)) AS retain_pct_lv5, AVG(s.x_chain_depth) AS chain_depth_avg,
          AVG(COALESCE(100.0-s.x_rate1,0)) AS agent_pct_lv1, AVG(COALESCE(100.0-s.x_rate2,0)) AS agent_pct_lv2,
          AVG(COALESCE(100.0-s.x_rate3,0)) AS agent_pct_lv3, AVG(COALESCE(100.0-s.x_rate4,0)) AS agent_pct_lv4,
          AVG(COALESCE(100.0-s.x_rate5,0)) AS agent_pct_lv5,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate1,0)/100.0)                        AS agent_cost_lv1,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate2,0)/100.0)                        AS agent_cost_lv2,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate3,0)/100.0)                        AS agent_cost_lv3,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate4,0)/100.0)                        AS agent_cost_lv4,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate5,0)/100.0)                        AS agent_cost_lv5,
          SUM(-s.x_net*(COALESCE(100.0-s.x_rate1,0)+COALESCE(100.0-s.x_rate2,0)
                       +COALESCE(100.0-s.x_rate3,0)+COALESCE(100.0-s.x_rate4,0)
                       +COALESCE(100.0-s.x_rate5,0))/100.0)                   AS agent_cost_chain_additive,
          SUM(-s.x_net*(1.0 - CAST(COALESCE(s.x_rate1,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate2,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate3,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate4,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate5,100) AS DOUBLE)/100.0))
                                                                       AS agent_cost_chain_nested,
           AVG(s.x_rbpct) AS rbpct, AVG(s.x_freecomm*1.0) AS freecomm_rate,
           PERCENTILE_APPROX(s.x_stake,0.25) AS p25, PERCENTILE_APPROX(s.x_stake,0.50) AS p50,
           PERCENTILE_APPROX(s.x_stake,0.75) AS p75, PERCENTILE_APPROX(s.x_stake,0.90) AS p90,
           PERCENTILE_APPROX(s.x_stake,0.95) AS p95, PERCENTILE_APPROX(s.x_stake,0.99) AS p99,
           PERCENTILE_APPROX(s.x_valid,0.50) AS p50_valid,
           PERCENTILE_APPROX(s.x_net,0.50)   AS p50_profit,
           SUM(CASE WHEN s.x_rec = 1 THEN s.x_stake ELSE 0 END) AS st_in,
           SUM(CASE WHEN s.x_rec = 1 THEN 1 ELSE 0 END)         AS nb_in,
           SUM(CASE WHEN s.x_rec = 1 THEN s.x_net ELSE 0 END)   AS net_in,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN s.x_stake ELSE 0 END) AS st_out,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN 1 ELSE 0 END)         AS nb_out,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN s.x_net ELSE 0 END)   AS net_out,
           SUM(CASE WHEN s.x_rec=1 THEN s.x_stake ELSE 0 END) AS st_rec,
           SUM(CASE WHEN s.x_rec=1 THEN 1 ELSE 0 END)         AS nb_rec
    FROM x_mk s
    WHERE s.is_clean = 1
      AND s.x_member IS NOT NULL AND TRIM(CAST(s.x_member AS STRING)) <> ''
    GROUP BY s.x_member
  ),
      q AS (
        SELECT  CAST(lmc02 AS STRING)                AS member_id,                                          -- 取值表达式：取用 lmc02（被改会员号），产出「member_id」
                CAST(lmc04 AS STRING)                AS action,                                             -- 取值表达式：取用 lmc04（动作类别），产出「action」
                CAST(lmc05 AS STRING)                AS content,                                            -- 取值表达式：取用 lmc05（变更内容串），产出「content」——目检对象
                CAST(lmc08 AS STRING)                AS action_time                                         -- 取值表达式：取用 lmc08（操作时间），产出「action_time」
        FROM    ods_mariadb_2b.ods_a168_log_mem_change                                                      -- 取数来源：取自会员变更日志表（与 §TL-14 同源）
        WHERE   dt >= '2026-03-21' AND dt < '2026-08-07'                                                    -- 过滤条件：限定全局窗，涉 dt（营业日）
          AND   ( CAST(lmc05 AS STRING) LIKE '%mem016%'                                                     -- 并列条件：粗筛含 mem016（enable）之变更串
               OR CAST(lmc05 AS STRING) LIKE '%mem017%' )                                                   -- 并列条件：或含 mem017（canbet）之变更串
        LIMIT 20                                                                                           -- 行数上限：只看屏幕 20 行，目检段式后再定 §P12b 谓词
      )
    SELECT q.*,
           -- 一·经济层
           ROUND(e.stake,4) AS stake, ROUND(e.valid,4) AS valid_bet,
           ROUND(-e.net,4) AS profit, e.n_bets, e.n_rounds,
           ROUND(e.net/NULLIF(e.stake,0),8) AS roi,
           ROUND(e.net_in/NULLIF(e.st_in,0),8) AS roi_post,
           ROUND(e.net_out/NULLIF(e.st_out,0),8) AS roi_non_post,
           ROUND((e.net-e.rebate)/NULLIF(e.stake,0),8) AS roi_ex_rebate,
           ROUND(e.net,4) AS roi_numerator, ROUND(e.stake,4) AS roi_denominator,
           CASE WHEN e.stake IS NULL THEN 'NULL_DENOM' WHEN e.stake<=0 THEN 'ZERO_DENOM'
                WHEN e.n_bets<30 THEN 'THIN_EXPOSURE' ELSE 'OK' END AS roi_denominator_status,
           ROUND(e.rebate,4) AS rebate_cost, ROUND(e.agent_cost,4)                           AS cost_complement_b,
       ROUND(e.agent_pct,4)                            AS pct_complement,
       ROUND(e.company_retain_pct,4)                   AS pct_top_bet23,
       'AG03-UNRESOLVED'                                     AS agent_formula_version,
      'ALL5_LEVELS_bet23_to_bet27'                    AS agent_level_scope,
      ROUND(e.agent_cost_lv1,4) AS agent_cost_lv1, ROUND(e.agent_cost_lv2,4) AS agent_cost_lv2,
      ROUND(e.agent_cost_lv3,4) AS agent_cost_lv3, ROUND(e.agent_cost_lv4,4) AS agent_cost_lv4,
      ROUND(e.agent_cost_lv5,4) AS agent_cost_lv5,
      ROUND(e.agent_pct_lv1,6) AS agent_pct_lv1, ROUND(e.agent_pct_lv2,6) AS agent_pct_lv2,
      ROUND(e.agent_pct_lv3,6) AS agent_pct_lv3, ROUND(e.agent_pct_lv4,6) AS agent_pct_lv4,
      ROUND(e.agent_pct_lv5,6) AS agent_pct_lv5,
      ROUND(e.retain_pct_lv1,6) AS retain_pct_lv1, ROUND(e.retain_pct_lv2,6) AS retain_pct_lv2,
      ROUND(e.retain_pct_lv3,6) AS retain_pct_lv3, ROUND(e.retain_pct_lv4,6) AS retain_pct_lv4,
      ROUND(e.retain_pct_lv5,6) AS retain_pct_lv5, ROUND(e.chain_depth_avg,4) AS chain_depth_avg,
      ROUND(e.agent_cost_chain_additive,4)            AS agent_cost_chain_additive,
      ROUND(e.agent_cost_chain_nested,4)              AS agent_cost_chain_nested,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_additive,4) AS residual_chain_additive,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_nested,4)   AS residual_chain_nested,
      'PENDING_AG03'                                  AS decision_status,
      'FALSE'                                         AS admit_to_risk_decision,
      'NOT_FOR_ENFORCEMENT'                           AS deliverable_class,
       ROUND(e.agent_cost_a_legacy,4)                  AS agent_cost_a_legacy,
       ROUND(e.agent_cost_valid_base_legacy,4)         AS agent_cost_valid_base_legacy,
           ROUND(-e.net-e.rebate,4)                        AS ngr,
       ROUND(-e.net-e.rebate-e.agent_cost,4)           AS residual_b,
       ROUND(-e.net-e.rebate-e.agent_cost_a_legacy,4)  AS residual_a,
           ROUND((-e.net-e.rebate)/NULLIF(e.stake,0),8)    AS ngr_rate,
       ROUND((-e.net-e.rebate-e.agent_cost)/NULLIF(e.stake,0),8)   AS residual_b_rate,
      -- 【HF9c · canonical accounting contract】
      --   以下 canonical 字段只增加明确 scope；不删除、不覆盖既有字段。
      --   formal_bet23_* 保持 HF9b 当前生产公式及其 NULL/0 语义；
      --   lv1~lv5 / additive / nested 则分别采用各自原始 e.* 成本字段，
      --   rate 一律从未舍入的 e.* 分子 / e.stake 计算，禁止由展示值反算。
      ROUND(e.agent_cost,4) AS agent_cost_bet23_formal_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost,4) AS net_margin_bet23_formal_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost)/NULLIF(e.stake,0),8) AS net_margin_bet23_formal_rate_canonical,
      ROUND(e.agent_cost_lv1,4) AS agent_cost_lv1_bet23_canonical,
      ROUND(e.agent_cost_lv2,4) AS agent_cost_lv2_bet24_canonical,
      ROUND(e.agent_cost_lv3,4) AS agent_cost_lv3_bet25_canonical,
      ROUND(e.agent_cost_lv4,4) AS agent_cost_lv4_bet26_canonical,
      ROUND(e.agent_cost_lv5,4) AS agent_cost_lv5_bet27_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_lv1,4) AS net_margin_lv1_bet23_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_lv1)/NULLIF(e.stake,0),8) AS net_margin_lv1_bet23_rate_canonical,
      ROUND(e.agent_cost_chain_additive,4) AS agent_cost_chain_additive_canonical,
      ROUND(e.agent_cost_chain_nested,4) AS agent_cost_chain_nested_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_additive,4) AS net_margin_chain_additive_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_nested,4) AS net_margin_chain_nested_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_chain_additive)/NULLIF(e.stake,0),8) AS net_margin_chain_additive_rate_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_chain_nested)/NULLIF(e.stake,0),8) AS net_margin_chain_nested_rate_canonical,
       ROUND((-e.net-e.rebate-e.agent_cost_a_legacy)/NULLIF(e.stake,0),8) AS residual_a_rate,
           -- 二·分布层
           ROUND(e.stake/NULLIF(e.n_bets,0),4) AS avg_stake_per_bet,
           ROUND(e.valid/NULLIF(e.n_rounds,0),4) AS avg_valid_bet_per_round,
           ROUND(-e.net/NULLIF(e.n_rounds,0),4) AS avg_profit_per_round,
           ROUND(-e.net/NULLIF(e.active_days,0),4) AS avg_profit_per_day,
           ROUND(-e.net/NULLIF(e.active_shoes,0),4) AS avg_profit_per_shoe,
           ROUND(e.stake/NULLIF(e.active_days,0),4) AS avg_stake_per_active_day,
           ROUND(e.n_rounds*1.0/NULLIF(e.active_days,0),4) AS avg_rounds_per_active_day,
           ROUND(e.st_in/NULLIF(e.nb_in,0),4) AS avg_stake_post,
           ROUND(e.st_out/NULLIF(e.nb_out,0),4) AS avg_stake_non_post,
           ROUND(e.p25,4) AS p25_stake, ROUND(e.p50,4) AS p50_stake, ROUND(e.p75,4) AS p75_stake,
           ROUND(e.p90,4) AS p90_stake, ROUND(e.p95,4) AS p95_stake, ROUND(e.p99,4) AS p99_stake,
           ROUND(e.p50_valid,4) AS p50_valid_bet, ROUND(e.p50_profit,4) AS p50_profit,
           ROUND(e.p95/NULLIF(e.p50,0),6) AS p95_over_p50,
           ROUND(e.p99/NULLIF(e.p50,0),6) AS p99_over_p50,
           ROUND((e.stake/NULLIF(e.n_bets,0))/NULLIF(e.p50,0),6) AS avg_over_p50,
           -- 三·关系层
           e.n_tables AS common_table_count, e.n_dealers AS common_dealer_count,
           e.n_ips AS common_ip_count, e.n_products AS common_product_count,
           ROUND(e.st_in/NULLIF(e.stake,0),8) AS share_post,
           -- 四·rate 层
           ROUND(-e.net/NULLIF(e.stake,0),8) AS hold_rate,
           ROUND(-e.net_in/NULLIF(e.st_in,0),8) AS hold_rate_post,
           ROUND(e.rebate/NULLIF(e.valid,0),8) AS rebate_rate_actual,
           ROUND(e.rbpct,6) AS rebate_pct_config,
           ROUND(e.valid/NULLIF(e.stake,0),6) AS turnover_multiple,
           ROUND(e.freecomm_rate,6) AS free_comm_rate,
           ROUND(e.net_in/NULLIF(e.st_in,0)-e.net_out/NULLIF(e.st_out,0),8) AS roi_delta_post,
           -- 五·动态层
           e.first_seen_d AS first_seen, e.last_seen_d AS last_seen,
           e.active_days, e.active_shoes, e.active_sessions,
           DATEDIFF(e.last_seen_d, e.first_seen_d)+1 AS span_days,
           ROUND(e.active_days*1.0/NULLIF(DATEDIFF(e.last_seen_d,e.first_seen_d)+1,0),6) AS persistence,
           ROUND((e.st_in/NULLIF(e.nb_in,0))/NULLIF(e.st_out/NULLIF(e.nb_out,0),0),6) AS ramp_post,
           ROUND((e.st_rec/NULLIF(e.nb_rec,0))/NULLIF(e.stake/NULLIF(e.n_bets,0),0),6) AS ramp_recent,
           ROUND((e.st_rec/NULLIF(e.stake,0))/0.30,6) AS stake_ramp,
           -- 六·决策层（HF9f · 详见档头【HF9f 变更说明】；本段两版逐字同一）
           NTILE(5) OVER (ORDER BY e.stake) AS vip_tier,                                                        -- 窗口取值：相对刻度 B 族，全体五等分；须连同下方血统五元组一并解读，禁作硬阈值判型
           PERCENT_RANK() OVER (ORDER BY -e.net-e.rebate-e.agent_cost)    AS economic_value,                    -- 窗口取值：HF9f·F-19 修正 —— HF9e 写作 -(-…) 双负号致方向颠倒（#075 实测 corr(economic_value, residual_b) = -1.0000）；今与 action_priority 排序键归一，值大即平台真净利高
           PERCENT_RANK() OVER (ORDER BY e.net/NULLIF(e.stake,0))         AS roi_pr_global,                     -- 窗口取值：HF9f·F-17 正名 —— 本列实为 ROI（玩家净回报率）之全体百分位，与「风险」无关；旧名 risk_value 见下一行
           PERCENT_RANK() OVER (ORDER BY e.net/NULLIF(e.stake,0))         AS risk_value,                        -- 窗口取值：兼容列，恒等于 roi_pr_global，仅为下游迁移窗保留；HF9g 起废弃，禁新引用
           PERCENT_RANK() OVER (ORDER BY e.stake)                         AS pr_stake,                          -- 窗口取值：兼容列，恒等于 pr_global，原名保留以免断链
           PERCENT_RANK() OVER (ORDER BY e.stake)                         AS pr_global,                         -- 窗口取值：HF9f·F-1 双轨之一 —— 全体口径百分位，参照总体即本件全部输出行
           CASE WHEN e.n_rounds >= 30                                                                           -- 条件分支：起始分支 —— 仅在合格子集内计算合格口径百分位
                  THEN PERCENT_RANK() OVER (PARTITION BY CASE WHEN e.n_rounds >= 30 THEN 1 ELSE 0 END ORDER BY e.stake)  -- 分支取值：以合格与否分区，故本值即 n_rounds>=30 子集内之百分位
                ELSE NULL END                                             AS pr_qualified,                      -- 条件分支：收束上方分支 —— 不合格者留 NULL（NULL＝未测，非 0），产出「pr_qualified」
           'n_rounds>=30'                                                 AS pr_qualified_population,           -- 字面取值：血统 —— 合格子集之定义
           COUNT(*) OVER ()                                               AS pr_global_population_n,            -- 窗口取值：血统 —— 全体口径之参照总体规模，渲染时现算，禁写死
           SUM(CASE WHEN e.n_rounds >= 30 THEN 1 ELSE 0 END) OVER ()      AS pr_qualified_population_n,         -- 窗口取值：血统 —— 合格子集之参照总体规模，现算，禁写死
           'PERCENT_RANK_OVER_ORDER_BY_e_stake'                           AS pr_calculation_method,             -- 字面取值：血统 —— 算法标识
           'HF9f'                                                         AS pr_calculation_version,            -- 字面取值：血统 —— 算法版本
           CASE WHEN e.n_rounds IS NULL OR e.n_rounds < 30 THEN 'THIN_ROUNDS' ELSE 'OK' END AS evidence_flag,   -- 条件分支：HF9f·F-2a 证据旗标 —— THIN_ROUNDS 者禁入执行队列，仅入观察队列
           CASE WHEN e.n_rounds IS NULL       THEN NULL                                                         -- 条件分支：起始分支 —— 未测者留 NULL（自家铁律：NULL ≠ 0）
                WHEN e.n_rounds >= 31483      THEN 'L1_POWERED'                                                 -- 分支判定：MDE 反解第一档
                WHEN e.n_rounds >= 15409      THEN 'L2_CI_1P5'                                                  -- 分支判定：MDE 反解第二档
                WHEN e.n_rounds >=  8668      THEN 'L3_CI_2P0'                                                  -- 分支判定：MDE 反解第三档
                WHEN e.n_rounds >=  3852      THEN 'L4_CI_3P0'                                                  -- 分支判定：MDE 反解第四档
                ELSE 'L5_INSUFFICIENT' END                                AS evidence_rate,                     -- 条件分支：收束上方 —— HF9f·F-3 证据分档，承 HF9e 前议之 MDE 反解五档，须于 F-4 敏感性实验后复核
           ROUND(1.96 * 0.95 / SQRT(NULLIF(CAST(e.n_rounds AS DOUBLE),0)),8) AS hold_ci_halfwidth_approx,       -- 比率表达式：HF9f·F-3 逐行现算之 95% 半宽近似；常数 0.95 为登记值，本轮 #075 实测每局 ROI 隐含 σ 于最薄层为 0.9249，二者差异待 F-4 裁定
           CASE WHEN e.stake IS NULL OR e.stake<=0 OR e.n_bets<30 OR e.n_rounds IS NULL OR e.n_rounds<30 THEN 'Z 证据不足 · 不动作'  -- 条件分支：HF9f·F-2 双条件取严 —— HF9e 仅卡 e.n_bets<30，致 n_bets>=30 而 n_rounds<30 者绕过 Z（#075 实测 18,537 名，其中 8,145 名已入 A/D 待裁）；今两条件并列取严
                WHEN PERCENT_RANK() OVER (ORDER BY -e.net-e.rebate-e.agent_cost)<=0.10                          -- 分支判定：平台真净利之最低十分位
                  THEN 'A 净亏最大十分位 · 优先复核'                                                             -- 分支取值：HF9f·F-20 正名 —— 本档 Σresidual_b 于 #075 实测 = -100,236,896，系平台净亏最大群，旧名「残值最低十分位 · 待裁」名实不符
                WHEN PERCENT_RANK() OVER (ORDER BY -e.net-e.rebate-e.agent_cost)>=0.80                          -- 分支判定：平台真净利之最高二十分位
                  THEN 'D 净利最高二十分位 · 优先留存'                                                           -- 分支取值：HF9f·F-20 正名 —— 本档 Σresidual_b 于 #075 实测 = +281,733,190，系核心利润源；与 A 档方向相反，旧版同标「待裁」属名实不符
                ELSE 'E 常规' END                                          AS action_priority                   -- 条件分支：收束上方判词，产出「action_priority」
    FROM q
    LEFT JOIN x_agg e ON CAST(e.x_key AS STRING) = CAST(q.`member_id` AS STRING)
  ) y
) z
-- ── 逐批 WHERE 阶梯（★ 口诀：上界 ＝ 下界 ＋ 100000，两数同进）──
--    本件 T_true 未测，无需先跑 T_true；以 0 / 100000 控制本批返回区间，末批由实际行数 < 100000 判定
--    WHERE z.audit_rn >        0 AND z.audit_rn <=   100000   -- 第 1 批
--    WHERE z.audit_rn >   100000 AND z.audit_rn <=   200000   -- 第 2 批
--    WHERE z.audit_rn >   200000 AND z.audit_rn <=   300000   -- 第 3 批
--    WHERE z.audit_rn >   300000 AND z.audit_rn <=   400000   -- 第 4 批
--    WHERE z.audit_rn >   400000 AND z.audit_rn <=   500000   -- 第 5 批
--    WHERE z.audit_rn >   500000 AND z.audit_rn <=   600000   -- 第 6 批
--    WHERE z.audit_rn >   600000 AND z.audit_rn <=   700000   -- 第 7 批
--    …余批类推。第 k 批：WHERE z.audit_rn > (k-1)*100000 AND z.audit_rn <= k*100000
--    某批返回 < 100000 行即为末批，其后不再取。
--
--    ⚠ 常见误写（务必避开）：只推下界而上界不动 ——
--        WHERE z.audit_rn > 100000 AND z.audit_rn <= 100000   ← 自相矛盾，恒为假，返回空集
--        WHERE z.audit_rn > 200000 AND z.audit_rn <= 100000   ← 同上，空集
--      两个数必须**同时**前进，且始终相差 100000。
--      下界 ＝ 上一批之上界；上界 ＝ 本批之上界。
WHERE z.audit_rn > 0 AND z.audit_rn <= 100000 -- ★ HF9c 本批区间
ORDER BY z.audit_rn;


-- ══════════════════════════════════════════════════════════════════════════════════════════════
-- 123. _PH0_1b_table_inventory.csv   [总包行 12393~12445 · 原 10 列 ＋六层约 60 列]
--     典型学：Z00 基建/元数据　派生旗标：recent（s.x_rec = 1 · 仅供 CASE 条件聚合，全包无任何 WHERE/AND/HAVING 以此过滤）　连接：全窗基线
-- ══════════════════════════════════════════════════════════════════════════════════════════════
-- ★ W-64 · D-14 警示（本件属 x_win 族 · 66 件之一 · 详见 §Z 段 D-14 全案）
--   本件以 `CROSS JOIN x_win e` 接入全局基线，x_win 无 GROUP BY ⇒ 恒 1 行 ⇒ e.* 全行同值。
--   故：economic_value / roi_pr_global / risk_value / pr_stake / pr_global 恒为 0；
--       action_priority 每一行皆为「A 净亏最大十分位 · 优先复核」（Z 分支永不触发）；
--       evidence_rate 恒为最高档；vip_tier 由常数键分档 ⇒ 无信息且非确定。
--   ⇒ 本件决策层三列 **NOT_FOR_DECISION**，裁定前不得用于排班、抽查或汇报。
-- ── ① 先跑 T_true 留档（不足 100000 者一次导全，不必分批）──
-- ── ① T_true：HF9c 不再强制预跑完整 COUNT。
--    本批实际返回行数 < 100000 即判定为末批；全批完成后以各批 n_rows / audit_rn 范围核对总量。

-- ── ② 分批取数：第 1 批。第 k 批只改末行两数为 (k-1)*100000 与 k*100000 ──
--    审计字段二（REDTEAM 2026-08-24 裁定 · 四锁）：
--      audit_rn  全局观测坐标 —— 由**与原版审计版逐字同一**之排序键所生，两版可逐行对账
--      batch_id  物理分批信息 —— 该行所属批次，由 audit_rn 算得，非引擎所赋
--    ★ 锁三：二者皆为审计字段，**不得进入任何业务指标计算**。
--    ★ 锁四：两版经 audit_rn 逐行字段核验后，方可宣布输出完全一致。

-- ── ③ 每批取回后自证四数（任一不符即停手回报，禁止放行）──
--    n_rows        = COUNT(*)      须等于 COUNT(DISTINCT audit_rn)   （批内无重复）
--    audit_rn_min  = MIN(audit_rn) 须等于 (k-1)*100000 + 1           （与上批严丝合缝）
--    audit_rn_max  = MAX(audit_rn) 须等于 min + n_rows - 1           （批内无缺口）
--    全批取毕再验：各批 audit_rn 之并集 = 1 .. T_true，无缺号、无重号。
--     ★ 首行＝平台真净亏最多者（已扣退水与代理占成）。
--
SELECT z.*,
       CAST(FLOOR((z.audit_rn - 1) / 100000) + 1 AS INT)          AS batch_id,
       'A168_HF9F_20260827_0900' AS run_id,
       '2026-08-27 09:00:00' AS snapshot_sync_time
FROM (
  SELECT y.*,
         ROW_NUMBER() OVER (ORDER BY y.`residual_b` ASC, y.`roi` DESC, y.`table_name`, y.`h_src`, y.`has_uid`, y.`has_time`, y.`has_amount`, y.`n_cols`, y.`table_nature`, y.`scope_db`, y.`scope_pattern`, y.`scope_scanned_at`) AS audit_rn
  FROM (
    WITH
      x_ranked AS (
    SELECT b.bet01, b.bet03, b.bet04, b.bet05, b.bet09, b.bet11, b.bet13,
           b.bet15, b.bet16, b.bet17, b.bet18, b.bet19, b.bet20, b.bet21,
           b.bet22, b.bet23, b.bet24, b.bet25, b.bet26, b.bet27, b.bet38, b.bet39, b.category, b.commission,
           b.dt, b.eid, b.ip, b.validbet, b.updatetime, b.sync_time,
           ROW_NUMBER() OVER (
             PARTITION BY b.bet01
             ORDER BY b.updatetime DESC, b.sync_time DESC, b.dt DESC)      AS x_rn
    FROM ods_mariadb_2b.ods_a168_bet02 b
    WHERE b.dt >= '2026-03-21' AND b.dt < '2026-08-07'
      AND b.bet02 = '101'
      AND b.sync_time <= '2026-08-27 09:00:00'
  ),
    x_testagent AS (
    SELECT age001 AS agent_id FROM ods_mariadb_2b.ods_a168_agent WHERE age022 = '1'
  ),
    x_bs0 AS (
    SELECT b.bet05 AS x_member, b.eid AS x_dealer, b.bet39 AS x_table,
           b.bet03 AS x_shoe, b.ip AS x_ip, b.bet09 AS x_product, b.dt AS x_date,
           CONCAT_WS('|', b.bet03, b.bet04, b.bet39)                      AS x_round,
           CONCAT_WS('|', b.bet39, b.bet03)                               AS x_tblshoe,
           CAST(NULLIF(TRIM(b.bet04),'') AS INT)                          AS x_rno,
           CASE WHEN b.dt >= '2026-07-08' THEN 1 ELSE 0 END               AS x_rec,
           CASE WHEN TRIM(b.commission)='1' THEN 1 ELSE 0 END             AS x_freecomm,
           CAST(NULLIF(TRIM(b.bet13),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_stake,
           CAST(NULLIF(TRIM(b.validbet),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_valid,
           CAST(NULLIF(TRIM(b.bet16),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_rebate,
           CAST(NULLIF(TRIM(b.bet17),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_net,
           CAST(NULLIF(TRIM(b.bet15),'') AS DECIMAL(20,6))                AS x_rbpct,
           COALESCE(CAST(NULLIF(TRIM(b.bet23),'') AS DECIMAL(20,6)),0)   AS x_agpct,
          NULLIF(CAST(NULLIF(TRIM(b.bet23),'') AS DECIMAL(20,6)),0)     AS x_rate1,
          NULLIF(CAST(NULLIF(TRIM(b.bet24),'') AS DECIMAL(20,6)),0)     AS x_rate2,
          NULLIF(CAST(NULLIF(TRIM(b.bet25),'') AS DECIMAL(20,6)),0)     AS x_rate3,
          NULLIF(CAST(NULLIF(TRIM(b.bet26),'') AS DECIMAL(20,6)),0)     AS x_rate4,
          NULLIF(CAST(NULLIF(TRIM(b.bet27),'') AS DECIMAL(20,6)),0)     AS x_rate5,
          (CASE WHEN NULLIF(CAST(NULLIF(TRIM(b.bet22),'') AS BIGINT),0) IS NOT NULL THEN 5
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet21),'') AS BIGINT),0) IS NOT NULL THEN 4
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet20),'') AS BIGINT),0) IS NOT NULL THEN 3
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet19),'') AS BIGINT),0) IS NOT NULL THEN 2
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet18),'') AS BIGINT),0) IS NOT NULL THEN 1
                ELSE 0 END)                                             AS x_chain_depth,
           CASE WHEN COALESCE(t1.agent_id,t2.agent_id,t3.agent_id,
                              t4.agent_id,t5.agent_id) IS NOT NULL
                THEN 1 ELSE 0 END                                        AS f_testline
    FROM x_ranked b
    LEFT JOIN x_testagent t1 ON t1.agent_id = b.bet18
    LEFT JOIN x_testagent t2 ON t2.agent_id = b.bet19
    LEFT JOIN x_testagent t3 ON t3.agent_id = b.bet20
    LEFT JOIN x_testagent t4 ON t4.agent_id = b.bet21
    LEFT JOIN x_testagent t5 ON t5.agent_id = b.bet22
    WHERE b.x_rn = 1
      AND b.category='1' AND UPPER(TRIM(b.bet38))='N'
      AND CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8)) > 0
  ),
  x_mk AS (
    SELECT s.*,
           CASE WHEN s.f_testline = 0 THEN 1 ELSE 0 END                 AS is_clean
    FROM x_bs0 s
  ),
  x_agg AS (
    SELECT s.x_member                                                        AS x_key,
           COUNT(*) AS n_bets, COUNT(DISTINCT s.x_round) AS n_rounds,
           COUNT(DISTINCT s.x_date) AS active_days, COUNT(DISTINCT s.x_tblshoe) AS active_shoes,
           COUNT(DISTINCT CONCAT_WS('|', s.x_date, s.x_table)) AS active_sessions,
           COUNT(DISTINCT s.x_table) AS n_tables, COUNT(DISTINCT s.x_dealer) AS n_dealers,
           COUNT(DISTINCT s.x_ip) AS n_ips, COUNT(DISTINCT s.x_product) AS n_products,
           MIN(s.x_date) AS first_seen_d, MAX(s.x_date) AS last_seen_d,
           SUM(s.x_stake) AS stake, SUM(s.x_valid) AS valid, SUM(s.x_rebate) AS rebate,
           SUM(s.x_net) AS net, SUM(-s.x_net *(100.0-s.x_agpct)/100.0) AS agent_cost,
           AVG(100.0-s.x_agpct)                   AS agent_pct,
           AVG(s.x_agpct)                         AS company_retain_pct,
           SUM(-s.x_net *s.x_agpct/100.0)         AS agent_cost_a_legacy,
           SUM(s.x_valid*s.x_agpct/100.0)         AS agent_cost_valid_base_legacy,
          AVG(COALESCE(s.x_rate1,100)) AS retain_pct_lv1, AVG(COALESCE(s.x_rate2,100)) AS retain_pct_lv2,
          AVG(COALESCE(s.x_rate3,100)) AS retain_pct_lv3, AVG(COALESCE(s.x_rate4,100)) AS retain_pct_lv4,
          AVG(COALESCE(s.x_rate5,100)) AS retain_pct_lv5, AVG(s.x_chain_depth) AS chain_depth_avg,
          AVG(COALESCE(100.0-s.x_rate1,0)) AS agent_pct_lv1, AVG(COALESCE(100.0-s.x_rate2,0)) AS agent_pct_lv2,
          AVG(COALESCE(100.0-s.x_rate3,0)) AS agent_pct_lv3, AVG(COALESCE(100.0-s.x_rate4,0)) AS agent_pct_lv4,
          AVG(COALESCE(100.0-s.x_rate5,0)) AS agent_pct_lv5,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate1,0)/100.0)                        AS agent_cost_lv1,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate2,0)/100.0)                        AS agent_cost_lv2,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate3,0)/100.0)                        AS agent_cost_lv3,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate4,0)/100.0)                        AS agent_cost_lv4,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate5,0)/100.0)                        AS agent_cost_lv5,
          SUM(-s.x_net*(COALESCE(100.0-s.x_rate1,0)+COALESCE(100.0-s.x_rate2,0)
                       +COALESCE(100.0-s.x_rate3,0)+COALESCE(100.0-s.x_rate4,0)
                       +COALESCE(100.0-s.x_rate5,0))/100.0)                   AS agent_cost_chain_additive,
          SUM(-s.x_net*(1.0 - CAST(COALESCE(s.x_rate1,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate2,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate3,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate4,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate5,100) AS DOUBLE)/100.0))
                                                                       AS agent_cost_chain_nested,
           AVG(s.x_rbpct) AS rbpct, AVG(s.x_freecomm*1.0) AS freecomm_rate,
           PERCENTILE_APPROX(s.x_stake,0.25) AS p25, PERCENTILE_APPROX(s.x_stake,0.50) AS p50,
           PERCENTILE_APPROX(s.x_stake,0.75) AS p75, PERCENTILE_APPROX(s.x_stake,0.90) AS p90,
           PERCENTILE_APPROX(s.x_stake,0.95) AS p95, PERCENTILE_APPROX(s.x_stake,0.99) AS p99,
           PERCENTILE_APPROX(s.x_valid,0.50) AS p50_valid,
           PERCENTILE_APPROX(s.x_net,0.50)   AS p50_profit,
           SUM(CASE WHEN s.x_rec = 1 THEN s.x_stake ELSE 0 END) AS st_in,
           SUM(CASE WHEN s.x_rec = 1 THEN 1 ELSE 0 END)         AS nb_in,
           SUM(CASE WHEN s.x_rec = 1 THEN s.x_net ELSE 0 END)   AS net_in,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN s.x_stake ELSE 0 END) AS st_out,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN 1 ELSE 0 END)         AS nb_out,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN s.x_net ELSE 0 END)   AS net_out,
           SUM(CASE WHEN s.x_rec=1 THEN s.x_stake ELSE 0 END) AS st_rec,
           SUM(CASE WHEN s.x_rec=1 THEN 1 ELSE 0 END)         AS nb_rec
    FROM x_mk s
    WHERE s.is_clean = 1
      AND s.x_member IS NOT NULL AND TRIM(CAST(s.x_member AS STRING)) <> ''
    GROUP BY s.x_member
  ),
  x_win AS (
    SELECT            COUNT(*) AS n_bets, COUNT(DISTINCT s.x_round) AS n_rounds,
           COUNT(DISTINCT s.x_date) AS active_days, COUNT(DISTINCT s.x_tblshoe) AS active_shoes,
           COUNT(DISTINCT CONCAT_WS('|', s.x_date, s.x_table)) AS active_sessions,
           COUNT(DISTINCT s.x_table) AS n_tables, COUNT(DISTINCT s.x_dealer) AS n_dealers,
           COUNT(DISTINCT s.x_ip) AS n_ips, COUNT(DISTINCT s.x_product) AS n_products,
           MIN(s.x_date) AS first_seen_d, MAX(s.x_date) AS last_seen_d,
           SUM(s.x_stake) AS stake, SUM(s.x_valid) AS valid, SUM(s.x_rebate) AS rebate,
           SUM(s.x_net) AS net, SUM(-s.x_net *(100.0-s.x_agpct)/100.0) AS agent_cost,
           AVG(100.0-s.x_agpct)                   AS agent_pct,
           AVG(s.x_agpct)                         AS company_retain_pct,
           SUM(-s.x_net *s.x_agpct/100.0)         AS agent_cost_a_legacy,
           SUM(s.x_valid*s.x_agpct/100.0)         AS agent_cost_valid_base_legacy,
          AVG(COALESCE(s.x_rate1,100)) AS retain_pct_lv1, AVG(COALESCE(s.x_rate2,100)) AS retain_pct_lv2,
          AVG(COALESCE(s.x_rate3,100)) AS retain_pct_lv3, AVG(COALESCE(s.x_rate4,100)) AS retain_pct_lv4,
          AVG(COALESCE(s.x_rate5,100)) AS retain_pct_lv5, AVG(s.x_chain_depth) AS chain_depth_avg,
          AVG(COALESCE(100.0-s.x_rate1,0)) AS agent_pct_lv1, AVG(COALESCE(100.0-s.x_rate2,0)) AS agent_pct_lv2,
          AVG(COALESCE(100.0-s.x_rate3,0)) AS agent_pct_lv3, AVG(COALESCE(100.0-s.x_rate4,0)) AS agent_pct_lv4,
          AVG(COALESCE(100.0-s.x_rate5,0)) AS agent_pct_lv5,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate1,0)/100.0)                        AS agent_cost_lv1,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate2,0)/100.0)                        AS agent_cost_lv2,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate3,0)/100.0)                        AS agent_cost_lv3,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate4,0)/100.0)                        AS agent_cost_lv4,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate5,0)/100.0)                        AS agent_cost_lv5,
          SUM(-s.x_net*(COALESCE(100.0-s.x_rate1,0)+COALESCE(100.0-s.x_rate2,0)
                       +COALESCE(100.0-s.x_rate3,0)+COALESCE(100.0-s.x_rate4,0)
                       +COALESCE(100.0-s.x_rate5,0))/100.0)                   AS agent_cost_chain_additive,
          SUM(-s.x_net*(1.0 - CAST(COALESCE(s.x_rate1,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate2,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate3,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate4,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate5,100) AS DOUBLE)/100.0))
                                                                       AS agent_cost_chain_nested,
           AVG(s.x_rbpct) AS rbpct, AVG(s.x_freecomm*1.0) AS freecomm_rate,
           PERCENTILE_APPROX(s.x_stake,0.25) AS p25, PERCENTILE_APPROX(s.x_stake,0.50) AS p50,
           PERCENTILE_APPROX(s.x_stake,0.75) AS p75, PERCENTILE_APPROX(s.x_stake,0.90) AS p90,
           PERCENTILE_APPROX(s.x_stake,0.95) AS p95, PERCENTILE_APPROX(s.x_stake,0.99) AS p99,
           PERCENTILE_APPROX(s.x_valid,0.50) AS p50_valid,
           PERCENTILE_APPROX(s.x_net,0.50)   AS p50_profit,
           SUM(CASE WHEN s.x_rec = 1 THEN s.x_stake ELSE 0 END) AS st_in,
           SUM(CASE WHEN s.x_rec = 1 THEN 1 ELSE 0 END)         AS nb_in,
           SUM(CASE WHEN s.x_rec = 1 THEN s.x_net ELSE 0 END)   AS net_in,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN s.x_stake ELSE 0 END) AS st_out,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN 1 ELSE 0 END)         AS nb_out,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN s.x_net ELSE 0 END)   AS net_out,
           SUM(CASE WHEN s.x_rec=1 THEN s.x_stake ELSE 0 END) AS st_rec,
           SUM(CASE WHEN s.x_rec=1 THEN 1 ELSE 0 END)         AS nb_rec
    FROM x_mk s
    WHERE s.is_clean = 1
      AND s.x_member IS NOT NULL AND TRIM(CAST(s.x_member AS STRING)) <> ''
  ),
      q AS (
        WITH col_flag AS (                                                                                  -- 公共表表达式：开启中间结果集 col_flag——逐表之三类列存在性
          SELECT c.TABLE_NAME                                                            AS table_name,     -- 取列：表名
                 MAX(CASE WHEN LOWER(c.COLUMN_NAME) REGEXP                                                  -- 条件分支：UID 型列——含编码式（bet05／memNNN／ageNNN）
                            '^(uid|member_id|user_id|username|account|mem[0-9]{2,3}|bet05|age[0-9]{3}|lmc[0-9]{2})$'
                           OR c.COLUMN_COMMENT REGEXP '會員|会员|帳號|账号|用戶|用户'                        -- 并列条件：中文列义命中会员键
                           THEN 1 ELSE 0 END)                                            AS has_uid,        -- 条件分支：产出「has_uid」
                 MAX(CASE WHEN LOWER(c.DATA_TYPE) REGEXP 'date|time'                                        -- 条件分支：时间型列——先认类型，再认名
                           OR LOWER(c.COLUMN_NAME) REGEXP 'time|date|_at$|_dt$|^dt$|created|updated'        -- 并列条件：列名命中时间族
                           OR c.COLUMN_COMMENT REGEXP '時間|时间|日期'                                       -- 并列条件：中文列义命中
                           THEN 1 ELSE 0 END)                                            AS has_time,       -- 条件分支：产出「has_time」
                 MAX(CASE WHEN LOWER(c.DATA_TYPE) REGEXP 'decimal|double|float'                             -- 条件分支：金额型列——先认类型
                           OR LOWER(c.COLUMN_NAME) REGEXP 'amount|money|balance|sum|fee|cash'               -- 并列条件：列名命中金额族
                           OR c.COLUMN_COMMENT REGEXP '金額|金额|餘額|余额|款'                               -- 并列条件：中文列义命中
                           THEN 1 ELSE 0 END)                                            AS has_amount,     -- 条件分支：产出「has_amount」
                 COUNT(*)                                                                AS n_cols          -- 计数表达式：列数，配置表通常列少
          FROM information_schema.columns c                                                                 -- 取数来源：取自元数据字典（列清单）
          WHERE c.TABLE_SCHEMA = 'ods_mariadb_2b'                                                           -- 过滤条件：限定 TABLE_SCHEMA等于 'ods_mariadb_2b'
          GROUP BY c.TABLE_NAME                                                                             -- 分组：按表名汇总
        )                                                                                                   -- 续行：收束上方的子查询或函数括号
        SELECT                                                                                              -- 取列：起始取列子句
          t.TABLE_NAME                                                                   AS table_name,     -- 取列：表名
          CASE                                                                                              -- 条件分支：起始分支——六源归类，责任博彩优先判以免被状态族吞并
            WHEN LOWER(t.TABLE_NAME) REGEXP 'self_?exclu|cooling|cool_?off|cooldown|responsible|_rg$|^rg_'   -- 分支判定：责任博彩族（★ 已排除 response 之误撞）
              THEN 'H-SRC-05 自我排除／冷静期／责任博彩'                                                     -- 分支判定：H 轴最高价值之源
            WHEN LOWER(t.TABLE_NAME) REGEXP 'wallet|pay|deposit|withdraw|cashier|recharge|transact|transation|fund|remit|balance|cash|order' -- 分支判定：支付族（★ v1.0.1 补 wallet／balance／cash）
              THEN 'H-SRC-01 支付／资金'                                                                    -- 分支判定：归支付源
            WHEN LOWER(t.TABLE_NAME) REGEXP 'session|login|logout|online|heartbeat|device|token|visit'       -- 分支判定：会话族
              THEN 'H-SRC-02 会话／登录'                                                                    -- 分支判定：归会话源
            WHEN LOWER(t.TABLE_NAME) REGEXP 'mem_change|member_log|suspend|close|reopen|freeze|restrict|limit|level|vip|status' -- 分支判定：会员状态族
              THEN 'H-SRC-03 会员状态变更'                                                                  -- 分支判定：归状态源
            WHEN LOWER(t.TABLE_NAME) REGEXP 'ticket|case|complain|dispute|service|support|feedback|chat|message|msg|alarm|alert' -- 分支判定：工单／消息族
              THEN 'H-SRC-04 客服工单／消息'                                                                -- 分支判定：归工单源（★ 告警与工单须于 §P-H0-3 再辨）
            WHEN LOWER(t.TABLE_NAME) REGEXP '^ods_a168_(log_|change_log)|_log$|history|journal|record|trace' -- 分支判定：日志族（★ v1.0.1 新增，变更留痕之通称）
              THEN 'H-SRC-06 日志／变更留痕'                                                                -- 分支判定：归日志源
            ELSE '（未命中六源）'                                                                           -- 分支判定：余者照登，以备扩关键词后翻查
          END                                                                            AS h_src,         -- 条件分支：收束上方判词，产出「h_src」
          f.has_uid,                                                                                        -- 取列：是否具会员键
          f.has_time,                                                                                       -- 取列：是否具时间列
          f.has_amount,                                                                                     -- 取列：是否具金额列
          f.n_cols,                                                                                         -- 取列：列数
          CASE                                                                                              -- 条件分支：起始分支——表性质判别（D-5）
            WHEN f.has_uid = 1 AND f.has_time = 1 AND f.has_amount = 1 THEN '★ 事务表候选（三列俱备）'      -- 分支判定：可作 H 轴资金证据源之候选
            WHEN f.has_uid = 1 AND f.has_time = 1                      THEN '事件表候选（无金额）'          -- 分支判定：可作行为事件源
            WHEN f.has_uid = 0 AND f.has_time = 0                      THEN '配置表（无会员键无时间）'      -- 分支判定：无会员级事件，不可作证据源
            ELSE '无从判（须逐表验货）'                                                                     -- 分支判定：余者待 §P-H0-3
          END                                                                            AS table_nature,  -- 条件分支：收束上方判词，产出「table_nature」
          'ods_mariadb_2b'                                                               AS scope_db,      -- 字面取值：检索范围之库——NO_TRACE 之锚
          'v1.0.1 六族表名正则 ＋ 三列性质判别（含编码式列名 betNN／memNNN／ageNNN／lmcNN）' AS scope_pattern, -- 字面取值：检索范围之模式
          NOW()                                                                          AS scope_scanned_at -- 取值表达式：检索时刻，六态判读之时间锚
        FROM information_schema.tables t                                                                    -- 取数来源：取自元数据字典（表清单）
        LEFT JOIN col_flag f ON f.table_name = t.TABLE_NAME                                                 -- 左连接：取自本条自建的中间结果集 col_flag，连接键为 table_name
        WHERE t.TABLE_SCHEMA = 'ods_mariadb_2b'                                                             -- 过滤条件：限定 TABLE_SCHEMA等于 'ods_mariadb_2b'
      )
    SELECT q.*,
           -- 一·经济层
           ROUND(e.stake,4) AS stake, ROUND(e.valid,4) AS valid_bet,
           ROUND(-e.net,4) AS profit, e.n_bets, e.n_rounds,
           ROUND(e.net/NULLIF(e.stake,0),8) AS roi,
           ROUND(e.net_in/NULLIF(e.st_in,0),8) AS roi_recent,
           ROUND(e.net_out/NULLIF(e.st_out,0),8) AS roi_non_recent,
           ROUND((e.net-e.rebate)/NULLIF(e.stake,0),8) AS roi_ex_rebate,
           ROUND(e.net,4) AS roi_numerator, ROUND(e.stake,4) AS roi_denominator,
           CASE WHEN e.stake IS NULL THEN 'NULL_DENOM' WHEN e.stake<=0 THEN 'ZERO_DENOM'
                WHEN e.n_bets<30 THEN 'THIN_EXPOSURE' ELSE 'OK' END AS roi_denominator_status,
           ROUND(e.rebate,4) AS rebate_cost, ROUND(e.agent_cost,4)                           AS cost_complement_b,
       ROUND(e.agent_pct,4)                            AS pct_complement,
       ROUND(e.company_retain_pct,4)                   AS pct_top_bet23,
       'AG03-UNRESOLVED'                                     AS agent_formula_version,
      'ALL5_LEVELS_bet23_to_bet27'                    AS agent_level_scope,
      ROUND(e.agent_cost_lv1,4) AS agent_cost_lv1, ROUND(e.agent_cost_lv2,4) AS agent_cost_lv2,
      ROUND(e.agent_cost_lv3,4) AS agent_cost_lv3, ROUND(e.agent_cost_lv4,4) AS agent_cost_lv4,
      ROUND(e.agent_cost_lv5,4) AS agent_cost_lv5,
      ROUND(e.agent_pct_lv1,6) AS agent_pct_lv1, ROUND(e.agent_pct_lv2,6) AS agent_pct_lv2,
      ROUND(e.agent_pct_lv3,6) AS agent_pct_lv3, ROUND(e.agent_pct_lv4,6) AS agent_pct_lv4,
      ROUND(e.agent_pct_lv5,6) AS agent_pct_lv5,
      ROUND(e.retain_pct_lv1,6) AS retain_pct_lv1, ROUND(e.retain_pct_lv2,6) AS retain_pct_lv2,
      ROUND(e.retain_pct_lv3,6) AS retain_pct_lv3, ROUND(e.retain_pct_lv4,6) AS retain_pct_lv4,
      ROUND(e.retain_pct_lv5,6) AS retain_pct_lv5, ROUND(e.chain_depth_avg,4) AS chain_depth_avg,
      ROUND(e.agent_cost_chain_additive,4)            AS agent_cost_chain_additive,
      ROUND(e.agent_cost_chain_nested,4)              AS agent_cost_chain_nested,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_additive,4) AS residual_chain_additive,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_nested,4)   AS residual_chain_nested,
      'PENDING_AG03'                                  AS decision_status,
      'FALSE'                                         AS admit_to_risk_decision,
      'NOT_FOR_ENFORCEMENT'                           AS deliverable_class,
       ROUND(e.agent_cost_a_legacy,4)                  AS agent_cost_a_legacy,
       ROUND(e.agent_cost_valid_base_legacy,4)         AS agent_cost_valid_base_legacy,
           ROUND(-e.net-e.rebate,4)                        AS ngr,
       ROUND(-e.net-e.rebate-e.agent_cost,4)           AS residual_b,
       ROUND(-e.net-e.rebate-e.agent_cost_a_legacy,4)  AS residual_a,
           ROUND((-e.net-e.rebate)/NULLIF(e.stake,0),8)    AS ngr_rate,
       ROUND((-e.net-e.rebate-e.agent_cost)/NULLIF(e.stake,0),8)   AS residual_b_rate,
      -- 【HF9c · canonical accounting contract】
      --   以下 canonical 字段只增加明确 scope；不删除、不覆盖既有字段。
      --   formal_bet23_* 保持 HF9b 当前生产公式及其 NULL/0 语义；
      --   lv1~lv5 / additive / nested 则分别采用各自原始 e.* 成本字段，
      --   rate 一律从未舍入的 e.* 分子 / e.stake 计算，禁止由展示值反算。
      ROUND(e.agent_cost,4) AS agent_cost_bet23_formal_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost,4) AS net_margin_bet23_formal_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost)/NULLIF(e.stake,0),8) AS net_margin_bet23_formal_rate_canonical,
      ROUND(e.agent_cost_lv1,4) AS agent_cost_lv1_bet23_canonical,
      ROUND(e.agent_cost_lv2,4) AS agent_cost_lv2_bet24_canonical,
      ROUND(e.agent_cost_lv3,4) AS agent_cost_lv3_bet25_canonical,
      ROUND(e.agent_cost_lv4,4) AS agent_cost_lv4_bet26_canonical,
      ROUND(e.agent_cost_lv5,4) AS agent_cost_lv5_bet27_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_lv1,4) AS net_margin_lv1_bet23_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_lv1)/NULLIF(e.stake,0),8) AS net_margin_lv1_bet23_rate_canonical,
      ROUND(e.agent_cost_chain_additive,4) AS agent_cost_chain_additive_canonical,
      ROUND(e.agent_cost_chain_nested,4) AS agent_cost_chain_nested_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_additive,4) AS net_margin_chain_additive_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_nested,4) AS net_margin_chain_nested_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_chain_additive)/NULLIF(e.stake,0),8) AS net_margin_chain_additive_rate_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_chain_nested)/NULLIF(e.stake,0),8) AS net_margin_chain_nested_rate_canonical,
       ROUND((-e.net-e.rebate-e.agent_cost_a_legacy)/NULLIF(e.stake,0),8) AS residual_a_rate,
           -- 二·分布层
           ROUND(e.stake/NULLIF(e.n_bets,0),4) AS avg_stake_per_bet,
           ROUND(e.valid/NULLIF(e.n_rounds,0),4) AS avg_valid_bet_per_round,
           ROUND(-e.net/NULLIF(e.n_rounds,0),4) AS avg_profit_per_round,
           ROUND(-e.net/NULLIF(e.active_days,0),4) AS avg_profit_per_day,
           ROUND(-e.net/NULLIF(e.active_shoes,0),4) AS avg_profit_per_shoe,
           ROUND(e.stake/NULLIF(e.active_days,0),4) AS avg_stake_per_active_day,
           ROUND(e.n_rounds*1.0/NULLIF(e.active_days,0),4) AS avg_rounds_per_active_day,
           ROUND(e.st_in/NULLIF(e.nb_in,0),4) AS avg_stake_recent,
           ROUND(e.st_out/NULLIF(e.nb_out,0),4) AS avg_stake_non_recent,
           ROUND(e.p25,4) AS p25_stake, ROUND(e.p50,4) AS p50_stake, ROUND(e.p75,4) AS p75_stake,
           ROUND(e.p90,4) AS p90_stake, ROUND(e.p95,4) AS p95_stake, ROUND(e.p99,4) AS p99_stake,
           ROUND(e.p50_valid,4) AS p50_valid_bet, ROUND(e.p50_profit,4) AS p50_profit,
           ROUND(e.p95/NULLIF(e.p50,0),6) AS p95_over_p50,
           ROUND(e.p99/NULLIF(e.p50,0),6) AS p99_over_p50,
           ROUND((e.stake/NULLIF(e.n_bets,0))/NULLIF(e.p50,0),6) AS avg_over_p50,
           -- 三·关系层
           e.n_tables AS common_table_count, e.n_dealers AS common_dealer_count,
           e.n_ips AS common_ip_count, e.n_products AS common_product_count,
           ROUND(e.st_in/NULLIF(e.stake,0),8) AS share_recent,
           -- 四·rate 层
           ROUND(-e.net/NULLIF(e.stake,0),8) AS hold_rate,
           ROUND(-e.net_in/NULLIF(e.st_in,0),8) AS hold_rate_recent,
           ROUND(e.rebate/NULLIF(e.valid,0),8) AS rebate_rate_actual,
           ROUND(e.rbpct,6) AS rebate_pct_config,
           ROUND(e.valid/NULLIF(e.stake,0),6) AS turnover_multiple,
           ROUND(e.freecomm_rate,6) AS free_comm_rate,
           ROUND(e.net_in/NULLIF(e.st_in,0)-e.net_out/NULLIF(e.st_out,0),8) AS roi_delta_recent,
           -- 五·动态层
           e.first_seen_d AS first_seen, e.last_seen_d AS last_seen,
           e.active_days, e.active_shoes, e.active_sessions,
           DATEDIFF(e.last_seen_d, e.first_seen_d)+1 AS span_days,
           ROUND(e.active_days*1.0/NULLIF(DATEDIFF(e.last_seen_d,e.first_seen_d)+1,0),6) AS persistence,
           ROUND((e.st_in/NULLIF(e.nb_in,0))/NULLIF(e.st_out/NULLIF(e.nb_out,0),0),6) AS ramp_recent_vs_prior,
           ROUND((e.st_rec/NULLIF(e.nb_rec,0))/NULLIF(e.stake/NULLIF(e.n_bets,0),0),6) AS ramp_recent_vs_all,
           ROUND((e.st_rec/NULLIF(e.stake,0))/0.30,6) AS stake_ramp,
           -- 六·决策层（HF9g-P5 · D-14 斧正 —— 本件属【全窗基线族】，相对刻度与决策标签一律 NULL）
           --   病灶：x_win 系全窗单行聚合（无 GROUP BY，恒 1 行，此为设计使然，非缺陷），
           --         经 CROSS JOIN 接入后 e.* 全行同值；六层之 NTILE / PERCENT_RANK 施于常数即退化，
           --         PERCENT_RANK 恒 0 ⇒ action_priority 恒判 A，全件 100% 误标。
           --   ★ 斧正原则：不给 x_win 补 GROUP BY —— 那会改变其「全窗基线」语义，属退化。
           --     正解与 #018 之 G-05／G-06 同治：范围外之行不得接受任何下游评分与决策标签。
           --   ★ 本件之 e.* 仍照常供其它列作全窗基线使用，仅六层相对刻度与决策标签置 NULL。
           CAST(NULL AS INT)                                              AS vip_tier,                        -- 空值取值：全窗基线族无实体可分档，置 NULL（NULL＝不适用，非 0）
           CAST(NULL AS DOUBLE)                                           AS economic_value,                  -- 空值取值：同上，禁以常数百分位冒充经济价值
           CAST(NULL AS DOUBLE)                                           AS roi_pr_global,                   -- 空值取值：同上
           CAST(NULL AS DOUBLE)                                           AS risk_value,                      -- 空值取值：兼容列，同上
           CAST(NULL AS DOUBLE)                                           AS pr_stake,                        -- 空值取值：兼容列，同上
           CAST(NULL AS DOUBLE)                                           AS pr_global,                       -- 空值取值：同上
           CAST(NULL AS DOUBLE)                                           AS pr_qualified,                    -- 空值取值：同上
           'GLOBAL_BASELINE_NO_ENTITY_RANKING'                            AS pr_qualified_population,         -- 字面取值：血统 —— 明示本件为全窗基线族，无实体排序总体
           CAST(NULL AS BIGINT)                                           AS pr_global_population_n,          -- 空值取值：血统 —— 不适用
           CAST(NULL AS BIGINT)                                           AS pr_qualified_population_n,       -- 空值取值：血统 —— 不适用
           'NOT_APPLICABLE_GLOBAL_BASELINE'                               AS pr_calculation_method,           -- 字面取值：血统 —— 算法不适用
           'HF9g-P5'                                                      AS pr_calculation_version,          -- 字面取值：血统 —— 算法版本
           CAST(NULL AS STRING)                                           AS evidence_flag,                   -- 空值取值：证据旗标不适用于全窗基线
           CAST(NULL AS STRING)                                           AS evidence_rate,                   -- 空值取值：同上
           CAST(NULL AS DOUBLE)                                           AS hold_ci_halfwidth_approx,        -- 空值取值：同上
           'X 全窗基线 · 不参与实体赏罚'                                    AS action_priority                  -- 字面取值：★ D-14 斧正 —— 本族恒不入赏罚，取代原 100% 误标之「A」
    FROM q
    CROSS JOIN x_win e
  ) y
) z
-- ── 逐批 WHERE 阶梯（★ 口诀：上界 ＝ 下界 ＋ 100000，两数同进）──
--    本件 T_true 未测，无需先跑 T_true；以 0 / 100000 控制本批返回区间，末批由实际行数 < 100000 判定
--    WHERE z.audit_rn >        0 AND z.audit_rn <=   100000   -- 第 1 批
--    WHERE z.audit_rn >   100000 AND z.audit_rn <=   200000   -- 第 2 批
--    WHERE z.audit_rn >   200000 AND z.audit_rn <=   300000   -- 第 3 批
--    WHERE z.audit_rn >   300000 AND z.audit_rn <=   400000   -- 第 4 批
--    WHERE z.audit_rn >   400000 AND z.audit_rn <=   500000   -- 第 5 批
--    WHERE z.audit_rn >   500000 AND z.audit_rn <=   600000   -- 第 6 批
--    WHERE z.audit_rn >   600000 AND z.audit_rn <=   700000   -- 第 7 批
--    …余批类推。第 k 批：WHERE z.audit_rn > (k-1)*100000 AND z.audit_rn <= k*100000
--    某批返回 < 100000 行即为末批，其后不再取。
--
--    ⚠ 常见误写（务必避开）：只推下界而上界不动 ——
--        WHERE z.audit_rn > 100000 AND z.audit_rn <= 100000   ← 自相矛盾，恒为假，返回空集
--        WHERE z.audit_rn > 200000 AND z.audit_rn <= 100000   ← 同上，空集
--      两个数必须**同时**前进，且始终相差 100000。
--      下界 ＝ 上一批之上界；上界 ＝ 本批之上界。
WHERE z.audit_rn > 0 AND z.audit_rn <= 100000 -- ★ HF9c 本批区间
ORDER BY z.audit_rn;


-- ══════════════════════════════════════════════════════════════════════════════════════════════
-- 124. _PH0_2b_column_inventory.csv   [总包行 12457~12505 · 原 11 列 ＋六层约 60 列]
--     典型学：Z00 基建/元数据　派生旗标：recent（s.x_rec = 1 · 仅供 CASE 条件聚合，全包无任何 WHERE/AND/HAVING 以此过滤）　连接：全窗基线
-- ══════════════════════════════════════════════════════════════════════════════════════════════
-- ★ W-64 · D-14 警示（本件属 x_win 族 · 66 件之一 · 详见 §Z 段 D-14 全案）
--   本件以 `CROSS JOIN x_win e` 接入全局基线，x_win 无 GROUP BY ⇒ 恒 1 行 ⇒ e.* 全行同值。
--   故：economic_value / roi_pr_global / risk_value / pr_stake / pr_global 恒为 0；
--       action_priority 每一行皆为「A 净亏最大十分位 · 优先复核」（Z 分支永不触发）；
--       evidence_rate 恒为最高档；vip_tier 由常数键分档 ⇒ 无信息且非确定。
--   ⇒ 本件决策层三列 **NOT_FOR_DECISION**，裁定前不得用于排班、抽查或汇报。
-- ── ① 先跑 T_true 留档（不足 100000 者一次导全，不必分批）──
-- ── ① T_true：HF9c 不再强制预跑完整 COUNT。
--    本批实际返回行数 < 100000 即判定为末批；全批完成后以各批 n_rows / audit_rn 范围核对总量。

-- ── ② 分批取数：第 1 批。第 k 批只改末行两数为 (k-1)*100000 与 k*100000 ──
--    审计字段二（REDTEAM 2026-08-24 裁定 · 四锁）：
--      audit_rn  全局观测坐标 —— 由**与原版审计版逐字同一**之排序键所生，两版可逐行对账
--      batch_id  物理分批信息 —— 该行所属批次，由 audit_rn 算得，非引擎所赋
--    ★ 锁三：二者皆为审计字段，**不得进入任何业务指标计算**。
--    ★ 锁四：两版经 audit_rn 逐行字段核验后，方可宣布输出完全一致。

-- ── ③ 每批取回后自证四数（任一不符即停手回报，禁止放行）──
--    n_rows        = COUNT(*)      须等于 COUNT(DISTINCT audit_rn)   （批内无重复）
--    audit_rn_min  = MIN(audit_rn) 须等于 (k-1)*100000 + 1           （与上批严丝合缝）
--    audit_rn_max  = MAX(audit_rn) 须等于 min + n_rows - 1           （批内无缺口）
--    全批取毕再验：各批 audit_rn 之并集 = 1 .. T_true，无缺号、无重号。
--     ★ 首行＝平台真净亏最多者（已扣退水与代理占成）。
--
SELECT z.*,
       CAST(FLOOR((z.audit_rn - 1) / 100000) + 1 AS INT)          AS batch_id,
       'A168_HF9F_20260827_0900' AS run_id,
       '2026-08-27 09:00:00' AS snapshot_sync_time
FROM (
  SELECT y.*,
         ROW_NUMBER() OVER (ORDER BY y.`residual_b` ASC, y.`roi` DESC, y.`table_name`, y.`col_pos`, y.`column_name`, y.`data_type`, y.`column_comment`, y.`name_style`, y.`col_family`, y.`fp_flag`, y.`scope_db`, y.`scope_pattern`, y.`scope_scanned_at`) AS audit_rn
  FROM (
    WITH
      x_ranked AS (
    SELECT b.bet01, b.bet03, b.bet04, b.bet05, b.bet09, b.bet11, b.bet13,
           b.bet15, b.bet16, b.bet17, b.bet18, b.bet19, b.bet20, b.bet21,
           b.bet22, b.bet23, b.bet24, b.bet25, b.bet26, b.bet27, b.bet38, b.bet39, b.category, b.commission,
           b.dt, b.eid, b.ip, b.validbet, b.updatetime, b.sync_time,
           ROW_NUMBER() OVER (
             PARTITION BY b.bet01
             ORDER BY b.updatetime DESC, b.sync_time DESC, b.dt DESC)      AS x_rn
    FROM ods_mariadb_2b.ods_a168_bet02 b
    WHERE b.dt >= '2026-03-21' AND b.dt < '2026-08-07'
      AND b.bet02 = '101'
      AND b.sync_time <= '2026-08-27 09:00:00'
  ),
    x_testagent AS (
    SELECT age001 AS agent_id FROM ods_mariadb_2b.ods_a168_agent WHERE age022 = '1'
  ),
    x_bs0 AS (
    SELECT b.bet05 AS x_member, b.eid AS x_dealer, b.bet39 AS x_table,
           b.bet03 AS x_shoe, b.ip AS x_ip, b.bet09 AS x_product, b.dt AS x_date,
           CONCAT_WS('|', b.bet03, b.bet04, b.bet39)                      AS x_round,
           CONCAT_WS('|', b.bet39, b.bet03)                               AS x_tblshoe,
           CAST(NULLIF(TRIM(b.bet04),'') AS INT)                          AS x_rno,
           CASE WHEN b.dt >= '2026-07-08' THEN 1 ELSE 0 END               AS x_rec,
           CASE WHEN TRIM(b.commission)='1' THEN 1 ELSE 0 END             AS x_freecomm,
           CAST(NULLIF(TRIM(b.bet13),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_stake,
           CAST(NULLIF(TRIM(b.validbet),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_valid,
           CAST(NULLIF(TRIM(b.bet16),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_rebate,
           CAST(NULLIF(TRIM(b.bet17),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_net,
           CAST(NULLIF(TRIM(b.bet15),'') AS DECIMAL(20,6))                AS x_rbpct,
           COALESCE(CAST(NULLIF(TRIM(b.bet23),'') AS DECIMAL(20,6)),0)   AS x_agpct,
          NULLIF(CAST(NULLIF(TRIM(b.bet23),'') AS DECIMAL(20,6)),0)     AS x_rate1,
          NULLIF(CAST(NULLIF(TRIM(b.bet24),'') AS DECIMAL(20,6)),0)     AS x_rate2,
          NULLIF(CAST(NULLIF(TRIM(b.bet25),'') AS DECIMAL(20,6)),0)     AS x_rate3,
          NULLIF(CAST(NULLIF(TRIM(b.bet26),'') AS DECIMAL(20,6)),0)     AS x_rate4,
          NULLIF(CAST(NULLIF(TRIM(b.bet27),'') AS DECIMAL(20,6)),0)     AS x_rate5,
          (CASE WHEN NULLIF(CAST(NULLIF(TRIM(b.bet22),'') AS BIGINT),0) IS NOT NULL THEN 5
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet21),'') AS BIGINT),0) IS NOT NULL THEN 4
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet20),'') AS BIGINT),0) IS NOT NULL THEN 3
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet19),'') AS BIGINT),0) IS NOT NULL THEN 2
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet18),'') AS BIGINT),0) IS NOT NULL THEN 1
                ELSE 0 END)                                             AS x_chain_depth,
           CASE WHEN COALESCE(t1.agent_id,t2.agent_id,t3.agent_id,
                              t4.agent_id,t5.agent_id) IS NOT NULL
                THEN 1 ELSE 0 END                                        AS f_testline
    FROM x_ranked b
    LEFT JOIN x_testagent t1 ON t1.agent_id = b.bet18
    LEFT JOIN x_testagent t2 ON t2.agent_id = b.bet19
    LEFT JOIN x_testagent t3 ON t3.agent_id = b.bet20
    LEFT JOIN x_testagent t4 ON t4.agent_id = b.bet21
    LEFT JOIN x_testagent t5 ON t5.agent_id = b.bet22
    WHERE b.x_rn = 1
      AND b.category='1' AND UPPER(TRIM(b.bet38))='N'
      AND CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8)) > 0
  ),
  x_mk AS (
    SELECT s.*,
           CASE WHEN s.f_testline = 0 THEN 1 ELSE 0 END                 AS is_clean
    FROM x_bs0 s
  ),
  x_agg AS (
    SELECT s.x_member                                                        AS x_key,
           COUNT(*) AS n_bets, COUNT(DISTINCT s.x_round) AS n_rounds,
           COUNT(DISTINCT s.x_date) AS active_days, COUNT(DISTINCT s.x_tblshoe) AS active_shoes,
           COUNT(DISTINCT CONCAT_WS('|', s.x_date, s.x_table)) AS active_sessions,
           COUNT(DISTINCT s.x_table) AS n_tables, COUNT(DISTINCT s.x_dealer) AS n_dealers,
           COUNT(DISTINCT s.x_ip) AS n_ips, COUNT(DISTINCT s.x_product) AS n_products,
           MIN(s.x_date) AS first_seen_d, MAX(s.x_date) AS last_seen_d,
           SUM(s.x_stake) AS stake, SUM(s.x_valid) AS valid, SUM(s.x_rebate) AS rebate,
           SUM(s.x_net) AS net, SUM(-s.x_net *(100.0-s.x_agpct)/100.0) AS agent_cost,
           AVG(100.0-s.x_agpct)                   AS agent_pct,
           AVG(s.x_agpct)                         AS company_retain_pct,
           SUM(-s.x_net *s.x_agpct/100.0)         AS agent_cost_a_legacy,
           SUM(s.x_valid*s.x_agpct/100.0)         AS agent_cost_valid_base_legacy,
          AVG(COALESCE(s.x_rate1,100)) AS retain_pct_lv1, AVG(COALESCE(s.x_rate2,100)) AS retain_pct_lv2,
          AVG(COALESCE(s.x_rate3,100)) AS retain_pct_lv3, AVG(COALESCE(s.x_rate4,100)) AS retain_pct_lv4,
          AVG(COALESCE(s.x_rate5,100)) AS retain_pct_lv5, AVG(s.x_chain_depth) AS chain_depth_avg,
          AVG(COALESCE(100.0-s.x_rate1,0)) AS agent_pct_lv1, AVG(COALESCE(100.0-s.x_rate2,0)) AS agent_pct_lv2,
          AVG(COALESCE(100.0-s.x_rate3,0)) AS agent_pct_lv3, AVG(COALESCE(100.0-s.x_rate4,0)) AS agent_pct_lv4,
          AVG(COALESCE(100.0-s.x_rate5,0)) AS agent_pct_lv5,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate1,0)/100.0)                        AS agent_cost_lv1,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate2,0)/100.0)                        AS agent_cost_lv2,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate3,0)/100.0)                        AS agent_cost_lv3,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate4,0)/100.0)                        AS agent_cost_lv4,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate5,0)/100.0)                        AS agent_cost_lv5,
          SUM(-s.x_net*(COALESCE(100.0-s.x_rate1,0)+COALESCE(100.0-s.x_rate2,0)
                       +COALESCE(100.0-s.x_rate3,0)+COALESCE(100.0-s.x_rate4,0)
                       +COALESCE(100.0-s.x_rate5,0))/100.0)                   AS agent_cost_chain_additive,
          SUM(-s.x_net*(1.0 - CAST(COALESCE(s.x_rate1,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate2,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate3,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate4,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate5,100) AS DOUBLE)/100.0))
                                                                       AS agent_cost_chain_nested,
           AVG(s.x_rbpct) AS rbpct, AVG(s.x_freecomm*1.0) AS freecomm_rate,
           PERCENTILE_APPROX(s.x_stake,0.25) AS p25, PERCENTILE_APPROX(s.x_stake,0.50) AS p50,
           PERCENTILE_APPROX(s.x_stake,0.75) AS p75, PERCENTILE_APPROX(s.x_stake,0.90) AS p90,
           PERCENTILE_APPROX(s.x_stake,0.95) AS p95, PERCENTILE_APPROX(s.x_stake,0.99) AS p99,
           PERCENTILE_APPROX(s.x_valid,0.50) AS p50_valid,
           PERCENTILE_APPROX(s.x_net,0.50)   AS p50_profit,
           SUM(CASE WHEN s.x_rec = 1 THEN s.x_stake ELSE 0 END) AS st_in,
           SUM(CASE WHEN s.x_rec = 1 THEN 1 ELSE 0 END)         AS nb_in,
           SUM(CASE WHEN s.x_rec = 1 THEN s.x_net ELSE 0 END)   AS net_in,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN s.x_stake ELSE 0 END) AS st_out,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN 1 ELSE 0 END)         AS nb_out,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN s.x_net ELSE 0 END)   AS net_out,
           SUM(CASE WHEN s.x_rec=1 THEN s.x_stake ELSE 0 END) AS st_rec,
           SUM(CASE WHEN s.x_rec=1 THEN 1 ELSE 0 END)         AS nb_rec
    FROM x_mk s
    WHERE s.is_clean = 1
      AND s.x_member IS NOT NULL AND TRIM(CAST(s.x_member AS STRING)) <> ''
    GROUP BY s.x_member
  ),
  x_win AS (
    SELECT            COUNT(*) AS n_bets, COUNT(DISTINCT s.x_round) AS n_rounds,
           COUNT(DISTINCT s.x_date) AS active_days, COUNT(DISTINCT s.x_tblshoe) AS active_shoes,
           COUNT(DISTINCT CONCAT_WS('|', s.x_date, s.x_table)) AS active_sessions,
           COUNT(DISTINCT s.x_table) AS n_tables, COUNT(DISTINCT s.x_dealer) AS n_dealers,
           COUNT(DISTINCT s.x_ip) AS n_ips, COUNT(DISTINCT s.x_product) AS n_products,
           MIN(s.x_date) AS first_seen_d, MAX(s.x_date) AS last_seen_d,
           SUM(s.x_stake) AS stake, SUM(s.x_valid) AS valid, SUM(s.x_rebate) AS rebate,
           SUM(s.x_net) AS net, SUM(-s.x_net *(100.0-s.x_agpct)/100.0) AS agent_cost,
           AVG(100.0-s.x_agpct)                   AS agent_pct,
           AVG(s.x_agpct)                         AS company_retain_pct,
           SUM(-s.x_net *s.x_agpct/100.0)         AS agent_cost_a_legacy,
           SUM(s.x_valid*s.x_agpct/100.0)         AS agent_cost_valid_base_legacy,
          AVG(COALESCE(s.x_rate1,100)) AS retain_pct_lv1, AVG(COALESCE(s.x_rate2,100)) AS retain_pct_lv2,
          AVG(COALESCE(s.x_rate3,100)) AS retain_pct_lv3, AVG(COALESCE(s.x_rate4,100)) AS retain_pct_lv4,
          AVG(COALESCE(s.x_rate5,100)) AS retain_pct_lv5, AVG(s.x_chain_depth) AS chain_depth_avg,
          AVG(COALESCE(100.0-s.x_rate1,0)) AS agent_pct_lv1, AVG(COALESCE(100.0-s.x_rate2,0)) AS agent_pct_lv2,
          AVG(COALESCE(100.0-s.x_rate3,0)) AS agent_pct_lv3, AVG(COALESCE(100.0-s.x_rate4,0)) AS agent_pct_lv4,
          AVG(COALESCE(100.0-s.x_rate5,0)) AS agent_pct_lv5,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate1,0)/100.0)                        AS agent_cost_lv1,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate2,0)/100.0)                        AS agent_cost_lv2,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate3,0)/100.0)                        AS agent_cost_lv3,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate4,0)/100.0)                        AS agent_cost_lv4,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate5,0)/100.0)                        AS agent_cost_lv5,
          SUM(-s.x_net*(COALESCE(100.0-s.x_rate1,0)+COALESCE(100.0-s.x_rate2,0)
                       +COALESCE(100.0-s.x_rate3,0)+COALESCE(100.0-s.x_rate4,0)
                       +COALESCE(100.0-s.x_rate5,0))/100.0)                   AS agent_cost_chain_additive,
          SUM(-s.x_net*(1.0 - CAST(COALESCE(s.x_rate1,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate2,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate3,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate4,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate5,100) AS DOUBLE)/100.0))
                                                                       AS agent_cost_chain_nested,
           AVG(s.x_rbpct) AS rbpct, AVG(s.x_freecomm*1.0) AS freecomm_rate,
           PERCENTILE_APPROX(s.x_stake,0.25) AS p25, PERCENTILE_APPROX(s.x_stake,0.50) AS p50,
           PERCENTILE_APPROX(s.x_stake,0.75) AS p75, PERCENTILE_APPROX(s.x_stake,0.90) AS p90,
           PERCENTILE_APPROX(s.x_stake,0.95) AS p95, PERCENTILE_APPROX(s.x_stake,0.99) AS p99,
           PERCENTILE_APPROX(s.x_valid,0.50) AS p50_valid,
           PERCENTILE_APPROX(s.x_net,0.50)   AS p50_profit,
           SUM(CASE WHEN s.x_rec = 1 THEN s.x_stake ELSE 0 END) AS st_in,
           SUM(CASE WHEN s.x_rec = 1 THEN 1 ELSE 0 END)         AS nb_in,
           SUM(CASE WHEN s.x_rec = 1 THEN s.x_net ELSE 0 END)   AS net_in,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN s.x_stake ELSE 0 END) AS st_out,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN 1 ELSE 0 END)         AS nb_out,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN s.x_net ELSE 0 END)   AS net_out,
           SUM(CASE WHEN s.x_rec=1 THEN s.x_stake ELSE 0 END) AS st_rec,
           SUM(CASE WHEN s.x_rec=1 THEN 1 ELSE 0 END)         AS nb_rec
    FROM x_mk s
    WHERE s.is_clean = 1
      AND s.x_member IS NOT NULL AND TRIM(CAST(s.x_member AS STRING)) <> ''
  ),
      q AS (
        WITH cand AS (                                                                                      -- 公共表表达式：开启中间结果集 cand——六源命中之候选表
          SELECT t.TABLE_NAME                                                            AS table_name      -- 取列：表名
          FROM information_schema.tables t                                                                  -- 取数来源：取自元数据字典（表清单）
          WHERE t.TABLE_SCHEMA = 'ods_mariadb_2b'                                                           -- 过滤条件：限定 TABLE_SCHEMA等于 'ods_mariadb_2b'
            AND LOWER(t.TABLE_NAME) REGEXP                                                                  -- 并列条件：六族任一命中即入候选
              'self_?exclu|cooling|cool_?off|cooldown|responsible|_rg$|^rg_|wallet|pay|deposit|withdraw|cashier|recharge|transact|transation|fund|remit|balance|cash|order|session|login|logout|online|heartbeat|device|token|visit|mem_change|member_log|suspend|close|reopen|freeze|restrict|limit|level|vip|status|ticket|case|complain|dispute|service|support|feedback|chat|message|msg|alarm|alert|^ods_a168_(log_|change_log)|_log$|history|journal|record|trace'
        )                                                                                                   -- 续行：收束上方的子查询或函数括号
        SELECT                                                                                              -- 取列：起始取列子句
          c.TABLE_NAME                                                                   AS table_name,     -- 取列：表名
          c.ORDINAL_POSITION                                                             AS col_pos,        -- 取列：列序，供还原表结构
          c.COLUMN_NAME                                                                  AS column_name,    -- 取列：列名
          c.DATA_TYPE                                                                    AS data_type,      -- 取列：数据类型
          c.COLUMN_COMMENT                                                               AS column_comment, -- 取列：列注释——编码列唯一可读之语义线索
          CASE WHEN LOWER(c.COLUMN_NAME) REGEXP '^(bet|mem|age|lmc|emp|acc|lacc)[0-9]{2,3}$'                -- 分支判定：编码式列名
               THEN '★ 编码式列名（语义须读 COLUMN_COMMENT）' ELSE '普通列名' END          AS name_style,    -- 条件分支：产出「name_style」
          CASE                                                                                              -- 条件分支：起始分支——列义归族（★ 只作标记，不参与过滤）
            WHEN LOWER(c.COLUMN_NAME) REGEXP 'self_?exclu|cooling|cool_?off|cooldown'                       -- 分支判定：责任博彩族（★ 已去 respons，免撞 responseDate）
              OR c.COLUMN_COMMENT REGEXP '自我排除|冷靜期|冷静期|責任博彩|责任博彩|自我限制'                  -- 并列条件：中文列义命中
              THEN '★★ RG 责任博彩'                                                                        -- 分支判定：H 轴最高价值之列
            WHEN LOWER(c.COLUMN_NAME) REGEXP 'deposit|withdraw|recharge|refund|chargeback|reject|fail'       -- 分支判定：支付事件族
              OR c.COLUMN_COMMENT REGEXP '充值|入金|存款|提現|提现|出金|退款|拒付|失敗|失败'                  -- 并列条件：中文列义命中
              THEN '支付事件'                                                                               -- 分支判定：归支付事件
            WHEN LOWER(c.COLUMN_NAME) REGEXP 'amount|money|balance|fee|cash'                                -- 分支判定：金额族
              OR c.COLUMN_COMMENT REGEXP '金額|金额|餘額|余额'                                               -- 并列条件：中文列义命中
              THEN '金额'                                                                                   -- 分支判定：归金额
            WHEN LOWER(c.COLUMN_NAME) REGEXP 'login|logout|session|online|duration|heartbeat'                -- 分支判定：会话族
              OR c.COLUMN_COMMENT REGEXP '登入|登录|登出|會話|会话|在線|在线|時長|时长'                       -- 并列条件：中文列义命中
              THEN '会话'                                                                                   -- 分支判定：归会话
            WHEN LOWER(c.COLUMN_NAME) REGEXP '^(old|new|before|after|prev|from|to)_|_(old|new|before|after)$' -- 分支判定：前后态族——变更留痕之指纹
              OR c.COLUMN_COMMENT REGEXP '變更前|变更前|變更後|变更后|原值|新值'                              -- 并列条件：中文列义命中
              THEN '★ 前后态（变更留痕指纹）'                                                               -- 分支判定：H-SRC-03/06 之核心
            WHEN LOWER(c.COLUMN_NAME) REGEXP '^(uid|member_id|user_id|username|account|mem[0-9]{2,3}|bet05|age[0-9]{3}|lmc[0-9]{2})$' -- 分支判定：会员键族（含编码式）
              OR c.COLUMN_COMMENT REGEXP '會員|会员|帳號|账号'                                               -- 并列条件：中文列义命中
              THEN '★ UID 候选键'                                                                           -- 分支判定：UID 可连接性之前提
            WHEN LOWER(c.DATA_TYPE) REGEXP 'date|time'                                                      -- 分支判定：时间型——先认类型，最可靠
              OR LOWER(c.COLUMN_NAME) REGEXP 'time|date|_at$|_dt$|^dt$|created|updated'                     -- 并列条件：列名命中
              OR c.COLUMN_COMMENT REGEXP '時間|时间|日期'                                                    -- 并列条件：中文列义命中
              THEN '★ 时间候选列'                                                                           -- 分支判定：时间覆盖之前提（★ D-1 之修复：本族已入输出）
            ELSE '（未标记）'                                                                               -- 分支判定：余者照登，不丢弃
          END                                                                            AS col_family,    -- 条件分支：收束上方判词，产出「col_family」
          CASE WHEN LOWER(c.COLUMN_NAME) REGEXP 'response|respond'                                          -- 分支判定：疑似假阳性——response 曾撞 responsible
               THEN '⚠ 疑似假阳性（response 非 responsible）' ELSE '—' END                AS fp_flag,       -- 条件分支：产出「fp_flag」，不静默丢弃
          'ods_mariadb_2b'                                                               AS scope_db,      -- 字面取值：检索范围之库
          'v1.0.1 候选表全列输出（关键词只作标记不作过滤）'                              AS scope_pattern, -- 字面取值：检索范围之模式
          NOW()                                                                          AS scope_scanned_at -- 取值表达式：检索时刻
        FROM information_schema.columns c                                                                   -- 取数来源：取自元数据字典（列清单）
        JOIN cand k ON k.table_name = c.TABLE_NAME                                                          -- 连接：取自本条自建的中间结果集 cand，连接键为 table_name
        WHERE c.TABLE_SCHEMA = 'ods_mariadb_2b'                                                             -- 过滤条件：限定 TABLE_SCHEMA等于 'ods_mariadb_2b'
      )
    SELECT q.*,
           -- 一·经济层
           ROUND(e.stake,4) AS stake, ROUND(e.valid,4) AS valid_bet,
           ROUND(-e.net,4) AS profit, e.n_bets, e.n_rounds,
           ROUND(e.net/NULLIF(e.stake,0),8) AS roi,
           ROUND(e.net_in/NULLIF(e.st_in,0),8) AS roi_recent,
           ROUND(e.net_out/NULLIF(e.st_out,0),8) AS roi_non_recent,
           ROUND((e.net-e.rebate)/NULLIF(e.stake,0),8) AS roi_ex_rebate,
           ROUND(e.net,4) AS roi_numerator, ROUND(e.stake,4) AS roi_denominator,
           CASE WHEN e.stake IS NULL THEN 'NULL_DENOM' WHEN e.stake<=0 THEN 'ZERO_DENOM'
                WHEN e.n_bets<30 THEN 'THIN_EXPOSURE' ELSE 'OK' END AS roi_denominator_status,
           ROUND(e.rebate,4) AS rebate_cost, ROUND(e.agent_cost,4)                           AS cost_complement_b,
       ROUND(e.agent_pct,4)                            AS pct_complement,
       ROUND(e.company_retain_pct,4)                   AS pct_top_bet23,
       'AG03-UNRESOLVED'                                     AS agent_formula_version,
      'ALL5_LEVELS_bet23_to_bet27'                    AS agent_level_scope,
      ROUND(e.agent_cost_lv1,4) AS agent_cost_lv1, ROUND(e.agent_cost_lv2,4) AS agent_cost_lv2,
      ROUND(e.agent_cost_lv3,4) AS agent_cost_lv3, ROUND(e.agent_cost_lv4,4) AS agent_cost_lv4,
      ROUND(e.agent_cost_lv5,4) AS agent_cost_lv5,
      ROUND(e.agent_pct_lv1,6) AS agent_pct_lv1, ROUND(e.agent_pct_lv2,6) AS agent_pct_lv2,
      ROUND(e.agent_pct_lv3,6) AS agent_pct_lv3, ROUND(e.agent_pct_lv4,6) AS agent_pct_lv4,
      ROUND(e.agent_pct_lv5,6) AS agent_pct_lv5,
      ROUND(e.retain_pct_lv1,6) AS retain_pct_lv1, ROUND(e.retain_pct_lv2,6) AS retain_pct_lv2,
      ROUND(e.retain_pct_lv3,6) AS retain_pct_lv3, ROUND(e.retain_pct_lv4,6) AS retain_pct_lv4,
      ROUND(e.retain_pct_lv5,6) AS retain_pct_lv5, ROUND(e.chain_depth_avg,4) AS chain_depth_avg,
      ROUND(e.agent_cost_chain_additive,4)            AS agent_cost_chain_additive,
      ROUND(e.agent_cost_chain_nested,4)              AS agent_cost_chain_nested,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_additive,4) AS residual_chain_additive,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_nested,4)   AS residual_chain_nested,
      'PENDING_AG03'                                  AS decision_status,
      'FALSE'                                         AS admit_to_risk_decision,
      'NOT_FOR_ENFORCEMENT'                           AS deliverable_class,
       ROUND(e.agent_cost_a_legacy,4)                  AS agent_cost_a_legacy,
       ROUND(e.agent_cost_valid_base_legacy,4)         AS agent_cost_valid_base_legacy,
           ROUND(-e.net-e.rebate,4)                        AS ngr,
       ROUND(-e.net-e.rebate-e.agent_cost,4)           AS residual_b,
       ROUND(-e.net-e.rebate-e.agent_cost_a_legacy,4)  AS residual_a,
           ROUND((-e.net-e.rebate)/NULLIF(e.stake,0),8)    AS ngr_rate,
       ROUND((-e.net-e.rebate-e.agent_cost)/NULLIF(e.stake,0),8)   AS residual_b_rate,
      -- 【HF9c · canonical accounting contract】
      --   以下 canonical 字段只增加明确 scope；不删除、不覆盖既有字段。
      --   formal_bet23_* 保持 HF9b 当前生产公式及其 NULL/0 语义；
      --   lv1~lv5 / additive / nested 则分别采用各自原始 e.* 成本字段，
      --   rate 一律从未舍入的 e.* 分子 / e.stake 计算，禁止由展示值反算。
      ROUND(e.agent_cost,4) AS agent_cost_bet23_formal_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost,4) AS net_margin_bet23_formal_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost)/NULLIF(e.stake,0),8) AS net_margin_bet23_formal_rate_canonical,
      ROUND(e.agent_cost_lv1,4) AS agent_cost_lv1_bet23_canonical,
      ROUND(e.agent_cost_lv2,4) AS agent_cost_lv2_bet24_canonical,
      ROUND(e.agent_cost_lv3,4) AS agent_cost_lv3_bet25_canonical,
      ROUND(e.agent_cost_lv4,4) AS agent_cost_lv4_bet26_canonical,
      ROUND(e.agent_cost_lv5,4) AS agent_cost_lv5_bet27_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_lv1,4) AS net_margin_lv1_bet23_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_lv1)/NULLIF(e.stake,0),8) AS net_margin_lv1_bet23_rate_canonical,
      ROUND(e.agent_cost_chain_additive,4) AS agent_cost_chain_additive_canonical,
      ROUND(e.agent_cost_chain_nested,4) AS agent_cost_chain_nested_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_additive,4) AS net_margin_chain_additive_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_nested,4) AS net_margin_chain_nested_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_chain_additive)/NULLIF(e.stake,0),8) AS net_margin_chain_additive_rate_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_chain_nested)/NULLIF(e.stake,0),8) AS net_margin_chain_nested_rate_canonical,
       ROUND((-e.net-e.rebate-e.agent_cost_a_legacy)/NULLIF(e.stake,0),8) AS residual_a_rate,
           -- 二·分布层
           ROUND(e.stake/NULLIF(e.n_bets,0),4) AS avg_stake_per_bet,
           ROUND(e.valid/NULLIF(e.n_rounds,0),4) AS avg_valid_bet_per_round,
           ROUND(-e.net/NULLIF(e.n_rounds,0),4) AS avg_profit_per_round,
           ROUND(-e.net/NULLIF(e.active_days,0),4) AS avg_profit_per_day,
           ROUND(-e.net/NULLIF(e.active_shoes,0),4) AS avg_profit_per_shoe,
           ROUND(e.stake/NULLIF(e.active_days,0),4) AS avg_stake_per_active_day,
           ROUND(e.n_rounds*1.0/NULLIF(e.active_days,0),4) AS avg_rounds_per_active_day,
           ROUND(e.st_in/NULLIF(e.nb_in,0),4) AS avg_stake_recent,
           ROUND(e.st_out/NULLIF(e.nb_out,0),4) AS avg_stake_non_recent,
           ROUND(e.p25,4) AS p25_stake, ROUND(e.p50,4) AS p50_stake, ROUND(e.p75,4) AS p75_stake,
           ROUND(e.p90,4) AS p90_stake, ROUND(e.p95,4) AS p95_stake, ROUND(e.p99,4) AS p99_stake,
           ROUND(e.p50_valid,4) AS p50_valid_bet, ROUND(e.p50_profit,4) AS p50_profit,
           ROUND(e.p95/NULLIF(e.p50,0),6) AS p95_over_p50,
           ROUND(e.p99/NULLIF(e.p50,0),6) AS p99_over_p50,
           ROUND((e.stake/NULLIF(e.n_bets,0))/NULLIF(e.p50,0),6) AS avg_over_p50,
           -- 三·关系层
           e.n_tables AS common_table_count, e.n_dealers AS common_dealer_count,
           e.n_ips AS common_ip_count, e.n_products AS common_product_count,
           ROUND(e.st_in/NULLIF(e.stake,0),8) AS share_recent,
           -- 四·rate 层
           ROUND(-e.net/NULLIF(e.stake,0),8) AS hold_rate,
           ROUND(-e.net_in/NULLIF(e.st_in,0),8) AS hold_rate_recent,
           ROUND(e.rebate/NULLIF(e.valid,0),8) AS rebate_rate_actual,
           ROUND(e.rbpct,6) AS rebate_pct_config,
           ROUND(e.valid/NULLIF(e.stake,0),6) AS turnover_multiple,
           ROUND(e.freecomm_rate,6) AS free_comm_rate,
           ROUND(e.net_in/NULLIF(e.st_in,0)-e.net_out/NULLIF(e.st_out,0),8) AS roi_delta_recent,
           -- 五·动态层
           e.first_seen_d AS first_seen, e.last_seen_d AS last_seen,
           e.active_days, e.active_shoes, e.active_sessions,
           DATEDIFF(e.last_seen_d, e.first_seen_d)+1 AS span_days,
           ROUND(e.active_days*1.0/NULLIF(DATEDIFF(e.last_seen_d,e.first_seen_d)+1,0),6) AS persistence,
           ROUND((e.st_in/NULLIF(e.nb_in,0))/NULLIF(e.st_out/NULLIF(e.nb_out,0),0),6) AS ramp_recent_vs_prior,
           ROUND((e.st_rec/NULLIF(e.nb_rec,0))/NULLIF(e.stake/NULLIF(e.n_bets,0),0),6) AS ramp_recent_vs_all,
           ROUND((e.st_rec/NULLIF(e.stake,0))/0.30,6) AS stake_ramp,
           -- 六·决策层（HF9g-P5 · D-14 斧正 —— 本件属【全窗基线族】，相对刻度与决策标签一律 NULL）
           --   病灶：x_win 系全窗单行聚合（无 GROUP BY，恒 1 行，此为设计使然，非缺陷），
           --         经 CROSS JOIN 接入后 e.* 全行同值；六层之 NTILE / PERCENT_RANK 施于常数即退化，
           --         PERCENT_RANK 恒 0 ⇒ action_priority 恒判 A，全件 100% 误标。
           --   ★ 斧正原则：不给 x_win 补 GROUP BY —— 那会改变其「全窗基线」语义，属退化。
           --     正解与 #018 之 G-05／G-06 同治：范围外之行不得接受任何下游评分与决策标签。
           --   ★ 本件之 e.* 仍照常供其它列作全窗基线使用，仅六层相对刻度与决策标签置 NULL。
           CAST(NULL AS INT)                                              AS vip_tier,                        -- 空值取值：全窗基线族无实体可分档，置 NULL（NULL＝不适用，非 0）
           CAST(NULL AS DOUBLE)                                           AS economic_value,                  -- 空值取值：同上，禁以常数百分位冒充经济价值
           CAST(NULL AS DOUBLE)                                           AS roi_pr_global,                   -- 空值取值：同上
           CAST(NULL AS DOUBLE)                                           AS risk_value,                      -- 空值取值：兼容列，同上
           CAST(NULL AS DOUBLE)                                           AS pr_stake,                        -- 空值取值：兼容列，同上
           CAST(NULL AS DOUBLE)                                           AS pr_global,                       -- 空值取值：同上
           CAST(NULL AS DOUBLE)                                           AS pr_qualified,                    -- 空值取值：同上
           'GLOBAL_BASELINE_NO_ENTITY_RANKING'                            AS pr_qualified_population,         -- 字面取值：血统 —— 明示本件为全窗基线族，无实体排序总体
           CAST(NULL AS BIGINT)                                           AS pr_global_population_n,          -- 空值取值：血统 —— 不适用
           CAST(NULL AS BIGINT)                                           AS pr_qualified_population_n,       -- 空值取值：血统 —— 不适用
           'NOT_APPLICABLE_GLOBAL_BASELINE'                               AS pr_calculation_method,           -- 字面取值：血统 —— 算法不适用
           'HF9g-P5'                                                      AS pr_calculation_version,          -- 字面取值：血统 —— 算法版本
           CAST(NULL AS STRING)                                           AS evidence_flag,                   -- 空值取值：证据旗标不适用于全窗基线
           CAST(NULL AS STRING)                                           AS evidence_rate,                   -- 空值取值：同上
           CAST(NULL AS DOUBLE)                                           AS hold_ci_halfwidth_approx,        -- 空值取值：同上
           'X 全窗基线 · 不参与实体赏罚'                                    AS action_priority                  -- 字面取值：★ D-14 斧正 —— 本族恒不入赏罚，取代原 100% 误标之「A」
    FROM q
    CROSS JOIN x_win e
  ) y
) z
-- ── 逐批 WHERE 阶梯（★ 口诀：上界 ＝ 下界 ＋ 100000，两数同进）──
--    本件 T_true 未测，无需先跑 T_true；以 0 / 100000 控制本批返回区间，末批由实际行数 < 100000 判定
--    WHERE z.audit_rn >        0 AND z.audit_rn <=   100000   -- 第 1 批
--    WHERE z.audit_rn >   100000 AND z.audit_rn <=   200000   -- 第 2 批
--    WHERE z.audit_rn >   200000 AND z.audit_rn <=   300000   -- 第 3 批
--    WHERE z.audit_rn >   300000 AND z.audit_rn <=   400000   -- 第 4 批
--    WHERE z.audit_rn >   400000 AND z.audit_rn <=   500000   -- 第 5 批
--    WHERE z.audit_rn >   500000 AND z.audit_rn <=   600000   -- 第 6 批
--    WHERE z.audit_rn >   600000 AND z.audit_rn <=   700000   -- 第 7 批
--    …余批类推。第 k 批：WHERE z.audit_rn > (k-1)*100000 AND z.audit_rn <= k*100000
--    某批返回 < 100000 行即为末批，其后不再取。
--
--    ⚠ 常见误写（务必避开）：只推下界而上界不动 ——
--        WHERE z.audit_rn > 100000 AND z.audit_rn <= 100000   ← 自相矛盾，恒为假，返回空集
--        WHERE z.audit_rn > 200000 AND z.audit_rn <= 100000   ← 同上，空集
--      两个数必须**同时**前进，且始终相差 100000。
--      下界 ＝ 上一批之上界；上界 ＝ 本批之上界。
WHERE z.audit_rn > 0 AND z.audit_rn <= 100000 -- ★ HF9c 本批区间
ORDER BY z.audit_rn;


-- ══════════════════════════════════════════════════════════════════════════════════════════════
-- 125. _PH0_3_lmc_category.csv   [总包行 12598~12615 · 原 12 列 ＋六层约 60 列]
--     典型学：M10 责任博彩　派生旗标：pre_rg（s.x_rec = 1 · 仅供 CASE 条件聚合，全包无任何 WHERE/AND/HAVING 以此过滤）　连接：全窗基线
-- ══════════════════════════════════════════════════════════════════════════════════════════════
-- ★ W-64 · D-14 警示（本件属 x_win 族 · 66 件之一 · 详见 §Z 段 D-14 全案）
--   本件以 `CROSS JOIN x_win e` 接入全局基线，x_win 无 GROUP BY ⇒ 恒 1 行 ⇒ e.* 全行同值。
--   故：economic_value / roi_pr_global / risk_value / pr_stake / pr_global 恒为 0；
--       action_priority 每一行皆为「A 净亏最大十分位 · 优先复核」（Z 分支永不触发）；
--       evidence_rate 恒为最高档；vip_tier 由常数键分档 ⇒ 无信息且非确定。
--   ⇒ 本件决策层三列 **NOT_FOR_DECISION**，裁定前不得用于排班、抽查或汇报。
-- ── ① 先跑 T_true 留档（不足 100000 者一次导全，不必分批）──
-- ── ① T_true：HF9c 不再强制预跑完整 COUNT。
--    本批实际返回行数 < 100000 即判定为末批；全批完成后以各批 n_rows / audit_rn 范围核对总量。

-- ── ② 分批取数：第 1 批。第 k 批只改末行两数为 (k-1)*100000 与 k*100000 ──
--    审计字段二（REDTEAM 2026-08-24 裁定 · 四锁）：
--      audit_rn  全局观测坐标 —— 由**与原版审计版逐字同一**之排序键所生，两版可逐行对账
--      batch_id  物理分批信息 —— 该行所属批次，由 audit_rn 算得，非引擎所赋
--    ★ 锁三：二者皆为审计字段，**不得进入任何业务指标计算**。
--    ★ 锁四：两版经 audit_rn 逐行字段核验后，方可宣布输出完全一致。

-- ── ③ 每批取回后自证四数（任一不符即停手回报，禁止放行）──
--    n_rows        = COUNT(*)      须等于 COUNT(DISTINCT audit_rn)   （批内无重复）
--    audit_rn_min  = MIN(audit_rn) 须等于 (k-1)*100000 + 1           （与上批严丝合缝）
--    audit_rn_max  = MAX(audit_rn) 须等于 min + n_rows - 1           （批内无缺口）
--    全批取毕再验：各批 audit_rn 之并集 = 1 .. T_true，无缺号、无重号。
--     ★ 首行＝平台真净亏最多者（已扣退水与代理占成）。
--
SELECT z.*,
       CAST(FLOOR((z.audit_rn - 1) / 100000) + 1 AS INT)          AS batch_id,
       'A168_HF9F_20260827_0900' AS run_id,
       '2026-08-27 09:00:00' AS snapshot_sync_time
FROM (
  SELECT y.*,
         ROW_NUMBER() OVER (ORDER BY y.`residual_b` ASC, y.`roi` DESC, y.`lmc04_category`, y.`n_events`, y.`n_target_id`, y.`n_operator`, y.`dt_min`, y.`dt_max`, y.`n_in_win`, y.`avg_len_content`, y.`avg_len_sql`, y.`n_content_hit_mem01617`, y.`n_sql_hit_mem01617`, y.`n_hit_rg_semantics`) AS audit_rn
  FROM (
    WITH
      x_ranked AS (
    SELECT b.bet01, b.bet03, b.bet04, b.bet05, b.bet09, b.bet11, b.bet13,
           b.bet15, b.bet16, b.bet17, b.bet18, b.bet19, b.bet20, b.bet21,
           b.bet22, b.bet23, b.bet24, b.bet25, b.bet26, b.bet27, b.bet38, b.bet39, b.category, b.commission,
           b.dt, b.eid, b.ip, b.validbet, b.updatetime, b.sync_time,
           ROW_NUMBER() OVER (
             PARTITION BY b.bet01
             ORDER BY b.updatetime DESC, b.sync_time DESC, b.dt DESC)      AS x_rn
    FROM ods_mariadb_2b.ods_a168_bet02 b
    WHERE b.dt >= '2026-03-21' AND b.dt < '2026-08-07'
      AND b.bet02 = '101'
      AND b.sync_time <= '2026-08-27 09:00:00'
  ),
    x_testagent AS (
    SELECT age001 AS agent_id FROM ods_mariadb_2b.ods_a168_agent WHERE age022 = '1'
  ),
    x_bs0 AS (
    SELECT b.bet05 AS x_member, b.eid AS x_dealer, b.bet39 AS x_table,
           b.bet03 AS x_shoe, b.ip AS x_ip, b.bet09 AS x_product, b.dt AS x_date,
           CONCAT_WS('|', b.bet03, b.bet04, b.bet39)                      AS x_round,
           CONCAT_WS('|', b.bet39, b.bet03)                               AS x_tblshoe,
           CAST(NULLIF(TRIM(b.bet04),'') AS INT)                          AS x_rno,
           CASE WHEN b.dt >= '2026-07-08' THEN 1 ELSE 0 END               AS x_rec,
           CASE WHEN TRIM(b.commission)='1' THEN 1 ELSE 0 END             AS x_freecomm,
           CAST(NULLIF(TRIM(b.bet13),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_stake,
           CAST(NULLIF(TRIM(b.validbet),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_valid,
           CAST(NULLIF(TRIM(b.bet16),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_rebate,
           CAST(NULLIF(TRIM(b.bet17),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_net,
           CAST(NULLIF(TRIM(b.bet15),'') AS DECIMAL(20,6))                AS x_rbpct,
           COALESCE(CAST(NULLIF(TRIM(b.bet23),'') AS DECIMAL(20,6)),0)   AS x_agpct,
          NULLIF(CAST(NULLIF(TRIM(b.bet23),'') AS DECIMAL(20,6)),0)     AS x_rate1,
          NULLIF(CAST(NULLIF(TRIM(b.bet24),'') AS DECIMAL(20,6)),0)     AS x_rate2,
          NULLIF(CAST(NULLIF(TRIM(b.bet25),'') AS DECIMAL(20,6)),0)     AS x_rate3,
          NULLIF(CAST(NULLIF(TRIM(b.bet26),'') AS DECIMAL(20,6)),0)     AS x_rate4,
          NULLIF(CAST(NULLIF(TRIM(b.bet27),'') AS DECIMAL(20,6)),0)     AS x_rate5,
          (CASE WHEN NULLIF(CAST(NULLIF(TRIM(b.bet22),'') AS BIGINT),0) IS NOT NULL THEN 5
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet21),'') AS BIGINT),0) IS NOT NULL THEN 4
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet20),'') AS BIGINT),0) IS NOT NULL THEN 3
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet19),'') AS BIGINT),0) IS NOT NULL THEN 2
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet18),'') AS BIGINT),0) IS NOT NULL THEN 1
                ELSE 0 END)                                             AS x_chain_depth,
           CASE WHEN COALESCE(t1.agent_id,t2.agent_id,t3.agent_id,
                              t4.agent_id,t5.agent_id) IS NOT NULL
                THEN 1 ELSE 0 END                                        AS f_testline
    FROM x_ranked b
    LEFT JOIN x_testagent t1 ON t1.agent_id = b.bet18
    LEFT JOIN x_testagent t2 ON t2.agent_id = b.bet19
    LEFT JOIN x_testagent t3 ON t3.agent_id = b.bet20
    LEFT JOIN x_testagent t4 ON t4.agent_id = b.bet21
    LEFT JOIN x_testagent t5 ON t5.agent_id = b.bet22
    WHERE b.x_rn = 1
      AND b.category='1' AND UPPER(TRIM(b.bet38))='N'
      AND CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8)) > 0
  ),
  x_mk AS (
    SELECT s.*,
           CASE WHEN s.f_testline = 0 THEN 1 ELSE 0 END                 AS is_clean
    FROM x_bs0 s
  ),
  x_agg AS (
    SELECT s.x_member                                                        AS x_key,
           COUNT(*) AS n_bets, COUNT(DISTINCT s.x_round) AS n_rounds,
           COUNT(DISTINCT s.x_date) AS active_days, COUNT(DISTINCT s.x_tblshoe) AS active_shoes,
           COUNT(DISTINCT CONCAT_WS('|', s.x_date, s.x_table)) AS active_sessions,
           COUNT(DISTINCT s.x_table) AS n_tables, COUNT(DISTINCT s.x_dealer) AS n_dealers,
           COUNT(DISTINCT s.x_ip) AS n_ips, COUNT(DISTINCT s.x_product) AS n_products,
           MIN(s.x_date) AS first_seen_d, MAX(s.x_date) AS last_seen_d,
           SUM(s.x_stake) AS stake, SUM(s.x_valid) AS valid, SUM(s.x_rebate) AS rebate,
           SUM(s.x_net) AS net, SUM(-s.x_net *(100.0-s.x_agpct)/100.0) AS agent_cost,
           AVG(100.0-s.x_agpct)                   AS agent_pct,
           AVG(s.x_agpct)                         AS company_retain_pct,
           SUM(-s.x_net *s.x_agpct/100.0)         AS agent_cost_a_legacy,
           SUM(s.x_valid*s.x_agpct/100.0)         AS agent_cost_valid_base_legacy,
          AVG(COALESCE(s.x_rate1,100)) AS retain_pct_lv1, AVG(COALESCE(s.x_rate2,100)) AS retain_pct_lv2,
          AVG(COALESCE(s.x_rate3,100)) AS retain_pct_lv3, AVG(COALESCE(s.x_rate4,100)) AS retain_pct_lv4,
          AVG(COALESCE(s.x_rate5,100)) AS retain_pct_lv5, AVG(s.x_chain_depth) AS chain_depth_avg,
          AVG(COALESCE(100.0-s.x_rate1,0)) AS agent_pct_lv1, AVG(COALESCE(100.0-s.x_rate2,0)) AS agent_pct_lv2,
          AVG(COALESCE(100.0-s.x_rate3,0)) AS agent_pct_lv3, AVG(COALESCE(100.0-s.x_rate4,0)) AS agent_pct_lv4,
          AVG(COALESCE(100.0-s.x_rate5,0)) AS agent_pct_lv5,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate1,0)/100.0)                        AS agent_cost_lv1,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate2,0)/100.0)                        AS agent_cost_lv2,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate3,0)/100.0)                        AS agent_cost_lv3,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate4,0)/100.0)                        AS agent_cost_lv4,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate5,0)/100.0)                        AS agent_cost_lv5,
          SUM(-s.x_net*(COALESCE(100.0-s.x_rate1,0)+COALESCE(100.0-s.x_rate2,0)
                       +COALESCE(100.0-s.x_rate3,0)+COALESCE(100.0-s.x_rate4,0)
                       +COALESCE(100.0-s.x_rate5,0))/100.0)                   AS agent_cost_chain_additive,
          SUM(-s.x_net*(1.0 - CAST(COALESCE(s.x_rate1,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate2,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate3,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate4,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate5,100) AS DOUBLE)/100.0))
                                                                       AS agent_cost_chain_nested,
           AVG(s.x_rbpct) AS rbpct, AVG(s.x_freecomm*1.0) AS freecomm_rate,
           PERCENTILE_APPROX(s.x_stake,0.25) AS p25, PERCENTILE_APPROX(s.x_stake,0.50) AS p50,
           PERCENTILE_APPROX(s.x_stake,0.75) AS p75, PERCENTILE_APPROX(s.x_stake,0.90) AS p90,
           PERCENTILE_APPROX(s.x_stake,0.95) AS p95, PERCENTILE_APPROX(s.x_stake,0.99) AS p99,
           PERCENTILE_APPROX(s.x_valid,0.50) AS p50_valid,
           PERCENTILE_APPROX(s.x_net,0.50)   AS p50_profit,
           SUM(CASE WHEN s.x_rec = 1 THEN s.x_stake ELSE 0 END) AS st_in,
           SUM(CASE WHEN s.x_rec = 1 THEN 1 ELSE 0 END)         AS nb_in,
           SUM(CASE WHEN s.x_rec = 1 THEN s.x_net ELSE 0 END)   AS net_in,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN s.x_stake ELSE 0 END) AS st_out,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN 1 ELSE 0 END)         AS nb_out,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN s.x_net ELSE 0 END)   AS net_out,
           SUM(CASE WHEN s.x_rec=1 THEN s.x_stake ELSE 0 END) AS st_rec,
           SUM(CASE WHEN s.x_rec=1 THEN 1 ELSE 0 END)         AS nb_rec
    FROM x_mk s
    WHERE s.is_clean = 1
      AND s.x_member IS NOT NULL AND TRIM(CAST(s.x_member AS STRING)) <> ''
    GROUP BY s.x_member
  ),
  x_win AS (
    SELECT            COUNT(*) AS n_bets, COUNT(DISTINCT s.x_round) AS n_rounds,
           COUNT(DISTINCT s.x_date) AS active_days, COUNT(DISTINCT s.x_tblshoe) AS active_shoes,
           COUNT(DISTINCT CONCAT_WS('|', s.x_date, s.x_table)) AS active_sessions,
           COUNT(DISTINCT s.x_table) AS n_tables, COUNT(DISTINCT s.x_dealer) AS n_dealers,
           COUNT(DISTINCT s.x_ip) AS n_ips, COUNT(DISTINCT s.x_product) AS n_products,
           MIN(s.x_date) AS first_seen_d, MAX(s.x_date) AS last_seen_d,
           SUM(s.x_stake) AS stake, SUM(s.x_valid) AS valid, SUM(s.x_rebate) AS rebate,
           SUM(s.x_net) AS net, SUM(-s.x_net *(100.0-s.x_agpct)/100.0) AS agent_cost,
           AVG(100.0-s.x_agpct)                   AS agent_pct,
           AVG(s.x_agpct)                         AS company_retain_pct,
           SUM(-s.x_net *s.x_agpct/100.0)         AS agent_cost_a_legacy,
           SUM(s.x_valid*s.x_agpct/100.0)         AS agent_cost_valid_base_legacy,
          AVG(COALESCE(s.x_rate1,100)) AS retain_pct_lv1, AVG(COALESCE(s.x_rate2,100)) AS retain_pct_lv2,
          AVG(COALESCE(s.x_rate3,100)) AS retain_pct_lv3, AVG(COALESCE(s.x_rate4,100)) AS retain_pct_lv4,
          AVG(COALESCE(s.x_rate5,100)) AS retain_pct_lv5, AVG(s.x_chain_depth) AS chain_depth_avg,
          AVG(COALESCE(100.0-s.x_rate1,0)) AS agent_pct_lv1, AVG(COALESCE(100.0-s.x_rate2,0)) AS agent_pct_lv2,
          AVG(COALESCE(100.0-s.x_rate3,0)) AS agent_pct_lv3, AVG(COALESCE(100.0-s.x_rate4,0)) AS agent_pct_lv4,
          AVG(COALESCE(100.0-s.x_rate5,0)) AS agent_pct_lv5,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate1,0)/100.0)                        AS agent_cost_lv1,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate2,0)/100.0)                        AS agent_cost_lv2,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate3,0)/100.0)                        AS agent_cost_lv3,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate4,0)/100.0)                        AS agent_cost_lv4,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate5,0)/100.0)                        AS agent_cost_lv5,
          SUM(-s.x_net*(COALESCE(100.0-s.x_rate1,0)+COALESCE(100.0-s.x_rate2,0)
                       +COALESCE(100.0-s.x_rate3,0)+COALESCE(100.0-s.x_rate4,0)
                       +COALESCE(100.0-s.x_rate5,0))/100.0)                   AS agent_cost_chain_additive,
          SUM(-s.x_net*(1.0 - CAST(COALESCE(s.x_rate1,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate2,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate3,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate4,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate5,100) AS DOUBLE)/100.0))
                                                                       AS agent_cost_chain_nested,
           AVG(s.x_rbpct) AS rbpct, AVG(s.x_freecomm*1.0) AS freecomm_rate,
           PERCENTILE_APPROX(s.x_stake,0.25) AS p25, PERCENTILE_APPROX(s.x_stake,0.50) AS p50,
           PERCENTILE_APPROX(s.x_stake,0.75) AS p75, PERCENTILE_APPROX(s.x_stake,0.90) AS p90,
           PERCENTILE_APPROX(s.x_stake,0.95) AS p95, PERCENTILE_APPROX(s.x_stake,0.99) AS p99,
           PERCENTILE_APPROX(s.x_valid,0.50) AS p50_valid,
           PERCENTILE_APPROX(s.x_net,0.50)   AS p50_profit,
           SUM(CASE WHEN s.x_rec = 1 THEN s.x_stake ELSE 0 END) AS st_in,
           SUM(CASE WHEN s.x_rec = 1 THEN 1 ELSE 0 END)         AS nb_in,
           SUM(CASE WHEN s.x_rec = 1 THEN s.x_net ELSE 0 END)   AS net_in,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN s.x_stake ELSE 0 END) AS st_out,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN 1 ELSE 0 END)         AS nb_out,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN s.x_net ELSE 0 END)   AS net_out,
           SUM(CASE WHEN s.x_rec=1 THEN s.x_stake ELSE 0 END) AS st_rec,
           SUM(CASE WHEN s.x_rec=1 THEN 1 ELSE 0 END)         AS nb_rec
    FROM x_mk s
    WHERE s.is_clean = 1
      AND s.x_member IS NOT NULL AND TRIM(CAST(s.x_member AS STRING)) <> ''
  ),
      q AS (
        SELECT                                                                                              -- 取列：起始取列子句
          COALESCE(NULLIF(TRIM(lmc04), ''), '（空）')                            AS lmc04_category,         -- 取值表达式：變更類別，空值归一为「（空）」
          COUNT(*)                                                               AS n_events,               -- 计数表达式：事件数
          COUNT(DISTINCT TRIM(lmc02))                                            AS n_target_id,            -- 计数表达式：去重被改对象 ID（lmc02 = ID）
          COUNT(DISTINCT TRIM(lmc06))                                            AS n_operator,             -- 计数表达式：去重操作者数（lmc06 = 操作者）
          MIN(dt)                                                                AS dt_min,                 -- 聚合取值：分区日下界
          MAX(dt)                                                                AS dt_max,                 -- 聚合取值：分区日上界
          SUM(CASE WHEN dt >= '2026-03-21' AND dt < '2026-08-07' THEN 1 ELSE 0 END) AS n_in_win,            -- 条件计数：窗内事件数
          ROUND(AVG(LENGTH(COALESCE(lmc05, ''))), 2)                             AS avg_len_content,        -- 聚合取值：內容平均长度，判文本解析之工作量
          ROUND(AVG(LENGTH(COALESCE(lmc09, ''))), 2)                             AS avg_len_sql,            -- 聚合取值：SQL 平均长度
          SUM(CASE WHEN lmc05 REGEXP 'mem016|mem017' THEN 1 ELSE 0 END)          AS n_content_hit_mem01617, -- 条件计数：★ 內容文本命中 mem016/mem017 之行数
          SUM(CASE WHEN lmc09 REGEXP 'mem016|mem017' THEN 1 ELSE 0 END)          AS n_sql_hit_mem01617,     -- 条件计数：★ SQL 文本命中 mem016/mem017 之行数
          SUM(CASE WHEN CONCAT(COALESCE(lmc05, ''), COALESCE(lmc09, ''))
                        REGEXP '自我|排除|冷靜|冷静|責任|责任|限額|限额|凍結|冻结|停用|封鎖|封锁'
                   THEN 1 ELSE 0 END)                                            AS n_hit_rg_semantics      -- 条件计数：★★ 文本内是否含责任博彩语义——RG 之最后一线希望
        FROM ods_mariadb_2b.ods_a168_log_mem_change                                                         -- 取数来源：取自会员变更日志表
        GROUP BY COALESCE(NULLIF(TRIM(lmc04), ''), '（空）')                                                 -- 分组：按變更類別汇总
      )
    SELECT q.*,
           -- 一·经济层
           ROUND(e.stake,4) AS stake, ROUND(e.valid,4) AS valid_bet,
           ROUND(-e.net,4) AS profit, e.n_bets, e.n_rounds,
           ROUND(e.net/NULLIF(e.stake,0),8) AS roi,
           ROUND(e.net_in/NULLIF(e.st_in,0),8) AS roi_pre_rg,
           ROUND(e.net_out/NULLIF(e.st_out,0),8) AS roi_non_pre_rg,
           ROUND((e.net-e.rebate)/NULLIF(e.stake,0),8) AS roi_ex_rebate,
           ROUND(e.net,4) AS roi_numerator, ROUND(e.stake,4) AS roi_denominator,
           CASE WHEN e.stake IS NULL THEN 'NULL_DENOM' WHEN e.stake<=0 THEN 'ZERO_DENOM'
                WHEN e.n_bets<30 THEN 'THIN_EXPOSURE' ELSE 'OK' END AS roi_denominator_status,
           ROUND(e.rebate,4) AS rebate_cost, ROUND(e.agent_cost,4)                           AS cost_complement_b,
       ROUND(e.agent_pct,4)                            AS pct_complement,
       ROUND(e.company_retain_pct,4)                   AS pct_top_bet23,
       'AG03-UNRESOLVED'                                     AS agent_formula_version,
      'ALL5_LEVELS_bet23_to_bet27'                    AS agent_level_scope,
      ROUND(e.agent_cost_lv1,4) AS agent_cost_lv1, ROUND(e.agent_cost_lv2,4) AS agent_cost_lv2,
      ROUND(e.agent_cost_lv3,4) AS agent_cost_lv3, ROUND(e.agent_cost_lv4,4) AS agent_cost_lv4,
      ROUND(e.agent_cost_lv5,4) AS agent_cost_lv5,
      ROUND(e.agent_pct_lv1,6) AS agent_pct_lv1, ROUND(e.agent_pct_lv2,6) AS agent_pct_lv2,
      ROUND(e.agent_pct_lv3,6) AS agent_pct_lv3, ROUND(e.agent_pct_lv4,6) AS agent_pct_lv4,
      ROUND(e.agent_pct_lv5,6) AS agent_pct_lv5,
      ROUND(e.retain_pct_lv1,6) AS retain_pct_lv1, ROUND(e.retain_pct_lv2,6) AS retain_pct_lv2,
      ROUND(e.retain_pct_lv3,6) AS retain_pct_lv3, ROUND(e.retain_pct_lv4,6) AS retain_pct_lv4,
      ROUND(e.retain_pct_lv5,6) AS retain_pct_lv5, ROUND(e.chain_depth_avg,4) AS chain_depth_avg,
      ROUND(e.agent_cost_chain_additive,4)            AS agent_cost_chain_additive,
      ROUND(e.agent_cost_chain_nested,4)              AS agent_cost_chain_nested,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_additive,4) AS residual_chain_additive,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_nested,4)   AS residual_chain_nested,
      'PENDING_AG03'                                  AS decision_status,
      'FALSE'                                         AS admit_to_risk_decision,
      'NOT_FOR_ENFORCEMENT'                           AS deliverable_class,
       ROUND(e.agent_cost_a_legacy,4)                  AS agent_cost_a_legacy,
       ROUND(e.agent_cost_valid_base_legacy,4)         AS agent_cost_valid_base_legacy,
           ROUND(-e.net-e.rebate,4)                        AS ngr,
       ROUND(-e.net-e.rebate-e.agent_cost,4)           AS residual_b,
       ROUND(-e.net-e.rebate-e.agent_cost_a_legacy,4)  AS residual_a,
           ROUND((-e.net-e.rebate)/NULLIF(e.stake,0),8)    AS ngr_rate,
       ROUND((-e.net-e.rebate-e.agent_cost)/NULLIF(e.stake,0),8)   AS residual_b_rate,
      -- 【HF9c · canonical accounting contract】
      --   以下 canonical 字段只增加明确 scope；不删除、不覆盖既有字段。
      --   formal_bet23_* 保持 HF9b 当前生产公式及其 NULL/0 语义；
      --   lv1~lv5 / additive / nested 则分别采用各自原始 e.* 成本字段，
      --   rate 一律从未舍入的 e.* 分子 / e.stake 计算，禁止由展示值反算。
      ROUND(e.agent_cost,4) AS agent_cost_bet23_formal_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost,4) AS net_margin_bet23_formal_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost)/NULLIF(e.stake,0),8) AS net_margin_bet23_formal_rate_canonical,
      ROUND(e.agent_cost_lv1,4) AS agent_cost_lv1_bet23_canonical,
      ROUND(e.agent_cost_lv2,4) AS agent_cost_lv2_bet24_canonical,
      ROUND(e.agent_cost_lv3,4) AS agent_cost_lv3_bet25_canonical,
      ROUND(e.agent_cost_lv4,4) AS agent_cost_lv4_bet26_canonical,
      ROUND(e.agent_cost_lv5,4) AS agent_cost_lv5_bet27_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_lv1,4) AS net_margin_lv1_bet23_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_lv1)/NULLIF(e.stake,0),8) AS net_margin_lv1_bet23_rate_canonical,
      ROUND(e.agent_cost_chain_additive,4) AS agent_cost_chain_additive_canonical,
      ROUND(e.agent_cost_chain_nested,4) AS agent_cost_chain_nested_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_additive,4) AS net_margin_chain_additive_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_nested,4) AS net_margin_chain_nested_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_chain_additive)/NULLIF(e.stake,0),8) AS net_margin_chain_additive_rate_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_chain_nested)/NULLIF(e.stake,0),8) AS net_margin_chain_nested_rate_canonical,
       ROUND((-e.net-e.rebate-e.agent_cost_a_legacy)/NULLIF(e.stake,0),8) AS residual_a_rate,
           -- 二·分布层
           ROUND(e.stake/NULLIF(e.n_bets,0),4) AS avg_stake_per_bet,
           ROUND(e.valid/NULLIF(e.n_rounds,0),4) AS avg_valid_bet_per_round,
           ROUND(-e.net/NULLIF(e.n_rounds,0),4) AS avg_profit_per_round,
           ROUND(-e.net/NULLIF(e.active_days,0),4) AS avg_profit_per_day,
           ROUND(-e.net/NULLIF(e.active_shoes,0),4) AS avg_profit_per_shoe,
           ROUND(e.stake/NULLIF(e.active_days,0),4) AS avg_stake_per_active_day,
           ROUND(e.n_rounds*1.0/NULLIF(e.active_days,0),4) AS avg_rounds_per_active_day,
           ROUND(e.st_in/NULLIF(e.nb_in,0),4) AS avg_stake_pre_rg,
           ROUND(e.st_out/NULLIF(e.nb_out,0),4) AS avg_stake_non_pre_rg,
           ROUND(e.p25,4) AS p25_stake, ROUND(e.p50,4) AS p50_stake, ROUND(e.p75,4) AS p75_stake,
           ROUND(e.p90,4) AS p90_stake, ROUND(e.p95,4) AS p95_stake, ROUND(e.p99,4) AS p99_stake,
           ROUND(e.p50_valid,4) AS p50_valid_bet, ROUND(e.p50_profit,4) AS p50_profit,
           ROUND(e.p95/NULLIF(e.p50,0),6) AS p95_over_p50,
           ROUND(e.p99/NULLIF(e.p50,0),6) AS p99_over_p50,
           ROUND((e.stake/NULLIF(e.n_bets,0))/NULLIF(e.p50,0),6) AS avg_over_p50,
           -- 三·关系层
           e.n_tables AS common_table_count, e.n_dealers AS common_dealer_count,
           e.n_ips AS common_ip_count, e.n_products AS common_product_count,
           ROUND(e.st_in/NULLIF(e.stake,0),8) AS share_pre_rg,
           -- 四·rate 层
           ROUND(-e.net/NULLIF(e.stake,0),8) AS hold_rate,
           ROUND(-e.net_in/NULLIF(e.st_in,0),8) AS hold_rate_pre_rg,
           ROUND(e.rebate/NULLIF(e.valid,0),8) AS rebate_rate_actual,
           ROUND(e.rbpct,6) AS rebate_pct_config,
           ROUND(e.valid/NULLIF(e.stake,0),6) AS turnover_multiple,
           ROUND(e.freecomm_rate,6) AS free_comm_rate,
           ROUND(e.net_in/NULLIF(e.st_in,0)-e.net_out/NULLIF(e.st_out,0),8) AS roi_delta_pre_rg,
           -- 五·动态层
           e.first_seen_d AS first_seen, e.last_seen_d AS last_seen,
           e.active_days, e.active_shoes, e.active_sessions,
           DATEDIFF(e.last_seen_d, e.first_seen_d)+1 AS span_days,
           ROUND(e.active_days*1.0/NULLIF(DATEDIFF(e.last_seen_d,e.first_seen_d)+1,0),6) AS persistence,
           ROUND((e.st_in/NULLIF(e.nb_in,0))/NULLIF(e.st_out/NULLIF(e.nb_out,0),0),6) AS ramp_pre_rg,
           ROUND((e.st_rec/NULLIF(e.nb_rec,0))/NULLIF(e.stake/NULLIF(e.n_bets,0),0),6) AS ramp_recent,
           ROUND((e.st_rec/NULLIF(e.stake,0))/0.30,6) AS stake_ramp,
           -- 六·决策层（HF9g-P5 · D-14 斧正 —— 本件属【全窗基线族】，相对刻度与决策标签一律 NULL）
           --   病灶：x_win 系全窗单行聚合（无 GROUP BY，恒 1 行，此为设计使然，非缺陷），
           --         经 CROSS JOIN 接入后 e.* 全行同值；六层之 NTILE / PERCENT_RANK 施于常数即退化，
           --         PERCENT_RANK 恒 0 ⇒ action_priority 恒判 A，全件 100% 误标。
           --   ★ 斧正原则：不给 x_win 补 GROUP BY —— 那会改变其「全窗基线」语义，属退化。
           --     正解与 #018 之 G-05／G-06 同治：范围外之行不得接受任何下游评分与决策标签。
           --   ★ 本件之 e.* 仍照常供其它列作全窗基线使用，仅六层相对刻度与决策标签置 NULL。
           CAST(NULL AS INT)                                              AS vip_tier,                        -- 空值取值：全窗基线族无实体可分档，置 NULL（NULL＝不适用，非 0）
           CAST(NULL AS DOUBLE)                                           AS economic_value,                  -- 空值取值：同上，禁以常数百分位冒充经济价值
           CAST(NULL AS DOUBLE)                                           AS roi_pr_global,                   -- 空值取值：同上
           CAST(NULL AS DOUBLE)                                           AS risk_value,                      -- 空值取值：兼容列，同上
           CAST(NULL AS DOUBLE)                                           AS pr_stake,                        -- 空值取值：兼容列，同上
           CAST(NULL AS DOUBLE)                                           AS pr_global,                       -- 空值取值：同上
           CAST(NULL AS DOUBLE)                                           AS pr_qualified,                    -- 空值取值：同上
           'GLOBAL_BASELINE_NO_ENTITY_RANKING'                            AS pr_qualified_population,         -- 字面取值：血统 —— 明示本件为全窗基线族，无实体排序总体
           CAST(NULL AS BIGINT)                                           AS pr_global_population_n,          -- 空值取值：血统 —— 不适用
           CAST(NULL AS BIGINT)                                           AS pr_qualified_population_n,       -- 空值取值：血统 —— 不适用
           'NOT_APPLICABLE_GLOBAL_BASELINE'                               AS pr_calculation_method,           -- 字面取值：血统 —— 算法不适用
           'HF9g-P5'                                                      AS pr_calculation_version,          -- 字面取值：血统 —— 算法版本
           CAST(NULL AS STRING)                                           AS evidence_flag,                   -- 空值取值：证据旗标不适用于全窗基线
           CAST(NULL AS STRING)                                           AS evidence_rate,                   -- 空值取值：同上
           CAST(NULL AS DOUBLE)                                           AS hold_ci_halfwidth_approx,        -- 空值取值：同上
           'X 全窗基线 · 不参与实体赏罚'                                    AS action_priority                  -- 字面取值：★ D-14 斧正 —— 本族恒不入赏罚，取代原 100% 误标之「A」
    FROM q
    CROSS JOIN x_win e
  ) y
) z
-- ── 逐批 WHERE 阶梯（★ 口诀：上界 ＝ 下界 ＋ 100000，两数同进）──
--    本件 T_true 未测，无需先跑 T_true；以 0 / 100000 控制本批返回区间，末批由实际行数 < 100000 判定
--    WHERE z.audit_rn >        0 AND z.audit_rn <=   100000   -- 第 1 批
--    WHERE z.audit_rn >   100000 AND z.audit_rn <=   200000   -- 第 2 批
--    WHERE z.audit_rn >   200000 AND z.audit_rn <=   300000   -- 第 3 批
--    WHERE z.audit_rn >   300000 AND z.audit_rn <=   400000   -- 第 4 批
--    WHERE z.audit_rn >   400000 AND z.audit_rn <=   500000   -- 第 5 批
--    WHERE z.audit_rn >   500000 AND z.audit_rn <=   600000   -- 第 6 批
--    WHERE z.audit_rn >   600000 AND z.audit_rn <=   700000   -- 第 7 批
--    …余批类推。第 k 批：WHERE z.audit_rn > (k-1)*100000 AND z.audit_rn <= k*100000
--    某批返回 < 100000 行即为末批，其后不再取。
--
--    ⚠ 常见误写（务必避开）：只推下界而上界不动 ——
--        WHERE z.audit_rn > 100000 AND z.audit_rn <= 100000   ← 自相矛盾，恒为假，返回空集
--        WHERE z.audit_rn > 200000 AND z.audit_rn <= 100000   ← 同上，空集
--      两个数必须**同时**前进，且始终相差 100000。
--      下界 ＝ 上一批之上界；上界 ＝ 本批之上界。
WHERE z.audit_rn > 0 AND z.audit_rn <= 100000 -- ★ HF9c 本批区间
ORDER BY z.audit_rn;


-- ══════════════════════════════════════════════════════════════════════════════════════════════
-- 126. _PH0_4L1_member_columns.csv   [总包行 12811~12820 · 原 5 列 ＋六层约 60 列]
--     典型学：Z00 基建/元数据　派生旗标：recent（s.x_rec = 1 · 仅供 CASE 条件聚合，全包无任何 WHERE/AND/HAVING 以此过滤）　连接：全窗基线
-- ══════════════════════════════════════════════════════════════════════════════════════════════
-- ★ W-64 · D-14 警示（本件属 x_win 族 · 66 件之一 · 详见 §Z 段 D-14 全案）
--   本件以 `CROSS JOIN x_win e` 接入全局基线，x_win 无 GROUP BY ⇒ 恒 1 行 ⇒ e.* 全行同值。
--   故：economic_value / roi_pr_global / risk_value / pr_stake / pr_global 恒为 0；
--       action_priority 每一行皆为「A 净亏最大十分位 · 优先复核」（Z 分支永不触发）；
--       evidence_rate 恒为最高档；vip_tier 由常数键分档 ⇒ 无信息且非确定。
--   ⇒ 本件决策层三列 **NOT_FOR_DECISION**，裁定前不得用于排班、抽查或汇报。
-- ── ① 先跑 T_true 留档（不足 100000 者一次导全，不必分批）──
-- ── ① T_true：HF9c 不再强制预跑完整 COUNT。
--    本批实际返回行数 < 100000 即判定为末批；全批完成后以各批 n_rows / audit_rn 范围核对总量。

-- ── ② 分批取数：第 1 批。第 k 批只改末行两数为 (k-1)*100000 与 k*100000 ──
--    审计字段二（REDTEAM 2026-08-24 裁定 · 四锁）：
--      audit_rn  全局观测坐标 —— 由**与原版审计版逐字同一**之排序键所生，两版可逐行对账
--      batch_id  物理分批信息 —— 该行所属批次，由 audit_rn 算得，非引擎所赋
--    ★ 锁三：二者皆为审计字段，**不得进入任何业务指标计算**。
--    ★ 锁四：两版经 audit_rn 逐行字段核验后，方可宣布输出完全一致。

-- ── ③ 每批取回后自证四数（任一不符即停手回报，禁止放行）──
--    n_rows        = COUNT(*)      须等于 COUNT(DISTINCT audit_rn)   （批内无重复）
--    audit_rn_min  = MIN(audit_rn) 须等于 (k-1)*100000 + 1           （与上批严丝合缝）
--    audit_rn_max  = MAX(audit_rn) 须等于 min + n_rows - 1           （批内无缺口）
--    全批取毕再验：各批 audit_rn 之并集 = 1 .. T_true，无缺号、无重号。
--     ★ 首行＝平台真净亏最多者（已扣退水与代理占成）。
--
SELECT z.*,
       CAST(FLOOR((z.audit_rn - 1) / 100000) + 1 AS INT)          AS batch_id,
       'A168_HF9F_20260827_0900' AS run_id,
       '2026-08-27 09:00:00' AS snapshot_sync_time
FROM (
  SELECT y.*,
         ROW_NUMBER() OVER (ORDER BY y.`residual_b` ASC, y.`roi` DESC, y.`table_name`, y.`col_pos`, y.`column_name`, y.`data_type`, y.`column_comment`) AS audit_rn
  FROM (
    WITH
      x_ranked AS (
    SELECT b.bet01, b.bet03, b.bet04, b.bet05, b.bet09, b.bet11, b.bet13,
           b.bet15, b.bet16, b.bet17, b.bet18, b.bet19, b.bet20, b.bet21,
           b.bet22, b.bet23, b.bet24, b.bet25, b.bet26, b.bet27, b.bet38, b.bet39, b.category, b.commission,
           b.dt, b.eid, b.ip, b.validbet, b.updatetime, b.sync_time,
           ROW_NUMBER() OVER (
             PARTITION BY b.bet01
             ORDER BY b.updatetime DESC, b.sync_time DESC, b.dt DESC)      AS x_rn
    FROM ods_mariadb_2b.ods_a168_bet02 b
    WHERE b.dt >= '2026-03-21' AND b.dt < '2026-08-07'
      AND b.bet02 = '101'
      AND b.sync_time <= '2026-08-27 09:00:00'
  ),
    x_testagent AS (
    SELECT age001 AS agent_id FROM ods_mariadb_2b.ods_a168_agent WHERE age022 = '1'
  ),
    x_bs0 AS (
    SELECT b.bet05 AS x_member, b.eid AS x_dealer, b.bet39 AS x_table,
           b.bet03 AS x_shoe, b.ip AS x_ip, b.bet09 AS x_product, b.dt AS x_date,
           CONCAT_WS('|', b.bet03, b.bet04, b.bet39)                      AS x_round,
           CONCAT_WS('|', b.bet39, b.bet03)                               AS x_tblshoe,
           CAST(NULLIF(TRIM(b.bet04),'') AS INT)                          AS x_rno,
           CASE WHEN b.dt >= '2026-07-08' THEN 1 ELSE 0 END               AS x_rec,
           CASE WHEN TRIM(b.commission)='1' THEN 1 ELSE 0 END             AS x_freecomm,
           CAST(NULLIF(TRIM(b.bet13),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_stake,
           CAST(NULLIF(TRIM(b.validbet),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_valid,
           CAST(NULLIF(TRIM(b.bet16),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_rebate,
           CAST(NULLIF(TRIM(b.bet17),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_net,
           CAST(NULLIF(TRIM(b.bet15),'') AS DECIMAL(20,6))                AS x_rbpct,
           COALESCE(CAST(NULLIF(TRIM(b.bet23),'') AS DECIMAL(20,6)),0)   AS x_agpct,
          NULLIF(CAST(NULLIF(TRIM(b.bet23),'') AS DECIMAL(20,6)),0)     AS x_rate1,
          NULLIF(CAST(NULLIF(TRIM(b.bet24),'') AS DECIMAL(20,6)),0)     AS x_rate2,
          NULLIF(CAST(NULLIF(TRIM(b.bet25),'') AS DECIMAL(20,6)),0)     AS x_rate3,
          NULLIF(CAST(NULLIF(TRIM(b.bet26),'') AS DECIMAL(20,6)),0)     AS x_rate4,
          NULLIF(CAST(NULLIF(TRIM(b.bet27),'') AS DECIMAL(20,6)),0)     AS x_rate5,
          (CASE WHEN NULLIF(CAST(NULLIF(TRIM(b.bet22),'') AS BIGINT),0) IS NOT NULL THEN 5
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet21),'') AS BIGINT),0) IS NOT NULL THEN 4
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet20),'') AS BIGINT),0) IS NOT NULL THEN 3
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet19),'') AS BIGINT),0) IS NOT NULL THEN 2
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet18),'') AS BIGINT),0) IS NOT NULL THEN 1
                ELSE 0 END)                                             AS x_chain_depth,
           CASE WHEN COALESCE(t1.agent_id,t2.agent_id,t3.agent_id,
                              t4.agent_id,t5.agent_id) IS NOT NULL
                THEN 1 ELSE 0 END                                        AS f_testline
    FROM x_ranked b
    LEFT JOIN x_testagent t1 ON t1.agent_id = b.bet18
    LEFT JOIN x_testagent t2 ON t2.agent_id = b.bet19
    LEFT JOIN x_testagent t3 ON t3.agent_id = b.bet20
    LEFT JOIN x_testagent t4 ON t4.agent_id = b.bet21
    LEFT JOIN x_testagent t5 ON t5.agent_id = b.bet22
    WHERE b.x_rn = 1
      AND b.category='1' AND UPPER(TRIM(b.bet38))='N'
      AND CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8)) > 0
  ),
  x_mk AS (
    SELECT s.*,
           CASE WHEN s.f_testline = 0 THEN 1 ELSE 0 END                 AS is_clean
    FROM x_bs0 s
  ),
  x_agg AS (
    SELECT s.x_member                                                        AS x_key,
           COUNT(*) AS n_bets, COUNT(DISTINCT s.x_round) AS n_rounds,
           COUNT(DISTINCT s.x_date) AS active_days, COUNT(DISTINCT s.x_tblshoe) AS active_shoes,
           COUNT(DISTINCT CONCAT_WS('|', s.x_date, s.x_table)) AS active_sessions,
           COUNT(DISTINCT s.x_table) AS n_tables, COUNT(DISTINCT s.x_dealer) AS n_dealers,
           COUNT(DISTINCT s.x_ip) AS n_ips, COUNT(DISTINCT s.x_product) AS n_products,
           MIN(s.x_date) AS first_seen_d, MAX(s.x_date) AS last_seen_d,
           SUM(s.x_stake) AS stake, SUM(s.x_valid) AS valid, SUM(s.x_rebate) AS rebate,
           SUM(s.x_net) AS net, SUM(-s.x_net *(100.0-s.x_agpct)/100.0) AS agent_cost,
           AVG(100.0-s.x_agpct)                   AS agent_pct,
           AVG(s.x_agpct)                         AS company_retain_pct,
           SUM(-s.x_net *s.x_agpct/100.0)         AS agent_cost_a_legacy,
           SUM(s.x_valid*s.x_agpct/100.0)         AS agent_cost_valid_base_legacy,
          AVG(COALESCE(s.x_rate1,100)) AS retain_pct_lv1, AVG(COALESCE(s.x_rate2,100)) AS retain_pct_lv2,
          AVG(COALESCE(s.x_rate3,100)) AS retain_pct_lv3, AVG(COALESCE(s.x_rate4,100)) AS retain_pct_lv4,
          AVG(COALESCE(s.x_rate5,100)) AS retain_pct_lv5, AVG(s.x_chain_depth) AS chain_depth_avg,
          AVG(COALESCE(100.0-s.x_rate1,0)) AS agent_pct_lv1, AVG(COALESCE(100.0-s.x_rate2,0)) AS agent_pct_lv2,
          AVG(COALESCE(100.0-s.x_rate3,0)) AS agent_pct_lv3, AVG(COALESCE(100.0-s.x_rate4,0)) AS agent_pct_lv4,
          AVG(COALESCE(100.0-s.x_rate5,0)) AS agent_pct_lv5,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate1,0)/100.0)                        AS agent_cost_lv1,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate2,0)/100.0)                        AS agent_cost_lv2,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate3,0)/100.0)                        AS agent_cost_lv3,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate4,0)/100.0)                        AS agent_cost_lv4,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate5,0)/100.0)                        AS agent_cost_lv5,
          SUM(-s.x_net*(COALESCE(100.0-s.x_rate1,0)+COALESCE(100.0-s.x_rate2,0)
                       +COALESCE(100.0-s.x_rate3,0)+COALESCE(100.0-s.x_rate4,0)
                       +COALESCE(100.0-s.x_rate5,0))/100.0)                   AS agent_cost_chain_additive,
          SUM(-s.x_net*(1.0 - CAST(COALESCE(s.x_rate1,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate2,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate3,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate4,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate5,100) AS DOUBLE)/100.0))
                                                                       AS agent_cost_chain_nested,
           AVG(s.x_rbpct) AS rbpct, AVG(s.x_freecomm*1.0) AS freecomm_rate,
           PERCENTILE_APPROX(s.x_stake,0.25) AS p25, PERCENTILE_APPROX(s.x_stake,0.50) AS p50,
           PERCENTILE_APPROX(s.x_stake,0.75) AS p75, PERCENTILE_APPROX(s.x_stake,0.90) AS p90,
           PERCENTILE_APPROX(s.x_stake,0.95) AS p95, PERCENTILE_APPROX(s.x_stake,0.99) AS p99,
           PERCENTILE_APPROX(s.x_valid,0.50) AS p50_valid,
           PERCENTILE_APPROX(s.x_net,0.50)   AS p50_profit,
           SUM(CASE WHEN s.x_rec = 1 THEN s.x_stake ELSE 0 END) AS st_in,
           SUM(CASE WHEN s.x_rec = 1 THEN 1 ELSE 0 END)         AS nb_in,
           SUM(CASE WHEN s.x_rec = 1 THEN s.x_net ELSE 0 END)   AS net_in,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN s.x_stake ELSE 0 END) AS st_out,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN 1 ELSE 0 END)         AS nb_out,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN s.x_net ELSE 0 END)   AS net_out,
           SUM(CASE WHEN s.x_rec=1 THEN s.x_stake ELSE 0 END) AS st_rec,
           SUM(CASE WHEN s.x_rec=1 THEN 1 ELSE 0 END)         AS nb_rec
    FROM x_mk s
    WHERE s.is_clean = 1
      AND s.x_member IS NOT NULL AND TRIM(CAST(s.x_member AS STRING)) <> ''
    GROUP BY s.x_member
  ),
  x_win AS (
    SELECT            COUNT(*) AS n_bets, COUNT(DISTINCT s.x_round) AS n_rounds,
           COUNT(DISTINCT s.x_date) AS active_days, COUNT(DISTINCT s.x_tblshoe) AS active_shoes,
           COUNT(DISTINCT CONCAT_WS('|', s.x_date, s.x_table)) AS active_sessions,
           COUNT(DISTINCT s.x_table) AS n_tables, COUNT(DISTINCT s.x_dealer) AS n_dealers,
           COUNT(DISTINCT s.x_ip) AS n_ips, COUNT(DISTINCT s.x_product) AS n_products,
           MIN(s.x_date) AS first_seen_d, MAX(s.x_date) AS last_seen_d,
           SUM(s.x_stake) AS stake, SUM(s.x_valid) AS valid, SUM(s.x_rebate) AS rebate,
           SUM(s.x_net) AS net, SUM(-s.x_net *(100.0-s.x_agpct)/100.0) AS agent_cost,
           AVG(100.0-s.x_agpct)                   AS agent_pct,
           AVG(s.x_agpct)                         AS company_retain_pct,
           SUM(-s.x_net *s.x_agpct/100.0)         AS agent_cost_a_legacy,
           SUM(s.x_valid*s.x_agpct/100.0)         AS agent_cost_valid_base_legacy,
          AVG(COALESCE(s.x_rate1,100)) AS retain_pct_lv1, AVG(COALESCE(s.x_rate2,100)) AS retain_pct_lv2,
          AVG(COALESCE(s.x_rate3,100)) AS retain_pct_lv3, AVG(COALESCE(s.x_rate4,100)) AS retain_pct_lv4,
          AVG(COALESCE(s.x_rate5,100)) AS retain_pct_lv5, AVG(s.x_chain_depth) AS chain_depth_avg,
          AVG(COALESCE(100.0-s.x_rate1,0)) AS agent_pct_lv1, AVG(COALESCE(100.0-s.x_rate2,0)) AS agent_pct_lv2,
          AVG(COALESCE(100.0-s.x_rate3,0)) AS agent_pct_lv3, AVG(COALESCE(100.0-s.x_rate4,0)) AS agent_pct_lv4,
          AVG(COALESCE(100.0-s.x_rate5,0)) AS agent_pct_lv5,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate1,0)/100.0)                        AS agent_cost_lv1,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate2,0)/100.0)                        AS agent_cost_lv2,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate3,0)/100.0)                        AS agent_cost_lv3,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate4,0)/100.0)                        AS agent_cost_lv4,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate5,0)/100.0)                        AS agent_cost_lv5,
          SUM(-s.x_net*(COALESCE(100.0-s.x_rate1,0)+COALESCE(100.0-s.x_rate2,0)
                       +COALESCE(100.0-s.x_rate3,0)+COALESCE(100.0-s.x_rate4,0)
                       +COALESCE(100.0-s.x_rate5,0))/100.0)                   AS agent_cost_chain_additive,
          SUM(-s.x_net*(1.0 - CAST(COALESCE(s.x_rate1,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate2,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate3,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate4,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate5,100) AS DOUBLE)/100.0))
                                                                       AS agent_cost_chain_nested,
           AVG(s.x_rbpct) AS rbpct, AVG(s.x_freecomm*1.0) AS freecomm_rate,
           PERCENTILE_APPROX(s.x_stake,0.25) AS p25, PERCENTILE_APPROX(s.x_stake,0.50) AS p50,
           PERCENTILE_APPROX(s.x_stake,0.75) AS p75, PERCENTILE_APPROX(s.x_stake,0.90) AS p90,
           PERCENTILE_APPROX(s.x_stake,0.95) AS p95, PERCENTILE_APPROX(s.x_stake,0.99) AS p99,
           PERCENTILE_APPROX(s.x_valid,0.50) AS p50_valid,
           PERCENTILE_APPROX(s.x_net,0.50)   AS p50_profit,
           SUM(CASE WHEN s.x_rec = 1 THEN s.x_stake ELSE 0 END) AS st_in,
           SUM(CASE WHEN s.x_rec = 1 THEN 1 ELSE 0 END)         AS nb_in,
           SUM(CASE WHEN s.x_rec = 1 THEN s.x_net ELSE 0 END)   AS net_in,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN s.x_stake ELSE 0 END) AS st_out,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN 1 ELSE 0 END)         AS nb_out,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN s.x_net ELSE 0 END)   AS net_out,
           SUM(CASE WHEN s.x_rec=1 THEN s.x_stake ELSE 0 END) AS st_rec,
           SUM(CASE WHEN s.x_rec=1 THEN 1 ELSE 0 END)         AS nb_rec
    FROM x_mk s
    WHERE s.is_clean = 1
      AND s.x_member IS NOT NULL AND TRIM(CAST(s.x_member AS STRING)) <> ''
  ),
      q AS (
        SELECT                                                                                              -- 取列：起始取列子句
          c.TABLE_NAME                                                           AS table_name,             -- 取列：表名
          c.ORDINAL_POSITION                                                     AS col_pos,                -- 取列：列序
          c.COLUMN_NAME                                                          AS column_name,            -- 取列：列名
          c.DATA_TYPE                                                            AS data_type,              -- 取列：数据类型
          c.COLUMN_COMMENT                                                       AS column_comment          -- 取列：列注释——编码列唯一可读之语义线索
        FROM information_schema.columns c                                                                   -- 取数来源：取自元数据字典（列清单）
        WHERE c.TABLE_SCHEMA = 'ods_mariadb_2b'                                                             -- 过滤条件：限定 TABLE_SCHEMA等于 'ods_mariadb_2b'
          AND c.TABLE_NAME IN ('ods_a168_member', 'ods_a168_member_dtl', 'ods_a168_member_url')             -- 并列条件：限定三张会员主表
      )
    SELECT q.*,
           -- 一·经济层
           ROUND(e.stake,4) AS stake, ROUND(e.valid,4) AS valid_bet,
           ROUND(-e.net,4) AS profit, e.n_bets, e.n_rounds,
           ROUND(e.net/NULLIF(e.stake,0),8) AS roi,
           ROUND(e.net_in/NULLIF(e.st_in,0),8) AS roi_recent,
           ROUND(e.net_out/NULLIF(e.st_out,0),8) AS roi_non_recent,
           ROUND((e.net-e.rebate)/NULLIF(e.stake,0),8) AS roi_ex_rebate,
           ROUND(e.net,4) AS roi_numerator, ROUND(e.stake,4) AS roi_denominator,
           CASE WHEN e.stake IS NULL THEN 'NULL_DENOM' WHEN e.stake<=0 THEN 'ZERO_DENOM'
                WHEN e.n_bets<30 THEN 'THIN_EXPOSURE' ELSE 'OK' END AS roi_denominator_status,
           ROUND(e.rebate,4) AS rebate_cost, ROUND(e.agent_cost,4)                           AS cost_complement_b,
       ROUND(e.agent_pct,4)                            AS pct_complement,
       ROUND(e.company_retain_pct,4)                   AS pct_top_bet23,
       'AG03-UNRESOLVED'                                     AS agent_formula_version,
      'ALL5_LEVELS_bet23_to_bet27'                    AS agent_level_scope,
      ROUND(e.agent_cost_lv1,4) AS agent_cost_lv1, ROUND(e.agent_cost_lv2,4) AS agent_cost_lv2,
      ROUND(e.agent_cost_lv3,4) AS agent_cost_lv3, ROUND(e.agent_cost_lv4,4) AS agent_cost_lv4,
      ROUND(e.agent_cost_lv5,4) AS agent_cost_lv5,
      ROUND(e.agent_pct_lv1,6) AS agent_pct_lv1, ROUND(e.agent_pct_lv2,6) AS agent_pct_lv2,
      ROUND(e.agent_pct_lv3,6) AS agent_pct_lv3, ROUND(e.agent_pct_lv4,6) AS agent_pct_lv4,
      ROUND(e.agent_pct_lv5,6) AS agent_pct_lv5,
      ROUND(e.retain_pct_lv1,6) AS retain_pct_lv1, ROUND(e.retain_pct_lv2,6) AS retain_pct_lv2,
      ROUND(e.retain_pct_lv3,6) AS retain_pct_lv3, ROUND(e.retain_pct_lv4,6) AS retain_pct_lv4,
      ROUND(e.retain_pct_lv5,6) AS retain_pct_lv5, ROUND(e.chain_depth_avg,4) AS chain_depth_avg,
      ROUND(e.agent_cost_chain_additive,4)            AS agent_cost_chain_additive,
      ROUND(e.agent_cost_chain_nested,4)              AS agent_cost_chain_nested,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_additive,4) AS residual_chain_additive,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_nested,4)   AS residual_chain_nested,
      'PENDING_AG03'                                  AS decision_status,
      'FALSE'                                         AS admit_to_risk_decision,
      'NOT_FOR_ENFORCEMENT'                           AS deliverable_class,
       ROUND(e.agent_cost_a_legacy,4)                  AS agent_cost_a_legacy,
       ROUND(e.agent_cost_valid_base_legacy,4)         AS agent_cost_valid_base_legacy,
           ROUND(-e.net-e.rebate,4)                        AS ngr,
       ROUND(-e.net-e.rebate-e.agent_cost,4)           AS residual_b,
       ROUND(-e.net-e.rebate-e.agent_cost_a_legacy,4)  AS residual_a,
           ROUND((-e.net-e.rebate)/NULLIF(e.stake,0),8)    AS ngr_rate,
       ROUND((-e.net-e.rebate-e.agent_cost)/NULLIF(e.stake,0),8)   AS residual_b_rate,
      -- 【HF9c · canonical accounting contract】
      --   以下 canonical 字段只增加明确 scope；不删除、不覆盖既有字段。
      --   formal_bet23_* 保持 HF9b 当前生产公式及其 NULL/0 语义；
      --   lv1~lv5 / additive / nested 则分别采用各自原始 e.* 成本字段，
      --   rate 一律从未舍入的 e.* 分子 / e.stake 计算，禁止由展示值反算。
      ROUND(e.agent_cost,4) AS agent_cost_bet23_formal_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost,4) AS net_margin_bet23_formal_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost)/NULLIF(e.stake,0),8) AS net_margin_bet23_formal_rate_canonical,
      ROUND(e.agent_cost_lv1,4) AS agent_cost_lv1_bet23_canonical,
      ROUND(e.agent_cost_lv2,4) AS agent_cost_lv2_bet24_canonical,
      ROUND(e.agent_cost_lv3,4) AS agent_cost_lv3_bet25_canonical,
      ROUND(e.agent_cost_lv4,4) AS agent_cost_lv4_bet26_canonical,
      ROUND(e.agent_cost_lv5,4) AS agent_cost_lv5_bet27_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_lv1,4) AS net_margin_lv1_bet23_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_lv1)/NULLIF(e.stake,0),8) AS net_margin_lv1_bet23_rate_canonical,
      ROUND(e.agent_cost_chain_additive,4) AS agent_cost_chain_additive_canonical,
      ROUND(e.agent_cost_chain_nested,4) AS agent_cost_chain_nested_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_additive,4) AS net_margin_chain_additive_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_nested,4) AS net_margin_chain_nested_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_chain_additive)/NULLIF(e.stake,0),8) AS net_margin_chain_additive_rate_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_chain_nested)/NULLIF(e.stake,0),8) AS net_margin_chain_nested_rate_canonical,
       ROUND((-e.net-e.rebate-e.agent_cost_a_legacy)/NULLIF(e.stake,0),8) AS residual_a_rate,
           -- 二·分布层
           ROUND(e.stake/NULLIF(e.n_bets,0),4) AS avg_stake_per_bet,
           ROUND(e.valid/NULLIF(e.n_rounds,0),4) AS avg_valid_bet_per_round,
           ROUND(-e.net/NULLIF(e.n_rounds,0),4) AS avg_profit_per_round,
           ROUND(-e.net/NULLIF(e.active_days,0),4) AS avg_profit_per_day,
           ROUND(-e.net/NULLIF(e.active_shoes,0),4) AS avg_profit_per_shoe,
           ROUND(e.stake/NULLIF(e.active_days,0),4) AS avg_stake_per_active_day,
           ROUND(e.n_rounds*1.0/NULLIF(e.active_days,0),4) AS avg_rounds_per_active_day,
           ROUND(e.st_in/NULLIF(e.nb_in,0),4) AS avg_stake_recent,
           ROUND(e.st_out/NULLIF(e.nb_out,0),4) AS avg_stake_non_recent,
           ROUND(e.p25,4) AS p25_stake, ROUND(e.p50,4) AS p50_stake, ROUND(e.p75,4) AS p75_stake,
           ROUND(e.p90,4) AS p90_stake, ROUND(e.p95,4) AS p95_stake, ROUND(e.p99,4) AS p99_stake,
           ROUND(e.p50_valid,4) AS p50_valid_bet, ROUND(e.p50_profit,4) AS p50_profit,
           ROUND(e.p95/NULLIF(e.p50,0),6) AS p95_over_p50,
           ROUND(e.p99/NULLIF(e.p50,0),6) AS p99_over_p50,
           ROUND((e.stake/NULLIF(e.n_bets,0))/NULLIF(e.p50,0),6) AS avg_over_p50,
           -- 三·关系层
           e.n_tables AS common_table_count, e.n_dealers AS common_dealer_count,
           e.n_ips AS common_ip_count, e.n_products AS common_product_count,
           ROUND(e.st_in/NULLIF(e.stake,0),8) AS share_recent,
           -- 四·rate 层
           ROUND(-e.net/NULLIF(e.stake,0),8) AS hold_rate,
           ROUND(-e.net_in/NULLIF(e.st_in,0),8) AS hold_rate_recent,
           ROUND(e.rebate/NULLIF(e.valid,0),8) AS rebate_rate_actual,
           ROUND(e.rbpct,6) AS rebate_pct_config,
           ROUND(e.valid/NULLIF(e.stake,0),6) AS turnover_multiple,
           ROUND(e.freecomm_rate,6) AS free_comm_rate,
           ROUND(e.net_in/NULLIF(e.st_in,0)-e.net_out/NULLIF(e.st_out,0),8) AS roi_delta_recent,
           -- 五·动态层
           e.first_seen_d AS first_seen, e.last_seen_d AS last_seen,
           e.active_days, e.active_shoes, e.active_sessions,
           DATEDIFF(e.last_seen_d, e.first_seen_d)+1 AS span_days,
           ROUND(e.active_days*1.0/NULLIF(DATEDIFF(e.last_seen_d,e.first_seen_d)+1,0),6) AS persistence,
           ROUND((e.st_in/NULLIF(e.nb_in,0))/NULLIF(e.st_out/NULLIF(e.nb_out,0),0),6) AS ramp_recent_vs_prior,
           ROUND((e.st_rec/NULLIF(e.nb_rec,0))/NULLIF(e.stake/NULLIF(e.n_bets,0),0),6) AS ramp_recent_vs_all,
           ROUND((e.st_rec/NULLIF(e.stake,0))/0.30,6) AS stake_ramp,
           -- 六·决策层（HF9g-P5 · D-14 斧正 —— 本件属【全窗基线族】，相对刻度与决策标签一律 NULL）
           --   病灶：x_win 系全窗单行聚合（无 GROUP BY，恒 1 行，此为设计使然，非缺陷），
           --         经 CROSS JOIN 接入后 e.* 全行同值；六层之 NTILE / PERCENT_RANK 施于常数即退化，
           --         PERCENT_RANK 恒 0 ⇒ action_priority 恒判 A，全件 100% 误标。
           --   ★ 斧正原则：不给 x_win 补 GROUP BY —— 那会改变其「全窗基线」语义，属退化。
           --     正解与 #018 之 G-05／G-06 同治：范围外之行不得接受任何下游评分与决策标签。
           --   ★ 本件之 e.* 仍照常供其它列作全窗基线使用，仅六层相对刻度与决策标签置 NULL。
           CAST(NULL AS INT)                                              AS vip_tier,                        -- 空值取值：全窗基线族无实体可分档，置 NULL（NULL＝不适用，非 0）
           CAST(NULL AS DOUBLE)                                           AS economic_value,                  -- 空值取值：同上，禁以常数百分位冒充经济价值
           CAST(NULL AS DOUBLE)                                           AS roi_pr_global,                   -- 空值取值：同上
           CAST(NULL AS DOUBLE)                                           AS risk_value,                      -- 空值取值：兼容列，同上
           CAST(NULL AS DOUBLE)                                           AS pr_stake,                        -- 空值取值：兼容列，同上
           CAST(NULL AS DOUBLE)                                           AS pr_global,                       -- 空值取值：同上
           CAST(NULL AS DOUBLE)                                           AS pr_qualified,                    -- 空值取值：同上
           'GLOBAL_BASELINE_NO_ENTITY_RANKING'                            AS pr_qualified_population,         -- 字面取值：血统 —— 明示本件为全窗基线族，无实体排序总体
           CAST(NULL AS BIGINT)                                           AS pr_global_population_n,          -- 空值取值：血统 —— 不适用
           CAST(NULL AS BIGINT)                                           AS pr_qualified_population_n,       -- 空值取值：血统 —— 不适用
           'NOT_APPLICABLE_GLOBAL_BASELINE'                               AS pr_calculation_method,           -- 字面取值：血统 —— 算法不适用
           'HF9g-P5'                                                      AS pr_calculation_version,          -- 字面取值：血统 —— 算法版本
           CAST(NULL AS STRING)                                           AS evidence_flag,                   -- 空值取值：证据旗标不适用于全窗基线
           CAST(NULL AS STRING)                                           AS evidence_rate,                   -- 空值取值：同上
           CAST(NULL AS DOUBLE)                                           AS hold_ci_halfwidth_approx,        -- 空值取值：同上
           'X 全窗基线 · 不参与实体赏罚'                                    AS action_priority                  -- 字面取值：★ D-14 斧正 —— 本族恒不入赏罚，取代原 100% 误标之「A」
    FROM q
    CROSS JOIN x_win e
  ) y
) z
-- ── 逐批 WHERE 阶梯（★ 口诀：上界 ＝ 下界 ＋ 100000，两数同进）──
--    本件 T_true 未测，无需先跑 T_true；以 0 / 100000 控制本批返回区间，末批由实际行数 < 100000 判定
--    WHERE z.audit_rn >        0 AND z.audit_rn <=   100000   -- 第 1 批
--    WHERE z.audit_rn >   100000 AND z.audit_rn <=   200000   -- 第 2 批
--    WHERE z.audit_rn >   200000 AND z.audit_rn <=   300000   -- 第 3 批
--    WHERE z.audit_rn >   300000 AND z.audit_rn <=   400000   -- 第 4 批
--    WHERE z.audit_rn >   400000 AND z.audit_rn <=   500000   -- 第 5 批
--    WHERE z.audit_rn >   500000 AND z.audit_rn <=   600000   -- 第 6 批
--    WHERE z.audit_rn >   600000 AND z.audit_rn <=   700000   -- 第 7 批
--    …余批类推。第 k 批：WHERE z.audit_rn > (k-1)*100000 AND z.audit_rn <= k*100000
--    某批返回 < 100000 行即为末批，其后不再取。
--
--    ⚠ 常见误写（务必避开）：只推下界而上界不动 ——
--        WHERE z.audit_rn > 100000 AND z.audit_rn <= 100000   ← 自相矛盾，恒为假，返回空集
--        WHERE z.audit_rn > 200000 AND z.audit_rn <= 100000   ← 同上，空集
--      两个数必须**同时**前进，且始终相差 100000。
--      下界 ＝ 上一批之上界；上界 ＝ 本批之上界。
WHERE z.audit_rn > 0 AND z.audit_rn <= 100000 -- ★ HF9c 本批区间
ORDER BY z.audit_rn;


-- ══════════════════════════════════════════════════════════════════════════════════════════════
-- 127. _PH0_4b_rg_keyword.csv   [总包行 12664~12694 · 原 11 列 ＋六层约 60 列]
--     典型学：M10 责任博彩　派生旗标：pre_rg（s.x_rec = 1 · 仅供 CASE 条件聚合，全包无任何 WHERE/AND/HAVING 以此过滤）　连接：全窗基线
-- ══════════════════════════════════════════════════════════════════════════════════════════════
-- ★ W-64 · D-14 警示（本件属 x_win 族 · 66 件之一 · 详见 §Z 段 D-14 全案）
--   本件以 `CROSS JOIN x_win e` 接入全局基线，x_win 无 GROUP BY ⇒ 恒 1 行 ⇒ e.* 全行同值。
--   故：economic_value / roi_pr_global / risk_value / pr_stake / pr_global 恒为 0；
--       action_priority 每一行皆为「A 净亏最大十分位 · 优先复核」（Z 分支永不触发）；
--       evidence_rate 恒为最高档；vip_tier 由常数键分档 ⇒ 无信息且非确定。
--   ⇒ 本件决策层三列 **NOT_FOR_DECISION**，裁定前不得用于排班、抽查或汇报。
-- ── ① 先跑 T_true 留档（不足 100000 者一次导全，不必分批）──
-- ── ① T_true：HF9c 不再强制预跑完整 COUNT。
--    本批实际返回行数 < 100000 即判定为末批；全批完成后以各批 n_rows / audit_rn 范围核对总量。

-- ── ② 分批取数：第 1 批。第 k 批只改末行两数为 (k-1)*100000 与 k*100000 ──
--    审计字段二（REDTEAM 2026-08-24 裁定 · 四锁）：
--      audit_rn  全局观测坐标 —— 由**与原版审计版逐字同一**之排序键所生，两版可逐行对账
--      batch_id  物理分批信息 —— 该行所属批次，由 audit_rn 算得，非引擎所赋
--    ★ 锁三：二者皆为审计字段，**不得进入任何业务指标计算**。
--    ★ 锁四：两版经 audit_rn 逐行字段核验后，方可宣布输出完全一致。

-- ── ③ 每批取回后自证四数（任一不符即停手回报，禁止放行）──
--    n_rows        = COUNT(*)      须等于 COUNT(DISTINCT audit_rn)   （批内无重复）
--    audit_rn_min  = MIN(audit_rn) 须等于 (k-1)*100000 + 1           （与上批严丝合缝）
--    audit_rn_max  = MAX(audit_rn) 须等于 min + n_rows - 1           （批内无缺口）
--    全批取毕再验：各批 audit_rn 之并集 = 1 .. T_true，无缺号、无重号。
--     ★ 首行＝平台真净亏最多者（已扣退水与代理占成）。
--
SELECT z.*,
       CAST(FLOOR((z.audit_rn - 1) / 100000) + 1 AS INT)          AS batch_id,
       'A168_HF9F_20260827_0900' AS run_id,
       '2026-08-27 09:00:00' AS snapshot_sync_time
FROM (
  SELECT y.*,
         ROW_NUMBER() OVER (ORDER BY y.`residual_b` ASC, y.`roi` DESC, y.`lmc04_category`, y.`n_events`, y.`rg_self_exclusion`, y.`rg_cooling_off`, y.`rg_responsible`, y.`biz_limit`, y.`biz_freeze`, y.`biz_disable`, y.`biz_block`, y.`amb_exclude_any`, y.`n_in_win`) AS audit_rn
  FROM (
    WITH
      x_ranked AS (
    SELECT b.bet01, b.bet03, b.bet04, b.bet05, b.bet09, b.bet11, b.bet13,
           b.bet15, b.bet16, b.bet17, b.bet18, b.bet19, b.bet20, b.bet21,
           b.bet22, b.bet23, b.bet24, b.bet25, b.bet26, b.bet27, b.bet38, b.bet39, b.category, b.commission,
           b.dt, b.eid, b.ip, b.validbet, b.updatetime, b.sync_time,
           ROW_NUMBER() OVER (
             PARTITION BY b.bet01
             ORDER BY b.updatetime DESC, b.sync_time DESC, b.dt DESC)      AS x_rn
    FROM ods_mariadb_2b.ods_a168_bet02 b
    WHERE b.dt >= '2026-03-21' AND b.dt < '2026-08-07'
      AND b.bet02 = '101'
      AND b.sync_time <= '2026-08-27 09:00:00'
  ),
    x_testagent AS (
    SELECT age001 AS agent_id FROM ods_mariadb_2b.ods_a168_agent WHERE age022 = '1'
  ),
    x_bs0 AS (
    SELECT b.bet05 AS x_member, b.eid AS x_dealer, b.bet39 AS x_table,
           b.bet03 AS x_shoe, b.ip AS x_ip, b.bet09 AS x_product, b.dt AS x_date,
           CONCAT_WS('|', b.bet03, b.bet04, b.bet39)                      AS x_round,
           CONCAT_WS('|', b.bet39, b.bet03)                               AS x_tblshoe,
           CAST(NULLIF(TRIM(b.bet04),'') AS INT)                          AS x_rno,
           CASE WHEN b.dt >= '2026-07-08' THEN 1 ELSE 0 END               AS x_rec,
           CASE WHEN TRIM(b.commission)='1' THEN 1 ELSE 0 END             AS x_freecomm,
           CAST(NULLIF(TRIM(b.bet13),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_stake,
           CAST(NULLIF(TRIM(b.validbet),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_valid,
           CAST(NULLIF(TRIM(b.bet16),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_rebate,
           CAST(NULLIF(TRIM(b.bet17),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_net,
           CAST(NULLIF(TRIM(b.bet15),'') AS DECIMAL(20,6))                AS x_rbpct,
           COALESCE(CAST(NULLIF(TRIM(b.bet23),'') AS DECIMAL(20,6)),0)   AS x_agpct,
          NULLIF(CAST(NULLIF(TRIM(b.bet23),'') AS DECIMAL(20,6)),0)     AS x_rate1,
          NULLIF(CAST(NULLIF(TRIM(b.bet24),'') AS DECIMAL(20,6)),0)     AS x_rate2,
          NULLIF(CAST(NULLIF(TRIM(b.bet25),'') AS DECIMAL(20,6)),0)     AS x_rate3,
          NULLIF(CAST(NULLIF(TRIM(b.bet26),'') AS DECIMAL(20,6)),0)     AS x_rate4,
          NULLIF(CAST(NULLIF(TRIM(b.bet27),'') AS DECIMAL(20,6)),0)     AS x_rate5,
          (CASE WHEN NULLIF(CAST(NULLIF(TRIM(b.bet22),'') AS BIGINT),0) IS NOT NULL THEN 5
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet21),'') AS BIGINT),0) IS NOT NULL THEN 4
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet20),'') AS BIGINT),0) IS NOT NULL THEN 3
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet19),'') AS BIGINT),0) IS NOT NULL THEN 2
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet18),'') AS BIGINT),0) IS NOT NULL THEN 1
                ELSE 0 END)                                             AS x_chain_depth,
           CASE WHEN COALESCE(t1.agent_id,t2.agent_id,t3.agent_id,
                              t4.agent_id,t5.agent_id) IS NOT NULL
                THEN 1 ELSE 0 END                                        AS f_testline
    FROM x_ranked b
    LEFT JOIN x_testagent t1 ON t1.agent_id = b.bet18
    LEFT JOIN x_testagent t2 ON t2.agent_id = b.bet19
    LEFT JOIN x_testagent t3 ON t3.agent_id = b.bet20
    LEFT JOIN x_testagent t4 ON t4.agent_id = b.bet21
    LEFT JOIN x_testagent t5 ON t5.agent_id = b.bet22
    WHERE b.x_rn = 1
      AND b.category='1' AND UPPER(TRIM(b.bet38))='N'
      AND CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8)) > 0
  ),
  x_mk AS (
    SELECT s.*,
           CASE WHEN s.f_testline = 0 THEN 1 ELSE 0 END                 AS is_clean
    FROM x_bs0 s
  ),
  x_agg AS (
    SELECT s.x_member                                                        AS x_key,
           COUNT(*) AS n_bets, COUNT(DISTINCT s.x_round) AS n_rounds,
           COUNT(DISTINCT s.x_date) AS active_days, COUNT(DISTINCT s.x_tblshoe) AS active_shoes,
           COUNT(DISTINCT CONCAT_WS('|', s.x_date, s.x_table)) AS active_sessions,
           COUNT(DISTINCT s.x_table) AS n_tables, COUNT(DISTINCT s.x_dealer) AS n_dealers,
           COUNT(DISTINCT s.x_ip) AS n_ips, COUNT(DISTINCT s.x_product) AS n_products,
           MIN(s.x_date) AS first_seen_d, MAX(s.x_date) AS last_seen_d,
           SUM(s.x_stake) AS stake, SUM(s.x_valid) AS valid, SUM(s.x_rebate) AS rebate,
           SUM(s.x_net) AS net, SUM(-s.x_net *(100.0-s.x_agpct)/100.0) AS agent_cost,
           AVG(100.0-s.x_agpct)                   AS agent_pct,
           AVG(s.x_agpct)                         AS company_retain_pct,
           SUM(-s.x_net *s.x_agpct/100.0)         AS agent_cost_a_legacy,
           SUM(s.x_valid*s.x_agpct/100.0)         AS agent_cost_valid_base_legacy,
          AVG(COALESCE(s.x_rate1,100)) AS retain_pct_lv1, AVG(COALESCE(s.x_rate2,100)) AS retain_pct_lv2,
          AVG(COALESCE(s.x_rate3,100)) AS retain_pct_lv3, AVG(COALESCE(s.x_rate4,100)) AS retain_pct_lv4,
          AVG(COALESCE(s.x_rate5,100)) AS retain_pct_lv5, AVG(s.x_chain_depth) AS chain_depth_avg,
          AVG(COALESCE(100.0-s.x_rate1,0)) AS agent_pct_lv1, AVG(COALESCE(100.0-s.x_rate2,0)) AS agent_pct_lv2,
          AVG(COALESCE(100.0-s.x_rate3,0)) AS agent_pct_lv3, AVG(COALESCE(100.0-s.x_rate4,0)) AS agent_pct_lv4,
          AVG(COALESCE(100.0-s.x_rate5,0)) AS agent_pct_lv5,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate1,0)/100.0)                        AS agent_cost_lv1,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate2,0)/100.0)                        AS agent_cost_lv2,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate3,0)/100.0)                        AS agent_cost_lv3,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate4,0)/100.0)                        AS agent_cost_lv4,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate5,0)/100.0)                        AS agent_cost_lv5,
          SUM(-s.x_net*(COALESCE(100.0-s.x_rate1,0)+COALESCE(100.0-s.x_rate2,0)
                       +COALESCE(100.0-s.x_rate3,0)+COALESCE(100.0-s.x_rate4,0)
                       +COALESCE(100.0-s.x_rate5,0))/100.0)                   AS agent_cost_chain_additive,
          SUM(-s.x_net*(1.0 - CAST(COALESCE(s.x_rate1,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate2,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate3,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate4,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate5,100) AS DOUBLE)/100.0))
                                                                       AS agent_cost_chain_nested,
           AVG(s.x_rbpct) AS rbpct, AVG(s.x_freecomm*1.0) AS freecomm_rate,
           PERCENTILE_APPROX(s.x_stake,0.25) AS p25, PERCENTILE_APPROX(s.x_stake,0.50) AS p50,
           PERCENTILE_APPROX(s.x_stake,0.75) AS p75, PERCENTILE_APPROX(s.x_stake,0.90) AS p90,
           PERCENTILE_APPROX(s.x_stake,0.95) AS p95, PERCENTILE_APPROX(s.x_stake,0.99) AS p99,
           PERCENTILE_APPROX(s.x_valid,0.50) AS p50_valid,
           PERCENTILE_APPROX(s.x_net,0.50)   AS p50_profit,
           SUM(CASE WHEN s.x_rec = 1 THEN s.x_stake ELSE 0 END) AS st_in,
           SUM(CASE WHEN s.x_rec = 1 THEN 1 ELSE 0 END)         AS nb_in,
           SUM(CASE WHEN s.x_rec = 1 THEN s.x_net ELSE 0 END)   AS net_in,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN s.x_stake ELSE 0 END) AS st_out,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN 1 ELSE 0 END)         AS nb_out,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN s.x_net ELSE 0 END)   AS net_out,
           SUM(CASE WHEN s.x_rec=1 THEN s.x_stake ELSE 0 END) AS st_rec,
           SUM(CASE WHEN s.x_rec=1 THEN 1 ELSE 0 END)         AS nb_rec
    FROM x_mk s
    WHERE s.is_clean = 1
      AND s.x_member IS NOT NULL AND TRIM(CAST(s.x_member AS STRING)) <> ''
    GROUP BY s.x_member
  ),
  x_win AS (
    SELECT            COUNT(*) AS n_bets, COUNT(DISTINCT s.x_round) AS n_rounds,
           COUNT(DISTINCT s.x_date) AS active_days, COUNT(DISTINCT s.x_tblshoe) AS active_shoes,
           COUNT(DISTINCT CONCAT_WS('|', s.x_date, s.x_table)) AS active_sessions,
           COUNT(DISTINCT s.x_table) AS n_tables, COUNT(DISTINCT s.x_dealer) AS n_dealers,
           COUNT(DISTINCT s.x_ip) AS n_ips, COUNT(DISTINCT s.x_product) AS n_products,
           MIN(s.x_date) AS first_seen_d, MAX(s.x_date) AS last_seen_d,
           SUM(s.x_stake) AS stake, SUM(s.x_valid) AS valid, SUM(s.x_rebate) AS rebate,
           SUM(s.x_net) AS net, SUM(-s.x_net *(100.0-s.x_agpct)/100.0) AS agent_cost,
           AVG(100.0-s.x_agpct)                   AS agent_pct,
           AVG(s.x_agpct)                         AS company_retain_pct,
           SUM(-s.x_net *s.x_agpct/100.0)         AS agent_cost_a_legacy,
           SUM(s.x_valid*s.x_agpct/100.0)         AS agent_cost_valid_base_legacy,
          AVG(COALESCE(s.x_rate1,100)) AS retain_pct_lv1, AVG(COALESCE(s.x_rate2,100)) AS retain_pct_lv2,
          AVG(COALESCE(s.x_rate3,100)) AS retain_pct_lv3, AVG(COALESCE(s.x_rate4,100)) AS retain_pct_lv4,
          AVG(COALESCE(s.x_rate5,100)) AS retain_pct_lv5, AVG(s.x_chain_depth) AS chain_depth_avg,
          AVG(COALESCE(100.0-s.x_rate1,0)) AS agent_pct_lv1, AVG(COALESCE(100.0-s.x_rate2,0)) AS agent_pct_lv2,
          AVG(COALESCE(100.0-s.x_rate3,0)) AS agent_pct_lv3, AVG(COALESCE(100.0-s.x_rate4,0)) AS agent_pct_lv4,
          AVG(COALESCE(100.0-s.x_rate5,0)) AS agent_pct_lv5,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate1,0)/100.0)                        AS agent_cost_lv1,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate2,0)/100.0)                        AS agent_cost_lv2,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate3,0)/100.0)                        AS agent_cost_lv3,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate4,0)/100.0)                        AS agent_cost_lv4,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate5,0)/100.0)                        AS agent_cost_lv5,
          SUM(-s.x_net*(COALESCE(100.0-s.x_rate1,0)+COALESCE(100.0-s.x_rate2,0)
                       +COALESCE(100.0-s.x_rate3,0)+COALESCE(100.0-s.x_rate4,0)
                       +COALESCE(100.0-s.x_rate5,0))/100.0)                   AS agent_cost_chain_additive,
          SUM(-s.x_net*(1.0 - CAST(COALESCE(s.x_rate1,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate2,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate3,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate4,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate5,100) AS DOUBLE)/100.0))
                                                                       AS agent_cost_chain_nested,
           AVG(s.x_rbpct) AS rbpct, AVG(s.x_freecomm*1.0) AS freecomm_rate,
           PERCENTILE_APPROX(s.x_stake,0.25) AS p25, PERCENTILE_APPROX(s.x_stake,0.50) AS p50,
           PERCENTILE_APPROX(s.x_stake,0.75) AS p75, PERCENTILE_APPROX(s.x_stake,0.90) AS p90,
           PERCENTILE_APPROX(s.x_stake,0.95) AS p95, PERCENTILE_APPROX(s.x_stake,0.99) AS p99,
           PERCENTILE_APPROX(s.x_valid,0.50) AS p50_valid,
           PERCENTILE_APPROX(s.x_net,0.50)   AS p50_profit,
           SUM(CASE WHEN s.x_rec = 1 THEN s.x_stake ELSE 0 END) AS st_in,
           SUM(CASE WHEN s.x_rec = 1 THEN 1 ELSE 0 END)         AS nb_in,
           SUM(CASE WHEN s.x_rec = 1 THEN s.x_net ELSE 0 END)   AS net_in,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN s.x_stake ELSE 0 END) AS st_out,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN 1 ELSE 0 END)         AS nb_out,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN s.x_net ELSE 0 END)   AS net_out,
           SUM(CASE WHEN s.x_rec=1 THEN s.x_stake ELSE 0 END) AS st_rec,
           SUM(CASE WHEN s.x_rec=1 THEN 1 ELSE 0 END)         AS nb_rec
    FROM x_mk s
    WHERE s.is_clean = 1
      AND s.x_member IS NOT NULL AND TRIM(CAST(s.x_member AS STRING)) <> ''
  ),
      q AS (
        SELECT                                                                                              -- 取列：起始取列子句
          COALESCE(NULLIF(TRIM(lmc04), ''), '（空）')                            AS lmc04_category,         -- 取值表达式：變更類別
          COUNT(*)                                                               AS n_events,               -- 计数表达式：该类事件总数
          SUM(CASE WHEN CONCAT(COALESCE(lmc05,''), COALESCE(lmc09,'')) LIKE '%自我排除%'
                    OR CONCAT(COALESCE(lmc05,''), COALESCE(lmc09,'')) LIKE '%self_exclu%'
                   THEN 1 ELSE 0 END)                                            AS rg_self_exclusion,      -- 条件计数：★★ 真 RG——自我排除
          SUM(CASE WHEN CONCAT(COALESCE(lmc05,''), COALESCE(lmc09,'')) LIKE '%冷靜%'
                    OR CONCAT(COALESCE(lmc05,''), COALESCE(lmc09,'')) LIKE '%冷静%'
                    OR CONCAT(COALESCE(lmc05,''), COALESCE(lmc09,'')) LIKE '%cooling%'
                   THEN 1 ELSE 0 END)                                            AS rg_cooling_off,         -- 条件计数：★★ 真 RG——冷静期
          SUM(CASE WHEN CONCAT(COALESCE(lmc05,''), COALESCE(lmc09,'')) LIKE '%責任博彩%'
                    OR CONCAT(COALESCE(lmc05,''), COALESCE(lmc09,'')) LIKE '%责任博彩%'
                    OR CONCAT(COALESCE(lmc05,''), COALESCE(lmc09,'')) LIKE '%responsible%'
                   THEN 1 ELSE 0 END)                                            AS rg_responsible,         -- 条件计数：★★ 真 RG——责任博彩
          SUM(CASE WHEN CONCAT(COALESCE(lmc05,''), COALESCE(lmc09,'')) LIKE '%限額%'
                    OR CONCAT(COALESCE(lmc05,''), COALESCE(lmc09,'')) LIKE '%限额%'
                   THEN 1 ELSE 0 END)                                            AS biz_limit,              -- 条件计数：商业管控——限额（★ 非 RG）
          SUM(CASE WHEN CONCAT(COALESCE(lmc05,''), COALESCE(lmc09,'')) LIKE '%凍結%'
                    OR CONCAT(COALESCE(lmc05,''), COALESCE(lmc09,'')) LIKE '%冻结%'
                   THEN 1 ELSE 0 END)                                            AS biz_freeze,             -- 条件计数：商业管控——冻结
          SUM(CASE WHEN CONCAT(COALESCE(lmc05,''), COALESCE(lmc09,'')) LIKE '%停用%'
                   THEN 1 ELSE 0 END)                                            AS biz_disable,            -- 条件计数：商业管控——停用
          SUM(CASE WHEN CONCAT(COALESCE(lmc05,''), COALESCE(lmc09,'')) LIKE '%封鎖%'
                    OR CONCAT(COALESCE(lmc05,''), COALESCE(lmc09,'')) LIKE '%封锁%'
                   THEN 1 ELSE 0 END)                                            AS biz_block,              -- 条件计数：商业管控——封锁
          SUM(CASE WHEN CONCAT(COALESCE(lmc05,''), COALESCE(lmc09,'')) LIKE '%排除%'
                   THEN 1 ELSE 0 END)                                            AS amb_exclude_any,        -- 条件计数：★ 歧义词——「排除」单独出现，须人工判其上下文
          SUM(CASE WHEN dt >= '2026-03-21' AND dt < '2026-08-07' THEN 1 ELSE 0 END) AS n_in_win             -- 条件计数：窗内事件数
        FROM ods_mariadb_2b.ods_a168_log_mem_change                                                         -- 取数来源：取自会员变更日志表
        GROUP BY COALESCE(NULLIF(TRIM(lmc04), ''), '（空）')                                                 -- 分组：按變更類別汇总
      )
    SELECT q.*,
           -- 一·经济层
           ROUND(e.stake,4) AS stake, ROUND(e.valid,4) AS valid_bet,
           ROUND(-e.net,4) AS profit, e.n_bets, e.n_rounds,
           ROUND(e.net/NULLIF(e.stake,0),8) AS roi,
           ROUND(e.net_in/NULLIF(e.st_in,0),8) AS roi_pre_rg,
           ROUND(e.net_out/NULLIF(e.st_out,0),8) AS roi_non_pre_rg,
           ROUND((e.net-e.rebate)/NULLIF(e.stake,0),8) AS roi_ex_rebate,
           ROUND(e.net,4) AS roi_numerator, ROUND(e.stake,4) AS roi_denominator,
           CASE WHEN e.stake IS NULL THEN 'NULL_DENOM' WHEN e.stake<=0 THEN 'ZERO_DENOM'
                WHEN e.n_bets<30 THEN 'THIN_EXPOSURE' ELSE 'OK' END AS roi_denominator_status,
           ROUND(e.rebate,4) AS rebate_cost, ROUND(e.agent_cost,4)                           AS cost_complement_b,
       ROUND(e.agent_pct,4)                            AS pct_complement,
       ROUND(e.company_retain_pct,4)                   AS pct_top_bet23,
       'AG03-UNRESOLVED'                                     AS agent_formula_version,
      'ALL5_LEVELS_bet23_to_bet27'                    AS agent_level_scope,
      ROUND(e.agent_cost_lv1,4) AS agent_cost_lv1, ROUND(e.agent_cost_lv2,4) AS agent_cost_lv2,
      ROUND(e.agent_cost_lv3,4) AS agent_cost_lv3, ROUND(e.agent_cost_lv4,4) AS agent_cost_lv4,
      ROUND(e.agent_cost_lv5,4) AS agent_cost_lv5,
      ROUND(e.agent_pct_lv1,6) AS agent_pct_lv1, ROUND(e.agent_pct_lv2,6) AS agent_pct_lv2,
      ROUND(e.agent_pct_lv3,6) AS agent_pct_lv3, ROUND(e.agent_pct_lv4,6) AS agent_pct_lv4,
      ROUND(e.agent_pct_lv5,6) AS agent_pct_lv5,
      ROUND(e.retain_pct_lv1,6) AS retain_pct_lv1, ROUND(e.retain_pct_lv2,6) AS retain_pct_lv2,
      ROUND(e.retain_pct_lv3,6) AS retain_pct_lv3, ROUND(e.retain_pct_lv4,6) AS retain_pct_lv4,
      ROUND(e.retain_pct_lv5,6) AS retain_pct_lv5, ROUND(e.chain_depth_avg,4) AS chain_depth_avg,
      ROUND(e.agent_cost_chain_additive,4)            AS agent_cost_chain_additive,
      ROUND(e.agent_cost_chain_nested,4)              AS agent_cost_chain_nested,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_additive,4) AS residual_chain_additive,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_nested,4)   AS residual_chain_nested,
      'PENDING_AG03'                                  AS decision_status,
      'FALSE'                                         AS admit_to_risk_decision,
      'NOT_FOR_ENFORCEMENT'                           AS deliverable_class,
       ROUND(e.agent_cost_a_legacy,4)                  AS agent_cost_a_legacy,
       ROUND(e.agent_cost_valid_base_legacy,4)         AS agent_cost_valid_base_legacy,
           ROUND(-e.net-e.rebate,4)                        AS ngr,
       ROUND(-e.net-e.rebate-e.agent_cost,4)           AS residual_b,
       ROUND(-e.net-e.rebate-e.agent_cost_a_legacy,4)  AS residual_a,
           ROUND((-e.net-e.rebate)/NULLIF(e.stake,0),8)    AS ngr_rate,
       ROUND((-e.net-e.rebate-e.agent_cost)/NULLIF(e.stake,0),8)   AS residual_b_rate,
      -- 【HF9c · canonical accounting contract】
      --   以下 canonical 字段只增加明确 scope；不删除、不覆盖既有字段。
      --   formal_bet23_* 保持 HF9b 当前生产公式及其 NULL/0 语义；
      --   lv1~lv5 / additive / nested 则分别采用各自原始 e.* 成本字段，
      --   rate 一律从未舍入的 e.* 分子 / e.stake 计算，禁止由展示值反算。
      ROUND(e.agent_cost,4) AS agent_cost_bet23_formal_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost,4) AS net_margin_bet23_formal_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost)/NULLIF(e.stake,0),8) AS net_margin_bet23_formal_rate_canonical,
      ROUND(e.agent_cost_lv1,4) AS agent_cost_lv1_bet23_canonical,
      ROUND(e.agent_cost_lv2,4) AS agent_cost_lv2_bet24_canonical,
      ROUND(e.agent_cost_lv3,4) AS agent_cost_lv3_bet25_canonical,
      ROUND(e.agent_cost_lv4,4) AS agent_cost_lv4_bet26_canonical,
      ROUND(e.agent_cost_lv5,4) AS agent_cost_lv5_bet27_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_lv1,4) AS net_margin_lv1_bet23_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_lv1)/NULLIF(e.stake,0),8) AS net_margin_lv1_bet23_rate_canonical,
      ROUND(e.agent_cost_chain_additive,4) AS agent_cost_chain_additive_canonical,
      ROUND(e.agent_cost_chain_nested,4) AS agent_cost_chain_nested_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_additive,4) AS net_margin_chain_additive_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_nested,4) AS net_margin_chain_nested_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_chain_additive)/NULLIF(e.stake,0),8) AS net_margin_chain_additive_rate_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_chain_nested)/NULLIF(e.stake,0),8) AS net_margin_chain_nested_rate_canonical,
       ROUND((-e.net-e.rebate-e.agent_cost_a_legacy)/NULLIF(e.stake,0),8) AS residual_a_rate,
           -- 二·分布层
           ROUND(e.stake/NULLIF(e.n_bets,0),4) AS avg_stake_per_bet,
           ROUND(e.valid/NULLIF(e.n_rounds,0),4) AS avg_valid_bet_per_round,
           ROUND(-e.net/NULLIF(e.n_rounds,0),4) AS avg_profit_per_round,
           ROUND(-e.net/NULLIF(e.active_days,0),4) AS avg_profit_per_day,
           ROUND(-e.net/NULLIF(e.active_shoes,0),4) AS avg_profit_per_shoe,
           ROUND(e.stake/NULLIF(e.active_days,0),4) AS avg_stake_per_active_day,
           ROUND(e.n_rounds*1.0/NULLIF(e.active_days,0),4) AS avg_rounds_per_active_day,
           ROUND(e.st_in/NULLIF(e.nb_in,0),4) AS avg_stake_pre_rg,
           ROUND(e.st_out/NULLIF(e.nb_out,0),4) AS avg_stake_non_pre_rg,
           ROUND(e.p25,4) AS p25_stake, ROUND(e.p50,4) AS p50_stake, ROUND(e.p75,4) AS p75_stake,
           ROUND(e.p90,4) AS p90_stake, ROUND(e.p95,4) AS p95_stake, ROUND(e.p99,4) AS p99_stake,
           ROUND(e.p50_valid,4) AS p50_valid_bet, ROUND(e.p50_profit,4) AS p50_profit,
           ROUND(e.p95/NULLIF(e.p50,0),6) AS p95_over_p50,
           ROUND(e.p99/NULLIF(e.p50,0),6) AS p99_over_p50,
           ROUND((e.stake/NULLIF(e.n_bets,0))/NULLIF(e.p50,0),6) AS avg_over_p50,
           -- 三·关系层
           e.n_tables AS common_table_count, e.n_dealers AS common_dealer_count,
           e.n_ips AS common_ip_count, e.n_products AS common_product_count,
           ROUND(e.st_in/NULLIF(e.stake,0),8) AS share_pre_rg,
           -- 四·rate 层
           ROUND(-e.net/NULLIF(e.stake,0),8) AS hold_rate,
           ROUND(-e.net_in/NULLIF(e.st_in,0),8) AS hold_rate_pre_rg,
           ROUND(e.rebate/NULLIF(e.valid,0),8) AS rebate_rate_actual,
           ROUND(e.rbpct,6) AS rebate_pct_config,
           ROUND(e.valid/NULLIF(e.stake,0),6) AS turnover_multiple,
           ROUND(e.freecomm_rate,6) AS free_comm_rate,
           ROUND(e.net_in/NULLIF(e.st_in,0)-e.net_out/NULLIF(e.st_out,0),8) AS roi_delta_pre_rg,
           -- 五·动态层
           e.first_seen_d AS first_seen, e.last_seen_d AS last_seen,
           e.active_days, e.active_shoes, e.active_sessions,
           DATEDIFF(e.last_seen_d, e.first_seen_d)+1 AS span_days,
           ROUND(e.active_days*1.0/NULLIF(DATEDIFF(e.last_seen_d,e.first_seen_d)+1,0),6) AS persistence,
           ROUND((e.st_in/NULLIF(e.nb_in,0))/NULLIF(e.st_out/NULLIF(e.nb_out,0),0),6) AS ramp_pre_rg,
           ROUND((e.st_rec/NULLIF(e.nb_rec,0))/NULLIF(e.stake/NULLIF(e.n_bets,0),0),6) AS ramp_recent,
           ROUND((e.st_rec/NULLIF(e.stake,0))/0.30,6) AS stake_ramp,
           -- 六·决策层（HF9g-P5 · D-14 斧正 —— 本件属【全窗基线族】，相对刻度与决策标签一律 NULL）
           --   病灶：x_win 系全窗单行聚合（无 GROUP BY，恒 1 行，此为设计使然，非缺陷），
           --         经 CROSS JOIN 接入后 e.* 全行同值；六层之 NTILE / PERCENT_RANK 施于常数即退化，
           --         PERCENT_RANK 恒 0 ⇒ action_priority 恒判 A，全件 100% 误标。
           --   ★ 斧正原则：不给 x_win 补 GROUP BY —— 那会改变其「全窗基线」语义，属退化。
           --     正解与 #018 之 G-05／G-06 同治：范围外之行不得接受任何下游评分与决策标签。
           --   ★ 本件之 e.* 仍照常供其它列作全窗基线使用，仅六层相对刻度与决策标签置 NULL。
           CAST(NULL AS INT)                                              AS vip_tier,                        -- 空值取值：全窗基线族无实体可分档，置 NULL（NULL＝不适用，非 0）
           CAST(NULL AS DOUBLE)                                           AS economic_value,                  -- 空值取值：同上，禁以常数百分位冒充经济价值
           CAST(NULL AS DOUBLE)                                           AS roi_pr_global,                   -- 空值取值：同上
           CAST(NULL AS DOUBLE)                                           AS risk_value,                      -- 空值取值：兼容列，同上
           CAST(NULL AS DOUBLE)                                           AS pr_stake,                        -- 空值取值：兼容列，同上
           CAST(NULL AS DOUBLE)                                           AS pr_global,                       -- 空值取值：同上
           CAST(NULL AS DOUBLE)                                           AS pr_qualified,                    -- 空值取值：同上
           'GLOBAL_BASELINE_NO_ENTITY_RANKING'                            AS pr_qualified_population,         -- 字面取值：血统 —— 明示本件为全窗基线族，无实体排序总体
           CAST(NULL AS BIGINT)                                           AS pr_global_population_n,          -- 空值取值：血统 —— 不适用
           CAST(NULL AS BIGINT)                                           AS pr_qualified_population_n,       -- 空值取值：血统 —— 不适用
           'NOT_APPLICABLE_GLOBAL_BASELINE'                               AS pr_calculation_method,           -- 字面取值：血统 —— 算法不适用
           'HF9g-P5'                                                      AS pr_calculation_version,          -- 字面取值：血统 —— 算法版本
           CAST(NULL AS STRING)                                           AS evidence_flag,                   -- 空值取值：证据旗标不适用于全窗基线
           CAST(NULL AS STRING)                                           AS evidence_rate,                   -- 空值取值：同上
           CAST(NULL AS DOUBLE)                                           AS hold_ci_halfwidth_approx,        -- 空值取值：同上
           'X 全窗基线 · 不参与实体赏罚'                                    AS action_priority                  -- 字面取值：★ D-14 斧正 —— 本族恒不入赏罚，取代原 100% 误标之「A」
    FROM q
    CROSS JOIN x_win e
  ) y
) z
-- ── 逐批 WHERE 阶梯（★ 口诀：上界 ＝ 下界 ＋ 100000，两数同进）──
--    本件 T_true 未测，无需先跑 T_true；以 0 / 100000 控制本批返回区间，末批由实际行数 < 100000 判定
--    WHERE z.audit_rn >        0 AND z.audit_rn <=   100000   -- 第 1 批
--    WHERE z.audit_rn >   100000 AND z.audit_rn <=   200000   -- 第 2 批
--    WHERE z.audit_rn >   200000 AND z.audit_rn <=   300000   -- 第 3 批
--    WHERE z.audit_rn >   300000 AND z.audit_rn <=   400000   -- 第 4 批
--    WHERE z.audit_rn >   400000 AND z.audit_rn <=   500000   -- 第 5 批
--    WHERE z.audit_rn >   500000 AND z.audit_rn <=   600000   -- 第 6 批
--    WHERE z.audit_rn >   600000 AND z.audit_rn <=   700000   -- 第 7 批
--    …余批类推。第 k 批：WHERE z.audit_rn > (k-1)*100000 AND z.audit_rn <= k*100000
--    某批返回 < 100000 行即为末批，其后不再取。
--
--    ⚠ 常见误写（务必避开）：只推下界而上界不动 ——
--        WHERE z.audit_rn > 100000 AND z.audit_rn <= 100000   ← 自相矛盾，恒为假，返回空集
--        WHERE z.audit_rn > 200000 AND z.audit_rn <= 100000   ← 同上，空集
--      两个数必须**同时**前进，且始终相差 100000。
--      下界 ＝ 上一批之上界；上界 ＝ 本批之上界。
WHERE z.audit_rn > 0 AND z.audit_rn <= 100000 -- ★ HF9c 本批区间
ORDER BY z.audit_rn;


-- ══════════════════════════════════════════════════════════════════════════════════════════════
-- 128. _PH0_4w2_balance_points.csv   [总包行 12777~12799 · 原 12 列 ＋六层约 60 列]
--     典型学：M12 资金轨迹　派生旗标：recent（s.x_rec = 1 · 仅供 CASE 条件聚合，全包无任何 WHERE/AND/HAVING 以此过滤）　连接：全窗基线
-- ══════════════════════════════════════════════════════════════════════════════════════════════
-- ★ W-64 · D-14 警示（本件属 x_win 族 · 66 件之一 · 详见 §Z 段 D-14 全案）
--   本件以 `CROSS JOIN x_win e` 接入全局基线，x_win 无 GROUP BY ⇒ 恒 1 行 ⇒ e.* 全行同值。
--   故：economic_value / roi_pr_global / risk_value / pr_stake / pr_global 恒为 0；
--       action_priority 每一行皆为「A 净亏最大十分位 · 优先复核」（Z 分支永不触发）；
--       evidence_rate 恒为最高档；vip_tier 由常数键分档 ⇒ 无信息且非确定。
--   ⇒ 本件决策层三列 **NOT_FOR_DECISION**，裁定前不得用于排班、抽查或汇报。
-- ── ① 先跑 T_true 留档（不足 100000 者一次导全，不必分批）──
-- ── ① T_true：HF9c 不再强制预跑完整 COUNT。
--    本批实际返回行数 < 100000 即判定为末批；全批完成后以各批 n_rows / audit_rn 范围核对总量。

-- ── ② 分批取数：第 1 批。第 k 批只改末行两数为 (k-1)*100000 与 k*100000 ──
--    审计字段二（REDTEAM 2026-08-24 裁定 · 四锁）：
--      audit_rn  全局观测坐标 —— 由**与原版审计版逐字同一**之排序键所生，两版可逐行对账
--      batch_id  物理分批信息 —— 该行所属批次，由 audit_rn 算得，非引擎所赋
--    ★ 锁三：二者皆为审计字段，**不得进入任何业务指标计算**。
--    ★ 锁四：两版经 audit_rn 逐行字段核验后，方可宣布输出完全一致。
SELECT z.*,
       CAST(FLOOR((z.audit_rn - 1) / 100000) + 1 AS INT)          AS batch_id,
       'A168_HF9F_20260827_0900' AS run_id,
       '2026-08-27 09:00:00' AS snapshot_sync_time
FROM (
  SELECT y.*,
         ROW_NUMBER() OVER (ORDER BY y.`residual_b` ASC, y.`roi` DESC, y.`dt_slice`, y.`n_user_active`, y.`n_pts_total`, y.`pts_avg`, y.`pts_min`, y.`pts_p50`, y.`pts_p90`, y.`pts_p99`, y.`pts_max`, y.`pts_ok_avg`, y.`n_user_single_pt`, y.`pct_single_pt`) AS audit_rn
  FROM (
    WITH
      x_ranked AS (
    SELECT b.bet01, b.bet03, b.bet04, b.bet05, b.bet09, b.bet11, b.bet13,
           b.bet15, b.bet16, b.bet17, b.bet18, b.bet19, b.bet20, b.bet21,
           b.bet22, b.bet23, b.bet24, b.bet25, b.bet26, b.bet27, b.bet38, b.bet39, b.category, b.commission,
           b.dt, b.eid, b.ip, b.validbet, b.updatetime, b.sync_time,
           ROW_NUMBER() OVER (
             PARTITION BY b.bet01
             ORDER BY b.updatetime DESC, b.sync_time DESC, b.dt DESC)      AS x_rn
    FROM ods_mariadb_2b.ods_a168_bet02 b
    WHERE b.dt >= '2026-03-21' AND b.dt < '2026-08-07'
      AND b.bet02 = '101'
      AND b.sync_time <= '2026-08-27 09:00:00'
  ),
    x_testagent AS (
    SELECT age001 AS agent_id FROM ods_mariadb_2b.ods_a168_agent WHERE age022 = '1'
  ),
    x_bs0 AS (
    SELECT b.bet05 AS x_member, b.eid AS x_dealer, b.bet39 AS x_table,
           b.bet03 AS x_shoe, b.ip AS x_ip, b.bet09 AS x_product, b.dt AS x_date,
           CONCAT_WS('|', b.bet03, b.bet04, b.bet39)                      AS x_round,
           CONCAT_WS('|', b.bet39, b.bet03)                               AS x_tblshoe,
           CAST(NULLIF(TRIM(b.bet04),'') AS INT)                          AS x_rno,
           CASE WHEN b.dt >= '2026-07-08' THEN 1 ELSE 0 END               AS x_rec,
           CASE WHEN TRIM(b.commission)='1' THEN 1 ELSE 0 END             AS x_freecomm,
           CAST(NULLIF(TRIM(b.bet13),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_stake,
           CAST(NULLIF(TRIM(b.validbet),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_valid,
           CAST(NULLIF(TRIM(b.bet16),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_rebate,
           CAST(NULLIF(TRIM(b.bet17),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_net,
           CAST(NULLIF(TRIM(b.bet15),'') AS DECIMAL(20,6))                AS x_rbpct,
           COALESCE(CAST(NULLIF(TRIM(b.bet23),'') AS DECIMAL(20,6)),0)   AS x_agpct,
          NULLIF(CAST(NULLIF(TRIM(b.bet23),'') AS DECIMAL(20,6)),0)     AS x_rate1,
          NULLIF(CAST(NULLIF(TRIM(b.bet24),'') AS DECIMAL(20,6)),0)     AS x_rate2,
          NULLIF(CAST(NULLIF(TRIM(b.bet25),'') AS DECIMAL(20,6)),0)     AS x_rate3,
          NULLIF(CAST(NULLIF(TRIM(b.bet26),'') AS DECIMAL(20,6)),0)     AS x_rate4,
          NULLIF(CAST(NULLIF(TRIM(b.bet27),'') AS DECIMAL(20,6)),0)     AS x_rate5,
          (CASE WHEN NULLIF(CAST(NULLIF(TRIM(b.bet22),'') AS BIGINT),0) IS NOT NULL THEN 5
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet21),'') AS BIGINT),0) IS NOT NULL THEN 4
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet20),'') AS BIGINT),0) IS NOT NULL THEN 3
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet19),'') AS BIGINT),0) IS NOT NULL THEN 2
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet18),'') AS BIGINT),0) IS NOT NULL THEN 1
                ELSE 0 END)                                             AS x_chain_depth,
           CASE WHEN COALESCE(t1.agent_id,t2.agent_id,t3.agent_id,
                              t4.agent_id,t5.agent_id) IS NOT NULL
                THEN 1 ELSE 0 END                                        AS f_testline
    FROM x_ranked b
    LEFT JOIN x_testagent t1 ON t1.agent_id = b.bet18
    LEFT JOIN x_testagent t2 ON t2.agent_id = b.bet19
    LEFT JOIN x_testagent t3 ON t3.agent_id = b.bet20
    LEFT JOIN x_testagent t4 ON t4.agent_id = b.bet21
    LEFT JOIN x_testagent t5 ON t5.agent_id = b.bet22
    WHERE b.x_rn = 1
      AND b.category='1' AND UPPER(TRIM(b.bet38))='N'
      AND CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8)) > 0
  ),
  x_mk AS (
    SELECT s.*,
           CASE WHEN s.f_testline = 0 THEN 1 ELSE 0 END                 AS is_clean
    FROM x_bs0 s
  ),
  x_agg AS (
    SELECT s.x_member                                                        AS x_key,
           COUNT(*) AS n_bets, COUNT(DISTINCT s.x_round) AS n_rounds,
           COUNT(DISTINCT s.x_date) AS active_days, COUNT(DISTINCT s.x_tblshoe) AS active_shoes,
           COUNT(DISTINCT CONCAT_WS('|', s.x_date, s.x_table)) AS active_sessions,
           COUNT(DISTINCT s.x_table) AS n_tables, COUNT(DISTINCT s.x_dealer) AS n_dealers,
           COUNT(DISTINCT s.x_ip) AS n_ips, COUNT(DISTINCT s.x_product) AS n_products,
           MIN(s.x_date) AS first_seen_d, MAX(s.x_date) AS last_seen_d,
           SUM(s.x_stake) AS stake, SUM(s.x_valid) AS valid, SUM(s.x_rebate) AS rebate,
           SUM(s.x_net) AS net, SUM(-s.x_net *(100.0-s.x_agpct)/100.0) AS agent_cost,
           AVG(100.0-s.x_agpct)                   AS agent_pct,
           AVG(s.x_agpct)                         AS company_retain_pct,
           SUM(-s.x_net *s.x_agpct/100.0)         AS agent_cost_a_legacy,
           SUM(s.x_valid*s.x_agpct/100.0)         AS agent_cost_valid_base_legacy,
          AVG(COALESCE(s.x_rate1,100)) AS retain_pct_lv1, AVG(COALESCE(s.x_rate2,100)) AS retain_pct_lv2,
          AVG(COALESCE(s.x_rate3,100)) AS retain_pct_lv3, AVG(COALESCE(s.x_rate4,100)) AS retain_pct_lv4,
          AVG(COALESCE(s.x_rate5,100)) AS retain_pct_lv5, AVG(s.x_chain_depth) AS chain_depth_avg,
          AVG(COALESCE(100.0-s.x_rate1,0)) AS agent_pct_lv1, AVG(COALESCE(100.0-s.x_rate2,0)) AS agent_pct_lv2,
          AVG(COALESCE(100.0-s.x_rate3,0)) AS agent_pct_lv3, AVG(COALESCE(100.0-s.x_rate4,0)) AS agent_pct_lv4,
          AVG(COALESCE(100.0-s.x_rate5,0)) AS agent_pct_lv5,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate1,0)/100.0)                        AS agent_cost_lv1,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate2,0)/100.0)                        AS agent_cost_lv2,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate3,0)/100.0)                        AS agent_cost_lv3,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate4,0)/100.0)                        AS agent_cost_lv4,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate5,0)/100.0)                        AS agent_cost_lv5,
          SUM(-s.x_net*(COALESCE(100.0-s.x_rate1,0)+COALESCE(100.0-s.x_rate2,0)
                       +COALESCE(100.0-s.x_rate3,0)+COALESCE(100.0-s.x_rate4,0)
                       +COALESCE(100.0-s.x_rate5,0))/100.0)                   AS agent_cost_chain_additive,
          SUM(-s.x_net*(1.0 - CAST(COALESCE(s.x_rate1,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate2,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate3,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate4,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate5,100) AS DOUBLE)/100.0))
                                                                       AS agent_cost_chain_nested,
           AVG(s.x_rbpct) AS rbpct, AVG(s.x_freecomm*1.0) AS freecomm_rate,
           PERCENTILE_APPROX(s.x_stake,0.25) AS p25, PERCENTILE_APPROX(s.x_stake,0.50) AS p50,
           PERCENTILE_APPROX(s.x_stake,0.75) AS p75, PERCENTILE_APPROX(s.x_stake,0.90) AS p90,
           PERCENTILE_APPROX(s.x_stake,0.95) AS p95, PERCENTILE_APPROX(s.x_stake,0.99) AS p99,
           PERCENTILE_APPROX(s.x_valid,0.50) AS p50_valid,
           PERCENTILE_APPROX(s.x_net,0.50)   AS p50_profit,
           SUM(CASE WHEN s.x_rec = 1 THEN s.x_stake ELSE 0 END) AS st_in,
           SUM(CASE WHEN s.x_rec = 1 THEN 1 ELSE 0 END)         AS nb_in,
           SUM(CASE WHEN s.x_rec = 1 THEN s.x_net ELSE 0 END)   AS net_in,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN s.x_stake ELSE 0 END) AS st_out,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN 1 ELSE 0 END)         AS nb_out,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN s.x_net ELSE 0 END)   AS net_out,
           SUM(CASE WHEN s.x_rec=1 THEN s.x_stake ELSE 0 END) AS st_rec,
           SUM(CASE WHEN s.x_rec=1 THEN 1 ELSE 0 END)         AS nb_rec
    FROM x_mk s
    WHERE s.is_clean = 1
      AND s.x_member IS NOT NULL AND TRIM(CAST(s.x_member AS STRING)) <> ''
    GROUP BY s.x_member
  ),
  x_win AS (
    SELECT            COUNT(*) AS n_bets, COUNT(DISTINCT s.x_round) AS n_rounds,
           COUNT(DISTINCT s.x_date) AS active_days, COUNT(DISTINCT s.x_tblshoe) AS active_shoes,
           COUNT(DISTINCT CONCAT_WS('|', s.x_date, s.x_table)) AS active_sessions,
           COUNT(DISTINCT s.x_table) AS n_tables, COUNT(DISTINCT s.x_dealer) AS n_dealers,
           COUNT(DISTINCT s.x_ip) AS n_ips, COUNT(DISTINCT s.x_product) AS n_products,
           MIN(s.x_date) AS first_seen_d, MAX(s.x_date) AS last_seen_d,
           SUM(s.x_stake) AS stake, SUM(s.x_valid) AS valid, SUM(s.x_rebate) AS rebate,
           SUM(s.x_net) AS net, SUM(-s.x_net *(100.0-s.x_agpct)/100.0) AS agent_cost,
           AVG(100.0-s.x_agpct)                   AS agent_pct,
           AVG(s.x_agpct)                         AS company_retain_pct,
           SUM(-s.x_net *s.x_agpct/100.0)         AS agent_cost_a_legacy,
           SUM(s.x_valid*s.x_agpct/100.0)         AS agent_cost_valid_base_legacy,
          AVG(COALESCE(s.x_rate1,100)) AS retain_pct_lv1, AVG(COALESCE(s.x_rate2,100)) AS retain_pct_lv2,
          AVG(COALESCE(s.x_rate3,100)) AS retain_pct_lv3, AVG(COALESCE(s.x_rate4,100)) AS retain_pct_lv4,
          AVG(COALESCE(s.x_rate5,100)) AS retain_pct_lv5, AVG(s.x_chain_depth) AS chain_depth_avg,
          AVG(COALESCE(100.0-s.x_rate1,0)) AS agent_pct_lv1, AVG(COALESCE(100.0-s.x_rate2,0)) AS agent_pct_lv2,
          AVG(COALESCE(100.0-s.x_rate3,0)) AS agent_pct_lv3, AVG(COALESCE(100.0-s.x_rate4,0)) AS agent_pct_lv4,
          AVG(COALESCE(100.0-s.x_rate5,0)) AS agent_pct_lv5,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate1,0)/100.0)                        AS agent_cost_lv1,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate2,0)/100.0)                        AS agent_cost_lv2,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate3,0)/100.0)                        AS agent_cost_lv3,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate4,0)/100.0)                        AS agent_cost_lv4,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate5,0)/100.0)                        AS agent_cost_lv5,
          SUM(-s.x_net*(COALESCE(100.0-s.x_rate1,0)+COALESCE(100.0-s.x_rate2,0)
                       +COALESCE(100.0-s.x_rate3,0)+COALESCE(100.0-s.x_rate4,0)
                       +COALESCE(100.0-s.x_rate5,0))/100.0)                   AS agent_cost_chain_additive,
          SUM(-s.x_net*(1.0 - CAST(COALESCE(s.x_rate1,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate2,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate3,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate4,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate5,100) AS DOUBLE)/100.0))
                                                                       AS agent_cost_chain_nested,
           AVG(s.x_rbpct) AS rbpct, AVG(s.x_freecomm*1.0) AS freecomm_rate,
           PERCENTILE_APPROX(s.x_stake,0.25) AS p25, PERCENTILE_APPROX(s.x_stake,0.50) AS p50,
           PERCENTILE_APPROX(s.x_stake,0.75) AS p75, PERCENTILE_APPROX(s.x_stake,0.90) AS p90,
           PERCENTILE_APPROX(s.x_stake,0.95) AS p95, PERCENTILE_APPROX(s.x_stake,0.99) AS p99,
           PERCENTILE_APPROX(s.x_valid,0.50) AS p50_valid,
           PERCENTILE_APPROX(s.x_net,0.50)   AS p50_profit,
           SUM(CASE WHEN s.x_rec = 1 THEN s.x_stake ELSE 0 END) AS st_in,
           SUM(CASE WHEN s.x_rec = 1 THEN 1 ELSE 0 END)         AS nb_in,
           SUM(CASE WHEN s.x_rec = 1 THEN s.x_net ELSE 0 END)   AS net_in,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN s.x_stake ELSE 0 END) AS st_out,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN 1 ELSE 0 END)         AS nb_out,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN s.x_net ELSE 0 END)   AS net_out,
           SUM(CASE WHEN s.x_rec=1 THEN s.x_stake ELSE 0 END) AS st_rec,
           SUM(CASE WHEN s.x_rec=1 THEN 1 ELSE 0 END)         AS nb_rec
    FROM x_mk s
    WHERE s.is_clean = 1
      AND s.x_member IS NOT NULL AND TRIM(CAST(s.x_member AS STRING)) <> ''
  ),
      q AS (
        WITH per_user AS (                                                                                  -- 公共表表达式：开启中间结果集 per_user——单日逐账号之点数
          SELECT TRIM(`user`)                                                    AS u,                      -- 取列：账号
                 COUNT(*)                                                        AS n_pts,                  -- 计数表达式：该账号当日行数
                 SUM(CASE WHEN TRIM(status) = '1' THEN 1 ELSE 0 END)             AS n_pts_ok                -- 条件计数：其中成功态行数
          FROM ods_mariadb_2b.ods_a168_wallet_dtl                                                           -- 取数来源：取自钱包明细表
          WHERE dt = '2026-06-15'                                                                           -- 过滤条件：限定单日切片（窗中段）
          GROUP BY TRIM(`user`)                                                                             -- 分组：按账号汇总
        )                                                                                                   -- 续行：收束上方的子查询或函数括号
        SELECT                                                                                              -- 取列：起始取列子句
          '2026-06-15'                                                           AS dt_slice,               -- 字面取值：切片日
          COUNT(*)                                                               AS n_user_active,          -- 计数表达式：当日活跃账号数
          SUM(n_pts)                                                             AS n_pts_total,            -- 聚合取值：当日总行数
          ROUND(AVG(n_pts), 2)                                                   AS pts_avg,                -- 聚合取值：人均点数
          MIN(n_pts)                                                             AS pts_min,                -- 聚合取值：点数下界
          PERCENTILE_APPROX(n_pts, 0.50)                                         AS pts_p50,                -- 聚合取值：★ 点数中位——决定日内轨迹可否建
          PERCENTILE_APPROX(n_pts, 0.90)                                         AS pts_p90,                -- 聚合取值：点数九十分位
          PERCENTILE_APPROX(n_pts, 0.99)                                         AS pts_p99,                -- 聚合取值：点数九九分位
          MAX(n_pts)                                                             AS pts_max,                -- 聚合取值：点数上界
          ROUND(AVG(n_pts_ok), 2)                                                AS pts_ok_avg,             -- 聚合取值：人均成功态点数
          SUM(CASE WHEN n_pts = 1 THEN 1 ELSE 0 END)                             AS n_user_single_pt,       -- 条件计数：★ 当日仅一个点之账号数——其轨迹不可建
          ROUND(SUM(CASE WHEN n_pts = 1 THEN 1 ELSE 0 END) * 100.0
                / NULLIF(COUNT(*), 0), 4)                                        AS pct_single_pt           -- 比率表达式：单点账号占比
        FROM per_user                                                                                      -- 取数来源：取自本条自建的中间结果集 per_user
      )
    SELECT q.*,
           -- 一·经济层
           ROUND(e.stake,4) AS stake, ROUND(e.valid,4) AS valid_bet,
           ROUND(-e.net,4) AS profit, e.n_bets, e.n_rounds,
           ROUND(e.net/NULLIF(e.stake,0),8) AS roi,
           ROUND(e.net_in/NULLIF(e.st_in,0),8) AS roi_recent,
           ROUND(e.net_out/NULLIF(e.st_out,0),8) AS roi_non_recent,
           ROUND((e.net-e.rebate)/NULLIF(e.stake,0),8) AS roi_ex_rebate,
           ROUND(e.net,4) AS roi_numerator, ROUND(e.stake,4) AS roi_denominator,
           CASE WHEN e.stake IS NULL THEN 'NULL_DENOM' WHEN e.stake<=0 THEN 'ZERO_DENOM'
                WHEN e.n_bets<30 THEN 'THIN_EXPOSURE' ELSE 'OK' END AS roi_denominator_status,
           ROUND(e.rebate,4) AS rebate_cost, ROUND(e.agent_cost,4)                           AS cost_complement_b,
       ROUND(e.agent_pct,4)                            AS pct_complement,
       ROUND(e.company_retain_pct,4)                   AS pct_top_bet23,
       'AG03-UNRESOLVED'                                     AS agent_formula_version,
      'ALL5_LEVELS_bet23_to_bet27'                    AS agent_level_scope,
      ROUND(e.agent_cost_lv1,4) AS agent_cost_lv1, ROUND(e.agent_cost_lv2,4) AS agent_cost_lv2,
      ROUND(e.agent_cost_lv3,4) AS agent_cost_lv3, ROUND(e.agent_cost_lv4,4) AS agent_cost_lv4,
      ROUND(e.agent_cost_lv5,4) AS agent_cost_lv5,
      ROUND(e.agent_pct_lv1,6) AS agent_pct_lv1, ROUND(e.agent_pct_lv2,6) AS agent_pct_lv2,
      ROUND(e.agent_pct_lv3,6) AS agent_pct_lv3, ROUND(e.agent_pct_lv4,6) AS agent_pct_lv4,
      ROUND(e.agent_pct_lv5,6) AS agent_pct_lv5,
      ROUND(e.retain_pct_lv1,6) AS retain_pct_lv1, ROUND(e.retain_pct_lv2,6) AS retain_pct_lv2,
      ROUND(e.retain_pct_lv3,6) AS retain_pct_lv3, ROUND(e.retain_pct_lv4,6) AS retain_pct_lv4,
      ROUND(e.retain_pct_lv5,6) AS retain_pct_lv5, ROUND(e.chain_depth_avg,4) AS chain_depth_avg,
      ROUND(e.agent_cost_chain_additive,4)            AS agent_cost_chain_additive,
      ROUND(e.agent_cost_chain_nested,4)              AS agent_cost_chain_nested,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_additive,4) AS residual_chain_additive,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_nested,4)   AS residual_chain_nested,
      'PENDING_AG03'                                  AS decision_status,
      'FALSE'                                         AS admit_to_risk_decision,
      'NOT_FOR_ENFORCEMENT'                           AS deliverable_class,
       ROUND(e.agent_cost_a_legacy,4)                  AS agent_cost_a_legacy,
       ROUND(e.agent_cost_valid_base_legacy,4)         AS agent_cost_valid_base_legacy,
           ROUND(-e.net-e.rebate,4)                        AS ngr,
       ROUND(-e.net-e.rebate-e.agent_cost,4)           AS residual_b,
       ROUND(-e.net-e.rebate-e.agent_cost_a_legacy,4)  AS residual_a,
           ROUND((-e.net-e.rebate)/NULLIF(e.stake,0),8)    AS ngr_rate,
       ROUND((-e.net-e.rebate-e.agent_cost)/NULLIF(e.stake,0),8)   AS residual_b_rate,
      -- 【HF9c · canonical accounting contract】
      --   以下 canonical 字段只增加明确 scope；不删除、不覆盖既有字段。
      --   formal_bet23_* 保持 HF9b 当前生产公式及其 NULL/0 语义；
      --   lv1~lv5 / additive / nested 则分别采用各自原始 e.* 成本字段，
      --   rate 一律从未舍入的 e.* 分子 / e.stake 计算，禁止由展示值反算。
      ROUND(e.agent_cost,4) AS agent_cost_bet23_formal_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost,4) AS net_margin_bet23_formal_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost)/NULLIF(e.stake,0),8) AS net_margin_bet23_formal_rate_canonical,
      ROUND(e.agent_cost_lv1,4) AS agent_cost_lv1_bet23_canonical,
      ROUND(e.agent_cost_lv2,4) AS agent_cost_lv2_bet24_canonical,
      ROUND(e.agent_cost_lv3,4) AS agent_cost_lv3_bet25_canonical,
      ROUND(e.agent_cost_lv4,4) AS agent_cost_lv4_bet26_canonical,
      ROUND(e.agent_cost_lv5,4) AS agent_cost_lv5_bet27_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_lv1,4) AS net_margin_lv1_bet23_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_lv1)/NULLIF(e.stake,0),8) AS net_margin_lv1_bet23_rate_canonical,
      ROUND(e.agent_cost_chain_additive,4) AS agent_cost_chain_additive_canonical,
      ROUND(e.agent_cost_chain_nested,4) AS agent_cost_chain_nested_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_additive,4) AS net_margin_chain_additive_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_nested,4) AS net_margin_chain_nested_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_chain_additive)/NULLIF(e.stake,0),8) AS net_margin_chain_additive_rate_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_chain_nested)/NULLIF(e.stake,0),8) AS net_margin_chain_nested_rate_canonical,
       ROUND((-e.net-e.rebate-e.agent_cost_a_legacy)/NULLIF(e.stake,0),8) AS residual_a_rate,
           -- 二·分布层
           ROUND(e.stake/NULLIF(e.n_bets,0),4) AS avg_stake_per_bet,
           ROUND(e.valid/NULLIF(e.n_rounds,0),4) AS avg_valid_bet_per_round,
           ROUND(-e.net/NULLIF(e.n_rounds,0),4) AS avg_profit_per_round,
           ROUND(-e.net/NULLIF(e.active_days,0),4) AS avg_profit_per_day,
           ROUND(-e.net/NULLIF(e.active_shoes,0),4) AS avg_profit_per_shoe,
           ROUND(e.stake/NULLIF(e.active_days,0),4) AS avg_stake_per_active_day,
           ROUND(e.n_rounds*1.0/NULLIF(e.active_days,0),4) AS avg_rounds_per_active_day,
           ROUND(e.st_in/NULLIF(e.nb_in,0),4) AS avg_stake_recent,
           ROUND(e.st_out/NULLIF(e.nb_out,0),4) AS avg_stake_non_recent,
           ROUND(e.p25,4) AS p25_stake, ROUND(e.p50,4) AS p50_stake, ROUND(e.p75,4) AS p75_stake,
           ROUND(e.p90,4) AS p90_stake, ROUND(e.p95,4) AS p95_stake, ROUND(e.p99,4) AS p99_stake,
           ROUND(e.p50_valid,4) AS p50_valid_bet, ROUND(e.p50_profit,4) AS p50_profit,
           ROUND(e.p95/NULLIF(e.p50,0),6) AS p95_over_p50,
           ROUND(e.p99/NULLIF(e.p50,0),6) AS p99_over_p50,
           ROUND((e.stake/NULLIF(e.n_bets,0))/NULLIF(e.p50,0),6) AS avg_over_p50,
           -- 三·关系层
           e.n_tables AS common_table_count, e.n_dealers AS common_dealer_count,
           e.n_ips AS common_ip_count, e.n_products AS common_product_count,
           ROUND(e.st_in/NULLIF(e.stake,0),8) AS share_recent,
           -- 四·rate 层
           ROUND(-e.net/NULLIF(e.stake,0),8) AS hold_rate,
           ROUND(-e.net_in/NULLIF(e.st_in,0),8) AS hold_rate_recent,
           ROUND(e.rebate/NULLIF(e.valid,0),8) AS rebate_rate_actual,
           ROUND(e.rbpct,6) AS rebate_pct_config,
           ROUND(e.valid/NULLIF(e.stake,0),6) AS turnover_multiple,
           ROUND(e.freecomm_rate,6) AS free_comm_rate,
           ROUND(e.net_in/NULLIF(e.st_in,0)-e.net_out/NULLIF(e.st_out,0),8) AS roi_delta_recent,
           -- 五·动态层
           e.first_seen_d AS first_seen, e.last_seen_d AS last_seen,
           e.active_days, e.active_shoes, e.active_sessions,
           DATEDIFF(e.last_seen_d, e.first_seen_d)+1 AS span_days,
           ROUND(e.active_days*1.0/NULLIF(DATEDIFF(e.last_seen_d,e.first_seen_d)+1,0),6) AS persistence,
           ROUND((e.st_in/NULLIF(e.nb_in,0))/NULLIF(e.st_out/NULLIF(e.nb_out,0),0),6) AS ramp_recent_vs_prior,
           ROUND((e.st_rec/NULLIF(e.nb_rec,0))/NULLIF(e.stake/NULLIF(e.n_bets,0),0),6) AS ramp_recent_vs_all,
           ROUND((e.st_rec/NULLIF(e.stake,0))/0.30,6) AS stake_ramp,
           -- 六·决策层（HF9g-P5 · D-14 斧正 —— 本件属【全窗基线族】，相对刻度与决策标签一律 NULL）
           --   病灶：x_win 系全窗单行聚合（无 GROUP BY，恒 1 行，此为设计使然，非缺陷），
           --         经 CROSS JOIN 接入后 e.* 全行同值；六层之 NTILE / PERCENT_RANK 施于常数即退化，
           --         PERCENT_RANK 恒 0 ⇒ action_priority 恒判 A，全件 100% 误标。
           --   ★ 斧正原则：不给 x_win 补 GROUP BY —— 那会改变其「全窗基线」语义，属退化。
           --     正解与 #018 之 G-05／G-06 同治：范围外之行不得接受任何下游评分与决策标签。
           --   ★ 本件之 e.* 仍照常供其它列作全窗基线使用，仅六层相对刻度与决策标签置 NULL。
           CAST(NULL AS INT)                                              AS vip_tier,                        -- 空值取值：全窗基线族无实体可分档，置 NULL（NULL＝不适用，非 0）
           CAST(NULL AS DOUBLE)                                           AS economic_value,                  -- 空值取值：同上，禁以常数百分位冒充经济价值
           CAST(NULL AS DOUBLE)                                           AS roi_pr_global,                   -- 空值取值：同上
           CAST(NULL AS DOUBLE)                                           AS risk_value,                      -- 空值取值：兼容列，同上
           CAST(NULL AS DOUBLE)                                           AS pr_stake,                        -- 空值取值：兼容列，同上
           CAST(NULL AS DOUBLE)                                           AS pr_global,                       -- 空值取值：同上
           CAST(NULL AS DOUBLE)                                           AS pr_qualified,                    -- 空值取值：同上
           'GLOBAL_BASELINE_NO_ENTITY_RANKING'                            AS pr_qualified_population,         -- 字面取值：血统 —— 明示本件为全窗基线族，无实体排序总体
           CAST(NULL AS BIGINT)                                           AS pr_global_population_n,          -- 空值取值：血统 —— 不适用
           CAST(NULL AS BIGINT)                                           AS pr_qualified_population_n,       -- 空值取值：血统 —— 不适用
           'NOT_APPLICABLE_GLOBAL_BASELINE'                               AS pr_calculation_method,           -- 字面取值：血统 —— 算法不适用
           'HF9g-P5'                                                      AS pr_calculation_version,          -- 字面取值：血统 —— 算法版本
           CAST(NULL AS STRING)                                           AS evidence_flag,                   -- 空值取值：证据旗标不适用于全窗基线
           CAST(NULL AS STRING)                                           AS evidence_rate,                   -- 空值取值：同上
           CAST(NULL AS DOUBLE)                                           AS hold_ci_halfwidth_approx,        -- 空值取值：同上
           'X 全窗基线 · 不参与实体赏罚'                                    AS action_priority                  -- 字面取值：★ D-14 斧正 —— 本族恒不入赏罚，取代原 100% 误标之「A」
    FROM q
    CROSS JOIN x_win e
  ) y
) z
-- ── 逐批 WHERE 阶梯（★ 口诀：上界 ＝ 下界 ＋ 100000，两数同进）──
--    本件 T_true 未测，无需先跑 T_true；以 0 / 100000 控制本批返回区间，末批由实际行数 < 100000 判定
--    WHERE z.audit_rn >        0 AND z.audit_rn <=   100000   -- 第 1 批
--    WHERE z.audit_rn >   100000 AND z.audit_rn <=   200000   -- 第 2 批
--    WHERE z.audit_rn >   200000 AND z.audit_rn <=   300000   -- 第 3 批
--    WHERE z.audit_rn >   300000 AND z.audit_rn <=   400000   -- 第 4 批
--    WHERE z.audit_rn >   400000 AND z.audit_rn <=   500000   -- 第 5 批
--    WHERE z.audit_rn >   500000 AND z.audit_rn <=   600000   -- 第 6 批
--    WHERE z.audit_rn >   600000 AND z.audit_rn <=   700000   -- 第 7 批
--    …余批类推。第 k 批：WHERE z.audit_rn > (k-1)*100000 AND z.audit_rn <= k*100000
--    某批返回 < 100000 行即为末批，其后不再取。
--
--    ⚠ 常见误写（务必避开）：只推下界而上界不动 ——
--        WHERE z.audit_rn > 100000 AND z.audit_rn <= 100000   ← 自相矛盾，恒为假，返回空集
--        WHERE z.audit_rn > 200000 AND z.audit_rn <= 100000   ← 同上，空集
--      两个数必须**同时**前进，且始终相差 100000。
--      下界 ＝ 上一批之上界；上界 ＝ 本批之上界。
WHERE z.audit_rn > 0 AND z.audit_rn <= 100000 -- ★ HF9c 本批区间
ORDER BY z.audit_rn;


-- ══════════════════════════════════════════════════════════════════════════════════════════════
-- 129. _PH0_6b_member_daily.csv   [总包行 13015~13025 · 原 6 列 ＋六层约 60 列]
--     典型学：Z00 基建/元数据　派生旗标：recent（s.x_rec = 1 · 仅供 CASE 条件聚合，全包无任何 WHERE/AND/HAVING 以此过滤）　连接：q.`dt_day`
-- ══════════════════════════════════════════════════════════════════════════════════════════════
-- ── ① 先跑 T_true 留档（不足 100000 者一次导全，不必分批）──
-- ── ① T_true：HF9c 不再强制预跑完整 COUNT。
--    本批实际返回行数 < 100000 即判定为末批；全批完成后以各批 n_rows / audit_rn 范围核对总量。

-- ── ② 分批取数：第 1 批。第 k 批只改末行两数为 (k-1)*100000 与 k*100000 ──
--    审计字段二（REDTEAM 2026-08-24 裁定 · 四锁）：
--      audit_rn  全局观测坐标 —— 由**与原版审计版逐字同一**之排序键所生，两版可逐行对账
--      batch_id  物理分批信息 —— 该行所属批次，由 audit_rn 算得，非引擎所赋
--    ★ 锁三：二者皆为审计字段，**不得进入任何业务指标计算**。
--    ★ 锁四：两版经 audit_rn 逐行字段核验后，方可宣布输出完全一致。
SELECT z.*,
       CAST(FLOOR((z.audit_rn - 1) / 100000) + 1 AS INT)          AS batch_id,
       'A168_HF9F_20260827_0900' AS run_id,
       '2026-08-27 09:00:00' AS snapshot_sync_time
FROM (
  SELECT y.*,
         ROW_NUMBER() OVER (ORDER BY y.`residual_b` ASC, y.`roi` DESC, y.`dt_day`, y.`n_rows`, y.`n_mem001`, y.`rows_per_key`, y.`n_enable_N`, y.`n_canbet_N`) AS audit_rn
  FROM (
    WITH
      x_ranked AS (
    SELECT b.bet01, b.bet03, b.bet04, b.bet05, b.bet09, b.bet11, b.bet13,
           b.bet15, b.bet16, b.bet17, b.bet18, b.bet19, b.bet20, b.bet21,
           b.bet22, b.bet23, b.bet24, b.bet25, b.bet26, b.bet27, b.bet38, b.bet39, b.category, b.commission,
           b.dt, b.eid, b.ip, b.validbet, b.updatetime, b.sync_time,
           ROW_NUMBER() OVER (
             PARTITION BY b.bet01
             ORDER BY b.updatetime DESC, b.sync_time DESC, b.dt DESC)      AS x_rn
    FROM ods_mariadb_2b.ods_a168_bet02 b
    WHERE b.dt >= '2026-03-21' AND b.dt < '2026-08-07'
      AND b.bet02 = '101'
      AND b.sync_time <= '2026-08-27 09:00:00'
  ),
    x_testagent AS (
    SELECT age001 AS agent_id FROM ods_mariadb_2b.ods_a168_agent WHERE age022 = '1'
  ),
    x_bs0 AS (
    SELECT b.bet05 AS x_member, b.eid AS x_dealer, b.bet39 AS x_table,
           b.bet03 AS x_shoe, b.ip AS x_ip, b.bet09 AS x_product, b.dt AS x_date,
           CONCAT_WS('|', b.bet03, b.bet04, b.bet39)                      AS x_round,
           CONCAT_WS('|', b.bet39, b.bet03)                               AS x_tblshoe,
           CAST(NULLIF(TRIM(b.bet04),'') AS INT)                          AS x_rno,
           CASE WHEN b.dt >= '2026-07-08' THEN 1 ELSE 0 END               AS x_rec,
           CASE WHEN TRIM(b.commission)='1' THEN 1 ELSE 0 END             AS x_freecomm,
           CAST(NULLIF(TRIM(b.bet13),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_stake,
           CAST(NULLIF(TRIM(b.validbet),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_valid,
           CAST(NULLIF(TRIM(b.bet16),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_rebate,
           CAST(NULLIF(TRIM(b.bet17),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_net,
           CAST(NULLIF(TRIM(b.bet15),'') AS DECIMAL(20,6))                AS x_rbpct,
           COALESCE(CAST(NULLIF(TRIM(b.bet23),'') AS DECIMAL(20,6)),0)   AS x_agpct,
          NULLIF(CAST(NULLIF(TRIM(b.bet23),'') AS DECIMAL(20,6)),0)     AS x_rate1,
          NULLIF(CAST(NULLIF(TRIM(b.bet24),'') AS DECIMAL(20,6)),0)     AS x_rate2,
          NULLIF(CAST(NULLIF(TRIM(b.bet25),'') AS DECIMAL(20,6)),0)     AS x_rate3,
          NULLIF(CAST(NULLIF(TRIM(b.bet26),'') AS DECIMAL(20,6)),0)     AS x_rate4,
          NULLIF(CAST(NULLIF(TRIM(b.bet27),'') AS DECIMAL(20,6)),0)     AS x_rate5,
          (CASE WHEN NULLIF(CAST(NULLIF(TRIM(b.bet22),'') AS BIGINT),0) IS NOT NULL THEN 5
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet21),'') AS BIGINT),0) IS NOT NULL THEN 4
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet20),'') AS BIGINT),0) IS NOT NULL THEN 3
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet19),'') AS BIGINT),0) IS NOT NULL THEN 2
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet18),'') AS BIGINT),0) IS NOT NULL THEN 1
                ELSE 0 END)                                             AS x_chain_depth,
           CASE WHEN COALESCE(t1.agent_id,t2.agent_id,t3.agent_id,
                              t4.agent_id,t5.agent_id) IS NOT NULL
                THEN 1 ELSE 0 END                                        AS f_testline
    FROM x_ranked b
    LEFT JOIN x_testagent t1 ON t1.agent_id = b.bet18
    LEFT JOIN x_testagent t2 ON t2.agent_id = b.bet19
    LEFT JOIN x_testagent t3 ON t3.agent_id = b.bet20
    LEFT JOIN x_testagent t4 ON t4.agent_id = b.bet21
    LEFT JOIN x_testagent t5 ON t5.agent_id = b.bet22
    WHERE b.x_rn = 1
      AND b.category='1' AND UPPER(TRIM(b.bet38))='N'
      AND CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8)) > 0
  ),
  x_mk AS (
    SELECT s.*,
           CASE WHEN s.f_testline = 0 THEN 1 ELSE 0 END                 AS is_clean
    FROM x_bs0 s
  ),
  x_agg AS (
    SELECT s.x_date                                                        AS x_key,
           COUNT(*) AS n_bets, COUNT(DISTINCT s.x_round) AS n_rounds,
           COUNT(DISTINCT s.x_date) AS active_days, COUNT(DISTINCT s.x_tblshoe) AS active_shoes,
           COUNT(DISTINCT CONCAT_WS('|', s.x_date, s.x_table)) AS active_sessions,
           COUNT(DISTINCT s.x_table) AS n_tables, COUNT(DISTINCT s.x_dealer) AS n_dealers,
           COUNT(DISTINCT s.x_ip) AS n_ips, COUNT(DISTINCT s.x_product) AS n_products,
           MIN(s.x_date) AS first_seen_d, MAX(s.x_date) AS last_seen_d,
           SUM(s.x_stake) AS stake, SUM(s.x_valid) AS valid, SUM(s.x_rebate) AS rebate,
           SUM(s.x_net) AS net, SUM(-s.x_net *(100.0-s.x_agpct)/100.0) AS agent_cost,
           AVG(100.0-s.x_agpct)                   AS agent_pct,
           AVG(s.x_agpct)                         AS company_retain_pct,
           SUM(-s.x_net *s.x_agpct/100.0)         AS agent_cost_a_legacy,
           SUM(s.x_valid*s.x_agpct/100.0)         AS agent_cost_valid_base_legacy,
          AVG(COALESCE(s.x_rate1,100)) AS retain_pct_lv1, AVG(COALESCE(s.x_rate2,100)) AS retain_pct_lv2,
          AVG(COALESCE(s.x_rate3,100)) AS retain_pct_lv3, AVG(COALESCE(s.x_rate4,100)) AS retain_pct_lv4,
          AVG(COALESCE(s.x_rate5,100)) AS retain_pct_lv5, AVG(s.x_chain_depth) AS chain_depth_avg,
          AVG(COALESCE(100.0-s.x_rate1,0)) AS agent_pct_lv1, AVG(COALESCE(100.0-s.x_rate2,0)) AS agent_pct_lv2,
          AVG(COALESCE(100.0-s.x_rate3,0)) AS agent_pct_lv3, AVG(COALESCE(100.0-s.x_rate4,0)) AS agent_pct_lv4,
          AVG(COALESCE(100.0-s.x_rate5,0)) AS agent_pct_lv5,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate1,0)/100.0)                        AS agent_cost_lv1,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate2,0)/100.0)                        AS agent_cost_lv2,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate3,0)/100.0)                        AS agent_cost_lv3,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate4,0)/100.0)                        AS agent_cost_lv4,
          SUM(-s.x_net*COALESCE(100.0-s.x_rate5,0)/100.0)                        AS agent_cost_lv5,
          SUM(-s.x_net*(COALESCE(100.0-s.x_rate1,0)+COALESCE(100.0-s.x_rate2,0)
                       +COALESCE(100.0-s.x_rate3,0)+COALESCE(100.0-s.x_rate4,0)
                       +COALESCE(100.0-s.x_rate5,0))/100.0)                   AS agent_cost_chain_additive,
          SUM(-s.x_net*(1.0 - CAST(COALESCE(s.x_rate1,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate2,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate3,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate4,100) AS DOUBLE)/100.0
                            * CAST(COALESCE(s.x_rate5,100) AS DOUBLE)/100.0))
                                                                       AS agent_cost_chain_nested,
           AVG(s.x_rbpct) AS rbpct, AVG(s.x_freecomm*1.0) AS freecomm_rate,
           PERCENTILE_APPROX(s.x_stake,0.25) AS p25, PERCENTILE_APPROX(s.x_stake,0.50) AS p50,
           PERCENTILE_APPROX(s.x_stake,0.75) AS p75, PERCENTILE_APPROX(s.x_stake,0.90) AS p90,
           PERCENTILE_APPROX(s.x_stake,0.95) AS p95, PERCENTILE_APPROX(s.x_stake,0.99) AS p99,
           PERCENTILE_APPROX(s.x_valid,0.50) AS p50_valid,
           PERCENTILE_APPROX(s.x_net,0.50)   AS p50_profit,
           SUM(CASE WHEN s.x_rec = 1 THEN s.x_stake ELSE 0 END) AS st_in,
           SUM(CASE WHEN s.x_rec = 1 THEN 1 ELSE 0 END)         AS nb_in,
           SUM(CASE WHEN s.x_rec = 1 THEN s.x_net ELSE 0 END)   AS net_in,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN s.x_stake ELSE 0 END) AS st_out,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN 1 ELSE 0 END)         AS nb_out,
           SUM(CASE WHEN NOT (s.x_rec = 1) THEN s.x_net ELSE 0 END)   AS net_out,
           SUM(CASE WHEN s.x_rec=1 THEN s.x_stake ELSE 0 END) AS st_rec,
           SUM(CASE WHEN s.x_rec=1 THEN 1 ELSE 0 END)         AS nb_rec
    FROM x_mk s
    WHERE s.is_clean = 1
      AND s.x_date IS NOT NULL AND TRIM(CAST(s.x_date AS STRING)) <> ''
    GROUP BY s.x_date
  ),
      q AS (
        SELECT                                                                                              -- 取列：起始取列子句
          dt                                                                     AS dt_day,                 -- 取列：分区日
          COUNT(*)                                                               AS n_rows,                 -- 计数表达式：当日行数
          COUNT(DISTINCT TRIM(mem001))                                           AS n_mem001,               -- 计数表达式：当日去重会员键数
          ROUND(COUNT(*) * 1.0 / NULLIF(COUNT(DISTINCT TRIM(mem001)), 0), 4)     AS rows_per_key,           -- 比率表达式：日内版本数
          SUM(CASE WHEN TRIM(mem016) = 'N' THEN 1 ELSE 0 END)                    AS n_enable_N,             -- 条件计数：当日停用数
          SUM(CASE WHEN TRIM(mem017) = 'N' THEN 1 ELSE 0 END)                    AS n_canbet_N              -- 条件计数：当日禁投注数
        FROM ods_mariadb_2b.ods_a168_member                                                                 -- 取数来源：取自会员主表
        WHERE dt >= '2026-03-21' AND dt < '2026-08-07'                                                      -- 过滤条件：限定分析窗
        GROUP BY dt                                                                                         -- 分组：按分区日汇总
      )
    SELECT q.*,
           -- 一·经济层
           ROUND(e.stake,4) AS stake, ROUND(e.valid,4) AS valid_bet,
           ROUND(-e.net,4) AS profit, e.n_bets, e.n_rounds,
           ROUND(e.net/NULLIF(e.stake,0),8) AS roi,
           ROUND(e.net_in/NULLIF(e.st_in,0),8) AS roi_recent,
           ROUND(e.net_out/NULLIF(e.st_out,0),8) AS roi_non_recent,
           ROUND((e.net-e.rebate)/NULLIF(e.stake,0),8) AS roi_ex_rebate,
           ROUND(e.net,4) AS roi_numerator, ROUND(e.stake,4) AS roi_denominator,
           CASE WHEN e.stake IS NULL THEN 'NULL_DENOM' WHEN e.stake<=0 THEN 'ZERO_DENOM'
                WHEN e.n_bets<30 THEN 'THIN_EXPOSURE' ELSE 'OK' END AS roi_denominator_status,
           ROUND(e.rebate,4) AS rebate_cost, ROUND(e.agent_cost,4)                           AS cost_complement_b,
       ROUND(e.agent_pct,4)                            AS pct_complement,
       ROUND(e.company_retain_pct,4)                   AS pct_top_bet23,
       'AG03-UNRESOLVED'                                     AS agent_formula_version,
      'ALL5_LEVELS_bet23_to_bet27'                    AS agent_level_scope,
      ROUND(e.agent_cost_lv1,4) AS agent_cost_lv1, ROUND(e.agent_cost_lv2,4) AS agent_cost_lv2,
      ROUND(e.agent_cost_lv3,4) AS agent_cost_lv3, ROUND(e.agent_cost_lv4,4) AS agent_cost_lv4,
      ROUND(e.agent_cost_lv5,4) AS agent_cost_lv5,
      ROUND(e.agent_pct_lv1,6) AS agent_pct_lv1, ROUND(e.agent_pct_lv2,6) AS agent_pct_lv2,
      ROUND(e.agent_pct_lv3,6) AS agent_pct_lv3, ROUND(e.agent_pct_lv4,6) AS agent_pct_lv4,
      ROUND(e.agent_pct_lv5,6) AS agent_pct_lv5,
      ROUND(e.retain_pct_lv1,6) AS retain_pct_lv1, ROUND(e.retain_pct_lv2,6) AS retain_pct_lv2,
      ROUND(e.retain_pct_lv3,6) AS retain_pct_lv3, ROUND(e.retain_pct_lv4,6) AS retain_pct_lv4,
      ROUND(e.retain_pct_lv5,6) AS retain_pct_lv5, ROUND(e.chain_depth_avg,4) AS chain_depth_avg,
      ROUND(e.agent_cost_chain_additive,4)            AS agent_cost_chain_additive,
      ROUND(e.agent_cost_chain_nested,4)              AS agent_cost_chain_nested,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_additive,4) AS residual_chain_additive,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_nested,4)   AS residual_chain_nested,
      'PENDING_AG03'                                  AS decision_status,
      'FALSE'                                         AS admit_to_risk_decision,
      'NOT_FOR_ENFORCEMENT'                           AS deliverable_class,
       ROUND(e.agent_cost_a_legacy,4)                  AS agent_cost_a_legacy,
       ROUND(e.agent_cost_valid_base_legacy,4)         AS agent_cost_valid_base_legacy,
           ROUND(-e.net-e.rebate,4)                        AS ngr,
       ROUND(-e.net-e.rebate-e.agent_cost,4)           AS residual_b,
       ROUND(-e.net-e.rebate-e.agent_cost_a_legacy,4)  AS residual_a,
           ROUND((-e.net-e.rebate)/NULLIF(e.stake,0),8)    AS ngr_rate,
       ROUND((-e.net-e.rebate-e.agent_cost)/NULLIF(e.stake,0),8)   AS residual_b_rate,
      -- 【HF9c · canonical accounting contract】
      --   以下 canonical 字段只增加明确 scope；不删除、不覆盖既有字段。
      --   formal_bet23_* 保持 HF9b 当前生产公式及其 NULL/0 语义；
      --   lv1~lv5 / additive / nested 则分别采用各自原始 e.* 成本字段，
      --   rate 一律从未舍入的 e.* 分子 / e.stake 计算，禁止由展示值反算。
      ROUND(e.agent_cost,4) AS agent_cost_bet23_formal_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost,4) AS net_margin_bet23_formal_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost)/NULLIF(e.stake,0),8) AS net_margin_bet23_formal_rate_canonical,
      ROUND(e.agent_cost_lv1,4) AS agent_cost_lv1_bet23_canonical,
      ROUND(e.agent_cost_lv2,4) AS agent_cost_lv2_bet24_canonical,
      ROUND(e.agent_cost_lv3,4) AS agent_cost_lv3_bet25_canonical,
      ROUND(e.agent_cost_lv4,4) AS agent_cost_lv4_bet26_canonical,
      ROUND(e.agent_cost_lv5,4) AS agent_cost_lv5_bet27_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_lv1,4) AS net_margin_lv1_bet23_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_lv1)/NULLIF(e.stake,0),8) AS net_margin_lv1_bet23_rate_canonical,
      ROUND(e.agent_cost_chain_additive,4) AS agent_cost_chain_additive_canonical,
      ROUND(e.agent_cost_chain_nested,4) AS agent_cost_chain_nested_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_additive,4) AS net_margin_chain_additive_canonical,
      ROUND(-e.net-e.rebate-e.agent_cost_chain_nested,4) AS net_margin_chain_nested_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_chain_additive)/NULLIF(e.stake,0),8) AS net_margin_chain_additive_rate_canonical,
      ROUND((-e.net-e.rebate-e.agent_cost_chain_nested)/NULLIF(e.stake,0),8) AS net_margin_chain_nested_rate_canonical,
       ROUND((-e.net-e.rebate-e.agent_cost_a_legacy)/NULLIF(e.stake,0),8) AS residual_a_rate,
           -- 二·分布层
           ROUND(e.stake/NULLIF(e.n_bets,0),4) AS avg_stake_per_bet,
           ROUND(e.valid/NULLIF(e.n_rounds,0),4) AS avg_valid_bet_per_round,
           ROUND(-e.net/NULLIF(e.n_rounds,0),4) AS avg_profit_per_round,
           ROUND(-e.net/NULLIF(e.active_days,0),4) AS avg_profit_per_day,
           ROUND(-e.net/NULLIF(e.active_shoes,0),4) AS avg_profit_per_shoe,
           ROUND(e.stake/NULLIF(e.active_days,0),4) AS avg_stake_per_active_day,
           ROUND(e.n_rounds*1.0/NULLIF(e.active_days,0),4) AS avg_rounds_per_active_day,
           ROUND(e.st_in/NULLIF(e.nb_in,0),4) AS avg_stake_recent,
           ROUND(e.st_out/NULLIF(e.nb_out,0),4) AS avg_stake_non_recent,
           ROUND(e.p25,4) AS p25_stake, ROUND(e.p50,4) AS p50_stake, ROUND(e.p75,4) AS p75_stake,
           ROUND(e.p90,4) AS p90_stake, ROUND(e.p95,4) AS p95_stake, ROUND(e.p99,4) AS p99_stake,
           ROUND(e.p50_valid,4) AS p50_valid_bet, ROUND(e.p50_profit,4) AS p50_profit,
           ROUND(e.p95/NULLIF(e.p50,0),6) AS p95_over_p50,
           ROUND(e.p99/NULLIF(e.p50,0),6) AS p99_over_p50,
           ROUND((e.stake/NULLIF(e.n_bets,0))/NULLIF(e.p50,0),6) AS avg_over_p50,
           -- 三·关系层
           e.n_tables AS common_table_count, e.n_dealers AS common_dealer_count,
           e.n_ips AS common_ip_count, e.n_products AS common_product_count,
           ROUND(e.st_in/NULLIF(e.stake,0),8) AS share_recent,
           -- 四·rate 层
           ROUND(-e.net/NULLIF(e.stake,0),8) AS hold_rate,
           ROUND(-e.net_in/NULLIF(e.st_in,0),8) AS hold_rate_recent,
           ROUND(e.rebate/NULLIF(e.valid,0),8) AS rebate_rate_actual,
           ROUND(e.rbpct,6) AS rebate_pct_config,
           ROUND(e.valid/NULLIF(e.stake,0),6) AS turnover_multiple,
           ROUND(e.freecomm_rate,6) AS free_comm_rate,
           ROUND(e.net_in/NULLIF(e.st_in,0)-e.net_out/NULLIF(e.st_out,0),8) AS roi_delta_recent,
           -- 五·动态层
           e.first_seen_d AS first_seen, e.last_seen_d AS last_seen,
           e.active_days, e.active_shoes, e.active_sessions,
           DATEDIFF(e.last_seen_d, e.first_seen_d)+1 AS span_days,
           ROUND(e.active_days*1.0/NULLIF(DATEDIFF(e.last_seen_d,e.first_seen_d)+1,0),6) AS persistence,
           ROUND((e.st_in/NULLIF(e.nb_in,0))/NULLIF(e.st_out/NULLIF(e.nb_out,0),0),6) AS ramp_recent_vs_prior,
           ROUND((e.st_rec/NULLIF(e.nb_rec,0))/NULLIF(e.stake/NULLIF(e.n_bets,0),0),6) AS ramp_recent_vs_all,
           ROUND((e.st_rec/NULLIF(e.stake,0))/0.30,6) AS stake_ramp,
           -- 六·决策层（HF9f · 详见档头【HF9f 变更说明】；本段两版逐字同一）
           NTILE(5) OVER (ORDER BY e.stake) AS vip_tier,                                                        -- 窗口取值：相对刻度 B 族，全体五等分；须连同下方血统五元组一并解读，禁作硬阈值判型
           PERCENT_RANK() OVER (ORDER BY -e.net-e.rebate-e.agent_cost)    AS economic_value,                    -- 窗口取值：HF9f·F-19 修正 —— HF9e 写作 -(-…) 双负号致方向颠倒（#075 实测 corr(economic_value, residual_b) = -1.0000）；今与 action_priority 排序键归一，值大即平台真净利高
           PERCENT_RANK() OVER (ORDER BY e.net/NULLIF(e.stake,0))         AS roi_pr_global,                     -- 窗口取值：HF9f·F-17 正名 —— 本列实为 ROI（玩家净回报率）之全体百分位，与「风险」无关；旧名 risk_value 见下一行
           PERCENT_RANK() OVER (ORDER BY e.net/NULLIF(e.stake,0))         AS risk_value,                        -- 窗口取值：兼容列，恒等于 roi_pr_global，仅为下游迁移窗保留；HF9g 起废弃，禁新引用
           PERCENT_RANK() OVER (ORDER BY e.stake)                         AS pr_stake,                          -- 窗口取值：兼容列，恒等于 pr_global，原名保留以免断链
           PERCENT_RANK() OVER (ORDER BY e.stake)                         AS pr_global,                         -- 窗口取值：HF9f·F-1 双轨之一 —— 全体口径百分位，参照总体即本件全部输出行
           CASE WHEN e.n_rounds >= 30                                                                           -- 条件分支：起始分支 —— 仅在合格子集内计算合格口径百分位
                  THEN PERCENT_RANK() OVER (PARTITION BY CASE WHEN e.n_rounds >= 30 THEN 1 ELSE 0 END ORDER BY e.stake)  -- 分支取值：以合格与否分区，故本值即 n_rounds>=30 子集内之百分位
                ELSE NULL END                                             AS pr_qualified,                      -- 条件分支：收束上方分支 —— 不合格者留 NULL（NULL＝未测，非 0），产出「pr_qualified」
           'n_rounds>=30'                                                 AS pr_qualified_population,           -- 字面取值：血统 —— 合格子集之定义
           COUNT(*) OVER ()                                               AS pr_global_population_n,            -- 窗口取值：血统 —— 全体口径之参照总体规模，渲染时现算，禁写死
           SUM(CASE WHEN e.n_rounds >= 30 THEN 1 ELSE 0 END) OVER ()      AS pr_qualified_population_n,         -- 窗口取值：血统 —— 合格子集之参照总体规模，现算，禁写死
           'PERCENT_RANK_OVER_ORDER_BY_e_stake'                           AS pr_calculation_method,             -- 字面取值：血统 —— 算法标识
           'HF9f'                                                         AS pr_calculation_version,            -- 字面取值：血统 —— 算法版本
           CASE WHEN e.n_rounds IS NULL OR e.n_rounds < 30 THEN 'THIN_ROUNDS' ELSE 'OK' END AS evidence_flag,   -- 条件分支：HF9f·F-2a 证据旗标 —— THIN_ROUNDS 者禁入执行队列，仅入观察队列
           CASE WHEN e.n_rounds IS NULL       THEN NULL                                                         -- 条件分支：起始分支 —— 未测者留 NULL（自家铁律：NULL ≠ 0）
                WHEN e.n_rounds >= 31483      THEN 'L1_POWERED'                                                 -- 分支判定：MDE 反解第一档
                WHEN e.n_rounds >= 15409      THEN 'L2_CI_1P5'                                                  -- 分支判定：MDE 反解第二档
                WHEN e.n_rounds >=  8668      THEN 'L3_CI_2P0'                                                  -- 分支判定：MDE 反解第三档
                WHEN e.n_rounds >=  3852      THEN 'L4_CI_3P0'                                                  -- 分支判定：MDE 反解第四档
                ELSE 'L5_INSUFFICIENT' END                                AS evidence_rate,                     -- 条件分支：收束上方 —— HF9f·F-3 证据分档，承 HF9e 前议之 MDE 反解五档，须于 F-4 敏感性实验后复核
           ROUND(1.96 * 0.95 / SQRT(NULLIF(CAST(e.n_rounds AS DOUBLE),0)),8) AS hold_ci_halfwidth_approx,       -- 比率表达式：HF9f·F-3 逐行现算之 95% 半宽近似；常数 0.95 为登记值，本轮 #075 实测每局 ROI 隐含 σ 于最薄层为 0.9249，二者差异待 F-4 裁定
           CASE WHEN e.stake IS NULL OR e.stake<=0 OR e.n_bets<30 OR e.n_rounds IS NULL OR e.n_rounds<30 THEN 'Z 证据不足 · 不动作'  -- 条件分支：HF9f·F-2 双条件取严 —— HF9e 仅卡 e.n_bets<30，致 n_bets>=30 而 n_rounds<30 者绕过 Z（#075 实测 18,537 名，其中 8,145 名已入 A/D 待裁）；今两条件并列取严
                WHEN PERCENT_RANK() OVER (ORDER BY -e.net-e.rebate-e.agent_cost)<=0.10                          -- 分支判定：平台真净利之最低十分位
                  THEN 'A 净亏最大十分位 · 优先复核'                                                             -- 分支取值：HF9f·F-20 正名 —— 本档 Σresidual_b 于 #075 实测 = -100,236,896，系平台净亏最大群，旧名「残值最低十分位 · 待裁」名实不符
                WHEN PERCENT_RANK() OVER (ORDER BY -e.net-e.rebate-e.agent_cost)>=0.80                          -- 分支判定：平台真净利之最高二十分位
                  THEN 'D 净利最高二十分位 · 优先留存'                                                           -- 分支取值：HF9f·F-20 正名 —— 本档 Σresidual_b 于 #075 实测 = +281,733,190，系核心利润源；与 A 档方向相反，旧版同标「待裁」属名实不符
                ELSE 'E 常规' END                                          AS action_priority                   -- 条件分支：收束上方判词，产出「action_priority」
    FROM q
    LEFT JOIN x_agg e ON CAST(e.x_key AS STRING) = CAST(q.`dt_day` AS STRING)
  ) y
) z
-- ── 逐批 WHERE 阶梯（★ 口诀：上界 ＝ 下界 ＋ 100000，两数同进）──
--    本件 T_true 未测，无需先跑 T_true；以 0 / 100000 控制本批返回区间，末批由实际行数 < 100000 判定
--    WHERE z.audit_rn >        0 AND z.audit_rn <=   100000   -- 第 1 批
--    WHERE z.audit_rn >   100000 AND z.audit_rn <=   200000   -- 第 2 批
--    WHERE z.audit_rn >   200000 AND z.audit_rn <=   300000   -- 第 3 批
--    WHERE z.audit_rn >   300000 AND z.audit_rn <=   400000   -- 第 4 批
--    WHERE z.audit_rn >   400000 AND z.audit_rn <=   500000   -- 第 5 批
--    WHERE z.audit_rn >   500000 AND z.audit_rn <=   600000   -- 第 6 批
--    WHERE z.audit_rn >   600000 AND z.audit_rn <=   700000   -- 第 7 批
--    …余批类推。第 k 批：WHERE z.audit_rn > (k-1)*100000 AND z.audit_rn <= k*100000
--    某批返回 < 100000 行即为末批，其后不再取。
--
--    ⚠ 常见误写（务必避开）：只推下界而上界不动 ——
--        WHERE z.audit_rn > 100000 AND z.audit_rn <= 100000   ← 自相矛盾，恒为假，返回空集
--        WHERE z.audit_rn > 200000 AND z.audit_rn <= 100000   ← 同上，空集
--      两个数必须**同时**前进，且始终相差 100000。
--      下界 ＝ 上一批之上界；上界 ＝ 本批之上界。
WHERE z.audit_rn > 0 AND z.audit_rn <= 100000 -- ★ HF9c 本批区间
ORDER BY z.audit_rn;
-- ══════════════════════════════════════════════════════════════════════════════════════════════
-- 130. DICT_ALL_columns.csv   [字典补件 · 元数据 · 无六层商业块]
--     典型学：DIC 字典/元数据　粒度：table × column　说明：全库逐表逐列字典（含同名跨表现算）
--     ★ 本件循 #078 S03_agent_score 之例，**不套六层商业模板** —— 元数据无实体可分档，
--       施以 NTILE / PERCENT_RANK 即重蹈 D-14 覆辙（相对刻度施于非实体行）。
-- ══════════════════════════════════════════════════════════════════════════════════════════════
-- 【本件立意】口诀 §八「字典缺口 —— P4 无一件承载」之补件其一。
--   全部字段直取 information_schema.columns，同名跨表统计以窗口函数**现算**，无一硬编码（铁律第九条）。
--   同名异型者标 CROSS_TABLE_TYPE_DIVERGENT，与 #Z04_name_collision 之「义异且型异」互为交叉验证。
-- ── ① T_true：本件行数远小于 100000，一次导全即可；批次阶梯照列以保体例一致 ──
-- ── ② 分批取数：第 1 批。第 k 批只改末行两数为 (k-1)*100000 与 k*100000 ──
SELECT z.*,
       CAST(FLOOR((z.audit_rn - 1) / 100000) + 1 AS INT)          AS batch_id,
       'A168_HF9F_20260827_0900' AS run_id,
       '2026-08-27 09:00:00' AS snapshot_sync_time
FROM (
  SELECT y.*,
         ROW_NUMBER() OVER (ORDER BY y.`table_name`, y.`ordinal_position`, y.`column_name`) AS audit_rn
  FROM (
      SELECT c.`TABLE_SCHEMA`                                            AS table_schema,                    -- 直取：库名，来源 information_schema.columns
             c.`TABLE_NAME`                                              AS table_name,                      -- 直取：表名
             c.`COLUMN_NAME`                                             AS column_name,                     -- 直取：列名
             CAST(c.`ORDINAL_POSITION` AS BIGINT)                        AS ordinal_position,                -- 类型转换：列序号，CAST 为 BIGINT（自家铁律：数值列一律显式转型）
             c.`DATA_TYPE`                                               AS data_type,                       -- 直取：基础型别
             c.`COLUMN_TYPE`                                             AS column_type,                     -- 直取：完整型别（含长度）
             c.`IS_NULLABLE`                                             AS is_nullable,                     -- 直取：可空性
             c.`COLUMN_DEFAULT`                                          AS column_default,                  -- 直取：预设值（NULL ＝ 无预设，非 0）
             c.`COLUMN_COMMENT`                                          AS column_comment,                  -- 直取：列注释（空字符串 ≠ NULL，两者皆保留原样）
             CAST(LENGTH(c.`COLUMN_NAME`) AS BIGINT)                     AS name_len,                        -- 现算：列名长度
             CASE WHEN c.`COLUMN_COMMENT` IS NULL OR TRIM(c.`COLUMN_COMMENT`) = '' THEN 0 ELSE 1 END          AS has_comment,                     -- 条件分支：是否具注释，供覆盖率现算
             CAST(COUNT(*)        OVER (PARTITION BY c.`COLUMN_NAME`) AS BIGINT)                              AS n_occurrence_in_schema,          -- 窗口聚合：同名列在全库出现次数（现算，非登记值）
             CAST(COUNT(DISTINCT c.`TABLE_NAME`) OVER (PARTITION BY c.`COLUMN_NAME`) AS BIGINT)               AS n_tables_with_name,              -- 窗口聚合：同名列跨表数
             CAST(COUNT(DISTINCT c.`DATA_TYPE`)  OVER (PARTITION BY c.`COLUMN_NAME`) AS BIGINT)               AS n_types_with_name,               -- 窗口聚合：同名列之相异基础型别数
             CASE WHEN CAST(COUNT(DISTINCT c.`TABLE_NAME`) OVER (PARTITION BY c.`COLUMN_NAME`) AS BIGINT) <= 1 THEN 'UNIQUE_TO_ONE_TABLE'
                  WHEN CAST(COUNT(DISTINCT c.`DATA_TYPE`)  OVER (PARTITION BY c.`COLUMN_NAME`) AS BIGINT) > 1 THEN 'CROSS_TABLE_TYPE_DIVERGENT'
                  ELSE 'CROSS_TABLE_TYPE_UNIFORM' END                    AS name_collision_class,            -- 条件分支：同名异型判级 —— 型异者列为高风险，与 Z04 之「义异且型异」同治
             CASE WHEN c.`TABLE_NAME` = 'ods_a168_bet01' THEN 1 ELSE 0 END                                    AS in_bet01,                        -- 条件分支：本列是否属 bet01
             CASE WHEN c.`TABLE_NAME` = 'ods_a168_bet02' THEN 1 ELSE 0 END                                    AS in_bet02,                        -- 条件分支：本列是否属 bet02
             CAST(COUNT(*) OVER (PARTITION BY c.`TABLE_NAME`) AS BIGINT)                                      AS n_columns_in_table,              -- 窗口聚合：本表列数
             'INFORMATION_SCHEMA.COLUMNS'                                AS evidence_source,                 -- 字面取值：血统 —— 证据来源，非人工登记
             'OBSERVED'                                                  AS evidence_grade,                  -- 字面取值：证据分级 —— 引擎目录直读，属实测
             'NOT_APPLICABLE'                                            AS economic_path_status,            -- 字面取值：本件为元数据，无经济路径（取代已废之「提升业绩幅度」栏）
             'FALSE'                                                     AS admit_to_risk_decision,          -- 字面取值：字典不入风控决策，与 registry 十六对象同为 FALSE 起步
             'DICTIONARY_METADATA'                                       AS deliverable_class                -- 字面取值：交付件类别 —— 元数据，非实体评分
      FROM `information_schema`.`columns` c
      WHERE c.`TABLE_SCHEMA` = 'ods_mariadb_2b'
  ) y
) z
-- ── 逐批 WHERE 阶梯（★ 口诀：上界 ＝ 下界 ＋ 100000，两数同进）──
--    WHERE z.audit_rn >        0 AND z.audit_rn <=   100000   -- 第 1 批
--    某批返回 < 100000 行即为末批，其后不再取。
WHERE z.audit_rn > 0 AND z.audit_rn <= 100000 -- ★ HF9c 本批区间
ORDER BY z.audit_rn;
--     ★ audit_rn 之排序键与分批作业版**逐字同一**（锁一），故两版可逐行对账。

-- ══════════════════════════════════════════════════════════════════════════════════════════════
-- 131. DICT_ALL_tables.csv   [字典补件 · 元数据 · 无六层商业块]
--     典型学：DIC 字典/元数据　粒度：table　说明：全库逐表清单（含引擎统计行数与精确计数探针）
--     ★ 本件循 #078 S03_agent_score 之例，**不套六层商业模板** —— 元数据无实体可分档，
--       施以 NTILE / PERCENT_RANK 即重蹈 D-14 覆辙（相对刻度施于非实体行）。
-- ══════════════════════════════════════════════════════════════════════════════════════════════
-- 【本件立意】口诀 §八字典补件其二。
--   ★ 行数分级须并读：n_rows_engine 出自 INFORMATION_SCHEMA.TABLES.TABLE_ROWS，属**引擎统计**而非 COUNT(*) 实测，
--     故 row_count_grade 恒标 ENGINE_STATISTIC_NOT_EXACT_COUNT；欲得精确基数，请取 probe_sql_exact_count 一栏逐条执行。
--   此栏为**现算生成**之 SQL 字符串（与 #Z06_generated_probe_sql 同治），非人工登记，故可随表清单自动扩张。
-- ── ① T_true：本件行数远小于 100000，一次导全即可；批次阶梯照列以保体例一致 ──
-- ── ② 分批取数：第 1 批。第 k 批只改末行两数为 (k-1)*100000 与 k*100000 ──
SELECT z.*,
       CAST(FLOOR((z.audit_rn - 1) / 100000) + 1 AS INT)          AS batch_id,
       'A168_HF9F_20260827_0900' AS run_id,
       '2026-08-27 09:00:00' AS snapshot_sync_time
FROM (
  SELECT y.*,
         ROW_NUMBER() OVER (ORDER BY y.`table_family`, y.`table_name`) AS audit_rn
  FROM (
      SELECT t.`TABLE_SCHEMA`                                            AS table_schema,                    -- 直取：库名
             t.`TABLE_NAME`                                              AS table_name,                      -- 直取：表名
             t.`TABLE_TYPE`                                              AS table_type,                      -- 直取：表类别
             t.`ENGINE`                                                  AS engine_name,                     -- 直取：引擎
             CAST(k.`n_columns`      AS BIGINT)                          AS n_columns,                       -- 类型转换：列数，由 information_schema.columns 现算聚合而得
             CAST(k.`n_commented`    AS BIGINT)                          AS n_columns_commented,             -- 类型转换：具注释之列数
             ROUND(CAST(k.`n_commented` AS DOUBLE) / NULLIF(CAST(k.`n_columns` AS DOUBLE),0), 6)              AS comment_coverage,                -- 比率表达式：注释覆盖率，NULLIF 防除零（自家铁律）
             CAST(t.`TABLE_ROWS`     AS BIGINT)                          AS n_rows_engine,                   -- 类型转换：引擎统计行数 —— ★ 非 COUNT(*) 实测，分级见 row_count_grade
             CAST(t.`AVG_ROW_LENGTH` AS BIGINT)                          AS avg_row_length,                  -- 类型转换：平均行长
             CAST(t.`DATA_LENGTH`    AS BIGINT)                          AS data_length,                     -- 类型转换：数据长度
             'INFORMATION_SCHEMA.TABLES.TABLE_ROWS'                      AS row_count_source,                -- 字面取值：血统 —— 行数出处
             'ENGINE_STATISTIC_NOT_EXACT_COUNT'                          AS row_count_grade,                 -- 字面取值：★ 证据分级 —— 引擎统计值，非 COUNT(*) 精确实测，不得当作精确基数引用
             CONCAT('SELECT ''', t.`TABLE_NAME`, ''' AS table_name, CAST(COUNT(*) AS BIGINT) AS n_rows_exact FROM `', t.`TABLE_SCHEMA`, '`.`', t.`TABLE_NAME`, '`;')                                  AS probe_sql_exact_count,           -- 现算：逐表精确计数探针 SQL（生成而非硬编码，与 Z06 同治）
             CASE WHEN t.`TABLE_NAME` IN ('ods_a168_bet01','ods_a168_bet02') THEN 'CORE_BET'
                  WHEN t.`TABLE_NAME` LIKE 'ods_a168_member%'              THEN 'MEMBER'
                  WHEN t.`TABLE_NAME` LIKE 'ods_a168_agent%'               THEN 'AGENT'
                  WHEN t.`TABLE_NAME` LIKE '%log%'                         THEN 'LOG'
                  WHEN t.`TABLE_NAME` LIKE '%alert%' OR t.`TABLE_NAME` LIKE '%ip%' THEN 'RISK_CONTROL'
                  ELSE 'OTHER' END                                       AS table_family,                    -- 条件分支：表族归类，供 registry 之 join_key/family 栏承接
             'INFORMATION_SCHEMA.TABLES + COLUMNS'                       AS evidence_source,                 -- 字面取值：血统
             'OBSERVED_METADATA_ENGINE_ESTIMATE_ROWS'                    AS evidence_grade,                  -- 字面取值：证据分级 —— 结构为实测，行数为估计，二者不同级，故并书
             'NOT_APPLICABLE'                                            AS economic_path_status,            -- 字面取值：元数据无经济路径
             'FALSE'                                                     AS admit_to_risk_decision,          -- 字面取值：字典不入风控决策
             'DICTIONARY_METADATA'                                       AS deliverable_class                -- 字面取值：交付件类别
      FROM `information_schema`.`tables` t
      LEFT JOIN (
        SELECT c.`TABLE_SCHEMA` AS s, c.`TABLE_NAME` AS tn,
               COUNT(*)                                                                        AS n_columns,
               SUM(CASE WHEN c.`COLUMN_COMMENT` IS NULL OR TRIM(c.`COLUMN_COMMENT`) = '' THEN 0 ELSE 1 END) AS n_commented
        FROM `information_schema`.`columns` c
        WHERE c.`TABLE_SCHEMA` = 'ods_mariadb_2b'
        GROUP BY c.`TABLE_SCHEMA`, c.`TABLE_NAME`
      ) k ON k.`s` = t.`TABLE_SCHEMA` AND k.`tn` = t.`TABLE_NAME`
      WHERE t.`TABLE_SCHEMA` = 'ods_mariadb_2b'
  ) y
) z
-- ── 逐批 WHERE 阶梯（★ 口诀：上界 ＝ 下界 ＋ 100000，两数同进）──
--    WHERE z.audit_rn >        0 AND z.audit_rn <=   100000   -- 第 1 批
--    某批返回 < 100000 行即为末批，其后不再取。
WHERE z.audit_rn > 0 AND z.audit_rn <= 100000 -- ★ HF9c 本批区间
ORDER BY z.audit_rn;
--     ★ audit_rn 之排序键与分批作业版**逐字同一**（锁一），故两版可逐行对账。

-- ══════════════════════════════════════════════════════════════════════════════════════════════
-- 132. DICT_SEMANTIC_ruling.csv   [字典补件 · 元数据 · 无六层商业块]
--     典型学：DIC 字典/元数据　粒度：column_name　说明：bet01 ↔ bet02 同名列裁决字典（首批入册）
--     ★ 本件循 #078 S03_agent_score 之例，**不套六层商业模板** —— 元数据无实体可分档，
--       施以 NTILE / PERCENT_RANK 即重蹈 D-14 覆辙（相对刻度施于非实体行）。
-- ══════════════════════════════════════════════════════════════════════════════════════════════
-- 【本件立意】口诀 §八字典补件其三 —— 裁决字典，首批入册 bet01 ↔ bet02 二十余条。
--   ★ 三层分离，不得混读：
--     ① 结构层（presence / type_match / comment_match / ord_shift）—— 逐行现算，OBSERVED；
--     ② 裁决层（ruling_verdict）—— 登记文本，其所引数字悉数出自本包交付件，非臆断；
--     ③ 分级层（evidence_grade / evidence_source）—— 四级分级并附出处，可逐条回溯。
--   ★ ord_shift 一栏即「bet14 起整体错位一格」之直接量测：若该假说成立，bet14 及其后各列之 ord_shift 应现出系统性非零。
--   ★ 未裁者一律 R-UNRULED ＋ UNKNOWN，禁以推断填充。
-- ── ① T_true：本件行数远小于 100000，一次导全即可；批次阶梯照列以保体例一致 ──
-- ── ② 分批取数：第 1 批。第 k 批只改末行两数为 (k-1)*100000 与 k*100000 ──
SELECT z.*,
       CAST(FLOOR((z.audit_rn - 1) / 100000) + 1 AS INT)          AS batch_id,
       'A168_HF9F_20260827_0900' AS run_id,
       '2026-08-27 09:00:00' AS snapshot_sync_time
FROM (
  SELECT y.*,
         ROW_NUMBER() OVER (ORDER BY y.`ord_bet01`, y.`ord_bet02`, y.`column_name`) AS audit_rn
  FROM (
      SELECT COALESCE(a.`COLUMN_NAME`, b.`COLUMN_NAME`)                  AS column_name,                     -- 现算：以 bet01 侧为主、bet02 侧补齐之列名
             CASE WHEN a.`COLUMN_NAME` IS NOT NULL AND b.`COLUMN_NAME` IS NOT NULL THEN 'BOTH'
                  WHEN a.`COLUMN_NAME` IS NOT NULL                              THEN 'BET01_ONLY'
                  ELSE 'BET02_ONLY' END                                  AS presence,                        -- 条件分支：两表存在性
             a.`COLUMN_TYPE`                                             AS type_bet01,                      -- 直取：bet01 侧型别
             b.`COLUMN_TYPE`                                             AS type_bet02,                      -- 直取：bet02 侧型别
             a.`COLUMN_COMMENT`                                          AS comment_bet01,                   -- 直取：bet01 侧注释
             b.`COLUMN_COMMENT`                                          AS comment_bet02,                   -- 直取：bet02 侧注释
             CAST(a.`ORDINAL_POSITION` AS BIGINT)                        AS ord_bet01,                       -- 类型转换：bet01 侧列序
             CAST(b.`ORDINAL_POSITION` AS BIGINT)                        AS ord_bet02,                       -- 类型转换：bet02 侧列序
             CAST(b.`ORDINAL_POSITION` AS BIGINT) - CAST(a.`ORDINAL_POSITION` AS BIGINT)                      AS ord_shift,                       -- 现算：★ 列序位移 —— 「bet14 起整体错位一格」之直接量测，非登记值
             CASE WHEN a.`COLUMN_TYPE` IS NULL OR b.`COLUMN_TYPE` IS NULL THEN 'NOT_COMPARABLE'
                  WHEN a.`COLUMN_TYPE` = b.`COLUMN_TYPE`                  THEN 'TYPE_SAME'
                  ELSE 'TYPE_DIVERGENT' END                              AS type_match,                      -- 条件分支：型别是否一致
             CASE WHEN a.`COLUMN_COMMENT` IS NULL OR b.`COLUMN_COMMENT` IS NULL THEN 'NOT_COMPARABLE'
                  WHEN TRIM(a.`COLUMN_COMMENT`) = TRIM(b.`COLUMN_COMMENT`) THEN 'COMMENT_SAME'
                  ELSE 'COMMENT_DIVERGENT' END                           AS comment_match,                   -- 条件分支：注释是否一致 —— 同名异义之首要线索
             CASE COALESCE(a.`COLUMN_NAME`, b.`COLUMN_NAME`)
                  WHEN 'bet01'     THEN 'R-01'  WHEN 'bet02'     THEN 'R-02'  WHEN 'bet03'  THEN 'R-03'
                  WHEN 'bet04'     THEN 'R-04'  WHEN 'bet05'     THEN 'R-05'  WHEN 'bet07'  THEN 'R-07'
                  WHEN 'bet08'     THEN 'R-08'  WHEN 'bet09'     THEN 'R-09'  WHEN 'bet11'  THEN 'R-11'
                  WHEN 'bet13'     THEN 'R-13'  WHEN 'bet14'     THEN 'R-14'  WHEN 'bet16'  THEN 'R-16'
                  WHEN 'bet17'     THEN 'R-17'  WHEN 'bet23'     THEN 'R-23'  WHEN 'bet24'  THEN 'R-24'
                  WHEN 'bet25'     THEN 'R-25'  WHEN 'bet26'     THEN 'R-26'  WHEN 'bet27'  THEN 'R-27'
                  WHEN 'bet38'     THEN 'R-38'  WHEN 'bet39'     THEN 'R-39'  WHEN 'bet41'  THEN 'R-41'
                  WHEN 'validbet'  THEN 'R-VB'  WHEN 'category'  THEN 'R-CAT' WHEN 'commission' THEN 'R-COM'
                  ELSE 'R-UNRULED' END                                   AS ruling_id,                       -- 条件分支：裁决编号 —— 已入册者给号，未裁者标 R-UNRULED
             CASE COALESCE(a.`COLUMN_NAME`, b.`COLUMN_NAME`)
                  WHEN 'bet01'     THEN '注单主键 —— 去重以 PARTITION BY bet01 为准；bet01 身份与 ROW_NUMBER 并列检测（M0-6）尚未补，去重正确性之地基待验'
                  WHEN 'bet02'     THEN '产品码 —— 百家乐口径恒为 101；全包窗内一律 bet02 = ''101'''
                  WHEN 'bet03'     THEN '靴×桌复合键 —— 实测 nd_bet03 = nd_shoe_table，跨桌数为 0'
                  WHEN 'bet04'     THEN '局内序号 —— 实测基数数十、上限百余，非桌号'
                  WHEN 'bet05'     THEN '会员号 —— q 侧谓词 bet05 > 0 之对象；不受 bet14 起错位影响'
                  WHEN 'bet07'     THEN '账期 —— 与分区列 dt 100% 一致；日期切割一律用 dt 字面量'
                  WHEN 'bet08'     THEN '下注时间 —— DATE(bet08) 与 dt 不符率实测 38.60%，禁作日期切割'
                  WHEN 'bet09'     THEN '注型 —— 族别决定庄家优势，注型 edge 向量之分组键'
                  WHEN 'bet11'     THEN '汇率 —— ODS 存原币，金额须乘 bet11 方为折算值'
                  WHEN 'bet13'     THEN '下注额（stake）—— 金额列，varchar 存储，取用须 CAST AS BIGINT'
                  WHEN 'bet14'     THEN '★ 错位根因所在 —— 自本列起 bet01 与 bet02 疑整体位移一格，凡本列之后者语义须逐列复核'
                  WHEN 'bet16'     THEN '退水金额 —— H16 恒等式 bet17 = bet14 − bet13 + bet16 实测 100% 成立'
                  WHEN 'bet17'     THEN '结算后额 —— H16 之左式；H41 以 bet41 代 bet16 仅 7.60% 命中，足证 bet16 与 bet41 语义相异'
                  WHEN 'bet23'     THEN '★ 代理第一级保留率（非占成份额）—— 实测 95~96%，其补数 4~5% 方为成本率；五级之和近 480% 属正常，不构成矛盾'
                  WHEN 'bet24'     THEN '代理第二级保留率 —— 同 bet23 之读法'
                  WHEN 'bet25'     THEN '代理第三级保留率 —— 同 bet23 之读法'
                  WHEN 'bet26'     THEN '代理第四级保留率 —— 同 bet23 之读法'
                  WHEN 'bet27'     THEN '代理第五级保留率 —— 同 bet23 之读法'
                  WHEN 'bet38'     THEN '重对标记 —— 全包窗内取 N'
                  WHEN 'bet39'     THEN '桌号（table_id）—— 实测基数三十，为 round_key 三键之一'
                  WHEN 'bet41'     THEN '★ 与 validbet 逐位相同者 125,653,747 行、相异 964 行、最大差 1,000,000 —— 恒等式须收窄为 CONDITIONAL，非全等'
                  WHEN 'validbet'  THEN '有效投注 —— 与 bet41 同上；零值注单占记录 7.60%、占会员 50.33%，其 mu0 近零，系对冲/免佣之经济指纹'
                  WHEN 'category'  THEN '结算单类别 —— 1 为常态（输赢两向），2 为单向扣款（派彩恒零），二者不可混算'
                  WHEN 'commission' THEN '佣金旗标 —— 相异取值八个；语义 UNKNOWN（F-47 未结），凡涉庄佣之推算一律标 CONDITIONAL'
                  ELSE 'UNRULED —— 尚未入册裁决，禁以推断填充（自家铁律：NULL ≠ 0，UNKNOWN ≠ 已知）' END                                                                                              AS ruling_verdict,                  -- 条件分支：裁决正文 —— 语义为登记文本，其所引数字皆出自本包实测交付件
             CASE COALESCE(a.`COLUMN_NAME`, b.`COLUMN_NAME`)
                  WHEN 'bet16'     THEN 'OBSERVED'   WHEN 'bet17'  THEN 'OBSERVED'   WHEN 'bet41' THEN 'OBSERVED'
                  WHEN 'validbet'  THEN 'OBSERVED'   WHEN 'bet39'  THEN 'OBSERVED'   WHEN 'bet04' THEN 'OBSERVED'
                  WHEN 'bet03'     THEN 'OBSERVED'   WHEN 'bet07'  THEN 'OBSERVED'   WHEN 'bet08' THEN 'OBSERVED'
                  WHEN 'category'  THEN 'OBSERVED'
                  WHEN 'bet23'     THEN 'INFERRED'   WHEN 'bet24'  THEN 'INFERRED'   WHEN 'bet25' THEN 'INFERRED'
                  WHEN 'bet26'     THEN 'INFERRED'   WHEN 'bet27'  THEN 'INFERRED'   WHEN 'bet14' THEN 'INFERRED'
                  WHEN 'bet01'     THEN 'CONDITIONAL' WHEN 'commission' THEN 'UNKNOWN'
                  WHEN 'bet02'     THEN 'OBSERVED'   WHEN 'bet05'  THEN 'OBSERVED'   WHEN 'bet09' THEN 'OBSERVED'
                  WHEN 'bet11'     THEN 'OBSERVED'   WHEN 'bet13'  THEN 'OBSERVED'   WHEN 'bet38' THEN 'OBSERVED'
                  ELSE 'UNKNOWN' END                                     AS evidence_grade,                  -- 条件分支：四级证据分级 OBSERVED / INFERRED / CONDITIONAL / UNKNOWN
             CASE COALESCE(a.`COLUMN_NAME`, b.`COLUMN_NAME`)
                  WHEN 'bet16'     THEN '#P01E_identity_test · #P01A_crosstab'
                  WHEN 'bet17'     THEN '#P01E_identity_test'
                  WHEN 'bet41'     THEN '#VB_41_identity_global · #VB_41c1_964_detail · #VB_41c2_concentration'
                  WHEN 'validbet'  THEN '#VB_00_validbet_contract · #VB_00b_zero_five_rates · #P01D_vs_validbet'
                  WHEN 'bet03'     THEN '#DICT_01b_roundkey_card · #Z08_roundkey_integrity'
                  WHEN 'bet04'     THEN '#DICT_01b_roundkey_card'
                  WHEN 'bet39'     THEN '#DICT_01b_roundkey_card · #Z08_roundkey_integrity'
                  WHEN 'bet07'     THEN '#Z09_time_axis_recon'
                  WHEN 'bet08'     THEN '#Z09_time_axis_recon'
                  WHEN 'category'  THEN '#QSB_01a_category_census'
                  WHEN 'bet23'     THEN '#S03_agent_score · #DICT_01b_roundkey_card · #QSB_02a_lowcard_fields'
                  WHEN 'bet24'     THEN '#S03_agent_score · #QSB_02a_lowcard_fields'
                  WHEN 'bet25'     THEN '#S03_agent_score · #QSB_02a_lowcard_fields'
                  WHEN 'bet26'     THEN '#S03_agent_score · #QSB_02a_lowcard_fields'
                  WHEN 'bet27'     THEN '#S03_agent_score'
                  WHEN 'bet09'     THEN '#QSB_02c_push_by_family · #R03chk_settlement_form'
                  WHEN 'commission' THEN '#QSB_02a_lowcard_fields（仅得基数八，语义未结）'
                  WHEN 'bet14'     THEN '#Z04_name_collision · 本件 ord_shift 现算'
                  ELSE '' END                                            AS evidence_source,                 -- 条件分支：证据出处 —— 逐条指向本包交付件，可回溯
             CASE WHEN COALESCE(a.`COLUMN_NAME`, b.`COLUMN_NAME`) IN ('bet16','bet41','validbet','bet09') THEN 'CANDIDATE'
                  ELSE 'NOT_ESTABLISHED' END                             AS economic_path_status,            -- 条件分支：经济路径状态 PROVEN/CANDIDATE/NOT_ESTABLISHED/NOT_APPLICABLE —— 首批一律不填 PROVEN
             'FALSE'                                                     AS admit_to_risk_decision,          -- 字面取值：字典不入风控决策
             'DICTIONARY_SEMANTIC_RULING'                                AS deliverable_class                -- 字面取值：交付件类别
      FROM        (SELECT * FROM `information_schema`.`columns` WHERE `TABLE_SCHEMA` = 'ods_mariadb_2b' AND `TABLE_NAME` = 'ods_a168_bet01') a
      FULL OUTER JOIN
                  (SELECT * FROM `information_schema`.`columns` WHERE `TABLE_SCHEMA` = 'ods_mariadb_2b' AND `TABLE_NAME` = 'ods_a168_bet02') b
        ON a.`COLUMN_NAME` = b.`COLUMN_NAME`
  ) y
) z
-- ── 逐批 WHERE 阶梯（★ 口诀：上界 ＝ 下界 ＋ 100000，两数同进）──
--    WHERE z.audit_rn >        0 AND z.audit_rn <=   100000   -- 第 1 批
--    某批返回 < 100000 行即为末批，其后不再取。
WHERE z.audit_rn > 0 AND z.audit_rn <= 100000 -- ★ HF9c 本批区间
ORDER BY z.audit_rn;
--     ★ audit_rn 之排序键与分批作业版**逐字同一**（锁一），故两版可逐行对账。

-- ══════════════════════════════════════════════════════════════════════════════════════════════
-- 133. RK01_round_fact.csv   [局级事实表 · 新建 · 无六层商业块]
--     典型学：ROUND 局键事实　粒度：round_key = bet03|bet04|bet39　说明：同局共现之唯一事实地基
--     ★ 本件循 #078 S03_agent_score / #132 DICT_SEMANTIC_ruling 之例，**不套六层商业模板** ——
--       「局」非可处置实体（不可限红、不可冻结、不可给退水），施以 NTILE / PERCENT_RANK
--       即重蹈 D-14 覆辙（相对刻度施于非实体行）。局之赏罚一律回落至会员／荷官／桌台三实体。
--     ★ 2026-09-03 校对斧正（三版同步，以 DICT_ALL_columns.csv 与本包正典逐栏核对）：
--       ① 测试线 CTE 原书 agent_id／is_test 二栏，于 ods_a168_agent（51 栏）皆不存在 ⇒ 改正典 age001／age022='1'（与 x_testagent 同）；
--       ② 荷官栏原取 bet06，字典注「開局時間」（datetime）⇒ 改 eid（字典注「荷官」，正典 x_bs0 之 x_dealer）；
--       ③ validbet 缺者回落 bet13（承 ord 层 COALESCE(vb_raw, stake_raw)）；
--       ④ 闸门去 bet13>0（正典无）、补 bet05>0（正典有），六锁自此与 round_key 族逐字同一；
--       ⑤ ggr 系【庄家视角】= (bet13 − bet14)/bet11 = −game_pnl（本包 game_pnl 为会员视角 payout−stake），hold_pct 为洗码口径。
--     ★ 2026-09-03 第二轮斧正（承先生「须依原本 132 件」之训）：
--       ⑥ 去重排序键原书 ORDER BY sync_time DESC 单键——全档 139 处正典皆为
--          ORDER BY updatetime DESC, sync_time DESC, dt DESC 三键；单键遇并列即不确定 ⇒ 已归正典。
--       ⑦ 「6,048,725」原注为「口诀已实测」，实出 #014 DICT_01b_roundkey_card.csv 之落盘实测，
--          且其口径只四锁 ⇒ 本件六锁之 T_true 必 ≤ 之，已由「约等于」改「上界」。
--       ⑧ 分批数系由上界推得，已标为上界，待探针 §1 实测回填。
--     ★ 2026-09-03 第三轮斧正（承平行会话之校对，经本地逐项实测复核；采其实、正其数）：
--       ⑨ 注释同步补齐五处：L76 立约条 · §Z 执行顺序 · 等价性依据 · 二元锚二处，皆 132 → 133。
--          ⛔ 另二处刻意不改，系【历史记载】：E1 段「同段『第 129 件』→『第 132 件』」与「改动清单
--          （132 件 × 2 行）」——记述 OPT 那一轮之改动范围，改之即篡改变更史。
--       ⑩ 【登记册 OQ-13 · 可复现性 S1】测试线名册**不受快照锁**：全档 177 处取 ods_a168_agent，
--          无一处带 sync_time 条件；而 bet02 侧恒锁 sync_time <= '2026-08-27 09:00:00'。
--          ⇒ 名册随时间漂移，同一 SQL 于不同日跑出不同剔除集。实测佐证：包内七处 ta 注记书
--          「公司测试线代理（214 条，跨五级）」，而 2026-09-03 实跑探针 §0 得 **215**（+1）。
--          ⛔ 本件不擅改他模块之 214 注记（属他人模块之注记，另案）；此处只登记根因与佐证。
--          【待裁】是否为 ta CTE 补快照锁（如 age_sync_time <= 快照，若该表有此栏），或改取
--          冻结名册 CSV，使跑批可复现。未裁前，跨日重跑之剔除集差异属预期，非缺陷。
--          ★ 2026-09-03 编号更正：本条原书临时编号「RC-01」，因其无 SSOT 地位、且与既有 H 轴源系统码
--            H-SRC-01（支付／资金，自 v11 沿用并已入两份交付件）字串冲突——全库 78 档含该字串，76 档
--            实为 H-SRC-01，误中率约 97%——已退场，改登 registry v1.5.004 之 open_questions **OQ-13**。
--       ⑪ 【登记册 OQ-14 · 口径分歧 S2】本件测试线连接双侧 CAST 至 BIGINT（承本件头注之 ID 铁律），
--          而包内正典（x_testagent 与 ta 两族）皆以 varchar 直比（t1.aid = r.bet18，无 CAST）。
--          二者于前导零、空白之处置不同 ⇒ 剔除集可能相异。包内铁律与包内正典自相矛盾，须裁其一：
--          （甲）本件从正典去 CAST，与 132 件同源；（乙）正典向本件看齐补 CAST，属跨 132 件之大改。
--          实测：本件六锁下测试线剔 11,737 行、0 局（探针 §2 L3→L4）。未裁前此数以 CAST 版为准。
--          ★ 2026-09-03 编号更正：本条原书临时编号「CD-01」，无 SSOT 地位，已退场，改登 registry
--            v1.5.004 之 open_questions **OQ-14**。二号之退场登记见 id_namespace_registry。
--       ⑫ 【n_member_pairs 之使用契约 · 重要】本件之 n_member_pairs = C(n_members, 2) 系【对-局次】，
--          **非**唯一会员对数——同一对会员可跨多局反复共现。故 T-01 显著性检定须另分：
--             n_pair_occurrences（对-局次，全窗 Σ = 1,181,326,647 · 2026-09-03 实测）
--             n_unique_member_pairs（唯一对数，须自本件再聚合一层至会员对级，非本件粒度）
--          ⛔ 以对-局次充唯一对数，会因重复共局而严重放大显著性。
--          ⛔ 且**均匀随机零模型已证不可用**：C(723,442, 2) = 261,683,801,961 全体可能对，
--          均匀假设下每对期望共现 1,181,326,647 / 261,683,801,961 = 0.004514 次 ⇒ 同局 5 次即得
--          lift = 1,108×，荒谬。根因：实测每局人数 P50 = 11、≥10 人局占 57.05%、多方局占 96.95%
--          （探针 §3）⇒ 过半牌局逾十人同局，「两人同局 N 次」本身几无信息量。
--          ⇒ 正解为 configuration model：按各会员自身局数加权，并按【桌 × 靴】分层（同桌同靴非独立）。
-- ══════════════════════════════════════════════════════════════════════════════════════════════
-- 【本件立意】填补一项结构空白：round_key 已证为【真同局键】（跨桌局键 0 · 单局最大会员 256 ·
--   P999 = 93.2 —— 二者出 #118 Z08_roundkey_integrity.csv 之落盘实测），却在既有 132 件中**无一以其为主键**。
--   而 T-01 同桌聚集 / T-04 跨账户对打 / T-05 自我对冲 三类之核心证据皆为「同局共现」，
--   其零模型（共现基率）无处可算 ⇒ 三类之统计显著性至今无从判定。
--   ★ 本件只出【事实】，不出【判定】：无旗标、无分档、无 action，一切下游自行现算。
--
-- 【口径六锁 · 与全包逐字同一，勿改】
--   ① 窗口   dt >= '2026-03-21' AND dt < '2026-08-07'（139 营运日；dt 系账务日，Z09 已证 100%）
--   ② 产品   bet02 = '101'（百家乐）
--   ③ 快照   sync_time <= '2026-08-27 09:00:00'
--   ④ 去重   PARTITION BY bet01 ORDER BY updatetime DESC, sync_time DESC, dt DESC 取 rn = 1
--   ⑤ 基础闸 category = '1' · UPPER(bet38) = 'N' · 非测试线（五级代理左连取 NULL）
--            · bet05 > 0（会员号为正）· bet11 > 0（汇率为正）
--   ⑥ 归一   一切金额除以 bet11（汇率），与本包 round_key 族 ord 层（#075 S01 之 x_bs0 同）逐字同法
--
-- 【禁令遵循】
--   · P-07 禁 OFFSET —— 本件用 audit_rn 键集分批，非 OFFSET
--   · P-08 禁以 DATE(bet08) 切日 —— 本件一律用 dt（账务日）
--   · 只用行注释，无块注释（分号／斜线在块注释内会被误判为语句终止）
--   · 一切 ID 比较 CAST 至 BIGINT（全库 ID 存为 varchar(65533)）
--   · 一切除法以 NULLIF 护零；NULL ≠ 0，未观测者留 NULL 不写 0
--
-- 【规模 · 2026-09-03 实测回填】T_true ＝ **6,048,562 行**（非估非推，系实跑回值）。
--   实测源：《函数/RK01_行数实测探针_v2_0_1.sql》§1，2026-09-03 于 StarRocks 全窗六锁实跑，耗时 10.685 秒。
--   ┌ t_true_rows = 6,048,562 ＝ nd_round_key = 6,048,562（判读一 PASS：主键唯一，无 TRIM 口径分歧）
--   ├ n_bets_total = 124,713,543 ｜ 每局均注 20.6187 ｜ 每局均人 15.1447
--   ├ nd_table = 30（合 #014 之 nd_bet39 = 30）｜ nd_table_shoe = 123,357（≤ #014 之 123,359）
--   ├ nd_biz_date = 139 ｜ min 2026-03-21 ｜ max 2026-08-06（合窗内营运日数）
--   └ 多方局 5,863,816（96.95%）｜ **n_member_pairs_total = 1,181,326,647**（共现零模型之分母基数，首次实测）
--   【与上界之关系】#014 DICT_01b_roundkey_card.csv 四锁局键数 6,048,725 系上界；本件六锁实测 6,048,562，
--   低 163 局（99.9973%），符「必 ≤ 上界」之判读二。
--   【163 局之归因 · 由探针 §2 有锚阶梯逐闸给出】
--     L0 窗口+产品+快照        125,654,711 行 ／ 6,048,790 局
--     L1 ＋category='1'        125,649,147 行 ／ 6,048,725 局   ← ★ 与 #014 落盘数**逐位相等**（锚合）
--     L2 ＋去重 rn=1           124,726,293 行 ／ 6,048,725 局   ← 剔 922,854 行、**0 局**（预判「去重不减局」成立）
--     L3 ＋bet38='N'           124,725,280 行 ／ 6,048,562 局   ← 剔 1,013 行、**163 局**（163 局之唯一来源）
--     L4 ＋剔测试线             124,713,543 行 ／ 6,048,562 局   ← 剔 11,737 行、0 局
--     L5 ＋bet05>0             124,713,543 行 ／ 6,048,562 局   ← 剔 0 行、0 局（★ 空闸，见下）
--     L6 ＋bet11>0             124,713,543 行 ／ 6,048,562 局   ← 剔 0 行、0 局（★ 空闸，见下）
--   ★ **VACUOUS_FILTER 登记**：bet05>0 与 bet11>0 二闸于本窗剔 0 行——非「无用」而系「无对象」，
--     属恒真闸。存之以防日后脏数据渗入（防御性闸），然**不得**据其「已过闸」宣称数据洁净：
--     空集上之通过等于未检（承 R24b 之 VACUOUS_ASSURANCE 同理）。
--   ★ category 之写法：#014 用 TRIM(category)='1'、本件用 category='1'，实测两者所选母体**逐位相同**
--     （125,649,147 = 125,649,147）⇒ category 栏无前后空白，两写法此窗内等价。
--   【不可混引】#118 Z08_roundkey_integrity.csv 之局键数 6,919,057 系【二锁】（bet02＋快照，**无 dt 窗口**，
--   注单 143,085,880 行），含窗外历史，与本件口径最远，引用时须随附口径标注。
--   ROW_NUMBER() 全局排序系 blocking 算子，须全量物化后方生效，LIMIT 不能提前截断（D-14 案同理）。
--   原版审计版一次导全者，须确认 query_mem_limit 足量；否则改走分批作业版。
--
-- 【经济用途 —— 本件之所以值得建】
--   ① 零模型地基：共现基率 = f(每局人数分布)。无此分布，「两人同局 N 次」之显著性不可判，
--      T-01/T-04/T-05 三类之一切 lift / jaccard 皆缺分母 ⇒ 现状是有分子无分母。
--   ② 局级 hold 之离散：桌×靴×局三层方差分解之输入。S02b 双峰已证「桌台解释 95.9%、
--      荷官仅 69.1%」，但那是【局速】；局级 hold 之方差归属至今未测。
--   ③ 靴内位置效应：round_seq 与 hold 之关系（T-03 尾投已 FATAL 证伪，但那是【会员行为】，
--      本件测的是【牌局本身】，二者不同问，不受 T-03 禁令约束）。
--   ★ 以上三项皆为【可算而未算】，非【已证有效】。本件只提供地基，不承诺增益。
-- ── 分批作业版：每批 100,000 行 ＋ audit_rn ＋ batch_id ──
-- ── ① T_true ＝ **6,048,562 行**（2026-09-03 实测回填；探针 v2.0.0 §1 全窗六锁实跑）。
--      ⇒ 共 **61 批**，末批 **48,562 行**（前 60 批各 100,000 行）。
--      本批实际返回行数 < 100000 即判定为末批；末批行数须为 48,562，不符即须查。
-- ── ② 分批取数：第 1 批。第 k 批只改末行两数为 (k-1)*100000 与 k*100000 ──
--      审计字段二（四锁）：audit_rn 全局观测坐标（排序键与原版逐字同一，两版可逐行对账）；
--      batch_id 物理分批信息（由 audit_rn 算得，非引擎所赋）。
--      ★ 锁三：二者皆为审计字段，不得进入任何业务指标计算。
--      ★ 锁四：两版经 audit_rn 逐行字段核验后，方可宣布输出完全一致。
SELECT z.*,
       CAST(FLOOR((z.audit_rn - 1) / 100000) + 1 AS INT) AS batch_id
FROM (
SELECT w.*,
       ROW_NUMBER() OVER (ORDER BY w.`biz_date`, w.`table_id`, w.`shoe_key`, w.`round_seq`, w.`round_key`) AS audit_rn,
       'A168_HF9F_20260827_0900' AS run_id,
       '2026-08-27 09:00:00' AS snapshot_sync_time
FROM (
    WITH ta AS (
      SELECT DISTINCT CAST(NULLIF(TRIM(age001), '') AS BIGINT) AS aid
      FROM ods_mariadb_2b.ods_a168_agent
      WHERE age022 = '1'
    ),
    rk AS (
      SELECT b.*,
             ROW_NUMBER() OVER (
               PARTITION BY b.bet01
               ORDER BY b.updatetime DESC, b.sync_time DESC, b.dt DESC)                AS rn
      FROM ods_mariadb_2b.ods_a168_bet02 b
      WHERE b.dt >= '2026-03-21' AND b.dt < '2026-08-07'
        AND b.bet02 = '101'
        AND b.sync_time <= '2026-08-27 09:00:00'
    ),
    base AS (
      SELECT CONCAT_WS('|', TRIM(r.bet03), TRIM(r.bet04), TRIM(r.bet39))        AS round_key,
             TRIM(r.bet39)                                                      AS table_id,
             TRIM(r.bet03)                                                      AS shoe_key,
             TRIM(r.bet04)                                                      AS round_seq,
             r.dt                                                               AS biz_date,
             CAST(NULLIF(TRIM(r.bet05), '') AS BIGINT)                          AS member_id,
             TRIM(r.eid)                                                        AS dealer_id,
             TRIM(r.bet09)                                                      AS bet_family,
             CAST(NULLIF(TRIM(r.bet13), '') AS DECIMAL(20,8))
               / NULLIF(CAST(NULLIF(TRIM(r.bet11), '') AS DECIMAL(20,8)), 0)    AS stake,
             COALESCE(CAST(NULLIF(TRIM(r.validbet), '') AS DECIMAL(20,8)),
                      CAST(NULLIF(TRIM(r.bet13), '') AS DECIMAL(20,8)))
               / NULLIF(CAST(NULLIF(TRIM(r.bet11), '') AS DECIMAL(20,8)), 0)    AS vbet,
             (CAST(NULLIF(TRIM(r.bet13), '') AS DECIMAL(20,8))
            - CAST(NULLIF(TRIM(r.bet14), '') AS DECIMAL(20,8)))
               / NULLIF(CAST(NULLIF(TRIM(r.bet11), '') AS DECIMAL(20,8)), 0)    AS ggr,
             CAST(NULLIF(TRIM(r.bet16), '') AS DECIMAL(20,8))
               / NULLIF(CAST(NULLIF(TRIM(r.bet11), '') AS DECIMAL(20,8)), 0)    AS rebate
      FROM rk r
      LEFT JOIN ta t1 ON t1.aid = CAST(NULLIF(TRIM(r.bet18), '') AS BIGINT)
      LEFT JOIN ta t2 ON t2.aid = CAST(NULLIF(TRIM(r.bet19), '') AS BIGINT)
      LEFT JOIN ta t3 ON t3.aid = CAST(NULLIF(TRIM(r.bet20), '') AS BIGINT)
      LEFT JOIN ta t4 ON t4.aid = CAST(NULLIF(TRIM(r.bet21), '') AS BIGINT)
      LEFT JOIN ta t5 ON t5.aid = CAST(NULLIF(TRIM(r.bet22), '') AS BIGINT)
      WHERE r.rn = 1
        AND r.category = '1'
        AND UPPER(TRIM(r.bet38)) = 'N'
        AND COALESCE(t1.aid, t2.aid, t3.aid, t4.aid, t5.aid) IS NULL
        AND CAST(NULLIF(TRIM(r.bet05), '') AS BIGINT) > 0
        AND CAST(NULLIF(TRIM(r.bet11), '') AS DECIMAL(20,8)) > 0
    )
    SELECT b.round_key,
           b.table_id,
           b.shoe_key,
           b.round_seq,
           MIN(b.biz_date)                                                      AS biz_date,
           COUNT(DISTINCT b.dealer_id)                                          AS n_dealer_id,
           MIN(b.dealer_id)                                                     AS dealer_id_min,
           COUNT(DISTINCT b.member_id)                                          AS n_members,
           COUNT(*)                                                             AS n_bets,
           COUNT(DISTINCT b.bet_family)                                         AS n_bet_family,
           ROUND(SUM(b.stake), 4)                                               AS stake,
           ROUND(SUM(b.vbet), 4)                                                AS validbet,
           ROUND(SUM(b.ggr), 4)                                                 AS ggr,
           ROUND(SUM(b.rebate), 4)                                              AS rebate,
           ROUND(SUM(b.ggr) * 100.0 / NULLIF(SUM(b.vbet), 0), 6)                AS hold_pct,
           ROUND(SUM(b.stake) / NULLIF(COUNT(*), 0), 4)                         AS stake_per_bet,
           ROUND(SUM(b.stake) / NULLIF(COUNT(DISTINCT b.member_id), 0), 4)      AS stake_per_member,
           ROUND(COUNT(*) * 1.0 / NULLIF(COUNT(DISTINCT b.member_id), 0), 4)    AS bets_per_member,
           SUM(CASE WHEN b.vbet = 0 THEN 1 ELSE 0 END)                          AS n_zero_validbet,
           CASE WHEN COUNT(DISTINCT b.member_id) >= 2 THEN 1 ELSE 0 END         AS is_multiparty,
           CAST(COUNT(DISTINCT b.member_id) * (COUNT(DISTINCT b.member_id) - 1) / 2 AS BIGINT)
                                                                                AS n_member_pairs
    FROM base b
    GROUP BY b.round_key, b.table_id, b.shoe_key, b.round_seq
) w
) z
WHERE z.audit_rn >        0 AND z.audit_rn <= 100000   -- 第 1 批
ORDER BY z.audit_rn;
--     ★ audit_rn 之排序键与分批作业版**逐字同一**（锁一），故两版可逐行对账。
--     ★ n_member_pairs 系【零模型之分子基数】：全窗 Σ n_member_pairs 即同局共现之总对次，
--       T-01 之 lift 分母应由此现算，而非以「两两皆可能同局」之均匀假设充数。
--     ★ n_dealer_id > 1 者须查：同一局键若出现多个荷官，或系桌台字段污染，或系换班切局，
--       与 G3 十三张桌（900~913）之疑似电子桌占位标识同属待裁项。
--       【2026-09-03 实测】6,048,562 局中：单荷官 6,041,849 局（99.889%）· **多荷官 6,713 局（0.111%）**
--       · 荷官为空 0 局 · 单局最多荷官数 3。⇒ 现象确存且量小，非普遍污染；
--       须逐局取样查其 eid 与开局时间（bet06）之关系，以辨『换班切局』抑或『字段污染』——
--       未辨明前，本件 dealer_id_min 一栏**不得**用作荷官归属之唯一依据（承 P-17：无阈值不出判定）。
--       【形态实测 · 每局会员数】P50 = 11 · P90 = 32 · P99 = 63 · P999 = 94 · 最大 256；
--       单局最多注单 414。独玩局 184,746（3.05%）· 2~4 人 903,091 · 5~9 人 1,509,720 · ≥10 人 3,451,005（57.05%）。
--       ★ 最大值 256 与 414 与 #118 Z08 逐位相同 —— 该二极值之持有局落于窗内，故二口径同值。

-- 134. HE01_bet_side_edge.csv   [投注面级已实现优势表 · 新建 · 无六层商业块]
--     典型学：BET_SIDE 已实现优势　粒度：bet_side × is_freecomm　说明：realized 口径之投注面事实地基
--     ★ 本件循 #078 S03_agent_score / #130~#132 字典三件 / #133 RK01 局级事实表之例，**不套六层商业模板** ——
--       「投注面」非可处置实体（不可限红、不可冻结、不可给退水），施以 NTILE / PERCENT_RANK
--       即重蹈 D-14 覆辙（相对刻度施于非实体行）。投注面之赏罚一律回落至会员／荷官／桌台三实体。
-- ══════════════════════════════════════════════════════════════════════════════════════════════
-- 【命名双轨 · KILLCRITIC-01 · 本件之第一铁律】
--   ⛔ 本件所出者一律为 **realized（已实现，含运气）**，正名 hold_valid_bet ／ hold_rate。
--   ⛔ `house_edge` 一名**永久保留予【理论】优势**，本件绝不产出该名，亦不得被引为理论 edge。
--      理论 edge 现状 NULL：授权未下，且 #017 探针 R3 实测 overdispersion Q/(k−1) = 9.3~42.6，
--      单一常数 edge 架构已 KILL —— 纵获授权，亦不得以静态单值映射。
--   ⛔ 已实现 ≠ 理论期望。混称即污染 theo → ADT → NMPT → ESI 全链。
--
-- 【本件立意】填补第二项结构空白：既有 133 件中，**无一以 bet09（投注面）为主键**。
--   而「免佣桌可否与一般桌共用一个 edge」「未知产品之 theo 该不该 NULL」「逐面证据够不够」
--   三问皆需投注面级事实为地基，现状是**有会员级 hold 而无投注面级 hold**。
--   ★ 本件只出【事实】，不出【判定】：无旗标分档、无 action、无相对排名，一切下游自行现算。
--   ★ 粒度取 bet_side × is_freecomm（较 HE-01 探针之 bet_side 单键更细）——
--     按 is_freecomm 上卷即得 HE-01 之 23 行视图，故【只增不减】，无一信息丢失。
--
-- 【口径六锁 · 与全包逐字同一，勿改】
--   ① 窗口   dt >= '2026-03-21' AND dt < '2026-08-07'
--   ② 产品   bet02 = '101'（百家乐）
--   ③ 快照   sync_time <= '2026-08-27 09:00:00'
--   ④ 去重   PARTITION BY bet01 ORDER BY updatetime DESC, sync_time DESC, dt DESC 取 rn = 1
--   ⑤ 基础闸 category = '1' · UPPER(bet38) = 'N' · 非测试线（五级代理左连取 NULL）
--            · bet05 > 0（会员号为正）· bet11 > 0（汇率为正）
--   ⑥ 归一   一切金额除以 bet11（汇率），与本包 round_key 族 ord 层逐字同法
--
-- 【二口径并出 · 与 #133 之差异须知】
--   · profit ＝ −bet17 / bet11  —— ★ 六层块正典之 profit（`profit = -e.net`），本件以之为主口径。
--   · ggr    ＝ (bet13 − bet14) / bet11 —— 与 #133 RK01 之 ggr 逐字同式（牌桌毛赢，庄家视角）。
--   ⇒ 二者并出，令「牌桌毛赢」与「会员净输赢之负」之差可就地对账，⛔ 不以其一冒充其一。
--
-- 【加权双口径 · 循 #075 之 p_base_round_w／p_base_round_unw 先例（2026-08-11 增，供两种 estimand 对照）】
--   · company_pct_unw ＝ AVG(bet23)                         —— 逐注**等权**（与六层块 194 处 AVG 同式）
--   · company_pct_w   ＝ Σ(bet23 × valid_bet) / Σ valid_bet —— **暴露加权**
--   · rebate_pct_unw / rebate_pct_w 同理（bet15）
--   ⛔ 二者系两个 estimand，非两种精度；**并列出示，禁替换**。
--   · ess_valid_bet ＝ (Σw)² / Σw²（w = valid_bet），ess_ratio ＝ ESS ÷ n_orders
--     ⇒ ESS ≪ n 即证「加权后信息已压缩到极少数注单」；⛔ 禁以 n 大冒充证据强。
--
-- 【规模 · 2026-09-03 实测回填（非估非推，系 Superset／StarRocks 实跑回值）】
--   T_true ＝ **39 行**（bet_side × is_freecomm；HE-02 探针实跑 8.242 秒回值）。
--   按 is_freecomm 上卷 ＝ 23 行（HE-01 探针实跑 9.600 秒回值），其中
--     evidence_flag = 'OK' 16 面 ／ 'NO_EVIDENCE' 7 面（各 1 注、10 元、零盈亏）。
--   全体对账：Σn_orders 124,713,543（与 #133 RK01 之 n_bets_total 逐位相等）
--     ｜ Σstake 13,436,093,473.3334 ｜ Σvalid_bet 12,101,545,164.6446 ｜ Σprofit 225,932,201.2126
--     ｜ hold_valid_bet 1.86696986 % ｜ hold_rate 1.68153192 % ｜ valid/stake 90.06743804 %
--   ⇒ 三路互证闭合：本件 ↔ 审计/实测庄家优势_逐投注面_v1.0.0_20260903.csv ↔ #075 S01_player_score
--     （723,442 会员，1.866970 % ／ 1.681532 % ／ 90.067438 %）。逐面金额差 ≤ 0.0050（分币级舍入）。
--   ⇒ 覆盖率闸（HE-03 实跑 7.484 秒）：未过证据门者 7 注 / 洗码 70 元，mapped_coverage_rate = 0.99999999。
--
-- 【已测得之结构事实（供下游引用，⛔ 本件不据此出判定）】
--   ① 洗码折扣只落在 6 面（valid_over_stake < 1）：Banker 0.89588406 · Player 0.89817489 ·
--      BankerDragonBonus 0.98199111 · PlayerDragonBonus 0.98239240 · BankerNatural 0.98334541 ·
--      PlayerNatural 0.97884579；此 6 面占全体洗码 96.0560 %。其余 17 面 valid_over_stake = 1。
--      ⇒ 「对本金」与「对洗码」两分母之 9.93 个百分点落差，几乎全由 Banker／Player 二面所致。
--   ② 免佣 vs 一般之两样本 z 检定（HE-05 实跑 7.824 秒）：16 面中 **5 面** DIFFERENT_AT_5PCT ——
--      PPair z = 7.5623（比 1.429）· AnyPair z = 5.8186（1.733）· PlayerDragonBonus z = −5.0674（0.231）·
--      BankerDragonBonus z = 2.7392（1.266）· PlayerNatural z = −2.5712（0.728）。
--      ⛔ 而主力二面 **Banker z = 0.1991、Player z = −1.2296 皆 NOT_DISTINGUISHED**。
--      ⇒ 定谳：bet09 一元对主力面（占洗码 96%）**足以**定 realized edge；对 5 个边注面**不足**，
--        且方向不一（有升有降），故非「免佣一律使 edge 上升」之单向规律。
--      ⛔ 纵用 (bet09, is_freecomm) 二元亦只是分层常数 —— #017 R3 之 overdispersion 已否决单一常数架构。
--   ③ 免佣占比之两口径差（HE-06 实跑 8.038 秒）：等权（占注单数）恒低于暴露加权（占洗码）——
--      Banker 0.088967 → 0.132838（+49.3%）· Player 0.077263 → 0.118313（+53.1%）·
--      Lucky7 0.068401 → 0.137614（+101.2%）· PerfectPair 0.095716 → 0.175967（+83.8%）。
--      ⇒ **免佣注单之注额系统性大于一般注单**；凡以 free_comm_rate 为判据者，两口径可差逾一倍。
--   ④ 公司自留比例之两口径差极小：主力面 |gap| ≤ 0.13 个百分点（Banker 96.005899 → 95.876407）；
--      唯 Small 面 gap = −1.016558 为最大。⇒ 该栏加权收益甚微，登记以备，不主张替换。
--
-- 【禁令遵循】
--   · P-07 禁 OFFSET —— 本件用 audit_rn 键集分批，非 OFFSET
--   · P-08 禁以 DATE(bet08) 切日 —— 本件一律用 dt（账务日）
--   · 只用行注释，无块注释；一切 ID 比较 CAST 至 BIGINT；一切除法以 NULLIF 护零
--   · NULL ≠ 0，未观测者留 NULL 不写 0
-- ▸ 导出：需要 —— 存为「数据库/HE01_bet_side_edge.csv」
-- ── 分批作业版：每批 100,000 行 ＋ audit_rn ＋ batch_id ──
-- ── ① T_true ＝ **39 行**（2026-09-03 实测回填）⇒ 共 **1 批**，末批 **39 行**。
-- ── ② 分批取数：第 1 批。第 k 批只改末行两数为 (k-1)*100000 与 k*100000 ──
--      审计字段二（四锁）：audit_rn 全局观测坐标（排序键与原版逐字同一，两版可逐行对账）；
--      batch_id 物理分批信息（由 audit_rn 算得，非引擎所赋）。
--      ★ 锁三：二者皆为审计字段，不得进入任何业务指标计算。
--      ★ 锁四：两版经 audit_rn 逐行字段核验后，方可宣布输出完全一致。
SELECT z.*,
       CAST(FLOOR((z.audit_rn - 1) / 100000) + 1 AS INT) AS batch_id
FROM (
SELECT w.*,
       ROW_NUMBER() OVER (ORDER BY w.`valid_bet` DESC, w.`bet_side`, w.`is_freecomm`) AS audit_rn,
       'A168_HF9F_20260827_0900' AS run_id,
       '2026-08-27 09:00:00' AS snapshot_sync_time
FROM (
    WITH ta AS (
      SELECT DISTINCT CAST(NULLIF(TRIM(age001), '') AS BIGINT) AS aid
      FROM ods_mariadb_2b.ods_a168_agent
      WHERE age022 = '1'
    ),
    rk AS (
      SELECT b.*,
             ROW_NUMBER() OVER (
               PARTITION BY b.bet01
               ORDER BY b.updatetime DESC, b.sync_time DESC, b.dt DESC)                AS rn
      FROM ods_mariadb_2b.ods_a168_bet02 b
      WHERE b.dt >= '2026-03-21' AND b.dt < '2026-08-07'
        AND b.bet02 = '101'
        AND b.sync_time <= '2026-08-27 09:00:00'
    ),
    base AS (
      SELECT TRIM(r.bet09)                                                      AS bet_side,
             CASE WHEN TRIM(r.commission) = '1' THEN 1 ELSE 0 END               AS is_freecomm,
             CAST(NULLIF(TRIM(r.bet05), '') AS BIGINT)                          AS member_id,
             TRIM(r.bet39)                                                      AS table_id,
             CAST(NULLIF(TRIM(r.bet13), '') AS DECIMAL(20,8))
               / NULLIF(CAST(NULLIF(TRIM(r.bet11), '') AS DECIMAL(20,8)), 0)    AS stake,
             COALESCE(CAST(NULLIF(TRIM(r.validbet), '') AS DECIMAL(20,8)),
                      CAST(NULLIF(TRIM(r.bet13), '') AS DECIMAL(20,8)))
               / NULLIF(CAST(NULLIF(TRIM(r.bet11), '') AS DECIMAL(20,8)), 0)    AS vbet,
             -CAST(NULLIF(TRIM(r.bet17), '') AS DECIMAL(20,8))
               / NULLIF(CAST(NULLIF(TRIM(r.bet11), '') AS DECIMAL(20,8)), 0)    AS profit,
             (CAST(NULLIF(TRIM(r.bet13), '') AS DECIMAL(20,8))
            - CAST(NULLIF(TRIM(r.bet14), '') AS DECIMAL(20,8)))
               / NULLIF(CAST(NULLIF(TRIM(r.bet11), '') AS DECIMAL(20,8)), 0)    AS ggr,
             CAST(NULLIF(TRIM(r.bet16), '') AS DECIMAL(20,8))
               / NULLIF(CAST(NULLIF(TRIM(r.bet11), '') AS DECIMAL(20,8)), 0)    AS rebate,
             CAST(NULLIF(TRIM(r.bet15), '') AS DECIMAL(20,6))                   AS rebate_pct,
             COALESCE(CAST(NULLIF(TRIM(r.bet23), '') AS DECIMAL(20,6)), 0)      AS company_pct
      FROM rk r
      LEFT JOIN ta t1 ON t1.aid = CAST(NULLIF(TRIM(r.bet18), '') AS BIGINT)
      LEFT JOIN ta t2 ON t2.aid = CAST(NULLIF(TRIM(r.bet19), '') AS BIGINT)
      LEFT JOIN ta t3 ON t3.aid = CAST(NULLIF(TRIM(r.bet20), '') AS BIGINT)
      LEFT JOIN ta t4 ON t4.aid = CAST(NULLIF(TRIM(r.bet21), '') AS BIGINT)
      LEFT JOIN ta t5 ON t5.aid = CAST(NULLIF(TRIM(r.bet22), '') AS BIGINT)
      WHERE r.rn = 1
        AND r.category = '1'
        AND UPPER(TRIM(r.bet38)) = 'N'
        AND COALESCE(t1.aid, t2.aid, t3.aid, t4.aid, t5.aid) IS NULL
        AND CAST(NULLIF(TRIM(r.bet05), '') AS BIGINT) > 0
        AND CAST(NULLIF(TRIM(r.bet11), '') AS DECIMAL(20,8)) > 0
    )
    SELECT b.bet_side,
           b.is_freecomm,
           COUNT(*)                                                             AS n_orders,
           COUNT(DISTINCT b.member_id)                                          AS n_member,
           COUNT(DISTINCT b.table_id)                                           AS n_table,
           ROUND(SUM(b.stake), 4)                                               AS stake,
           ROUND(SUM(b.vbet), 4)                                                AS valid_bet,
           ROUND(SUM(b.profit), 4)                                              AS profit,
           ROUND(SUM(b.ggr), 4)                                                 AS ggr,
           ROUND(SUM(b.rebate), 4)                                              AS rebate_cost,
           ROUND(SUM(b.profit) / NULLIF(SUM(b.vbet), 0), 8)                     AS hold_valid_bet,
           ROUND(SUM(b.profit) / NULLIF(SUM(b.stake), 0), 8)                    AS hold_rate,
           ROUND(SUM(b.vbet) / NULLIF(SUM(b.stake), 0), 8)                      AS valid_over_stake,
           ROUND(1.959964 * STDDEV_SAMP(b.profit / NULLIF(b.vbet, 0))
                 / NULLIF(SQRT(COUNT(*)), 0), 8)                                AS ci95_halfwidth_crude,
           ROUND(POW(SUM(b.vbet), 2) / NULLIF(SUM(b.vbet * b.vbet), 0), 1)      AS ess_valid_bet,
           ROUND(POW(SUM(b.vbet), 2) / NULLIF(SUM(b.vbet * b.vbet), 0)
                 / NULLIF(COUNT(*), 0), 8)                                      AS ess_ratio,
           ROUND(AVG(b.company_pct), 6)                                         AS company_pct_unw,
           ROUND(SUM(b.company_pct * b.vbet) / NULLIF(SUM(b.vbet), 0), 6)       AS company_pct_w,
           ROUND(AVG(b.rebate_pct), 6)                                          AS rebate_pct_unw,
           ROUND(SUM(b.rebate_pct * b.vbet) / NULLIF(SUM(b.vbet), 0), 6)        AS rebate_pct_w,
           CASE WHEN COUNT(*) >= 30 THEN 'OK' ELSE 'NO_EVIDENCE' END            AS evidence_flag,
           CASE WHEN POW(SUM(b.vbet), 2) / NULLIF(SUM(b.vbet * b.vbet), 0)
                     / NULLIF(COUNT(*), 0) < 0.01
                THEN 'THIN_WEIGHTED_EVIDENCE' ELSE 'OK' END                     AS weight_evidence_flag,
           'REALIZED_NOT_THEORETICAL'                                           AS caliber
    FROM base b
    GROUP BY b.bet_side, b.is_freecomm
) w
) z
WHERE z.audit_rn >        0 AND z.audit_rn <= 100000   -- 第 1 批
ORDER BY z.audit_rn;
--     ★ audit_rn 之排序键与分批作业版**逐字同一**（锁一），故两版可逐行对账。
--     ★ 本件仅 39 行，一批即全；分批版之 batch_id 只为体例一致与两版可逐行对账，非因体量。
--     ★ evidence_flag = 'NO_EVIDENCE' 之面（各 1 注、10 元、零盈亏）⛔ 一律不得进入任何加权或 theo 计算。
--     ★ caliber 恒为 'REALIZED_NOT_THEORETICAL' —— 硬编码于列内，令下游无从误认作理论 edge。
--     ★ 下游若欲算 theo：theo = Σ(valid_bet_j × edge_j)，其 edge 须为【理论】值；
--       以本件之 realized 值代入者，对本窗近乎恒等式（Σtheo ≈ Σprofit），⛔ 只可作分摊，不可称期望。

-- 135. RK02_table_day_risk.csv   [桌台 × 日 之风险调整表 · 新建 · 无六层商业块]
--     典型学：桌台 日序风险　粒度：table_id × biz_date　说明：Sharpe／Sortino／MDD 之唯一无阻断来源
--     ★ 本件循 ＃078 S03_agent_score ／ ＃130~＃132 字典三件 ／ ＃133 RK01 ／ ＃134 HE01 之例，
--       **不套六层商业模板** —— 无 NTILE／PERCENT_RANK／vip_tier／economic_value／action_priority。
-- ══════════════════════════════════════════════════════════════════════════════════════════════
-- 【本件立意 · 承 UCC 统一坐标之 TS 轴】
--   UCC 登记册实测：sharpe ／ sortino ／ mdd 三者全库 **0 栏**，归「② 缺算」而非「① 缺件」——
--   其所缺者只是【日序粒度】，非授权。而 桌台 系**营运单位**，其收益波动本就该管。
--   ⇒ 自 ODS 按 桌台 × 日 聚合即得，**不需解 F-47、不需理论 edge、不需 x_prod**。
--   ★ 这是当前**唯一无须解任何阻断即可补上之风险调整指标**。
--   ★ 本件只出【事实】，不出【判定】：无旗标分档、无 action、无相对排名。
--
-- 【口径六锁 · 与全包逐字同一，勿改】
--   ① 窗口 dt >= '2026-03-21' AND dt < '2026-08-07'　② 产品 bet02 = '101'
--   ③ 快照 sync_time <= '2026-08-27 09:00:00'
--   ④ 去重 PARTITION BY bet01 ORDER BY updatetime DESC, sync_time DESC, dt DESC 取 rn = 1
--   ⑤ 基础闸 category='1' · UPPER(bet38)='N' · 非测试线 · bet05>0 · bet11>0 · table_id 非空
--   ⑥ 归一 一切金额除以 bet11（汇率）
--
-- 【风险量之基准 —— ⛔ 必读】
--   本件一切风险量皆以 **ggr（＝(bet13 − bet14)/bet11，牌桌毛赢，庄家视角）** 之【日序】为基，
--   与 ＃133 RK01 之 ggr 逐字同式。⛔ 承 UCC 引用纪律：**引用 MDD 必带基准**——
--   2026-09-03 平台层实测：以 ggr_sum 为基 MDD/累计 ＝ 0.051923%%，以 profit 为基 0.086628%%，
--   以 ngr 为基 0.123954%%，三者相差逾一倍。本件恒以 ggr 为基，故列 risk_basis 一栏自证。
--
-- 【定义】（皆于该 桌台 之【全窗】上算，逐日行内重复携带，便于下游直接筛）
--   mean_daily_ggr  日 ggr 之均值　　sd_daily_ggr  日 ggr 之样本标准差
--   downside_sd     仅计 ggr < 均值 之下行离差（Sortino 之分母）
--   sharpe_window   mean_daily_ggr ÷ sd_daily_ggr　　sortino_window  mean_daily_ggr ÷ downside_sd
--   cum_ggr／peak_cum／drawdown 逐日累计与回撤；mdd_window 全窗最大回撤
--   mdd_over_ggr_window  mdd_window ÷ |ggr_window| —— 与平台层 0.051923%% 同口径，可直接对照
--   negative_day_rate    亏损日占比　　evidence_flag  n_active_days < 30 即 THIN_DAYS
--   ⛔ 无风险利率一律取 0（本口径为【收益波动比】，非金融学之 Sharpe），故不得称年化夏普。
---- 【G3 桌之处置 —— 只出旗标，不代裁】
--   桌号 900~913 共 14 张疑非真人（G3 族）。2026-09-03 实测（T_table_span 原生列）：
--   G3 占 n_rounds **12.1450%**、占 n_bets **15.1820%**；⛔ 外部所称「占 33.2% 局数」系取自
--   n_rounds_xagg（六层块广播栏，实测 32.4936%），**非本表原生局数**，引用即口径污染。
--   ⇒ 本件只出 is_g3_table 旗标，**不硬剔** —— 剔与不剔属商业裁定，本件不代裁（承「只出事实」）。
--   ⇒ 下游若作方差分解，**须先以 is_g3_table = 0 过滤**，否则 14 张伪桌会主导结果。
--
-- 【未纳入 · 候裁定】
--   · 年化与无风险利率：须先定资金成本口径，未裁前不算。
--   · 会员级 Sharpe／Sortino：会员日序过稀（多数会员活跃日 < 30），⛔ 强行算即以噪声充信号。
--   · 与 ＃133 RK01 之关系：RK01 系【局级】事实，本件系【日级】风险；二者粒度不同，禁互冒。
-- ▸ 导出：需要 —— 存为「数据库/RK02_table_day_risk.csv」
-- ── 分批作业版：每批 100,000 行 ＋ audit_rn ＋ batch_id ──
-- ── 分批取数：第 1 批。第 k 批只改末行两数为 (k-1)*100000 与 k*100000 ──
SELECT z.*,
       CAST(FLOOR((z.audit_rn - 1) / 100000) + 1 AS INT) AS batch_id
FROM (
SELECT w.*,
       ROW_NUMBER() OVER (ORDER BY w.`table_id`, w.`biz_date`) AS audit_rn,
       'A168_HF9F_20260827_0900' AS run_id,
       '2026-08-27 09:00:00' AS snapshot_sync_time
FROM (
    WITH ta AS (
      SELECT DISTINCT CAST(NULLIF(TRIM(age001), '') AS BIGINT) AS aid
      FROM ods_mariadb_2b.ods_a168_agent
      WHERE age022 = '1'
    ),
    rk AS (
      SELECT b.*,
             ROW_NUMBER() OVER (
               PARTITION BY b.bet01
               ORDER BY b.updatetime DESC, b.sync_time DESC, b.dt DESC)                AS rn
      FROM ods_mariadb_2b.ods_a168_bet02 b
      WHERE b.dt >= '2026-03-21' AND b.dt < '2026-08-07'
        AND b.bet02 = '101'
        AND b.sync_time <= '2026-08-27 09:00:00'
    ),
    base AS (
      SELECT TRIM(r.bet39)                                                              AS table_id,
             r.dt                                                               AS biz_date,
             CONCAT_WS('|', TRIM(r.bet03), TRIM(r.bet04), TRIM(r.bet39))        AS round_key,
             CAST(NULLIF(TRIM(r.bet05), '') AS BIGINT)                          AS member_id,
             CAST(NULLIF(TRIM(r.bet13), '') AS DECIMAL(20,8))
               / NULLIF(CAST(NULLIF(TRIM(r.bet11), '') AS DECIMAL(20,8)), 0)    AS stake,
             COALESCE(CAST(NULLIF(TRIM(r.validbet), '') AS DECIMAL(20,8)),
                      CAST(NULLIF(TRIM(r.bet13), '') AS DECIMAL(20,8)))
               / NULLIF(CAST(NULLIF(TRIM(r.bet11), '') AS DECIMAL(20,8)), 0)    AS vbet,
             (CAST(NULLIF(TRIM(r.bet13), '') AS DECIMAL(20,8))
            - CAST(NULLIF(TRIM(r.bet14), '') AS DECIMAL(20,8)))
               / NULLIF(CAST(NULLIF(TRIM(r.bet11), '') AS DECIMAL(20,8)), 0)    AS ggr,
             CAST(NULLIF(TRIM(r.bet16), '') AS DECIMAL(20,8))
               / NULLIF(CAST(NULLIF(TRIM(r.bet11), '') AS DECIMAL(20,8)), 0)    AS rebate
      FROM rk r
      LEFT JOIN ta t1 ON t1.aid = CAST(NULLIF(TRIM(r.bet18), '') AS BIGINT)
      LEFT JOIN ta t2 ON t2.aid = CAST(NULLIF(TRIM(r.bet19), '') AS BIGINT)
      LEFT JOIN ta t3 ON t3.aid = CAST(NULLIF(TRIM(r.bet20), '') AS BIGINT)
      LEFT JOIN ta t4 ON t4.aid = CAST(NULLIF(TRIM(r.bet21), '') AS BIGINT)
      LEFT JOIN ta t5 ON t5.aid = CAST(NULLIF(TRIM(r.bet22), '') AS BIGINT)
      WHERE r.rn = 1
        AND r.category = '1'
        AND UPPER(TRIM(r.bet38)) = 'N'
        AND COALESCE(t1.aid, t2.aid, t3.aid, t4.aid, t5.aid) IS NULL
        AND CAST(NULLIF(TRIM(r.bet05), '') AS BIGINT) > 0
        AND CAST(NULLIF(TRIM(r.bet11), '') AS DECIMAL(20,8)) > 0
        AND TRIM(r.bet39) <> ''
    ),
    dayagg AS (
      SELECT b.table_id, b.biz_date,
             COUNT(*)                                                           AS n_bets,
             COUNT(DISTINCT b.round_key)                                         AS n_rounds,
             COUNT(DISTINCT b.member_id)                                          AS n_members,
             SUM(b.stake)                                                         AS stake,
             SUM(b.vbet)                                                          AS valid_bet,
             SUM(b.ggr)                                                           AS ggr,
             SUM(b.rebate)                                                        AS rebate
      FROM base b
      GROUP BY b.table_id, b.biz_date
    ),
    w1 AS (
      SELECT d.*,
             AVG(d.ggr)          OVER (PARTITION BY d.table_id)                      AS mean_daily_ggr,
             STDDEV_SAMP(d.ggr)  OVER (PARTITION BY d.table_id)                      AS sd_daily_ggr,
             COUNT(*)            OVER (PARTITION BY d.table_id)                      AS n_active_days,
             SUM(d.ggr)          OVER (PARTITION BY d.table_id ORDER BY d.biz_date
                                       ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cum_ggr
      FROM dayagg d
    ),
    w2 AS (
      SELECT w1.*,
             MAX(w1.cum_ggr) OVER (PARTITION BY w1.table_id ORDER BY w1.biz_date
                                   ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)     AS peak_cum,
             CASE WHEN w1.ggr < w1.mean_daily_ggr
                  THEN POW(w1.ggr - w1.mean_daily_ggr, 2) ELSE 0 END                     AS dn_sq,
             CASE WHEN w1.ggr < 0 THEN 1.0 ELSE 0.0 END                                  AS is_neg_day
      FROM w1
    ),
    w3 AS (
      SELECT w2.*,
             w2.peak_cum - w2.cum_ggr                                            AS drawdown,
             MAX(w2.peak_cum - w2.cum_ggr) OVER (PARTITION BY w2.table_id)           AS mdd_window,
             SQRT(SUM(w2.dn_sq) OVER (PARTITION BY w2.table_id)
                  / NULLIF(COUNT(*) OVER (PARTITION BY w2.table_id) - 1, 0))          AS downside_sd,
             AVG(w2.is_neg_day) OVER (PARTITION BY w2.table_id)                       AS negative_day_rate,
             SUM(w2.ggr) OVER (PARTITION BY w2.table_id)                              AS ggr_window
      FROM w2
    )
    SELECT x.table_id,
           x.biz_date,
           x.n_bets,
           x.n_rounds,
           x.n_members,
           ROUND(x.stake, 4)                                                     AS stake,
           ROUND(x.valid_bet, 4)                                                 AS valid_bet,
           ROUND(x.ggr, 4)                                                       AS ggr,
           ROUND(x.rebate, 4)                                                    AS rebate,
           ROUND(x.ggr / NULLIF(x.valid_bet, 0), 8)                              AS hold_valid_bet_day,
           ROUND(x.ggr / NULLIF(x.stake, 0), 8)                                  AS hold_rate_day,
           x.n_active_days,
           ROUND(x.mean_daily_ggr, 4)                                            AS mean_daily_ggr,
           ROUND(x.sd_daily_ggr, 4)                                              AS sd_daily_ggr,
           ROUND(x.downside_sd, 4)                                               AS downside_sd,
           ROUND(x.mean_daily_ggr / NULLIF(x.sd_daily_ggr, 0), 8)                AS sharpe_window,
           ROUND(x.mean_daily_ggr / NULLIF(x.downside_sd, 0), 8)                 AS sortino_window,
           ROUND(x.cum_ggr, 4)                                                   AS cum_ggr,
           ROUND(x.peak_cum, 4)                                                  AS peak_cum,
           ROUND(x.drawdown, 4)                                                  AS drawdown,
           ROUND(x.mdd_window, 4)                                                AS mdd_window,
           ROUND(x.ggr_window, 4)                                                AS ggr_window,
           ROUND(x.mdd_window / NULLIF(ABS(x.ggr_window), 0), 8)                 AS mdd_over_ggr_window,
           ROUND(x.negative_day_rate, 6)                                         AS negative_day_rate,
           CASE WHEN x.table_id IN ('900','901','902','903','904','905','906','907','908','909','910','911','912','913')
                THEN 1 ELSE 0 END                                                     AS is_g3_table,
           CASE WHEN x.n_active_days >= 30 THEN 'OK' ELSE 'THIN_DAYS' END        AS evidence_flag,
           'GGR_BASED_DAILY_SERIES'                                              AS risk_basis
    FROM w3 x
) w
) z
WHERE z.audit_rn >        0 AND z.audit_rn <= 100000   -- 第 1 批
ORDER BY z.audit_rn;
--     ★ audit_rn 之排序键与分批作业版逐字同一，两版可逐行对账。
--     ★ ⛔ 本件系 2026-09-03 新建，**从未在 StarRocks 上执行过** —— 全量重导前须先单跑冒烟：
--       ① 行数须 ≈ 实体数 × 活跃日数；② mdd_over_ggr_window 之量级须与平台层 0.051923% 可比；
--       ③ sd_daily_ggr = 0 之实体（单日活跃）其 sharpe_window 须为 NULL 而非 Inf。

-- 136. RK03_dealer_day_risk.csv   [荷官 × 日 之风险调整表 · 新建 · 无六层商业块]
--     典型学：荷官 日序风险　粒度：dealer_id × biz_date　说明：Sharpe／Sortino／MDD 之唯一无阻断来源
--     ★ 本件循 ＃078 S03_agent_score ／ ＃130~＃132 字典三件 ／ ＃133 RK01 ／ ＃134 HE01 之例，
--       **不套六层商业模板** —— 无 NTILE／PERCENT_RANK／vip_tier／economic_value／action_priority。
-- ══════════════════════════════════════════════════════════════════════════════════════════════
-- 【本件立意 · 承 UCC 统一坐标之 TS 轴】
--   UCC 登记册实测：sharpe ／ sortino ／ mdd 三者全库 **0 栏**，归「② 缺算」而非「① 缺件」——
--   其所缺者只是【日序粒度】，非授权。而 荷官 系**营运单位**，其收益波动本就该管。
--   ⇒ 自 ODS 按 荷官 × 日 聚合即得，**不需解 F-47、不需理论 edge、不需 x_prod**。
--   ★ 这是当前**唯一无须解任何阻断即可补上之风险调整指标**。
--   ★ 本件只出【事实】，不出【判定】：无旗标分档、无 action、无相对排名。
--
-- 【口径六锁 · 与全包逐字同一，勿改】
--   ① 窗口 dt >= '2026-03-21' AND dt < '2026-08-07'　② 产品 bet02 = '101'
--   ③ 快照 sync_time <= '2026-08-27 09:00:00'
--   ④ 去重 PARTITION BY bet01 ORDER BY updatetime DESC, sync_time DESC, dt DESC 取 rn = 1
--   ⑤ 基础闸 category='1' · UPPER(bet38)='N' · 非测试线 · bet05>0 · bet11>0 · dealer_id 非空
--   ⑥ 归一 一切金额除以 bet11（汇率）
--
-- 【风险量之基准 —— ⛔ 必读】
--   本件一切风险量皆以 **ggr（＝(bet13 − bet14)/bet11，牌桌毛赢，庄家视角）** 之【日序】为基，
--   与 ＃133 RK01 之 ggr 逐字同式。⛔ 承 UCC 引用纪律：**引用 MDD 必带基准**——
--   2026-09-03 平台层实测：以 ggr_sum 为基 MDD/累计 ＝ 0.051923%%，以 profit 为基 0.086628%%，
--   以 ngr 为基 0.123954%%，三者相差逾一倍。本件恒以 ggr 为基，故列 risk_basis 一栏自证。
--
-- 【定义】（皆于该 荷官 之【全窗】上算，逐日行内重复携带，便于下游直接筛）
--   mean_daily_ggr  日 ggr 之均值　　sd_daily_ggr  日 ggr 之样本标准差
--   downside_sd     仅计 ggr < 均值 之下行离差（Sortino 之分母）
--   sharpe_window   mean_daily_ggr ÷ sd_daily_ggr　　sortino_window  mean_daily_ggr ÷ downside_sd
--   cum_ggr／peak_cum／drawdown 逐日累计与回撤；mdd_window 全窗最大回撤
--   mdd_over_ggr_window  mdd_window ÷ |ggr_window| —— 与平台层 0.051923%% 同口径，可直接对照
--   negative_day_rate    亏损日占比　　evidence_flag  n_active_days < 30 即 THIN_DAYS
--   ⛔ 无风险利率一律取 0（本口径为【收益波动比】，非金融学之 Sharpe），故不得称年化夏普。
---- 【未纳入 · 候裁定】
--   · 年化与无风险利率：须先定资金成本口径，未裁前不算。
--   · 会员级 Sharpe／Sortino：会员日序过稀（多数会员活跃日 < 30），⛔ 强行算即以噪声充信号。
--   · 与 ＃133 RK01 之关系：RK01 系【局级】事实，本件系【日级】风险；二者粒度不同，禁互冒。
-- ▸ 导出：需要 —— 存为「数据库/RK03_dealer_day_risk.csv」
-- ── 分批作业版：每批 100,000 行 ＋ audit_rn ＋ batch_id ──
-- ── 分批取数：第 1 批。第 k 批只改末行两数为 (k-1)*100000 与 k*100000 ──
SELECT z.*,
       CAST(FLOOR((z.audit_rn - 1) / 100000) + 1 AS INT) AS batch_id
FROM (
SELECT w.*,
       ROW_NUMBER() OVER (ORDER BY w.`dealer_id`, w.`biz_date`) AS audit_rn,
       'A168_HF9F_20260827_0900' AS run_id,
       '2026-08-27 09:00:00' AS snapshot_sync_time
FROM (
    WITH ta AS (
      SELECT DISTINCT CAST(NULLIF(TRIM(age001), '') AS BIGINT) AS aid
      FROM ods_mariadb_2b.ods_a168_agent
      WHERE age022 = '1'
    ),
    rk AS (
      SELECT b.*,
             ROW_NUMBER() OVER (
               PARTITION BY b.bet01
               ORDER BY b.updatetime DESC, b.sync_time DESC, b.dt DESC)                AS rn
      FROM ods_mariadb_2b.ods_a168_bet02 b
      WHERE b.dt >= '2026-03-21' AND b.dt < '2026-08-07'
        AND b.bet02 = '101'
        AND b.sync_time <= '2026-08-27 09:00:00'
    ),
    base AS (
      SELECT TRIM(r.eid)                                                              AS dealer_id,
             r.dt                                                               AS biz_date,
             CONCAT_WS('|', TRIM(r.bet03), TRIM(r.bet04), TRIM(r.bet39))        AS round_key,
             CAST(NULLIF(TRIM(r.bet05), '') AS BIGINT)                          AS member_id,
             CAST(NULLIF(TRIM(r.bet13), '') AS DECIMAL(20,8))
               / NULLIF(CAST(NULLIF(TRIM(r.bet11), '') AS DECIMAL(20,8)), 0)    AS stake,
             COALESCE(CAST(NULLIF(TRIM(r.validbet), '') AS DECIMAL(20,8)),
                      CAST(NULLIF(TRIM(r.bet13), '') AS DECIMAL(20,8)))
               / NULLIF(CAST(NULLIF(TRIM(r.bet11), '') AS DECIMAL(20,8)), 0)    AS vbet,
             (CAST(NULLIF(TRIM(r.bet13), '') AS DECIMAL(20,8))
            - CAST(NULLIF(TRIM(r.bet14), '') AS DECIMAL(20,8)))
               / NULLIF(CAST(NULLIF(TRIM(r.bet11), '') AS DECIMAL(20,8)), 0)    AS ggr,
             CAST(NULLIF(TRIM(r.bet16), '') AS DECIMAL(20,8))
               / NULLIF(CAST(NULLIF(TRIM(r.bet11), '') AS DECIMAL(20,8)), 0)    AS rebate
      FROM rk r
      LEFT JOIN ta t1 ON t1.aid = CAST(NULLIF(TRIM(r.bet18), '') AS BIGINT)
      LEFT JOIN ta t2 ON t2.aid = CAST(NULLIF(TRIM(r.bet19), '') AS BIGINT)
      LEFT JOIN ta t3 ON t3.aid = CAST(NULLIF(TRIM(r.bet20), '') AS BIGINT)
      LEFT JOIN ta t4 ON t4.aid = CAST(NULLIF(TRIM(r.bet21), '') AS BIGINT)
      LEFT JOIN ta t5 ON t5.aid = CAST(NULLIF(TRIM(r.bet22), '') AS BIGINT)
      WHERE r.rn = 1
        AND r.category = '1'
        AND UPPER(TRIM(r.bet38)) = 'N'
        AND COALESCE(t1.aid, t2.aid, t3.aid, t4.aid, t5.aid) IS NULL
        AND CAST(NULLIF(TRIM(r.bet05), '') AS BIGINT) > 0
        AND CAST(NULLIF(TRIM(r.bet11), '') AS DECIMAL(20,8)) > 0
        AND TRIM(r.eid) <> ''
    ),
    dayagg AS (
      SELECT b.dealer_id, b.biz_date,
             COUNT(*)                                                           AS n_bets,
             COUNT(DISTINCT b.round_key)                                         AS n_rounds,
             COUNT(DISTINCT b.member_id)                                          AS n_members,
             SUM(b.stake)                                                         AS stake,
             SUM(b.vbet)                                                          AS valid_bet,
             SUM(b.ggr)                                                           AS ggr,
             SUM(b.rebate)                                                        AS rebate
      FROM base b
      GROUP BY b.dealer_id, b.biz_date
    ),
    w1 AS (
      SELECT d.*,
             AVG(d.ggr)          OVER (PARTITION BY d.dealer_id)                      AS mean_daily_ggr,
             STDDEV_SAMP(d.ggr)  OVER (PARTITION BY d.dealer_id)                      AS sd_daily_ggr,
             COUNT(*)            OVER (PARTITION BY d.dealer_id)                      AS n_active_days,
             SUM(d.ggr)          OVER (PARTITION BY d.dealer_id ORDER BY d.biz_date
                                       ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cum_ggr
      FROM dayagg d
    ),
    w2 AS (
      SELECT w1.*,
             MAX(w1.cum_ggr) OVER (PARTITION BY w1.dealer_id ORDER BY w1.biz_date
                                   ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)     AS peak_cum,
             CASE WHEN w1.ggr < w1.mean_daily_ggr
                  THEN POW(w1.ggr - w1.mean_daily_ggr, 2) ELSE 0 END                     AS dn_sq,
             CASE WHEN w1.ggr < 0 THEN 1.0 ELSE 0.0 END                                  AS is_neg_day
      FROM w1
    ),
    w3 AS (
      SELECT w2.*,
             w2.peak_cum - w2.cum_ggr                                            AS drawdown,
             MAX(w2.peak_cum - w2.cum_ggr) OVER (PARTITION BY w2.dealer_id)           AS mdd_window,
             SQRT(SUM(w2.dn_sq) OVER (PARTITION BY w2.dealer_id)
                  / NULLIF(COUNT(*) OVER (PARTITION BY w2.dealer_id) - 1, 0))          AS downside_sd,
             AVG(w2.is_neg_day) OVER (PARTITION BY w2.dealer_id)                       AS negative_day_rate,
             SUM(w2.ggr) OVER (PARTITION BY w2.dealer_id)                              AS ggr_window
      FROM w2
    )
    SELECT x.dealer_id,
           x.biz_date,
           x.n_bets,
           x.n_rounds,
           x.n_members,
           ROUND(x.stake, 4)                                                     AS stake,
           ROUND(x.valid_bet, 4)                                                 AS valid_bet,
           ROUND(x.ggr, 4)                                                       AS ggr,
           ROUND(x.rebate, 4)                                                    AS rebate,
           ROUND(x.ggr / NULLIF(x.valid_bet, 0), 8)                              AS hold_valid_bet_day,
           ROUND(x.ggr / NULLIF(x.stake, 0), 8)                                  AS hold_rate_day,
           x.n_active_days,
           ROUND(x.mean_daily_ggr, 4)                                            AS mean_daily_ggr,
           ROUND(x.sd_daily_ggr, 4)                                              AS sd_daily_ggr,
           ROUND(x.downside_sd, 4)                                               AS downside_sd,
           ROUND(x.mean_daily_ggr / NULLIF(x.sd_daily_ggr, 0), 8)                AS sharpe_window,
           ROUND(x.mean_daily_ggr / NULLIF(x.downside_sd, 0), 8)                 AS sortino_window,
           ROUND(x.cum_ggr, 4)                                                   AS cum_ggr,
           ROUND(x.peak_cum, 4)                                                  AS peak_cum,
           ROUND(x.drawdown, 4)                                                  AS drawdown,
           ROUND(x.mdd_window, 4)                                                AS mdd_window,
           ROUND(x.ggr_window, 4)                                                AS ggr_window,
           ROUND(x.mdd_window / NULLIF(ABS(x.ggr_window), 0), 8)                 AS mdd_over_ggr_window,
           ROUND(x.negative_day_rate, 6)                                         AS negative_day_rate,
           CAST(NULL AS INT)                                                        AS is_g3_table,
           CASE WHEN x.n_active_days >= 30 THEN 'OK' ELSE 'THIN_DAYS' END        AS evidence_flag,
           'GGR_BASED_DAILY_SERIES'                                              AS risk_basis
    FROM w3 x
) w
) z
WHERE z.audit_rn >        0 AND z.audit_rn <= 100000   -- 第 1 批
ORDER BY z.audit_rn;
--     ★ audit_rn 之排序键与分批作业版逐字同一，两版可逐行对账。
--     ★ ⛔ 本件系 2026-09-03 新建，**从未在 StarRocks 上执行过** —— 全量重导前须先单跑冒烟：
--       ① 行数须 ≈ 实体数 × 活跃日数；② mdd_over_ggr_window 之量级须与平台层 0.051923% 可比；
--       ③ sd_daily_ggr = 0 之实体（单日活跃）其 sharpe_window 须为 NULL 而非 Inf。
-- ══════════════════════════════════════════════════════════════════════════════════════════════
-- 137. RK04_member_econ_by_scope.csv   [会员经济 × 荷官类 × 线别 之分类表 · 新建 · 无六层商业块]
--     典型学：口径分离　粒度：member_id × dealer_class × line_class　说明：哨兵与测试线不得与真实荷官同锅计算
--     ★ 本件循 ＃078 S03_agent_score ／ ＃130~＃132 字典三件 ／ ＃133 RK01 ／ ＃134 HE01 ／ ＃135~＃136 RK02/RK03 之例，
--       **不套六层商业模板** —— 无 NTILE／PERCENT_RANK／vip_tier／economic_value／action_priority。
-- ══════════════════════════════════════════════════════════════════════════════════════════════
-- 【本件立意 · 2026-09-04 实测所迫】
--   ⛔ 实测揭出：＃070 R03_player_dealer 之 `WHERE pdw.is_sentinel_dealer = 0` 只剔**行**、不剔**钱**。
--      因六层块 x_agg 之过滤仅 rn=1 · category='1' · bet38='N' · bet11>0 · is_clean=1 · 会员非空，
--      **完全不看 eid**，故每行携带之 stake／valid_bet／profit／ngr／residual_b／agent_cost
--      一律是【该会员全荷官口径】，内含其在哨兵荷官（eid ∈ {'-1','0'}）上之全部注单。
--   ⛔ 且 q 原生层**完全不排除测试线代理**（区块内 x_testagent／f_testline／is_clean 命中数 ＝ 0），
--      而 x_agg 排（is_clean = 1）。⇒ 两层过滤方向相反，同一件内自相矛盾。
--   ⇒ 2026-09-04 实测（＃071 现档 800,000 行）：哨兵行占 4.3104%，却占 stake_amount 之 15.8341%
--      （376,389,405.8320）；六层 stake 为空之会员（即测试线会员）＃071 计 54 名、＃070 计 3 名。
--   ★ 本件之职：把这三笔账**分开摆出来**，使下游得以「真实荷官 × 清白线」口径重算经济量，
--     而**不必改动共享六层块** —— 改之即废 63 件可沿用之交付件，并废 ＃071 已落盘之 80 万行。
--
-- 【口径六锁 · 与全包逐字同一，勿改】
--   ① 窗口 dt >= '2026-03-21' AND dt < '2026-08-07'　② 产品 bet02 = '101'
--   ③ 快照 sync_time <= '2026-08-27 09:00:00'
--   ④ 去重 PARTITION BY bet01 ORDER BY updatetime DESC, sync_time DESC, dt DESC 取 rn = 1
--   ⑤ 基础闸 category='1' · UPPER(bet38)='N' · bet11>0　⑥ 归一 一切金额除以 bet11（汇率）
--   ★ 本件之 x_ranked／x_testagent／x_bs0 三个 CTE 系【自 ＃071 逐字复制】，故与六层块同源同锁。
--   ⛔ 本件**不施** is_clean=1、不施 eid 非空、不施 bet05>0、不施排除 TIP —— 因这四者正是待分类之对象。
--
-- 【分类轴】
--   dealer_class  REAL      eid 非空且 ∉ {'-1','0'} —— 真实荷官
--                 SENTINEL  eid ∈ {'-1','0'}        —— 哨兵值，⛔ 不得与 REAL 同锅
--                 UNKNOWN   eid 为空                —— q 原生层丢弃、x_agg 保留之那批
--   line_class    CLEAN     f_testline = 0          —— 清白线
--                 TEST_LINE f_testline = 1          —— 测试线（age022 = '1' 之代理链），⛔ 不得与 CLEAN 同锅
--   另出 TIP 注单与 bet05 非正数之计数与金额，使 q 层与 x_agg 层之四道口径差全部可见。
--
-- 【⛔ 对账闸（本件之验收硬判据）】
--   Σ（line_class = 'CLEAN' 之全部 dealer_class）之 n_bets／stake／valid_bet／rebate／net／agent_cost
--   **须逐会员等于** ＃070／＃071 六层块之 n_bets／stake／valid_bet／rebate_cost／(-profit)／cost_complement_b。
--   容差：本件金额取 ROUND(…,6)，＃070／＃071 取 ROUND(…,4)，故合计后四舍五入至 4 位再比，
--   理论最大偏差 3e-6；⛔ 超此即表示本件与六层块已不同源，须停手回报。
--
-- 【本件不做之事】
--   · 不出任何判定：无旗标分档、无 action、无相对排名、无 vip_tier。
--   · 不代裁「该以何口径为准」—— 剔哨兵与否属商业裁定，本件只把账分开摆出。
--   · 不改 ＃070／＃071 一字。
-- ▸ 导出：需要 —— 存为「数据库/RK04_member_econ_by_scope.csv」
-- ── 分批作业版：每批 100,000 行 ＋ audit_rn ＋ batch_id ──
-- ── 分批取数：第 1 批。第 k 批只改末行两数为 (k-1)*100000 与 k*100000 ──
SELECT z.*,
       CAST(FLOOR((z.audit_rn - 1) / 100000) + 1 AS INT) AS batch_id
FROM (
SELECT w.*,
       ROW_NUMBER() OVER (ORDER BY w.`member_id`, w.`dealer_class`, w.`line_class`) AS audit_rn,
       'A168_HF9F_20260827_0900' AS run_id,
       '2026-08-27 09:00:00' AS snapshot_sync_time
FROM (
    WITH
      x_ranked AS (
    SELECT b.bet01, b.bet03, b.bet04, b.bet05, b.bet09, b.bet11, b.bet13,
           b.bet15, b.bet16, b.bet17, b.bet18, b.bet19, b.bet20, b.bet21,
           b.bet22, b.bet23, b.bet24, b.bet25, b.bet26, b.bet27, b.bet38, b.bet39, b.category, b.commission,
           b.dt, b.eid, b.ip, b.validbet, b.updatetime, b.sync_time,
           ROW_NUMBER() OVER (
             PARTITION BY b.bet01
             ORDER BY b.updatetime DESC, b.sync_time DESC, b.dt DESC)      AS x_rn
    FROM ods_mariadb_2b.ods_a168_bet02 b
    WHERE b.dt >= '2026-03-21' AND b.dt < '2026-08-07'
      AND b.bet02 = '101'
      AND b.sync_time <= '2026-08-27 09:00:00'
  ),
    x_testagent AS (
    SELECT age001 AS agent_id FROM ods_mariadb_2b.ods_a168_agent WHERE age022 = '1'
  ),
    x_bs0 AS (
    SELECT b.bet05 AS x_member, b.eid AS x_dealer, b.bet39 AS x_table,
           b.bet03 AS x_shoe, b.ip AS x_ip, b.bet09 AS x_product, b.dt AS x_date,
           CONCAT_WS('|', b.bet03, b.bet04, b.bet39)                      AS x_round,
           CONCAT_WS('|', b.bet39, b.bet03)                               AS x_tblshoe,
           CAST(NULLIF(TRIM(b.bet04),'') AS INT)                          AS x_rno,
           CASE WHEN b.dt >= '2026-07-08' THEN 1 ELSE 0 END               AS x_rec,
           CASE WHEN TRIM(b.commission)='1' THEN 1 ELSE 0 END             AS x_freecomm,
           CAST(NULLIF(TRIM(b.bet13),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_stake,
           CAST(NULLIF(TRIM(b.validbet),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_valid,
           CAST(NULLIF(TRIM(b.bet16),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_rebate,
           CAST(NULLIF(TRIM(b.bet17),'') AS DECIMAL(20,4))
             / CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8))            AS x_net,
           CAST(NULLIF(TRIM(b.bet15),'') AS DECIMAL(20,6))                AS x_rbpct,
           COALESCE(CAST(NULLIF(TRIM(b.bet23),'') AS DECIMAL(20,6)),0)   AS x_agpct,
          NULLIF(CAST(NULLIF(TRIM(b.bet23),'') AS DECIMAL(20,6)),0)     AS x_rate1,
          NULLIF(CAST(NULLIF(TRIM(b.bet24),'') AS DECIMAL(20,6)),0)     AS x_rate2,
          NULLIF(CAST(NULLIF(TRIM(b.bet25),'') AS DECIMAL(20,6)),0)     AS x_rate3,
          NULLIF(CAST(NULLIF(TRIM(b.bet26),'') AS DECIMAL(20,6)),0)     AS x_rate4,
          NULLIF(CAST(NULLIF(TRIM(b.bet27),'') AS DECIMAL(20,6)),0)     AS x_rate5,
          (CASE WHEN NULLIF(CAST(NULLIF(TRIM(b.bet22),'') AS BIGINT),0) IS NOT NULL THEN 5
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet21),'') AS BIGINT),0) IS NOT NULL THEN 4
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet20),'') AS BIGINT),0) IS NOT NULL THEN 3
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet19),'') AS BIGINT),0) IS NOT NULL THEN 2
                WHEN NULLIF(CAST(NULLIF(TRIM(b.bet18),'') AS BIGINT),0) IS NOT NULL THEN 1
                ELSE 0 END)                                             AS x_chain_depth,
           CASE WHEN COALESCE(t1.agent_id,t2.agent_id,t3.agent_id,
                              t4.agent_id,t5.agent_id) IS NOT NULL
                THEN 1 ELSE 0 END                                        AS f_testline
    FROM x_ranked b
    LEFT JOIN x_testagent t1 ON t1.agent_id = b.bet18
    LEFT JOIN x_testagent t2 ON t2.agent_id = b.bet19
    LEFT JOIN x_testagent t3 ON t3.agent_id = b.bet20
    LEFT JOIN x_testagent t4 ON t4.agent_id = b.bet21
    LEFT JOIN x_testagent t5 ON t5.agent_id = b.bet22
    WHERE b.x_rn = 1
      AND b.category='1' AND UPPER(TRIM(b.bet38))='N'
      AND CAST(NULLIF(TRIM(b.bet11),'') AS DECIMAL(20,8)) > 0
  ),
  x_scope AS (
    SELECT s.*,
           CASE WHEN NULLIF(TRIM(CAST(s.x_dealer AS STRING)),'') IS NULL THEN 'UNKNOWN'
                WHEN TRIM(CAST(s.x_dealer AS STRING)) IN ('-1','0')      THEN 'SENTINEL'
                ELSE 'REAL' END                                            AS dealer_class,
           CASE WHEN s.f_testline = 0 THEN 'CLEAN' ELSE 'TEST_LINE' END    AS line_class,
           CASE WHEN UPPER(TRIM(CAST(s.x_product AS STRING))) LIKE 'TIP\_1\_%' THEN 1 ELSE 0 END AS f_tip,
           CASE WHEN CAST(NULLIF(TRIM(CAST(s.x_member AS STRING)),'') AS BIGINT) > 0 THEN 1 ELSE 0 END AS f_uid_pos
    FROM x_bs0 s
  )
    SELECT s.x_member                                                        AS member_id,
           s.dealer_class,
           s.line_class,
           COUNT(*)                                                          AS n_bets,
           COUNT(DISTINCT s.x_round)                                         AS n_rounds,
           COUNT(DISTINCT s.x_dealer)                                        AS n_dealers,
           COUNT(DISTINCT s.x_date)                                          AS active_days,
           MIN(s.x_date)                                                     AS first_seen_d,
           MAX(s.x_date)                                                     AS last_seen_d,
           ROUND(SUM(s.x_stake), 6)                                          AS stake,
           ROUND(SUM(s.x_valid), 6)                                          AS valid_bet,
           ROUND(SUM(s.x_rebate), 6)                                         AS rebate,
           ROUND(SUM(s.x_net), 6)                                            AS net,
           ROUND(-SUM(s.x_net), 6)                                           AS profit,
           ROUND(SUM(-s.x_net * (100.0 - s.x_agpct) / 100.0), 6)             AS agent_cost,
           ROUND(-SUM(s.x_net) - SUM(s.x_rebate), 6)                         AS ngr,
           ROUND(-SUM(s.x_net) - SUM(s.x_rebate)
                 - SUM(-s.x_net * (100.0 - s.x_agpct) / 100.0), 6)           AS residual_b,
           ROUND(SUM(s.x_net) / NULLIF(SUM(s.x_stake), 0), 8)                AS roi,
           SUM(s.f_tip)                                                      AS n_bets_tip,
           ROUND(SUM(CASE WHEN s.f_tip = 1 THEN s.x_stake ELSE 0 END), 6)    AS stake_tip,
           SUM(CASE WHEN s.f_uid_pos = 0 THEN 1 ELSE 0 END)                  AS n_bets_uid_nonpositive,
           ROUND(SUM(CASE WHEN s.f_uid_pos = 0 THEN s.x_stake ELSE 0 END), 6) AS stake_uid_nonpositive,
           'MEMBER_x_DEALERCLASS_x_LINECLASS'                                AS grain_key,
           'NO_SIX_LAYER_BLOCK'                                              AS six_layer_status,
           'SCOPE_SEPARATED_NOT_SUMMABLE_ACROSS_CLASSES'                     AS combine_rule,
           'FALSE'                                                           AS admit_to_risk_decision
    FROM x_scope s
    WHERE s.x_member IS NOT NULL AND TRIM(CAST(s.x_member AS STRING)) <> ''
    GROUP BY s.x_member, s.dealer_class, s.line_class
) w
) z
WHERE z.audit_rn >        0 AND z.audit_rn <=  100000   -- 第 1 批
ORDER BY z.audit_rn;
--     ★ audit_rn 之排序键 (member_id, dealer_class, line_class) 即本件之 GROUP BY 键，
--       故【必然唯一】，三版逐行可对账，且无死键。
--     ★ ⛔ 本件系 2026-09-04 新建，**从未在 StarRocks 上执行过** —— 全量重导前须先单跑冒烟：
--       ① 行数 ≈ 会员数 × 1~6（多数会员只有 REAL × CLEAN 一行）；
--       ② 对账闸：Σ(line_class='CLEAN') 逐会员 == ＃070／＃071 六层块之同名量（容差 3e-6）；
--       ③ dealer_class 之相异值须恰为 {REAL, SENTINEL, UNKNOWN}，line_class 恰为 {CLEAN, TEST_LINE}；
--       ④ SENTINEL 之 stake 占全体之比，须与 2026-09-04 现档实测 15.8341% 同量级
--          （现档系 residual_b ASC 之头部偏样，仅作量级参照，⛔ 不得作为期望值）。
